-- ===== VIEWS =====
CREATE OR REPLACE VIEW public.ai_agent_quality AS  WITH runs AS (
         SELECT agent_runs.agent,
            count(*) AS runs_30d,
            count(*) FILTER (WHERE (agent_runs.status = ANY (ARRAY['error'::text, 'failed'::text]))) AS errors
           FROM agent_runs
          WHERE (agent_runs.started_at >= (now() - '30 days'::interval))
          GROUP BY agent_runs.agent
        ), acts AS (
         SELECT agent_actions.agent,
            count(*) AS actions_30d,
            count(*) FILTER (WHERE (agent_actions.status = ANY (ARRAY['pending'::text, 'needs_review'::text]))) AS open_escalations,
            count(*) FILTER (WHERE (agent_actions.status = 'rejected'::text)) AS rejected,
            count(*) FILTER (WHERE (agent_actions.status = ANY (ARRAY['approved'::text, 'done'::text, 'auto_done'::text]))) AS accepted
           FROM agent_actions
          WHERE (agent_actions.created_at >= (now() - '30 days'::interval))
          GROUP BY agent_actions.agent
        )
 SELECT COALESCE(r.agent, a.agent) AS agent,
    COALESCE(r.runs_30d, (0)::bigint) AS runs_30d,
    COALESCE(r.errors, (0)::bigint) AS errors,
    round(((100.0 * ((COALESCE(r.runs_30d, (0)::bigint) - COALESCE(r.errors, (0)::bigint)))::numeric) / (NULLIF(r.runs_30d, 0))::numeric), 1) AS run_success_pct,
    COALESCE(a.actions_30d, (0)::bigint) AS actions_30d,
    COALESCE(a.open_escalations, (0)::bigint) AS open_escalations,
    COALESCE(a.rejected, (0)::bigint) AS rejected,
    COALESCE(a.accepted, (0)::bigint) AS accepted,
    round(((100.0 * (a.rejected)::numeric) / (NULLIF((a.rejected + a.accepted), 0))::numeric), 1) AS rejection_rate_pct
   FROM (runs r
     FULL JOIN acts a ON ((a.agent = r.agent)));

CREATE OR REPLACE VIEW public.ap_aging AS  SELECT v.name AS vendor,
    sum(
        CASE
            WHEN (CURRENT_DATE <= COALESCE(b.due_date, b.bill_date)) THEN (b.total - b.amount_paid)
            ELSE (0)::numeric
        END) AS current_due,
    sum(
        CASE
            WHEN (((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) >= 1) AND ((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) <= 30)) THEN (b.total - b.amount_paid)
            ELSE (0)::numeric
        END) AS d1_30,
    sum(
        CASE
            WHEN (((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) >= 31) AND ((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) <= 60)) THEN (b.total - b.amount_paid)
            ELSE (0)::numeric
        END) AS d31_60,
    sum(
        CASE
            WHEN (((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) >= 61) AND ((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) <= 90)) THEN (b.total - b.amount_paid)
            ELSE (0)::numeric
        END) AS d61_90,
    sum(
        CASE
            WHEN ((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) > 90) THEN (b.total - b.amount_paid)
            ELSE (0)::numeric
        END) AS d90_plus,
    sum((b.total - b.amount_paid)) AS total_due
   FROM (ap_bills b
     JOIN po_vendors v ON ((v.id = b.vendor_id)))
  WHERE (b.status = ANY (ARRAY['open'::text, 'partial'::text]))
  GROUP BY v.name;

CREATE OR REPLACE VIEW public.ap_open_bills AS  SELECT b.id,
    b.bill_no,
    v.name AS vendor,
    b.bill_date,
    b.due_date,
    b.total,
    b.amount_paid,
    (b.total - b.amount_paid) AS balance_due,
    b.status,
    (CURRENT_DATE - b.due_date) AS days_overdue
   FROM (ap_bills b
     JOIN po_vendors v ON ((v.id = b.vendor_id)))
  WHERE (b.status = ANY (ARRAY['open'::text, 'partial'::text]))
  ORDER BY b.due_date;

CREATE OR REPLACE VIEW public.budget_vs_actual AS  WITH actual AS (
         SELECT l.account_code,
            (date_trunc('month'::text, (j.entry_date)::timestamp with time zone))::date AS period_month,
            sum(l.debit) AS dr,
            sum(l.credit) AS cr
           FROM (gl_journal_lines l
             JOIN gl_journal j ON (((j.id = l.journal_id) AND (j.status = 'posted'::text))))
          GROUP BY l.account_code, ((date_trunc('month'::text, (j.entry_date)::timestamp with time zone))::date)
        )
 SELECT b.id AS budget_id,
    b.name AS budget_name,
    b.fiscal_year,
    bl.account_code,
    ga.name AS account_name,
    ga.type,
    bl.period_month,
    bl.amount AS budget_amount,
    COALESCE(
        CASE
            WHEN (ga.normal_balance = 'D'::bpchar) THEN (a.dr - a.cr)
            ELSE (a.cr - a.dr)
        END, (0)::numeric) AS actual_amount,
    (bl.amount - COALESCE(
        CASE
            WHEN (ga.normal_balance = 'D'::bpchar) THEN (a.dr - a.cr)
            ELSE (a.cr - a.dr)
        END, (0)::numeric)) AS variance
   FROM (((budget_lines bl
     JOIN budgets b ON ((b.id = bl.budget_id)))
     JOIN gl_accounts ga ON ((ga.code = bl.account_code)))
     LEFT JOIN actual a ON (((a.account_code = bl.account_code) AND (a.period_month = bl.period_month))));

CREATE OR REPLACE VIEW public.budget_vs_actual_summary AS  SELECT budget_id,
    budget_name,
    fiscal_year,
    account_code,
    account_name,
    type,
    sum(budget_amount) AS budget_ytd,
    sum(actual_amount) AS actual_ytd,
    sum(variance) AS variance_ytd,
        CASE
            WHEN (sum(budget_amount) <> (0)::numeric) THEN round(((100.0 * sum(actual_amount)) / sum(budget_amount)), 1)
            ELSE NULL::numeric
        END AS pct_of_budget
   FROM budget_vs_actual
  GROUP BY budget_id, budget_name, fiscal_year, account_code, account_name, type
  ORDER BY account_code;

CREATE OR REPLACE VIEW public.category_price_stats AS  SELECT i.category,
    count(qq.quote_amount) AS n,
    round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((qq.quote_amount)::double precision)))::numeric, 0) AS median,
    round((percentile_cont((0.25)::double precision) WITHIN GROUP (ORDER BY ((qq.quote_amount)::double precision)))::numeric, 0) AS p25,
    round((percentile_cont((0.75)::double precision) WITHIN GROUP (ORDER BY ((qq.quote_amount)::double precision)))::numeric, 0) AS p75,
    round(avg(qq.quote_amount), 0) AS mean,
    round(COALESCE(stddev_pop(qq.quote_amount), (0)::numeric), 0) AS sd
   FROM (quotes qq
     JOIN inquiries i ON ((i.id = qq.inquiry_id)))
  WHERE ((qq.quote_amount IS NOT NULL) AND (qq.quote_amount > (0)::numeric) AND (i.category IS NOT NULL))
  GROUP BY i.category;

CREATE OR REPLACE VIEW public.crm_deal_kpis AS  SELECT (( SELECT count(*) AS count
           FROM (inquiries i
             JOIN crm_stages s ON ((s.key = i.pipeline_stage)))
          WHERE ((NOT s.is_won) AND (NOT s.is_lost))))::integer AS open_deals,
    (( SELECT count(*) AS count
           FROM (inquiries i
             JOIN crm_stages s ON ((s.key = i.pipeline_stage)))
          WHERE s.is_won))::integer AS won_deals,
    (( SELECT count(*) AS count
           FROM (inquiries i
             JOIN crm_stages s ON ((s.key = i.pipeline_stage)))
          WHERE s.is_lost))::integer AS lost_deals,
    ( SELECT round(avg((EXTRACT(epoch FROM (COALESCE(i.completed_at, now()) - i.created_at)) / 86400.0)), 1) AS round
           FROM (inquiries i
             JOIN crm_stages s ON ((s.key = i.pipeline_stage)))
          WHERE s.is_won) AS avg_cycle_days,
    ( SELECT round(COALESCE(sum(((i.expected_value * (s.probability)::numeric) / 100.0)), (0)::numeric), 2) AS round
           FROM (inquiries i
             JOIN crm_stages s ON ((s.key = i.pipeline_stage)))
          WHERE ((NOT s.is_won) AND (NOT s.is_lost))) AS weighted_forecast,
    (( SELECT count(*) AS count
           FROM crm_activities
          WHERE ((crm_activities.done = false) AND (crm_activities.due_at IS NOT NULL) AND (crm_activities.due_at < now()))))::integer AS overdue_activities;

CREATE OR REPLACE VIEW public.crm_pipeline_report AS  SELECT s.key,
    s.label,
    s.sort_order,
    s.probability,
    s.is_won,
    s.is_lost,
    (count(i.id))::integer AS deals,
    round(COALESCE(sum(i.expected_value), (0)::numeric), 2) AS value,
    round(COALESCE(sum(((i.expected_value * (s.probability)::numeric) / 100.0)), (0)::numeric), 2) AS weighted
   FROM (crm_stages s
     LEFT JOIN inquiries i ON ((i.pipeline_stage = s.key)))
  WHERE s.active
  GROUP BY s.key, s.label, s.sort_order, s.probability, s.is_won, s.is_lost
  ORDER BY s.sort_order;

CREATE OR REPLACE VIEW public.customer_health AS  WITH inq AS (
         SELECT i.id,
            i.customer_id,
            i.status,
            i.pipeline_stage,
            i.created_at,
            i.completed_at,
            i.outcome,
            i.stage_changed_at,
            ( SELECT min(q.created_at) AS min
                   FROM quotes q
                  WHERE (q.inquiry_id = i.id)) AS first_quote_at,
            ( SELECT count(*) AS count
                   FROM quotes q
                  WHERE (q.inquiry_id = i.id)) AS n_quotes
           FROM inquiries i
        ), inq2 AS (
         SELECT inq.id,
            inq.customer_id,
            inq.status,
            inq.pipeline_stage,
            inq.created_at,
            inq.completed_at,
            inq.outcome,
            inq.stage_changed_at,
            inq.first_quote_at,
            inq.n_quotes,
            (EXTRACT(epoch FROM (inq.first_quote_at - inq.created_at)) / 3600.0) AS resp_hrs,
                CASE
                    WHEN ((inq.status = 'revealed'::text) AND (inq.completed_at IS NULL) AND (inq.created_at < (now() - '30 days'::interval))) THEN true
                    WHEN ((inq.status = 'quoted'::text) AND (inq.created_at < (now() - '7 days'::interval))) THEN true
                    WHEN ((COALESCE(inq.pipeline_stage, ''::text) = 'qualifying'::text) AND (inq.n_quotes = 0) AND (inq.created_at < (now() - '2 days'::interval))) THEN true
                    ELSE false
                END AS stalled,
            ((inq.completed_at IS NOT NULL) OR (inq.outcome = 'won'::text)) AS completed,
            ((inq.status = 'revealed'::text) OR (inq.completed_at IS NOT NULL) OR (inq.outcome = 'won'::text)) AS progressed
           FROM inq
        ), cust AS (
         SELECT c.id AS customer_id,
            c.full_name,
            c.email,
            COALESCE(c.banned, false) AS banned,
            COALESCE(c.chat_strikes, 0) AS strikes,
            ( SELECT count(*) AS count
                   FROM inq2 x
                  WHERE (x.customer_id = c.id)) AS total_inq,
            ( SELECT count(*) AS count
                   FROM inq2 x
                  WHERE ((x.customer_id = c.id) AND (x.status <> 'cancelled'::text) AND (COALESCE(x.pipeline_stage, ''::text) <> 'lost'::text))) AS active_inq,
            ( SELECT count(*) AS count
                   FROM inq2 x
                  WHERE ((x.customer_id = c.id) AND x.progressed)) AS progressed_inq,
            ( SELECT count(*) AS count
                   FROM inq2 x
                  WHERE ((x.customer_id = c.id) AND x.completed)) AS completed_inq,
            ( SELECT count(*) AS count
                   FROM inq2 x
                  WHERE ((x.customer_id = c.id) AND x.stalled)) AS stalled_inq,
            ( SELECT max(GREATEST(x.created_at, COALESCE(x.stage_changed_at, x.created_at))) AS max
                   FROM inq2 x
                  WHERE (x.customer_id = c.id)) AS last_activity,
            ( SELECT round(avg(x.resp_hrs), 1) AS round
                   FROM inq2 x
                  WHERE ((x.customer_id = c.id) AND (x.resp_hrs IS NOT NULL))) AS avg_resp_hrs,
            ( SELECT round(avg(r.rating), 2) AS round
                   FROM reviews r
                  WHERE (r.customer_id = c.id)) AS avg_review,
            ( SELECT count(*) AS count
                   FROM reviews r
                  WHERE ((r.customer_id = c.id) AND (r.rating <= 2))) AS bad_reviews,
            ( SELECT count(*) AS count
                   FROM transactions t
                  WHERE ((t.customer_id = c.id) AND ((t.refund_status IS NOT NULL) OR (t.refund_requested_at IS NOT NULL)))) AS disputes
           FROM customers c
        ), scored AS (
         SELECT cust.customer_id,
            cust.full_name,
            cust.email,
            cust.banned,
            cust.strikes,
            cust.total_inq,
            cust.active_inq,
            cust.progressed_inq,
            cust.completed_inq,
            cust.stalled_inq,
            cust.last_activity,
            cust.avg_resp_hrs,
            cust.avg_review,
            cust.bad_reviews,
            cust.disputes,
            ((cust.last_activity IS NOT NULL) AND (cust.last_activity < (now() - '45 days'::interval))) AS dormant,
            round(LEAST((100)::numeric, ((
                CASE
                    WHEN (cust.last_activity >= (now() - '30 days'::interval)) THEN 60
                    WHEN (cust.last_activity >= (now() - '60 days'::interval)) THEN 40
                    WHEN (cust.last_activity >= (now() - '120 days'::interval)) THEN 20
                    ELSE 5
                END)::numeric + (((LEAST(cust.total_inq, (5)::bigint))::numeric / 5.0) * (40)::numeric))), 1) AS engagement,
            round(GREATEST((0)::numeric, LEAST((100)::numeric, (((
                CASE
                    WHEN (cust.avg_review IS NOT NULL) THEN ((cust.avg_review / 5.0) * (100)::numeric)
                    ELSE (70)::numeric
                END - (
                CASE
                    WHEN (cust.disputes > 0) THEN 30
                    ELSE 0
                END)::numeric) - ((cust.bad_reviews * 15))::numeric) - ((LEAST(cust.strikes, 3) * 10))::numeric))), 1) AS satisfaction,
            round(
                CASE
                    WHEN (cust.active_inq > 0) THEN (((cust.progressed_inq)::numeric / (cust.active_inq)::numeric) * (100)::numeric)
                    WHEN (cust.total_inq = 0) THEN (50)::numeric
                    ELSE (20)::numeric
                END, 1) AS progress,
            round((GREATEST(0, (
                CASE
                    WHEN (cust.avg_resp_hrs IS NULL) THEN 60
                    WHEN (cust.avg_resp_hrs < (24)::numeric) THEN 100
                    WHEN (cust.avg_resp_hrs < (72)::numeric) THEN 70
                    WHEN (cust.avg_resp_hrs < (168)::numeric) THEN 40
                    ELSE 20
                END -
                CASE
                    WHEN (cust.disputes > 0) THEN 40
                    ELSE 0
                END)))::numeric, 1) AS service
           FROM cust
        )
 SELECT customer_id,
    full_name,
    email,
    total_inq,
    active_inq,
    progressed_inq,
    completed_inq,
    stalled_inq,
    avg_resp_hrs,
    avg_review,
    bad_reviews,
    disputes,
    dormant,
    strikes,
    banned,
    last_activity,
    engagement,
    satisfaction,
    progress,
    service,
    round(((((engagement * 0.25) + (satisfaction * 0.30)) + (progress * 0.25)) + (service * 0.20)), 1) AS health,
        CASE
            WHEN (banned OR (disputes > 0) OR (bad_reviews > 0) OR ((total_inq > 0) AND (active_inq = 0)) OR (round(((((engagement * 0.25) + (satisfaction * 0.30)) + (progress * 0.25)) + (service * 0.20)), 1) < (40)::numeric)) THEN 'high'::text
            WHEN ((stalled_inq > 0) OR (strikes > 0) OR dormant OR (round(((((engagement * 0.25) + (satisfaction * 0.30)) + (progress * 0.25)) + (service * 0.20)), 1) < (65)::numeric)) THEN 'medium'::text
            ELSE 'low'::text
        END AS risk_tier
   FROM scored;

CREATE OR REPLACE VIEW public.customer_kpis AS  SELECT count(*) AS customers,
    round(avg(health), 1) AS avg_health,
    round(avg(satisfaction), 1) AS avg_satisfaction,
    round(avg(avg_resp_hrs) FILTER (WHERE (avg_resp_hrs IS NOT NULL)), 1) AS avg_response_hrs,
    round(((100.0 * (count(*) FILTER (WHERE (progress >= (60)::numeric)))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS pct_progressing,
    count(*) FILTER (WHERE (disputes > 0)) AS open_disputes,
    count(*) FILTER (WHERE (stalled_inq > 0)) AS with_stalled,
    count(*) FILTER (WHERE dormant) AS dormant_count,
    count(*) FILTER (WHERE (risk_tier = 'high'::text)) AS risk_high,
    count(*) FILTER (WHERE (risk_tier = 'medium'::text)) AS risk_medium,
    count(*) FILTER (WHERE (risk_tier = 'low'::text)) AS risk_low
   FROM customer_health;

CREATE OR REPLACE VIEW public.document_inventory AS  SELECT o.bucket_id AS bucket,
    o.name AS path,
    COALESCE(((o.metadata ->> 'size'::text))::bigint, (0)::bigint) AS bytes,
    COALESCE((o.metadata ->> 'mimetype'::text), ''::text) AS mime,
    o.created_at,
    rp.retention_days,
    rp.class AS retention_class,
    ((rp.retention_days IS NOT NULL) AND (o.created_at < (now() - ((rp.retention_days || ' days'::text))::interval))) AS past_retention,
    (EXISTS ( SELECT 1
           FROM documents d
          WHERE ((d.bucket = o.bucket_id) AND (d.path = o.name)))) AS registered,
    (EXISTS ( SELECT 1
           FROM documents d
          WHERE ((d.bucket = o.bucket_id) AND (d.path = o.name) AND (d.extracted IS NOT NULL)))) AS ocr_done
   FROM (storage.objects o
     LEFT JOIN retention_policy rp ON ((rp.bucket = o.bucket_id)))
  WHERE ((o.name IS NOT NULL) AND ("right"(o.name, 1) <> '/'::text));

CREATE OR REPLACE VIEW public.document_kpis AS  SELECT ( SELECT count(*) AS count
           FROM document_inventory) AS total_documents,
    ( SELECT COALESCE(sum(document_inventory.bytes), (0)::numeric) AS "coalesce"
           FROM document_inventory) AS total_bytes,
    ( SELECT count(DISTINCT document_inventory.bucket) AS count
           FROM document_inventory) AS buckets,
    ( SELECT count(*) AS count
           FROM document_inventory
          WHERE document_inventory.past_retention) AS past_retention,
    ( SELECT count(*) AS count
           FROM document_inventory
          WHERE (document_inventory.bytes > ((30 * 1024) * 1024))) AS oversized,
    ( SELECT count(*) AS count
           FROM documents) AS registered_docs,
    ( SELECT count(*) AS count
           FROM documents
          WHERE (documents.extracted IS NOT NULL)) AS ocr_done,
    ( SELECT count(*) AS count
           FROM documents
          WHERE ((COALESCE(documents.status, ''::text) <> ALL (ARRAY['done'::text, 'skipped'::text])) OR (COALESCE(documents.error, ''::text) <> ''::text))) AS ocr_backlog,
    round(((100.0 * (( SELECT count(*) AS count
           FROM documents
          WHERE (documents.extracted IS NOT NULL)))::numeric) / (NULLIF(( SELECT count(*) AS count
           FROM documents), 0))::numeric), 1) AS ocr_coverage_pct,
    ( SELECT count(*) AS count
           FROM doc_versions) AS version_records,
    ( SELECT max(objects.created_at) AS max
           FROM storage.objects
          WHERE (objects.bucket_id = 'backups'::text)) AS last_backup_at,
    ( SELECT ((EXTRACT(epoch FROM (now() - max(objects.created_at))) / (86400)::numeric))::integer AS int4
           FROM storage.objects
          WHERE (objects.bucket_id = 'backups'::text)) AS days_since_backup,
    ( SELECT count(*) AS count
           FROM legal_documents) AS legal_documents,
    ( SELECT count(*) AS count
           FROM dropbox_files
          WHERE (NOT dropbox_files.is_folder)) AS dropbox_files,
    ( SELECT count(*) AS count
           FROM dropbox_files
          WHERE dropbox_files.is_folder) AS dropbox_folders,
    ( SELECT COALESCE(sum(dropbox_files.size), (0)::numeric) AS "coalesce"
           FROM dropbox_files) AS dropbox_bytes,
    ( SELECT max(dropbox_files.synced_at) AS max
           FROM dropbox_files) AS dropbox_last_sync;

CREATE OR REPLACE VIEW public.executive_control_session AS  SELECT id,
    user_id,
        CASE
            WHEN ((closed_at IS NULL) AND (expires_at > now())) THEN 'control'::text
            ELSE 'observe'::text
        END AS mode,
    mfa_ref AS mfa_session_id,
    reason,
    opened_at AS created_at,
    expires_at,
    closed_at AS revoked_at
   FROM control_mode_session s;

CREATE OR REPLACE VIEW public.fa_register AS  SELECT id,
    asset_no,
    name,
    category,
    acquire_date,
    in_service_date,
    cost,
    salvage_value,
    useful_life_months,
    accumulated_depreciation,
    (cost - accumulated_depreciation) AS net_book_value,
    status,
    disposed_date
   FROM fa_assets
  ORDER BY asset_no;

CREATE OR REPLACE VIEW public.finance_kpis AS  WITH rr AS (
         SELECT COALESCE(sum(
                CASE
                    WHEN (ga.type = 'revenue'::text) THEN (l.credit - l.debit)
                    ELSE (0)::numeric
                END), (0)::numeric) AS rev30,
            COALESCE(sum(
                CASE
                    WHEN (ga.type = 'expense'::text) THEN (l.debit - l.credit)
                    ELSE (0)::numeric
                END), (0)::numeric) AS exp30
           FROM ((gl_journal_lines l
             JOIN gl_journal j ON (((j.id = l.journal_id) AND (j.status = 'posted'::text))))
             JOIN gl_accounts ga ON ((ga.code = l.account_code)))
          WHERE (j.entry_date >= (CURRENT_DATE - 30))
        ), ar AS (
         SELECT COALESCE(sum(supplier_dues.amount_due) FILTER (WHERE (supplier_dues.status <> ALL (ARRAY['paid'::text, 'waived'::text]))), (0)::numeric) AS ar_outstanding,
            COALESCE(sum(supplier_dues.amount_due) FILTER (WHERE ((supplier_dues.status <> ALL (ARRAY['paid'::text, 'waived'::text])) AND (supplier_dues.due_date_30 < CURRENT_DATE))), (0)::numeric) AS ar_overdue,
            COALESCE(sum(supplier_dues.amount_due) FILTER (WHERE (supplier_dues.status = 'paid'::text)), (0)::numeric) AS ar_collected
           FROM supplier_dues
        ), ap AS (
         SELECT COALESCE(sum(ap_open_bills.balance_due), (0)::numeric) AS ap_outstanding,
            COALESCE(sum(ap_open_bills.balance_due) FILTER (WHERE (ap_open_bills.days_overdue > 0)), (0)::numeric) AS ap_overdue
           FROM ap_open_bills
        ), bud AS (
         SELECT count(*) FILTER (WHERE ((budget_vs_actual_summary.type = 'expense'::text) AND (budget_vs_actual_summary.pct_of_budget > (110)::numeric))) AS budget_overruns
           FROM budget_vs_actual_summary
        )
 SELECT ( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
           FROM gl_account_balances
          WHERE (gl_account_balances.code = ANY (ARRAY['1000'::text, '1050'::text]))) AS cash,
    ( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
           FROM gl_account_balances
          WHERE (gl_account_balances.type = 'revenue'::text)) AS revenue_total,
    ( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
           FROM gl_account_balances
          WHERE (gl_account_balances.type = 'expense'::text)) AS expense_total,
    (( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
           FROM gl_account_balances
          WHERE (gl_account_balances.type = 'revenue'::text)) - ( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
           FROM gl_account_balances
          WHERE (gl_account_balances.type = 'expense'::text))) AS net_income,
        CASE
            WHEN (( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.type = 'revenue'::text)) > (0)::numeric) THEN round(((100.0 * (( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.type = 'revenue'::text)) - ( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.type = 'expense'::text)))) / ( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.type = 'revenue'::text))), 1)
            ELSE NULL::numeric
        END AS margin_pct,
    rr.rev30 AS revenue_30d,
    rr.exp30 AS expense_30d,
    (rr.exp30 - rr.rev30) AS monthly_burn,
        CASE
            WHEN (((rr.exp30 - rr.rev30) > (0)::numeric) AND (( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.code = ANY (ARRAY['1000'::text, '1050'::text]))) > (0)::numeric)) THEN round((( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.code = ANY (ARRAY['1000'::text, '1050'::text]))) / (rr.exp30 - rr.rev30)), 1)
            ELSE NULL::numeric
        END AS runway_months,
    ar.ar_outstanding,
    ar.ar_overdue,
    ar.ar_collected,
        CASE
            WHEN ((ar.ar_collected + ar.ar_outstanding) > (0)::numeric) THEN round(((100.0 * ar.ar_collected) / (ar.ar_collected + ar.ar_outstanding)), 1)
            ELSE NULL::numeric
        END AS collection_rate,
    ap.ap_outstanding,
    ap.ap_overdue,
    bud.budget_overruns
   FROM rr,
    ar,
    ap,
    bud;

CREATE OR REPLACE VIEW public.gl_account_balances AS  SELECT a.code,
    a.name,
    a.type,
    a.normal_balance,
    COALESCE(sum(l.debit), (0)::numeric) AS debit_total,
    COALESCE(sum(l.credit), (0)::numeric) AS credit_total,
        CASE
            WHEN (a.normal_balance = 'D'::bpchar) THEN (COALESCE(sum(l.debit), (0)::numeric) - COALESCE(sum(l.credit), (0)::numeric))
            ELSE (COALESCE(sum(l.credit), (0)::numeric) - COALESCE(sum(l.debit), (0)::numeric))
        END AS balance
   FROM ((gl_accounts a
     LEFT JOIN gl_journal_lines l ON ((l.account_code = a.code)))
     LEFT JOIN gl_journal j ON (((j.id = l.journal_id) AND (j.status = 'posted'::text))))
  GROUP BY a.code, a.name, a.type, a.normal_balance;

CREATE OR REPLACE VIEW public.gl_balance_sheet AS  SELECT type,
    code,
    name,
    balance AS amount
   FROM gl_account_balances
  WHERE (type = ANY (ARRAY['asset'::text, 'liability'::text, 'equity'::text]))
  ORDER BY type, code;

CREATE OR REPLACE VIEW public.gl_ledger AS  SELECT j.id AS journal_id,
    j.entry_no,
    j.entry_date,
    j.source,
    j.source_ref,
    j.memo,
    l.account_code,
    a.name AS account_name,
    a.type AS account_type,
    l.debit,
    l.credit
   FROM ((gl_journal j
     JOIN gl_journal_lines l ON ((l.journal_id = j.id)))
     JOIN gl_accounts a ON ((a.code = l.account_code)))
  WHERE (j.status = 'posted'::text);

CREATE OR REPLACE VIEW public.gl_pnl AS  SELECT type,
    code,
    name,
    balance AS amount
   FROM gl_account_balances
  WHERE (type = ANY (ARRAY['revenue'::text, 'expense'::text]))
  ORDER BY type DESC, code;

CREATE OR REPLACE VIEW public.gl_trial_balance AS  SELECT code,
    name,
    type,
        CASE
            WHEN ((balance >= (0)::numeric) AND (normal_balance = 'D'::bpchar)) THEN balance
            ELSE (0)::numeric
        END AS debit,
        CASE
            WHEN ((balance >= (0)::numeric) AND (normal_balance = 'C'::bpchar)) THEN balance
            ELSE (0)::numeric
        END AS credit,
    balance
   FROM gl_account_balances
  WHERE ((debit_total <> (0)::numeric) OR (credit_total <> (0)::numeric))
  ORDER BY code;

CREATE OR REPLACE VIEW public.governance_kpis AS  WITH agents AS (
         SELECT category_agents.slug,
            category_agents.persona
           FROM category_agents
          WHERE category_agents.active
        ), kn AS (
         SELECT DISTINCT agent_knowledge.agent_key
           FROM agent_knowledge
        ), act30 AS (
         SELECT agent_actions.id,
            agent_actions.agent,
            agent_actions.kind,
            agent_actions.status,
            agent_actions.risk,
            agent_actions.title,
            agent_actions.recommendation,
            agent_actions.detail,
            agent_actions.target_table,
            agent_actions.target_id,
            agent_actions.created_at,
            agent_actions.decided_at,
            agent_actions.decided_by,
            agent_actions.confidence,
            agent_actions.evidence,
            agent_actions.escalated,
            agent_actions.escalation_reason
           FROM agent_actions
          WHERE (agent_actions.created_at > (now() - '30 days'::interval))
        )
 SELECT ( SELECT count(*) AS count
           FROM agents) AS active_agents,
    ( SELECT count(*) AS count
           FROM agents
          WHERE ((agents.persona IS NOT NULL) AND (length(agents.persona) > 40))) AS agents_with_persona,
    ( SELECT count(*) AS count
           FROM agent_knowledge
          WHERE (agent_knowledge.agent_key = '_global'::text)) AS global_rules,
    ( SELECT count(*) AS count
           FROM agent_knowledge) AS knowledge_items,
    ( SELECT agent_governance.version
           FROM agent_governance
          WHERE agent_governance.active
          ORDER BY agent_governance.version DESC
         LIMIT 1) AS governance_version,
    ( SELECT count(*) AS count
           FROM act30) AS decisions_30d,
    ( SELECT count(*) AS count
           FROM act30
          WHERE (act30.confidence IS NOT NULL)) AS decisions_with_confidence,
    ( SELECT round(avg(act30.confidence), 2) AS round
           FROM act30
          WHERE (act30.confidence IS NOT NULL)) AS avg_confidence,
    ( SELECT count(*) AS count
           FROM act30
          WHERE act30.escalated) AS escalated_30d,
    ( SELECT count(*) AS count
           FROM agent_actions
          WHERE (agent_actions.status = ANY (ARRAY['pending'::text, 'needs_review'::text]))) AS open_for_review,
    ( SELECT count(*) AS count
           FROM agent_actions) AS audit_trail_total,
    ( SELECT count(DISTINCT agent_actions.agent) AS count
           FROM agent_actions) AS agents_with_audit_trail;

CREATE OR REPLACE VIEW public.inquiries_supplier_live AS  SELECT id,
    category,
    emirate,
    role_needed,
    status,
    created_at,
    scope_type,
    trades,
    keywords,
    brief_source,
    urgency,
    boq_confidence,
    drawing_redacted_paths,
    outcome,
    hired_supplier_id,
    summary_masked AS summary,
    raw_input_masked AS raw_input,
    budget_masked AS budget,
    spec_masked AS spec,
    boq_masked AS boq,
    completeness_masked AS completeness
   FROM inquiries i;

CREATE OR REPLACE VIEW public.inquiries_supplier_safe AS  SELECT i.id,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'category'::text)
            ELSE i.category
        END AS category,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'emirate'::text)
            ELSE i.emirate
        END AS emirate,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'role_needed'::text)
            ELSE i.role_needed
        END AS role_needed,
    i.status,
        CASE
            WHEN (b.brief IS NOT NULL) THEN ((b.brief ->> 'created_at'::text))::timestamp with time zone
            ELSE i.created_at
        END AS created_at,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'scope_type'::text)
            ELSE i.scope_type
        END AS scope_type,
        CASE
            WHEN (b.brief IS NOT NULL) THEN fn_jsonb_text_array((b.brief -> 'trades'::text))
            ELSE i.trades
        END AS trades,
        CASE
            WHEN (b.brief IS NOT NULL) THEN fn_jsonb_text_array((b.brief -> 'keywords'::text))
            ELSE i.keywords
        END AS keywords,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'brief_source'::text)
            ELSE i.brief_source
        END AS brief_source,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'urgency'::text)
            ELSE i.urgency
        END AS urgency,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'boq_confidence'::text)
            ELSE i.boq_confidence
        END AS boq_confidence,
        CASE
            WHEN (b.brief IS NOT NULL) THEN fn_jsonb_text_array((b.brief -> 'drawing_redacted_paths'::text))
            ELSE i.drawing_redacted_paths
        END AS drawing_redacted_paths,
    i.outcome,
    i.hired_supplier_id,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'summary'::text)
            ELSE i.summary_masked
        END AS summary,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'raw_input'::text)
            ELSE i.raw_input_masked
        END AS raw_input,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'budget'::text)
            ELSE i.budget_masked
        END AS budget,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief -> 'spec'::text)
            ELSE i.spec_masked
        END AS spec,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief -> 'boq'::text)
            ELSE i.boq_masked
        END AS boq,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief -> 'completeness'::text)
            ELSE i.completeness_masked
        END AS completeness
   FROM (inquiries i
     LEFT JOIN LATERAL ( SELECT b2.brief
           FROM inquiry_supplier_brief b2
          WHERE (b2.inquiry_id = i.id)
          ORDER BY b2.version DESC
         LIMIT 1) b ON (true));

CREATE OR REPLACE VIEW public.inv_on_hand AS  SELECT i.id,
    i.sku,
    i.name,
    i.uom,
    i.category,
    COALESCE(sum(m.qty_delta), (0)::numeric) AS qty_on_hand,
    COALESCE(sum(m.cost_delta), (0)::numeric) AS inventory_value,
        CASE
            WHEN (COALESCE(sum(m.qty_delta), (0)::numeric) <> (0)::numeric) THEN round((sum(m.cost_delta) / sum(m.qty_delta)), 4)
            ELSE (0)::numeric
        END AS avg_unit_cost,
    i.reorder_point,
    (COALESCE(sum(m.qty_delta), (0)::numeric) <= i.reorder_point) AS needs_reorder
   FROM (inv_items i
     LEFT JOIN inv_stock_moves m ON ((m.item_id = i.id)))
  GROUP BY i.id, i.sku, i.name, i.uom, i.category, i.reorder_point;

CREATE OR REPLACE VIEW public.inv_valuation AS  SELECT COALESCE(sum(cost_delta), (0)::numeric) AS total_inventory_value,
    count(DISTINCT item_id) FILTER (WHERE true) AS items_with_moves
   FROM inv_stock_moves;

CREATE OR REPLACE VIEW public.knowledge_kpis AS  WITH cats AS (
         SELECT category_agents.slug,
            category_agents.requires_regulation
           FROM category_agents
          WHERE (category_agents.active AND (category_agents.slug !~ '_'::text))
        ), base AS (
         SELECT ( SELECT count(*) AS count
                   FROM cats) AS categories_total,
            ( SELECT count(*) AS count
                   FROM cats c
                  WHERE (EXISTS ( SELECT 1
                           FROM agent_knowledge k
                          WHERE (k.agent_key = ('cat:'::text || c.slug))))) AS cat_with_knowledge,
            ( SELECT count(*) AS count
                   FROM cats c
                  WHERE (EXISTS ( SELECT 1
                           FROM qualification_playbooks p
                          WHERE ((p.category = c.slug) OR (c.slug ~~* (('%'::text || p.category) || '%'::text)) OR (p.category ~~* (('%'::text || c.slug) || '%'::text)))))) AS cat_with_playbook,
            ( SELECT count(*) AS count
                   FROM cats c
                  WHERE (EXISTS ( SELECT 1
                           FROM regulations r
                          WHERE ((r.status = 'active'::text) AND (r.approved_at IS NOT NULL) AND (c.slug = ANY (r.categories)))))) AS cat_with_regs,
            ( SELECT count(*) AS count
                   FROM cats c
                  WHERE c.requires_regulation) AS regs_required,
            ( SELECT count(*) AS count
                   FROM cats c
                  WHERE (c.requires_regulation AND (EXISTS ( SELECT 1
                           FROM regulations r
                          WHERE ((r.status = 'active'::text) AND (r.approved_at IS NOT NULL) AND (c.slug = ANY (r.categories))))))) AS cat_regulated_covered,
            ( SELECT count(*) AS count
                   FROM regulations) AS regulations,
            ( SELECT count(*) AS count
                   FROM regulations
                  WHERE ((regulations.status = 'active'::text) AND (regulations.approved_at IS NOT NULL))) AS regulations_published,
            ( SELECT count(*) AS count
                   FROM regulations
                  WHERE (regulations.approved_at IS NULL)) AS regulations_pending,
            ( SELECT count(*) AS count
                   FROM mdm_standards) AS standards,
            ( SELECT count(*) AS count
                   FROM mdm_manufacturers) AS manufacturers,
            ( SELECT count(*) AS count
                   FROM mdm_brands) AS brands,
            ( SELECT count(*) AS count
                   FROM materials) AS materials,
            ( SELECT count(*) AS count
                   FROM qualification_playbooks) AS playbooks,
            ( SELECT count(*) AS count
                   FROM category_specs) AS category_specs,
            ( SELECT count(*) AS count
                   FROM kb_chunks) AS chunks,
            ( SELECT count(*) AS count
                   FROM agent_knowledge) AS knowledge_entries,
            ( SELECT count(*) AS count
                   FROM kb_revisions) AS revisions,
            ( SELECT count(*) AS count
                   FROM kb_revisions
                  WHERE ((COALESCE((kb_revisions.ai_validation ->> 'result'::text), 'pass'::text) = ANY (ARRAY['fail'::text, 'flag'::text, 'warn'::text])) OR (kb_revisions.status = 'rejected'::text))) AS flagged_revisions,
            ( SELECT count(*) AS count
                   FROM compliance_sources
                  WHERE compliance_sources.active) AS compliance_active,
            ( SELECT count(*) AS count
                   FROM compliance_sources
                  WHERE (compliance_sources.active AND (compliance_sources.last_checked_at >= (now() - '45 days'::interval)))) AS compliance_fresh,
            ( SELECT count(*) AS count
                   FROM category_specs
                  WHERE (category_specs.updated_at >= (now() - '180 days'::interval))) AS specs_fresh,
            ( SELECT count(*) AS count
                   FROM regulations
                  WHERE (regulations.updated_at >= (now() - '365 days'::interval))) AS regs_fresh,
            ( SELECT count(*) AS count
                   FROM kb_usage_log
                  WHERE (kb_usage_log.created_at >= (now() - '30 days'::interval))) AS queries_30d,
            ( SELECT count(DISTINCT kb_usage_log.category) AS count
                   FROM kb_usage_log
                  WHERE (kb_usage_log.created_at >= (now() - '30 days'::interval))) AS topics_queried_30d
        )
 SELECT categories_total,
    cat_with_knowledge,
    cat_with_playbook,
    cat_with_regs,
    regulations,
    regulations_published,
    regulations_pending,
    standards,
    manufacturers,
    brands,
    materials,
    playbooks,
    category_specs,
    chunks,
    knowledge_entries,
    revisions,
    flagged_revisions,
    compliance_active,
    compliance_fresh,
    specs_fresh,
    regs_fresh,
    queries_30d,
    topics_queried_30d,
    round(((100.0 * ((((cat_with_knowledge)::numeric / (NULLIF(categories_total, 0))::numeric) + ((cat_with_playbook)::numeric / (NULLIF(categories_total, 0))::numeric)) + COALESCE(((cat_regulated_covered)::numeric / (NULLIF(regs_required, 0))::numeric), (1)::numeric))) / 3.0), 1) AS coverage_pct,
    round(((100.0 * (cat_with_knowledge)::numeric) / (NULLIF(categories_total, 0))::numeric), 1) AS knowledge_coverage_pct,
    round(((100.0 * (cat_with_playbook)::numeric) / (NULLIF(categories_total, 0))::numeric), 1) AS playbook_coverage_pct,
    round(((100.0 * ((revisions - flagged_revisions))::numeric) / (NULLIF(revisions, 0))::numeric), 1) AS accuracy_pct,
    round(((100.0 * ((COALESCE(((compliance_fresh)::numeric / (NULLIF(compliance_active, 0))::numeric), (1)::numeric) + COALESCE(((specs_fresh)::numeric / (NULLIF(category_specs, 0))::numeric), (1)::numeric)) + COALESCE(((regs_fresh)::numeric / (NULLIF(regulations, 0))::numeric), (1)::numeric))) / (3)::numeric), 1) AS freshness_pct,
    round(((100.0 * (cat_with_knowledge)::numeric) / (NULLIF(categories_total, 0))::numeric), 1) AS usage_reach_pct,
    round((100.0 * COALESCE(((cat_regulated_covered)::numeric / (NULLIF(regs_required, 0))::numeric), (1)::numeric)), 1) AS regulation_coverage_pct,
    regs_required,
    cat_regulated_covered
   FROM base b;

CREATE OR REPLACE VIEW public.legal_kpis AS  SELECT ( SELECT count(*) AS count
           FROM legal_documents) AS policies_published,
    ( SELECT count(*) AS count
           FROM legal_documents
          WHERE (legal_documents.updated_at < (now() - '365 days'::interval))) AS policies_stale,
    ( SELECT count(*) AS count
           FROM legal_checklist) AS required_total,
    ( SELECT count(*) AS count
           FROM legal_checklist
          WHERE legal_checklist.present) AS required_present,
    ( SELECT count(*) AS count
           FROM legal_checklist
          WHERE (NOT legal_checklist.present)) AS required_missing,
    ( SELECT count(*) AS count
           FROM legal_checklist
          WHERE ((NOT legal_checklist.present) AND (legal_checklist.priority = 1))) AS critical_missing,
    round(((100.0 * (( SELECT count(*) AS count
           FROM legal_checklist
          WHERE legal_checklist.present))::numeric) / (NULLIF(( SELECT count(*) AS count
           FROM legal_checklist), 0))::numeric), 1) AS coverage_pct,
    ( SELECT count(*) AS count
           FROM customers) AS customers,
    round(((100.0 * (( SELECT count(*) AS count
           FROM customers
          WHERE (customers.tos_accepted_at IS NOT NULL)))::numeric) / (NULLIF(( SELECT count(*) AS count
           FROM customers), 0))::numeric), 1) AS customer_terms_acceptance_pct,
    ( SELECT count(*) AS count
           FROM leads
          WHERE (leads.approval_status = 'approved'::text)) AS suppliers_approved,
    round(((100.0 * (( SELECT count(*) AS count
           FROM leads
          WHERE ((leads.approval_status = 'approved'::text) AND (leads.accepted_terms_at IS NOT NULL))))::numeric) / (NULLIF(( SELECT count(*) AS count
           FROM leads
          WHERE (leads.approval_status = 'approved'::text)), 0))::numeric), 1) AS supplier_terms_acceptance_pct,
    ( SELECT count(*) AS count
           FROM agent_actions
          WHERE ((agent_actions.kind = 'legal_flag'::text) AND (agent_actions.status = ANY (ARRAY['pending'::text, 'needs_review'::text])))) AS open_legal_flags,
    ( SELECT count(*) AS count
           FROM legal_reviews
          WHERE ((legal_reviews.risk_level = 'high'::text) AND legal_reviews.needs_licensed_review)) AS high_risk_reviews;

CREATE OR REPLACE VIEW public.marketing_category_demand AS  WITH cats AS (
         SELECT DISTINCT COALESCE(NULLIF(inquiries.category, ''::text), 'other'::text) AS c
           FROM inquiries
          WHERE (inquiries.category IS NOT NULL)
        UNION
         SELECT seo_categories.slug
           FROM seo_categories
        )
 SELECT c AS category,
    ( SELECT count(*) AS count
           FROM inquiries i
          WHERE ((COALESCE(NULLIF(i.category, ''::text), 'other'::text) = c.c) AND (i.created_at >= (now() - '90 days'::interval)))) AS inquiries_90d,
    ( SELECT count(*) AS count
           FROM leads l
          WHERE ((l.approval_status = 'approved'::text) AND (l.claimed = true) AND (l.categories ~~* (('%'::text || c.c) || '%'::text)))) AS suppliers,
    (EXISTS ( SELECT 1
           FROM seo_categories s
          WHERE ((s.slug = c.c) AND s.generated))) AS has_seo_page,
    (EXISTS ( SELECT 1
           FROM blog_posts b
          WHERE ((b.category = c.c) AND b.published))) AS has_blog
   FROM cats c;

CREATE OR REPLACE VIEW public.marketing_kpis AS  WITH f AS (
         SELECT funnel_metrics(30) AS fm
        ), mi AS (
         SELECT COALESCE(sum(meta_insights.spend), (0)::numeric) AS meta_spend,
            COALESCE(sum(meta_insights.impressions), (0)::numeric) AS meta_impr,
            COALESCE(sum(meta_insights.clicks), (0)::numeric) AS meta_clicks,
            COALESCE(sum(meta_insights.results), (0)::numeric) AS meta_results,
            count(*) FILTER (WHERE (meta_insights.effective_status = 'ACTIVE'::text)) AS meta_active
           FROM meta_insights
          WHERE ((meta_insights.time_window = 'last_30d'::text) AND (meta_insights.campaign_name ~~* '%quotesdone%'::text))
        )
 SELECT ((f.fm ->> 'inquiries'::text))::integer AS inquiries_30d,
    ((f.fm ->> 'matched'::text))::integer AS matched_30d,
    ((f.fm ->> 'quoted'::text))::integer AS quoted_30d,
    ((f.fm ->> 'revealed'::text))::integer AS revealed_30d,
    ((f.fm ->> 'reveal_fees'::text))::numeric AS revenue_30d,
        CASE
            WHEN (((f.fm ->> 'inquiries'::text))::integer > 0) THEN round(((100.0 * (((f.fm ->> 'quoted'::text))::integer)::numeric) / (((f.fm ->> 'inquiries'::text))::integer)::numeric), 1)
            ELSE NULL::numeric
        END AS inq_to_quote_pct,
        CASE
            WHEN (((f.fm ->> 'quoted'::text))::integer > 0) THEN round(((100.0 * (((f.fm ->> 'revealed'::text))::integer)::numeric) / (((f.fm ->> 'quoted'::text))::integer)::numeric), 1)
            ELSE NULL::numeric
        END AS quote_to_reveal_pct,
    ( SELECT count(*) AS count
           FROM blog_posts
          WHERE blog_posts.published) AS blog_published,
    ( SELECT count(*) AS count
           FROM blog_posts) AS blog_total,
    ( SELECT count(*) AS count
           FROM content_drafts
          WHERE (COALESCE(content_drafts.status, ''::text) <> ALL (ARRAY['published'::text, 'discarded'::text]))) AS drafts_pending,
    ( SELECT count(*) AS count
           FROM social_posts
          WHERE (COALESCE(social_posts.status, ''::text) = ANY (ARRAY['staged'::text, 'scheduled'::text, 'draft'::text, 'pending'::text]))) AS social_staged,
    ( SELECT count(*) AS count
           FROM social_posts
          WHERE (COALESCE(social_posts.status, ''::text) = ANY (ARRAY['published'::text, 'sent'::text]))) AS social_published,
    ( SELECT count(*) AS count
           FROM seo_categories) AS seo_pages,
    ( SELECT count(*) AS count
           FROM seo_categories
          WHERE seo_categories.generated) AS seo_generated,
    ( SELECT count(*) AS count
           FROM leads) AS leads_total,
    ( SELECT count(*) AS count
           FROM outreach) AS outreach_sent,
    ( SELECT COALESCE(gl_account_balances.balance, (0)::numeric) AS "coalesce"
           FROM gl_account_balances
          WHERE (gl_account_balances.code = '6200'::text)) AS mkt_spend,
    ( SELECT count(*) AS count
           FROM customers
          WHERE (customers.created_at >= (now() - '30 days'::interval))) AS new_customers_30d,
        CASE
            WHEN (mi.meta_spend > (0)::numeric) THEN round((mi.meta_spend / (NULLIF(( SELECT count(*) AS count
               FROM customers
              WHERE (customers.created_at >= (now() - '30 days'::interval))), 0))::numeric), 2)
            ELSE NULL::numeric
        END AS cac,
        CASE
            WHEN (mi.meta_spend > (0)::numeric) THEN round((((f.fm ->> 'reveal_fees'::text))::numeric / mi.meta_spend), 2)
            WHEN (( SELECT COALESCE(gl_account_balances.balance, (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.code = '6200'::text)) > (0)::numeric) THEN round((((f.fm ->> 'reveal_fees'::text))::numeric / ( SELECT COALESCE(gl_account_balances.balance, (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.code = '6200'::text))), 2)
            ELSE NULL::numeric
        END AS roi,
    ( SELECT count(*) AS count
           FROM marketing_category_demand
          WHERE ((marketing_category_demand.inquiries_90d > 0) AND (marketing_category_demand.suppliers = 0))) AS supply_gaps,
    ( SELECT count(*) AS count
           FROM marketing_category_demand
          WHERE (NOT marketing_category_demand.has_seo_page)) AS seo_gaps,
    mi.meta_spend AS meta_spend_30d,
    mi.meta_impr AS meta_impressions_30d,
    mi.meta_clicks AS meta_clicks_30d,
    mi.meta_results AS meta_results_30d,
    mi.meta_active AS meta_active_campaigns,
        CASE
            WHEN (mi.meta_results > (0)::numeric) THEN round((mi.meta_spend / mi.meta_results), 2)
            ELSE NULL::numeric
        END AS meta_cpl,
        CASE
            WHEN (mi.meta_spend > (0)::numeric) THEN round((((f.fm ->> 'reveal_fees'::text))::numeric / mi.meta_spend), 2)
            ELSE NULL::numeric
        END AS meta_roi
   FROM f,
    mi;

CREATE OR REPLACE VIEW public.marketplace_health AS  SELECT fn_health_index() AS health;

CREATE OR REPLACE VIEW public.ops_kpis AS  WITH m AS (
         SELECT fn_ops_metrics() AS j
        )
 SELECT ((j ->> 'open_rfqs_no_quotes_7d'::text))::integer AS no_quote_backlog,
    ((j ->> 'matched_not_quoted'::text))::integer AS matched_not_quoted,
    ((j ->> 'avg_first_quote_hours'::text))::numeric AS avg_first_quote_hours,
    ((j ->> 'response_rate_pct'::text))::numeric AS response_rate_pct,
    ((j ->> 'overdue_activities'::text))::integer AS overdue_activities,
    ( SELECT count(*) AS count
           FROM agent_actions
          WHERE (agent_actions.status = ANY (ARRAY['pending'::text, 'needs_review'::text]))) AS pending_approvals,
    ( SELECT count(*) AS count
           FROM agent_actions
          WHERE ((agent_actions.status = ANY (ARRAY['pending'::text, 'needs_review'::text])) AND (COALESCE(agent_actions.risk, ''::text) = ANY (ARRAY['high'::text, 'critical'::text])))) AS high_risk_pending,
    ( SELECT count(*) AS count
           FROM crm_tasks
          WHERE (COALESCE(crm_tasks.status, ''::text) <> 'done'::text)) AS open_tasks,
    ( SELECT count(*) AS count
           FROM crm_tasks
          WHERE ((COALESCE(crm_tasks.status, ''::text) <> 'done'::text) AND (crm_tasks.due_date < now()))) AS overdue_tasks,
    ( SELECT count(*) AS count
           FROM inquiries
          WHERE ((inquiries.status = 'quoted'::text) AND (NOT (EXISTS ( SELECT 1
                   FROM transactions t
                  WHERE ((t.inquiry_id = inquiries.id) AND (t.revealed_at IS NOT NULL))))))) AS awaiting_reveal,
    ( SELECT count(*) AS count
           FROM cron.job) AS cron_jobs,
    ( SELECT count(*) AS count
           FROM cron.job_run_details
          WHERE ((job_run_details.status <> 'succeeded'::text) AND (job_run_details.start_time >= (now() - '24:00:00'::interval)))) AS cron_failures_24h,
    ( SELECT count(*) AS count
           FROM agent_runs
          WHERE ((agent_runs.status = ANY (ARRAY['error'::text, 'failed'::text])) AND (agent_runs.started_at >= (now() - '24:00:00'::interval)))) AS agent_errors_24h,
    ( SELECT count(*) AS count
           FROM error_events
          WHERE (error_events.created_at >= (now() - '24:00:00'::interval))) AS app_errors_24h,
    ( SELECT count(*) AS count
           FROM agent_actions
          WHERE ((agent_actions.kind = ANY (ARRAY['incident'::text, 'security_incident'::text])) AND (agent_actions.status = ANY (ARRAY['pending'::text, 'needs_review'::text])))) AS open_incidents
   FROM m;

CREATE OR REPLACE VIEW public.po_open AS  SELECT o.id,
    o.po_no,
    v.name AS vendor,
    o.status,
    o.order_date,
    o.expected_date,
    o.subtotal,
    COALESCE(sum((l.qty * l.unit_price)), (0)::numeric) AS ordered_value,
    COALESCE(sum((l.qty_received * l.unit_price)), (0)::numeric) AS received_value,
    COALESCE(sum(((l.qty - l.qty_received) * l.unit_price)), (0)::numeric) AS outstanding_value
   FROM ((po_orders o
     JOIN po_vendors v ON ((v.id = o.vendor_id)))
     LEFT JOIN po_lines l ON ((l.po_id = o.id)))
  WHERE (o.status = ANY (ARRAY['draft'::text, 'approved'::text, 'partial'::text, 'received'::text]))
  GROUP BY o.id, o.po_no, v.name, o.status, o.order_date, o.expected_date, o.subtotal;

CREATE OR REPLACE VIEW public.project_summary AS  SELECT p.id AS project_id,
    p.customer_id,
    p.name,
    p.status,
    p.target_open_date,
    p.budget_total,
    p.created_at,
    count(i.id) AS rfq_count,
    count(i.id) FILTER (WHERE (i.status <> ALL (ARRAY['completed'::text, 'cancelled'::text]))) AS rfq_open,
    count(i.id) FILTER (WHERE (i.hired_supplier_id IS NOT NULL)) AS rfq_awarded,
    round(COALESCE(sum(i.expected_value), (0)::numeric), 0) AS pipeline_value,
    ( SELECT COALESCE(jsonb_agg(s.b ORDER BY (s.b ->> 'category'::text)), '[]'::jsonb) AS "coalesce"
           FROM ( SELECT jsonb_build_object('category', COALESCE(i2.category, 'uncategorised'::text), 'rfqs', count(*), 'open', count(*) FILTER (WHERE (i2.status <> ALL (ARRAY['completed'::text, 'cancelled'::text]))), 'awarded', count(*) FILTER (WHERE (i2.hired_supplier_id IS NOT NULL)), 'value_aed', round(COALESCE(sum(i2.expected_value), (0)::numeric), 0)) AS b
                   FROM inquiries i2
                  WHERE (i2.project_id = p.id)
                  GROUP BY COALESCE(i2.category, 'uncategorised'::text)) s) AS trade_breakdown,
    ( SELECT count(DISTINCT m.supplier_id) AS count
           FROM (inquiry_matches m
             JOIN inquiries i3 ON ((i3.id = m.inquiry_id)))
          WHERE (i3.project_id = p.id)) AS supplier_count,
        CASE
            WHEN (p.target_open_date IS NULL) THEN NULL::numeric
            WHEN (p.target_open_date <= (p.created_at)::date) THEN (100)::numeric
            ELSE round(LEAST((100)::numeric, GREATEST((0)::numeric, (((100)::numeric * ((CURRENT_DATE - (p.created_at)::date))::numeric) / (NULLIF((p.target_open_date - (p.created_at)::date), 0))::numeric))), 0)
        END AS timeline_pct
   FROM (projects p
     LEFT JOIN inquiries i ON ((i.project_id = p.id)))
  GROUP BY p.id, p.customer_id, p.name, p.status, p.target_open_date, p.budget_total, p.created_at;

CREATE OR REPLACE VIEW public.reg_coverage AS  SELECT count(*) FILTER (WHERE (copyright = 'free'::text)) AS free_codes,
    count(*) FILTER (WHERE ((copyright = 'free'::text) AND (status = 'indexed'::text))) AS indexed,
    count(*) FILTER (WHERE ((copyright = 'free'::text) AND (status <> 'indexed'::text))) AS missing,
    count(*) FILTER (WHERE ((priority = 1) AND (copyright = 'free'::text))) AS critical_total,
    count(*) FILTER (WHERE ((priority = 1) AND (copyright = 'free'::text) AND (status = 'indexed'::text))) AS critical_indexed,
    count(*) FILTER (WHERE (copyright = 'copyrighted'::text)) AS reference_only,
    round(((100.0 * (count(*) FILTER (WHERE ((copyright = 'free'::text) AND (status = 'indexed'::text))))::numeric) / (NULLIF(count(*) FILTER (WHERE (copyright = 'free'::text)), 0))::numeric), 1) AS coverage_pct
   FROM reg_catalog;

CREATE OR REPLACE VIEW public.report_kpis AS  WITH reg AS (
         SELECT report_registry.source,
            report_registry.report_type,
            report_registry.title,
            report_registry.period,
            report_registry.created_at,
            report_registry.id
           FROM report_registry
        ), lt AS (
         SELECT max(reg.created_at) FILTER (WHERE (reg.report_type = 'weekly'::text)) AS weekly_at,
            max(reg.created_at) FILTER (WHERE (reg.report_type = 'monthly'::text)) AS monthly_at,
            max(reg.created_at) FILTER (WHERE (reg.report_type = 'quarterly'::text)) AS quarterly_at,
            max(reg.created_at) FILTER (WHERE (reg.report_type = 'department'::text)) AS department_at,
            max(reg.created_at) FILTER (WHERE (reg.report_type = 'supplier'::text)) AS supplier_at,
            max(reg.created_at) FILTER (WHERE (reg.report_type = 'customer'::text)) AS customer_at,
            max(reg.created_at) FILTER (WHERE (reg.report_type = 'ai'::text)) AS ai_at,
            max(reg.created_at) FILTER (WHERE (reg.source = 'exec'::text)) AS exec_at,
            max(reg.created_at) FILTER (WHERE (reg.source = 'finance'::text)) AS finance_at
           FROM reg
        ), daily AS (
         SELECT max(agent_actions.created_at) AS daily_at
           FROM agent_actions
          WHERE (agent_actions.kind = 'exec_briefing'::text)
        )
 SELECT ( SELECT count(*) AS count
           FROM reg) AS total_reports,
    ( SELECT count(*) AS count
           FROM reg
          WHERE (reg.created_at > (now() - '30 days'::interval))) AS reports_30d,
    ( SELECT count(DISTINCT reg.report_type) AS count
           FROM reg) AS report_types,
    d.daily_at,
    lt.weekly_at,
    lt.monthly_at,
    lt.quarterly_at,
    lt.department_at,
    lt.supplier_at,
    lt.customer_at,
    lt.ai_at,
    lt.exec_at,
    lt.finance_at,
    (d.daily_at > (now() - '36:00:00'::interval)) AS daily_fresh,
    (lt.weekly_at > (now() - '8 days'::interval)) AS weekly_fresh,
    (lt.monthly_at > date_trunc('month'::text, now())) AS monthly_fresh,
    (lt.quarterly_at > (now() - '95 days'::interval)) AS quarterly_fresh,
    (lt.department_at > (now() - '2 days'::interval)) AS department_fresh,
    (lt.supplier_at > (now() - '2 days'::interval)) AS supplier_fresh,
    (lt.customer_at > (now() - '2 days'::interval)) AS customer_fresh,
    (lt.ai_at > (now() - '2 days'::interval)) AS ai_fresh,
    (((((((
        CASE
            WHEN COALESCE((d.daily_at > (now() - '36:00:00'::interval)), false) THEN 0
            ELSE 1
        END +
        CASE
            WHEN COALESCE((lt.weekly_at > (now() - '8 days'::interval)), false) THEN 0
            ELSE 1
        END) +
        CASE
            WHEN COALESCE((lt.monthly_at > date_trunc('month'::text, now())), false) THEN 0
            ELSE 1
        END) +
        CASE
            WHEN COALESCE((lt.quarterly_at > (now() - '95 days'::interval)), false) THEN 0
            ELSE 1
        END) +
        CASE
            WHEN COALESCE((lt.department_at > (now() - '2 days'::interval)), false) THEN 0
            ELSE 1
        END) +
        CASE
            WHEN COALESCE((lt.supplier_at > (now() - '2 days'::interval)), false) THEN 0
            ELSE 1
        END) +
        CASE
            WHEN COALESCE((lt.customer_at > (now() - '2 days'::interval)), false) THEN 0
            ELSE 1
        END) +
        CASE
            WHEN COALESCE((lt.ai_at > (now() - '2 days'::interval)), false) THEN 0
            ELSE 1
        END) AS stale_count
   FROM lt,
    daily d;

CREATE OR REPLACE VIEW public.report_registry AS  SELECT 'narrative'::text AS source,
    board_reports.report_type,
    board_reports.title,
    COALESCE((board_reports.week_start)::text, to_char(board_reports.created_at, 'YYYY-MM-DD'::text)) AS period,
    board_reports.created_at,
    board_reports.id
   FROM board_reports
UNION ALL
 SELECT 'exec'::text AS source,
    'exec_summary'::text AS report_type,
    ((exec_reports.officer || ' — '::text) || exec_reports.period) AS title,
    exec_reports.period,
    exec_reports.created_at,
    exec_reports.id
   FROM exec_reports
UNION ALL
 SELECT 'finance'::text AS source,
    COALESCE(finance_reports.kind, 'financial'::text) AS report_type,
    ((('Financial — '::text || COALESCE(finance_reports.kind, ''::text)) || ' '::text) || COALESCE((finance_reports.period_start)::text, ''::text)) AS title,
    COALESCE((finance_reports.period_start)::text, to_char(finance_reports.created_at, 'YYYY-MM-DD'::text)) AS period,
    finance_reports.created_at,
    finance_reports.id
   FROM finance_reports;

CREATE OR REPLACE VIEW public.security_kpis AS  SELECT ( SELECT count(*) AS count
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = 'public'::name) AND (c.relkind = 'r'::"char"))) AS tables,
    ( SELECT count(*) AS count
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = 'public'::name) AND (c.relkind = 'r'::"char") AND c.relrowsecurity)) AS rls_enabled,
    round(((100.0 * (( SELECT count(*) AS count
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = 'public'::name) AND (c.relkind = 'r'::"char") AND c.relrowsecurity)))::numeric) / (NULLIF(( SELECT count(*) AS count
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = 'public'::name) AND (c.relkind = 'r'::"char"))), 0))::numeric), 1) AS rls_coverage_pct,
    ( SELECT count(*) AS count
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = 'public'::name) AND (c.relkind = 'r'::"char") AND c.relrowsecurity AND (NOT (EXISTS ( SELECT 1
                   FROM pg_policy pol
                  WHERE (pol.polrelid = c.oid)))))) AS rls_deny_default,
    ( SELECT count(*) AS count
           FROM (pg_proc p
             JOIN pg_namespace n ON ((n.oid = p.pronamespace)))
          WHERE ((n.nspname = 'public'::name) AND p.prosecdef AND ((p.proconfig IS NULL) OR (NOT (EXISTS ( SELECT 1
                   FROM unnest(p.proconfig) cc(cc)
                  WHERE (cc.cc ~~ 'search_path=%'::text))))))) AS secdef_mutable_searchpath,
    ( SELECT count(*) AS count
           FROM security_events
          WHERE ((security_events.severity = ANY (ARRAY['high'::text, 'critical'::text])) AND (security_events.created_at >= (now() - '7 days'::interval)))) AS high_sev_events_7d,
    ( SELECT count(*) AS count
           FROM security_events
          WHERE (security_events.created_at >= (now() - '7 days'::interval))) AS events_7d,
    ( SELECT count(*) AS count
           FROM fraud_flags
          WHERE (COALESCE(fraud_flags.status, ''::text) <> ALL (ARRAY['resolved'::text, 'dismissed'::text]))) AS open_fraud_flags,
    ( SELECT count(*) AS count
           FROM agent_actions
          WHERE ((agent_actions.kind = 'security_incident'::text) AND (agent_actions.status = ANY (ARRAY['pending'::text, 'needs_review'::text])))) AS open_incidents,
    ( SELECT count(*) AS count
           FROM error_events
          WHERE (error_events.created_at >= (now() - '24:00:00'::interval))) AS errors_24h,
    ( SELECT count(*) AS count
           FROM auth.users
          WHERE (users.banned_until IS NOT NULL)) AS banned_users,
    ( SELECT count(*) AS count
           FROM auth.users
          WHERE (users.last_sign_in_at >= (now() - '7 days'::interval))) AS active_users_7d,
    COALESCE(( SELECT count(*) AS count
           FROM auth.audit_log_entries
          WHERE ((audit_log_entries.created_at >= (now() - '7 days'::interval)) AND ((audit_log_entries.payload ->> 'action'::text) ~~* '%fail%'::text))), (0)::bigint) AS failed_logins_7d,
    ( SELECT count(*) AS count
           FROM app_secrets) AS secrets_count;

CREATE OR REPLACE VIEW public.strategy_kpis AS  WITH sup AS (
         SELECT quotes.supplier_id,
            count(*) AS c
           FROM quotes
          WHERE ((quotes.created_at > (now() - '90 days'::interval)) AND (quotes.supplier_id IS NOT NULL))
          GROUP BY quotes.supplier_id
        ), agg AS (
         SELECT count(*) AS active,
            COALESCE(round(((100.0 * (max(sup.c))::numeric) / NULLIF(sum(sup.c), (0)::numeric)), 1), (0)::numeric) AS top_share
           FROM sup
        ), fin AS (
         SELECT finance_kpis.cash,
            finance_kpis.monthly_burn,
            finance_kpis.runway_months,
            finance_kpis.revenue_30d,
            finance_kpis.margin_pct
           FROM finance_kpis
        ), rk AS (
         SELECT count(*) FILTER (WHERE (strategy_risks.status = 'open'::text)) AS open_risks,
            max(strategy_risks.score) AS top_score,
            (array_agg(strategy_risks.title ORDER BY strategy_risks.score DESC))[1] AS top_title
           FROM strategy_risks
          WHERE (strategy_risks.status = 'open'::text)
        )
 SELECT agg.active AS active_suppliers_90d,
    agg.top_share AS top_supplier_share_pct,
    jsonb_array_length(COALESCE((fn_strategy_metrics() -> 'under_supplied'::text), '[]'::jsonb)) AS under_supplied_categories,
    fin.cash,
    fin.monthly_burn,
        CASE
            WHEN ((fin.cash > (0)::numeric) AND (fin.monthly_burn > (0)::numeric)) THEN round((fin.cash / fin.monthly_burn), 1)
            ELSE fin.runway_months
        END AS runway_months,
    fin.revenue_30d,
    fin.margin_pct,
    COALESCE(rk.open_risks, (0)::bigint) AS open_risks,
    COALESCE(rk.top_score, 0) AS top_risk_score,
    rk.top_title AS top_risk,
    ( SELECT count(*) AS count
           FROM market_intel
          WHERE ((market_intel.kind = 'competitor'::text) AND (market_intel.status <> 'dismissed'::text))) AS competitor_intel,
    ( SELECT count(*) AS count
           FROM market_intel
          WHERE ((market_intel.kind = 'trend'::text) AND (market_intel.status <> 'dismissed'::text))) AS market_trends,
    ( SELECT count(*) AS count
           FROM market_intel
          WHERE (market_intel.status = 'open'::text)) AS open_intel,
    ( SELECT max(simulations.created_at) AS max
           FROM simulations) AS last_simulation_at
   FROM agg,
    fin,
    rk;

CREATE OR REPLACE VIEW public.supplier_health AS  WITH s AS (
         SELECT l.id AS supplier_id,
            l.company_name,
            l.banned,
            l.matching_blocked,
            COALESCE(l.chat_strikes, 0) AS strikes,
            l.approval_status,
            l.claimed,
            l.license_expiry,
            l.license_doc_path,
            l.insurance_expiry,
            l.insurance_doc_path,
            l.egr_doc_path,
            l.trn,
            l.iso_expiry,
            l.manufacturer_auth_expiry,
            l.registration_expires_at,
            l.portal_updated_at,
            COALESCE(l.rv_response_rate, (0)::numeric) AS rv_rate,
            ((l.rv_responded IS NOT NULL) OR (l.rv_reveals IS NOT NULL)) AS has_rv,
            p.perf_score,
            p.rating,
            p.quoted,
            p.quote_rate,
            ( SELECT max(q.created_at) AS max
                   FROM quotes q
                  WHERE (q.supplier_id = l.id)) AS last_quote_at,
            ( SELECT round(avg(((((COALESCE((r.r_quality)::integer, r.rating) + COALESCE((r.r_documentation)::integer, r.rating)) + COALESCE((r.r_compliance)::integer, r.rating)))::numeric / 3.0)), 2) AS round
                   FROM reviews r
                  WHERE (r.supplier_id = l.id)) AS review_quality
           FROM (leads l
             LEFT JOIN supplier_perf p ON ((p.supplier_id = l.id)))
          WHERE ((l.claimed = true) AND (COALESCE(l.approval_status, ''::text) = 'approved'::text))
        ), scored AS (
         SELECT s.supplier_id,
            s.company_name,
            s.banned,
            s.matching_blocked,
            s.strikes,
            s.approval_status,
            s.claimed,
            s.license_expiry,
            s.license_doc_path,
            s.insurance_expiry,
            s.insurance_doc_path,
            s.egr_doc_path,
            s.trn,
            s.iso_expiry,
            s.manufacturer_auth_expiry,
            s.registration_expires_at,
            s.portal_updated_at,
            s.rv_rate,
            s.has_rv,
            s.perf_score,
            s.rating,
            s.quoted,
            s.quote_rate,
            s.last_quote_at,
            s.review_quality,
            round(GREATEST((COALESCE(s.perf_score, (0)::numeric) * (100)::numeric), ((COALESCE(s.review_quality, (0)::numeric) / 5.0) * (100)::numeric), ((COALESCE(s.rating, (0)::numeric) / 5.0) * (100)::numeric)), 1) AS quality,
            round((GREATEST(0, ((((((
                CASE
                    WHEN ((s.license_doc_path IS NOT NULL) AND ((s.license_expiry IS NULL) OR (s.license_expiry >= CURRENT_DATE))) THEN 25
                    ELSE 0
                END +
                CASE
                    WHEN ((s.insurance_doc_path IS NOT NULL) AND ((s.insurance_expiry IS NULL) OR (s.insurance_expiry >= CURRENT_DATE))) THEN 25
                    ELSE 0
                END) +
                CASE
                    WHEN (s.egr_doc_path IS NOT NULL) THEN 25
                    ELSE 0
                END) +
                CASE
                    WHEN (s.trn IS NOT NULL) THEN 25
                    ELSE 0
                END) - (LEAST(s.strikes, 3) * 8)) -
                CASE
                    WHEN ((s.iso_expiry IS NOT NULL) AND (s.iso_expiry < CURRENT_DATE)) THEN 10
                    ELSE 0
                END) -
                CASE
                    WHEN ((s.manufacturer_auth_expiry IS NOT NULL) AND (s.manufacturer_auth_expiry < CURRENT_DATE)) THEN 10
                    ELSE 0
                END)))::numeric, 1) AS compliance,
            round((
                CASE
                    WHEN s.has_rv THEN s.rv_rate
                    ELSE COALESCE(s.quote_rate, (0)::numeric)
                END * (100)::numeric), 1) AS response,
            round(((
                CASE
                    WHEN (GREATEST(COALESCE(s.last_quote_at, s.portal_updated_at), s.portal_updated_at) >= (now() - '30 days'::interval)) THEN 60
                    WHEN (GREATEST(COALESCE(s.last_quote_at, s.portal_updated_at), s.portal_updated_at) >= (now() - '60 days'::interval)) THEN 40
                    WHEN (GREATEST(COALESCE(s.last_quote_at, s.portal_updated_at), s.portal_updated_at) >= (now() - '120 days'::interval)) THEN 20
                    ELSE 5
                END +
                CASE
                    WHEN ((s.registration_expires_at IS NULL) OR (s.registration_expires_at >= now())) THEN 40
                    ELSE 0
                END))::numeric, 1) AS retention
           FROM s
        )
 SELECT supplier_id,
    company_name,
    quality,
    compliance,
    response,
    retention,
    round(((((quality * 0.30) + (compliance * 0.30)) + (response * 0.20)) + (retention * 0.20)), 1) AS health,
        CASE
            WHEN (banned OR matching_blocked OR (strikes >= 3) OR (compliance < (40)::numeric) OR (round(((((quality * 0.30) + (compliance * 0.30)) + (response * 0.20)) + (retention * 0.20)), 1) < (40)::numeric)) THEN 'high'::text
            WHEN ((compliance < (75)::numeric) OR (strikes > 0) OR (retention < (30)::numeric) OR (round(((((quality * 0.30) + (compliance * 0.30)) + (response * 0.20)) + (retention * 0.20)), 1) < (65)::numeric)) THEN 'medium'::text
            ELSE 'low'::text
        END AS risk_tier,
    ((last_quote_at IS NULL) AND (portal_updated_at < (now() - '45 days'::interval))) AS dormant,
    strikes,
    banned,
    matching_blocked,
    last_quote_at,
    portal_updated_at
   FROM scored;

CREATE OR REPLACE VIEW public.supplier_kpis AS  SELECT count(*) AS active_suppliers,
    round(avg(quality), 1) AS avg_quality,
    round(avg(response), 1) AS avg_response_score,
    round(((100.0 * (count(*) FILTER (WHERE (compliance >= (80)::numeric)))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS pct_compliant,
    round(((100.0 * (count(*) FILTER (WHERE (NOT dormant)))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS retention_rate,
    count(*) FILTER (WHERE (risk_tier = 'high'::text)) AS risk_high,
    count(*) FILTER (WHERE (risk_tier = 'medium'::text)) AS risk_medium,
    count(*) FILTER (WHERE (risk_tier = 'low'::text)) AS risk_low,
    count(*) FILTER (WHERE dormant) AS dormant_count,
    round(avg(health), 1) AS avg_health
   FROM supplier_health;

CREATE OR REPLACE VIEW public.supplier_perf AS  WITH base AS (
         SELECT l.id AS supplier_id,
            l.company_name,
            COALESCE(l.app_rating, l.rating) AS rating,
            ( SELECT count(*) AS count
                   FROM inquiry_matches m
                  WHERE (m.supplier_id = l.id)) AS matched,
            ( SELECT count(*) AS count
                   FROM quotes q
                  WHERE (q.supplier_id = l.id)) AS quoted,
            ( SELECT count(*) AS count
                   FROM inquiries i
                  WHERE (i.hired_supplier_id = l.id)) AS won,
            ( SELECT count(*) AS count
                   FROM reviews r
                  WHERE (r.supplier_id = l.id)) AS review_count
           FROM leads l
          WHERE (l.claimed = true)
        )
 SELECT supplier_id,
    company_name,
    rating,
    matched,
    quoted,
    won,
    review_count,
    round(((quoted)::numeric / (NULLIF(matched, 0))::numeric), 3) AS quote_rate,
    round(((won)::numeric / (NULLIF(quoted, 0))::numeric), 3) AS win_rate,
    round(((((COALESCE(rating, (0)::numeric) / 5.0) * 0.50) + (COALESCE(((won)::numeric / (NULLIF(quoted, 0))::numeric), (0)::numeric) * 0.35)) + (((LEAST(quoted, (10)::bigint))::numeric / 10.0) * 0.15)), 3) AS perf_score
   FROM base b;

CREATE OR REPLACE VIEW public.supplier_reputation AS  WITH disp AS (
         SELECT transactions.supplier_id,
            count(*) FILTER (WHERE ((transactions.refund_status IS NOT NULL) AND (transactions.refund_status <> 'none'::text))) AS disputes,
            count(*) AS reveals
           FROM transactions
          GROUP BY transactions.supplier_id
        )
 SELECT l.id AS supplier_id,
    l.company_name,
    count(r.id) AS review_count,
    round(avg(r.rating), 2) AS overall,
    round(avg(r.r_communication), 2) AS communication,
    round(avg(r.r_quality), 2) AS quality,
    round(avg(r.r_punctuality), 2) AS punctuality,
    round(avg(r.r_documentation), 2) AS documentation,
    round(avg(r.r_after_sales), 2) AS after_sales,
    round(avg(r.r_compliance), 2) AS compliance,
    COALESCE(sp.quote_rate, (0)::numeric) AS responsiveness,
    COALESCE(d.disputes, (0)::bigint) AS disputes,
        CASE
            WHEN (COALESCE(d.reveals, (0)::bigint) > 0) THEN round(((100.0 * (d.disputes)::numeric) / (d.reveals)::numeric), 1)
            ELSE (0)::numeric
        END AS dispute_rate_pct,
    round(LEAST((100)::numeric, GREATEST((0)::numeric, (((COALESCE(avg(r.rating), (0)::numeric) * (16)::numeric) + (COALESCE(sp.quote_rate, (0)::numeric) * 0.2)) -
        CASE
            WHEN (COALESCE(d.reveals, (0)::bigint) > 0) THEN (((100.0 * (d.disputes)::numeric) / (d.reveals)::numeric) * 0.3)
            ELSE (0)::numeric
        END))), 1) AS reputation_index
   FROM (((leads l
     LEFT JOIN reviews r ON ((r.supplier_id = l.id)))
     LEFT JOIN supplier_perf sp ON ((sp.supplier_id = l.id)))
     LEFT JOIN disp d ON ((d.supplier_id = l.id)))
  GROUP BY l.id, l.company_name, sp.quote_rate, d.disputes, d.reveals;

CREATE OR REPLACE VIEW public.supplier_twin AS  SELECT l.id AS supplier_id,
    l.company_name,
    l.emirate AS home_emirate,
    l.categories AS specialties,
    sp.matched,
    sp.quoted,
    sp.won,
    sp.quote_rate,
    sp.win_rate,
    sp.perf_score,
    rep.reputation_index,
    rep.overall AS avg_rating,
    rep.review_count,
    rep.disputes,
    rep.dispute_rate_pct,
    q.quotes_count,
    q.avg_quote_value,
    q.min_quote_value,
    q.max_quote_value,
    q.avg_response_hours,
    q.busiest_month,
    wq.typical_project_size,
    pr.preferred_regions
   FROM (((((leads l
     LEFT JOIN supplier_perf sp ON ((sp.supplier_id = l.id)))
     LEFT JOIN supplier_reputation rep ON ((rep.supplier_id = l.id)))
     LEFT JOIN LATERAL ( SELECT count(*) AS quotes_count,
            round(avg(qq.quote_amount), 0) AS avg_quote_value,
            min(qq.quote_amount) AS min_quote_value,
            max(qq.quote_amount) AS max_quote_value,
            round(avg((EXTRACT(epoch FROM (qq.created_at - i.created_at)) / 3600.0)), 1) AS avg_response_hours,
            mode() WITHIN GROUP (ORDER BY ((EXTRACT(month FROM qq.created_at))::integer)) AS busiest_month
           FROM (quotes qq
             JOIN inquiries i ON ((i.id = qq.inquiry_id)))
          WHERE (qq.supplier_id = l.id)) q ON (true))
     LEFT JOIN LATERAL ( SELECT round(avg(qq.quote_amount), 0) AS typical_project_size
           FROM (quotes qq
             JOIN inquiries i ON ((i.id = qq.inquiry_id)))
          WHERE ((qq.supplier_id = l.id) AND (i.hired_supplier_id = l.id))) wq ON (true))
     LEFT JOIN LATERAL ( SELECT array_agg(DISTINCT i.emirate) FILTER (WHERE (i.emirate IS NOT NULL)) AS preferred_regions
           FROM (quotes qq
             JOIN inquiries i ON ((i.id = qq.inquiry_id)))
          WHERE (qq.supplier_id = l.id)) pr ON (true));

CREATE OR REPLACE VIEW public.v_action_executor_authority AS  SELECT action_class,
    kind,
    target,
    active,
    advisory_safe,
        CASE kind
            WHEN 'edge'::text THEN ( SELECT (e.target = ANY (c.scope))
               FROM internal_credential c
              WHERE ((c.context = 'fn.cos_execute'::text) AND c.active AND (c.retired_at IS NULL)))
            WHEN 'rpc'::text THEN (EXISTS ( SELECT 1
               FROM org_action_executor_rpc_allowed a
              WHERE (a.target = e.target)))
            ELSE false
        END AS authorised_now
   FROM org_action_executor e;

CREATE OR REPLACE VIEW public.v_ai_agent_health AS  WITH runs AS (
         SELECT agent_runs.agent,
            count(*) FILTER (WHERE (agent_runs.started_at > (now() - '30 days'::interval))) AS runs_30d,
            count(*) FILTER (WHERE ((agent_runs.started_at > (now() - '30 days'::interval)) AND (agent_runs.status = 'error'::text))) AS errors_30d,
            max(agent_runs.started_at) AS last_run
           FROM agent_runs
          GROUP BY agent_runs.agent
        ), acts AS (
         SELECT agent_actions.agent,
            count(*) FILTER (WHERE (agent_actions.created_at > (now() - '30 days'::interval))) AS actions_30d,
            count(*) FILTER (WHERE ((agent_actions.created_at > (now() - '30 days'::interval)) AND (agent_actions.decided_at IS NOT NULL))) AS decided_30d,
            count(*) FILTER (WHERE ((agent_actions.created_at > (now() - '30 days'::interval)) AND (lower(COALESCE(agent_actions.status, ''::text)) = ANY (ARRAY['rejected'::text, 'dismissed'::text, 'declined'::text, 'overridden'::text])))) AS rejected_30d,
            round(avg(agent_actions.confidence) FILTER (WHERE (agent_actions.created_at > (now() - '30 days'::interval))), 1) AS avg_confidence
           FROM agent_actions
          GROUP BY agent_actions.agent
        )
 SELECT COALESCE(r.agent, a.agent) AS agent,
    COALESCE(r.runs_30d, (0)::bigint) AS runs_30d,
    COALESCE(r.errors_30d, (0)::bigint) AS errors_30d,
    r.last_run,
    COALESCE(a.decided_30d, (0)::bigint) AS decided_30d,
    COALESCE(a.rejected_30d, (0)::bigint) AS rejected_30d,
    round(
        CASE
            WHEN (a.actions_30d > 0) THEN (((a.rejected_30d)::numeric / (a.actions_30d)::numeric) * (100)::numeric)
            ELSE NULL::numeric
        END, 1) AS override_pct,
    a.avg_confidence,
    COALESCE(a.actions_30d, (0)::bigint) AS actions_30d
   FROM (runs r
     FULL JOIN acts a ON ((a.agent = r.agent)))
  ORDER BY (round(
        CASE
            WHEN (a.actions_30d > 0) THEN (((a.rejected_30d)::numeric / (a.actions_30d)::numeric) * (100)::numeric)
            ELSE NULL::numeric
        END, 1)) DESC NULLS LAST, COALESCE(r.runs_30d, (0)::bigint) DESC;

CREATE OR REPLACE VIEW public.v_ai_level_distribution AS  WITH r AS (
         SELECT
                CASE
                    WHEN (COALESCE(ai_cost_log.tier, ''::text) = 'none'::text) THEN '0 no AI'::text
                    WHEN (ai_cost_log.tier = 'small'::text) THEN '1 cheap'::text
                    WHEN (ai_cost_log.tier = 'medium'::text) THEN '2 medium'::text
                    WHEN (ai_cost_log.tier = 'large'::text) THEN '3 premium'::text
                    WHEN (ai_cost_log.tier = 'xlarge'::text) THEN '4 human-level'::text
                    ELSE '? unclassified'::text
                END AS level,
            ai_cost_log.cost_aed,
            ai_cost_log.prompt_tokens,
            ai_cost_log.cached_in_tokens
           FROM ai_cost_log
          WHERE (ai_cost_log.occurred_at >= (now() - '30 days'::interval))
        )
 SELECT level,
    count(*) AS calls,
    round(((100.0 * (count(*))::numeric) / NULLIF(sum(count(*)) OVER (), (0)::numeric)), 1) AS pct_of_calls,
    round(sum(cost_aed), 2) AS cost_aed,
    round(((100.0 * sum(cost_aed)) / NULLIF(sum(sum(cost_aed)) OVER (), (0)::numeric)), 1) AS pct_of_cost,
    sum(prompt_tokens) AS prompt_tokens,
    sum(cached_in_tokens) AS from_cache,
        CASE level
            WHEN '0 no AI'::text THEN 20
            WHEN '1 cheap'::text THEN 55
            WHEN '2 medium'::text THEN 20
            WHEN '3 premium'::text THEN 5
            ELSE 0
        END AS spec_target_pct
   FROM r
  GROUP BY level
  ORDER BY level;

CREATE OR REPLACE VIEW public.v_ai_observability AS  SELECT ( SELECT count(*) AS count
           FROM agent_runs
          WHERE (agent_runs.started_at > (now() - '24:00:00'::interval))) AS runs_24h,
    ( SELECT count(*) AS count
           FROM agent_runs
          WHERE ((agent_runs.started_at > (now() - '24:00:00'::interval)) AND (agent_runs.status = 'error'::text))) AS errors_24h,
    ( SELECT count(*) AS count
           FROM agent_actions
          WHERE (lower(COALESCE(agent_actions.status, ''::text)) = ANY (ARRAY['pending'::text, 'needs_review'::text]))) AS open_approvals,
    ( SELECT round(avg(v_ai_agent_health.override_pct), 1) AS round
           FROM v_ai_agent_health
          WHERE (v_ai_agent_health.override_pct IS NOT NULL)) AS avg_override_pct,
    ( SELECT round(avg(v_eval_latest.score), 1) AS round
           FROM v_eval_latest) AS avg_eval_score,
    ( SELECT round(avg(v_kb_confidence.confidence), 1) AS round
           FROM v_kb_confidence) AS kb_avg_confidence,
    ( SELECT count(*) AS count
           FROM v_kb_review_due) AS kb_review_due,
    ( SELECT count(*) AS count
           FROM kb_chunks
          WHERE (kb_chunks.embedding_gte IS NOT NULL)) AS kb_embedded,
    ( SELECT count(*) AS count
           FROM kb_chunks) AS kb_total,
    ( SELECT count(*) AS count
           FROM kb_usage_log
          WHERE (kb_usage_log.created_at > (now() - '7 days'::interval))) AS kb_queries_7d;

CREATE OR REPLACE VIEW public.v_ai_quality_proxy AS  SELECT agent,
    count(*) FILTER (WHERE (decided_at IS NOT NULL)) AS decided_30d,
    count(*) FILTER (WHERE (lower(COALESCE(status, ''::text)) = ANY (ARRAY['rejected'::text, 'dismissed'::text, 'declined'::text, 'overridden'::text]))) AS rejected_30d,
    round(
        CASE
            WHEN (count(*) FILTER (WHERE (decided_at IS NOT NULL)) > 0) THEN (((count(*) FILTER (WHERE (lower(COALESCE(status, ''::text)) = ANY (ARRAY['rejected'::text, 'dismissed'::text, 'declined'::text, 'overridden'::text]))))::numeric / (count(*) FILTER (WHERE (decided_at IS NOT NULL)))::numeric) * (100)::numeric)
            ELSE NULL::numeric
        END, 1) AS override_pct
   FROM agent_actions
  WHERE (created_at > (now() - '30 days'::interval))
  GROUP BY agent
  ORDER BY (round(
        CASE
            WHEN (count(*) FILTER (WHERE (decided_at IS NOT NULL)) > 0) THEN (((count(*) FILTER (WHERE (lower(COALESCE(status, ''::text)) = ANY (ARRAY['rejected'::text, 'dismissed'::text, 'declined'::text, 'overridden'::text]))))::numeric / (count(*) FILTER (WHERE (decided_at IS NOT NULL)))::numeric) * (100)::numeric)
            ELSE NULL::numeric
        END, 1)) DESC NULLS LAST;

CREATE OR REPLACE VIEW public.v_ai_spend AS  SELECT b.dept_key,
    d.name AS department,
    b.monthly_aed,
    b.period_label,
    COALESCE(sum(l.cost_aed), (0)::numeric) AS spent_aed,
        CASE
            WHEN (b.monthly_aed > (0)::numeric) THEN round((((100)::numeric * COALESCE(sum(l.cost_aed), (0)::numeric)) / b.monthly_aed))
            ELSE (0)::numeric
        END AS pct_used,
    count(l.id) AS calls,
    count(l.id) FILTER (WHERE l.cached) AS cache_hits,
    count(l.id) FILTER (WHERE l.could_be_cheaper) AS downgradable_calls,
    COALESCE(sum((l.prompt_tokens + l.output_tokens)), (0)::bigint) AS tokens
   FROM ((department_budget b
     LEFT JOIN org_departments d ON ((d.dept_key = b.dept_key)))
     LEFT JOIN ai_cost_log l ON (((l.dept_key = b.dept_key) AND (to_char(l.occurred_at, 'YYYY-MM'::text) = b.period_label))))
  GROUP BY b.dept_key, d.name, b.monthly_aed, b.period_label;

CREATE OR REPLACE VIEW public.v_approval_trace AS  SELECT r.id AS request_id,
    r.organization_id,
    r.entity_type,
    r.entity_id,
    r.status AS request_status,
    r.current_step,
    r.created_at,
    (s.ord)::integer AS step,
    COALESCE((s.step ->> 'key'::text), ('step_'::text || s.ord)) AS step_key,
    COALESCE((s.step ->> 'label'::text), (s.step ->> 'key'::text), ('Step '::text || s.ord)) AS step_label,
    (s.step ->> 'role'::text) AS step_role,
        CASE
            WHEN (d.decision IS NOT NULL) THEN d.decision
            WHEN (r.status = 'rejected'::text) THEN 'blocked'::text
            WHEN (r.status = 'approved'::text) THEN 'approved'::text
            WHEN (s.ord = r.current_step) THEN 'pending'::text
            ELSE 'waiting'::text
        END AS step_status,
    d.decided_by,
    d.decided_at,
    d.note AS decision_note
   FROM (((procurement_approval_request r
     JOIN procurement_approval_policy p ON ((p.id = r.policy_id)))
     CROSS JOIN LATERAL ( SELECT t.ord,
            t.step
           FROM jsonb_array_elements(p.steps) WITH ORDINALITY t(step, ord)) s)
     LEFT JOIN LATERAL ( SELECT (x.value ->> 'decision'::text) AS decision,
            (x.value ->> 'by'::text) AS decided_by,
            ((x.value ->> 'at'::text))::timestamp with time zone AS decided_at,
            (x.value ->> 'note'::text) AS note
           FROM jsonb_array_elements(r.decisions) x(value)
          WHERE (((x.value ->> 'step'::text))::integer = s.ord)
          ORDER BY ((x.value ->> 'at'::text))::timestamp with time zone DESC
         LIMIT 1) d ON (true));

CREATE OR REPLACE VIEW public.v_audit_coverage AS  WITH sources AS (
         SELECT 'decision_log'::text AS store,
            'Every routed agent decision'::text AS covers,
            ( SELECT count(*) AS count
                   FROM decision_log) AS rows_held,
            ( SELECT max(decision_log.created_at) AS max
                   FROM decision_log) AS last_write
        UNION ALL
         SELECT 'decision_record'::text,
            'Structured decisions with impact analysis'::text,
            ( SELECT count(*) AS count
                   FROM decision_record) AS count,
            ( SELECT max(decision_record.created_at) AS max
                   FROM decision_record) AS max
        UNION ALL
         SELECT 'company_event'::text,
            'Business events published by db triggers'::text,
            ( SELECT count(*) AS count
                   FROM company_event) AS count,
            ( SELECT max(company_event.occurred_at) AS max
                   FROM company_event) AS max
        UNION ALL
         SELECT 'agent_runs'::text,
            'Every scheduled function run and outcome'::text,
            ( SELECT count(*) AS count
                   FROM agent_runs) AS count,
            ( SELECT max(agent_runs.started_at) AS max
                   FROM agent_runs) AS max
        UNION ALL
         SELECT 'agent_action_log'::text,
            'Actions taken by employees'::text,
            ( SELECT count(*) AS count
                   FROM agent_action_log) AS count,
            NULL::timestamp with time zone
        UNION ALL
         SELECT 'os_audit_log'::text,
            'Operator and system actions'::text,
            ( SELECT count(*) AS count
                   FROM os_audit_log) AS count,
            NULL::timestamp with time zone
        UNION ALL
         SELECT 'security_audit_log'::text,
            'Security-relevant events'::text,
            ( SELECT count(*) AS count
                   FROM security_audit_log) AS count,
            NULL::timestamp with time zone
        UNION ALL
         SELECT 'ai_cost_log'::text,
            'Every model call: model, reason, tokens, cost'::text,
            ( SELECT count(*) AS count
                   FROM ai_cost_log) AS count,
            ( SELECT max(ai_cost_log.occurred_at) AS max
                   FROM ai_cost_log) AS max
        UNION ALL
         SELECT 'review_chain'::text,
            'Approval hops on anything published'::text,
            ( SELECT count(*) AS count
                   FROM review_chain) AS count,
            NULL::timestamp with time zone
        UNION ALL
         SELECT 'brand_signal'::text,
            'Fraud and brand-misuse detections'::text,
            ( SELECT count(*) AS count
                   FROM brand_signal) AS count,
            ( SELECT max(brand_signal.detected_at) AS max
                   FROM brand_signal) AS max
        UNION ALL
         SELECT 'evolution_proposal'::text,
            'Self-detected process defects'::text,
            ( SELECT count(*) AS count
                   FROM evolution_proposal) AS count,
            ( SELECT max(evolution_proposal.created_at) AS max
                   FROM evolution_proposal) AS max
        UNION ALL
         SELECT 'metric_snapshot'::text,
            'Point-in-time metric history'::text,
            ( SELECT count(*) AS count
                   FROM metric_snapshot) AS count,
            ( SELECT max(metric_snapshot.taken_at) AS max
                   FROM metric_snapshot) AS max
        )
 SELECT store,
    covers,
    rows_held,
    last_write,
        CASE
            WHEN (rows_held = 0) THEN 'EMPTY'::text
            WHEN (last_write IS NULL) THEN 'NO_TIMESTAMP'::text
            WHEN (last_write > (now() - '7 days'::interval)) THEN 'ACTIVE'::text
            ELSE 'STALE'::text
        END AS state
   FROM sources;

CREATE OR REPLACE VIEW public.v_auth_watch AS  SELECT customer_phone_otps.created_at AS at,
    'otp_high_attempts'::text AS signal,
        CASE
            WHEN (customer_phone_otps.attempts >= 5) THEN 'high'::text
            ELSE 'medium'::text
        END AS severity,
    COALESCE(customer_phone_otps.phone, ''::text) AS subject,
    jsonb_build_object('table', 'customer_phone_otps', 'attempts', customer_phone_otps.attempts, 'consumed', customer_phone_otps.consumed, 'customer_id', customer_phone_otps.customer_id) AS detail
   FROM customer_phone_otps
  WHERE ((customer_phone_otps.attempts >= 3) AND (customer_phone_otps.created_at > (now() - '30 days'::interval)))
UNION ALL
 SELECT phone_verifications.created_at AS at,
    'verify_high_attempts'::text AS signal,
        CASE
            WHEN (phone_verifications.attempts >= 5) THEN 'high'::text
            ELSE 'medium'::text
        END AS severity,
    COALESCE(phone_verifications.email, phone_verifications.phone, ''::text) AS subject,
    jsonb_build_object('table', 'phone_verifications', 'attempts', phone_verifications.attempts, 'user_kind', phone_verifications.user_kind, 'used', (phone_verifications.used_at IS NOT NULL)) AS detail
   FROM phone_verifications
  WHERE ((phone_verifications.attempts >= 3) AND (phone_verifications.created_at > (now() - '30 days'::interval)))
UNION ALL
 SELECT security_events.created_at AS at,
    security_events.kind AS signal,
    COALESCE(security_events.severity,
        CASE
            WHEN (security_events.kind = 'login_failed'::text) THEN 'medium'::text
            ELSE 'info'::text
        END) AS severity,
    COALESCE(security_events.subject, ''::text) AS subject,
    COALESCE(security_events.detail, '{}'::jsonb) AS detail
   FROM security_events
  WHERE ((security_events.kind = ANY (ARRAY['admin_login'::text, 'login_failed'::text])) AND (security_events.created_at > (now() - '30 days'::interval)));

CREATE OR REPLACE VIEW public.v_autonomy_status AS  SELECT ((fn_autonomy_status() ->> 'allowed'::text))::boolean AS autonomy_allowed,
    (fn_autonomy_status() -> 'blockers'::text) AS blockers,
    ( SELECT count(*) AS count
           FROM spec_backlog
          WHERE ((spec_backlog.priority = 0) AND (spec_backlog.status = 'open'::text))) AS p0_open,
    ( SELECT count(*) AS count
           FROM autonomy_control_audit
          WHERE (autonomy_control_audit.direction = 'widen'::text)) AS widenings_ever,
    ( SELECT max(autonomy_control_audit.at) AS max
           FROM autonomy_control_audit
          WHERE (autonomy_control_audit.direction = 'widen'::text)) AS last_widening;

CREATE OR REPLACE VIEW public.v_bi_scorecard AS  WITH latest AS (
         SELECT DISTINCT ON (s.metric_key) s.metric_key,
            s.value,
            s.error,
            s.taken_at
           FROM metric_snapshot s
          ORDER BY s.metric_key, s.taken_at DESC
        )
 SELECT d.metric_key,
    d.label,
    d.domain,
    d.owner_dept,
    l.value,
    d.target,
    d.direction,
        CASE
            WHEN (l.error IS NOT NULL) THEN 'ERROR'::text
            WHEN ((l.value IS NULL) OR (d.target IS NULL)) THEN 'UNMEASURED'::text
            WHEN ((d.direction = 'up'::text) AND (l.value >= d.target)) THEN 'ON_TARGET'::text
            WHEN ((d.direction = 'down'::text) AND (l.value <= d.target)) THEN 'ON_TARGET'::text
            WHEN ((d.direction = 'up'::text) AND (l.value >= (d.target * 0.7))) THEN 'BEHIND'::text
            WHEN ((d.direction = 'down'::text) AND (l.value <= (d.target * 1.3))) THEN 'BEHIND'::text
            ELSE 'OFF_TARGET'::text
        END AS state,
    l.error,
    l.taken_at,
    d.definition
   FROM (metric_definition d
     LEFT JOIN latest l ON ((l.metric_key = d.metric_key)))
  WHERE d.active;

CREATE OR REPLACE VIEW public.v_business_health AS  SELECT round(avg(score) FILTER (WHERE (status <> 'no data'::text))) AS overall_score_measurable,
    round(avg(score)) AS overall_score_all_departments,
    count(*) FILTER (WHERE (status = 'healthy'::text)) AS healthy,
    count(*) FILTER (WHERE (status = 'watch'::text)) AS watch,
    count(*) FILTER (WHERE (status = 'at risk'::text)) AS at_risk,
    count(*) FILTER (WHERE (status = 'no data'::text)) AS unmeasurable,
    ( SELECT count(*) AS count
           FROM risk_register
          WHERE (risk_register.status = 'open'::text)) AS open_risks,
    ( SELECT count(*) AS count
           FROM spec_backlog
          WHERE ((spec_backlog.status <> 'done'::text) AND (spec_backlog.priority = 1))) AS open_p1
   FROM v_department_health;

CREATE OR REPLACE VIEW public.v_capability_gaps AS  SELECT department,
    agent_key,
    title,
    seniority,
    ( SELECT count(*) AS count
           FROM skills_matrix s
          WHERE (s.agent_key = a.agent_key)) AS skills,
    ( SELECT count(*) AS count
           FROM skills_matrix s
          WHERE ((s.agent_key = a.agent_key) AND (s.rating >= 4))) AS strong_skills,
    ( SELECT count(*) AS count
           FROM skills_matrix s
          WHERE ((s.agent_key = a.agent_key) AND (s.rating <= 2))) AS weak_skills,
    ( SELECT count(*) AS count
           FROM employee_kpi k
          WHERE ((k.agent_key = a.agent_key) AND k.active)) AS kpis,
    ( SELECT count(*) AS count
           FROM employee_authority ea
          WHERE (ea.agent_key = a.agent_key)) AS authorities,
    ( SELECT count(*) AS count
           FROM employee_workflow w
          WHERE (w.agent_key = a.agent_key)) AS workflows,
    ( SELECT count(*) AS count
           FROM agent_knowledge kn
          WHERE (kn.agent_key = a.agent_key)) AS own_knowledge_rows,
        CASE
            WHEN (( SELECT count(*) AS count
               FROM agent_knowledge kn
              WHERE (kn.agent_key = a.agent_key)) = 0) THEN 'NO OWN KNOWLEDGE - relies entirely on shared domains'::text
            ELSE 'has own knowledge'::text
        END AS knowledge_status
   FROM org_agents a
  WHERE active;

CREATE OR REPLACE VIEW public.v_capability_matrix AS  SELECT agent_key,
    title,
    seniority,
    department,
    manager_key,
    ( SELECT count(*) AS count
           FROM org_agents r
          WHERE (r.manager_key = a.agent_key)) AS direct_reports,
    ( SELECT count(*) AS count
           FROM employee_kpi k
          WHERE ((k.agent_key = a.agent_key) AND k.active)) AS owned_kpis,
    ( SELECT count(*) AS count
           FROM employee_authority ea
          WHERE (ea.agent_key = a.agent_key)) AS personal_authorities,
    ( SELECT count(*) AS count
           FROM org_authority au
          WHERE (au.dept_key = a.department)) AS dept_authorities,
    ( SELECT count(*) AS count
           FROM org_action_executor e
          WHERE ((e.department = a.department) AND e.active)) AS executable_actions,
    ( SELECT count(*) AS count
           FROM agent_knowledge k
          WHERE (k.agent_key = a.agent_key)) AS knowledge_topics,
    ( SELECT count(*) AS count
           FROM agent_memory m
          WHERE (m.agent_key = a.agent_key)) AS memories,
        CASE
            WHEN (( SELECT count(*) AS count
               FROM employee_kpi k
              WHERE ((k.agent_key = a.agent_key) AND k.active)) = 0) THEN 'NO KPI'::text
            WHEN (( SELECT count(*) AS count
               FROM org_action_executor e
              WHERE ((e.department = a.department) AND e.active)) = 0) THEN 'CANNOT ACT'::text
            ELSE 'ok'::text
        END AS employee_status
   FROM org_agents a;

CREATE OR REPLACE VIEW public.v_category_coverage AS  SELECT c.num,
    c.slug AS catalog_slug,
    c.name,
    c.regulated,
    m.agent_slug,
    (m.agent_slug = c.slug) AS agent_is_canonical,
    COALESCE(( SELECT count(*) AS count
           FROM agent_knowledge k
          WHERE ((k.agent_key = ('cat:'::text || c.slug)) AND (k.topic IN ( SELECT knowledge_module_standard.module
                   FROM knowledge_module_standard
                  WHERE knowledge_module_standard.required)))), (0)::bigint) AS standard_modules,
    COALESCE(( SELECT count(*) AS count
           FROM agent_knowledge k
          WHERE (k.agent_key = ('cat:'::text || COALESCE(m.agent_slug, '~none~'::text)))), (0)::bigint) AS legacy_rows_elsewhere,
    ( SELECT count(DISTINCT l.id) AS count
           FROM (lead_trade_map t
             JOIN leads l ON ((l.invite_trades && ARRAY[t.trade_key])))
          WHERE (t.catalog_slug = c.slug)) AS supplier_supply,
        CASE
            WHEN (COALESCE(( SELECT count(*) AS count
               FROM agent_knowledge k
              WHERE ((k.agent_key = ('cat:'::text || c.slug)) AND (k.topic IN ( SELECT knowledge_module_standard.module
                       FROM knowledge_module_standard
                      WHERE knowledge_module_standard.required)))), (0)::bigint) = 14) THEN 'COMPLIANT'::text
            WHEN (m.status = 'mapped'::text) THEN 'MAPPED_NOT_TO_STANDARD'::text
            ELSE 'NO_AGENT'::text
        END AS coverage
   FROM (catalog_supplier_categories c
     LEFT JOIN category_agent_map m ON ((m.catalog_slug = c.slug)));

CREATE OR REPLACE VIEW public.v_commercial_effect_due AS  SELECT e.task_id,
    t.title,
    t.dept_key,
    e.owner_agent_key,
    e.terminal_goal_key,
    e.expected_outcome,
    e.expected_outcome_value,
    e.expected_outcome_unit,
    e.expected_cost_aed,
    e.risk,
    e.review_date,
    e.review_trigger,
    (CURRENT_DATE - e.review_date) AS days_overdue
   FROM (task_commercial_effect e
     JOIN org_tasks t ON ((t.id = e.task_id)))
  WHERE ((NOT e.no_commercial_effect) AND (e.measured_at IS NULL) AND (e.review_date <= CURRENT_DATE));

CREATE OR REPLACE VIEW public.v_constitution AS  SELECT article_no,
    section,
    title,
    body,
    version,
    effective_from
   FROM company_constitution
  ORDER BY article_no;

CREATE OR REPLACE VIEW public.v_control_mode_identity AS  SELECT admin_email,
    phone_secret_key,
    active,
    ( SELECT "right"(btrim(s.value), 4) AS "right"
           FROM app_secrets s
          WHERE (s.key = i.phone_secret_key)) AS phone_tail,
    note,
    created_at
   FROM control_mode_identity i;

CREATE OR REPLACE VIEW public.v_control_mode_status AS  SELECT actor_email,
    reason,
    opened_at,
    expires_at,
    actions_used,
    ((closed_at IS NULL) AND (expires_at > now())) AS active
   FROM control_mode_session s
  ORDER BY opened_at DESC;

CREATE OR REPLACE VIEW public.v_cost_optimisation AS  SELECT task_class,
    model_used,
    tier,
    count(*) AS calls,
    round(sum(cost_aed), 2) AS cost_aed,
    count(*) FILTER (WHERE could_be_cheaper) AS could_downgrade,
    count(*) FILTER (WHERE cached) AS served_from_cache,
    round(avg(prompt_tokens)) AS avg_prompt_tokens,
    string_agg(DISTINCT cheaper_reason, ' | '::text) AS reasons
   FROM ai_cost_log
  GROUP BY task_class, model_used, tier
  ORDER BY (round(sum(cost_aed), 2)) DESC NULLS LAST;

CREATE OR REPLACE VIEW public.v_critical_capability_tests AS  WITH latest AS (
         SELECT DISTINCT ON (agent_runs.agent) agent_runs.agent,
            agent_runs.status,
            agent_runs.started_at
           FROM agent_runs
          ORDER BY agent_runs.agent, agent_runs.started_at DESC
        )
 SELECT capability_key,
    capability,
    owner_dept,
    test_kind,
    test_ref,
    why_critical,
        CASE
            WHEN ((test_kind = 'none'::text) OR (test_ref IS NULL)) THEN 'UNTESTED'::text
            WHEN (test_kind = 'rpc_selftest'::text) THEN 'SELFTEST_ON_BUILD'::text
            WHEN (test_kind = 'scenario'::text) THEN COALESCE(( SELECT
                    CASE
                        WHEN (s.last_result = 'pass'::text) THEN 'PASSING'::text
                        WHEN (s.last_result = 'not_run'::text) THEN 'NEVER_RUN'::text
                        ELSE 'FAILING'::text
                    END AS "case"
               FROM scenario_library s
              WHERE (s.scenario_key = c.test_ref)), 'NEVER_RUN'::text)
            WHEN (test_kind = 'suite'::text) THEN COALESCE(( SELECT
                    CASE
                        WHEN (l.status = 'ok'::text) THEN 'PASSING'::text
                        ELSE 'FAILING'::text
                    END AS "case"
               FROM latest l
              WHERE (l.agent = c.test_ref)), 'NEVER_RUN'::text)
            ELSE 'UNKNOWN'::text
        END AS state,
        CASE
            WHEN ((test_kind = 'suite'::text) AND (COALESCE(( SELECT t.pass_pct
               FROM v_test_matrix t
              WHERE (t.suite = c.test_ref)), (100)::numeric) < (100)::numeric)) THEN true
            ELSE false
        END AS flaky_in_window,
    ( SELECT t.pass_pct
           FROM v_test_matrix t
          WHERE (t.suite = c.test_ref)) AS pass_pct_14d,
    ( SELECT l.started_at
           FROM latest l
          WHERE (l.agent = c.test_ref)) AS last_run
   FROM critical_capability c;

CREATE OR REPLACE VIEW public.v_cron_failing AS  SELECT j.jobname,
    j.schedule,
    j.active,
    count(*) FILTER (WHERE (d.status <> 'succeeded'::text)) AS failed_runs,
    count(*) AS total_runs,
    min(d.start_time) FILTER (WHERE (d.status <> 'succeeded'::text)) AS first_failure,
    max(d.start_time) FILTER (WHERE (d.status <> 'succeeded'::text)) AS last_failure,
    max(d.start_time) FILTER (WHERE (d.status = 'succeeded'::text)) AS last_success,
    "left"((array_agg(d.return_message ORDER BY d.start_time DESC) FILTER (WHERE (d.status <> 'succeeded'::text)))[1], 300) AS last_error
   FROM (cron.job j
     JOIN cron.job_run_details d ON ((d.jobid = j.jobid)))
  WHERE (d.start_time > (now() - '7 days'::interval))
  GROUP BY j.jobname, j.schedule, j.active
 HAVING (count(*) FILTER (WHERE (d.status <> 'succeeded'::text)) > 0);

CREATE OR REPLACE VIEW public.v_customer_ltv AS  SELECT id AS customer_id,
    full_name,
    email,
    ( SELECT count(*) AS count
           FROM inquiries i
          WHERE (i.customer_id = c.id)) AS inquiries,
    ( SELECT count(*) AS count
           FROM inquiries i
          WHERE ((i.customer_id = c.id) AND ((i.completed_at IS NOT NULL) OR (i.outcome = 'won'::text)))) AS completed,
    ( SELECT count(*) AS count
           FROM transactions t
          WHERE ((t.customer_id = c.id) AND (t.fee_status = 'paid'::text))) AS paid_reveals,
    (COALESCE(( SELECT sum(t.reveal_fee) AS sum
           FROM transactions t
          WHERE ((t.customer_id = c.id) AND (t.fee_status = 'paid'::text))), (0)::numeric))::numeric(12,2) AS revenue_to_date_aed,
    GREATEST(( SELECT max(i.created_at) AS max
           FROM inquiries i
          WHERE (i.customer_id = c.id)), ( SELECT max(t.revealed_at) AS max
           FROM transactions t
          WHERE (t.customer_id = c.id))) AS last_activity,
        CASE
            WHEN (COALESCE(( SELECT sum(t.reveal_fee) AS sum
               FROM transactions t
              WHERE ((t.customer_id = c.id) AND (t.fee_status = 'paid'::text))), (0)::numeric) >= (2000)::numeric) THEN 'high'::text
            WHEN (COALESCE(( SELECT sum(t.reveal_fee) AS sum
               FROM transactions t
              WHERE ((t.customer_id = c.id) AND (t.fee_status = 'paid'::text))), (0)::numeric) >= (500)::numeric) THEN 'medium'::text
            WHEN (COALESCE(( SELECT sum(t.reveal_fee) AS sum
               FROM transactions t
              WHERE ((t.customer_id = c.id) AND (t.fee_status = 'paid'::text))), (0)::numeric) > (0)::numeric) THEN 'low'::text
            ELSE 'none'::text
        END AS value_tier
   FROM customers c
  ORDER BY ((COALESCE(( SELECT sum(t.reveal_fee) AS sum
           FROM transactions t
          WHERE ((t.customer_id = c.id) AND (t.fee_status = 'paid'::text))), (0)::numeric))::numeric(12,2)) DESC;

CREATE OR REPLACE VIEW public.v_customer_master AS  SELECT id AS customer_id,
    full_name AS name,
    phone AS mobile,
    email,
        CASE
            WHEN (COALESCE(btrim(signed_terms_path), ''::text) <> ''::text) THEN ('QD-TC-'::text || upper("left"(replace((id)::text, '-'::text, ''::text), 8)))
            ELSE NULL::text
        END AS tc_document_no,
    signed_terms_path AS tc_document_path,
    signed_terms_url AS tc_document_url,
    tos_version AS tc_version,
    COALESCE(signed_terms_at, tos_accepted_at) AS tc_accepted_at,
    tos_ip AS tc_accepted_ip,
    (((('/QuotesDone Backup/Customers/'::text || fn_dbx_safe(COALESCE(full_name, 'Customer'::text))) || ' ('::text) || "left"((id)::text, 8)) || ')'::text) AS dropbox_folder,
    phone_verified,
    email_verified,
    created_at AS registered_at
   FROM customers c
  ORDER BY created_at DESC NULLS LAST;

CREATE OR REPLACE VIEW public.v_dead_letter_open AS  SELECT source,
    kind,
    reason,
    count(*) AS items,
    min(first_failed_at) AS oldest,
    max(created_at) AS newest
   FROM dead_letter
  WHERE (resolved_at IS NULL)
  GROUP BY source, kind, reason
  ORDER BY (count(*)) DESC;

CREATE OR REPLACE VIEW public.v_decision_intelligence AS  SELECT id,
    decided_by,
    dept_key,
    "left"(problem, 90) AS problem,
    confidence,
    status,
    financial_aed,
    reversible,
    ((impact_business IS NOT NULL) AND (length(impact_business) > 20)) AS has_business,
    ((impact_financial IS NOT NULL) AND (length(impact_financial) > 20)) AS has_financial,
    ((impact_legal IS NOT NULL) AND (length(impact_legal) > 10)) AS has_legal,
    ((impact_customer IS NOT NULL) AND (length(impact_customer) > 20)) AS has_customer,
    (jsonb_array_length(COALESCE(evidence, '[]'::jsonb)) > 0) AS has_evidence,
        CASE
            WHEN ((impact_business IS NOT NULL) AND (length(impact_business) > 20) AND ((impact_financial IS NOT NULL) AND (length(impact_financial) > 20)) AND ((impact_legal IS NOT NULL) AND (length(impact_legal) > 10)) AND ((impact_customer IS NOT NULL) AND (length(impact_customer) > 20)) AND (jsonb_array_length(COALESCE(evidence, '[]'::jsonb)) > 0)) THEN 'COMPLETE'::text
            ELSE 'INCOMPLETE'::text
        END AS intelligence_verdict,
    created_at
   FROM decision_record d;

CREATE OR REPLACE VIEW public.v_decision_matrix AS  SELECT dept_key,
    action_class,
    max_tier,
    threshold_aed,
    note,
    (EXISTS ( SELECT 1
           FROM org_action_executor e
          WHERE ((e.department = au.dept_key) AND (e.action_class = au.action_class) AND e.active))) AS executor_wired,
    ( SELECT count(*) AS count
           FROM decision_log dl
          WHERE (dl.actor = au.dept_key)) AS decisions_logged,
        CASE
            WHEN (max_tier = 'gated'::text) THEN 'founder approval required'::text
            WHEN (max_tier = 'advisory'::text) THEN 'recommend only'::text
            ELSE 'autonomous'::text
        END AS effect
   FROM org_authority au;

CREATE OR REPLACE VIEW public.v_decision_trace_incomplete AS  SELECT id,
    created_at,
    agent_key,
    role_id,
    department_id,
    decision_type,
    (role_id IS NULL) AS missing_role,
    ((jsonb_typeof(evidence_refs) IS DISTINCT FROM 'array'::text) OR (COALESCE(jsonb_array_length(evidence_refs), 0) = 0)) AS missing_evidence,
    (escalation_decision IS NULL) AS missing_authority,
    (final_status IS NULL) AS missing_output_status
   FROM decision_trace
  WHERE ((role_id IS NULL) OR (jsonb_typeof(evidence_refs) IS DISTINCT FROM 'array'::text) OR (COALESCE(jsonb_array_length(evidence_refs), 0) = 0) OR (escalation_decision IS NULL) OR (final_status IS NULL));

CREATE OR REPLACE VIEW public.v_deliverability AS  WITH sent AS (
         SELECT count(*) FILTER (WHERE (leads.invited_at IS NOT NULL)) AS invites_ever,
            count(*) FILTER (WHERE (leads.invited_at > (now() - '1 day'::interval))) AS invites_24h,
            count(*) FILTER (WHERE (leads.invited_at > (now() - '3 days'::interval))) AS invites_3d,
            count(*) FILTER (WHERE (leads.invited_at > (now() - '7 days'::interval))) AS invites_7d,
            count(*) FILTER (WHERE (leads.invite_status = 'bounced'::text)) AS bounced_ever,
            count(*) FILTER (WHERE ((leads.invite_status = 'bounced'::text) AND (leads.invited_at > (now() - '3 days'::interval)))) AS bounced_3d,
            count(*) FILTER (WHERE ((leads.invite_status = 'bounced'::text) AND (leads.invited_at > (now() - '7 days'::interval)))) AS bounced_7d
           FROM leads
        ), list AS (
         SELECT count(*) FILTER (WHERE (COALESCE(TRIM(BOTH FROM leads.email), ''::text) <> ''::text)) AS with_email,
            count(*) FILTER (WHERE (leads.email_verified = ANY (ARRAY['verified'::text, 'true'::text]))) AS verified,
            count(*) FILTER (WHERE ((COALESCE(TRIM(BOTH FROM leads.email), ''::text) <> ''::text) AND (leads.email_verified IS NULL))) AS unverified,
            count(*) FILTER (WHERE ((COALESCE(TRIM(BOTH FROM leads.email), ''::text) <> ''::text) AND (NOT (leads.email ~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+[.][A-Za-z]{2,}$'::text)))) AS malformed
           FROM leads
        )
 SELECT ( SELECT (NULLIF(app_secrets.value, ''::text))::integer AS "nullif"
           FROM app_secrets
          WHERE (app_secrets.key = 'invite_daily_cap'::text)) AS cap_today,
    ( SELECT app_secrets.value
           FROM app_secrets
          WHERE (app_secrets.key = 'invite_enabled'::text)) AS invites_enabled,
    s.invites_ever,
    s.invites_24h,
    s.invites_3d,
    s.invites_7d,
    s.bounced_ever,
    s.bounced_3d,
    s.bounced_7d,
        CASE
            WHEN (s.invites_3d > 0) THEN round(((100.0 * (s.bounced_3d)::numeric) / (s.invites_3d)::numeric), 1)
            ELSE NULL::numeric
        END AS bounce_pct_3d,
        CASE
            WHEN (s.invites_7d > 0) THEN round(((100.0 * (s.bounced_7d)::numeric) / (s.invites_7d)::numeric), 1)
            ELSE NULL::numeric
        END AS bounce_pct_7d,
    ( SELECT count(*) AS count
           FROM email_suppressions) AS suppressed_total,
    ( SELECT count(*) AS count
           FROM email_suppressions
          WHERE (email_suppressions.email ~ '^qa[.]'::text)) AS suppressed_self_inflicted,
    l.with_email,
    l.verified,
    l.unverified,
    l.malformed,
        CASE
            WHEN (( SELECT app_secrets.value
               FROM app_secrets
              WHERE (app_secrets.key = 'invite_enabled'::text)) <> 'true'::text) THEN 'PAUSED'::text
            WHEN ((s.invites_3d >= 15) AND (((s.bounced_3d)::numeric / (GREATEST(s.invites_3d, (1)::bigint))::numeric) > 0.08)) THEN 'OVER LIMIT - should be paused'::text
            WHEN ((s.invites_7d >= 20) AND (((s.bounced_7d)::numeric / (GREATEST(s.invites_7d, (1)::bigint))::numeric) >= 0.05)) THEN 'ELEVATED - ramp will throttle'::text
            WHEN (s.invites_ever < 50) THEN 'WARMING - too little history to judge'::text
            ELSE 'HEALTHY'::text
        END AS state
   FROM sent s,
    list l;

CREATE OR REPLACE VIEW public.v_department_health AS  WITH base AS (
         SELECT d.dept_key,
            d.name AS department,
            d.health_fn
           FROM org_departments d
        ), tasks AS (
         SELECT t.dept_key,
            count(*) AS n,
            count(*) FILTER (WHERE (t.status = 'done'::text)) AS done,
            count(*) FILTER (WHERE (t.status = ANY (ARRAY['failed'::text, 'blocked'::text]))) AS bad
           FROM org_tasks t
          WHERE (t.updated_at > (now() - '14 days'::interval))
          GROUP BY t.dept_key
        ), runs AS (
         SELECT a.department AS dept_key,
            count(*) AS n,
            count(*) FILTER (WHERE (r.status = 'ok'::text)) AS ok
           FROM (agent_runs r
             JOIN org_agents a ON ((a.agent_key = r.agent)))
          WHERE (r.started_at > (now() - '7 days'::interval))
          GROUP BY a.department
        ), scored AS (
         SELECT b.dept_key,
            b.department,
                CASE
                    WHEN ((COALESCE(t.n, (0)::bigint) > 0) AND (COALESCE(r.n, (0)::bigint) > 0)) THEN round(((((100.0 * ((t.done)::numeric + ((((t.n - t.done) - t.bad))::numeric * 0.5))) / (NULLIF(t.n, 0))::numeric) + ((100.0 * (r.ok)::numeric) / (NULLIF(r.n, 0))::numeric)) / (2)::numeric))
                    WHEN (COALESCE(t.n, (0)::bigint) > 0) THEN round(((100.0 * ((t.done)::numeric + ((((t.n - t.done) - t.bad))::numeric * 0.5))) / (NULLIF(t.n, 0))::numeric))
                    WHEN (COALESCE(r.n, (0)::bigint) > 0) THEN round(((100.0 * (r.ok)::numeric) / (NULLIF(r.n, 0))::numeric))
                    ELSE NULL::numeric
                END AS score,
                CASE
                    WHEN ((COALESCE(t.n, (0)::bigint) > 0) AND (COALESCE(r.n, (0)::bigint) > 0)) THEN (((((((('task throughput ('::text || t.done) || ' done of '::text) || t.n) || ', 14d) and run success ('::text) || r.ok) || ' ok of '::text) || r.n) || ', 7d)'::text)
                    WHEN (COALESCE(t.n, (0)::bigint) > 0) THEN (((('task throughput ('::text || t.done) || ' done of '::text) || t.n) || ', 14d); no runs recorded for its staff'::text)
                    WHEN (COALESCE(r.n, (0)::bigint) > 0) THEN (((('run success ('::text || r.ok) || ' ok of '::text) || r.n) || ', 7d); no tasks moved in 14d'::text)
                    ELSE 'no tasks moved and no runs recorded — nothing to measure yet'::text
                END AS basis
           FROM ((base b
             LEFT JOIN tasks t ON ((t.dept_key = b.dept_key)))
             LEFT JOIN runs r ON ((r.dept_key = b.dept_key)))
        )
 SELECT dept_key,
    department,
    GREATEST((0)::numeric, LEAST((100)::numeric, COALESCE(score, (0)::numeric))) AS score,
    basis,
        CASE
            WHEN (score IS NULL) THEN 'no data'::text
            WHEN (score >= (90)::numeric) THEN 'healthy'::text
            WHEN (score >= (70)::numeric) THEN 'watch'::text
            WHEN (score > (0)::numeric) THEN 'at risk'::text
            ELSE 'no data'::text
        END AS status
   FROM scored;

CREATE OR REPLACE VIEW public.v_digital_twin AS  SELECT ( SELECT count(*) AS count
           FROM org_agents
          WHERE org_agents.active) AS employees_active,
    ( SELECT count(*) AS count
           FROM org_departments
          WHERE org_departments.active) AS departments,
    ( SELECT count(*) AS count
           FROM company_goals
          WHERE company_goals.active) AS company_goals,
    ( SELECT count(*) AS count
           FROM catalog_supplier_categories) AS categories_target,
    ( SELECT count(*) AS count
           FROM category_agent_map
          WHERE (category_agent_map.status = 'mapped'::text)) AS categories_covered,
    ( SELECT count(*) AS count
           FROM v_knowledge_compliance
          WHERE (v_knowledge_compliance.verdict = 'COMPLIANT'::text)) AS knowledge_bases_compliant,
    ( SELECT count(*) AS count
           FROM leads) AS suppliers_in_pipeline,
    ( SELECT count(*) AS count
           FROM inquiries) AS inquiries_total,
    ( SELECT count(*) AS count
           FROM quotes) AS quotes_total,
    ( SELECT count(*) AS count
           FROM transactions) AS transactions_total,
    ( SELECT COALESCE(sum(z.amount_aed), (0)::numeric) AS "coalesce"
           FROM ( SELECT (0)::numeric AS amount_aed) z) AS revenue_placeholder,
    ( SELECT count(*) AS count
           FROM org_tasks
          WHERE (org_tasks.status = ANY (ARRAY['assigned'::text, 'in_progress'::text]))) AS work_in_progress,
    ( SELECT count(*) AS count
           FROM org_tasks
          WHERE (org_tasks.status = 'proposed'::text)) AS awaiting_founder,
    ( SELECT count(*) AS count
           FROM risk_register
          WHERE (risk_register.status = 'open'::text)) AS open_risks,
    ( SELECT count(*) AS count
           FROM institutional_memory) AS memories_held,
    ( SELECT count(*) AS count
           FROM company_event
          WHERE (company_event.occurred_at > (now() - '24:00:00'::interval))) AS events_24h,
    ( SELECT count(*) AS count
           FROM agent_runs
          WHERE (agent_runs.started_at > (now() - '24:00:00'::interval))) AS agent_runs_24h,
    ( SELECT count(*) AS count
           FROM agent_runs
          WHERE ((agent_runs.started_at > (now() - '24:00:00'::interval)) AND (agent_runs.status = 'error'::text))) AS agent_errors_24h,
    ( SELECT count(*) AS count
           FROM spec_backlog
          WHERE (spec_backlog.status = 'pending'::text)) AS open_backlog,
    ( SELECT count(*) AS count
           FROM spec_backlog
          WHERE ((spec_backlog.status = 'pending'::text) AND (spec_backlog.priority = 1))) AS open_p1;

CREATE OR REPLACE VIEW public.v_email_deadletter AS  SELECT id,
    type,
    to_email,
    to_role,
    subject,
    attempts,
    last_error,
    created_at
   FROM notifications
  WHERE (status = 'failed'::text)
  ORDER BY created_at DESC;

CREATE OR REPLACE VIEW public.v_employee_knowledge_compliance AS  SELECT a.agent_key,
    a.title,
    a.department,
    a.seniority,
    count(DISTINCT ek.layer_no) AS layers_bound,
    ( SELECT count(*) AS count
           FROM employee_knowledge_standard
          WHERE employee_knowledge_standard.required) AS layers_required,
    ( SELECT count(*) AS count
           FROM employee_workflow w
          WHERE (w.agent_key = a.agent_key)) AS workflows,
    ( SELECT count(*) AS count
           FROM employee_kpi k
          WHERE ((k.agent_key = a.agent_key) AND k.active)) AS kpis,
    ( SELECT count(*) AS count
           FROM employee_authority ea
          WHERE (ea.agent_key = a.agent_key)) AS authorities,
        CASE
            WHEN ((count(DISTINCT ek.layer_no) = ( SELECT count(*) AS count
               FROM employee_knowledge_standard
              WHERE employee_knowledge_standard.required)) AND (( SELECT count(*) AS count
               FROM employee_kpi k
              WHERE ((k.agent_key = a.agent_key) AND k.active)) > 0)) THEN 'COMPLIANT'::text
            ELSE 'INCOMPLETE'::text
        END AS verdict
   FROM (org_agents a
     LEFT JOIN employee_knowledge ek ON ((ek.agent_key = a.agent_key)))
  WHERE a.active
  GROUP BY a.agent_key, a.title, a.department, a.seniority;

CREATE OR REPLACE VIEW public.v_eval_latest AS  SELECT prompt_key,
    score,
    cases_total,
    created_at
   FROM ( SELECT prompt_eval_runs.id,
            prompt_eval_runs.prompt_key,
            prompt_eval_runs.version,
            prompt_eval_runs.score,
            prompt_eval_runs.cases_total,
            prompt_eval_runs.detail,
            prompt_eval_runs.created_at,
            row_number() OVER (PARTITION BY prompt_eval_runs.prompt_key ORDER BY prompt_eval_runs.created_at DESC) AS rn
           FROM prompt_eval_runs) x
  WHERE (rn = 1)
  ORDER BY score NULLS FIRST;

CREATE OR REPLACE VIEW public.v_event_backbone AS  SELECT event_type,
    count(DISTINCT agent_key) AS subscribers,
    ( SELECT count(*) AS count
           FROM company_event e
          WHERE (e.event_type = s.event_type)) AS events_ever,
    ( SELECT count(*) AS count
           FROM company_event e
          WHERE ((e.event_type = s.event_type) AND (e.occurred_at > (now() - '24:00:00'::interval)))) AS events_24h,
    ( SELECT count(*) AS count
           FROM event_delivery d
          WHERE (d.event_type = s.event_type)) AS deliveries,
        CASE
            WHEN (( SELECT count(*) AS count
               FROM company_event e
              WHERE (e.event_type = s.event_type)) = 0) THEN 'NO_EVENTS_EVER'::text
            WHEN (( SELECT count(*) AS count
               FROM event_delivery d
              WHERE (d.event_type = s.event_type)) = 0) THEN 'UNDELIVERED'::text
            ELSE 'LIVE'::text
        END AS state,
    ( SELECT count(*) AS count
           FROM event_rollup r
          WHERE (r.event_type = s.event_type)) AS chains,
    ( SELECT count(*) AS count
           FROM event_rollup r
          WHERE ((r.event_type = s.event_type) AND (r.outcome = ANY (ARRAY['open'::text, 'partial'::text])))) AS chains_open
   FROM event_subscription s
  WHERE active
  GROUP BY event_type
  ORDER BY event_type;

CREATE OR REPLACE VIEW public.v_executions_without_decision_trace AS  SELECT a.id,
    a.action_class,
    a.executor,
    a.correlation_id,
    a.status,
    a.created_at
   FROM (action_execution a
     LEFT JOIN decision_trace d ON ((d.correlation_id = a.correlation_id)))
  WHERE (d.id IS NULL);

CREATE OR REPLACE VIEW public.v_executor_registry_gaps AS  SELECT action_class,
    department,
    kind,
    target,
    risk_tier,
    reversible,
    (idempotency_strategy IS NULL) AS idempotency_undeclared,
    (reversible AND (compensation_action_class IS NULL)) AS reversible_without_compensation,
    ((risk_tier = 'high'::text) AND COALESCE(advisory_safe, false)) AS high_risk_marked_advisory_safe,
    (owner_os IS NULL) AS owner_os_undeclared
   FROM org_action_executor e
  WHERE (active AND ((idempotency_strategy IS NULL) OR (reversible AND (compensation_action_class IS NULL)) OR ((risk_tier = 'high'::text) AND COALESCE(advisory_safe, false)) OR (owner_os IS NULL)));

CREATE OR REPLACE VIEW public.v_expense_receipt_gap AS  SELECT id,
    vendor,
    amount,
    currency,
    charged_on,
    source,
    doc_name,
    created_at,
    (CURRENT_DATE - charged_on) AS age_days,
    ((doc_name IS NOT NULL) AND (doc_name <> ''::text)) AS document_was_received,
        CASE
            WHEN ((doc_name IS NOT NULL) AND (doc_name <> ''::text)) THEN 'the receipt was received and read but the archive write was refused - re-forward the vendor email to the inbound address to retry'::text
            ELSE 'no receipt document was ever attached to this entry - retrieve the invoice from the vendor billing portal and attach it manually'::text
        END AS remedy
   FROM expense_entries e
  WHERE (doc_path IS NULL)
  ORDER BY charged_on DESC;

CREATE OR REPLACE VIEW public.v_founder_inbox AS  SELECT id,
    created_at,
    agent,
    kind,
    risk,
    title,
    recommendation,
    target_table,
    target_id,
    'refund_decision'::text AS bucket
   FROM agent_actions a
  WHERE ((status = 'needs_review'::text) AND (EXISTS ( SELECT 1
           FROM phase_c_action_class c
          WHERE ((c.action_class = a.kind) AND c.founder_approval_required))));

CREATE OR REPLACE VIEW public.v_fraud_score AS  SELECT subject_type,
    subject_id,
    open_flags,
    latest_flag,
    reasons,
    (LEAST((100)::bigint, raw))::integer AS score,
        CASE
            WHEN (LEAST((100)::bigint, raw) >= 60) THEN 'high'::text
            WHEN (LEAST((100)::bigint, raw) >= 25) THEN 'medium'::text
            ELSE 'low'::text
        END AS tier
   FROM ( SELECT fraud_flags.subject_type,
            fraud_flags.subject_id,
            count(*) AS open_flags,
            max(fraud_flags.created_at) AS latest_flag,
            array_agg(DISTINCT fraud_flags.kind) AS reasons,
            sum(
                CASE lower(fraud_flags.severity)
                    WHEN 'critical'::text THEN 60
                    WHEN 'high'::text THEN 40
                    WHEN 'medium'::text THEN 15
                    WHEN 'low'::text THEN 5
                    ELSE 10
                END) AS raw
           FROM fraud_flags
          WHERE (COALESCE(fraud_flags.status, 'open'::text) <> ALL (ARRAY['resolved'::text, 'dismissed'::text, 'closed'::text, 'false_positive'::text]))
          GROUP BY fraud_flags.subject_type, fraud_flags.subject_id) s
  ORDER BY ((LEAST((100)::bigint, raw))::integer) DESC;

CREATE OR REPLACE VIEW public.v_gap_report AS  SELECT priority,
    source_doc,
    area,
    item,
    status,
    verdict_at_audit,
    evidence,
    notes,
    updated_at
   FROM spec_backlog
  WHERE (status <> 'done'::text);

CREATE OR REPLACE VIEW public.v_group_completeness AS  SELECT g.id AS group_id,
    g.inquiry_id,
    g.rfq_mode,
    count(*) FILTER (WHERE sr.mandatory) AS shared_required_mandatory,
    count(*) FILTER (WHERE (sr.mandatory AND (a.id IS NOT NULL))) AS shared_answered_mandatory,
    COALESCE(array_agg(sr.field_id ORDER BY sr.field_id) FILTER (WHERE (sr.mandatory AND (a.id IS NULL))), '{}'::text[]) AS shared_missing_mandatory,
    ( SELECT count(*) AS count
           FROM inquiry_workstream w
          WHERE ((w.group_id = g.id) AND w.active)) AS active_workstreams,
    ( SELECT count(*) AS count
           FROM (inquiry_answer_conflict c
             JOIN field_definition fd ON ((fd.field_id = c.field_id)))
          WHERE ((c.group_id = g.id) AND (c.resolved_at IS NULL) AND (fd.scope = 'shared'::text))) AS open_shared_conflicts
   FROM ((inquiry_workstream_group g
     LEFT JOIN LATERAL ( SELECT r.field_id,
            bool_or(r.mandatory) AS mandatory
           FROM ((inquiry_workstream_requirement r
             JOIN inquiry_workstream w ON ((w.id = r.workstream_id)))
             JOIN field_definition fd ON ((fd.field_id = r.field_id)))
          WHERE ((w.group_id = g.id) AND w.active AND (fd.scope = 'shared'::text))
          GROUP BY r.field_id) sr ON (true))
     LEFT JOIN inquiry_answer a ON (((a.group_id = g.id) AND (a.field_id = sr.field_id) AND (a.superseded_by IS NULL) AND (a.value IS NOT NULL) AND (btrim(a.value) <> ''::text) AND (a.precedence <> ALL (ARRAY['model_inference'::answer_precedence, 'unknown'::answer_precedence])))))
  GROUP BY g.id, g.inquiry_id, g.rfq_mode;

CREATE OR REPLACE VIEW public.v_group_dispatch AS  SELECT group_id,
    inquiry_id,
    rfq_mode,
    active_workstreams,
    shared_missing_mandatory,
    (cardinality(shared_missing_mandatory) = 0) AS shared_complete,
    (open_shared_conflicts = 0) AS no_unresolved_shared_conflict,
    COALESCE(( SELECT bool_and(wd.dispatch_eligible) AS bool_and
           FROM v_workstream_dispatch wd
          WHERE ((wd.group_id = gc.group_id) AND wd.active)), false) AS all_active_workstreams_eligible,
    COALESCE(( SELECT array_agg(wd.trade_key ORDER BY wd.trade_key) AS array_agg
           FROM v_workstream_dispatch wd
          WHERE ((wd.group_id = gc.group_id) AND wd.active AND (NOT wd.dispatch_eligible))), '{}'::text[]) AS blocking_trades,
    COALESCE(( SELECT jsonb_object_agg(gr.gate_key, COALESCE(( SELECT (g.state)::text AS state
                   FROM inquiry_gate g
                  WHERE ((g.group_id = gc.group_id) AND (g.workstream_id IS NULL) AND (g.gate_key = gr.gate_key))), 'not_evaluated'::text)) AS jsonb_object_agg
           FROM inquiry_gate_required gr
          WHERE (gr.level = 'group'::text)), '{}'::jsonb) AS gate_states,
    (NOT (EXISTS ( SELECT 1
           FROM inquiry_gate_required gr
          WHERE ((gr.level = 'group'::text) AND (NOT (EXISTS ( SELECT 1
                   FROM inquiry_gate g
                  WHERE ((g.group_id = gc.group_id) AND (g.workstream_id IS NULL) AND (g.gate_key = gr.gate_key) AND fn_gate_state_satisfies(g.state))))))))) AS group_gates_passed,
    ((active_workstreams > 0) AND (cardinality(shared_missing_mandatory) = 0) AND (open_shared_conflicts = 0) AND COALESCE(( SELECT bool_and(wd.dispatch_eligible) AS bool_and
           FROM v_workstream_dispatch wd
          WHERE ((wd.group_id = gc.group_id) AND wd.active)), false) AND (NOT (EXISTS ( SELECT 1
           FROM inquiry_gate_required gr
          WHERE ((gr.level = 'group'::text) AND (NOT (EXISTS ( SELECT 1
                   FROM inquiry_gate g
                  WHERE ((g.group_id = gc.group_id) AND (g.workstream_id IS NULL) AND (g.gate_key = gr.gate_key) AND fn_gate_state_satisfies(g.state)))))))))) AS overall_dispatch_eligible
   FROM v_group_completeness gc;

CREATE OR REPLACE VIEW public.v_handoff_stalled AS  SELECT id,
    action_id,
    from_dept,
    accountable_owner,
    to_dept,
    to_role,
    purpose,
    status,
    deadline,
    accepted_by,
    accepted_at,
    returns_count,
    owner_active,
    transport_status,
    stall_reason,
    days_past_deadline
   FROM ( SELECT c.id,
            c.action_id,
            c.from_dept,
            c.accountable_owner,
            c.to_dept,
            c.to_role,
            c.purpose,
            c.status,
            c.deadline,
            c.accepted_by,
            c.accepted_at,
            c.returns_count,
            o.active AS owner_active,
            a.status AS transport_status,
                CASE
                    WHEN (NOT o.active) THEN 'owner_inactive'::text
                    WHEN ((c.status = 'open'::text) AND (now() > c.deadline)) THEN 'overdue_never_accepted'::text
                    WHEN ((c.status = 'accepted'::text) AND (now() > c.deadline)) THEN 'overdue_accepted_not_closed'::text
                    WHEN ((c.status = 'accepted'::text) AND (c.accepted_at < (now() - '3 days'::interval))) THEN 'accepted_never_closed'::text
                    WHEN ((c.status = 'returned'::text) AND (c.updated_at < (now() - '2 days'::interval))) THEN 'returned_not_corrected'::text
                    WHEN ((c.status = ANY (ARRAY['open'::text, 'accepted'::text])) AND (a.status <> ALL (ARRAY['pending'::text, 'needs_review'::text]))) THEN 'transport_closed_contract_open'::text
                    ELSE NULL::text
                END AS stall_reason,
                CASE
                    WHEN (now() > c.deadline) THEN round((EXTRACT(epoch FROM (now() - c.deadline)) / 86400.0), 2)
                    ELSE (0)::numeric
                END AS days_past_deadline
           FROM ((handoff_contract c
             JOIN org_agents o ON ((o.agent_key = c.accountable_owner)))
             JOIN agent_actions a ON ((a.id = c.action_id)))
          WHERE (c.status = ANY (ARRAY['open'::text, 'accepted'::text, 'returned'::text]))) s
  WHERE (stall_reason IS NOT NULL);

CREATE OR REPLACE VIEW public.v_handoff_without_contract AS  SELECT id AS action_id,
    agent AS receiving_agent,
    status,
    title,
    created_at,
    round((EXTRACT(epoch FROM (now() - created_at)) / 86400.0), 1) AS age_days
   FROM agent_actions a
  WHERE ((kind = 'handoff'::text) AND (NOT (EXISTS ( SELECT 1
           FROM handoff_contract c
          WHERE (c.action_id = a.id)))));

CREATE OR REPLACE VIEW public.v_innovation_pipeline AS  SELECT id,
    title,
    dept_key,
    submitted_by,
    category,
    serves_goal,
    expected_value_aed,
    effort,
    confidence,
    score,
    stage,
    outcome,
    created_at
   FROM idea i
  ORDER BY
        CASE stage
            WHEN 'proposed'::text THEN 1
            WHEN 'assessing'::text THEN 2
            WHEN 'approved'::text THEN 3
            WHEN 'building'::text THEN 4
            WHEN 'shipped'::text THEN 5
            ELSE 6
        END, score DESC NULLS LAST;

CREATE OR REPLACE VIEW public.v_inquiry_trade_status AS  SELECT c.group_id,
    c.trade_key,
    t.label_en,
    t.is_core,
    c.status,
    c.evidence_source,
    c.evidence_score,
    c.score_basis,
    c.confirmation_factors,
    c.requires_confirmation,
    c.match_reason,
    c.proposed_at,
    c.confirmed_at,
    c.confirmed_by,
    c.rejected_at,
    c.rejection_reason,
    c.inactivated_at,
    c.activated_at,
    c.workstream_id,
    w.active AS workstream_active,
    ( SELECT count(*) AS count
           FROM inquiry_trade_candidate_evidence e
          WHERE (e.candidate_id = c.id)) AS evidence_rows,
    ((c.status = 'confirmed'::text) AND w.active) AS counts_toward_dispatch
   FROM ((inquiry_trade_candidate c
     JOIN mep_trade t ON ((t.trade_key = c.trade_key)))
     LEFT JOIN inquiry_workstream w ON ((w.id = c.workstream_id)));

CREATE OR REPLACE VIEW public.v_inquiry_workstream_identity AS  SELECT i.id AS inquiry_id,
    g.id AS group_id,
    (g.id IS NOT NULL) AS has_group,
        CASE
            WHEN (g.id IS NULL) THEN (1)::bigint
            ELSE ( SELECT count(*) AS count
               FROM inquiry_workstream w
              WHERE ((w.group_id = g.id) AND w.active))
        END AS effective_workstreams,
        CASE
            WHEN (g.id IS NULL) THEN 'implicit_single_workstream'::text
            ELSE 'multi_workstream'::text
        END AS shape
   FROM (inquiry_intake i
     LEFT JOIN inquiry_workstream_group g ON ((g.inquiry_id = i.id)));

CREATE OR REPLACE VIEW public.v_internal_credential_health AS  SELECT id,
    context,
    label,
    is_legacy,
    active,
    COALESCE(array_length(scope, 1), 0) AS scope_size,
    scope,
    use_count,
    last_used_at,
    last_function,
        CASE
            WHEN (last_used_at IS NULL) THEN NULL::integer
            ELSE ((EXTRACT(epoch FROM (now() - last_used_at)) / (86400)::numeric))::integer
        END AS days_since_use,
    ((EXTRACT(epoch FROM (now() - created_at)) / (86400)::numeric))::integer AS age_days,
    rotated_at,
    expires_at,
    (active AND ((last_used_at IS NULL) OR (last_used_at < (now() - '30 days'::interval)))) AS unused_30d,
    (active AND (NOT is_legacy) AND (created_at < (now() - '90 days'::interval)) AND ((rotated_at IS NULL) OR (rotated_at < (now() - '90 days'::interval)))) AS rotation_due
   FROM internal_credential c;

CREATE OR REPLACE VIEW public.v_internal_escalation_queue AS  SELECT id,
    created_at,
    agent,
    kind,
    risk,
    title,
    recommendation,
    target_table,
    target_id,
        CASE
            WHEN (kind = ANY (ARRAY['payment_approval'::text, 'purchase_order'::text, 'credential_change'::text, 'legal_flag'::text, 'security_incident'::text, 'supplier_ban'::text, 'data_deletion'::text])) THEN 'blocking'::text
            ELSE 'automation_gap'::text
        END AS bucket
   FROM agent_actions a
  WHERE ((status = 'needs_review'::text) AND (NOT (EXISTS ( SELECT 1
           FROM phase_c_action_class c
          WHERE ((c.action_class = a.kind) AND c.founder_approval_required)))));

CREATE OR REPLACE VIEW public.v_internal_secret_migration_progress AS  WITH j AS (
         SELECT job.jobid,
            job.jobname,
            job.active,
            (regexp_match(job.command, 'functions/v1/([a-z0-9_]+)'::text))[1] AS target_function,
            (job.command ~ 'key\s*=\s*''inbound_secret'''::text) AS on_shared_secret,
            (regexp_match(job.command, 'key\s*=\s*''(cred_[a-z0-9_]+)'''::text))[1] AS scoped_key
           FROM cron.job
        )
 SELECT ( SELECT count(*) AS count
           FROM j) AS cron_jobs_total,
    ( SELECT count(*) AS count
           FROM j
          WHERE j.on_shared_secret) AS still_on_shared_secret,
    ( SELECT count(*) AS count
           FROM j
          WHERE (j.on_shared_secret AND j.active)) AS still_on_shared_secret_active,
    ( SELECT count(*) AS count
           FROM j
          WHERE (j.scoped_key IS NOT NULL)) AS moved_to_scoped_credential,
    ( SELECT count(DISTINCT j.target_function) AS count
           FROM j
          WHERE (j.on_shared_secret AND (j.target_function IS NOT NULL))) AS functions_still_reachable_by_shared_secret,
    ( SELECT internal_credential.use_count
           FROM internal_credential
          WHERE (internal_credential.context = 'legacy.shared'::text)) AS shared_secret_use_count,
    ( SELECT internal_credential.last_used_at
           FROM internal_credential
          WHERE (internal_credential.context = 'legacy.shared'::text)) AS shared_secret_last_used,
    ( SELECT internal_credential.last_function
           FROM internal_credential
          WHERE (internal_credential.context = 'legacy.shared'::text)) AS shared_secret_last_function,
    ( SELECT count(*) AS count
           FROM internal_credential
          WHERE (internal_credential.active AND (NOT internal_credential.is_legacy))) AS scoped_credentials_issued,
    ((( SELECT count(*) AS count
           FROM j
          WHERE (j.on_shared_secret AND j.active)) = 0) AND (COALESCE(( SELECT internal_credential.last_used_at
           FROM internal_credential
          WHERE (internal_credential.context = 'legacy.shared'::text)), '1970-01-01 00:00:00+00'::timestamp with time zone) < (now() - '7 days'::interval))) AS safe_to_withdraw_shared_secret;

CREATE OR REPLACE VIEW public.v_invite_funnel AS  SELECT COALESCE(tt.label, u.code) AS trade,
    u.code AS trade_code,
    count(DISTINCT l.id) AS invited,
    count(DISTINCT l.id) FILTER (WHERE (l.invite_status = 'sent'::text)) AS delivered,
    count(DISTINCT l.id) FILTER (WHERE (l.invite_status = 'bounced'::text)) AS bounced,
    count(DISTINCT l.id) FILTER (WHERE ((COALESCE(l.claimed, false) = true) OR (l.registration_status IS NOT NULL))) AS registered
   FROM leads l,
    (LATERAL unnest(
        CASE
            WHEN (cardinality(l.invite_trades) = 0) THEN ARRAY['(unclassified)'::text]
            ELSE l.invite_trades
        END) u(code)
     LEFT JOIN taxonomy_trade tt ON ((tt.code = u.code)))
  WHERE (l.invite_status IS NOT NULL)
  GROUP BY COALESCE(tt.label, u.code), u.code;

CREATE OR REPLACE VIEW public.v_invite_nonresponders AS  SELECT id,
    company_name,
    email,
    COALESCE(phone_e164, phone) AS phone,
    invite_trades,
    invited_at,
    ((now())::date - (invited_at)::date) AS days_since_invite
   FROM leads l
  WHERE ((invite_status = ANY (ARRAY['sent'::text, 'queued'::text])) AND (COALESCE(claimed, false) = false) AND (invited_at IS NOT NULL) AND (invited_at < (now() - '7 days'::interval)))
  ORDER BY invited_at;

CREATE OR REPLACE VIEW public.v_kb_citation_check AS  SELECT id,
    category,
    "left"(title, 80) AS title,
    citation,
    source_kind,
    source_id,
    created_at
   FROM kb_chunks
  WHERE ((citation IS NULL) OR (length(btrim(COALESCE(citation, ''::text))) < 8))
  ORDER BY created_at DESC;

CREATE OR REPLACE VIEW public.v_kb_confidence AS  SELECT id,
    category,
    title,
    confidence,
    has_citation,
    effective_date,
    created_at,
        CASE
            WHEN (confidence >= 75) THEN 'high'::text
            WHEN (confidence >= 50) THEN 'medium'::text
            ELSE 'low'::text
        END AS band
   FROM ( SELECT kb_chunks.id,
            kb_chunks.category,
            "left"(kb_chunks.title, 80) AS title,
            LEAST(100, (((
                CASE
                    WHEN ((kb_chunks.citation IS NOT NULL) AND (length(btrim(kb_chunks.citation)) >= 8)) THEN 40
                    ELSE 0
                END +
                CASE
                    WHEN ((kb_chunks.title IS NOT NULL) AND (btrim(kb_chunks.title) <> ''::text)) THEN 20
                    ELSE 0
                END) +
                CASE
                    WHEN (length(COALESCE(kb_chunks.content, ''::text)) >= 200) THEN 20
                    ELSE 0
                END) +
                CASE
                    WHEN ((kb_chunks.effective_date IS NOT NULL) AND (kb_chunks.effective_date >= CURRENT_DATE)) THEN 20
                    WHEN (kb_chunks.effective_date IS NOT NULL) THEN 10
                    ELSE 0
                END)) AS confidence,
            ((kb_chunks.citation IS NOT NULL) AND (length(btrim(COALESCE(kb_chunks.citation, ''::text))) >= 8)) AS has_citation,
            kb_chunks.effective_date,
            kb_chunks.created_at
           FROM kb_chunks) s;

CREATE OR REPLACE VIEW public.v_kb_coverage AS  SELECT c.slug AS category,
    c.name AS label,
    c.num,
    count(k.id) AS chunks,
        CASE
            WHEN (count(k.id) = 0) THEN 'gap'::text
            WHEN (count(k.id) < 3) THEN 'thin'::text
            ELSE 'covered'::text
        END AS status
   FROM (catalog_supplier_categories c
     LEFT JOIN kb_chunks k ON ((regexp_replace(COALESCE(k.category, ''::text), '^cat:'::text, ''::text) = c.slug)))
  GROUP BY c.slug, c.name, c.num;

CREATE OR REPLACE VIEW public.v_kb_operational_86_coverage AS  SELECT c.num,
    c.slug AS live_catalog_slug,
    c.name AS live_catalog_name,
    r.route_key,
    r.expected_catalog_slug,
    (r.expected_catalog_slug IS DISTINCT FROM c.slug) AS slug_differs,
    r.route_type,
    r.coverage_status,
    count(m.subcategory_slug) AS mapped_subcategories,
    count(DISTINCT m.package_slug) AS mapped_packages,
        CASE
            WHEN (r.catalog_num IS NULL) THEN 'UNMAPPED'::text
            WHEN (count(m.subcategory_slug) = 0) THEN 'EMPTY'::text
            ELSE 'MAPPED'::text
        END AS verdict
   FROM ((catalog_supplier_categories c
     LEFT JOIN kb_operational_route r ON ((r.catalog_num = c.num)))
     LEFT JOIN kb_operational_route_map m ON ((m.catalog_num = r.catalog_num)))
  GROUP BY c.num, c.slug, c.name, r.route_key, r.expected_catalog_slug, r.route_type, r.coverage_status, r.catalog_num
  ORDER BY c.num;

CREATE OR REPLACE VIEW public.v_kb_regulation_gaps AS  SELECT slug AS category,
    name,
    ( SELECT count(*) AS count
           FROM kb_chunks k
          WHERE ((k.category_norm = regexp_replace(lower(c.slug), '^cat:'::text, ''::text)) AND (k.source_kind = 'trade'::text))) AS trade_chunks
   FROM category_agents c
  WHERE ((requires_regulation IS TRUE) AND (NOT (EXISTS ( SELECT 1
           FROM kb_chunks k
          WHERE ((k.source_kind = 'regulation'::text) AND (k.category_norm IN ( SELECT regexp_replace(lower(c.slug), '^cat:'::text, ''::text) AS regexp_replace
                UNION
                 SELECT a.maps_to
                   FROM kb_category_aliases a
                  WHERE (a.category = regexp_replace(lower(c.slug), '^cat:'::text, ''::text)))))))))
  ORDER BY slug;

CREATE OR REPLACE VIEW public.v_kb_review_due AS  SELECT id,
    category,
    "left"(title, 80) AS title,
    effective_date,
    created_at,
    array_remove(ARRAY[
        CASE
            WHEN ((source_kind = 'regulation'::text) AND (effective_date IS NULL)) THEN 'undated'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((source_kind = 'regulation'::text) AND ((citation IS NULL) OR (length(btrim(COALESCE(citation, ''::text))) < 8))) THEN 'weak_citation'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((source_kind = 'regulation'::text) AND (effective_date IS NOT NULL) AND (effective_date < (CURRENT_DATE - '3 years'::interval))) THEN 'aging_regulation'::text
            ELSE NULL::text
        END], NULL::text) AS reasons
   FROM kb_chunks
  WHERE (((source_kind = 'regulation'::text) AND (effective_date IS NULL)) OR ((source_kind = 'regulation'::text) AND ((citation IS NULL) OR (length(btrim(COALESCE(citation, ''::text))) < 8))) OR ((source_kind = 'regulation'::text) AND (effective_date IS NOT NULL) AND (effective_date < (CURRENT_DATE - '3 years'::interval))))
  ORDER BY created_at DESC;

CREATE OR REPLACE VIEW public.v_kb_risk AS  SELECT id,
    category,
    source_kind,
    "left"(title, 80) AS title,
    effective_date,
        CASE
            WHEN (source_kind = 'regulation'::text) THEN 'high'::text
            WHEN (source_kind = ANY (ARRAY['material'::text, 'trade'::text])) THEN 'medium'::text
            ELSE 'low'::text
        END AS risk_tier,
        CASE
            WHEN (source_kind = 'regulation'::text) THEN 'compliance/legal'::text
            WHEN (source_kind = ANY (ARRAY['material'::text, 'trade'::text])) THEN 'technical/spec'::text
            ELSE 'general'::text
        END AS risk_reason
   FROM kb_chunks;

CREATE OR REPLACE VIEW public.v_kb_route_crosswalk AS  WITH m AS (
         SELECT kb_operational_route_map.catalog_num,
            count(DISTINCT kb_operational_route_map.package_slug) AS packages,
            count(DISTINCT kb_operational_route_map.subcategory_slug) AS subcategories,
            string_agg(DISTINCT kb_operational_route_map.package_slug, ', '::text ORDER BY kb_operational_route_map.package_slug) AS package_list
           FROM kb_operational_route_map
          GROUP BY kb_operational_route_map.catalog_num
        ), sc AS (
         SELECT rm.catalog_num,
            q.mandatory,
            count(*) AS n,
            count(*) FILTER (WHERE (COALESCE(btrim(q.field_key), ''::text) = ''::text)) AS no_field_key
           FROM (kb_operational_route_map rm
             JOIN kb_stage.questions q ON ((q.subcategory_slug = rm.subcategory_slug)))
          GROUP BY rm.catalog_num, q.mandatory
        ), qs AS (
         SELECT sc.catalog_num,
            COALESCE(sum(sc.n) FILTER (WHERE sc.mandatory), (0)::numeric) AS mandatory_q,
            COALESCE(sum(sc.n) FILTER (WHERE (NOT sc.mandatory)), (0)::numeric) AS optional_q,
            COALESCE(sum(sc.no_field_key) FILTER (WHERE sc.mandatory), (0)::numeric) AS mandatory_no_key,
            COALESCE(sum(sc.no_field_key) FILTER (WHERE (NOT sc.mandatory)), (0)::numeric) AS optional_no_key
           FROM sc
          GROUP BY sc.catalog_num
        ), rec AS (
         SELECT rm.catalog_num,
            count(DISTINCT r_1.record_id) AS records,
            count(DISTINCT s.v) AS sources,
            count(DISTINCT r_1.record_id) FILTER (WHERE ((COALESCE(r_1.jurisdiction, ''::text) <> ''::text) OR (COALESCE(r_1.authority, ''::text) <> ''::text))) AS regulated_records
           FROM ((kb_operational_route_map rm
             JOIN kb_stage.records r_1 ON ((r_1.subcategory_slug = rm.subcategory_slug)))
             LEFT JOIN LATERAL ( SELECT jsonb_array_elements_text(
                        CASE
                            WHEN (jsonb_typeof(r_1.source_ids) = 'array'::text) THEN r_1.source_ids
                            ELSE '[]'::jsonb
                        END) AS v) s ON (true))
          GROUP BY rm.catalog_num
        ), al AS (
         SELECT kb_operational_alias.catalog_num,
            count(*) FILTER (WHERE (kb_operational_alias.language = 'en'::text)) AS aliases_en,
            count(*) FILTER (WHERE (kb_operational_alias.language = 'ar'::text)) AS aliases_ar
           FROM kb_operational_alias
          GROUP BY kb_operational_alias.catalog_num
        ), gp AS (
         SELECT rm.catalog_num,
            count(*) AS gaps
           FROM (kb_operational_route_map rm
             JOIN kb_stage.knowledge_gaps g ON ((g.subcategory_slug = rm.subcategory_slug)))
          GROUP BY rm.catalog_num
        ), tst AS (
         SELECT kb_operational_route_test.catalog_num,
            count(*) AS route_tests
           FROM kb_operational_route_test
          GROUP BY kb_operational_route_test.catalog_num
        )
 SELECT r.catalog_num,
    r.catalog_name,
    r.expected_catalog_slug AS production_slug,
    r.route_key,
    r.route_type,
    r.coverage_status,
    COALESCE(m.packages, (0)::bigint) AS packages,
    COALESCE(m.package_list, ''::text) AS package_list,
    COALESCE(m.subcategories, (0)::bigint) AS subcategories,
    COALESCE(qs.mandatory_q, (0)::numeric) AS mandatory_q,
    COALESCE(qs.optional_q, (0)::numeric) AS optional_q,
    COALESCE(qs.mandatory_no_key, (0)::numeric) AS mandatory_no_key,
    COALESCE(qs.optional_no_key, (0)::numeric) AS optional_no_key,
    COALESCE(rec.records, (0)::bigint) AS records,
    COALESCE(rec.sources, (0)::bigint) AS sources,
    COALESCE(rec.regulated_records, (0)::bigint) AS regulated_records,
    COALESCE(al.aliases_en, (0)::bigint) AS aliases_en,
    COALESCE(al.aliases_ar, (0)::bigint) AS aliases_ar,
    COALESCE(gp.gaps, (0)::bigint) AS knowledge_gaps,
    COALESCE(tst.route_tests, (0)::bigint) AS route_tests
   FROM ((((((kb_operational_route r
     LEFT JOIN m ON ((m.catalog_num = r.catalog_num)))
     LEFT JOIN qs ON ((qs.catalog_num = r.catalog_num)))
     LEFT JOIN rec ON ((rec.catalog_num = r.catalog_num)))
     LEFT JOIN al ON ((al.catalog_num = r.catalog_num)))
     LEFT JOIN gp ON ((gp.catalog_num = r.catalog_num)))
     LEFT JOIN tst ON ((tst.catalog_num = r.catalog_num)));

CREATE OR REPLACE VIEW public.v_kb_route_regulatory_status AS  SELECT catalog_num,
    catalog_name,
    regulatory_coverage_status,
    regulatory_coverage_note,
    ( SELECT count(DISTINCT NULLIF(btrim(k.authority), ''::text)) AS count
           FROM (kb_operational_route_map m
             JOIN kb_stage.records k ON ((k.subcategory_slug = m.subcategory_slug)))
          WHERE (m.catalog_num = r.catalog_num)) AS named_authorities_in_corpus,
    fn_kb_route_activation_blocked(catalog_num) AS activation_gate
   FROM kb_operational_route r;

CREATE OR REPLACE VIEW public.v_kernel_trigger_source_derived AS  WITH wt(t, why) AS (
         VALUES ('agent_actions'::text,'the legacy agent work queue'::text), ('org_tasks'::text,'the department task queue'::text), ('phase_c_task'::text,'the kernel task table'::text), ('notifications'::text,'the outbound message queue: a queued message is work owed to a person'::text), ('os_incidents'::text,'phase_b_business_object.incident, governed by W29'::text), ('board_reports'::text,'phase_b_business_object.intelligence_product, governed by W25'::text), ('evolution_proposal'::text,'phase_b_business_object.organization_change_request, governed by W30'::text), ('leads'::text,'the supplier lead / supplier_account population, governed by W09'::text), ('inquiries'::text,'phase_b_business_object.inquiry, governed by W05'::text), ('inquiry_intake'::text,'the inquiry draft that becomes phase_b_business_object.inquiry'::text), ('quotes'::text,'phase_b_business_object.quotation, governed by W14'::text), ('transactions'::text,'phase_b_business_object.payment_transaction, governed by W16'::text), ('customers'::text,'phase_b_business_object.customer_account, governed by W04'::text)
        ), body AS (
         SELECT p.oid,
            p.proname,
            regexp_replace(regexp_replace(p.prosrc, '/\*.*?\*/'::text, ' '::text, 'g'::text), '--[^\n]*'::text, ' '::text, 'g'::text) AS src
           FROM (pg_proc p
             JOIN pg_namespace n ON ((n.oid = p.pronamespace)))
          WHERE ((n.nspname = 'public'::name) AND (p.prokind = 'f'::"char"))
        ), writer AS (
         SELECT b.oid,
            b.proname,
            string_agg(DISTINCT wt.t, ', '::text) AS work_tables
           FROM (body b
             JOIN wt ON ((b.src ~* (('(insert\s+into|update)\s+(public\.)?'::text || wt.t) || '\y'::text))))
          GROUP BY b.oid, b.proname
        ), kernelcaller AS (
         SELECT b.oid,
            b.proname
           FROM body b
          WHERE ((b.src ~ '\yfn_kernel_trigger_submit\s*\('::text) OR (b.src ~ '\yfn_kernel_signal_submit\s*\('::text) OR (b.src ~ '\yfn_kernel_source_emit\s*\('::text))
        ), replayer AS (
         SELECT b.oid,
            b.proname
           FROM body b
          WHERE ((b.src ~ '\yphase_c_event_outbox\y'::text) AND (b.src ~ '\yfn_(kernel|phase_c)_(workflow_start|event_ingress)\s*\('::text))
        ), cronjob AS (
         SELECT j.jobid,
            j.active,
            regexp_replace(regexp_replace(j.command, '/\*.*?\*/'::text, ' '::text, 'g'::text), '--[^\n]*'::text, ' '::text, 'g'::text) AS cmd
           FROM cron.job j
        ), cron_fact AS (
         SELECT cj.jobid,
            cj.active,
            (EXISTS ( SELECT 1
                   FROM writer wr
                  WHERE ((strpos(cj.cmd, (wr.proname)::text) > 0) AND (cj.cmd ~ (('\y'::text || (wr.proname)::text) || '\s*\('::text))))) AS creates_work,
            ((cj.cmd ~ '\yfn_kernel_trigger_submit\s*\('::text) OR (EXISTS ( SELECT 1
                   FROM kernelcaller kc
                  WHERE ((strpos(cj.cmd, (kc.proname)::text) > 0) AND (cj.cmd ~ (('\y'::text || (kc.proname)::text) || '\s*\('::text)))))) AS routes,
            (EXISTS ( SELECT 1
                   FROM replayer rp
                  WHERE ((strpos(cj.cmd, (rp.proname)::text) > 0) AND (cj.cmd ~ (('\y'::text || (rp.proname)::text) || '\s*\('::text))))) AS replays
           FROM cronjob cj
        ), trg_fact AS (
         SELECT (((((n.nspname)::text || '.'::text) || (c.relname)::text) || ':'::text) || (tg.tgname)::text) AS source_ref,
            (tg.tgenabled <> 'D'::"char") AS active,
            COALESCE(( SELECT bool_or((u.tn <> c.relname)) AS bool_or
                   FROM writer wr,
                    LATERAL unnest(string_to_array(wr.work_tables, ', '::text)) u(tn)
                  WHERE (wr.oid = tg.tgfoid)), false) AS creates_work,
            (EXISTS ( SELECT 1
                   FROM kernelcaller kc
                  WHERE (kc.oid = tg.tgfoid))) AS routes,
            (EXISTS ( SELECT 1
                   FROM replayer rp
                  WHERE (rp.oid = tg.tgfoid))) AS replays
           FROM ((pg_trigger tg
             JOIN pg_class c ON ((c.oid = tg.tgrelid)))
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE (NOT tg.tgisinternal)
        ), evt_fact AS (
         SELECT e.evtname AS source_ref,
            (e.evtenabled <> 'D'::"char") AS active,
            (EXISTS ( SELECT 1
                   FROM writer wr
                  WHERE (wr.oid = e.evtfoid))) AS creates_work,
            (EXISTS ( SELECT 1
                   FROM kernelcaller kc
                  WHERE (kc.oid = e.evtfoid))) AS routes,
            (EXISTS ( SELECT 1
                   FROM replayer rp
                  WHERE (rp.oid = e.evtfoid))) AS replays
           FROM pg_event_trigger e
        )
 SELECT s.source_key,
    s.source_kind,
    s.source_ref,
    s.source_class,
    s.adapter_trigger_type,
    s.workflow_id,
    s.accountable_role_id,
    s.connection_state,
    s.disposition,
    s.evidence,
        CASE s.source_kind
            WHEN 'cron_job'::text THEN cf.active
            WHEN 'database_trigger'::text THEN tf.active
            WHEN 'event_trigger'::text THEN ef.active
            ELSE s.recorded_active
        END AS is_active_now,
        CASE s.source_kind
            WHEN 'cron_job'::text THEN cf.creates_work
            WHEN 'database_trigger'::text THEN tf.creates_work
            WHEN 'event_trigger'::text THEN ef.creates_work
            ELSE s.recorded_creates_work
        END AS creates_work_now,
        CASE s.source_kind
            WHEN 'cron_job'::text THEN cf.routes
            WHEN 'database_trigger'::text THEN tf.routes
            WHEN 'event_trigger'::text THEN ef.routes
            ELSE ((EXISTS ( SELECT 1
               FROM (kernelcaller kc
                 JOIN body b2 ON ((b2.oid = kc.oid)))
              WHERE (b2.src ~~ (('%'''::text || s.source_key) || '''%'::text)))) OR (EXISTS ( SELECT 1
               FROM (((((phase_c_edge_function_writes w
                 JOIN pg_class cl ON ((cl.relname = w.table_name)))
                 JOIN pg_namespace ns ON (((ns.oid = cl.relnamespace) AND (ns.nspname = 'public'::name))))
                 JOIN pg_trigger tg ON (((tg.tgrelid = cl.oid) AND (NOT tg.tgisinternal) AND (tg.tgenabled <> 'D'::"char"))))
                 JOIN pg_proc tp ON ((tp.oid = tg.tgfoid)))
                 JOIN kernelcaller kc2 ON ((kc2.proname = tp.proname)))
              WHERE ((NOT w.unbounded) AND (s.source_kind = 'edge_function'::text) AND (w.edge_function = regexp_replace(s.source_key, '^edge:'::text, ''::text))))) OR COALESCE(s.recorded_routes_through_inbox, false))
        END AS routes_through_inbox,
        CASE s.source_kind
            WHEN 'cron_job'::text THEN cf.replays
            WHEN 'database_trigger'::text THEN tf.replays
            WHEN 'event_trigger'::text THEN ef.replays
            ELSE false
        END AS outbox_used_as_request_queue,
    ( SELECT r.kind
           FROM fn_phase_c_resolve_actor(s.accountable_role_id) r(kind, role_id, department_id, system_actor_id, reason)) AS accountable_kind
   FROM (((kernel_trigger_source s
     LEFT JOIN cron_fact cf ON ((cf.jobid =
        CASE
            WHEN ((s.source_kind = 'cron_job'::text) AND (s.source_ref ~ '^[0-9]+$'::text)) THEN (s.source_ref)::bigint
            ELSE NULL::bigint
        END)))
     LEFT JOIN trg_fact tf ON (((s.source_kind = 'database_trigger'::text) AND (tf.source_ref = s.source_ref))))
     LEFT JOIN evt_fact ef ON (((s.source_kind = 'event_trigger'::text) AND (ef.source_ref = s.source_ref))));

CREATE OR REPLACE VIEW public.v_knowledge_compliance AS  SELECT a.slug AS agent_slug,
    a.name,
    a.agent_class,
    count(k.topic) FILTER (WHERE (k.topic IS NOT NULL)) AS modules_present,
    ( SELECT count(*) AS count
           FROM knowledge_module_standard
          WHERE knowledge_module_standard.required) AS modules_required,
    string_agg(s.module, ', '::text ORDER BY s.ord) FILTER (WHERE (k.topic IS NULL)) AS missing_modules,
        CASE
            WHEN (count(k.topic) FILTER (WHERE (k.topic IS NOT NULL)) = ( SELECT count(*) AS count
               FROM knowledge_module_standard
              WHERE knowledge_module_standard.required)) THEN 'COMPLIANT'::text
            ELSE 'INCOMPLETE'::text
        END AS verdict
   FROM ((category_agents a
     CROSS JOIN knowledge_module_standard s)
     LEFT JOIN agent_knowledge k ON (((k.agent_key = ('cat:'::text || a.slug)) AND (k.topic = s.module))))
  WHERE (s.required AND (a.agent_class <> 'internal_staff'::text))
  GROUP BY a.slug, a.name, a.agent_class;

CREATE OR REPLACE VIEW public.v_knowledge_matrix AS  SELECT agent_key,
    layer,
    count(*) AS topics,
    round(avg(length(content))) AS avg_chars,
    count(*) FILTER (WHERE (topic = ANY (ARRAY['Industry Knowledge'::text, 'Products & Services'::text, 'Technical Knowledge'::text, 'Supplier Knowledge'::text, 'Quotation Knowledge'::text, 'Documents Knowledge'::text, 'UAE Regulations & Authorities'::text, 'Inquiry Qualification Logic'::text]))) AS spec_modules_present,
    max(updated_at) AS last_updated
   FROM agent_knowledge k
  GROUP BY agent_key, layer;

CREATE OR REPLACE VIEW public.v_knowledge_review_due AS  SELECT agent_key,
    replace(agent_key, 'cat:'::text, ''::text) AS catalog_slug,
    count(*) AS modules_due,
    min(review_due) AS due_since
   FROM agent_knowledge k
  WHERE ((review_due IS NOT NULL) AND (review_due <= CURRENT_DATE))
  GROUP BY agent_key
  ORDER BY (min(review_due)), agent_key;

CREATE OR REPLACE VIEW public.v_lead_routing_coverage AS  SELECT m.catalog_slug,
    c.name AS category,
    count(DISTINCT l.id) AS leads_routable,
    ( SELECT count(*) AS count
           FROM category_agent_map am
          WHERE ((am.catalog_slug = m.catalog_slug) AND (am.status = 'mapped'::text))) AS has_agent,
    ( SELECT kc.verdict
           FROM v_knowledge_compliance kc
          WHERE (kc.agent_slug = m.catalog_slug)) AS knowledge_verdict
   FROM ((lead_trade_map m
     JOIN catalog_supplier_categories c ON ((c.slug = m.catalog_slug)))
     JOIN leads l ON ((l.invite_trades && ARRAY[m.trade_key])))
  GROUP BY m.catalog_slug, c.name;

CREATE OR REPLACE VIEW public.v_lead_text AS  SELECT id,
    ((' '::text || regexp_replace(regexp_replace(lower(regexp_replace(concat_ws(' '::text, sector, sub_type, categories, services, products, description, company_name, capability_summary), '&#0?38;|&amp;'::text, ' and '::text, 'g'::text)), '[^a-z0-9]+'::text, ' '::text, 'g'::text), '\s+'::text, ' '::text, 'g'::text)) || ' '::text) AS hay
   FROM leads l;

CREATE OR REPLACE VIEW public.v_legacy_secret_users AS  SELECT function_name,
    count(*) AS uses,
    min(at) AS first_seen,
    max(at) AS last_seen
   FROM internal_credential_audit
  WHERE (reason = 'legacy_secret_used'::text)
  GROUP BY function_name
  ORDER BY (count(*)) DESC;

CREATE OR REPLACE VIEW public.v_llm_calls_without_task_class AS  SELECT date_trunc('day'::text, occurred_at) AS day,
    count(*) AS calls,
    count(*) FILTER (WHERE ((task_class IS NULL) OR (btrim(task_class) = ''::text))) AS no_task_class,
    count(DISTINCT model_used) AS distinct_models
   FROM ai_cost_log
  GROUP BY (date_trunc('day'::text, occurred_at))
  ORDER BY (date_trunc('day'::text, occurred_at)) DESC;

CREATE OR REPLACE VIEW public.v_llm_identity_route_offcatalog AS  SELECT i.identity_key,
    s.slot,
    s.model_id,
    ( SELECT count(*) AS count
           FROM ai_cost_log l
          WHERE (l.model_used = s.model_id)) AS ledger_rows
   FROM (model_policy_by_identity i
     CROSS JOIN LATERAL ( VALUES ('primary'::text,i.primary_model), ('fallback'::text,i.fallback_model), ('escalation'::text,i.escalation_model)) s(slot, model_id))
  WHERE ((s.model_id IS NOT NULL) AND (s.model_id <> ALL (ARRAY['none'::text, 'none/deterministic'::text])) AND (NOT (EXISTS ( SELECT 1
           FROM model_registry r
          WHERE ((r.model_id = s.model_id) AND r.active)))));

CREATE OR REPLACE VIEW public.v_llm_model_mix AS  SELECT c.fn,
    c.model_used AS model,
    count(*) AS calls,
    count(*) FILTER (WHERE ((p.model_primary IS NOT NULL) AND (c.model_used <> p.model_primary))) AS fallbacks,
    count(*) FILTER (WHERE (NOT COALESCE(c.ok, true))) AS failures,
    round(avg(c.latency_ms)) AS avg_ms,
    sum(COALESCE(c.prompt_tokens, 0)) AS prompt_tokens,
    sum(COALESCE(c.output_tokens, 0)) AS output_tokens,
    round(sum(COALESCE(c.cost_aed, (0)::numeric)), 4) AS cost_aed,
    bool_or(COALESCE(c.cached, false)) AS uses_caching,
    max(c.occurred_at) AS last_seen
   FROM (ai_cost_log c
     LEFT JOIN model_policy p ON (((p.task_class = c.task_class) AND COALESCE(p.active, true))))
  WHERE (c.occurred_at > (now() - '30 days'::interval))
  GROUP BY c.fn, c.model_used;

CREATE OR REPLACE VIEW public.v_llm_offpolicy AS  SELECT fn,
    model,
    calls,
    last_seen
   FROM v_llm_model_mix m
  WHERE ((model IS NOT NULL) AND (model <> 'none'::text) AND (NOT (EXISTS ( SELECT 1
           FROM model_policy p
          WHERE (COALESCE(p.active, true) AND ((p.model_primary = m.model) OR (p.model_fallback = m.model)))))));

CREATE OR REPLACE VIEW public.v_llm_route_never_succeeded AS  SELECT model_used AS model_route,
    count(*) AS calls,
    count(*) FILTER (WHERE ok) AS ok_calls,
    min(occurred_at) AS first_seen,
    max(occurred_at) AS last_seen,
    ( SELECT h.open_until
           FROM llm_route_health h
          WHERE (h.model_id = c.model_used)) AS open_until
   FROM ai_cost_log c
  WHERE ((model_used IS NOT NULL) AND (model_used <> 'none'::text))
  GROUP BY model_used
 HAVING ((count(*) FILTER (WHERE ok) = 0) AND (count(*) > 0));

CREATE OR REPLACE VIEW public.v_llm_unclassified_failures AS  SELECT (date_trunc('day'::text, created_at))::date AS day,
    model_route,
    count(*) AS unclassified
   FROM llm_attempt
  WHERE ((NOT ok) AND (class_key = 'unclassified'::text))
  GROUP BY ((date_trunc('day'::text, created_at))::date), model_route;

CREATE OR REPLACE VIEW public.v_marketplace_liquidity AS  SELECT c.slug AS category,
    c.name,
    cov.coverage,
    cov.supplier_supply AS suppliers_in_pipeline,
    ( SELECT count(*) AS count
           FROM (leads l
             JOIN lead_trade_map t ON ((l.invite_trades && ARRAY[t.trade_key])))
          WHERE ((t.catalog_slug = c.slug) AND l.verified)) AS suppliers_verified,
    ( SELECT count(*) AS count
           FROM inquiries i
          WHERE (i.category = c.slug)) AS inquiries,
        CASE
            WHEN (( SELECT count(*) AS count
               FROM (leads l
                 JOIN lead_trade_map t ON ((l.invite_trades && ARRAY[t.trade_key])))
              WHERE ((t.catalog_slug = c.slug) AND l.verified)) >= 5) THEN 'liquid'::text
            WHEN (cov.supplier_supply >= 50) THEN 'supply_available_unverified'::text
            WHEN (cov.supplier_supply > 0) THEN 'thin_supply'::text
            ELSE 'no_supply'::text
        END AS liquidity_status
   FROM (catalog_supplier_categories c
     JOIN v_category_coverage cov ON ((cov.catalog_slug = c.slug)));

CREATE OR REPLACE VIEW public.v_memory_matrix AS  SELECT 'agent'::text AS scope_type,
    m.agent_key AS scope,
    m.kind,
    count(*) AS rows_held,
    max(m.created_at) AS newest,
    min(m.created_at) AS oldest
   FROM agent_memory m
  GROUP BY m.agent_key, m.kind
UNION ALL
 SELECT 'department'::text AS scope_type,
    o.scope,
    o.kind,
    count(*) AS rows_held,
    max(o.created_at) AS newest,
    min(o.created_at) AS oldest
   FROM org_memory o
  GROUP BY o.scope, o.kind;

CREATE OR REPLACE VIEW public.v_memory_promotion_candidates AS  SELECT id,
    agent_key,
    kind,
    importance,
    source,
    created_at,
    "left"(content, 240) AS preview,
    length(content) AS content_len
   FROM agent_memory m
  WHERE (NOT (EXISTS ( SELECT 1
           FROM memory_promotions p
          WHERE (p.memory_id = m.id))))
  ORDER BY importance DESC NULLS LAST, created_at DESC;

CREATE OR REPLACE VIEW public.v_mkt_brand_by_category AS  SELECT i.category,
    qi.brand,
    count(*) AS line_count,
    count(DISTINCT q.supplier_id) AS suppliers,
    round(sum(COALESCE(qi.amount, (0)::numeric)), 2) AS total_amount
   FROM ((quote_items qi
     JOIN quotes q ON (((q.id)::text = qi.quote_id)))
     JOIN inquiries i ON ((i.id = q.inquiry_id)))
  WHERE ((qi.brand IS NOT NULL) AND (btrim(qi.brand) <> ''::text) AND (i.category IS NOT NULL))
  GROUP BY i.category, qi.brand
  ORDER BY i.category, (count(*)) DESC;

CREATE OR REPLACE VIEW public.v_mkt_over_budget AS  SELECT id AS inquiry_id,
    category,
    budget_aed,
    min_quote,
    (min_quote - budget_aed) AS overrun,
    created_at
   FROM ( SELECT i.id,
            i.category,
            i.created_at,
            (NULLIF(regexp_replace(COALESCE((regexp_match(i.budget, '([0-9][0-9,\.]{2,})'::text))[1], ''::text), '[^0-9]'::text, ''::text, 'g'::text), ''::text))::numeric AS budget_aed,
            ( SELECT min(q.quote_amount) AS min
                   FROM quotes q
                  WHERE ((q.inquiry_id = i.id) AND (COALESCE(q.status, ''::text) <> 'draft'::text))) AS min_quote
           FROM inquiries i
          WHERE ((i.budget IS NOT NULL) AND (btrim(i.budget) <> ''::text))) s
  WHERE ((budget_aed IS NOT NULL) AND (budget_aed >= (100)::numeric) AND (min_quote IS NOT NULL) AND (min_quote > budget_aed))
  ORDER BY (min_quote - budget_aed) DESC;

CREATE OR REPLACE VIEW public.v_mkt_response_by_category AS  WITH fq AS (
         SELECT i.id,
            i.category,
            i.created_at,
            ( SELECT min(q.created_at) AS min
                   FROM quotes q
                  WHERE (q.inquiry_id = i.id)) AS first_quote_at
           FROM inquiries i
          WHERE (i.category IS NOT NULL)
        )
 SELECT category,
    count(*) AS rfqs,
    count(first_quote_at) AS rfqs_quoted,
    round(avg((EXTRACT(epoch FROM (first_quote_at - created_at)) / 3600.0)) FILTER (WHERE (first_quote_at IS NOT NULL)), 1) AS avg_first_quote_hrs,
    round((((count(*) FILTER (WHERE (first_quote_at IS NULL)))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 1) AS no_quote_pct
   FROM fq
  GROUP BY category
  ORDER BY (round(avg((EXTRACT(epoch FROM (first_quote_at - created_at)) / 3600.0)) FILTER (WHERE (first_quote_at IS NOT NULL)), 1)) DESC NULLS LAST;

CREATE OR REPLACE VIEW public.v_mkt_underpriced AS  SELECT q.id AS quote_id,
    q.inquiry_id,
    i.category,
    q.supplier_id,
    q.quote_amount,
    (x.pc ->> 'median'::text) AS category_median,
    q.created_at
   FROM ((quotes q
     JOIN inquiries i ON ((i.id = q.inquiry_id)))
     CROSS JOIN LATERAL ( SELECT fn_price_confidence(i.category, q.quote_amount) AS pc) x)
  WHERE ((COALESCE(q.status, ''::text) <> 'draft'::text) AND (i.category IS NOT NULL) AND ((x.pc ->> 'band'::text) = 'suspiciously_low'::text))
  ORDER BY q.created_at DESC;

CREATE OR REPLACE VIEW public.v_model_policy_offcatalog AS  SELECT p.task_class,
    p.tier,
    p.model_primary,
    p.model_fallback,
    (r1.model_id IS NULL) AS primary_not_in_registry,
    ((p.model_fallback IS NOT NULL) AND (r2.model_id IS NULL)) AS fallback_not_in_registry
   FROM ((model_policy p
     LEFT JOIN model_registry r1 ON (((r1.model_id = p.model_primary) AND r1.active)))
     LEFT JOIN model_registry r2 ON (((r2.model_id = p.model_fallback) AND r2.active)))
  WHERE (COALESCE(p.active, true) AND (p.model_primary IS NOT NULL) AND (p.model_primary <> 'none'::text) AND ((r1.model_id IS NULL) OR ((p.model_fallback IS NOT NULL) AND (r2.model_id IS NULL))));

CREATE OR REPLACE VIEW public.v_obj_ai_change AS  SELECT record_id,
    business_key,
    version,
    state,
    owner_scope,
    owner_ref,
    payload,
    superseded_by,
    superseded_at,
    run_id,
    step_run_id,
    trace_id,
    created_by,
    created_at
   FROM phase_d_object_record
  WHERE (object_id = 'ai_change'::text);

CREATE OR REPLACE VIEW public.v_obj_capability_case AS  SELECT record_id,
    business_key,
    version,
    state,
    owner_scope,
    owner_ref,
    payload,
    superseded_by,
    superseded_at,
    run_id,
