CREATE OR REPLACE VIEW public.v_obj_content_campaign AS  SELECT record_id,
    business_key,
    version,
    state,
    owner_scope,
    owner_ref,
    payload,
    superseded_by,
    superseded_at,
    run_id,
    step_run_id,
    trace_id,
    created_by,
    created_at
   FROM phase_d_object_record
  WHERE (object_id = 'content_campaign'::text);

CREATE OR REPLACE VIEW public.v_obj_customer_case AS  SELECT record_id,
    business_key,
    version,
    state,
    owner_scope,
    owner_ref,
    payload,
    superseded_by,
    superseded_at,
    run_id,
    step_run_id,
    trace_id,
    created_by,
    created_at
   FROM phase_d_object_record
  WHERE (object_id = 'customer_case'::text);

CREATE OR REPLACE VIEW public.v_obj_customer_selection AS  SELECT record_id,
    business_key,
    version,
    state,
    owner_scope,
    owner_ref,
    payload,
    superseded_by,
    superseded_at,
    run_id,
    step_run_id,
    trace_id,
    created_by,
    created_at
   FROM phase_d_object_record
  WHERE (object_id = 'customer_selection'::text);

CREATE OR REPLACE VIEW public.v_obj_customer_terms_acceptance AS  SELECT record_id,
    business_key,
    version,
    state,
    owner_scope,
    owner_ref,
    payload,
    superseded_by,
    superseded_at,
    run_id,
    step_run_id,
    trace_id,
