CREATE OR REPLACE VIEW public.v_operating_manual AS  SELECT 'operating_system'::text AS section,
    o.os_key AS key,
    o.name AS title,
    o.mission AS summary,
    jsonb_build_object('purpose', o.charter, 'mandate', o.mandate, 'owner', o.owner_agent, 'adapts_by', o.adapts_by, 'departments', ( SELECT jsonb_agg(d.dept_key) AS jsonb_agg
           FROM os_department d
          WHERE (d.os_key = o.os_key)), 'owns', ( SELECT jsonb_agg(r.responsibility) AS jsonb_agg
           FROM os_responsibility r
          WHERE (r.os_key = o.os_key)), 'inputs', ( SELECT jsonb_agg(i.kind) AS jsonb_agg
           FROM os_interface i
          WHERE ((i.os_key = o.os_key) AND (i.direction = 'input'::text))), 'outputs', ( SELECT jsonb_agg(i.kind) AS jsonb_agg
           FROM os_interface i
          WHERE ((i.os_key = o.os_key) AND (i.direction = 'output'::text))), 'workflows', ( SELECT jsonb_agg(w.workflow_key) AS jsonb_agg
           FROM workflow w
          WHERE (w.os_key = o.os_key)), 'objectives', ( SELECT jsonb_object_agg(z.horizon, z.objective) AS jsonb_object_agg
           FROM ( SELECT DISTINCT ON (ob.horizon) ob.horizon,
                    ob.objective
                   FROM os_objective ob
                  WHERE (ob.os_key = o.os_key)
                  ORDER BY ob.horizon, ob.id) z)) AS detail
   FROM operating_system o
  WHERE o.active
UNION ALL
 SELECT 'workflow'::text AS section,
    w.workflow_key AS key,
    w.name AS title,
    w.description AS summary,
    jsonb_build_object('os', w.os_key, 'trigger', w.trigger_event, 'steps', ( SELECT jsonb_agg(jsonb_build_object('n', s.step_no, 'step', s.step, 'actor', s.actor_role, 'gate', s.gate) ORDER BY s.step_no) AS jsonb_agg
           FROM workflow_step s
          WHERE (s.workflow_key = w.workflow_key))) AS detail
   FROM workflow w
UNION ALL
 SELECT 'policy'::text AS section,
    ('priority_'::text || (priority_hierarchy.rank)::text) AS key,
    priority_hierarchy.principle AS title,
    priority_hierarchy.meaning AS summary,
    jsonb_build_object('rank', priority_hierarchy.rank, 'overrides_below', priority_hierarchy.overrides_below) AS detail
   FROM priority_hierarchy
UNION ALL
 SELECT 'scheduled_job'::text AS section,
    cron_registry.jobname AS key,
    cron_registry.human_name AS title,
    cron_registry.purpose AS summary,
    jsonb_build_object('category', cron_registry.category) AS detail
   FROM cron_registry
UNION ALL
 SELECT 'governance_policy'::text AS section,
    gp.policy AS key,
    gp.policy AS title,
    gp.rule AS summary,
    jsonb_build_object('domain', gp.domain, 'enforced_by', gp.enforced_by, 'enforcement', gp.enforcement, 'owner_dept', gp.owner_dept) AS detail
   FROM governance_policy gp
UNION ALL
 SELECT 'decision_rule'::text AS section,
    dp.key,
    initcap(replace(dp.key, '_'::text, ' '::text)) AS title,
    dp.description AS summary,
    jsonb_build_object('value', dp.value, 'updated_at', dp.updated_at) AS detail
   FROM decision_policy dp
UNION ALL
 SELECT 'department'::text AS section,
    d.dept_key AS key,
    d.name AS title,
    d.charter AS summary,
    jsonb_build_object('north_star', d.north_star, 'lead_agent', d.lead_agent, 'brain_agent', d.brain_agent, 'health_fn', d.health_fn) AS detail
   FROM org_departments d
  WHERE COALESCE(d.active, true);

CREATE OR REPLACE VIEW public.v_ops_hard_gate_coverage AS  SELECT (raw ->> 'action_class'::text) AS action_class,
    title AS gate_title,
    (raw ->> 'default_tier'::text) AS corpus_default_tier,
    (raw ->> 'approval_role'::text) AS approval_role,
    ( SELECT count(*) AS count
           FROM org_authority a
          WHERE (a.action_class = (g.raw ->> 'action_class'::text))) AS org_authority_rows,
    ( SELECT string_agg(((a.dept_key || '='::text) || a.max_tier), ', '::text ORDER BY a.dept_key) AS string_agg
           FROM org_authority a
          WHERE (a.action_class = (g.raw ->> 'action_class'::text))) AS existing_authority,
        CASE
            WHEN (( SELECT count(*) AS count
               FROM org_authority a
              WHERE (a.action_class = (g.raw ->> 'action_class'::text))) = 0) THEN 'NO AUTHORITY ROW - relies on fail-closed default'::text
            ELSE 'covered'::text
        END AS status
   FROM ops_kb_stage.hard_gates g;

CREATE OR REPLACE VIEW public.v_ops_supplier_corpus_link AS  SELECT d.department_key,
    d.name AS department_name,
    r.catalog_num,
    c.slug AS live_catalog_slug,
    c.name AS live_catalog_name,
    ( SELECT count(*) AS count
           FROM kb_operational_route_map m
          WHERE (m.catalog_num = r.catalog_num)) AS mapped_subcategories
   FROM ((ops_kb_stage.departments d
     CROSS JOIN kb_operational_route r)
     JOIN catalog_supplier_categories c ON ((c.num = r.catalog_num)))
  WHERE (d.department_key = ANY (ARRAY['rfq_intelligence'::text, 'marketplace_operations'::text, 'supplier_knowledge'::text, 'document_intelligence'::text]));

CREATE OR REPLACE VIEW public.v_org_chart AS  SELECT d.sort,
    d.dept_key,
    d.name AS department,
    d.lead_agent AS head_agent,
    a.agent_key,
    a.title,
    a.seniority,
    a.manager_key,
    a.role,
    a.responsibilities,
    a.active,
    (a.agent_key = d.lead_agent) AS is_head,
    ( SELECT count(*) AS count
           FROM org_agents r
          WHERE (r.manager_key = a.agent_key)) AS direct_reports,
    ( SELECT count(*) AS count
           FROM org_agents x
          WHERE (x.department = d.dept_key)) AS dept_headcount
   FROM (org_departments d
     LEFT JOIN org_agents a ON ((a.department = d.dept_key)))
  WHERE d.active;

CREATE OR REPLACE VIEW public.v_org_role_full AS  SELECT r.role_id,
    r.display_name,
    r.primary_department_id,
    d.name AS department_name,
    r.manager_role_id,
    m.display_name AS manager_name,
    r.runtime_mode,
    r.runtime_agent_key,
    r.authority_level,
    r.status,
    ( SELECT count(*) AS count
           FROM employee_kpi k
          WHERE ((k.agent_key = r.runtime_agent_key) AND k.active)) AS kpi_count,
    ( SELECT count(*) AS count
           FROM employee_knowledge k
          WHERE (k.agent_key = r.runtime_agent_key)) AS knowledge_count,
    ( SELECT count(*) AS count
           FROM employee_authority k
          WHERE (k.agent_key = r.runtime_agent_key)) AS authority_count,
    ( SELECT count(*) AS count
           FROM org_tasks t
          WHERE ((t.assigned_agent = r.runtime_agent_key) AND (t.status = ANY (ARRAY['assigned'::text, 'in_progress'::text])))) AS open_tasks,
    ( SELECT COALESCE(array_agg(c.committee_key ORDER BY c.committee_key), '{}'::text[]) AS "coalesce"
           FROM org_role_committee c
          WHERE (c.role_id = r.role_id)) AS committees
   FROM ((org_role r
     JOIN org_departments d ON ((d.dept_key = r.primary_department_id)))
     LEFT JOIN org_role m ON ((m.role_id = r.manager_role_id)));

CREATE OR REPLACE VIEW public.v_os_action_classification AS  SELECT classification,
    count(*) AS actions,
    string_agg(action, ', '::text ORDER BY action) AS action_list
   FROM control_mode_action
  GROUP BY classification;

CREATE OR REPLACE VIEW public.v_os_health AS  SELECT num,
    os_key,
    name,
    owner_agent,
    employees,
    open_tasks,
    round(((open_tasks)::numeric / (NULLIF(employees, 0))::numeric), 2) AS backlog_per_head,
    ( SELECT count(*) AS count
           FROM (org_tasks t
             JOIN os_department od ON ((od.dept_key = t.dept_key)))
          WHERE ((od.os_key = s.os_key) AND (t.status <> 'done'::text) AND (t.created_at < (now() - '14 days'::interval)))) AS stale_tasks,
    ( SELECT round(((100.0 * (count(*) FILTER (WHERE (rc.decision = 'approve'::text)))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS round
           FROM (review_chain rc
             JOIN os_department od ON ((od.dept_key = rc.dept_key)))
          WHERE (od.os_key = s.os_key)) AS review_pass_pct,
    ( SELECT count(*) AS count
           FROM risk_register r
          WHERE (EXISTS ( SELECT 1
                   FROM (os_department od
                     JOIN org_agents a ON ((a.department = od.dept_key)))
                  WHERE ((od.os_key = s.os_key) AND (a.agent_key = r.owner_agent))))) AS open_risks,
    ( SELECT count(*) AS count
           FROM (org_tasks t
             JOIN os_department od ON ((od.dept_key = t.dept_key)))
          WHERE ((od.os_key = s.os_key) AND (t.title ~~ 'KPI missed:%'::text) AND (t.status <> 'done'::text))) AS kpi_gaps,
    budget_aed,
    spent_aed,
    round(((100.0 * spent_aed) / NULLIF(budget_aed, (0)::numeric)), 1) AS budget_pct,
    ( SELECT round(((100.0 * (count(*) FILTER (WHERE t.needs_founder))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS round
           FROM (org_tasks t
             JOIN os_department od ON ((od.dept_key = t.dept_key)))
          WHERE ((od.os_key = s.os_key) AND (t.status <> 'done'::text))) AS needs_founder_pct
   FROM v_os_scoreboard s;

CREATE OR REPLACE VIEW public.v_os_scoreboard AS  SELECT o.num,
    o.os_key,
    o.name,
    o.owner_agent,
    count(DISTINCT od.dept_key) AS departments,
    count(DISTINCT a.agent_key) AS employees,
    count(DISTINCT t.id) FILTER (WHERE (t.status <> 'done'::text)) AS open_tasks,
    COALESCE(sum(DISTINCT b.monthly_aed), (0)::numeric) AS budget_aed,
    COALESCE(sum(DISTINCT b.spent_aed), (0)::numeric) AS spent_aed,
    count(DISTINCT k.id) FILTER (WHERE k.active) AS kpis,
    count(DISTINCT k.id) FILTER (WHERE (k.active AND (k.measure_sql IS NULL))) AS kpis_unmeasurable
   FROM (((((operating_system o
     LEFT JOIN os_department od ON ((od.os_key = o.os_key)))
     LEFT JOIN org_agents a ON (((a.department = od.dept_key) AND a.active)))
     LEFT JOIN org_tasks t ON ((t.dept_key = od.dept_key)))
     LEFT JOIN department_budget b ON ((b.dept_key = od.dept_key)))
     LEFT JOIN employee_kpi k ON ((k.agent_key = a.agent_key)))
  WHERE o.active
  GROUP BY o.num, o.os_key, o.name, o.owner_agent
  ORDER BY o.num;

CREATE OR REPLACE VIEW public.v_payment_health AS  SELECT ( SELECT count(*) AS count
           FROM transactions
          WHERE (transactions.revealed_at IS NOT NULL)) AS reveals_paid,
    ( SELECT COALESCE(sum(transactions.reveal_fee), (0)::numeric) AS "coalesce"
           FROM transactions
          WHERE (transactions.revealed_at IS NOT NULL)) AS reveal_revenue_aed,
    ( SELECT count(*) AS count
           FROM transactions
          WHERE ((transactions.refund_status IS NOT NULL) AND (transactions.refund_status <> 'none'::text))) AS refunds,
    ( SELECT count(*) AS count
           FROM payment_dispute) AS disputes_total,
    ( SELECT count(*) AS count
           FROM payment_dispute
          WHERE (payment_dispute.status = 'needs_response'::text)) AS disputes_open,
    ( SELECT count(*) AS count
           FROM payment_dispute
          WHERE ((payment_dispute.status = 'needs_response'::text) AND (payment_dispute.evidence_due_by < (now() + '3 days'::interval)))) AS disputes_due_soon,
    ( SELECT count(*) AS count
           FROM payment_dispute
          WHERE (payment_dispute.status = 'lost'::text)) AS disputes_lost,
        CASE
            WHEN (( SELECT count(*) AS count
               FROM transactions
              WHERE (transactions.revealed_at IS NOT NULL)) > 0) THEN round(((100.0 * (( SELECT count(*) AS count
               FROM payment_dispute))::numeric) / (( SELECT count(*) AS count
               FROM transactions
              WHERE (transactions.revealed_at IS NOT NULL)))::numeric), 2)
            ELSE NULL::numeric
        END AS dispute_rate_pct,
        CASE
            WHEN (( SELECT count(*) AS count
               FROM payment_dispute
              WHERE ((payment_dispute.status = 'needs_response'::text) AND (payment_dispute.evidence_due_by < now()))) > 0) THEN 'OVERDUE DISPUTE - evidence deadline passed, that money is lost'::text
            WHEN (( SELECT count(*) AS count
               FROM payment_dispute
              WHERE (payment_dispute.status = 'needs_response'::text)) > 0) THEN 'DISPUTE AWAITING RESPONSE'::text
            WHEN (( SELECT count(*) AS count
               FROM transactions
              WHERE (transactions.revealed_at IS NOT NULL)) = 0) THEN 'NO PAYMENTS YET - Stripe is live and has processed nothing'::text
            ELSE 'OK'::text
        END AS state;

CREATE OR REPLACE VIEW public.v_payment_reconciliation AS  SELECT started_at,
    status,
    counts,
    note
   FROM agent_runs r
  WHERE ((agent = 'stripe_webhook'::text) AND ((status = 'error'::text) OR (note ~~* '%PAID BUT NOT RECORDED%'::text)))
  ORDER BY started_at DESC;

CREATE OR REPLACE VIEW public.v_phase_c_event_binding_state AS  SELECT b.event_id,
    b.event_name,
    b.workflow_id,
    b.primary_consumer_role_id,
    b.connection_status AS structural_status_stored,
    ( SELECT s.status
           FROM fn_phase_c_event_binding_status(b.event_id) s(status, evidence)) AS structural_status_derived,
    (( SELECT s.status
           FROM fn_phase_c_event_binding_status(b.event_id) s(status, evidence)) IS DISTINCT FROM b.connection_status) AS structural_status_disagrees,
    r.observation AS runtime_observation,
    r.outbox_rows,
    r.delivered_rows,
    r.delivery_attempts,
    r.first_seen,
    r.last_seen
   FROM (phase_c_event_binding b
     CROSS JOIN LATERAL fn_phase_c_event_runtime_observation(b.event_id) r(observation, outbox_rows, delivered_rows, delivery_attempts, first_seen, last_seen));

CREATE OR REPLACE VIEW public.v_phase_c_object_terminal AS  SELECT 'founder_command'::text AS kind,
    (c.command_id)::text AS ref,
    c.state,
    COALESCE(s.terminal, false) AS is_terminal,
    (s.state IS NOT NULL) AS state_is_modelled,
    c.trace_id
   FROM (founder_command c
     LEFT JOIN phase_c_command_state s ON ((s.state = c.state)))
UNION ALL
 SELECT 'workflow_run'::text AS kind,
    (r.run_id)::text AS ref,
    r.state,
    (r.state = ANY (ARRAY['completed'::text, 'cancelled'::text, 'failed'::text, 'superseded'::text, 'expired'::text, 'rejected'::text])) AS is_terminal,
    true AS state_is_modelled,
    r.trace_id
   FROM phase_c_workflow_run r
UNION ALL
 SELECT 'step_run'::text AS kind,
    (sr.step_run_id)::text AS ref,
    sr.state,
    (sr.state = ANY (ARRAY['completed'::text, 'cancelled'::text, 'failed'::text, 'superseded'::text, 'skipped'::text])) AS is_terminal,
    true AS state_is_modelled,
    sr.trace_id
   FROM phase_c_workflow_step_run sr
UNION ALL
 SELECT 'task'::text AS kind,
    (t.task_id)::text AS ref,
    t.state,
    COALESCE(ts.terminal, false) AS is_terminal,
    (ts.state IS NOT NULL) AS state_is_modelled,
    t.trace_id
   FROM (phase_c_task t
     LEFT JOIN phase_c_task_state ts ON ((ts.state = t.state)))
UNION ALL
 SELECT 'handoff_run'::text AS kind,
    (h.handoff_run_id)::text AS ref,
    h.status AS state,
    (h.status = ANY (ARRAY['accepted'::text, 'rejected'::text, 'cancelled'::text, 'superseded'::text, 'returned'::text])) AS is_terminal,
    true AS state_is_modelled,
    h.trace_id
   FROM phase_c_handoff_run h;

CREATE OR REPLACE VIEW public.v_phase_c_trace_subject AS  SELECT trace_id,
    trace_policy_id,
    subject_kind,
    subject_ref,
    status,
    sealed_at,
    superseded_by,
    state_after,
    created_at,
    evidence_refs,
        CASE subject_kind
            WHEN 'command'::text THEN 'founder_command'::text
            WHEN 'founder_command'::text THEN 'founder_command'::text
            WHEN 'run'::text THEN 'workflow_run'::text
            WHEN 'workflow_run'::text THEN 'workflow_run'::text
            WHEN 'step'::text THEN 'step_run'::text
            WHEN 'step_run'::text THEN 'step_run'::text
            WHEN 'task'::text THEN 'task'::text
            WHEN 'handoff'::text THEN 'handoff_run'::text
            WHEN 'handoff_run'::text THEN 'handoff_run'::text
            ELSE 'unmapped'::text
        END AS nkind,
        CASE subject_kind
            WHEN 'command'::text THEN (command_id)::text
            WHEN 'founder_command'::text THEN (command_id)::text
            WHEN 'run'::text THEN (run_id)::text
            WHEN 'workflow_run'::text THEN (run_id)::text
            WHEN 'step'::text THEN (step_run_id)::text
            WHEN 'step_run'::text THEN (step_run_id)::text
            WHEN 'task'::text THEN (task_id)::text
            WHEN 'handoff'::text THEN subject_ref
            WHEN 'handoff_run'::text THEN subject_ref
            ELSE NULL::text
        END AS nref
   FROM phase_c_trace t;

CREATE OR REPLACE VIEW public.v_phase_c_what_reaches_the_founder AS  SELECT 'founder_approval_request'::text AS surface,
    'approval request the founder must decide'::text AS kind,
    count(*) AS rows_total,
    count(*) FILTER (WHERE (founder_approval_request.state = 'pending'::text)) AS awaiting_founder,
    count(*) FILTER (WHERE (founder_approval_request.action_class <> 'refund_decision'::text)) AS non_refund_rows
   FROM founder_approval_request
UNION ALL
 SELECT 'founder_release_approval'::text AS surface,
    'completed historical record; insert refused since Phase C'::text AS kind,
    count(*) AS rows_total,
    count(*) FILTER (WHERE (founder_release_approval.approved_at IS NULL)) AS awaiting_founder,
    count(*) AS non_refund_rows
   FROM founder_release_approval
UNION ALL
 SELECT 'procurement_approval_request'::text AS surface,
    'insert refused since Phase C'::text AS kind,
    count(*) AS rows_total,
    count(*) FILTER (WHERE (procurement_approval_request.status = 'pending'::text)) AS awaiting_founder,
    count(*) AS non_refund_rows
   FROM procurement_approval_request
UNION ALL
 SELECT 'org_action_executor.notifies_human'::text AS surface,
    'executor that messages a human — not an approval queue'::text AS kind,
    count(*) AS rows_total,
    (0)::bigint AS awaiting_founder,
    (0)::bigint AS non_refund_rows
   FROM org_action_executor
  WHERE (org_action_executor.notifies_human AND org_action_executor.active);

CREATE OR REPLACE VIEW public.v_pricing_consistency AS  WITH c AS (
         SELECT fn_supplier_subscription.fee,
            fn_supplier_subscription.currency,
            fn_supplier_subscription.period,
            fn_supplier_subscription.start_date,
            fn_supplier_subscription.free_limit,
            fn_supplier_subscription.fee_source,
            fn_supplier_subscription.start_source,
            fn_supplier_subscription.free_source
           FROM fn_supplier_subscription() fn_supplier_subscription(fee, currency, period, start_date, free_limit, fee_source, start_source, free_source)
        ), pc AS (
         SELECT pricing_config.id,
            pricing_config.promo_reveal_rate,
            pricing_config.promo_reveal_cap,
            pricing_config.standard_reveal_rate,
            pricing_config.standard_reveal_cap,
            pricing_config.promo_until,
            pricing_config.supplier_free_count,
            pricing_config.supplier_reg_fee,
            pricing_config.supplier_reg_period,
            pricing_config.refund_window_working_days,
            pricing_config.updated_at,
            pricing_config.auto_approve_suppliers,
            pricing_config.supplier_reg_currency,
            pricing_config.reveal_currency
           FROM pricing_config
          ORDER BY pricing_config.id
         LIMIT 1
        ), s AS (
         SELECT ( SELECT (NULLIF(app_secrets.value, ''::text))::numeric AS "nullif"
                   FROM app_secrets
                  WHERE (app_secrets.key = 'supplier_subscription_aed'::text)) AS fee,
            ( SELECT (NULLIF(app_secrets.value, ''::text))::date AS "nullif"
                   FROM app_secrets
                  WHERE (app_secrets.key = 'supplier_subscription_start'::text)) AS start_date,
            ( SELECT (NULLIF(app_secrets.value, ''::text))::integer AS "nullif"
                   FROM app_secrets
                  WHERE (app_secrets.key = 'founding_free_limit'::text)) AS free_limit
        )
 SELECT 'annual_fee'::text AS fact,
    ( SELECT (c.fee)::text AS fee
           FROM c) AS resolved,
    ( SELECT (pc.supplier_reg_fee)::text AS supplier_reg_fee
           FROM pc) AS pricing_config,
    ( SELECT (s.fee)::text AS fee
           FROM s) AS app_secrets,
    (NOT (( SELECT pc.supplier_reg_fee
           FROM pc) IS DISTINCT FROM COALESCE(( SELECT s.fee
           FROM s), ( SELECT pc.supplier_reg_fee
           FROM pc)))) AS agree
UNION ALL
 SELECT 'currency'::text AS fact,
    ( SELECT c.currency
           FROM c) AS resolved,
    ( SELECT pc.supplier_reg_currency
           FROM pc) AS pricing_config,
    NULL::text AS app_secrets,
    (( SELECT pc.supplier_reg_currency
           FROM pc) = 'AED'::text) AS agree
UNION ALL
 SELECT 'period'::text AS fact,
    ( SELECT c.period
           FROM c) AS resolved,
    ( SELECT pc.supplier_reg_period
           FROM pc) AS pricing_config,
    NULL::text AS app_secrets,
    (( SELECT pc.supplier_reg_period
           FROM pc) = 'yearly'::text) AS agree
UNION ALL
 SELECT 'billing_starts'::text AS fact,
    ( SELECT (c.start_date)::text AS start_date
           FROM c) AS resolved,
    NULL::text AS pricing_config,
    ( SELECT (s.start_date)::text AS start_date
           FROM s) AS app_secrets,
    (COALESCE(( SELECT s.start_date
           FROM s), '2027-08-01'::date) = '2027-08-01'::date) AS agree
UNION ALL
 SELECT 'free_registrations'::text AS fact,
    ( SELECT (c.free_limit)::text AS free_limit
           FROM c) AS resolved,
    ( SELECT (pc.supplier_free_count)::text AS supplier_free_count
           FROM pc) AS pricing_config,
    ( SELECT (s.free_limit)::text AS free_limit
           FROM s) AS app_secrets,
    (NOT (( SELECT pc.supplier_free_count
           FROM pc) IS DISTINCT FROM COALESCE(( SELECT s.free_limit
           FROM s), ( SELECT pc.supplier_free_count
           FROM pc)))) AS agree;

CREATE OR REPLACE VIEW public.v_pricing_knowledge_drift AS  SELECT id,
    agent_key,
    topic,
    updated_at,
    "left"(content, 200) AS starts_with
   FROM agent_knowledge
  WHERE (((content ~~* '%registration%'::text) OR (content ~~* '%subscription%'::text)) AND ((content ~~* '%AED 1,000/year%'::text) OR (content ~~* '%AED 1000/year%'::text) OR (content ~~* '%1,000 suppliers free%'::text) OR (content ~~* '%first 1000 suppliers FREE%'::text)) AND (content !~~ '%2027%'::text));

CREATE OR REPLACE VIEW public.v_refund_metrics AS  SELECT count(*) AS refunds_total,
    count(*) FILTER (WHERE (status = 'requested'::text)) AS awaiting_decision,
    count(*) FILTER (WHERE (status = 'approved'::text)) AS approved_not_settled,
    count(*) FILTER (WHERE (status = 'processing'::text)) AS processing,
    count(*) FILTER (WHERE (status = 'succeeded'::text)) AS settled,
    count(*) FILTER (WHERE (status = 'failed'::text)) AS failed,
    count(*) FILTER (WHERE (status = 'rejected'::text)) AS rejected,
    count(*) FILTER (WHERE (status = 'cancelled'::text)) AS cancelled,
    count(*) FILTER (WHERE within_auto_window) AS inside_auto_window,
    COALESCE(round((sum(amount_fils) FILTER (WHERE (status = 'succeeded'::text)) / 100.0), 2), (0)::numeric) AS refunded_aed,
    COALESCE(round((sum(amount_fils) FILTER (WHERE (status = 'processing'::text)) / 100.0), 2), (0)::numeric) AS in_flight_aed,
    count(*) FILTER (WHERE ((status = 'processing'::text) AND (created_at < (now() - '24:00:00'::interval)))) AS processing_over_24h,
    count(*) FILTER (WHERE ((status = 'succeeded'::text) AND (amount_fils IS NULL))) AS settled_amount_unknown,
    count(*) FILTER (WHERE (amount_fils IS NULL)) AS amount_unknown_total,
    ( SELECT COALESCE(round((sum(r2.amount_fils) / 100.0), 2), (0)::numeric) AS "coalesce"
           FROM refunds r2
          WHERE ((r2.status = 'succeeded'::text) AND (r2.settled_at > (now() - '30 days'::interval)))) AS refunded_aed_30d,
    ( SELECT count(*) AS count
           FROM refunds r3
          WHERE ((r3.status = 'succeeded'::text) AND (r3.settled_at > (now() - '30 days'::interval)) AND (r3.amount_fils IS NULL))) AS refunded_aed_30d_amount_unknown,
    ( SELECT count(*) AS count
           FROM v_refunds_unreconciled) AS unreconciled,
    ( SELECT count(*) AS count
           FROM refund_event_quarantine
          WHERE (refund_event_quarantine.resolved_at IS NULL)) AS quarantined_events,
    ( SELECT COALESCE(jsonb_object_agg(t.reason_code, t.c), '{}'::jsonb) AS "coalesce"
           FROM ( SELECT refunds_1.reason_code,
                    count(*) AS c
                   FROM refunds refunds_1
                  WHERE (refunds_1.status = 'succeeded'::text)
                  GROUP BY refunds_1.reason_code) t) AS by_reason,
    ((count(*) FILTER (WHERE (amount_fils IS NULL)) > 0) OR (( SELECT count(*) AS count
           FROM refund_event_quarantine
          WHERE (refund_event_quarantine.resolved_at IS NULL)) > 0) OR (count(*) FILTER (WHERE ((status = 'processing'::text) AND (created_at < (now() - '24:00:00'::interval)))) > 0)) AS needs_attention
   FROM refunds;

CREATE OR REPLACE VIEW public.v_refund_quarantine_open AS  SELECT id,
    stripe_refund_id,
    event_type,
    reason,
    created_at,
    (now() - created_at) AS waiting,
    payload
   FROM refund_event_quarantine
  WHERE (resolved_at IS NULL)
  ORDER BY created_at;

CREATE OR REPLACE VIEW public.v_refunds_unreconciled AS  SELECT id,
    settled_at,
    amount_fils,
        CASE
            WHEN (amount_fils IS NULL) THEN NULL::numeric
            ELSE round(((amount_fils)::numeric / 100.0), 2)
        END AS amount_aed,
    (amount_fils IS NULL) AS amount_unknown,
    amount_source,
    currency,
    reason_code,
    status,
    stripe_refund_id,
    stripe_payment_intent,
    inquiry_id,
    customer_id,
    decided_by,
    reconciliation_note,
        CASE
            WHEN (amount_fils IS NULL) THEN 'amount unknown - resolve before reconciling'::text
            WHEN (status = 'processing'::text) THEN 'stuck in processing - Stripe may already have paid it; confirm and settle'::text
            WHEN (settled_at IS NULL) THEN 'settled_at missing'::text
            ELSE 'awaiting reconciliation'::text
        END AS blocker
   FROM refunds r
  WHERE ((reconciled_at IS NULL) AND ((status = ANY (ARRAY['succeeded'::text, 'processing'::text])) OR (amount_fils IS NULL)))
  ORDER BY (amount_fils IS NULL) DESC, settled_at NULLS FIRST;

CREATE OR REPLACE VIEW public.v_resource_pressure AS  SELECT resource,
    kind,
    owner_dept,
    unit,
    capacity,
    committed,
        CASE
            WHEN (capacity > (0)::numeric) THEN round(((100.0 * committed) / capacity), 1)
            ELSE NULL::numeric
        END AS used_pct,
        CASE
            WHEN (capacity = (0)::numeric) THEN 'UNSET'::text
            WHEN (((100.0 * committed) / capacity) >= (halt_at_pct)::numeric) THEN 'HALT'::text
            WHEN (((100.0 * committed) / capacity) >= (degrade_at_pct)::numeric) THEN 'DEGRADE'::text
            ELSE 'OK'::text
        END AS state,
    note
   FROM resource_pool r;

CREATE OR REPLACE VIEW public.v_revenue_cascade_coverage AS  WITH d AS (
         SELECT a.packaged_department,
            a.dept_key
           FROM (org_department_alias a
             JOIN org_departments od ON (((od.dept_key = a.dept_key) AND od.active)))
          WHERE (NOT a.is_second_home)
        ), o AS (
         SELECT o_1.dept_key,
            count(*) FILTER (WHERE o_1.active) AS objectives,
            count(*) FILTER (WHERE (o_1.active AND (cg.key IS NOT NULL))) AS linked_to_a_goal,
            count(*) FILTER (WHERE (o_1.active AND (o_1.goal_key = 'revenue_annual'::text))) AS on_revenue_target,
            count(*) FILTER (WHERE (o_1.active AND (cg.key IS NOT NULL) AND (o_1.target_value IS NOT NULL) AND (COALESCE(o_1.measure_sql, ''::text) <> ''::text))) AS linked_and_measurable,
            count(*) FILTER (WHERE (o_1.active AND (o_1.actual_value IS NOT NULL))) AS measured
           FROM (department_objective o_1
             LEFT JOIN company_goals cg ON (((cg.key = o_1.goal_key) AND cg.active)))
          GROUP BY o_1.dept_key
        ), k AS (
         SELECT r.primary_department_id AS dept_key,
            count(*) FILTER (WHERE k_1.active) AS role_kpis,
            count(*) FILTER (WHERE (k_1.active AND (k_1.serves_goal = 'revenue_annual'::text))) AS kpis_on_revenue,
            count(*) FILTER (WHERE (k_1.active AND (k_1.actual_value IS NOT NULL))) AS kpis_measured
           FROM (employee_kpi k_1
             JOIN org_role r ON (((r.runtime_agent_key = k_1.agent_key) AND (r.status = 'active'::text))))
          GROUP BY r.primary_department_id
        )
 SELECT d.packaged_department,
    d.dept_key,
    COALESCE(o.objectives, (0)::bigint) AS objectives,
    COALESCE(o.linked_to_a_goal, (0)::bigint) AS objectives_linked_to_a_company_goal,
    COALESCE(o.on_revenue_target, (0)::bigint) AS objectives_on_the_revenue_target,
    COALESCE(o.linked_and_measurable, (0)::bigint) AS objectives_linked_and_measurable,
    COALESCE(o.measured, (0)::bigint) AS objectives_measured,
    COALESCE(k.role_kpis, (0)::bigint) AS role_kpis,
    COALESCE(k.kpis_on_revenue, (0)::bigint) AS role_kpis_on_the_revenue_target,
    COALESCE(k.kpis_measured, (0)::bigint) AS role_kpis_measured,
        CASE
            WHEN (COALESCE(o.linked_and_measurable, (0)::bigint) > 0) THEN 'reconciled_and_measurable'::text
            WHEN (COALESCE(o.linked_to_a_goal, (0)::bigint) > 0) THEN 'reconciled_not_measurable'::text
            WHEN (COALESCE(o.objectives, (0)::bigint) > 0) THEN 'objectives_but_none_linked_to_a_company_goal'::text
            ELSE 'no_objective_at_all'::text
        END AS reconciliation_status,
    ((COALESCE(o.on_revenue_target, (0)::bigint) > 0) OR (COALESCE(k.kpis_on_revenue, (0)::bigint) > 0)) AS reaches_the_revenue_target
   FROM ((d
     LEFT JOIN o ON ((o.dept_key = d.dept_key)))
     LEFT JOIN k ON ((k.dept_key = d.dept_key)));

CREATE OR REPLACE VIEW public.v_role_identity_collision AS  WITH agg AS (
         SELECT i.agent_key,
            count(*) AS roles_served,
            array_agg(i.packaged_role_id ORDER BY i.packaged_role_id) AS roles,
            array_agg(DISTINCT i.archetype ORDER BY i.archetype) AS archetypes,
            array_agg(DISTINCT i.packaged_department ORDER BY i.packaged_department) AS packaged_departments,
            count(DISTINCT fn_archetype_tier(i.archetype)) AS tiers_spanned
           FROM org_role_identity i
          GROUP BY i.agent_key
         HAVING (count(*) > 1)
        )
 SELECT a.agent_key,
    a.roles_served,
    a.roles,
    a.archetypes,
    a.packaged_departments,
    ag.department AS runtime_department,
    ag.seniority AS runtime_seniority,
    ag.active AS agent_active,
    ( SELECT array_agg(d.dept_key ORDER BY d.dept_key) AS array_agg
           FROM org_departments d
          WHERE (d.lead_agent = a.agent_key)) AS leads_departments,
    (a.tiers_spanned > 1) AS spans_seniority_tiers,
    (('reviewer-auditor'::text = ANY (a.archetypes)) AND (('director'::text = ANY (a.archetypes)) OR ('operations-specialist'::text = ANY (a.archetypes)) OR ('analyst-controller'::text = ANY (a.archetypes)))) AS creator_reviewer_conflict,
    (('director'::text = ANY (a.archetypes)) AND (('operations-specialist'::text = ANY (a.archetypes)) OR ('analyst-controller'::text = ANY (a.archetypes)))) AS manager_subordinate_conflict,
        CASE
            WHEN ('reviewer-auditor'::text = ANY (a.archetypes)) THEN 'split'::text
            WHEN (('director'::text = ANY (a.archetypes)) AND (('operations-specialist'::text = ANY (a.archetypes)) OR ('analyst-controller'::text = ANY (a.archetypes)))) THEN 'split'::text
            ELSE 'isolate'::text
        END AS required_verdict,
    ( SELECT array_agg(DISTINCT d2.resolution ORDER BY d2.resolution) AS array_agg
           FROM role_isolation_decision d2
          WHERE (d2.agent_key = a.agent_key)) AS recorded_resolutions,
    ( SELECT count(*) AS count
           FROM org_role_identity i2
          WHERE ((i2.agent_key = a.agent_key) AND (NOT (EXISTS ( SELECT 1
                   FROM role_isolation_decision d3
                  WHERE ((d3.agent_key = i2.agent_key) AND (d3.packaged_role_id = i2.packaged_role_id))))))) AS roles_without_decision
   FROM (agg a
     JOIN org_agents ag ON ((ag.agent_key = a.agent_key)));

CREATE OR REPLACE VIEW public.v_scenario_expectation_changes_reportable AS  SELECT scenario_id,
    original_expected,
    new_expected,
    reason,
    work_item,
    changed_by,
    changed_at
   FROM v_scenario_expectation_ledger
  WHERE (effective_kind = 'change'::text)
  ORDER BY changed_at DESC;

CREATE OR REPLACE VIEW public.v_scenario_expectation_current AS  SELECT b.scenario_id,
    b.expected AS original_expected,
    COALESCE(c.new_expected, b.expected) AS current_expected,
    (c.id IS NOT NULL) AS revised,
    c.reason,
    c.work_item,
    c.changed_by,
    c.changed_at
   FROM (scenario_expectation_baseline b
     LEFT JOIN LATERAL ( SELECT ch.id,
            ch.scenario_id,
            ch.original_expected,
            ch.new_expected,
            ch.reason,
            ch.work_item,
            ch.changed_by,
            ch.changed_at
           FROM scenario_expectation_change ch
          WHERE (ch.scenario_id = b.scenario_id)
          ORDER BY ch.changed_at DESC, ch.id DESC
         LIMIT 1) c ON (true));

CREATE OR REPLACE VIEW public.v_scenario_expectation_drift AS  SELECT s.scenario_id,
    b.expected AS baseline_expected,
    s.expected AS live_expected
   FROM (kb_stage.scenario_tests s
     JOIN scenario_expectation_baseline b ON ((b.scenario_id = s.scenario_id)))
  WHERE ((COALESCE(s.expected, ''::text) IS DISTINCT FROM COALESCE(b.expected, ''::text)) AND (NOT (EXISTS ( SELECT 1
           FROM scenario_expectation_change c
          WHERE ((c.scenario_id = s.scenario_id) AND (c.new_expected = COALESCE(s.expected, ''::text)))))));

CREATE OR REPLACE VIEW public.v_scenario_expectation_ledger AS  SELECT c.id,
    c.scenario_id,
    c.original_expected,
    c.new_expected,
    c.reason,
    c.work_item,
    c.changed_by,
    c.changed_at,
    c.entry_kind,
    COALESCE(a.kind, c.entry_kind) AS effective_kind,
    a.reason AS annotation_reason,
    a.annotated_by,
    a.annotated_at
   FROM (scenario_expectation_change c
     LEFT JOIN LATERAL ( SELECT an.id,
            an.change_id,
            an.kind,
            an.reason,
            an.annotated_by,
            an.annotated_at
           FROM scenario_expectation_annotation an
          WHERE (an.change_id = c.id)
          ORDER BY an.annotated_at DESC, an.id DESC
         LIMIT 1) a ON (true));

CREATE OR REPLACE VIEW public.v_scope_disposition_effective AS  SELECT d.group_id,
    d.trade_key,
    d.scope_component,
    max(d.specificity) AS specificity,
        CASE
            WHEN (count(DISTINCT d.disposition) FILTER (WHERE (d.specificity = mx.mx_spec)) > 1) THEN 'conflicted'::text
            ELSE min(d.disposition) FILTER (WHERE (d.specificity = mx.mx_spec))
        END AS disposition,
    count(DISTINCT d.disposition) FILTER (WHERE (d.specificity = mx.mx_spec)) AS competing_dispositions,
    min(d.reason) FILTER (WHERE (d.specificity = mx.mx_spec)) AS reason,
    array_agg(DISTINCT d.clause_index) FILTER (WHERE (d.specificity = mx.mx_spec)) AS clause_indexes
   FROM (inquiry_scope_disposition d
     JOIN LATERAL ( SELECT max(d2.specificity) AS mx_spec
           FROM inquiry_scope_disposition d2
          WHERE ((d2.group_id = d.group_id) AND (NOT (d2.trade_key IS DISTINCT FROM d.trade_key)) AND (d2.scope_component = d.scope_component))) mx ON (true))
  WHERE (d.specificity = mx.mx_spec)
  GROUP BY d.group_id, d.trade_key, d.scope_component, mx.mx_spec;

CREATE OR REPLACE VIEW public.v_slow_queries AS  SELECT queryid,
    calls,
    round((total_exec_time)::numeric, 1) AS total_ms,
    round((mean_exec_time)::numeric, 2) AS mean_ms,
    round((max_exec_time)::numeric, 2) AS max_ms,
    rows,
    "left"(query, 240) AS query
   FROM extensions.pg_stat_statements
  WHERE (calls > 1)
  ORDER BY mean_exec_time DESC
 LIMIT 50;

CREATE OR REPLACE VIEW public.v_storage_bucket_policy AS  SELECT id AS bucket,
    public,
    file_size_limit,
    round(((file_size_limit)::numeric / 1048576.0), 1) AS size_limit_mb,
    COALESCE(array_length(allowed_mime_types, 1), 0) AS allowed_types,
    allowed_mime_types,
    (allowed_mime_types IS NULL) AS accepts_anything,
    ((file_size_limit IS NULL) OR (file_size_limit > 104857600)) AS size_limit_ineffective,
    ( SELECT count(*) AS count
           FROM storage.objects o
          WHERE (o.bucket_id = b.id)) AS objects
   FROM storage.buckets b;

CREATE OR REPLACE VIEW public.v_supplier_alignment AS  SELECT l.id AS lead_id,
    l.company_name,
    l.email,
    l.emirate,
    ls.sub_slug,
    cs.name AS subcategory_name,
    ls.domain_slug,
    cd.name AS domain_name,
    ls.is_primary,
    ls.score,
    m.agent_slug,
    m.confidence AS mapping_confidence,
    (ca.slug IS NOT NULL) AS agent_exists,
    ((ak.modules IS NOT NULL) AND (ak.modules > 0)) AS agent_has_knowledge,
    COALESCE(ak.modules, (0)::bigint) AS knowledge_modules
   FROM ((((((leads l
     JOIN lead_subcategory ls ON ((ls.lead_id = l.id)))
     JOIN catalog_subcategories cs ON ((cs.slug = ls.sub_slug)))
     JOIN catalog_domains cd ON ((cd.slug = ls.domain_slug)))
     LEFT JOIN subcategory_agent_map m ON ((m.sub_slug = ls.sub_slug)))
     LEFT JOIN category_agents ca ON (((ca.slug = m.agent_slug) AND (ca.folded_into IS NULL))))
     LEFT JOIN ( SELECT replace(agent_knowledge.agent_key, 'cat:'::text, ''::text) AS slug,
            count(*) AS modules
           FROM agent_knowledge
          WHERE (agent_knowledge.agent_key ~~ 'cat:%'::text)
          GROUP BY (replace(agent_knowledge.agent_key, 'cat:'::text, ''::text))) ak ON ((ak.slug = m.agent_slug)));

CREATE OR REPLACE VIEW public.v_supplier_billing AS  WITH cfg AS (
         SELECT s_1.start_date,
            s_1.fee,
            s_1.free_limit,
            COALESCE(( SELECT (lower(a.value) = 'true'::text)
                   FROM app_secrets a
                  WHERE (a.key = 'subscription_honour_12m'::text)), false) AS honour_12m
           FROM fn_supplier_subscription() s_1(fee, currency, period, start_date, free_limit, fee_source, start_source, free_source)
        ), s AS (
         SELECT l.id AS supplier_id,
            l.company_name,
            l.claimed_by AS email,
            l.founding_rank,
            l.subscription_exempt,
            l.subscription_paid_until,
            l.banned,
            l.matching_blocked,
            (COALESCE(l.registration_submitted_at, l.approved_at, l.created_at))::date AS registered_on,
            c.start_date,
            c.fee,
            c.free_limit,
            c.honour_12m
           FROM (leads l
             CROSS JOIN cfg c)
          WHERE ((COALESCE(l.claimed, false) = true) AND (l.approval_status = 'approved'::text))
        )
 SELECT supplier_id,
    company_name,
    email,
    founding_rank,
    subscription_exempt,
    registered_on,
    subscription_paid_until,
        CASE
            WHEN honour_12m THEN GREATEST(start_date, ((registered_on + '1 year'::interval))::date)
            ELSE start_date
        END AS billing_starts_on,
        CASE
            WHEN subscription_exempt THEN 'exempt'::text
            WHEN (CURRENT_DATE <
            CASE
                WHEN honour_12m THEN GREATEST(start_date, ((registered_on + '1 year'::interval))::date)
                ELSE start_date
            END) THEN 'not_due'::text
            WHEN ((subscription_paid_until IS NOT NULL) AND (subscription_paid_until >= CURRENT_DATE)) THEN 'active'::text
            WHEN (subscription_paid_until IS NULL) THEN 'due'::text
            ELSE 'past_due'::text
        END AS billing_status,
        CASE
            WHEN subscription_exempt THEN (0)::numeric
            WHEN (CURRENT_DATE <
            CASE
                WHEN honour_12m THEN GREATEST(start_date, ((registered_on + '1 year'::interval))::date)
                ELSE start_date
            END) THEN (0)::numeric
            WHEN ((subscription_paid_until IS NOT NULL) AND (subscription_paid_until >= CURRENT_DATE)) THEN (0)::numeric
            ELSE fee
        END AS amount_due_aed,
    fee AS annual_fee_aed,
    free_limit
   FROM s;

CREATE OR REPLACE VIEW public.v_supplier_coi AS  WITH sup AS (
         SELECT leads.id,
            leads.company_name,
            NULLIF(regexp_replace(COALESCE(leads.phone, ''::text), '\D'::text, ''::text, 'g'::text), ''::text) AS ph,
            NULLIF(regexp_replace(COALESCE(leads.whatsapp, ''::text), '\D'::text, ''::text, 'g'::text), ''::text) AS wa,
            lower(NULLIF(leads.email, ''::text)) AS em,
            NULLIF(leads.trn, ''::text) AS trn,
            NULLIF(leads.trade_license_no, ''::text) AS lic
           FROM leads
          WHERE (leads.claimed = true)
        ), ids AS (
         SELECT sup.id,
            sup.company_name,
            'phone'::text AS k,
            sup.ph AS v
           FROM sup
          WHERE ((sup.ph IS NOT NULL) AND (length(sup.ph) >= 7))
        UNION ALL
         SELECT sup.id,
            sup.company_name,
            'whatsapp'::text,
            sup.wa
           FROM sup
          WHERE ((sup.wa IS NOT NULL) AND (length(sup.wa) >= 7))
        UNION ALL
         SELECT sup.id,
            sup.company_name,
            'email'::text,
            sup.em
           FROM sup
          WHERE (sup.em IS NOT NULL)
        UNION ALL
         SELECT sup.id,
            sup.company_name,
            'trn'::text,
            sup.trn
           FROM sup
          WHERE (sup.trn IS NOT NULL)
        UNION ALL
         SELECT sup.id,
            sup.company_name,
            'license'::text,
            sup.lic
           FROM sup
          WHERE (sup.lic IS NOT NULL)
        )
 SELECT k AS shared_field,
    v AS shared_value,
    count(DISTINCT id) AS supplier_count,
    array_agg(DISTINCT id) AS supplier_ids,
    array_agg(DISTINCT company_name) AS companies
   FROM ids
  GROUP BY k, v
 HAVING (count(DISTINCT id) > 1)
  ORDER BY (count(DISTINCT id)) DESC, k;

CREATE OR REPLACE VIEW public.v_supplier_doc_score AS  WITH docs AS (
         SELECT (d.ref_id)::bigint AS lead_id,
            bool_or((d.kind = 'licence'::text)) AS doc_licence,
            bool_or((d.kind = 'catalog'::text)) AS doc_catalog,
            bool_or((d.kind = 'profile'::text)) AS doc_profile,
            (count(*))::integer AS doc_rows
           FROM documents d
          WHERE ((d.ref_table = 'leads'::text) AND (d.ref_id ~ '^[0-9]+$'::text))
          GROUP BY (d.ref_id)::bigint
        ), f AS (
         SELECT l.id AS lead_id,
            l.company_name,
            COALESCE(NULLIF(btrim(l.claimed_by), ''::text), NULLIF(btrim(l.email), ''::text)) AS contact_email,
            l.approval_status,
            COALESCE(l.claimed, false) AS claimed,
            COALESCE(l.banned, false) AS banned,
            l.lifecycle_stage,
            cc.name AS primary_category,
            COALESCE(dd.doc_rows, 0) AS extracted_doc_rows,
            ((COALESCE(btrim(l.license_doc_path), ''::text) <> ''::text) OR COALESCE(dd.doc_licence, false)) AS has_licence,
            ((l.license_expiry IS NOT NULL) AND (l.license_expiry < CURRENT_DATE)) AS licence_expired,
            l.license_expiry,
            (COALESCE(btrim(l.egr_doc_path), ''::text) <> ''::text) AS has_egr,
            (COALESCE(btrim(l.iban_doc_path), ''::text) <> ''::text) AS has_iban,
            (COALESCE(btrim(l.vat_doc_path), ''::text) <> ''::text) AS has_vat_doc,
            ((COALESCE(btrim(l.trn), ''::text) <> ''::text) OR (COALESCE(btrim(l.vat_number), ''::text) <> ''::text)) AS has_vat_no,
            (COALESCE(btrim(l.insurance_doc_path), ''::text) <> ''::text) AS has_insurance,
            ((l.insurance_expiry IS NOT NULL) AND (l.insurance_expiry < CURRENT_DATE)) AS insurance_expired,
            l.insurance_expiry,
            ((COALESCE(btrim(l.company_profile_doc_path), ''::text) <> ''::text) OR COALESCE(dd.doc_profile, false)) AS has_profile,
            ((COALESCE(array_length(l.catalog_doc_paths, 1), 0) > 0) OR COALESCE(dd.doc_catalog, false)) AS has_catalogue,
            (COALESCE(btrim(l.iso_doc_path), ''::text) <> ''::text) AS has_iso,
            ((l.iso_expiry IS NOT NULL) AND (l.iso_expiry < CURRENT_DATE)) AS iso_expired,
            (COALESCE(btrim(l.manufacturer_auth_doc_path), ''::text) <> ''::text) AS has_mfa,
            ((l.manufacturer_auth_expiry IS NOT NULL) AND (l.manufacturer_auth_expiry < CURRENT_DATE)) AS mfa_expired,
            (COALESCE(btrim(l.signed_terms_path), ''::text) <> ''::text) AS has_signed_terms
           FROM (((leads l
             LEFT JOIN docs dd ON ((dd.lead_id = l.id)))
             LEFT JOIN lead_category lc ON (((lc.lead_id = l.id) AND lc.is_primary)))
             LEFT JOIN catalog_supplier_categories cc ON ((cc.slug = lc.slug)))
        ), s AS (
         SELECT f.lead_id,
            f.company_name,
            f.contact_email,
            f.approval_status,
            f.claimed,
            f.banned,
            f.lifecycle_stage,
            f.primary_category,
            f.extracted_doc_rows,
            f.has_licence,
            f.licence_expired,
            f.license_expiry,
            f.has_egr,
            f.has_iban,
            f.has_vat_doc,
            f.has_vat_no,
            f.has_insurance,
            f.insurance_expired,
            f.insurance_expiry,
            f.has_profile,
            f.has_catalogue,
            f.has_iso,
            f.iso_expired,
            f.has_mfa,
            f.mfa_expired,
            f.has_signed_terms,
            ((((((((
                CASE
                    WHEN (f.has_licence AND (NOT f.licence_expired)) THEN 30
                    ELSE 0
                END +
                CASE
                    WHEN f.has_egr THEN 12
                    ELSE 0
                END) +
                CASE
                    WHEN f.has_iban THEN 10
                    ELSE 0
                END) +
                CASE
                    WHEN f.has_vat_doc THEN 10
                    WHEN f.has_vat_no THEN 5
                    ELSE 0
                END) +
                CASE
                    WHEN (f.has_insurance AND (NOT f.insurance_expired)) THEN 10
                    ELSE 0
                END) +
                CASE
                    WHEN f.has_profile THEN 10
                    ELSE 0
                END) +
                CASE
                    WHEN f.has_catalogue THEN 10
                    ELSE 0
                END) +
                CASE
                    WHEN (f.has_iso AND (NOT f.iso_expired)) THEN 5
                    ELSE 0
                END) +
                CASE
                    WHEN (f.has_mfa AND (NOT f.mfa_expired)) THEN 3
                    ELSE 0
                END) AS score,
            array_remove(ARRAY[
                CASE
                    WHEN (NOT f.has_licence) THEN 'Trade licence (mandatory)'::text
                    WHEN f.licence_expired THEN ('Trade licence EXPIRED on '::text || (f.license_expiry)::text)
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_egr) THEN 'Establishment card'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_iban) THEN 'Bank IBAN letter'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((NOT f.has_vat_doc) AND (NOT f.has_vat_no)) THEN 'VAT certificate / TRN'::text
                    WHEN (NOT f.has_vat_doc) THEN 'VAT certificate (TRN on file, document missing)'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_insurance) THEN 'Insurance certificate'::text
                    WHEN f.insurance_expired THEN ('Insurance certificate EXPIRED on '::text || (f.insurance_expiry)::text)
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_profile) THEN 'Company profile'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_catalogue) THEN 'Product catalogue'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_iso) THEN 'ISO certificate'::text
                    WHEN f.iso_expired THEN 'ISO certificate EXPIRED'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_mfa) THEN 'Manufacturer authorisation'::text
                    WHEN f.mfa_expired THEN 'Manufacturer authorisation EXPIRED'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_signed_terms) THEN 'Signed Terms & Conditions'::text
                    ELSE NULL::text
                END], NULL::text) AS missing
           FROM f
        )
 SELECT lead_id,
    company_name,
    contact_email,
    primary_category,
    approval_status,
    claimed,
    banned,
    lifecycle_stage,
    score,
        CASE
            WHEN (score >= 85) THEN 'A'::text
            WHEN (score >= 70) THEN 'B'::text
            WHEN (score >= 50) THEN 'C'::text
            WHEN (score >= 25) THEN 'D'::text
            ELSE 'F'::text
        END AS grade,
    cardinality(missing) AS missing_count,
    missing,
    has_licence,
    licence_expired,
    has_egr,
    has_iban,
    has_vat_doc,
    has_vat_no,
    has_insurance,
    insurance_expired,
    has_profile,
    has_catalogue,
    has_iso,
    has_mfa,
    has_signed_terms,
    extracted_doc_rows
   FROM s;

CREATE OR REPLACE VIEW public.v_supplier_exception_board AS  SELECT id,
    company_name,
    approval_status,
    licence_gate_reason,
    exception_opened_at,
    exception_due_at,
    exception_reminders,
    exception_last_reminder_at,
    GREATEST(0, (EXTRACT(day FROM (exception_due_at - now())))::integer) AS days_remaining,
    (exception_due_at <= now()) AS overdue,
        CASE
            WHEN (exception_due_at <= now()) THEN 'auto-reject is due'::text
            WHEN (EXTRACT(day FROM (exception_due_at - now())) <= (2)::numeric) THEN 'final days'::text
            ELSE 'in window'::text
        END AS urgency
   FROM leads l
  WHERE ((COALESCE(approval_status, ''::text) = 'action_required'::text) AND (exception_opened_at IS NOT NULL) AND (exception_closed_at IS NULL))
  ORDER BY exception_due_at;

CREATE OR REPLACE VIEW public.v_supplier_exception_health AS  SELECT ( SELECT count(*) AS count
           FROM v_supplier_exception_queue) AS open_now,
    ( SELECT count(*) AS count
           FROM v_supplier_exception_queue
          WHERE (v_supplier_exception_queue.urgency = 'overdue'::text)) AS overdue,
    ( SELECT count(*) AS count
           FROM v_supplier_exception_queue
          WHERE (v_supplier_exception_queue.urgency = 'closing_soon'::text)) AS closing_within_3_days,
    ( SELECT count(*) AS count
           FROM leads
          WHERE (leads.exception_outcome = 'expired_auto_rejected'::text)) AS auto_rejected_total,
    ( SELECT count(*) AS count
           FROM leads
          WHERE (leads.exception_outcome = 'resolved'::text)) AS self_resolved_total,
    ( SELECT count(*) AS count
           FROM leads
          WHERE (leads.registration_submitted_at IS NOT NULL)) AS registrations_total,
    ( SELECT fn_supplier_exception_days() AS fn_supplier_exception_days) AS window_days;

CREATE OR REPLACE VIEW public.v_supplier_exception_outcomes AS  SELECT COALESCE(exception_outcome, '(open or never opened)'::text) AS outcome,
    count(*) AS suppliers
   FROM leads
  WHERE (exception_opened_at IS NOT NULL)
  GROUP BY COALESCE(exception_outcome, '(open or never opened)'::text)
  ORDER BY (count(*)) DESC;

CREATE OR REPLACE VIEW public.v_supplier_exception_queue AS  SELECT id,
    company_name,
    claimed_by AS supplier_email,
    emirate,
    licence_gate_reason AS reason,
    exception_opened_at,
    exception_due_at,
    GREATEST(0, (EXTRACT(day FROM (exception_due_at - now())))::integer) AS days_remaining,
    exception_reminders AS reminders_sent,
        CASE
            WHEN (exception_due_at <= now()) THEN 'overdue'::text
            WHEN (exception_due_at <= (now() + '3 days'::interval)) THEN 'closing_soon'::text
            ELSE 'open'::text
        END AS urgency
   FROM leads l
  WHERE ((approval_status = 'action_required'::text) AND (exception_closed_at IS NULL))
  ORDER BY exception_due_at NULLS FIRST;

CREATE OR REPLACE VIEW public.v_supplier_intelligence AS  SELECT l.id AS lead_id,
    l.company_name,
    l.emirate,
    l.verified,
    l.approval_status,
    s.reliability,
    s.response_rate,
    s.quotes_submitted,
    s.quotes_won,
    s.rejection_count,
    s.price_index,
    s.quality_rating,
        CASE
            WHEN (NOT l.verified) THEN 'UNVERIFIED - must not receive an RFQ'::text
            WHEN (COALESCE(s.quotes_submitted, 0) = 0) THEN 'UNPROVEN - never quoted'::text
            WHEN (COALESCE(s.response_rate, (0)::numeric) < (30)::numeric) THEN 'SLOW RESPONDER - reveals here are refund risk'::text
            WHEN (COALESCE(s.rejection_count, 0) >= 5) THEN 'FREQUENTLY REJECTED - check scope fit before fanning out'::text
            WHEN (COALESCE(s.reliability, (0)::numeric) >= (75)::numeric) THEN 'RELIABLE - safe to prioritise'::text
            ELSE 'AVERAGE'::text
        END AS verdict,
    s.last_active,
    s.computed_at
   FROM (leads l
     LEFT JOIN supplier_score s ON ((s.lead_id = l.id)));

CREATE OR REPLACE VIEW public.v_supplier_load AS  SELECT l.id AS supplier_id,
    l.company_name,
    count(DISTINCT im.inquiry_id) FILTER (WHERE ((i.completed_at IS NULL) AND (COALESCE(i.status, ''::text) <> 'cancelled'::text))) AS active_matched,
    count(DISTINCT im.inquiry_id) AS total_matched,
    sh.response AS response_rate,
    sh.risk_tier,
    ((count(DISTINCT im.inquiry_id) FILTER (WHERE ((i.completed_at IS NULL) AND (COALESCE(i.status, ''::text) <> 'cancelled'::text))) >= 10) AND (COALESCE(sh.response, (100)::numeric) < (50)::numeric)) AS overloaded
   FROM (((leads l
     JOIN inquiry_matches im ON ((im.supplier_id = l.id)))
     LEFT JOIN inquiries i ON ((i.id = im.inquiry_id)))
     LEFT JOIN supplier_health sh ON ((sh.supplier_id = l.id)))
  WHERE (l.claimed = true)
  GROUP BY l.id, l.company_name, sh.response, sh.risk_tier
  ORDER BY (count(DISTINCT im.inquiry_id) FILTER (WHERE ((i.completed_at IS NULL) AND (COALESCE(i.status, ''::text) <> 'cancelled'::text)))) DESC;

CREATE OR REPLACE VIEW public.v_supplier_match_exclusions AS  SELECT id,
    company_name,
    approval_status,
    licence_gate_reason,
    exception_due_at,
    GREATEST(0, (EXTRACT(day FROM (exception_due_at - now())))::integer) AS days_remaining
   FROM leads l
  WHERE (COALESCE(approval_status, ''::text) = ANY (ARRAY['action_required'::text, 'rejected'::text]));

CREATE OR REPLACE VIEW public.v_supplier_pricing AS  SELECT supplier_reg_fee AS annual_fee,
    supplier_reg_currency AS currency,
    supplier_reg_period AS period,
    supplier_free_count AS free_registrations,
    registered_supplier_count() AS ranked_suppliers,
    GREATEST(0, (supplier_free_count - registered_supplier_count())) AS free_slots_remaining,
    supplier_charging_starts AS charging_starts,
    standard_reveal_rate AS reveal_rate,
    reveal_currency,
    (((((((((('Free until '::text || to_char(((supplier_charging_starts - 1))::timestamp with time zone, 'FMDD FMMonth YYYY'::text)) || '. From '::text) || to_char((supplier_charging_starts)::timestamp with time zone, 'FMDD FMMonth YYYY'::text)) || ': '::text) || supplier_reg_currency) || ' '::text) || TRIM(BOTH FROM to_char(supplier_reg_fee, '999G999'::text))) || '/year. The first '::text) || supplier_free_count) || ' registered suppliers are permanently exempt. No commission, ever.'::text) AS published_statement
   FROM pricing_config p
  WHERE (id = 1);

CREATE OR REPLACE VIEW public.v_supply_gap AS  WITH pool AS (
         SELECT c.slug,
            c.name,
            c.num,
            count(DISTINCT lc.lead_id) FILTER (WHERE ((l.email IS NOT NULL) AND (l.email <> ''::text) AND (COALESCE(l.banned, false) = false))) AS sendable,
            count(DISTINCT lc.lead_id) FILTER (WHERE (l.invite_status IS NOT NULL)) AS invited,
            count(DISTINCT lc.lead_id) FILTER (WHERE l.claimed) AS claimed,
            count(DISTINCT lc.lead_id) FILTER (WHERE (l.approval_status = 'approved'::text)) AS approved
           FROM ((catalog_supplier_categories c
             LEFT JOIN lead_category lc ON ((lc.slug = c.slug)))
             LEFT JOIN leads l ON ((l.id = lc.lead_id)))
          GROUP BY c.slug, c.name, c.num
        )
 SELECT slug,
    name,
    num,
    sendable,
    invited,
    claimed,
    approved,
    GREATEST((0)::bigint, (10 - approved)) AS gap_to_target,
    (ceil(((GREATEST((0)::bigint, (10 - approved)))::numeric / 0.05)))::integer AS sendable_needed_at_5pct,
    GREATEST((0)::bigint, ((ceil(((GREATEST((0)::bigint, (10 - approved)))::numeric / 0.05)))::integer - sendable)) AS sendable_shortfall,
        CASE
            WHEN (approved >= 10) THEN 'TARGET MET'::text
            WHEN (sendable = 0) THEN 'NO POOL - must source from scratch'::text
            WHEN (sendable < (ceil(((GREATEST((0)::bigint, (10 - approved)))::numeric / 0.05)))::integer) THEN 'POOL TOO THIN - scrape more'::text
            WHEN (invited = 0) THEN 'READY - not yet invited'::text
            ELSE 'IN PROGRESS'::text
        END AS status
   FROM pool;

CREATE OR REPLACE VIEW public.v_test_matrix AS  SELECT agent AS suite,
    count(*) AS runs_14d,
    count(*) FILTER (WHERE (status = 'ok'::text)) AS passed,
    count(*) FILTER (WHERE (status = 'error'::text)) AS failed,
    round(((100.0 * (count(*) FILTER (WHERE (status = 'ok'::text)))::numeric) / (GREATEST(count(*), (1)::bigint))::numeric)) AS pass_pct,
    max(started_at) AS last_run,
        CASE
            WHEN (count(*) FILTER (WHERE (status = 'error'::text)) = 0) THEN 'PASS'::text
            WHEN (count(*) FILTER (WHERE (status = 'ok'::text)) = 0) THEN 'FAIL'::text
            ELSE 'FLAKY'::text
        END AS verdict
   FROM agent_runs r
  WHERE ((started_at > (now() - '14 days'::interval)) AND ((agent ~~* '%test%'::text) OR (agent ~~* '%eval%'::text) OR (agent ~~* '%qa%'::text) OR (agent ~~* '%exam%'::text) OR (agent ~~* '%smoke%'::text) OR (agent ~~* '%drill%'::text) OR (agent ~~* '%canary%'::text) OR (agent ~~* '%health%'::text)))
  GROUP BY agent;

CREATE OR REPLACE VIEW public.v_tool_calls_never_returning AS  SELECT t.tool_id,
    t.kind,
    t.failure_behaviour,
    count(c.id) FILTER (WHERE (c.created_at > (now() - '7 days'::interval))) AS calls_7d,
    count(c.id) FILTER (WHERE ((c.status = 'ok'::text) AND (c.created_at > (now() - '7 days'::interval)))) AS ok_7d,
    count(c.id) FILTER (WHERE ((c.status = 'ok_empty'::text) AND (c.created_at > (now() - '7 days'::interval)))) AS empty_7d,
    count(c.id) FILTER (WHERE ((c.status <> ALL (ARRAY['ok'::text, 'ok_empty'::text])) AND (c.created_at > (now() - '7 days'::interval)))) AS failed_7d
   FROM (agent_tool t
     LEFT JOIN agent_tool_call c ON ((c.tool_id = t.tool_id)))
  WHERE t.active
  GROUP BY t.tool_id, t.kind, t.failure_behaviour;

CREATE OR REPLACE VIEW public.v_trade_scope_status AS  SELECT c.group_id,
    c.trade_key,
    c.status AS candidate_status,
    COALESCE(e.disposition,
        CASE
            WHEN (c.status = 'confirmed'::text) THEN 'included'::text
            WHEN (c.status = 'proposed'::text) THEN 'proposed'::text
            WHEN (c.status = 'rejected'::text) THEN 'excluded'::text
            ELSE 'unknown'::text
        END) AS disposition,
    COALESCE(e.specificity, '-1'::integer) AS specificity,
    k.contributes,
    k.requires_clarification,
    k.is_conflict,
    e.reason,
    e.clause_indexes,
    w.id AS workstream_id,
    w.active AS workstream_active
   FROM (((inquiry_trade_candidate c
     LEFT JOIN v_scope_disposition_effective e ON (((e.group_id = c.group_id) AND (e.trade_key = c.trade_key) AND (e.scope_component = 'complete_trade_scope'::text))))
     LEFT JOIN scope_disposition_kind k ON ((k.disposition = COALESCE(e.disposition,
        CASE
            WHEN (c.status = 'confirmed'::text) THEN 'included'::text
            WHEN (c.status = 'proposed'::text) THEN 'proposed'::text
            WHEN (c.status = 'rejected'::text) THEN 'excluded'::text
            ELSE 'unknown'::text
        END))))
     LEFT JOIN inquiry_workstream w ON ((w.id = c.workstream_id)))
UNION
 SELECT e.group_id,
    e.trade_key,
    NULL::text AS candidate_status,
    e.disposition,
    e.specificity,
    k.contributes,
    k.requires_clarification,
    k.is_conflict,
    e.reason,
    e.clause_indexes,
    NULL::bigint AS workstream_id,
    NULL::boolean AS workstream_active
   FROM (v_scope_disposition_effective e
     JOIN scope_disposition_kind k ON ((k.disposition = e.disposition)))
  WHERE ((e.scope_component = 'complete_trade_scope'::text) AND (NOT (EXISTS ( SELECT 1
           FROM inquiry_trade_candidate c
          WHERE ((c.group_id = e.group_id) AND (c.trade_key = e.trade_key))))));

CREATE OR REPLACE VIEW public.v_ui_label_missing AS  SELECT 'action_kind'::text AS domain,
    a.kind AS key,
    count(*) AS rows_in_use
   FROM (agent_actions a
     LEFT JOIN ui_label l ON (((l.domain = 'action_kind'::text) AND (l.key = a.kind))))
  WHERE ((l.key IS NULL) AND (a.kind IS NOT NULL))
  GROUP BY a.kind
UNION ALL
 SELECT 'notification_type'::text AS domain,
    n.type AS key,
    count(*) AS rows_in_use
   FROM (notifications n
     LEFT JOIN ui_label l ON (((l.domain = 'notification_type'::text) AND (l.key = n.type))))
  WHERE ((l.key IS NULL) AND (n.type IS NOT NULL))
  GROUP BY n.type;

CREATE OR REPLACE VIEW public.v_unit_economics AS  WITH p AS (
         SELECT pricing_config.standard_reveal_rate AS rate,
            pricing_config.supplier_reg_fee AS reg_fee
           FROM pricing_config
         LIMIT 1
        ), t AS (
         SELECT count(*) FILTER (WHERE (transactions.revealed_at IS NOT NULL)) AS reveals_total,
            count(*) FILTER (WHERE (transactions.revealed_at > (now() - '30 days'::interval))) AS reveals_30d,
            COALESCE(sum(transactions.reveal_fee) FILTER (WHERE (transactions.revealed_at IS NOT NULL)), (0)::numeric) AS reveal_revenue_total,
            COALESCE(sum(transactions.reveal_fee) FILTER (WHERE (transactions.revealed_at > (now() - '30 days'::interval))), (0)::numeric) AS reveal_revenue_30d,
            COALESCE(avg(transactions.reveal_fee) FILTER (WHERE (transactions.revealed_at IS NOT NULL)), (0)::numeric) AS avg_reveal_fee,
            count(*) FILTER (WHERE ((transactions.refund_status IS NOT NULL) AND (transactions.refund_status <> 'none'::text))) AS refunds
           FROM transactions
        ), s AS (
         SELECT count(*) FILTER (WHERE leads.verified) AS verified_suppliers,
            count(*) AS leads_total,
            count(*) FILTER (WHERE (leads.registration_paid_at IS NOT NULL)) AS paying_suppliers
           FROM leads
        ), i AS (
         SELECT count(*) AS inquiries_total,
            count(*) FILTER (WHERE (inquiries.created_at > (now() - '30 days'::interval))) AS inquiries_30d
           FROM inquiries
        ), c AS (
         SELECT COALESCE(sum(ai_cost_log.cost_aed), (0)::numeric) AS ai_cost_30d
           FROM ai_cost_log
          WHERE (ai_cost_log.occurred_at > (now() - '30 days'::interval))
        ), b AS (
         SELECT COALESCE(sum(department_budget.monthly_aed), (0)::numeric) AS fixed_monthly_aed
           FROM department_budget
        )
 SELECT p.rate AS reveal_rate,
    p.reg_fee AS supplier_reg_fee_aed,
    t.reveals_total,
    t.reveals_30d,
    t.reveal_revenue_total,
    t.reveal_revenue_30d,
    round(t.avg_reveal_fee, 2) AS avg_reveal_fee_aed,
    t.refunds,
    s.leads_total,
    s.verified_suppliers,
    s.paying_suppliers,
    i.inquiries_total,
    i.inquiries_30d,
    c.ai_cost_30d,
    b.fixed_monthly_aed,
        CASE
            WHEN (t.reveals_30d > 0) THEN round((c.ai_cost_30d / (t.reveals_30d)::numeric), 2)
            ELSE NULL::numeric
        END AS ai_cost_per_reveal_aed,
        CASE
            WHEN (t.avg_reveal_fee > (0)::numeric) THEN ceil((b.fixed_monthly_aed / t.avg_reveal_fee))
            ELSE NULL::numeric
        END AS breakeven_reveals_per_month,
        CASE
            WHEN (t.reveals_total = 0) THEN 'PRE-REVENUE: no reveal has ever been paid'::text
            ELSE 'LIVE'::text
        END AS state
   FROM p,
    t,
    s,
    i,
    c,
    b;

CREATE OR REPLACE VIEW public.v_workflow_matrix AS  SELECT e.department,
    e.action_class,
    e.active AS executor_active,
    e.note,
    au.max_tier,
    au.threshold_aed
   FROM (org_action_executor e
     FULL JOIN org_authority au ON (((au.dept_key = e.department) AND (au.action_class = e.action_class))));

CREATE OR REPLACE VIEW public.v_workflow_side_effects_without_executor AS  SELECT w.workflow_key,
    s.step_no,
    s.action_class
   FROM ((workflow w
     JOIN workflow_step s ON ((s.workflow_key = w.workflow_key)))
     LEFT JOIN org_action_executor e ON (((e.action_class = s.action_class) AND e.active)))
  WHERE (w.active AND (s.action_class IS NOT NULL) AND (e.action_class IS NULL));

CREATE OR REPLACE VIEW public.v_workstream_answer AS  SELECT w.id AS workstream_id,
    w.group_id,
    w.trade_key,
    w.active,
    a.id AS answer_id,
    a.field_id,
    a.value,
    a.unit,
    a.scope,
    a.precedence,
    a.source_kind,
    a.confirmed_at,
        CASE
            WHEN (a.scope = 'inquiry_shared'::text) THEN 'shared'::text
            WHEN (EXISTS ( SELECT 1
               FROM inquiry_answer_scope s
              WHERE ((s.answer_id = a.id) AND (s.workstream_id = w.id)))) THEN 'owned'::text
            ELSE 'referenced'::text
        END AS via,
    ((a.value IS NOT NULL) AND (btrim(a.value) <> ''::text) AND (a.precedence <> ALL (ARRAY['model_inference'::answer_precedence, 'unknown'::answer_precedence])) AND ((a.scope = 'inquiry_shared'::text) OR (EXISTS ( SELECT 1
           FROM inquiry_answer_scope s
          WHERE ((s.answer_id = a.id) AND (s.workstream_id = w.id)))))) AS satisfies_mandatory
   FROM (inquiry_workstream w
     JOIN inquiry_answer a ON (((a.group_id = w.group_id) AND (a.superseded_by IS NULL))))
  WHERE ((a.scope = 'inquiry_shared'::text) OR (EXISTS ( SELECT 1
           FROM inquiry_answer_scope s
          WHERE ((s.answer_id = a.id) AND (s.workstream_id = w.id)))) OR (EXISTS ( SELECT 1
           FROM field_definition_reference r
          WHERE ((r.field_id = a.field_id) AND (r.referencing_trade_key = w.trade_key)))));

CREATE OR REPLACE VIEW public.v_workstream_brand_policy AS  SELECT w.id AS workstream_id,
    w.group_id,
    w.trade_key,
    w.active,
    sh.value AS shared_default,
    ov.value AS trade_override,
    COALESCE(ov.value, sh.value) AS effective_policy,
        CASE
            WHEN (ov.value IS NOT NULL) THEN 'trade_override'::text
            WHEN (sh.value IS NOT NULL) THEN 'shared_default'::text
            ELSE 'unset'::text
        END AS effective_source,
    d.permits_equivalent,
    d.requires_brand_list,
    d.requires_customer_confirmation
   FROM (((inquiry_workstream w
     LEFT JOIN inquiry_answer sh ON (((sh.group_id = w.group_id) AND (sh.field_id = 'shared.brand_acceptance_policy'::text) AND (sh.superseded_by IS NULL))))
     LEFT JOIN inquiry_answer ov ON (((ov.group_id = w.group_id) AND (ov.field_id = (w.trade_key || '.brand_acceptance_policy_override'::text)) AND (ov.superseded_by IS NULL) AND (EXISTS ( SELECT 1
           FROM inquiry_answer_scope s
          WHERE ((s.answer_id = ov.id) AND (s.workstream_id = w.id)))))))
     LEFT JOIN brand_acceptance_policy_value d ON ((d.policy_value = COALESCE(ov.value, sh.value))));

CREATE OR REPLACE VIEW public.v_workstream_completeness AS  SELECT w.id AS workstream_id,
    w.group_id,
    w.trade_key,
    w.active,
    count(*) FILTER (WHERE r.mandatory) AS required_mandatory,
    count(*) FILTER (WHERE (r.mandatory AND va.satisfies_mandatory)) AS answered_mandatory,
    count(*) FILTER (WHERE (NOT r.mandatory)) AS required_optional,
    count(*) FILTER (WHERE ((NOT r.mandatory) AND va.satisfies_mandatory)) AS answered_optional,
    COALESCE(array_agg(r.field_id ORDER BY r.field_id) FILTER (WHERE (r.mandatory AND (NOT COALESCE(va.satisfies_mandatory, false)))), '{}'::text[]) AS missing_mandatory,
    COALESCE(( SELECT array_agg(DISTINCT vc.field_id) AS array_agg
           FROM v_workstream_conflict vc
          WHERE (vc.workstream_id = w.id)), '{}'::text[]) AS blocked_by
   FROM ((inquiry_workstream w
     LEFT JOIN inquiry_workstream_requirement r ON ((r.workstream_id = w.id)))
     LEFT JOIN v_workstream_answer va ON (((va.workstream_id = w.id) AND (va.field_id = r.field_id))))
  GROUP BY w.id, w.group_id, w.trade_key, w.active;

CREATE OR REPLACE VIEW public.v_workstream_conflict AS  SELECT w.id AS workstream_id,
    w.group_id,
    w.trade_key,
    c.id AS conflict_id,
    c.field_id,
    c.blocking_scope,
    c.opened_at
   FROM ((inquiry_workstream w
     JOIN inquiry_answer_conflict c ON (((c.group_id = w.group_id) AND (c.resolved_at IS NULL))))
     JOIN field_definition fd ON ((fd.field_id = c.field_id)))
  WHERE ((fd.scope = 'shared'::text) OR ((fd.scope = 'trade_specific'::text) AND (fd.trade_key = w.trade_key)) OR ((fd.scope = 'trade_subset'::text) AND (EXISTS ( SELECT 1
           FROM field_definition_trade t
          WHERE ((t.field_id = fd.field_id) AND (t.trade_key = w.trade_key))))));

CREATE OR REPLACE VIEW public.v_workstream_dispatch AS  SELECT workstream_id,
    group_id,
    trade_key,
    active,
    required_mandatory,
    answered_mandatory,
    missing_mandatory,
    blocked_by,
    (cardinality(missing_mandatory) = 0) AS mandatory_complete,
    (cardinality(blocked_by) = 0) AS no_unresolved_conflict,
    COALESCE(( SELECT jsonb_object_agg(gr.gate_key, COALESCE(( SELECT (g.state)::text AS state
                   FROM inquiry_gate g
                  WHERE ((g.workstream_id = c.workstream_id) AND (g.gate_key = gr.gate_key))), 'not_evaluated'::text)) AS jsonb_object_agg
           FROM inquiry_gate_required gr
          WHERE (gr.level = 'workstream'::text)), '{}'::jsonb) AS gate_states,
    (NOT (EXISTS ( SELECT 1
           FROM inquiry_gate_required gr
          WHERE ((gr.level = 'workstream'::text) AND (NOT (EXISTS ( SELECT 1
                   FROM inquiry_gate g
                  WHERE ((g.workstream_id = c.workstream_id) AND (g.gate_key = gr.gate_key) AND fn_gate_state_satisfies(g.state))))))))) AS gates_passed,
    (active AND (cardinality(missing_mandatory) = 0) AND (cardinality(blocked_by) = 0) AND (NOT (EXISTS ( SELECT 1
           FROM inquiry_gate_required gr
          WHERE ((gr.level = 'workstream'::text) AND (NOT (EXISTS ( SELECT 1
                   FROM inquiry_gate g
                  WHERE ((g.workstream_id = c.workstream_id) AND (g.gate_key = gr.gate_key) AND fn_gate_state_satisfies(g.state)))))))))) AS dispatch_eligible
   FROM v_workstream_completeness c;

-- ===== FUNCTIONS =====
CREATE OR REPLACE FUNCTION public._kb_next_ver(k text, r text)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ select coalesce(max(version),0)+1 from public.kb_revisions where entry_kind=k and entry_ref=r $function$


CREATE OR REPLACE FUNCTION public._next_docver(p_type text, p_id text)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ select coalesce(max(version),0)+1 from public.doc_versions where entity_type=p_type and entity_id=p_id $function$


CREATE OR REPLACE FUNCTION public._rfq_answered(v text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select v is not null
     and btrim(v) <> ''
     and btrim(v) not in ('[]','{}','-','?')
     and lower(btrim(v)) not in ('null','not sure','unknown','tbd','n/a','na');
$function$


CREATE OR REPLACE FUNCTION public._rfq_concept(k text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
    when k is null or btrim(k) = '' then null
    -- location first: "emirate / area" is a place, not a quantity
    when k ~ '(location|emirate|address|site|floor|region|area/|/area)' then 'loc'
    when k ~ '(quantity|qty|size|sizes|dimension|dimensions|area|volume|units|linear|count|sqm|sqft)' then 'qty'
    when k ~ '(scope|supply_install|install)'         then 'scope'
    when k ~ '(timeline|schedule|duration|deadline|when)' then 'time'
    when k ~ '(budget|price|cost)'                    then 'budget'
    when k ~ '(finish|material|fabric|fibre|colou?r)' then 'material'
    when k ~ '(item|product|element|service)'         then 'item'
    else null end;
$function$


CREATE OR REPLACE FUNCTION public.a00_kernel_routine_ownership_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_d       jsonb;
  v_derived text;
begin
  v_d := public.fn_kernel_routine_ownership(
           NEW.schema_name || '.' || NEW.routine_name, NEW.identity_args, NEW.source_kind);
  v_derived := v_d->>'ownership_class';

  if v_derived is distinct from NEW.ownership_class then
    raise exception
      'kernel_routine_ownership refuses %.%(%): recorded class %, but the facts support %. Rule %. %',
      NEW.schema_name, NEW.routine_name, NEW.identity_args, NEW.ownership_class, v_derived,
      v_d->>'rule', v_d->>'evidence'
      using errcode = '23514';
  end if;

  if NEW.classified_by_rule is distinct from (v_d->>'rule') then
    raise exception
      'kernel_routine_ownership refuses %.%(%): recorded rule % is not the rule that fired (%). %',
      NEW.schema_name, NEW.routine_name, NEW.identity_args, NEW.classified_by_rule,
      v_d->>'rule', v_d->>'evidence'
      using errcode = '23514';
  end if;

  return null;
end
$function$


CREATE OR REPLACE FUNCTION public.a00_llm_attempt_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  raise exception
    'llm_attempt is append-only (attempted % on attempt_id %). A retry inserts a new row with the next attempt_no; it never rewrites an earlier attempt, because first-attempt success rate must stay computable.',
    tg_op, coalesce(old.attempt_id::text,'?')
    using errcode = 'restrict_violation';
end $function$


CREATE OR REPLACE FUNCTION public.add_working_days(d date, n integer)
 RETURNS date
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cur date := d; added int := 0;
begin
  while added < n loop
    cur := cur + 1;
    if public.fn_is_working_day(cur) then added := added + 1; end if;
  end loop;
  return cur;
end;$function$


CREATE OR REPLACE FUNCTION public.ai_rec(p_sig text, p_cond boolean, p_risk text, p_title text, p_reco text, p_assumptions jsonb DEFAULT NULL::jsonb, p_impact text DEFAULT NULL::text, p_cost text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if p_cond and not exists (select 1 from agent_actions where kind='ai_improvement' and detail->>'signal'=p_sig and status in ('pending','needs_review')) then
    insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id,assumptions,expected_impact,cost)
    values ('ai_trainer','ai_improvement','pending',p_risk,p_title,p_reco,jsonb_build_object('signal',p_sig),'ai',p_sig,p_assumptions,p_impact,p_cost);
  end if;
end $function$


CREATE OR REPLACE FUNCTION public.auth_uid_by_email(p_email text)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'auth', 'public'
AS $function$
  select id from auth.users where lower(email) = lower(p_email) limit 1;
$function$


CREATE OR REPLACE FUNCTION public.block_disposable_signup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare em text;
begin
  if TG_TABLE_NAME = 'customers' then
    em := NEW.email;
  else
    -- only gate genuine supplier signups; leave scraped leads (claimed false/null) untouched
    if NEW.claimed is distinct from true then return NEW; end if;
    em := coalesce(NEW.claimed_by, NEW.email);
  end if;
  if em is not null and is_disposable_email(em) then
    raise exception 'Please use a permanent email address; temporary inboxes are not allowed.' using errcode = '23514';
  end if;
  return NEW;
end$function$


CREATE OR REPLACE FUNCTION public.canary_scan(haystack text)
 RETURNS TABLE(kind text, label text, fingerprint text, matched text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select c.kind, c.label, c.fingerprint,
    case
      when position(lower(c.fingerprint) in lower(haystack))>0 then 'fingerprint'
      when position(lower(c.label) in lower(haystack))>0 then 'company name'
      when c.honeytoken_email is not null and position(lower(c.honeytoken_email) in lower(haystack))>0 then 'honeytoken email'
    end as matched
  from canary_records c
  where position(lower(c.fingerprint) in lower(haystack))>0
     or position(lower(c.label) in lower(haystack))>0
     or (c.honeytoken_email is not null and position(lower(c.honeytoken_email) in lower(haystack))>0);
$function$


CREATE OR REPLACE FUNCTION public.dedupe_it_incident()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if NEW.agent='it' and NEW.kind='incident' and coalesce(NEW.status,'pending')='pending' then
    if exists (
      select 1 from public.agent_actions a
      where a.agent='it' and a.kind='incident' and a.status='pending'
        and coalesce(a.target_table,'')=coalesce(NEW.target_table,'')
    ) then
      return null; -- duplicate open incident; skip
    end if;
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.doc_rec(p_sig text, p_cond boolean, p_risk text, p_title text, p_reco text, p_assumptions jsonb DEFAULT NULL::jsonb, p_impact text DEFAULT NULL::text, p_cost text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if p_cond and not exists (select 1 from agent_actions where kind='doc_task' and detail->>'signal'=p_sig and status in ('pending','needs_review')) then
    insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id,assumptions,expected_impact,cost)
    values ('document_controller','doc_task','pending',p_risk,p_title,p_reco,jsonb_build_object('signal',p_sig),'documents',p_sig,p_assumptions,p_impact,p_cost);
  end if;
end $function$


CREATE OR REPLACE FUNCTION public.enqueue_supplier_invites(p_cap integer DEFAULT NULL::integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_site text;
  v_today date := (now() at time zone 'UTC')::date;
  v_planned int; v_used int; v_remaining int; v_subj text; v_body text; v_count int;
  v_inv_recent int; v_bounced_recent int; v_rate numeric; v_max_rate numeric; v_target int; v_cap int;
  v_pause boolean := false; v_why text;
  v_hol_name text; v_hol_action text; v_hol_end date;
begin
  if coalesce((select value from app_secrets where key='invite_enabled'),'false') <> 'true' then return 0; end if;

  -- THE CALENDAR THE COMPANY KEEPS ABOUT ITSELF. Checked before anything is planned or written, so
  -- a frozen day leaves no invite_schedule row claiming it planned sends it never made.
  select c.event_name, c.action, c.ends_on into v_hol_name, v_hol_action, v_hol_end
    from public.company_calendar c
   where c.kind = 'public_holiday'
     and v_today between c.starts_on and coalesce(c.ends_on, c.starts_on)
   order by c.starts_on limit 1;
  if v_hol_name is not null then
    insert into agent_runs(agent, status, counts, note, started_at, finished_at)
    values ('supplier_invites', 'ok',
            jsonb_build_object('queued', 0, 'calendar_paused', true, 'resumes_on', coalesce(v_hol_end, v_today) + 1),
            'Invites held: company_calendar has "' || v_hol_name || '" covering today. Its recorded action: '
            || coalesce(v_hol_action, '(none recorded)'), now(), now());
    return 0;
  end if;

  v_cap := coalesce((select nullif(value,'')::int from app_secrets where key='invite_daily_cap'), 10);
  insert into invite_schedule(day, planned, status) values (v_today, v_cap, 'approved')
    on conflict (day) do update set planned = excluded.planned, status = 'approved';
  v_planned := least(coalesce(p_cap, v_cap), v_cap);
  if v_planned <= 0 then return 0; end if;

  v_max_rate := coalesce((select nullif(value,'')::numeric from app_secrets where key='invite_max_bounce_rate'), 0.08);
  select count(*) into v_inv_recent from leads where invited_at > now() - interval '3 days';
  select count(*) into v_bounced_recent from leads where invite_status='bounced' and invited_at > now() - interval '3 days';
  v_rate := round(v_bounced_recent::numeric / greatest(v_inv_recent,1), 3);

  if v_inv_recent >= 15 and v_rate > v_max_rate then
    v_pause := true;
    v_why := 'bounce rate '||(v_rate*100)||'% over 3 days ('||v_bounced_recent||'/'||v_inv_recent||') exceeds the '||(v_max_rate*100)||'% limit';
  end if;
  -- SCALES WITH THE RAMP (12 Aug 2026). See the header: five was right at a cap of ten and wrong at
  -- two hundred. greatest() ignores nulls, so both arms are non-null by construction.
  if not v_pause and v_bounced_recent >= greatest(5, ceil(v_inv_recent * v_max_rate)::int) then
    v_pause := true;
    v_why := v_bounced_recent||' hard bounces in 3 days against '||v_inv_recent||' sent. Regardless of rate, that is a list-quality problem';
  end if;

  if v_pause then
    update app_secrets set value='false' where key='invite_enabled';
    if not exists (select 1 from founder_alerts where event='invite_paused_bounce' and created_at > now()-interval '24 hours') then
      insert into founder_alerts(level,event,detail,channel)
        values('crit','invite_paused_bounce','Supplier invites AUTO-PAUSED: '||v_why||'. Clean the list before resuming.','system');
      insert into notifications(type,to_email,to_role,channel,subject,body,status)
        values('invite_paused_bounce', coalesce((select split_part(value,',',1) from app_secrets where key='admin_emails'),'management@quotesdone.com'),'admin','email','Supplier invites paused - deliverability risk','Invites were auto-paused: '||v_why||'. Validate the list, then re-enable.','queued');
    end if;
    return 0;
  end if;

  select coalesce(nullif(btrim(value),''), 'https://quotesdone.com') into v_site
    from app_secrets where key='public_site_url';
  select value into v_subj from app_secrets where key='invite_subject';
  select value into v_body from app_secrets where key='invite_body';
  select count(*) into v_used from notifications where type='supplier_invite' and (created_at at time zone 'UTC')::date = v_today;
  v_remaining := greatest(0, v_planned - v_used);
  if v_remaining <= 0 then return 0; end if;

  v_target := coalesce((select nullif(value,'')::int from app_secrets where key='invite_target_per_category'),
                       (select nullif(value,'')::int from app_secrets where key='invite_target_per_trade'), 10);

  -- MATERIALIZED, 4 Aug 2026, and it is load-bearing. Both CTEs are referenced exactly once, from
  -- inside the correlated subquery in `prio`. Without this keyword Postgres inlines them there and
  -- re-runs the whole leads x lead_subcategory aggregate once per candidate - 19,632 times, twice
  -- over, ~220 s against a 120 s timeout. Neither depends on the outer row, so computing them once
  -- is semantically identical and 54x faster. Do not remove.
  with activated as materialized (
    select ls.domain_slug, count(distinct l.id) ct
    from leads l join lead_subcategory ls on ls.lead_id = l.id
    where coalesce(l.claimed,false) = true
    group by ls.domain_slug
  ),
  under as materialized (
    select d.slug as domain_slug, coalesce(a.ct,0) as have
    from catalog_domains d left join activated a on a.domain_slug = d.slug
    where coalesce(a.ct,0) < v_target
  ),
  cand as (
    select distinct on (lower(l.email)) l.id, l.email, l.company_name, l.claim_token, l.email_domain, l.email_verified
    from leads l
    where l.email is not null and l.email <> '' and l.invite_status is null
      and coalesce(l.source,'') <> 'self_registered' and coalesce(l.claimed,false) = false
      and (public.fn_email_sendable(l.email)->>'ok')::boolean
    order by lower(l.email), l.id
  ),
  prio as (
    select c.id, c.email, c.company_name, c.claim_token, c.email_domain,
      coalesce((select u.domain_slug from lead_subcategory ls join under u on u.domain_slug = ls.domain_slug
                 where ls.lead_id = c.id order by u.have asc, ls.score desc limit 1), '~none') as pdomain,
      case when c.email_verified in ('verified','true') then 0 else 1 end as unverified_rank,
      -- ROLE ADDRESSES LAST (12 Aug 2026). All five bounces to date are role addresses on domains
      -- with live MX, every one flagged email_verified by the scrape, so neither the MX cull nor
      -- that flag protects against them. Not excluded: 5,870 of 19,835 eligible leads publish no
      -- other address and dropping them would drop the supplier. Ranked behind a named human at the
      -- same verification rank, so a run reaches people first and works down to shared inboxes only
      -- when it runs out of them.
      case when split_part(lower(c.email),'@',1) in
             ('info','sales','admin','contact','enquiry','enquiries','inquiry','office','mail',
              'support','hello','marketing','general','accounts','reception','careers','hr')
           then 1 else 0 end as role_rank
    from cand c
  ),
  elig as (
    select id, email, company_name, claim_token from (
      select id, email, company_name, claim_token, pdomain, unverified_rank, role_rank,
        case when pdomain='~none' then 1 else 0 end as is_none,
        row_number() over (partition by pdomain order by unverified_rank, role_rank, id) as rk,
        row_number() over (partition by coalesce(email_domain, split_part(email,'@',2)) order by unverified_rank, role_rank, id) as domain_rk
      from prio
    ) r
    where domain_rk <= 5
    order by is_none, rk, unverified_rank, role_rank, pdomain
    limit v_remaining
  ),
  ins as (
    insert into notifications(type,to_email,to_role,lead_id,subject,body,status,created_at)
    select 'supplier_invite', email, 'supplier', id, v_subj,
           replace(
             replace(v_body, '{{company}}', coalesce(nullif(btrim(company_name),''), 'there')),
             '{{link}}', v_site || '/en/portal?t=' || claim_token::text), 'queued', now()
    from elig returning to_email
  )
  update leads set invite_status='queued', invited_at=now()
  where invite_status is null and lower(email) in (select lower(to_email) from ins);
  get diagnostics v_count = row_count;
  update invite_schedule set sent = sent + v_count where day = v_today;
  return v_count;
end;
$function$


CREATE OR REPLACE FUNCTION public.ensure_category_agent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not exists (select 1 from public.category_agents where slug = NEW.slug) then
    insert into public.category_agents(slug, name, active, created_at)
    values (
      NEW.slug,
      coalesce(NEW.name, initcap(replace(NEW.slug, '-', ' '))),
      true,
      now()
    );
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fin_alert(p_sig text, p_risk text, p_title text, p_reco text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not exists (select 1 from agent_actions where kind='finance_alert' and detail->>'signal'=p_sig and status in ('pending','needs_review')) then
    insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id)
    values ('finance_ai','finance_alert','pending',p_risk,p_title,p_reco,jsonb_build_object('signal',p_sig),'finance',p_sig);
  end if;
end $function$


CREATE OR REPLACE FUNCTION public.fn_accrue_dues_interest()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_rate numeric; v_updated int := 0;
begin
  v_rate := coalesce((select num_value from public.gl_settings where key='clawback_interest_monthly_pct'), 0.75) / 100.0;

  with calc as (
    select d.id,
           round(coalesce(d.amount_due,0) * v_rate *
                 greatest(0, (date_part('year',  age(current_date, d.due_date::date)) * 12
                            + date_part('month', age(current_date, d.due_date::date)))::int), 2) as want
    from public.supplier_dues d
    where d.paid_at is null
      -- H6 (OS audit): once collections_legal has escalated a due it FREEZES the interest; the monthly
      -- accrual must not overwrite that frozen figure, so exclude legal-stage dues here.
      and coalesce(d.status,'') not in ('paid','settled','waived','cancelled','legal')
      and d.legal_stage is null
      and coalesce(d.amount_due,0) > 0
      and d.due_date is not null
  )
  update public.supplier_dues d
     set interest_amount = c.want
    from calc c
   where c.id = d.id
     and coalesce(d.interest_amount,0) is distinct from c.want;

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_action_invoke_collect()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_ok int := 0; v_retry int := 0; v_dead int := 0; v_wait int := 0;
        v_status int; v_body text; v_err text; v_good boolean;
begin
  for r in
    select a.id, a.action_class, a.attempts, a.executor,
           (a.response->>'net_request_id')::bigint req,
           coalesce((a.response->>'max_attempts')::int, 1) max_attempts,
           a.started_at
      from public.action_execution a
     where a.status = 'running' and (a.response->>'net_request_id') is not null
  loop
    select status_code, content, error_msg into v_status, v_body, v_err
      from net._http_response where id = r.req;

    if not found then
      if r.started_at < now() - interval '10 minutes' then
        v_status := null; v_err := 'no pg_net response after 10 minutes';
      else
        v_wait := v_wait + 1; continue;
      end if;
    end if;

    -- A 200 IS NOT ENOUGH. quote_compare returned {ok:false,'parse_failed'} at HTTP 200 for weeks.
    v_good := v_status = 200
              and coalesce(v_body,'') <> ''
              and coalesce((nullif(v_body,'')::jsonb ->> 'ok'), 'true') <> 'false';

    if v_good then
      update public.action_execution
         set status = 'succeeded', finished_at = now(),
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','succeeded','at',now(),'http_status',v_status,
               'body', left(coalesce(v_body,''), 4000))
       where id = r.id;
      v_ok := v_ok + 1;

      begin
        update public.org_tasks k
           set status = 'done', updated_at = now(), last_run_at = now(),
               result = coalesce(k.result,'{}'::jsonb) || jsonb_build_object(
                 'mode','executed_by_invoker', 'executor', r.executor,
                 'http_status', v_status, 'at', now(),
                 'summary', left(coalesce(v_body,''), 500),
                 -- SIX KEYS, NOT THREE (12 Aug 2026). See the header: action_worker is the largest
                 -- producer in the estate and emits `outcome`, which none of the original three
                 -- matched, so 254 of 556 invocations in 7 days closed their task with a NULL
                 -- deliverable while carrying real work in the body. Appended, never reordered, so
                 -- anything extracting correctly today is untouched.
                 'deliverable', case
                    when pg_input_is_valid(coalesce(v_body,''), 'jsonb') then coalesce(
                      nullif(btrim(coalesce((v_body::jsonb)->>'recommendation','')),''),
                      nullif(btrim(coalesce((v_body::jsonb)->>'deliverable','')),''),
                      nullif(btrim(coalesce((v_body::jsonb)->>'note','')),''),
                      nullif(btrim(coalesce((v_body::jsonb)->>'outcome','')),''),
                      nullif(btrim(coalesce((v_body::jsonb)->>'summary','')),''),
                      nullif(btrim(coalesce((v_body::jsonb)->>'result','')),''))
                    else nullif(btrim(coalesce(v_body,'')),'') end)
         where k.id = (select (a.request->>'org_task_id')::bigint from public.action_execution a where a.id = r.id)
           and k.status in ('assigned','in_progress');
      exception when others then
        update public.action_execution
           set response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
                 'org_task_close', 'refused', 'reason', left(SQLERRM, 400))
         where id = r.id;
      end;
    elsif coalesce(r.attempts,1) < r.max_attempts then
      update public.action_execution
         set status = 'queued',
             response = coalesce(response,'{}'::jsonb) - 'net_request_id' || jsonb_build_object(
               'invoker','retrying','at',now(),'http_status',v_status,
               'error', left(coalesce(v_err, v_body, 'unknown'), 500))
       where id = r.id;
      v_retry := v_retry + 1;
    else
      update public.action_execution
         set status = 'failed', finished_at = now(),
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','failed','at',now(),'http_status',v_status,
               'error', left(coalesce(v_err, v_body, 'unknown'), 500))
       where id = r.id;
      insert into public.dead_letter(source, source_id, kind, reason, payload, first_failed_at, attempts)
      values ('fn_action_invoke_collect', r.id::text, r.action_class,
              left(coalesce(v_err, v_body, 'http ' || coalesce(v_status::text,'?')), 500),
              jsonb_build_object('executor', r.executor, 'http_status', v_status,
                                 'body', left(coalesce(v_body,''), 2000)),
              now(), coalesce(r.attempts,1));
      v_dead := v_dead + 1;
    end if;
  end loop;

  return jsonb_build_object('succeeded', v_ok, 'retrying', v_retry, 'dead_lettered', v_dead,
                            'still_in_flight', v_wait, 'ran_at', now());
end
$function$


CREATE OR REPLACE FUNCTION public.fn_action_invoke_dispatch(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_req bigint; v_sent int := 0; v_refused int := 0; v_skipped int := 0;
        v_url text; v_secret text; v_ref text; v_key text;
begin
  select value into v_secret from app_secrets where key = 'cred_action_invoker';
  if v_secret is null then
    return jsonb_build_object('error', 'no cred_action_invoker credential', 'ran_at', now());
  end if;
  -- The project ref is read off an existing cron command rather than hard-coded, so the same
  -- migration file is correct on production and on staging.
  select value into v_ref from app_secrets where key = 'project_ref';
  if v_ref is null then
    select substring(command from 'https://([a-z]+)[.]supabase[.]co') into v_ref
      from cron.job where command like '%supabase.co/functions/v1/%' limit 1;
  end if;
  if v_ref is null then return jsonb_build_object('error','cannot determine project ref','ran_at',now()); end if;

  for r in
    select a.id, a.action_class, a.request, a.idempotency_key, a.attempts,
           e.target, e.kind, e.active, e.risk_tier, e.advisory_safe, e.reversible,
           e.required_authority, e.compensation_action_class, e.idempotency_strategy, e.params,
           e.notifies_human, e.unattended_ok,
           coalesce(e.timeout_seconds, 60) timeout_seconds, coalesce(e.max_attempts, 1) max_attempts
      from public.action_execution a
      join public.org_action_executor e on e.action_class = a.action_class
     where a.status = 'queued' and e.kind = 'edge'
     order by a.created_at
     limit greatest(coalesce(p_limit, 5), 1)
  loop
    -- ---- the three absolute refusals, the human-contact refusal, then the risk tier -----------
    -- notifies_human is checked BEFORE the risk tier on purpose. The tier answers "how much
    -- damage if this is wrong"; notifies_human answers "does a person hear from us either way",
    -- and a message that should not have been sent cannot be un-sent by a low risk score.
    if not r.active
       or coalesce(r.required_authority,'') = 'founder'
       or (not r.reversible and r.compensation_action_class is null)
       or (coalesce(r.notifies_human,false) and not coalesce(r.unattended_ok,false))
       or not (r.risk_tier = 'low' and r.advisory_safe and r.reversible) then
      update public.action_execution
         set response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker', 'refused', 'at', now(),
               'reason', case
                 when not r.active then 'executor row is inactive'
                 when coalesce(r.required_authority,'') = 'founder' then 'reserved to the founder'
                 when (not r.reversible and r.compensation_action_class is null)
                   then 'not reversible and declares no compensation_action_class'
                 when (coalesce(r.notifies_human,false) and not coalesce(r.unattended_ok,false))
                   then 'notifies_human is true and unattended_ok has not been set for this class — a person hears from us when this runs, and nobody has decided it may run unattended'
                 else format('risk gate: tier=%s advisory_safe=%s reversible=%s — the invoker dispatches low/advisory_safe/reversible only',
                             r.risk_tier, r.advisory_safe, r.reversible) end)
       where id = r.id;
      v_refused := v_refused + 1;
      continue;
    end if;

    -- ---- idempotency: the column exists on both tables and was never consulted ---------------
    v_key := coalesce(nullif(btrim(r.idempotency_key),''),
                      r.action_class || ':' || md5(coalesce(r.request::text,'')));
    if r.idempotency_strategy is distinct from 'none_read_only'
       and exists (select 1 from public.action_execution x
                    where x.id <> r.id and x.status = 'succeeded'
                      and x.idempotency_key = v_key
                      and x.finished_at > now() - interval '24 hours') then
      update public.action_execution
         set status = 'succeeded', finished_at = now(),
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','deduplicated','at',now(),'idempotency_key',v_key,
               'strategy', r.idempotency_strategy)
       where id = r.id;
      v_skipped := v_skipped + 1;
      continue;
    end if;

    v_url := 'https://' || v_ref || '.supabase.co/functions/v1/' || r.target;
    select net.http_post(
             url := v_url,
             headers := '{"Content-Type":"application/json"}'::jsonb,
             -- org_action_executor.params is the per-executor payload TEMPLATE and it existed,
             -- empty, on all 55 rows. Without it the invoker sent {org_task_id, dept_key, title}
             -- to every target and compliance_archive answered 400 unknown_action — found by
             -- execution on the first real sweep, not by reading. params is the base of the body
             -- so a target's contract is declared as data, not coded into the invoker.
             body := coalesce(r.params, '{}'::jsonb) || coalesce(r.request, '{}'::jsonb)
                     || jsonb_build_object('__secret', v_secret),
             timeout_milliseconds := r.timeout_seconds * 1000)
      into v_req;

    update public.action_execution
       set status = 'running', attempts = coalesce(attempts,0) + 1,
           executor = r.target, idempotency_key = v_key,
           started_at = coalesce(started_at, now()),
           response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
             'invoker','dispatched','at',now(),'net_request_id',v_req,'url',v_url,
             'timeout_seconds', r.timeout_seconds, 'attempt', coalesce(r.attempts,0)+1,
             'max_attempts', r.max_attempts)
     where id = r.id;
    v_sent := v_sent + 1;
  end loop;

  return jsonb_build_object('dispatched', v_sent, 'refused', v_refused,
                            'deduplicated', v_skipped, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_action_invoke_rpc(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_ran int := 0; v_refused int := 0; v_skipped int := 0; v_failed int := 0;
        v_key text; v_res jsonb; v_missing boolean; v_required int;
begin
  for r in
    select a.id, a.action_class, a.request, a.idempotency_key, a.attempts,
           e.target, e.active, e.risk_tier, e.advisory_safe, e.reversible,
           e.required_authority, e.compensation_action_class, e.idempotency_strategy,
           e.notifies_human, e.unattended_ok
      from public.action_execution a
      join public.org_action_executor e on e.action_class = a.action_class
     where a.status = 'queued' and e.kind = 'rpc'
     order by a.created_at
     limit greatest(coalesce(p_limit, 5), 1)
  loop
    -- THE SAME REFUSALS AS THE EDGE PATH, in the same order and for the same reasons. A SQL
    -- function is not safer than an HTTP call because it is closer to the data; if anything it is
    -- nearer the money. notifies_human is still checked before the risk tier: a message that
    -- should not have been sent cannot be un-sent by a low risk score.
    if not r.active
       or coalesce(r.required_authority,'') = 'founder'
       or (not r.reversible and r.compensation_action_class is null)
       or (coalesce(r.notifies_human,false) and not coalesce(r.unattended_ok,false))
       or not (r.risk_tier = 'low' and r.advisory_safe and r.reversible) then
      update public.action_execution
         set response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','refused','at',now(),'kind','rpc',
               'reason', case
                 when not r.active then 'executor row is inactive'
                 when coalesce(r.required_authority,'') = 'founder' then 'reserved to the founder'
                 when (not r.reversible and r.compensation_action_class is null)
                   then 'not reversible and declares no compensation_action_class'
                 when (coalesce(r.notifies_human,false) and not coalesce(r.unattended_ok,false))
                   then 'notifies_human is true and unattended_ok has not been set for this class'
                 else format('risk gate: tier=%s advisory_safe=%s reversible=%s - the invoker runs low/advisory_safe/reversible only',
                             r.risk_tier, r.advisory_safe, r.reversible) end)
       where id = r.id;
      v_refused := v_refused + 1;
      continue;
    end if;

    -- CAN THIS TARGET ACTUALLY BE CALLED? Asked of pg_proc, not assumed from the table. A missing
    -- function and a function needing arguments we do not have are different failures and are
    -- reported as different reasons.
    select (p.oid is null), coalesce(p.pronargs - p.pronargdefaults, -1)
      into v_missing, v_required
      from (select 1) _
      left join pg_proc p on p.proname = r.target and p.pronamespace = 'public'::regnamespace;

    if v_missing then
      update public.action_execution
         set status = 'failed', finished_at = now(), attempts = coalesce(attempts,0) + 1,
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','failed','at',now(),'kind','rpc',
               'error', format('executor target public.%s() does not exist', r.target))
       where id = r.id;
      v_failed := v_failed + 1;
      continue;
    end if;

    if v_required > 0 then
      update public.action_execution
         set status = 'failed', finished_at = now(), attempts = coalesce(attempts,0) + 1,
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','failed','at',now(),'kind','rpc',
               'error', format('public.%s() requires %s argument(s) with no default, and a workflow step carries none to give it. Supply them through org_action_executor.params, or give the function defaults - do not let the invoker invent them.',
                               r.target, v_required))
       where id = r.id;
      v_failed := v_failed + 1;
      continue;
    end if;

    v_key := coalesce(nullif(btrim(r.idempotency_key),''),
                      r.action_class || ':' || md5(coalesce(r.request::text,'')));
    if r.idempotency_strategy is distinct from 'none_read_only'
       and exists (select 1 from public.action_execution x
                    where x.id <> r.id and x.status = 'succeeded'
                      and x.idempotency_key = v_key
                      and x.finished_at > now() - interval '24 hours') then
      update public.action_execution
         set status = 'succeeded', finished_at = now(),
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','deduplicated','at',now(),'kind','rpc','idempotency_key',v_key)
       where id = r.id;
      v_skipped := v_skipped + 1;
      continue;
    end if;

    -- One form for every return shape. A set-returning function yields its rows; a scalar
    -- function in FROM yields exactly one. Wrapped per row so one failing target cannot roll back
    -- the others in this sweep.
    begin
      execute format('select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from public.%I() t', r.target)
        into v_res;
      update public.action_execution
         set status = 'succeeded', finished_at = now(), attempts = coalesce(attempts,0) + 1,
             executor = r.target, idempotency_key = v_key,
             started_at = coalesce(started_at, now()),
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','succeeded','at',now(),'kind','rpc','result', v_res)
       where id = r.id;
      v_ran := v_ran + 1;
    exception when others then
      update public.action_execution
         set status = 'failed', finished_at = now(), attempts = coalesce(attempts,0) + 1,
             executor = r.target,
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','failed','at',now(),'kind','rpc',
               'error', replace(coalesce(sqlerrm,'unknown'), '''', ''))
       where id = r.id;
      v_failed := v_failed + 1;
    end;
  end loop;

  return jsonb_build_object('ran', v_ran, 'refused', v_refused, 'deduplicated', v_skipped,
                            'failed', v_failed, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_action_policies(p_kind text, p_confidence numeric)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select array_remove(array[
    -- action_autonomy: the standing per-kind rule that decides whether the sweep may clear this
    -- action or the founder must see it. The action's own kind selects the answer.
    (select 'action_autonomy: '||coalesce(p_kind,'(no kind)')||' → '||(d.value->>p_kind)
       from public.decision_policy d
      where d.key = 'action_autonomy' and p_kind is not null and d.value ? p_kind),
    -- confidence_min, against this action's own confidence, so two actions of the same kind read
    -- differently. An action with no confidence says that rather than being left blank.
    (select case when p_confidence is null
              then 'confidence_min '||(d.value#>>'{}')||' — this action records no confidence, so the floor cannot be applied'
              else 'confidence_min '||(d.value#>>'{}')||' — this action '||round(p_confidence, 2)::text
                   ||case when p_confidence < (d.value#>>'{}')::numeric then ', below the floor' else ', at or above the floor' end end
       from public.decision_policy d where d.key = 'confidence_min'),
    -- the chairman doctrine list: an action inside it is not a judgement call.
    (select 'founder_review_gates: '||p_kind||' is on the founder-review list'
       from public.decision_policy d
      where d.key = 'founder_review_gates' and p_kind is not null and d.value ? p_kind)
  ], null);
$function$


CREATE OR REPLACE FUNCTION public.fn_action_queue_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_dupes int := 0; v_cleared int := 0;
begin
  -- 1. DUPLICATES. Keep the newest of each (agent, kind, normalised title); supersede the rest.
  --    A leading integer is a COUNT, not an identity: "4 agent run(s) failed in last 24h" and
  --    "10 agent run(s) failed in last 24h" are the same recurring incident reported twice.
  with ranked as (
    select id, agent, kind,
           regexp_replace(title, '^[0-9]+\s+', 'N ') as norm_title,
           first_value(id) over (partition by agent, kind, regexp_replace(title, '^[0-9]+\s+', 'N ')
                                 order by created_at desc) keep_id,
           row_number() over (partition by agent, kind, regexp_replace(title, '^[0-9]+\s+', 'N ')
                              order by created_at desc) rn
      from public.agent_actions
     where status in ('pending','needs_review')
  ), dupes as (select id, keep_id from ranked where rn > 1)
  update public.agent_actions a
     set status = 'superseded',
         decided_by = 'action_queue_sweep',
         decided_at = now(),
         detail = coalesce(a.detail, '{}'::jsonb)
                  || jsonb_build_object('superseded_by', d.keep_id, 'swept_at', now(),
                                        'reason', 'same agent/kind and same title once a leading count is normalised')
    from dupes d where a.id = d.id;
  get diagnostics v_dupes = row_count;

  -- 2. STALE INCIDENTS whose condition has cleared. An incident naming failed runs is a
  --    POINT-IN-TIME observation over its own 24-hour window. Older than 48 hours it is either
  --    already superseded by a newer one above, or nothing has failed in the window it names.
  --    The old global "has anything failed anywhere in 48h" guard is gone: it made this branch
  --    unreachable in any estate that is actually running.
  update public.agent_actions a
     set status = 'auto_resolved',
         decided_by = 'action_queue_sweep',
         decided_at = now(),
         detail = coalesce(a.detail, '{}'::jsonb)
                  || jsonb_build_object('auto_resolved_at', now(),
                                        'reason', 'point-in-time run-failure incident older than 48h; '
                                               || 'any still-live failure is carried by a newer incident')
   where a.status in ('pending','needs_review')
     and a.kind = 'incident'
     and a.created_at < now() - interval '48 hours'
     and a.title ~* 'run\(s\) failed';
  get diagnostics v_cleared = row_count;

  if v_dupes + v_cleared > 0 then
    insert into public.founder_alerts(level, event, detail, channel)
      values ('info', 'Action queue swept',
              v_dupes || ' duplicate(s) superseded and ' || v_cleared
              || ' stale incident(s) auto-resolved. Handoffs, legal flags, customer escalations and '
              || 'recommendations were left untouched — those need you.', 'os');
  end if;

  return jsonb_build_object('superseded', v_dupes, 'auto_resolved', v_cleared,
    'still_open', (select count(*) from public.agent_actions where status in ('pending','needs_review')),
    'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_add_working_days(p_from timestamp with time zone, p_days integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d date; left_ int := greatest(0, coalesce(p_days,0)); tod time; res timestamptz;
begin
  if p_from is null then return null; end if;
  d   := (p_from at time zone 'Asia/Dubai')::date;
  tod := (p_from at time zone 'Asia/Dubai')::time;
  while left_ > 0 loop
    d := d + 1;
    if public.fn_is_working_day(d) then left_ := left_ - 1; end if;
  end loop;
  -- if we consumed no days and landed on a non-working day, roll forward
  while not public.fn_is_working_day(d) loop d := d + 1; end loop;
  res := ((d::text || ' ' || tod::text)::timestamp) at time zone 'Asia/Dubai';
  return res;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_action_resolve_addressee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_key text;
begin
  if new.agent is null or new.agent = '' then
    new.agent := 'brief';
    new.escalated := true;
    new.escalation_reason := coalesce(new.escalation_reason, 'written with no addressee at all');
    return new;
  end if;

  if exists (select 1 from public.org_agents o where o.agent_key = new.agent and o.active) then
    return new;
  end if;

  v_key := public.fn_org_agent_resolve(new.agent);

  if v_key is null then
    new.detail := coalesce(new.detail, '{}'::jsonb)
                  || jsonb_build_object('addressed_as', new.agent, 'addressee_unresolved', true);
    new.escalated := true;
    new.escalation_reason := coalesce(new.escalation_reason,
      'addressee "' || new.agent || '" is not an employee and no org_agent_alias maps it');
    new.agent := 'brief';
    return new;
  end if;

  new.detail := coalesce(new.detail, '{}'::jsonb) || jsonb_build_object('addressed_as', new.agent);
  new.agent := v_key;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_action_trace()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Delegates to the shared builder so the UPDATE path and the INSERT path cannot produce
  -- different trace shapes. fn_agent_action_trace_row resolves role, department and manager from
  -- the roster and pulls the knowledge actually retrieved near the decision.
  perform public.fn_agent_action_trace_row(new);
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_action_trace_ins()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.decided_at is not null then
    perform public.fn_agent_action_trace_row(new);
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_action_trace_row(a agent_actions)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_ids text[]; v_id uuid;
begin
  -- knowledge actually retrieved by this agent near the decision, from the recording table
  select coalesce(array_agg(distinct k), '{}') into v_ids
    from agent_context_retrieval r, unnest(r.knowledge_ids) k
   where r.agent_key = a.agent
     and r.created_at between a.decided_at - interval '30 minutes' and a.decided_at + interval '1 minute';

  select public.fn_write_decision_trace(jsonb_build_object(
    'agent_key',       a.agent,
    'entity_type',     coalesce(a.target_table,'agent_action'),
    'entity_id',       coalesce(a.target_id::text, a.id::text),
    'decision_type',   a.kind,
    'decided_by',      coalesce(a.decided_by, a.agent),
    'task_id',         a.id::text,
    'confidence',      a.confidence::text,
    'risk',            jsonb_build_object('tier', a.risk, 'escalated', a.escalated),
    'evidence_refs',   coalesce(a.evidence, '[]'::jsonb),
    'alternatives',    coalesce(a.alternatives, '[]'::jsonb),
    'assumptions',     coalesce(a.assumptions, '[]'::jsonb),
    'knowledge_refs',  to_jsonb(v_ids),
    'proposed_action', a.recommendation,
    'expected_outcome',a.expected_impact,
    'escalation_decision', case when a.escalated then 'escalated' else 'within_authority' end,
    'outcome_status',  case when a.status in ('done','approved') then 'accepted'
                            when a.status in ('rejected','dismissed') then 'rejected'
                            else 'pending' end,
    'final_status',    a.status
  )) into v_id;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_action_work_sweep(p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_q int := 0; r record; v_key text;
begin
  for r in
    select a.id, a.kind,
           (select count(*) from public.action_execution x
             where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')
               and x.status = 'failed') as failures
      from public.agent_actions a
      join public.org_agents o on o.agent_key = a.agent and o.active
      join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'auto'
     where a.status = 'pending'
       -- Nothing live and nothing already settled for this item...
       and not exists (select 1 from public.action_execution x
                        where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')
                          and x.status in ('queued','running','succeeded'))
       -- ...and fewer than two attempts have failed. Equality, not LIKE: `_` is a single-character
       -- wildcard in LIKE and 'agent_action:' is full of them, so `like 'agent_action:'||id` would
       -- also match keys this function never wrote.
       and (select count(*) from public.action_execution x
             where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')
               and x.status = 'failed') < 2
     order by a.created_at
     limit greatest(coalesce(p_limit, 10), 1)
  loop
    v_key := 'agent_action:' || r.id || case when r.failures >= 1 then '#2' else '' end;
    insert into public.action_execution(id, correlation_id, action_class, executor, idempotency_key,
                                        risk_tier, reversible, request, status, attempts)
    values (gen_random_uuid(), gen_random_uuid(), 'agent_action_work', 'action_worker',
            v_key, 'low', true,
            jsonb_build_object('action_id', r.id, 'kind', r.kind,
                               'source', 'fn_agent_action_work_sweep',
                               'attempt', r.failures + 1),
            'queued', 0)
    on conflict (idempotency_key) do nothing;
    v_q := v_q + 1;
  end loop;

  return jsonb_build_object('queued', v_q, 'ran_at', now(),
    'eligible_remaining', (select count(*) from public.agent_actions a
                             join public.org_agents o on o.agent_key = a.agent and o.active
                             join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'auto'
                            where a.status = 'pending'
                              and not exists (select 1 from public.action_execution x
                                               where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')
                                                 and x.status in ('queued','running','succeeded'))
                              and (select count(*) from public.action_execution x
                                    where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')
                                      and x.status = 'failed') < 2),
    -- Named separately so "we have stopped trying" is never counted as "we are working on it".
    'exhausted_two_attempts', (select count(*) from public.agent_actions a
                                 join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'auto'
                                where a.status = 'pending'
                                  and (select count(*) from public.action_execution x
                                        where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')
                                          and x.status = 'failed') >= 2),
    'never_auto_settled', (select count(*) from public.agent_actions a
                             join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'founder'
                            where a.status = 'pending'),
    'unrouted', (select count(*) from public.agent_actions a
                  where a.status = 'pending'
                    and not exists (select 1 from public.agent_action_kind_policy p where p.kind = a.kind)));
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_actions_fill_alternatives()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  -- WAS `d record`. A record that is never assigned raises 55000 on the first field reference;
  -- these three are null when the lookup is skipped, and null is answerable.
  v_alts     jsonb;
  v_decision text;
  v_amt      text;
begin
  -- Nothing to do once every field the caller could supply is already there.
  if NEW.alternatives is not null and NEW.assumptions is not null
     and NEW.expected_impact is not null and NEW.cost is not null then
    return NEW;
  end if;

  if NEW.decision_log_id is not null then
    select l.alternatives, l.decision into v_alts, v_decision
      from public.decision_log l where l.id = NEW.decision_log_id;
  end if;

  if NEW.alternatives is null
     and v_alts is not null
     and v_alts::text not in ('null', '[]', '{}') then
    NEW.alternatives := v_alts;
  end if;

  if NEW.assumptions is null then
    NEW.assumptions := jsonb_build_array(
      'The action context recorded in detail is accurate as supplied by ' || coalesce(NEW.agent, 'the agent') || '.',
      'fn_should_escalate and fn_authorize were evaluated on that context'
        || case when v_decision is not null then ' and returned ' || v_decision || '.' else '.' end);
  end if;

  if NEW.expected_impact is null then
    NEW.expected_impact := case
      when coalesce(NEW.status, '') in ('needs_review', 'held_for_review')
        then 'Held: nothing changes until a human decides. Until then the condition this action reports remains as it is.'
      else 'Proceeds as recommended: ' || left(coalesce(NEW.recommendation, NEW.title, 'the recommended action'), 220) end;
  end if;

  if NEW.cost is null then
    begin
      v_amt := nullif(to_jsonb(NEW.detail) ->> 'amount_aed', '');
      if v_amt is null then v_amt := nullif(to_jsonb(NEW.detail) ->> 'amount', ''); end if;
    exception when others then v_amt := null; end;
    NEW.cost := case when v_amt is not null
      then 'AED ' || v_amt || ' — the amount carried in this action''s own context.'
      else 'No spend is recorded in this action''s context; the cost is the reviewer''s time.' end;
  end if;

  return NEW;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_autonomy_blocked(p_agent_key text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with me as (select coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key) as k)
  select jsonb_build_object(
    'agent_key', (select k from me),
    'asked_as', p_agent_key,
    'blocked', exists (select 1 from agent_remediation
                        where agent_key = (select k from me) and blocks_autonomy and status <> 'passed'),
    'open_remediations', coalesce((select jsonb_agg(jsonb_build_object(
        'id', id, 'failure_class', failure_class, 'competency', competency, 'status', status))
      from agent_remediation where agent_key = (select k from me) and status <> 'passed'), '[]'::jsonb),
    'readiness', coalesce((select jsonb_agg(distinct readiness) from org_role_identity
                            where agent_key = (select k from me)), '[]'::jsonb));
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_context(p_agent_key text DEFAULT NULL::text, p_max_chars integer DEFAULT 9000)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare out text := ''; r record; piece text; cap int; own_cap int;
        v_ops jsonb; v_ops_txt text;
        v_dept text; v_role text; v_charter text; v_north text; v_health_fn text;
        v_status text; v_state jsonb; v_l4 text := '';
        v_emp text := ''; v_title text; v_resp text; v_mgr text; v_sen text; v_plan text;
        v_cap_tasks int; v_line text; v_n int; v_os text; v_pad int := 0;
        v_genome text;
        v_risks text;
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  cap := greatest(coalesce(p_max_chars,9000), 22000);
  own_cap := least(cap/2, 6000);
  if p_agent_key is not null then
    select a.department, a.role into v_dept, v_role from org_agents a where a.agent_key=p_agent_key;
    select d.charter, d.north_star, d.health_fn into v_charter, v_north, v_health_fn
      from org_departments d where d.dept_key=v_dept;
    select status into v_status from org_onboarding where agent_key=p_agent_key;
    out := out || '# YOUR IDENTITY AT QUOTESDONE'||E'\n'
      ||'You are '||coalesce(v_role, p_agent_key||' (senior specialist)')
      ||case when v_charter is not null then '. Department charter: '||v_charter else '' end
      ||case when v_north is not null then ' North star: '||v_north||'.' else '' end
      ||' Employment status: '||coalesce(v_status,'onboarding')||'.'||E'\n'
      ||'POSTURE: You are a senior executive employee, not an assistant. DEFAULT TO ACTION: if work falls within your delegated authority (org_authority tiers), execute it completely, then report the result - do not ask permission you already have. Proactively identify work from your charter and live state; do not wait for tasks. Escalate ONLY when an action exceeds your authority, carries material business risk, or hits a constitutional gate (money movement, identity/auth, security and secrets, destructive operations, legal judgment, the autonomy framework itself). Reason from executive judgment first; use the layers to VERIFY facts, never as a substitute for thinking. Quote operational numbers ONLY from LIVE STATE. If two layers conflict, say so explicitly and escalate the contradiction to Knowledge Management. Close every piece of work with the loop: measure the outcome, record the lesson, improve the playbook. If your employment status is not certified, mark your outputs as provisional.'||E'\n\n';

    -- ---- THE COMPANY GENOME (spec layer 9: every employee inherits all eleven attributes) -----
    -- genome-inherited-by-every-employee read 2 of 11 on production. This routine carried
    -- 'values' and 'vision' incidentally and none of the other nine, because it never read
    -- company_constitution at all - it reads org_agents, agent_knowledge, org_tasks and
    -- policy_rules, and no genome store.
    --
    -- A LIST OF HEADINGS WOULD SATISFY THE CHECK AND TEACH NOBODY ANYTHING. All eleven regexes
    -- match on the titles alone, in about 250 characters. That is the accidental pass this row
    -- keeps turning up, so each line carries the doctrine itself and not just its name.
    select string_agg('- '||c.title||': '||left(regexp_replace(c.body, '\s+', ' ', 'g'), 220),
                      E'\n' order by c.article_no)
      into v_genome
      from public.company_constitution c
     where c.title in ('Core values','Vision','Decision principles','Risk appetite',
                       'Hiring philosophy','Brand personality','Customer promises',
                       'Supplier promises','Ethics','Leadership style','Growth strategy');
    if v_genome is not null then
      out := out || '# THE COMPANY GENOME - you inherit every line of this'||E'\n'||v_genome||E'\n\n';
    end if;

    -- ---- WHAT THE COMPANY IS WORRIED ABOUT --------------------------------------------------
    -- ai-conversation-worry asks whether an employee could answer "what worries you most today?"
    -- with the COMPANY'S OWN judgement rather than an improvisation. It could not: risk_register
    -- holds 18 live entries across commercial, customer, financial, legal, operational, security
    -- and supplier, and not one word of them reached any employee. The check tests for a stored
    -- risk appearing VERBATIM in the context, precisely so that naming the topic cannot pass for
    -- carrying the content.
    --
    -- RENDERED RAW, AND THAT IS DELIBERATE. No regexp_replace and no truncation of r.risk: the
    -- longest is 66 characters and the check matches on left(risk, 50), so collapsing whitespace
    -- could silently break the match on a row that happens to contain a double space. The whole
    -- register is only 730 characters of risk text; the mitigation is what makes it actionable
    -- rather than merely alarming, and is capped at 140.
    --
    -- Closed risks are excluded. A risk the company has already dealt with is not a worry, and one
    -- of the closed rows is a fixture.
    -- ALIAS rr, NOT r. This routine already declares `r record` at the top for its own loops, and
    -- plpgsql resolves the identifier to that variable in preference to a table alias — so an
    -- alias of r raised "record r is not assigned yet" and took the whole context down. Caught on
    -- staging, which is the entire reason it goes there first.
    select string_agg('- ['||coalesce(rr.impact,'?')||' impact / '||coalesce(rr.probability,'?')
                      ||' likelihood] '||rr.risk
                      ||case when coalesce(rr.mitigation,'') <> ''
                             then '  -> mitigating: '||left(rr.mitigation, 140) else '' end,
                      E'\n' order by case coalesce(rr.impact,'') when 'high' then 0 when 'medium' then 1 else 2 end,
                                     case coalesce(rr.probability,'') when 'high' then 0 when 'medium' then 1 else 2 end,
                                     rr.id)
      into v_risks
      from public.risk_register rr
     where coalesce(rr.status,'open') in ('open','mitigating') and length(rr.risk) > 20;
    if v_risks is not null then
      out := out || '# WHAT THE COMPANY IS WORRIED ABOUT - its own live risk register'||E'\n'
                 || v_risks||E'\n\n';
    end if;

    -- ---- THE EMPLOYEE OBJECT (spec line 372) --------------------------------------------------
    select a.title, a.responsibilities, a.manager_key, a.seniority, a.improvement_plan, a.max_open_tasks
      into v_title, v_resp, v_mgr, v_sen, v_plan, v_cap_tasks
      from org_agents a where a.agent_key = p_agent_key;

    v_emp := '# YOUR EMPLOYEE RECORD'||E'\n'
      ||'Job title: '||coalesce(v_title,'(untitled)')
      ||'  |  Department: '||coalesce(v_dept,'(unassigned)')
      ||'  |  Seniority: '||coalesce(v_sen,'(unset)')||E'\n';

    -- The reporting line, finally walked. CEO -> Chief of Staff -> Department Heads -> Specialists.
    if v_mgr is not null then
      select 'Reports to: '||m.agent_key||' — '||coalesce(m.title, m.role, 'manager') into v_line
        from org_agents m where m.agent_key = v_mgr;
      v_emp := v_emp || coalesce(v_line, 'Reports to: '||v_mgr) || E'\n';
    else
      v_emp := v_emp || 'Reports to: nobody — you are the top of the reporting line.'||E'\n';
    end if;

    select count(*), string_agg(x.agent_key||' ('||coalesce(x.title, x.role, 'specialist')||')', '; ' order by x.agent_key)
      into v_n, v_line
      from (select b.agent_key, b.title, b.role from org_agents b
             where b.manager_key = p_agent_key and b.active order by b.agent_key limit 12) x;
    if coalesce(v_n,0) > 0 then
      v_emp := v_emp || 'Your direct reports ('||v_n||'): '||v_line||E'\n'
        ||'You are accountable for their output: review it, return poor work for revision, and coach them.'||E'\n';
    end if;

    if v_resp is not null then v_emp := v_emp || 'Your responsibilities: '||left(v_resp, 600)||E'\n'; end if;
    if v_plan is not null then v_emp := v_emp || 'Your improvement plan: '||left(v_plan, 300)||E'\n'; end if;

    -- ---- AUTHORITY LIMITS ----------------------------------------------------------------------
    -- Per-employee first (employee_authority), falling back to the department grant that
    -- cos_execute:170 actually enforces. Stating the ceiling is what makes "escalate only when an
    -- action exceeds your authority" in the POSTURE above an instruction rather than a slogan.
    select string_agg(z.action_class||' -> '||z.max_tier
             ||case when z.threshold_aed is not null then ' (up to '||z.threshold_aed||' AED)' else '' end, '; '
             order by z.action_class)
      into v_line
      from (select e.action_class, e.max_tier, e.threshold_aed from employee_authority e
             where e.agent_key = p_agent_key order by e.action_class limit 14) z;
    if v_line is null then
      select string_agg(z.action_class||' -> '||z.max_tier
               ||case when z.threshold_aed is not null then ' (up to '||z.threshold_aed||' AED)' else '' end, '; '
               order by z.action_class)
        into v_line
        from (select o.action_class, o.max_tier, o.threshold_aed from org_authority o
               where o.dept_key = v_dept order by o.action_class limit 14) z;
      if v_line is not null then
        v_emp := v_emp || E'\n'||'# YOUR AUTHORITY (delegated to '||v_dept||', no personal grant on file)'||E'\n';
      end if;
    else
      v_emp := v_emp || E'\n'||'# YOUR AUTHORITY (granted to you personally)'||E'\n';
    end if;
    if v_line is not null then
      v_emp := v_emp || v_line || E'\n'
        ||'Anything not on that list is GATED: propose it, do not do it.'||E'\n';
    end if;

    -- ---- ESCALATION RULES (blueprint component 5) ----------------------------------------------
    -- The spec requires every employee to have Escalation Rules alongside Role, Authority, KPIs,
    -- Knowledge and Decision Rights. There is no escalation table — only escalations_archive — but
    -- ops_knowledge.escalation_rule carries a real one on 1,206 of its 3,959 records, shaped
    -- {"when": ..., "action": ...}. Its only reader was fn_kb_retrieve, which has ZERO callers
    -- anywhere, so the rules reached nobody.
    --
    -- Read here rather than by widening fn_ops_knowledge_search: that function's return type would
    -- have to change, which needs a DROP, and fn_agent_context itself depends on it. An additive
    -- read is the smaller and safer diff.
    select string_agg(distinct '- when ' || replace(e.escalation_rule->>'when','_',' ')
                             || ' -> ' || replace(e.escalation_rule->>'action','_',' '), E'\n')
      into v_line
      from (select escalation_rule from ops_knowledge
             where dept_key = v_dept
               and escalation_rule is not null
               and escalation_rule ? 'when' and escalation_rule ? 'action'
             limit 40) e;
    if v_line is not null then
      v_emp := v_emp || E'\n'||'# WHEN TO ESCALATE (your department''s recorded rules)'||E'\n'||left(v_line, 700)||E'\n';
    end if;

    -- ---- KPIs: how this employee's work is judged ----------------------------------------------
    select string_agg(z.kpi||' — target '||coalesce(z.target_value::text,'?')||' '||coalesce(z.unit,'')
             ||' ('||coalesce(z.cadence,'ongoing')
             ||case when z.serves_goal is not null then '; serves company goal '||z.serves_goal else '' end||')', E'\n- '
             order by z.kpi)
      into v_line
      from (select k.kpi, k.target_value, k.unit, k.cadence, k.serves_goal from employee_kpi k
             where k.agent_key = p_agent_key and k.active order by k.kpi limit 8) z;
    if v_line is not null then
      v_emp := v_emp || E'\n'||'# YOUR KPIs — this is how your work is measured'||E'\n- '||v_line||E'\n';
    end if;

    -- ---- CURRENT WORKLOAD, measured rather than assumed -----------------------------------------
    -- max_open_tasks is a CAP. This is the LOAD against it, read live at prompt time.
    select 'Your department has '||count(*)||' task(s) in flight ('
           ||count(*) filter (where t.status='assigned')||' assigned, '
           ||count(*) filter (where t.status='in_progress')||' in progress), plus '
           ||(select count(*) from org_tasks p where p.dept_key = v_dept and p.status='proposed')
           ||' awaiting a founder decision. Your personal cap is '||coalesce(v_cap_tasks,0)||' open task(s).'
      into v_line
      from org_tasks t where t.dept_key = v_dept and t.status in ('assigned','in_progress');
    if v_line is not null then
      v_emp := v_emp || E'\n'||'# YOUR CURRENT WORKLOAD (live)'||E'\n'||v_line||E'\n';
      select string_agg('- ['||z.status||'] '||left(z.title,90), E'\n' order by z.id)
        into v_line
        from (select t.id, t.status, t.title from org_tasks t
               where t.dept_key = v_dept and t.status in ('assigned','in_progress')
               order by t.id limit 6) z;
      if v_line is not null then v_emp := v_emp || v_line || E'\n'; end if;
    end if;

    -- ---- WHICH OPERATING SYSTEM YOU BELONG TO (spec file #2) ------------------------------------
    -- The Universal OS Blueprint's first four components — Purpose, Mission, Objectives,
    -- Responsibilities — were all POPULATED and read by NOTHING: operating_system.charter/mandate
    -- and .mission 10/10, os_objective 50 rows (all five horizons for all ten OSes),
    -- os_responsibility 71 rows whose only reader was fn_graph_rebuild. The single view that
    -- exposed them, v_operating_manual, has zero readers itself.
    --
    -- An employee belongs to an OS through org_agents.department -> os_department -> operating_system.
    -- Emitting it here is the same fix that closed row #1: the company knew all of this and never
    -- told the people doing the work.
    --
    -- 4. THE OWNER. 'owner' is one of the seven attributes the blueprint names per OS
    --    (operating_system.owner_agent, 10/10 populated, all ten resolving to a live employee) and
    --    it was the one attribute of the seven that never left the table: fn_os_improve read the
    --    column on a cron, but the block below emitted name/Purpose/Mission/Mandate/OWNS/objectives
    --    and no owner line, so measured across all 66 active employees not one could name who owns
    --    their OS. A responsibility an employee cannot escalate is a responsibility with no route
    --    out, which is what makes this the same defect as the other three: known by the company,
    --    never told to the person doing the work.
    for r in
      select o.os_key, o.name, o.charter, o.mandate, o.mission, o.owner_agent,
             (select coalesce(w.title, w.role) from org_agents w
               where w.agent_key = o.owner_agent and w.active) owner_title,
             (select string_agg(x.responsibility, ', ' order by x.responsibility)
                from (select responsibility from os_responsibility where os_key = o.os_key
                       order by responsibility limit 12) x) resp,
             (select string_agg(y.horizon || ': ' || y.objective, E'\n- '
                       order by case y.horizon when 'strategic' then 1 when 'annual' then 2
                                               when 'quarterly' then 3 when 'weekly' then 4 else 5 end)
                from (select horizon, objective from os_objective
                       where os_key = o.os_key and coalesce(active,true)) y) objectives
        from os_department d
        join operating_system o on o.os_key = d.os_key and coalesce(o.active,true)
       where d.dept_key = v_dept
       limit 1
    loop
      v_os := r.os_key;
      -- Emitted and measured from ONE expression. The line's length is what compensates the layer
      -- budgets below, so a second copy of the text is a copy that can be edited alone and leave
      -- the compensation quietly wrong.
      v_line := case when r.owner_agent is not null
                     then 'Your OS is owned by: '||r.owner_agent
                       ||coalesce(' — '||left(r.owner_title,60), '')
                       ||'. Escalate OS-level decisions there.'||E'\n'
                     else '' end;
      v_pad := length(v_line);
      v_emp := v_emp || E'\n'||'# YOUR OPERATING SYSTEM — '||coalesce(r.name, r.os_key)||E'\n'
        ||case when r.charter is not null then 'Purpose: '||left(r.charter,300)||E'\n' else '' end
        ||case when r.mission is not null then 'Mission: '||left(r.mission,240)||E'\n' else '' end
        ||case when r.mandate is not null then 'Mandate: '||left(r.mandate,240)||E'\n' else '' end
        ||v_line
        ||case when r.resp is not null
               then 'Your OS OWNS, and no other OS may own: '||r.resp||E'\n'
                 ||'If work belongs to another OS, hand it over — do not duplicate it.'||E'\n'
               else '' end
        ||case when r.objectives is not null
               then 'Your OS objectives by horizon:'||E'\n- '||r.objectives||E'\n' else '' end;
    end loop;

    -- THE OWNER LINE IS NOT PAID FOR OUT OF THE KNOWLEDGE BUDGET. LAYER 2 admits a piece while
    -- length(out) + length(piece) <= own_cap + 2200 and LAYER 1 while <= cap, and `out` already
    -- carries the employee record — so 70-97 characters added here come straight off the end of
    -- LAYER 1. Measured on production the first time this line was deployed WITHOUT this
    -- compensation: 19 employees lost a global knowledge topic each, including 'Penalty &
    -- collections model' (priority 94), 'Escalation policy' (93) and 'canon:supplier_status' (93).
    -- That is the file header's own rule — anything inserted before the layers deletes something
    -- already proven to reach an employee — and the owner line is the one insertion that cannot be
    -- moved to the end, because it has to land inside the OS block. So it buys its own space
    -- instead: both budgets grow by exactly the characters it used, which leaves every other
    -- inclusion decision bit-for-bit where it was. v_pad is 0 when no OS block was emitted.
    cap := cap + v_pad;
    own_cap := own_cap + v_pad;

    -- ---- WHAT THE COMPANY IS TRYING TO ACHIEVE ---------------------------------------------------
    -- company_goals was read by dept_plan:79 and by nothing an ordinary employee ever saw. The spec
    -- opens with "Every employee works toward the same business objectives" and "Every decision made
    -- by every AI employee should support these objectives".
    -- goal_period held 183 rows, refreshed daily by fn_goal_period_refresh, and was read by NOTHING
    -- but its own refresher. It carries the only actual-versus-target the company computes, so a
    -- goal without it is an aspiration and a goal with it is a number someone can act on.
    select string_agg(z.goal||' ('||coalesce(z.metric,'no metric')
             ||case when z.target_value is not null then '; target '||z.target_value||' '||coalesce(z.unit,'') else '' end
             ||case when z.actual_value is not null
                    then '; CURRENTLY '||z.actual_value||coalesce(' ('||z.status||')','') else '; not yet measured' end||')', E'\n- '
             order by z.sort nulls last)
      into v_line
      from (select g.goal, g.metric, g.target_value, g.unit, g.sort, gp.actual_value, gp.status
              from company_goals g
              left join lateral (select p.actual_value, p.status from goal_period p
                                  where p.goal_key = g.key
                                  order by p.updated_at desc nulls last limit 1) gp on true
             where g.active and (g.owner_dept is null or g.owner_dept = v_dept or g.owner_dept = 'exec')
             order by g.sort nulls last limit 8) z;
    if v_line is not null then
      v_emp := v_emp || E'\n'||'# COMPANY GOALS YOUR WORK MUST MOVE'||E'\n- '||v_line||E'\n';
    end if;

    select string_agg('- '||z.objective, E'\n' order by z.sort nulls last)
      into v_line
      from (select o.objective, o.sort from department_objective o
             where o.dept_key = v_dept and coalesce(o.active,true) order by o.sort nulls last limit 6) z;
    if v_line is not null then
      v_emp := v_emp || E'\n'||'# YOUR DEPARTMENT''S OBJECTIVES'||E'\n'||v_line||E'\n';
    end if;

    -- ---- THE IMPROVEMENT LOOP, WHICH WROTE WHERE NOTHING READ -------------------------------
    -- Of the seven self-optimisation loops, four wrote into tables nobody consulted:
    -- self_review 31 rows, evolution_proposal 32 (31 proposed, 1 ever implemented), decision_record
    -- 3, company_reflection 9 — each read by nothing but its own writer. The spec's "Continuous
    -- Improvement" section is what they implement, so the department they concern is the reader.
    -- Bounded hard: this is context, not a report.
    select string_agg(z.line, E'\n' order by z.ord, z.line)
      into v_line
      from (
        select 1 ord, '- OPEN FINDING ('||s.review_type||'): '||left(s.finding, 160)
               ||coalesce(' — proposed: '||left(s.proposal,120), '') line
          from self_review s
         where coalesce(s.status,'open') not in ('done','implemented','rejected')
         order by s.created_at desc limit 3
      ) z;
    if v_line is not null then
      v_emp := v_emp || E'\n'||'# WHAT THIS ORGANISATION IS TRYING TO FIX'||E'\n'||v_line||E'\n';
    end if;

    select string_agg('- PROPOSED CHANGE ('||e.change_class||'): '||left(e.proposal, 170), E'\n' order by e.id desc)
      into v_line
      from (select id, change_class, proposal from evolution_proposal
             where status = 'proposed' order by id desc limit 3) e;
    if v_line is not null then
      v_emp := v_emp || v_line || E'\n';
    end if;

    -- decision_record carries serves_goal and the reasoning behind past calls. 3 rows, 0 readers.
    -- "Learn from results" cannot happen if the record of what was decided reaches nobody.
    select string_agg('- '||coalesce(d.decided_by,'someone')||' decided: '||left(d.recommendation, 150)
             ||coalesce(' (serves '||d.serves_goal||')','')
             ||coalesce(' — outcome: '||left(d.actual_outcome,80), ' — outcome not yet recorded'), E'\n' order by d.id desc)
      into v_line
      from (select id, decided_by, recommendation, serves_goal, actual_outcome from decision_record
             where dept_key = v_dept or dept_key is null order by id desc limit 2) d;
    if v_line is not null then
      v_emp := v_emp || E'\n'||'# DECISIONS ALREADY ON RECORD FOR YOUR DEPARTMENT'||E'\n'||v_line||E'\n';
    end if;

    -- company_reflection: 9 rows, written nightly by fn_company_reflect, read by nothing but its
    -- own writer. It is the company asking itself what is going wrong, which is the "Continuous
    -- Improvement" section in one table — and the exec department is who it is for.
    if v_dept = 'exec' then
      select '- '||to_char(c.reflected_on,'DD Mon')||': '||c.concerns||' concern(s), '||c.actions
             ||' action(s) — '||left(coalesce(c.answers->>'biggest_risk', c.answers::text), 200)
        into v_line
        from company_reflection c order by c.reflected_on desc limit 1;
      if v_line is not null then
        v_emp := v_emp || E'\n'||'# THE COMPANY''S OWN LATEST REFLECTION'||E'\n'||v_line||E'\n';
      end if;
    end if;

    out := out || left(v_emp, 6200) || E'\n\n';
  end if;
  if p_agent_key is not null then
    out := out || '# LAYER 2 - YOUR PROFESSIONAL EXPERTISE'||E'\n\n';
    for r in select topic,content from agent_knowledge
             where coalesce(layer,'profession') in ('profession','state')
               and (agent_key = p_agent_key
                    or (v_dept is not null
                        and not exists (select 1 from agent_knowledge k2
                                         where k2.agent_key = p_agent_key
                                           and coalesce(k2.layer,'profession') in ('profession','state'))
                        and agent_key in (select b.agent_key from org_agents b
                                           where b.active and b.department = v_dept
                                             and b.agent_key <> p_agent_key)))
             order by priority desc nulls last, updated_at desc loop
      piece := '## '||coalesce(r.topic,'')||E'\n'||coalesce(r.content,'')||E'\n\n';
      if length(out)+length(piece) <= own_cap + 2200 then out := out||piece; end if;
    end loop;
  end if;
  out := out || '# LAYER 1 - COMPANY KNOWLEDGE (authoritative; pricing marked LIVE overrides any other figure)'||E'\n\n';
  -- TRUNCATE, DO NOT DROP. See the migration header: the per-item guard below compares one
  -- item against the WHOLE-context cap, so "Company FAQ (canonical answers)" — 197,956 chars
  -- at priority 96, the highest global row there is — could never fit and was silently
  -- skipped on every call for every employee.
  for r in select topic,content from agent_knowledge
           where agent_key='_global' and coalesce(priority,0)>=90 order by priority desc nulls last, updated_at desc loop
    piece := '## '||coalesce(r.topic,'')||E'\n'||
             case when length(coalesce(r.content,'')) > 1500
                  then left(r.content, 1500)||E'\n'||'[… truncated here at 1,500 of '
                       ||length(r.content)||' characters. This item exists in full in '
                       ||'agent_knowledge; ask for the rest if you need it.]'
                  else coalesce(r.content,'') end||E'\n\n';
    if length(out)+length(piece) <= cap then out := out||piece; end if;
  end loop;
  for r in select topic,content from agent_knowledge
           where agent_key='_global' and coalesce(priority,0)<90 order by priority desc nulls last, updated_at desc loop
    piece := '## '||coalesce(r.topic,'')||E'\n'||
             case when length(coalesce(r.content,'')) > 1500
                  then left(r.content, 1500)||E'\n'||'[… truncated here at 1,500 of '
                       ||length(r.content)||' characters. This item exists in full in '
                       ||'agent_knowledge; ask for the rest if you need it.]'
                  else coalesce(r.content,'') end||E'\n\n';
    if length(out)+length(piece) <= cap then out := out||piece; end if;
  end loop;
  if v_health_fn is not null then
    begin
      execute format('select %I()', v_health_fn) into v_state;
      piece := '# LAYER 3 - LIVE OPERATIONAL STATE (from '||v_health_fn||' at '||now()::timestamptz(0)||'; the ONLY valid source for operational numbers)'||E'\n'
               ||left(coalesce(v_state::text,'{}'), 2600)||E'\n\n';
      if length(out)+length(piece) <= cap + 3000 then out := out||piece; end if;
    exception when others then
      out := out || '# LAYER 3 - LIVE OPERATIONAL STATE unavailable ('||sqlerrm||'); do not quote operational numbers this turn.'||E'\n\n';
    end;
  end if;
  if p_agent_key is not null then
    for r in select topic, content from agent_knowledge
             where layer='experience' and agent_key in (p_agent_key,'_global')
             order by updated_at desc limit 12 loop
      v_l4 := v_l4 || '## '||coalesce(r.topic,'')||E'\n'||coalesce(r.content,'')||E'\n\n';
    end loop;
    for r in select kind, content from agent_memory m
             where m.agent_key=p_agent_key and m.importance >= 5
               and not exists (select 1 from policy_rules p where p.active and m.content ~* p.forbid_regex)
             order by m.importance desc, m.created_at desc limit 8 loop
      v_l4 := v_l4 || '## memory ('||r.kind||')'||E'\n'||r.content||E'\n\n';
    end loop;
    v_l4 := v_l4 || coalesce(public.fn_agent_institutional_memory(p_agent_key, 6), '');
    if v_l4 <> '' then
      out := out || '# LAYER 4 - WHAT THIS ORGANIZATION HAS LEARNED'||E'\n\n'|| left(v_l4, 3500);
    end if;
  end if;
  -- ---- THE OS LAYER'S THREE UNREAD OUTPUTS ------------------------------------------------------
  -- Appended at the END on purpose. v_emp is truncated at 6,200 characters and LAYER 2 is budgeted
  -- against length(out); adding any of this earlier would silently delete something already proven
  -- to reach the employee. An output landing exactly on a ceiling is truncation, not coincidence.
  if v_os is not null then
    -- os_objective.measure was a LABEL on all 50 rows — 'gl_journal', 'qualified pipeline',
    -- 'KPI instrumentation'. A label cannot be met or missed. measure_sql now resolves to a number
    -- on a daily cron and this is the only place that number reaches a person.
    select string_agg(z.horizon||': '||z.objective||' — reads '
             ||coalesce(z.actual_value::text,'no value')
             ||coalesce(' (measured '||to_char(z.measured_at,'DD Mon')||')', ' (measure failed)'),
             E'\n- '
             order by case z.horizon when 'strategic' then 1 when 'annual' then 2
                                     when 'quarterly' then 3 when 'weekly' then 4 else 5 end)
      into v_line
      from (select horizon, objective, actual_value, measured_at from os_objective
             where os_key = v_os and coalesce(active,true)) z;
    if v_line is not null then
      out := out || E'\n'||'# YOUR OS OBJECTIVES, MEASURED (the number, not the aspiration)'
             ||E'\n- '||left(v_line, 1600)||E'\n';
    end if;

    -- OS.txt line 109: "Leadership OS should not duplicate this knowledge; it queries Finance OS
    -- when needed." os_knowledge_domain wrote that routing down 315 times and nothing resolved it;
    -- its only reader, fn_knowledge_gaps, takes no os_key and cannot answer "who owns this".
    v_line := public.fn_os_knowledge_query(v_os);
    if coalesce(v_line,'') <> '' then
      out := out || E'\n'||'# KNOWLEDGE YOUR OS DOES NOT OWN — QUERY THE OWNER, DO NOT DUPLICATE IT'
             ||E'\n'||left(v_line, 1300)||E'\n';
    end if;

    -- workflow_run and workflow_step_run were 0 rows with 0 readers while workflow held 14 active
    -- definitions and workflow_step 117 steps. A run nobody can see is the diagram again.
    select string_agg('- '||coalesce(w.name, x.workflow_key)||': step '||coalesce(x.current_step,0)
             ||' of '||(select count(*) from workflow_step s where s.workflow_key = x.workflow_key)
             ||' ('||x.status||')'
             ||coalesce(' — now: '||(select sr.input->>'step' from workflow_step_run sr
                                      where sr.workflow_run_id = x.id
                                        and sr.step_no = x.current_step), ''),
             E'\n' order by x.started_at desc nulls last)
      into v_line
      -- THE LIMIT MUST SIT AFTER THE FILTER, NOT BEFORE IT. This subquery used to take the 8
      -- newest runs COMPANY-WIDE and only then join workflow and filter on os_key, so the moment
      -- one OS owned all 8 newest runs every other OS's employees saw nothing. Measured on
      -- production 6 Aug 2026: all 8 newest in-flight runs were operations, while intelligence had
      -- 19 running, leadership 12, evolution 6 and knowledge 2 — and not one of those employees'
      -- prompts carried this section. The os_key filter now sits INSIDE the subquery so the 8 is
      -- per-OS; the outer join and where are left in place so the emitted text is byte-identical
      -- for an OS that was already inside the company-wide window.
      from (select r2.id, r2.workflow_key, r2.current_step, r2.status, r2.started_at
              from workflow_run r2 join workflow w2 on w2.workflow_key = r2.workflow_key
             where r2.status in ('queued','running') and w2.os_key = v_os
             order by r2.started_at desc nulls last limit 8) x
      join workflow w on w.workflow_key = x.workflow_key
     where w.os_key = v_os;
    if v_line is not null then
      out := out || E'\n'||'# YOUR OS''S WORKFLOWS IN FLIGHT (workflow_run)'||E'\n'
             ||left(v_line, 900)||E'\n'
             ||'Close a step with fn_workflow_step_done(run, step_no, output).'||E'\n';
    end if;
  end if;

  -- ---- THE TARGET OPERATING MODEL — the Company Operations pack, finally addressed to a person ---
  -- ops_kb_stage carries twelve relational projections of the pack (departments, roles, sops, kpis,
  -- workflows, handoffs, event_subscriptions, live_bindings, scenarios, templates, decision_rules,
  -- exception_playbooks) and on 2026-08-10 not one of them had a runtime reader:
  -- fn_ops_department_context, the only function that reads them, had ZERO callers. That is the
  -- same defect as the 115,148 knowledge records that sat in kb_stage while every customer path
  -- read kb_chunks — complete, enabled, unread.
  --
  -- Bounded HARD. agent_brain times out around 56 s on a ~30,800-token prompt; the handoff inbox
  -- that caused two of those timeouts added 2,082 characters and is now capped at 647. This block
  -- is a DIGEST plus a pointer, not the corpus: the full text stays one call away in
  -- fn_ops_department_context(dept, topic). Cap below: 900 characters.
  if v_dept is not null then
    v_ops := public.fn_ops_department_context(v_dept, null, 2);
    if v_ops is not null and jsonb_array_length(coalesce(v_ops->'target_departments','[]'::jsonb)) > 0 then
      v_ops_txt := 'Your department maps to '
        || (select string_agg(t, ', ') from jsonb_array_elements_text(v_ops->'target_departments') t)
        || ' in the target operating model: '
        || jsonb_array_length(v_ops->'sops') || ' SOP(s), '
        || jsonb_array_length(v_ops->'decision_rules') || ' decision rule(s), '
        || jsonb_array_length(v_ops->'exception_playbooks') || ' exception playbook(s), '
        || jsonb_array_length(v_ops->'kpis') || ' KPI(s), '
        || jsonb_array_length(v_ops->'handoffs') || ' handoff(s), '
        || jsonb_array_length(v_ops->'templates') || ' template(s).' || E'\n';

      -- the two highest-priority decision rules, which is what actually changes a decision
      select coalesce(string_agg('- RULE ' || coalesce(d->>'rule_id','?') || ': when ' ||
               left(coalesce(d->>'when',''),110) || ' -> ' || left(coalesce(d->>'then',''),110) ||
               case when coalesce((d->>'requires_human_review')::boolean,false)
                    then ' [needs human review]' else '' end, E'\n'), '')
        into v_line from (select d from jsonb_array_elements(v_ops->'decision_rules') d limit 2) z;
      if coalesce(v_line,'') <> '' then v_ops_txt := v_ops_txt || v_line || E'\n'; end if;

      -- who you hand work to and who hands it to you: the pack's cross-department contract
      select coalesce(string_agg('- ' || (h->>'direction') || ' ' || coalesce(h->>'workflow','') ||
               ' (' || coalesce(h->>'from','?') || ' -> ' || coalesce(h->>'to','?') || '): ' ||
               left(coalesce(h->>'you_must',''),90), E'\n'), '')
        into v_line from (select h from jsonb_array_elements(v_ops->'handoffs') h limit 2) z;
      if coalesce(v_line,'') <> '' then v_ops_txt := v_ops_txt || v_line || E'\n'; end if;

      -- the events the target model says this department consumes. NOT live on the bus, and said
      -- so rather than implied: all 100 pack subscriptions carry active=false.
      select coalesce(string_agg(e->>'event', ', '), '')
        into v_line from (select e from jsonb_array_elements(v_ops->'event_subscriptions') e limit 6) z;
      if coalesce(v_line,'') <> '' then
        v_ops_txt := v_ops_txt || 'Events your target model consumes (NOT yet activated on the live bus): '
                     || v_line || E'\n';
      end if;

      out := out || E'\n' || '# HOW YOUR DEPARTMENT IS DEFINED IN THE TARGET OPERATING MODEL'
             || E'\n' || left(v_ops_txt, 900) || E'\n'
             || 'Full text: select fn_ops_department_context(''' || v_dept || ''', <your topic>).' || E'\n';
    end if;
  end if;

  return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_context(p_agent_key text, p_max_chars integer, p_query text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare out text; v_dept text; lib text := ''; ops text := ''; r record; r2 record;
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  out := public.fn_agent_context(p_agent_key, p_max_chars);
  if p_agent_key is null or coalesce(p_query,'') = '' then return out; end if;
  select a.department into v_dept from org_agents a where a.agent_key = p_agent_key;
  for r in
    with hits as (
      select 1 as ord, s.* from public.fn_dept_library_search(v_dept, p_query, 4) s
      union all
      select 2 as ord, s.* from public.fn_dept_library_search('company', p_query, 2) s
    ), uniq as (
      select distinct on (id) id, title, content, ord, rank from hits order by id, ord
    )
    select title, content from uniq order by ord, rank desc
  loop
    exit when length(lib) > 2600;
    lib := lib || '## ' || coalesce(r.title,'') || E'\n' || left(coalesce(r.content,''), 700) || E'\n\n';
  end loop;
  if lib <> '' then
    out := out || E'\n' ||
      '# LAYER 2b - YOUR DEPARTMENT REFERENCE LIBRARY (retrieved from dept_library for this task; cite the title in [brackets] when you use it)' ||
      E'\n\n' || lib;
  end if;

  for r2 in
    select title, content, record_type, authority_tier, implementation_status, rank
      from public.fn_ops_knowledge_search(v_dept, p_query, 5)
     order by rank desc
  loop
    exit when length(ops) > 2400;
    ops := ops || '## [' || coalesce(r2.record_type,'record') || ' · authority: ' ||
           coalesce(r2.authority_tier,'?') || ' · ' || coalesce(r2.implementation_status,'?') || '] ' ||
           coalesce(r2.title,'') || E'\n' || left(coalesce(r2.content,''), 700) || E'\n\n';
  end loop;
  if ops <> '' then
    out := out || E'\n' ||
      '# LAYER 2c - HOW THIS COMPANY OPERATES (your department''s own SOPs, decision rules, exception playbooks and KPI definitions). ' ||
      'These OVERRIDE generic practice. Respect the authority tier on each: gated means it needs approval, ' ||
      'supervised means a human reviews it, autonomous means you may act. A record marked target_state describes ' ||
      'a capability the company has NOT built yet — plan around it, do not assume it exists.' ||
      E'\n\n' || ops;
  end if;

  -- LAYER 2d/2e/2f: the V3 delivery. Added here rather than in a new function because this is
  -- the path every agent already calls; a second assembler would have been a corpus no runtime
  -- function reads. fn_agent_context_v3 does the deterministic filtering and the budgeting.
  declare v3 jsonb; sec text := ''; itm jsonb; begin
    v3 := public.fn_agent_context_v3(p_agent_key, null, p_query, null, 9000);
    if v3 ? 'role_knowledge' then
      for itm in select * from jsonb_array_elements(v3->'role_knowledge') loop
        exit when length(sec) > 2400;
        sec := sec || '## ' || coalesce(itm->>'title','') || ' [' || coalesce(itm->>'record_id','') || ']' || E'
'
            || left(coalesce(itm->>'content',''), 700) || E'

';
      end loop;
      if sec <> '' then
        out := out || E'
' ||
          '# LAYER 2d - YOUR PROFESSIONAL ROLE KNOWLEDGE (the packaged role identity you hold: purpose, ' ||
          'competencies, expert decision checklist and evidence contract). Cite the [record_id] you use.'
          || E'

' || sec;
      end if;
    end if;

    sec := '';
    for itm in select * from jsonb_array_elements(coalesce(v3->'deterministic_rules','[]'::jsonb)) loop
      exit when length(sec) > 2000;
      sec := sec || '- [' || coalesce(itm->>'record_id','') || ' · ' || coalesce(itm->>'layer','') ||
             ' · authority ' || coalesce(itm->>'authority_tier','?') || '] ' || coalesce(itm->>'title','') || E'
';
    end loop;
    if sec <> '' then
      out := out || E'
' ||
        '# LAYER 2f - DETERMINISTIC RULES THAT BIND YOU (authority, policy, decision playbooks, KPI ' ||
        'definitions). These are looked up as structured records, never inferred from similarity. If a ' ||
        'rule here contradicts anything above, the rule wins.' || E'

' || sec;
    end if;

    sec := '';
    for itm in select * from jsonb_array_elements(coalesce(v3->'live_data_required','[]'::jsonb)) loop
      exit when length(sec) > 900;
      sec := sec || '- ' || coalesce(itm->>'title','') || E'
';
    end loop;
    if sec <> '' then
      out := out || E'
' ||
        '# LAYER 2g - FACTS YOU MUST FETCH, NOT REMEMBER. For each of these the current value comes from ' ||
        'a live authorised tool. Answering one of them from the text above is a wrong answer, however ' ||
        'confident it reads.' || E'

' || sec;
    end if;
    -- The trace has to be able to name what was read. Recorded here because this is where
    -- the assembled context and its record ids are both in scope. A STABLE function may not
    -- execute an INSERT, which is why this one and its caller are now VOLATILE.
    perform public.fn_record_context_retrieval(
      p_agent_key, null, null,
      (select array_agg(x) from jsonb_array_elements_text(coalesce(v3->'knowledge_ids','[]'::jsonb)) x),
      p_max_chars, length(out));
  end;
  return out;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_context_capped(p_agent_key text, p_max_chars integer DEFAULT 9000, p_query text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_want   int := greatest(coalesce(p_max_chars, 9000), 500);
  v_raw    text;
  v_l2     int;
  v_head   text; v_tail text;
  v_room   int;
  v_note   text;
  v_stored text;
  c_head_max_age constant interval := interval '3 hours';
  v_reserve constant int := 4500;
  v_mark   constant text := E'\n# --- END STABLE CONTEXT ---\n';
  -- THE RESOLVED KEY. Everything below uses this, never the raw argument: the stored-prefix lookup
  -- keys on it too, or an alias would miss the cache it should hit and rebuild the head every call.
  v_key    text;
  v_live   boolean;
begin
  v_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);

  select a.active into v_live from public.org_agents a where a.agent_key = v_key;
  if v_live is null then
    return '[No such employee: ' || coalesce(p_agent_key,'(null)') || '. It resolves to nothing in '
        || 'org_agents or org_agent_alias, so there is no identity, no authority and no knowledge '
        || 'to assemble. Do not proceed as though there were.]' || v_mark;
  end if;
  if not v_live then
    return '[Employee ' || v_key || ' is INACTIVE — merged away or stood down. No context is '
        || 'assembled for an inactive employee, because a context is what lets one act. Address '
        || 'the surviving role instead.]' || v_mark;
  end if;

  if p_query is null or btrim(p_query) = '' then
    v_raw := public.fn_agent_context(v_key, v_want);
  else
    v_raw := public.fn_agent_context(v_key, v_want, p_query);

    -- Fail-open: no row, a stale row, or a different budget all fall through to the live head
    -- computed below, which is exactly the pre-14-Aug behaviour.
    if v_want = 24000 then
      select h.head into v_stored from agent_context_head h
       where h.agent_key = v_key and h.built_at > now() - c_head_max_age
         and h.head_chars = 19500;
    end if;
  end if;

  if v_raw is null then return null; end if;

  v_l2 := position('# LAYER 2b' in v_raw);

  -- No query-matched tail: the whole thing is standing context and is stable as it is.
  if v_l2 = 0 then
    if length(v_raw) <= v_want then return v_raw || v_mark; end if;
    return left(v_raw, v_want - 110) || v_mark ||
      E'\n[context truncated to the ' || v_want || ' characters requested; ' || length(v_raw) ||
      ' were available. No retrieved department layer was present, so this cut is positional.]';
  end if;

  v_head := substr(v_raw, 1, v_l2 - 1);   -- standing context: identity, expertise, company, live
  v_tail := substr(v_raw, v_l2);          -- LAYER 2b + 2c, retrieved for THIS question

  -- Everything fits: nothing is trimmed and the head is whole.
  if length(v_raw) <= v_want then return v_head || v_mark || v_tail; end if;

  v_room := v_want - v_reserve;           -- FIXED. Does not depend on this question's retrieval.

  if v_room < 600 then
    -- The budget cannot fit the standing context at all. Keep what answers the question.
    return E'[Standing context omitted in full: the ' || v_want || '-character budget does not fit '
      || 'it alongside the material retrieved for this question. Identity, expertise, company '
      || 'knowledge and live state are NOT below - do not assert anything about them.]' || v_mark
      || left(v_tail, greatest(v_want - 300, 400));
  end if;

  v_note := E'\n[Standing context trimmed to the first ' || v_room || ' characters of '
         || length(v_head) || '. What follows was retrieved for this specific question. If you '
         || 'need the omitted background, say so rather than guessing at it.]\n';

  -- head is left() to a CONSTANT length, so for a given agent and budget these bytes are identical
  -- on every call. Everything that varies - the note's digits, the retrieved layers - is after the
  -- marker.
  return coalesce(v_stored, left(v_head, v_room)) || v_mark || v_note ||
         case when length(v_tail) > v_reserve
              then left(v_tail, v_reserve - 120) ||
                   E'\n[retrieved material truncated at ' || v_reserve || ' characters]'
              else v_tail end;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_context_head_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record; v_head text; v_md5 text; v_prev text;
  n_seen int := 0; n_changed int := 0; n_failed int := 0;
begin
  -- Only employees that have actually reasoned recently. Refreshing all 93 would spend a minute of
  -- CPU an hour building prefixes nothing reads; an employee that starts working is picked up on
  -- the next tick and serves live context until then, which is what it gets today anyway.
  for r in
    select distinct c.agent_key
      from ai_cost_log c
     where c.fn = 'agent_brain' and c.agent_key is not null
       and c.occurred_at > now() - interval '14 days'
  loop
    begin
      v_head := left(public.fn_agent_context(r.agent_key, 24000), 19500);
      if v_head is null or length(v_head) < 500 then n_failed := n_failed + 1; continue; end if;
      n_seen := n_seen + 1;
      v_md5  := md5(v_head);
      -- Read the prior hash BEFORE the upsert: asking afterwards always says "unchanged", because
      -- the upsert has already written the value being compared against.
      select h.head_md5 into v_prev from agent_context_head h where h.agent_key = r.agent_key;
      if v_prev is distinct from v_md5 then n_changed := n_changed + 1; end if;
      insert into agent_context_head (agent_key, head, head_md5, head_chars)
      values (r.agent_key, v_head, v_md5, length(v_head))
      on conflict (agent_key) do update
        set head       = excluded.head,
            head_md5   = excluded.head_md5,
            head_chars = excluded.head_chars,
            built_at   = now(),
            changed_at = case when agent_context_head.head_md5 = excluded.head_md5
                              then agent_context_head.changed_at else now() end;
    exception when others then
      -- One employee whose context cannot be built must not stop the other thirteen.
      n_failed := n_failed + 1;
    end;
  end loop;
  return jsonb_build_object('refreshed', n_seen, 'changed', n_changed, 'failed', n_failed);
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_context_v3(p_agent_key text, p_task_class text DEFAULT NULL::text, p_task_text text DEFAULT NULL::text, p_category_key text DEFAULT NULL::text, p_budget_chars integer DEFAULT 24000)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_agent      record;
  v_identity   jsonb;
  v_pkg_dept   text;
  v_role_ids   text[];
  v_out        jsonb;
  v_ids        text[] := '{}';
  v_used       integer := 0;
  v_budget     integer := greatest(coalesce(p_budget_chars, 24000), 2000);
  v_q          tsquery;
  v_scope      text[];
  v_role       record;
begin
  -- RESOLVE BEFORE CONTEXT ASSEMBLY (14 Aug 2026).
  --
  -- This lookup was `where a.agent_key = p_agent_key` against org_agents, so it only ever answered
  -- to a runtime agent_key. Measured: fn_agent_context_v3('chief_of_staff') returned
  -- {"error":"unknown agent"} - and chief_of_staff is not a stale string, it is brief's own
  -- role_id in org_role. fn_org_agent_resolve('chief_of_staff') has always returned 'brief'.
  --
  -- This is the hottest path in the company: agent_brain, action_worker, dept_plan, agent_act and
  -- exec_agents all assemble context through here. An employee addressed by its canonical role id,
  -- a merged-away key, a packaged role id or a job title got no context at all - not a failure,
  -- an empty prompt - while the resolver that answers all four sat one call away.
  --
  -- Section 2 of the closure brief requires identity to be resolved BEFORE context assembly. This
  -- is that line. coalesce keeps an unknown key unknown, so the refusal below still fires.
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);

  select a.agent_key, a.department, a.role, a.title, a.manager_key, a.seniority,
         a.responsibilities, a.max_open_tasks, a.active, d.name dept_name, d.charter, d.north_star
    into v_agent
    from org_agents a
    left join org_departments d on d.dept_key = a.department
   where a.agent_key = p_agent_key;

  if v_agent.agent_key is null then
    return jsonb_build_object('error', 'unknown agent', 'agent_key', p_agent_key);
  end if;

  v_scope := public.fn_dept_scope(v_agent.department);

  select array_agg(packaged_role_id order by packaged_role_id), min(packaged_department)
    into v_role_ids, v_pkg_dept
    from org_role_identity where agent_key = p_agent_key;

  -- The canonical role. Runtime mode, owned and forbidden decisions, activation, contracts,
  -- handoffs, escalation and committee seats are the reorganisation reaching the model.
  select r.role_id, r.display_name, r.runtime_mode, r.authority_level, r.owned_decisions,
         r.forbidden_decisions, r.activation_conditions, r.output_contracts, r.handoff_targets,
         r.escalation_targets, r.manager_role_id, r.budget_limit, r.evaluation_suite,
         (select coalesce(jsonb_agg(jsonb_build_object('committee', c.committee_key, 'seat', c.seat)
                                    order by c.committee_key), '[]'::jsonb)
            from org_role_committee c where c.role_id = r.role_id) as committees
    into v_role
    from org_role r where r.runtime_agent_key = p_agent_key and r.status = 'active';

  -- 1. IDENTITY — who the agent is, who it reports to, what it may decide.
  v_identity := jsonb_build_object(
    'agent_key', v_agent.agent_key,
    'title', coalesce(v_agent.title, v_agent.role),
    'department', v_agent.department,
    'department_name', v_agent.dept_name,
    'department_charter', v_agent.charter,
    'department_north_star', v_agent.north_star,
    'department_knowledge_scope', to_jsonb(v_scope),
    'manager', v_agent.manager_key,
    'seniority', v_agent.seniority,
    'responsibilities', v_agent.responsibilities,
    'packaged_role_ids', coalesce(to_jsonb(v_role_ids), '[]'::jsonb),
    'packaged_department', v_pkg_dept,
    'readiness', (select jsonb_agg(distinct readiness) from org_role_identity where agent_key = p_agent_key),
    -- ONE ROW PER ACTION CLASS. Scoping across the merged keys returns the same action_class once
    -- per predecessor department — 157 entries for a Growth role where 67 classes exist — and an
    -- agent reading three different tiers for the same class would pick whichever it saw first.
    -- Most restrictive wins: advisory < gated < supervised < autonomous.
    'authority', coalesce((
      select jsonb_agg(jsonb_build_object('action_class', action_class, 'max_tier', max_tier,
                                          'threshold_aed', threshold_aed) order by action_class)
        from (select distinct on (action_class) action_class, max_tier, threshold_aed
                from org_authority where dept_key = any(v_scope)
               order by action_class,
                        case max_tier when 'advisory' then 1 when 'gated' then 2
                                      when 'supervised' then 3 else 4 end,
                        threshold_aed nulls first) a), '[]'::jsonb),
    'max_open_tasks', v_agent.max_open_tasks)
    || case when v_role.role_id is null then '{}'::jsonb else jsonb_build_object(
         'role_id', v_role.role_id,
         'role_display_name', v_role.display_name,
         'runtime_mode', v_role.runtime_mode,
         'authority_level', v_role.authority_level,
         'owned_decisions', to_jsonb(v_role.owned_decisions),
         'forbidden_decisions', to_jsonb(v_role.forbidden_decisions),
         'activation_conditions', v_role.activation_conditions,
         'output_contracts', to_jsonb(v_role.output_contracts),
         'handoff_targets', to_jsonb(v_role.handoff_targets),
         'escalation_targets', to_jsonb(v_role.escalation_targets),
         'manager_role_id', v_role.manager_role_id,
         'budget_limit_aed', v_role.budget_limit,
         'evaluation_suite', v_role.evaluation_suite,
         'committees', v_role.committees) end;

  if p_task_text is not null and length(p_task_text) > 1 then
    v_q := public.fn_task_tsquery(p_task_text);
  end if;

  -- 2. DETERMINISTIC RULES — structured, complete, never similarity-ranked.
  with rules as (
    select record_id, layer, record_type, title, structured_data, authority_tier, risk_level,
           version, source_freshness, effective_date, review_after
      from ops_knowledge
     where runtime_eligible
       and supersession_state = 'current'
       and layer in ('authority','kpi','decision_playbook','policy')
       and (
         (scope_type = 'company')
         or (scope_type = 'department' and dept_key = any(v_scope))
         or (role_key = any(coalesce(v_role_ids, '{}')))
         or (p_category_key is not null and category_key = p_category_key)
       )
     order by case layer when 'authority' then 0 when 'policy' then 1 when 'decision_playbook' then 2 else 3 end,
              record_id
     limit 60
  )
  select jsonb_agg(to_jsonb(r)), array_agg(r.record_id) into v_out, v_ids from rules r;
  v_out := jsonb_build_object('deterministic_rules', coalesce(v_out, '[]'::jsonb));
  v_ids := coalesce(v_ids, '{}');

  -- 3. NARRATIVE — company core, then department, then role, then category, each cut to a
  --    share of the budget so no single layer can crowd the others out of the prompt.
  v_out := v_out
    || jsonb_build_object('company_core', fn_context_slice(null, null, null, 'company_core', v_q, v_budget / 6))
    || jsonb_build_object('department_knowledge', fn_context_slice(v_agent.department, null, null, 'department_shared', v_q, v_budget / 3))
    || jsonb_build_object('role_knowledge', fn_context_slice(null, v_role_ids, null, 'role_specific', v_q, v_budget / 3))
    || jsonb_build_object('category_knowledge',
         case when p_category_key is null then '[]'::jsonb
              else fn_context_slice(null, null, p_category_key, 'category_specialist', v_q, v_budget / 6) end);

  -- 4. VALIDATED EXPERIENCE — only lessons a manager or evaluator has validated. A proposed
  --    lesson is deliberately invisible here; that is the whole point of the two states.
  v_out := v_out || jsonb_build_object('validated_experience', coalesce((
      select jsonb_agg(jsonb_build_object('id', id, 'topic', topic, 'content', left(content, 1200),
                                          'confidence', confidence, 'valid_until', valid_until))
        from (select * from agent_knowledge
               where agent_key = p_agent_key
                 and layer = 'experience'
                 and validation_status = 'validated'
                 and (valid_until is null or valid_until >= current_date)
               order by coalesce(confidence, 0) desc, updated_at desc nulls last
               limit 8) e), '[]'::jsonb));

  -- 5. LIVE DATA BINDINGS — what the agent must fetch rather than remember. The binding is
  --    knowledge; the value is not, and is never cached here.
  v_out := v_out || jsonb_build_object('live_data_required', coalesce((
      select jsonb_agg(jsonb_build_object('record_id', record_id, 'title', title,
                                          'binding', structured_data))
        from ops_knowledge
       where record_type = 'live_data_binding' and runtime_eligible
         and supersession_state = 'current'
         and (scope_type = 'company' or dept_key = any(v_scope))
       limit 12), '[]'::jsonb));

  -- 6. TOOLS the agent is actually allowed to execute.
  v_out := v_out || jsonb_build_object('tools', coalesce((
      select jsonb_agg(jsonb_build_object('action_class', action_class, 'kind', kind,
                                          'risk_tier', risk_tier, 'reversible', reversible,
                                          'required_authority', required_authority,
                                          'notifies_human', notifies_human))
        from org_action_executor
       where active and (department = any(v_scope) or target = p_agent_key)
       limit 30), '[]'::jsonb));

  -- collect every knowledge id the assembly actually used
  select v_ids || coalesce(array_agg(x), '{}') into v_ids
    from (select jsonb_array_elements(coalesce(v_out->'company_core','[]'::jsonb) ||
                                      coalesce(v_out->'department_knowledge','[]'::jsonb) ||
                                      coalesce(v_out->'role_knowledge','[]'::jsonb) ||
                                      coalesce(v_out->'category_knowledge','[]'::jsonb)) ->> 'record_id' x) s;

  return jsonb_build_object(
    'identity', v_identity,
    'task_class', p_task_class,
    'category_key', p_category_key,
    'company_objective', coalesce((
      select jsonb_agg(jsonb_build_object('key', key, 'goal', goal, 'metric', metric,
                                          'target', target_value, 'unit', unit, 'period', period,
                                          'owner_dept', owner_dept, 'horizon', horizon))
        from (select * from company_goals
               where active
               order by (owner_dept is not distinct from v_agent.department) desc,
                        (category = 'Financial') desc, sort
               limit 8) g), '[]'::jsonb),
    'budget_chars', v_budget,
    'knowledge_ids', to_jsonb(v_ids),
    'knowledge_count', coalesce(array_length(v_ids, 1), 0),
    'assembled_at', now()
  ) || v_out;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_decision(p_agent text, p_kind text, p_title text, p_recommendation text, p_confidence numeric DEFAULT NULL::numeric, p_evidence jsonb DEFAULT '[]'::jsonb, p_risk text DEFAULT 'low'::text, p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_sensitive boolean; v_escalate boolean; v_reason text; v_status text; v_id bigint;
begin
  v_sensitive := (p_kind ~* 'legal|financ|complian|security|payment|refund|payout|pricing|price'
                  or p_agent ~* 'legal|security|finance|compliance');
  v_escalate := (coalesce(p_confidence,0) < 0.6) or v_sensitive;
  v_reason := case
    when coalesce(p_confidence,0) < 0.6 and v_sensitive then 'Low confidence and sensitive domain — human review required.'
    when coalesce(p_confidence,0) < 0.6 then 'Confidence below 0.60 threshold — human review required.'
    when v_sensitive then 'Sensitive domain (legal/financial/compliance/security) — human review required.'
    else null end;
  v_status := case when v_escalate then 'needs_review' else 'pending' end;

  insert into public.agent_actions(agent,kind,status,risk,title,recommendation,detail,
                                   confidence,evidence,escalated,escalation_reason,created_at)
  values (p_agent,p_kind,v_status,p_risk,p_title,p_recommendation,p_detail,
          p_confidence,coalesce(p_evidence,'[]'::jsonb),v_escalate,v_reason, now())
  returning id into v_id;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_handoff_inbox(p_agent_key text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select string_agg(line, E'\n' order by created_at)
  from (
    select a.created_at,
           -- Bound the WHOLE line, not its parts. Capping title and recommendation separately
           -- still left four employees over budget because the prefix varies ("from Document
           -- Controller" is longer than "doc_task"). 215 x 3 lines + 2 newlines = 647, inside the
           -- 678 this inbox was trimmed to after it timed agent_brain out twice.
           left(
           '- #'||a.id||' ('||extract(day from now() - a.created_at)::int||'d old, '
             ||case when a.kind = 'handoff'
                    then 'from '||coalesce(a.detail->>'from_name', a.detail->>'from', 'a colleague')
                    else a.kind end
             ||case when a.kind = any(fn_agent_inbox_closable_kinds()) then '' else ', FOUNDER DECIDES — do not close' end
             ||'): '
             -- The TITLE was never capped, only the recommendation. With handoffs only that was
             -- harmless; the wider kinds carry long generated titles and the block measured 821
             -- characters for `docs` and 769 for `it` — both ABOVE the 678 this inbox was trimmed
             -- to after it timed agent_brain out twice at ~56s. `it`'s prompt is 30,821 tokens and
             -- its one prior success took 53,139 ms, so the margin is real and small. Capped at 80
             -- so three lines cannot exceed roughly the budget that was proved safe.
             ||coalesce(a.title,'(untitled)')
             ||coalesce(' — '||a.recommendation, '')
           , 215) as line
      from agent_actions a
     where coalesce(public.fn_org_agent_resolve(a.agent), a.agent)
         = coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key)
       and a.status in ('pending','needs_review')
     order by a.created_at
     limit 3
  ) z;
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_inbox_closable_kinds()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select array(
    select distinct kind from public.agent_actions
     where kind is not null
       and lower(kind) !~ '(refund|payout|charge|payment|transfer|chargeback)'
    union
    select unnest(array['handoff','improvement_question','knowledge_task','ai_improvement',
      'report_recommendation','ops_recommendation','doc_task','report_task','objective_step',
      'supply_health','autonomy_stall','legal_flag','security_incident','customer_escalation',
      'compliance_update','strategy_rec','marketing_recommendation','incident','prompt_approval',
      'decision.route_category','finance_alert','finance_marketing_budget'])
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_institutional_memory(p_agent_key text, p_limit integer DEFAULT 6)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_dept text; v_cat text; out text := ''; r record;
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  if p_agent_key is null then return ''; end if;

  select department into v_dept from org_agents where agent_key = p_agent_key;
  if p_agent_key like 'cat:%' then v_cat := replace(p_agent_key, 'cat:', ''); end if;

  for r in
    select m.kind, m.headline, m.detail, m.outcome, m.money_aed, m.category_slug, m.confidence
    from institutional_memory m
    where (m.visible_to is null
           or array_length(m.visible_to,1) is null
           or 'all' = any(m.visible_to)
           or v_dept = any(m.visible_to)
           or p_agent_key = any(m.visible_to))
      and (m.category_slug is null or m.category_slug = v_cat)
      and coalesce(m.confidence, 1) >= 0.6
    order by coalesce(m.occurred_at, m.created_at) desc, coalesce(m.confidence,0) desc
    limit greatest(coalesce(p_limit,6), 1)
  loop
    out := out || '## lesson (' || coalesce(r.kind,'note') || ')' || E'\n'
        || coalesce(r.headline,'') || E'\n'
        || left(coalesce(r.detail,''), 600)
        || case when r.outcome is not null then E'\n' || 'What changed as a result: ' || left(r.outcome, 300) else '' end
        || case when coalesce(r.money_aed,0) <> 0 then ' (AED ' || r.money_aed || ' at stake)' else '' end
        || E'\n\n';
  end loop;

  return out;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_agent_silence_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int:=0; f int:=0; g int:=0; nr int:=0; v_email text; v_run bigint;
begin
  insert into agent_runs(agent, started_at) values ('agent_silence_watch', clock_timestamp()) returning id into v_run;

  select to_email into v_email from notifications
   where type='founder_brief' and to_email is not null order by created_at desc limit 1;

  insert into cron_job_seen (jobid, jobname, schedule)
  select j.jobid, j.jobname, j.schedule from cron.job j where j.active
  on conflict (jobid) do update set last_seen = now(), jobname = excluded.jobname, schedule = excluded.schedule;

  -- Record successes BEFORE evaluating, so they survive the 14-day history prune.
  update cron_job_seen s
     set last_success = h.last_ok
    from (select jobid, max(start_time) as last_ok
            from cron.job_run_details where status='succeeded' group by jobid) h
   where h.jobid = s.jobid
     and (s.last_success is null or s.last_success < h.last_ok);

  for r in
    -- ONE AGGREGATE, NOT THREE CORRELATED SUBQUERIES PER JOB. This loop used to ask
    -- cron.job_run_details three separate questions for each of 165 active jobs against an 80 MB
    -- heap with no usable index, and on 11 Aug 2026 it began exceeding the statement timeout and
    -- stopped watching anything at all. A watchdog that dies silently is worse than no watchdog:
    -- fn_agent_silence_watch is the routine that would have reported its own absence.
    with h as (
      select jobid,
             count(*)                                                        as history_rows,
             max(start_time) filter (where status='succeeded')               as last_ok_live,
             count(*) filter (where status='failed'
                              and start_time > now() - interval '24 hours')  as fails_24h
        from cron.job_run_details
       group by jobid)
    select j.jobid, j.jobname,
           case when split_part(j.schedule,' ',5) <> '*' then 336
                when split_part(j.schedule,' ',3) <> '*' then 1440
                when split_part(j.schedule,' ',2) =  '*' then 6
                else 72 end as thresh_h,
           coalesce(h.history_rows, 0) as history_rows,
           greatest(h.last_ok_live, s.last_success) as last_ok,
           coalesce(h.fails_24h, 0) as fails_24h,
           s.first_seen,
           s.last_success as stored_ok
      from cron.job j
      left join h on h.jobid = j.jobid
      left join cron_job_seen s on s.jobid = j.jobid
     where j.active
  loop
    -- Never-run: only when there is NO history AND we have never recorded a success.
    if r.history_rows = 0 and r.stored_ok is null then
      if r.first_seen is not null and r.first_seen < now() - (r.thresh_h||' hours')::interval then
        if not exists (select 1 from founder_alerts where event='cron_never_ran'
                        and detail like '%"'||r.jobname||'"%'
                        and created_at > now() - interval '24 hours') then
          insert into founder_alerts(level,event,detail,channel)
          values ('high','cron_never_ran', jsonb_build_object(
            'job', r.jobname,
            'first_seen', r.first_seen::text,
            'known_for_hours', round(extract(epoch from (now()-r.first_seen))/3600),
            'expected_within_hours', r.thresh_h)::text, 'email');
          if v_email is not null then
            insert into notifications(type,to_email,subject,body,status)
            values ('agent_silence', v_email, 'Scheduled job has never run: '||r.jobname,
              'Job "'||r.jobname||'" is active but has no run history at all. It has been registered since '||
              r.first_seen::text||' and should have run at least every '||r.thresh_h||' hours. It is likely misregistered.','pending');
          end if;
          nr := nr + 1;
        end if;
      else
        g := g + 1;
      end if;
      continue;
    end if;

    if r.last_ok is null or r.last_ok < now() - (r.thresh_h||' hours')::interval then
      if not exists (select 1 from founder_alerts where event='cron_silent'
                      and detail like '%"'||r.jobname||'"%'
                      and created_at > now() - interval '24 hours') then
        insert into founder_alerts(level,event,detail,channel)
        values ('high','cron_silent', jsonb_build_object(
          'job',r.jobname,'last_success',coalesce(r.last_ok::text,'no success on record'),
          'silent_hours',round(extract(epoch from (now()-r.last_ok))/3600),
          'expected_within_hours',r.thresh_h)::text,'email');
        if v_email is not null then
          insert into notifications(type,to_email,subject,body,status)
          values ('agent_silence',v_email,'Scheduled job stopped: '||r.jobname,
            'Job "'||r.jobname||'" last succeeded '||coalesce(r.last_ok::text,'unknown')||
            '. Expected at least every '||r.thresh_h||' hours.','pending');
        end if;
        n := n + 1;
      end if;
    end if;

    if r.fails_24h > 0 then
      if not exists (select 1 from founder_alerts where event='cron_failing'
                      and detail like '%"'||r.jobname||'"%'
                      and created_at > now() - interval '24 hours') then
        insert into founder_alerts(level,event,detail,channel)
        values ('high','cron_failing',
          jsonb_build_object('job',r.jobname,'failures_24h',r.fails_24h,
                             'last_success',coalesce(r.last_ok::text,'unknown'))::text,'email');
        if v_email is not null then
          insert into notifications(type,to_email,subject,body,status)
          values ('agent_silence',v_email,'Scheduled job failing: '||r.jobname,
            'Job "'||r.jobname||'" has failed '||r.fails_24h||' time(s) in the last 24 hours. Last success: '||
            coalesce(r.last_ok::text,'unknown')||'. Check cron.job_run_details for the error text.','pending');
        end if;
        f := f + 1;
      end if;
    end if;
  end loop;

  update agent_runs
     set finished_at=clock_timestamp(), status='ok',
         counts=jsonb_build_object('active_jobs',(select count(*) from cron.job where active),
                                   'in_grace',g,'silent',n,'failing',f,'never_ran',nr)
   where id=v_run;

  return jsonb_build_object('ran_at',now(),
    'active_jobs',(select count(*) from cron.job where active),
    'in_grace',g,'silent_alerts',n,'failing_alerts',f,'never_ran_alerts',nr);
exception when others then
  update agent_runs set finished_at=clock_timestamp(), status='error', note=left(sqlerrm,500) where id=v_run;
  raise;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_tool_allowed(p_agent_key text, p_tool_id text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.fn_agent_tools(p_agent_key) t where t.tool_id = p_tool_id);
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_tools(p_agent_key text, p_kind text DEFAULT NULL::text)
 RETURNS TABLE(tool_id text, purpose text, kind text, impl_kind text, impl_target text, input_schema jsonb, timeout_seconds integer, max_attempts integer, backoff text, failure_behaviour text, requires_current_data boolean, required_credential text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with me as (
    select a.agent_key, a.department,
           coalesce((select array_agg(i.packaged_role_id) from org_role_identity i
                      where i.agent_key = a.agent_key), '{}'::text[]) as role_ids
    from org_agents a
   where a.agent_key = coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key)
     and a.active
  )
  select t.tool_id, t.purpose, t.kind, t.impl_kind, t.impl_target,
         t.input_schema, t.timeout_seconds, t.max_attempts, t.backoff,
         t.failure_behaviour, t.requires_current_data, t.required_credential
  from agent_tool t, me
  where t.active
    and t.staging_available
    and (p_kind is null or t.kind = p_kind)
    and (t.authorised_departments = '{}'::text[]
         or '*' = any(t.authorised_departments)
         or me.department = any(t.authorised_departments))
    and (t.authorised_roles = '{}'::text[]
         or '*' = any(t.authorised_roles)
         or me.role_ids && t.authorised_roles)
  order by t.kind, t.tool_id;
$function$


CREATE OR REPLACE FUNCTION public.fn_agents_board()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare out jsonb;
begin
  with runs as (
    select agent, count(*) filter (where started_at > now() - interval '24 hours') as runs24,
           count(*) filter (where started_at > now() - interval '24 hours' and status in ('error','failed')) as fails24,
           max(started_at) as last_run, (array_agg(status order by started_at desc))[1] as last_status
    from agent_runs group by agent
  ), base as (
    select a.agent_key, coalesce(nullif(trim(a.department),''),'General') as department, a.role, a.kind, coalesce(a.active,true) as active,
      coalesce(r.runs24,0) as runs24, coalesce(r.fails24,0) as fails24, r.last_run, r.last_status
    from org_agents a left join runs r on r.agent = a.agent_key
  ), dc as (select department, count(*) c, sum(runs24) rs from base group by department)
  select jsonb_build_object(
    'total',(select count(*) from base),
    'runs24',(select coalesce(sum(runs24),0) from base),
    'departments',(select coalesce(jsonb_agg(jsonb_build_object('key',d.department,'label',d.department,'count',d.c,'runs',d.rs,
        'cards',(select jsonb_agg(jsonb_build_object('id',b.agent_key,'agent_key',b.agent_key,'role',b.role,'kind',b.kind,'active',b.active,'runs24',b.runs24,'fails24',b.fails24,'last_status',b.last_status,'last_run',b.last_run) order by b.runs24 desc, b.agent_key) from base b where b.department=d.department))
        order by d.rs desc nulls last, d.department),'[]'::jsonb) from dc d),
    'rows',(select coalesce(jsonb_agg(jsonb_build_object('id',b.agent_key,'agent_key',b.agent_key,'department',b.department,'role',b.role,'kind',b.kind,'active',b.active,'runs24',b.runs24,'fails24',b.fails24,'last_status',b.last_status,'last_run',b.last_run) order by b.runs24 desc, b.agent_key),'[]'::jsonb) from base b)
  ) into out; return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ai_confidence_prior(p_agent_key text, p_task_class text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- A CONSTANT IS NOT A MEASUREMENT, AND THIS IS THE GUARD THAT SAYS SO.
  -- The founder's own reading of the two existing emitters: "always emit exactly 1.000, which
  -- carries no information". A model that reports the same number every time would otherwise
  -- downgrade itself to a cheaper tier on the strength of its own unvarying optimism. stddev = 0
  -- over the window means the signal has no content, so it does not route anything. n >= 5 for the
  -- same reason at the other end: one confident answer is an anecdote.
  select case
           when count(*) >= 5 and coalesce(stddev_samp(confidence), 0) > 0
           then jsonb_build_object(
                  'prior', round(percentile_cont(0.5) within group (order by confidence)::numeric, 4),
                  'n', count(*),
                  'spread', round(stddev_samp(confidence)::numeric, 4))
           else null
         end
    from public.ai_cost_log
   where agent_key = coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key)
     and task_class = p_task_class
     and confidence is not null
     and occurred_at > now() - interval '14 days';
$function$


CREATE OR REPLACE FUNCTION public.fn_ai_gate(p_answer text, p_sources jsonb DEFAULT '[]'::jsonb, p_confidence numeric DEFAULT NULL::numeric, p_action text DEFAULT 'run_agent_action'::text, p_actor text DEFAULT 'agent'::text, p_attrs jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare g jsonb; a jsonb; esc jsonb; conf_min numeric; viol text[]:='{}'; approved boolean; route text;
        v_sources jsonb;
begin
  g := public.fn_require_grounding(p_answer, p_sources);
  if not (g->>'grounded')::boolean then viol := array_append(viol,'ungrounded: retrieve knowledge and cite a source'); end if;
  select value::numeric into conf_min from decision_policy where key='confidence_min';
  if p_confidence is not null and p_confidence < coalesce(conf_min,0.6) then
     viol := array_append(viol,'low_confidence: below '||coalesce(conf_min,0.6)||' — ask a clarifying question or escalate'); end if;
  a := public.fn_authorize(p_actor, p_action, p_attrs);
  if not (a->>'allowed')::boolean then viol := array_append(viol,'unauthorized: '||(a->>'reason')); end if;
  -- THE ROUTER CANNOT NAME WHO TAKES IT WITHOUT KNOWING WHO RAISED IT. p_actor was passed to
  -- fn_authorize and withheld from fn_should_escalate, so every escalation this gate produced was
  -- addressed to the same company-wide owner. It travels up the escalating employee's own line now.
  esc := public.fn_should_escalate(p_attrs || jsonb_build_object('confidence',p_confidence,'actor',p_actor));
  route := esc->>'route_to';
  approved := (array_length(viol,1) is null) and not (esc->>'escalate')::boolean;
  -- WHAT THIS DECISION WAS TAKEN ON: the caller's citations plus the two verdicts the gate obtained
  -- for itself. Reaching this line means both calls returned, so both elements are real retrievals.
  v_sources := (case when jsonb_typeof(p_sources)='array' then p_sources else '[]'::jsonb end)
    || jsonb_build_array(
         jsonb_build_object('kind','policy_check','ref','fn_should_escalate','result',esc),
         jsonb_build_object('kind','authority_check','ref','fn_authorize','result',a));
  -- log the governance decision (immutable)
  insert into decision_log(actor,kind,ctx,decision,confidence,reasons,sources,route_to)
  values (p_actor,'ai_gate', jsonb_build_object('action',p_action,'attrs',p_attrs),
          case when approved then 'approved' else 'blocked' end, p_confidence,
          to_jsonb(viol || array(select jsonb_array_elements_text(coalesce(esc->'reasons','[]')))), v_sources, route);
  return jsonb_build_object('approved',approved,'violations',to_jsonb(viol),
    'grounding',g,'authorization',a,'escalation',esc,'route_to',route,'sources',v_sources,
    'directive', case when approved then 'emit'
                      when (esc->>'escalate')::boolean and route is not null then 'escalate to '||route
                      when (esc->>'escalate')::boolean then 'escalate: no party is configured to take this — '
                           ||coalesce(esc->>'route_note','decision_policy.review_owner resolves to nobody')
                      else 'revise before emitting' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_ai_quality_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_regs int:=0; v_spikes int:=0; v_detail jsonb; v_open int; v_owner text; v_t0 timestamptz := now();
begin
  -- ONE ROW PER AGENT PER NIGHT. Resolved to the canonical key here rather than left to the BEFORE
  -- INSERT trigger, because the trigger fires per row and therefore turns N raw agents into N rows
  -- that all claim the same identity. The rate is recomputed from the underlying counts, never
  -- averaged from the per-row percentages.
  insert into public.ai_quality_snapshots(agent, override_pct, actions_30d)
  select k.agent,
         round(100.0 * sum(v.rejected_30d)::numeric / nullif(sum(v.actions_30d), 0), 1),
         sum(v.actions_30d)::int
    from public.v_ai_agent_health v
    cross join lateral (select case
             when exists (select 1 from public.org_agents o where o.agent_key = v.agent and o.active)
               then v.agent
             else coalesce(public.fn_org_agent_resolve(v.agent), v.agent)
           end as agent) k
   where v.override_pct is not null
   group by k.agent
  having sum(v.actions_30d) > 0;

  with ranked as (
    select prompt_key, score, created_at,
           row_number() over(partition by prompt_key order by created_at desc) rn
    from public.prompt_eval_runs
  ),
  reg as (
    select c.prompt_key, c.score cur, p.score prev
    from ranked c join ranked p on p.prompt_key=c.prompt_key and p.rn=2
    where c.rn=1 and (c.score < p.score - 5 or c.score < 70)
  ),
  ins as (
    insert into public.security_events(kind,severity,source,subject,detail)
    select 'eval_regression', case when cur<70 then 'high' else 'medium' end, 'ai_quality_watch', prompt_key,
           jsonb_build_object('current',cur,'previous',prev)
    from reg returning 1
  )
  select count(*) into v_regs from ins;

  with cur as (
    -- Same resolution rule as the insert above, so `cur` and `hist` speak one vocabulary. Before
    -- this, 17 of 52 agents carried a raw name here and a canonical one in the snapshot, and the
    -- join below could not match them at all.
    select k.agent,
           round(100.0 * sum(v.rejected_30d)::numeric / nullif(sum(v.actions_30d), 0), 1) as override_pct,
           sum(v.actions_30d)::int as actions_30d
      from public.v_ai_agent_health v
      cross join lateral (select case
               when exists (select 1 from public.org_agents o where o.agent_key = v.agent and o.active)
                 then v.agent
               else coalesce(public.fn_org_agent_resolve(v.agent), v.agent)
             end as agent) k
     where v.override_pct is not null
     group by k.agent
    having sum(v.actions_30d) >= 5
       and k.agent not in ('security','onboarding','email')
  ),
  hist as (
    -- Weighted by actions, not a flat mean of percentages: the historical rows still contain the
    -- pre-fix duplicates, and a flat avg lets an agent with one action in a month move the trailing
    -- average as much as one with a hundred and sixty.
    select agent,
           sum(override_pct * greatest(actions_30d, 1))::numeric / nullif(sum(greatest(actions_30d, 1)), 0) as avg_prev,
           count(*) n
    from public.ai_quality_snapshots where at < now()-interval '12 hours' group by agent
  ),
  spike as (
    select c.agent, c.override_pct, round(h.avg_prev,1) avg_prev
    from cur c join hist h on h.agent=c.agent
    where h.n>=1 and c.override_pct > coalesce(h.avg_prev,0)+20
  ),
  ins2 as (
    insert into public.security_events(kind,severity,source,subject,detail)
    select 'override_spike','medium','ai_quality_watch', agent,
           jsonb_build_object('override_pct',override_pct,'trailing_avg',avg_prev)
    from spike returning 1
  )
  select count(*) into v_spikes from ins2;

  v_detail := jsonb_build_object('eval_regressions',v_regs,'override_spikes',v_spikes);

  -- Added 10 Aug 2026: this routine has detected quality falling since it was written and never
  -- emitted an event, so nothing downstream could react to it.
  if v_regs + v_spikes > 0 then
    perform fn_emit('ai.confidence_dropped',
                    case when se.kind='eval_regression' then 'prompt' else 'agent' end,
                    se.subject, 'ai_quality_watch',
                    se.detail || jsonb_build_object('finding', se.kind, 'severity', se.severity))
       from public.security_events se
      where se.source='ai_quality_watch' and se.kind in ('eval_regression','override_spike')
        and se.created_at >= v_t0;
  end if;

  if v_regs+v_spikes > 0 then
    select count(*) into v_open from public.agent_actions
      where kind='ai_quality_alert' and coalesce(status,'') in ('pending','needs_review')
        and created_at > now()-interval '24 hours';
    if v_open = 0 then
      insert into public.agent_actions(agent,kind,status,risk,title,recommendation,target_table,detail)
      values('ai_trainer','ai_quality_alert','pending','medium',
        'AI quality alert: '||v_regs||' eval regression(s), '||v_spikes||' override spike(s)',
        'Open the AI Observability dashboard and review security_events of kind eval_regression / override_spike. Consider rolling back the regressed prompt version, or investigating why a human-facing agent''s suggestions are being rejected.',
        'security_events', v_detail);
      select split_part(coalesce(value,'management@quotesdone.com'),',',1) into v_owner
        from public.app_secrets where key='admin_emails';
      insert into public.notifications(type,to_email,to_role,channel,subject,body,status)
      values('ai_quality_alert', v_owner,'admin','email','QuotesDone: AI quality alert',
        'The AI quality watch flagged '||v_regs||' eval regression(s) and '||v_spikes||' override spike(s). Open the AI Observability dashboard and check security_events (kind eval_regression / override_spike).','queued');
    end if;
  end if;
  return v_detail;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_ai_route(p_task_class text DEFAULT NULL::text, p_dept_key text DEFAULT NULL::text, p_confidence numeric DEFAULT NULL::numeric, p_fn text DEFAULT NULL::text, p_escalate boolean DEFAULT false, p_require_caps text[] DEFAULT NULL::text[], p_agent_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_class   text;
  v_src     text;
  v_pol     model_policy%rowtype;
  v_reg     model_registry%rowtype;
  v_fb      model_registry%rowtype;
  v_bud     department_budget%rowtype;
  v_pct     numeric := 0;
  v_model   text;
  v_why     text;
  v_min     numeric;
  v_tier    text;
  v_vis     boolean := 'vision' = any(coalesce(p_require_caps, '{}'::text[]));
  v_aud     boolean := 'audio'  = any(coalesce(p_require_caps, '{}'::text[]));
  v_tls     boolean := 'tools'  = any(coalesce(p_require_caps, '{}'::text[]));
  v_sub     model_registry%rowtype;
  v_want    int;
  v_idp     model_policy_by_identity%rowtype;
  v_generic boolean := false;
  v_rt      jsonb;
  v_prior   jsonb;
  v_conf    numeric;
  v_rtier   text;
  v_canon   text;
begin
  if p_task_class is not null and length(btrim(p_task_class)) > 0 then
    v_class := p_task_class; v_src := 'caller-supplied task_class';
  else
    select task_class into v_class from fn_task_class where fn = p_fn and active;
    if v_class is not null then
      v_src := 'classified from calling function "' || p_fn || '"';
    else
      v_class := 'general_drafting';
      v_generic := true;
      v_src := 'UNMAPPED function "' || coalesce(p_fn,'?') || '" - defaulted to general_drafting (medium). Add a fn_task_class row to route this properly.';
    end if;
  end if;

  -- THE PACK'S FOUR-ROLE TAXONOMY REACHES THE PATH IT WAS WRITTEN FOR (14 Aug 2026).
  --
  -- All 93 employees carry org_agents.routing_tier - director 36, operations_specialist 23,
  -- analyst_controller 21, reviewer_auditor 10 - and on the main employee path it was DEAD.
  -- fn_routing_tier_model below only fires when v_generic is true, i.e. when the calling function
  -- is unmapped; agent_brain IS mapped, to agent_reasoning, so every employee from a marketing
  -- copywriter to the CEO got the same blanket large tier.
  --
  -- Meanwhile model_policy carries routine_employee_reasoning at MEDIUM, and its own rationale
  -- says: "Pack: replaces the current blanket large-tier agent_reasoning. agent_reasoning is LIVE
  -- on anthropic/claude-sonnet-5 and agent_brain is ~93% of OpenRouter spend." It had ZERO callers.
  -- A policy written to replace something, that nothing points at, is a build order nobody wired.
  --
  -- This is a ROUTING decision taken from the role, not an override of task_class routing: the
  -- class is chosen by who is asking, then the policy for that class applies normally.
  --
  -- WHO STAYS ON LARGE, AND WHY. Only operations_specialist moves. reviewer_auditor stays large
  -- deliberately - all 24 Reviewer/Auditor rows in the pack name a large model, and a reviewer on
  -- the cheap model is a green check that means nothing. director and analyst_controller stay
  -- because their work is the consequential kind the large tier exists for.
  if v_class = 'agent_reasoning' and p_agent_key is not null then
    v_canon := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
    select a.routing_tier into v_rtier from org_agents a
     where a.agent_key = v_canon and a.active;
    if v_rtier = 'operations_specialist'
       and exists (select 1 from model_policy mp
                    where mp.task_class = 'routine_employee_reasoning' and mp.active) then
      v_class := 'routine_employee_reasoning';
      v_src := v_src || ' | routing_tier "operations_specialist" for "' || v_canon
                     || '" selected the routine employee class instead of the blanket large tier';
    end if;
  end if;

  select * into v_pol from model_policy where task_class = v_class and active;
  if not found then
    select * into v_pol from model_policy where task_class = 'general_drafting' and active;
    v_src := v_src || ' | no policy for "' || v_class || '", fell back to general_drafting';
    v_generic := true;
  end if;

  -- THE ROLE DEFAULT. model_policy_by_identity carries 120 rows — 96 target employees and 24
  -- current production agents — and had NO reader in the database at all. The pack states its own
  -- precedence on every row: note = 'Role default only; task_class routing overrides it.' So it
  -- applies only where the caller would otherwise get the generic general_drafting fallback:
  -- either the named class has no policy, or the calling function is unmapped in fn_task_class.
  --
  -- v_generic exists because the first version of this branch was UNREACHABLE. It hung off
  -- `if not found` on the model_policy lookup, and an unmapped function has already had v_class
  -- rewritten to 'general_drafting' by then — which IS found. Measured: fn_ai_route(...,'cfo')
  -- returned identity_policy null. Same shape as the unreachable block in
  -- fn_kb_route_activation_blocked found earlier today: a branch guarded by a condition that
  -- cannot occur.
  --
  -- 23 of the 24 current_agent keys resolve to a real org_agents row; 'cat:*' covers the
  -- category desks.
  if v_generic and p_agent_key is not null then
    select * into v_idp from model_policy_by_identity
     where scope = 'current_agent'
       and (identity_key = p_agent_key
            or (identity_key = 'cat:*' and p_agent_key like 'cat:%'))
     order by (identity_key = p_agent_key) desc
     limit 1;
    if found and v_idp.primary_model is not null then
      v_pol.model_primary  := v_idp.primary_model;
      v_pol.model_fallback := coalesce(v_idp.fallback_model, v_pol.model_fallback);
      v_pol.max_tokens     := coalesce(v_idp.max_output_tokens, v_pol.max_tokens);
      v_src := v_src || ' | role default for "' || p_agent_key || '" applied from model_policy_by_identity';
    end if;
  end if;

  -- ---- ROUTING TIER, added 11 Aug 2026 ---------------------------------------------------------
  -- The pack's four-role taxonomy carried onto the 93 real employees as org_agents.routing_tier.
  -- Fires LAST and only if the pack had nothing to say about this specific agent, so an explicit
  -- current_agent row always wins. Resolves tier -> registry tier -> cheapest active approved model
  -- AT CALL TIME: no model id is stored anywhere, so this follows the fleet instead of going stale.
  -- Measured direction against the general_drafting default (haiku, 1.00 USD/Mtok in):
  -- operations_specialist 4x cheaper, analyst/director unchanged, reviewer_auditor 2x dearer and
  -- deliberately so - all 24 Reviewer/Auditor rows in the pack name sonnet-5, and a reviewer on the
  -- cheap model is a green check that means nothing.
  if v_generic and p_agent_key is not null and v_idp.identity_key is null then
    v_rt := public.fn_routing_tier_model(p_agent_key);
    if v_rt is not null and (v_rt->>'model') is not null then
      v_pol.model_primary := v_rt->>'model';
      v_pol.tier          := v_rt->>'registry_tier';
      v_src := v_src || ' | routing_tier "' || (v_rt->>'routing_tier') || '" for "' || p_agent_key
                     || '" resolved to ' || (v_rt->>'model') || ' (' || (v_rt->>'registry_tier') || ' tier)';
    end if;
  end if;
  -- ----------------------------------------------------------------------------------------------

  if v_pol.tier = 'none' then
    return jsonb_build_object(
      'use_llm', false, 'task_class', v_class, 'tier', 'none',
      'why', 'REFUSED. ' || coalesce(v_pol.deterministic_alternative, 'This is deterministic - use code.')
             || ' [' || v_src || ']',
      'deterministic_alternative', v_pol.deterministic_alternative);
  end if;

  v_tier  := v_pol.tier;
  v_model := v_pol.model_primary;
  v_why   := coalesce(v_pol.rationale, 'policy for ' || v_class) || ' [' || v_src || ']';

  if p_escalate then
    v_model := coalesce(v_pol.model_fallback, v_model);
    v_why   := v_why || ' | ESCALATED one tier after an unsatisfactory cheaper attempt';
  end if;

  select (value #>> '{}')::numeric into v_min from decision_policy where key = 'confidence_min';
  -- THE PRIOR, 11 Aug 2026. Both arms below are original and NEITHER HAS EVER FIRED, because
  -- p_confidence is the confidence of THIS call and no caller can know that before the call.
  -- Measured the day this was written: 7 of 1,746 model calls in seven days carried a confidence at
  -- all. The only confidence that CAN exist beforehand is the agent's own recent record on this
  -- task class, so that is what a caller supplying nothing now routes on.
  --
  -- fn_ai_confidence_prior returns null unless there are at least 5 observations AND they vary.
  -- The variance guard is the important half: the two callers that emitted a confidence before
  -- tonight always emitted exactly 1.0000, and a model reporting the same number every time would
  -- otherwise downgrade itself to a cheaper tier on the strength of its own unvarying optimism.
  v_conf := p_confidence;
  if v_conf is null and p_agent_key is not null then
    v_prior := public.fn_ai_confidence_prior(p_agent_key, v_class);
    if v_prior is not null then v_conf := (v_prior->>'prior')::numeric; end if;
  end if;

  if v_conf is not null then
    if v_conf >= 0.95 and v_tier in ('large','xlarge') then
      select model_id into v_model from model_registry
       where active and approved and tier = 'medium' order by in_per_mtok_usd limit 1;
      v_why := v_why || ' | confidence ' || v_conf
               || case when v_prior is null then ''
                       else ' (' || p_agent_key || ' own median over ' || (v_prior->>'n')
                            || ' calls on ' || v_class || ', spread ' || (v_prior->>'spread') || ')' end
               || ' >= 0.95, downgraded to medium - no second opinion needed';
    elsif v_min is not null and v_conf < v_min and v_tier = 'small' then
      v_model := coalesce(v_pol.model_fallback, v_model);
      v_why := v_why || ' | confidence ' || v_conf
               || case when v_prior is null then ''
                       else ' (' || p_agent_key || ' own median over ' || (v_prior->>'n') || ' calls)' end
               || ' below floor ' || v_min || ', escalated a tier';
    end if;
  end if;

  -- A CALL WITH NO DEPARTMENT IS A CALL NO CEILING CAN STOP (13 Aug 2026). The halt below needs a
  -- dept_key to find a budget, and 59 of this month's calls arrived without one - inquiry_intake,
  -- drawing_boq, doc_extract, license_extract, supplier_onboard and eleven more, i.e. the demand
  -- path. fn_task_class already maps fn -> task_class for this same function's model choice; it now
  -- carries the owning department too, so an un-attributed call is attributed by what it IS rather
  -- than left outside every ceiling. An explicit p_dept_key from the caller still wins.
  -- CANONICAL BEFORE THE CEILING (14 Aug 2026). department_budget holds the ten canonical rows;
  -- a caller passing a merged-away key ('procurement', 'marketing', 'sales' ...) found NO budget
  -- row and skipped the ceiling entirely. fn_dept_canonical resolves the key the caller used to
  -- the department that actually owns it.
  if public.fn_dept_canonical(coalesce(p_dept_key, (select t.dept_key from fn_task_class t where t.fn = p_fn and t.active))) is not null then
    select * into v_bud from department_budget
     where dept_key = public.fn_dept_canonical(coalesce(p_dept_key, (select t.dept_key from fn_task_class t where t.fn = p_fn and t.active)));
    if found and v_bud.monthly_aed > 0 then
      v_pct := round(100 * coalesce(
        (select sum(cost_aed) from ai_cost_log
          where dept_key = any(public.fn_dept_scope(v_bud.dept_key))
            and occurred_at >= date_trunc('month', now())), 0)
        / v_bud.monthly_aed, 2);
      if v_pct >= v_bud.halt_at_pct then
        return jsonb_build_object(
          'use_llm', false, 'task_class', v_class, 'tier', v_tier, 'halted', true, 'budget_pct', v_pct,
          'why', 'HALTED. ' || v_bud.dept_key || ' is at ' || v_pct || '% of its monthly AI budget (halt at '
                 || v_bud.halt_at_pct || '%). Non-gated work stops until the budget resets or is raised.');
      elsif v_pct >= v_bud.degrade_at_pct then
        select model_id into v_model from model_registry
         where active and approved
           and tier = case v_tier when 'xlarge' then 'large' when 'large' then 'medium' else 'small' end
         order by in_per_mtok_usd limit 1;
        v_why := v_why || ' | department at ' || v_pct || '% of budget, degraded one tier';
      end if;
    end if;
  end if;

  select * into v_reg from model_registry where model_id = v_model and active;
  if not found then
    select * into v_reg from model_registry
     where active and approved and tier = (case v_tier when 'xlarge' then 'xlarge' else v_tier end)
     order by in_per_mtok_usd limit 1;
    v_why := v_why || ' | WARNING: policy model "' || v_model || '" is not in model_registry; substituted ' || coalesce(v_reg.model_id,'(none)');
    v_model := v_reg.model_id;
  end if;

  -- CAPABILITY. Price and tier chose the model above; if it cannot see, hear or call tools the
  -- provider will simply reject the payload. Substitute the nearest capable model, preferring the
  -- intended tier, then the closest tier ABOVE it, and only then below - a capability substitution
  -- must never quietly become a quality downgrade.
  v_want := fn_ai_route_tier_rank(v_tier);
  if (v_vis or v_aud or v_tls)
     and not ( (not v_vis or coalesce(v_reg.supports_vision,false))
           and (not v_aud or coalesce(v_reg.supports_audio, false))
           and (not v_tls or coalesce(v_reg.supports_tools, false)) ) then

    select * into v_sub from model_registry
     where active and approved
       and (not v_vis or supports_vision) and (not v_aud or supports_audio) and (not v_tls or supports_tools)
     order by (fn_ai_route_tier_rank(tier) < v_want),                 -- at-or-above the tier first
              abs(fn_ai_route_tier_rank(tier) - v_want),              -- then closest to it
              in_per_mtok_usd                                          -- then cheapest
     limit 1;

    if found then
      v_why := v_why || ' | CAPABILITY OVERRIDE: ' || v_model || ' cannot do ('
               || array_to_string(coalesce(p_require_caps,'{}'::text[]), '+') || '); substituted ' || v_sub.model_id
               || ' (' || v_sub.tier || ' tier, intended ' || v_tier || ')';
      v_reg := v_sub; v_model := v_sub.model_id;
    else
      return jsonb_build_object(
        'use_llm', false, 'task_class', v_class, 'tier', v_tier, 'caps', to_jsonb(p_require_caps),
        'why', 'REFUSED. No active approved model in model_registry supports ('
               || array_to_string(coalesce(p_require_caps,'{}'::text[]), '+')
               || '). Add one, or mark the capability on an existing model.');
    end if;
  end if;

  select * into v_fb from model_registry
   where model_id = v_pol.model_fallback and active
     and (not v_vis or supports_vision) and (not v_aud or supports_audio) and (not v_tls or supports_tools);
  if not found and (v_vis or v_aud or v_tls) then
    select * into v_fb from model_registry
     where active and approved and model_id <> v_model
       and (not v_vis or supports_vision) and (not v_aud or supports_audio) and (not v_tls or supports_tools)
     order by (fn_ai_route_tier_rank(tier) < v_want), abs(fn_ai_route_tier_rank(tier) - v_want), in_per_mtok_usd
     limit 1;
  end if;

  return jsonb_build_object(
    'use_llm', true,
    'task_class', v_class,
    'tier', v_tier,
    'model', v_model,
    'fallback', v_fb.model_id,
    'max_tokens', v_pol.max_tokens,
    'cache_ttl_min', coalesce(v_pol.cache_ttl_min, 0),
    'cache', coalesce(v_reg.supports_cache, false),
    'stream', coalesce(v_reg.supports_streaming, true),
    'caps', to_jsonb(coalesce(p_require_caps, '{}'::text[])),
    'in_per_mtok_usd', v_reg.in_per_mtok_usd,
    'out_per_mtok_usd', v_reg.out_per_mtok_usd,
    'cache_read_per_mtok_usd', v_reg.cache_read_per_mtok_usd,
    'budget_pct', v_pct,
    'identity_policy', case when v_idp.identity_key is null then null else jsonb_build_object(
        'identity_key', v_idp.identity_key, 'deterministic_first', v_idp.deterministic_first,
        'reasoning_effort', v_idp.reasoning_effort, 'authority_tier', v_idp.authority_tier) end,
    'routing_tier', v_rt,
    'confidence_prior', v_prior,
    'confidence_used', v_conf,
    'why', v_why);
end $function$


CREATE OR REPLACE FUNCTION public.fn_ai_route_tier_rank(p_tier text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$ select case p_tier when 'small' then 1 when 'medium' then 2 when 'large' then 3 when 'xlarge' then 4 else 0 end $function$


CREATE OR REPLACE FUNCTION public.fn_ai_spend_guard()
 RETURNS TABLE(scope text, verdict text, pct numeric, note text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r             record;
  v_month_start date := date_trunc('month', now())::date;
  v_day_of      numeric := greatest(extract(day from now())::numeric, 1);
  v_days_in     numeric := extract(day from (date_trunc('month', now()) + interval '1 month - 1 day'))::numeric;
  v_today       numeric;
  v_baseline    numeric;
  v_spike       numeric := coalesce((select nullif(value,'')::numeric from app_secrets where key='ai_spend_spike_multiple'), 5.0);
  v_verdict     text;
  v_note        text;
  v_proj        numeric;
  v_blind_pct   numeric;
begin
  -- HOW MUCH OF THIS MONTH'S SPEND THE AUTOMATIC HALT CANNOT SEE. fn_ai_route enforces the ceiling
  -- by looking up department_budget for the call's dept_key; a call logged without one has no
  -- budget to be measured against and cannot be halted. Measured here rather than asserted, because
  -- the sentence this feeds used to be a hardcoded claim that went stale.
  select round(100.0 * count(*) filter (where dept_key is null) / nullif(count(*), 0), 1)
    into v_blind_pct
    from ai_cost_log where occurred_at >= v_month_start;
  v_blind_pct := coalesce(v_blind_pct, 0);

  -- ---- 1 & 3: per-department consumption and month-end projection ----
  for r in
    select b.dept_key, b.monthly_aed, b.degrade_at_pct, b.halt_at_pct,
           coalesce((select sum(l.cost_aed) from ai_cost_log l
                      where l.dept_key = any(public.fn_dept_scope(b.dept_key))
                        and l.occurred_at >= v_month_start), 0) as spent
    from department_budget b
    where b.monthly_aed > 0
  loop
    pct  := round(100 * r.spent / r.monthly_aed, 2);
    v_proj := round(r.spent / v_day_of * v_days_in, 2);

    if pct >= r.halt_at_pct then
      v_verdict := 'HALT';
      v_note := r.dept_key || ' has spent ' || round(r.spent,2) || ' of ' || r.monthly_aed
             || ' AED (' || pct || '%), at or past its halt threshold of ' || r.halt_at_pct || '%.';
    elsif pct >= r.degrade_at_pct then
      v_verdict := 'DEGRADE';
      v_note := r.dept_key || ' has spent ' || round(r.spent,2) || ' of ' || r.monthly_aed
             || ' AED (' || pct || '%), past its degrade threshold of ' || r.degrade_at_pct || '%.';
    elsif v_proj > r.monthly_aed then
      v_verdict := 'PROJECTED OVER';
      v_note := r.dept_key || ' is at ' || pct || '% on day ' || v_day_of || ', but the current run-rate projects '
             || v_proj || ' AED by month end against a ' || r.monthly_aed || ' AED budget.';
    else
      v_verdict := 'OK';
      v_note := r.dept_key || ': ' || round(r.spent,2) || '/' || r.monthly_aed || ' AED (' || pct
             || '%), projecting ' || v_proj || ' AED.';
    end if;

    insert into ai_spend_probe (scope, spent_aed, budget_aed, pct, projected_aed, verdict, note)
    values (r.dept_key, r.spent, r.monthly_aed, pct, v_proj, v_verdict, v_note);

    -- THE STORED COUNTER STOPS LYING. department_budget.spent_aed was 0.00 for every real
    -- department while AED 106 had been spent this month, because nothing ever wrote it. The
    -- enforcing paths (this function and fn_ai_route) always summed ai_cost_log live and were
    -- never affected; fn_budget_available read the column and therefore reported every budget
    -- as untouched, which is what fn_check_spend authorises business spend against.
    -- fn_budget_available now computes live too, so this write is for anything that READS the
    -- column - dashboards, reports, the founder's own eye - not for any decision.
    update department_budget
       set spent_aed = round(r.spent, 4), period_label = to_char(now(), 'YYYY-MM'), updated_at = now()
     where dept_key = r.dept_key
       and (spent_aed is distinct from round(r.spent, 4) or period_label is distinct from to_char(now(), 'YYYY-MM'));

    if v_verdict <> 'OK' then
      if not exists (select 1 from os_incidents
                      where status='open' and kind='ai_spend' and detail->>'scope' = r.dept_key) then
        insert into os_incidents (title, kind, severity, status, detail, opened_by)
        values (left('AI spend ' || v_verdict || ': ' || r.dept_key, 300), 'ai_spend',
                case when v_verdict='HALT' then 'high' else 'medium' end, 'open',
                jsonb_build_object('scope', r.dept_key, 'spent_aed', round(r.spent,2),
                  'budget_aed', r.monthly_aed, 'pct', pct, 'projected_aed', v_proj,
                  'verdict', v_verdict,
                  'halt_enforcement', 'The automatic halt IS enforced, by fn_ai_route inside ai_gateway: it compares month-to-date dept spend against department_budget.halt_at_pct and returns use_llm=false, which the gateway refuses as budget_halted. It can only act on calls that carry a dept_key; ' || v_blind_pct || '% of this month''s logged calls do not, and that share is outside the ceiling.'),
                'ai_spend_guard');
        insert into founder_alerts (level, event, detail, channel)
        values (case when v_verdict='HALT' then 'crit' else 'warn' end, 'ai_spend_' || lower(replace(v_verdict,' ','_')),
                v_note || ' The automatic halt is enforced by fn_ai_route in ai_gateway and stops non-gated work for a department at its halt_at_pct. It cannot see calls logged without a dept_key: ' || v_blind_pct || '% of this month''s calls, which remain outside the ceiling.', 'system');
      end if;
    else
      update os_incidents set status='resolved', resolved_at=now(), resolved_by='ai_spend_guard',
             resolution = 'Back within budget: ' || v_note
       where status='open' and kind='ai_spend' and detail->>'scope' = r.dept_key;
    end if;

    scope := r.dept_key; verdict := v_verdict; note := v_note;
    return next;
  end loop;

  -- ---- 2: company-wide daily run-rate spike ----
  select coalesce(sum(cost_aed),0) into v_today
    from ai_cost_log where occurred_at >= current_date;
  select coalesce(avg(d),0) into v_baseline from (
    select sum(cost_aed) d from ai_cost_log
    where occurred_at >= current_date - interval '7 days' and occurred_at < current_date
    group by date_trunc('day', occurred_at)
  ) x;

  if v_baseline > 0 and v_today > v_baseline * v_spike then
    v_verdict := 'SPIKE';
    v_note := 'Company AI spend today is ' || round(v_today,2) || ' AED against a trailing daily average of '
           || round(v_baseline,2) || ' AED - ' || round(v_today / v_baseline, 1)
           || 'x the baseline. Autonomy multiplies call volume; check what started.';
    if not exists (select 1 from os_incidents where status='open' and kind='ai_spend' and detail->>'scope'='company_daily') then
      insert into os_incidents (title, kind, severity, status, detail, opened_by)
      values (left('AI spend SPIKE: ' || round(v_today/v_baseline,1) || 'x the daily baseline', 300),
              'ai_spend', 'high', 'open',
              jsonb_build_object('scope','company_daily','today_aed',round(v_today,2),
                'baseline_aed',round(v_baseline,2),'multiple',round(v_today/v_baseline,1),
                'threshold_multiple', v_spike), 'ai_spend_guard');
      insert into founder_alerts (level, event, detail, channel)
      values ('crit','ai_spend_spike', v_note, 'system');
    end if;
  else
    v_verdict := 'OK';
    v_note := 'Company AI spend today ' || round(v_today,2) || ' AED against a ' || round(v_baseline,2) || ' AED trailing daily average.';
    update os_incidents set status='resolved', resolved_at=now(), resolved_by='ai_spend_guard',
           resolution = v_note
     where status='open' and kind='ai_spend' and detail->>'scope'='company_daily';
  end if;

  insert into ai_spend_probe (scope, spent_aed, budget_aed, pct, verdict, note)
  values ('company_daily', v_today, v_baseline, case when v_baseline>0 then round(100*v_today/v_baseline,2) else null end, v_verdict, v_note);

  scope := 'company_daily'; verdict := v_verdict;
  pct := case when v_baseline>0 then round(100*v_today/v_baseline,2) else null end;
  note := v_note;
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ai_trainer()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_runs int; v_err int; v_run_ok numeric;
  v_open int; v_rej int; v_acc int; v_reject_rate numeric; v_esc_rate numeric;
  v_qa_total int; v_qa_failed int; v_qa_pass numeric;
  v_sat numeric; v_halluc numeric; v_clarif numeric;
  v_quote_q numeric; v_match_cov numeric;
  v_health numeric; v_kpis jsonb; n_rec int; v_weak text; v_secret text; n_drafted int:=0; v_ref text;
begin
  select count(*), count(*) filter (where status in ('error','failed')) into v_runs, v_err from agent_runs where started_at>=now()-interval '30 days';
  v_run_ok := round(100.0*(v_runs-v_err)/nullif(v_runs,0),1);
  select count(*) filter (where status in ('pending','needs_review')),
         count(*) filter (where status='rejected'),
         count(*) filter (where status in ('approved','done','auto_done'))
    into v_open, v_rej, v_acc from agent_actions where created_at>=now()-interval '30 days';
  v_reject_rate := round(100.0*v_rej/nullif(v_rej+v_acc,0),1);
  v_esc_rate := round(100.0*v_open/nullif(v_open+v_acc+v_rej,0),1);
  select total, failed into v_qa_total, v_qa_failed from qa_results order by run_at desc limit 1;
  v_qa_pass := round(100.0*(coalesce(v_qa_total,0)-coalesce(v_qa_failed,0))/nullif(v_qa_total,0),1);
  select avg_satisfaction into v_sat from customer_kpis;
  v_halluc := round(100.0*(coalesce(v_rej,0)+coalesce(v_qa_failed,0))/nullif(coalesce(v_acc,0)+coalesce(v_rej,0)+coalesce(v_qa_total,0),0),1);
  select round(100.0*count(*) filter (where rfq_ready)/nullif(count(*),0),1) into v_clarif from inquiries where created_at>=now()-interval '90 days';
  select (kpis->>'quote_quality_avg')::numeric, (kpis->>'match_coverage_pct')::numeric into v_quote_q, v_match_cov from agent_evals order by snapshot_at desc limit 1;

  v_kpis := jsonb_build_object(
    'window_days',30,'run_success_pct',v_run_ok,'escalation_rate_pct',v_esc_rate,'rejection_rate_pct',v_reject_rate,
    'qa_pass_pct',v_qa_pass,'qa_cases',v_qa_total,'customer_satisfaction',v_sat,
    'hallucination_proxy_pct',v_halluc,'clarification_efficiency_pct',v_clarif,
    'quote_quality_avg',v_quote_q,'match_coverage_pct',v_match_cov,
    'runs_30d',v_runs,'errors_30d',v_err,'open_escalations',v_open,'rejected',v_rej,'accepted',v_acc);

  insert into agent_evals(snapshot_at, window_days, kpis) values (now(), 30, v_kpis);
  v_health := round(coalesce(v_run_ok,100)*0.30 + (100-coalesce(v_halluc,0))*0.25 + coalesce(v_sat,70)*0.20 + coalesce(v_qa_pass,100)*0.15 + coalesce((select coverage_pct from knowledge_kpis),60)*0.10,1);
  insert into ai_trainer_snapshots(snapshot_date, kpis) values (current_date, v_kpis || jsonb_build_object('ai_health',v_health))
    on conflict (snapshot_date) do update set kpis=excluded.kpis, created_at=now();

  select string_agg(agent||' ('||coalesce(run_success_pct,0)||'% ok, '||coalesce(rejection_rate_pct,0)||'% rejected)', '; ')
    into v_weak from ai_agent_quality where runs_30d>=20 and (coalesce(run_success_pct,100)<90 or coalesce(rejection_rate_pct,0)>30);
  perform ai_rec('weak_agents', v_weak is not null, 'medium', 'Under-performing agents',
    'These agents need attention: '||v_weak||'. Review their logic/prompt or the knowledge they rely on.',
    jsonb_build_array(
      'A failed run means the agent performed badly. Several routines here write status=error to record a real-world FINDING they were built to report, so a watcher doing its job correctly lands in this list.',
      'A founder rejection means the agent was wrong. Rejecting a correct recommendation for a business reason counts identically.',
      'The 20-run floor makes the percentages meaningful, and it also hides every agent below it — an agent that ran three times and failed all three never appears here.'),
    'These are the agents the company relies on unattended. Fixing the prompt or knowledge behind them raises the quality of everything they touch, rather than correcting outputs one at a time.',
    'Model spend to re-benchmark after a change, plus engineering time. The costly mistake is rewriting a prompt for an agent whose real problem is the knowledge it retrieves.');

  perform ai_rec('low_quote_quality', coalesce(v_quote_q,100) < 60, 'medium', 'Quote-review quality is low',
    'Structured quote quality is averaging '||coalesce(v_quote_q,0)||'/100. The Trainer is drafting an improved quote_review prompt for your approval; also strengthening category knowledge helps.',
    jsonb_build_array(
      'The score measures the QUOTES suppliers submit, not the reviewer reading them. A low average can mean suppliers are quoting thinly, and rewriting the review prompt would not move it.',
      'coalesce(v_quote_q,100) treats "never measured" as a perfect 100, so this rule stays silent when there is no evidence at all rather than raising a false alarm — silence here is not a pass.',
      'The average comes from the newest agent_evals snapshot only, so a single bad day moves it.'),
    'Quote quality is what the customer compares. Every point of it is the difference between a buyer who can decide and a buyer who asks all three suppliers to re-quote.',
    'Model spend on the drafted prompt plus a benchmark run. Rollout stays founder-approved, so nothing changes on the strength of this alert alone.');

  perform ai_rec('thin_benchmarks', coalesce(v_qa_total,0) < 20, 'low', 'Add more test benchmarks',
    'The QA suite has only '||coalesce(v_qa_total,0)||' cases. Add benchmark cases (quotes, RFQ qualification, compliance answers) so regressions are caught automatically.',
    jsonb_build_array(
      'Twenty is a chosen floor, not a derived one. Twenty cases covering one path are worth less than five spanning quoting, qualification and compliance.',
      'The count comes from the most recent qa_results row, so a suite that failed to run leaves an old, small number standing and looks like a thin suite rather than a missing run.'),
    'Benchmarks are the only thing that makes a prompt change comparable. Without them every improvement is an opinion and every regression is invisible until a customer finds it.',
    'Model spend per case, per run. Cases are cheap; the cost is writing ones that test something real rather than restating what the model already does well.');

  perform ai_rec('prompts_unbenchmarked', (select count(*) from prompt_versions where status='active' and eval_score is null)>0, 'low', 'Prompts have no eval score',
    (select count(*)::text from prompt_versions where status='active' and eval_score is null)||' active prompt(s) have never been benchmarked. Run an eval so future changes can be compared objectively.',
    jsonb_build_array(
      'A null eval_score means never benchmarked. It would read identically if a benchmark ran and failed to write its score back.',
      'These prompts are live: status=''active'' is what the routines load, so an unbenchmarked prompt is already in production use.'),
    'A score on each active prompt turns the next prompt change from a guess into a comparison. Until then there is no way to tell an improvement from a regression.',
    'Model spend, one eval run per prompt. Small, and it is the precondition for every other improvement on this board being measurable.');

  perform ai_rec('accuracy_watch', coalesce(v_halluc,0) > 15, 'high', 'Accuracy watch — high correction rate',
    'The AI was corrected/failed '||coalesce(v_halluc,0)||'% of the time (founder rejections + QA failures). Review the rejected actions to find the pattern and fix the responsible prompt or knowledge.',
    jsonb_build_array(
      'This is a PROXY, and its name says so where the founder does not read it. It is (founder rejections + QA failures) over (accepted + rejected + QA cases), so a founder rejecting a CORRECT recommendation for a business reason raises it exactly as much as a genuine hallucination.',
      'The denominator mixes two different populations — live agent actions and QA test cases — so the percentage is not a rate of anything that happens in one place.',
      'A high figure means disagreement, which is not the same as inaccuracy. Reviewing the rejected actions, which is what the recommendation asks for, is the only way to tell the two apart.'),
    'If the pattern is real, fixing the prompt or knowledge behind it corrects every future answer of that shape. If it is the founder disagreeing on business grounds, the finding is that the agent''s brief is wrong, not its reasoning — and that is worth as much.',
    'No spend to review. Model spend only if a prompt is redrafted afterwards.');

  -- CLOSED LOOP: when quote quality is low and no draft is already awaiting approval, ask the LLM to author an improved
  -- quote_review prompt DRAFT (founder still approves before rollout). De-duped so it drafts once per open cycle.
  if coalesce(v_quote_q,100) < 60
     and not exists (select 1 from agent_actions where kind='prompt_approval' and detail->>'key'='quote_review.system' and status in ('pending','needs_review'))
     and not exists (select 1 from prompt_versions where prompt_key='quote_review.system' and status='draft') then
    select value into v_secret from app_secrets where key='cred_db_internal';
    -- PROMOTE-SAFE REF. This was a literal project ref, which meant this routine's definition
    -- differed between projects and `apply_sql --promote` would have repointed production at
    -- staging. Same lookup fn_action_invoke_dispatch and fn_rfq_redispatch_sweep use.
    select value into v_ref from app_secrets where key='project_ref';
    if v_ref is null then
      select substring(command from 'https://([a-z]+)[.]supabase[.]co') into v_ref
        from cron.job where command like '%supabase.co/functions/v1/%' limit 1;
    end if;
    if v_ref is not null then
      perform net.http_post(
        url:='https://'||v_ref||'.supabase.co/functions/v1/prompt_improve',
        headers:='{"Content-Type":"application/json"}'::jsonb,
        body:=jsonb_build_object('__secret',v_secret,'key','quote_review.system',
          'reason','Structured quote quality is averaging '||coalesce(v_quote_q,0)||'/100 — quotes lack itemised detail (brand/model/spec/unit price) and clear scope; the prompt should require full line-item detail and flag missing fields.'));
      n_drafted := 1;
    end if;
  end if;

  select count(*) into n_rec from agent_actions where agent='ai_trainer' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at',now(),'ai_health',v_health,'kpis',v_kpis,'open_recommendations',n_rec,'auto_drafted',n_drafted);
end $function$


CREATE OR REPLACE FUNCTION public.fn_alert_severe(p_level text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Deliberately generous and deliberately explicit. Anything a routine plausibly means as
  -- "somebody has to look at this now". info / warn / warning / action are NOT severe and stay out.
  select lower(coalesce(p_level,'')) in ('critical','crit','error','high','fatal','sev1','urgent');
$function$


CREATE OR REPLACE FUNCTION public.fn_answer_precedence_rank(p answer_precedence)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case p
    when 'customer_confirmed'      then 1
    when 'approved_document'       then 2
    when 'document_extracted'      then 3
    when 'deterministic_inference' then 4
    when 'model_inference'         then 5
    else 6 end;
$function$


CREATE OR REPLACE FUNCTION public.fn_ap_bill_dupe_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_prior bigint;
begin
  if coalesce(new.status,'') in ('void','duplicate_hold') then return new; end if;

  select id into v_prior from ap_bills
  where vendor_id = new.vendor_id
    and coalesce(status,'') not in ('void','duplicate_hold')
    and id is distinct from new.id
    and total = new.total
    and bill_date = new.bill_date
  order by id limit 1;

  if v_prior is not null then
    new.status := 'duplicate_hold';

    insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
    values ('fake_supplier','critical','ap_bill', coalesce(new.bill_no, new.id::text), 'duplicate_invoice_presented',
            'Same vendor, same amount, same date as an invoice already booked. Held, not posted.',
            jsonb_build_object('vendor_id', new.vendor_id, 'total', new.total,
                               'bill_date', new.bill_date, 'prior_bill_id', v_prior,
                               'presented_bill_no', new.bill_no))
    on conflict do nothing;

    insert into institutional_memory (kind, subject_type, subject_id, headline, detail, outcome,
                                      money_aed, learned_by, confidence, evidence_ref)
    values ('pattern','ap_bill', coalesce(new.bill_no, new.id::text),
            'Duplicate invoice presentation held before payment.',
            format('Vendor %s presented %s for %s on %s, matching bill id %s already on file.',
                   new.vendor_id, coalesce(new.bill_no,'(no ref)'), new.total, new.bill_date, v_prior),
            'held as duplicate_hold; not posted, not paid', new.total, 'finance_bookkeeper', 1.0,
            'trg_ap_bill_dupe_guard; ap_bills id ' || v_prior);

    insert into company_event (event_type, entity_type, entity_id, actor, payload)
    values ('invoice.flagged','ap_bill', coalesce(new.bill_no, new.id::text), 'finance_bookkeeper',
            jsonb_build_object('reason','duplicate_invoice','vendor_id', new.vendor_id,
                               'total', new.total,'prior_bill_id', v_prior));

    raise warning 'invoice held as duplicate of bill id %', v_prior;
  end if;
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_ap_duplicate_scan()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer := 0;
begin
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'fake_supplier','critical','ap_bill', min(b.bill_no), 'duplicate_invoice_booked',
         'More than one non-void bill exists for the same vendor, amount and date.',
         jsonb_build_object('vendor_id', b.vendor_id, 'total', b.total, 'bill_date', b.bill_date,
                            'bill_ids', array_agg(b.id order by b.id), 'count', count(*))
  from ap_bills b
  where coalesce(b.status,'') <> 'void'
  group by b.vendor_id, b.total, b.bill_date
  having count(*) > 1
  on conflict do nothing;
  get diagnostics n = row_count;
  return n;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_ap_pay(p_bill bigint, p_date date DEFAULT NULL::date, p_amount numeric DEFAULT NULL::numeric, p_from_account text DEFAULT '1000'::text, p_by text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare b record; pay numeric(18,2); j bigint; newpaid numeric(18,2);
begin
  select * into b from public.ap_bills where id=p_bill;
  if b.id is null then raise exception 'bill % not found', p_bill; end if;
  if b.status in ('paid','void') then raise exception 'bill % is %', p_bill, b.status; end if;
  pay := coalesce(round(p_amount,2), b.total - b.amount_paid);
  if pay <= 0 then raise exception 'nothing to pay on bill %', p_bill; end if;
  if b.amount_paid + pay > b.total then raise exception 'overpay bill %: %/%', p_bill, b.amount_paid+pay, b.total; end if;

  j := public.fn_gl_entry(coalesce(p_date,current_date),
         'Payment '||coalesce(b.bill_no,'bill '||p_bill),
         'ap_payment', p_bill::text,
         jsonb_build_array(jsonb_build_object('account','2000','debit', pay),
                           jsonb_build_object('account',p_from_account,'credit', pay)),
         p_by);
  newpaid := b.amount_paid + pay;
  update public.ap_bills
     set amount_paid = newpaid,
         status = case when newpaid >= total then 'paid' else 'partial' end,
         pay_journal_id = j
   where id=p_bill;
  return j;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ap_pay_block_held()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status in ('paid','partial') and coalesce(old.status,'') = 'duplicate_hold' then
    raise exception 'bill % is held as a duplicate and cannot be paid until a person clears the hold',
      coalesce(new.bill_no, new.id::text);
  end if;
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_approval_decide(p_request uuid, p_actor uuid, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare r public.procurement_approval_request;
        v_steps jsonb; v_n int; v_step jsonb; v_role text; v_actor_role text;
        v_next int; v_status text;
begin
  if coalesce(p_decision, '') not in ('approved', 'rejected') then
    raise exception 'decision must be approved or rejected, got %', p_decision;
  end if;
  select * into r from public.procurement_approval_request where id = p_request for update;
  if not found then raise exception 'approval request % not found', p_request; end if;
  if r.status <> 'pending' then
    return jsonb_build_object('ok', false, 'error', 'already_' || r.status,
                              'request_id', r.id, 'status', r.status);
  end if;

  -- THE TRUST BOUNDARY IS HERE, NOT IN THE ENDPOINT. Every caller — the customer endpoint, the
  -- staff console, a psql session — routes through this routine, so the membership and role check
  -- lives in it once instead of in each caller.
  select m.role into v_actor_role
    from public.customer_organization_member m
   where m.organization_id = r.organization_id and m.user_id = p_actor and coalesce(m.active, true);
  if v_actor_role is null then
    if exists (select 1 from public.customer_organization o
                where o.id = r.organization_id and o.owner_customer_id = p_actor) then
      v_actor_role := 'owner';
    else
      raise exception 'actor % is not an active member of organization %', p_actor, r.organization_id;
    end if;
  end if;

  select p.steps into v_steps from public.procurement_approval_policy p where p.id = r.policy_id;
  v_steps := coalesce(v_steps, '[]'::jsonb);
  v_n := jsonb_array_length(v_steps);
  if v_n = 0 then raise exception 'approval request % has no policy steps', r.id; end if;
  if r.current_step < 1 or r.current_step > v_n then
    raise exception 'approval request % is at step % of %', r.id, r.current_step, v_n;
  end if;

  v_step := v_steps -> (r.current_step - 1);
  v_role := v_step->>'role';
  if v_role is not null and v_actor_role <> v_role and v_actor_role <> 'owner' then
    raise exception 'step % (%) is decided by %, not %',
      r.current_step, coalesce(v_step->>'label', v_step->>'key'), v_role, v_actor_role;
  end if;

  if p_decision = 'rejected' then      v_status := 'rejected'; v_next := r.current_step;
  elsif r.current_step >= v_n then     v_status := 'approved'; v_next := r.current_step;
  else                                 v_status := 'pending';  v_next := r.current_step + 1;
  end if;

  update public.procurement_approval_request
     set decisions = decisions || jsonb_build_array(jsonb_build_object(
           'step', r.current_step,
           'key', v_step->>'key',
           'label', coalesce(v_step->>'label', v_step->>'key', 'Step ' || r.current_step),
           'decision', p_decision,
           'by', p_actor,
           'by_role', v_actor_role,
           'at', now(),
           'note', p_note)),
         current_step = v_next,
         status = v_status
   where id = r.id;

  return jsonb_build_object('ok', true, 'request_id', r.id, 'status', v_status,
                            'decided_step', r.current_step, 'current_step', v_next,
                            'steps_total', v_n, 'decided_by', p_actor, 'decided_by_role', v_actor_role);
end $function$


CREATE OR REPLACE FUNCTION public.fn_approval_list(p_customer uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with orgs as (
    select o.id, o.name from public.customer_organization o where o.owner_customer_id = p_customer
    union
    select o.id, o.name from public.customer_organization o
      join public.customer_organization_member m on m.organization_id = o.id
     where m.user_id = p_customer and coalesce(m.active, true)
  )
  select jsonb_build_object(
    'organizations', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'name', name) order by name) from orgs), '[]'::jsonb),
    'policies', coalesce((select jsonb_agg(jsonb_build_object(
          'id', p.id, 'organization_id', p.organization_id, 'name', p.name,
          'active', p.active, 'conditions', p.conditions, 'steps', p.steps) order by p.name)
        from public.procurement_approval_policy p
       where p.organization_id in (select id from orgs)), '[]'::jsonb),
    'requests', coalesce((select jsonb_agg(x order by x->>'created_at' desc) from (
          select jsonb_build_object(
            'id', r.id, 'organization_id', r.organization_id,
            'entity_type', r.entity_type, 'entity_id', r.entity_id,
            'policy_id', r.policy_id, 'status', r.status,
            'current_step', r.current_step, 'created_at', r.created_at,
            'steps', coalesce((select jsonb_agg(jsonb_build_object(
                        'step', t.step, 'key', t.step_key, 'label', t.step_label, 'role', t.step_role,
                        'status', t.step_status, 'decided_by', t.decided_by,
                        'decided_at', t.decided_at, 'note', t.decision_note) order by t.step)
                      from public.v_approval_trace t where t.request_id = r.id), '[]'::jsonb)) as x
            from public.procurement_approval_request r
           where r.organization_id in (select id from orgs)) y), '[]'::jsonb));
$function$


CREATE OR REPLACE FUNCTION public.fn_approval_policy_match(p_org uuid, p_entity_type text, p_amount numeric, p_category text DEFAULT NULL::text, p_emirate text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select p.id
    from public.procurement_approval_policy p
   where p.organization_id = p_org
     and p.active
     and jsonb_typeof(p.steps) = 'array'
     and jsonb_array_length(p.steps) > 0
     and (p.conditions->>'entity_type' is null or p.conditions->>'entity_type' = p_entity_type)
     and coalesce(p_amount, 0) >= coalesce((p.conditions->>'min_amount')::numeric, 0)
     and (p.conditions->'categories' is null or p_category is null or p.conditions->'categories' ? p_category)
     and (p.conditions->'emirates'   is null or p_emirate  is null or p.conditions->'emirates'   ? p_emirate)
   order by coalesce((p.conditions->>'min_amount')::numeric, 0) desc, p.name
   limit 1
$function$


CREATE OR REPLACE FUNCTION public.fn_approval_raise_on_award()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_org uuid; v_policy uuid; v_amount numeric;
begin
  select o.id into v_org from public.customer_organization o
   where o.owner_customer_id = new.customer_id limit 1;
  if v_org is null then
    select m.organization_id into v_org from public.customer_organization_member m
     where m.user_id = new.customer_id and coalesce(m.active, true) limit 1;
  end if;
  if v_org is null then return new; end if;          -- not an enterprise buyer: nothing to approve

  select coalesce(q.customer_price, q.quote_amount) into v_amount
    from public.quotes q
   where q.inquiry_id = new.id and q.supplier_id = new.hired_supplier_id
   order by q.created_at desc limit 1;

  v_policy := public.fn_approval_policy_match(v_org, 'inquiry', v_amount, new.category, new.emirate);
  if v_policy is null then return new; end if;       -- no policy covers this purchase

  if exists (select 1 from public.procurement_approval_request r
              where r.entity_type = 'inquiry' and r.entity_id = new.id::text
                and r.status in ('pending', 'approved')) then
    return new;                                      -- idempotent: one live chain per award
  end if;

  insert into public.procurement_approval_request (organization_id, entity_type, entity_id, policy_id)
  values (v_org, 'inquiry', new.id::text, v_policy);
  return new;
exception when others then
  raise warning 'fn_approval_raise_on_award skipped inquiry %: %', new.id, sqlerrm;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_approval_trace_audit()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_unattributed int; v_gated int; v_msg text;
begin
  -- An action that reached a terminal state with no decider recorded. The authority model exists
  -- precisely so that somebody is accountable for each of these.
  select count(*) into v_unattributed from public.agent_actions
   where status in ('approved','done','auto_done','resolved')
     and coalesce(btrim(decided_by), '') = '';

  -- An action whose department requires approval for its class, that carries no approval at all.
  select count(*) into v_gated from public.agent_actions a
   where a.status in ('approved','done','auto_done','resolved')
     and coalesce(btrim(a.decided_by), '') = ''
     and exists (select 1 from public.org_authority o
                  where o.action_class = a.kind and coalesce(o.max_tier, '') = 'gated');

  if v_unattributed > 0 then
    v_msg := v_unattributed || ' action(s) reached a terminal state with no decider recorded'
          || case when v_gated > 0 then ', ' || v_gated || ' of them in a gated action class' else '' end || '.';
    insert into public.founder_alerts(level, event, detail, channel)
      values (case when v_gated > 0 then 'warn' else 'info' end,
              'Governance monitor — missing approvals', v_msg, 'os');
  end if;
  return jsonb_build_object('monitor', 'missing_approvals', 'unattributed', v_unattributed,
    'gated_without_approval', v_gated, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_archetype_tier(p_archetype text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case p_archetype
           when 'director' then 1
           when 'analyst-controller' then 2
           when 'reviewer-auditor' then 2
           when 'operations-specialist' then 3
           else 9 end;
$function$


CREATE OR REPLACE FUNCTION public.fn_artifact_publish_blocked(p_subject_type text, p_subject_id text, p_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r artifact_review;
begin
  if p_sha256 is null or btrim(p_sha256) = '' then
    return jsonb_build_object('blocked', true, 'reason', 'no_artifact_digest',
      'detail', 'publishing needs the digest of the bytes that will be published');
  end if;
  select * into r from artifact_review
   where subject_type = p_subject_type and subject_id = p_subject_id
     and artifact_sha256 = p_sha256
   order by created_at desc limit 1;

  if r.id is null then
    return jsonb_build_object('blocked', true, 'reason', 'no_review_for_these_bytes',
      'detail', 'the artifact was never reviewed, or it changed after the review');
  end if;
  if r.verdict <> 'pass' then
    return jsonb_build_object('blocked', true, 'reason', 'review_failed',
      'failures', to_jsonb(r.failures), 'review_id', r.id);
  end if;
  return jsonb_build_object('blocked', false, 'review_id', r.id, 'reviewer', r.reviewer_agent,
                            'reviewed_at', r.created_at);
end $function$


CREATE OR REPLACE FUNCTION public.fn_artifact_review_valid()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_author   text;
  v_reviewer text;
begin
  -- Resolve BOTH sides before comparing. coalesce keeps an unrecognised identity as itself rather
  -- than turning it into null: null = null is null, and a guard that evaluates to null lets the
  -- row through.
  v_author   := coalesce(public.fn_org_agent_resolve(new.author_agent),   new.author_agent);
  v_reviewer := coalesce(public.fn_org_agent_resolve(new.reviewer_agent), new.reviewer_agent);

  if new.verdict = 'pass' then
    -- A PASS WITH NO REVIEWER IS WORSE THAN A SELF-REVIEW, and the previous guard permitted it:
    -- a null reviewer_agent is never equal to author_agent, so the comparison answered "not a
    -- self-review" and the row went in with nobody having looked at the artifact.
    if new.reviewer_agent is null or btrim(new.reviewer_agent) = '' then
      raise exception 'artifact % % cannot be marked pass with no reviewer recorded',
        new.subject_type, new.subject_id
        using errcode = 'check_violation';
    end if;

    if new.author_agent is not null and v_author = v_reviewer then
      raise exception
        'artifact_review refuses a self-review: author "%" and reviewer "%" are the same employee (%). %',
        new.author_agent, new.reviewer_agent, v_author,
        'Route the artifact to the QA path (ai_quality_reviewer) or to fn_pick_reviewer(dept, author).'
        using errcode = 'check_violation';
    end if;
  end if;

  -- Store both sides canonical, so every later count over this table measures employees and not
  -- spelling. Same discipline as trg_review_chain_no_self_review.
  new.author_agent   := case when new.author_agent   is null then null else v_author   end;
  new.reviewer_agent := case when new.reviewer_agent is null then null else v_reviewer end;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_assign_founding_rank()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_limit int; v_rank int;
begin
  -- Rank a supplier once, and only once they are a VERIFIED supplier. Claiming a scraped listing
  -- is not registration; registration without documents is not verification.
  if new.founding_rank is not null then return new; end if;
  if coalesce(new.verified,false) is not true then return new; end if;
  if coalesce(new.banned,false) is true then return new; end if;
  if coalesce(new.approval_status,'') in ('rejected','action_required') then return new; end if;

  v_limit := coalesce((select nullif(value,'')::int from public.app_secrets where key='founding_free_limit'), 1000);

  -- Serialise rank assignment so two concurrent verifications cannot take the same number.
  perform pg_advisory_xact_lock(hashtext('qd_founding_rank'));
  select coalesce(max(founding_rank),0) + 1 into v_rank from public.leads;

  new.founding_rank := v_rank;
  -- Exemption is permanent: it is stamped at verification and never recalculated, so a supplier
  -- who was inside the first 1,000 stays exempt even as the base grows.
  new.subscription_exempt := (v_rank <= v_limit);
  return new;
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_assign_founding_ranks()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_limit int; v_max int; v_assigned int := 0;
begin
  v_limit := coalesce((select nullif(value,'')::int from app_secrets where key='founding_free_limit'), 1000);
  select coalesce(max(founding_rank),0) into v_max from leads;
  with candidates as (
    select id, row_number() over (
             order by coalesce(approved_at, registration_submitted_at, created_at) asc, id asc) + v_max as new_rank
    from leads
    where founding_rank is null
      and coalesce(verified,false) = true
      and coalesce(banned,false) = false
      and coalesce(approval_status,'') not in ('rejected','action_required')
  )
  update leads l set founding_rank = c.new_rank,
                     subscription_exempt = (c.new_rank <= v_limit)
  from candidates c where l.id = c.id;
  get diagnostics v_assigned = row_count;
  return json_build_object('newly_ranked', v_assigned, 'highest_rank', (select coalesce(max(founding_rank),0) from leads),
                           'founding_slots_left', greatest(0, v_limit - (select count(*) from leads where founding_rank is not null)),
                           'free_limit', v_limit);
end $function$


CREATE OR REPLACE FUNCTION public.fn_assign_training(p_agent_key text, p_competency text, p_purpose text DEFAULT 'practice'::text, p_n integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_roles text[]; v_dept text; v_rows jsonb;
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  if p_purpose not in ('practice','retest','drift_check') then
    raise exception 'purpose must be practice, retest or drift_check';
  end if;
  select array_agg(packaged_role_id) into v_roles from org_role_identity where agent_key = p_agent_key;
  select packaged_department into v_dept from org_role_identity where agent_key = p_agent_key limit 1;
  if v_roles is null then
    return jsonb_build_object('assigned', 0, 'reason', 'agent has no role identity');
  end if;

  with pool as (
    select c.case_id, c.case_family, c.competency, c.scope_key
      from agent_training_case c
     -- The parentheses matter: AND binds tighter than OR, so without them the competency
     -- filter applied only to the department branch and every role case slipped past it.
     where ((c.scope_type = 'role' and c.scope_key = any(v_roles))
         or (c.scope_type = 'department' and c.scope_key = v_dept))
       and (p_competency is null or c.competency = p_competency)
  ), unseen as (
    select p.* from pool p
     where not exists (select 1 from agent_training_attempt a
                        where a.agent_key = p_agent_key and a.case_id = p.case_id)
     order by md5(p.case_id || p_agent_key || p_purpose)     -- stable per (agent,purpose), not an ordered list
     limit greatest(coalesce(p_n, 5), 1)
  ), ins as (
    insert into agent_training_attempt (agent_key, case_id, purpose, competency)
    select p_agent_key, case_id, p_purpose, competency from unseen
    on conflict (agent_key, case_id, purpose) do nothing
    returning id, case_id
  )
  select jsonb_agg(jsonb_build_object('attempt_id', i.id, 'case_id', i.case_id,
                                      'payload', c.payload))
    into v_rows
    from ins i join agent_training_case c on c.case_id = i.case_id;

  return jsonb_build_object('assigned', coalesce(jsonb_array_length(v_rows), 0),
                            'purpose', p_purpose, 'cases', coalesce(v_rows, '[]'::jsonb));
end $function$


CREATE OR REPLACE FUNCTION public.fn_audit_prune()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n_audit int; n_undo int;
begin
  delete from os_audit_log where action='agent_run' and at < now() - interval '180 days';
  get diagnostics n_audit = row_count;

  delete from undo_log where created_at < now() - interval '90 days';
  get diagnostics n_undo = row_count;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('audit_prune', now(), now(), 'ok',
          jsonb_build_object('audit_pruned',n_audit,'undo_pruned',n_undo),
          'Retention: '||n_audit||' agent-run audit rows and '||n_undo||' undo rows older than their window removed.');

  return jsonb_build_object('audit_pruned',n_audit,'undo_pruned',n_undo);
end $function$


CREATE OR REPLACE FUNCTION public.fn_authority_rank(p text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- How much UNSUPERVISED power the tier confers. advisory advises only; gated needs approval
  -- before acting; supervised acts and is reviewed after; autonomous acts unreviewed.
  select case p when 'advisory' then 0 when 'gated' then 1 when 'supervised' then 2
                when 'autonomous' then 3 else 3 end;   -- unknown tier ranks highest: fail closed
$function$


CREATE OR REPLACE FUNCTION public.fn_authorize(p_email text, p_action text, p_attrs jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_role text; c jsonb; ok boolean:=false; reason text; maxamt numeric; amt numeric;
begin
  v_role := public.fn_role_of(p_email);
  if v_role='owner' then return jsonb_build_object('allowed',true,'role',v_role,'reason','owner has full access'); end if;
  select rp.constraint_json into c from role_permissions rp where rp.role=v_role and rp.action=p_action;
  if c is null then
    if exists(select 1 from role_permissions rp where rp.role=v_role and rp.action='*') then
      return jsonb_build_object('allowed',true,'role',v_role,'reason','role wildcard'); end if;
    return jsonb_build_object('allowed',false,'role',v_role,'reason','role "'||v_role||'" lacks permission "'||p_action||'"');
  end if;
  ok := true; reason := 'granted';
  if c ? 'max_amount_aed' then
    maxamt := (c->>'max_amount_aed')::numeric; amt := nullif(p_attrs->>'amount_aed','')::numeric;
    if amt is not null and amt > maxamt then ok:=false; reason:='amount '||amt||' exceeds role limit '||maxamt; end if;
  end if;
  if c ? 'purpose' and coalesce(p_attrs->>'purpose','') <> (c->>'purpose') then ok:=false; reason:='purpose must be '||(c->>'purpose'); end if;
  return jsonb_build_object('allowed',ok,'role',v_role,'reason',reason,'constraint',c);
end $function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_audit()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with per as (
    select d.dept_key, d.name,
      (select max(created_at) from org_memory m where m.scope=d.dept_key and m.kind='plan')   as last_plan,
      (select max(created_at) from org_memory m where m.scope=d.dept_key and m.kind='lesson') as last_lesson,
      (select count(*) from org_tasks t where t.dept_key=d.dept_key and t.status in ('assigned','proposed','in_progress')) as open_tasks,
      (select count(*) from org_tasks t where t.dept_key=d.dept_key and t.status='done' and t.updated_at > now()-interval '7 days') as done_7d
    from org_departments d where d.active
  )
  select jsonb_build_object(
    'as_of', now(),
    'departments', (select jsonb_agg(jsonb_build_object(
        'dept', dept_key, 'name', name,
        'last_plan', last_plan, 'last_lesson', last_lesson, 'open_tasks', open_tasks, 'done_7d', done_7d,
        'status', case
          when (last_plan is null or last_plan < now()-interval '4 days') and open_tasks=0 and done_7d=0 then 'red'
          when (last_plan is null or last_plan < now()-interval '3 days') then 'amber'
          else 'green' end
      ) order by dept_key) from per),
    'summary', (select jsonb_build_object(
        'green', count(*) filter (where (last_plan is not null and last_plan >= now()-interval '3 days')),
        'stalled', count(*) filter (where (last_plan is null or last_plan < now()-interval '4 days') and open_tasks=0 and done_7d=0))
      from per)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_audit_run()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a jsonb; stalled int;
begin
  a := fn_autonomy_audit();
  stalled := coalesce((a->'summary'->>'stalled')::int, 0);
  insert into org_memory(scope,kind,content,source)
    values ('exec','audit','Autonomy self-audit: '||(a->'summary')::text||' — '||stalled||' department loop(s) stalled.', 'autonomy_audit');
  if stalled > 0 then
    insert into agent_actions(agent,kind,status,risk,title,recommendation,detail)
    values ('brief','autonomy_stall','pending','medium',
      stalled||' department loop(s) have stalled',
      'One or more departments have not planned in 4+ days and have no open or recent work. Check fn_autonomy_audit().',
      a);
  end if;
  return a;
end $function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_check(p_kind text, p_target_table text, p_recommendation text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select case
    when p_kind ~* 'refund|payout|payment|withdraw|transfer|invoice_pay|money|charge' then 'approve'
    when p_kind ~* 'delete|purge|remove_record' and coalesce(p_target_table,'') in ('leads','customers') then 'approve'
    when p_kind = 'approve_supplier' and coalesce(p_recommendation,'') <> 'approve' then 'approve'
    else 'auto'
  end;
$function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_class(p_kind text, p_target_table text, p_recommendation text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare pol jsonb; d text;
begin
  -- Policy-bounded carve-out (chairman doctrine 2026-07-24): a refund fully inside
  -- the published policy window is routine work, not an executive decision.
  if p_kind = 'refund_within_window' then return 'ack'; end if;
  -- HARD RAILS: money, destructive, and supplier approval can never be auto-cleared by policy.
  if p_kind ~* 'refund|payout|payment|withdraw|transfer|invoice_pay|money|charge' then return 'founder'; end if;
  if p_kind ~* 'delete|purge|remove_record' and coalesce(p_target_table,'') in ('leads','customers') then return 'founder'; end if;
  if p_kind='approve_supplier' and coalesce(p_recommendation,'')='approve' then return 'clean_supplier'; end if;
  if p_kind='approve_supplier' then return 'founder'; end if;
  -- POLICY: founder-editable per-kind disposition.
  select value into pol from public.decision_policy where key='action_autonomy';
  d := pol->>p_kind;
  if d in ('ack','founder','keep') then return d; end if;
  -- LEGACY FALLBACK
  if p_kind in ('security_alert','compliance_update','incident','supply_health','sla_no_supply') then return 'ack'; end if;
  return 'keep';
end $function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_control_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_key    text := coalesce(new.key, old.key);
  v_old    text := old.value;
  v_new    text := new.value;
  v_reason text := nullif(trim(coalesce(current_setting('app.change_reason', true), '')), '');
  v_dir    text := 'neutral';
  v_widen  boolean := false;
begin
  if v_key not in ('agent_autonomy_enabled','agent_autonomy_from','cos_frozen','ai_kill_switch') then
    return coalesce(new, old);
  end if;

  if tg_op = 'DELETE' then
    -- Deleting cos_frozen or ai_kill_switch removes a brake; deleting the enable flag adds one.
    v_widen := v_key in ('cos_frozen','ai_kill_switch');
  elsif v_key = 'agent_autonomy_enabled' then
    v_widen := v_new = 'true' and coalesce(v_old,'false') <> 'true';
  elsif v_key = 'cos_frozen' then
    v_widen := coalesce(v_new,'false') <> 'true' and v_old = 'true';
  elsif v_key = 'ai_kill_switch' then
    v_widen := coalesce(v_new,'false') = 'false' and coalesce(v_old,'false') <> 'false';
  elsif v_key = 'agent_autonomy_from' then
    v_widen := tg_op = 'INSERT' or v_new is distinct from v_old;   -- any move of the date is a widen
  end if;
  v_dir := case when v_widen then 'widen' else 'tighten' end;

  if v_widen and (v_reason is null or length(v_reason) < 12) then
    raise exception
      'app_secrets.%: widening autonomy needs a stated reason. Run '
      '`set local app.change_reason = ''why, in a sentence'';` in the same transaction. '
      'A PostgREST update from an edge function cannot set that, which is the point — this key '
      'was reachable by all 190 service-role functions. Tightening (freeze, kill switch, disable) '
      'never needs a reason and is never refused.', v_key
      using errcode = 'check_violation';
  end if;

  insert into public.autonomy_control_audit (object, op, direction, old_value, new_value, reason)
  values ('app_secrets:' || v_key, tg_op, v_dir, v_old, v_new, v_reason);

  return coalesce(new, old);
end $function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_dispose()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare r record; n_appr int:=0; n_ack int:=0; n_queue int:=0; c text;
begin
  for r in select * from public.agent_actions
           where status in ('pending','held_for_review','proposed','open','needs_review')
  loop
    c := public.fn_autonomy_class(r.kind, r.target_table, r.recommendation);
    if c='clean_supplier' and r.target_id ~ '^\d+$' then
      update public.leads set approval_status='approved', approved_at=now(),
             approval_decided_by='chief_of_staff (auto)', lifecycle_stage='active'
       where id=r.target_id::bigint and approval_status='pending' and coalesce(banned,false)=false;
      update public.agent_actions set status='approved', decided_by='chief_of_staff (auto)', decided_at=now() where id=r.id;
      n_appr := n_appr+1;
    elsif c='ack' then
      update public.agent_actions set status='auto_done', decided_by='chief_of_staff (auto)', decided_at=now() where id=r.id;
      n_ack := n_ack+1;
    else  -- 'founder' or 'keep' → remains visible in the queue
      n_queue := n_queue+1;
    end if;
  end loop;
  return jsonb_build_object('approved_suppliers',n_appr,'auto_cleared_logged',n_ack,'in_your_queue',n_queue);
end $function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_blockers text[] := '{}';
  v_p0       record;
  v_enabled  text;
  v_from     text;
  v_frozen   text;
  v_kill     text;
begin
  for v_p0 in
    select id, item from public.spec_backlog where priority = 0 and status = 'open' order by id
  loop
    v_blockers := array_append(v_blockers, 'spec_backlog#' || v_p0.id || ' open: ' || left(v_p0.item, 90));
  end loop;

  select value into v_enabled from public.app_secrets where key = 'agent_autonomy_enabled';
  select value into v_from    from public.app_secrets where key = 'agent_autonomy_from';
  select value into v_frozen  from public.app_secrets where key = 'cos_frozen';
  select value into v_kill    from public.app_secrets where key = 'ai_kill_switch';

  if coalesce(v_enabled, 'false') <> 'true' then
    v_blockers := array_append(v_blockers, 'agent_autonomy_enabled is not true');
  end if;
  if v_frozen = 'true' then
    v_blockers := array_append(v_blockers, 'cos_frozen is true');
  end if;
  if v_kill is not null and v_kill <> 'false' then
    v_blockers := array_append(v_blockers, 'ai_kill_switch is set');
  end if;
  begin
    if v_from is not null and v_from::date > current_date then
      v_blockers := array_append(v_blockers, 'agent_autonomy_from is in the future: ' || v_from);
    end if;
  exception when others then
    v_blockers := array_append(v_blockers, 'agent_autonomy_from is unparseable: ' || coalesce(v_from, 'null'));
  end;

  return jsonb_build_object(
    'allowed',    cardinality(v_blockers) = 0,
    'blockers',   to_jsonb(v_blockers),
    'checked_at', now());
exception when others then
  return jsonb_build_object(
    'allowed', false,
    'blockers', to_jsonb(array['autonomy status could not be determined: ' || sqlerrm]),
    'checked_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_backup_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_last timestamptz; v_status text; v_stale boolean; v_owner text; v_open int;
begin
  select started_at, status into v_last, v_status
    from agent_runs where agent='backup' order by started_at desc limit 1;
  v_stale := (v_last is null) or (v_last < now() - interval '26 hours') or (coalesce(v_status,'')='error');
  if not v_stale then
    return jsonb_build_object('ok',true,'last',v_last,'status',v_status);
  end if;
  select count(*) into v_open from agent_actions
    where kind='backup_alert' and coalesce(status,'') in ('pending','needs_review')
  -- A DEDUPE WINDOW THE SAME LENGTH AS THE CHECK INTERVAL SUPPRESSES ON A KNIFE EDGE (13 Aug 2026).
  -- The backup was broken from 10 to 12 August and this watcher produced exactly ONE alert:
  -- agent_action 2662 at 2026-08-11 08:00:00.63, one email, still pending. The watcher runs daily
  -- at 08:00, and the previous row was 24 hours old minus a fraction of a second, so it was still
  -- inside `created_at > now() - 24 hours` and the second day's alert was skipped. Twenty hours is
  -- strictly shorter than the cadence, so a daily check always re-alerts on a continuing outage
  -- while a ten-minute caller still cannot spam.
      and created_at > now()-interval '20 hours';

  if v_open = 0 then
    insert into agent_actions(agent,kind,status,risk,title,recommendation,target_table,detail)
    values('security','backup_alert','pending','high',
      'Backup may have failed or is overdue',
      'The daily logical backup has not completed successfully in the last 26 hours (last: '||coalesce(v_last::text,'never')||', status: '||coalesce(v_status,'unknown')||'). Check the backup function and logs. Managed daily backups and the Dropbox mirror remain as fallbacks.',
      'agent_runs', jsonb_build_object('last_backup',v_last,'last_status',v_status));
    insert into security_events(kind,severity,source,subject,detail)
    values('backup_overdue','high','backup','logical backup',
      jsonb_build_object('last_backup',v_last,'last_status',v_status));
    select split_part(coalesce(value,'management@quotesdone.com'),',',1) into v_owner
      from app_secrets where key='admin_emails';
    insert into notifications(type,to_email,to_role,channel,subject,body,status)
    values('backup_alert', v_owner, 'admin','email','QuotesDone: backup overdue or failed',
      'The daily logical backup has not completed in the last 26 hours (last: '||coalesce(v_last::text,'never')||', status: '||coalesce(v_status,'unknown')||'). Please check. Managed daily backups + the Dropbox mirror remain as fallbacks.','queued');
    -- AN OUTAGE THAT LASTS MUST GET LOUDER, NOT REPEAT ITSELF. One identical email a day says the
    -- same thing on day one and on day five, and the day-five reader has already filed the day-one
    -- copy. Past 48 hours this also raises a founder_alert and states the age in hours, which is
    -- the number that decides whether this is a hiccup or a company with no restorable backup.
    if v_last is null or v_last < now() - interval '48 hours' then
      insert into founder_alerts(level,event,detail,channel)
      values('crit','backup_outage_prolonged',
        'The daily logical backup has now been failing for '
        || coalesce(round(extract(epoch from (now()-v_last))/3600)::text || ' hours', 'as long as there are records')
        || ' (last run: '||coalesce(v_last::text,'never')||', status: '||coalesce(v_status,'unknown')
        || '). This is past the point where one more day of silence is acceptable: verify the backup '
        || 'function itself, then run dr_drill to prove the newest backup still restores.','system');
    end if;

  end if;
  return jsonb_build_object('alerted',true,'last',v_last,'status',v_status,'existing_open',v_open);
end $function$


CREATE OR REPLACE FUNCTION public.fn_ban_overdue_dues()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_days int; v_n int := 0; v_admin text;
begin
  v_days  := coalesce((select num_value from public.gl_settings where key='clawback_ban_days'), 90)::int;
  v_admin := coalesce((select split_part(value,',',1) from public.app_secrets where key='admin_emails'),'management@quotesdone.com');

  for r in
    select d.id, d.supplier_id, d.amount_due, d.admin_fee, d.interest_amount, d.due_date,
           l.company_name, coalesce(l.claimed_by,l.email) as email,
           l.accepted_terms_at, l.accepted_terms_version, l.signed_terms_path, l.banned
    from public.supplier_dues d
    join public.leads l on l.id = d.supplier_id
    where d.paid_at is null
      and coalesce(d.status,'') not in ('paid','settled','waived','cancelled')
      and coalesce(d.amount_due,0) > 0
      and d.due_date is not null
      and current_date >= (d.due_date::date + v_days)
      and d.legal_escalated_at is null
  loop
    update public.supplier_dues
       set status = 'legal', legal_stage = 'pending_case', legal_escalated_at = now()
     where id = r.id;

    update public.leads
       set banned = true,
           banned_reason = 'Unpaid refund clawback of AED ' ||
                           round(coalesce(r.amount_due,0)+coalesce(r.admin_fee,0)+coalesce(r.interest_amount,0),2) ||
                           ' more than ' || v_days || ' days past due (due ' || r.due_date::date || ').',
           matching_blocked = true,
           matching_block_reason = 'Banned: unpaid refund clawback escalated to legal'
     where id = r.supplier_id;

    insert into public.founder_alerts(level, event, detail, channel)
    values ('crit', 'supplier_banned_legal',
      coalesce(r.company_name,'Supplier #'||r.supplier_id) || ' has been banned and due #' || r.id ||
      ' escalated to legal: AED ' || round(coalesce(r.amount_due,0)+coalesce(r.admin_fee,0)+coalesce(r.interest_amount,0),2) ||
      ' unpaid for over ' || v_days || ' days. ' ||
      case when r.accepted_terms_at is null
           then '*** NO SIGNED TERMS ON RECORD - the supplier agreement cannot be produced as evidence, so a filing may not be supportable. Verify before instructing the legal agent. ***'
           else 'Terms accepted ' || r.accepted_terms_at::date || ' (version ' || coalesce(r.accepted_terms_version,'?') || ') - available as supporting evidence.'
      end, 'system');

    v_n := v_n + 1;
  end loop;

  return v_n;
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_bi_snapshot()
 RETURNS TABLE(metric_key text, value numeric, error text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v numeric; e text;
begin
  for r in select m.metric_key, m.measure_sql from metric_definition m where m.active loop
    v := null; e := null;
    begin
      execute r.measure_sql into v;
    exception when others then e := left(sqlerrm, 200);
    end;
    insert into metric_snapshot (metric_key, value, error) values (r.metric_key, v, e);
    metric_key := r.metric_key; value := v; error := e;
    return next;
  end loop;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_binding_constraint(p_days integer DEFAULT 90)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_since timestamptz := now() - make_interval(days => greatest(p_days, 1));
  v_visitors_reason text;
  v_stages jsonb;
begin
  select no_measure_reason into v_visitors_reason
    from public.company_goals where key = 'website_visitors';

  with raw as (
    select
      (select count(*) from public.customers  where created_at >= v_since)              as customers,
      (select count(*) from public.inquiries  where created_at >= v_since)              as inquiries,
      (select count(distinct q.inquiry_id) from public.quotes q where q.created_at >= v_since)
                                                                                        as inquiries_quoted,
      (select count(*) from public.quotes     where created_at >= v_since)              as quotes,
      (select count(*) from public.transactions
        where revealed_at >= v_since and refund_confirmed_at is null)                   as paid_reveals,
      (select count(*) from public.supplier_capabilities where confirmed_at is not null) as confirmed_suppliers
  ),
  st as (
    select * from (values
      ('visitors_to_registration', 'Site visitors who register',      null::bigint, null::bigint,
       v_visitors_reason),
      ('registration_to_inquiry',  'Registered customers who post an inquiry',
       (select customers from raw), (select inquiries from raw), null),
      ('inquiry_to_quote',         'Inquiries that receive at least one quote',
       (select inquiries from raw), (select inquiries_quoted from raw), null),
      ('quote_to_paid_reveal',     'Quoted inquiries that reach a paid reveal',
       (select inquiries_quoted from raw), (select paid_reveals from raw), null)
    ) v(stage_key, stage, denominator, numerator, not_measurable_reason))
  select jsonb_agg(jsonb_build_object(
      'stage_key', stage_key,
      'stage', stage,
      'denominator', denominator,
      'numerator', numerator,
      'state', case
        when not_measurable_reason is not null then 'not_instrumented'
        when denominator is null or numerator is null then 'not_measured'
        when denominator = 0 then 'no_demand'
        else 'measured' end,
      'pass_through_pct', case
        when not_measurable_reason is not null or denominator is null
          or numerator is null or denominator = 0 then null
        else round(100.0 * numerator / denominator, 1) end,
      'reason', not_measurable_reason)
    order by stage_key)
    into v_stages from st;

  return jsonb_build_object(
    'window_days', p_days,
    'stages', v_stages,
    'confirmed_suppliers', (select count(*) from public.supplier_capabilities where confirmed_at is not null),
    -- The binding stage is the lowest MEASURED pass-through. Stages that are not instrumented or
    -- have no demand are excluded from the ranking and listed separately, because a stage nobody
    -- can measure could easily be the real constraint and must not be quietly ruled out.
    'binding_stage', (
      select e->>'stage_key' from jsonb_array_elements(v_stages) e
       where e->>'state' = 'measured'
       order by (e->>'pass_through_pct')::numeric asc limit 1),
    'binding_pass_through_pct', (
      select (e->>'pass_through_pct')::numeric from jsonb_array_elements(v_stages) e
       where e->>'state' = 'measured'
       order by (e->>'pass_through_pct')::numeric asc limit 1),
    'stages_ranked', (select count(*) from jsonb_array_elements(v_stages) e
                       where e->>'state' = 'measured'),
    'stages_excluded_from_the_ranking', (
      select coalesce(jsonb_agg(jsonb_build_object('stage_key', e->>'stage_key',
                                                   'state', e->>'state',
                                                   'reason', e->>'reason')), '[]'::jsonb)
        from jsonb_array_elements(v_stages) e where e->>'state' <> 'measured'),
    'reallocation_rule',
      'Effort moved to a stage other than the binding one changes activity, not revenue. If a stage '
      ||'is listed as not_instrumented, the honest answer is that the binding constraint is not '
      ||'known yet and the first move is to instrument it.',
    'trajectory', public.fn_revenue_trajectory());
end $function$


CREATE OR REPLACE FUNCTION public.fn_blueprint_regressions(p_spec text, p_ref text)
 RETURNS TABLE(check_id text, name text, was boolean, now_ boolean, direction text, evidence text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with runs as (
    select distinct run_id, run_at from os_blueprint_result
     where spec_file = p_spec and ref = p_ref order by run_at desc limit 2
  ), newest as (select * from os_blueprint_result where run_id = (select run_id from runs order by run_at desc limit 1)),
     prev   as (select * from os_blueprint_result where run_id = (select run_id from runs order by run_at asc  limit 1))
  select n.check_id, n.name, p.ok, n.ok,
         case when p.ok and not n.ok then 'REGRESSED'
              when not p.ok and n.ok then 'FIXED'
              else 'unchanged' end,
         n.evidence
    from newest n
    join prev p using (check_id)
   where (select count(*) from runs) = 2
     and p.ok is distinct from n.ok
   order by 5, 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_blueprint_result_prune()
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with d as (delete from os_blueprint_result where run_at < now() - interval '90 days' returning 1)
  select count(*)::int from d;
$function$


CREATE OR REPLACE FUNCTION public.fn_board_report()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  inq_t int; inq_p int; q_t int; q_p int; c_t int; c_p int; s_t int; s_p int;
  rev_t numeric; rev_p numeric; conv numeric; qpr numeric;
  gap int; expired int; crit int; gatepass numeric;
  health jsonb; eval jsonb; officer text; topcats text;
  wtrend text; body text; owner text; d jsonb;
begin
  select count(*) filter (where created_at>=now()-interval '7 days'),
         count(*) filter (where created_at>=now()-interval '14 days' and created_at<now()-interval '7 days')
    into inq_t, inq_p from inquiries;
  select count(*) filter (where created_at>=now()-interval '7 days'),
         count(*) filter (where created_at>=now()-interval '14 days' and created_at<now()-interval '7 days')
    into q_t, q_p from quotes;
  select count(*) filter (where created_at>=now()-interval '7 days'),
         count(*) filter (where created_at>=now()-interval '14 days' and created_at<now()-interval '7 days')
    into c_t, c_p from customers;
  select count(*) filter (where registration_submitted_at>=now()-interval '7 days'),
         count(*) filter (where registration_submitted_at>=now()-interval '14 days' and registration_submitted_at<now()-interval '7 days')
    into s_t, s_p from leads;
  select coalesce(sum(reveal_fee) filter (where revealed_at>=now()-interval '7 days'),0),
         coalesce(sum(reveal_fee) filter (where revealed_at>=now()-interval '14 days' and revealed_at<now()-interval '7 days'),0)
    into rev_t, rev_p from transactions where coalesce(refund_status,'')<>'approved';
  select round(100.0*count(distinct t.inquiry_id)/nullif(count(distinct i.id),0),1) into conv
    from inquiries i left join transactions t on t.inquiry_id=i.id where i.created_at>=now()-interval '30 days';
  select round(avg(qc),1) into qpr from (select count(*) qc from quotes q join inquiries i on i.id=q.inquiry_id where i.created_at>=now()-interval '30 days' group by q.inquiry_id) z;
  select count(*) into gap from inquiries i where i.status not in ('completed','accepted','closed','cancelled') and not exists(select 1 from inquiry_matches m where m.inquiry_id=i.id);
  begin select count(*) into expired from leads where license_expiry<current_date and coalesce(approval_status,'')='approved'; exception when others then expired:=0; end;
  select count(*) into crit from founder_alerts where public.fn_alert_severe(level) and created_at>=now()-interval '7 days';
  select round(100.0*count(*) filter (where nullif(quality->>'score','')::numeric>=60)/nullif(count(*) filter (where quality is not null),0),1) into gatepass
    from quotes where created_at>=now()-interval '7 days';
  begin select public.fn_health_index() into health; exception when others then health:=null; end;
  begin select public.fn_eval_snapshot(30) into eval; exception when others then eval:=null; end;
  select string_agg(cat,', ') into topcats from (select coalesce(nullif(category,''),'(uncat)') cat, count(*) n from inquiries where created_at>=now()-interval '7 days' group by 1 order by n desc limit 5) z;
  officer := public.fn_officer_recs(8);

  wtrend :=
    '- RFQs: '||inq_t||' (prev '||inq_p||')'||E'\n'||
    '- Quotes: '||q_t||' (prev '||q_p||')'||E'\n'||
    '- New customers: '||c_t||' (prev '||c_p||')'||E'\n'||
    '- New supplier registrations: '||s_t||' (prev '||s_p||')'||E'\n'||
    '- Revenue: AED '||round(rev_t)||' (prev AED '||round(rev_p)||')';

  d := jsonb_build_array();
  if expired>0 then d := d||to_jsonb('Review '||expired||' supplier(s) with expired trade licence'::text); end if;
  if crit>0 then d := d||to_jsonb('Address '||crit||' critical alert(s) from this week'::text); end if;
  if gap>0 then d := d||to_jsonb('Decide sourcing for '||gap||' unmatched demand item(s)'::text); end if;

  body := public.fn_report_skeleton(
    'QuotesDone Weekly Board Report — '||to_char(current_date,'DD Mon YYYY'),
    'Marketplace health '||coalesce(health->>'index','—')||'/100 ('||coalesce(health->>'band','no data')||'). '||
      inq_t||' RFQs and '||q_t||' quotes this week; revenue AED '||round(rev_t)||'; 30-day conversion '||coalesce(conv::text,'—')||'%.',
    jsonb_build_array(
      jsonb_build_object('heading','Key Metrics (this week)','body',
        'RFQs '||inq_t||' · Quotes '||q_t||' · Avg quotes/RFQ (30d) '||coalesce(qpr::text,'—')||' · Conversion (30d) '||coalesce(conv::text,'—')||'% · Revenue AED '||round(rev_t)||' · Quote-gate pass '||coalesce(gatepass::text,'—')||'%'),
      jsonb_build_object('heading','Trends (WoW)','body',wtrend),
      jsonb_build_object('heading','Growth','body','Top categories: '||coalesce(topcats,'—')),
      jsonb_build_object('heading','AI Performance','body','Health index '||coalesce(health->>'index','—')||'/100; eval sample '||coalesce(eval->'samples'->>'quotes','0')||' quotes, gate pass '||coalesce(gatepass::text,'—')||'%.'),
      jsonb_build_object('heading','Issues','body','Supply gaps: '||gap||' · Expired licences: '||expired||' · Critical alerts (7d): '||crit),
      jsonb_build_object('heading','Recommendations (officers)','body',coalesce(officer,'No officer recommendations available yet.'))
    ),
    d,
    'Health: '||coalesce(health::text,'n/a')||E'\n'||'Eval: '||coalesce(eval::text,'n/a'));

  insert into public.board_reports(week_start, title, body, kpis)
  values (date_trunc('week',current_date)::date,
          'QuotesDone Weekly Board Report — '||to_char(current_date,'DD Mon YYYY'), body,
          jsonb_build_object('rfqs',inq_t,'quotes',q_t,'customers',c_t,'suppliers',s_t,'revenue',rev_t,'conversion',conv,'gate_pass',gatepass,'health',(health->>'index')));

  select split_part(coalesce(value,'management@quotesdone.com'),',',1) into owner from app_secrets where key='admin_emails';
  insert into notifications(type,to_email,to_role,channel,subject,body)
  values ('board_report', coalesce(owner,'management@quotesdone.com'),'admin','email',
          'QuotesDone Weekly Board Report — '||to_char(current_date,'DD Mon'), body);
end $function$


CREATE OR REPLACE FUNCTION public.fn_board_review(p_subject text, p_subject_ref text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare adv record; ch jsonb; v_rec text; v_conf numeric; v_supply int; v_rev numeric;
  n_pro int:=0; n_cond int:=0; n_against int:=0; v_out jsonb := '[]'::jsonb;
begin
  ch := fn_challenge(p_subject,'board','board');
  select count(*) into v_supply from leads where approval_status='approved';
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev from transactions where revealed_at>now()-interval '30 days';

  for adv in select * from board_advisor where active order by advisor_key loop
    -- each advisor reasons through its own lens against the same facts
    if adv.advisor_key='risk' and (ch->>'stance')='recommend_against' then
      v_rec:='do_not_proceed'; v_conf:=0.85;
    elsif adv.advisor_key='economist' and v_rev=0 then
      v_rec:='proceed_with_conditions'; v_conf:=0.7;
    elsif adv.advisor_key in ('customer','supplier') and v_supply=0 then
      v_rec:='abstain'; v_conf:=0.5;
    elsif (ch->>'stance')='recommend_against' then
      v_rec:='do_not_proceed'; v_conf:=0.75;
    elsif (ch->>'stance')='concern' then
      v_rec:='proceed_with_conditions'; v_conf:=0.65;
    else
      v_rec:='proceed'; v_conf:=0.6;
    end if;

    insert into board_opinion (subject,subject_ref,advisor_key,recommendation,rationale,confidence)
    values (p_subject,p_subject_ref,adv.advisor_key,v_rec,
      adv.name||' ('||adv.lens||') asks: '||adv.asks||' — '||
      case v_rec
        when 'do_not_proceed' then 'On the evidence available this fails that test.'
        when 'proceed_with_conditions' then 'Proceed only with a named metric, a captured baseline and a reversal path.'
        when 'abstain' then 'There is no data on this side of the marketplace yet; an opinion would be invention.'
        else 'Nothing in this lens argues against it.' end, v_conf);

    if v_rec='proceed' then n_pro:=n_pro+1;
    elsif v_rec='proceed_with_conditions' then n_cond:=n_cond+1;
    elsif v_rec='do_not_proceed' then n_against:=n_against+1; end if;

    v_out := v_out || jsonb_build_array(jsonb_build_object('advisor',adv.name,'lens',adv.lens,'recommendation',v_rec,'confidence',v_conf));
  end loop;

  return jsonb_build_object('subject',p_subject,'proceed',n_pro,'with_conditions',n_cond,
    'against',n_against,'abstained',(select count(*) from board_advisor where active)-n_pro-n_cond-n_against,
    'board_verdict', case when n_against>0 then 'DO NOT PROCEED' when n_cond>0 then 'PROCEED WITH CONDITIONS' else 'PROCEED' end,
    'challenge_stance', ch->>'stance', 'opinions', v_out);
end $function$


CREATE OR REPLACE FUNCTION public.fn_boq_fixture_score(p_fixture_id bigint, p_actual jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare f public.boq_fixture%rowtype; d jsonb := '[]'::jsonb;
  v_checked int := 0; v_matched int := 0;
  v_doors numeric; v_windows numeric; v_total numeric;
begin
  select * into f from public.boq_fixture where id = p_fixture_id;
  if not found then return jsonb_build_object('error','no such fixture'); end if;

  -- Largest matching line wins: a plan can list "D1 flush wooden doors" and a separate
  -- "door frames" line, and the schedule quantity is the one being checked.
  select max((l->>'qty')::numeric) into v_doors
    from jsonb_array_elements(coalesce(p_actual->'boq','[]'::jsonb)) l
   where (l->>'description') ~* '\ydoor' and (l->>'qty') ~ '^[0-9.]+$'
     and coalesce(l->>'unit','') ~* 'no|ea|pc';
  select max((l->>'qty')::numeric) into v_windows
    from jsonb_array_elements(coalesce(p_actual->'boq','[]'::jsonb)) l
   where (l->>'description') ~* '\ywindow' and (l->>'qty') ~ '^[0-9.]+$'
     and coalesce(l->>'unit','') ~* 'no|ea|pc';
  v_total := nullif(p_actual->>'total_area_sqm','')::numeric;

  if f.expect_doors is not null then
    v_checked := v_checked + 1;
    if v_doors = f.expect_doors then v_matched := v_matched + 1; end if;
    d := d || jsonb_build_array(jsonb_build_object('field','doors','expected',f.expect_doors,
           'actual',v_doors,'match', v_doors = f.expect_doors));
  end if;

  if f.expect_windows is not null then
    v_checked := v_checked + 1;
    if v_windows = f.expect_windows then v_matched := v_matched + 1; end if;
    d := d || jsonb_build_array(jsonb_build_object('field','windows','expected',f.expect_windows,
           'actual',v_windows,'match', v_windows = f.expect_windows));
  end if;

  -- The stated built-up area is preferred; where the drawing prints none, the room sum is the
  -- only figure it states and is what the pipeline's total is compared against.
  if coalesce(f.expect_total_sqm, f.expect_rooms_sqm) is not null then
    declare v_exp numeric := coalesce(f.expect_total_sqm, f.expect_rooms_sqm); v_hit boolean;
    begin
      v_hit := v_total is not null
               and abs(v_total - v_exp) <= v_exp * (f.tolerance_pct / 100.0);
      v_checked := v_checked + 1;
      if v_hit then v_matched := v_matched + 1; end if;
      d := d || jsonb_build_array(jsonb_build_object('field','total_area_sqm','expected',v_exp,
             'actual',v_total,'tolerance_pct',f.tolerance_pct,'match',v_hit));
    end;
  end if;

  return jsonb_build_object('checked', v_checked, 'matched', v_matched,
    'score_pct', case when v_checked > 0 then round(100.0*v_matched/v_checked, 2) else null end,
    'detail', d, 'boq_lines', jsonb_array_length(coalesce(p_actual->'boq','[]'::jsonb)));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_brand_scan()
 RETURNS TABLE(rule_key text, hits integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- 1. Supplier claims to be registered but has no trade licence number.
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'fake_supplier','high','lead', l.id::text, 'no_trade_licence',
         'Supplier reached registration without a trade licence number.',
         jsonb_build_object('company', l.company_name, 'status', l.registration_status)
  from leads l
  where l.registration_submitted_at is not null
    and coalesce(nullif(trim(l.trade_license_no),''), null) is null
  on conflict do nothing;

  -- 2. Licence expired but still approved to receive RFQs.
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'fake_supplier','critical','lead', l.id::text, 'licence_expired_but_approved',
         'Approved supplier holds an expired trade licence.',
         jsonb_build_object('company', l.company_name, 'expiry', l.license_expiry)
  from leads l
  where l.approval_status = 'approved' and l.license_expiry is not null and l.license_expiry < current_date
  on conflict do nothing;

  -- 3. Two different suppliers claiming the same trade licence number.
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'fake_supplier','critical','trade_license', t.lic, 'duplicate_trade_licence',
         'The same trade licence number is claimed by more than one supplier record.',
         jsonb_build_object('licence', t.lic, 'count', t.n)
  from (
    select trim(trade_license_no) as lic, count(*) as n
    from leads where coalesce(trim(trade_license_no),'') <> ''
    group by 1 having count(*) > 1
  ) t
  on conflict do nothing;

  -- 4. Supplier name impersonating QuotesDone.
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'brand_misuse','high','lead', l.id::text, 'name_impersonates_platform',
         'Supplier trading name contains the platform brand.',
         jsonb_build_object('company', l.company_name)
  from leads l
  where l.company_name ~* '(quotes ?done|quotesdone)'
  on conflict do nothing;

  -- 5. Scam RFQ: request for money, gift cards or advance payment inside a buyer brief.
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'scam_rfq','high','inquiry', i.id::text, 'advance_payment_solicitation',
         'Buyer brief solicits an advance payment, gift card or wire transfer.',
         jsonb_build_object('excerpt', left(coalesce(i.raw_input,''), 240))
  from inquiries i
  where coalesce(i.raw_input,'') ~* '(gift ?card|western union|wire transfer|advance fee|upfront payment to release|crypto payment)'
  on conflict do nothing;

  -- 6. Scam RFQ: attempt to move the conversation off-platform before reveal.
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'scam_rfq','medium','inquiry', i.id::text, 'off_platform_contact',
         'Buyer brief pushes contact off-platform before a paid reveal.',
         jsonb_build_object('excerpt', left(coalesce(i.raw_input,''), 240))
  from inquiries i
  where coalesce(i.raw_input,'') ~* '(whatsapp me on|call me directly on|contact me at .*@|my number is [+0-9])'
  on conflict do nothing;

  -- 7. Fake review: a supplier with a high rating and an implausible review count for its footprint.
  insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
  select 'fake_review','medium','lead', l.id::text, 'implausible_review_profile',
         'Perfect rating with a high review count and no verifiable web presence.',
         jsonb_build_object('company', l.company_name, 'rating', l.rating, 'reviews', l.reviews)
  from leads l
  where l.rating is not null and l.rating >= 4.9 and coalesce(l.reviews,0) >= 100
    and coalesce(nullif(trim(l.website),''), null) is null
  on conflict do nothing;

  return query
    select b.rule_key, count(*)::integer
    from brand_signal b
    where b.detected_at > now() - interval '5 minutes'
    group by b.rule_key;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_budget_available(p_dept text)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select greatest(
    coalesce(b.monthly_aed, 0)
    - coalesce((select sum(l.cost_aed) from ai_cost_log l
                 where l.dept_key = any(public.fn_dept_scope(b.dept_key))
                   and l.occurred_at >= date_trunc('month', now())), 0),
    0)
  from department_budget b
  where b.dept_key = public.fn_dept_canonical(p_dept);
$function$


CREATE OR REPLACE FUNCTION public.fn_budget_create(p_name text, p_year integer, p_by text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare b bigint;
begin
  insert into public.budgets(name,fiscal_year,created_by) values (p_name,p_year,p_by) returning id into b;
  return b;
end $function$


CREATE OR REPLACE FUNCTION public.fn_budget_rollup()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_period text := to_char(current_date,'YYYY-MM'); n int := 0; v_degraded int := 0; v_halted int := 0; r record;
begin
  -- Every department is rolled, including the ones that spent nothing. The previous inner join
  -- skipped zero-spend departments entirely, leaving last month's spent_aed and period_label in
  -- place indefinitely. Only rows whose value actually changes are written, so updated_at still
  -- means "this budget moved".
  update department_budget b
     set spent_aed = v.total, period_label = v_period, updated_at = now()
  from (
    select b2.dept_key,
           coalesce((select sum(l.cost_aed) from ai_cost_log l
                      where l.dept_key = b2.dept_key
                        and l.occurred_at >= date_trunc('month', now())), 0) as total
      from department_budget b2
  ) v
  where b.dept_key = v.dept_key
    and (b.spent_aed is distinct from v.total or b.period_label is distinct from v_period);
  get diagnostics n = row_count;

  for r in
    select dept_key, monthly_aed, spent_aed, degrade_at_pct, halt_at_pct,
           round(100.0*spent_aed/nullif(monthly_aed,0),1) as pct
    from department_budget
    where monthly_aed > 0 and spent_aed is not null
  loop
    if r.pct >= r.halt_at_pct then
      v_halted := v_halted + 1;
      insert into founder_alerts (level, event, detail, channel)
      select 'high','ai_budget_halt', r.dept_key||' has spent '||r.pct||'% of its monthly AI budget ('||r.spent_aed||' of '||r.monthly_aed||' AED). Halt threshold '||r.halt_at_pct||'% reached.','email'
      where not exists (select 1 from founder_alerts where event='ai_budget_halt' and detail like r.dept_key||'%' and created_at > now()-interval '24 hours');
      -- The same fact, on the bus, so the Finance OS hears it as well as the founder.
      if not exists (select 1 from company_event where event_type='budget.exceeded'
                       and entity_id = r.dept_key and occurred_at > now()-interval '24 hours') then
        perform public.fn_emit('budget.exceeded','department', r.dept_key, 'cfo',
                  jsonb_build_object('pct', r.pct, 'spent_aed', r.spent_aed,
                                     'monthly_aed', r.monthly_aed, 'halt_at_pct', r.halt_at_pct));
      end if;
    elsif r.pct >= r.degrade_at_pct then
      v_degraded := v_degraded + 1;
      insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
      select r.dept_key, 'AI budget degrade threshold: '||r.dept_key,
             r.dept_key||' has spent '||r.pct||'% of its monthly AI budget. Move non-critical work to the cheaper model tier and enable response caching before the halt threshold at '||r.halt_at_pct||'%.',
             'proposed','gated', false, 'recommend'
      where not exists (select 1 from org_tasks where title='AI budget degrade threshold: '||r.dept_key and status<>'done');
    end if;
  end loop;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('budget_rollup', now(), now(), 'ok',
          jsonb_build_object('depts_changed',n,'degraded',v_degraded,'halted',v_halted),
          'AI spend rolled into department budgets: '||n||' department(s) changed, '||v_degraded||' past degrade threshold, '||v_halted||' past halt.');
  return jsonb_build_object('updated',n,'degraded',v_degraded,'halted',v_halted);
end $function$


CREATE OR REPLACE FUNCTION public.fn_budget_set(p_budget bigint, p_account text, p_month date, p_amount numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  insert into public.budget_lines(budget_id,account_code,period_month,amount)
    values (p_budget, p_account, date_trunc('month',p_month)::date, round(p_amount,2))
  on conflict (budget_id,account_code,period_month)
    do update set amount = excluded.amount;
end $function$


CREATE OR REPLACE FUNCTION public.fn_budget_set_annual(p_budget bigint, p_account text, p_amount numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare yr int; base numeric(18,2); rem numeric(18,2); mth date; i int; amt numeric(18,2);
begin
  select fiscal_year into yr from public.budgets where id=p_budget;
  if yr is null then raise exception 'budget % not found', p_budget; end if;
  base := round(round(p_amount,2)/12, 2);
  rem  := round(p_amount,2) - base*12;                 -- rounding remainder to last month
  for i in 0..11 loop
    mth := make_date(yr,1,1) + (i||' months')::interval;
    amt := base + case when i=11 then rem else 0 end;
    perform public.fn_budget_set(p_budget, p_account, mth, amt);
  end loop;
end $function$


CREATE OR REPLACE FUNCTION public.fn_bump_exam_question(p_id bigint)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  update knowledge_exam_questions set times_asked = coalesce(times_asked,0)+1, last_asked = now() where id = p_id;
$function$


CREATE OR REPLACE FUNCTION public.fn_cancel_inquiry(p_inquiry uuid, p_customer uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v inquiries%rowtype; v_paid boolean; v_cnt int; v_warned boolean:=false; v_email text;
begin
  select * into v from inquiries where id=p_inquiry;
  if not found then return jsonb_build_object('error','inquiry_not_found'); end if;
  if p_customer is not null and v.customer_id is distinct from p_customer then
    return jsonb_build_object('error','not_your_inquiry'); end if;
  if v.status='cancelled' or v.pipeline_stage='cancelled' then
    return jsonb_build_object('ok',true,'already_cancelled',true); end if;
  select exists(select 1 from transactions where inquiry_id=p_inquiry) into v_paid;
  if v_paid or v.status in ('revealed','completed') or v.pipeline_stage in ('revealed','won') then
    return jsonb_build_object('error','already_revealed',
      'message','This request already has an active revealed deal and cannot be cancelled. You can close it instead.'); end if;

  update inquiries set status='cancelled', pipeline_stage='cancelled', outcome='cancelled',
      lost_reason=coalesce(p_reason,'customer_cancelled'), completed_at=now(), stage_changed_at=now()
    where id=p_inquiry;
  insert into inquiry_cancellations(inquiry_id,customer_id,reason) values (p_inquiry, v.customer_id, p_reason);

  select count(*) into v_cnt from inquiry_cancellations where customer_id=v.customer_id and created_at > now()-interval '30 days';
  if v.customer_id is not null and v_cnt >= 3 then
    select email into v_email from customers where id=v.customer_id;
    if v_email is not null and position('@' in v_email)>1
       and not exists (select 1 from notifications where type='cancel_warning' and to_email=v_email and created_at > now()-interval '30 days') then
      insert into notifications(type,to_email,to_role,inquiry_id,subject,body,channel,status)
      values('cancel_warning', v_email, 'customer', p_inquiry,
        'A quick note about cancelled requests',
        'We noticed a few of your recent requests were cancelled. That is completely fine — but every request you post is prepared and quoted by suppliers who set aside real time for it. To keep things fair for them, we kindly ask that you post requests you intend to proceed with. If you would like help scoping a job before posting, our team is glad to assist.',
        'email','queued');
      v_warned:=true;
    end if;
  end if;
  return jsonb_build_object('ok',true,'cancelled',true,'cancellations_30d',v_cnt,'warned',v_warned);
end $function$


CREATE OR REPLACE FUNCTION public.fn_capability_enrich_sweep(p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record;
  v_ref text; v_secret text;
  v_sent int := 0; v_eligible int := 0;
begin
  select value into v_secret from app_secrets where key = 'cred_db_internal';
  if v_secret is null then
    return jsonb_build_object('error', 'cred_db_internal missing', 'ran_at', now());
  end if;

  select value into v_ref from app_secrets where key = 'project_ref';
  if v_ref is null then
    select substring(command from 'https://([a-z]+)[.]supabase[.]co') into v_ref
      from cron.job where command like '%supabase.co/functions/v1/%' limit 1;
  end if;
  if v_ref is null then
    return jsonb_build_object('error', 'cannot determine project ref', 'ran_at', now());
  end if;

  select count(*) into v_eligible
    from public.leads l
   where l.approval_status = 'approved'
     and l.capability_enriched_at is null
     and l.claimed_by is not null
     and l.claimed_by not ilike '%@example.%'
     and coalesce(l.company_name,'') not ilike 'ZZ DEMO%'
     and coalesce((l.enrich_retry->>'count')::int, 0) < 8
     and coalesce((l.enrich_retry->>'last')::timestamptz, 'epoch'::timestamptz) < now() - interval '12 hours';

  for r in
    select l.id
      from public.leads l
     where l.approval_status = 'approved'
       and l.capability_enriched_at is null
       and l.claimed_by is not null
       and l.claimed_by not ilike '%@example.%'
       and coalesce(l.company_name,'') not ilike 'ZZ DEMO%'
       and coalesce((l.enrich_retry->>'count')::int, 0) < 8
       and coalesce((l.enrich_retry->>'last')::timestamptz, 'epoch'::timestamptz) < now() - interval '12 hours'
     order by l.id
     limit greatest(p_limit, 0)
  loop
    -- Stamped BEFORE the call so a request that never returns still consumes its attempt and the
    -- backoff holds. capability_enriched_at is left for enrich_capability to set: this routine
    -- records that it ASKED, never that the work was done.
    update public.leads
       set enrich_retry = coalesce(enrich_retry, '{}'::jsonb)
                        || jsonb_build_object(
                             'last', now(),
                             'count', coalesce((enrich_retry->>'count')::int, 0) + 1)
     where id = r.id;

    perform net.http_post(
      url     := 'https://' || v_ref || '.supabase.co/functions/v1/enrich_capability',
      headers := jsonb_build_object('Content-Type', 'application/json'),
      body    := jsonb_build_object('__secret', v_secret, 'lead_id', r.id));

    v_sent := v_sent + 1;
  end loop;

  return jsonb_build_object(
    'ran_at', now(), 'eligible', v_eligible, 'retried', v_sent, 'limit', p_limit,
    'note', case when v_eligible = 0
                 then 'Every claimed, approved supplier has a capability record. Nothing to retry.'
                 else v_sent || ' approved supplier(s) had no capability record and were re-sent to '
                      || 'enrich_capability; without one they are invisible to the matcher and to every RFQ.'
            end);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_capability_verify()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_real int := 0; v_present int := 0; v_absent int := 0; v_failing int := 0;
begin
  update public.critical_capability c
     set last_verdict = case
           when t.last_run is not null then lower(t.state)
           when to_regproc('public.'||c.test_ref) is not null
             or to_regclass('public.'||c.test_ref) is not null
             or exists (select 1 from pg_trigger g where g.tgname = c.test_ref)
             or exists (select 1 from public.scenario_library s where s.scenario_key = c.test_ref)
             then 'mechanism_present'
           else 'mechanism_absent' end,
         last_checked = coalesce(t.last_run,
           (select s.last_run from public.scenario_library s where s.scenario_key = c.test_ref),
           now())
    from public.v_critical_capability_tests t
   where t.capability_key = c.capability_key;

  select count(*) filter (where last_verdict in ('passing','failing')),
         count(*) filter (where last_verdict = 'mechanism_present'),
         count(*) filter (where last_verdict = 'mechanism_absent'),
         count(*) filter (where last_verdict = 'failing')
    into v_real, v_present, v_absent, v_failing
    from public.critical_capability;

  -- A capability that has FAILED is not a log line. It goes to the founder's alert stream with its
  -- own key, once per verdict, so a capability that fails for a week does not raise seven alerts.
  insert into public.founder_alerts (level, event, detail, channel)
  select 'critical', 'Critical capability failing',
         c.capability_key||' — '||c.capability||' (owner: '||coalesce(c.owner_dept,'unassigned')
         ||', test '||coalesce(c.test_ref,'?')||')',
         'os'
    from public.critical_capability c
   where c.last_verdict = 'failing'
     and not exists (select 1 from public.founder_alerts a
                      where a.event = 'Critical capability failing'
                        and a.detail like c.capability_key||' —%'
                        and a.created_at > now() - interval '20 hours');

  insert into public.agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('capability_verify', now(), now(), 'ok',
    jsonb_build_object('exercised', v_real, 'mechanism_present', v_present,
                       'mechanism_absent', v_absent, 'failing', v_failing),
    v_real||' capabilit(ies) carry a real test verdict of which '||v_failing||' are failing; '
    ||v_present||' verified present but never behaviourally exercised; '||v_absent||' missing their mechanism entirely.');

  return jsonb_build_object('exercised', v_real, 'mechanism_present', v_present,
                            'mechanism_absent', v_absent, 'failing', v_failing);
end $function$


CREATE OR REPLACE FUNCTION public.fn_cascade_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_decompose jsonb;
  v_dept_ok int; v_dept_bad int;
  v_kpi_ok int;  v_kpi_bad int;
begin
  v_decompose := public.fn_goal_decompose();
  select measured, failed into v_dept_ok, v_dept_bad from public.fn_dept_objective_measure();
  select measured, failed into v_kpi_ok,  v_kpi_bad  from public.fn_employee_kpi_measure();

  -- NO KPI->OBJECTIVE COLUMN IS WRITTEN HERE, AND THAT IS DELIBERATE.
  -- The first draft of this function bound employee_kpi.serves_objective to the matching
  -- department_objective.id. Staging refused it:
  --   ERROR 23503: Key (serves_objective)=(139) is not present in table "os_objective"
  -- employee_kpi.serves_objective is a foreign key to os_objective, NOT to department_objective.
  -- The column name says "objective"; the constraint says which one, and the two tables are
  -- different layers with different vocabularies. Had the ids happened to overlap, that update
  -- would have joined every role KPI to an unrelated row and nothing would have failed.
  -- The KPI->objective link is therefore resolved at read time in fn_revenue_cascade, on
  -- (department, serves_goal), which is a fact rather than an id coincidence.
  return jsonb_build_object(
    'decompose', v_decompose,
    'department_objectives_measured', v_dept_ok,
    'department_objectives_measure_failed', v_dept_bad,
    'role_kpis_measured', v_kpi_ok,
    'role_kpis_measure_failed', v_kpi_bad,
    'role_kpis_pointing_at_an_os_objective',
      (select count(*) from public.employee_kpi where active and serves_objective is not null),
    'note', 'employee_kpi.serves_objective references os_objective, a second objective table that '
            ||'is measured but carries no company goal_key. It is reported, never written here.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_category_checklist(p_category text, p_label text DEFAULT NULL::text, p_text text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_decide   jsonb;
  v_num      integer;
  v_cat_key  text;
  v_route    record;
  v_curated  jsonb;
  v_bank     jsonb;
  v_policy   jsonb;
  v_resolved text;
begin
  -- 1. curated fields for the customer-facing slug, if the company has any
  select fields into v_curated from category_specs where category = p_category limit 1;

  -- 2a. a system category slug the company assigned resolves deterministically; only
  --     customer prose goes to the language resolver.
  select catalog_num into v_num from category_route_map where category = p_category;
  if v_num is not null then v_resolved := 'category_route_map'; end if;

  -- 2b. resolve to a catalogue route using the existing resolver, not a new matcher
  if v_num is null then
  v_decide := fn_kb_route_decide(coalesce(nullif(btrim(concat_ws(' ', p_label, p_category, p_text)), ''), p_category));
  v_num := nullif(v_decide->>'catalog_num', '')::integer;
  v_resolved := 'route_decider';
  end if;
  if v_num is null then
    -- the decider asked for clarification; take its top candidate only when it is unambiguous
    if coalesce(jsonb_array_length(v_decide->'candidates'), 0) = 1 then
      v_num := (v_decide->'candidates'->0->>'catalog_num')::integer;
      v_resolved := 'single_candidate';
    end if;
  end if;
  if v_num is null then
    select catalog_num into v_num from kb_operational_route
     where expected_catalog_slug = p_category or route_key = p_category limit 1;
    if v_num is not null then v_resolved := 'exact_slug'; end if;
  end if;

  if v_num is null then
    return jsonb_build_object(
      'category', p_category, 'route_resolved', false,
      'resolution', 'unresolved',
      'clarification', v_decide->>'clarification',
      'candidates', coalesce(v_decide->'candidates', '[]'::jsonb),
      'curated_fields', coalesce(v_curated, '[]'::jsonb),
      'packaged_questions', '[]'::jsonb, 'mandatory_fields', '[]'::jsonb,
      'never_infer', '[]'::jsonb, 'knowledge_ids', '[]'::jsonb);
  end if;

  select * into v_route from kb_operational_route where catalog_num = v_num;
  select category_key into v_cat_key from org_category_identity where catalog_num = v_num;

  -- 3. the packaged question bank for that route (field / question / mandatory / why)
  select structured_data->'questions' into v_bank
    from ops_knowledge
   where category_key = v_cat_key and runtime_eligible and supersession_state = 'current'
     and source_path like '%02_FIELD_AND_QUESTION_BANK_V2.yaml'
   limit 1;

  -- 4. the V3 minimum-sufficient policy: what must be answered, and what may never be guessed
  select structured_data into v_policy
    from ops_knowledge
   where category_key = v_cat_key and runtime_eligible and supersession_state = 'current'
     and source_path like '%02_MINIMUM_SUFFICIENT_QUESTION_POLICY_V3.yaml'
   limit 1;

  return jsonb_build_object(
    'category', p_category,
    'route_resolved', true,
    'resolution', v_resolved,
    'catalog_num', v_num,
    'route_key', v_route.route_key,
    'route_name', v_route.catalog_name,
    'category_key', v_cat_key,
    'coverage_status', v_route.coverage_status,
    'regulatory_coverage_status', v_route.regulatory_coverage_status,
    'curated_fields', coalesce(v_curated, '[]'::jsonb),
    'packaged_questions', coalesce(v_bank, '[]'::jsonb),
    'mandatory_fields', coalesce(v_policy->'mandatory_fields', '[]'::jsonb),
    'route_specific_fields', coalesce(v_policy->'route_specific_fields', '[]'::jsonb),
    'ask_order', coalesce(v_policy->'ask_order', '[]'::jsonb),
    'stop_rule', v_policy->>'stop_rule',
    'never_infer', coalesce(v_policy->'never_infer', '[]'::jsonb),
    'knowledge_ids', coalesce((
      select jsonb_agg(record_id) from ops_knowledge
       where category_key = v_cat_key and runtime_eligible and supersession_state = 'current'), '[]'::jsonb));
end $function$


CREATE OR REPLACE FUNCTION public.fn_category_expert_ref(p_category text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_slug text; v_txt text;
begin
  v_slug := case
    when p_category ~* 'cctv|security|surveillance' then 'cctv-security'
    when p_category ~* 'hvac|air.?con|ac-' then 'ac-maintenance'
    when p_category ~* 'duct' then 'ac-duct-cleaning'
    when p_category ~* 'glass|glaz|alumin' then 'aluminium-glass'
    when p_category = 'carpentry' then 'carpentry-joinery'
    when p_category ~* 'joinery|kitchen' then 'joinery-kitchens'
    when p_category ~* 'tiling|tile|marble|granite' then 'tiling-marble'
    when p_category ~* 'gypsum|false.?ceiling|ceiling' then 'false-ceiling'
    when p_category ~* 'upholstery|blind|curtain' then 'curtains-blinds'
    when p_category ~* 'fit.?out' then 'commercial-retail-fitout'
    when p_category ~* 'combined.?mep|^mep$' then 'combined-mep'
    when p_category ~* 'steel|fabrication' then 'structural-steel-fabrication'
    when p_category ~* 'pest' then 'pest-control'
    when p_category ~* 'tent|shade' then 'tents-and-shade-structures'
    when p_category ~* 'general|other|handyman|facilit' then coalesce(
        (select 'general-services-other' where exists (select 1 from agent_knowledge where agent_key='cat:general-services-other')), p_category)
    else p_category end;
  select string_agg('## '||topic||E'\n'||content, E'\n\n')
    into v_txt from agent_knowledge
    where agent_key = 'cat:'||v_slug
      and topic in ('Pricing benchmarks & red flags','Quote analysis & comparison',
                    'Standards, materials & specifications','Field expertise — UAE codes, standards & specs');
  return left(coalesce(v_txt,''), 4500);
end $function$


CREATE OR REPLACE FUNCTION public.fn_category_knowledge(p_category text)
 RETURNS TABLE(catalog_slug text, topic text, content text, priority integer, layer text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- THE KNOWLEDGE WAS COMPLETE AND UNREACHABLE.
  -- All 84 spec categories carry their 8 modules under agent_key 'cat:<catalogue-slug>', but the
  -- live intake assigns one of 56 LEGACY slugs whose overlap with the catalogue is exactly zero.
  -- lead_trade_map is the bridge; this is the first thing that walks it at read time.
  -- Accepts either vocabulary so callers do not need to know which one they hold.
  with resolved as (
    select coalesce(
      (select c.slug from public.catalog_supplier_categories c where c.slug = p_category),
      (select m.catalog_slug from public.lead_trade_map m
         join public.catalog_supplier_categories c2 on c2.slug = m.catalog_slug
        where m.trade_key = p_category)
    ) as slug
  )
  select r.slug, k.topic, k.content, k.priority, k.layer
    from resolved r
    join public.agent_knowledge k on k.agent_key = 'cat:' || r.slug
   where r.slug is not null
   order by k.priority desc nulls last, k.topic;
$function$


CREATE OR REPLACE FUNCTION public.fn_category_knowledge_promote()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_slug text; v_know text; v_name text; r jsonb;
begin
  if NEW.kind='category_knowledge' and NEW.status in ('approved','done')
     and coalesce(OLD.status,'') not in ('approved','done') then
    v_slug := NEW.detail->>'slug'; v_know := NEW.detail->>'knowledge'; v_name := NEW.detail->>'name';
    if v_slug is not null and v_know is not null then
      -- publish the quoting-knowledge blob live (full parity) if not already present
      if not exists (select 1 from agent_knowledge where agent_key='cat:'||v_slug) then
        insert into agent_knowledge(agent_key,topic,content,priority,created_at,updated_at)
        values ('cat:'||v_slug, coalesce(v_name,v_slug), v_know, 100, now(), now());
      else
        update agent_knowledge set content=v_know, updated_at=now() where agent_key='cat:'||v_slug;
      end if;
      -- apply the proposed regulation -> category mapping
      for r in select * from jsonb_array_elements(coalesce(NEW.detail->'reg_matches','[]'::jsonb)) loop
        update regulations
          set categories = array(select distinct e from unnest(coalesce(categories,'{}'::text[]) || array[v_slug]) e)
          where id::text = (r->>'id') and not (v_slug = any(coalesce(categories,'{}'::text[])));
      end loop;
    end if;
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_category_questions(p_category text, p_lang text DEFAULT 'en'::text, p_limit integer DEFAULT 22)
 RETURNS TABLE(field_key text, question text, answer_type text, mandatory boolean, ask_order integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'kb_stage'
AS $function$
  -- THE SPEC'S "INQUIRY QUALIFICATION LOGIC", REACHABLE FOR THE FIRST TIME.
  -- 16,588 questions (4,117 distinct texts, 7,079 mandatory, 14,051 bilingual) live in kb_stage
  -- keyed by FAMILY slug. The intake speaks a legacy slug. The chain is
  --   intake slug -> lead_trade_map -> catalogue slug -> catalog_category_domain -> family
  -- and this walks all of it, accepting either vocabulary at the front.
  --
  -- field_key is NULL on every row; the real supplier-facing key and the ask-order live inside
  -- `activation`. Sorting by that order is the point - it is what makes this an ordered interview
  -- rather than the flat, unordered list category_specs.fields produces.
  --
  -- Deduplicated on question text: a family spans up to 465 subcategories which repeat the generic
  -- spine (emirate, exact need, scope, quantity, date), so without DISTINCT ON the first 20 rows
  -- would be the same question twenty times.
  with fam as (
    select d.domain_slug
      from public.catalog_category_domain d
     where d.catalog_slug = coalesce(
       (select c.slug from public.catalog_supplier_categories c where c.slug = p_category),
       (select m.catalog_slug from public.lead_trade_map m where m.trade_key = p_category))
  )
  select * from (
    select distinct on (q.question_en)
           coalesce(q.activation->>'supplier_facing_field', q.field_key) as field_key,
           case when p_lang = 'ar' and coalesce(q.question_ar,'') <> '' then q.question_ar else q.question_en end as question,
           q.answer_type,
           q.mandatory,
           coalesce((q.activation->>'order')::int, 999) as ask_order
      from kb_stage.questions q
      join fam on fam.domain_slug = q.category_slug
     where coalesce(q.question_en,'') <> ''
     order by q.question_en, q.mandatory desc
  ) x
  order by x.mandatory desc, x.ask_order, x.field_key
  limit greatest(p_limit, 1);
$function$


CREATE OR REPLACE FUNCTION public.fn_category_quote_ready(p_category text, p_spec jsonb, p_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_chk     jsonb;
  v_missing text[] := '{}';
  f         text;
begin
  v_chk := fn_category_checklist(p_category, p_label, null);
  if not (v_chk->>'route_resolved')::boolean then
    return jsonb_build_object('ready', false, 'reason', 'route_unresolved',
                              'clarification', v_chk->>'clarification',
                              'missing', '[]'::jsonb, 'checklist', v_chk);
  end if;
  for f in select jsonb_array_elements_text(v_chk->'mandatory_fields') loop
    if coalesce(p_spec, '{}'::jsonb) ->> f is null
       or btrim(coalesce(p_spec ->> f, '')) = '' then
      v_missing := v_missing || f;
    end if;
  end loop;
  return jsonb_build_object(
    'ready', coalesce(array_length(v_missing, 1), 0) = 0,
    'reason', case when coalesce(array_length(v_missing,1),0) = 0 then 'complete' else 'missing_mandatory_fields' end,
    'missing', to_jsonb(v_missing),
    'route_key', v_chk->>'route_key',
    'category_key', v_chk->>'category_key',
    'stop_rule', v_chk->>'stop_rule',
    'never_infer', v_chk->'never_infer',
    'knowledge_ids', v_chk->'knowledge_ids');
end $function$


CREATE OR REPLACE FUNCTION public.fn_category_readiness_recompute()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  update org_category_identity c
     set readiness = case
       when not exists (select 1 from ops_knowledge k where k.category_key = c.category_key
                          and k.runtime_eligible and k.supersession_state = 'current') then 'blocked'
       when (select (fn_category_checklist(r.expected_catalog_slug, r.catalog_name, null)->>'route_resolved')::boolean
               from kb_operational_route r where r.catalog_num = c.catalog_num) then 'decision_trace_connected'
       else 'knowledge_imported' end,
         updated_at = now();
  select jsonb_object_agg(readiness, n) into v
    from (select readiness, count(*) n from org_category_identity group by 1) s;
  return jsonb_build_object('counts', v);
end $function$


CREATE OR REPLACE FUNCTION public.fn_category_sales(p_min_age_hours integer DEFAULT 24)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  rec record; v_hot int := 0; v_gap int := 0; v_cats int := 0; v_slug text; v_label text;
begin
  ---------------------------------------------------------------- HOT LEADS
  -- Quotes are in, the customer has not revealed. Every one of these is uncollected revenue.
  for rec in
    select i.id, i.category, i.emirate, count(q.id) as n_quotes, min(q.created_at) as first_quote
      from inquiries i
      join quotes q on q.inquiry_id = i.id and q.status = 'submitted'
     where not exists (select 1 from transactions tr where tr.inquiry_id = i.id and tr.revealed_at is not null)
       and coalesce(i.status,'') <> 'split'
     group by i.id, i.category, i.emirate
    having min(q.created_at) < now() - make_interval(hours => p_min_age_hours)
  loop
    v_slug := 'cat:' || lower(coalesce(nullif(trim(rec.category),''),'uncategorised'));
    v_label := coalesce(nullif(trim(rec.category),''),'Uncategorised');
    -- one open hot_lead per inquiry
    if not exists (select 1 from agent_actions
                    where kind = 'hot_lead' and target_id = rec.id::text
                      and status in ('needs_review','pending','open','proposed')) then
      insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id,assumptions,expected_impact,cost)
      values (v_slug,'hot_lead','needs_review','medium',
              'Hot lead — ' || v_label || ' / ' || coalesce(nullif(trim(rec.emirate),''),'UAE') ||
                ': ' || rec.n_quotes || ' quote(s), not revealed',
              'nudge the customer to reveal',
              jsonb_build_object('inquiry_id',rec.id,'category',rec.category,'emirate',rec.emirate,
                                 'quotes',rec.n_quotes,'waiting_since',rec.first_quote),
              'inquiries', rec.id::text,
              -- s36 (13 Aug 2026): what this nudge takes on trust.
              jsonb_build_array(
                'That the customer has SEEN the quotes. The reveal gate hides supplier identity, not the fact that offers arrived; whether they have opened the portal at all is not measured here.',
                'That ' || rec.n_quotes || ' quote(s) is enough to decide on. Quoting is blind, so a customer who is waiting may be waiting for one more comparable offer rather than hesitating over these.',
                'The age is measured from the FIRST quote (' || to_char(rec.first_quote at time zone 'UTC','YYYY-MM-DD HH24:MI') || 'Z), so an inquiry whose quotes arrived days apart looks older than the customer''s actual wait for a comparable set.'),
              'This is the one point in the funnel where money changes hands. A quoted inquiry that is never revealed is the supplier''s work and the platform''s fee both thrown away.',
              'No spend. One nudge to the customer. The reveal fee is theirs to pay and is not a discount to offer.');
      v_hot := v_hot + 1;
    end if;
  end loop;

  ---------------------------------------------------------------- SUPPLY GAPS
  -- Category+emirate combinations where finalized demand found nobody. Feeds supplier activation.
  for rec in
    select coalesce(nullif(trim(i.category),''),'uncategorised') as category,
           coalesce(nullif(trim(i.emirate),''),'UAE') as emirate,
           count(*) as n_inquiries
      from inquiries i
     where i.rfq_ready is true
       and coalesce(i.status,'') <> 'split'
       and not exists (select 1 from inquiry_matches m where m.inquiry_id = i.id)
       and i.created_at > now() - interval '30 days'
     group by 1,2
  loop
    v_slug := 'cat:' || lower(rec.category);
    if not exists (select 1 from agent_actions
                    where kind = 'supply_gap' and agent = v_slug
                      and detail->>'emirate' = rec.emirate
                      and status in ('needs_review','pending','open','proposed')) then
      insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id,assumptions,expected_impact,cost)
      values (v_slug,'supply_gap','needs_review','high',
              'Supply gap — ' || rec.category || ' / ' || rec.emirate || ': no suppliers matched',
              'source or activate suppliers in this category',
              jsonb_build_object('category',rec.category,'emirate',rec.emirate,'inquiries',rec.n_inquiries),
              'inquiries', null,
              -- s36 (13 Aug 2026): what this gap takes on trust.
              jsonb_build_array(
                'A gap means the matcher wrote no inquiry_matches row. That does NOT distinguish "no supplier exists in this category" from "suppliers exist but none has declared this capability" - the second is fixable today and the first is not.',
                'The window is 30 days, so a gap already closed by a supplier who joined yesterday keeps appearing until the inquiry ages out of it.',
                'Category and emirate are the customer''s intake as it was recorded. A mis-categorised inquiry manufactures a gap in a category with no real demand behind it.'),
              'An RFQ in a category with no supplier cannot be quoted at all, so the request is lost before price ever matters. Supply is the binding constraint on revenue.',
              'No spend to decide. Filling it costs invitation volume and sending reputation, which the invite ramp caps - or nothing at all, if a supplier already on file simply has not declared the capability.');
      v_gap := v_gap + 1;
    end if;
  end loop;

  select count(distinct coalesce(nullif(trim(category),''),'uncategorised')) into v_cats from inquiries;

  insert into agent_runs(agent,status,counts,note,started_at,finished_at)
  values ('category_sales','ok',
          jsonb_build_object('hot',v_hot,'gaps',v_gap,'categories',v_cats),
          'category sweep: ' || v_hot || ' new hot lead(s), ' || v_gap || ' new supply gap(s) across ' || v_cats || ' categories',
          now(), now());

  return json_build_object('hot',v_hot,'gaps',v_gap,'categories',v_cats);
end $function$


CREATE OR REPLACE FUNCTION public.fn_category_specialist_scorecard(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_since timestamptz := now() - make_interval(days => greatest(coalesce(p_days,30),1));
  v_routed int; v_routed_ok int; v_inq int; v_quotable int; v_completeness_rows int;
  v_disp int; v_responded int; v_quotes int; v_valid int;
  v_overlays int; v_with_knowledge int;
begin
  select count(*) into v_overlays from org_role where status='active' and runtime_mode='knowledge_overlay';
  select count(distinct k.category_key) into v_with_knowledge
    from ops_knowledge k where k.category_key is not null and k.runtime_eligible;

  select count(*), count(*) filter (where coalesce(category,'') <> ''),
         count(*) filter (where coalesce(rfq_ready,false)),
         count(*) filter (where completeness is not null)
    into v_routed, v_routed_ok, v_quotable, v_completeness_rows
    from inquiries where created_at >= v_since;
  v_inq := v_routed;

  -- Dispatch is inquiry_matches.sent_at: a match that was never sent is a coverage fact, not a
  -- specialist outcome, so it is excluded from the denominator rather than counted as unanswered.
  select count(*) into v_disp from inquiry_matches where sent_at >= v_since;
  select count(distinct m.id) into v_responded
    from inquiry_matches m
    join quotes q on q.inquiry_id = m.inquiry_id and q.supplier_id = m.supplier_id
   where m.sent_at >= v_since;

  select count(*) into v_quotes from quotes where created_at >= v_since;
  select count(*) into v_valid from quotes
   where created_at >= v_since and coalesce(status,'') not in ('draft','invalid','withdrawn');

  return jsonb_build_object(
    'window_days', p_days,
    'overlays_active', v_overlays,
    'categories_with_runtime_knowledge', v_with_knowledge,
    'routing_accuracy', case when v_routed = 0 then null
                             else round(100.0 * v_routed_ok / v_routed, 1) end,
    'routing_accuracy_basis', case when v_routed = 0
      then 'no inquiry created in the window: not measurable, and deliberately not reported as 100'
      else v_routed_ok||' of '||v_routed||' inquiries carry a resolved category' end,
    'inquiry_quoteability', case when v_inq = 0 then null
                                 else round(100.0 * v_quotable / v_inq, 1) end,
    'inquiry_quoteability_basis', case when v_inq = 0
      then 'no inquiry in the window' else v_quotable||' of '||v_inq||' marked rfq_ready' end,
    'mandatory_field_completeness', null,
    'mandatory_field_completeness_basis',
      'not measurable: inquiries.completeness is jsonb and holds '||v_completeness_rows
      ||' non-null value(s) in this window. The column exists and no path writes it, so any number '
      ||'reported here would describe the schema rather than the inquiries',
    'supplier_response_rate', case when v_disp = 0 then null
                                   else round(100.0 * v_responded / v_disp, 1) end,
    'supplier_response_rate_basis', case when v_disp = 0
      then 'nothing dispatched in the window; with one confirmed supplier company-wide this is '
           ||'expected and is a coverage fact, not a specialist failure'
      else v_responded||' of '||v_disp||' dispatches answered' end,
    'valid_quotations', case when v_quotes = 0 then null
                             else round(100.0 * v_valid / v_quotes, 1) end,
    'valid_quotations_basis', case when v_quotes = 0
      then 'no quotation in the window' else v_valid||' of '||v_quotes end,
    'measured_at', now());
end
$function$


CREATE OR REPLACE FUNCTION public.fn_ceo_questions()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare qs text[] := array[]::text[]; n int := 0; q text;
  v_rev numeric; v_sup int; v_inq int; v_worst text; v_cost numeric; v_prev numeric;
begin
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev from transactions where revealed_at > now()-interval '30 days';
  select count(*) into v_sup from leads where claimed and approval_status='approved';
  select count(*) into v_inq from inquiries where created_at > now()-interval '30 days';
  select dept_key into v_worst from org_tasks where title like 'KPI missed:%' and status<>'done'
    group by dept_key order by count(*) desc limit 1;
  select coalesce(sum(cost_aed),0) into v_cost from ai_cost_log where occurred_at > now()-interval '7 days';
  select coalesce(sum(cost_aed),0) into v_prev from ai_cost_log where occurred_at between now()-interval '14 days' and now()-interval '7 days';

  if v_rev = 0 then
    qs := array_append(qs, 'Why are we not growing? Revenue is zero over 30 days with '||v_sup||' onboarded suppliers and '||v_inq||' inquiries. What is the single binding constraint, and what would remove it?');
  end if;
  if v_sup = 0 then
    qs := array_append(qs, 'We have 86 fully briefed category experts and no onboarded suppliers. Are we building capability ahead of demand, and is that still the right sequence?');
  end if;
  if v_worst is not null then
    qs := array_append(qs, 'Why is '||v_worst||' missing more targets than any other department this week? Is it capability, capacity, or a target that was never realistic?');
  end if;
  if v_prev > 0 and v_cost > v_prev * 1.25 then
    qs := array_append(qs, 'AI cost rose from '||round(v_prev,2)||' to '||round(v_cost,2)||' AED week on week. What drove it and did it buy anything?');
  end if;
  qs := array_append(qs, 'Which workflow wastes the most employee time, and what would automating it be worth?');
  qs := array_append(qs, 'Which department produced the highest return on its AI spend this month, and what are the others not copying?');
  qs := array_append(qs, 'What are we doing today only because we have always done it?');

  foreach q in array qs loop
    insert into org_tasks (dept_key,title,detail,status,tier,needs_founder,action_class)
    select 'exec','CEO question: '||left(q,80),
           q||E'\n\nAnswer with evidence from company data, not opinion. If the answer implies a change, open it as an initiative with a named metric and a baseline so it can be graded.',
           'proposed','advisory',false,'recommend'
    where not exists (select 1 from org_tasks where title='CEO question: '||left(q,80) and status<>'done');
    if found then n := n + 1; end if;
  end loop;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('ceo_questions',now(),now(),'ok',jsonb_build_object('asked',n),
          'CEO self-questioning: '||n||' strategic question(s) raised from live company data.');
  return jsonb_build_object('asked',n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_challenge(p_proposal text, p_proposed_by text DEFAULT 'founder'::text, p_challenger text DEFAULT 'brief'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  h record; v_id bigint; v_stance text := 'support'; v_conf numeric := 0.5;
  v_reason text := ''; v_alts jsonb := '[]'::jsonb; v_evidence jsonb := '[]'::jsonb;
  v_rank int; v_principle text; v_weight int := 0;
  v_prior record; v_supply int; v_rev numeric;
begin
  for h in select * from challenge_heuristic where active and p_proposal ~* pattern order by rank_touched limit 3
  loop
    -- a rank-1 conflict is severe on its own; lower ranks accumulate
    v_weight := v_weight + case h.rank_touched when 1 then 3 when 2 then 2 else 1 end;
    if v_rank is null or h.rank_touched < v_rank then v_rank := h.rank_touched; v_principle := h.principle; end if;
    v_reason := v_reason || case when v_reason='' then '' else ' ' end || h.concern;
    if h.alternative is not null then v_alts := v_alts || jsonb_build_array(h.alternative); end if;
  end loop;

  for v_prior in
    select headline, detail, outcome from institutional_memory
     where outcome in ('worse','improved')
       and p_proposal ~* coalesce(substring(headline from '\w+'),'zzzz')
     order by created_at desc limit 3
  loop
    v_evidence := v_evidence || jsonb_build_array(jsonb_build_object(
      'type','prior_outcome','verdict',v_prior.outcome,'lesson',left(v_prior.detail,240)));
    if v_prior.outcome='worse' then v_weight := v_weight + 3; end if;
  end loop;

  select count(*) into v_supply from leads where approval_status='approved';
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev
    from transactions where revealed_at > now()-interval '30 days';
  v_evidence := v_evidence || jsonb_build_array(jsonb_build_object(
    'type','current_state','onboarded_suppliers',v_supply,'revenue_30d_aed',v_rev,
    'note', case when v_supply=0
      then 'The marketplace has no onboarded supply, so any demand-side or pricing change cannot be validated against real behaviour yet.'
      else 'Supply exists; effects are measurable.' end));

  if v_supply=0 and p_proposal ~* '(fee|price|commission|campaign|customer|demand)' then
    v_weight := v_weight + 1;
    v_reason := v_reason || ' There is also no onboarded supply to measure the effect against, so the change would be unfalsifiable at the moment it is made.';
  end if;

  if v_weight >= 3 then v_stance := 'recommend_against'; v_conf := least(0.95, 0.60 + v_weight*0.05);
  elsif v_weight >= 1 then v_stance := 'concern'; v_conf := 0.65;
  else v_stance := 'support'; v_conf := 0.6;
       v_reason := 'No conflict with the priority hierarchy, no contrary prior outcome on record, and current state does not argue against it.';
  end if;

  -- A REFUSAL WITH NO REASON IS NOT A CHALLENGE. v_weight can cross the recommend_against
  -- threshold from institutional_memory alone, and only the heuristic loop above writes v_reason —
  -- so a proposal with two prior attempts that ended worse and no matching heuristic was recorded
  -- as recommend_against with an empty reasoning. Write the basis that actually drove the weight.
  if v_reason = '' and v_stance <> 'support' then
    v_reason := 'No principle in the priority hierarchy is touched by this, but '
      ||(select count(*) from jsonb_array_elements(v_evidence) e
          where e->>'type'='prior_outcome' and e->>'verdict'='worse')
      ||' prior attempt(s) on record ended worse: '
      ||coalesce((select string_agg(left(e->>'lesson',200), ' | ')
                    from jsonb_array_elements(v_evidence) e
                   where e->>'type'='prior_outcome' and e->>'verdict'='worse'),
                 'the outcome was recorded without a lesson')||'.';
  end if;

  if v_alts='[]'::jsonb and v_stance<>'support' then
    v_alts := jsonb_build_array('Run it as a bounded test with a named metric and a captured baseline, so it can be graded and reversed.');
  end if;

  insert into challenge_record (proposal,proposed_by,challenged_by,stance,confidence,reasoning,
                                violates_rank,violates_principle,evidence,alternatives)
  values (p_proposal,p_proposed_by,p_challenger,v_stance,v_conf,v_reason,v_rank,v_principle,v_evidence,v_alts)
  returning id into v_id;

  return jsonb_build_object('id',v_id,'stance',v_stance,'confidence',v_conf,
    'conflicts_with', case when v_principle is null then null else 'Rank '||v_rank||' — '||v_principle end,
    'reasoning',v_reason,'evidence',v_evidence,'alternatives',v_alts);
end $function$


CREATE OR REPLACE FUNCTION public.fn_check_licence_activity(p_subject_id text, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_lead leads%rowtype; v_cat text; v_rx text; v_note text;
begin
  begin
    select * into v_lead from leads where id = p_subject_id::bigint;
  exception when others then
    return jsonb_build_object('passed', false, 'detail', 'subject_id "' || p_subject_id || '" is not a lead id, so the licence activity cannot be checked');
  end;
  if v_lead.id is null then
    return jsonb_build_object('passed', false, 'detail', 'no lead ' || p_subject_id);
  end if;

  v_cat := (select unnest from unnest(v_lead.invite_trades) limit 1);
  if v_cat is null then
    return jsonb_build_object('passed', false, 'detail', 'supplier has declared no category, so no licence activity can be matched against it');
  end if;

  select activity_regex, note into v_rx, v_note from category_licence_activity where catalog_slug = v_cat;
  if v_rx is null then
    return jsonb_build_object('passed', false,
      'detail', 'no licence-activity rule recorded for category "' || v_cat || '" - cannot verify cover, so this application must be reviewed by a person');
  end if;

  if coalesce(trim(v_lead.license_activity), '') = '' then
    return jsonb_build_object('passed', false,
      'detail', 'trade licence activity was never captured for this supplier - request the licence and record its activity before approving');
  end if;

  if v_lead.license_activity ~ v_rx then
    return jsonb_build_object('passed', true,
      'detail', 'licence activity "' || v_lead.license_activity || '" covers ' || v_cat || coalesce('. ' || v_note, ''));
  end if;

  return jsonb_build_object('passed', false,
    'detail', 'MISMATCH: licence activity "' || v_lead.license_activity || '" does not cover the category applied for ("' || v_cat || '"). Request a licence whose activity includes that trade, or an amendment adding it.');
end; $function$


CREATE OR REPLACE FUNCTION public.fn_check_licence_expiry(p_subject_id text, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_exp date; v_no text;
begin
  begin
    select license_expiry, trade_license_no into v_exp, v_no from leads where id = p_subject_id::bigint;
  exception when others then
    return jsonb_build_object('passed', false, 'detail', 'subject_id is not a lead id');
  end;
  if coalesce(trim(v_no),'') = '' then
    return jsonb_build_object('passed', false, 'detail', 'no trade licence number recorded');
  end if;
  if v_exp is null then
    return jsonb_build_object('passed', false, 'detail', 'licence expiry date not recorded');
  end if;
  if v_exp < current_date then
    return jsonb_build_object('passed', false, 'detail', 'trade licence expired on ' || v_exp);
  end if;
  return jsonb_build_object('passed', true, 'detail', 'licence ' || v_no || ' valid to ' || v_exp);
end; $function$


CREATE OR REPLACE FUNCTION public.fn_check_spend(p_dept text, p_amount numeric, p_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_avail numeric; v_month numeric; v_limit numeric; v_route text; v_afford boolean;
  v_tier text; v_gated boolean := false;
begin
  p_agent := coalesce(public.fn_org_agent_resolve(p_agent), p_agent);
  select coalesce(monthly_aed,0), fn_budget_available(p_dept) into v_month, v_avail
  from department_budget where dept_key = p_dept;

  if v_month is null then
    return jsonb_build_object('ok', false, 'reason',
      'no budget is recorded for department "' || p_dept || '", so no spend can be authorised against it',
      'route_to','finance');
  end if;

  v_afford := coalesce(p_amount,0) <= v_avail;

  select max(threshold_aed) into v_limit
  from employee_authority where agent_key = p_agent;

  -- REPUTATION REACHES THE MOMENT THE MONEY WOULD MOVE.
  -- fn_reputation_recompute already demotes a probation-tier employee's max_tier from 'autonomous'
  -- to 'gated'; until now nothing consulted that at the point of spend, so a demoted employee kept
  -- their nominal ceiling. On probation the personal limit does not apply and the spend goes to a
  -- person — the same decision, applied where it bites.
  select r.tier into v_tier from agent_reputation r where r.agent_key = p_agent;
  if v_tier = 'probation' then v_gated := true; v_limit := 0; end if;

  v_route := case
    when coalesce(p_amount,0) >  10000 then 'founder'
    when coalesce(p_amount,0) >= 1000  then 'brief'
    -- a gated employee is never the approver of their own spend
    when v_gated then 'brief'
    else coalesce(p_agent,'department head') end;

  return jsonb_build_object(
    'ok', v_afford and (v_limit is null or coalesce(p_amount,0) <= v_limit),
    'affordable', v_afford,
    'requested_aed', coalesce(p_amount,0),
    'available_aed', v_avail,
    'monthly_aed', v_month,
    'agent_limit_aed', v_limit,
    'reputation_tier', coalesce(v_tier,'ungraded'),
    'route_to', v_route,
    'reason', case
      when not v_afford then format('Requested AED %s exceeds the AED %s remaining in the %s budget this period. Reduce the scope, defer to next period, or ask Finance to reallocate.', coalesce(p_amount,0), v_avail, p_dept)
      when v_gated then format('Affordable, but %s is on probation in the reputation system, so their personal spending limit does not apply. Route to %s.', coalesce(p_agent,'this employee'), v_route)
      when v_limit is not null and coalesce(p_amount,0) > v_limit then format('Affordable, but AED %s is above %s''s personal limit of AED %s. Route to %s.', coalesce(p_amount,0), p_agent, v_limit, v_route)
      else format('Within budget: AED %s of AED %s available. Approver: %s.', coalesce(p_amount,0), v_avail, v_route) end);
end; $function$


CREATE OR REPLACE FUNCTION public.fn_chief_of_staff()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare disp jsonb; exec jsonb; health jsonb; ops jsonb; rev jsonb;
  n_pending int; n_aging int; n_depts int; brief text; recs text; dept_txt text; esc_txt text; owner text;
  prioritized jsonb; run_id bigint;
begin
  disp := public.fn_autonomy_dispose();
  exec := public.fn_ws_exec();
  health := exec->'command'->'health'; ops := exec->'command'->'ops'; rev := ops->'revenue';

  select count(*) into n_pending from public.agent_actions where status in ('pending','held_for_review','proposed','open','needs_review');
  select count(*) into n_aging from public.agent_actions
    where status in ('pending','held_for_review','proposed','open','needs_review') and created_at < now()-interval '3 days';
  select count(distinct agent) into n_depts from public.agent_runs where started_at > now()-interval '24 hours';

  select string_agg(line, E'\n' order by line) into dept_txt from (
    select '- '||agent||': '||count(*)||' runs'||
           case when count(*) filter (where status='error')>0 then ' ('||count(*) filter (where status='error')||' failed)' else '' end as line
    from public.agent_runs where started_at > now()-interval '24 hours' group by agent
  ) d;

  select string_agg('- ['||coalesce(risk,'?')||'] '||coalesce(title,kind)||' ('||agent||')', E'\n') into esc_txt from (
    select agent,risk,title,kind from public.agent_actions
     where status in ('pending','held_for_review','proposed','open','needs_review') order by created_at asc limit 10
  ) e;

  select coalesce(jsonb_agg(x order by cat asc),'[]'::jsonb) into prioritized from (
    select jsonb_build_object('id',id,'agent',agent,'risk',risk,'title',title,
             'age_days',round(extract(epoch from (now()-created_at))/86400)) x, created_at cat
    from public.agent_actions where status in ('pending','held_for_review','proposed','open','needs_review')
    order by created_at asc limit 15
  ) s;

  recs := '';
  if n_pending>0 then recs := recs||'1) '||n_pending||' item(s) in your queue (payments, deletions, flagged suppliers, marketing to post, BD to enable, to-dos).'||E'\n'; end if;
  if n_aging>0 then recs := recs||'2) '||n_aging||' waited >3 days — action or dismiss.'||E'\n'; end if;
  if (health->>'band') is not null and lower(health->>'band')<>'good'
     then recs := recs||'3) Health "'||(health->>'band')||'" ('||coalesce(health->>'index','?')||'/100).'||E'\n'; end if;
  if recs='' then recs := 'Queue clear. Everything auto-handled where safe.'; end if;

  brief := 'Chief of Staff — daily briefing ('||to_char(now(),'DD Mon YYYY')||')'||E'\n\n'
    ||'HEADLINE: auto-approved '||coalesce(disp->>'approved_suppliers','0')||' clean supplier(s), auto-cleared '
      ||coalesce(disp->>'auto_cleared_logged','0')||' logged alert(s). '||n_pending||' item(s) in your queue. Health '
      ||coalesce(health->>'index','?')||'/100 ('||coalesce(health->>'band','?')||').'||E'\n\n'
    ||'YOUR QUEUE:'||E'\n'||coalesce(esc_txt,'- Empty.')||E'\n\n'
    ||'DEPARTMENTS (24h):'||E'\n'||coalesce(dept_txt,'- No agent runs in the last 24h.')||E'\n\n'
    ||'KPIs: revenue month '||coalesce(rev->>'month_aed','0')||' AED, cash received '||coalesce(rev->>'cash_received_aed','0')
      ||' AED, pending fees '||coalesce(rev->>'pending_fees_aed','0')||' AED, active RFQs '||coalesce(ops->'marketplace'->>'active_rfqs','0')||'.'||E'\n\n'
    ||'RECOMMENDATIONS:'||E'\n'||recs;

  insert into public.agent_runs(agent,started_at,finished_at,status,counts,note)
    values('chief_of_staff',now(),now(),'ok',
      jsonb_build_object('approved_suppliers',disp->>'approved_suppliers','auto_cleared',disp->>'auto_cleared_logged',
        'in_queue',n_pending,'aging',n_aging,'departments',n_depts),'coordination + autonomy v2')
    returning id into run_id;

  insert into public.agent_actions(agent,kind,status,risk,title,recommendation,target_table,target_id,detail)
    values('chief_of_staff','exec_briefing','auto_done','low',
      'Chief of Staff briefing — '||n_pending||' in queue, '||coalesce(disp->>'auto_cleared_logged','0')||' auto-cleared',
      'Informational.', null, null,
      jsonb_build_object('briefing',brief,'prioritized',prioritized,'autonomy',disp,'health',health->>'index','in_queue',n_pending));

  select split_part(coalesce(value,'management@quotesdone.com'),',',1) into owner from public.app_secrets where key='admin_emails';
  owner := coalesce(nullif(trim(owner),''),'management@quotesdone.com');
  insert into public.notifications(type,to_email,to_role,channel,subject,body)
    values('chief_of_staff', owner, 'admin','email',
      'Chief of Staff — '||n_pending||' in your queue, health '||coalesce(health->>'index','?')||'/100', brief);

  return jsonb_build_object('ok',true,'autonomy',disp,'in_queue',n_pending,'aging',n_aging,'departments',n_depts,'run_id',run_id);
end $function$


CREATE OR REPLACE FUNCTION public.fn_classify_llm_failure(p_err text, p_http_status integer DEFAULT NULL::integer, p_finish_reason text DEFAULT NULL::text, p_model text DEFAULT NULL::text, p_latency_ms integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  e text := coalesce(p_err, '');
  k text;
  truncated boolean;
begin
  -- ai_gateway slices lastErr to exactly 200 chars. At 200 the evidence stops before `choices`,
  -- so anything read past that point would be a guess. Say so rather than infer.
  truncated := length(e) >= 200;

  k := case
    -- BILLING FIRST (added 14 Aug 2026). Stable across every OpenRouter model, and not
    -- retryable: retrying an out-of-credit request cannot succeed and burns the wall budget.
    when p_http_status = 402
      or e ~* '(requires more credits|insufficient[_ ]credit|can only afford|quota exceeded|payment required)'
      then 'insufficient_credit'
    -- credentials first: deterministic, and must never be retried
    when p_http_status in (401, 403)
      or e ~* '(unauthor|forbidden|invalid api key|no auth credentials|api[_ ]?key missing)'
      then 'unauthorised'
    when p_http_status = 429
      or e ~* '(rate[ _-]?limit|too many requests|quota exceeded|insufficient (credits|quota)|capacity)'
      then 'rate_limited'
    -- our own stopwatch reads as a model failure unless it is named
    when e ~* '(signal has been aborted|aborterror|the operation was aborted|timed? ?out|etimedout|deadline|gateway_deadline)'
      then 'timeout'
    when e ~* '(not a valid model|model not found|no endpoints found|unknown model|no allowed providers)'
      then 'route_not_registered'
    when p_model is not null
      and not exists (select 1 from model_registry r where r.model_id = p_model and r.active)
      then 'route_not_registered'
    -- a REAL provider error object, or a 5xx with no payload
    when e ~ '"error"\s*:' or e ~* '^\s*\{"error"'
      or (p_http_status between 500 and 599 and e !~ '"object"\s*:\s*"chat\.completion"')
      then 'provider_error'
    -- the shape the certification actually hit
    when e ~ '"object"\s*:\s*"chat\.completion"' or e ~ '^\s*\{"id"\s*:\s*"gen-'
      then 'empty_completion'
    when lower(coalesce(p_finish_reason,'')) = 'length'
      or e ~* '(unexpected end of json|unparseable|invalid json|json parse|content_filter)'
      then 'malformed_output'
    when e ~* '(tool[_ ]call|tool result|tool failed|function call failed)'
      then 'tool_failure'
    when e ~* '(embedding|kb_match|retriev|context slice|no chunks)'
      then 'retrieval_failure'
    when e ~* '(pgrst|sqlstate|does not exist|deadlock detected|connection (reset|refused|closed)|relation .* does not exist)'
      then 'database_failure'
    when e ~* '(route_failed|no route|no model policy|budget|spend guard|ladder empty)'
      then 'orchestration_failure'
    when e ~* '(harness|fixture|test runner|seed(ing)? failed)'
      then 'test_runner_failure'
    else 'unclassified'
  end;

  return jsonb_build_object(
    'class_key', k,
    'retryable', (select retryable from llm_failure_class where class_key = k),
    'max_retries', (select max_retries from llm_failure_class where class_key = k),
    'retry_backoff_ms', (select retry_backoff_ms from llm_failure_class where class_key = k),
    'trips_breaker', (select trips_breaker from llm_failure_class where class_key = k),
    'opens_on_first', (select opens_on_first from llm_failure_class where class_key = k),
    -- honesty flag: the caller learns the evidence was cut off, so 'empty_completion' is never
    -- mistaken for a diagnosed root cause
    'evidence_truncated', truncated,
    'latency_ms', p_latency_ms
  );
end $function$


CREATE OR REPLACE FUNCTION public.fn_collections()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run bigint; v_reminded int:=0; r record;
begin
  insert into agent_runs(agent, started_at) values ('collections', now()) returning id into v_run;
  -- NO commission is charged on won jobs (founder policy: zero commission). This engine never creates dues.
  -- The only supplier charge is the non-response fine (= the refunded reveal fee), created by qd_on_refund_resolved,
  -- and enforced by a matching block until settled. Here we only send a gentle reminder; no extra fees are added.
  for r in select d.*, l.claimed_by, l.email as lead_email, l.company_name
           from supplier_dues d join leads l on l.id=d.supplier_id
           where d.status in ('due','pending','reminded')
             and (d.last_reminder_at is null or d.last_reminder_at < now()-interval '4 days')
             and d.reminders < 3
  loop
    update supplier_dues set status='reminded', reminders=reminders+1, last_reminder_at=now() where id=r.id;
    insert into notifications(type,to_email,to_role,channel,status,lead_id,subject,body)
      values ('nonresponse_reminder', coalesce(r.claimed_by,r.lead_email), 'supplier', 'portal', 'portal', r.supplier_id,
        'Reminder: outstanding non-response charge',
        'Reminder: a non-response charge of AED '||round(r.amount_due)||' is outstanding on your account. This equals the reveal fee that was refunded to a customer because a paid reveal was not responded to. Please settle it on the portal to lift the hold on new matches. QuotesDone charges no commission on won jobs.');
    v_reminded := v_reminded + 1;
  end loop;
  update agent_runs set finished_at=now(), status='ok', counts=jsonb_build_object('reminders',v_reminded,'commission_charged',0) where id=v_run;
end;$function$


CREATE OR REPLACE FUNCTION public.fn_company_brief(p_max_chars integer DEFAULT 1600)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s jsonb; out text; d jsonb;
begin
  s := fn_company_state();
  out := 'COMPANY SELF-KNOWLEDGE (authoritative org facts — you may answer any question about the company from this):'||E'\n'
       ||'Vision: '||(s->>'vision')||E'\n'
       ||'Totals: '||(s->'totals'->>'departments')||' departments, '||(s->'totals'->>'brain_agents')||' brain agents, '
       ||(s->'totals'->>'category_sales_agents')||' category sales agents, '||(s->'totals'->>'tools_wired')||' wired tools, '
       ||(s->'totals'->>'open_objectives')||' open objectives, '||(s->'totals'->>'open_tasks')||' open tasks.'||E'\n'
       ||'Departments (lead · brain agents · north star):'||E'\n';
  for d in select * from jsonb_array_elements(s->'departments') loop
    out := out || '- '||(d->>'name')||' ['||(d->>'dept')||']: lead '||coalesce(d->>'lead_agent','—')
                || ', '||(d->>'headcount')||' agent(s)';
    if jsonb_array_length(d->'brain_agents') > 0 then
      out := out || ' ('||replace(replace(replace((d->'brain_agents')::text,'"',''),'[',''),']','')||')';
    end if;
    out := out || ', north star: '||coalesce(d->>'north_star','—')||E'\n';
    exit when length(out) > p_max_chars;
  end loop;
  return left(out, greatest(p_max_chars, 400));
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_facts_sync()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c record; pct text; capnote text; txt text; regline text;
begin
  select * into c from pricing_config where id=1; if c is null then return; end if;

  pct := trim(to_char(coalesce(c.standard_reveal_rate,0)*100,'FM990.##'))||'%';
  capnote := case when coalesce(c.standard_reveal_cap,0) >= 1000000
                  then 'no cap'
                  else 'capped at '||coalesce(c.reveal_currency,'AED')||' '||trim(to_char(c.standard_reveal_cap,'FM999999990')) end;

  -- The registration sentence is DERIVED, including the date. A generator that silently omits the
  -- start date produces a row that reads as "charged today" to every agent that retrieves it.
  if c.supplier_charging_starts is null then
    regline := 'Supplier registration: the annual subscription START DATE IS NOT SET in pricing_config — '
            || 'do NOT state when the fee begins; say the founder must confirm it. ';
  else
    regline := 'Supplier registration is FREE for EVERY supplier until '
            || to_char(c.supplier_charging_starts - 1, 'FMDD FMMonth YYYY') || '. '
            || 'From ' || to_char(c.supplier_charging_starts, 'FMDD FMMonth YYYY') || ' a '
            || coalesce(c.supplier_reg_period,'yearly') || ' subscription of '
            || coalesce(c.supplier_reg_currency,'AED') || ' '
            || trim(to_char(c.supplier_reg_fee,'FM999,999,990.##')) || ' applies, and it is NOT charged '
            || 'before that date. The first ' || c.supplier_free_count || ' businesses to register are '
            || 'exempt PERMANENTLY and never pay it — that exemption does not expire. ';
  end if;

  txt := 'PRICING & FEES — LIVE, AUTO-SYNCED FROM pricing_config (authoritative; OVERRIDES any pricing figure stated elsewhere). '
    ||'Customer REVEAL FEE: '||pct||' of the accepted quotation value ('||capnote||'), paid by the customer to unlock their chosen supplier. '
    ||'Suppliers pay NO commission on won jobs. '
    ||regline
    ||'Non-response window: '||c.refund_window_working_days||' working days — if a revealed supplier does not respond in that window and cannot be reached, the customer reveal fee is refunded and the supplier is charged a non-response fee equal to that reveal fee and blocked from matching until paid. '
    ||'There is NO 2% fee and NO supplier commission — never quote those. (Auto-updated '||to_char(now(),'YYYY-MM-DD HH24:MI')||' UTC.)';

  update agent_knowledge set content=txt, priority=100, updated_at=now()
    where agent_key='_global' and topic='Pricing & fees (LIVE — auto-synced)';
  if not found then
    insert into agent_knowledge(agent_key,topic,content,priority,updated_at)
      values ('_global','Pricing & fees (LIVE — auto-synced)',txt,100,now());
  end if;
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_faq_sync()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_body text; n int;
begin
  select count(*) into n from company_faq where status='approved';
  select 'QUOTESDONE COMPANY FAQ — canonical answers every agent must use verbatim-in-spirit (founder-approved). '||
         'If asked anything here, answer consistently with this. Do not contradict it or invent beyond it.'||E'\n\n'||
         coalesce(string_agg(
           '## ['||section||'] '||question||E'\n'||coalesce(answer,'(no answer yet)')||
           case when audience<>'all' then E'\n(Audience: '||audience||')' else '' end,
           E'\n\n' order by section, sort, id), '')
    into v_body
  from company_faq where status='approved';

  if n=0 then
    delete from agent_knowledge where agent_key='_global' and topic='Company FAQ (canonical answers)';
    return jsonb_build_object('synced',0);
  end if;
  if exists(select 1 from agent_knowledge where agent_key='_global' and topic='Company FAQ (canonical answers)') then
    update agent_knowledge set content=v_body, updated_at=now()
      where agent_key='_global' and topic='Company FAQ (canonical answers)';
  else
    insert into agent_knowledge(agent_key,topic,content,priority,created_at,updated_at)
      values('_global','Company FAQ (canonical answers)', v_body, 96, now(), now());
  end if;
  return jsonb_build_object('synced', n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_indices()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  d_auto numeric; d_know numeric; d_dec numeric; d_fin numeric; d_cust numeric;
  d_supp numeric; d_sec numeric; d_res numeric; d_inno numeric; d_strat numeric; v_mat numeric;
  e_vel numeric; e_backlog numeric; e_collab numeric; e_knowcreate numeric; e_autorate numeric; v_energy numeric;
  m_quality numeric; m_speed numeric; m_completion numeric; m_fraud numeric; m_conf numeric; v_mh numeric;
  v_kpis int; v_gaps int;
begin
  select coalesce(100 - round(100.0*count(*) filter (where needs_founder)/nullif(count(*),0),1),100)
    into d_auto from org_tasks where status<>'done';
  select coalesce(round(100.0*count(*) filter (where validation_status not in ('unvalidated','unreviewed'))/nullif(count(*),0),1),0)
    into d_know from agent_knowledge;
  select coalesce(round(100.0*count(*) filter (where verdict='improved')
           /nullif(count(*) filter (where verdict in ('improved','no_change','worse')),0),1),50)
    into d_dec from outcome_record;
  select case when coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) > 0 then 60 else 10 end
    into d_fin from transactions where revealed_at > now()-interval '90 days';
  select case when count(*) > 0 then 50 else 10 end into d_cust from customers;
  select least(100, round(100.0*(select count(*) from v_supply_gap where approved>=10)/86.0,1)) into d_supp;
  select coalesce(round(100.0*count(*) filter (where ok)/nullif(count(*),0),1),50)
    into d_sec from health_checks where check_kind='http' and created_at > now()-interval '7 days';
  select round(100.0*count(*) filter (where last_tested is not null)/nullif(count(*),0),1)
    into d_res from continuity_plan;
  select least(100,(select count(*) from evolution_proposal)*5) into d_inno;
  select count(*) into v_kpis from employee_kpi where active;
  select count(*) into v_gaps from org_tasks where title like 'KPI missed:%' and status<>'done';
  d_strat := greatest(0, round(100.0 - 100.0*v_gaps/nullif(v_kpis,0), 1));

  v_mat := round((d_auto+d_know+d_dec+d_fin+d_cust+d_supp+d_sec+d_res+d_inno+d_strat)/10.0,1);
  insert into company_index (measured_on,index_name,dimensions,score,band)
  values (current_date,'company_maturity',
    jsonb_build_object('automation',d_auto,'knowledge_quality',d_know,'decision_accuracy',d_dec,
      'financial_health',d_fin,'customer_trust',d_cust,'supplier_ecosystem',d_supp,'security',d_sec,
      'operational_resilience',d_res,'innovation',d_inno,'strategic_execution',d_strat), v_mat,
    case when v_mat>=80 then 'mature' when v_mat>=60 then 'developing' when v_mat>=40 then 'early' else 'nascent' end)
  on conflict (measured_on,index_name) do update set dimensions=excluded.dimensions, score=excluded.score, band=excluded.band;

  select count(*) into e_vel from decision_log where created_at > now()-interval '7 days';
  select coalesce(round(100.0 - 100.0*count(*) filter (where created_at < now()-interval '14 days')/nullif(count(*),0),1),100)
    into e_backlog from org_tasks where status<>'done';
  select coalesce(round(100.0*count(*) filter (where decision='approve')/nullif(count(*),0),1),50)
    into e_collab from review_chain where created_at > now()-interval '30 days';
  select least(100,count(*)) into e_knowcreate from agent_knowledge where updated_at > now()-interval '7 days';
  e_autorate := d_auto;
  v_energy := round((least(100,e_vel)+e_backlog+e_collab+e_knowcreate+e_autorate)/5.0,1);
  insert into company_index (measured_on,index_name,dimensions,score,band)
  values (current_date,'organizational_energy',
    jsonb_build_object('decision_velocity_7d',e_vel,'backlog_freshness',e_backlog,
      'collaboration_efficiency',e_collab,'knowledge_creation_7d',e_knowcreate,'automation_rate',e_autorate),
    v_energy, case when v_energy>=75 then 'high' when v_energy>=50 then 'steady' else 'slowing' end)
  on conflict (measured_on,index_name) do update set dimensions=excluded.dimensions, score=excluded.score, band=excluded.band;

  select coalesce(round(avg(reliability),1),0) into m_quality from supplier_score where reliability is not null;
  select coalesce(round(100.0*count(*) filter (where sent_at is not null and sent_at-created_at < interval '24 hours')
           /nullif(count(*),0),1),0) into m_speed from notifications where created_at > now()-interval '30 days';
  select coalesce(round(100.0*count(*) filter (where exists(select 1 from quotes q where q.inquiry_id=i.id))
           /nullif(count(*),0),1),0) into m_completion from inquiries i where i.created_at > now()-interval '30 days';
  select coalesce(100 - least(100,count(*)*5),100) into m_fraud from fraud_flags;
  select coalesce(round(avg(confidence)*100,1),50) into m_conf from decision_log where confidence is not null;
  v_mh := round((m_quality+m_speed+coalesce(m_completion,0)+m_fraud+m_conf)/5.0,1);
  insert into company_index (measured_on,index_name,dimensions,score,band)
  values (current_date,'marketplace_health',
    jsonb_build_object('supplier_quality',m_quality,'quote_speed',m_speed,'rfq_completion',m_completion,
      'fraud_clean',m_fraud,'ai_confidence',m_conf), v_mh,
    case when v_mh>=75 then 'healthy' when v_mh>=50 then 'fragile' else 'unhealthy' end)
  on conflict (measured_on,index_name) do update set dimensions=excluded.dimensions, score=excluded.score, band=excluded.band;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('company_indices',now(),now(),'ok',
    jsonb_build_object('maturity',v_mat,'energy',v_energy,'marketplace_health',v_mh),
    'Company indices: maturity '||v_mat||', energy '||v_energy||', marketplace health '||v_mh||'.');
  return jsonb_build_object('maturity',v_mat,'energy',v_energy,'marketplace_health',v_mh);
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_map(p_per_class integer DEFAULT 40)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with cap as (select greatest(1, least(coalesce(p_per_class, 40), 200)) n),
  ranked as (
    select g.kind, g.ref_id, g.label, g.props,
           row_number() over (partition by g.kind order by g.label, g.ref_id) rn
      from graph_nodes g
  ),
  kept as (select * from ranked, cap where ranked.rn <= cap.n),
  totals as (select kind, count(*) total from graph_nodes group by kind)
  select jsonb_build_object(
    'rebuilt_at', (select max(updated_at) from graph_nodes),
    'node_total', (select count(*) from graph_nodes),
    'edge_total', (select count(*) from graph_edges),
    'per_class_cap', (select n from cap),
    'classes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'kind', t.kind, 'total', t.total,
               'shown', (select count(*) from kept k where k.kind = t.kind))
             order by t.total desc)
        from totals t), '[]'::jsonb),
    'nodes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'kind', k.kind, 'id', k.ref_id, 'label', k.label, 'props', k.props)
             order by k.kind, k.label)
        from kept k), '[]'::jsonb),
    'edges', coalesce((
      select jsonb_agg(distinct jsonb_build_object(
               'src_kind', e.src_kind, 'src', e.src_ref, 'rel', e.rel,
               'dst_kind', e.dst_kind, 'dst', e.dst_ref))
        from graph_edges e
       where exists (select 1 from kept a where a.kind = e.src_kind and a.ref_id = e.src_ref)
         and exists (select 1 from kept b where b.kind = e.dst_kind and b.ref_id = e.dst_ref)),
      '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_company_reflect()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a jsonb; n_concern int := 0; n_act int := 0;
  v_learned int; v_errors int; v_wrong int; v_dept text; v_improved text;
  v_stale int; v_missed int; v_comp int; v_worst text; v_bus text;
begin
  select count(*) into v_learned from institutional_memory where created_at > now()-interval '24 hours';
  select count(*) into v_errors  from agent_runs where status='error' and started_at > now()-interval '24 hours';
  select count(*) into v_wrong   from outcome_record where verdict='worse' and closed_at > now()-interval '24 hours';
  select dept_key into v_dept from org_tasks where status<>'done' group by dept_key order by count(*) desc limit 1;
  select string_agg(actor, ', ') into v_improved from (
    select distinct actor from outcome_record where verdict='improved' and closed_at > now()-interval '7 days' limit 3) x;
  select count(*) into v_stale from agent_knowledge where validation_status in ('stale','quarantined');
  select count(*) into v_missed from v_supply_gap where status='READY - not yet invited';
  select count(*) into v_comp from competitor;
  select name into v_worst from v_supply_gap where status like 'NO POOL%' limit 1;

  -- xos-15. The company asks itself whether its own nervous system is carrying traffic. A
  -- subscribed event type that has never fired is a promise the company is not keeping.
  select coalesce(string_agg(event_type || ' ' || state, ', ' order by event_type),
                  'every subscribed event type is carrying traffic')
    into v_bus from v_event_backbone where state <> 'LIVE';

  a := jsonb_build_object(
    'what_did_i_learn', v_learned||' lesson(s) entered institutional memory in the last 24 hours.',
    'what_mistakes_did_i_make', v_errors||' agent run(s) errored.',
    'which_decisions_were_wrong', v_wrong||' graded improvement(s) made things worse and were flagged for reversal.',
    'which_departments_are_struggling', coalesce('Heaviest open backlog: '||v_dept,'No department is carrying an unusual backlog.'),
    'which_employees_improved', coalesce('Improvements that worked came from: '||v_improved,'No graded improvement has closed successfully yet.'),
    'which_knowledge_became_outdated', v_stale||' knowledge item(s) are stale or quarantined.',
    'which_opportunities_did_i_miss', v_missed||' category/categories have a viable supplier pool and no invitations sent.',
    'which_competitor_became_stronger', v_comp||' competitor(s) tracked but 0 market signals captured, so this cannot be answered honestly yet.',
    'is_my_nervous_system_carrying_traffic', 'Event types subscribed but not live: '||v_bus,
    'how_can_i_be_better_tomorrow', coalesce('Close the supply gap starting with '||v_worst,'Close the open KPI gaps before taking on new work.'));

  if v_errors > 10 then n_concern := n_concern + 1; end if;
  if v_wrong  > 0  then n_concern := n_concern + 1; end if;
  if v_stale  > 50 then n_concern := n_concern + 1; end if;

  -- xos-12. This used to be `insert into org_tasks ... 'procurement'` — the Leadership OS writing
  -- a command straight into the Marketplace OS's queue. It emits now, and procurement's
  -- supply.gap subscription turns it into exactly the same one task, through the bus, with an
  -- audit trail the direct write never had. Deduped on the same 24h window so a nightly
  -- reflection cannot emit the same gap twice.
  if v_missed > 0 then
    if not exists (select 1 from company_event
                    where event_type='supply.gap' and occurred_at > now()-interval '20 hours') then
      perform public.fn_emit('supply.gap', 'category', 'ready_uninvited', 'ceo',
                jsonb_build_object('categories_ready', v_missed,
                                   'detail', v_missed||' category(ies) hold a viable supplier pool with '
                                          || 'no invitations sent. Queue them, or record why not.'));
      n_act := n_act + 1;
    end if;
  end if;

  insert into company_reflection (reflected_on,answers,concerns,actions)
  values (current_date,a,n_concern,n_act)
  on conflict (reflected_on) do update set answers=excluded.answers, concerns=excluded.concerns, actions=excluded.actions;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('company_reflect',now(),now(),'ok',jsonb_build_object('concerns',n_concern,'actions',n_act),
    'Nightly self-reflection: '||n_concern||' concern(s), '||n_act||' action(s) opened. Nobody asked for this.');
  return jsonb_build_object('concerns',n_concern,'actions',n_act,'answers',a);
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_situation()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v text;
begin
  select concat_ws(E'\n',
    'COMPANY SITUATION as at ' || to_char(now(), 'YYYY-MM-DD HH24:MI') || ' UTC. Computed from live rows and shared by every department - do not re-derive it.',
    '',
    'MARKETPLACE STATE',
    (select string_agg('- ' || label || ': ' || coalesce(value::text,'unmeasured')
              || case when target is not null then ' (target ' || target || ', ' || state || ')' else '' end, E'\n' order by domain, label)
     from v_bi_scorecard),
    '',
    'CATEGORY COVERAGE',
    (select '- ' || count(*) filter (where coverage='COMPLIANT') || ' of ' || count(*)
            || ' catalogue categories have an employee at the full 14-module standard; '
            || count(*) filter (where coverage='NO_AGENT') || ' have no employee at all.'
     from v_category_coverage),
    '',
    'RESOURCE PRESSURE',
    (select coalesce(string_agg('- ' || resource || ': ' || state || ' (' || coalesce(used_pct::text,'0') || '% of ' || capacity || ' ' || unit || ')', E'\n' order by resource)
            filter (where state <> 'OK'), '- All pools within limits.')
     from v_resource_pressure),
    '',
    'OPEN RISKS AND SELF-DETECTED DEFECTS',
    (select '- ' || count(*) || ' proposals open from the self-evolution scan; '
            || (select count(*) from risk_register where coalesce(status,'open') = 'open') || ' open risks on the register.'
     from evolution_proposal where status = 'proposed'),
    '',
    'ECONOMIC REALITY',
    (select '- ' || state || '. Reveal rate ' || (reveal_rate*100) || '%, ' || leads_total || ' leads in pipeline, '
            || verified_suppliers || ' verified, ' || inquiries_total || ' inquiries ever, ' || reveals_total || ' reveals ever.'
     from v_unit_economics)
  ) into v;
  return v;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_company_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s jsonb;
begin
  s := jsonb_build_object(
    'employees',        (select count(*) from org_agents where active),
    -- THE CUSTOMER BASE, which the snapshot has never recorded. Zero is the measurement today —
    -- 0 customers and 0 inquiries carrying one — and writing it down daily is what makes the day
    -- it stops being zero visible in the replay.
    'customers',              (select count(*) from customers),
    'customers_with_inquiry', (select count(distinct customer_id) from inquiries where customer_id is not null),
    'departments',      (select count(*) from org_departments where active),
    'operating_systems',(select count(*) from operating_system where active),
    'kpis',             (select count(*) from employee_kpi where active),
    'kpis_measurable',  (select count(*) from employee_kpi where active and measure_sql is not null),
    'kpi_gaps_open',    (select count(*) from org_tasks where title like 'KPI missed:%' and status<>'done'),
    'open_tasks',       (select count(*) from org_tasks where status<>'done'),
    'needs_founder',    (select count(*) from org_tasks where status<>'done' and needs_founder),
    'approved_suppliers',(select count(*) from leads where approval_status='approved'),
    'sendable_pool',    (select coalesce(sum(sendable),0) from v_supply_gap),
    'categories_at_target',(select count(*) from v_supply_gap where approved>=10),
    'revenue_30d_aed',  (select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) from transactions where revealed_at>now()-interval '30 days'),
    'ai_cost_30d_aed',  (select round(coalesce(sum(cost_aed),0),2) from ai_cost_log where occurred_at>now()-interval '30 days'),
    'knowledge_items',  (select count(*) from agent_knowledge),
    'knowledge_quarantined',(select count(*) from agent_knowledge where validation_status='quarantined'),
    'outcomes_pending', (select count(*) from outcome_record where verdict='pending'),
    'outcomes_improved',(select count(*) from outcome_record where verdict='improved'),
    'decisions_7d',     (select count(*) from decision_log where created_at>now()-interval '7 days'),
    'agent_runs_7d',    (select count(*) from agent_runs where started_at>now()-interval '7 days'),
    'error_rate_7d',    (select round(100.0*count(*) filter (where status='error')/nullif(count(*),0),2) from agent_runs where started_at>now()-interval '7 days'),
    'os_health',        (select jsonb_object_agg(os_key,health) from os_review where period=to_char(now(),'IYYY-"W"IW')),
    'indices',          (select jsonb_object_agg(index_name,score) from company_index where measured_on=current_date),
    'autonomy_enabled', (select value from app_secrets where key='agent_autonomy_enabled'),
    'invite_enabled',   (select value from app_secrets where key='invite_enabled'));

  insert into company_snapshot (snapshot_on, state) values (current_date, s)
  on conflict (snapshot_on) do update set state=excluded.state, created_at=now();

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('company_snapshot',now(),now(),'ok',jsonb_build_object('keys',(select count(*) from jsonb_object_keys(s))),
    'Company state snapshotted for '||current_date||'. Any past day can now be reconstructed.');
  return s;
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_state()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with depts as (
    select d.dept_key, d.name, d.charter, d.north_star, d.lead_agent, d.active,
           coalesce((select array_agg(a.agent_key order by a.agent_key) from org_agents a where a.department=d.dept_key and a.active), '{}') as brain_agents,
           (select count(*) from org_agents a where a.department=d.dept_key and a.active) as brain_count,
           (select count(*) from org_action_executor e where e.department=d.dept_key and e.active) as tool_count
    from org_departments d where d.active
  )
  select jsonb_build_object(
    'vision', (select vision from company_vision where id=1),
    'mission', (select mission from company_vision where id=1),
    'as_of', now(),
    'totals', jsonb_build_object(
      'departments', (select count(*) from depts),
      'brain_agents', (select count(*) from org_agents where active),
      'category_sales_agents', (select count(*) from category_agents),
      'tools_wired', (select count(*) from org_action_executor where active),
      'open_objectives', (select count(*) from org_objectives where status not in ('done','cancelled')),
      'open_tasks', (select count(*) from org_tasks where status in ('assigned','proposed','in_progress'))
    ),
    'departments', (select jsonb_agg(jsonb_build_object(
        'dept', dept_key, 'name', name, 'charter', charter, 'north_star', north_star,
        'lead_agent', lead_agent, 'brain_agents', brain_agents,
        'headcount', brain_count + case when dept_key='procurement' then (select count(*) from category_agents) else 0 end,
        'tools_wired', tool_count) order by dept_key) from depts)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_context_retrieval_prune()
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with d as (delete from agent_context_retrieval where created_at < now() - interval '7 days' returning 1)
  select count(*)::int from d;
$function$


CREATE OR REPLACE FUNCTION public.fn_context_slice(p_dept text, p_role_ids text[], p_category text, p_layer text, p_q tsquery, p_budget integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with scoped as (
    select record_id, title, content, version, source_freshness, effective_date, review_after,
           layer, record_type, authority_tier, tsv
      from ops_knowledge
     where runtime_eligible
       and supersession_state = 'current'
       and layer = p_layer
       and (
         (p_layer = 'company_core'        and scope_type = 'company')
      -- THE MERGE ARM. A department that absorbed another owns its predecessor's knowledge; the
      -- 5,775 rows tagged with the 22 absorbed keys are not rewritten, they are scoped in.
      or (p_layer = 'department_shared'   and dept_key = any(public.fn_dept_scope(p_dept)))
      or (p_layer = 'role_specific'       and role_key = any(coalesce(p_role_ids, '{}')))
      or (p_layer = 'category_specialist' and category_key = p_category)
       )
  ), matched as (
    -- THE FILTER THAT WAS DEAD. No `or true`: when a query is supplied it now decides membership.
    select *, ts_rank(tsv, p_q) as rank, 'query'::text as match
      from scoped
     where p_q is not null and tsv @@ p_q
  ), fallback as (
    -- Only consulted when topical retrieval under-delivers. Highest authority first, and every row
    -- carries match='fallback' so the caller can tell the difference.
    select *, 0::real as rank, 'fallback'::text as match
      from scoped
     where p_q is null or (select count(*) from matched) < 3
  ), unioned as (
    select * from matched
    union all
    select * from fallback f where not exists (select 1 from matched m where m.record_id = f.record_id)
  ), deduped as (
    -- Duplicate suppression: the same record can be reachable by more than one scope arm, and the
    -- same TITLE often repeats across package generations. Keep the freshest of each title.
    select distinct on (coalesce(nullif(title,''), record_id))
           record_id, title, content, version, source_freshness, effective_date, review_after,
           layer, record_type, authority_tier, rank, match
      from unioned
     order by coalesce(nullif(title,''), record_id),
              (match = 'query') desc, rank desc,
              coalesce(effective_date, '1900-01-01'::date) desc, record_id
  ), ranked as (
    select *,
           -- freshness is carried, not judged here: review_after in the past is stale and the
           -- caller must be able to see that rather than infer it.
           (review_after is not null and review_after < current_date) as stale,
           sum(least(length(content), 1800)) over (
             order by (match = 'query') desc, rank desc, record_id
             rows between unbounded preceding and current row) as running
      from deduped
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'record_id', record_id, 'title', title, 'layer', layer, 'record_type', record_type,
           'version', version, 'source_freshness', source_freshness,
           'review_after', review_after, 'stale', stale,
           'authority_tier', authority_tier, 'match', match,
           'content', left(content, 1800))
         order by (match = 'query') desc, rank desc, record_id), '[]'::jsonb)
    from ranked
   where running <= greatest(p_budget, 1800);
$function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_challenge_minutes()
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select greatest(1, least(15, coalesce((select value from public.app_secrets where key='control_mode_challenge_minutes')::int, 5)));
$function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_challenge_start(p_actor_email text, p_code_hash text, p_ip text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id record; v_phone text; v_recent int; v_row public.control_mode_challenge%rowtype; v_min int;
begin
  select * into v_id from public.control_mode_identity
   where admin_email = lower(btrim(p_actor_email)) and active;
  if not found then
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'challenge_denied', false, 'not a registered Control Mode identity');
    return jsonb_build_object('ok', false, 'error', 'not_a_control_mode_identity',
      'message', 'This account is not registered for Control Mode. Registering one is itself a Control Mode change.');
  end if;

  select value into v_phone from public.app_secrets where key = v_id.phone_secret_key;
  if coalesce(length(btrim(v_phone)),0) < 8 then
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'challenge_denied', false, 'no phone configured at ' || v_id.phone_secret_key);
    return jsonb_build_object('ok', false, 'error', 'control_mode_phone_not_configured',
      'message', 'No Control Mode phone number is configured. Set app_secrets.' || v_id.phone_secret_key || '.');
  end if;

  -- Rate limit. Without one, an attacker with a session cookie can spray the founder's phone until
  -- a code is approved out of irritation.
  select count(*) into v_recent from public.control_mode_challenge
   where admin_email = v_id.admin_email and created_at > now() - interval '1 hour';
  if v_recent >= 5 then
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'challenge_denied', false, 'rate limit: 5 challenges per hour');
    return jsonb_build_object('ok', false, 'error', 'too_many_challenges',
      'message', 'Too many Control Mode codes requested in the last hour. Wait, then try again.');
  end if;

  -- Anything still open is void. Two live codes means two ways in.
  update public.control_mode_challenge
     set consumed_at = now(), consumed_why = 'superseded'
   where admin_email = v_id.admin_email and consumed_at is null;

  v_min := public.fn_control_mode_challenge_minutes();
  insert into public.control_mode_challenge (admin_email, nonce, code_hash, phone_tail, expires_at, ip)
  values (v_id.admin_email, encode(extensions.gen_random_bytes(18), 'hex'), p_code_hash,
          right(btrim(v_phone), 4), now() + make_interval(mins => v_min), p_ip)
  returning * into v_row;

  insert into public.control_mode_audit (actor_email, event, allowed, reason, detail)
  values (p_actor_email, 'challenge_started', true, 'control_mode challenge issued',
          jsonb_build_object('challenge_id', v_row.id, 'phone_tail', v_row.phone_tail, 'minutes', v_min));

  return jsonb_build_object('ok', true, 'challenge_id', v_row.id, 'nonce', v_row.nonce,
                            'expires_at', v_row.expires_at, 'phone_tail', v_row.phone_tail,
                            'phone', btrim(v_phone), 'minutes', v_min);
end $function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_close(p_actor_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n int;
begin
  update public.control_mode_session set closed_at = now(), closed_reason = 'closed by actor'
   where actor_email = p_actor_email and closed_at is null;
  get diagnostics v_n = row_count;
  if v_n > 0 then
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'close', true, 'closed by actor');
  end if;
  return jsonb_build_object('ok', true, 'closed', v_n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_identity_active(p_email text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.control_mode_identity
                  where admin_email = lower(btrim(p_email)) and active);
$function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_minutes()
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  select least(60, greatest(5, coalesce((select nullif(btrim(value),'')::int from app_secrets where key='control_mode_minutes'), 15)));
$function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_open(p_actor_email text, p_reason text, p_challenge_id uuid, p_nonce text, p_code text, p_user_id uuid DEFAULT NULL::uuid, p_ip text DEFAULT NULL::text, p_ua text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_c public.control_mode_challenge%rowtype; v_id uuid; v_min int := public.fn_control_mode_minutes();
        v_reason text; v_raw_len int;
begin
  if coalesce(btrim(p_reason),'') = '' then
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'open_denied', false, 'no reason given');
    return jsonb_build_object('ok', false, 'error', 'reason_required',
      'message', 'Control Mode needs a reason. It is written into the audit trail beside whatever you change.');
  end if;

  -- Bound the reason exactly as user_agent is bounded below, and record what was dropped.
  v_reason := btrim(p_reason);
  v_raw_len := length(v_reason);
  if v_raw_len > 1000 then
    v_reason := left(v_reason, 1000) || ' [truncated from ' || v_raw_len || ' characters]';
  end if;

  select * into v_c from public.control_mode_challenge
   where id = p_challenge_id
     and admin_email = lower(btrim(p_actor_email))
     and purpose = 'control_mode'
   for update;

  if not found then
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'open_denied', false, 'no such Control Mode challenge for this identity');
    return jsonb_build_object('ok', false, 'error', 'challenge_not_found',
      'message', 'That Control Mode request does not exist, or belongs to a different account. Start a new one.');
  end if;

  if v_c.consumed_at is not null then
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'open_denied', false, 'challenge already used: ' || coalesce(v_c.consumed_why,'used'));
    return jsonb_build_object('ok', false, 'error', 'challenge_already_used',
      'message', 'That code has already been used. Request a new one.');
  end if;

  if v_c.expires_at <= now() then
    update public.control_mode_challenge set consumed_at = now(), consumed_why = 'expired' where id = v_c.id;
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'open_denied', false, 'challenge expired');
    return jsonb_build_object('ok', false, 'error', 'challenge_expired',
      'message', 'That code has expired. Request a new one.');
  end if;

  if v_c.attempts >= v_c.max_attempts then
    update public.control_mode_challenge set consumed_at = now(), consumed_why = 'attempts_exhausted' where id = v_c.id;
    insert into public.control_mode_audit (actor_email, event, allowed, reason)
    values (p_actor_email, 'open_denied', false, 'attempt limit reached');
    return jsonb_build_object('ok', false, 'error', 'too_many_attempts',
      'message', 'Too many wrong codes. That request is closed - start a new one.');
  end if;

  -- Nonce and code are checked together, and only the hashed code is ever compared.
  if v_c.nonce <> coalesce(p_nonce,'') or v_c.code_hash <> public.fn_otp_hash(coalesce(p_code,'')) then
    update public.control_mode_challenge set attempts = attempts + 1 where id = v_c.id;
    insert into public.control_mode_audit (actor_email, event, allowed, reason, detail)
    values (p_actor_email, 'open_denied', false, 'mfa_failed',
            jsonb_build_object('attempt', v_c.attempts + 1, 'of', v_c.max_attempts));
    return jsonb_build_object('ok', false, 'error', 'mfa_failed',
      'attempts_left', greatest(0, v_c.max_attempts - (v_c.attempts + 1)),
      'message', 'That code is not right. Check the message and try again.');
  end if;

  update public.control_mode_challenge set consumed_at = now(), consumed_why = 'opened' where id = v_c.id;

  update public.control_mode_session
     set closed_at = now(), closed_reason = 'superseded by a new session'
   where actor_email = p_actor_email and closed_at is null;

  insert into public.control_mode_session (user_id, actor_email, reason, expires_at, mfa_method, mfa_ref, ip, user_agent)
  values (p_user_id, p_actor_email, v_reason, now() + make_interval(mins => v_min),
          'control_mode_challenge', v_c.id, p_ip, left(coalesce(p_ua,''), 300))
  returning id into v_id;

  insert into public.control_mode_audit (actor_email, event, session_id, allowed, reason, detail)
  values (p_actor_email, 'open', v_id, true, v_reason,
          jsonb_build_object('minutes', v_min, 'ip', p_ip, 'challenge_id', v_c.id,
                             'reason_chars', v_raw_len, 'reason_truncated', (v_raw_len > 1000)));

  return jsonb_build_object('ok', true, 'session_id', v_id, 'expires_at', now() + make_interval(mins => v_min),
                            'minutes', v_min,
                            'message', 'Control Mode is open for ' || v_min || ' minutes. It closes on its own.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_require(p_actor_email text, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_class text; v_s record;
begin
  -- AUDIT 8.3 TIER 0. Phase 1 rolled back to observe-only. Still audited, deliberately: during an
  -- incident, the record of what was done under the relaxed control is the most valuable thing here.
  if public.fn_phase1_disarmed() then
    insert into public.control_mode_audit (actor_email, event, action, allowed, reason)
    values (p_actor_email, 'action_allowed_phase1_disarmed', p_action, true,
            'Phase 1 Control Mode is disarmed - see public.phase1_rollback_log for who disarmed it and why');
    return jsonb_build_object('allowed', true, 'mode', 'disarmed',
      'reason', 'Phase 1 Control Mode is disarmed (rollback tier 0)');
  end if;

  select classification into v_class from public.control_mode_action where action = p_action;

  -- FAIL CLOSED. An action nobody classified is an action nobody thought about, and the cost of
  -- being wrong is asymmetric: refusing a read is an inconvenience, allowing an unreviewed mutation
  -- is the incident. The refusal is audited so the missing classification is discoverable.
  if v_class is null then
    insert into public.control_mode_audit (actor_email, event, action, allowed, reason)
    values (p_actor_email, 'action_unclassified', p_action, false, 'action is not in control_mode_action');
    return jsonb_build_object(
      'allowed', false, 'mode', 'observe', 'error', 'action_classification_required',
      'message', 'This action has not been classified as read-only or mutating, so it is refused. '
              || 'Classify it in control_mode_action (and in os_api ACTION_CLASS) before using it.');
  end if;

  if v_class = 'read_only' then
    return jsonb_build_object('allowed', true, 'mode', 'observe', 'reason', 'action is registered read-only');
  end if;

  if v_class = 'mode_control' then
    return jsonb_build_object('allowed', true, 'mode', 'observe', 'reason', 'Control Mode plumbing; handled before the gate');
  end if;

  -- FOUNDER-GATED (15 Aug 2026). The founder's own command channel. It writes, so it is audited
  -- exactly like a Control Mode action; it is not gated by Control Mode, because the identity
  -- allow-list in phase_c_founder_identity is the control, and it is a stronger one than a
  -- fifteen-minute session — a stolen admin session is not the founder.
  if v_class = 'founder_gated' then
    insert into public.control_mode_audit (actor_email, event, action, allowed, reason)
    values (p_actor_email, 'action_allowed_founder_gated', p_action, true,
            'founder-identity gated: writes a work plan only, and fn_founder_command_submit refuses a caller who is not the registered founder');
    return jsonb_build_object('allowed', true, 'mode', 'founder',
      'reason', 'founder-identity gated; Control Mode does not apply to the founder''s own command channel');
  end if;

  select * into v_s from public.control_mode_session
   where actor_email = p_actor_email and closed_at is null and expires_at > now()
   order by opened_at desc limit 1;

  if not found then
    insert into public.control_mode_audit (actor_email, event, action, allowed, reason)
    values (p_actor_email, 'action_denied', p_action, false, 'no active Control Mode session');
    return jsonb_build_object('allowed', false, 'mode', 'observe', 'error', 'control_mode_required',
      'message', 'This changes something, so it needs Control Mode. Open it with a code sent to your phone, and say why.');
  end if;

  update public.control_mode_session set actions_used = actions_used + 1 where id = v_s.id;
  insert into public.control_mode_audit (actor_email, event, action, session_id, allowed, reason)
  values (p_actor_email, 'action_allowed', p_action, v_s.id, true, v_s.reason);

  return jsonb_build_object('allowed', true, 'mode', 'control', 'session_id', v_s.id, 'reason', v_s.reason,
                            'seconds_remaining', greatest(0, extract(epoch from (v_s.expires_at - now()))::int));
end $function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_session_mfa_is_real()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v public.control_mode_challenge%rowtype;
begin
  select * into v from public.control_mode_challenge where id = new.mfa_ref;
  if not found then
    raise exception 'control mode: mfa_ref % is not a challenge', new.mfa_ref using errcode = '23514';
  end if;
  if lower(btrim(v.admin_email)) <> lower(btrim(new.actor_email)) then
    raise exception 'control mode: challenge belongs to %, not %', v.admin_email, new.actor_email using errcode = '23514';
  end if;
  if v.purpose <> 'control_mode' then
    raise exception 'control mode: challenge % was issued for %, not control_mode', v.id, v.purpose using errcode = '23514';
  end if;
  if v.consumed_at is null or coalesce(v.consumed_why,'') <> 'opened' then
    raise exception 'control mode: challenge % was not consumed by an open (consumed_why=%)',
      v.id, coalesce(v.consumed_why,'<null>') using errcode = '23514';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_status(p_actor_email text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    -- An open session still reads as Control, disarmed or not: if one exists it is real and it
    -- is audited, and hiding it would be its own lie.
    (select jsonb_build_object(
       'mode','control', 'session_id', s.id, 'reason', s.reason,
       'opened_at', s.opened_at, 'expires_at', s.expires_at,
       'seconds_remaining', greatest(0, extract(epoch from (s.expires_at - now()))::int),
       'actions_used', s.actions_used)
     from public.control_mode_session s
     where s.actor_email = p_actor_email and s.closed_at is null and s.expires_at > now()
     order by s.opened_at desc limit 1),
    -- THE GATE IS OFF. Say so, say who turned it off and when, and say what is still holding —
    -- because "no second factor" is not "no security", and the founder should not read it as one.
    (select jsonb_build_object(
       'mode','disarmed', 'session_id', null,
       'disarmed_at', r.at, 'disarmed_by', r.actor,
       'message','Control Mode is switched off. Changes go through without a code, and every one '
                 ||'of them is still authenticated, attributed and audited. Turned off '
                 ||to_char(r.at at time zone 'UTC','DD Mon YYYY')||' by '||coalesce(r.actor,'an administrator')||'.')
     from public.phase1_rollback_log r
     where public.fn_phase1_disarmed()
     order by r.at desc limit 1),
    jsonb_build_object('mode','observe','session_id', null,
      'message','Observe Mode. Everything is readable; nothing can be changed until Control Mode is opened with a code.'));
$function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_sweep()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_sessions int; v_deleted int := 0;
begin
  with c as (
    update public.control_mode_session set closed_at = now(), closed_reason = 'expired'
     where closed_at is null and expires_at <= now() returning id, actor_email
  ), a as (
    insert into public.control_mode_audit (actor_email, event, session_id, allowed, reason)
    select actor_email, 'expired', id, true, 'session timed out' from c
  )
  select count(*)::int into v_sessions from c;

  update public.control_mode_challenge
     set consumed_at = now(), consumed_why = 'expired'
   where consumed_at is null and expires_at <= now();

  -- RETENTION, RING-FENCED. Everything above this point is the sweep's actual job; everything
  -- inside is tidying. A failure here is recorded and swallowed so it can never again roll back a
  -- session that was supposed to close.
  begin
    delete from public.control_mode_challenge c
     where c.consumed_at < now() - interval '7 days'
       and not exists (select 1 from public.control_mode_session s where s.mfa_ref = c.id);
    get diagnostics v_deleted = row_count;
  exception when others then
    insert into public.agent_runs(agent, status, counts, note, started_at, finished_at)
    values ('control_mode_sweep', 'error',
            jsonb_build_object('sessions_expired', v_sessions, 'retention_failed', true),
            'Control-mode challenge retention failed but the sweep still expired its sessions: '
            || replace(coalesce(sqlerrm,'unknown'), '''', ''), now(), now());
  end;

  return v_sessions;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_cos_work_gate()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_budget int;
  v_used   int;
  v_demand int;
  v_reflect int;
  v_classes jsonb;
begin
  select coalesce((value #>> '{}')::int, 6) into v_budget
    from public.decision_policy where key = 'cos_reflection_tasks_per_day';
  v_budget := coalesce(v_budget, 6);

  select count(*) into v_used
    from public.org_tasks k
   where k.last_run_at >= date_trunc('day', (now() at time zone 'utc')) at time zone 'utc'
     and not public.fn_task_is_demand(k.action_class)
     -- NOT `result->>'mode' <> 'executed_by_invoker'`, which is what this said first and it
     -- over-counted by ten on the first run. That mode is written by fn_action_invoke_collect at
     -- COLLECT time, so a task the invoker dispatched at :45 and has not collected yet still reads
     -- mode NULL and was counted as model work. The ten 'Supply gap' knowledge_acquire tasks in
     -- flight this morning are exactly that: kb_deepen at 0.026 AED a call, charged against a
     -- ceiling meant for a 25,000-token one. The invoker ALWAYS leaves an action_execution row and
     -- the cos_execute model path never does, so the row is the reliable discriminator and it is
     -- true from dispatch, not from collection.
     and not exists (
       select 1 from public.action_execution a
        where (a.request->>'org_task_id') = k.id::text
          and a.created_at >= date_trunc('day', (now() at time zone 'utc')) at time zone 'utc');

  select count(*) filter (where not public.fn_task_is_demand(action_class))
    into v_reflect
    from public.org_tasks where status in ('assigned','in_progress');

  -- The concrete classes cos_execute may select on. PostgREST cannot evaluate the regex above, so
  -- the gate resolves it here against the classes that ACTUALLY have open work and hands back a
  -- list. One source of truth, and the edge function carries no copy of the pattern.
  --
  -- AND IT REFUSES ANY CLASS WIRED TO AN UNSAFE EXECUTOR. This gate moves demand work to the FRONT
  -- of cos_execute's queue, and a cost control must never widen a risk. Found on the first run, and
  -- it was not hypothetical: org_tasks 1360 and 1361 - "Start invites: kitchen-and-bathroom-
  -- suppliers", "Start invites: real-estate-agencies" - are action_class='invite', tier='autonomous',
  -- status='assigned', wired to fn_org_exec_invite with risk_tier='high', advisory_safe=false,
  -- reversible=false. They carry the HIGHEST ids in a 385-row FIFO queue, so today they are
  -- unreachable; promoting 'invite' to the head of the queue would have put a high-risk irreversible
  -- supplier mailing first in line, on the exact day the founder wrote "LAST — supplier invites. DO
  -- NOT ENABLE YET" because the bounce rate is at the platform's own 0.08 brake.
  --
  -- A class is eligible only if NO active executor for it is high-risk, irreversible or not
  -- advisory-safe. This is the same triple fn_org_task_execute_sweep already requires before it will
  -- invoke anything; the two paths now agree instead of disagreeing.
  select coalesce(jsonb_agg(distinct k.action_class), '[]'::jsonb) into v_classes
    from public.org_tasks k
   where k.status in ('assigned','in_progress')
     and k.action_class is not null
     and public.fn_task_is_demand(k.action_class)
     and not exists (
       select 1 from public.org_action_executor e
        where e.action_class = k.action_class and e.active
          and (e.risk_tier <> 'low' or not e.advisory_safe or not e.reversible));

  -- demand_open counts ELIGIBLE demand only — the same set cos_execute can actually select. Counting
  -- every demand-classed row here would report "2 revenue-path tasks still run uncapped" for two
  -- invite tasks the gate has just refused to hand over, and gated=false would then describe a run
  -- that in fact calls no model. The number and the decision have to come from one set.
  select count(*) into v_demand
    from public.org_tasks
   where status in ('assigned','in_progress')
     and action_class is not null
     and v_classes ? action_class;

  return jsonb_build_object(
    'demand_classes',         v_classes,
    'reflection_budget',      v_budget,
    'reflection_used_today',  v_used,
    'reflection_allowed',     v_used < v_budget,
    'demand_open',            v_demand,
    'reflection_open',        v_reflect,
    -- nothing at all to do without a model: the ceiling is spent AND no revenue-path task is waiting
    'gated',                  (v_used >= v_budget and v_demand = 0),
    'reason', case
        when v_used < v_budget then
          'reflection ' || v_used || '/' || v_budget || ' today; working normally'
        when v_demand > 0 then
          'reflection ceiling reached (' || v_used || '/' || v_budget || '); ' || v_demand ||
          ' revenue-path task(s) still run uncapped'
        else
          'reflection ceiling reached (' || v_used || '/' || v_budget || ') and no revenue-path task '
          'is waiting, so no model is called this run'
      end
  );
end
$function$


CREATE OR REPLACE FUNCTION public.fn_cost_per_os(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_since timestamptz := now() - make_interval(days => greatest(coalesce(p_days,30), 1));
  v_rows jsonb; v_total numeric; v_calls bigint; v_unattributed bigint;
  v_unpriceable bigint; v_unpriceable_tokens bigint; v_first_unpriceable date; v_last_unpriceable date;
begin
  select coalesce(sum(cost_aed),0), count(*),
         count(*) filter (where dept_key is null),
         count(*) filter (where coalesce(cost_aed,0)=0 and (coalesce(prompt_tokens,0)+coalesce(output_tokens,0))>0 and not coalesce(cached,false)),
         coalesce(sum(coalesce(prompt_tokens,0)+coalesce(output_tokens,0))
                  filter (where coalesce(cost_aed,0)=0 and (coalesce(prompt_tokens,0)+coalesce(output_tokens,0))>0 and not coalesce(cached,false)),0),
         min(occurred_at) filter (where coalesce(cost_aed,0)=0 and (coalesce(prompt_tokens,0)+coalesce(output_tokens,0))>0 and not coalesce(cached,false))::date,
         max(occurred_at) filter (where coalesce(cost_aed,0)=0 and (coalesce(prompt_tokens,0)+coalesce(output_tokens,0))>0 and not coalesce(cached,false))::date
    into v_total, v_calls, v_unattributed, v_unpriceable, v_unpriceable_tokens, v_first_unpriceable, v_last_unpriceable
    from ai_cost_log where occurred_at > v_since;

  select coalesce(jsonb_agg(x order by x->>'cost_aed' desc), '[]'::jsonb) into v_rows from (
    select jsonb_build_object(
             'os_key',       coalesce(d.os_key, '(unattributed)'),
             'departments',  count(distinct l.dept_key),
             'calls',        count(*),
             'tokens',       coalesce(sum(coalesce(l.prompt_tokens,0)+coalesce(l.output_tokens,0)),0),
             'cost_aed',     round(coalesce(sum(l.cost_aed),0), 4),
             'share_pct',    case when v_total > 0
                                  then round(100.0 * coalesce(sum(l.cost_aed),0) / v_total, 1)
                                  else null end,
             'cost_per_call', case when count(*) > 0
                                   then round(coalesce(sum(l.cost_aed),0) / count(*), 5) else null end
           ) x
      from ai_cost_log l
      left join os_department d on d.dept_key = l.dept_key
     where l.occurred_at > v_since
     group by coalesce(d.os_key, '(unattributed)')
  ) s;

  return jsonb_build_object(
    'window_days', p_days,
    'since', v_since,
    'total_cost_aed', round(v_total, 4),
    'by_os', v_rows,
    -- THE COVERAGE TRAVELS WITH THE NUMBER. A caller cannot read one without the other.
    'coverage', jsonb_build_object(
      'calls', v_calls,
      'attributed_to_a_department', v_calls - v_unattributed,
      'unattributed', v_unattributed,
      'attributed_pct', case when v_calls > 0
                             then round(100.0 * (v_calls - v_unattributed) / v_calls, 1) else null end,
      'departments_seen', (select count(distinct dept_key) from ai_cost_log where occurred_at > v_since),
      'departments_active', (select count(*) from org_departments where active),
      'unpriceable_calls', v_unpriceable,
      'unpriceable_tokens', v_unpriceable_tokens,
      'unpriceable_window', case when v_unpriceable > 0
        then v_first_unpriceable::text || ' to ' || v_last_unpriceable::text else null end,
      'note', 'Unpriceable = real tokens, not cached, cost_aed 0. Those calls are counted in "calls" and contribute 0 to cost, so total_cost_aed is a FLOOR, not the spend. They are deliberately not repriced: applying today''s model_rate to past usage would report a number that was never charged.')
  );
end $function$


CREATE OR REPLACE FUNCTION public.fn_cron_liveness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'cron'
AS $function$
declare v_age numeric; v_last timestamptz;
begin
  select max(start_time) into v_last from cron.job_run_details;
  if v_last is null then
    return jsonb_build_object('healthy', false, 'newest_run_age_min', null, 'note', 'no cron run history');
  end if;
  v_age := extract(epoch from (now() - v_last))/60.0;
  return jsonb_build_object(
    'healthy', v_age <= 20,               -- crons run every few minutes; >20min silence = scheduler down
    'newest_run_age_min', round(v_age,1),
    'checked_at', now());
exception when others then
  return jsonb_build_object('healthy', null, 'error', sqlerrm);
end $function$


CREATE OR REPLACE FUNCTION public.fn_cron_ran(p_jobname text, p_within interval DEFAULT '26:00:00'::interval)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'cron', 'public', 'pg_temp'
AS $function$
declare v boolean;
begin
  select exists (
    select 1 from cron.job j
    join cron.job_run_details d on d.jobid = j.jobid
    where j.jobname = p_jobname
      and d.start_time > now() - p_within
      and d.status = 'succeeded'
  ) into v;
  return coalesce(v,false);
exception when others then
  return true;  -- if the history is unreadable, do not raise a false alarm
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_decision_support(p_customer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  -- A median over fewer than this many quotes is an anecdote wearing a statistic's clothes.
  MIN_PRICE_N constant int := 5;
  v_recommend jsonb;
  v_chase     jsonb;
  v_market    jsonb;
begin
  if p_customer is null then return jsonb_build_object('error','no_customer'); end if;

  -- ── 1. WHICH QUOTE, AND WHY ────────────────────────────────────────────────────────────────
  -- lead_time is free text ('3 weeks', '10-14 days', 'ASAP'). The first integer is taken and
  -- scaled by the unit word; anything that yields no integer is UNKNOWN and never claimed as fast.
  -- A quote with no parseable lead time cannot win the speed comparison, which is the honest
  -- outcome: we would be guessing on the customer's behalf.
  with q as (
    select i.id inq, i.summary, i.category, q.id qid, q.supplier_id,
           coalesce(q.customer_price, q.quote_amount) price,
           q.lead_time,
           case
             when q.lead_time ~ '\d' then
               (regexp_match(q.lead_time, '(\d+)'))[1]::int
               * case when q.lead_time ~* 'week' then 7 when q.lead_time ~* 'month' then 30 else 1 end
             else null
           end days
    from inquiries i
    join quotes q on q.inquiry_id = i.id
    where i.customer_id = p_customer
      and coalesce(q.status,'') not in ('withdrawn','expired','rejected')
      and coalesce(q.customer_price, q.quote_amount) is not null
  ),
  agg as (
    select inq, min(summary) summary, min(category) category, count(*) n,
           min(price) lo, max(price) hi,
           (array_agg(qid order by price asc))[1]                       cheapest_id,
           (array_agg(price order by price asc))[1]                     cheapest_price,
           (array_agg(price order by price asc))[2]                     next_price,
           (array_agg(qid  order by days asc) filter (where days is not null))[1] fastest_id,
           (array_agg(days order by days asc) filter (where days is not null))[1] fastest_days,
           (array_agg(days order by price asc))[1]                      cheapest_days,
           count(*) filter (where days is not null)                     n_with_days
    from q group by inq
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'inquiry_id', inq, 'summary', summary, 'category', category, 'quotes', n,
           'cheapest_quote_id', cheapest_id, 'cheapest_price', cheapest_price,
           'saving_vs_next', case when next_price is not null then next_price - cheapest_price end,
           'fastest_quote_id', fastest_id, 'fastest_days', fastest_days,
           'same_quote_wins', (fastest_id is not null and fastest_id = cheapest_id),
           -- Only a real trade-off gets a trade-off sentence. Null here means either one quote
           -- won both ways, or too few lead times were stated to compare speed at all.
           'days_sooner', case when fastest_id is distinct from cheapest_id and fastest_days is not null
                                 and cheapest_days is not null then cheapest_days - fastest_days end,
           'spread', hi - lo,
           'lead_times_stated', n_with_days
         ) order by n desc), '[]'::jsonb)
    into v_recommend from agg where n >= 2;

  -- ── 2. WHAT A JOB LIKE THIS NORMALLY COSTS ─────────────────────────────────────────────────
  -- Answered per category the customer actually uses, or - for a customer with no requests yet -
  -- left empty rather than filled with the platform average of nothing.
  -- fn_norm_trades is resolved ONCE PER CATEGORY here, not inside the correlated subqueries below.
  -- Called per row it is re-evaluated against all 15,306 supplier_capabilities rows twice over and
  -- the whole function times out - measured, it did.
  with cats as (
    select distinct i.category, i.emirate, public.fn_norm_trades(i.category) norm from inquiries i
    where i.customer_id = p_customer and i.category is not null
  ),
  m as (
    select c.category, c.emirate,
           s.n price_n, s.median, s.p25, s.p75,
           -- THROUGH THE LEXICON, NOT THE RAW CATEGORY. A probe with category 'marble' counted 0
           -- suppliers against 15,306 capability rows, because no supplier lists a trade called
           -- "marble" - fn_norm_trades('marble') is {flooring}, and that is the vocabulary the
           -- capability rows are written in. Comparing the customer's word directly against the
           -- supplier's word is the same defect that left discover() returning nothing while
           -- route_inquiry worked: one path got the lexicon and its sibling did not.
           (select count(*) from supplier_capabilities sc
             where (sc.trades && c.norm or sc.services && c.norm)
               and (c.emirate is null or sc.coverage_emirates && array[c.emirate])) suppliers_covering,
           (select count(*) from supplier_capabilities sc
             where (sc.trades && c.norm or sc.services && c.norm)
               and (c.emirate is null or sc.coverage_emirates && array[c.emirate])
               and sc.review_status = 'confirmed')                                  suppliers_confirmed,
           (select round(avg(extract(epoch from (q.created_at - i2.created_at))/86400)::numeric, 1)
              from inquiries i2 join quotes q on q.inquiry_id = i2.id
             where i2.category = c.category)                                        avg_days_to_quote
    from cats c left join category_price_stats s on s.category = c.category
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'category', category, 'emirate', emirate,
           -- The price block is present ONLY when it rests on enough quotes to mean something.
           -- Absent is a statement; a median over two quotes is a different and false one.
           'price_known', (coalesce(price_n,0) >= MIN_PRICE_N),
           'price_n', coalesce(price_n,0),
           'median', case when coalesce(price_n,0) >= MIN_PRICE_N then median end,
           'p25',    case when coalesce(price_n,0) >= MIN_PRICE_N then p25 end,
           'p75',    case when coalesce(price_n,0) >= MIN_PRICE_N then p75 end,
           'suppliers_covering', suppliers_covering,
           'suppliers_confirmed', suppliers_confirmed,
           'avg_days_to_quote', avg_days_to_quote
         )), '[]'::jsonb)
    into v_market from m;

  -- ── 3. A REQUEST HAS GONE QUIET ────────────────────────────────────────────────────────────
  -- One state per open request, each with the action that actually moves it. The thresholds are
  -- deliberately generous: telling somebody their request is stalled on day one is noise, and a
  -- portal that cries stalled is one a customer stops reading.
  with open_i as (
    select i.id, i.summary, i.category, i.created_at,
           extract(epoch from (now() - i.created_at))/86400 age_days,
           (select count(*) from inquiry_matches m where m.inquiry_id = i.id) invited,
           (select count(*) from quotes q where q.inquiry_id = i.id
              and coalesce(q.status,'') not in ('withdrawn','expired','rejected')) quotes
    from inquiries i
    where i.customer_id = p_customer
      and coalesce(i.status,'open') not in ('closed','cancelled','completed','archived')
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'inquiry_id', id, 'summary', summary, 'category', category,
           'age_days', round(age_days::numeric,1), 'invited', invited, 'quotes', quotes,
           -- QUOTE-BEARING STATES ARE TESTED FIRST. Written the other way round, a request that had
           -- collected two quotes but no inquiry_matches row reported 'not_yet_sent' - the portal
           -- telling a customer we had not reached any supplier while two of their quotes sat on
           -- the screen. A quote is proof of delivery; the absence of a match row is only proof
           -- that one path recorded it. Caught by an aborted-transaction probe that seeded exactly
           -- that shape; an empty result would have proved nothing.
           'state', case
             when quotes >= 2 and age_days >= 7              then 'undecided'
             when quotes  = 1 and age_days >= 5              then 'only_one'
             when quotes  = 0 and invited = 0 and age_days >= 1 then 'not_yet_sent'
             when quotes  = 0 and age_days >= 3              then 'no_replies'
             else 'healthy' end
         ) order by age_days desc), '[]'::jsonb)
    into v_chase
    from open_i
   where case
           when quotes >= 2 and age_days >= 7 then true
           when quotes  = 1 and age_days >= 5 then true
           when quotes  = 0 and invited = 0 and age_days >= 1 then true
           when quotes  = 0 and age_days >= 3 then true
           else false end;

  return jsonb_build_object(
    'recommend', v_recommend,
    'market',    v_market,
    'chase',     v_chase,
    'min_price_n', MIN_PRICE_N,
    'as_of', now()
  );
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_document_refs()
 RETURNS TABLE(ref_table text, ref_id text, source text, supplier_id bigint, supplier_name text, revealed boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with me as (
    select c.id
      from public.customers c
     where lower(c.email) = lower(nullif(auth.email(), ''))
        or c.id = auth.uid()
     order by (lower(c.email) = lower(nullif(auth.email(), ''))) desc nulls last
     limit 1
  )
  -- the customer's own uploads
  select 'inquiries'::text, i.id::text, 'inquiry'::text, null::bigint, null::text, true
    from public.inquiries i join me on i.customer_id = me.id
  union all
  -- quotation files sent against their RFQs. A draft quote is not shown to the customer by
  -- customer_api, so its attachment is not shown here either.
  select 'quotes'::text, q.id::text, 'quote'::text, q.supplier_id,
         case when t.id is not null then l.company_name end,
         t.id is not null
    from public.quotes q
    join public.inquiries i on i.id = q.inquiry_id
    join me on i.customer_id = me.id
    left join public.leads l on l.id = q.supplier_id
    left join public.transactions t
           on t.quote_id = q.id and t.customer_id = me.id and t.revealed_at is not null
   where coalesce(q.status, '') <> 'draft'
  union all
  -- supplier documents, and ONLY for a supplier this customer has paid to reveal
  select 'leads'::text, l.id::text, 'supplier'::text, l.id, l.company_name, true
    from public.leads l
   where exists (select 1 from public.transactions t join me on t.customer_id = me.id
                  where t.supplier_id = l.id and t.revealed_at is not null);
$function$


CREATE OR REPLACE FUNCTION public.fn_customer_documents(p_q text DEFAULT NULL::text, p_kind text DEFAULT NULL::text, p_lim integer DEFAULT 50, p_related_refs text[] DEFAULT NULL::text[])
 RETURNS TABLE(id bigint, kind text, file_name text, bucket text, path text, mime text, status text, created_at timestamp with time zone, source text, ref_table text, ref_id text, supplier text, supplier_revealed boolean, expiry_date date, expiry_source text, covers text, covers_source text, summary text, specifications text[], certifications text[], brands text[], extracted_at timestamp with time zone, match_reason text, score real)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with q as (
    -- A QUESTION IS NOT A SEARCH STRING. plainto_tsquery ANDs every content word, so the spec's own
    -- example — "Find warranty documents for HVAC" — becomes find & warranti & document & hvac and
    -- matches nothing a human would call a warranty document. Measured on staging: 0 hits against a
    -- fixture whose filename is literally hvac-warranty-agreement.pdf. The lexemes are therefore
    -- OR-ed, and ts_rank does the discriminating — a document carrying two of the four terms
    -- outranks one carrying a single term, which is what "ask in natural language" has to mean.
    select nullif(btrim(coalesce(p_q, '')), '') as qtext,
           (select nullif(string_agg('''' || replace(l.lexeme, '''', '''''') || '''', ' | '), '')::tsquery
              from unnest(to_tsvector('english', coalesce(p_q, ''))) l) as tsq,
           coalesce(p_related_refs, '{}'::text[]) as rel
  ),
  base as (
    select d.id, d.kind, d.file_name, d.bucket, d.path, d.mime, d.status, d.created_at,
           d.processed_at, r.source, d.ref_table, d.ref_id,
           case when r.revealed then r.supplier_name end as supplier,
           coalesce(r.revealed, false) as supplier_revealed,
           l.license_expiry, l.insurance_expiry, l.iso_expiry, l.manufacturer_auth_expiry,
           l.license_activity, l.iso_certifications,
           case when jsonb_typeof(d.extracted) = 'object' then d.extracted else '{}'::jsonb end as ex
      from public.documents d
      join public.fn_customer_document_refs() r
        on r.ref_table = d.ref_table and r.ref_id = d.ref_id
      left join public.leads l on r.revealed and l.id = r.supplier_id
  ),
  arr as (
    select b.*,
           (select coalesce(array_agg(x), '{}'::text[]) from jsonb_array_elements_text(
              case when jsonb_typeof(b.ex->'specifications') = 'array' then b.ex->'specifications'
                   else '[]'::jsonb end) x) as specs,
           (select coalesce(array_agg(x), '{}'::text[]) from jsonb_array_elements_text(
              case when jsonb_typeof(b.ex->'certifications') = 'array' then b.ex->'certifications'
                   else '[]'::jsonb end) x) as certs,
           (select coalesce(array_agg(x), '{}'::text[]) from jsonb_array_elements_text(
              case when jsonb_typeof(b.ex->'brands') = 'array' then b.ex->'brands'
                   else '[]'::jsonb end) x) as brnds,
           (select coalesce(array_agg(x), '{}'::text[]) from jsonb_array_elements_text(
              case when jsonb_typeof(b.iso_certifications) = 'array' then b.iso_certifications
                   else '[]'::jsonb end) x) as iso_certs
      from base b
  ),
  shaped as (
    select a.id, a.kind, a.file_name, a.bucket, a.path, a.mime, a.status, a.created_at,
           a.source, a.ref_table, a.ref_id, a.supplier, a.supplier_revealed,
           -- EXPIRY: only from a field that means expiry.
           coalesce(
             case when a.ex->>'expiry_date' ~ '^\d{4}-\d{2}-\d{2}$' then (a.ex->>'expiry_date')::date end,
             case when a.ex->>'valid_until' ~ '^\d{4}-\d{2}-\d{2}$' then (a.ex->>'valid_until')::date end,
             case when a.kind in ('licence', 'license') then a.license_expiry end,
             case when a.kind = 'insurance' then a.insurance_expiry end,
             case when a.kind in ('iso', 'certificate') then a.iso_expiry end,
             case when a.kind = 'manufacturer' then a.manufacturer_auth_expiry end
           ) as expiry_date,
           case
             when a.ex->>'expiry_date' ~ '^\d{4}-\d{2}-\d{2}$' then 'extracted.expiry_date'
             when a.ex->>'valid_until' ~ '^\d{4}-\d{2}-\d{2}$' then 'extracted.valid_until'
             when a.kind in ('licence', 'license') and a.license_expiry is not null then 'leads.license_expiry'
             when a.kind = 'insurance' and a.insurance_expiry is not null then 'leads.insurance_expiry'
             when a.kind in ('iso', 'certificate') and a.iso_expiry is not null then 'leads.iso_expiry'
             when a.kind = 'manufacturer' and a.manufacturer_auth_expiry is not null then 'leads.manufacturer_auth_expiry'
           end as expiry_source,
           -- COVERAGE: what the document covers, from the extractor's own key first.
           coalesce(
             nullif(btrim(coalesce(a.ex->>'covers', '')), ''),
             nullif(btrim(coalesce(a.ex->>'coverage', '')), ''),
             case when a.kind in ('licence', 'license') then nullif(btrim(coalesce(a.license_activity, '')), '') end,
             case when a.kind in ('iso', 'certificate') then nullif(array_to_string(a.iso_certs, ', '), '') end,
             nullif(array_to_string(a.certs, ', '), '')
           ) as covers,
           case
             when nullif(btrim(coalesce(a.ex->>'covers', '')), '') is not null then 'extracted.covers'
             when nullif(btrim(coalesce(a.ex->>'coverage', '')), '') is not null then 'extracted.coverage'
             when a.kind in ('licence', 'license')
              and nullif(btrim(coalesce(a.license_activity, '')), '') is not null then 'leads.license_activity'
             when a.kind in ('iso', 'certificate')
              and nullif(array_to_string(a.iso_certs, ', '), '') is not null then 'leads.iso_certifications'
             when nullif(array_to_string(a.certs, ', '), '') is not null then 'extracted.certifications'
           end as covers_source,
           left(nullif(btrim(coalesce(a.ex->>'text', '')), ''), 600) as summary,
           a.specs, a.certs, a.brnds, a.processed_at,
           -- THE HAYSTACK IS THE WHOLE EXTRACTION. jsonb_to_tsvector with a ["string"] filter walks
           -- every string value in the jsonb, so doc_extract's text/specifications/certifications/
           -- brands AND license_extract's issuer/covers/reference are all searchable without this
           -- function having to know which extractor wrote the row. A hand-picked key list is how
           -- `covers: "Full system"` ended up unsearchable in the first version.
           -- The filename is de-punctuated first: the parser lexes hvac-warranty-agreement.pdf as a
           -- single `file` token, so "warranty" did not match the file actually called that.
           to_tsvector('english',
             regexp_replace(coalesce(a.file_name, ''), '[^a-zA-Z0-9]+', ' ', 'g') || ' ' ||
             coalesce(a.kind, '') || ' ' || coalesce(a.supplier, '') || ' ' ||
             coalesce(a.license_activity, ''))
           || jsonb_to_tsvector('english', a.ex, '["string"]') as hay
      from arr a
  ),
  ranked as (
    -- match_reason and the rank are computed here, and the final select orders by THIS alias.
    -- RETURNS TABLE makes `score` and `created_at` OUT parameters, and an unqualified ORDER BY
    -- against a name that is also a parameter is how a SQL function starts erroring at call time.
    select s.*,
           case when q.qtext is null then 'all'
                when s.hay @@ q.tsq then 'text'
                else 'related_request' end as mreason,
           case when q.qtext is null then 0::real else ts_rank(s.hay, q.tsq) end as rank_score
      from shaped s, q
     where (p_kind is null or s.kind = lower(btrim(p_kind)))
       and (q.qtext is null
            or s.hay @@ q.tsq
            or (s.ref_table || ':' || s.ref_id) = any (q.rel))
  )
  select z.id, z.kind, z.file_name, z.bucket, z.path, z.mime, z.status, z.created_at,
         z.source, z.ref_table, z.ref_id, z.supplier, z.supplier_revealed,
         z.expiry_date, z.expiry_source, z.covers, z.covers_source,
         z.summary, z.specs, z.certs, z.brnds, z.processed_at, z.mreason, z.rank_score
    from ranked z
   order by z.rank_score desc, z.created_at desc nulls last
   limit greatest(1, coalesce(p_lim, 50));
$function$


CREATE OR REPLACE FUNCTION public.fn_customer_forecast(p_customer uuid, p_horizon_days integer DEFAULT 365)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_rfqs int; v_months int; v_first timestamptz; v_last timestamptz;
  v_spend numeric; v_span_days numeric;
  v_series jsonb; v_by_cat jsonb; v_predictions jsonb;
  v_sufficient boolean; v_reason text;
  v_proj_rfqs numeric; v_proj_spend numeric;
begin
  select count(*), min(i.created_at), max(i.created_at),
         count(distinct date_trunc('month', i.created_at))
    into v_rfqs, v_first, v_last, v_months
    from inquiries i
   where i.customer_id = p_customer and i.parent_inquiry_id is null;

  select coalesce(sum(coalesce(t.quote_amount, 0)), 0) into v_spend
    from transactions t
   where t.customer_id = p_customer and coalesce(t.refund_status, '') <> 'approved';

  -- No history at all. Say so; do not project.
  if coalesce(v_rfqs, 0) = 0 then
    return jsonb_build_object(
      'customer_id', p_customer, 'as_of', now(), 'horizon_days', p_horizon_days,
      'basis', 'no_history', 'sufficient_data', false,
      'empty_reason', 'No requests recorded on this account yet. This forecast is derived from your own past RFQs and orders, so there is nothing to project from until you post your first request.',
      'observed', jsonb_build_object('rfqs', 0, 'months_active', 0, 'spend_aed', 0,
                                     'first_rfq', null, 'last_rfq', null),
      'series', '[]'::jsonb,
      'next_year', jsonb_build_object('horizon_days', p_horizon_days, 'projected_rfqs', null,
                                      'projected_spend_aed', null, 'by_category', '[]'::jsonb),
      'predictions', '[]'::jsonb);
  end if;

  -- The observed window only. The series starts at the customer's FIRST request, never at a padded
  -- twelve months back, so a three-month-old account shows three points and not nine empty ones.
  with months as (
    select generate_series(date_trunc('month', v_first), date_trunc('month', now()), interval '1 month') m
  ), actual as (
    select date_trunc('month', i.created_at) m, count(*) c,
           round(coalesce(sum(i.expected_value), 0), 0) v
      from inquiries i
     where i.customer_id = p_customer and i.parent_inquiry_id is null
     group by 1
  )
  select jsonb_agg(jsonb_build_object('month', to_char(months.m, 'Mon YY'),
                                      'rfqs', coalesce(actual.c, 0),
                                      'value_aed', coalesce(actual.v, 0)) order by months.m)
    into v_series
    from months left join actual on actual.m = months.m;

  -- Two months of activity and three requests is the floor for a run-rate projection. Below it the
  -- figures are null and the reason is printed rather than a straight line drawn through one point.
  v_span_days  := greatest(30, extract(epoch from (now() - v_first)) / 86400.0);
  v_sufficient := v_rfqs >= 3 and v_months >= 2;
  if v_sufficient then
    v_proj_rfqs  := round((v_rfqs::numeric / v_span_days) * p_horizon_days, 1);
    v_proj_spend := round((coalesce(v_spend, 0) / v_span_days) * p_horizon_days, 0);
    v_reason     := null;
  else
    v_proj_rfqs  := null;
    v_proj_spend := null;
    v_reason     := format('Only %s request(s) across %s active month(s) so far. A run-rate projection needs at least 3 requests spanning 2 months, so the next-year figures are withheld rather than extrapolated from a single point.',
                           v_rfqs, v_months);
  end if;

  -- Category mix, projected forward at the same run rate. Shares come from the customer's own
  -- requests, so a customer who only ever bought joinery is not shown an HVAC line.
  with cat as (
    select coalesce(i.category, 'uncategorised') c, count(*) n,
           round(coalesce(sum(i.expected_value), 0), 0) v
      from inquiries i
     where i.customer_id = p_customer and i.parent_inquiry_id is null
     group by 1
  )
  select jsonb_agg(jsonb_build_object(
           'category', c,
           'observed_rfqs', n,
           'observed_value_aed', v,
           'share_pct', round(100.0 * n / nullif(v_rfqs, 0), 1),
           'projected_rfqs', case when v_sufficient
                                  then round(v_proj_rfqs * n / nullif(v_rfqs, 0), 1) end,
           'projected_spend_aed', case when v_sufficient
                                  then round(v_proj_spend * n / nullif(v_rfqs, 0), 0) end
         ) order by n desc, c)
    into v_by_cat from cat;

  -- ── §20: what this customer will likely need next, and by when ────────────────────────────────
  -- Derived, never guessed: for each of the customer's OPEN projects that has a target open date,
  -- the categories they have procured on their other projects and have not yet raised here. The
  -- horizon is that project's own deadline minus the lead time this customer has actually observed
  -- in that category (median days between raising a request and the project's target open date).
  with own as (
    select i.project_id, coalesce(i.category, 'uncategorised') c, i.created_at, p.target_open_date
      from inquiries i join projects p on p.id = i.project_id
     where i.customer_id = p_customer and i.project_id is not null
  ), lead_time as (
    select c, percentile_cont(0.5) within group (
             order by (target_open_date - created_at::date)) med_days
      from own where target_open_date is not null
     group by c
  ), history as (
    select c, count(distinct project_id) projects_used, max(created_at) last_used
      from own group by c
  ), open_projects as (
    select p.id, p.name, p.target_open_date
      from projects p
     where p.customer_id = p_customer
       and coalesce(p.status, 'active') not in ('completed', 'archived', 'cancelled')
       and p.target_open_date is not null
  ), gaps as (
    select op.id project_id, op.name project_name, op.target_open_date, h.c category,
           h.projects_used, lt.med_days,
           greatest(0, (op.target_open_date - current_date)
                       - coalesce(round(lt.med_days)::int, 0)) within_days
      from open_projects op
      cross join history h
      left join lead_time lt on lt.c = h.c
     where not exists (select 1 from inquiries i2
                        where i2.project_id = op.id
                          and coalesce(i2.category, 'uncategorised') = h.c)
  )
  select jsonb_agg(jsonb_build_object(
           'project_id', project_id,
           'project_name', project_name,
           'category', category,
           'target_open_date', target_open_date,
           'within_days', within_days,
           'expected_by', current_date + within_days,
           'confidence', case when projects_used >= 2 and med_days is not null then 'high'
                              when projects_used >= 1 and med_days is not null then 'medium'
                              else 'low' end,
           'reason', format('You have procured %s on %s of your other project(s)%s, and %s has no %s request yet.',
                            category, projects_used,
                            case when med_days is null then ''
                                 else format(', typically %s days before the target open date', round(med_days)) end,
                            project_name, category),
           'recommended_action', case
             when within_days = 0 then format('Post the %s RFQ now — the lead time you have historically needed has already started.', category)
             else format('Contact suppliers and post the %s RFQ within %s day(s) to keep %s on its target open date of %s.',
                         category, within_days, project_name, target_open_date) end
         ) order by within_days, category)
    into v_predictions from gaps;

  return jsonb_build_object(
    'customer_id', p_customer, 'as_of', now(), 'horizon_days', p_horizon_days,
    'basis', 'history', 'sufficient_data', v_sufficient, 'empty_reason', v_reason,
    'observed', jsonb_build_object('rfqs', v_rfqs, 'months_active', v_months,
                                   'spend_aed', round(coalesce(v_spend, 0), 0),
                                   'first_rfq', v_first, 'last_rfq', v_last),
    'series', coalesce(v_series, '[]'::jsonb),
    'next_year', jsonb_build_object('horizon_days', p_horizon_days,
                                    'projected_rfqs', v_proj_rfqs,
                                    'projected_spend_aed', v_proj_spend,
                                    'by_category', coalesce(v_by_cat, '[]'::jsonb)),
    'predictions', coalesce(v_predictions, '[]'::jsonb));
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_orders(p_customer uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', o.id, 'po_no', o.po_no, 'status', o.status,
      'order_date', o.order_date, 'expected_date', o.expected_date,
      'currency', o.currency, 'subtotal', o.subtotal, 'memo', o.memo,
      'inquiry_id', o.inquiry_id, 'quote_id', o.quote_id, 'project_id', o.project_id,
      'approved_at', o.approved_at,
      'lines', coalesce((select jsonb_agg(jsonb_build_object(
                  'line_no', l.line_no, 'description', l.description, 'qty', l.qty,
                  'unit_price', l.unit_price, 'qty_received', l.qty_received) order by l.line_no)
                from public.po_lines l where l.po_id = o.id), '[]'::jsonb))
      order by o.order_date desc, o.id desc), '[]'::jsonb)
    from public.po_orders o
   where o.customer_id = p_customer;
$function$


CREATE OR REPLACE FUNCTION public.fn_customer_preference_learn(p_customer_id uuid, p_stated jsonb DEFAULT '{}'::jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_consent timestamptz;
  v_existing jsonb;
  v_inferred jsonb;
begin
  if p_customer_id is null then return 0; end if;

  -- CONSENT IS THE GATE, and it reuses the consent the customer already gave. No new column, no
  -- new UI, no second consent vocabulary.
  --
  -- WITHDRAWAL DELETES. The fixture caught this: clearing customer_preference.consented_at is not
  -- withdrawing consent, because consent lives on customers.tos_accepted_at and the next inquiry
  -- simply re-learned and restored the copy. So the absence of consent actively REMOVES the
  -- profile rather than merely declining to refresh it — row absent is indistinguishable from
  -- never consented, which is the property the readers rely on.
  select c.tos_accepted_at into v_consent from customers c where c.id = p_customer_id;
  if v_consent is null then
    delete from customer_preference where customer_id = p_customer_id;
    return 0;
  end if;

  select p.preferences into v_existing from customer_preference p where p.customer_id = p_customer_id;

  -- The same aggregates fn_ws_customer_360 computes live today, persisted instead of recomputed.
  select jsonb_build_object(
           'categories', coalesce(jsonb_agg(distinct i.category) filter (where i.category is not null), '[]'::jsonb),
           'emirates',   coalesce(jsonb_agg(distinct i.emirate)  filter (where i.emirate  is not null), '[]'::jsonb),
           'scope_type', mode() within group (order by i.scope_type),
           'budget_aed_avg', round(avg(nullif(i.expected_value, 0))::numeric, 2),
           'rfqs_seen', count(*))
    into v_inferred
    from inquiries i where i.customer_id = p_customer_id;

  insert into customer_preference (customer_id, preferences, consented_at, updated_at)
  values (p_customer_id,
          jsonb_build_object(
            -- stated is merged, never replaced: an inference must not clear a typed choice.
            'stated',   coalesce(v_existing->'stated', '{}'::jsonb) || coalesce(p_stated, '{}'::jsonb),
            'inferred', coalesce(v_inferred, '{}'::jsonb),
            'source',   'fn_customer_preference_learn'),
          v_consent, now())
  on conflict (customer_id) do update
    set preferences = excluded.preferences,
        consented_at = excluded.consented_at,
        updated_at   = now();
  return 1;
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_savings(p_customer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_min_sample int;
  v_rows int;
  v_by_cat jsonb;
  v_spread numeric; v_bench numeric;
begin
  select coalesce((p.policy ->> 'min_sample')::int, 4) into v_min_sample
    from supplier_negotiation_policy p where p.scope = 'default';
  v_min_sample := coalesce(v_min_sample, 4);

  select count(*) into v_rows
    from quotes q join inquiries i on i.id = q.inquiry_id
   where i.customer_id = p_customer and coalesce(q.status, '') <> 'draft'
     and q.quote_amount is not null and q.quote_amount > 0;

  if v_rows = 0 then
    return jsonb_build_object(
      'customer_id', p_customer, 'as_of', now(), 'min_sample', v_min_sample,
      'by_category', '[]'::jsonb,
      'total_spread_saving_aed', null, 'total_benchmark_saving_aed', null,
      'quotes_considered', 0,
      'empty_reason', 'No quotes on your requests yet. Potential savings are measured from the quotes you actually hold — the spread between them, and each one against the market median for its category — so there is nothing to compute until suppliers respond.');
  end if;

  with live as (
    select q.id, q.inquiry_id, q.quote_amount, coalesce(i.category, 'uncategorised') category
      from quotes q join inquiries i on i.id = q.inquiry_id
     where i.customer_id = p_customer and coalesce(q.status, '') <> 'draft'
       and q.quote_amount is not null and q.quote_amount > 0
       and coalesce(i.status, '') not in ('completed', 'cancelled', 'closed')
  ), per_rfq as (
    select inquiry_id, category, count(*) n_quotes,
           max(quote_amount) - min(quote_amount) spread, min(quote_amount) cheapest
      from live group by inquiry_id, category
  ), bench as (
    select l.category, l.inquiry_id, min(l.quote_amount) cheapest, s.median, s.n
      from live l left join category_price_stats s on s.category = l.category
     group by l.category, l.inquiry_id, s.median, s.n
  )
  select jsonb_agg(x order by x ->> 'category'), sum((x ->> 'spread_saving_aed')::numeric),
         sum(coalesce((x ->> 'benchmark_saving_aed')::numeric, 0))
    into v_by_cat, v_spread, v_bench
    from (
      select jsonb_build_object(
               'category', p.category,
               'rfqs', count(distinct p.inquiry_id),
               'quotes', sum(p.n_quotes),
               'spread_saving_aed', round(sum(case when p.n_quotes >= 2 then p.spread else 0 end), 0),
               'market_median', max(b.median),
               'market_sample_n', max(b.n),
               'benchmark_saving_aed', case when max(b.n) >= v_min_sample
                 then round(greatest(0, sum(b.cheapest) - sum(b.median)), 0) end,
               'benchmark_basis', case when coalesce(max(b.n), 0) >= v_min_sample
                 then format('cheapest quote(s) held against a market median over %s comparable quote(s)', max(b.n))
                 else format('no market benchmark: only %s comparable quote(s) recorded in this category, and %s are needed',
                             coalesce(max(b.n), 0), v_min_sample) end
             ) x
        from per_rfq p join bench b on b.inquiry_id = p.inquiry_id and b.category = p.category
       group by p.category
    ) z;

  return jsonb_build_object(
    'customer_id', p_customer, 'as_of', now(), 'min_sample', v_min_sample,
    'by_category', coalesce(v_by_cat, '[]'::jsonb),
    'total_spread_saving_aed', v_spread,
    'total_benchmark_saving_aed', case when v_bench > 0 then v_bench end,
    'quotes_considered', v_rows,
    'empty_reason', case when coalesce(v_bench, 0) = 0
      then format('No market benchmark saving is shown: no category on your open requests yet has the %s comparable quotes this house policy requires before it will quote a market median.', v_min_sample) end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_stats(p_customer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb; v_inq int; v_open int; v_quotes int; v_deals int; v_spend numeric; v_list jsonb; v_hist jsonb;
begin
  select count(*) into v_inq from inquiries where customer_id=p_customer and parent_inquiry_id is null;
  select count(*) into v_open from inquiries where customer_id=p_customer and parent_inquiry_id is null and coalesce(status,'') not in ('completed','closed','cancelled','split');
  select count(*) into v_quotes from quotes q where q.status <> 'draft' and q.inquiry_id in (select id from inquiries where customer_id=p_customer);
  select count(*) into v_deals from transactions where customer_id=p_customer;
  select coalesce(sum(coalesce(reveal_fee,0)+coalesce(app_fee,0)),0) into v_spend from transactions where customer_id=p_customer and coalesce(refund_status,'')<>'approved';
  select jsonb_agg(x order by (x->>'created_at') desc) into v_list from (
    select jsonb_build_object(
      'id', i.id, 'category', i.category, 'emirate', i.emirate, 'status', i.status,
      'created_at', i.created_at, 'pipeline_stage', i.pipeline_stage, 'outcome', i.outcome,
      'has_drawing', (i.drawing_file_path is not null), 'boq_confidence', i.boq_confidence,
      'quotes_count', (select count(*) from quotes q where q.inquiry_id=i.id and q.status <> 'draft'),
      'minutes_since', round(extract(epoch from (now()-i.created_at))/60.0)::int,
      'editable', (i.status='sent') and (now()-i.created_at) < interval '60 minutes',
      'edit_minutes_left', greatest(0, 60 - round(extract(epoch from (now()-i.created_at))/60.0)::int)
    ) x from inquiries i where i.customer_id=p_customer and i.parent_inquiry_id is null
  ) t;
  with months as (select date_trunc('month',(now()-(n||' month')::interval)) m from generate_series(0,11) n),
  ib as (select date_trunc('month',created_at) m, count(*) c from inquiries where customer_id=p_customer and parent_inquiry_id is null group by 1)
  select jsonb_agg(jsonb_build_object('month',to_char(months.m,'Mon YY'),'inquiries',coalesce(ib.c,0)) order by months.m)
    into v_hist from months left join ib on ib.m=months.m;
  v := jsonb_build_object(
    'customer_id', p_customer,'inquiries_total', v_inq,'open_inquiries', v_open,
    'quotes_received', v_quotes,'avg_quotes_per_inquiry', round(v_quotes::numeric/nullif(v_inq,0),1),
    'deals', v_deals,'total_spend', v_spend,
    'inquiries', coalesce(v_list,'[]'::jsonb),'history_12m', v_hist);
  return v;
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_success()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_kpis jsonb; n_checkin int:=0; n_reengage int:=0; n_esc int:=0; rec record; v_subject text; v_body text;
begin
  -- snapshot KPIs
  select to_jsonb(k) into v_kpis from public.customer_kpis k;
  insert into public.customer_kpi_snapshots(snapshot_date,kpis) values(current_date,coalesce(v_kpis,'{}'::jsonb))
    on conflict (snapshot_date) do update set kpis=excluded.kpis, created_at=now();

  -- FOLLOW-UP (operational, auto-send): project check-in — revealed but not completed for 7+ days
  for rec in
    select i.id as inquiry_id, i.customer_id, c.full_name, c.email, i.category
    from inquiries i join customers c on c.id=i.customer_id
    where i.status='revealed' and i.completed_at is null
      and coalesce(i.stage_changed_at,i.created_at) < now()-interval '7 days'
      and coalesce(c.banned,false)=false and c.email like '%@%'
      and not exists (select 1 from notifications n where n.type='customer_checkin' and n.body like '%'||i.id::text||'%' and n.created_at>now()-interval '21 days')
    limit 200
  loop
    v_subject:='How is your '||coalesce(rec.category,'project')||' going?';
    v_body:='Hi '||coalesce(rec.full_name,'there')||E',\n\nWe wanted to check in on your '||coalesce(rec.category,'project')||' booked through QuotesDone. Is everything going well with your supplier?\n\nIf you need anything — a hand resolving an issue, another quote, or help with your next project — just reply to this email. We are here to help.\n\n(ref '||rec.inquiry_id||')';
    insert into notifications(type,to_email,to_role,channel,subject,body,status)
    values('customer_checkin',rec.email,'customer','email',v_subject,v_body,'queued');
    n_checkin:=n_checkin+1;
  end loop;

  -- FOLLOW-UP (operational, auto-send): re-engagement — last project 30+ days ago, no new inquiry since
  for rec in
    select c.id as customer_id, c.full_name, c.email
    from customers c
    where coalesce(c.banned,false)=false and c.email like '%@%'
      and exists (select 1 from inquiries i where i.customer_id=c.id and (i.status='revealed' or i.completed_at is not null))
      and (select max(created_at) from inquiries i where i.customer_id=c.id) < now()-interval '30 days'
      and not exists (select 1 from notifications n where n.type='customer_reengage' and n.to_email=c.email and n.created_at>now()-interval '45 days')
    limit 200
  loop
    v_subject:='Planning your next project?';
    v_body:='Hi '||coalesce(rec.full_name,'there')||E',\n\nIt has been a little while since your last project on QuotesDone. Whenever you are planning your next one — big or small — post it in a minute and compare anonymous quotes from vetted UAE suppliers.\n\nStart here: https://quotesdone.com/app\n\nHappy to help anytime.';
    insert into notifications(type,to_email,to_role,channel,subject,body,status)
    values('customer_reengage',rec.email,'customer','email',v_subject,v_body,'queued');
    n_reengage:=n_reengage+1;
  end loop;

  -- ESCALATIONS to founder (never auto-resolve): disputes/refunds, reveal non-response, bad reviews, complaints
  for rec in
    select 'dispute' as sig, t.customer_id as cid, coalesce(c.full_name,'customer') as who, t.id::text as ref,
      'Refund/dispute open — review and resolve.' as msg, 'high' as risk
    from transactions t join customers c on c.id=t.customer_id
    where (t.refund_status is not null or (t.refund_requested_at is not null and t.refund_resolved_at is null))
    union all
    select 'reveal_no_response', t.customer_id, coalesce(c.full_name,'customer'), t.id::text,
      'Customer paid to reveal but supplier has not acknowledged within 48h — service risk.', 'high'
    from transactions t join customers c on c.id=t.customer_id
    where t.supplier_ack_at is null and t.revealed_at is not null and t.revealed_at < now()-interval '48 hours' and t.refund_status is null
    union all
    select 'bad_review', r.customer_id, coalesce(c.full_name,'customer'), r.id::text,
      'Low review left ('||r.rating||'/5) — follow up on dissatisfaction.', 'medium'
    from reviews r join customers c on c.id=r.customer_id where r.rating<=2
    union all
    select 'complaint', c.id, coalesce(c.full_name,'customer'), im.id::text,
      'Inbound complaint from customer — needs attention.', 'high'
    from inbound_messages im join customers c on lower(c.email)=lower(im.from_email)
    where im.ai_category ilike '%complaint%' and im.replied_at is null
  loop
    if not exists (select 1 from agent_actions a where a.kind='customer_escalation' and a.detail->>'signal'=rec.sig and a.detail->>'ref'=rec.ref and a.status in ('pending','needs_review')) then
      insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id)
      values('customer_success','customer_escalation','pending',rec.risk,
        public.fn_ui_label('customer_signal', rec.sig)||': '||rec.who, rec.msg,
        jsonb_build_object('signal',rec.sig,'ref',rec.ref,'customer',rec.who),
        'customers', rec.cid::text);
      n_esc:=n_esc+1;
    end if;
  end loop;

  return jsonb_build_object('ran_at',now(),'kpis',v_kpis,'checkins_queued',n_checkin,'reengage_queued',n_reengage,'escalations',n_esc);
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_supplier_score(p_customer uuid, p_supplier bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_sent int; v_quoted int; v_awarded int; v_reveals int; v_acked int; v_refunds int;
  v_avg_quote numeric; v_resp_hours numeric; v_last timestamptz;
  v_rating numeric; v_dims jsonb; v_reviews int;
  v_responsiveness numeric; v_award_rate numeric; v_delivery numeric;
  v_quality numeric; v_refund_free numeric;
  v_parts jsonb := '[]'::jsonb; v_sum numeric := 0; v_wt numeric := 0;
  v_global jsonb; v_supplier text;
  -- each component contributes only when the customer's history actually carries it, so a single
  -- review does not become the whole verdict and a missing dimension does not read as a zero
  v_method text := 'weighted mean over the components with data';
begin
  select l.company_name into v_supplier from leads l where l.id = p_supplier;
  if v_supplier is null then
    return jsonb_build_object('error', 'unknown_supplier', 'supplier_id', p_supplier);
  end if;

  select count(*) into v_sent
    from inquiry_matches m join inquiries i on i.id = m.inquiry_id
   where m.supplier_id = p_supplier and i.customer_id = p_customer;

  select count(*), round(avg(q.quote_amount), 0),
         round(avg(extract(epoch from (q.created_at - i.created_at)) / 3600.0)::numeric, 1),
         max(q.created_at)
    into v_quoted, v_avg_quote, v_resp_hours, v_last
    from quotes q join inquiries i on i.id = q.inquiry_id
   where q.supplier_id = p_supplier and i.customer_id = p_customer
     and coalesce(q.status, '') <> 'draft';

  select count(*) into v_awarded
    from inquiries i
   where i.customer_id = p_customer and i.hired_supplier_id = p_supplier;

  select count(*),
         count(*) filter (where t.supplier_ack_at is not null),
         count(*) filter (where coalesce(t.refund_status, '') = 'approved')
    into v_reveals, v_acked, v_refunds
    from transactions t
   where t.customer_id = p_customer and t.supplier_id = p_supplier;

  select count(*), round(avg(r.rating)::numeric, 2),
         jsonb_build_object(
           'communication', round(avg(r.r_communication)::numeric, 2),
           'quality', round(avg(r.r_quality)::numeric, 2),
           'punctuality', round(avg(r.r_punctuality)::numeric, 2),
           'documentation', round(avg(r.r_documentation)::numeric, 2),
           'after_sales', round(avg(r.r_after_sales)::numeric, 2),
           'compliance', round(avg(r.r_compliance)::numeric, 2))
    into v_reviews, v_rating, v_dims
    from reviews r
   where r.customer_id = p_customer and r.supplier_id = p_supplier;

  select jsonb_build_object('reliability', s.reliability, 'quality_rating', s.quality_rating,
                            'price_index', s.price_index, 'response_rate', s.response_rate,
                            'avg_response_hours', s.avg_response_hours,
                            'quotes_submitted', s.quotes_submitted, 'quotes_won', s.quotes_won,
                            'computed_at', s.computed_at)
    into v_global from supplier_score s where s.lead_id = p_supplier;

  -- Nothing shared: report the global figures and refuse to invent a relationship.
  if coalesce(v_sent, 0) = 0 and coalesce(v_quoted, 0) = 0 and coalesce(v_reveals, 0) = 0
     and coalesce(v_reviews, 0) = 0 then
    return jsonb_build_object(
      'customer_id', p_customer, 'supplier_id', p_supplier, 'supplier_name', v_supplier,
      'basis', 'no_shared_history', 'relationship_score', null,
      'empty_reason', format('You have not worked with %s yet. A relationship score is built from your own RFQs, quotes, orders and reviews with a supplier, so there is nothing to score until the first one.', v_supplier),
      'history', jsonb_build_object('rfqs_sent', 0, 'quotes_received', 0, 'orders', 0,
                                    'reveals', 0, 'reviews', 0),
      'delivery_pct', null, 'quality_pct', null, 'win_rate_pct', null,
      'avg_response_hours', null, 'avg_quote_aed', null, 'last_interaction_at', null,
      'your_rating', null, 'your_rating_dimensions', null,
      'components', '[]'::jsonb,
      'platform_wide', coalesce(v_global, 'null'::jsonb));
  end if;

  if v_sent > 0 then
    v_responsiveness := round(least(100, 100.0 * v_quoted / v_sent), 1);
    v_parts := v_parts || jsonb_build_object('name', 'responsiveness', 'value', v_responsiveness,
      'weight', 30, 'basis', format('%s of %s RFQs you sent came back with a quote', v_quoted, v_sent));
    v_sum := v_sum + v_responsiveness * 30; v_wt := v_wt + 30;
  end if;

  if v_quoted > 0 then
    v_award_rate := round(100.0 * v_awarded / v_quoted, 1);
    v_parts := v_parts || jsonb_build_object('name', 'award_rate', 'value', v_award_rate,
      'weight', 15, 'basis', format('you awarded %s of their %s quote(s)', v_awarded, v_quoted));
    v_sum := v_sum + v_award_rate * 15; v_wt := v_wt + 15;
  end if;

  if v_reveals > 0 then
    v_delivery      := round(100.0 * v_acked / v_reveals, 1);
    v_refund_free   := round(100.0 * (v_reveals - v_refunds) / v_reveals, 1);
    v_parts := v_parts || jsonb_build_object('name', 'delivery', 'value', v_delivery,
      'weight', 30, 'basis', format('%s of %s reveal(s) were acknowledged by the supplier', v_acked, v_reveals));
    v_parts := v_parts || jsonb_build_object('name', 'no_refund', 'value', v_refund_free,
      'weight', 10, 'basis', format('%s of %s reveal(s) ended in a refund', v_refunds, v_reveals));
    v_sum := v_sum + v_delivery * 30 + v_refund_free * 10; v_wt := v_wt + 40;
  end if;

  if v_reviews > 0 and v_rating is not null then
    v_quality := round(100.0 * v_rating / 5.0, 1);
    v_parts := v_parts || jsonb_build_object('name', 'your_rating', 'value', v_quality,
      'weight', 25, 'basis', format('your %s review(s) average %s out of 5', v_reviews, v_rating));
    v_sum := v_sum + v_quality * 25; v_wt := v_wt + 25;
  end if;

  return jsonb_build_object(
    'customer_id', p_customer, 'supplier_id', p_supplier, 'supplier_name', v_supplier,
    'basis', 'shared_history', 'empty_reason', null,
    'relationship_score', case when v_wt > 0 then round(v_sum / v_wt, 0)::int end,
    'score_method', v_method,
    'history', jsonb_build_object('rfqs_sent', v_sent, 'quotes_received', v_quoted,
                                  'orders', v_awarded, 'reveals', v_reveals, 'reviews', v_reviews),
    'delivery_pct', v_delivery,
    'quality_pct', v_quality,
    'win_rate_pct', v_award_rate,
    'avg_response_hours', v_resp_hours,
    'avg_quote_aed', v_avg_quote,
    'last_interaction_at', v_last,
    'your_rating', v_rating,
    'your_rating_dimensions', case when v_reviews > 0 then v_dims end,
    'components', v_parts,
    'platform_wide', coalesce(v_global, 'null'::jsonb));
end $function$


CREATE OR REPLACE FUNCTION public.fn_customers_board(p_search text DEFAULT ''::text, p_limit integer DEFAULT 80, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare out jsonb;
begin
  with base as (
    select c.id::text as id, coalesce(nullif(trim(c.full_name),''),'(unnamed)') as full_name, c.email, c.phone,
      coalesce(c.email_verified,false) as email_verified, coalesce(c.phone_verified,false) as phone_verified, c.banned, c.created_at,
      case when c.banned then 'banned' when coalesce(c.email_verified,false) or coalesce(c.phone_verified,false) then 'verified' else 'new' end as stage
    from customers c
    where coalesce(p_search,'')='' or c.full_name ilike '%'||p_search||'%' or c.email ilike '%'||p_search||'%' or c.phone ilike '%'||p_search||'%'
  ), ranked as (select *, row_number() over (partition by stage order by created_at desc) rn from base),
  sc as (select stage, count(*) c from base group by stage)
  select jsonb_build_object(
    'total',(select count(*) from base),
    'stages',(select jsonb_agg(jsonb_build_object('key',s.key,'label',s.label,'count',coalesce((select c from sc where sc.stage=s.key),0),
      'cards',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'full_name',r.full_name,'email',r.email,'phone',r.phone,'email_verified',r.email_verified,'banned',r.banned) order by r.rn) from ranked r where r.stage=s.key and r.rn<=12),'[]'::jsonb))
      order by s.ord)
      from (values ('new','New',1),('verified','Verified',2),('banned','Banned',3)) s(key,label,ord)),
    'rows',(select coalesce(jsonb_agg(jsonb_build_object('id',b.id,'full_name',b.full_name,'email',b.email,'phone',b.phone,'email_verified',b.email_verified,'phone_verified',b.phone_verified,'banned',b.banned,'stage',b.stage,'created_at',b.created_at) order by b.created_at desc),'[]'::jsonb)
             from (select * from base order by created_at desc limit greatest(1,least(p_limit,200)) offset greatest(0,p_offset)) b)
  ) into out; return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_data_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare res jsonb;
begin
  select jsonb_build_object(
    'category_growth', (select coalesce(fn_marketplace_analytics()->'category_growth','[]'::jsonb)),
    'competitive_categories', (select coalesce(fn_marketplace_analytics()->'competitive_categories','[]'::jsonb)),
    'price_spread', (select coalesce(jsonb_agg(jsonb_build_object('category',category,'n',n,'median',median,'p25',p25,'p75',p75) order by n desc),'[]'::jsonb)
        from (select * from category_price_stats order by n desc limit 10) z),
    'monthly_volume', (select coalesce(jsonb_agg(jsonb_build_object('month',m,'rfqs',c) order by m),'[]'::jsonb)
        from (select to_char(date_trunc('month',created_at),'YYYY-MM') m, count(*) c from inquiries where created_at > now()-interval '6 months' group by 1) z)
  ) into res;
  return res;
end $function$


CREATE OR REPLACE FUNCTION public.fn_day_conductor()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d date := current_date; v_ok int := 0; v_bad int := 0;
begin
  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'ceo_reviews_company',1,'an exec or board report in the last 24h',
    jsonb_build_object('board_reports_24h',(select count(*) from board_reports where created_at>now()-interval '24 hours'),
                       'exec_reports_24h',(select count(*) from exec_reports where created_at>now()-interval '24 hours')),
    ((select count(*) from board_reports where created_at>now()-interval '24 hours')
   + (select count(*) from exec_reports where created_at>now()-interval '24 hours'))>0,
    'strategy_ai_daily / board_report_weekly / exec_meeting_weekly'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'cos_reviews_departments',2,'cos_execute_hourly fired and succeeded',
    jsonb_build_object('cron_ok',fn_cron_ran('cos_execute_hourly','3 hours'),
                       'runs_24h',(select count(*) from agent_runs where agent='chief_of_staff' and started_at>now()-interval '24 hours')),
    fn_cron_ran('cos_execute_hourly','3 hours'),'cos_execute_hourly'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'departments_plan',3,'dept_plan_daily fired and succeeded',
    jsonb_build_object('cron_ok',fn_cron_ran('dept_plan_daily')),
    fn_cron_ran('dept_plan_daily'),'dept_plan_daily (does not always write agent_runs)'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'tasks_execute',4,'agent runs happened',
    jsonb_build_object('runs_24h',(select count(*) from agent_runs where started_at>now()-interval '24 hours'),
                       'errors_24h',(select count(*) from agent_runs where started_at>now()-interval '24 hours' and status='error')),
    (select count(*) from agent_runs where started_at>now()-interval '24 hours')>0,'all scheduled workers'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'results_measured',5,'outcomes gradeable and KPIs measurable',
    jsonb_build_object('outcomes_pending',(select count(*) from outcome_record where verdict='pending'),
                       'kpis_measurable',(select count(*) from employee_kpi where active and measure_sql is not null)),
    (select count(*) from employee_kpi where active and measure_sql is not null)>0,'outcome_evaluate_daily / kpi_review_weekly'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'lessons_learned',6,'dept_learn_daily fired and succeeded',
    jsonb_build_object('cron_ok',fn_cron_ran('dept_learn_daily'),
                       'memory_rows',(select count(*) from institutional_memory)),
    fn_cron_ran('dept_learn_daily'),'dept_learn_daily (does not always write agent_runs)'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'knowledge_updated',7,'knowledge touched in the last 24h',
    jsonb_build_object('touched_24h',(select count(*) from agent_knowledge where updated_at>now()-interval '24 hours')),
    (select count(*) from agent_knowledge where updated_at>now()-interval '24 hours')>0,'kb_deepen / knowledge_curator_daily'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  insert into day_cadence (business_day, stage, stage_order, expected, observed, ok, note)
  select d,'tomorrow_planned',8,'open work exists',
    jsonb_build_object('open_tasks',(select count(*) from org_tasks where status<>'done')),
    (select count(*) from org_tasks where status<>'done')>0,'dept_plan_daily / kpi_review_weekly'
  on conflict (business_day,stage) do update set observed=excluded.observed, ok=excluded.ok, checked_at=now();

  select count(*) filter (where ok), count(*) filter (where not ok) into v_ok, v_bad
    from day_cadence where business_day=d;

  if v_bad>0 then
    insert into founder_alerts (level,event,detail,channel)
    select 'high','daily_cadence_broken',
      'The daily operating loop did not complete. Failed stages: '||
      (select string_agg(stage,', ' order by stage_order) from day_cadence where business_day=d and not ok),'email'
    where not exists (select 1 from founder_alerts where event='daily_cadence_broken' and created_at>now()-interval '20 hours');
  end if;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('day_conductor',now(),now(),case when v_bad>0 then 'error' else 'ok' end,
    jsonb_build_object('stages_ok',v_ok,'stages_failed',v_bad),
    'Daily operating rhythm: '||v_ok||' of '||(v_ok+v_bad)||' stages verified.');

  return jsonb_build_object('day',d,'ok',v_ok,'failed',v_bad);
end $function$


CREATE OR REPLACE FUNCTION public.fn_dbx_category(p_lead_id bigint)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select public.fn_dbx_safe(coalesce(
    -- 1. the supplier's primary catalog category (the real 86-item taxonomy)
    (select c.name from public.lead_category lc
       join public.catalog_supplier_categories c on c.slug = lc.slug
      where lc.lead_id = p_lead_id and lc.is_primary
      order by lc.score desc nulls last limit 1),
    -- 2. any catalog category we managed to map, best score first
    (select c.name from public.lead_category lc
       join public.catalog_supplier_categories c on c.slug = lc.slug
      where lc.lead_id = p_lead_id
      order by lc.score desc nulls last limit 1),
    -- 3. legacy text, but only when it is literally a catalog slug or catalog name
    (select c.name from public.leads l
       join public.catalog_supplier_categories c
         on c.slug = btrim(split_part(coalesce(l.categories,''),',',1))
         or lower(c.name) = lower(btrim(split_part(coalesce(l.categories,''),',',1)))
         or c.slug = btrim(coalesce(l.sector,''))
      where l.id = p_lead_id limit 1),
    'Uncategorized'));
$function$


CREATE OR REPLACE FUNCTION public.fn_dbx_safe(x text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select btrim(regexp_replace(regexp_replace(coalesce(x,''),'[\\/:*?"<>|\r\n\t]+',' ','g'),'\s+',' ','g'))
$function$


CREATE OR REPLACE FUNCTION public.fn_decide(p_kind text, p_ctx jsonb, p_actor text DEFAULT 'agent'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  res jsonb; conf numeric; reasons jsonb := '[]'::jsonb; route text; decision text;
  sources jsonb := '[]'::jsonb;
  v_alt text; v_alt_why text; v_alt_score numeric;
  v_ctx jsonb := coalesce(p_ctx, '{}'::jsonb);
  v_q text; v_cands text[]; v_hits jsonb := '[]'::jsonb; v_evidence jsonb;
  v_options jsonb; v_amount numeric; v_dept text;
  v_problem text; v_imp_bus text; v_imp_fin text; v_imp_leg text; v_imp_cus text;
  v_escalates boolean; v_status text; v_approver text; v_authorised boolean;
  v_dr_id bigint; v_dr_status text; v_verdict text; v_gate_reason text;
  v_corr uuid; v_trace uuid; v_prior jsonb;
begin
  begin v_amount := nullif(coalesce(v_ctx->>'amount_aed', v_ctx->>'amount'), '')::numeric;
  exception when others then v_amount := null; end;
  v_dept := nullif(v_ctx->>'dept_key', '');

  if p_kind='escalate' then
    -- p_actor goes IN. Without it the router has no line to send the escalation up and answers
    -- every caller with the same company-wide owner; see fn_should_escalate's reporting-line rung.
    res := public.fn_should_escalate(v_ctx || jsonb_build_object('actor', p_actor));
    decision := case when (res->>'escalate')::boolean then 'escalate' else 'proceed' end;
    reasons := res->'reasons'; route := res->>'route_to';
    conf := case when (res->>'escalate')::boolean then 0.9 else 0.8 end;
    -- WHY THIS PARTY, NOT JUST WHICH. 'decision_policy' was a label naming a table; the router's
    -- own verdict — route_basis, route_note and the reasons it fired on — is the retrieval this
    -- decision was actually taken on, and it is what makes the routing auditable after the fact.
    sources := to_jsonb(array['decision_policy'])
      || jsonb_build_array(jsonb_build_object('kind','policy_check','ref','fn_should_escalate','result',res));
    v_alt := case when decision='escalate' then 'proceed' else 'escalate' end;
    v_alt_why := 'the opposite verdict from fn_should_escalate on the same context';

  elsif p_kind='price' then
    res := public.fn_price_confidence(coalesce(v_ctx->>'category','default'), nullif(v_ctx->>'amount_aed','')::numeric);
    decision := 'priced'; conf := coalesce((res->>'confidence')::numeric, 0.5);
    reasons := jsonb_build_array(coalesce(res->>'band', 'price band computed')); sources := to_jsonb(array['price_confidence']);
    route := null;   -- a price band hands off to nobody; 'none' was a name that named nobody
    v_alt := 'quote_manually'; v_alt_why := 'refer the price to a human estimator instead of the band';

  elsif p_kind='route_category' then
    route := public.fn_resolve_cat_agent(coalesce(v_ctx->>'category',''));
    decision := coalesce(route,'unmatched'); conf := case when route is null then 0.3 else 0.85 end;
    reasons := jsonb_build_array('mapped category "'||coalesce(v_ctx->>'category','')||'" to agent '||coalesce(route,'(none)'));
    sources := to_jsonb(array['category_agents']);
    v_alt := 'Secretary'; v_alt_why := 'the unrouted-work fallback, which is slower but never drops the item';

  elsif p_kind='invite' then
    -- rank approved suppliers for a category (+ optional emirate)
    with pool as (
      select id, company_name, coalesce(capability_score,0) cap, coalesce(app_rating,rating,0) rat, coalesce(rv_response_rate,0) resp
      from leads
      where coalesce(approval_status,'')='approved'
        and (coalesce(v_ctx->>'category','')='' or lower(coalesce(categories,''))||' '||lower(coalesce(sub_type,'')) like '%'||lower(v_ctx->>'category')||'%')
        and (coalesce(v_ctx->>'emirate','')='' or coalesce(v_ctx->>'emirate')= any(coalesce(service_emirates,array[emirate])))
      order by (coalesce(capability_score,0)*0.5 + coalesce(app_rating,rating,0)*8 + coalesce(rv_response_rate,0)*0.3) desc
      limit coalesce((v_ctx->>'n')::int, 5))
    select jsonb_agg(jsonb_build_object('id',id,'name',company_name,'cap',cap,'rating',rat,'response',resp)) into res from pool;
    decision := 'invite_ranked'; conf := case when res is null then 0.2 when jsonb_array_length(res)>=3 then 0.8 else 0.5 end;
    reasons := jsonb_build_array('ranked by capability_score, rating and response rate');
    sources := to_jsonb(array['leads','supplier_capability','response_rate']);
    res := jsonb_build_object('suppliers', coalesce(res,'[]'));
    v_alt := 'broadcast_to_all_approved';
    v_alt_why := 'invite every approved supplier instead of the ranked shortlist — more coverage, worse response rate';

  elsif p_kind='approve' then
    res := public.fn_should_escalate(v_ctx || jsonb_build_object('actor', p_actor));
    if (res->>'escalate')::boolean then decision:='human_review'; conf:=0.9; reasons:=res->'reasons';
    else decision:='auto_approve'; conf:=0.85; reasons:=jsonb_build_array('within autonomous thresholds'); end if;
    route := res->>'route_to';
    sources := to_jsonb(array['decision_policy'])
      || jsonb_build_array(jsonb_build_object('kind','policy_check','ref','fn_should_escalate','result',res));
    v_alt := case when decision='human_review' then 'auto_approve' else 'human_review' end;
    v_alt_why := 'the opposite side of the autonomous threshold in decision_policy';

  else
    decision := 'unsupported_kind'; conf := 0; reasons := jsonb_build_array('no handler for kind '||p_kind); route:='Secretary';
    v_alt := 'add_a_handler'; v_alt_why := 'teach fn_decide this kind rather than routing it to a person every time';
  end if;

  -- ROUTE_TO NAMES A PARTY, OR IT NAMES NOBODY AND IS NULL.
  --
  -- MEASURED DEFECT, production, 6 Aug 2026: every routed decision this engine has ever written
  -- names something the org model does not contain. route_category wrote 'cat:signage' (9 rows) —
  -- a knowledge persona in category_agents, not an employee; price wrote the literal string
  -- 'none'; the unsupported-kind branch wrote 'Secretary', which matches no agent_key, no title
  -- and no dept_key across all 67 employees. The requirement is "Should I escalate? routes to a
  -- NAMED PARTY", and a column that is merely non-null answers it with a string.
  --
  -- The ladder resolves whatever the branch above chose, and it invents nobody: each rung returns
  -- a party the org model already contains, and if none does, the value is whatever
  -- fn_should_escalate itself answers — so a configuration gap stays visible as an unresolvable
  -- route rather than being papered over here.
  --   1. the name is already an active employee or a staffed department -> keep it
  --   2. 'cat:x' is a knowledge persona; the party is 'x' if 'x' is one  -> cat:it -> it
  --   3. the deciding actor's own department, if staffed — the work stays where it arose
  --   4. the escalation resolver's answer, which is the same one every other kind gets
  -- A decision that hands off to nobody carries NULL, which is what `invite` already did. The
  -- category agent itself is not lost: it is already the value of `decision` and is quoted in
  -- `reasons`, which is where "which persona holds this knowledge" belongs.
  route := nullif(btrim(coalesce(route, '')), '');
  if route in ('none', 'unmatched') then route := null; end if;
  if route is not null then
    route := coalesce(
      public.fn_route_party(route),
      public.fn_route_party(regexp_replace(route, '^cat:', '')),
      public.fn_route_party((select a.department from public.org_agents a
                              where a.agent_key = p_actor and a.active limit 1)),
      public.fn_should_escalate(jsonb_build_object('actor', p_actor)) ->> 'route_to');
  end if;

  -- STEP 3, KNOWLEDGE RETRIEVAL. fn_memory_search had zero callers, which is the whole defect:
  -- the engine decided without consulting anything the company already knew.
  --
  -- NARROW FIRST, THEN WIDER. fn_memory_search builds its query with plainto_tsquery, which ANDs
  -- every lexeme, so handing it a whole sentence retrieves NOTHING: 'Which agent owns Printing /
  -- Packaging / Signage work when an RFQ arrives' returned 0 hits on production while 'signage'
  -- returned 5. The candidates are therefore tried shortest-first and the first one that retrieves
  -- wins. A failed search must not lose the decision, so it degrades to "searched, no hits".
  v_cands := array_remove(array[
      nullif(btrim(coalesce(v_ctx->>'category','')), ''),
      nullif(array_to_string((regexp_split_to_array(
        btrim(coalesce(v_ctx->>'question', v_ctx->>'problem','')), '\s+'))[1:4], ' '), ''),
      nullif(btrim(coalesce(v_ctx->>'question', v_ctx->>'problem','')), ''),
      p_kind], null);

  foreach v_q in array v_cands loop
    begin
      select coalesce(jsonb_agg(jsonb_build_object(
               'kind', m.kind, 'ref', m.ref, 'snippet', left(m.snippet, 180),
               'score', round(m.score::numeric, 4))), '[]'::jsonb)
        into v_hits
        from public.fn_memory_search(v_q, null::text[], 5) m;
    exception when others then v_hits := '[]'::jsonb; end;
    exit when jsonb_array_length(v_hits) > 0;
  end loop;

  sources := sources || jsonb_build_array(jsonb_build_object(
               'kind', 'memory_search', 'q', v_q, 'hits', jsonb_array_length(v_hits))) || v_hits;

  -- HOW THE LAST DECISIONS OF THIS KIND TURNED OUT. decision_trace.outcome_status was written by
  -- fn_execution_sweep and read by nobody; it is retrieved here, recorded as a source, and it
  -- BITES: a kind whose executions have failed more often than they succeeded loses the confidence
  -- it needs to be taken autonomously and escalates instead. That is the difference between a
  -- measured outcome and a stored one.
  v_prior := public.fn_decision_outcomes(p_kind, 90);
  sources := sources || jsonb_build_array(jsonb_build_object(
               'kind', 'prior_outcomes', 'ref', 'decision_trace', 'result', v_prior));
  if coalesce((v_prior->>'graded')::int, 0) >= 3
     and coalesce((v_prior->>'failed')::int, 0) > coalesce((v_prior->>'succeeded')::int, 0) then
    conf := least(conf, 0.65);
    reasons := coalesce(reasons,'[]'::jsonb) || jsonb_build_array(format(
      'the last %s graded %s decisions went %s failed against %s succeeded, so this one is not taken autonomously',
      v_prior->>'graded', p_kind, v_prior->>'failed', v_prior->>'succeeded'));
  end if;

  v_evidence := sources;

  -- STEP 6. Two scored alternatives, always. One "option" is a conclusion, not a choice.
  v_options := jsonb_build_array(
    jsonb_build_object('option', decision, 'score', conf, 'selected', true, 'rationale', reasons),
    jsonb_build_object('option', coalesce(v_alt,'no_action'),
                       'score', coalesce(v_alt_score, round(1 - conf, 2)), 'selected', false,
                       'rationale', jsonb_build_array(coalesce(v_alt_why, 'the alternative the engine scored lower'))));

  -- STEP 1 and STEP 4. The problem in words, and the four impacts derived from what was computed.
  v_problem := format('Decision requested (%s) by %s: %s', p_kind, p_actor,
                 left(coalesce(nullif(btrim(concat_ws(' ', nullif(v_ctx->>'question',''), nullif(v_ctx->>'problem',''))), ''),
                               v_ctx::text), 400));
  v_imp_bus := format('Business: the engine selected "%s" over "%s" for %s. %s',
                 decision, coalesce(v_alt,'no_action'), p_actor, coalesce(v_alt_why,''));
  v_imp_fin := case when coalesce(v_amount,0) > 0
                 then format('Financial: AED %s is committed by this decision and is checked against %s spend authority before the gate lets it through.',
                             v_amount, coalesce(v_dept,'company'))
                 else format('Financial: no money moves. A %s decision consumes no spend authority and financial_aed stays null.', p_kind) end;
  v_imp_leg := case when p_kind in ('price','approve','invite')
                 then format('Legal: %s decisions are visible to a counterparty, so the record is retained for audit and PDPL subject access.', p_kind)
                 else format('Legal: internal routing only; a %s decision creates no counterparty obligation.', p_kind) end;
  v_imp_cus := case when coalesce(route,'none') in ('none','')
                 then format('Customer: no customer-facing step changes; the %s decision stays inside the operating system.', p_kind)
                 else format('Customer: the work moves to %s, which sets who answers the customer next and how quickly.', route) end;

  -- STEP 7. Whether this is the engine's to take. Escalating decisions stay 'proposed' and never
  -- reach the gate; autonomous ones are written as 'approved' so trg_decision_gate must inspect
  -- them, and it is free to refuse — 'blocked_by_gate' coming back out is a working gate, not a bug.
  --
  -- THE ACTOR MUST HAVE AUTHORITY ON FILE. This is now belt AND braces: fn_decision_gate consults
  -- the register itself for every writer (scripts/sql/fn_decision_gate_authority_register.sql), and
  -- the engine declines to even propose an autonomous decision for an actor it cannot find there —
  -- an escalation is a better answer than a refusal for something the engine could see coming.
  -- 'founder' is the one identity the gate treats as top authority without an employee_authority
  -- row, so it resolves here too; every other actor must be on the list.
  v_authorised := p_actor = 'founder'
                  or exists (select 1 from public.employee_authority ea where ea.agent_key = p_actor);
  if not v_authorised then
    reasons := coalesce(reasons,'[]'::jsonb) || jsonb_build_array(
      format('%s has no employee_authority record, so this decision is escalated rather than taken autonomously', p_actor));
  end if;

  v_escalates := decision in ('escalate','human_review','unsupported_kind')
                 or conf < 0.7
                 or jsonb_array_length(v_evidence) = 0
                 or not v_authorised;
  v_status   := case when v_escalates then 'proposed' else 'approved' end;
  v_approver := case when v_escalates then null else p_actor end;

  insert into public.decision_record(
      decided_by, dept_key, problem, context, options, risks, benefits, recommendation,
      confidence, expected_outcome, rollback_plan, approved_by, status,
      impact_business, impact_financial, financial_aed, impact_legal, impact_customer,
      evidence, reversible)
  values (
      p_actor, v_dept, v_problem, left(v_ctx::text, 2000), v_options,
      format('Risk: if "%s" is the wrong call, %s. Scored %s against %s for the alternative.',
             decision, coalesce(v_alt_why,'the rejected alternative was the better one'),
             conf, coalesce(v_alt_score, round(1 - conf, 2))),
      format('Benefit: the %s step is taken now instead of waiting for a person, on %s retrieved reference(s).',
             p_kind, jsonb_array_length(v_hits)),
      -- recommendation is the ONE decision_record field fn_agent_context actually emits to an
      -- employee ('# DECISIONS ALREADY ON RECORD FOR YOUR DEPARTMENT', left(...,150)). The step-3
      -- retrieval was landing on evidence, which travels nowhere, so the count of references the
      -- engine consulted is carried here instead of being computed and thrown away.
      format('%s (confidence %s, route %s, %s reference(s) retrieved)',
             decision, conf, coalesce(route,'none'), jsonb_array_length(v_hits)),
      conf,
      format('Expected: %s is carried out and the outcome recorded against decision_record.', decision),
      case when v_escalates then 'Rollback: nothing executed; the decision sits at proposed until a human takes it.'
           else format('Rollback: set status back to proposed and re-run fn_decide(%L, ...) with corrected context.', p_kind) end,
      v_approver, v_status,
      v_imp_bus, v_imp_fin, v_amount, v_imp_leg, v_imp_cus,
      v_evidence, coalesce(v_amount,0) = 0)
  returning id, status, gate_verdict, gate_reason
       into v_dr_id, v_dr_status, v_verdict, v_gate_reason;

  insert into public.decision_log(actor,kind,ctx,decision,confidence,reasons,sources,route_to)
  values (p_actor,p_kind,v_ctx,decision,conf,reasons,sources,route);

  -- STEP 9. Execution linked BACK to the decision. One correlation_id ties the trace to the
  -- action, and the action carries the decision_record id it came from, so
  -- v_executions_without_decision_trace stays empty for anything this engine produced.
  -- The row is written 'queued' and public.fn_execution_run (cron execution_run_hourly) performs
  -- it: it delivers the decision to the actor the decision named and settles the row against the
  -- artefact it created. Claiming 'succeeded' here would be claiming an outcome before the act.
  if v_verdict = 'passed' then
    begin v_corr := nullif(current_setting('app.correlation_id', true), '')::uuid;
    exception when others then v_corr := null; end;
    v_corr := coalesce(v_corr, gen_random_uuid());

    insert into public.decision_trace(
        correlation_id, entity_type, entity_id, decision_type, proposed_by, decided_by,
        policy_keys, knowledge_refs, evidence_refs, alternatives, assumptions, risk,
        confidence, authority_result, decision)
    values (v_corr, 'decision_record', v_dr_id::text, p_kind, p_actor, coalesce(v_approver, p_actor),
        array['decision_policy'], v_hits, v_evidence, v_options,
        jsonb_build_array(format('context supplied by %s is current', p_actor)),
        jsonb_build_object('escalated', v_escalates, 'route_to', route, 'financial_aed', v_amount),
        conf,
        jsonb_build_object('gate_verdict', v_verdict, 'approved_by', v_approver, 'status', v_dr_status),
        jsonb_build_object('kind', p_kind, 'decision', decision, 'decision_record_id', v_dr_id,
                           'confidence', conf))
    returning id into v_trace;

    insert into public.action_execution(
        correlation_id, action_class, executor, idempotency_key, risk_tier, reversible, request, status)
    values (v_corr, 'decision.'||p_kind, p_actor, 'decision_record:'||v_dr_id::text,
        case when coalesce(v_amount,0) >= 1000 then 'high'
             when coalesce(v_amount,0) > 0 then 'medium' else 'low' end,
        coalesce(v_amount,0) = 0,
        jsonb_build_object('decision_record_id', v_dr_id, 'decision_trace_id', v_trace,
                           'kind', p_kind, 'decision', decision, 'route_to', route, 'ctx', v_ctx),
        'queued');
  end if;


  -- BOARD BEFORE A MAJOR DECISION (spec #3 s24). Every active advisor gives an independent opinion
  -- on the problem this decision answers, keyed to the decision_record by id -- so the link is a
  -- foreign key and not the text match the scorer had to fall back on when subject_ref was null on
  -- all 28 rows. fn_challenge underneath is pure SQL, so this costs no model call.
  -- Guarded twice: only when a record was actually written, and an advisor that throws must not
  -- lose the decision it was advising on. The failure is raised as a warning rather than swallowed.
  if v_dr_id is not null then
    begin
      perform public.fn_board_review(
        coalesce((select d.problem from public.decision_record d where d.id = v_dr_id), p_kind),
        v_dr_id::text);
    exception when others then
      raise warning 'fn_board_review failed for decision_record % : %', v_dr_id, sqlerrm;
    end;
  end if;

  return jsonb_build_object('kind',p_kind,'decision',decision,'confidence',conf,'reasons',reasons,
                            'route_to',route,'sources',sources,'detail',res,
                            'decision_record_id',v_dr_id,'status',v_dr_status,
                            'gate_verdict',v_verdict,'gate_reason',v_gate_reason,
                            'options',v_options,'knowledge_hits',jsonb_array_length(v_hits),
                            'prior_outcomes',v_prior);
end $function$


CREATE OR REPLACE FUNCTION public.fn_decision_conflict_scan()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_conflicts int; v_sample text;
begin
  -- The same actor and kind reaching two different verdicts inside a week is either a change of
  -- mind nobody recorded or an inconsistency. Either way the founder should be told which.
  with pairs as (
    select l.actor, l.kind, count(distinct l.decision) k,
           string_agg(distinct l.decision, ' vs ') verdicts
      from public.decision_log l
     where l.created_at > now() - interval '7 days' and coalesce(l.decision,'') <> ''
     group by l.actor, l.kind
    having count(distinct l.decision) > 1)
  select count(*), coalesce(string_agg(actor || '/' || kind || ': ' || verdicts, '; '), '')
    into v_conflicts, v_sample from pairs;

  if v_conflicts > 0 then
    insert into public.founder_alerts(level, event, detail, channel)
      values ('info', 'Governance monitor — conflicting decisions',
              v_conflicts || ' actor/kind pair(s) reached more than one verdict in 7 days. ' || left(v_sample, 900), 'os');
  end if;
  return jsonb_build_object('monitor', 'conflicting_decisions', 'conflicts', v_conflicts, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_decision_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_was text; v_spend jsonb; v_reason text; v_limit numeric; v_actor text; v_auth integer;
begin
  v_was := case when tg_op = 'UPDATE' then coalesce(old.status,'') else '' end;

  if new.status in ('approved','executed') and v_was not in ('approved','executed') then
    v_reason := null;

    if coalesce(length(new.impact_business),0)  < 20
    or coalesce(length(new.impact_financial),0) < 20
    or coalesce(length(new.impact_legal),0)     < 10
    or coalesce(length(new.impact_customer),0)  < 20
    or jsonb_array_length(coalesce(new.evidence,'[]'::jsonb)) = 0 then
      v_reason := 'Impact analysis incomplete: business, financial, legal and customer impact plus at least one evidence reference are all required before approval.';
    end if;

    -- THE AUTHORITY REGISTER, CONSULTED. Not "is this affordable" — that is the spend question
    -- below and it only asks anything when money moves. This asks the step-7 question: is the
    -- approver someone this company has recorded as able to decide anything at all?
    if v_reason is null then
      v_actor := coalesce(nullif(btrim(new.approved_by),''), new.decided_by);
      if coalesce(v_actor,'') <> 'founder' then
        select count(*) into v_auth
          from public.employee_authority ea
         where ea.agent_key = v_actor;
        if coalesce(v_auth,0) = 0 then
          v_reason := format('%s has no employee_authority record. The authority register is the '
                          || 'list of who may decide what; an actor absent from it cannot approve a '
                          || 'decision, whatever the amount involved.',
                          coalesce(v_actor, '(no approver named)'));
        end if;
      end if;
    end if;

    if v_reason is null and coalesce(new.financial_aed,0) > 0 then
      -- fn_emit_budget_exceeded is fn_check_spend plus a company_event on a breach. Same verdict,
      -- and the breach now leaves a trace the founder actually reads.
      v_spend := public.fn_emit_budget_exceeded(new.dept_key, new.financial_aed, new.approved_by,
                   coalesce(left(new.problem, 200), 'decision_record #' || coalesce(new.id::text,'?')));
      v_limit := nullif(v_spend->>'agent_limit_aed','')::numeric;

      if not coalesce((v_spend->>'affordable')::boolean, false) then
        v_reason := v_spend->>'reason';
      elsif v_limit is not null and coalesce(new.financial_aed,0) > v_limit then
        -- THE PERSONAL GRANT, ENFORCED. Previously computed and thrown away.
        v_reason := format('AED %s exceeds %s''s personal authority limit of AED %s recorded in '
                        || 'employee_authority. Affordable for the department, but not this '
                        || 'employee''s to approve — route to %s.',
                        new.financial_aed, coalesce(new.approved_by,'(unnamed approver)'), v_limit,
                        coalesce(v_spend->>'route_to','the Chief of Staff'));
      elsif coalesce(new.financial_aed,0) > 10000 and coalesce(new.approved_by,'') not in ('founder','ceo') then
        v_reason := format('AED %s is above the AED 10,000 founder threshold and approved_by is "%s".', new.financial_aed, coalesce(new.approved_by,'(none)'));
      elsif coalesce(new.financial_aed,0) >= 1000 and coalesce(new.approved_by,'') not in ('brief','founder','ceo') then
        v_reason := format('AED %s needs Chief of Staff approval and approved_by is "%s".', new.financial_aed, coalesce(new.approved_by,'(none)'));
      end if;
    end if;

    if v_reason is not null then
      -- Refuse, and leave the refusal on the row rather than aborting the transaction
      -- and losing every trace of it.
      new.status          := 'blocked_by_gate';
      new.gate_verdict    := 'refused';
      new.gate_reason     := v_reason;
      new.gate_checked_at := now();
      raise warning 'decision refused by gate: %', v_reason;
    else
      new.gate_verdict    := 'passed';
      new.gate_reason     := null;
      new.gate_checked_at := now();
    end if;
  end if;
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_decision_outcomes(p_kind text, p_days integer DEFAULT 90)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- 'cancelled' is counted and reported but is NOT a failure: it means the decision was withdrawn
  -- or refused before it ran, which the authority gate has already ruled on and which says nothing
  -- about whether decisions OF THIS KIND work when they are carried out. Folding it in would make
  -- three gate refusals suppress a whole decision kind for ninety days, which is a punishment, not
  -- a measurement.
  select jsonb_build_object(
           'decision_type', p_kind,
           'window_days',   greatest(coalesce(p_days, 90), 1),
           'traced',        count(*),
           'graded',        count(*) filter (where t.outcome_status is not null),
           'succeeded',     count(*) filter (where t.outcome_status = 'succeeded'),
           'failed',        count(*) filter (where t.outcome_status in ('failed','stalled')),
           'cancelled',     count(*) filter (where t.outcome_status = 'cancelled'),
           'last_evaluated_at', max(t.evaluated_at))
    from public.decision_trace t
   where t.decision_type = p_kind
     and t.created_at > now() - make_interval(days => greatest(coalesce(p_days, 90), 1));
$function$


CREATE OR REPLACE FUNCTION public.fn_decision_trace_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.sealed_at is not null then
    -- Only the outcome may be graded after sealing. Everything the decision was BASED on is frozen.
    if (new.decision        is distinct from old.decision)
    or (new.evidence_refs   is distinct from old.evidence_refs)
    or (new.knowledge_refs  is distinct from old.knowledge_refs)
    or (new.tool_result_refs is distinct from old.tool_result_refs)
    or (new.confidence      is distinct from old.confidence)
    or (new.authority_result is distinct from old.authority_result)
    or (new.agent_key       is distinct from old.agent_key)
    or (new.role_id         is distinct from old.role_id)
    or (new.proposed_action is distinct from old.proposed_action) then
      raise exception 'decision_trace % is sealed. Evidence, confidence, authority and identity cannot be edited after the fact; grade the outcome instead.', old.id;
    end if;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_delete_proposer()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_out jsonb := '[]'::jsonb; c record; v_n int; v_id bigint; v_prev record;
  v_specs jsonb := jsonb_build_array(
    jsonb_build_object('category','model_policy_by_identity_target_employee','agent','ai_director','risk','low',
      'title_suffix','imported model-policy rows that name no employee',
      'sql', $s$select count(*) from model_policy_by_identity where scope='target_employee'$s$,
      'why','96 rows scoped target_employee, 0 matching an org_agents.agent_key. DECIDED 11 Aug 2026: KEEP. They are the pack''s TARGET ORG CHART - department, title, manager and authority_tier for 96 roles - not dead routing config. routing_tier superseded their MODEL choice, not their org design. fn_ai_route reads only scope=''current_agent'', so they route nothing.'),
    jsonb_build_object('category','decorative_company_goals','agent','analytics_director','risk','medium',
      'title_suffix','Company goals that cannot be missed and cannot pull anything down',
      'sql', $s$select count(*) from company_goals g where g.active and coalesce(g.measure_sql,'')='' and coalesce(g.no_measure_reason,'')='' and not exists (select 1 from department_objective d where d.goal_key=g.key and d.active)$s$,
      'why','Active, no measure_sql, no department objective, AND no recorded reason why. A goal that cannot be measured cannot be missed. Giving it a measure or a written reason both count; leaving it silent does not.'),
    jsonb_build_object('category','orphan_agent_expectations','agent','it','risk','low',
      'title_suffix','agent_expectations rows watching something that does not exist',
      'sql', $s$select count(*) from agent_expectations e where public.fn_org_agent_resolve(e.agent) is null and coalesce(e.kind,'') <> 'code' and not exists (select 1 from cron.job j where j.jobname ilike '%'||e.agent||'%' or j.command ilike '%'||e.agent||'%')$s$,
      'why','Resolves to no employee through key OR alias, is not a code/job name, and matches no cron job. Each one can raise a silence alarm about a thing that cannot run, which is how an employee gets dispatched to diagnose nothing.'),
    jsonb_build_object('category','unmeasurable_employee_kpis','agent','analytics_director','risk','medium',
      'title_suffix','Employee KPIs with a target and no way to measure it',
      'sql', $s$select count(*) from employee_kpi k where k.active and coalesce(k.measure_sql,'')='' and coalesce(k.no_measure_reason,'')=''$s$,
      'why','An employee is told it is judged on something nobody can score, and nobody has written down why. Most need an instrument or demand that does not exist yet rather than deletion - a recorded reason closes this, a silent row does not.'),
    jsonb_build_object('category','inactive_org_agents','agent','hr_director','risk','low',
      'title_suffix','Employees marked inactive and still on the books',
      'sql', $s$select count(*) from org_agents where not coalesce(active,true)$s$,
      'why','An inactive employee still resolves in manager chains and still appears in joins that do not filter on active. Either reactivate it or remove it deliberately.')
  );
begin
  for c in select * from jsonb_array_elements(v_specs) as t(spec)
  loop
    execute (c.spec->>'sql') into v_n;
    if coalesce(v_n,0) = 0 then continue; end if;

    select id into v_id from public.agent_actions
     where kind = 'delete_proposal' and detail->>'category' = c.spec->>'category'
       and status = 'needs_review' limit 1;
    if v_id is not null then
      update public.agent_actions
         set title = v_n || ' — ' || (c.spec->>'title_suffix'),
             detail = coalesce(detail,'{}'::jsonb) || jsonb_build_object(
               'count', v_n, 'why', c.spec->>'why', 'counted_by', c.spec->>'sql',
               'counted_at', now())
       where id = v_id;
      continue;
    end if;

    -- THE DECISION HOLDS UNTIL THE FACT CHANGES. A category answered 'keep' is not asked again at
    -- the same size or smaller. It IS asked again if the count grows past what was accepted, which
    -- is a different question about a different number.
    select (detail->>'count')::int as n, detail->>'decision' as decision
      into v_prev
      from public.agent_actions
     where kind = 'delete_proposal' and detail->>'category' = c.spec->>'category'
       and detail ? 'decision'
     order by id desc limit 1;
    if found and v_prev.decision in ('keep','keep_with_reason','retire')
       and v_n <= coalesce(v_prev.n, 0) then
      continue;
    end if;

    insert into public.agent_actions (agent, kind, status, risk, title, recommendation, detail)
    values (c.spec->>'agent', 'delete_proposal', 'needs_review', c.spec->>'risk',
            v_n || ' — ' || (c.spec->>'title_suffix'),
            'Decide deliberately: remove, retire (active=false), or keep with a stated reason. Do not close this without one of the three.',
            jsonb_build_object('category', c.spec->>'category', 'count', v_n,
              'why', c.spec->>'why', 'counted_by', c.spec->>'sql', 'counted_at', now(),
              'reopened_over', case when v_prev.n is null then null else v_prev.n end,
              'proposes','review for removal — this routine never deletes anything'));
    v_out := v_out || jsonb_build_array(jsonb_build_object('category', c.spec->>'category', 'count', v_n));
  end loop;

  insert into public.agent_runs(agent, status, counts, note, started_at, finished_at)
  values ('delete_proposer','ok', jsonb_build_object('opened', jsonb_array_length(v_out)),
          'delete proposals refreshed; ' || jsonb_array_length(v_out) || ' newly opened', now(), now());
  return v_out;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_demo_marker_scan()
 RETURNS TABLE(rel text, col text, rows bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n bigint;
begin
  for r in
    select c.table_name t, c.column_name k
      from information_schema.columns c
      join information_schema.tables tb
        on tb.table_schema = c.table_schema and tb.table_name = c.table_name
     where c.table_schema = 'public'
       and tb.table_type = 'BASE TABLE'
       and c.data_type in ('text','character varying','character')
     order by 1, 2
  loop
    begin
      execute format(
        'select count(*) from public.%I where %I ~* %L', r.t, r.k,
        'ZZ DEMO|example\.invalid|qd-demo') into n;
    exception when others then
      n := -1;   -- an unreadable column is reported, never silently counted as zero
    end;
    if n <> 0 then rel := r.t; col := r.k; rows := n; return next; end if;
  end loop;
end $function$


CREATE OR REPLACE FUNCTION public.fn_dept_authority(p_dept text, p_action_class text, p_amount_aed numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v jsonb;
begin
  v := public.fn_ops_authority_check(p_dept, p_action_class, p_amount_aed, null);
  return jsonb_build_object(
    'dept', p_dept,
    'action_class', p_action_class,
    'tier', v->>'effective_tier',
    'threshold_aed', (v->>'threshold_aed')::numeric,
    'capped', coalesce(v->>'production_tier', 'gated') is distinct from (v->>'effective_tier'),
    'reviewed', (v->>'reviewed')::boolean,
    'reason', v->>'reason');
end $function$


CREATE OR REPLACE FUNCTION public.fn_dept_can_plan(p_dept_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_stalled int; v_cap int := 5; v_last timestamptz;
begin
  -- Only ASSIGNED-but-never-run work counts as pile-up. Work in progress, work
  -- awaiting the founder, and work already attempted are not what the cap is for.
  select count(*) into v_stalled from org_tasks
   where dept_key = p_dept_key and status = 'assigned' and attempts = 0
     and created_at < now() - interval '48 hours';

  select max(created_at) into v_last from org_memory
   where scope = p_dept_key and kind = 'plan' and source = 'dept_plan';

  -- No department goes silent for more than a week, whatever its backlog. A
  -- department that cannot plan cannot improve, and that is the failure mode the
  -- autonomous-company design exists to prevent.
  if v_last is null or v_last < now() - interval '7 days' then
    return jsonb_build_object('can_plan', true, 'reason',
      'weekly floor: last self-plan ' || coalesce(v_last::text,'never') || ' - planning regardless of backlog',
      'stalled', v_stalled);
  end if;

  if v_stalled >= v_cap then
    return jsonb_build_object('can_plan', false, 'reason',
      v_stalled || ' tasks assigned over 48h ago and never attempted. Execution is behind planning; drain before adding.',
      'stalled', v_stalled);
  end if;

  return jsonb_build_object('can_plan', true, 'reason',
    v_stalled || ' stalled task(s), under the cap of ' || v_cap, 'stalled', v_stalled);
end $function$


CREATE OR REPLACE FUNCTION public.fn_dept_canonical(p_dept text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select d.merged_into from public.org_departments d
      where d.dept_key = p_dept and d.merged_into is not null),
    p_dept);
$function$


CREATE OR REPLACE FUNCTION public.fn_dept_library_search(p_dept text, p_query text, p_limit integer DEFAULT 5)
 RETURNS TABLE(id bigint, department text, title text, content text, rank real)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare q_or tsquery; words text[];
begin
  words := array(select w from unnest(regexp_split_to_array(lower(regexp_replace(coalesce(p_query,''),'[^a-z0-9 ]',' ','g')),'\s+')) w where length(w)>2);
  if array_length(words,1) is null then return; end if;
  begin q_or := to_tsquery('english', array_to_string(words,' | ')); exception when others then return; end;
  return query
    select l.id, l.department, l.title, l.content, ts_rank(l.tsv, q_or) as rank
    from dept_library l
    where (p_dept is null or l.department = p_dept) and l.tsv @@ q_or
    order by ts_rank(l.tsv, q_or) desc, l.id
    limit greatest(1, least(coalesce(p_limit,5),20));
end $function$


CREATE OR REPLACE FUNCTION public.fn_dept_objective_measure()
 RETURNS TABLE(measured integer, failed integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v numeric; n_ok int := 0; n_bad int := 0;
begin
  for r in select id, measure_sql from department_objective
            where coalesce(active,true) and coalesce(measure_sql,'') <> '' loop
    begin
      execute r.measure_sql into v;
      update department_objective set actual_value = v, measured_at = now() where id = r.id;
      n_ok := n_ok + 1;
    exception when others then
      update department_objective set actual_value = null, measured_at = null where id = r.id;
      n_bad := n_bad + 1;
    end;
  end loop;
  return query select n_ok, n_bad;
end $function$


CREATE OR REPLACE FUNCTION public.fn_dept_scope(p_dept text)
 RETURNS text[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select array(select p_dept
               union
               select d.dept_key from public.org_departments d where d.merged_into = p_dept);
$function$


CREATE OR REPLACE FUNCTION public.fn_derive_supplier_registration_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_fee numeric; v_start date;
begin
  -- Only registered suppliers carry a registration state. The other ~20k scraped listings are
  -- left completely untouched so bulk maintenance on leads stays cheap.
  if coalesce(new.claimed,false) is not true and new.founding_rank is null then
    return new;
  end if;

  select coalesce(p.supplier_reg_fee,1000), coalesce(p.supplier_charging_starts,'2027-08-01'::date)
    into v_fee, v_start from public.pricing_config p where p.id = 1;
  v_fee := coalesce(v_fee,1000); v_start := coalesce(v_start,'2027-08-01'::date);

  if coalesce(new.subscription_exempt,false) then
    new.registration_status := 'exempt'; new.registration_fee_due := 0;
  elsif new.subscription_paid_until is not null and new.subscription_paid_until >= current_date then
    new.registration_status := 'paid'; new.registration_fee_due := 0;
  elsif current_date < v_start then
    new.registration_status := 'not_due'; new.registration_fee_due := 0;
  else
    new.registration_status := 'due'; new.registration_fee_due := v_fee;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_dispatch_agent_knowledge_gaps(p_stale_days integer DEFAULT 14, p_thin_min integer DEFAULT 4)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare a jsonb; g jsonb; opened int := 0; resolved_before int; resolved_after int; total_gap int := 0;
begin
  g := fn_knowledge_gaps(p_stale_days, p_thin_min);
  select count(*) into resolved_before from agent_actions where kind='knowledge_task' and detail->>'signal' like 'agent_knowledge:%' and status in ('pending','needs_review');
  for a in select * from jsonb_array_elements(g->'agents') loop
    declare v_gap boolean := (a->>'status') in ('stale','thin'); v_slug text := a->>'slug';
    begin
      if v_gap then total_gap := total_gap + 1; end if;
      perform kn_task('agent_knowledge:'||v_slug, v_gap, case when (a->>'status')='thin' then 'low' else 'medium' end,
        'Refresh knowledge: '||coalesce(a->>'name',v_slug),
        coalesce(a->>'name',v_slug)||' has '||coalesce(a->>'items','0')||' knowledge item(s), last refreshed '||
        coalesce((a->>'days_stale')||' days ago','never')||' (status: '||(a->>'status')||'). Regenerate its field brief so it advises with current expertise. Auto-closes once refreshed.',
        jsonb_build_array(
          'Item count and refresh date measure the SHELF, not the reading. '||coalesce(a->>'name',v_slug)||' could hold a large, fresh brief it never retrieves and look identical here to one that reads it on every call.',
          'The thresholds are chosen, not derived: under '||p_thin_min||' item(s) is "thin" and '||p_stale_days||' day(s) is "stale". An agent whose field genuinely changes twice a year is stale here every fortnight.',
          '"Regenerate" assumes the source material has moved on. Regenerating against an unchanged world produces a new date and the same knowledge, which closes this task without improving anything.',
          coalesce(a->>'name',v_slug)||' is doing work worth briefing. An agent that has never run is stale in exactly the same way as one that runs hourly.'),
        coalesce(a->>'name',v_slug)||' currently advises from '||coalesce(a->>'items','0')||' item(s) last refreshed '||coalesce((a->>'days_stale')||' days ago','never')||'. Refreshing changes what it tells suppliers and customers; leaving it means confident advice from a stale field brief, which does not fail visibly.',
        'Model spend, one generation per agent. The cheap failure is regenerating everything on a schedule; the expensive one is an agent quoting last quarter''s rules to a customer.');
    end;
  end loop;
  select count(*) into resolved_after from agent_actions where kind='knowledge_task' and detail->>'signal' like 'agent_knowledge:%' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at', now(), 'gaps_found', total_gap, 'open_tasks', resolved_after,
    'summary', g->'summary');
end $function$


CREATE OR REPLACE FUNCTION public.fn_dispute_open(p_stripe_dispute_id text, p_stripe_charge_id text, p_payment_ref text, p_amount_aed numeric, p_reason text, p_evidence_due_by timestamp with time zone)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id bigint; v_txn bigint;
begin
  select id into v_txn from transactions where payment_ref = p_payment_ref limit 1;

  insert into payment_dispute (stripe_dispute_id, stripe_charge_id, payment_ref, transaction_id,
                               amount_aed, reason, evidence_due_by)
  values (p_stripe_dispute_id, p_stripe_charge_id, p_payment_ref, v_txn,
          p_amount_aed, p_reason, p_evidence_due_by)
  on conflict (stripe_dispute_id) do update set
    status = 'needs_response', evidence_due_by = excluded.evidence_due_by
  returning id into v_id;

  insert into founder_alerts (level, event, detail, channel)
  values ('crit','payment_dispute',
          format('Card dispute opened: AED %s, reason "%s", evidence due %s. Stripe dispute %s. An unanswered dispute is lost automatically and counts toward the account dispute rate.',
                 coalesce(p_amount_aed,0), coalesce(p_reason,'unknown'),
                 coalesce(p_evidence_due_by::text,'unknown'), p_stripe_dispute_id),
          'system');

  insert into company_event (event_type, entity_type, entity_id, actor, payload)
  values ('invoice.flagged','dispute', p_stripe_dispute_id, 'cfo',
          jsonb_build_object('amount_aed', p_amount_aed, 'reason', p_reason,
                             'evidence_due_by', p_evidence_due_by, 'transaction_id', v_txn));

  insert into institutional_memory (kind, subject_type, subject_id, headline, detail, outcome,
                                    money_aed, learned_by, confidence, evidence_ref)
  values ('pattern','dispute', p_stripe_dispute_id,
          'Card dispute opened on a reveal fee.',
          format('Reason "%s" on AED %s. Disputes on a facilitation fee usually mean the buyer did not understand what they paid for, or the supplier never responded after reveal.', coalesce(p_reason,'unknown'), coalesce(p_amount_aed,0)),
          'open', p_amount_aed, 'cfo', 1.0, 'payment_dispute id '||v_id);

  return v_id;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_doc_control()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run bigint; v_remind int := 0; v_expired int := 0; r record; v_days int;
begin
  insert into agent_runs(agent, started_at) values ('docs', now()) returning id into v_run;
  for r in select id, company_name, claimed_by, email, license_expiry from leads
           where approval_status='approved' and claimed=true and license_expiry is not null
  loop
    v_days := r.license_expiry - current_date;
    if v_days between 0 and 7 then
      if not exists (select 1 from notifications where lead_id=r.id and type='licence_expiry_reminder' and created_at > now()-interval '6 days') then
        insert into notifications(type,to_email,to_role,channel,lead_id,subject,body)
          values ('licence_expiry_reminder', coalesce(r.claimed_by,r.email), 'supplier', 'email', r.id,
            'Your trade licence expires in '||v_days||' day(s) - QuotesDone',
            'Dear '||coalesce(r.company_name,'partner')||', our records show your trade licence expires on '||to_char(r.license_expiry,'DD Mon YYYY')||' ('||v_days||' day(s) away). Please upload your renewed trade licence in your supplier portal to keep your account active and continue receiving job matches. Portal: https://quotesdone.com/suppliers/');
        v_remind := v_remind + 1;
      end if;
    elsif v_days < 0 then
      if not exists (select 1 from notifications where lead_id=r.id and type='licence_expired' and created_at > now()-interval '7 days') then
        insert into notifications(type,to_email,to_role,channel,lead_id,subject,body)
          values ('licence_expired', coalesce(r.claimed_by,r.email), 'supplier', 'email', r.id,
            'Action needed: your trade licence has expired - QuotesDone',
            'Dear '||coalesce(r.company_name,'partner')||', our records show your trade licence expired on '||to_char(r.license_expiry,'DD Mon YYYY')||'. To keep receiving jobs on QuotesDone, please upload your renewed licence in your portal as soon as possible: https://quotesdone.com/suppliers/');
        insert into agent_actions(agent,kind,status,risk,title,recommendation,target_table,target_id,detail)
          values ('docs','licence_expired','pending','medium',coalesce(r.company_name,'Supplier #'||r.id)||' - trade licence EXPIRED','suspend or chase renewal','leads',r.id::text,jsonb_build_object('expiry',r.license_expiry));
        v_expired := v_expired + 1;
      end if;
    end if;
  end loop;
  update agent_runs set finished_at=now(), status='ok', counts=jsonb_build_object('reminders',v_remind,'expired',v_expired) where id=v_run;
end;$function$


CREATE OR REPLACE FUNCTION public.fn_doc_diff(p_type text, p_id text, p_va integer, p_vb integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a jsonb; b jsonb; k text; res jsonb := '{}';
begin
  select snapshot into a from public.doc_versions where entity_type=p_type and entity_id=p_id and version=p_va;
  select snapshot into b from public.doc_versions where entity_type=p_type and entity_id=p_id and version=p_vb;
  if a is null or b is null then return jsonb_build_object('error','version not found'); end if;
  for k in select distinct key from (select jsonb_object_keys(a) key union select jsonb_object_keys(b)) z loop
    if (a->k) is distinct from (b->k) then
      res := res || jsonb_build_object(k, jsonb_build_object('from', a->k, 'to', b->k));
    end if;
  end loop;
  return jsonb_build_object('entity',p_type||':'||p_id,'from_version',p_va,'to_version',p_vb,'changes',res);
end $function$


CREATE OR REPLACE FUNCTION public.fn_doc_expiry_scan()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare rec record; n int:=0; owner text;
begin
  select split_part(coalesce(value,'management@quotesdone.com'),',',1) into owner from app_secrets where key='admin_emails';
  for rec in
    select id, company_name, 'trade licence' as doc, license_expiry as exp from leads where license_expiry is not null and license_expiry <= current_date+30 and coalesce(approval_status,'')='approved'
    union all
    select id, company_name, 'insurance', insurance_expiry from leads where insurance_expiry is not null and insurance_expiry <= current_date+30 and coalesce(approval_status,'')='approved'
    union all
    select id, company_name, 'registration', registration_expires_at::date from leads where registration_expires_at is not null and registration_expires_at::date <= current_date+30 and coalesce(approval_status,'')='approved'
    union all
    select id, company_name, 'ISO certification', iso_expiry from leads where iso_expiry is not null and iso_expiry <= current_date+30 and coalesce(approval_status,'')='approved'
    union all
    select id, company_name, 'manufacturer authorisation', manufacturer_auth_expiry from leads where manufacturer_auth_expiry is not null and manufacturer_auth_expiry <= current_date+30 and coalesce(approval_status,'')='approved'
  loop
    if not exists (select 1 from notifications where type='doc_expiry' and lead_id=rec.id and subject like '%'||rec.doc||'%' and created_at > now()-interval '20 days') then
      insert into notifications(type,to_email,to_role,lead_id,channel,subject,body)
      values ('doc_expiry', owner, 'admin', rec.id, 'email',
        'Supplier document expiring: '||rec.doc,
        coalesce(rec.company_name,'Supplier #'||rec.id)||' — '||rec.doc||' expires '||rec.exp||'. Follow up for renewal.');
      n:=n+1;
    end if;
  end loop;
  return jsonb_build_object('flagged',n,'scanned_at',now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_doc_final_notice(p_days integer DEFAULT 7)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  rec record; v_email int := 0; v_wa int := 0; v_skipped int := 0;
  v_horizon date := current_date + make_interval(days => p_days);
  v_phone text; v_to text; v_label text; v_exp date;
begin
  for rec in
    select id, company_name, claimed_by, email, phone, whatsapp,
           license_expiry, insurance_expiry
      from leads
     where approval_status = 'approved'
       and coalesce(banned,false) = false
       and coalesce(matching_blocked,false) = false
       and ((license_expiry   is not null and license_expiry   between current_date and v_horizon)
         or (insurance_expiry is not null and insurance_expiry between current_date and v_horizon))
  loop
    -- Whichever gating document expires first is the one we lead with.
    if rec.license_expiry is not null and rec.license_expiry between current_date and v_horizon
       and (rec.insurance_expiry is null or rec.license_expiry <= rec.insurance_expiry) then
      v_label := 'trade licence'; v_exp := rec.license_expiry;
    else
      v_label := 'insurance certificate'; v_exp := rec.insurance_expiry;
    end if;

    -- One final notice per document per expiry cycle. Without this the daily cron would send
    -- the same warning seven days running.
    if exists (select 1 from notifications
                where type = 'doc_final_notice' and lead_id = rec.id
                  and subject like '%' || v_label || '%'
                  and created_at > now() - interval '20 days') then
      v_skipped := v_skipped + 1; continue;
    end if;

    v_to := nullif(trim(coalesce(rec.claimed_by, rec.email)), '');
    if v_to is null or position('@' in v_to) = 0 then v_skipped := v_skipped + 1; continue; end if;

    insert into notifications(type,to_email,to_role,lead_id,channel,subject,body,status)
    values ('doc_final_notice', v_to, 'supplier', rec.id, 'email',
      'Final reminder: your ' || v_label || ' expires on ' || v_exp,
      'Dear ' || coalesce(rec.company_name,'supplier') || ',' || chr(10) || chr(10) ||
      'Your ' || v_label || ' on file with QuotesDone expires on ' || v_exp || '.' || chr(10) || chr(10) ||
      'If we do not have a valid copy by then, your account will be paused automatically and you will stop receiving customer requests until it is renewed. This is temporary and there is no fee to restore it.' || chr(10) || chr(10) ||
      'Two ways to fix it, either is fine:' || chr(10) ||
      '  1. Reply to this email with the renewed document attached. Our system reads it and updates your profile automatically.' || chr(10) ||
      '  2. Upload it in the Documents tab of your supplier portal: https://quotesdone.com/portal' || chr(10) || chr(10) ||
      'If you have already renewed, please send us the latest copy so our records match.',
      'queued');
    v_email := v_email + 1;

    -- WhatsApp: queued for the same supplier when we hold a number. Delivery depends on the
    -- approved template described in the header comment.
    v_phone := nullif(trim(coalesce(rec.whatsapp, rec.phone)), '');
    if v_phone is not null then
      insert into notifications(type,to_email,to_role,lead_id,channel,to_phone,subject,body,status)
      values ('supplier_doc_expiry', v_to, 'supplier', rec.id, 'whatsapp', v_phone,
        'Your ' || v_label || ' expires on ' || v_exp,
        'Your ' || v_label || ' expires on ' || v_exp || '. Renew it to keep receiving QuotesDone requests: https://quotesdone.com/portal',
        'queued');
      v_wa := v_wa + 1;
    end if;
  end loop;

  return json_build_object('emails_queued', v_email, 'whatsapp_queued', v_wa,
                           'skipped', v_skipped, 'days_ahead', p_days,
                           'whatsapp_deliverable', false,
                           'whatsapp_note', 'Queued but not deliverable until a supplier_doc_expiry template SID is registered in wa_template_sids.',
                           'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_doc_history(p_type text, p_id text)
 RETURNS TABLE(version integer, changed_fields text[], checksum text, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ select version, changed_fields, checksum, created_at from public.doc_versions
   where entity_type=p_type and entity_id=p_id order by version desc $function$


CREATE OR REPLACE FUNCTION public.fn_document_controller()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k record; v_health numeric; v_ret numeric; v_backup numeric; n int;
begin
  select * into k from document_kpis;
  v_ret := round(100.0*(k.total_documents - coalesce(k.past_retention,0))/nullif(k.total_documents,0),1);
  v_backup := case when coalesce(k.days_since_backup,999) <= 10 then 100 when coalesce(k.days_since_backup,999) <= 20 then 60 else 20 end;
  v_health := round(coalesce(k.ocr_coverage_pct,100)*0.30 + coalesce(v_ret,100)*0.35 + v_backup*0.20 + greatest(0,100-coalesce(k.oversized,0)*5)*0.15,1);

  insert into document_kpi_snapshots(snapshot_date,kpis) values (current_date, to_jsonb(k)||jsonb_build_object('doc_health',v_health))
    on conflict (snapshot_date) do update set kpis=excluded.kpis, created_at=now();

  -- recommendations (founder-visible; the Controller NEVER deletes a document on its own)
  perform doc_rec('past_retention', coalesce(k.past_retention,0) > 0, 'medium', 'Documents past retention period',
    k.past_retention||' document(s) are older than their retention class. Review for archival or deletion — the Controller flags only and never deletes on its own.',
    jsonb_build_array(
      'The retention class on each document is right. A document filed under the wrong class ages out early and appears here as safe to delete when it is not.',
      'Past retention means MAY be deleted, never MUST. A document under an open dispute, refund claim or regulatory query outlives its class, and this rule cannot see any of those.',
      'Nothing else depends on these files: a quote PDF, a signed T&C or a redacted drawing still referenced by a live RFQ would read identically here.'),
    'Reviewing '||coalesce(k.past_retention,0)||' document(s) keeps the retention promise made to customers in the T&C, which is a commitment and not housekeeping. It also lifts the retention component of doc_health, currently weighted 0.35.',
    'No spend; storage saved is negligible at this size. The real cost is asymmetric and one-way: deleting a document that was still needed cannot be undone, which is why this routine only ever flags.');

  perform doc_rec('ocr_backlog', coalesce(k.ocr_backlog,0) > 0, 'low', 'Documents pending OCR/processing',
    k.ocr_backlog||' registered document(s) are not fully processed/extracted. Re-run the doc processing pipeline.',
    jsonb_build_array(
      'These are processable. A scanned photograph, a CAD original or a password-protected PDF will never extract, and re-running the pipeline on them produces the same backlog tomorrow.',
      'The backlog is pipeline lag, not a pipeline that has stopped — this rule counts unprocessed documents and cannot tell a queue from an outage.'),
    'Extracted text is what makes a document findable and quotable; until then '||coalesce(k.ocr_backlog,0)||' document(s) are stored but effectively invisible to every search and every agent that reads them.',
    'Model spend, small and per document. Re-running on files that can never extract is the wasteful case, which is what the first assumption is there to catch.');

  perform doc_rec('backup_stale', coalesce(k.days_since_backup,999) > 10, 'high', 'Backup may be stale',
    'The last backup to the backups bucket was '||coalesce(k.days_since_backup::text,'never')||' day(s) ago. Confirm the weekly Dropbox backup job is running.',
    jsonb_build_array(
      'An object in the backups bucket means a GOOD backup. This rule reads the newest object''s age and never opens it, so a job writing a truncated or empty archive on schedule looks perfectly healthy.',
      'coalesce(days_since_backup, 999) treats "never backed up" as 999 days rather than as unknown — deliberately, because for a backup the safe reading of no evidence is the alarming one.',
      'The Dropbox side is reachable. A backup written locally but never mirrored still ages this counter correctly and still leaves nothing off-site.'),
    'This is the only rule here that protects against total loss. Everything else on this board is tidiness; a stale backup means a bad day becomes an unrecoverable one.',
    'No spend — the backup job and the Dropbox quota are already paid for. The cost of being wrong is the entire company''s records.');

  perform doc_rec('oversized', coalesce(k.oversized,0) > 0, 'low', 'Oversized files',
    k.oversized||' file(s) exceed 30MB. Consider compressing or archiving to control storage cost.',
    jsonb_build_array(
      'Size is a proxy for waste. A 40MB drawing set is large because it is a drawing set, and compressing it can destroy exactly the detail a supplier needs to price the job.',
      '30MB is a chosen threshold, not a limit anything enforces — nothing breaks at 31MB.'),
    'Marginal. At this volume the storage saving is pennies; the honest value is spotting an upload path that is storing something it should not, such as an unresized original.',
    'No spend. Compressing costs engineering time and risks degrading a customer''s drawing, which is why this is the lowest-risk item on the board and stays a suggestion.');

  select count(*) into n from agent_actions where agent='document_controller' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at',now(),'doc_health',v_health,'kpis',to_jsonb(k),'open_tasks',n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_dropbox_list(p_prefix text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'prefix', p_prefix,
    'items', coalesce((
      select jsonb_agg(to_jsonb(t) order by t.is_folder desc, lower(t.name))
      from (
        select id, path, name, is_folder, size, server_modified
        from dropbox_files
        where substring(path, 1, length(path) - length(split_part(path,'/', -1)) - 1) = p_prefix
      ) t
    ), '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_dues_to_escalate(p_days integer)
 RETURNS TABLE(due_id bigint, supplier_id bigint, principal numeric, currency text, reveal_date date, due_date date, days_overdue integer, company_name text, contact_name text, email text, phone text, trade_license_no text, emirate text, category text, signed_terms_path text, claimed_by text, accepted_terms_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select d.id, d.supplier_id, d.amount_due, coalesce(d.currency,'AED'), d.reveal_date, d.due_date::date,
         (current_date - d.due_date::date) as days_overdue,
         l.company_name, l.contact_name, coalesce(l.claimed_by,l.email) as email, coalesce(l.phone_e164,l.phone),
         l.trade_license_no, l.emirate,
         coalesce(nullif(btrim(split_part(coalesce(l.categories,''),',',1)),''), nullif(l.sector,''),'Uncategorized') as category,
         l.signed_terms_path, l.claimed_by, l.accepted_terms_at
  from public.supplier_dues d
  join public.leads l on l.id = d.supplier_id
  where d.status not in ('paid','waived','cancelled','legal')
    and d.legal_escalated_at is null
    and coalesce(d.amount_due,0) > 0
    and current_date >= add_working_days(d.due_date::date, p_days);
$function$


CREATE OR REPLACE FUNCTION public.fn_ea_agenda(p_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'as_of', now(),
    'today', jsonb_build_object(
      'events', coalesce((select jsonb_agg(jsonb_build_object('id',id,'kind',kind,'title',title,'starts_at',starts_at,'location',location,'attendees',attendees) order by starts_at)
          from ea_events where status='scheduled' and coalesce(starts_at, now())::date = current_date),'[]'::jsonb),
      'reminders_due', coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'remind_at',remind_at) order by remind_at)
          from ea_reminders where not done and remind_at <= now()+interval '1 day'),'[]'::jsonb)
    ),
    'upcoming_events', coalesce((select jsonb_agg(jsonb_build_object('id',id,'kind',kind,'title',title,'starts_at',starts_at,'location',location) order by starts_at)
        from ea_events where status='scheduled' and starts_at > current_date and starts_at <= (current_date + (p_days||' days')::interval)),'[]'::jsonb),
    'open_tasks', coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'priority',priority,'due',due_date,'source',source) order by (due_date is null), due_date)
        from (select * from crm_tasks where coalesce(status,'open') not in ('done','cancelled') order by (due_date is null), due_date limit 15) t),'[]'::jsonb),
    'overdue_tasks', (select count(*) from crm_tasks where coalesce(status,'open') not in ('done','cancelled') and due_date < now()),
    'approvals_to_clear', jsonb_build_object(
      'total',(select count(*) from agent_actions where status in ('pending','needs_review')),
      'high_risk',(select count(*) from agent_actions where status in ('pending','needs_review') and coalesce(risk,'') in ('high','critical')),
      'top', coalesce((select jsonb_agg(jsonb_build_object('agent',agent,'title',title,'risk',risk,
            'reason', coalesce(nullif(btrim(recommendation),''), nullif(btrim(escalation_reason),''), 'queued for founder review: ' || coalesce(kind,'action')),
            'policies', public.fn_action_policies(kind, confidence),
            'confidence', confidence,
            'os', public.fn_owning_os(agent),
            'alternatives', (select d.alternatives from public.decision_log d where d.id = decision_log_id),
            'outcome', case when decided_at is not null
                 then coalesce(status,'decided') || ' by ' || coalesce(decided_by,'the system') || ' on ' || decided_at::date
                 else 'still open, no decision recorded since ' || created_at::date end)
          order by (coalesce(risk,'')='high') desc, created_at desc)
          from (select * from agent_actions where status in ('pending','needs_review') order by (coalesce(risk,'')='high') desc, created_at desc limit 8) a),'[]'::jsonb)
    ),
    'recent_meetings', coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'meeting_at',meeting_at,'summary',left(summary,240)) order by meeting_at desc)
        from (select * from ea_meetings order by meeting_at desc limit 5) m),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ea_assistant()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_agenda jsonb; n_rem int:=0; n_nudge int:=0; rec record;
begin
  v_agenda := fn_ea_agenda(7);
  insert into ea_snapshots(snapshot_date, agenda) values (current_date, v_agenda)
    on conflict (snapshot_date) do update set agenda=excluded.agenda, created_at=now();

  -- mark due reminders as notified (they surface in the agenda; internal only)
  update ea_reminders set notified_at=now() where not done and remind_at <= now() and notified_at is null;
  select count(*) into n_rem from ea_reminders where not done and remind_at <= now();

  -- nudge: overdue tasks/follow-ups -> founder-visible EA reminder action (de-duped daily)
  if (select count(*) from crm_tasks where coalesce(status,'')<>'done' and due_date < now()) > 0
     and not exists (select 1 from agent_actions where agent='executive_assistant' and detail->>'signal'='overdue_followups' and status in ('pending','needs_review') and created_at::date=current_date) then
    insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id)
    values('executive_assistant','handoff','pending','low','Overdue follow-ups need your attention',
      (select count(*)::text from crm_tasks where coalesce(status,'')<>'done' and due_date < now())||' task(s)/follow-up(s) are past due. Review your open items in the agenda.',
      jsonb_build_object('signal','overdue_followups'),'ea','overdue');
    n_nudge:=1;
  end if;

  return jsonb_build_object('ran_at',now(),'reminders_due',n_rem,'nudged',n_nudge,'agenda',v_agenda);
end $function$


CREATE OR REPLACE FUNCTION public.fn_edge_health_scan()
 RETURNS TABLE(fn_key text, verdict text, silent_minutes numeric, opened_incident boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r            record;
  v_beat       timestamptz;
  v_silent     numeric;
  v_verdict    text;
  v_note       text;
  v_open       boolean;
  v_title      text;
  v_platform   jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_platform
  from (
    select coalesce(headers->>'sb-error-code', 'status_' || coalesce(status_code::text,'null')) as code,
           count(*) as n
    from net._http_response
    where created > timezone('utc', now()) - interval '30 minutes'
      and (status_code is null or status_code < 200 or status_code >= 300)
    group by 1 order by 2 desc limit 10
  ) x;

  for r in select * from edge_expectation where active order by fn_key loop
    v_beat := null; v_note := null; v_open := false;
    begin
      execute r.heartbeat_sql into v_beat;
    exception when others then
      v_verdict := 'PROBE FAILED';
      v_note := 'heartbeat_sql could not be evaluated: ' || left(sqlerrm, 200);
    end;

    if v_note is null then
      v_silent := case when v_beat is null then null
                       else round(extract(epoch from (now() - v_beat)) / 60.0, 1) end;
      v_verdict := case
        when v_beat is null then 'STALE'
        when v_silent > r.max_silence_minutes then 'STALE'
        else 'ALIVE' end;
    else
      v_silent := null;
    end if;

    insert into edge_health_probe (fn_key, last_beat_at, silent_minutes, verdict, note)
    values (r.fn_key, v_beat, v_silent, v_verdict, v_note);

    if v_verdict <> 'ALIVE' then
      v_title := 'Silent failure: ' || r.fn_key || ' has produced no effect for ' ||
                 coalesce(v_silent::text || ' minutes', 'an unknown period') ||
                 ' (threshold ' || r.max_silence_minutes || ')';

      if not exists (
        select 1 from os_incidents
        where status = 'open' and detail->>'fn_key' = r.fn_key
      ) then
        insert into os_incidents (title, kind, severity, status, detail, opened_by)
        values (
          left(v_title, 300), 'silent_failure', r.severity, 'open',
          jsonb_build_object(
            'fn_key', r.fn_key,
            'cron_jobname', r.cron_jobname,
            'purpose', r.purpose,
            'blast_radius', r.blast_radius,
            'last_beat_at', v_beat,
            'silent_minutes', v_silent,
            'threshold_minutes', r.max_silence_minutes,
            'probe_note', v_note,
            'platform_errors_30m', v_platform,
            'detected_by', 'fn_edge_health_scan'),
          'edge_health_watchdog');
        v_open := true;

        insert into org_tasks (dept_key, title, detail, status, tier, action_class, needs_founder)
        values (
          coalesce(r.dept_key, 'technology'),
          left(v_title, 300),
          r.purpose || E'\n\nWhat breaks while this stays down: ' || r.blast_radius ||
          E'\n\nLast observed effect: ' || coalesce(v_beat::text, 'never') ||
          E'\nCron job: ' || coalesce(r.cron_jobname, 'unknown') ||
          E'\nSeverity: ' || r.severity ||
          E'\nPlatform error codes in the last 30 minutes: ' || v_platform::text ||
          E'\n\nNote: this was detected by watching the capability''s EFFECT, not its logs. ' ||
          'A function killed by the platform (546 WORKER_RESOURCE_LIMIT, OOM, timeout) never ' ||
          'reaches its own error handler, so agent_runs will look clean. Check ' ||
          'net._http_response and the edge function logs directly.',
          'proposed', 'supervised', 'investigate',
          -- a dark backup or a dark availability probe is founder-visible, not just a ticket
          (r.severity = 'high'));
      end if;
    else
      update os_incidents
         set status = 'resolved', resolved_at = now(), resolved_by = 'edge_health_watchdog',
             resolution = 'Capability resumed producing effects; last beat ' || coalesce(v_beat::text,'?')
       where status = 'open' and detail->>'fn_key' = r.fn_key;
      update org_tasks
         set status = 'done', updated_at = now(),
             result = coalesce(result,'{}'::jsonb) || jsonb_build_object('auto_closed','capability recovered','last_beat_at', v_beat)
       where status in ('proposed','assigned','in_progress')
         and action_class = 'investigate'
         and title like 'Silent failure: ' || r.fn_key || ' %';
    end if;

    fn_key := r.fn_key; verdict := v_verdict; silent_minutes := v_silent; opened_incident := v_open;
    return next;
  end loop;
end $function$


CREATE OR REPLACE FUNCTION public.fn_edit_inquiry(p_inquiry uuid, p_customer uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v inquiries%rowtype; v_paid boolean; v_deadline timestamptz;
  v_material boolean := false; v_reason text; v_stale int := 0; v_notified int := 0;
  v_cust_email text; v_admin text;
begin
  select * into v from inquiries where id=p_inquiry;
  if not found then return jsonb_build_object('error','inquiry_not_found'); end if;
  if p_customer is not null and v.customer_id is distinct from p_customer then
    return jsonb_build_object('error','not_your_inquiry'); end if;
  select exists(select 1 from transactions where inquiry_id=p_inquiry) into v_paid;
  if v_paid or v.status in ('revealed','completed','cancelled','closed') or v.pipeline_stage in ('revealed','won','cancelled') then
    return jsonb_build_object('error','not_editable','status',v.status,
      'message','This request can no longer be edited.'); end if;
  v_deadline := v.created_at + interval '1 hour';
  if now() > v_deadline then
    return jsonb_build_object('error','edit_window_closed','editable_until',v_deadline,
      'message','Inquiries can be edited within 1 hour of submitting. Please create a new request for changes after that.'); end if;

  -- Decide materiality BEFORE the update, while the old row is still in hand.
  v_material :=
       (p_patch ? 'spec'       and (p_patch->'spec')       is distinct from v.spec)
    or (p_patch ? 'boq'        and (p_patch->'boq')        is distinct from v.boq)
    or (p_patch ? 'budget'     and (p_patch->>'budget')    is distinct from v.budget)
    or (p_patch ? 'scope_type' and (p_patch->>'scope_type') is distinct from v.scope_type)
    or (p_patch ? 'emirate'    and (p_patch->>'emirate')   is distinct from v.emirate)
    or (p_patch ? 'trades'     and array(select jsonb_array_elements_text(p_patch->'trades')) is distinct from v.trades);

  update inquiries set
    summary   = coalesce(p_patch->>'summary', summary),
    raw_input = coalesce(p_patch->>'raw_input', raw_input),
    budget    = coalesce(p_patch->>'budget', budget),
    emirate   = coalesce(p_patch->>'emirate', emirate),
    scope_type= coalesce(p_patch->>'scope_type', scope_type),
    spec      = case when p_patch ? 'spec' then p_patch->'spec' else spec end,
    boq       = case when p_patch ? 'boq' then p_patch->'boq' else boq end,
    trades    = case when p_patch ? 'trades' then array(select jsonb_array_elements_text(p_patch->'trades')) else trades end,
    keywords  = case when p_patch ? 'keywords' then array(select jsonb_array_elements_text(p_patch->'keywords')) else keywords end
    where id=p_inquiry;

  if v_material then
    v_reason := 'The customer changed the requirements of this request on '
             || to_char(now() at time zone 'Asia/Dubai','DD Mon YYYY HH24:MI')
             || ' (Dubai), after this quote was submitted.';

    -- Stale the live quotes and tell each supplier, in one statement so a quote can never be
    -- reverted without its supplier being told.
    with staled as (
      update quotes q
         set stale_at = now(), stale_reason = v_reason, status = 'draft'
       where q.inquiry_id = p_inquiry
         and q.stale_at is null
         and coalesce(q.status,'') in ('submitted','draft')
      returning q.id, q.supplier_id
    ),
    told as (
      insert into notifications(type, to_email, to_role, lead_id, inquiry_id, quote_id, channel, subject, body, status)
      select 'quote_requirements_changed',
             coalesce(l.claimed_by, l.email), 'supplier', s.supplier_id, p_inquiry, s.id, 'email',
             'The customer changed this request — please re-quote',
             'Hello ' || coalesce(l.company_name,'') || ',' || chr(10) || chr(10) ||
             'A customer has changed the requirements of a request you had already quoted, so your quote has been set back to draft and is no longer being shown to them.' || chr(10) || chr(10) ||
             v_reason || chr(10) || chr(10) ||
             'Please open the request in your supplier portal, review what changed, and submit an updated quote. Your original figures are still there — nothing has been deleted.' || chr(10) || chr(10) ||
             'QuotesDone',
             'queued'
        from staled s join leads l on l.id = s.supplier_id
       where coalesce(l.claimed_by, l.email) is not null
      returning 1
    )
    select (select count(*) from staled), (select count(*) from told) into v_stale, v_notified;

    if v_stale > 0 then
      select email into v_cust_email from customers where id = v.customer_id;
      v_admin := coalesce((select split_part(value,',',1) from app_secrets where key='admin_emails'),
                          'management@quotesdone.com');

      -- The customer must know their edit cost them their quotes, or they will wait for prices
      -- that are never coming back on their own.
      if v_cust_email is not null then
        insert into notifications(type, to_email, to_role, inquiry_id, channel, subject, body, status)
        values ('inquiry_edit_staled_quotes', v_cust_email, 'customer', p_inquiry, 'email',
                'Your change means we have asked for fresh prices',
                'Hello,' || chr(10) || chr(10) ||
                'You changed the requirements on your request, so the ' || v_stale ||
                ' quote(s) already submitted no longer match what you are asking for. We have asked those suppliers to re-quote against your updated requirements.' || chr(10) || chr(10) ||
                'You do not need to do anything — the new prices will appear as they arrive.' || chr(10) || chr(10) ||
                'QuotesDone', 'queued');
      end if;

      insert into agent_actions(agent, kind, status, risk, title, recommendation, detail, target_table, target_id)
      values ('procurement','requote_required','needs_review','medium',
              'Requirements changed after ' || v_stale || ' quote(s) were submitted',
              'Watch that the invited suppliers actually re-quote. If they do not, the customer is left with a request that had prices and now has none.',
              jsonb_build_object('inquiry_id', p_inquiry, 'quotes_staled', v_stale,
                                 'suppliers_notified', v_notified, 'changed_at', now()),
              'inquiries', p_inquiry::text);
    end if;
  end if;

  return jsonb_build_object('ok',true,'edited',true,'editable_until',v_deadline,
                            'material_change', v_material,
                            'quotes_staled', v_stale,
                            'suppliers_notified', v_notified);
end $function$


CREATE OR REPLACE FUNCTION public.fn_email_sendable(p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_e text; v_pat record; v_dom text;
begin
  v_e := lower(btrim(coalesce(p_email,'')));
  if v_e = '' then
    return jsonb_build_object('ok', false, 'reason', 'no address');
  end if;
  if v_e !~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+[.][A-Za-z]{2,}$' then
    return jsonb_build_object('ok', false, 'reason', 'not a valid address shape');
  end if;
  if exists (select 1 from email_suppressions s where lower(s.email) = v_e) then
    return jsonb_build_object('ok', false, 'reason', 'suppressed');
  end if;
  v_dom := split_part(v_e, '@', 2);
  if exists (select 1 from email_domain_mx m
              where m.domain = v_dom and m.has_mx = false
                and m.kind in ('nxdomain','no_records')) then
    return jsonb_build_object('ok', false, 'reason', 'domain does not accept mail');
  end if;
  for v_pat in select pattern, reason from email_block_pattern where active loop
    if v_e ~ v_pat.pattern then
      return jsonb_build_object('ok', false, 'reason', v_pat.reason);
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'reason', 'sendable');
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_emit(p_event_type text, p_entity_type text, p_entity_id text, p_actor text DEFAULT 'system'::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id bigint;
begin
  -- correlation_id and causation_id are deliberately NOT named here. They carry the column
  -- defaults, which read app.correlation_id / app.causation_event_id — so an event emitted inside
  -- fn_event_dispatch's loop joins the chain it came from, and one emitted from a cron starts its
  -- own. Naming them here would override that and silently break the chain.
  insert into company_event (event_type, entity_type, entity_id, actor, payload)
  values (p_event_type, p_entity_type, p_entity_id, coalesce(p_actor,'system'), coalesce(p_payload,'{}'::jsonb))
  returning id into v_id;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_emit_budget_exceeded(p_dept text, p_amount numeric, p_requested_by text, p_purpose text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  v := fn_check_spend(p_dept, p_amount, p_requested_by);
  if not coalesce((v->>'affordable')::boolean, true) then
    insert into company_event (event_type, entity_type, entity_id, actor, payload)
    values ('budget.exceeded','department', p_dept, coalesce(p_requested_by,'system'),
            jsonb_build_object('requested_aed', p_amount, 'available_aed', v->>'available_aed',
                               'purpose', p_purpose, 'reason', v->>'reason'));
  end if;
  return v;
end; $function$


