CREATE OR REPLACE FUNCTION public.fn_employee_kpi_measure()
 RETURNS TABLE(measured integer, failed integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n_ok int := 0; n_bad int := 0;
begin
  create temporary table if not exists _kpi_now on commit drop as
    select kpi_id, agent_key, actual, target, unit, attainment, verdict from fn_kpi_scoreboard();

  update employee_kpi k
     set actual_value = s.actual,
         measured_at  = case when s.actual is null then null else now() end
    from _kpi_now s where s.kpi_id = k.id;

  insert into employee_kpi_history
    (kpi_id, agent_key, actual_value, target_value, unit, attainment, verdict)
  select s.kpi_id, s.agent_key, s.actual, s.target, s.unit, s.attainment, s.verdict
    from _kpi_now s
  on conflict (kpi_id, measured_on) do update
    set actual_value = excluded.actual_value,
        target_value = excluded.target_value,
        unit         = excluded.unit,
        attainment   = excluded.attainment,
        verdict      = excluded.verdict,
        measured_at  = now();

  select count(*) filter (where measured_at is not null),
         count(*) filter (where measured_at is null and coalesce(measure_sql,'') <> '')
    into n_ok, n_bad
    from employee_kpi where active;
  return query select n_ok, n_bad;
end $function$


CREATE OR REPLACE FUNCTION public.fn_employee_kpi_trend(p_agent_key text, p_days integer DEFAULT 90)
 RETURNS TABLE(kpi text, unit text, observations bigint, first_value numeric, latest_value numeric, direction text, latest_verdict text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with h as (
    select k.kpi, h.kpi_id, h.actual_value, h.unit, h.verdict, h.measured_on,
           first_value(h.actual_value) over w_asc  as first_v,
           first_value(h.actual_value) over w_desc as latest_v,
           first_value(h.verdict)      over w_desc as latest_verdict,
           row_number()                over w_desc as rn,
           count(*)                    over (partition by h.kpi_id) as n
      from employee_kpi_history h
      join employee_kpi k on k.id = h.kpi_id
     where h.agent_key = coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key)
       and h.measured_on > (now() at time zone 'utc')::date - p_days
       and h.actual_value is not null
    window w_asc  as (partition by h.kpi_id order by h.measured_on),
           w_desc as (partition by h.kpi_id order by h.measured_on desc)
  )
  select kpi, unit, n,
         first_v, latest_v,
         case when n < 2 or first_v is null or latest_v is null then 'no trend yet'
              when latest_v = first_v then 'flat'
              when (unit = 'percent_max') = (latest_v < first_v) then 'improving'
              else 'worsening' end,
         latest_verdict
    from h where rn = 1
   order by kpi;
$function$


CREATE OR REPLACE FUNCTION public.fn_employee_responsibilities_backfill()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_txt text; v_kpi text; v_obj text; v_n int := 0;
begin
  for r in select a.agent_key, a.role, a.title, a.seniority, a.department, a.manager_key
             from org_agents a
            where a.active and coalesce(btrim(a.responsibilities),'') = ''
  loop
    select string_agg('- '||k.kpi||' (target '||coalesce(k.target_value::text,'?')||' '
                      ||coalesce(k.unit,'')||', '||coalesce(k.cadence,'ongoing')||')', E'\n' order by k.kpi)
      into v_kpi from employee_kpi k where k.agent_key = r.agent_key and k.active;

    select string_agg('- '||d.objective, E'\n' order by d.sort, d.id)
      into v_obj from department_objective d where d.dept_key = r.department and d.active;

    v_txt := coalesce(r.role, r.title, r.agent_key)
      || case when r.seniority is not null then E'\n\nSeniority: '||r.seniority else '' end
      || case when r.manager_key is not null then '. Reports to: '||r.manager_key else '' end
      || case when v_kpi is not null then E'\n\nYou are measured on:\n'||v_kpi else '' end
      || case when v_obj is not null then E'\n\nYour department exists to:\n'||v_obj else '' end
      || E'\n\nYou own the operational decisions inside this scope. When the answer is not in your'
      || ' knowledge, retrieve it, consult the specialist who holds it, or raise a knowledge-gap'
      || ' task - never answer from a guess.';

    update org_agents set responsibilities = v_txt where agent_key = r.agent_key;
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('written', v_n,
    'note', 'Composed from role, title, seniority, manager, live employee_kpi rows and the department''s objectives. Blanks only; never overwrites.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_employee_scorecard(p_agent_key text, p_max_chars integer DEFAULT 1400)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_cap  int := greatest(coalesce(p_max_chars, 1400), 300);
  v_out  text := '';
  v_line text;
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  if coalesce(btrim(p_agent_key),'') = '' then return null; end if;

  -- YOUR NUMBER. attainment mirrors fn_kpi_scoreboard exactly, including the percent_max
  -- inversion; it is NOT recomputed with a different rule, because two rules that must agree is
  -- how sec() and J() ended up with 8 and 11 variants of the same helper.
  -- An unmeasured KPI says so in words. It must never read as a zero.
  select string_agg(
           '- '||z.kpi||': target '||coalesce(z.target_value::text,'?')||' '||coalesce(z.unit,'')
           ||case
               when z.actual_value is null then ' — NOT MEASURED YET (no number exists; do not assume one)'
               else ' — you are at '||z.actual_value::text
                    ||case when z.target_value is null then ''
                    when z.target_value = 0 then
                      case when z.actual_value <= 0 then ', at the zero-defect target (MET)'
                           else ', against a target of ZERO (MISSED)' end
                           when z.unit = 'percent_max'
                             then ', '||round(least(100.0, 100.0 * z.target_value / nullif(z.actual_value,0)),0)::text||'% of target'
                           else ', '||round(100.0 * z.actual_value / z.target_value,0)::text||'% of target' end
                    ||case
                        when z.target_value is null or z.target_value = 0 then ''
                        when z.unit = 'percent_max' then
                          case when z.actual_value <= z.target_value then ' (MET)' else ' (MISSED)' end
                        else
                          case when z.actual_value >= z.target_value then ' (MET)'
                               when z.actual_value >= 0.9 * z.target_value then ' (NEAR)'
                               else ' (MISSED)' end end
             end
           ||case when z.serves_goal is not null then ' — serves company goal '||z.serves_goal else '' end,
           E'\n' order by z.kpi)
    into v_line
    from (select k.kpi, k.target_value, k.unit, k.actual_value, k.serves_goal
            from employee_kpi k
           where k.agent_key = p_agent_key and k.active
           order by k.kpi limit 8) z;

  if v_line is not null then
    v_out := v_out || E'\n# YOUR NUMBER RIGHT NOW — measured, not asserted\n' || v_line || E'\n';
  end if;

  -- YOUR DEPARTMENT'S OBJECTIVE and the company goal it serves. This is the chain the founder
  -- described, delivered to the one employee that has to act on it.
  select string_agg(
           '- '||d.objective
           ||case when d.target_value is not null then ' (target '||d.target_value::text||' '||coalesce(d.unit,'')||')' else '' end
           ||case when d.actual_value is not null then ', department is at '||d.actual_value::text
                  when d.measure_sql is not null then ', not yet measured'
                  else '' end
           ||case when g.key is not null then E'\n    serves company goal '||g.key||' — "'||g.goal||'"' else '' end,
           E'\n' order by d.sort, d.id)
    into v_line
    from department_objective d
    join org_agents a on a.agent_key = p_agent_key and a.department = d.dept_key
    left join company_goals g on g.key = d.goal_key and g.active
   where d.active
   limit 6;

  if v_line is not null then
    v_out := v_out || E'\n# WHAT YOUR DEPARTMENT IS FOR\n' || v_line || E'\n';
  end if;

  if v_out = '' then return null; end if;
  return left(v_out, v_cap);
end $function$


CREATE OR REPLACE FUNCTION public.fn_enable_dropbox_sync()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare jid int; begin
  select jobid into jid from cron.job where jobname='dropbox_sync_daily';
  if jid is not null then perform cron.alter_job(jid, active:=true); return 'enabled'; end if;
  return 'not_found';
end $function$


CREATE OR REPLACE FUNCTION public.fn_enforce_rls_on_new_tables()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare r record;
begin
  for r in
    select object_identity, schema_name, object_type
    from pg_event_trigger_ddl_commands()
    where command_tag in ('CREATE TABLE','CREATE TABLE AS','SELECT INTO')
      and object_type = 'table'
      and schema_name = 'public'
  loop
    execute format('alter table %s enable row level security', r.object_identity);
  end loop;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_enqueue_doc_backups()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare n integer := 0; m integer;
begin
  with s as (
    select l.*,
      '/QuotesDone Backup/Suppliers/'
        || public.fn_dbx_category(l.id)
        || '/' || fn_dbx_safe(coalesce(l.company_name,'Supplier')) || ' (' || l.id || ')/' as base
    from public.leads l
    where l.approved_at is not null or l.registration_submitted_at is not null
       or l.signed_terms_path is not null or l.company_profile_doc_path is not null
       or l.license_doc_path is not null or coalesce(l.claimed,false)
  ),
  sd as (
    select s.id, s.base, v.doc_type, v.bucket, v.path
    from s cross join lateral (values
      ('Trade licence','supplier-docs', s.license_doc_path),
      ('Bank IBAN','supplier-docs', s.iban_doc_path),
      ('Establishment card','supplier-docs', s.egr_doc_path),
      ('Insurance','supplier-docs', s.insurance_doc_path),
      ('VAT certificate','supplier-docs', s.vat_doc_path),
      ('ISO certificate','supplier-docs', s.iso_doc_path),
      ('Manufacturer authorization','supplier-docs', s.manufacturer_auth_doc_path),
      ('Company profile','supplier-docs', s.company_profile_doc_path),
      ('Signed Terms & Conditions','signed-terms', s.signed_terms_path)
    ) v(doc_type,bucket,path)
    where v.path is not null and length(v.path)>0
  )
  insert into public.doc_backups(entity,entity_id,doc_type,bucket,path,file_name,dropbox_path,source,dedupe_key)
  select 'supplier', sd.id::text, sd.doc_type, sd.bucket, sd.path,
         regexp_replace(sd.path,'^.*/',''),
         sd.base || sd.doc_type || ' - ' || regexp_replace(sd.path,'^.*/',''),
         'storage', 'S:'||sd.id||':'||sd.doc_type||':'||sd.path
  from sd on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  insert into public.doc_backups(entity,entity_id,doc_type,bucket,path,file_name,dropbox_path,source,dedupe_key)
  select 'supplier', s.id::text, 'Catalogue', 'supplier-docs', cat,
         regexp_replace(cat,'^.*/',''), s.base || 'Catalogue - ' || regexp_replace(cat,'^.*/',''),
         'storage', 'S:'||s.id||':cat:'||cat
  from ( select l.id,
      '/QuotesDone Backup/Suppliers/'
        || public.fn_dbx_category(l.id)
        || '/' || fn_dbx_safe(coalesce(l.company_name,'Supplier')) || ' (' || l.id || ')/' as base, l.catalog_doc_paths
    from public.leads l
    where (l.approved_at is not null or l.registration_submitted_at is not null
       or l.signed_terms_path is not null or l.company_profile_doc_path is not null
       or l.license_doc_path is not null or coalesce(l.claimed,false)) and l.catalog_doc_paths is not null ) s,
    unnest(s.catalog_doc_paths) cat
  where cat is not null and length(cat)>0 on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  insert into public.doc_backups(entity,entity_id,doc_type,source,gen_kind,gen_ref,dropbox_path,dedupe_key)
  select 'supplier', s.id::text, 'Company Details','generated','supplier_details', s.id::text,
         s.base || 'Company Details.pdf', 'S:'||s.id||':details'
  from ( select l.id,
      '/QuotesDone Backup/Suppliers/'
        || public.fn_dbx_category(l.id)
        || '/' || fn_dbx_safe(coalesce(l.company_name,'Supplier')) || ' (' || l.id || ')/' as base
    from public.leads l
    where l.approved_at is not null or l.registration_submitted_at is not null
       or l.signed_terms_path is not null or l.company_profile_doc_path is not null
       or l.license_doc_path is not null or coalesce(l.claimed,false) ) s
  on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  insert into public.doc_backups(entity,entity_id,doc_type,bucket,path,file_name,dropbox_path,source,dedupe_key)
  select 'customer', c.id::text, 'Signed Terms & Conditions','signed-terms', c.signed_terms_path,
         regexp_replace(c.signed_terms_path,'^.*/',''),
         '/QuotesDone Backup/Customers/'||fn_dbx_safe(coalesce(c.full_name,'Customer'))||' ('||left(c.id::text,8)||')/Signed Terms & Conditions - '||regexp_replace(c.signed_terms_path,'^.*/',''),
         'storage', 'C:'||c.id||':terms:'||c.signed_terms_path
  from public.customers c where c.signed_terms_path is not null and length(c.signed_terms_path)>0
  on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  insert into public.doc_backups(entity,entity_id,doc_type,source,gen_kind,gen_ref,dropbox_path,dedupe_key)
  select 'customer', c.id::text, 'Customer Details','generated','customer_details', c.id::text,
         '/QuotesDone Backup/Customers/'||fn_dbx_safe(coalesce(c.full_name,'Customer'))||' ('||left(c.id::text,8)||')/Customer Details.pdf',
         'C:'||c.id||':details'
  from public.customers c on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  insert into public.doc_backups(entity,entity_id,doc_type,bucket,path,file_name,dropbox_path,source,dedupe_key)
  select 'inquiry', i.id::text, 'RFQ drawing','drawing-files', i.drawing_file_path,
         coalesce(i.drawing_file_name, regexp_replace(i.drawing_file_path,'^.*/','')),
         '/QuotesDone Backup/Customers/'||fn_dbx_safe(coalesce(c.full_name,'Customer'))||' ('||left(c.id::text,8)||')/Inquiries/'
           || to_char(i.created_at,'YYYY-MM-DD')||' '||left(i.id::text,8)||' - '||fn_dbx_safe(coalesce(i.status,'inquiry'))
           || '/Drawing - '||coalesce(i.drawing_file_name, regexp_replace(i.drawing_file_path,'^.*/','')),
         'storage', 'I:'||i.id||':drawing:'||i.drawing_file_path
  from public.inquiries i join public.customers c on c.id=i.customer_id
  where i.drawing_file_path is not null and length(i.drawing_file_path)>0
  on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  insert into public.doc_backups(entity,entity_id,doc_type,source,gen_kind,gen_ref,dropbox_path,dedupe_key)
  select 'inquiry', i.id::text, 'Inquiry Summary','generated','inquiry_summary', i.id::text,
         '/QuotesDone Backup/Customers/'||fn_dbx_safe(coalesce(c.full_name,'Customer'))||' ('||left(c.id::text,8)||')/Inquiries/'
           || to_char(i.created_at,'YYYY-MM-DD')||' '||left(i.id::text,8)||' - '||fn_dbx_safe(coalesce(i.status,'inquiry'))
           || '/Inquiry Summary.pdf', 'I:'||i.id||':summary'
  from public.inquiries i join public.customers c on c.id=i.customer_id
  on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  -- Quote comparison reports: one PDF per distinct quote-set (>=2 live quotes). Anonymized A/B/C.
  insert into public.doc_backups(entity,entity_id,doc_type,source,gen_kind,gen_ref,dropbox_path,dedupe_key)
  select 'inquiry', i.id::text, 'Quote Comparison','generated','comparison', i.id::text,
         '/QuotesDone Backup/Customers/'||fn_dbx_safe(coalesce(c.full_name,'Customer'))||' ('||left(c.id::text,8)||')/Inquiries/'
           || to_char(i.created_at,'YYYY-MM-DD')||' '||left(i.id::text,8)||' - '||fn_dbx_safe(coalesce(i.status,'inquiry'))
           || '/Quote Comparison Report '||to_char(now(),'YYYY-MM-DD')||' '||left(sig.sig,8)||'.pdf',
         'CMP:'||i.id||':'||sig.sig
  from public.inquiries i
  join public.customers c on c.id=i.customer_id
  join lateral ( select md5(coalesce(string_agg(q.quote_amount::text||':'||coalesce(q.status,''),'|' order by q.quote_amount),'')) as sig,
                        count(*) as nq
                 from public.quotes q where q.inquiry_id=i.id and q.status<>'draft' ) sig on true
  where sig.nq >= 2
  on conflict (dedupe_key) do nothing;
  get diagnostics m = row_count; n := n + m;

  return n;
end $function$


CREATE OR REPLACE FUNCTION public.fn_entity_activity(p_entity text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare out jsonb := '[]'::jsonb; l public.leads%rowtype;
begin
  -- comments (all entities)
  out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','comment','title','Comment','actor',c.author,'body',c.body,'at',c.created_at)) from public.entity_comments c where c.entity=p_entity and c.entity_id=p_id),'[]'::jsonb);
  -- audit trail (all entities)
  out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','audit','title',a.action,'actor',a.actor,'at',a.at,'ok',a.ok)) from public.os_audit_log a where a.entity_id=p_id and (a.entity=p_entity or (p_entity='supplier' and a.entity in ('leads','supplier','suppliers')))),'[]'::jsonb);
  if p_entity = 'supplier' then
    select * into l from public.leads where id = p_id::bigint;
    if l.id is not null then
      out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','agent','title',coalesce(nullif(btrim(aa.title),''), aa.kind),'actor',aa.agent,'body',aa.recommendation,'at',aa.created_at,'status',aa.status)) from public.agent_actions aa where aa.target_table='leads' and aa.target_id::text = p_id),'[]'::jsonb);
      out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','milestone','title',v.label,'actor','system','at',v.ts)) from (values
        ('Sourced', l.created_at),('Scraped', l.scraped_at),('Invited', l.invited_at),('AI reviewed', l.ai_reviewed_at),
        ('Documents extracted', l.doc_extracted_at),('Capability enriched', l.capability_enriched_at),
        ('Registration submitted', l.registration_submitted_at),('Terms accepted', l.accepted_terms_at),
        ('Terms signed', l.signed_terms_at),('Approved', l.approved_at)
      ) v(label, ts) where v.ts is not null),'[]'::jsonb);
    end if;
  end if;
  -- QD_RFQ_TRACE: the inquiry lifecycle, assembled from the rows that already record it.
  if p_entity in ('rfq','inquiry') and p_id ~ '^[0-9a-fA-F-]{36}$' then
    out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','milestone','title',v.label,'actor','system','at',v.ts))
      from public.inquiries i cross join lateral (values
             ('Inquiry created', i.created_at),
             ('Moved to stage: '||coalesce(i.pipeline_stage,'(none)'), i.stage_changed_at),
             ('Completed'||coalesce(' — '||i.outcome,''), i.completed_at)
           ) v(label, ts)
     where i.id = p_id::uuid and v.ts is not null),'[]'::jsonb);

    out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','decision',
        'title','Routed to category '||coalesce(i.category,'(none)')||
                case when coalesce(i.rfq_ready,false) then ' — brief complete' else ' — brief NOT complete' end,
        'actor','route_inquiry','body',left(coalesce(i.routing::text,''),400),'at',i.created_at))
      from public.inquiries i where i.id = p_id::uuid and i.routing is not null),'[]'::jsonb);

    out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','document',
        'title',coalesce(d.kind,'document')||' '||coalesce(d.file_name,''),'actor','doc_extract',
        'body','status '||coalesce(d.status,'?')||case when coalesce(d.indexed,false) then ', indexed' else '' end,
        'at',coalesce(d.processed_at,d.created_at)))
      from public.documents d where d.ref_table='inquiries' and d.ref_id::text = p_id),'[]'::jsonb);

    out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','match',
        'title','Dispatched to supplier #'||m.supplier_id||coalesce(' ('||ld.company_name||')',''),
        'actor','dispatch_inquiry',
        'body',coalesce(m.match_reason,'')||coalesce(' score '||m.similarity,''),'at',m.sent_at))
      from public.inquiry_matches m left join public.leads ld on ld.id = m.supplier_id
     where m.inquiry_id = p_id::uuid),'[]'::jsonb);

    out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','quote',
        'title','Quotation AED '||q.quote_amount||' from supplier #'||q.supplier_id,
        'actor',coalesce(q.source,'form'),
        'body','status '||coalesce(q.status,'?')||coalesce(', quality '||q.quality::text,''),
        'at',q.created_at,'status',q.status))
      from public.quotes q where q.inquiry_id = p_id::uuid),'[]'::jsonb);

    out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','comparison',
        'title','Quotation comparison produced','actor','quote_compare',
        'body',left(coalesce(c.explanation_en::text,''),400),'at',c.created_at))
      from public.comparison_run_v2 c where c.inquiry_id = p_id::uuid),'[]'::jsonb);

    out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','reveal',
        'title','Supplier revealed to the customer for AED '||t.reveal_fee,'actor','customer','at',t.revealed_at))
      from public.transactions t where t.inquiry_id = p_id::uuid and t.revealed_at is not null),'[]'::jsonb);

    out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','event','title',e.event_type,
        'actor',coalesce(e.actor,'system'),'at',e.occurred_at))
      from public.company_event e where e.entity_type in ('inquiry','inquiries') and e.entity_id = p_id),'[]'::jsonb);

    out := out || coalesce((select jsonb_agg(jsonb_build_object('kind','agent',
        'title',coalesce(nullif(btrim(aa.title),''), aa.kind),'actor',aa.agent,
        'body',aa.recommendation,'at',aa.created_at,'status',aa.status))
      from public.agent_actions aa where aa.target_table='inquiries' and aa.target_id::text = p_id),'[]'::jsonb);
  end if;


  -- CONFIGURATION ENTITIES. pricing_config, model_policy and prompts are changed by the company
  -- itself, and their history is the row-level change log rather than the action log. Without this
  -- branch "when did AI change pricing" had no reader at all.
  if p_entity in ('pricing_config','model_policy','prompts','config') then
    out := out || coalesce((select jsonb_agg(jsonb_build_object(
        'kind','change','title', u.op || ' on ' || u.table_name,
        'actor', coalesce(u.actor,'system'), 'at', u.created_at,
        'reverted', u.reverted, 'row_id', u.row_id) order by u.created_at desc)
      from (select * from public.undo_log u
             where u.table_name = p_entity
               and (coalesce(p_id,'') = '' or u.row_id::text = p_id)
             order by u.created_at desc limit 50) u), '[]'::jsonb);
  end if;

  return coalesce((select jsonb_agg(e) from (select e from jsonb_array_elements(out) e where (e->>'at') is not null order by (e->>'at') desc limit 80) z),'[]'::jsonb);
end $function$


CREATE OR REPLACE FUNCTION public.fn_entity_comment_add(p_entity text, p_id text, p_author text, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare r public.entity_comments%rowtype;
begin
  if coalesce(btrim(p_body),'') = '' then return jsonb_build_object('ok', false, 'error', 'empty'); end if;
  insert into public.entity_comments(entity, entity_id, author, body)
    values (p_entity, p_id, coalesce(nullif(btrim(p_author),''),'operator'), left(p_body, 4000))
    returning * into r;
  return jsonb_build_object('ok', true, 'id', r.id, 'at', r.created_at);
end $function$


CREATE OR REPLACE FUNCTION public.fn_entity_files(p_entity text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare out jsonb := '[]'::jsonb; l public.leads%rowtype;
begin
  if p_entity = 'supplier' then
    select * into l from public.leads where id = p_id::bigint;
    if l.id is not null then
      if l.license_doc_path is not null then out := out || jsonb_build_object('group','Compliance documents','type','Trade licence','name',coalesce(l.license_doc_name,'trade licence'),'bucket','supplier-docs','path',l.license_doc_path); end if;
      if l.iban_doc_path is not null then out := out || jsonb_build_object('group','Compliance documents','type','Bank / IBAN','name',coalesce(l.iban_doc_name,'iban letter'),'bucket','supplier-docs','path',l.iban_doc_path); end if;
      if l.egr_doc_path is not null then out := out || jsonb_build_object('group','Compliance documents','type','Establishment card','name',coalesce(l.egr_doc_name,'establishment card'),'bucket','supplier-docs','path',l.egr_doc_path); end if;
      if l.insurance_doc_path is not null then out := out || jsonb_build_object('group','Compliance documents','type','Insurance','name','insurance','bucket','supplier-docs','path',l.insurance_doc_path); end if;
      if l.vat_doc_path is not null then out := out || jsonb_build_object('group','Compliance documents','type','VAT certificate','name','vat certificate','bucket','supplier-docs','path',l.vat_doc_path); end if;
      if l.company_profile_doc_path is not null then out := out || jsonb_build_object('group','Compliance documents','type','Company profile','name','company profile','bucket','supplier-docs','path',l.company_profile_doc_path); end if;
      if l.signed_terms_path is not null then out := out || jsonb_build_object('group','Compliance documents','type','Signed terms','name','signed terms','bucket','signed-terms','path',l.signed_terms_path); end if;
      if l.catalog_doc_paths is not null then
        out := out || coalesce((select jsonb_agg(jsonb_build_object('group','Catalogues','type','Catalogue','name','catalogue','bucket','supplier-docs','path',x)) from unnest(l.catalog_doc_paths) x),'[]'::jsonb);
      end if;
      -- Storage scan: surface any stored documents whose column pointers are null (files live under <folder>/<supplier_id>/<file>).
      out := out || coalesce((
        select jsonb_agg(jsonb_build_object(
          'group', case when split_part(o.name,'/',1) in ('catalogs','catalogues') then 'Catalogues'
                        when o.bucket_id = 'signed-terms' then 'Signed terms'
                        else 'Compliance documents' end,
          'type', case split_part(o.name,'/',1)
                    when 'licence' then 'Trade licence' when 'license' then 'Trade licence' when 'licenses' then 'Trade licence'
                    when 'certs' then 'Certificate' when 'cert' then 'Certificate' when 'insurance' then 'Insurance'
                    when 'profile' then 'Company profile' when 'company_profile' then 'Company profile'
                    when 'catalogs' then 'Catalogue' when 'catalogues' then 'Catalogue'
                    when 'iban' then 'Bank / IBAN' when 'bank' then 'Bank / IBAN'
                    when 'vat' then 'VAT certificate' when 'egr' then 'Establishment card'
                    when 'terms' then 'Signed terms'
                    else initcap(replace(split_part(o.name,'/',1),'_',' ')) end,
          'name', regexp_replace(split_part(o.name,'/', greatest(array_length(string_to_array(o.name,'/'),1),1)), '^[0-9]+_', ''),
          'bucket', o.bucket_id,
          'path', o.name))
        from storage.objects o
        where o.bucket_id in ('supplier-docs','signed-terms')
          and split_part(o.name,'/',2) = p_id
          and not exists (select 1 from jsonb_array_elements(out) xx where xx->>'path' = o.name)
      ), '[]'::jsonb);
    end if;
    out := out || coalesce((select jsonb_agg(jsonb_build_object('group','Quotations submitted','type','Quote #'||q.id,'name',coalesce(q.original_file_name,'quote file'),'bucket','quote-files','path',q.original_file_path) order by q.created_at desc)
                            from public.quotes q where q.supplier_id = p_id::bigint and q.original_file_path is not null),'[]'::jsonb);

  elsif p_entity = 'customer' then
    out := out || coalesce((select jsonb_agg(jsonb_build_object('group','Drawings & RFQ files','type','RFQ drawing','name',coalesce(i.drawing_file_name,'drawing'),'bucket','drawing-files','path',i.drawing_file_path) order by i.created_at desc)
                            from public.inquiries i where i.customer_id = p_id::uuid and i.drawing_file_path is not null),'[]'::jsonb);
    out := out || coalesce((select jsonb_agg(jsonb_build_object('group','Quotations received','type','Quote #'||q.id,'name',coalesce(q.original_file_name,'quote file'),'bucket','quote-files','path',q.original_file_path) order by q.created_at desc)
                            from public.quotes q join public.inquiries i on i.id = q.inquiry_id where i.customer_id = p_id::uuid and q.original_file_path is not null),'[]'::jsonb);

  elsif p_entity in ('rfq','inquiry') then
    out := out || coalesce((select jsonb_agg(jsonb_build_object('group','Drawing','type','RFQ drawing','name',coalesce(i.drawing_file_name,'drawing'),'bucket','drawing-files','path',i.drawing_file_path))
                            from public.inquiries i where i.id = p_id::uuid and i.drawing_file_path is not null),'[]'::jsonb);
    out := out || coalesce((select jsonb_agg(jsonb_build_object('group','Quotations','type','Quote #'||q.id,'name',coalesce(q.original_file_name,'quote file'),'bucket','quote-files','path',q.original_file_path) order by q.created_at desc)
                            from public.quotes q where q.inquiry_id = p_id::uuid and q.original_file_path is not null),'[]'::jsonb);
  end if;
  return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_eval_run()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k jsonb;
begin
  k := public.fn_eval_snapshot(30);
  insert into public.agent_evals(window_days,kpis) values (30,k);
end $function$


CREATE OR REPLACE FUNCTION public.fn_eval_snapshot(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  intake_total int; intake_complete int; q_total int; q_scored int; q_pass numeric; q_avg numeric;
  inq_matched int; inq_all int; inq_done int; inq_open int; esc_pending int; esc_total int; lat_avg numeric;
  dec_total int; dec_grounded int; k jsonb;
begin
  select count(*) filter (where created_at > now()-(p_days||' days')::interval),
         count(*) filter (where created_at > now()-(p_days||' days')::interval and coalesce(rfq_ready,false))
    into intake_total, intake_complete from inquiries;
  select count(*) filter (where created_at > now()-(p_days||' days')::interval),
         count(*) filter (where created_at > now()-(p_days||' days')::interval and quality is not null),
         avg(nullif(quality->>'score','')::numeric) filter (where created_at > now()-(p_days||' days')::interval),
         count(*) filter (where created_at > now()-(p_days||' days')::interval and nullif(quality->>'score','')::numeric >= 60)
    into q_total, q_scored, q_avg, q_pass from quotes;
  select count(*) filter (where i.created_at > now()-(p_days||' days')::interval),
         count(*) filter (where i.created_at > now()-(p_days||' days')::interval and exists(select 1 from inquiry_matches m where m.inquiry_id=i.id))
    into inq_all, inq_matched from inquiries i;
  select count(*) filter (where created_at > now()-(p_days||' days')::interval and (status in ('completed','accepted','closed') or completed_at is not null)),
         count(*) filter (where created_at > now()-(p_days||' days')::interval) into inq_done, inq_open from inquiries;
  begin select count(*) filter (where created_at > now()-(p_days||' days')::interval and status='pending'), count(*) filter (where created_at > now()-(p_days||' days')::interval) into esc_pending, esc_total from agent_actions; exception when others then esc_pending:=0; esc_total:=0; end;
  begin select round(avg(extract(epoch from (finished_at-started_at)))::numeric,1) into lat_avg from agent_runs where started_at > now()-(p_days||' days')::interval and finished_at is not null; exception when others then lat_avg:=null; end;
  begin select count(*), count(*) filter (where jsonb_array_length(coalesce(sources,'[]'))>0) into dec_total, dec_grounded from decision_log where created_at > now()-(p_days||' days')::interval; exception when others then dec_total:=0; dec_grounded:=0; end;

  k := jsonb_build_object(
    'window_days', p_days,
    'rfq_completeness_pct', case when intake_total=0 then null else round(intake_complete::numeric/intake_total*100,1) end,
    'quote_gate_pass_pct',  case when q_scored=0 then null else round(q_pass::numeric/q_scored*100,1) end,
    'quote_quality_avg',    round(coalesce(q_avg,0),1),
    'match_coverage_pct',   case when inq_all=0 then null else round(inq_matched::numeric/inq_all*100,1) end,
    'resolution_pct',       case when inq_open=0 then null else round(inq_done::numeric/inq_open*100,1) end,
    'escalation_rate_pct',  case when esc_total=0 then null else round(esc_pending::numeric/esc_total*100,1) end,
    'agent_latency_sec_avg',lat_avg,
    'decision_grounding_pct', case when dec_total=0 then null else round(dec_grounded::numeric/dec_total*100,1) end,
    'clarification_efficiency', null, 'hallucination_rate_pct', null, 'customer_satisfaction', null,
    'samples', jsonb_build_object('inquiries',intake_total,'quotes',q_total,'agent_actions',esc_total,'decisions',dec_total));
  return k;
end $function$


CREATE OR REPLACE FUNCTION public.fn_event_consolidate()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record; v_outcome text; v_note text; v_backbone text; v_lesson bigint; v_sev text;
  n_closed int := 0; n_lessons int := 0; n_rollups int := 0; n_priorities int := 0;
  v_open_chains bigint := 0;
  -- Bounded like the dispatcher's batch, for the same reason: an unbounded first run on a backlog
  -- is how a burst happens.  The work is finite and the cron is hourly.
  c_max_close    constant int := 200;
  c_max_priority constant int := 25;
begin
  -- ── LINK 7 · the result comes back to the event that caused the work ────────────────────────
  -- A delivery whose task has closed but whose result column is still NULL is precisely the gap:
  -- the OS did the work and the event never heard.  org_tasks.result is the OS's own words; the
  -- status is the fallback when it closed without writing one.
  for r in
    select d.id as delivery_id, d.event_id, d.task_id, d.os_key,
           t.status, t.result, t.title, t.updated_at, e.correlation_id, e.event_type
      from event_delivery d
      join org_tasks t     on t.id = d.task_id
      join company_event e on e.id = d.event_id
     where d.closed_at is null and t.status in ('done','closed')
     order by d.id
     limit c_max_close
  loop
    update event_delivery
       -- ->> not nullif(...,''): org_tasks.result is jsonb and event_delivery.result is text.
       set result    = left(coalesce(nullif(r.result->>'summary',''),
                                     r.status || ': ' || coalesce(r.title,'')), 1000),
           closed_at = coalesce(r.updated_at, now())
     where id = r.delivery_id;
    n_closed := n_closed + 1;

    -- ── LINK 10 · Knowledge captures the lesson from an EVENT outcome ─────────────────────────
    -- Joined through event_delivery.task_id, which is what makes the lesson traceable to a
    -- dispatched event rather than to a task that arrived some other way.
    if not exists (select 1 from institutional_memory m
                    where m.subject_type = 'org_task' and m.subject_id = r.task_id::text) then
      v_lesson := public.fn_task_lesson(r.task_id, 'event_closed',
                    jsonb_build_object('event_type', r.event_type,
                                       'correlation_id', r.correlation_id::text,
                                       'os_key', r.os_key));
      if v_lesson is not null then n_lessons := n_lessons + 1; end if;
    end if;
  end loop;

  -- ── LINK 8 · the Chief of Staff consolidates ACROSS OSes ───────────────────────────────────
  -- One row per business episode, not per event: correlation_id is the episode.  os_count is the
  -- number of distinct Operating Systems the episode touched, which is the difference between a
  -- consolidation and a receipt.
  --
  -- LINK 4 IS READ HERE.  Each OS records an event_assessment — severity, impact, proposed action
  -- — before it raises a task, and until now nothing ever looked at one.  The episode's assessed
  -- severity travels with the consolidation into priority_note and into the priority.updated
  -- payload, so what the OSes said about impact reaches the person re-prioritising on it.
  for r in
    select e.correlation_id,
           min(e.id)                                        as root_event_id,
           (array_agg(e.event_type order by e.id))[1]       as root_type,
           count(distinct d.os_key)                         as os_count,
           count(d.task_id)                                 as tasks_total,
           count(*) filter (where d.closed_at is not null)   as tasks_closed,
           (select count(*) from event_assessment a
              join company_event ae on ae.id = a.event_id
             where ae.correlation_id = e.correlation_id)     as assessed,
           (select max(case a.severity when 'high' then 3 when 'medium' then 2 else 1 end)
              from event_assessment a
              join company_event ae on ae.id = a.event_id
             where ae.correlation_id = e.correlation_id)     as sev_rank
      from company_event e
      join event_delivery d on d.event_id = e.id
     where e.correlation_id is not null
     group by e.correlation_id
  loop
    -- Defence 2: never consolidate a chain a re-prioritisation started.
    if r.root_type = 'priority.updated' then continue; end if;

    v_outcome := case when r.tasks_total = 0                  then 'no_work'
                      when r.tasks_closed = 0                 then 'open'
                      when r.tasks_closed < r.tasks_total     then 'partial'
                      else 'closed' end;
    v_sev := case r.sev_rank when 3 then 'high' when 2 then 'medium' when 1 then 'low'
                             else 'unassessed' end;
    v_note := format('%s across %s OS: %s of %s task(s) closed. Impact: %s assessment(s), highest severity %s.',
                     r.root_type, r.os_count, r.tasks_closed, r.tasks_total,
                     coalesce(r.assessed,0), v_sev);

    insert into event_rollup (correlation_id, root_event_id, event_type, os_count,
                              tasks_total, tasks_closed, outcome, priority_note, consolidated_at)
    values (r.correlation_id, r.root_event_id, r.root_type, r.os_count,
            r.tasks_total, r.tasks_closed, v_outcome, v_note, now())
    on conflict (correlation_id) do update
      set os_count = excluded.os_count, tasks_total = excluded.tasks_total,
          tasks_closed = excluded.tasks_closed, outcome = excluded.outcome,
          priority_note = excluded.priority_note, consolidated_at = excluded.consolidated_at;
    n_rollups := n_rollups + 1;

    -- ── LINK 9 · the CEO re-prioritises off the consolidated outcome ──────────────────────────
    -- The episode must have crossed an OS boundary — a single-OS chain is that OS's own business
    -- and does not move company priorities — and at least one OS must have RETURNED something,
    -- because a priority cannot be revised against an outcome that does not exist yet.
    --   Deliberately not 'closed' only. Measured on production: all 22 cross-OS episodes sit at
    --   0/4 or 1/4 tasks closed, and one task that never closes would hold the whole episode — and
    --   the company's priorities — hostage forever. Link 9 says "off event OUTCOMES", not "off all
    --   of them". One re-prioritisation per episode either way: the dedupe is on correlation_id.
    if v_outcome in ('closed','partial') and r.os_count > 1 and n_priorities < c_max_priority
       and not exists (select 1 from company_event ce
                        where ce.event_type = 'priority.updated'
                          and ce.correlation_id = r.correlation_id) then
      -- xos-14. This event is CAUSED by the root of the chain and belongs to the same chain. The
      -- settings are read by company_event's column defaults, which is why fn_emit does not name
      -- either column.  Defence 1 lives here: same correlation_id => the `not exists` above is
      -- permanently true for this episode from the next run onward.
      perform set_config('app.correlation_id',      r.correlation_id::text, true);
      perform set_config('app.causation_event_id',  r.root_event_id::text,  true);
      perform public.fn_emit('priority.updated', 'event_chain', r.correlation_id::text, 'ceo',
                jsonb_build_object('root_event_id', r.root_event_id, 'root_type', r.root_type,
                                   'os_count', r.os_count, 'tasks_closed', r.tasks_closed,
                                   'assessments', coalesce(r.assessed,0), 'max_severity', v_sev,
                                   'note', v_note));
      perform set_config('app.correlation_id',     '', true);
      perform set_config('app.causation_event_id', '', true);
      n_priorities := n_priorities + 1;
    end if;
  end loop;

  -- The Knowledge OS's declared output. One per run rather than one per lesson: the bus carries
  -- the fact that institutional memory moved, not 58 copies of it.
  if n_lessons > 0 then
    perform public.fn_emit('knowledge.updated', 'institutional_memory', 'event_lessons',
              'knowledge_director', jsonb_build_object('lessons_added', n_lessons));
  end if;

  -- ── xos-15 · somebody looks at the bus ─────────────────────────────────────────────────────
  -- v_event_backbone is the one surface that says which subscribed event types are live, which
  -- have never fired and which are undelivered.  It had zero readers, which made it a diagram.
  -- chains_open is the consolidation backlog the view now carries: episodes that reached an OS
  -- and have not finished.  Reported here so the number lands in agent_runs rather than only in
  -- the view definition.
  select coalesce(string_agg(event_type || ' ' || state, ', ' order by event_type),
                  'every subscribed event type is LIVE')
    into v_backbone
    from v_event_backbone where state <> 'LIVE';

  select coalesce(sum(chains_open), 0) into v_open_chains from v_event_backbone;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('event_consolidate', now(), now(), 'ok',
          jsonb_build_object('deliveries_closed', n_closed, 'lessons', n_lessons,
                             'rollups', n_rollups, 'priorities_emitted', n_priorities,
                             'chains_open', v_open_chains),
          'Cross-OS contract closed: ' || n_closed || ' delivery result(s) returned, ' || n_lessons
          || ' lesson(s) captured, ' || n_rollups || ' chain(s) consolidated, ' || n_priorities
          || ' re-prioritisation(s) emitted, ' || v_open_chains || ' episode(s) still open. '
          || 'Bus backbone: ' || v_backbone);

  return jsonb_build_object('deliveries_closed', n_closed, 'lessons', n_lessons,
                            'rollups', n_rollups, 'priorities_emitted', n_priorities,
                            'chains_open', v_open_chains, 'bus_backbone', v_backbone);
end $function$


CREATE OR REPLACE FUNCTION public.fn_event_dispatch(p_lookback_minutes integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_delivered integer := 0; v_tasks integer := 0; v_gated integer := 0;
        v_unroutable integer := 0; v_assessed integer := 0; v_attached integer := 0;
        r record; v_task bigint; v_dept text; v_tier text; v_os text;
        v_impact text; v_subject_task bigint;
        v_title text; v_detail text; v_open_task bigint;
        -- RECURRENCE COOL-DOWN (14 Aug 2026). See the migration header: the open-task guard
        -- below cannot see a condition that is STILL TRUE after its task was closed, so a
        -- standing miss re-minted itself every tick and was answered again at the large tier.
        v_recur_task bigint; v_suppressed integer := 0; v_cooldown_days integer;
        v_open_bus integer; v_capped boolean; v_backpressured integer := 0;
        -- BACK-PRESSURE. 25 OPEN BUS TASKS PER DEPARTMENT, MEASURED 6 Aug 2026 ON PRODUCTION.
        --
        -- The queue grows ~100x faster than it drains. The dispatcher mints up to 50 (event,
        -- subscriber) pairs per */15 tick — 329 events arrived in the last 24 hours — while the
        -- whole organisation closed 132 org_tasks in 30 days, 4.4 a day. Of those 132, ZERO were
        -- bus-minted: all 395 tasks this routine has ever authored are still open, none has ever
        -- reached 'done'. 395 pieces of work nobody will ever reach is the same built-and-never-
        -- read defect the blueprint exists to catch, one level up.
        --
        -- 25 is the cap because it is generous against the MEASURED drain of every department.
        -- Closures in 30d, by department: knowledge 41, exec 32, it 14, procurement 8,
        -- knowledge_eng 7, finance 7, marketing 6, legal 5, evolution 4, intelligence 4,
        -- supplier_success 2, hr 1, sales 1. At the FASTEST of those, 25 open bus tasks is
        -- eighteen days of queue; at the median (5/30d) it is five months. A department holding
        -- more than 25 is not busy, it is unreachable, and minting a 26th is writing into a
        -- surface with no reader.
        --
        -- Open bus queue when this cap was chosen: knowledge 102, exec 97, knowledge_eng 46,
        -- sales 36, marketing 32 (over) — finance 19, evolution 19, intelligence 19, legal 12,
        -- it 12, procurement 1 (under). So the bus keeps minting per-event work for six of the
        -- eleven departments and stops piling it onto the five that are already buried.
        c_max_open_per_dept constant integer := 25;
        -- 50, MEASURED, NOT GUESSED. The backlog this uncovers is 147 undelivered (event,
        -- subscriber) pairs — 145 routable, 2 unroutable, across 99 events — against 182 open
        -- tasks today. Draining it in one tick would nearly double the open queue in fifteen
        -- minutes; at 50 it lands over three ticks and the first one can be inspected before the
        -- rest arrives. The cap bounds the RATE, not the total: the backlog is finite and the
        -- loop still delivers every pair.
        c_max_batch constant integer := 50;
begin
  -- Policy, not deploy. 0 disables the cool-down and restores the pre-14-Aug behaviour exactly.
  select coalesce((value #>> '{}')::int, 7) into v_cooldown_days
    from decision_policy where key = 'event_recur_cooldown_days';
  v_cooldown_days := coalesce(v_cooldown_days, 7);
  -- ── PASS 1 · ASSESS EVERYTHING PENDING, BEFORE ACTING ON ANY OF IT ──────────────────────────
  -- xos-04. The severity is the OS's own declared reading of this input from os_interface; the
  -- impact names which of the OS's declared responsibilities the event touches. Both come from
  -- tables the founder populated, so this is a JOIN, not a judgement. A NULL severity is itself
  -- the finding: the OS received an event it never declared it consumes, which is exactly the
  -- os_interface/event_subscription drift comp-07 measures.
  --
  -- HOISTED OUT OF THE LOOP 6 Aug 2026, AND IT IS A CORRECTNESS FIX, NOT A TIDY-UP. It used to sit
  -- inside the loop, one insert per iteration, which made "assessed before acting" true PER EVENT
  -- and false ACROSS THE BATCH. Any branch that ATTACHES event j to a task minted for event i
  -- earlier in the same run stamps assessed_at(j) AFTER created_at(i's task) — and when that task
  -- was raised after event j occurred, that reads exactly like acting before assessing. MEASURED
  -- on staging with the back-pressure branch in the loop: 56 deliveries assessed after the task
  -- they attached to, 50 of them on a back-pressure task, from a production baseline of 0. The
  -- latent form of the same hazard was already there in the duplicate-subject attach.
  --
  -- One statement, before any org_tasks row in this run exists, so every assessment strictly
  -- precedes every task and every delivery this run creates. The order is real, not asserted.
  --
  -- DELIBERATELY UNBOUNDED, where the delivery loop below takes 50. The two queries are separate
  -- and the invariant between them is "pass 1 is a SUPERSET of pass 2", not "identical" — a much
  -- weaker thing to keep true. Assessing an event this tick that gets delivered three ticks later
  -- is free (the insert is idempotent on (event_id, os_key)) and still correct: it was assessed
  -- before it was acted on. Sharing a LIMIT, by contrast, could cut the two batches differently on
  -- an e.id tie and leave a delivered pair unassessed, which is the one outcome xos-04 forbids.
  --
  -- The inner joins to org_agents/os_department are the v_os test from the old inline form: a
  -- subscription pointing at an employee who does not exist, or a department belonging to no OS,
  -- produces no assessment here and is handled as unroutable in the loop, exactly as before.
  with pending as (
    select distinct on (e.id, od.os_key)
           e.id as event_id, e.event_type, od.os_key, s.agent_key, s.reason
      from company_event e
      join event_subscription s on s.active and s.event_type = e.event_type
                               and s.agent_key <> coalesce(e.actor, '')
      join org_agents a         on a.agent_key = s.agent_key
      join os_department od     on od.dept_key = a.department
      left join event_delivery d on d.event_id = e.id and d.agent_key = s.agent_key
     where d.id is null
       and (p_lookback_minutes <= 0
            or e.occurred_at > now() - make_interval(mins => p_lookback_minutes))
     order by e.id, od.os_key, s.agent_key
  )
  insert into event_assessment (event_id, os_key, agent_key, severity, impact, proposed_action,
                                assessed_at)
  select p.event_id, p.os_key, p.agent_key, coalesce(i.severity, 'medium'),
         format('%s affects %s: %s', p.event_type, p.os_key,
                coalesce(rs.resp, 'no declared responsibilities')),
         case when i.severity is null
              then 'UNDECLARED INPUT: os_interface does not list this event type for this OS'
              else coalesce(p.reason, 'act on the subscription') end,
         -- clock_timestamp(), NOT the column default. "BEFORE acting" was UNMEASURABLE while every
         -- timestamp here came from now(): now() is TRANSACTION start, so the assessment, the task
         -- and the delivery all carried the identical value and `assessed_at > created_at` read 0
         -- whatever order the statements ran in. clock_timestamp() is statement time, so the
         -- ordering below is stored rather than assumed. Move this block after the loop and
         -- xos-04 fails, which is the property that makes it a measurement.
         clock_timestamp()
    from pending p
    left join lateral (select i2.severity from os_interface i2
                        where i2.os_key = p.os_key and i2.event_type = p.event_type
                          and i2.direction = 'input' limit 1) i on true
    left join lateral (select string_agg(x.responsibility, ', ') as resp
                         from (select responsibility from os_responsibility
                                where os_key = p.os_key order by responsibility limit 3) x) rs on true
  on conflict (event_id, os_key) do nothing;
  get diagnostics v_assessed = row_count;

  -- ── PASS 2 · ROUTE, RAISE WORK, DELIVER ─────────────────────────────────────────────────────
  -- p_lookback_minutes is KEPT and now means what its name says: an optional narrowing for a
  -- manual catch-up run, not a wall that silently drops events. <= 0 means "every undelivered
  -- event, however old", which is the setting the cron uses.
  for r in
    select e.id as event_id, e.event_type, e.entity_type, e.entity_id, e.actor, e.occurred_at,
           e.correlation_id, e.payload, s.agent_key, s.reason
    from company_event e
    join event_subscription s on s.active and s.event_type = e.event_type
    left join event_delivery d on d.event_id = e.id and d.agent_key = s.agent_key
    where d.id is null
      and (p_lookback_minutes <= 0
           or e.occurred_at > now() - make_interval(mins => p_lookback_minutes))
      and s.agent_key <> coalesce(e.actor, '')
    order by e.id
    -- BOUNDED ON PURPOSE. Dropping the time filter exposes a real backlog, and this bus has
    -- already produced 169 tasks in one hour once. A batch cap drains it over consecutive ticks
    -- instead of in a single burst, and the cron runs every 15 minutes.
    limit c_max_batch
  loop
    select department into v_dept from org_agents where agent_key = r.agent_key;
    -- xos-03. The OS, not just the agent. Resolved through the same os_department link the rest
    -- of the blueprint uses, so a department that belongs to no OS is visibly null rather than
    -- silently defaulted to one.
    select od.os_key into v_os from os_department od where od.dept_key = v_dept;
    v_task := null;

    -- xos-14. Everything raised from here on belongs to THIS event's chain and was CAUSED by it.
    -- Set before any insert so a trigger firing downstream inherits both through the column
    -- defaults on company_event — that is why the defaults read a setting rather than a literal.
    perform set_config('app.correlation_id', coalesce(r.correlation_id::text, ''), true);
    perform set_config('app.causation_event_id', r.event_id::text, true);

    if v_dept is null then
      -- xos-05. Say why. An unroutable subscription is a real defect in the subscription table
      -- and it was previously indistinguishable from a task that had not been created yet.
      --
      -- AND IT IS CLOSED HERE, 6 Aug 2026. An unroutable delivery is TERMINAL: no task exists, no
      -- task will ever exist, and no result can ever come back — so leaving result/closed_at NULL
      -- filed it forever as "loop still open". It is not open; it finished, badly, at this instant,
      -- and the reason it finished is already on the row. contract-consolidation asks whether the
      -- deliveries the bus made came back with a result; a broken subscription that can never come
      -- back dragged that ratio down permanently and no amount of correct work could ever clear it.
      -- The result is the reason, not a placeholder, and closed_at is now, not the delivery's past.
      insert into event_delivery (event_id, agent_key, event_type, os_key, task_id, delivered_at,
                                  unroutable_reason, result, closed_at)
      values (r.event_id, r.agent_key, r.event_type, v_os, null, clock_timestamp(),
              format('no org_agents row for subscriber %s — this subscription points at an '
                  || 'employee who does not exist, so the event reaches nobody', r.agent_key),
              left(format('unroutable: no org_agents row for subscriber %s; the event reached '
                  || 'nobody and nothing further will happen to this delivery', r.agent_key), 1000),
              clock_timestamp())
      on conflict do nothing;
      v_unroutable := v_unroutable + 1;
      v_delivered  := v_delivered + 1;
      continue;
    end if;

    -- 7.3 PRECONDITION. This used to hard-code tier 'autonomous', so a subscriber was granted
    -- autonomy by the dispatcher rather than by the authority model. It reads the tier now.
    v_tier := coalesce(public.fn_dept_authority(v_dept, 'analysis')->>'tier', 'gated');
    if v_tier <> 'autonomous' then v_gated := v_gated + 1; end if;

    -- xos-04. The assessment for this (event, OS) was written in PASS 1, before this loop began
    -- and therefore before any task in this run exists. Read the impact back for the task detail
    -- below rather than recomputing it, so the sentence the employee reads is the same sentence
    -- the OS recorded. NULL when the department resolves to no OS, which coalesce() handles.
    select a.impact into v_impact
      from event_assessment a where a.event_id = r.event_id and a.os_key = v_os;

    -- xos-05 / contract-consolidation. THE EVENT THAT REPORTS ON WORK IS NOT NEW WORK.
    --
    -- MEASURED 6 Aug 2026, and it is a divergent feedback loop, not an inefficiency. Closing one
    -- task runs fn_task_review, which writes 3-4 review_chain rows; trg_event_review emits one
    -- review.step per row; knowledge_director subscribes to review.step; and this loop minted a
    -- fresh org_task for every one of them. review.step was 183 of the ~300 events of the last
    -- seven days and 217 of 576 deliveries all time. The Chief of Staff's executor closes 2 tasks
    -- an hour, so every closure created 3-4 new tasks and the queue grew by working it — 336 open
    -- event-derived tasks against 58 ever closed, and no coverage ratio for "the loop closes"
    -- could ever be satisfied while that held.
    --
    -- The row already says what the event is about: fn_emit_event copies the whole source row into
    -- payload, so a review_chain event carries subject_type='org_task' and subject_id. When the
    -- event REPORTS ON a task that exists, the work is that task. The delivery is attached to it,
    -- so the result that comes back is that task's own result and the loop closes on the work
    -- itself rather than on a duplicate of it. Nothing is dropped: the delivery, its os_key and
    -- its assessment (pass 1) are all still written.
    --
    -- Scoped by the payload, not by an event-type list: any future emitter whose row names an
    -- org_task subject gets the same treatment, and one that does not still raises a task.
    v_subject_task := null;
    if r.payload->>'subject_type' = 'org_task' and coalesce(r.payload->>'subject_id','') ~ '^[0-9]+$' then
      select t.id into v_subject_task
        from org_tasks t where t.id = (r.payload->>'subject_id')::bigint;
    end if;
    if v_subject_task is not null then
      insert into event_delivery (event_id, agent_key, event_type, os_key, task_id, delivered_at)
      values (r.event_id, r.agent_key, r.event_type, v_os, v_subject_task, clock_timestamp())
      on conflict do nothing;
      v_attached  := v_attached + 1;
      v_delivered := v_delivered + 1;
      continue;
    end if;

    -- THE SAME SUBJECT, RAISED AGAIN, IS NOT A SECOND PIECE OF WORK.
    --
    -- The attach above handles an event that REPORTS ON a task. This is its sibling: an event that
    -- re-reports the SAME SUBJECT to the SAME department while that department's task for it is
    -- still open and untouched. MEASURED 6 Aug 2026 on production: of 372 open bus-minted tasks,
    -- 107 (29%) are duplicate copies — 'test.failed on scheduled_run uptime' had SIX open copies
    -- raised the same day, 'kpi.missed on metric open_p1' three. The Chief of Staff's executor
    -- closes 2 tasks an hour, so a condition that re-fires hourly minted copies faster than the
    -- company could ever work them, and every copy diluted the coverage the closing loop is scored
    -- on. The title is the subject identity the mint below already builds from event_type +
    -- entity_type + entity_id, so it is computed once here and reused rather than re-derived.
    --
    -- The delivery is STILL WRITTEN — the denominator does not shrink, and that is the point. When
    -- the department finally does the work, fn_event_consolidate closes EVERY delivery attached to
    -- that task, so all six events that reported the failure get the same result back. That is the
    -- contract ("the result comes back to the event that caused the work"), not an exemption from it.
    --
    -- Scoped to decided_by='fn_event_dispatch' so the bus can only ever attach to its OWN open
    -- task: a human's or another routine's task with a colliding title is never hijacked.
    -- ── BACK-PRESSURE ─────────────────────────────────────────────────────────────────────────
    -- THE BUS MUST NOT MINT NEW WORK INTO A DEPARTMENT WHOSE BUS QUEUE IS NOT DRAINING.
    --
    -- The two attach branches above stop the bus DUPLICATING work. Neither of them stops it
    -- OUTPACING the company: 395 bus tasks minted, 0 ever closed, against an organisation that
    -- closes 4.4 tasks a day across every department and every author. Deduplication cannot fix
    -- a rate mismatch — every one of those 395 is a distinct subject.
    --
    -- So the department's own open bus queue is the signal. Over the cap, this event does not get
    -- its own task; it is collapsed onto the department's single standing back-pressure task by
    -- rewriting v_title to a per-department constant. That makes the attach lookup immediately
    -- below do the work — the first over-cap event mints the standing task, every later one
    -- attaches to it — instead of adding a third near-identical branch beside the two above.
    --
    -- WHAT IS NOT SKIPPED, AND BOTH ARE THE POINT:
    --  * THE DELIVERY IS STILL WRITTEN, below, exactly as in every other branch. Skipping it would
    --    make the event permanently undeliverable again — the xos-02 defect at the top of this
    --    file — and would SHRINK the denominator of contract-consolidation, flattering that ratio
    --    while fixing nothing. Back-pressure regulates work, never the ledger.
    --  * THE ASSESSMENT IS ALREADY WRITTEN, in PASS 1, before this loop began — so it cannot be
    --    reached by any decision taken here. xos-04 says nothing is acted on unassessed, and no
    --    reordering of the branches in this loop can lose one or stamp one late.
    -- And when the department finally drains the standing task, fn_event_consolidate closes EVERY
    -- delivery attached to it, so all the queued events get their result back. Same contract as
    -- the duplicate-subject attach, one level up.
    select count(*) into v_open_bus
      from org_tasks t
     where t.decided_by = 'fn_event_dispatch'
       and t.dept_key = v_dept
       and t.status not in ('done','closed','cancelled');
    v_capped := v_open_bus >= c_max_open_per_dept;

    if v_capped then
      v_title  := left('bus.backpressure on department ' || v_dept, 200);
      v_detail := format('BUS BACK-PRESSURE — %s holds %s open task(s) raised by the event bus and '
                      || 'the bus has stopped minting more into it (cap %s). Events still arrive: '
                      || 'each one is delivered and assessed as normal and attached to THIS task '
                      || 'instead of raising its own, so nothing is lost and the queue stops '
                      || 'growing. Drain %s below %s open bus tasks and per-event tasks resume by '
                      || 'themselves. Close this one when the backlog is worked; every event '
                      || 'queued behind it gets that result back. Latest arrival: %s (%s %s) at %s.',
                         v_dept, v_open_bus, c_max_open_per_dept, v_dept, c_max_open_per_dept,
                         r.event_type, r.entity_type, coalesce(r.entity_id,'-'), r.occurred_at);
    else
      v_title  := left(r.event_type || ' on ' || r.entity_type || ' ' || coalesce(r.entity_id,''), 200);
      v_detail := format('Event %s (%s %s) raised by %s at %s. You subscribe to this because: %s. '
                      || 'Assessed impact: %s. Act on it or close it with a reason.',
                         r.event_type, r.entity_type, coalesce(r.entity_id,'-'),
                         coalesce(r.actor,'system'), r.occurred_at,
                         coalesce(r.reason,'subscription'), coalesce(v_impact,'not assessed'));
    end if;

    -- `status not in ('done','closed','cancelled')` rather than the old
    -- `in ('proposed','assigned','in_progress')`: the two lists disagreed about 'escalated', so an
    -- escalated task was open for the count above and closed for this lookup — which would mint a
    -- SECOND standing back-pressure task the moment the first one escalated, and had already been
    -- duplicating escalated subject tasks. One definition of open, used by both.
    select t.id into v_open_task
      from org_tasks t
     where t.decided_by = 'fn_event_dispatch'
       and t.dept_key = v_dept
       and t.title = v_title
       and t.status not in ('done','closed','cancelled')
     order by t.id
     limit 1;
    if v_open_task is not null then
      insert into event_delivery (event_id, agent_key, event_type, os_key, task_id, delivered_at)
      values (r.event_id, r.agent_key, r.event_type, v_os, v_open_task, clock_timestamp())
      on conflict do nothing;
      v_attached  := v_attached + 1;
      if v_capped then v_backpressured := v_backpressured + 1; end if;
      v_delivered := v_delivered + 1;
      continue;
    end if;

    -- ALREADY ANSWERED, INSIDE THE COOL-DOWN. The lookup above found nothing OPEN, which for a
    -- recurring condition means the last one was closed, not that the question is new. Attach
    -- to the task that already carries the answer rather than buying another one.
    if v_cooldown_days > 0 then
      select t.id into v_recur_task
        from org_tasks t
       -- Provenance is the delivery, not decided_by: the executor overwrites decided_by when
       -- it settles the row, so no closed task has ever carried 'fn_event_dispatch'.
       where exists (select 1 from event_delivery ed where ed.task_id = t.id)
         and t.dept_key = v_dept
         and t.title = v_title
         and t.status in ('done','closed','cancelled')
         and coalesce(t.updated_at, t.created_at) > clock_timestamp() - make_interval(days => v_cooldown_days)
       order by coalesce(t.updated_at, t.created_at) desc
       limit 1;
      if v_recur_task is not null then
        insert into event_delivery (event_id, agent_key, event_type, os_key, task_id, delivered_at)
        values (r.event_id, r.agent_key, r.event_type, v_os, v_recur_task, clock_timestamp())
        on conflict do nothing;
        v_suppressed := v_suppressed + 1;
        v_delivered  := v_delivered + 1;
        continue;
      end if;
    end if;

    insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class,
                           decided_by, created_at)
    values (v_dept,
            v_title,
            v_detail,
            case when v_tier = 'autonomous' then 'assigned' else 'proposed' end,
            v_tier, v_tier <> 'autonomous', 'analysis', 'fn_event_dispatch', clock_timestamp())
    returning id into v_task;
    v_tasks := v_tasks + 1;
    -- The standing task counts as back-pressured too: it is the one task the cap allows, not a
    -- per-event task that slipped through. Counted so `backpressured` in the return value is the
    -- full number of events the cap handled, and never silently one short.
    if v_capped then v_backpressured := v_backpressured + 1; end if;

    insert into event_delivery (event_id, agent_key, event_type, os_key, task_id, delivered_at)
    values (r.event_id, r.agent_key, r.event_type, v_os, v_task, clock_timestamp())
    on conflict do nothing;
    v_delivered := v_delivered + 1;
  end loop;

  -- Leave no correlation bound to the session after the loop: a later statement on this
  -- connection is NOT part of the last event's chain, and inheriting it would be a false link.
  perform set_config('app.correlation_id', '', true);
  perform set_config('app.causation_event_id', '', true);

  return jsonb_build_object('delivered', v_delivered, 'tasks_created', v_tasks,
                            'attached_to_existing_task', v_attached,
                            'backpressured', v_backpressured,
                            'suppressed_recurring', v_suppressed,
                            'recur_cooldown_days', v_cooldown_days,
                            'tasks_awaiting_a_human', v_gated,
                            'unroutable', v_unroutable, 'assessed', v_assessed,
                            'lookback_minutes', p_lookback_minutes,
                            'max_batch', c_max_batch,
                            'max_open_per_dept', c_max_open_per_dept);
end; $function$


CREATE OR REPLACE FUNCTION public.fn_evolution_scan()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into evolution_proposal (trigger_kind, subject, observation, evidence, proposal, change_class)
  select 'repeated_failure', r.agent,
         format('%s failed %s times in the last 7 days.', r.agent, r.fails),
         jsonb_build_object('failures_7d', r.fails),
         format('Root-cause %s rather than retry it. If the failure is external, add a documented fallback to continuity_plan; if it is a parsing or contract failure, fix the contract and add a regression test.', r.agent),
         'code'
  from (select agent, count(*) fails from agent_runs
        where status = 'error' and started_at > now() - interval '7 days'
        group by agent having count(*) >= 3) r
  on conflict do nothing;

  insert into evolution_proposal (trigger_kind, subject, observation, evidence, proposal, change_class)
  select 'metric_off_target', s.metric_key,
         format('%s is %s against a target of %s.', s.label, coalesce(s.value::text,'unmeasured'), s.target),
         jsonb_build_object('value', s.value, 'target', s.target, 'owner', s.owner_dept),
         format('%s owns this. Either the target is wrong and should be restated, or the operating approach behind it is wrong and should change. Do not carry it as-is for another period.', coalesce(s.owner_dept,'exec')),
         'process'
  from v_bi_scorecard s where s.state = 'OFF_TARGET'
  on conflict do nothing;

  insert into evolution_proposal (trigger_kind, subject, observation, evidence, proposal, change_class)
  select 'cost_anomaly', c.fn,
         format('%s made %s model calls in 30 days that the cost governor flagged as avoidable.', c.fn, c.n),
         jsonb_build_object('avoidable_calls', c.n, 'cost_aed', c.cost),
         format('Replace the flagged path in %s with a rule, a lookup or SQL, or drop it to the small tier.', c.fn),
         'model_routing'
  from (select fn, count(*) n, round(sum(cost_aed),2) cost from ai_cost_log
        where could_be_cheaper and occurred_at > now() - interval '30 days'
        group by fn having count(*) >= 5) c
  on conflict do nothing;

  -- ── THE FOUR STRUCTURAL QUESTIONS ─────────────────────────────────────────────────────────────
  insert into evolution_proposal (trigger_kind, subject, observation, evidence, proposal, change_class)
  select 'audit_gap', 'workforce',
         format('%s of %s active employees are dormant — no run, no recorded thought and no reasoning in 30 days. Longest-standing: %s.',
                d.idle, d.total, d.sample),
         jsonb_build_object('dormant', d.idle, 'active', d.total, 'sample', d.sample),
         'Decide, for each dormant role, which of two things is true: nothing routes to it, or the role is not needed. Where nothing routes to it the routing is the defect and the role is fine. Where the role is not needed it should be retired rather than carried as an employee that never works.',
         'org'
    from (select count(*) filter (where not (exists (select 1 from agent_runs r_a where r_a.agent = a.agent_key
                                    and r_a.started_at > now() - interval '30 days')
                       or exists (select 1 from agent_memory m_a where m_a.agent_key = a.agent_key
                                    and m_a.created_at > now() - interval '30 days')
                       or exists (select 1 from agent_chats c_a where c_a.agent_key = a.agent_key
                                    and c_a.created_at > now() - interval '30 days'))) idle,
                 count(*) total,
                 (select string_agg(x.agent_key, ', ') from (
                    select a2.agent_key from org_agents a2 where a2.active
                     and not (exists (select 1 from agent_runs r_a2 where r_a2.agent = a2.agent_key
                                    and r_a2.started_at > now() - interval '30 days')
                       or exists (select 1 from agent_memory m_a2 where m_a2.agent_key = a2.agent_key
                                    and m_a2.created_at > now() - interval '30 days')
                       or exists (select 1 from agent_chats c_a2 where c_a2.agent_key = a2.agent_key
                                    and c_a2.created_at > now() - interval '30 days'))
                     order by a2.agent_key limit 5) x) sample
            from org_agents a where a.active) d
   where d.idle > 0 and not exists (select 1 from evolution_proposal p
        where p.trigger_kind = 'audit_gap' and p.subject = 'workforce'
          and p.created_at > now() - interval '30 days')
  on conflict do nothing;

  insert into evolution_proposal (trigger_kind, subject, observation, evidence, proposal, change_class)
  select 'audit_gap', h.name,
         format('%s carries a backlog of %s open tasks per head across %s employee(s) — the role is overloaded.',
                h.name, h.backlog_per_head, coalesce(h.employees, 0)),
         jsonb_build_object('backlog_per_head', h.backlog_per_head, 'employees', h.employees,
                            'open_tasks', h.open_tasks, 'os_key', h.os_key),
         format('Either split the work of %s across more employees, or accept that the backlog is not going to be cleared and close what is no longer worth doing. Carrying it at this level is a decision by default.', h.name),
         'org'
    from v_os_health h
   where h.backlog_per_head > 5 and not exists (select 1 from evolution_proposal p
        where p.trigger_kind = 'audit_gap' and p.subject = h.name
          and p.created_at > now() - interval '30 days')
  on conflict do nothing;

  insert into evolution_proposal (trigger_kind, subject, observation, evidence, proposal, change_class)
  select 'audit_gap', z.dept_key,
         format('%s holds %s open task(s) and not one active employee in it has run in 30 days — the work has no one doing it.',
                z.dept_key, z.n),
         jsonb_build_object('open_tasks', z.n, 'department', z.dept_key),
         format('A new specialist is needed for %s, or the work belongs to a department that already has someone running. Decide which before hiring: staffing a queue that should have been routed elsewhere adds an employee and keeps the defect.', z.dept_key),
         'org'
    from (select t.dept_key, count(*) n from org_tasks t
           where t.status <> 'done' and t.dept_key is not null
             and not exists (select 1 from org_agents a join agent_runs r on r.agent = a.agent_key
                              and r.started_at > now() - interval '30 days'
                             where a.active and a.department = t.dept_key)
           group by t.dept_key having count(*) >= 5) z
   where not exists (select 1 from evolution_proposal p
        where p.trigger_kind = 'audit_gap' and p.subject = z.dept_key
          and p.created_at > now() - interval '30 days')
  on conflict do nothing;

  insert into evolution_proposal (trigger_kind, subject, observation, evidence, proposal, change_class)
  select 'audit_gap', 'organisation structure',
         format('%s department(s) have two or more employees who are ALL dormant: %s.', m.depts, m.sample),
         jsonb_build_object('departments', m.depts, 'sample', m.sample),
         'Consider whether these roles should merge. Two dormant employees in one department is either duplicated scope that should be consolidated into a single role, or a department that receives no work at all — and those two answers lead to opposite actions, so establish which before combining anything.',
         'org'
    from (select count(*) depts,
                 (select string_agg(y.department||' ('||y.n||')', ', ' order by y.n desc) from (
                    select a3.department, count(*) n from org_agents a3 where a3.active
                     and not exists (select 1 from agent_runs r3 where r3.agent = a3.agent_key
                                      and r3.started_at > now() - interval '30 days')
                     group by a3.department having count(*) >= 2 order by count(*) desc limit 5) y) sample
            from (select a.department from org_agents a where a.active
                   and not exists (select 1 from agent_runs r where r.agent = a.agent_key
                                    and r.started_at > now() - interval '30 days')
                   group by a.department having count(*) >= 2) q) m
   where m.depts > 0 and not exists (select 1 from evolution_proposal p
        where p.trigger_kind = 'audit_gap' and p.subject = 'organisation structure'
          and p.created_at > now() - interval '30 days')
  on conflict do nothing;

  -- ── IS THE PROMPTING UNMEASURED? ──────────────────────────────────────────────────────────────
  -- Added 10 Aug 2026. Every other trigger asks about routines, metrics, bills or people; the
  -- instructions the whole company reasons from were the one thing nothing ever proposed changing.
  -- Fires while any registered prompt has never been scored, or the newest score anywhere is over
  -- 30 days old. Goes quiet on its own when the benchmarks are being run.
  insert into evolution_proposal (trigger_kind, subject, observation, evidence, proposal, change_class)
  select 'prompt_unmeasured', 'prompt benchmarks',
         format('%s of %s registered prompt(s) have never been scored, and the newest evaluation anywhere is %s. %s benchmark case(s) are on file and nothing runs them.',
                pr.never, pr.total, coalesce(pr.newest::date::text, 'none ever'), pr.bench),
         jsonb_build_object('prompts', pr.total, 'never_evaluated', pr.never,
                            'newest_eval', pr.newest, 'benchmark_cases', pr.bench,
                            'unscored', pr.sample),
         'Run prompt_benchmarks against the active version of every prompt on a schedule and record the score, or retire the prompts nobody is willing to benchmark. An unscored prompt cannot regress visibly: fn_ai_quality_watch compares the last two eval runs, so a prompt with fewer than two has no regression detector at all and a change to it is unmeasurable.',
         'prompting'
    from (select (select count(*) from prompts) total,
                 (select count(*) from prompts p2
                   where not exists (select 1 from prompt_eval_runs e where e.prompt_key = p2.key)) never,
                 (select max(created_at) from prompt_eval_runs) newest,
                 (select count(*) from prompt_benchmarks) bench,
                 (select string_agg(p3.key, ', ' order by p3.key) from prompts p3
                   where not exists (select 1 from prompt_eval_runs e3 where e3.prompt_key = p3.key)) sample
         ) pr
   where (pr.never > 0 or pr.newest is null or pr.newest < now() - interval '30 days')
     and not exists (select 1 from evolution_proposal p
          where p.trigger_kind = 'prompt_unmeasured'
            and p.created_at > now() - interval '30 days')
  on conflict do nothing;

  return (select count(*) from evolution_proposal where status='proposed');
end; $function$


CREATE OR REPLACE FUNCTION public.fn_exam_pick_agent()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with last_sat as (
    select (select agent_key from knowledge_exam_results order by created_at desc limit 1) as k
  ),
  -- Want a category next only if the last one sat was NOT a category. A null last_sat (no exam has
  -- ever been sat) starts with an employee, which is the population that matters more.
  want as (
    select coalesce((select k from last_sat) not like 'cat:%', false) as want_cat
  ),
  ranked as (
    select k.agent_key,
           (k.agent_key like 'cat:%') as is_cat,
           e.last_exam
    from (select distinct agent_key from agent_knowledge where agent_key <> '_global') k
    left join (select agent_key, max(created_at) last_exam from knowledge_exam_results group by agent_key) e
      on e.agent_key = k.agent_key
  )
  select agent_key from ranked
  -- false sorts first, so rows whose population matches what we want come first; everything after
  -- that is the original ordering, and the second population is still reachable when the first is
  -- empty.
  order by (is_cat is distinct from (select want_cat from want)), last_exam asc nulls first, agent_key
  limit 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_exam_revert(p_agent_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare n int;
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  delete from agent_knowledge
    where topic like 'exam:%' and (p_agent_key is null or agent_key = p_agent_key);
  get diagnostics n = row_count;
  update knowledge_exam_results set filled = false, knowledge_id = null
    where filled and (p_agent_key is null or agent_key = p_agent_key);
  return jsonb_build_object('reverted', n, 'agent', coalesce(p_agent_key,'(all)'));
end $function$


CREATE OR REPLACE FUNCTION public.fn_exception_alerts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  rev_today numeric; rev_prev numeric;
  gw_bad int; q24 int; qpass24 int; last_backup timestamptz;
  fired text[] := '{}';
  procedure_note text;
begin
  -- helper: only fire if same event not raised in last 12h
  -- 1) revenue drop > 20% day-over-day (needs a meaningful prior day)
  select coalesce(sum(reveal_fee),0) into rev_today from transactions
    where revealed_at::date = current_date and coalesce(refund_status,'')<>'approved';
  select coalesce(sum(reveal_fee),0) into rev_prev from transactions
    where revealed_at::date = current_date-1 and coalesce(refund_status,'')<>'approved';
  if rev_prev >= 100 and rev_today < rev_prev*0.8 then
     if not exists(select 1 from founder_alerts where event='revenue_drop' and created_at>now()-interval '12 hours') then
        insert into founder_alerts(level,event,detail,channel) values
          ('critical','revenue_drop','Revenue AED '||round(rev_today)||' today vs AED '||round(rev_prev)||' yesterday (>20% drop).','email');
        fired := array_append(fired,'revenue_drop'); end if;
  end if;

  -- 2) payment gateway offline (latest stripe health check failing in last hour)
  select count(*) into gw_bad from health_checks
    where created_at>now()-interval '1 hour' and not ok
      and (lower(coalesce(check_kind,'')) like '%stripe%' or lower(coalesce(target,'')) like '%stripe%' or lower(coalesce(check_kind,'')) like '%pay%');
  if gw_bad > 0 then
     if not exists(select 1 from founder_alerts where event='gateway_offline' and created_at>now()-interval '3 hours') then
        insert into founder_alerts(level,event,detail,channel) values
          ('critical','gateway_offline','Payment gateway health check failing in the last hour.','email');
        fired := array_append(fired,'gateway_offline'); end if;
  end if;

  -- 3) AI confidence / quote-quality below threshold (proxy: gate pass-rate collapse with volume)
  select count(*) filter (where quality is not null),
         count(*) filter (where nullif(quality->>'score','')::numeric >= 60)
    into q24, qpass24 from quotes where created_at>now()-interval '24 hours';
  if q24 >= 5 and qpass24::numeric/nullif(q24,0) < 0.5 then
     if not exists(select 1 from founder_alerts where event='ai_confidence_low' and created_at>now()-interval '12 hours') then
        insert into founder_alerts(level,event,detail,channel) values
          ('warning','ai_confidence_low','Quote-quality gate pass rate '||round(qpass24::numeric/q24*100)||'% over last 24h ('||q24||' quotes) — below 50% threshold.','email');
        fired := array_append(fired,'ai_confidence_low'); end if;
  end if;

  -- 4) backup stale (no backup manifest in > 8 days)
  select max(updated_at) into last_backup from storage.objects where bucket_id='backups' and name like '%/_manifest.json';
  if last_backup is null or last_backup < now()-interval '8 days' then
     if not exists(select 1 from founder_alerts where event='backup_stale' and created_at>now()-interval '24 hours') then
        insert into founder_alerts(level,event,detail,channel) values
          ('critical','backup_stale','No fresh backup manifest in over 8 days (last: '||coalesce(last_backup::text,'never')||').','email');
        fired := array_append(fired,'backup_stale'); end if;
  end if;

  -- QD_CRON_HEALTH: fn_os_health computes the failing-now cron signal; nothing asked for it.
  if jsonb_array_length(coalesce(public.fn_os_health()->'failing_crons','[]'::jsonb)) > 0 then
    if not exists(select 1 from founder_alerts
                   where event='cron_failing' and created_at > now()-interval '6 hours') then
      insert into founder_alerts(level,event,detail,channel)
      select 'critical','cron_failing',
             'Scheduled job(s) failed on their most recent run: '||
             (select string_agg(distinct (e->>'job')||' — '||left(coalesce(e->>'message',''),120), '; ')
                from jsonb_array_elements(public.fn_os_health()->'failing_crons') e),
             'email';
      fired := array_append(fired,'cron_failing');
    end if;
  end if;

  -- surface criticals as founder notifications too
  insert into notifications(type,to_role,channel,subject,body)
  select 'exception_alert','admin','email','QuotesDone ALERT: '||event, detail
  from founder_alerts fa
  where fa.created_at>now()-interval '2 minutes' and public.fn_alert_severe(fa.level)
    and not exists(select 1 from notifications n where n.type='exception_alert' and n.subject='QuotesDone ALERT: '||fa.event and n.created_at>now()-interval '3 hours');

  return jsonb_build_object('fired', to_jsonb(fired), 'rev_today',rev_today,'rev_prev',rev_prev,'checked_at',now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_exec_meeting()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare m jsonb; findings jsonb := '[]'::jsonb; actions int := 0; recs jsonb;
  -- the six agenda sections, rebuilt per contribution, plus their company-scoped counterparts
  v_wins text; v_probs text; v_risks text; v_opps text; v_reqs text; v_kpis jsonb;
  v_dept text; v_opp_all int; v_co jsonb; p record; v_challenger text; v_ch int := 0;
  v_period text := to_char(now(),'IYYY-"W"IW');
  v_rev numeric; v_spend numeric; v_sup int; v_open int; v_avail numeric;
  v_red int; v_amber int; v_green int; r record; v_drivers text;
  v_report_id bigint; v_raised int := 0;
begin
  -- ensure the OS reviews for this week exist before the meeting reads them
  if not exists (select 1 from os_review where period = v_period) then
    perform fn_os_review();
  end if;

  select count(*) filter (where health='red'), count(*) filter (where health='amber'), count(*) filter (where health='green')
    into v_red, v_amber, v_green from os_review where period = v_period;

  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev from transactions where revealed_at > now()-interval '7 days';
  select coalesce(sum(cost_aed),0) into v_spend from ai_cost_log where occurred_at > now()-interval '7 days';
  select count(*) into v_sup from leads where approval_status='approved';
  select count(*) into v_open from org_tasks where status<>'done';
  select round(100.0*count(*) filter (where ok)/nullif(count(*),0),1) into v_avail
    from health_checks where check_kind='http' and created_at > now()-interval '7 days';

  select count(*) into v_opp_all from opportunity where coalesce(status,'open')='open';

  m := jsonb_build_object('week',v_period,'os_green',v_green,'os_amber',v_amber,'os_red',v_red,
       'revenue_7d_aed',v_rev,'ai_spend_7d_aed',round(coalesce(v_spend,0),2),
       'approved_suppliers',v_sup,'supplier_target',860,
       'open_tasks',v_open,'platform_availability_pct',v_avail);

  -- AGENDA ITEM 1..10: every operating system that is not green, named with its owner AND with the
  -- live per-OS figures out of v_os_health that put it there. LEFT JOIN: an OS the view cannot
  -- resolve still reaches the agenda, it just reaches it without drivers.
  for r in
    select o.num, o.name, r2.health, r2.owner_agent, r2.findings,
           h.open_risks, h.kpi_gaps, h.backlog_per_head, h.stale_tasks,
           h.review_pass_pct, h.budget_pct, h.needs_founder_pct,
           -- CAPACITY IS THE ONE DIMENSION v_os_health DOES NOT COMPUTE (6 Aug 2026). It is
           -- resource_pool committed/capacity and it exists only in os_review.metrics, so it
           -- was the one of the eight figures with no reader outside its own writer. Taken off
           -- the report row the meeting is already reading.
           r2.metrics->>'capacity_pct' capacity_pct
    from os_review r2 join operating_system o on o.os_key = r2.os_key
    left join v_os_health h on h.os_key = r2.os_key
    where r2.period = v_period order by
      case r2.health when 'red' then 1 when 'amber' then 2 else 3 end, o.num
  loop
    v_drivers := 'open_risks '||coalesce(r.open_risks::text,'?')
      ||', kpi_gaps '||coalesce(r.kpi_gaps::text,'?')
      ||', capacity_pct '||coalesce(r.capacity_pct,'?')
      ||', backlog_per_head '||coalesce(r.backlog_per_head::text,'?')
      ||', stale_tasks '||coalesce(r.stale_tasks::text,'?')
      ||', review_pass_pct '||coalesce(r.review_pass_pct::text,'?')
      ||', budget_pct '||coalesce(r.budget_pct::text,'?')
      ||', needs_founder_pct '||coalesce(r.needs_founder_pct::text,'?');
    -- THE SIX AGENDA SECTIONS. Each is a count over live rows and the top three by name; a
    -- section with nothing in it states the zero rather than being omitted, because a meeting is
    -- entitled to hear "no open risks" and a missing section is not the same claim.
    v_dept := (select department from org_agents where agent_key = r.owner_agent);

    v_wins := (select count(*) from org_tasks
                where status='done' and updated_at > now()-interval '7 days' and dept_key = v_dept)
      ||' task(s) closed in the last 7 days'
      || coalesce(': '||(select string_agg(w.title, '; ') from (
             select title from org_tasks where status='done'
              and updated_at > now()-interval '7 days' and dept_key = v_dept
              order by updated_at desc limit 3) w), '')||'.';

    v_probs := case when jsonb_typeof(r.findings)='array' and jsonb_array_length(r.findings) > 0
      then (select string_agg(coalesce(e->>'issue', e::text)||coalesce(' — '||(e->>'detail'), ''), '; ')
              from jsonb_array_elements(r.findings) e)
      else 'No unresolved finding recorded for this operating system in '||v_period||'.' end;

    v_kpis := jsonb_build_object('health', r.health,
      'open_risks', r.open_risks, 'kpi_gaps', r.kpi_gaps, 'capacity_pct', r.capacity_pct,
      'backlog_per_head', r.backlog_per_head, 'stale_tasks', r.stale_tasks,
      'review_pass_pct', r.review_pass_pct, 'budget_pct', r.budget_pct,
      'needs_founder_pct', r.needs_founder_pct);

    v_risks := (select count(*) from risk_register
                 where coalesce(status,'open') <> 'closed' and dept_key = v_dept)
      ||' open risk(s) on the register'
      || coalesce(': '||(select string_agg(k.risk, '; ') from (
             select risk from risk_register where coalesce(status,'open') <> 'closed'
              and dept_key = v_dept order by updated_at desc nulls last limit 3) k), '')||'.';

    v_opps := (select count(*) from opportunity op join org_agents oa on oa.agent_key = op.detected_by
                where coalesce(op.status,'open')='open' and oa.department = v_dept)
      ||' open opportunit(ies) attributed to this operating system'
      || coalesce(': '||(select string_agg(x.title, '; ') from (
             select op.title from opportunity op join org_agents oa on oa.agent_key = op.detected_by
              where coalesce(op.status,'open')='open' and oa.department = v_dept
              order by op.value_score desc nulls last limit 3) x), '')
      ||'; '||v_opp_all||' open company-wide.';

    v_reqs := (select count(*) from org_tasks
                where needs_founder and status <> 'done' and dept_key = v_dept)
      ||' item(s) awaiting a founder decision'
      || coalesce(': '||(select string_agg(q.title, '; ') from (
             select title from org_tasks where needs_founder and status <> 'done'
              and dept_key = v_dept order by created_at desc limit 3) q), '')||'.';

    findings := findings || jsonb_build_array(jsonb_build_object(
      'item', r.num||'. '||r.name, 'owner', coalesce(r.owner_agent,'unassigned'),
      'health', r.health, 'finding', r.findings::text, 'drivers', v_drivers,
      'wins', v_wins, 'problems', v_probs, 'kpis', v_kpis,
      'risks', v_risks, 'opportunities', v_opps, 'requests', v_reqs));
  end loop;

  -- COMPANY-LEVEL ITEMS the CEO owns directly
  if coalesce(v_rev,0)=0 then
    findings := findings || jsonb_build_array(jsonb_build_object('item','Revenue','owner','cfo','health','amber','finding','No revenue recognised in the last 7 days.'));
  end if;
  if v_sup < 860 then
    findings := findings || jsonb_build_array(jsonb_build_object('item','Supplier coverage','owner','procurement','health',
      case when v_sup=0 then 'red' else 'amber' end,
      'finding', v_sup||' approved suppliers against a target of 860 (10 in each of 86 categories).'));
  end if;
  if coalesce(v_avail,100) < 99.5 then
    findings := findings || jsonb_build_array(jsonb_build_object('item','Platform availability','owner','cto','health','amber','finding','Availability '||coalesce(v_avail,0)||'% against 99.5%.'));
  end if;

  -- The company-level items above are contributions too, so they carry the same six sections,
  -- scoped to the company rather than to one department. Merged rather than typed into each of
  -- the three: an item added later inherits the sections instead of arriving with four.
  v_co := jsonb_build_object(
    'wins', (select count(*) from org_tasks where status='done' and updated_at > now()-interval '7 days')
            ||' task(s) closed company-wide in the last 7 days.',
    'problems', v_red||' operating system(s) red and '||v_amber||' amber in '||v_period||'.',
    'kpis', m,
    'risks', (select count(*) from risk_register where coalesce(status,'open') <> 'closed')
             ||' open risk(s) on the company register.',
    'opportunities', v_opp_all||' open opportunit(ies) company-wide.',
    'requests', (select count(*) from org_tasks where needs_founder and status <> 'done')
                ||' item(s) awaiting a founder decision company-wide.');
  select coalesce(jsonb_agg(case when f ? 'wins' then f else f || v_co end order by ord), '[]'::jsonb)
    into findings from jsonb_array_elements(findings) with ordinality as t(f, ord);

  insert into org_tasks (dept_key,title,detail,status,tier,needs_founder,action_class)
  select coalesce((select department from org_agents where agent_key=f->>'owner'),'exec'),
    'Exec meeting '||v_period||': '||(f->>'item'),
    'Health: '||(f->>'health')||'. Owner: '||(f->>'owner')||'. '||(f->>'finding')
    ||coalesce(' Drivers: '||(f->>'drivers')||'.','')
    ||' Raised at the weekly executive meeting. Close it, or bring evidence the standard is wrong.',
    'proposed','advisory',false,'exec_review'
  from jsonb_array_elements(findings) f
  where coalesce(f->>'health','') <> 'green'
    and not exists (select 1 from org_tasks t where t.title='Exec meeting '||v_period||': '||(f->>'item') and t.status<>'done');
  get diagnostics actions = row_count;

  -- AGREED PRIORITIES, RANKED AND OWNED. One object per contribution that is not green, red
  -- before amber and then in operating-system order, which is the order the constitution gives:
  -- compliance and trust sit in the red band before anything amber is opened. `title` is the key
  -- fn_report_recommendation_approve already reads, so the founder's approve control gets a name
  -- rather than 160 characters of JSON.
  select coalesce(jsonb_agg(jsonb_build_object(
           'rank', x.rn, 'owner', x.owner, 'priority', x.health,
           'title', x.item, 'why', x.finding) order by x.rn), '[]'::jsonb)
    into recs from (
      select row_number() over (order by case f->>'health' when 'red' then 1 else 2 end, ord) rn,
             f->>'item' item, f->>'owner' owner, f->>'health' health,
             -- an operating system's readable problem statement lives in `problems`; `finding` is
             -- the raw os_review JSON. The three company items are the other way round.
             case when f ? 'drivers' then f->>'problems' else f->>'finding' end finding
        from jsonb_array_elements(findings) with ordinality as t(f, ord)
       where coalesce(f->>'health','') <> 'green') x;
  if jsonb_array_length(recs) = 0 then
    recs := jsonb_build_array(jsonb_build_object('rank', 1, 'owner', 'ceo', 'priority', 'hold',
      'title', 'Hold current priorities',
      'why', 'All ten operating systems green and company metrics within tolerance.'));
  end if;

  insert into exec_reports (officer,period,summary,findings,recommendations,metrics,status)
  values ('ceo',v_period,
    'Weekly executive meeting across ten operating systems. '||v_green||' green, '||v_amber||' amber, '||v_red
    ||' red. '||jsonb_array_length(findings)||' agenda contribution(s), '||actions||' action(s) assigned.',
    findings, recs, m, 'open')
  on conflict do nothing;

  -- THE DEBATE. The CEO's proposed priority order is put to another officer, who evaluates it
  -- through fn_challenge against challenge_heuristic and any prior outcome in institutional_memory
  -- and answers support / concern / recommend_against with its reasoning. The challenger is the
  -- first officer in the list who is not the one proposing, so this is officers challenging each
  -- other rather than the CEO agreeing with itself. Top three only: a debate, not thirteen rows of
  -- boilerplate a week.
  --
  -- In its own block because a challenge that throws must not fail the meeting — the cron's own
  -- success is what exec-meeting-weekly-autostart measures. The number that actually landed goes
  -- into the run note below, so a swallowed failure is visible rather than silent.
  begin
    for p in select (e->>'rank')::int prank, e->>'title' ptitle, e->>'owner' powner
               from jsonb_array_elements(recs) e
              where (e->>'rank')::int <= 3 order by (e->>'rank')::int
    loop
      v_challenger := coalesce((select e2->>'owner' from jsonb_array_elements(recs) e2
                                 where coalesce(e2->>'owner','') <> coalesce(p.powner,'')
                                 order by (e2->>'rank')::int limit 1), 'ceo');
      perform fn_challenge('Exec meeting '||v_period||' priority '||p.prank||': '||p.ptitle,
                           coalesce(p.powner,'ceo'), v_challenger);
      v_ch := v_ch + 1;
    end loop;
  exception when others then
    v_ch := -1;
  end;

  -- THE PRIORITIES REACH THE DECISION QUEUE.
  -- 33 of 40 exec_reports carried recommendations and agent_actions held ZERO row pointing at a
  -- report, so the founder could read the meeting's ranked priorities and had no way to act on
  -- them: the report surface has five approve controls bound to nothing. Each ranked priority is
  -- now raised once per period as an approvable action carrying target_table='exec_reports' and the
  -- report's id, which is what the approve control resolves.
  --
  -- One row per priority per week — typically two, one when every OS is green — so this cannot
  -- flood the queue. A bulk backfill of the 107 recommendation entries sitting in the last 30 days
  -- was deliberately NOT done: it would have taken the paused share of agent_actions from 2.6% to
  -- roughly 10.4% and regressed approval-center-everything-else-automatic, and most of those
  -- entries are superseded weekly anyway.
  --
  -- Its own block, like the debate above: a failure here must not fail the meeting, because the
  -- cron's own success is what exec-meeting-weekly-autostart measures.
  begin
    select id into v_report_id from exec_reports
     where officer='ceo' and period=v_period order by created_at desc limit 1;

    if v_report_id is not null then
      for p in select (e->>'rank')::int prank, e->>'title' ptitle, e->>'owner' powner,
                      e->>'why' pwhy, e->>'priority' phealth
                 from jsonb_array_elements(recs) e order by (e->>'rank')::int
      loop
        if not exists (select 1 from agent_actions a
                        where a.target_table='exec_reports'
                          and a.target_id = v_report_id::text
                          and coalesce(a.title,'') = 'Exec priority '||p.prank||': '||p.ptitle) then
          insert into agent_actions (agent, kind, status, risk, title, recommendation, detail,
                                     target_table, target_id)
          values (coalesce(p.powner,'ceo'), 'report_recommendation', 'pending',
                  case when p.phealth='red' then 'high' else 'medium' end,
                  'Exec priority '||p.prank||': '||p.ptitle,
                  coalesce(p.pwhy,'Ranked priority '||p.prank||' from the '||v_period||' executive meeting.'),
                  jsonb_build_object('source','fn_exec_meeting','period',v_period,'rank',p.prank,
                                     'owner',p.powner,'health',p.phealth,'report_id',v_report_id),
                  'exec_reports', v_report_id::text);
          v_raised := v_raised + 1;
        end if;
      end loop;
    end if;
  exception when others then
    v_raised := -1;
  end;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('exec_meeting',now(),now(),'ok',
    jsonb_build_object('os_green',v_green,'os_amber',v_amber,'os_red',v_red,'findings',jsonb_array_length(findings),'actions',actions,
      'priorities',jsonb_array_length(recs),'challenges',v_ch,'raised_for_approval',v_raised),
    'Executive meeting '||v_period||': '||v_green||' green / '||v_amber||' amber / '||v_red||' red across ten operating systems, '||actions||' actions assigned, '
    ||jsonb_array_length(recs)||' ranked priorities, '
    ||case when v_ch < 0 then 'the challenge round failed' else v_ch||' challenge(s) put to a second officer' end
    ||', '||case when v_raised < 0 then 'raising priorities for approval failed' else v_raised||' priority(ies) raised for founder approval' end||'.');

  return jsonb_build_object('week',v_period,'green',v_green,'amber',v_amber,'red',v_red,
                            'findings',jsonb_array_length(findings),'actions',actions,
                            'priorities',jsonb_array_length(recs),'challenges',v_ch,
                            'raised_for_approval',v_raised,'metrics',m);
end $function$


CREATE OR REPLACE FUNCTION public.fn_execution_run(p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_agent text; v_aa bigint; v_queue jsonb;
        v_done integer := 0; v_failed integer := 0; v_cancelled integer := 0;
begin
  for r in
    select a.id, a.correlation_id, a.action_class, a.risk_tier, a.request,
           d.id as dr_id, d.status as dr_status, d.gate_verdict as dr_verdict,
           d.recommendation, d.problem, d.decided_by
      from public.action_execution a
      left join public.decision_record d on d.id::text = a.request ->> 'decision_record_id'
     where a.status in ('queued','stalled')
     order by a.created_at
     limit greatest(coalesce(p_limit, 25), 1)
  loop
    -- NOT EXECUTABLE. The gate refused it, or it never reached the gate, or the decision is gone.
    if r.dr_id is null or coalesce(r.dr_verdict,'') <> 'passed'
       or coalesce(r.dr_status,'') not in ('approved','executed') then
      update public.action_execution
         set status      = 'cancelled',
             attempts    = coalesce(attempts,0) + 1,
             started_at  = coalesce(started_at, now()),
             finished_at = now(),
             response    = coalesce(response,'{}'::jsonb) || jsonb_build_object(
                             'ran_at', now(), 'outcome', 'cancelled',
                             'reason', case when r.dr_id is null
                                            then 'the decision this action came from no longer exists'
                                            else format('decision_record %s is %s and the gate said %s — not executable',
                                                        r.dr_id, coalesce(r.dr_status,'?'),
                                                        coalesce(r.dr_verdict,'nothing')) end)
       where id = r.id;
      v_cancelled := v_cancelled + 1;
      continue;
    end if;

    -- WHO THE DECISION NAMED. route_to is the party the engine chose, and it is a real identity in
    -- two different registers: an employee (org_agents) or a category desk (agent_knowledge, where
    -- 'cat:signage' carries 8 rows of its own knowledge). Failing that, the decider carries it.
    v_agent := coalesce(
      (select o.agent_key from public.org_agents o
        where o.agent_key = nullif(btrim(r.request ->> 'route_to'),'') and o.active limit 1),
      (select k.agent_key from public.agent_knowledge k
        where k.agent_key = nullif(btrim(r.request ->> 'route_to'),'') limit 1),
      (select o2.agent_key from public.org_agents o2
        where o2.agent_key = nullif(btrim(r.decided_by),'') and o2.active limit 1));

    if v_agent is null then
      update public.action_execution
         set status      = 'failed',
             attempts    = coalesce(attempts,0) + 1,
             started_at  = coalesce(started_at, now()),
             finished_at = now(),
             response    = coalesce(response,'{}'::jsonb) || jsonb_build_object(
                             'ran_at', now(), 'outcome', 'failed',
                             'reason', format('route_to %L resolves to no active employee and no category desk, and decider %L is not an active employee either',
                                              r.request ->> 'route_to', r.decided_by))
       where id = r.id;
      v_failed := v_failed + 1;
      continue;
    end if;

    -- PERFORM IT: the decision is handed to the actor it named.
    insert into public.agent_actions(agent, kind, title, recommendation, detail, risk, status, decided_by)
    values (v_agent, r.action_class,
            left(coalesce(nullif(btrim(r.problem),''), 'decision_record ' || r.dr_id::text), 180),
            coalesce(nullif(btrim(r.recommendation),''), 'carry out the decision on record'),
            jsonb_build_object('decision_record_id', r.dr_id, 'correlation_id', r.correlation_id,
                               'execution_id', r.id, 'route_to', r.request ->> 'route_to',
                               'source', 'fn_execution_run'),
            coalesce(r.risk_tier, 'low'), 'pending', r.decided_by)
    returning id into v_aa;

    -- A BEFORE trigger on agent_actions may swallow the row (dedupe_it_incident returns NULL for a
    -- duplicate open incident). No artefact means nothing was delivered, so it is not a success.
    if v_aa is null then
      update public.action_execution
         set status      = 'failed',
             attempts    = coalesce(attempts,0) + 1,
             started_at  = coalesce(started_at, now()),
             finished_at = now(),
             response    = coalesce(response,'{}'::jsonb) || jsonb_build_object(
                             'ran_at', now(), 'outcome', 'failed',
                             'reason', format('delivery to %L was refused by a trigger on agent_actions', v_agent))
       where id = r.id;
      v_failed := v_failed + 1;
      continue;
    end if;

    update public.action_execution
       set status      = 'succeeded',
           attempts    = coalesce(attempts,0) + 1,
           started_at  = coalesce(started_at, now()),
           finished_at = now(),
           response    = coalesce(response,'{}'::jsonb) || jsonb_build_object(
                           'ran_at', now(), 'outcome', 'succeeded',
                           'agent_action_id', v_aa, 'delivered_to', v_agent,
                           'decision_record_id', r.dr_id)
     where id = r.id;

    update public.decision_record
       set status = 'executed'
     where id = r.dr_id and status = 'approved';

    v_done := v_done + 1;
  end loop;

  select jsonb_object_agg(status, n) into v_queue
    from (select status, count(*) n from public.action_execution group by 1) z;

  return jsonb_build_object('executed', v_done, 'failed', v_failed, 'cancelled', v_cancelled,
                            'queue', coalesce(v_queue,'{}'::jsonb), 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_execution_sweep(p_stall_minutes integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_exec integer := 0; v_trace integer := 0; v_queue jsonb;
begin
  with seen as (
    select a.id,
           case
             when d.id is null                                        then 'cancelled'
             when d.status = 'executed'                               then 'succeeded'
             when d.gate_verdict = 'refused'
               or d.status not in ('approved','executed')             then 'cancelled'
             when a.created_at < now() - make_interval(mins => greatest(coalesce(p_stall_minutes,60), 1))
                                                                      then 'stalled'
             else a.status
           end as new_status,
           d.id as dr_id, d.status as dr_status, d.gate_verdict as dr_verdict
      from public.action_execution a
      left join public.decision_record d on d.id::text = a.request ->> 'decision_record_id'
     where a.status = 'queued')
  update public.action_execution a
     set status      = s.new_status,
         attempts    = coalesce(a.attempts, 0) + 1,
         started_at  = coalesce(a.started_at, now()),
         finished_at = case when s.new_status in ('succeeded','cancelled') then now() else a.finished_at end,
         response    = coalesce(a.response, '{}'::jsonb) || jsonb_build_object(
                         'swept_at', now(), 'observed', s.new_status,
                         'decision_record_id', s.dr_id,
                         'decision_status', s.dr_status, 'gate_verdict', s.dr_verdict)
    from seen s
   where s.id = a.id and s.new_status <> 'queued';
  get diagnostics v_exec = row_count;

  update public.decision_trace t
     set outcome_status = a.status,
         outcome        = jsonb_build_object('execution_id', a.id, 'status', a.status,
                            'action_class', a.action_class, 'attempts', a.attempts,
                            'finished_at', a.finished_at),
         evaluated_at   = now()
    from public.action_execution a
   where a.correlation_id = t.correlation_id
     and t.entity_type = 'decision_record'
     and coalesce(t.outcome_status,'') is distinct from a.status;
  get diagnostics v_trace = row_count;

  select jsonb_object_agg(status, n) into v_queue
    from (select status, count(*) n from public.action_execution group by 1) z;

  return jsonb_build_object('executions_settled', v_exec, 'traces_updated', v_trace,
                            'queue', coalesce(v_queue, '{}'::jsonb), 'swept_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_experience_promote()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_promoted int:=0; v_rejected int:=0; v_agent text;
begin
  for r in select m.* from org_memory m
           where m.active and m.kind='lesson'
             and m.created_at < now() - interval '7 days'
             and not exists (select 1 from agent_knowledge k
                             where k.layer='experience' and k.topic like '%[org#'||m.id||']')
  loop
    if exists (select 1 from policy_rules p where p.active and r.content ~* p.forbid_regex) then
      v_rejected := v_rejected + 1;
      insert into founder_alerts(level,event,detail,channel)
        values ('warn','experience_promotion_blocked',
                'org_memory lesson #'||r.id||' contradicts policy_rules and was NOT promoted: '||left(r.content,300),'system');
    else
      select coalesce(d.brain_agent,'_global') into v_agent from org_departments d where d.dept_key=r.scope;
      insert into agent_knowledge(agent_key, topic, content, priority, layer)
        values (coalesce(v_agent,'_global'),
                'Experience: '||left(regexp_replace(r.content,'^\[[a-z]+\]\s*',''),60)||' [org#'||r.id||']',
                r.content, 5, 'experience');
      v_promoted := v_promoted + 1;
    end if;
  end loop;
  return jsonb_build_object('promoted', v_promoted, 'lint_rejected', v_rejected);
end $function$


CREATE OR REPLACE FUNCTION public.fn_experiment_assign(p_key text, p_subject text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare e record; existing text; roll int; acc int:=0; v jsonb; chosen text;
begin
  select * into e from experiments where key=p_key and status='running';
  if e is null then return null; end if;
  select variant into existing from experiment_assignments where experiment=p_key and subject=p_subject;
  if existing is not null then return existing; end if;
  roll := (abs(('x'||substr(md5(p_key||':'||p_subject),1,8))::bit(32)::int) % 100);
  for v in select * from jsonb_array_elements(e.variants) loop
    acc := acc + coalesce((v->>'weight')::int,0);
    if roll < acc then chosen := v->>'name'; exit; end if;
  end loop;
  chosen := coalesce(chosen, (e.variants->0->>'name'));
  insert into experiment_assignments(experiment,subject,variant) values(p_key,p_subject,chosen) on conflict do nothing;
  return chosen;
end $function$


CREATE OR REPLACE FUNCTION public.fn_experiment_record(p_key text, p_subject text, p_event text, p_value numeric DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v text;
begin
  select variant into v from experiment_assignments where experiment=p_key and subject=p_subject;
  insert into experiment_events(experiment,subject,variant,event,value) values(p_key,p_subject,v,p_event,p_value);
end $function$


CREATE OR REPLACE FUNCTION public.fn_experiment_results(p_key text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_object_agg(variant, stats) from (
    select a.variant,
      jsonb_build_object(
        'subjects', count(distinct a.subject),
        'conversions', count(distinct e.subject) filter (where e.event='convert'),
        'conv_rate_pct', round(100.0*count(distinct e.subject) filter (where e.event='convert')/nullif(count(distinct a.subject),0),1)
      ) stats
    from experiment_assignments a left join experiment_events e on e.experiment=a.experiment and e.subject=a.subject
    where a.experiment=p_key group by a.variant) z;
$function$


CREATE OR REPLACE FUNCTION public.fn_expiring_docs(p_days integer DEFAULT 60)
 RETURNS TABLE(id bigint, company_name text, sector text, doc text, expiry date, days_left integer, status text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select l.id, l.company_name, l.sector, d.label, d.exp, (d.exp-current_date),
    case when d.exp<current_date then 'expired' when d.exp<=current_date+30 then 'expiring' else 'soon' end
  from leads l, lateral (values ('Trade license',l.license_expiry),('ISO certification',l.iso_expiry),
     ('Insurance',l.insurance_expiry),('Manufacturer authorization',l.manufacturer_auth_expiry)) d(label,exp)
  where d.exp is not null and d.exp <= current_date + p_days
    and coalesce(l.approval_status,'')='approved'
  order by d.exp asc;
$function$


CREATE OR REPLACE FUNCTION public.fn_external_authority(p_query text DEFAULT NULL::text, p_max_chars integer DEFAULT 2800)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_cap  int := greatest(coalesce(p_max_chars, 2800), 400);
  v_q    text := nullif(btrim(coalesce(p_query, '')), '');
  v_out  text := '';
  v_part text;
begin
  -- Relevance is a plain ILIKE over the words of the question, not full-text: these are 118 rows,
  -- the index would never be used, and a tsquery that fails to parse would silently return nothing.
  -- When no question is supplied, or nothing matches, the most authoritative rows are emitted
  -- anyway — an employee that does not know a regulation exists cannot ask about it.

  select string_agg('- ['||coalesce(r.authority,'?')||'] '||r.title
                    ||case when coalesce(r.doc_ref,'') <> '' then ' ('||r.doc_ref||')' else '' end
                    ||case when r.effective_date is not null then ' — in force '||r.effective_date else '' end
                    ||case when coalesce(r.summary,'') <> '' then E'\n    '||left(regexp_replace(r.summary,'\s+',' ','g'), 260) else '' end,
                    E'\n' order by (v_q is not null and (r.title ilike '%'||v_q||'%' or coalesce(r.summary,'') ilike '%'||v_q||'%')) desc,
                                   r.effective_date desc nulls last, r.id)
    into v_part
    from (select * from public.regulations
           where status = 'active' and approved_at is not null
           order by (v_q is not null and (title ilike '%'||v_q||'%' or coalesce(summary,'') ilike '%'||v_q||'%')) desc,
                    effective_date desc nulls last limit 8) r;
  if v_part is not null then
    v_out := v_out || 'UAE REGULATIONS IN FORCE (authoritative — cite the authority and the doc ref when you rely on one):'||E'\n'||v_part||E'\n\n';
  end if;

  select string_agg('- '||s.code||' — '||s.title||case when coalesce(s.authority,'') <> '' then ' ('||s.authority||')' else '' end,
                    E'\n' order by s.code)
    into v_part
    from (select * from public.mdm_standards where coalesce(active,true) order by code limit 14) s;
  if v_part is not null then
    v_out := v_out || 'INDUSTRY STANDARDS THE COMPANY WORKS TO:'||E'\n'||v_part||E'\n\n';
  end if;

  select string_agg('- '||m.name||case when coalesce(m.country,'') <> '' then ' ('||m.country||')' else '' end, ', '
                    order by m.name)
    into v_part
    from (select * from public.mdm_manufacturers where coalesce(active,true) order by name limit 22) m;
  if v_part is not null then
    v_out := v_out || 'MANUFACTURERS ON THE MASTER LIST:'||E'\n'||v_part||E'\n\n';
  end if;

  select string_agg('- '||coalesce(c.authority,'?')||': '||coalesce(c.topic,'(topic unrecorded)')
                    ||case when c.last_checked_at is not null then ' — last checked '||c.last_checked_at::date else ' — NEVER CHECKED' end,
                    E'\n' order by c.last_checked_at desc nulls last, c.id)
    into v_part
    from (select * from public.compliance_sources where active
           order by last_checked_at desc nulls last limit 8) c;
  if v_part is not null then
    v_out := v_out || 'AUTHORITIES THIS COMPANY WATCHES FOR CHANGE:'||E'\n'||v_part||E'\n\n';
  end if;

  select string_agg('- '||coalesce(k.authority,'?')||' '||coalesce(k.code_name,'?')
                    ||' ['||coalesce(k.status,'?')||']', E'\n' order by k.priority nulls last, k.authority)
    into v_part
    from (select * from public.reg_catalog where coalesce(status,'') = 'indexed'
           order by priority nulls last limit 10) k;
  if v_part is not null then
    v_out := v_out || 'REGULATORY CODES ALREADY INDEXED IN THE KNOWLEDGE BASE:'||E'\n'||v_part||E'\n\n';
  end if;

  if v_out = '' then return null; end if;

  return E'\n# LAYER 4 (EXTERNAL) - AUTHORITATIVE SOURCES OUTSIDE THIS COMPANY'||E'\n'
      || 'Spec #7 L541. These are external and authoritative: where they conflict with anything else '
      || 'in this context, they win, and you say so. Do not paraphrase a requirement without naming '
      || 'its authority.'||E'\n\n'
      || left(v_out, v_cap - 300);
end $function$


CREATE OR REPLACE FUNCTION public.fn_fa_acquire(p_name text, p_category text, p_acquire_date date, p_cost numeric, p_salvage numeric, p_life_months integer, p_in_service date DEFAULT NULL::date, p_fund_account text DEFAULT '1000'::text, p_post_gl boolean DEFAULT true, p_by text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare a bigint; j bigint;
begin
  insert into public.fa_assets(name,category,acquire_date,in_service_date,cost,salvage_value,
        useful_life_months,created_by)
    values (p_name,p_category,coalesce(p_acquire_date,current_date),
            coalesce(p_in_service,p_acquire_date,current_date),
            round(p_cost,2),round(coalesce(p_salvage,0),2),p_life_months,p_by)
    returning id into a;
  update public.fa_assets set asset_no='FA-'||lpad(a::text,6,'0') where id=a;
  if p_post_gl then                                  -- Dr Fixed Asset  Cr funding account
    j := public.fn_gl_entry(coalesce(p_acquire_date,current_date),
           'Asset acquisition '||p_name, 'fa_acquire', a::text,
           jsonb_build_array(jsonb_build_object('account','1600','debit',round(p_cost,2)),
                             jsonb_build_object('account',p_fund_account,'credit',round(p_cost,2))), p_by);
  end if;
  return a;
end $function$


CREATE OR REPLACE FUNCTION public.fn_fa_depreciate(p_asset bigint, p_period date)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare a record; depreciable numeric(18,2); remaining numeric(18,2);
        monthly numeric(18,2); amt numeric(18,2); j bigint;
begin
  select * into a from public.fa_assets where id=p_asset;
  if a.id is null then raise exception 'asset % not found', p_asset; end if;
  if a.status <> 'active' then return null; end if;
  if p_period < a.in_service_date then return null; end if;               -- not yet in service
  if exists (select 1 from public.fa_depreciation where asset_id=p_asset and period=p_period) then
    return null;                                                          -- already booked
  end if;
  depreciable := a.cost - a.salvage_value;
  remaining := depreciable - a.accumulated_depreciation;
  if remaining <= 0 then
    update public.fa_assets set status='fully_depreciated' where id=p_asset; return null;
  end if;
  monthly := round(depreciable / a.useful_life_months, 2);
  amt := least(monthly, remaining);                                       -- final period soaks rounding
  j := public.fn_gl_entry(p_period, 'Depreciation '||a.asset_no||' '||to_char(p_period,'YYYY-MM'),
         'fa_deprec', p_asset::text,
         jsonb_build_array(jsonb_build_object('account',a.expense_account,'debit',amt),
                           jsonb_build_object('account',a.accum_account,'credit',amt)), null);
  insert into public.fa_depreciation(asset_id,period,amount,gl_journal_id) values (p_asset,p_period,amt,j);
  update public.fa_assets
     set accumulated_depreciation = accumulated_depreciation + amt,
         status = case when accumulated_depreciation + amt >= depreciable then 'fully_depreciated' else 'active' end
   where id=p_asset;
  return j;
end $function$


CREATE OR REPLACE FUNCTION public.fn_fa_dispose(p_asset bigint, p_date date, p_proceeds numeric DEFAULT 0, p_proceeds_account text DEFAULT '1000'::text, p_by text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare a record; nbv numeric(18,2); proceeds numeric(18,2); gainloss numeric(18,2);
        gl_lines jsonb; j bigint;
begin
  select * into a from public.fa_assets where id=p_asset;
  if a.id is null then raise exception 'asset % not found', p_asset; end if;
  if a.status='disposed' then raise exception 'asset % already disposed', p_asset; end if;
  proceeds := round(coalesce(p_proceeds,0),2);
  nbv := a.cost - a.accumulated_depreciation;
  gainloss := proceeds - nbv;                          -- +gain / -loss
  gl_lines := jsonb_build_array(
      jsonb_build_object('account',a.accum_account,'debit',a.accumulated_depreciation),  -- clear accum
      jsonb_build_object('account',a.asset_account,'credit',a.cost));                     -- remove cost
  if proceeds > 0 then
    gl_lines := gl_lines || jsonb_build_object('account',p_proceeds_account,'debit',proceeds);
  end if;
  if gainloss > 0 then
    gl_lines := gl_lines || jsonb_build_object('account','4300','credit',gainloss);       -- gain
  elsif gainloss < 0 then
    gl_lines := gl_lines || jsonb_build_object('account','6500','debit',-gainloss);       -- loss
  end if;
  j := public.fn_gl_entry(coalesce(p_date,current_date), 'Disposal '||a.asset_no,
         'fa_dispose', p_asset::text, gl_lines, p_by);
  update public.fa_assets set status='disposed', disposed_date=coalesce(p_date,current_date) where id=p_asset;
  return j;
end $function$


CREATE OR REPLACE FUNCTION public.fn_fa_run_depreciation(p_period date DEFAULT NULL::date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare per date := coalesce(p_period, (date_trunc('month',current_date)+interval '1 month -1 day')::date);
        r record; n int := 0; j bigint;
begin
  for r in select id from public.fa_assets where status='active' and in_service_date <= per loop
    j := public.fn_fa_depreciate(r.id, per);
    if j is not null then n := n + 1; end if;
  end loop;
  return n;
end $function$


CREATE OR REPLACE FUNCTION public.fn_faq_answer(p_text text, p_min_rank numeric DEFAULT 0.15, p_embedding vector DEFAULT NULL::vector, p_min_similarity numeric DEFAULT 0.86)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_q tsquery; v_tpl record; v_sim numeric;
begin
  if p_text is null or length(btrim(p_text)) < 2 then
    return jsonb_build_object('answered', false, 'reason', 'input too short');
  end if;

  -- 1. Fixed intents. No retrieval, no model.
  select * into v_tpl from response_template
   where active and (
     (intent='greeting' and p_text ~* '^\s*(hi|hey|hello|salam|marhaba|good (morning|afternoon|evening))\W*$') or
     (intent='thanks'   and p_text ~* '^\s*(thanks|thank you|thx|shukran|much appreciated)\W*$')
   ) limit 1;
  if found then
    update response_template set used_count = used_count + 1 where key = v_tpl.key;
    return jsonb_build_object('answered', true, 'source', 'template', 'key', v_tpl.key,
                              'answer', v_tpl.body, 'confidence', 1.0);
  end if;

  -- 2. Keyword match. Cheap and precise when the wording lines up.
  v_q := websearch_to_tsquery('english', p_text);
  if v_q is not null then
    select f.question, f.answer,
           ts_rank(to_tsvector('english', coalesce(f.question,'')||' '||coalesce(f.answer,'')), v_q) as rank
      into r
      from company_faq f
     where f.public and f.status='approved'
       and to_tsvector('english', coalesce(f.question,'')||' '||coalesce(f.answer,'')) @@ v_q
     order by rank desc limit 1;
    if found and r.rank >= p_min_rank then
      return jsonb_build_object('answered', true, 'source', 'faq_keyword', 'question', r.question,
                                'answer', r.answer, 'confidence', round(r.rank::numeric, 4));
    end if;
  end if;

  -- 3. Semantic match. Catches the same question asked in different words.
  if p_embedding is not null then
    select f.question, f.answer, 1 - (f.embedding_gte <=> p_embedding) as sim into r
      from company_faq f
     where f.public and f.status='approved' and f.embedding_gte is not null
     order by f.embedding_gte <=> p_embedding limit 1;
    if found then
      v_sim := round((r.sim)::numeric, 4);
      if v_sim >= p_min_similarity then
        return jsonb_build_object('answered', true, 'source', 'faq_semantic', 'question', r.question,
                                  'answer', r.answer, 'confidence', v_sim);
      end if;
      return jsonb_build_object('answered', false, 'reason', 'no confident FAQ match',
                                'best_similarity', v_sim);
    end if;
  end if;

  return jsonb_build_object('answered', false, 'reason', 'no confident FAQ match');
end $function$


CREATE OR REPLACE FUNCTION public.fn_field_normalise(p_field_id text, p_value text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_type text; v_tol integer; v_norm text; v_num numeric; v_match text[];
begin
  if p_value is null then return null; end if;
  select answer_type, numeric_tolerance into v_type, v_tol
    from public.field_definition where field_id = p_field_id;

  v_norm := lower(btrim(regexp_replace(p_value, '\s+', ' ', 'g')));

  if coalesce(v_type,'') in ('number','numeric','integer','decimal','quantity') then
    v_match := regexp_match(replace(v_norm, ',', ''), '(-?[0-9]+(?:\.[0-9]+)?)');
    if v_match is not null then
      v_num := v_match[1]::numeric;
      return trim(to_char(round(v_num, coalesce(v_tol, 2)), 'FM99999999999990.99999999'));
    end if;
  end if;

  return v_norm;
end $function$


CREATE OR REPLACE FUNCTION public.fn_field_value_allowed(p_field_id text, p_value text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when p_value is null then true
    else coalesce(
      (select p_value = any(fd.allowed_values) from public.field_definition fd
        where fd.field_id = p_field_id and fd.allowed_values is not null), true)
  end;
$function$


CREATE OR REPLACE FUNCTION public.fn_finance_ai()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k record; fc jsonb; v_health numeric; n_esc int;
  s_run numeric; s_prof numeric; s_coll numeric; s_bud numeric;
begin
  select * into k from finance_kpis;
  fc := fn_finance_forecast();

  s_run := case when k.runway_months is null then (case when k.cash>0 then 80 else 10 end)
                when k.runway_months>=6 then 100 when k.runway_months>=3 then 70 when k.runway_months>=1 then 40 else 10 end;
  s_prof := case when k.net_income>0 then 100 when k.margin_pct is null then 50 else greatest(10, least(100, 60 + k.margin_pct/5)) end;
  s_coll := coalesce(k.collection_rate, 70);
  s_bud := greatest(0, 100 - coalesce(k.budget_overruns,0)*20);
  v_health := round(s_run*0.35 + s_prof*0.25 + s_coll*0.20 + s_bud*0.20, 1);

  insert into finance_kpi_snapshots(snapshot_date, kpis, forecast)
  values (current_date, to_jsonb(k) || jsonb_build_object('health',v_health), fc)
  on conflict (snapshot_date) do update set kpis=excluded.kpis, forecast=excluded.forecast, created_at=now();

  -- ESCALATIONS to founder (never auto-resolved; agent never moves money)
  if k.cash <= 0 then
    perform fin_alert('cash_negative','high','Book cash is negative',
      'Book cash is '||to_char(k.cash,'FM999999990.00')||' AED and owner capital is 0. Record a capital injection or fund operations to restore a positive position.');
  elsif k.runway_months is not null and k.runway_months < 3 then
    perform fin_alert('low_runway','high','Low cash runway',
      'Runway is ~'||k.runway_months||' months at the current burn. Increase revenue, cut spend, or add capital.');
  end if;
  if k.ar_overdue > 0 then
    perform fin_alert('ar_overdue', case when k.ar_overdue>=500 then 'high' else 'medium' end, 'Overdue collections',
      'AED '||to_char(k.ar_overdue,'FM999999990.00')||' in supplier commission is overdue. Reminders are automated; review whether to escalate or apply fines.');
  end if;
  if k.ap_overdue > 0 then
    perform fin_alert('ap_overdue','high','Overdue bills to pay',
      'AED '||to_char(k.ap_overdue,'FM999999990.00')||' in supplier bills is overdue. Review and pay — money movement is yours to action.');
  end if;
  if coalesce(k.budget_overruns,0) > 0 then
    perform fin_alert('budget_overrun','medium','Budget overrun',
      k.budget_overruns||' expense budget line(s) are over 110% of plan. Review spend or re-budget.');
  end if;

  select count(*) into n_esc from agent_actions where agent='finance_ai' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at',now(),'health',v_health,'kpis',to_jsonb(k),'forecast',fc,'open_alerts',n_esc);
end $function$


CREATE OR REPLACE FUNCTION public.fn_finance_forecast()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with base as (
    select (select coalesce(sum(balance),0) from gl_account_balances where code in ('1000','1050')) as cash,
           (select coalesce(sum(case when ga.type='revenue' then l.credit-l.debit else 0 end),0)
              from gl_journal_lines l join gl_journal j on j.id=l.journal_id and j.status='posted'
              join gl_accounts ga on ga.code=l.account_code where j.entry_date>=current_date-30) as rev30,
           (select coalesce(sum(case when ga.type='expense' then l.debit-l.credit else 0 end),0)
              from gl_journal_lines l join gl_journal j on j.id=l.journal_id and j.status='posted'
              join gl_accounts ga on ga.code=l.account_code where j.entry_date>=current_date-30) as exp30
  ),
  hz as (
    select h,
      (select coalesce(sum(amount_due),0) from supplier_dues where status not in ('paid','waived') and coalesce(due_date_30,reveal_date+30) <= current_date + h) as ar_in,
      (select coalesce(sum(balance_due),0) from ap_open_bills where coalesce(due_date, bill_date) <= current_date + h) as ap_out
    from (values (30),(60),(90)) v(h)
  )
  select jsonb_build_object(
    'as_of', now(),
    'cash_now', (select cash from base),
    'assumptions', jsonb_build_object('revenue_run_rate_30d',(select rev30 from base),'expense_run_rate_30d',(select exp30 from base)),
    'horizons', (select jsonb_agg(jsonb_build_object(
        'days', h,
        'expected_inflows', round(ar_in + (select rev30 from base)*(h/30.0), 2),
        'expected_outflows', round(ap_out + (select exp30 from base)*(h/30.0), 2),
        'projected_cash', round((select cash from base) + ar_in + (select rev30 from base)*(h/30.0) - ap_out - (select exp30 from base)*(h/30.0), 2),
        'revenue_forecast', round((select rev30 from base)*(h/30.0), 2)
      ) order by h) from hz)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_flag(p_key text, p_ctx jsonb DEFAULT '{}'::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare f record; aud jsonb; h int; subj text;
begin
  select * into f from feature_flags where key=p_key;
  if f is null or not f.enabled then return false; end if;
  aud := coalesce(f.audience,'{}');
  -- audience gates
  if aud ? 'country' and not (upper(coalesce(p_ctx->>'country','')) = any(select upper(jsonb_array_elements_text(aud->'country')))) then return false; end if;
  if aud ? 'category' and not (lower(coalesce(p_ctx->>'category','')) = any(select lower(jsonb_array_elements_text(aud->'category')))) then return false; end if;
  if aud ? 'role' and not (lower(coalesce(p_ctx->>'role','')) = any(select lower(jsonb_array_elements_text(aud->'role')))) then return false; end if;
  if coalesce((aud->>'enterprise')::boolean,false) and not coalesce((p_ctx->>'enterprise')::boolean,false) then return false; end if;
  -- percentage rollout, deterministic by subject
  subj := coalesce(p_ctx->>'subject', p_ctx->>'email', p_ctx->>'id', 'anon');
  h := (abs(('x'||substr(md5(p_key||':'||subj),1,8))::bit(32)::int) % 100);
  return h < coalesce(f.rollout_pct,100);
end $function$


CREATE OR REPLACE FUNCTION public.fn_founder_apply_setting(p_key text, p_value text, p_inbound text, p_actor text DEFAULT 'founder'::text, p_channel text DEFAULT 'whatsapp'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_old text; v_new text; v_num numeric; v_bool boolean; v_refusal text;
begin
  select * into r from public.fn_founder_settings() s where s.setting_key = p_key;

  if not found then
    v_refusal := 'I cannot change "' || coalesce(p_key,'(nothing)') || '" from a message. '
              || 'The settings I can change this way are: '
              || (select string_agg(s.setting_key, ', ' order by s.setting_key) from public.fn_founder_settings() s)
              || '. Money, refunds and the three go-live switches are deliberately not on that list.';
    insert into public.founder_directive(actor, channel, inbound, setting_key, applied, refusal)
    values (p_actor, p_channel, left(coalesce(p_inbound,''), 2000), p_key, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal);
  end if;

  v_old := r.current_value;

  -- TYPE AND BOUNDS. A mistyped number must not become an incident before anyone reads the reply.
  if r.kind in ('int','number') then
    begin v_num := p_value::numeric; exception when others then
      v_refusal := '"' || p_value || '" is not a number, and ' || p_key || ' takes one.'; end;
    if v_refusal is null and r.kind = 'int' and v_num <> trunc(v_num) then
      v_refusal := p_key || ' takes a whole number; "' || p_value || '" is not one.';
    end if;
    if v_refusal is null and r.min_val is not null and v_num < r.min_val then
      v_refusal := p_key || ' has a floor of ' || r.min_val || ' on this channel, and you asked for ' || v_num || '.';
    end if;
    if v_refusal is null and r.max_val is not null and v_num > r.max_val then
      v_refusal := p_key || ' has a ceiling of ' || r.max_val || ' on this channel, and you asked for ' || v_num
                || '. Change it in the OS if you really mean that.';
    end if;
    v_new := case when r.kind = 'int' then trunc(v_num)::bigint::text else v_num::text end;
  elsif r.kind = 'bool' then
    v_bool := case lower(btrim(p_value))
                when 'true' then true when 'on' then true when 'yes' then true when 'enable' then true when 'enabled' then true when '1' then true
                when 'false' then false when 'off' then false when 'no' then false when 'disable' then false when 'disabled' then false when '0' then false
                else null end;
    if v_bool is null then v_refusal := '"' || p_value || '" is not on or off, and ' || p_key || ' is a switch.';
    else v_new := case when v_bool then 'true' else 'false' end; end if;
  else
    v_new := p_value;
  end if;

  if v_refusal is not null then
    insert into public.founder_directive(actor, channel, inbound, setting_key, old_value, applied, refusal)
    values (p_actor, p_channel, left(coalesce(p_inbound,''), 2000), p_key, v_old, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal, 'key', p_key, 'old', v_old);
  end if;

  if v_old is not distinct from v_new then
    insert into public.founder_directive(actor, channel, inbound, setting_key, old_value, new_value, applied, refusal)
    values (p_actor, p_channel, left(coalesce(p_inbound,''), 2000), p_key, v_old, v_new, false, 'already at that value');
    return jsonb_build_object('ok', true, 'unchanged', true, 'key', p_key, 'old', v_old, 'new', v_new,
      'message', p_key || ' is already ' || v_new || '. Nothing to change.');
  end if;

  if r.store = 'app_secrets' then
    update public.app_secrets set value = v_new, updated_at = now() where key = p_key;
  else
    update public.decision_policy set value = to_jsonb(v_new), updated_at = now() where key = p_key;
    -- decision_policy holds real jsonb types, not strings: keep numbers as numbers.
    if r.kind in ('int','number') then
      update public.decision_policy set value = to_jsonb(v_new::numeric) where key = p_key;
    elsif r.kind = 'bool' then
      update public.decision_policy set value = to_jsonb(v_new::boolean) where key = p_key;
    end if;
  end if;

  insert into public.founder_directive(actor, channel, inbound, setting_key, old_value, new_value, applied)
  values (p_actor, p_channel, left(coalesce(p_inbound,''), 2000), p_key, v_old, v_new, true);

  insert into public.agent_runs(agent, status, counts, note, started_at, finished_at)
  values ('founder_directive', 'ok',
          jsonb_build_object('key', p_key, 'old', v_old, 'new', v_new, 'channel', p_channel),
          'The founder changed ' || p_key || ' from ' || coalesce(v_old,'(unset)') || ' to ' || v_new
          || ' by ' || p_channel || '. Instruction: ' || left(coalesce(p_inbound,''), 200), now(), now());

  return jsonb_build_object('ok', true, 'key', p_key, 'old', v_old, 'new', v_new,
    'message', 'Done — ' || p_key || ' changed from ' || coalesce(v_old,'(unset)') || ' to ' || v_new || '. ' || r.description);
end $function$


CREATE OR REPLACE FUNCTION public.fn_founder_approval_refund_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not exists (select 1 from public.phase_c_action_class
                 where action_class = new.action_class and founder_approval_required) then
    raise exception 'founder_approval_request: % is not a founder-approval action class. The founder is not the company''s approval queue; only a specific refund decision reaches him.', new.action_class
      using errcode = '23514';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_founder_brief()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_owner text; v_run bigint; v_fq jsonb; v_fq_n int := 0; v_fq_age int; v_fq_list text;
  v_auto_q int := 0; v_stalled int := 0;
  v_reg int; v_cust int; v_inq7 int; v_q7 int; v_deals int; v_rev numeric;
  v_pend int; v_kyc int; v_refunds int; v_reviews int;
  v_hot int; v_gap int; v_newsup int; v_newcust int;
  v_bd_q int; v_bd_sent int; v_chat_open int; v_viol int;
  v_officer text; v_health jsonb;
  v_topcats text; v_qpr numeric; v_conv numeric;
  v_expired int; v_crit int; v_crit_noise int := 0; v_decisions text; v_dn int := 0; v_fa_pending int := 0;
  v_body text; v_subj text;
  v_auto_cleared int; v_auto_appr int; v_handled text;   -- Phase B additions
  v_obj_open int := 0; v_obj_await int := 0; v_obj_done24 int := 0; v_task_done24 int := 0; v_obj_line text;  -- Org-foundation additions
  -- The four figures the overnight brief never carried: fraud rejected, matching accuracy,
  -- AI cost, and the emerging opportunity. Plus goal attainment, so the brief states progress
  -- against a target rather than only activity.
  v_fraud int := 0; v_match_now numeric; v_match_prev numeric;
  v_ai_cost numeric := 0; v_ai_cost_prev numeric := 0; v_ai_delta numeric := 0;
  v_opp text; v_goal numeric; v_goal_j jsonb;
  v_scope_confirmed int; v_scope_total int;   -- the supply side of matching accuracy, 13 Aug 2026
begin
  select split_part(coalesce(value,'management@quotesdone.com'),',',1) into v_owner from app_secrets where key='admin_emails';
  if v_owner is null then v_owner := 'management@quotesdone.com'; end if;
  insert into agent_runs(agent, started_at) values ('brief', now()) returning id into v_run;

  begin select coalesce(registered_supplier_count(),0) into v_reg; exception when others then v_reg := 0; end;
  select count(*) into v_cust from customers;
  select count(*) into v_inq7 from inquiries where created_at >= now()-interval '7 days';
  select count(*) into v_q7 from quotes where created_at >= now()-interval '7 days';
  select count(*) into v_deals from transactions;
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev from transactions where coalesce(fee_status,'')<>'refunded' and coalesce(refund_status,'')<>'approved';
  select count(*) into v_pend from agent_actions where status in ('pending','held_for_review','proposed','open','needs_review');
  select count(*) into v_kyc from leads where approval_status='pending';
  select count(*) into v_refunds from transactions where refund_status='requested';
  select count(*) into v_reviews from inbound_messages where needs_review=true;
  select count(distinct i.id) into v_hot from inquiries i join quotes q on q.inquiry_id=i.id left join transactions t on t.inquiry_id=i.id where t.id is null and i.status not in ('completed','accepted','closed','cancelled');
  select count(*) into v_gap from inquiries i where i.status not in ('completed','accepted','closed','cancelled') and not exists (select 1 from inquiry_matches m where m.inquiry_id=i.id);
  select count(*) into v_newsup from leads where registration_submitted_at >= now()-interval '7 days';
  select count(*) into v_newcust from customers where created_at >= now()-interval '7 days';
  select count(*) into v_bd_q from outreach where status='queued';
  select count(*) into v_bd_sent from outreach where status='sent';
  select count(*) into v_chat_open from chat_threads where status='open';
  select count(*) into v_viol from chat_violations where created_at >= now()-interval '7 days';

  begin select public.fn_health_index() into v_health; exception when others then v_health := null; end;

  begin
    select string_agg(cat,', ') into v_topcats from (
      select coalesce(nullif(category,''),'(uncategorized)') cat, count(*) n
      from inquiries where created_at>=now()-interval '7 days'
      group by 1 order by n desc limit 3) z;
  exception when others then v_topcats := null; end;

  begin
    select round(avg(qc),1) into v_qpr from (
      select count(*) qc from quotes q join inquiries i on i.id=q.inquiry_id
      where i.created_at>=now()-interval '30 days' group by q.inquiry_id) z;
  exception when others then v_qpr := null; end;
  begin
    select round(100.0*count(distinct t.inquiry_id)/nullif(count(distinct i.id),0),1) into v_conv
    from inquiries i left join transactions t on t.inquiry_id=i.id
    where i.created_at>=now()-interval '30 days';
  exception when others then v_conv := null; end;

  begin select count(*) into v_expired from leads where license_expiry is not null and license_expiry < current_date and coalesce(approval_status,'')='approved'; exception when others then v_expired:=0; end;
    -- SEVERITY HAS SEVEN SPELLINGS AND THIS COUNTED ONE (fixed 11 Aug 2026). founder_alerts.level
  -- carries error(92) warn(51) high(44) critical(41) info(21) warning(2) action(1). Reading only
  -- 'critical' hid every alert written by a routine that spells it 'error' or 'high'. Measured over
  -- the 24h before this change: 9 visible, 24 actually severe, 15 INVISIBLE - and 7 of the 9
  -- visible were 'AI credit low', which the founder has said explicitly does not gate his work.
  -- So he was shown 9 alerts of which 2 mattered, while 15 that mattered were not shown at all.
  select count(*) into v_crit from founder_alerts
   where public.fn_alert_severe(level)
     and event not ilike 'AI credit low%'
     and created_at >= now() - interval '24 hours';
  select count(*) into v_crit_noise from founder_alerts
   where event ilike 'AI credit low%' and created_at >= now() - interval '24 hours';

  begin
    select string_agg('- ['||label||'] '||act, E'\n')
    into v_officer
    from (
      select case er.officer
               when 'strategy' then 'Strategy' when 'operations' then 'Ops'
               when 'procurement_quality' then 'Quality' when 'data_science' then 'Data'
               when 'product_ux' then 'Product' when 'competitive' then 'Compete' else er.officer end as label,
             left(coalesce(rec->>'action',''),160) as act,
             case lower(coalesce(rec->>'impact','')) when 'high' then 0 when 'medium' then 1 else 2 end as ord
      from (select distinct on (officer) officer, recommendations, created_at from exec_reports order by officer, created_at desc) er,
           lateral jsonb_array_elements(er.recommendations) rec
      where coalesce(rec->>'action','') <> ''
      order by ord, label limit 5
    ) z;
  exception when others then v_officer := null; end;

  -- Phase B: what the Chief of Staff handled autonomously in the last 24h.
  select count(*) into v_auto_cleared from agent_actions
    where decided_by='chief_of_staff (auto)' and decided_at >= now()-interval '24 hours';
  begin
    select count(*) into v_auto_appr from leads
      where approval_decided_by='chief_of_staff (auto)' and approved_at >= now()-interval '24 hours';
  exception when others then v_auto_appr := 0; end;
  begin
    -- SUBJECTS, NOT A TALLY. "ops_alert: 3" tells the founder nothing about what was raised for
    -- him, and these rows are then CLOSED. The window also moves from 24 hours to 7 days so that a
    -- row created outside the last day is reported before it is marked digested rather than after.
    select string_agg('- ['||to_char(created_at,'DD Mon HH24:MI')||'] '||type||': '||
                      coalesce(nullif(subject,''),'(no subject)'), E'\n' order by created_at desc)
      into v_handled
    from (select type, subject, created_at from notifications
          where status='digest' and created_at >= now()-interval '7 days'
          order by created_at desc limit 25) z;
  exception when others then v_handled := null; end;

  -- Org foundation: the founder's objectives and how the organization is executing them.
  begin
    select count(*) into v_obj_open from org_objectives where status in ('open','in_progress','blocked');
    select count(*) into v_obj_done24 from org_objectives where status='done' and closed_at >= now()-interval '24 hours';
    select count(*) into v_task_done24 from org_tasks where status='done' and updated_at >= now()-interval '24 hours';
    select count(*) into v_obj_await from org_tasks t
      where t.status in ('proposed','escalated')
        and exists (select 1 from org_objectives o where o.id=t.objective_id and o.status in ('open','in_progress','blocked'));
    select string_agg(
        '- "'||left(o.objective,80)||'" — '||
        (select count(*) from org_tasks t where t.objective_id=o.id and t.status='done')||'/'||
        (select count(*) from org_tasks t where t.objective_id=o.id)||' tasks done'||
        case when (select count(*) from org_tasks t where t.objective_id=o.id and t.status in ('proposed','escalated'))>0
             then ', '||(select count(*) from org_tasks t where t.objective_id=o.id and t.status in ('proposed','escalated'))||' awaiting you'
             else '' end,
        E'\n' order by o.id desc)
      into v_obj_line from org_objectives o where o.status in ('open','in_progress','blocked');
  exception when others then v_obj_open:=0; v_obj_await:=0; v_obj_done24:=0; v_task_done24:=0; v_obj_line:=null; end;

  -- HIS QUEUE, SEPARATE FROM THE MACHINE'S. fn_founder_queue counts only kinds
  -- agent_action_kind_policy marks 'founder' — the ones no agent may settle — and ages them.
  begin
    v_fq := public.fn_founder_queue(5);
    v_fq_n := coalesce((v_fq->>'waiting_on_you_total')::int, 0);
    v_fq_age := (v_fq->>'oldest_days')::int;
    -- The two halves of "not his", counted separately because only one of them is moving.
    select count(*) into v_auto_q from public.agent_actions a
      join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'auto'
     where a.status = 'pending';
    select count(*) into v_stalled from public.agent_actions a
     where a.status in ('held_for_review','proposed','open','needs_review')
       and not exists (select 1 from public.agent_action_kind_policy q
                        where q.kind = a.kind and q.policy = 'founder');
    select string_agg('     · '||(x->>'kind')||' from '||(x->>'from')||' — '||(x->>'title')||
                      ' ('||(x->>'age_days')||'d)', E'\n')
      into v_fq_list from jsonb_array_elements(v_fq->'waiting_on_you') x;
  exception when others then v_fq_n := 0; v_fq_age := null; v_fq_list := null; end;

  select count(*) into v_fa_pending from public.founder_approval_request where state = 'pending';
  v_decisions := '';
  if v_kyc > 0 then v_dn:=v_dn+1; v_decisions := v_decisions||v_dn||'. Approve/deny '||v_kyc||' supplier KYC application(s)'||E'\n'; end if;
  if v_refunds > 0 then v_dn:=v_dn+1; v_decisions := v_decisions||v_dn||'. Resolve '||v_refunds||' refund request(s)'||E'\n'; end if;
  if v_obj_await > 0 then v_dn:=v_dn+1; v_decisions := v_decisions||v_dn||'. '||v_obj_await||' objective step(s) awaiting your approval/input'||E'\n'; end if;
  if v_fq_n > 0 then v_dn:=v_dn+1; v_decisions := v_decisions||v_dn||'. Settle '||v_fq_n||
    ' item(s) no agent is allowed to decide'||
    case when v_fq_age is not null then ' — the oldest has been waiting '||v_fq_age||' day(s)' else '' end||
    E'\n'||coalesce(v_fq_list||E'\n','');
  end if;
  if v_expired > 0 then v_dn:=v_dn+1; v_decisions := v_decisions||v_dn||'. Review '||v_expired||' supplier(s) with EXPIRED trade licence'||E'\n'; end if;
  if v_crit > 0 then v_dn:=v_dn+1; v_decisions := v_decisions||v_dn||'. Address '||v_crit||' severe alert(s) raised in last 24h (critical/error/high'||case when v_crit_noise>0 then '; '||v_crit_noise||' AI-credit notice(s) excluded' else '' end||')'||E'\n'; end if;
  if v_dn = 0 then v_decisions := 'None outstanding.'||E'\n'; end if;

  v_subj := 'QuotesDone daily brief — '||to_char(now() at time zone 'Asia/Dubai','Dy DD Mon');

  -- FRAUD REJECTED: supplier registrations refused, all-time and this week.
  begin select count(*) into v_fraud from public.leads
     where coalesce(approval_status,'') in ('rejected','banned') or coalesce(banned,false);
  exception when others then v_fraud := 0; end;

  -- MATCHING ACCURACY: the share of live RFQs that reached at least one supplier, this 30 days
  -- against the 30 before it. Precisely what it says — not a model score dressed up as one.
  begin
    select round(100.0 * count(*) filter (where exists (select 1 from public.inquiry_matches m where m.inquiry_id = i.id))
                 / greatest(count(*),1))
      into v_match_now from public.inquiries i where i.created_at > now() - interval '30 days';
    select round(100.0 * count(*) filter (where exists (select 1 from public.inquiry_matches m where m.inquiry_id = i.id))
                 / greatest(count(*),1))
      into v_match_prev from public.inquiries i
     where i.created_at between now() - interval '60 days' and now() - interval '30 days';
  exception when others then v_match_now := null; v_match_prev := null; end;

  -- THE SUPPLY SIDE OF MATCHING ACCURACY (13 Aug 2026).
  --
  -- The line above reports the share of RFQs that reached a supplier. It cannot report the reason a
  -- share is low, and right now the reason is one number: fn_match_capability's candidate CTE opens
  -- with `where sc.confirmed_at is not null`, and of 15,306 suppliers holding capability data
  -- exactly ONE has confirmed. So the marketplace can shortlist at most one supplier for any
  -- request, whatever the customer asks for.
  --
  -- It is on System Health as "Suppliers an RFQ can reach". The daily e-mail is a separate surface
  -- and never carried it, so the founder could read "0% of RFQs matched" every morning and not be
  -- told that no volume of RFQs could change it. A count without its reason sends you to the wrong
  -- budget: "no supplier matches that" reads as buy more suppliers; "15,306 hold it and one has
  -- confirmed" reads as chase confirmations.
  begin
    select count(*) filter (where sc.confirmed_at is not null), count(*)
      into v_scope_confirmed, v_scope_total
      from public.supplier_capabilities sc;
  exception when others then v_scope_confirmed := null; v_scope_total := null; end;

  -- AI COST: what the company spent on model calls, 30 days against the 30 before.
  begin
    select round(coalesce(sum(cost_aed),0),2) into v_ai_cost from public.ai_cost_log
      where occurred_at > now() - interval '30 days';
    select round(coalesce(sum(cost_aed),0),2) into v_ai_cost_prev from public.ai_cost_log
      where occurred_at between now() - interval '60 days' and now() - interval '30 days';
    v_ai_delta := v_ai_cost - v_ai_cost_prev;
  exception when others then v_ai_cost := 0; v_ai_cost_prev := 0; v_ai_delta := 0; end;

  -- THE EMERGING OPPORTUNITY the company detected on its own.
  begin select o.title into v_opp from public.opportunity o where o.status = 'open'
     order by o.value_score desc nulls last, o.created_at desc limit 1;
  exception when others then v_opp := null; end;

  -- GOAL ATTAINMENT against the monthly targets the goal ledger keeps.
  -- least(100.0, NULL) is 100.0 in PostgreSQL, so the previous inline version scored every
  -- UNMEASURED goal as a perfect 100 and averaged them with the two that were real. It also read
  -- last month's rows and ignored direction. fn_goal_attainment does all three correctly and
  -- returns the denominator, which is what stops a percentage being quoted without its base.
  begin
    v_goal_j := public.fn_goal_attainment('monthly');
    v_goal := (v_goal_j->>'pct')::numeric;
  exception when others then v_goal := null; v_goal_j := null; end;

  v_body :=
    'Good morning. Here is your QuotesDone snapshot.'||E'\n\n'||
    'HANDLED FOR YOU (last 24h): auto-cleared '||v_auto_cleared||' routine item(s)'||
      case when v_auto_appr>0 then ', auto-approved '||v_auto_appr||' licence-clean supplier(s)' else '' end||'.'||
      case when v_handled is not null then E'\n'||v_handled else '' end||E'\n\n'||
    'MARKETPLACE HEALTH: '||coalesce(v_health->>'index','—')||'/100 ('||coalesce(v_health->>'band','no data')||')'||
      case when coalesce(v_health->>'note','')<>'' then '  — '||(v_health->>'note') else '' end||E'\n\n'||
    'OBJECTIVES (what the organization is driving for you)'||E'\n'||
    '- Active objectives: '||v_obj_open||'  ·  tasks completed (24h): '||v_task_done24||'  ·  objectives closed (24h): '||v_obj_done24||E'\n'||
      case when v_obj_line is not null and v_obj_line<>'' then v_obj_line||E'\n' else '' end||E'\n'||
    'NEEDS YOU TODAY'||E'\n'||
    '- Waiting on YOU: '||v_fq_n||' item(s) no agent may settle'||
      case when v_fq_age is not null then ' (oldest '||v_fq_age||'d)' else '' end||
      ' plus '||v_kyc||' supplier KYC — these are yours'||E'\n'||
    '- The machine is working on: '||v_auto_q||' item(s) it will settle itself within the hour'||E'\n'||
    case when v_stalled > 0 then
      '- NOT MOVING: '||v_stalled||' item(s) sit in needs_review / proposed / open. The worker only '||
      'selects status=pending, so nothing is draining these. They are not yours to decide and they '||
      'are not being done either.'||E'\n'
    else '' end||
    '- Refund requests: '||v_refunds||E'\n'||
    '- Awaiting your approval: '||v_fa_pending||' refund decision(s) — the only routine approval that reaches you'||E'\n'||
    '- Inbound emails to review: '||v_reviews||E'\n'||
    '- Hot leads (quotes in, not revealed): '||v_hot||E'\n'||
    '- Supply gaps (demand, no supplier matched): '||v_gap||E'\n'||
    '- Chat: '||v_chat_open||' open, '||v_viol||' policy flag(s) this week'||E'\n\n'||
    'THIS WEEK'||E'\n'||
    '- New inquiries: '||v_inq7||'  ·  quotes: '||v_q7||E'\n'||
    '- Avg quotes/RFQ (30d): '||coalesce(v_qpr::text,'—')||'  ·  Conversion (30d): '||coalesce(v_conv::text,'—')||'%'||E'\n'||
    '- New customers: '||v_newcust||'  ·  new supplier registrations: '||v_newsup||E'\n'||
    '- Deals (reveals) all-time: '||v_deals||'  ·  revenue recognized: AED '||round(v_rev)||E'\n'||
    '- Top categories (7d): '||coalesce(v_topcats,'—')||E'\n\n'||
    'GROWTH'||E'\n'||
    '- Suppliers registered: '||v_reg||'  ·  BD invites queued: '||v_bd_q||'  ·  sent: '||v_bd_sent||E'\n'||
    case when v_officer is not null and v_officer <> '' then E'\n'||'OFFICER PRIORITIES (from weekly analysis)'||E'\n'||v_officer||E'\n' else '' end ||
    E'\n'||'DECISIONS NEEDED'||E'\n'||v_decisions||
    E'\n'||'QUALITY, COST AND OPPORTUNITY'||E'\n'||
    '- Fraud rejected: '||v_fraud||' supplier registration(s) refused or banned'||E'\n'||
    '- Matching accuracy: '||coalesce(v_match_now::text,'0')||'% of RFQs matched to a supplier (30d), previous 30d '||coalesce(v_match_prev::text,'0')||'%'||E'\n'||
    '- Suppliers an RFQ can reach: '||coalesce(v_scope_confirmed::text,'?')||' of '||coalesce(v_scope_total::text,'?')||' holding capability data have confirmed their own scope'||
      case when coalesce(v_scope_confirmed,0) < 2
           then ' — fn_match_capability gates on that confirmation, so a shortlist cannot exceed '||coalesce(v_scope_confirmed::text,'0')||' whatever a customer asks for'
           else '' end||E'\n'||
    '- AI cost: AED '||coalesce(v_ai_cost::text,'0')||' over 30d, previous 30d AED '||coalesce(v_ai_cost_prev::text,'0')||' ('||case when v_ai_delta >= 0 then '+' else '' end||coalesce(v_ai_delta::text,'0')||')'||E'\n'||
    '- Monthly goal attainment: '||coalesce(v_goal::text,'not measurable')||
      case when v_goal is not null then '% across '||coalesce(v_goal_j->>'goals_measured','?')||' of '||
             coalesce(v_goal_j->>'goals_total','?')||' goals that carry a measured actual for '||
             coalesce(v_goal_j->>'period','this period')||
             ' (the rest have no measure and are NOT counted as met)'
           else ' — no goal has a measured actual for this period' end||E'\n'||
    '- Emerging opportunity: '||coalesce(v_opp,'none detected')||E'\n'||
    E'\n'||'Open your dashboard: https://quotesdone.com/os  (Ops for live status; Governance for officer reports).';

  insert into notifications(type,to_email,to_role,channel,subject,body) values ('founder_brief',v_owner,'admin','email',v_subj,v_body);
  -- AND into founder_alerts, because that is where the console reads alerts from. Before this the
  -- newest row matching /brief/ was an unrelated error alert whose text contained the word.
  insert into public.founder_alerts(level, event, detail, channel)
    values ('info', 'Overnight founder brief', v_body, 'os');

  -- ONLY WHAT WAS ACTUALLY REPORTED. This closed EVERY digest row regardless of age, so anything
  -- older than the brief's own reporting window was marked handled without the founder ever seeing
  -- it. The window here and the window above are the same window on purpose.
  update notifications set status='digested'
   where status='digest' and created_at >= now()-interval '7 days' and created_at <= now();

  update agent_runs set finished_at=now(), status='ok', counts=jsonb_build_object('approvals',v_pend,'hot',v_hot,'gaps',v_gap,'bd_queued',v_bd_q,'kyc',v_kyc,'health',(v_health->>'index'),'decisions',v_dn,'auto_cleared_24h',v_auto_cleared,'objectives_open',v_obj_open) where id=v_run;
end;$function$


CREATE OR REPLACE FUNCTION public.fn_founder_command_clarify(p_command_id bigint, p_answer text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  cmd public.founder_command%rowtype;
  msg public.founder_command_message%rowtype;
  c record; v_combined text; v_qn text; v_owner text; v_child text;
  v_tasks bigint[] := '{}'; v_owners text[] := '{}'; v_task bigint;
  v_due timestamptz; v_wf text; v_start_event text; v_plan bigint; v_clar bigint;
  v_kernel jsonb; v_items int := 0; v_manager text; v_dept text;
  v_founder text;
begin
  v_founder := public.fn_phase_c_require_founder(p_actor);   -- raises 28000 for anyone else

  if coalesce(btrim(p_answer),'') = '' then
    return jsonb_build_object('ok', false, 'error','answer_required',
      'message','Say what you want and I will route it. An empty reply cannot resolve a clarification.');
  end if;
  select * into cmd from public.founder_command where command_id = p_command_id;
  if not found then return jsonb_build_object('ok', false, 'error','not_found'); end if;
  if cmd.state <> 'clarification_required' then
    return jsonb_build_object('ok', false, 'error','not_awaiting_clarification',
      'state', cmd.state,
      'message','This command is not waiting for a clarification.');
  end if;
  select * into msg from public.founder_command_message where message_id = cmd.message_id;

  -- The original instruction is never edited. The reply is APPENDED, on its own row, with its own
  -- timestamp, and the exact words the founder used.
  update public.founder_command_clarification
     set answer_text = p_answer, answered_at = now()
   where clarification_id = (select max(cl.clarification_id) from public.founder_command_clarification cl
                             where cl.command_id = p_command_id)
  returning clarification_id into v_clar;

  update public.founder_command set state = 'interpreting' where command_id = p_command_id;

  -- Re-interpret the instruction AND its clarification together, through the same deterministic
  -- classifier the first attempt used. No model is consulted; nothing is guessed.
  v_combined := coalesce(msg.raw_text,'') || E'\n' || p_answer;
  select * into c from public.fn_founder_command_classify(v_combined);

  insert into public.founder_command_interpretation
    (command_id, version, intent_id, confidence, matched_rule_id, workflow_ids,
     specificity_signals, reason)
  values (p_command_id,
          1 + coalesce((select max(i.version) from public.founder_command_interpretation i
                         where i.command_id = p_command_id), 0),
          c.intent_id, c.confidence, c.matched_rule_id, c.workflow_ids, c.specificity,
          'after clarification: ' || c.reason);

  -- Still not routable. Ask once more; still create nothing.
  if c.outcome not in ('ROUTE_AND_CREATE_TASKS','FOUNDER_INITIATED_POLICY_CHANGE',
                       'FOUNDER_INITIATED_PHASE_A_CHANGE','REFUND_APPROVAL') then
    v_qn := coalesce(nullif(c.reason,''), 'I still cannot route this safely.')
            || ' What exactly do you want changed, by how much, and by when?';
    insert into public.founder_command_clarification (command_id, question)
    values (p_command_id, v_qn);
    update public.founder_command set state = 'clarification_required' where command_id = p_command_id;
    return jsonb_build_object('ok', true, 'command_id', p_command_id,
      'status','clarification_required', 'tasks_created', 0, 'task_ids','[]'::jsonb,
      'owner','chief_of_staff', 'clarification', v_qn,
      'answer_recorded', true, 'clarification_id', v_clar, 'actor', v_founder);
  end if;

  -- Routable now. One command id, the plan and the tasks, in this transaction.
  update public.founder_command
     set intent_id = c.intent_id, outcome = c.outcome, priority = c.priority,
         primary_role_id = coalesce(nullif(c.primary_role_id,''), 'chief_of_staff'),
         state = 'accepted'
   where command_id = p_command_id;
  update public.founder_command set state = 'routed' where command_id = p_command_id;

  v_due := now() + case c.priority when 'P0' then interval '4 hours' when 'P1' then interval '2 days'
                                   when 'P2' then interval '5 days' else interval '10 days' end;
  v_wf := btrim(split_part(c.workflow_ids, ';', 1));

  insert into public.founder_command_workflow_link (command_id, workflow_id)
  select p_command_id, btrim(x) from unnest(string_to_array(c.workflow_ids, ';')) x
   where btrim(x) <> '' on conflict do nothing;

  select role_id into v_owner from public.fn_phase_c_resolve_actor(
    coalesce(nullif(c.primary_role_id,''), 'chief_of_staff'));
  -- ---- THE PLAN (not operational tasks) --------------------------------------------------
  -- K2 moved this for fn_founder_command_submit and left the clarify path behind, so answering a
  -- clarification still created four phase_c_task rows and no workflow run at all. Measured on
  -- command 270 through the real authenticated path on 17 Aug: tasks 4, runs 0, outbox 0.
  -- Plan items record who the command plan names. They are not work anybody is accountable for.
  if v_owner is not null then
    select r.manager_role_id, r.primary_department_id into v_manager, v_dept
      from public.org_role r where r.role_id = v_owner;
    insert into public.founder_command_plan_item
      (command_id, item_kind, role_id, department_id, summary, priority, workflow_id)
    values (p_command_id, 'primary', v_owner, coalesce(v_dept,''),
            left(v_combined, 1500), c.priority, nullif(v_wf,''))
    on conflict (command_id, item_kind, role_id) do nothing;
    v_items := v_items + 1; v_owners := v_owners || v_owner;
  end if;

  for v_child in select btrim(x) from unnest(string_to_array(c.child_role_ids, ';')) x where btrim(x) <> '' loop
    select role_id into v_owner from public.fn_phase_c_resolve_actor(v_child);
    continue when v_owner is null;
    select r.manager_role_id, r.primary_department_id into v_manager, v_dept
      from public.org_role r where r.role_id = v_owner;
    insert into public.founder_command_plan_item
      (command_id, item_kind, role_id, department_id, summary, priority, workflow_id)
    values (p_command_id, 'contribution', v_owner, coalesce(v_dept,''),
            'Contribution required by the command plan for ' || v_child || ': ' || left(v_combined, 1500),
            c.priority, nullif(v_wf,''))
    on conflict (command_id, item_kind, role_id) do nothing;
    v_items := v_items + 1; v_owners := v_owners || v_owner;
  end loop;

  -- ---- THE WORK --------------------------------------------------------------------------------
  -- One call, one run, one operational task, one factual event — the same kernel entry point the
  -- submit path uses, so the two can no longer drift apart.
  if coalesce(v_wf,'') <> '' and exists (select 1 from public.phase_b_workflow where workflow_id = v_wf) then
    v_kernel := public.fn_kernel_workflow_start(jsonb_build_object(
      'workflow_id', v_wf,
      'business_object_id', 'founder_command:' || p_command_id,
      'source_kind','founder_command',
      'source_ref','founder_command:' || p_command_id,
      'command_id', p_command_id,
      'correlation_id','cmd:' || p_command_id,
      'causation_id','command:' || p_command_id,
      'requested_by', v_founder,
      'priority', c.priority,
      'trigger_ctx', jsonb_build_object(
        'intent', c.intent_id, 'outcome', c.outcome, 'confidence', c.confidence,
        'matched_rule_id', c.matched_rule_id, 'after_clarification', true,
        'clarification_id', v_clar, 'plan_items', v_items)));
    v_task := (v_kernel->>'task_id')::bigint;
    v_start_event := v_kernel->>'event_id';
    if v_task is null then
      raise exception 'command %: the kernel returned no operational task for workflow %',
        p_command_id, v_wf using errcode = '23502';
    end if;
    insert into public.founder_command_task_link (command_id, task_id)
    values (p_command_id, v_task) on conflict do nothing;
    v_tasks := array[v_task];
    update public.phase_c_task set due_at = coalesce(due_at, v_due) where task_id = v_task;
  end if;

  insert into public.founder_command_plan (command_id, summary, child_task_count, departments)
  values (p_command_id,
          format('%s: %s after clarification. Command owner chief_of_staff; %s plan item(s), %s operational task against %s.',
                 c.intent_id, c.outcome, v_items, cardinality(v_tasks),
                 coalesce(nullif(c.workflow_ids,''),'no workflow')),
          v_items,
          coalesce((select string_agg(distinct t.department_id, '; ') from public.phase_c_task t
                     where t.command_id = p_command_id and t.department_id <> ''), ''))
  returning plan_id into v_plan;

  update public.founder_command set state = 'tasks_created', due_at = v_due
   where command_id = p_command_id;

  return jsonb_build_object('ok', true, 'command_id', p_command_id, 'status','tasks_created',
    'intent', c.intent_id, 'outcome', c.outcome, 'owner','chief_of_staff',
    'primary_owner', coalesce(v_owners[1],'founder'), 'task_ids', to_jsonb(v_tasks),
    'tasks_created', cardinality(v_tasks), 'workflow_id', v_wf,
    'event_emitted', v_start_event, 'plan_id', v_plan, 'clarification_id', v_clar,
    'answer_recorded', true, 'trace_id', cmd.trace_id, 'actor', v_founder,
    'interpretation','after clarification: ' || c.reason);
end $function$


CREATE OR REPLACE FUNCTION public.fn_founder_command_classify(p_text text)
 RETURNS TABLE(intent_id text, outcome text, workflow_ids text, primary_role_id text, child_role_ids text, priority text, confidence numeric, matched_rule_id text, specificity text, reason text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.phase_c_command_rule%rowtype; v_txt text := coalesce(p_text, '');
begin
  specificity := public.fn_phase_c_command_specificity(v_txt);
  for r in select * from public.phase_c_command_rule order by rule_order loop
    if v_txt ~* r.pattern and (r.antipattern = '' or not (v_txt ~* r.antipattern)) then
      if r.requires_specificity and specificity = '' then
        intent_id := 'AMBIGUOUS'; outcome := 'CLARIFICATION_REQUIRED';
        workflow_ids := ''; primary_role_id := 'chief_of_staff'; child_role_ids := '';
        priority := 'P2'; confidence := 0.35; matched_rule_id := r.rule_id;
        reason := format('matched %s but the instruction names no quantity, deadline, identifier or deliverable', r.rule_id);
        return next; return;
      end if;
      intent_id := r.intent_id; outcome := r.outcome; workflow_ids := r.workflow_ids;
      primary_role_id := r.primary_role_id; child_role_ids := r.child_role_ids;
      priority := r.priority; confidence := 0.95; matched_rule_id := r.rule_id;
      reason := format('deterministic registry rule %s (%s)', r.rule_id, r.notes);
      return next; return;
    end if;
  end loop;
  intent_id := 'AMBIGUOUS'; outcome := 'CLARIFICATION_REQUIRED'; workflow_ids := '';
  primary_role_id := 'chief_of_staff'; child_role_ids := ''; priority := 'P2';
  confidence := 0.0; matched_rule_id := '';
  reason := 'no registered command intent matches this instruction';
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_founder_command_control(p_command_id bigint, p_op text, p_target text, p_value text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_target bigint; v_state text; v_n bigint := 0; t record; v_trace bigint; v_founder text;
        v_out jsonb;
begin
  v_founder := public.fn_phase_c_require_founder(p_actor);   -- raises 28000 for anyone else

  v_target := nullif(regexp_replace(coalesce(p_target,''), '\D', '', 'g'), '')::bigint;
  if v_target is null then
    return jsonb_build_object('ok', false, 'error','identifier_required');
  end if;
  select state into v_state from public.founder_command where command_id = v_target;
  if v_state is null then return jsonb_build_object('ok', false, 'error','not_found'); end if;

  if p_op in ('cancel','supersede') then
    -- ROOT CAUSE 2. THIS BRANCH USED TO BE A SECOND CANCELLER. It set founder_command.state itself
    -- and closed the child tasks one by one, and it stopped there: the workflow run, its open step
    -- runs, its handoffs, its queued outbox rows and its open traces were left live beneath a
    -- command the founder had cancelled. The final Phase C acceptance cancelled command 338 through
    -- this exact path and left run 538 and step run 531 active.
    --
    -- It now delegates. fn_kernel_cancel is the canonical canceller and the only one: it walks the
    -- command, its plan, its runs, their step runs, tasks, handoffs, undelivered outbox rows and
    -- open traces, refuses a transition the state model does not declare, and counts what it left
    -- behind before returning. The founder identity is verified twice on purpose — once above, and
    -- again inside the kernel for the founder_command subject — because the kernel may not trust a
    -- caller's word about who is asking.
    v_out := public.fn_kernel_cancel(jsonb_build_object(
      'subject_kind', 'founder_command',
      'subject_ref',  v_target::text,
      'op',           p_op,
      'actor',        p_actor,
      'reason',       coalesce(nullif(btrim(p_value),''),
                               'founder ' || p_op || ' of command ' || v_target
                               || ' through the Command Center control')));

    -- IDEMPOTENT. A command already in its terminal state is not an error and must not become one:
    -- the second click of Cancel returns the same answer as the first and changes nothing.
    if coalesce((v_out->>'ok')::boolean, false) is not true
       and v_state in ('cancelled','superseded') then
      return jsonb_build_object('ok', true, 'command_id', v_target, 'status', v_state,
        'already_terminal', true, 'child_tasks_closed', 0, 'actor', v_founder,
        'kernel', v_out);
    end if;
    if coalesce((v_out->>'ok')::boolean, false) is not true then
      return jsonb_build_object('ok', false, 'command_id', v_target,
        'error', coalesce(v_out->>'error', 'cancellation_refused'), 'kernel', v_out);
    end if;

    return jsonb_build_object('ok', true, 'command_id', v_target,
      'status', case when p_op = 'cancel' then 'cancelled' else 'superseded' end,
      'superseded_by', case when p_op = 'supersede' then p_command_id else null end,
      'child_tasks_closed', coalesce((v_out->'closed'->>'tasks')::int, 0),
      'closed', v_out->'closed', 'actor', v_founder);

  elsif p_op = 'reprioritize' then
    if coalesce(p_value,'') !~ '^P[0-3]$' then
      return jsonb_build_object('ok', false, 'error','priority_required', 'allowed','P0..P3');
    end if;
    update public.founder_command set priority = p_value where command_id = v_target;
    update public.phase_c_task set priority = p_value where command_id = v_target and closed_at is null;
    get diagnostics v_n = row_count;
    return jsonb_build_object('ok', true, 'command_id', v_target, 'priority', p_value,
      'tasks_updated', v_n, 'actor', v_founder);

  elsif p_op = 'explain' then
    return jsonb_build_object('ok', true, 'command_id', v_target,
      'explanation', coalesce((select i.reason from public.founder_command_interpretation i
                               where i.command_id = v_target order by i.version desc limit 1),
                              'no interpretation recorded'),
      'traces', coalesce((select jsonb_agg(jsonb_build_object(
                              'trace_id', tr.trace_id, 'policy', tr.trace_policy_id,
                              'subject', tr.subject_kind, 'state_after', tr.state_after,
                              'status', tr.status) order by tr.trace_id)
                          from public.phase_c_trace tr where tr.command_id = v_target), '[]'::jsonb),
      'plan', (select p.summary from public.founder_command_plan p where p.command_id = v_target),
      'actor', v_founder);
  end if;
  return jsonb_build_object('ok', false, 'error','unknown_control_operation', 'op', p_op);
end $function$


CREATE OR REPLACE FUNCTION public.fn_founder_command_duplicate_result(p_command_id bigint, p_key text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'ok', true,
    'command_id', c.command_id,
    'status', c.state,
    'intent', c.intent_id,
    'outcome', c.outcome,
    'interpretation', coalesce(
      (select i.reason from public.founder_command_interpretation i
        where i.command_id = c.command_id order by i.version desc limit 1), ''),
    'control_command', c.intent_id in ('CMD-STATUS','CMD-CANCEL','CMD-REPRIORITIZE','CMD-EXPLAIN'),
    'workflow_ids', coalesce((select jsonb_agg(l.workflow_id order by l.workflow_id)
                              from public.founder_command_workflow_link l
                              where l.command_id = c.command_id), '[]'::jsonb),
    'task_ids', coalesce((select jsonb_agg(t.task_id order by t.task_id)
                          from public.phase_c_task t where t.command_id = c.command_id), '[]'::jsonb),
    'tasks_created', (select count(*) from public.phase_c_task t where t.command_id = c.command_id),
    'owner', c.command_owner_role_id,
    'primary_owner', coalesce((select t.accountable_role_id from public.phase_c_task t
                               where t.command_id = c.command_id order by t.task_id limit 1), ''),
    'child_owners', coalesce((select jsonb_agg(x.accountable_role_id order by x.task_id)
                              from (select t.task_id, t.accountable_role_id from public.phase_c_task t
                                    where t.command_id = c.command_id order by t.task_id offset 1) x), '[]'::jsonb),
    'category_overlays_invoked', coalesce((select jsonb_agg(o.overlay_id order by o.overlay_id)
                                           from public.founder_command_overlay_invocation o
                                           where o.command_id = c.command_id), '[]'::jsonb),
    'priority', c.priority,
    'due_at', c.due_at,
    'founder_approval_required', c.refund_semantics,
    'founder_initiated_only', c.founder_initiated_only,
    'clarification', (select cl.question from public.founder_command_clarification cl
                      where cl.command_id = c.command_id order by cl.clarification_id desc limit 1),
    'trace_id', c.trace_id,
    -- the two fields that make it honest rather than merely well-shaped
    'duplicate', true,
    'duplicate_of_idempotency_key', p_key)
  from public.founder_command c
  where c.command_id = p_command_id;
$function$


CREATE OR REPLACE FUNCTION public.fn_founder_command_inbox(p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'as_of', now(),
    'commands', coalesce((
      select jsonb_agg(x order by x->>'command_id' desc) from (
        select jsonb_build_object(
          'command_id', c.command_id, 'state', c.state, 'intent', c.intent_id,
          'outcome', c.outcome, 'priority', c.priority, 'due_at', c.due_at,
          'said', left(m.raw_text, 240), 'at', c.created_at,
          'owner', c.command_owner_role_id,
          'plan', (select p.summary from public.founder_command_plan p where p.command_id = c.command_id),
          'clarification', (select cl.question from public.founder_command_clarification cl
                            where cl.command_id = c.command_id and cl.answered_at is null
                            order by cl.clarification_id desc limit 1),
          'tasks_open', (select count(*) from public.phase_c_task t
                         where t.command_id = c.command_id and t.closed_at is null),
          'tasks_blocked', (select count(*) from public.phase_c_task t
                            where t.command_id = c.command_id and t.state = 'blocked'),
          'owners', (select coalesce(jsonb_agg(distinct t.accountable_role_id), '[]'::jsonb)
                     from public.phase_c_task t where t.command_id = c.command_id),
          'overlays_invoked', (select coalesce(jsonb_agg(o.overlay_id), '[]'::jsonb)
                               from public.founder_command_overlay_invocation o where o.command_id = c.command_id)
        ) x
        from public.founder_command c
        join public.founder_command_message m on m.message_id = c.message_id
        order by c.command_id desc
        limit greatest(1, coalesce(p_limit, 25))
      ) s), '[]'::jsonb),
    -- The ONE thing that is his to decide.  Nothing else in the company reaches this list.
    'awaiting_your_decision', coalesce((
      select jsonb_agg(jsonb_build_object(
        'request_id', a.request_id, 'transaction', a.subject_ref, 'prepared_by', a.prepared_by_role_id,
        'note', a.amount_note, 'since', a.created_at, 'command_id', a.command_id))
      from public.founder_approval_request a where a.state = 'pending'), '[]'::jsonb),
    'blocked_tasks', coalesce((
      select jsonb_agg(jsonb_build_object(
        'task_id', t.task_id, 'owner', t.accountable_role_id, 'manager', t.manager_role_id,
        'blocker', t.blocker, 'resolution_owner', t.blocker_owner_role_id, 'since', t.updated_at))
      from public.phase_c_task t where t.state = 'blocked'), '[]'::jsonb),
    'overdue_handoffs', coalesce((
      select jsonb_agg(jsonb_build_object(
        'handoff_run_id', h.handoff_run_id, 'handoff', h.handoff_id, 'sender', h.sender,
        'receiver', h.receiver, 'hours_late', h.hours_late))
      from public.fn_phase_c_handoff_overdue() h), '[]'::jsonb),
    'counts', jsonb_build_object(
      'commands', (select count(*) from public.founder_command),
      'open_commands', (select count(*) from public.founder_command where closed_at is null),
      'open_tasks', (select count(*) from public.phase_c_task where closed_at is null),
      'awaiting_founder', (select count(*) from public.founder_approval_request where state = 'pending'),
      'non_refund_awaiting_founder', public.fn_phase_c_non_refund_founder_approvals())
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_founder_command_message_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception 'founder_command_message %: the founder''s own words are append-only', old.message_id
    using errcode = '23514';
end $function$


CREATE OR REPLACE FUNCTION public.fn_founder_command_progress_add(p_command_id bigint, p_task_id bigint, p_author text, p_note text, p_evidence jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_author text; v_id bigint; v_trace bigint;
begin
  if coalesce(btrim(p_note), '') = '' then
    return jsonb_build_object('ok', false, 'error','note_required');
  end if;
  select role_id into v_author from public.fn_phase_c_resolve_actor(p_author);
  if v_author is null or not public.fn_phase_c_actor_may_own(v_author) then
    return jsonb_build_object('ok', false, 'error','author_not_canonical', 'author', p_author);
  end if;
  if not exists (select 1 from public.founder_command where command_id = p_command_id) then
    return jsonb_build_object('ok', false, 'error','unknown_command', 'command_id', p_command_id);
  end if;
  -- a note against a task must come from that task's own owner or its manager
  if p_task_id is not null and not exists (
       select 1 from public.phase_c_task t
       where t.task_id = p_task_id and t.command_id = p_command_id
         and (t.accountable_role_id = v_author or t.manager_role_id = v_author)) then
    return jsonb_build_object('ok', false, 'error','not_the_task_owner_or_manager',
      'author', v_author, 'task_id', p_task_id);
  end if;

  v_trace := public.fn_phase_c_trace_write('TRACE-ROLE-ACTION', jsonb_build_object(
    'subject_kind','progress_note', 'subject_ref', p_command_id::text,
    'command_id', p_command_id, 'task_id', p_task_id, 'actor_role_id', v_author,
    'output_hash', encode(sha256(convert_to(p_note, 'UTF8')), 'hex'), 'status','sealed'));

  insert into public.founder_command_progress_note
    (command_id, task_id, author_role_id, note, evidence, trace_id)
  values (p_command_id, p_task_id, v_author, p_note, coalesce(p_evidence, '{}'::jsonb), v_trace)
  returning note_id into v_id;
  if v_id is null then
    raise exception 'fn_founder_command_progress_add wrote no row' using errcode = '23502';
  end if;
  return jsonb_build_object('ok', true, 'note_id', v_id, 'author', v_author, 'trace_id', v_trace);
end $function$


CREATE OR REPLACE FUNCTION public.fn_founder_command_rollup(p_command_id bigint)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c public.founder_command%rowtype;
  n_total bigint; n_open bigint; n_blocked bigint; n_started bigint; n_failed bigint; n_done bigint;
  v_want text; v_summary text;
begin
  select * into c from public.founder_command where command_id = p_command_id for update;
  if not found then return null; end if;
  -- a terminal command is not re-opened by a late task movement
  if c.state in ('completed','cancelled','refused','superseded','failed') then return null; end if;

  select count(*),
         count(*) filter (where closed_at is null),
         count(*) filter (where state = 'blocked'),
         count(*) filter (where state in ('in_progress','accepted','review_required','revision_required')),
         count(*) filter (where state = 'failed'),
         count(*) filter (where state = 'completed')
    into n_total, n_open, n_blocked, n_started, n_failed, n_done
  from public.phase_c_task where command_id = p_command_id;

  if n_total = 0 then return null; end if;

  v_want := case
    when n_open = 0 and n_failed > 0 then 'failed'
    when n_open = 0                  then 'completed'
    when n_blocked > 0               then 'partially_blocked'
    when n_started > 0               then 'in_progress'
    else c.state
  end;
  if v_want = c.state then return null; end if;

  -- The frozen command state model still decides. A move it does not allow is not forced; the
  -- command stays where it is and the task movement is unaffected.
  if not exists (select 1 from public.phase_c_command_transition
                 where from_state = c.state and to_state = v_want) then
    return null;
  end if;

  update public.founder_command set
    state = v_want,
    closed_at = case when v_want in ('completed','failed') then now() else closed_at end
  where command_id = p_command_id;

  if v_want in ('completed','failed') then
    v_summary := format(
      '%s of %s task(s) completed, %s failed. Owners: %s.',
      n_done, n_total, n_failed,
      coalesce((select string_agg(distinct accountable_role_id, ', ' order by accountable_role_id)
                from public.phase_c_task where command_id = p_command_id), 'none'));
    insert into public.founder_command_completion (command_id, summary, evidence)
    values (p_command_id, v_summary, jsonb_build_object(
      'tasks_total', n_total, 'tasks_completed', n_done, 'tasks_failed', n_failed,
      'task_ids', coalesce((select jsonb_agg(task_id order by task_id)
                            from public.phase_c_task where command_id = p_command_id), '[]'::jsonb),
      'traces', coalesce((select jsonb_agg(trace_id) from public.phase_c_task
                          where command_id = p_command_id and trace_id is not null), '[]'::jsonb)))
    on conflict (command_id) do update set summary = excluded.summary,
      evidence = excluded.evidence, closed_at = now();

    perform public.fn_phase_c_trace_write('TRACE-FOUNDER-COMMAND', jsonb_build_object(
      'subject_kind','command', 'subject_ref', p_command_id::text, 'command_id', p_command_id,
      'actor_role_id','chief_of_staff', 'system_actor_id','system.task_engine',
      'state_before', c.state, 'state_after', v_want, 'status','sealed',
      'evidence_refs', jsonb_build_array(jsonb_build_object('completion_summary', v_summary))));
  end if;

  return v_want;
end $function$


CREATE OR REPLACE FUNCTION public.fn_founder_command_state_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'UPDATE' and new.state is distinct from old.state then
    if not exists (select 1 from public.phase_c_command_transition
                   where from_state = old.state and to_state = new.state) then
      raise exception 'founder_command %: transition % -> % is not in the Phase C command state model',
        old.command_id, old.state, new.state using errcode = '23514';
    end if;
    insert into public.founder_command_status_history (command_id, from_state, to_state, reason)
    values (old.command_id, old.state, new.state, 'state guard');
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_founder_command_status(p_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id bigint; r jsonb;
begin
  v_id := nullif(regexp_replace(coalesce(p_ref,''), '\D', '', 'g'), '')::bigint;
  if v_id is null then
    return jsonb_build_object('ok', false, 'error','identifier_required',
      'message','Give me a command id or a task id and I will read its current state.');
  end if;
  select jsonb_build_object(
    'ok', true, 'command_id', c.command_id, 'status', c.state, 'intent', c.intent_id,
    'outcome', c.outcome, 'owner', c.command_owner_role_id, 'priority', c.priority,
    'due_at', c.due_at, 'raw_text', m.raw_text,
    'workflow_ids', coalesce((select jsonb_agg(l.workflow_id order by l.workflow_id)
                              from public.founder_command_workflow_link l where l.command_id = c.command_id), '[]'::jsonb),
    'tasks', coalesce((select jsonb_agg(jsonb_build_object(
                          'task_id', t.task_id, 'owner', t.accountable_role_id,
                          'department', t.department_id, 'state', t.state,
                          'blocker', t.blocker, 'due_at', t.due_at) order by t.task_id)
                       from public.phase_c_task t where t.command_id = c.command_id), '[]'::jsonb),
    'clarification', (select cl.question from public.founder_command_clarification cl
                      where cl.command_id = c.command_id order by cl.clarification_id desc limit 1),
    'trace_id', c.trace_id)
  into r
  from public.founder_command c join public.founder_command_message m on m.message_id = c.message_id
  where c.command_id = v_id;
  return coalesce(r, jsonb_build_object('ok', false, 'error','not_found', 'ref', p_ref));
end $function$


CREATE OR REPLACE FUNCTION public.fn_founder_command_submit(p_founder_identity text, p_text text, p_idempotency_key text, p_ctx jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_start_event text; v_wf_selected text;
  c record; v_msg bigint; v_cmd bigint; v_existing bigint; v_trace bigint; v_task bigint;
  v_tasks bigint[] := '{}'; v_owners text[] := '{}'; v_overlays text[] := '{}';
  v_wf text; v_child text; v_owner text; v_kind text; v_manager text; v_dept text;
  v_action text; v_due timestamptz; v_intent public.phase_c_command_intent%rowtype;
  v_plan_id bigint; v_qn text; v_ov jsonb;
  v_kernel jsonb; v_items int := 0; v_status text;
begin
  if coalesce(p_founder_identity, '') = '' then
    raise exception 'founder identity is required' using errcode = '28000';
  end if;
  if not exists (select 1 from public.phase_c_founder_identity
                 where identity = lower(btrim(p_founder_identity)) and active) then
    return jsonb_build_object('ok', false, 'error', 'not_the_founder',
      'message', 'The Command Center accepts commands from the registered founder identity only.');
  end if;

  select m.message_id into v_msg from public.founder_command_message m
   where m.client_idempotency_key = p_idempotency_key;
  if v_msg is not null then
    select fc.command_id into v_existing from public.founder_command fc where fc.message_id = v_msg;
    return public.fn_founder_command_duplicate_result(v_existing, p_idempotency_key);
  end if;

  insert into public.founder_command_message
    (session_id, founder_identity, raw_text, raw_text_hash, client_idempotency_key, channel)
  values ((p_ctx->>'session_id')::bigint, lower(btrim(p_founder_identity)), p_text,
          encode(sha256(convert_to(coalesce(p_text,''), 'UTF8')), 'hex'), p_idempotency_key,
          coalesce(p_ctx->>'channel', 'command_center'))
  returning message_id into v_msg;

  select * into c from public.fn_founder_command_classify(p_text);

  insert into public.founder_command
    (message_id, intent_id, outcome, state, priority, primary_role_id,
     founder_initiated_only, refund_semantics)
  values (v_msg, c.intent_id, c.outcome, 'received', c.priority,
          coalesce(nullif(c.primary_role_id,''), 'chief_of_staff'),
          c.outcome in ('FOUNDER_INITIATED_POLICY_CHANGE','FOUNDER_INITIATED_PHASE_A_CHANGE'),
          c.outcome = 'REFUND_APPROVAL')
  returning command_id into v_cmd;
  if v_cmd is null then
    raise exception 'fn_founder_command_submit wrote no command row' using errcode = '23502';
  end if;

  insert into public.founder_command_interpretation
    (command_id, version, intent_id, confidence, matched_rule_id, workflow_ids, specificity_signals, reason)
  values (v_cmd, 1, c.intent_id, c.confidence, c.matched_rule_id, c.workflow_ids, c.specificity, c.reason);

  update public.founder_command set state = 'interpreting' where command_id = v_cmd;

  v_trace := public.fn_phase_c_trace_write('TRACE-FOUNDER-COMMAND', jsonb_build_object(
    'subject_kind','command', 'subject_ref', v_cmd::text, 'command_id', v_cmd,
    'actor_role_id','founder', 'system_actor_id','system.command_router',
    'input_hash', encode(sha256(convert_to(coalesce(p_text,''), 'UTF8')), 'hex'),
    'state_before','received', 'state_after','interpreting', 'status','open'));
  update public.founder_command set trace_id = v_trace where command_id = v_cmd;

  if c.outcome = 'REFUSE_UNSCOPED_UNSAFE_COMMAND' then
    update public.founder_command set state = 'refused', closed_at = now() where command_id = v_cmd;
    return jsonb_build_object('ok', true, 'command_id', v_cmd, 'status','refused',
      'intent', c.intent_id, 'interpretation', c.reason, 'workflow_ids','[]'::jsonb,
      'task_ids','[]'::jsonb, 'owner','chief_of_staff', 'tasks_created', 0,
      'blocker', 'Unscoped destructive or financial instruction. Name the individual cases and the evidence, and it will route.',
      'trace_id', v_trace);
  end if;

  if c.intent_id = 'AMBIGUOUS' then
    v_qn := case when c.matched_rule_id <> ''
      then 'I can route this, but not safely yet. What exactly do you want changed, by how much, and by when?'
      else 'I have no registered intent for that. What outcome do you want, in which area, and by when?' end;
    insert into public.founder_command_clarification (command_id, question) values (v_cmd, v_qn);
    update public.founder_command set state = 'clarification_required' where command_id = v_cmd;
    return jsonb_build_object('ok', true, 'command_id', v_cmd, 'status','clarification_required',
      'intent','AMBIGUOUS', 'interpretation', c.reason, 'workflow_ids','[]'::jsonb,
      'task_ids','[]'::jsonb, 'owner','chief_of_staff', 'tasks_created', 0,
      'clarification', v_qn, 'trace_id', v_trace);
  end if;

  if c.intent_id in ('CMD-STATUS','CMD-CANCEL','CMD-REPRIORITIZE','CMD-EXPLAIN') then
    update public.founder_command set state = 'accepted' where command_id = v_cmd;
    return jsonb_build_object('ok', true, 'command_id', v_cmd, 'status','accepted',
      'intent', c.intent_id, 'interpretation', c.reason, 'control_command', true,
      'workflow_ids','[]'::jsonb, 'task_ids','[]'::jsonb, 'owner','chief_of_staff',
      'tasks_created', 0, 'trace_id', v_trace,
      'next', 'call fn_founder_command_control(command_id, op, target_ref, value)');
  end if;

  update public.founder_command set state = 'accepted' where command_id = v_cmd;
  select * into v_intent from public.phase_c_command_intent where intent_id = c.intent_id;

  v_due := now() + case c.priority when 'P0' then interval '4 hours'
                                   when 'P1' then interval '2 days'
                                   else interval '5 days' end;

  for v_wf in select btrim(x) from unnest(string_to_array(c.workflow_ids, ';')) x where btrim(x) <> '' loop
    if exists (select 1 from public.phase_b_workflow where workflow_id = v_wf) then
      insert into public.founder_command_workflow_link (command_id, workflow_id)
      values (v_cmd, v_wf) on conflict do nothing;
    end if;
  end loop;
  update public.founder_command set state = 'routed' where command_id = v_cmd;

  v_wf_selected := btrim(split_part(c.workflow_ids, ';', 1));

  -- ---- THE PLAN (was: four phase_c_task rows) ------------------------------------------------
  -- The primary interpretation.
  v_owner := coalesce(nullif(c.primary_role_id, ''), v_intent.default_accountable_role_id, 'chief_of_staff');
  if v_owner <> 'founder' then
    select role_id into v_owner from public.fn_phase_c_resolve_actor(v_owner);
    if v_owner is null then
      raise exception 'command %: primary owner does not resolve to an active canonical role', v_cmd
        using errcode = '23514';
    end if;
    select r.manager_role_id, r.primary_department_id into v_manager, v_dept
      from public.org_role r where r.role_id = v_owner;
    insert into public.founder_command_plan_item
      (command_id, item_kind, role_id, department_id, summary, priority, workflow_id)
    values (v_cmd, 'primary', v_owner, coalesce(v_dept,''),
            left(coalesce(p_text,''), 2000), c.priority, nullif(v_wf_selected,''))
    on conflict (command_id, item_kind, role_id) do nothing;
    v_items := v_items + 1;
    v_owners := v_owners || v_owner;
  end if;

  -- The contributions.
  for v_child in select btrim(x) from unnest(string_to_array(c.child_role_ids, ';')) x where btrim(x) <> '' loop
    select kind, role_id into v_kind, v_owner from public.fn_phase_c_resolve_actor(v_child);
    if v_kind = 'overlay' then
      v_ov := public.fn_phase_c_overlay_invoke(v_child, jsonb_build_object(
        'command_id', v_cmd, 'evidence_refs', jsonb_build_array('CMD-' || v_cmd)));
      insert into public.founder_command_overlay_invocation
        (command_id, overlay_id, live_role_id, returns_to_role_id, result, trace_id)
      values (v_cmd, coalesce(v_ov->>'overlay_id', v_child), v_owner,
              coalesce(v_ov->>'return_owner', coalesce(v_owners[1], 'chief_of_staff')),
              v_ov, (v_ov->>'trace_id')::bigint)
      on conflict (command_id, overlay_id) do nothing;
      v_overlays := v_overlays || coalesce(v_ov->>'overlay_id', v_child);
      continue;
    end if;
    continue when v_kind is distinct from 'canonical' or v_owner is null;
    select r.manager_role_id, r.primary_department_id into v_manager, v_dept
      from public.org_role r where r.role_id = v_owner;
    insert into public.founder_command_plan_item
      (command_id, item_kind, role_id, department_id, summary, priority, workflow_id)
    values (v_cmd, 'contribution', v_owner, coalesce(v_dept,''),
            'Contribution required by the command plan for ' || v_child || ': '
              || left(coalesce(p_text,''), 1500),
            c.priority, nullif(v_wf_selected,''))
    on conflict (command_id, item_kind, role_id) do nothing;
    v_items := v_items + 1;
    v_owners := v_owners || v_owner;
  end loop;

  -- ---- THE WORK (was: an event that a consumer turned into a fifth task) ---------------------
  -- One call, one run, one operational task, one factual event. The task carries command_id, so
  -- the founder's thread can see the work his instruction actually produced.
  if v_wf_selected <> '' and exists (select 1 from public.phase_b_workflow where workflow_id = v_wf_selected) then
    v_kernel := public.fn_kernel_workflow_start(jsonb_build_object(
      'workflow_id', v_wf_selected,
      'business_object_id', 'founder_command:' || v_cmd,
      'source_kind','founder_command',
      'source_ref','founder_command:' || v_cmd,
      'command_id', v_cmd,
      'correlation_id','cmd:' || v_cmd,
      'causation_id','command:' || v_cmd,
      'requested_by', lower(btrim(p_founder_identity)),
      'priority', c.priority,
      'trigger_ctx', jsonb_build_object(
        'intent', c.intent_id, 'outcome', c.outcome, 'confidence', c.confidence,
        'matched_rule_id', c.matched_rule_id,
        'raw_text_hash', encode(sha256(convert_to(coalesce(p_text,''), 'UTF8')), 'hex'),
        'plan_items', v_items)));
    v_task := (v_kernel->>'task_id')::bigint;
    v_start_event := v_kernel->>'event_id';
    if v_task is null then
      raise exception 'command %: the kernel returned no operational task for workflow %',
        v_cmd, v_wf_selected using errcode = '23502';
    end if;
    insert into public.founder_command_task_link (command_id, task_id)
    values (v_cmd, v_task) on conflict do nothing;
    v_tasks := array[v_task];
    -- The command's due date is the founder's, and it is applied to the task the kernel made.
    update public.phase_c_task set due_at = coalesce(due_at, v_due) where task_id = v_task;
  end if;

  insert into public.founder_command_plan (command_id, summary, child_task_count, departments)
  values (v_cmd,
          format('%s: %s. Command owner chief_of_staff; %s plan item(s) and %s operational task(s) against %s%s.',
                 c.intent_id, c.outcome, v_items, cardinality(v_tasks),
                 coalesce(nullif(c.workflow_ids,''), 'no workflow'),
                 case when cardinality(v_overlays) > 0
                      then format('; %s category overlay invocation(s): %s',
                                  cardinality(v_overlays), array_to_string(v_overlays, ', '))
                      else '' end),
          greatest(v_items - 1, 0),
          coalesce((select string_agg(distinct i.department_id, '; ')
                    from public.founder_command_plan_item i
                   where i.command_id = v_cmd and i.department_id <> ''), ''))
  on conflict (command_id) do update set summary = excluded.summary,
    child_task_count = excluded.child_task_count, departments = excluded.departments
  returning plan_id into v_plan_id;

  if c.outcome = 'REFUND_APPROVAL' then
    insert into public.founder_approval_request
      (command_id, action_class, subject_ref, prepared_by_role_id, amount_note, evidence, state)
    values (v_cmd, 'refund_decision',
            coalesce((regexp_match(p_text, '(TX-[A-Za-z0-9_-]+)'))[1], 'UNIDENTIFIED_TRANSACTION'),
            'payments_and_billing_manager',
            'amount, reason, customer/supplier impact and fraud checks required before decision',
            jsonb_build_object('raw_command', left(coalesce(p_text,''), 500)), 'pending');
  end if;

  -- A command that produced no operational task did not create tasks, and does not claim to.
  if cardinality(v_tasks) > 0 then
    update public.founder_command set state = 'tasks_created', due_at = v_due where command_id = v_cmd;
    v_status := 'tasks_created';
  else
    update public.founder_command set due_at = v_due where command_id = v_cmd;
    v_status := 'routed';
  end if;

  return jsonb_build_object(
    'ok', true, 'command_id', v_cmd, 'status', v_status, 'intent', c.intent_id,
    'outcome', c.outcome, 'interpretation', c.reason,
    'workflow_ids', coalesce((select jsonb_agg(workflow_id order by workflow_id)
                              from public.founder_command_workflow_link where command_id = v_cmd), '[]'::jsonb),
    'task_ids', to_jsonb(v_tasks),
    'owner', 'chief_of_staff', 'primary_owner', coalesce(v_owners[1], 'founder'),
    'child_owners', to_jsonb(v_owners[2:]),
    'category_overlays_invoked', to_jsonb(v_overlays),
    'tasks_created', cardinality(v_tasks),
    'plan_items', v_items,
    'workflow_run_id', (v_kernel->>'run_id')::bigint,
    'step_run_id', (v_kernel->>'step_run_id')::bigint,
    'handoff_run_id', (v_kernel->>'handoff_run_id')::bigint,
    'event_id', v_start_event, 'outbox_id', (v_kernel->>'outbox_id')::bigint,
    'correlation_id', 'cmd:' || v_cmd,
    'blocker', case when cardinality(v_tasks) = 0
                    then 'The interpretation selected no registered workflow, so no operational task was '
                      || 'created. The plan is recorded; name the area and it will route.'
                    else null end,
    'priority', c.priority, 'due_at', v_due,
    'founder_approval_required', (c.outcome = 'REFUND_APPROVAL'),
    'founder_initiated_only', (c.outcome in ('FOUNDER_INITIATED_POLICY_CHANGE','FOUNDER_INITIATED_PHASE_A_CHANGE')),
    'plan_id', v_plan_id, 'trace_id', v_trace);
end $function$


CREATE OR REPLACE FUNCTION public.fn_founder_command_thread(p_command_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'ok', c.command_id is not null,
    'command_id', c.command_id,
    'said', m.raw_text,
    'said_at', m.received_at,
    'said_by', m.founder_identity,
    'secretary', c.command_owner_role_id,
    'understood_as', (select i.reason from public.founder_command_interpretation i
                      where i.command_id = c.command_id order by i.version desc limit 1),
    'intent', c.intent_id,
    'outcome', c.outcome,
    'state', c.state,
    'priority', c.priority,
    'due_at', c.due_at,
    'workflows', coalesce((select jsonb_agg(w.workflow_id || ' — ' || b.workflow_name order by w.workflow_id)
                           from public.founder_command_workflow_link w
                           join public.phase_b_workflow b on b.workflow_id = w.workflow_id
                           where w.command_id = c.command_id), '[]'::jsonb),
    'plan', (select p.summary from public.founder_command_plan p where p.command_id = c.command_id),
    'tasks', coalesce((select jsonb_agg(jsonb_build_object(
                          'task_id', t.task_id,
                          'owner', t.accountable_role_id,
                          'owner_name', (select r.display_name from public.org_role r where r.role_id = t.accountable_role_id),
                          'manager', t.manager_role_id,
                          'department', t.department_id,
                          'state', t.state,
                          'objective', left(t.objective, 300),
                          'acceptance', t.acceptance_criteria,
                          'closure', t.closure_criteria,
                          'reviewer', nullif(t.reviewer_role_id, ''),
                          'blocker', nullif(t.blocker, ''),
                          'blocker_owner', nullif(t.blocker_owner_role_id, ''),
                          'due_at', t.due_at,
                          'trace_id', t.trace_id) order by t.task_id)
                       from public.phase_c_task t where t.command_id = c.command_id), '[]'::jsonb),
    'progress', coalesce((select jsonb_agg(jsonb_build_object(
                            'note_id', n.note_id, 'at', n.created_at, 'by', n.author_role_id,
                            'by_name', (select r.display_name from public.org_role r where r.role_id = n.author_role_id),
                            'task_id', n.task_id, 'note', n.note, 'evidence', n.evidence,
                            'trace_id', n.trace_id) order by n.note_id)
                          from public.founder_command_progress_note n
                          where n.command_id = c.command_id), '[]'::jsonb),
    'overlays_invoked', coalesce((select jsonb_agg(o.overlay_id order by o.overlay_id)
                                  from public.founder_command_overlay_invocation o
                                  where o.command_id = c.command_id), '[]'::jsonb),
    'clarification', (select cl.question from public.founder_command_clarification cl
                      where cl.command_id = c.command_id order by cl.clarification_id desc limit 1),
    'completion', (select jsonb_build_object('summary', k.summary, 'evidence', k.evidence, 'at', k.closed_at)
                   from public.founder_command_completion k where k.command_id = c.command_id),
    'history', coalesce((select jsonb_agg(jsonb_build_object(
                            'from', h.from_state, 'to', h.to_state, 'at', h.at) order by h.history_id)
                         from public.founder_command_status_history h where h.command_id = c.command_id), '[]'::jsonb),
    'traces', coalesce((select jsonb_agg(jsonb_build_object(
                            'trace_id', tr.trace_id, 'policy', tr.trace_policy_id,
                            'subject', tr.subject_kind, 'state_after', tr.state_after) order by tr.trace_id)
                        from public.phase_c_trace tr where tr.command_id = c.command_id), '[]'::jsonb))
  from public.founder_command c
  join public.founder_command_message m on m.message_id = c.message_id
  where c.command_id = p_command_id;
$function$


CREATE OR REPLACE FUNCTION public.fn_founder_command_trace_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t public.phase_c_trace%rowtype;
begin
  if tg_op = 'INSERT' then
    -- A command is BORN at 'received'. That is the only state a row may be created in with no
    -- trace, because the trace is opened by the router on the next statement. Creating one at a
    -- LATER state with a null trace was how a command became invisible to both command trace
    -- checks: commands_ahead_of_their_trace uses an INNER JOIN, which drops a null trace_id.
    if new.trace_id is null then
      if new.state <> 'received' then
        raise exception
          'founder_command: cannot be created at state % with no trace; only received is trace-less at birth',
          new.state using errcode = '23514',
          hint = 'Insert the command at received and transition it, or supply the root trace on '
              || 'the insert. TRACE-FOUNDER-COMMAND declares trace_required=YES.';
      end if;
      return new;
    end if;
    select * into t from public.phase_c_trace where trace_id = new.trace_id;
    if not found then
      raise exception 'founder_command: root trace % does not exist', new.trace_id
        using errcode = '23503';
    end if;
    return new;
  end if;

  if new.state is not distinct from old.state then return new; end if;
  if new.state = 'received' then return new; end if;

  -- received -> interpreting is the one move that legitimately precedes the trace: it is the
  -- transition the router makes in order to open the trace, in the same transaction, on the very
  -- next statement. Requiring the trace here would make it impossible to ever write one. Every
  -- state after that must have it, which is what the assertion below enforces.
  if old.state = 'received' and new.state = 'interpreting' and new.trace_id is null then
    return new;
  end if;

  if new.trace_id is null then
    raise exception 'founder_command %: cannot leave % without a root trace', new.command_id, old.state
      using errcode = '23514';
  end if;
  select * into t from public.phase_c_trace where trace_id = new.trace_id;
  if not found then
    raise exception 'founder_command %: root trace % does not exist', new.command_id, new.trace_id
      using errcode = '23503';
  end if;

  -- Advance the root so the two can never disagree, then assert it. The assertion is not
  -- decoration: if a future path sets state without going through this trigger, it fails here
  -- rather than shipping a command whose evidence describes a different moment.
  perform public.fn_phase_c_trace_advance(
    new.trace_id, new.state,
    new.state in ('completed','failed','cancelled','refused','superseded'),
    jsonb_build_object('evidence_refs', jsonb_build_array(
      jsonb_build_object('command_transition', old.state || ' -> ' || new.state, 'at', now()))));

  select * into t from public.phase_c_trace where trace_id = new.trace_id;
  if t.state_after is distinct from new.state then
    raise exception 'founder_command %: state % but root trace % still says %',
      new.command_id, new.state, new.trace_id, t.state_after using errcode = '23514';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_founder_habits()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'habits_total',     (select count(*) from founder_habit),
    'habits_confident', (select count(*) from founder_habit where confident),
    'evidence_floor',   3,
    'learned_at',       (select max(computed_at) from founder_habit),
    -- The note is part of the payload rather than the screen, so a caller that renders the rows
    -- without reading `confident` still carries the caveat with them.
    'note', 'A habit below the evidence floor is an observation, not a preference. sample_n travels with every row.',
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
              'habit_key', h.habit_key, 'habit_kind', h.habit_kind, 'value', h.observed_value,
              'text', h.observed_text, 'sample_n', h.sample_n, 'confident', h.confident,
              'evidence', h.evidence, 'last_seen', h.last_seen)
            order by h.confident desc, h.sample_n desc, h.habit_key)
            from founder_habit h), '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_founder_habits_learn()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  EVIDENCE_FLOOR constant int := 3;
  v_founder text;
  n_rows int := 0;
  n_owners int := 0;
begin
  -- EVERY OWNER IDENTITY, NOT A CHOSEN ONE. The first version picked `order by email limit 1` and
  -- landed on ahmadalzain1993@admin.quotesdone.com, which has decided nothing — all twelve founder
  -- decisions are attributed to management@quotesdone.com. It learned 2 habits from the wrong
  -- person and would have gone on doing so silently. Picking an identity alphabetically is picking
  -- it arbitrarily; the table is keyed (founder, habit_key) precisely so both can be held.
  select count(*) into n_owners from public.user_roles where role = 'owner';
  if n_owners = 0 then
    return jsonb_build_object('ok', false, 'reason', 'no owner identity in user_roles');
  end if;

  for v_founder in select lower(email) from public.user_roles where role = 'owner' order by email loop

  -- ── HABIT 1: what he does with each kind of thing that reaches him ────────────────────────────
  insert into public.founder_habit (founder, habit_key, habit_kind, observed_value, observed_text,
                                    sample_n, confident, evidence, first_seen, last_seen, computed_at)
  select v_founder,
         'disposition:' || a.kind,
         'disposition',
         round(100.0 * count(*) filter (where a.status = 'approved')
               / nullif(count(*), 0), 1),
         case
           when count(*) filter (where a.status = 'rejected') = count(*)
             then 'Rejects every ' || a.kind || ' that reaches him (' || count(*) || ' of ' || count(*)
                  || '). The queue is spending his attention on work he does not want.'
           when count(*) filter (where a.status in ('approved','done')) = count(*)
             then 'Approves every ' || a.kind || ' that reaches him (' || count(*) || ' of ' || count(*)
                  || '). A candidate for higher autonomy.'
           else 'Approves ' || count(*) filter (where a.status in ('approved','done')) || ' of '
                || count(*) || ' ' || a.kind || '.'
         end,
         count(*)::int,
         count(*) >= EVIDENCE_FLOOR,
         jsonb_build_object('kind', a.kind,
           'approved', count(*) filter (where a.status in ('approved','done')),
           'rejected', count(*) filter (where a.status = 'rejected'),
           'total', count(*), 'evidence_floor', EVIDENCE_FLOOR),
         min(a.created_at), max(a.decided_at), now()
    from public.agent_actions a
   where lower(coalesce(a.decided_by,'')) = v_founder
     and a.decided_at is not null
   group by a.kind
  on conflict (founder, habit_key) do update set
    observed_value = excluded.observed_value, observed_text = excluded.observed_text,
    sample_n = excluded.sample_n, confident = excluded.confident, evidence = excluded.evidence,
    first_seen = excluded.first_seen, last_seen = excluded.last_seen, computed_at = now();
  get diagnostics n_rows = row_count;

  -- ── HABIT 2: how long he takes, per kind. The latency IS the preference ──────────────────────
  -- He answers what he approves in a fraction of the time he leaves a rejection sitting, so "how
  -- long has this been waiting" is a prediction about the answer, not just a backlog number.
  insert into public.founder_habit (founder, habit_key, habit_kind, observed_value, observed_text,
                                    sample_n, confident, evidence, first_seen, last_seen, computed_at)
  select v_founder,
         'latency:' || a.kind,
         'latency',
         round(avg(extract(epoch from (a.decided_at - a.created_at)) / 3600.0)::numeric, 1),
         'Takes a mean of '
           || round(avg(extract(epoch from (a.decided_at - a.created_at)) / 3600.0)::numeric, 1)
           || ' hour(s) to answer a ' || a.kind || ', over ' || count(*) || ' decision(s).',
         count(*)::int,
         count(*) >= EVIDENCE_FLOOR,
         jsonb_build_object('kind', a.kind, 'decisions', count(*),
           'min_hours', round(min(extract(epoch from (a.decided_at - a.created_at)) / 3600.0)::numeric, 1),
           'max_hours', round(max(extract(epoch from (a.decided_at - a.created_at)) / 3600.0)::numeric, 1),
           'evidence_floor', EVIDENCE_FLOOR),
         min(a.created_at), max(a.decided_at), now()
    from public.agent_actions a
   where lower(coalesce(a.decided_by,'')) = v_founder
     and a.decided_at is not null and a.created_at is not null
   group by a.kind
  on conflict (founder, habit_key) do update set
    observed_value = excluded.observed_value, observed_text = excluded.observed_text,
    sample_n = excluded.sample_n, confident = excluded.confident, evidence = excluded.evidence,
    first_seen = excluded.first_seen, last_seen = excluded.last_seen, computed_at = now();

  end loop;

  select count(*) into n_rows from public.founder_habit;

  insert into public.agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('founder_habits', now(), now(), 'ok',
          jsonb_build_object('habits', n_rows, 'owners', n_owners,
            'confident', (select count(*) from public.founder_habit where confident)),
          'Learned ' || n_rows || ' habit(s) across ' || n_owners || ' owner identit(ies) from the '
          || 'founder''s own decisions, of which '
          || (select count(*) from public.founder_habit where confident)
          || ' clear the ' || EVIDENCE_FLOOR || '-observation floor. The rest are recorded as '
          || 'observations and are NOT presented as preferences.');

  return jsonb_build_object('ok', true, 'owners', n_owners, 'habits', n_rows,
    'confident', (select count(*) from public.founder_habit where confident),
    'evidence_floor', EVIDENCE_FLOOR);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_founder_queue(p_limit integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'waiting_on_you_total',
      (select count(*) from public.agent_actions a
         join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'founder'
        where a.status in ('pending','needs_review')
          and a.created_at >= public.fn_os_fresh_start_at()),
    'oldest_days',
      (select round(extract(epoch from now() - min(a.created_at)) / 86400)::int
         from public.agent_actions a
         join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'founder'
        where a.status in ('pending','needs_review')
          and a.created_at >= public.fn_os_fresh_start_at()),
    'waiting_on_you', coalesce((
      select jsonb_agg(x order by x->>'raised')
        from (select jsonb_build_object(
                       'id', a.id, 'kind', a.kind,
                       'kind_label', public.fn_ui_label('action_kind', a.kind),
                       'from', a.agent,
                       'title', left(coalesce(a.title, a.recommendation, ''), 160),
                       'raised', a.created_at,
                       'age_days', round(extract(epoch from now() - a.created_at) / 86400)::int) as x
                from public.agent_actions a
                join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'founder'
               where a.status in ('pending','needs_review')
                 and a.created_at >= public.fn_os_fresh_start_at()
               order by a.created_at
               limit greatest(coalesce(p_limit, 12), 1)) z), '[]'::jsonb),
    -- The machine's own work in flight, kept separate so the two are never added together again.
    'machine_is_working_on', (select count(*) from public.agent_actions a
                                join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'auto'
                               where a.status = 'pending'
                                 and a.created_at >= public.fn_os_fresh_start_at()),
    -- A kind nobody has classified. Fail-closed and NAMED: the sweep will not queue it and the
    -- worker will not settle it, so if this list is not empty, work is sitting still and this is
    -- the only place that says so.
    'unrouted_kinds', coalesce((
      select jsonb_agg(jsonb_build_object('kind', k,
                                          'kind_label', public.fn_ui_label('action_kind', k),
                                          'pending', n, 'oldest_days', d))
        from (select a.kind k, count(*) n,
                     round(extract(epoch from now() - min(a.created_at)) / 86400)::int d
                from public.agent_actions a
               where a.status = 'pending'
                 and a.created_at >= public.fn_os_fresh_start_at()
                 and not exists (select 1 from public.agent_action_kind_policy p where p.kind = a.kind)
               group by a.kind order by 2 desc) y), '[]'::jsonb),
    'fresh_start_at', public.fn_os_fresh_start_at());
$function$


CREATE OR REPLACE FUNCTION public.fn_founder_settings()
 RETURNS TABLE(setting_key text, store text, kind text, min_val numeric, max_val numeric, current_value text, description text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with reg(setting_key, store, kind, min_val, max_val, description) as (values
    ('invite_daily_cap',                 'app_secrets',     'int',    1,   200, 'How many supplier invitations may be sent in one day. fn_invite_ramp raises it on its own while the list behaves; setting it here overrides today.'),
    ('invite_max_bounce_rate',           'app_secrets',     'number', 0.01, 0.20,'The hard-bounce rate at which invites auto-pause.'),
    ('invite_enabled',                   'app_secrets',     'bool',   null, null,'Whether supplier invitations send at all.'),
    ('invite_target_per_category',       'app_secrets',     'int',    1,   100, 'How many confirmed suppliers a trade category is aiming for before it stops being prioritised.'),
    ('supplier_emails_enabled',          'app_secrets',     'bool',   null, null,'Whether any email may be sent to suppliers.'),
    ('email_enabled',                    'app_secrets',     'bool',   null, null,'The master switch for outbound email.'),
    ('wa_daily_cap',                     'app_secrets',     'int',    1,   500, 'How many WhatsApp messages the company may send in a day.'),
    ('wa_per_recipient_24h',             'app_secrets',     'int',    1,    10, 'How many WhatsApp messages one recipient may get in 24 hours.'),
    ('wa_autoreply_enabled',             'app_secrets',     'bool',   null, null,'Whether inbound WhatsApp gets an automatic reply.'),
    ('workflow_reflection_steps_per_day','decision_policy', 'int',    1,   200, 'How many non-demand workflow steps - health reports, forecasts, recommendations - may run in a day.'),
    ('cos_reflection_tasks_per_day',     'decision_policy', 'int',    1,   100, 'How many non-revenue tasks the chief of staff may hand to a large model in a day.'),
    ('match_max_fanout',                 'decision_policy', 'int',    1,    20, 'How many suppliers one RFQ may be sent to.'),
    ('match_max_fanout_per_trade',       'decision_policy', 'int',    1,    10, 'How many suppliers within a single trade one RFQ may reach.'),
    ('match_relevance_floor',            'decision_policy', 'int',    0,   100, 'The relevance score below which a supplier is not matched to an RFQ at all.'),
    ('confidence_min',                   'decision_policy', 'number', 0,     1, 'The confidence below which an agent escalates instead of acting.'),
    ('matching_strike_limit',            'decision_policy', 'int',    1,    10, 'How many times a supplier may ignore an RFQ before the matcher stops offering them work.')
  )
  select r.setting_key, r.store, r.kind, r.min_val, r.max_val,
         case r.store
           when 'app_secrets'     then (select s.value from public.app_secrets s where s.key = r.setting_key)
           when 'decision_policy' then (select d.value #>> '{}' from public.decision_policy d where d.key = r.setting_key)
         end,
         r.description
  from reg r;
$function$


CREATE OR REPLACE FUNCTION public.fn_fraud_resolve(p_subject_type text, p_subject_id text, p_action text, p_by text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_ok boolean := true; v_msg text := '';
begin
  if p_action = 'ban' then
    begin
      if p_subject_type in ('customer','customers') then
        update customers set banned=true, banned_reason=coalesce(banned_reason,'fraud: manual ban by '||coalesce(p_by,'admin')) where id = p_subject_id::uuid;
      elsif p_subject_type in ('supplier','lead','leads') then
        update leads set banned=true, matching_blocked=true, matching_block_reason=coalesce(matching_block_reason,'fraud ban'), banned_reason=coalesce(banned_reason,'fraud: manual ban by '||coalesce(p_by,'admin')) where id = p_subject_id::bigint;
      else v_ok:=false; v_msg:='unknown subject_type';
      end if;
    exception when others then v_ok:=false; v_msg:=SQLERRM;
    end;
    update fraud_flags set status='resolved', updated_at=now() where subject_type=p_subject_type and subject_id=p_subject_id;
  elsif p_action = 'unban' then
    begin
      if p_subject_type in ('customer','customers') then update customers set banned=false, banned_reason=null where id=p_subject_id::uuid;
      elsif p_subject_type in ('supplier','lead','leads') then update leads set banned=false, matching_blocked=false where id=p_subject_id::bigint;
      end if;
    exception when others then v_ok:=false; v_msg:=SQLERRM; end;
    update fraud_flags set status='resolved', updated_at=now() where subject_type=p_subject_type and subject_id=p_subject_id;
  elsif p_action = 'dismiss' then
    update fraud_flags set status='dismissed', updated_at=now() where subject_type=p_subject_type and subject_id=p_subject_id;
  else v_ok:=false; v_msg:='unknown action';
  end if;
  return jsonb_build_object('ok', v_ok, 'action', p_action, 'subject', p_subject_type||':'||p_subject_id, 'error', nullif(v_msg,''), 'by', p_by, 'at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_fraud_scan()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare before_ct int; after_ct int;
begin
  select count(*) into before_ct from fraud_flags;

  -- Abnormal pricing vs category benchmark (uses fn_price_confidence bands)
  insert into fraud_flags(kind,severity,subject_type,subject_id,detail,updated_at)
  select 'abnormal_price',
         case when (x.pc->>'band')='suspiciously_low' then 'high' else 'medium' end,
         'quote', q.id::text,
         jsonb_build_object('band',x.pc->>'band','amount',q.quote_amount,'category',i.category,'median',x.pc->>'median'), now()
  from quotes q join inquiries i on i.id=q.inquiry_id
  cross join lateral (select fn_price_confidence(i.category, q.quote_amount) as pc) x
  where (x.pc->>'band') in ('suspiciously_low','suspiciously_high')
  on conflict (kind,subject_type,subject_id) do update set detail=excluded.detail, severity=excluded.severity, updated_at=now();

  -- Duplicate registered-supplier phones
  insert into fraud_flags(kind,severity,subject_type,subject_id,detail,updated_at)
  select 'dup_supplier_phone','medium','phone', phone,
         jsonb_build_object('supplier_ids', array_agg(id), 'count', count(*)), now()
  from leads where claimed = true and coalesce(phone,'') <> '' group by phone having count(*) > 1
  on conflict (kind,subject_type,subject_id) do update set detail=excluded.detail, updated_at=now();

  -- Duplicate customer phones
  insert into fraud_flags(kind,severity,subject_type,subject_id,detail,updated_at)
  select 'dup_customer_phone','medium','cphone', phone,
         jsonb_build_object('customer_ids', array_agg(id), 'count', count(*)), now()
  from customers where coalesce(phone,'') <> '' group by phone having count(*) > 1
  on conflict (kind,subject_type,subject_id) do update set detail=excluded.detail, updated_at=now();

  -- Identical bid amounts on the same RFQ from different suppliers (possible collusion/copy)
  insert into fraud_flags(kind,severity,subject_type,subject_id,detail,updated_at)
  select 'identical_bids','high','inquiry', inquiry_id::text,
         jsonb_build_object('amount', quote_amount, 'suppliers', array_agg(distinct supplier_id)), now()
  from quotes where quote_amount > 0
  group by inquiry_id, quote_amount having count(distinct supplier_id) > 1
  on conflict (kind,subject_type,subject_id) do update set detail=excluded.detail, updated_at=now();

  -- Copied quotations: same committed_hash across different suppliers
  insert into fraud_flags(kind,severity,subject_type,subject_id,detail,updated_at)
  select 'copied_quote','high','hash', committed_hash,
         jsonb_build_object('quote_ids', array_agg(id), 'suppliers', array_agg(distinct supplier_id)), now()
  from quotes where coalesce(committed_hash,'') <> ''
  group by committed_hash having count(distinct supplier_id) > 1
  on conflict (kind,subject_type,subject_id) do update set detail=excluded.detail, updated_at=now();

  select count(*) into after_ct from fraud_flags;
  return jsonb_build_object('total_flags', after_ct, 'new_flags', after_ct - before_ct);
end $function$


CREATE OR REPLACE FUNCTION public.fn_freeze_supplier_brief(p_inquiry_id uuid, p_reason text DEFAULT 'dispatch'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_brief jsonb; v_sha text; v_prev_sha text; v_ver integer;
begin
  -- MUST read the live projection. Reading inquiries_supplier_safe here would mean reading the
  -- previously frozen brief back, and no later change could ever be detected.
  select to_jsonb(s) - 'status' - 'outcome' - 'hired_supplier_id'
    into v_brief from public.inquiries_supplier_live s where s.id = p_inquiry_id;
  if v_brief is null then
    return jsonb_build_object('frozen', false, 'reason', 'inquiry_not_found');
  end if;
  v_sha := encode(sha256(convert_to(v_brief::text, 'UTF8')), 'hex');
  select b.brief_sha256, b.version into v_prev_sha, v_ver
    from public.inquiry_supplier_brief b where b.inquiry_id = p_inquiry_id order by b.version desc limit 1;
  if v_prev_sha is not null and v_prev_sha = v_sha then
    return jsonb_build_object('frozen', false, 'reason', 'unchanged', 'version', v_ver, 'sha256', v_sha);
  end if;
  insert into public.inquiry_supplier_brief(inquiry_id, version, frozen_reason, brief, brief_sha256)
  values (p_inquiry_id, coalesce(v_ver, 0) + 1, coalesce(p_reason, 'dispatch'), v_brief, v_sha)
  returning version into v_ver;
  return jsonb_build_object('frozen', true, 'version', v_ver, 'sha256', v_sha);
end $function$


CREATE OR REPLACE FUNCTION public.fn_gate_state_satisfies(s gate_state)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select s in ('passed','not_applicable');
$function$


CREATE OR REPLACE FUNCTION public.fn_gl_entry(p_date date, p_memo text, p_source text, p_ref text, p_lines jsonb, p_created_by text DEFAULT 'system'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare jid bigint; ln jsonb; i int := 0;
begin
  insert into public.gl_journal(entry_date, memo, source, source_ref, created_by)
    values (coalesce(p_date, (now() at time zone 'utc')::date), p_memo, coalesce(p_source,'manual'), p_ref, p_created_by)
    returning id into jid;
  for ln in select * from jsonb_array_elements(p_lines) loop
    i := i + 1;
    insert into public.gl_journal_lines(journal_id, line_no, account_code, debit, credit, memo)
      values (jid, i, (ln->>'account'),
              round(coalesce((ln->>'debit')::numeric,0),2),
              round(coalesce((ln->>'credit')::numeric,0),2),
              ln->>'memo');
  end loop;
  perform public.fn_gl_post(jid);
  return jid;
end $function$


CREATE OR REPLACE FUNCTION public.fn_gl_journal_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if tg_op in ('UPDATE','DELETE') and old.status = 'posted'
     and not (tg_op='UPDATE' and new.status='void' and old.status='posted' and new.reverses is not null) then
    -- allow only the controlled void marking done by fn_gl_reverse (new.status='void')
    if tg_op='DELETE' or (tg_op='UPDATE' and old.status='posted' and new.status='posted'
         and (new.entry_date<>old.entry_date or new.memo is distinct from old.memo or new.source<>old.source)) then
      raise exception 'Posted journal % is immutable (reverse it instead)', old.id;
    end if;
  end if;
  return case when tg_op='DELETE' then old else new end;
end $function$


CREATE OR REPLACE FUNCTION public.fn_gl_lines_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare st text;
begin
  select status into st from public.gl_journal where id = coalesce(new.journal_id, old.journal_id);
  if st = 'posted' then
    raise exception 'Cannot modify lines of a posted journal (reverse it instead)';
  end if;
  return case when tg_op='DELETE' then old else new end;
end $function$


CREATE OR REPLACE FUNCTION public.fn_gl_net_income()
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select coalesce(sum(case when type='revenue' then balance else -balance end),0)
  from public.gl_account_balances where type in ('revenue','expense');
$function$


CREATE OR REPLACE FUNCTION public.fn_gl_post(p_journal bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare d numeric(18,2); c numeric(18,2); n int; st text;
begin
  select status into st from public.gl_journal where id=p_journal;
  if st is null then raise exception 'journal % not found', p_journal; end if;
  if st='posted' then return p_journal; end if;
  select coalesce(sum(debit),0), coalesce(sum(credit),0), count(*) into d,c,n from public.gl_journal_lines where journal_id=p_journal;
  if n < 2 then raise exception 'journal % needs at least 2 lines', p_journal; end if;
  if d <> c then raise exception 'journal % out of balance: debits % <> credits %', p_journal, to_char(d,'FM999999990.00'), to_char(c,'FM999999990.00'); end if;
  if d = 0 then raise exception 'journal % has zero amount', p_journal; end if;
  update public.gl_journal
     set status='posted', posted_at=now(),
         entry_no = coalesce(entry_no, 'JE-'||lpad(p_journal::text,6,'0'))
   where id=p_journal;
  return p_journal;
end $function$


CREATE OR REPLACE FUNCTION public.fn_gl_reverse(p_journal bigint, p_date date, p_memo text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare jid bigint; r record;
begin
  if (select status from public.gl_journal where id=p_journal) <> 'posted' then
    raise exception 'can only reverse a posted journal'; end if;
  insert into public.gl_journal(entry_date, memo, source, source_ref, reverses, created_by)
    values (coalesce(p_date,(now() at time zone 'utc')::date),
            coalesce(p_memo,'Reversal of JE '||p_journal), 'reversal', p_journal::text, p_journal, 'system')
    returning id into jid;
  for r in select account_code, debit, credit, line_no from public.gl_journal_lines where journal_id=p_journal loop
    insert into public.gl_journal_lines(journal_id, line_no, account_code, debit, credit)
      values (jid, r.line_no, r.account_code, r.credit, r.debit);  -- swap
  end loop;
  perform public.fn_gl_post(jid);
  return jid;
end $function$


CREATE OR REPLACE FUNCTION public.fn_gl_sync_business()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int := 0; acct text;
        fee_pct numeric; fee_fixed numeric; fee numeric(18,2); gross numeric(18,2); net numeric(18,2);
        fx numeric; amt_aed numeric(18,2); diff numeric(18,2); extra numeric(18,2); lines jsonb;
begin
  select num_value into fee_pct   from public.gl_settings where key='stripe_fee_pct';
  select num_value into fee_fixed from public.gl_settings where key='stripe_fee_fixed';
  select num_value into fx        from public.gl_settings where key='usd_to_aed';
  fee_pct   := coalesce(fee_pct,0);
  fee_fixed := coalesce(fee_fixed,0);
  fx        := coalesce(fx, 3.6725);

  -- 1) Reveal-fee revenue with Stripe fee split (refunded transactions excluded)
  for r in
    select id, reveal_fee, coalesce(revealed_at::date, current_date) as d
    from public.transactions
    where fee_status='paid' and coalesce(reveal_fee,0) > 0
      and coalesce(refund_status,'') not in ('refunded','refund_approved')
      and not exists (select 1 from public.gl_journal g where g.source='reveal_fee' and g.source_ref=transactions.id::text)
  loop
    gross := round(r.reveal_fee,2);
    fee   := round(gross*fee_pct/100 + fee_fixed, 2);
    if fee >= gross then fee := 0; end if;
    net   := gross - fee;
    perform public.fn_gl_entry(r.d, 'Reveal fee (net of Stripe fee)', 'reveal_fee', r.id::text,
      case when fee > 0 then
        jsonb_build_array(
          jsonb_build_object('account','1050','debit',net),
          jsonb_build_object('account','6100','debit',fee),
          jsonb_build_object('account','4000','credit',gross))
      else
        jsonb_build_array(
          jsonb_build_object('account','1050','debit',gross),
          jsonb_build_object('account','4000','credit',gross))
      end, 'gl_sync');
    n := n + 1;
  end loop;

  -- 1b) REFUND PAID OUT TO THE CUSTOMER (previously never posted at all).
  -- If revenue was booked before the refund, this also reverses its effect on the P&L.
  for r in
    select t.id, coalesce(t.reveal_fee, t.app_fee, 0) as amt,
           coalesce(t.refund_resolved_at::date, t.revealed_at::date, current_date) as d
    from public.transactions t
    where coalesce(t.refund_status,'') in ('refunded','refund_approved')
      and coalesce(coalesce(t.reveal_fee, t.app_fee), 0) > 0
      and not exists (select 1 from public.gl_journal g where g.source='refund_paid' and g.source_ref=t.id::text)
  loop
    gross := round(r.amt,2);
    perform public.fn_gl_entry(r.d, 'Reveal fee refunded to customer (paid from our balance)',
      'refund_paid', r.id::text,
      jsonb_build_array(jsonb_build_object('account','6900','debit',gross),
                        jsonb_build_object('account','1050','credit',gross)), 'gl_sync');
    n := n + 1;
  end loop;

  -- 2) Clawback RAISED on the supplier. Credits 6900 (recovering the refund), NOT 4100.
  --    Any admin fee / interest assessed at the same time is genuine income -> 4400.
  for r in
    select id, amount_due,
           coalesce(admin_fee,0) + coalesce(interest_amount,0) as extra_owed,
           coalesce(reveal_date, created_at::date, current_date) as d
    from public.supplier_dues
    where coalesce(amount_due,0) > 0
      and coalesce(status,'') not in ('waived','cancelled','reversed')
      and not exists (select 1 from public.gl_journal g where g.source='commission_accrue' and g.source_ref=supplier_dues.id::text)
  loop
    extra := round(coalesce(r.extra_owed,0),2);
    lines := jsonb_build_array(
      jsonb_build_object('account','1110','debit', round(r.amount_due,2) + extra),
      jsonb_build_object('account','6900','credit', round(r.amount_due,2)));
    if extra > 0 then lines := lines || jsonb_build_array(jsonb_build_object('account','4400','credit', extra)); end if;
    perform public.fn_gl_entry(r.d,
      'Refund clawback raised on supplier' || case when extra > 0 then ' (incl. ' || extra || ' admin fee/interest)' else '' end,
      'commission_accrue', r.id::text, lines, 'gl_sync');
    n := n + 1;
  end loop;

  -- 2b) Supplier SETTLES via Stripe.
  for r in
    select id, amount_due,
           coalesce(fine_amount,0) + coalesce(interest_amount,0) + coalesce(admin_fee,0) as extra_owed,
           paid_at::date as d
    from public.supplier_dues
    where status in ('paid','settled') and paid_at is not null and coalesce(amount_due,0) > 0
      and not exists (select 1 from public.gl_journal g where g.source='commission_collect' and g.source_ref=supplier_dues.id::text)
  loop
    extra := round(coalesce(r.extra_owed,0),2);
    gross := round(r.amount_due,2) + extra;
    fee   := round(gross*fee_pct/100 + fee_fixed, 2);
    if fee >= gross then fee := 0; end if;
    net   := gross - fee;

    lines := jsonb_build_array(jsonb_build_object('account','1050','debit',net));
    if fee > 0 then lines := lines || jsonb_build_array(jsonb_build_object('account','6100','debit',fee)); end if;
    lines := lines || jsonb_build_array(jsonb_build_object('account','1110','credit', gross));

    perform public.fn_gl_entry(r.d,
      'Refund clawback settled by supplier via Stripe' || case when extra > 0 then ' (incl. ' || extra || ' admin fee/interest)' else '' end,
      'commission_collect', r.id::text, lines, 'gl_sync');
    n := n + 1;
  end loop;

  -- 2c) SUBSCRIPTION revenue (RULE 1). Previously never posted - 4200 sat unused.
  for r in
    select l.id, l.registration_fee_due, l.registration_paid_at::date as d
    from public.leads l
    where l.registration_status = 'paid'
      and l.registration_paid_at is not null
      and coalesce(l.registration_fee_due,0) >= 0
      and coalesce(l.subscription_exempt,false) = false
      and not exists (select 1 from public.gl_journal g
                      where g.source='subscription' and g.source_ref = l.id::text || ':' || l.registration_paid_at::date)
  loop
    gross := round(coalesce(r.registration_fee_due,0),2);
    if gross <= 0 then continue; end if;
    fee := round(gross*fee_pct/100 + fee_fixed, 2);
    if fee >= gross then fee := 0; end if;
    net := gross - fee;
    lines := jsonb_build_array(jsonb_build_object('account','1050','debit',net));
    if fee > 0 then lines := lines || jsonb_build_array(jsonb_build_object('account','6100','debit',fee)); end if;
    lines := lines || jsonb_build_array(jsonb_build_object('account','4200','credit',gross));
    perform public.fn_gl_entry(r.d, 'Annual supplier subscription', 'subscription',
      r.id::text || ':' || r.d::text, lines, 'gl_sync');
    n := n + 1;
  end loop;

  -- 3) Expense charges, converted to AED (the ledger currency)
  for r in
    select e.id, e.amount, upper(coalesce(e.currency,'AED')) as cur, e.category, e.vendor,
           coalesce(e.charged_on, e.created_at::date) as d
    from public.expense_entries e
    where coalesce(e.amount,0) > 0
      and not exists (select 1 from public.gl_journal g where g.source='expense' and g.source_ref=e.id::text)
  loop
    if r.cur not in ('AED','USD') then
      begin
        insert into public.founder_alerts(level, event, detail, channel)
        values ('warn', 'gl_unconvertible_currency',
                'Expense #'||r.id||' from '||coalesce(r.vendor,'?')||' is in '||r.cur||
                ', which has no rate in gl_settings, so it was NOT posted. Expenses are understated by '||
                r.amount||' '||r.cur||' until a rate is added. Skipped rather than booked at 1:1.', 'system');
      exception when others then null; end;
      continue;
    end if;
    amt_aed := round(r.amount * case when r.cur='USD' then fx else 1 end, 2);
    acct := coalesce((select account_code from public.gl_expense_map m where m.category=r.category), '6300');
    perform public.fn_gl_entry(r.d,
      'Expense: '||coalesce(r.category,'G&A')||case when r.cur='USD' then ' ('||r.amount||' USD @ '||fx||')' else '' end,
      'expense', r.id::text,
      jsonb_build_array(jsonb_build_object('account',acct,'debit',amt_aed),
                        jsonb_build_object('account','1000','credit',amt_aed)), 'gl_sync');
    n := n + 1;
  end loop;

  -- 3b) One-off FX correction for USD expenses posted at 1:1 before the 19 Jul 2026 fix.
  for r in
    select e.id, e.amount, e.category, e.vendor,
           coalesce(e.charged_on, e.created_at::date) as d,
           (select sum(jl.debit) from public.gl_journal g
              join public.gl_journal_lines jl on jl.journal_id = g.id
             where g.source='expense' and g.source_ref = e.id::text and jl.debit > 0) as posted_aed
    from public.expense_entries e
    where upper(coalesce(e.currency,'AED')) = 'USD'
      and coalesce(e.amount,0) > 0
      and exists (select 1 from public.gl_journal g where g.source='expense' and g.source_ref=e.id::text)
      and not exists (select 1 from public.gl_journal g where g.source='expense_fx_adj' and g.source_ref=e.id::text)
  loop
    diff := round(r.amount * fx, 2) - coalesce(r.posted_aed, 0);
    if diff is null or diff = 0 then continue; end if;
    acct := coalesce((select account_code from public.gl_expense_map m where m.category=r.category), '6300');
    perform public.fn_gl_entry(r.d,
      'FX correction: expense #'||r.id||' ('||coalesce(r.vendor,'?')||') was booked at 1:1; restated at USD/AED '||fx,
      'expense_fx_adj', r.id::text,
      jsonb_build_array(jsonb_build_object('account',acct,'debit',diff),
                        jsonb_build_object('account','1000','credit',diff)), 'gl_fx_fix');
    n := n + 1;
  end loop;

  return n;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_goal_attainment(p_horizon text DEFAULT 'monthly'::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with p as (
    select case p_horizon
             when 'monthly'   then to_char(now(),'YYYY-MM')
             when 'quarterly' then to_char(now(),'YYYY')||'-Q'||extract(quarter from now())::int
             else to_char(now(),'YYYY') end as label),
  s as (
    select g.actual_value, g.target_value, coalesce(cg.direction,'at_least') dir
      from goal_period g
      left join company_goals cg on cg.key = g.goal_key
      cross join p
     where g.horizon = p_horizon and g.period_label = p.label and g.target_value is not null)
  select jsonb_build_object(
    'horizon', p_horizon,
    'period', (select label from p),
    'goals_total', count(*),
    'goals_measured', count(*) filter (where actual_value is not null),
    'pct', round(avg(case
        -- NOT least(100, ...): least() ignores nulls, so an unmeasured goal scored 100%.
        when actual_value is null then null
        when dir in ('at_most','down')
          then least(100.0, case when actual_value = 0 then 100.0
                                 else 100.0 * target_value / nullif(actual_value,0) end)
        else least(100.0, 100.0 * actual_value / nullif(target_value,0)) end), 1))
  from s;
$function$


CREATE OR REPLACE FUNCTION public.fn_goal_decompose()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record;
  v_created int := 0;
  v_adopted int := 0;
  v_id bigint;
  v_unmeasurable int;
begin
  for r in
    select g.key, g.goal, g.target_value, g.unit, g.measure_sql, g.owner_dept, g.horizon
      from company_goals g
      join org_departments d on d.dept_key = g.owner_dept and d.active
     where g.active and coalesce(g.measure_sql,'') <> ''
  loop
    -- Adopt the existing objective for this (department, goal) pair if there is one.
    select id into v_id from department_objective
     where dept_key = r.owner_dept and goal_key = r.key and active
     order by sort, id limit 1;

    if v_id is not null then
      update department_objective
         set target_value = coalesce(target_value, r.target_value),
             unit         = coalesce(unit,         r.unit),
             measure_sql  = coalesce(measure_sql,  r.measure_sql),
             updated_at   = now()
       where id = v_id
         and (measure_sql is null or target_value is null or unit is null);
      if found then v_adopted := v_adopted + 1; end if;
    else
      insert into department_objective
        (dept_key, objective, horizon, goal_key, target_value, unit, measure_sql, status, active)
      values
        (r.owner_dept, r.goal, coalesce(r.horizon,'year_1'), r.key,
         r.target_value, r.unit, r.measure_sql, 'active', true);
      v_created := v_created + 1;
    end if;
  end loop;

  select count(*) into v_unmeasurable from company_goals where active and coalesce(measure_sql,'')='';

  return jsonb_build_object(
    'created', v_created,
    'adopted', v_adopted,
    'company_goals_without_a_measure', v_unmeasurable,
    'note', 'A goal with no measure_sql cannot be handed down. Those '||v_unmeasurable||
            ' goals are the same defect one level up.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_goal_period_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v numeric; n int := 0; created int := 0;
        v_month text := to_char(now(),'YYYY-MM');
        v_qtr   text := to_char(now(),'YYYY')||'-Q'||extract(quarter from now())::int;
        v_year  text := to_char(now(),'YYYY');
begin
  -- ---- ROLL THE PERIOD FORWARD ---------------------------------------------------------------
  -- A period that never opens is a period that never closes. Each active goal gets a row for the
  -- CURRENT month, quarter and year, carrying forward the target from its most recent row for that
  -- horizon so the target is not silently lost or re-derived differently.
  insert into goal_period (goal_key, horizon, period_label, target_value, owner_dept, status)
  select g.key, h.horizon, h.label,
         (select p.target_value from goal_period p
           where p.goal_key = g.key and p.horizon = h.horizon
           order by p.period_label desc limit 1),
         g.owner_dept, 'open'
    from company_goals g
    cross join (values ('monthly', v_month), ('quarterly', v_qtr), ('annual', v_year)) as h(horizon, label)
   where g.active
     and not exists (select 1 from goal_period p
                      where p.goal_key = g.key and p.horizon = h.horizon and p.period_label = h.label);
  get diagnostics created = row_count;

  -- ---- MEASURE THE CURRENT PERIOD -------------------------------------------------------------
  for r in
    select gp.id, gp.goal_key, gp.target_value, g.measure_sql, g.direction
    from goal_period gp join company_goals g on g.key = gp.goal_key
    where g.active and g.measure_sql is not null
      and gp.period_label in (v_month, v_qtr, v_year)
  loop
    v := null;
    begin execute r.measure_sql into v; exception when others then v := null; end;
    if v is not null then
      update goal_period
         set actual_value = v,
             status = case
               when r.target_value is null or r.target_value = 0 then 'tracking'
               -- 'at_most'/'at_least' is the vocabulary company_goals actually stores. 'down'/'up'
               -- are accepted as synonyms because one row still uses 'up' and a scorer that only
               -- knows one dialect is how 19 goals came to be scored upside down.
               when coalesce(r.direction,'at_least') in ('at_most','down')
                 then case when v <= r.target_value then 'on_track'
                           when v <= r.target_value * 1.1 then 'near' else 'at_risk' end
                 else case when v >= r.target_value then 'on_track'
                           when v >= r.target_value * 0.9 then 'near' else 'at_risk' end
             end,
             updated_at = now()
       where id = r.id;
      n := n + 1;
    end if;
  end loop;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('goal_period_refresh', now(), now(), 'ok',
          jsonb_build_object('updated', n, 'periods_opened', created,
                             'month', v_month, 'quarter', v_qtr, 'year', v_year),
          'Goal periods refreshed: '||created||' period row(s) opened for '||v_month||'/'||v_qtr||'/'||v_year
          ||', '||n||' measured from live SQL. '
          ||(select count(*) from company_goals where active and measure_sql is null)
          ||' active goal(s) still carry no measure_sql and can never produce an actual.');
  return jsonb_build_object('updated', n, 'periods_opened', created);
end $function$


CREATE OR REPLACE FUNCTION public.fn_governance_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_sensitive boolean;
begin
  v_sensitive := (coalesce(NEW.agent,'') ~* 'legal|financ|complian|security'
                  or coalesce(NEW.kind,'') ~* 'legal|financ|complian|security|payment|refund|payout|pricing|price');

  -- Explainability: stamp a confidence + evidence basis when the caller did not provide one.
  -- These agents derive recommendations deterministically from live platform data, so the
  -- factual basis is high-confidence; the evidence line records exactly why.
  --
  -- THE TWO ARE INDEPENDENT. They were nested, so supplying a confidence silently cost the row its
  -- evidence — see this file's header for the row that proved it.
  if NEW.confidence is null then
    NEW.confidence := 0.9;
  end if;
  if NEW.evidence is null then
    NEW.evidence := jsonb_build_object('basis','deterministic rule from live platform data',
                                       'agent',NEW.agent,'kind',NEW.kind);
  end if;

  -- Escalation marker (does not reroute status): low confidence or sensitive domain.
  if NEW.escalated is not true and (coalesce(NEW.confidence,0) < 0.6 or v_sensitive) then
    NEW.escalated := true;
    NEW.escalation_reason := coalesce(NEW.escalation_reason,
      case when coalesce(NEW.confidence,0) < 0.6
           then 'Confidence below 0.60 threshold — human review required.'
           else 'Sensitive domain (legal/financial/compliance/security) — human review required.' end);
  end if;

  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_graph_rebuild()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n_nodes int := 0; n_edges int := 0;
begin
  delete from graph_edges; delete from graph_nodes;

  insert into graph_nodes (kind, ref_id, label)
  select 'operating_system', os_key, name from operating_system where active
  union all select 'department', dept_key, name from org_departments where active
  union all select 'employee', agent_key, coalesce(title, agent_key) from org_agents where active
  union all select 'category', slug, name from catalog_supplier_categories
  union all select 'goal', key, goal from company_goals where active
  union all select 'workflow', workflow_key, name from workflow
  union all select 'responsibility', responsibility, responsibility from os_responsibility
  -- THE CATEGORY SPECIALISTS. The `served_by` edge below has always pointed here and this node kind
  -- has never existed, so all 84 of those edges hung off nothing.
  union all select 'category_agent', a.slug, coalesce(nullif(btrim(a.name), ''), a.slug)
    from category_agents a where coalesce(a.active, true)
  -- THE SUPPLY BOOK. One node per category pool rather than 20,470 dots, built from v_supply_gap so
  -- the map and the supply reports read from the same numbers. The label carries the state, so the
  -- node says something.
  union all select 'supplier_pool', g.slug,
         g.name || ' — ' || g.sendable || ' sendable, ' || g.invited || ' invited, ' || g.approved || ' approved'
    from v_supply_gap g
  -- THE KNOWLEDGE BASE. One node per KB category with its depth.
  union all select 'knowledge', k.category, k.category || ' — ' || k.n || ' chunk(s)'
    from (select category, count(*) n from kb_chunks where category is not null group by category) k
  -- ...and one per KNOWLEDGE DOMAIN the employees actually hold. These are a second, coarser
  -- vocabulary than the kb_chunks slugs ('UAE Regulations & Authorities' beside 'cat:signage'),
  -- and they are the only one that joins to an employee: measured, 0 of agent_knowledge's 1,942
  -- rows carry a topic equal to a kb_chunks category. Without these the knowledge->employee hop
  -- cannot be drawn at all.
  union all select 'knowledge', t.topic, t.topic || ' — held by ' || t.n || ' employee(s)'
    from (select topic, count(distinct agent_key) n from agent_knowledge
           where agent_key <> '_global' and topic is not null group by topic) t
  -- THE BUYER SIDE. One node per real customer. This is the class the map was missing: a
  -- marketplace brain that drew its supply pools, its departments and its knowledge, and no buyer.
  union all select 'customer', c.id::text,
         coalesce(nullif(btrim(c.full_name), ''), c.email, c.id::text)
    from customers c
  -- THE TRADE CHAIN. Empty today (0 inquiries, 0 quotes, 0 transactions) and deliberately left
  -- empty rather than seeded: each of these becomes a node the moment the business does the thing.
  union all select 'rfq', i.id::text,
         coalesce('RFQ #' || i.rfq_no::text, 'RFQ ' || left(i.id::text, 8))
         || ' — ' || coalesce(i.category, 'uncategorised') || ', ' || coalesce(i.status, 'new')
    from inquiries i
  union all select 'quote', q.id::text,
         'Quote ' || left(q.id::text, 8) || ' — AED ' || coalesce(q.customer_price, q.quote_amount, 0)::text
    from quotes q
  union all select 'revenue', t.id::text,
         'Reveal ' || left(t.id::text, 8) || ' — AED ' || coalesce(t.reveal_fee, t.app_fee, 0)::text
    from transactions t
  -- MARKETING. One node per piece of content the marketing employees actually produced.
  union all select 'campaign', d.id::text,
         coalesce(nullif(btrim(d.title), ''), 'draft ' || d.id::text)
         || ' — ' || coalesce(d.channel, 'unrouted') || ', ' || coalesce(d.status, 'draft')
    from content_drafts d
  on conflict do nothing;
  get diagnostics n_nodes = row_count;

  insert into graph_edges (src_kind, src_ref, rel, dst_kind, dst_ref)
  select 'operating_system', os_key, 'contains', 'department', dept_key from os_department
  union all
  select 'department', a.department, 'employs', 'employee', a.agent_key from org_agents a where a.active
  union all
  select 'employee', manager_key, 'manages', 'employee', agent_key from org_agents where active and manager_key is not null
  union all
  select 'operating_system', os_key, 'owns', 'responsibility', responsibility from os_responsibility
  union all
  select 'operating_system', os_key, 'runs', 'workflow', workflow_key from workflow where os_key is not null
  union all
  select distinct 'employee', k.agent_key, 'accountable_for', 'goal', k.serves_goal
    from employee_kpi k where k.active and k.serves_goal is not null
     and exists (select 1 from company_goals g where g.key=k.serves_goal and g.active)
     and exists (select 1 from org_agents a where a.agent_key=k.agent_key and a.active)
  union all
  select distinct 'category', c.slug, 'served_by', 'category_agent', m.agent_slug
    from category_agent_map m join catalog_supplier_categories c on c.slug=m.catalog_slug
   where exists (select 1 from category_agents a where a.slug=m.agent_slug and coalesce(a.active,true))
  -- Both hang off the category node that already exists, which is what makes the map walkable:
  -- department -> category -> supplier pool, and department -> category -> knowledge.
  union all
  select 'category', g.slug, 'supplied_by', 'supplier_pool', g.slug from v_supply_gap g
  union all
  select 'category', regexp_replace(k.category,'^cat:',''), 'documented_by', 'knowledge', k.category
    from (select distinct category from kb_chunks where category is not null) k
   where exists (select 1 from catalog_supplier_categories c
                  where c.slug = regexp_replace(k.category,'^cat:',''))
  -- ---- THE TRADE CHAIN, hop by hop ----------------------------------------------------------
  -- customer -> rfq: who asked for what.
  union all
  select distinct 'customer', i.customer_id::text, 'raised', 'rfq', i.id::text
    from inquiries i where i.customer_id is not null
     and exists (select 1 from customers c where c.id = i.customer_id)
  -- rfq -> category: what trade the ask belongs to.
  union all
  select distinct 'rfq', i.id::text, 'in_category', 'category', i.category
    from inquiries i where i.category is not null
     and exists (select 1 from catalog_supplier_categories c where c.slug = i.category)
  -- supplier_pool -> quote: which pool the price came out of. The quote hangs off the pool for the
  -- category of its own inquiry, which is the pool the RFQ was actually sent to.
  union all
  select distinct 'supplier_pool', i.category, 'priced_by', 'quote', q.id::text
    from quotes q join inquiries i on i.id = q.inquiry_id
   where i.category is not null
     and exists (select 1 from v_supply_gap g where g.slug = i.category)
  -- quote -> revenue: the reveal that turned a price into money.
  union all
  select distinct 'quote', t.quote_id::text, 'realised_as', 'revenue', t.id::text
    from transactions t where t.quote_id is not null
  -- revenue -> campaign: the marketing that fed the category the money came from.
  union all
  select distinct 'revenue', t.id::text, 'attributed_to', 'campaign', d.id::text
    from transactions t
    join inquiries i on i.id = t.inquiry_id
    join content_drafts d on d.category = i.category
  -- campaign -> knowledge: the corpus the content was written out of.
  union all
  select distinct 'campaign', d.id::text, 'draws_on', 'knowledge', d.category
    from content_drafts d where d.category is not null
     and exists (select 1 from kb_chunks k where k.category = d.category)
  -- knowledge -> employee: which domain each employee holds. kb_usage_log was tried first and is
  -- the wrong join despite being the usage table: measured, its `category` is the RETRIEVAL CONTEXT
  -- ('agent_context' on 144 of 144 rows), not a KB category, so 0 of its rows join to a knowledge
  -- node. agent_knowledge is the honest source and its topics are emitted as nodes above.
  union all
  select distinct 'knowledge', k.topic, 'held_by', 'employee', k.agent_key
    from agent_knowledge k
   where k.agent_key <> '_global' and k.topic is not null
     and exists (select 1 from org_agents a where a.agent_key = k.agent_key and a.active)
  on conflict do nothing;
  get diagnostics n_edges = row_count;

  -- THE NIGHTLY REBUILD USED TO EAT THE SUPPLIER-MARKET EDGES. fn_graph_supplier_market is careful
  -- in one direction only — it deletes just the `adjacent_to` edges it owns, with a comment saying
  -- it can therefore run independently of the nightly rebuild. The nightly rebuild was not careful
  -- back: `delete from graph_edges` above removes all 242 of its category adjacency edges, which
  -- then stayed missing until that function next ran on its own schedule. Calling it here closes
  -- the loop, so a rebuild always leaves a COMPLETE graph rather than one that is correct only
  -- between 04:05 and whenever the market function happens to run.
  perform public.fn_graph_supplier_market();

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('graph_rebuild',now(),now(),'ok',jsonb_build_object('nodes',n_nodes,'edges',n_edges),
    'Company brain rebuilt: '||n_nodes||' nodes, '||n_edges||' edges.');
  return jsonb_build_object('nodes',n_nodes,'edges',n_edges);
end $function$


CREATE OR REPLACE FUNCTION public.fn_graph_supplier_market()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n_edges int := 0; n_props int := 0;
begin
  -- Recomputed wholesale, like fn_graph_rebuild does. Only the edges this function owns are
  -- removed, so it can run independently of the nightly rebuild without eating its work.
  delete from graph_edges where rel = 'adjacent_to' and src_kind = 'category';

  -- b.slug > a.slug emits each unordered pair once. Without it every pair appears twice, which
  -- would double every count a reader aggregates and make the graph look denser than it is.
  insert into graph_edges (src_kind, src_ref, rel, dst_kind, dst_ref, props)
  select 'category', a.slug, 'adjacent_to', 'category', b.slug,
         jsonb_build_object('companies', count(distinct a.lead_id))
  from lead_category a
  join lead_category b on b.lead_id = a.lead_id and b.slug > a.slug
  group by a.slug, b.slug
  -- THE FLOOR IS THE HONESTY. Two companies serving both categories is a coincidence, not an
  -- adjacency, and drawing it would fill the graph with lines that mean nothing.
  having count(distinct a.lead_id) >= 5
  on conflict do nothing;
  get diagnostics n_edges = row_count;

  -- How many companies sit in each category, on the node itself, so a reader never has to guess
  -- whether a big-looking category is big.
  update graph_nodes n
     set props = coalesce(n.props, '{}'::jsonb) || jsonb_build_object('companies', c.n),
         updated_at = now()
  from (select slug, count(distinct lead_id) n from lead_category group by 1) c
  where n.kind = 'category' and n.ref_id = c.slug;
  get diagnostics n_props = row_count;

  return jsonb_build_object('adjacency_edges', n_edges, 'categories_counted', n_props);
end $function$


CREATE OR REPLACE FUNCTION public.fn_group_dispatch_report(p_group_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_gd public.v_group_dispatch%rowtype; v_blockers jsonb := '[]'::jsonb; r record;
        v_active jsonb; v_out jsonb; v_opt jsonb; v_conf jsonb; v_comp jsonb; v_n_active int;
begin
  select * into v_gd from public.v_group_dispatch where group_id = p_group_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'unknown_group'); end if;

  select coalesce(jsonb_agg(jsonb_build_object('trade', trade_key, 'disposition', disposition)
                            order by trade_key), '[]'::jsonb), count(*)
    into v_active, v_n_active from public.v_trade_scope_status
   where group_id = p_group_id and coalesce(contributes,false) and coalesce(workstream_active,false);
  select coalesce(jsonb_agg(jsonb_build_object('trade', trade_key, 'disposition', disposition,
                                               'reason', reason) order by trade_key), '[]'::jsonb)
    into v_out from public.v_trade_scope_status
   where group_id = p_group_id and disposition in ('excluded','by_others','client_supplied');
  select coalesce(jsonb_agg(jsonb_build_object('trade', trade_key, 'disposition', disposition,
                                               'reason', reason) order by trade_key), '[]'::jsonb)
    into v_opt from public.v_trade_scope_status
   where group_id = p_group_id and disposition in ('optional','future_phase','proposed','unknown');
  select coalesce(jsonb_agg(jsonb_build_object('trade', trade_key, 'clauses', clause_indexes,
                                               'reason', reason) order by trade_key), '[]'::jsonb)
    into v_conf from public.v_trade_scope_status
   where group_id = p_group_id and coalesce(is_conflict,false);
  select coalesce(jsonb_agg(jsonb_build_object('trade', trade_key, 'component', scope_component,
                                               'disposition', disposition) order by trade_key, scope_component), '[]'::jsonb)
    into v_comp from public.v_scope_disposition_effective
   where group_id = p_group_id and scope_component <> 'complete_trade_scope' and disposition <> 'included';

  if v_n_active = 0 then
    if jsonb_array_length(v_conf) > 0 then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'blocker','scope_confirmation_required','severity','blocking','conflicts', v_conf,
        'detail','Contradictory scope statements of equal specificity. The customer must say which applies.',
        'remedy','Answer the open clarification.'));
    else
      v_blockers := v_blockers || jsonb_build_array(public.fn_p2c1_no_active_trade_blocker(v_out, v_opt));
    end if;
  elsif jsonb_array_length(v_conf) > 0 then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'blocker','scope_confirmation_required','severity','blocking','conflicts', v_conf,
      'detail','Some trades are active but an unresolved scope conflict remains.'));
  end if;

  if cardinality(v_gd.shared_missing_mandatory) > 0 then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'blocker','shared_mandatory_missing','severity','blocking',
      'fields', to_jsonb(v_gd.shared_missing_mandatory),
      'detail','Shared project fields required by an active workstream are unanswered.'));
  end if;
  if not v_gd.no_unresolved_shared_conflict then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'blocker','open_shared_conflict','severity','blocking',
      'fields', (select coalesce(jsonb_agg(c.field_id), '[]'::jsonb)
                   from public.inquiry_answer_conflict c
                   join public.field_definition fd on fd.field_id = c.field_id
                  where c.group_id = p_group_id and c.resolved_at is null and fd.scope = 'shared'),
      'detail','A shared field has sources that disagree. Every workstream is affected.'));
  end if;
  for r in select * from public.v_workstream_dispatch
            where group_id = p_group_id and active and not dispatch_eligible loop
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'blocker','trade_not_eligible','severity','blocking','trade_key', r.trade_key,
      'missing_mandatory', to_jsonb(r.missing_mandatory),
      'unresolved_conflicts', to_jsonb(r.blocked_by), 'gate_states', r.gate_states,
      'detail','This trade is not dispatch-eligible, so the group is not.'));
  end loop;
  for r in select gr.gate_key,
                  coalesce((select g.state::text from public.inquiry_gate g
                             where g.group_id = p_group_id and g.workstream_id is null
                               and g.gate_key = gr.gate_key), 'not_evaluated') as state
             from public.inquiry_gate_required gr where gr.level = 'group' loop
    if r.state not in ('passed','not_applicable') then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'blocker','group_gate_not_satisfied','severity','blocking','gate_key', r.gate_key,
        'state', r.state,
        'detail', case when r.state = 'not_evaluated'
                       then 'This gate has never been evaluated. Absent reads as failed.'
                       else 'Gate state is ' || r.state || '.' end));
    end if;
  end loop;
  if jsonb_array_length(v_comp) > 0 then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'blocker','component_scope_restriction','severity','informational','restrictions', v_comp,
      'detail','Parts of an active trade are out of scope. The trade still dispatches; the RFQ must carry the restriction.'));
  end if;
  for r in select trade_key, evidence_score, score_basis, evidence_source
             from public.inquiry_trade_candidate
            where group_id = p_group_id and status = 'proposed' loop
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'blocker','trade_awaiting_confirmation','severity','informational','trade_key', r.trade_key,
      'evidence_source', r.evidence_source, 'evidence_score', r.evidence_score,
      'score_basis', r.score_basis,
      'detail','Proposed but not confirmed. It contributes nothing to dispatch until a person confirms it.'));
  end loop;
  if exists (select 1 from public.inquiry_trade_clarification
              where group_id = p_group_id and answered_at is null) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'blocker','open_clarification','severity','blocking',
      'question', (select question_en from public.inquiry_trade_clarification
                    where group_id = p_group_id and answered_at is null limit 1),
      'detail','The customer has been asked to settle the scope.'));
  end if;

  return jsonb_build_object(
    'ok', true, 'group_id', p_group_id,
    'overall_dispatch_eligible', (v_gd.overall_dispatch_eligible and v_n_active > 0
                                  and jsonb_array_length(v_conf) = 0),
    'active_included_trades', v_active, 'excluded_or_by_others_trades', v_out,
    'optional_or_future_trades', v_opt, 'unresolved_scope_conflicts', v_conf,
    'component_scope_restrictions', v_comp,
    'active_workstreams', v_gd.active_workstreams, 'shared_complete', v_gd.shared_complete,
    'group_gate_states', v_gd.gate_states, 'blocking_trades', to_jsonb(v_gd.blocking_trades),
    'blockers', v_blockers, 'blocker_count', jsonb_array_length(v_blockers));
end $function$


CREATE OR REPLACE FUNCTION public.fn_handoff_amend(p_id bigint, p_agent_key text, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c          handoff_contract%rowtype;
  v_evidence jsonb;
  v_accept   text[];
  v_deadline timestamptz;
  v_owner    text;
  v_gaps     text[] := '{}';
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  select * into c from handoff_contract where id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no handoff contract with that id');
  end if;
  if c.status = 'closed' then
    return jsonb_build_object('ok', false, 'reason', 'a closed handoff cannot be amended');
  end if;
  if not exists (select 1 from org_agents
                  where agent_key = p_agent_key and active and department = c.from_dept) then
    return jsonb_build_object('ok', false, 'reason', 'only an active employee of the originating department may amend',
                              'from_dept', c.from_dept);
  end if;

  v_evidence := case when jsonb_typeof(p_patch->'evidence') = 'array' then p_patch->'evidence' else c.evidence end;
  v_accept   := case when jsonb_typeof(p_patch->'acceptance_criteria') = 'array'
                     then public.fn_handoff_criteria(p_patch->'acceptance_criteria') else c.acceptance_criteria end;
  v_owner    := coalesce(nullif(btrim(p_patch->>'accountable_owner'), ''), p_agent_key);
  begin v_deadline := coalesce((p_patch->>'deadline')::timestamptz, c.deadline);
  exception when others then v_deadline := c.deadline; end;

  update handoff_contract
     set evidence = v_evidence,
         acceptance_criteria = v_accept,
         deadline = v_deadline,
         accountable_owner = v_owner,          -- guard refuses a blank, a stranger or an ex-employee
         status = case when c.status in ('rejected','returned') then 'open' else c.status end,
         return_status = case when c.status in ('rejected','returned') then null else c.return_status end,
         return_reason = case when c.status in ('rejected','returned') then null else c.return_reason end
   where id = p_id;

  -- Back into the receiver's inbox if the rejection had taken it out.
  update agent_actions
     set status = 'needs_review', decided_at = null, decided_by = null,
         detail = coalesce(detail, '{}'::jsonb) || jsonb_build_object('amended_at', now(), 'amended_by', p_agent_key)
   where id = c.action_id and c.status in ('rejected','returned');

  if jsonb_array_length(v_evidence) = 0 then v_gaps := v_gaps || 'evidence'::text; end if;
  if cardinality(v_accept) = 0 then v_gaps := v_gaps || 'acceptance_criteria'::text; end if;

  return jsonb_build_object('ok', true, 'id', p_id,
    'status', case when c.status in ('rejected','returned') then 'open' else c.status end,
    'accountable_owner', v_owner, 'owner_changed', v_owner is distinct from c.accountable_owner,
    'complete', array_length(v_gaps, 1) is null, 'missing_for_acceptance', to_jsonb(v_gaps));
end $function$


CREATE OR REPLACE FUNCTION public.fn_handoff_answer(p_id bigint, p_agent_key text, p_answer text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_asker text;
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  if coalesce(btrim(p_answer),'') = '' then
    return jsonb_build_object('ok', false, 'reason', 'empty answer');
  end if;
  select * into r from agent_actions
   where id = p_id and agent = p_agent_key
     and status in ('pending','needs_review');
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no open item with that id for this agent');
  end if;

  -- The refusal that keeps this honest. An employee may finish the company's own work; it may not
  -- close a legal flag, a security incident, a customer escalation, a compliance update, a money
  -- item or a prompt approval by writing a paragraph about it.
  if not (r.kind = any(fn_agent_inbox_closable_kinds())) then
    return jsonb_build_object('ok', false, 'kind', r.kind,
      'reason', 'items of kind '||r.kind||' are decided by the founder, not closed by an employee');
  end if;

  update agent_actions
     set status = 'done', decided_at = now(), decided_by = p_agent_key,
         detail = coalesce(detail,'{}'::jsonb)
                  || jsonb_build_object('answer', left(p_answer, 4000), 'answered_at', now())
   where id = p_id;

  -- Only a handoff has an asker waiting on a reply. Self-raised work has nobody to notify, and
  -- the existing guard already handles that rather than inventing a recipient.
  v_asker := coalesce(r.detail->>'from', '');
  if v_asker <> '' and exists (select 1 from org_agents o where o.agent_key = v_asker) then
    insert into agent_memory (agent_key, kind, content, source, importance)
    values (v_asker, 'learned',
            'Answer to the '||r.kind||' you raised — "'||coalesce(r.title,'(untitled)')||'": '
              ||left(p_answer, 1200),
            r.kind||':'||p_id, 4);
  end if;

  return jsonb_build_object('ok', true, 'id', p_id, 'kind', r.kind, 'asker_notified', v_asker <> '');
end $function$


CREATE OR REPLACE FUNCTION public.fn_handoff_close(p_id bigint, p_agent_key text, p_closure_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c         handoff_contract%rowtype;
  v_ev      jsonb := case when jsonb_typeof(p_closure_evidence) = 'array' then p_closure_evidence else '[]'::jsonb end;
  v_missing text[];
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  select * into c from handoff_contract where id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no handoff contract with that id');
  end if;
  if c.status <> 'accepted' then
    return jsonb_build_object('ok', false, 'reason', 'only an accepted handoff can be closed', 'status', c.status);
  end if;
  if not exists (select 1 from org_agents
                  where agent_key = p_agent_key and active and department = c.to_dept) then
    return jsonb_build_object('ok', false, 'reason', 'only an active employee of the receiving department may close it',
                              'to_dept', c.to_dept);
  end if;

  select coalesce(array_agg(x), '{}'::text[]) into v_missing
    from unnest(c.closure_criteria) x
   where not exists (
     select 1 from jsonb_array_elements(v_ev) e
      where btrim(coalesce(e->>'criterion', '')) = btrim(x)
        and coalesce(btrim(e->>'evidence'), '') <> '');
  if array_length(v_missing, 1) is not null then
    return jsonb_build_object('ok', false, 'reason', 'closure criteria without recorded proof',
      'unproven', to_jsonb(v_missing), 'declared', to_jsonb(c.closure_criteria));
  end if;

  update handoff_contract
     set status = 'closed', return_status = 'closed', closure_evidence = v_ev,
         closed_by = p_agent_key, closed_at = now()
   where id = p_id;

  update agent_actions
     set status = 'done', decided_at = now(), decided_by = p_agent_key,
         detail = coalesce(detail, '{}'::jsonb)
                  || jsonb_build_object('outcome', 'closed', 'closure_evidence', v_ev, 'closed_at', now())
   where id = c.action_id;

  perform public.fn_handoff_notify(c.accountable_owner,
    'Handoff #'||p_id||' ("'||c.purpose||'") was CLOSED by '||p_agent_key||' ('||c.to_dept||'). '
    ||'Proof recorded for '||cardinality(c.closure_criteria)||' closure criteria: '||v_ev::text,
    'handoff_contract:'||p_id);

  return jsonb_build_object('ok', true, 'id', p_id, 'status', 'closed', 'closed_by', p_agent_key,
    'criteria_proven', cardinality(c.closure_criteria), 'closure_evidence', v_ev);
end $function$


CREATE OR REPLACE FUNCTION public.fn_handoff_contract_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_check_owner boolean := false;
  v_owner       record;
  v_missing     text;
begin
  new.updated_at := now();

  -- (a) THE OWNER CANNOT BE LOST. NOT NULL stops the null; this stops the blank, the stranger,
  --     the deactivated replacement, and the owner who does not belong to the sending department.
  if coalesce(btrim(new.accountable_owner), '') = '' then
    raise exception 'handoff %: accountable_owner cannot be blank', coalesce(new.id, 0);
  end if;
  if tg_op = 'INSERT' then
    v_check_owner := true;
  elsif new.accountable_owner is distinct from old.accountable_owner then
    v_check_owner := true;
  end if;
  if v_check_owner then
    select agent_key, department, active into v_owner
      from org_agents where agent_key = new.accountable_owner;
    if not found then
      raise exception 'handoff %: accountable_owner % is not on the roster',
        coalesce(new.id, 0), new.accountable_owner;
    end if;
    if not v_owner.active then
      raise exception 'handoff %: accountable_owner % is not an active employee',
        coalesce(new.id, 0), new.accountable_owner;
    end if;
    if v_owner.department is distinct from new.from_dept then
      raise exception 'handoff %: accountable_owner % belongs to %, not the originating department %',
        coalesce(new.id, 0), new.accountable_owner, coalesce(v_owner.department, '(none)'), new.from_dept;
    end if;
  end if;

  -- (b) THE LIFECYCLE. open -> accepted|rejected; accepted -> returned|closed;
  --     rejected|returned -> open (the sender corrected it). closed is terminal.
  if tg_op = 'UPDATE' and new.status is distinct from old.status then
    if old.status = 'closed' then
      raise exception 'handoff %: closed is terminal, cannot move to %', new.id, new.status;
    end if;
    if not ((old.status = 'open'     and new.status in ('accepted','rejected'))
         or (old.status = 'accepted' and new.status in ('returned','closed'))
         or (old.status in ('rejected','returned') and new.status = 'open')) then
      raise exception 'handoff %: illegal transition % -> %', new.id, old.status, new.status;
    end if;
  end if;

  -- (c) CLOSURE NEEDS PROOF, PER CRITERION. This is CMP-HO-05 made unavoidable: a closure with a
  --     criterion nobody evidenced is refused, and the message names which criterion.
  if new.status = 'closed' then
    if new.closed_by is null or new.closed_at is null then
      raise exception 'handoff %: a closure must record who closed it and when', new.id;
    end if;
    select string_agg(c, '; ') into v_missing
      from unnest(new.closure_criteria) c
     where not exists (
       select 1 from jsonb_array_elements(coalesce(new.closure_evidence, '[]'::jsonb)) e
        where btrim(coalesce(e->>'criterion', '')) = btrim(c)
          and coalesce(btrim(e->>'evidence'), '') <> '');
    if v_missing is not null then
      raise exception 'handoff %: cannot close, no recorded proof for closure criteria: %',
        new.id, v_missing;
    end if;
  end if;

  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_handoff_criteria(p jsonb)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select coalesce(array_agg(btrim(x)) filter (where btrim(x) <> ''), '{}'::text[])
    from jsonb_array_elements_text(
           case when jsonb_typeof(p) = 'array' then p else '[]'::jsonb end) x;
$function$


CREATE OR REPLACE FUNCTION public.fn_handoff_notify(p_agent_key text, p_content text, p_source text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  if coalesce(btrim(p_agent_key), '') = ''
     or not exists (select 1 from org_agents where agent_key = p_agent_key) then
    return false;
  end if;
  insert into agent_memory (agent_key, kind, content, source, importance)
  values (p_agent_key, 'learned', left(p_content, 2000), p_source, 4);
  return true;
end $function$


CREATE OR REPLACE FUNCTION public.fn_handoff_open(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_from     text := btrim(coalesce(p->>'from_dept', ''));
  v_owner    text := btrim(coalesce(p->>'accountable_owner', ''));
  v_to       text := btrim(coalesce(p->>'to_dept', ''));
  v_role     text := btrim(coalesce(p->>'to_role', ''));
  v_purpose  text := btrim(coalesce(p->>'purpose', ''));
  v_act      text := btrim(coalesce(p->>'requested_action', ''));
  v_escal    text := btrim(coalesce(p->>'escalation_conditions', ''));
  v_evidence jsonb := case when jsonb_typeof(p->'evidence') = 'array' then p->'evidence' else '[]'::jsonb end;
  v_accept   text[] := public.fn_handoff_criteria(p->'acceptance_criteria');
  v_closure  text[] := public.fn_handoff_criteria(p->'closure_criteria');
  v_deadline timestamptz;
  v_missing  text[] := '{}';
  v_gaps     text[] := '{}';
  v_idem     text;
  v_recv     text;
  v_ownrec   record;
  v_action   bigint;
  v_id       bigint;
  v_dupe     bigint;
begin
  begin v_deadline := (p->>'deadline')::timestamptz; exception when others then v_deadline := null; end;

  if v_from    = '' then v_missing := v_missing || 'from_dept'::text;             end if;
  if v_owner   = '' then v_missing := v_missing || 'accountable_owner'::text;     end if;
  if v_to      = '' then v_missing := v_missing || 'to_dept'::text;               end if;
  if v_role    = '' then v_missing := v_missing || 'to_role'::text;               end if;
  if length(v_purpose) < 10 then v_missing := v_missing || 'purpose'::text;       end if;
  if length(v_act) < 10 then v_missing := v_missing || 'requested_action'::text;  end if;
  if v_escal   = '' then v_missing := v_missing || 'escalation_conditions'::text; end if;
  if v_deadline is null then v_missing := v_missing || 'deadline'::text;          end if;
  if cardinality(v_closure) = 0 then v_missing := v_missing || 'closure_criteria'::text; end if;
  if array_length(v_missing, 1) is not null then
    return jsonb_build_object('ok', false, 'reason', 'the handoff contract is not complete enough to open',
                              'missing', to_jsonb(v_missing));
  end if;
  if v_deadline <= now() then
    return jsonb_build_object('ok', false, 'reason', 'deadline is already in the past', 'deadline', v_deadline);
  end if;

  if not exists (select 1 from org_departments where dept_key = v_from) then
    return jsonb_build_object('ok', false, 'reason', 'unknown originating department', 'from_dept', v_from);
  end if;
  if not exists (select 1 from org_departments where dept_key = v_to) then
    return jsonb_build_object('ok', false, 'reason', 'unknown receiving department', 'to_dept', v_to);
  end if;
  select agent_key, department, active into v_ownrec from org_agents where agent_key = v_owner;
  if not found or not v_ownrec.active then
    return jsonb_build_object('ok', false, 'reason', 'accountable owner is not an active employee',
                              'accountable_owner', v_owner);
  end if;
  if v_ownrec.department is distinct from v_from then
    return jsonb_build_object('ok', false, 'reason', 'accountable owner does not belong to the originating department',
                              'accountable_owner', v_owner, 'owner_department', v_ownrec.department, 'from_dept', v_from);
  end if;

  -- REPLAY / DUPLICATE STATE. Same sender, same receiver, same ask = the same handoff.
  v_idem := coalesce(nullif(btrim(p->>'idempotency_key'), ''),
                     md5(v_from||'>'||v_to||'|'||lower(v_role)||'|'||lower(v_purpose)||'|'||lower(v_act)));
  select id into v_dupe from handoff_contract
   where idempotency_key = v_idem and status in ('open','accepted','returned') limit 1;
  if v_dupe is not null then
    return jsonb_build_object('ok', true, 'duplicate', true, 'id', v_dupe,
      'note', 'an identical handoff is already live; returning it rather than opening a second');
  end if;

  -- WHO ACTUALLY RECEIVES IT. The named role first, then a role that contains the name, then the
  -- department lead. A handoff addressed to a department with nobody in it is refused, not queued.
  select a.agent_key into v_recv
    from org_agents a
    left join org_departments d on d.dept_key = a.department
   where a.department = v_to and a.active
   order by (lower(a.role) = lower(v_role)) desc,
            (position(lower(v_role) in lower(coalesce(a.role,''))) > 0) desc,
            coalesce(a.available, true) desc,
            (a.agent_key = d.lead_agent) desc,
            a.agent_key
   limit 1;
  if v_recv is null then
    return jsonb_build_object('ok', false, 'reason', 'receiving department has no active employee to accept it',
                              'to_dept', v_to);
  end if;

  -- The transport row: this is what fn_agent_handoff_inbox already reads. Unchanged shape.
  insert into agent_actions (agent, kind, status, risk, title, recommendation, detail, target_table)
  values (v_recv, 'handoff', 'needs_review', 'medium',
          'Handoff — '||left(v_purpose, 160), left(v_act, 500),
          jsonb_build_object(
            'from', v_owner, 'from_name', v_owner, 'from_dept', v_from,
            'to_dept', v_to, 'to_role', v_role, 'deadline', v_deadline,
            'acceptance_criteria', to_jsonb(v_accept), 'closure_criteria', to_jsonb(v_closure),
            'escalation_conditions', v_escal, 'requested_at', now(), 'contract', true),
          'handoff_contract')
  returning id into v_action;

  insert into handoff_contract (action_id, idempotency_key, from_dept, accountable_owner, to_dept,
                                to_role, purpose, evidence, requested_action, deadline,
                                acceptance_criteria, closure_criteria, escalation_conditions)
  values (v_action, v_idem, v_from, v_owner, v_to, v_role, v_purpose, v_evidence, v_act, v_deadline,
          v_accept, v_closure, v_escal)
  returning id into v_id;

  update agent_actions set target_id = v_id::text where id = v_action;

  if jsonb_array_length(v_evidence) = 0 then v_gaps := v_gaps || 'evidence'::text; end if;
  if cardinality(v_accept) = 0 then v_gaps := v_gaps || 'acceptance_criteria'::text; end if;

  return jsonb_build_object('ok', true, 'id', v_id, 'action_id', v_action,
    'receiving_agent', v_recv, 'idempotency_key', v_idem,
    'complete', array_length(v_gaps, 1) is null,
    'rejectable_on_arrival', array_length(v_gaps, 1) is not null,
    'missing_for_acceptance', to_jsonb(v_gaps));
end $function$


CREATE OR REPLACE FUNCTION public.fn_handoff_respond(p_id bigint, p_agent_key text, p_decision text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c        handoff_contract%rowtype;
  v_dec    text := lower(btrim(coalesce(p_decision, '')));
  v_reason text := btrim(coalesce(p_reason, ''));
  v_gaps   text[] := '{}';
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  if v_dec not in ('accept','reject','return') then
    return jsonb_build_object('ok', false, 'reason', 'decision must be accept, reject or return');
  end if;
  select * into c from handoff_contract where id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no handoff contract with that id');
  end if;
  if not exists (select 1 from org_agents
                  where agent_key = p_agent_key and active and department = c.to_dept) then
    return jsonb_build_object('ok', false, 'reason', 'only an active employee of the receiving department may answer',
                              'to_dept', c.to_dept);
  end if;

  if jsonb_array_length(c.evidence) = 0 then v_gaps := v_gaps || 'evidence'::text; end if;
  if cardinality(c.acceptance_criteria) = 0 then v_gaps := v_gaps || 'acceptance_criteria'::text; end if;

  if v_dec = 'accept' then
    if c.status <> 'open' then
      return jsonb_build_object('ok', false, 'reason', 'only an open handoff can be accepted', 'status', c.status);
    end if;
    -- REJECTABLE ON ARRIVAL: an incomplete handoff cannot be silently taken on.
    if array_length(v_gaps, 1) is not null then
      return jsonb_build_object('ok', false, 'reason', 'handoff is incomplete and cannot be accepted',
        'missing', to_jsonb(v_gaps), 'next', 'reject it with a reason, or ask the sender to amend it');
    end if;
    update handoff_contract
       set status = 'accepted', return_status = 'accepted',
           accepted_by = p_agent_key, accepted_at = now(), return_reason = nullif(v_reason, '')
     where id = p_id;
    perform public.fn_handoff_notify(c.accountable_owner,
      'Handoff #'||p_id||' ("'||c.purpose||'") was ACCEPTED by '||p_agent_key||' ('||c.to_dept||'). '
      ||'Due '||to_char(c.deadline, 'YYYY-MM-DD HH24:MI')||'. Closure criteria: '
      ||array_to_string(c.closure_criteria, ' | '),
      'handoff_contract:'||p_id);
    return jsonb_build_object('ok', true, 'id', p_id, 'status', 'accepted',
      'accepted_by', p_agent_key, 'deadline', c.deadline,
      'acceptance_criteria', to_jsonb(c.acceptance_criteria),
      'closure_criteria', to_jsonb(c.closure_criteria));
  end if;

  if v_reason = '' then
    return jsonb_build_object('ok', false, 'reason', 'a '||v_dec||' must state why');
  end if;

  if v_dec = 'reject' then
    if c.status <> 'open' then
      return jsonb_build_object('ok', false, 'reason', 'only an open handoff can be rejected', 'status', c.status);
    end if;
    update handoff_contract
       set status = 'rejected',
           return_status = case when array_length(v_gaps, 1) is not null
                                then 'rejected_incomplete' else 'rejected' end,
           return_reason = v_reason
     where id = p_id;
    -- The transport row leaves the receiver's inbox; the sender is told, in their own memory.
    update agent_actions
       set status = 'done', decided_at = now(), decided_by = p_agent_key,
           detail = coalesce(detail, '{}'::jsonb)
                    || jsonb_build_object('outcome', 'rejected', 'reason', left(v_reason, 1000),
                                          'missing', to_jsonb(v_gaps), 'rejected_at', now())
     where id = c.action_id;
    perform public.fn_handoff_notify(c.accountable_owner,
      'Handoff #'||p_id||' ("'||c.purpose||'") was REJECTED by '||p_agent_key||' ('||c.to_dept||'): '
      ||v_reason||case when array_length(v_gaps, 1) is not null
                       then '. Missing: '||array_to_string(v_gaps, ', ')||'. Amend and resubmit with fn_handoff_amend.'
                       else '' end,
      'handoff_contract:'||p_id);
    return jsonb_build_object('ok', true, 'id', p_id, 'status', 'rejected',
      'return_status', case when array_length(v_gaps, 1) is not null then 'rejected_incomplete' else 'rejected' end,
      'missing', to_jsonb(v_gaps), 'sender_notified', c.accountable_owner);
  end if;

  -- return: the receiver took it on, then found it cannot be finished as handed over.
  if c.status <> 'accepted' then
    return jsonb_build_object('ok', false, 'reason', 'only an accepted handoff can be returned for correction',
                              'status', c.status);
  end if;
  update handoff_contract
     set status = 'returned', return_status = 'returned_for_correction',
         return_reason = v_reason, returns_count = returns_count + 1
   where id = p_id;
  perform public.fn_handoff_notify(c.accountable_owner,
    'Handoff #'||p_id||' ("'||c.purpose||'") was RETURNED FOR CORRECTION by '||p_agent_key||': '||v_reason
    ||' Correct it with fn_handoff_amend; it goes back to '||c.to_dept||' as open.',
    'handoff_contract:'||p_id);
  return jsonb_build_object('ok', true, 'id', p_id, 'status', 'returned',
    'return_status', 'returned_for_correction', 'returns_count', c.returns_count + 1,
    'sender_notified', c.accountable_owner);
end $function$


CREATE OR REPLACE FUNCTION public.fn_handoff_stalled(p_dept text DEFAULT NULL::text, p_limit integer DEFAULT 50)
 RETURNS SETOF v_handoff_stalled
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select * from public.v_handoff_stalled s
   where p_dept is null or s.from_dept = p_dept or s.to_dept = p_dept
   order by s.days_past_deadline desc, s.deadline
   limit greatest(1, coalesce(p_limit, 50));
$function$


CREATE OR REPLACE FUNCTION public.fn_health_index()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  s_acq numeric; s_supp numeric; s_rfq numeric; s_qual numeric;
  s_resp numeric; s_disp numeric; s_up numeric;
  signups_7d int; quotes_7d int; approved_suppliers int;
  inq_total int; inq_done int; avg_qual numeric; avg_resp numeric;
  blocked_30d int; msgs_30d int; up_ok int; up_tot int;
  parts numeric[]; overall numeric; band text; present int;
begin
  select count(*) into signups_7d from customers where created_at > now()-interval '7 days';
  select count(*) into quotes_7d  from quotes    where created_at > now()-interval '7 days';
  -- DEMO FIXTURES EXCLUDED. The marker is in the data, not the schema: the convention seeded on
  -- 7-8 Aug 2026 is 'ZZ DEMO ' in company_name and an @example.invalid address. Both are checked
  -- because either alone would let a half-formed fixture through.
  select count(*) into approved_suppliers from leads
     where (coalesce(approval_status,'')='approved' or claimed=true)
       and coalesce(company_name,'') not like 'ZZ DEMO%'
       and coalesce(email,'') not like '%@example.invalid';
  -- RFQ completion: real RFQs only (exclude split-parent containers and customer-cancelled),
  -- success = completed/won or closed-with-a-hire (a "closed, not hired" is NOT a completion).
  select count(*) filter (where created_at > now()-interval '90 days'
                            and coalesce(status,'')<>'split' and coalesce(category,'')<>'combined'
                            and coalesce(status,'')<>'cancelled'),
         count(*) filter (where created_at > now()-interval '90 days'
                            and coalesce(status,'')<>'split' and coalesce(category,'')<>'combined'
                            and (status in ('completed','won')
                                 or (status='closed' and coalesce(outcome,'') in ('hired','hired_elsewhere'))))
    into inq_total, inq_done from inquiries;
  select avg(nullif(quality->>'score','')::numeric) into avg_qual
    from quotes where quality is not null and created_at > now()-interval '90 days';
  select avg(nullif(rv_response_rate,0)) into avg_resp
    from leads where coalesce(rv_reveals,0) > 0;
  select count(*) filter (where coalesce(blocked,false)),
         count(*) into blocked_30d, msgs_30d
    from messages where created_at > now()-interval '30 days';
  select count(*) filter (where ok), count(*) into up_ok, up_tot
    from health_checks where created_at > now()-interval '24 hours';

  s_acq  := least(100, signups_7d * 10.0);
  s_supp := case when approved_suppliers=0 and quotes_7d=0 then null
                 else least(100, quotes_7d * 5.0) end;
  s_rfq  := case when inq_total=0 then null else round(inq_done::numeric/inq_total*100,1) end;
  s_qual := avg_qual;
  s_resp := case when avg_resp is null then null
                 when avg_resp <= 1 then round(avg_resp*100,1) else round(avg_resp,1) end;
  s_disp := case when msgs_30d=0 then null
                 else greatest(0, 100 - least(100, blocked_30d*5.0)) end;
  s_up   := case when up_tot=0 then null else round(up_ok::numeric/up_tot*100,1) end;

  parts := array_remove(array[s_acq,s_supp,s_rfq,s_qual,s_resp,s_disp,s_up], null);
  present := coalesce(array_length(parts,1),0);
  overall := case when present=0 then null else round((select avg(x) from unnest(parts) x),1) end;
  band := case when overall is null then 'no data'
               when overall >= 75 then 'healthy'
               when overall >= 50 then 'watch'
               else 'attention' end;

  return jsonb_build_object(
    'index', overall, 'band', band, 'components_present', present,
    -- A PROSE INSIGHT WITH A CAUSE AND A MAGNITUDE, not a blank.
    -- `overall` is the mean of the present components, so the ones furthest below it are
    -- arithmetically what hold the index there. "driven by" is division, not narrative.
    'note', case
      when present < 3 then 'insufficient data - pre-traction; index will firm up with volume'
      else (select 'Company health is '||overall||' of 100 ('||band||'), driven by '
              ||string_agg(w.label||' at '||w.score, ' and ' order by w.score, w.label)
              ||' - the two furthest below the '||overall||'-point average of '||present
              ||' measured components.'
              from (select v.label, v.score from (values
                      ('customer acquisition', s_acq), ('supplier activity', s_supp),
                      ('RFQ completion', s_rfq), ('quote quality', s_qual),
                      ('response time', s_resp), ('dispute health', s_disp), ('uptime', s_up)
                    ) v(label, score)
                     where v.score is not null order by v.score, v.label limit 2) w)
      end,
    'components', jsonb_build_object(
       'customer_acquisition', s_acq, 'supplier_activity', s_supp, 'rfq_completion', s_rfq,
       'quote_quality', s_qual, 'response_time', s_resp, 'dispute_health', s_disp,
       'uptime', s_up, 'revenue', null),
    'raw', jsonb_build_object(
       'signups_7d', signups_7d, 'quotes_7d', quotes_7d, 'approved_suppliers', approved_suppliers,
       'inquiries_eligible_90d', inq_total, 'completed_90d', inq_done,
       'blocked_msgs_30d', blocked_30d, 'uptime_ok', up_ok, 'uptime_checks', up_tot),
    'computed_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_idea_rescore()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.score := public.fn_idea_score(new.expected_value_aed, new.effort, new.confidence);
  new.updated_at := now();
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_idea_score(p_value numeric, p_effort text, p_confidence numeric)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select round(
    coalesce(p_value,0)
    * coalesce(p_confidence,0.5)
    / case lower(coalesce(p_effort,'m'))
        when 's' then 1 when 'small' then 1
        when 'm' then 3 when 'medium' then 3
        when 'l' then 8 when 'large' then 8
        when 'xl' then 20 else 3 end
  , 2);
$function$


CREATE OR REPLACE FUNCTION public.fn_identify_contact(p_phone text)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_d text; v_tail text; v_name text; v_sid bigint; v_cid text; v_claimed boolean; v_appr boolean;
begin
  v_d := regexp_replace(coalesce(p_phone,''), '[^0-9]', '', 'g');
  if length(v_d) < 7 then return json_build_object('audience','unknown'); end if;
  v_tail := right(v_d, 9);   -- tolerate +9715..., 05..., 5... variants

  -- THE FOUNDER. Before suppliers and customers: he is neither, and a number that is both his and
  -- a lead's must still be treated as his.
  if exists (
    select 1 from unnest(string_to_array(coalesce((select value from app_secrets where key='admin_mfa_phone'),''), ',')) p
     where length(regexp_replace(p,'[^0-9]','','g')) >= 9
       and right(regexp_replace(p,'[^0-9]','','g'), 9) = v_tail)
  then
    return json_build_object('audience','founder',
      'name', split_part(coalesce((select value from app_secrets where key='admin_emails'),''), ',', 1));
  end if;

  select id, company_name, coalesce(claimed,false), (approval_status='approved')
    into v_sid, v_name, v_claimed, v_appr
   from leads
   where right(regexp_replace(coalesce(phone_e164,''),'[^0-9]','','g'),9) = v_tail
      or right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),9) = v_tail
      or right(regexp_replace(coalesce(whatsapp,''),'[^0-9]','','g'),9) = v_tail
   limit 1;
  if v_sid is not null then
    return json_build_object('audience','supplier','name',v_name,'claimed',v_claimed,'approved',coalesce(v_appr,false));
  end if;

  select id::text, full_name into v_cid, v_name from customers
   where right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),9) = v_tail
   limit 1;
  if v_cid is not null then
    return json_build_object('audience','customer','name',v_name);
  end if;

  return json_build_object('audience','unknown');
end $function$


CREATE OR REPLACE FUNCTION public.fn_improvement_handover(p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r          record;
  v_to       text;
  v_sent     int := 0;
  v_unstaffed int := 0;
  v_already  int := 0;
  v_sample   jsonb := '[]'::jsonb;
begin
  for r in
    select t.id, t.dept_key, t.title, t.detail, t.status, t.created_at
      from org_tasks t
     where t.title like '% improvement: %'
       and t.created_at > now() - interval '90 days'
     order by t.id
     limit greatest(coalesce(p_limit, 200), 1)
  loop
    if exists (select 1 from agent_actions a
                where a.kind = 'improvement_question'
                  and a.target_table = 'org_tasks' and a.target_id = r.id::text) then
      v_already := v_already + 1;
      continue;
    end if;

    -- The department's own head, then its lead, then any active member. Validated ACTIVE at each
    -- step: org_departments.brain_agent still names 'onboarding' for supplier_success, a department
    -- with zero employees, so an unvalidated coalesce would address the question to a vacant desk.
    select coalesce(
             (select d.brain_agent from org_departments d where d.dept_key = r.dept_key
               and exists (select 1 from org_agents a where a.agent_key = d.brain_agent and a.active)),
             (select d.lead_agent  from org_departments d where d.dept_key = r.dept_key
               and exists (select 1 from org_agents a where a.agent_key = d.lead_agent and a.active)),
             (select a.agent_key from org_agents a
               where a.active and a.department = r.dept_key order by a.agent_key limit 1))
      into v_to;

    if v_to is null then
      v_unstaffed := v_unstaffed + 1;
      continue;
    end if;

    insert into agent_actions (agent, kind, status, risk, title, recommendation, detail,
                               target_table, target_id, escalated)
    values (v_to, 'improvement_question', 'needs_review', 'low',
            left(r.title, 200),
            coalesce(nullif(r.detail, ''), r.title)
              || E'\n\nThis is one of the five weekly improvement questions your Operating System '
              || 'raised for ' || r.dept_key || '. Answer it, or say why it does not apply.',
            jsonb_build_object('org_task_id', r.id, 'dept_key', r.dept_key,
                               'raised_at', r.created_at, 'task_status', r.status,
                               'source', 'fn_improvement_handover'),
            'org_tasks', r.id::text, false);

    v_sent := v_sent + 1;
    if jsonb_array_length(v_sample) < 10 then
      v_sample := v_sample || jsonb_build_array(jsonb_build_object('task', r.id, 'to', v_to,
                                                                   'dept', r.dept_key));
    end if;
  end loop;

  return jsonb_build_object('delivered', v_sent, 'already_delivered', v_already,
                            'no_active_employee', v_unstaffed, 'sample', v_sample);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_improvement_plan_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  a record; v_parts text[]; v_line text; v_plan text;
  v_written int := 0; v_cleared int := 0;
begin
  for a in select agent_key, department from org_agents where active loop
    v_parts := array[]::text[];

    -- 1. What this department's work has been returned for, most recent first.
    select 'Your department has had ' || count(*) || ' deliverable(s) returned by review recently. '
        || 'The reasons on record: ' || string_agg(distinct left(m.detail, 120), '; ')
      into v_line
      from institutional_memory m
     where m.subject_type = 'org_task' and m.outcome = 'worse'
       and a.department = any(coalesce(m.visible_to, array[]::text[]))
       and m.created_at > now() - interval '30 days';
    if v_line is not null and v_line not like '%has had 0 %' then
      v_parts := v_parts || v_line;
    end if;

    -- 2. KPIs this employee owns that are behind. Their own targets, not the department's.
    select 'You own ' || count(*) || ' KPI(s) with a target you are not currently meeting: '
        || string_agg(k.kpi || ' (target ' || coalesce(k.target_value::text,'?') || ' ' || coalesce(k.unit,'') || ')', '; ')
      into v_line
      from employee_kpi k
     where k.agent_key = a.agent_key and k.active
       and exists (select 1 from goal_period g
                    where g.goal_key = k.serves_goal
                      and g.status in ('at_risk','missed','behind'));
    if v_line is not null and v_line not like '%own 0 KPI%' then
      v_parts := v_parts || v_line;
    end if;

    -- 3. Root causes already diagnosed against KPI misses in this department.
    select 'Root cause(s) already recorded against KPI misses in your department: '
        || string_agg(left(t.root_cause, 180), ' | ')
      into v_line
      from (select o.root_cause, o.updated_at
              from org_tasks o
             where o.dept_key = a.department
               and o.title ilike 'KPI missed%'
               and coalesce(o.root_cause, '') <> ''
             order by o.updated_at desc
             limit 2) t;
    if v_line is not null then v_parts := v_parts || v_line; end if;

    -- 4. Open findings the organisation has already recorded against this department.
    select 'Open findings against your department: ' || string_agg(left(s.finding, 110), '; ')
      into v_line
      from (select finding from self_review
             where coalesce(status,'open') not in ('done','implemented','rejected')
             order by created_at desc limit 2) s;
    if v_line is not null then v_parts := v_parts || v_line; end if;

    v_plan := nullif(array_to_string(v_parts, ' '), '');

    -- NULL when there is nothing on record. An empty plan is honest; a generic one is noise that
    -- would reach 66 prompts and mean nothing in any of them.
    update org_agents set improvement_plan = left(v_plan, 900) where agent_key = a.agent_key;
    if v_plan is null then v_cleared := v_cleared + 1; else v_written := v_written + 1; end if;
  end loop;

  return jsonb_build_object('agents', v_written + v_cleared,
                            'with_a_plan', v_written, 'nothing_on_record', v_cleared);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_inbox_list()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'needs_review', (select count(*) from public.inbound_messages where needs_review=true and replied_at is null
                        and created_at >= public.fn_os_fresh_start_at()),
      'untriaged', (select count(*) from public.inbound_messages where needs_review=true and triaged_at is null and replied_at is null
                     and created_at >= public.fn_os_fresh_start_at()),
      'replied_7d', (select count(*) from public.inbound_messages where replied_at > now()-interval '7 days')),
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
        'id',id,'from_email',from_email,'subject',subject,'body',left(coalesce(body,''),1200),
        'category',ai_category,'summary',ai_summary,'draft',ai_draft_reply,
        'triaged_at',triaged_at,'created_at',created_at) order by created_at desc)
      from (select * from public.inbound_messages
             where needs_review=true and replied_at is null
               and created_at >= public.fn_os_fresh_start_at()
             order by created_at desc limit 50) m),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_inbox_send(p_id bigint, p_body text, p_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare m public.inbound_messages%rowtype;
begin
  select * into m from public.inbound_messages where id=p_id;
  if m.id is null then return jsonb_build_object('error','message not found'); end if;
  if m.from_email is null then return jsonb_build_object('error','no sender address'); end if;
  if coalesce(trim(p_body),'')='' then return jsonb_build_object('error','empty reply'); end if;

  insert into public.notifications(type,to_email,to_role,channel,subject,body)
    values('inbound_reply', m.from_email, null, 'email',
           case when coalesce(m.subject,'') ilike 're:%' then m.subject else 'Re: '||coalesce(m.subject,'your message') end,
           p_body);

  update public.inbound_messages set replied_at=now(), replied_by=coalesce(p_by,'founder'), needs_review=false where id=p_id;
  update public.agent_actions set status='approved', decided_by=coalesce(p_by,'founder'), decided_at=now()
   where target_table='inbound_messages' and target_id=p_id::text
     and status in ('pending','held_for_review','proposed','open');
  return jsonb_build_object('ok',true, 'to', m.from_email);
end $function$


CREATE OR REPLACE FUNCTION public.fn_index_slowdown_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n int := 0; r record; v_moved text; v_ins int;
begin
  for r in
    select z.index_name, z.measured_on, z.score, z.prev, z.dims, z.prev_dims
      from (select c.index_name, c.measured_on, c.score, c.dimensions dims,
                   lag(c.score)      over (partition by c.index_name order by c.measured_on) prev,
                   lag(c.dimensions) over (partition by c.index_name order by c.measured_on) prev_dims
              from public.company_index c
             where c.measured_on > current_date - 30) z
     where z.prev is not null and z.score < z.prev - 1 and z.measured_on > current_date - 7
       and not exists (select 1 from public.founder_alerts a
                        where a.created_at::date >= z.measured_on
                          and position(z.index_name in coalesce(a.event,'')||' '||coalesce(a.detail::text,'')) > 0)
       and not exists (select 1 from public.evolution_proposal p
                        where p.created_at::date >= z.measured_on
                          and position(z.index_name in coalesce(p.subject,'')||' '||coalesce(p.observation,'')) > 0)
       and not exists (select 1 from public.agent_actions g
                        where g.created_at::date >= z.measured_on
                          and position(z.index_name in coalesce(g.title,'')||' '||coalesce(g.detail::text,'')) > 0)
  loop
    -- WHERE THE DROP CAME FROM, out of the index's own stored dimensions. Only dimensions that
    -- actually fell, biggest mover first, with both values so the size is visible.
    select string_agg(d.k||' '||d.was||' to '||d.now_v, ', ' order by (d.was - d.now_v) desc)
      into v_moved
      from (select k, (r.prev_dims->>k)::numeric was, (r.dims->>k)::numeric now_v
              from jsonb_object_keys(r.dims) k
             where jsonb_typeof(r.dims->k) = 'number'
               and jsonb_typeof(coalesce(r.prev_dims->k,'null'::jsonb)) = 'number'
               and (r.prev_dims->>k)::numeric > (r.dims->>k)::numeric) d;

    insert into public.evolution_proposal (trigger_kind, subject, observation, evidence, proposal, change_class)
    values ('metric_off_target', r.index_name,
      format('%s fell from %s to %s on %s, a drop of %s points. Dimensions that moved down: %s.',
             r.index_name, r.prev, r.score, r.measured_on, round(r.prev - r.score, 2),
             coalesce(v_moved, 'none that the index breaks out — the drop is in the weighting, not in a named dimension')),
      jsonb_build_object('index', r.index_name, 'from', r.prev, 'to', r.score,
                         'fell_by', round(r.prev - r.score, 2), 'measured_on', r.measured_on,
                         'dimensions_down', v_moved),
      format('Find the cause of the %s fall before it compounds. The dimensions above are where it came from; the drop is arithmetic, the reason is not, and only one of those two is in the data.', r.index_name),
      'process')
    -- The partial unique index gets the final say. Its predicate is repeated verbatim so the
    -- arbiter resolves to evolution_proposal_dedupe_idx and nothing else.
    on conflict (trigger_kind, subject, change_class) where status = 'proposed' do nothing;
    -- Count what was written, not what was attempted: a duplicate that was skipped is not an
    -- investigation raised, and the note at the bottom is read as if it were.
    get diagnostics v_ins = row_count;
    n := n + v_ins;
  end loop;

  insert into public.agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('index_slowdown_watch', now(), now(), 'ok', jsonb_build_object('investigated', n),
    case when n = 0 then 'No index lost more than a point in the last 7 days without something already picking it up.'
         else n||' index fall(s) over a point raised for investigation, with the dimensions that moved.' end);

  return jsonb_build_object('investigated', n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_inquiry_answer_confirm(p_group_id bigint, p_field_id text, p_value text, p_confirmed_by text, p_reason text, p_workstream_ids bigint[] DEFAULT NULL::bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_res jsonb; v_conflict_id bigint; v_kept integer;
begin
  if coalesce(btrim(p_confirmed_by),'') = '' or coalesce(btrim(p_reason),'') = '' then
    return jsonb_build_object('ok', false, 'error', 'who_and_why_required');
  end if;

  select id into v_conflict_id from public.inquiry_answer_conflict
   where group_id = p_group_id and field_id = p_field_id and resolved_at is null;

  v_res := public.fn_inquiry_answer_set(p_group_id, p_field_id, p_value, 'customer_confirmed',
             'customer', p_confirmed_by, null, p_workstream_ids, null);
  if not (v_res->>'ok')::boolean then return v_res; end if;

  if v_conflict_id is not null then
    insert into public.inquiry_answer_conflict_value (conflict_id, value, precedence, source_kind)
    values (v_conflict_id, p_value, 'customer_confirmed', 'customer');
    update public.inquiry_answer_conflict
       set resolved_at = now(), resolved_by = p_confirmed_by, resolution_reason = p_reason
     where id = v_conflict_id;
    select count(*) into v_kept from public.inquiry_answer_conflict_value where conflict_id = v_conflict_id;
  end if;

  insert into public.inquiry_state_audit (group_id, event, detail, actor)
  values (p_group_id, 'conflict_resolved_by_confirmation',
          jsonb_build_object('field_id', p_field_id, 'conflict_id', v_conflict_id,
                             'reason', p_reason, 'evidence_values_kept', v_kept), p_confirmed_by);

  return jsonb_build_object('ok', true, 'action', v_res->>'action', 'conflict_id', v_conflict_id,
                            'evidence_values_kept', v_kept);
end $function$


CREATE OR REPLACE FUNCTION public.fn_inquiry_answer_set(p_group_id bigint, p_field_id text, p_value text, p_precedence answer_precedence, p_source_kind text, p_actor text DEFAULT 'system'::text, p_unit text DEFAULT NULL::text, p_workstream_ids bigint[] DEFAULT NULL::bigint[], p_document jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_fd public.field_definition%rowtype; v_answer_scope text;
  v_live public.inquiry_answer%rowtype; v_new_id bigint; v_conflict_id bigint;
  v_norm_new text; v_norm_live text; v_rank_new integer; v_rank_live integer;
  v_ws bigint; v_bad_ws bigint[]; v_action text;
begin
  select * into v_fd from public.field_definition where field_id = p_field_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'unknown_field', 'field_id', p_field_id);
  end if;
  if not exists (select 1 from public.inquiry_workstream_group where id = p_group_id) then
    return jsonb_build_object('ok', false, 'error', 'unknown_group');
  end if;

  v_answer_scope := case v_fd.scope when 'shared' then 'inquiry_shared' else v_fd.scope end;

  if v_fd.scope <> 'shared' then
    if p_workstream_ids is null or array_length(p_workstream_ids, 1) is null then
      return jsonb_build_object('ok', false, 'error', 'workstream_required',
        'message', 'A trade-specific answer must say which workstream it belongs to.');
    end if;
    select array_agg(w.id) into v_bad_ws
      from public.inquiry_workstream w
     where w.id = any(p_workstream_ids)
       and (w.group_id <> p_group_id
            or (v_fd.scope = 'trade_specific' and w.trade_key <> v_fd.trade_key)
            or (v_fd.scope = 'trade_subset' and not exists (
                  select 1 from public.field_definition_trade t
                   where t.field_id = v_fd.field_id and t.trade_key = w.trade_key)));
    if v_bad_ws is not null then
      return jsonb_build_object('ok', false, 'error', 'trade_mismatch',
        'field_id', p_field_id, 'field_trade', v_fd.trade_key, 'rejected_workstreams', v_bad_ws,
        'message', 'This field belongs to another trade. A trade-specific answer cannot satisfy a workstream that does not own the field.');
    end if;
    if (select count(*) from public.inquiry_workstream
         where id = any(p_workstream_ids)) <> array_length(p_workstream_ids, 1) then
      return jsonb_build_object('ok', false, 'error', 'unknown_workstream');
    end if;
  end if;

  select * into v_live from public.inquiry_answer
   where group_id = p_group_id and field_id = p_field_id and superseded_by is null;

  if not found then
    insert into public.inquiry_answer (group_id, field_id, value, unit, scope, precedence,
                                       source_kind, confirmed_at, confirmed_by)
    values (p_group_id, p_field_id, p_value, coalesce(p_unit, v_fd.unit), v_answer_scope,
            p_precedence, p_source_kind,
            case when p_precedence = 'customer_confirmed' then now() end,
            case when p_precedence = 'customer_confirmed' then p_actor end)
    returning id into v_new_id;
    v_action := 'inserted';
  else
    v_rank_new  := public.fn_answer_precedence_rank(p_precedence);
    v_rank_live := public.fn_answer_precedence_rank(v_live.precedence);
    v_norm_new  := public.fn_field_normalise(p_field_id, p_value);
    v_norm_live := public.fn_field_normalise(p_field_id, v_live.value);

    if v_rank_new < v_rank_live
       or (v_rank_new = v_rank_live and p_precedence = 'customer_confirmed'
           and v_norm_new is distinct from v_norm_live) then
      v_new_id := public.fn_inquiry_answer_supersede(v_live.id, p_group_id, p_field_id, p_value,
                    coalesce(p_unit, v_fd.unit), v_answer_scope, p_precedence, p_source_kind, p_actor);
      v_action := 'superseded';

    elsif v_norm_new is not distinct from v_norm_live then
      v_new_id := v_live.id;
      insert into public.inquiry_answer_corroboration
        (answer_id, value, normalised_value, precedence, source_kind, document_id)
      values (v_live.id, p_value, v_norm_new, p_precedence, p_source_kind, p_document->>'document_id');
      v_action := 'corroborated';

    else
      v_new_id := v_live.id;
      select id into v_conflict_id from public.inquiry_answer_conflict
       where group_id = p_group_id and field_id = p_field_id and resolved_at is null;
      if v_conflict_id is null then
        insert into public.inquiry_answer_conflict (group_id, field_id, blocking_scope)
        values (p_group_id, p_field_id,
                case when v_fd.scope = 'shared' then 'shared' else 'trade' end)
        returning id into v_conflict_id;
        insert into public.inquiry_answer_conflict_value (conflict_id, value, precedence, source_kind)
        values (v_conflict_id, v_live.value, v_live.precedence, v_live.source_kind);
      end if;
      insert into public.inquiry_answer_conflict_value
        (conflict_id, value, precedence, source_kind, document_id)
      values (v_conflict_id, p_value, p_precedence, p_source_kind, p_document->>'document_id');
      v_action := 'conflict_opened';
    end if;
  end if;

  if v_fd.scope <> 'shared' and v_action in ('inserted','superseded') then
    foreach v_ws in array p_workstream_ids loop
      insert into public.inquiry_answer_scope (answer_id, workstream_id)
      values (v_new_id, v_ws) on conflict do nothing;
    end loop;
  end if;

  if p_document is not null and v_action in ('inserted','superseded') then
    insert into public.inquiry_answer_document
      (answer_id, document_id, page_or_sheet, extraction_confidence, original_text, assigned_scope)
    values (v_new_id, p_document->>'document_id', p_document->>'page_or_sheet',
            (p_document->>'extraction_confidence')::numeric, p_document->>'original_text', v_answer_scope);
  end if;

  insert into public.inquiry_state_audit (group_id, event, detail, actor)
  values (p_group_id, 'answer_' || v_action,
          jsonb_build_object('field_id', p_field_id, 'precedence', p_precedence,
                             'source_kind', p_source_kind, 'answer_id', v_new_id,
                             'conflict_id', v_conflict_id), p_actor);

  return jsonb_build_object('ok', true, 'action', v_action, 'answer_id', v_new_id,
                            'field_id', p_field_id, 'conflict_id', v_conflict_id,
                            'scope', v_answer_scope);
end $function$


CREATE OR REPLACE FUNCTION public.fn_inquiry_answer_supersede(p_live_id bigint, p_group_id bigint, p_field_id text, p_value text, p_unit text, p_scope text, p_precedence answer_precedence, p_source_kind text, p_actor text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_new_id bigint;
begin
  v_new_id := nextval(pg_get_serial_sequence('public.inquiry_answer','id'));
  update public.inquiry_answer set superseded_by = v_new_id where id = p_live_id;
  insert into public.inquiry_answer (id, group_id, field_id, value, unit, scope, precedence,
                                     source_kind, confirmed_at, confirmed_by)
  values (v_new_id, p_group_id, p_field_id, p_value, p_unit, p_scope, p_precedence, p_source_kind,
          case when p_precedence = 'customer_confirmed' then now() end,
          case when p_precedence = 'customer_confirmed' then p_actor end);
  insert into public.inquiry_answer_scope (answer_id, workstream_id)
    select v_new_id, workstream_id from public.inquiry_answer_scope where answer_id = p_live_id
    on conflict do nothing;
  return v_new_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_inquiry_dispatch_eligible(p_inquiry_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with ws as (
    select d.workstream_id, d.trade_key, d.dispatch_eligible, d.mandatory_complete,
           d.no_unresolved_conflict, d.gates_passed, d.missing_mandatory, d.blocked_by
    from public.inquiry_workstream_group g
    join public.inquiry_workstream w on w.group_id = g.id
    join public.v_workstream_dispatch d on d.workstream_id = w.id
    where g.inquiry_id = p_inquiry_id and w.active
  )
  select case
    when (select count(*) from ws) = 0
      then jsonb_build_object('eligible', true, 'reason', 'no_workstreams', 'workstreams', 0)
    when (select bool_and(dispatch_eligible) from ws)
      then jsonb_build_object('eligible', true, 'reason', 'all_workstreams_eligible',
                              'workstreams', (select count(*) from ws))
    else jsonb_build_object(
      'eligible', false,
      'reason', 'workstream_not_dispatch_eligible',
      'workstreams', (select count(*) from ws),
      'blocking', (select jsonb_agg(jsonb_build_object(
          'workstream_id', workstream_id, 'trade', trade_key,
          'mandatory_complete', mandatory_complete,
          'no_unresolved_conflict', no_unresolved_conflict,
          'gates_passed', gates_passed,
          'missing_mandatory', to_jsonb(missing_mandatory),
          'blocked_by', to_jsonb(blocked_by)))
        from ws where not dispatch_eligible))
  end;
$function$


CREATE OR REPLACE FUNCTION public.fn_inquiry_interpret(p_group_id bigint, p_customer_text text DEFAULT NULL::text, p_structured jsonb DEFAULT NULL::jsonb, p_documents jsonb DEFAULT NULL::jsonb, p_actor text DEFAULT 'system'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id jsonb; v_n integer; v_apply jsonb; v_active text[]; v_conf boolean;
begin
  v_id := public.fn_trade_identify(p_group_id, p_customer_text, p_structured, p_documents, p_actor);
  if not coalesce((v_id->>'ok')::boolean,false) then return v_id; end if;

  v_n := public.fn_scope_detect(p_group_id, p_customer_text, p_actor);
  v_apply := public.fn_scope_apply(p_group_id, p_actor);

  select coalesce(array_agg(trade_key order by trade_key),'{}') into v_active
    from public.inquiry_workstream where group_id = p_group_id and active;
  select exists (select 1 from public.v_trade_scope_status
                  where group_id = p_group_id and is_conflict) into v_conf;

  -- Nothing active, or an unresolved scope conflict, must ask.
  if cardinality(v_active) = 0 or v_conf then
    insert into public.inquiry_trade_clarification (group_id, question_en, question_ar, options, reason)
    select p_group_id,
           case when v_conf then 'Two statements in your enquiry disagree about scope. Which applies?'
                else 'Which trades does this enquiry cover?' end,
           case when v_conf then 'هناك عبارتان متعارضتان بشأن نطاق العمل. أيهما ينطبق؟'
                else 'ما هي التخصصات التي يشملها هذا الطلب؟' end,
           coalesce((select array_agg(distinct trade_key) from public.v_trade_scope_status
                      where group_id = p_group_id and (is_conflict or not coalesce(contributes,false))),
                    array['hvac','electrical','plumbing','fire','elv']),
           case when v_conf then 'Contradictory scope statements of equal specificity. Resolved by asking, never by preferring the last sentence.'
                else 'Every detected trade is excluded, by others, optional, future-phase or unresolved.' end
    where not exists (select 1 from public.inquiry_trade_clarification c
                       where c.group_id = p_group_id and c.answered_at is null);
  end if;

  return jsonb_build_object('ok', true, 'identification', v_id, 'dispositions_recorded', v_n,
                            'scope_applied', v_apply,
                            'active_trades', to_jsonb(v_active),
                            'scope_conflict', v_conf,
                            'clarification_required',
                              exists (select 1 from public.inquiry_trade_clarification
                                       where group_id = p_group_id and answered_at is null));
end $function$


CREATE OR REPLACE FUNCTION public.fn_inquiry_workstream_activate(p_group_id bigint, p_trade_key text, p_actor text DEFAULT 'system'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_ws_id bigint; v_route integer; v_reactivated boolean := false; v_reqs integer;
begin
  if not exists (select 1 from public.mep_trade where trade_key = p_trade_key) then
    return jsonb_build_object('ok', false, 'error', 'unknown_trade', 'trade_key', p_trade_key);
  end if;
  if not exists (select 1 from public.inquiry_workstream_group where id = p_group_id) then
    return jsonb_build_object('ok', false, 'error', 'unknown_group');
  end if;

  select catalog_num into v_route from public.mep_trade_route
   where trade_key = p_trade_key and is_primary order by catalog_num limit 1;

  select id into v_ws_id from public.inquiry_workstream
   where group_id = p_group_id and trade_key = p_trade_key;

  if v_ws_id is null then
    insert into public.inquiry_workstream (group_id, trade_key, route_catalog_num)
    values (p_group_id, p_trade_key, v_route) returning id into v_ws_id;
  else
    update public.inquiry_workstream
       set active = true, activated_at = now(), deactivated_at = null
     where id = v_ws_id and active = false;
    v_reactivated := found;
    update public.inquiry_workstream set active = true where id = v_ws_id;
  end if;

  insert into public.inquiry_workstream_requirement (workstream_id, question_id, field_id, mandatory)
  select v_ws_id, min(q.question_id), s.field_id, bool_or(q.mandatory)
    from public.mep_trade_route tr
    join public.kb_operational_route_map m on m.catalog_num = tr.catalog_num
    join kb_stage.questions q on q.subcategory_slug = m.subcategory_slug
    join public.field_definition_source s
      on s.subcategory_slug = q.subcategory_slug and s.source_field_key = q.field_key
    left join public.subcategory_trade_contribution c
      on c.subcategory_slug = m.subcategory_slug and c.catalog_num = tr.catalog_num
     and c.trade_key = tr.trade_key
   where tr.trade_key = p_trade_key and q.field_key is not null
     and coalesce(c.contribution, 'technical') <> 'excluded'
     and (coalesce(c.contribution, 'technical') <> 'regulatory'
          or q.field_key = any(coalesce(c.contributed_field_keys, '{}'::text[])))
     and not exists (select 1 from public.field_definition_reference r
                      where r.field_id = s.field_id and r.referencing_trade_key = p_trade_key)
   group by s.field_id
  on conflict (workstream_id, field_id) do update
     set mandatory = public.inquiry_workstream_requirement.mandatory or excluded.mandatory;

  get diagnostics v_reqs = row_count;

  insert into public.inquiry_state_audit (group_id, workstream_id, event, detail, actor)
  values (p_group_id, v_ws_id,
          case when v_reactivated then 'workstream_reactivated' else 'workstream_activated' end,
          jsonb_build_object('trade_key', p_trade_key, 'route_catalog_num', v_route,
                             'requirements', v_reqs), p_actor);

  return jsonb_build_object('ok', true, 'workstream_id', v_ws_id, 'trade_key', p_trade_key,
                            'reactivated', v_reactivated, 'requirements', v_reqs);
end $function$


CREATE OR REPLACE FUNCTION public.fn_inquiry_workstream_deactivate(p_group_id bigint, p_trade_key text, p_actor text DEFAULT 'system'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_ws_id bigint;
begin
  update public.inquiry_workstream
     set active = false, deactivated_at = now()
   where group_id = p_group_id and trade_key = p_trade_key and active
   returning id into v_ws_id;
  if v_ws_id is null then
    return jsonb_build_object('ok', false, 'error', 'not_active');
  end if;
  insert into public.inquiry_state_audit (group_id, workstream_id, event, detail, actor)
  values (p_group_id, v_ws_id, 'workstream_deactivated',
          jsonb_build_object('trade_key', p_trade_key), p_actor);
  return jsonb_build_object('ok', true, 'workstream_id', v_ws_id);
end $function$


CREATE OR REPLACE FUNCTION public.fn_intake_slug_for_catalog(p_catalog_slug text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- The reverse of fn_category_knowledge: catalogue slug -> the legacy intake slug that owns the
  -- checklist. It is 1-to-many (flooring-suppliers is reached by carpets, epoxy-flooring, flooring,
  -- marble-granite and tiling), so the choice has to be deterministic or the same customer wording
  -- would land on a different checklist run to run.
  --
  -- Prefer a key the catalogue slug actually BEGINS with - 'flooring' for flooring-suppliers,
  -- 'aluminium' for aluminium-and-glass-suppliers, 'mep' for mep-suppliers-electromechanical.
  -- That picks the base trade over a facet of it. Where none prefixes, the shortest wins, which
  -- also prefers the base ('carpentry' over 'carpentry-joinery', 'fitout' over
  -- 'commercial-retail-fitout'). Only keys that exist in category_specs are eligible, because the
  -- answer has to be something the checklist lookup can actually use.
  select m.trade_key
    from public.lead_trade_map m
    join (select distinct category from public.category_specs) cs on cs.category = m.trade_key
   where m.catalog_slug = p_catalog_slug
   order by (p_catalog_slug like m.trade_key || '%') desc, length(m.trade_key) asc, m.trade_key asc
   limit 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_internal_auth(p_secret text, p_function text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare c public.internal_credential%rowtype; v_hash text; v_fn text;
begin
  v_fn := lower(btrim(coalesce(p_function, '')));
  if v_fn = '' then
    insert into public.internal_credential_audit (allowed, reason, function_name)
    values (false, 'no_function_named', p_function);
    return jsonb_build_object('ok', false, 'error', 'no_function_named',
      'message', 'The verifier was called without naming the function being invoked, so it cannot check scope.');
  end if;

  if coalesce(btrim(p_secret), '') = '' then
    insert into public.internal_credential_audit (allowed, reason, function_name)
    values (false, 'no_credential_presented', v_fn);
    return jsonb_build_object('ok', false, 'error', 'no_credential_presented');
  end if;

  v_hash := public.fn_internal_credential_hash(p_secret);
  select * into c from public.internal_credential where secret_hash = v_hash;

  if not found then
    insert into public.internal_credential_audit (allowed, reason, function_name)
    values (false, 'unknown_credential', v_fn);
    return jsonb_build_object('ok', false, 'error', 'unknown_credential');
  end if;

  if not c.active or c.retired_at is not null then
    insert into public.internal_credential_audit (credential_id, context, function_name, allowed, reason)
    values (c.id, c.context, v_fn, false, 'credential_retired');
    return jsonb_build_object('ok', false, 'error', 'credential_retired', 'context', c.context);
  end if;

  if c.expires_at is not null and c.expires_at <= now() then
    insert into public.internal_credential_audit (credential_id, context, function_name, allowed, reason)
    values (c.id, c.context, v_fn, false, 'credential_expired');
    return jsonb_build_object('ok', false, 'error', 'credential_expired', 'context', c.context,
      'expired_at', c.expires_at);
  end if;

  if not (c.scope @> array['*'] or c.scope @> array[v_fn]) then
    insert into public.internal_credential_audit (credential_id, context, function_name, allowed, reason, detail)
    values (c.id, c.context, v_fn, false, 'out_of_scope', jsonb_build_object('scope', c.scope));
    return jsonb_build_object('ok', false, 'error', 'out_of_scope', 'context', c.context,
      'message', format('The %s credential is not scoped to call %s.', c.context, v_fn));
  end if;

  update public.internal_credential
     set last_used_at = now(), last_function = v_fn, use_count = use_count + 1
   where id = c.id;

  -- THE ADDITION. Legacy only.
  if c.is_legacy then
    insert into public.internal_credential_audit (credential_id, context, function_name, allowed, reason)
    values (c.id, c.context, v_fn, true, 'legacy_secret_used');
  end if;

  return jsonb_build_object('ok', true, 'context', c.context, 'credential_id', c.id,
                            'legacy', c.is_legacy, 'scope_all', c.scope @> array['*']);
end $function$


CREATE OR REPLACE FUNCTION public.fn_internal_credential_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  raise exception 'internal_credential_audit is append-only; % is not permitted', TG_OP using errcode = '42501';
end $function$


CREATE OR REPLACE FUNCTION public.fn_internal_credential_hash(p_secret text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  select encode(extensions.hmac(p_secret,
           (select value from public.app_secrets where key = 'internal_credential_hmac_key'),
           'sha256'), 'hex');
$function$


CREATE OR REPLACE FUNCTION public.fn_internal_credential_issue(p_context text, p_scope text[], p_label text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_secret text; v_id bigint;
begin
  if coalesce(btrim(p_context), '') = '' then raise exception 'a context is required' using errcode = '22023'; end if;
  if p_scope is null or array_length(p_scope, 1) is null then
    raise exception 'a scope is required - name the functions this credential may call' using errcode = '22023';
  end if;
  -- The whole point of 9.5. An unrestricted credential is what we are removing, so it cannot be
  -- issued: only the seeded legacy row is allowed to hold '*'.
  if p_scope @> array['*'] then
    raise exception 'scope ''*'' is reserved for the legacy shared secret and cannot be issued' using errcode = '22023';
  end if;

  v_secret := encode(extensions.gen_random_bytes(32), 'hex');
  insert into public.internal_credential (context, label, secret_hash, scope, expires_at)
  values (btrim(p_context), p_label, public.fn_internal_credential_hash(v_secret),
          array(select distinct lower(btrim(s)) from unnest(p_scope) s where btrim(s) <> ''), p_expires_at)
  returning id into v_id;

  insert into public.internal_credential_audit (credential_id, context, allowed, reason, detail)
  values (v_id, btrim(p_context), true, 'issued', jsonb_build_object('scope', p_scope, 'label', p_label));

  -- Returned ONCE. There is no way to read it back; a lost credential is rotated, not recovered.
  return jsonb_build_object('ok', true, 'id', v_id, 'context', btrim(p_context), 'secret', v_secret,
    'warning', 'This secret is shown once and cannot be retrieved again. Store it now.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_internal_credential_retire(p_id bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.internal_credential%rowtype;
begin
  if length(coalesce(btrim(p_reason), '')) < 8 then
    raise exception 'a reason of at least 8 characters is required' using errcode = '22023';
  end if;
  select * into c from public.internal_credential where id = p_id;
  if not found then raise exception 'no credential %', p_id using errcode = '22023'; end if;

  update public.internal_credential set active = false, retired_at = now() where id = p_id;
  insert into public.internal_credential_audit (credential_id, context, allowed, reason, detail)
  values (p_id, c.context, true, 'retired',
          jsonb_build_object('why', p_reason, 'use_count_at_retirement', c.use_count, 'last_used_at', c.last_used_at));

  return jsonb_build_object('ok', true, 'id', p_id, 'context', c.context,
    'use_count_at_retirement', c.use_count, 'last_used_at', c.last_used_at);
end $function$


CREATE OR REPLACE FUNCTION public.fn_internal_credential_rotate(p_context text, p_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_old public.internal_credential%rowtype; v_new jsonb;
begin
  select * into v_old from public.internal_credential
   where context = btrim(p_context) and active and retired_at is null
   order by created_at desc limit 1;
  if not found then raise exception 'no active credential for context %', p_context using errcode = '22023'; end if;
  if v_old.scope @> array['*'] then
    raise exception 'the legacy shared secret is withdrawn, not rotated - see supabase/rollback and the 9.5 runbook' using errcode = '22023';
  end if;

  v_new := public.fn_internal_credential_issue(v_old.context, v_old.scope,
             coalesce(p_label, 'rotated from #' || v_old.id));
  update public.internal_credential set rotated_at = now() where id = v_old.id;

  return v_new || jsonb_build_object('previous_id', v_old.id,
    'note', 'The previous credential is STILL ACTIVE. Move callers across, watch use_count stop rising, then retire it.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_inv_adjust(p_item bigint, p_qty_delta numeric, p_unit_cost numeric DEFAULT NULL::numeric, p_offset_account text DEFAULT '6300'::text, p_date date DEFAULT NULL::date, p_memo text DEFAULT NULL::text, p_by text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare onq numeric(18,4); onv numeric(18,2); avg_c numeric(18,4);
        uc numeric(18,4); amt numeric(18,2); j bigint; inv_acct text; m bigint;
begin
  if p_qty_delta = 0 then raise exception 'adjustment qty_delta cannot be 0'; end if;
  select coalesce(sum(qty_delta),0), coalesce(sum(cost_delta),0)
    into onq, onv from public.inv_stock_moves where item_id=p_item;
  avg_c := case when onq <> 0 then onv/onq else 0 end;
  uc := coalesce(p_unit_cost, avg_c);                 -- default to current avg for reductions
  amt := round(p_qty_delta * uc, 2);                  -- signed
  select inventory_account into inv_acct from public.inv_items where id=p_item;
  if inv_acct is null then raise exception 'item % not found', p_item; end if;
  -- positive delta: Dr Inventory / Cr offset ; negative: Dr offset / Cr Inventory
  if amt >= 0 then
    j := public.fn_gl_entry(coalesce(p_date,current_date), coalesce(p_memo,'Inventory adjustment'),
           'inv_adjust', p_item::text,
           jsonb_build_array(jsonb_build_object('account',inv_acct,'debit',amt),
                             jsonb_build_object('account',p_offset_account,'credit',amt)), p_by);
  else
    j := public.fn_gl_entry(coalesce(p_date,current_date), coalesce(p_memo,'Inventory adjustment'),
           'inv_adjust', p_item::text,
           jsonb_build_array(jsonb_build_object('account',p_offset_account,'debit',-amt),
                             jsonb_build_object('account',inv_acct,'credit',-amt)), p_by);
  end if;
  insert into public.inv_stock_moves(item_id,move_date,move_type,qty_delta,cost_delta,
       unit_cost,ref_type,ref_id,gl_journal_id,memo,created_by)
    values (p_item, coalesce(p_date,current_date),'adjust', p_qty_delta, amt, uc,
            'adjust', p_item::text, j, p_memo, p_by)
    returning id into m;
  return m;
end $function$


CREATE OR REPLACE FUNCTION public.fn_inv_issue(p_item bigint, p_qty numeric, p_date date DEFAULT NULL::date, p_ref_type text DEFAULT 'manual'::text, p_ref_id text DEFAULT NULL::text, p_by text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare onq numeric(18,4); onv numeric(18,2); avg_c numeric(18,4);
        amt numeric(18,2); j bigint; inv_acct text; cogs_acct text; m bigint;
begin
  select coalesce(sum(qty_delta),0), coalesce(sum(cost_delta),0)
    into onq, onv from public.inv_stock_moves where item_id=p_item;
  if p_qty <= 0 then raise exception 'issue qty must be > 0'; end if;
  if p_qty > onq then raise exception 'insufficient stock for item %: have %, need %', p_item, onq, p_qty; end if;
  avg_c := case when onq <> 0 then onv/onq else 0 end;
  amt := round(p_qty * avg_c, 2);
  select inventory_account, cogs_account into inv_acct, cogs_acct from public.inv_items where id=p_item;
  j := public.fn_gl_entry(coalesce(p_date,current_date),
         'Inventory issue item '||p_item, 'inv_issue', p_ref_id,
         jsonb_build_array(jsonb_build_object('account',cogs_acct,'debit',amt),
                           jsonb_build_object('account',inv_acct,'credit',amt)), p_by);
  insert into public.inv_stock_moves(item_id,move_date,move_type,qty_delta,cost_delta,
       unit_cost,ref_type,ref_id,gl_journal_id,created_by)
    values (p_item, coalesce(p_date,current_date),'out', -p_qty, -amt, avg_c,
            p_ref_type, p_ref_id, j, p_by)
    returning id into m;
  return m;
end $function$


CREATE OR REPLACE FUNCTION public.fn_inv_receive(p_item bigint, p_qty numeric, p_unit_cost numeric, p_date date DEFAULT NULL::date, p_ref_type text DEFAULT 'manual'::text, p_ref_id text DEFAULT NULL::text, p_post_gl boolean DEFAULT true, p_by text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare amt numeric(18,2); j bigint; inv_acct text; m bigint;
begin
  if p_qty <= 0 then raise exception 'receive qty must be > 0'; end if;
  select inventory_account into inv_acct from public.inv_items where id=p_item;
  if inv_acct is null then raise exception 'item % not found', p_item; end if;
  amt := round(p_qty * p_unit_cost, 2);
  if p_post_gl then                                   -- Dr Inventory  Cr Cash(1000)
    j := public.fn_gl_entry(coalesce(p_date,current_date),
           'Inventory receipt item '||p_item, 'inv_receipt', p_ref_id,
           jsonb_build_array(jsonb_build_object('account',inv_acct,'debit',amt),
                             jsonb_build_object('account','1000','credit',amt)), p_by);
  end if;
  insert into public.inv_stock_moves(item_id,move_date,move_type,qty_delta,cost_delta,
       unit_cost,ref_type,ref_id,gl_journal_id,created_by)
    values (p_item, coalesce(p_date,current_date),'in', p_qty, amt, p_unit_cost,
            p_ref_type, p_ref_id, j, p_by)
    returning id into m;
  return m;
end $function$


CREATE OR REPLACE FUNCTION public.fn_invite_ramp()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_base int := 10; v_ceiling int := 200;
  v_sent_total int; v_last_sent timestamptz; v_stage int;
  v_sent7 int; v_bounced7 int; v_rate numeric;
  v_cur int; v_new int; v_note text;
  v_uncontacted int; v_max_rate numeric; v_at_floor boolean := false;
  v_named7 int := 0; v_named_b7 int := 0; v_role7 int := 0; v_role_b7 int := 0;
begin
  v_cur := coalesce((select nullif(value,'')::int from app_secrets where key='invite_daily_cap'), v_base);
  v_max_rate := coalesce((select nullif(value,'')::numeric from app_secrets where key='invite_max_bounce_rate'), 0.05);

  -- PAUSED IS A REPORTABLE STATE, NOT A SILENT ONE. Previously this returned here and said nothing,
  -- so a campaign auto-paused on bounce rate looked identical to a healthy one: both crons
  -- 'succeeded', no agent_runs row, no alert, and the stall detector below unreachable.
  if coalesce((select value from app_secrets where key='invite_enabled'),'false') <> 'true' then
    select count(*), max(invited_at) into v_sent_total, v_last_sent from leads where invited_at is not null;
    select count(*) into v_sent7    from leads where invited_at > now() - interval '7 days';
    select count(*) into v_bounced7 from leads where invite_status='bounced' and invited_at > now() - interval '7 days';
    select count(*) into v_uncontacted from leads
      where invited_at is null and coalesce(btrim(email),'') <> '';

    v_note := 'PAUSED: invite_enabled is false. '||v_uncontacted||' lead(s) with an email have never '
      ||'been invited, of '||(select count(*) from leads)||' total. Last invite '
      ||coalesce(to_char(v_last_sent at time zone 'UTC','YYYY-MM-DD HH24:MI')||'Z','never')
      ||'; '||v_sent_total||' issued lifetime; 7d bounce '
      ||round((v_bounced7::numeric / greatest(v_sent7,1))*100,1)||'% ('||v_bounced7||'/'||v_sent7||').';

    insert into agent_runs(agent,status,counts,note,finished_at)
    values('invite_ramp','ok',
           jsonb_build_object('paused',true,'cap',v_cur,'sent_total',v_sent_total,
                              'uncontacted_with_email',v_uncontacted),
           v_note, now());

    if v_uncontacted > 0
       and not exists (select 1 from founder_alerts
                        where event='invite_campaign_paused' and created_at > now()-interval '24 hours') then
      insert into founder_alerts(level,event,detail,channel)
      values('warn','invite_campaign_paused',
             'Supplier invites are PAUSED and nothing is being sent. '||v_note
             ||' Re-enabling sends into this bounce rate risks the sending domain — verify the list '
             ||'before setting app_secrets.invite_enabled back to true.','system');
    end if;

    return v_cur;
  end if;

  select count(*), max(invited_at) into v_sent_total, v_last_sent from leads where invited_at is not null;
  select count(*) into v_sent7    from leads where invited_at > now() - interval '7 days';
  select count(*) into v_bounced7 from leads where invite_status='bounced' and invited_at > now() - interval '7 days';
  v_rate := v_bounced7::numeric / greatest(v_sent7,1);

  -- THE SAME WINDOW, SPLIT BY WHO WE WROTE TO. A shared inbox and a named person are not one
  -- population: measured over every invitation ever sent, role addresses bounce at 8.6% (5/58) and
  -- named humans at 0% (0/13), and every bounce on record predates the role-last ordering.
  select count(*) filter (where not r), count(*) filter (where not r and b),
         count(*) filter (where r),     count(*) filter (where r and b)
    into v_named7, v_named_b7, v_role7, v_role_b7
    from (select (split_part(email,'@',1) ~* '^(info|support|sales|admin|contact|enquiry|enquiries|inquiry|office|mail|hello|team|general|reception|marketing|accounts|hr)$') as r,
                 (invite_status = 'bounced') as b
            from leads where invited_at > now() - interval '7 days') z;

  -- STAGE ON VOLUME ISSUED, NOT ON THE CALENDAR. The previous ladder read
  -- (today - min(invited_at)::date), so it advanced while the enqueuer was timing out and nothing
  -- was being sent. A warm-up schedule that ratchets on a domain that is not sending is a
  -- deliverability incident held in escrow until somebody fixes the sender.
  v_stage := case when v_sent_total <  25 then 10
                  when v_sent_total <  75 then 25
                  when v_sent_total < 200 then 50
                  when v_sent_total < 500 then 100
                  else v_ceiling end;

  if v_last_sent is null then
    v_new := v_base;
    v_note := 'nothing issued yet; cap held at base '||v_base;
  elsif v_last_sent < now() - interval '3 days' then
    -- Silence is now a reportable state. Seven days of daily statement timeouts went unnoticed
    -- because the only thing watching filed its alarm into a queue with no reader.
    v_new := v_base;
    v_note := 'stalled: nothing issued since '||to_char(v_last_sent at time zone 'UTC','YYYY-MM-DD HH24:MI')||'Z; cap held at base '||v_base;
    if not exists (select 1 from founder_alerts where event='invite_sender_stalled' and created_at > now()-interval '24 hours') then
      insert into founder_alerts(level,event,detail,channel)
      values('crit','invite_sender_stalled',
             'Supplier invites: nothing issued since '||to_char(v_last_sent at time zone 'UTC','YYYY-MM-DD HH24:MI')
             ||'Z, but invite_enabled is true. The enqueuer is FAILING, not paused. '
             ||'Check select * from public.v_cron_failing.','system');
    end if;
  elsif v_sent7 >= 20 and v_rate >= 0.05 then
    v_new := greatest(v_base, floor(v_cur * 0.5)::int);   -- deliverability wobble: throttle down
    v_at_floor := (v_new = v_cur);
    v_note := case when v_at_floor
      then 'THROTTLE WANTED BUT ALREADY AT THE FLOOR: 7d bounce '||round(v_rate*100,1)||'% ('||v_bounced7||'/'||v_sent7
           ||') >= 5%, and the cap is already at the base of '||v_base||' so there is nothing left to reduce.'
      else 'throttle: 7d bounce '||round(v_rate*100,1)||'% ('||v_bounced7||'/'||v_sent7||') >= 5%; cap '||v_cur||'->'||v_new end;
    -- THE CASE THAT USED TO BE SILENT. Every record this function wrote lived inside
    -- `if v_new <> v_cur`, so once the cap sat at its floor a list bouncing at twice the threshold
    -- produced no row and no warning — the louder the problem, the quieter the instrument.
    if v_at_floor and not exists (select 1 from founder_alerts
                                   where event='invite_throttle_exhausted' and created_at > now()-interval '24 hours') then
      insert into founder_alerts(level,event,detail,channel)
      values('crit','invite_throttle_exhausted',
             'Supplier invites: '||v_note||' The ramp has run out of ways to protect the sending domain '
             ||'short of stopping. Hard auto-pause triggers at '||round(v_max_rate*100,1)||'% or '
             ||greatest(5, ceil(v_sent7 * v_max_rate))::int||' hard bounces in the window, and '
             ||v_bounced7||' have been recorded. Verify the list, or set app_secrets.invite_enabled '
             ||'to false yourself.','system');
    end if;
  -- ---- ADDED 11 Aug 2026: THE ACCELERATOR NOW OBEYS THE SAME NUMBER THE BRAKE DOES -------------
  -- On 2026-08-06 this function recorded "healthy: ... 7d bounce 10.0% (1/10); cap 10->20". The
  -- throttle above needs v_sent7 >= 20 before it may act; the warm-up below needed nothing at all,
  -- so a rate at twice the threshold still doubled the cap. A sample too small to justify HALVING
  -- is not a sample that licenses DOUBLING. It holds instead.
  elsif v_bounced7 > 0 and v_rate >= 0.05 then
    v_new  := v_cur;
    v_note := 'hold: 7d bounce '||round(v_rate*100,1)||'% ('||v_bounced7||'/'||v_sent7||') is at or above 5% '
           ||'but only '||v_sent7||' send(s) in 7d - too few to throttle on, far too many to warm up into. '
           ||'Cap held at '||v_cur||' rather than doubled.';
    if not exists (select 1 from founder_alerts where event='invite_ramp_held' and created_at > now()-interval '24 hours') then
      insert into founder_alerts(level,event,detail,channel)
      values('warn','invite_ramp_held',
             'Supplier-invite cap HELD at '||v_cur||' instead of warming up: '||v_note
             ||' The list needs verifying before volume increases.','system');
    end if;
  -- ----------------------------------------------------------------------------------------------
  else
    v_new := least(v_stage, v_cur * 2);                   -- healthy: warm up, at most 2x/day, capped by the volume-stage
    v_note := 'healthy: '||v_sent_total||' issued lifetime, stage '||v_stage||', 7d bounce '||round(v_rate*100,1)||'% ('||v_bounced7||'/'||greatest(v_sent7,0)||'); cap '||v_cur||'->'||v_new;
  end if;

  v_new := greatest(v_base, least(v_new, v_ceiling));

  if v_new <> v_cur then
    update app_secrets set value = v_new::text where key='invite_daily_cap';
  end if;

  -- EVERY RUN FILES A REPORT, NOT ONLY THE RUNS THAT CHANGED A NUMBER. A daily instrument that
  -- writes a row only on the days it moves something cannot answer "is this healthy today", which
  -- is the only question anyone asks it — and its silence was previously indistinguishable from
  -- not having run.
  insert into agent_runs(agent,status,counts,note,finished_at)
    values('invite_ramp', case when v_at_floor then 'error' else 'ok' end,
           jsonb_build_object('old_cap',v_cur,'new_cap',v_new,'sent_total',v_sent_total,
                              'sent_7d',v_sent7,'bounced_7d',v_bounced7,
                              'named_sent_7d',v_named7,'named_bounced_7d',v_named_b7,
                              'role_sent_7d',v_role7,'role_bounced_7d',v_role_b7,
                              'named_bounce_pct_7d',round((v_named_b7::numeric/greatest(v_named7,1))*100,1),
                              'role_bounce_pct_7d',round((v_role_b7::numeric/greatest(v_role7,1))*100,1),
                              'bounce_pct_7d',round(v_rate*100,1),'at_floor',v_at_floor),
           coalesce(v_note,'')||' | SPLIT 7d: named '||v_named_b7||'/'||v_named7
             ||' ('||round((v_named_b7::numeric/greatest(v_named7,1))*100,1)||'%), role '
             ||v_role_b7||'/'||v_role7||' ('||round((v_role_b7::numeric/greatest(v_role7,1))*100,1)
             ||'%) - a shared inbox and a named person are not one population.', now());

  if v_new < v_cur then
    insert into founder_alerts(level,event,detail,channel)
      values('warn','invite_cap_throttled','Supplier-invite cap reduced '||v_cur||'->'||v_new||' — '
             ||coalesce(v_note,'')||'. Hard auto-pause triggers at '||round(v_max_rate*100,1)
             ||'% — read live from app_secrets.invite_max_bounce_rate rather than asserted, because '
             ||'this string said 8% for a day after the value became 0.05.','system');
  end if;
  return v_new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_invite_status_on_send()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.type = 'supplier_invite' and new.status = 'sent'
     and coalesce(old.status,'') is distinct from 'sent' and new.lead_id is not null then
  -- Kernel cutover. A delivery status change on an invitation already sent. The registration itself is the class-A event; this is its provider callback, and it belongs to the run that registration opened.
  perform public.fn_kernel_source_emit('dbtrigger:public.notifications:trg_invite_status_on_send', jsonb_build_object(
    'source_ref',  new.id::text,
    'workflow_run_id', public.fn_kernel_run_for('supplier_account:' || new.lead_id::text),
    'raw_payload', jsonb_build_object('notification_id', new.id::text, 'lead_id', new.lead_id::text, 'status', new.status)));
    update public.leads
       set invite_status = 'sent'
     where id = new.lead_id and coalesce(invite_status,'') = 'queued';
  end if;
  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_invite_week_activate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if NEW.kind = 'invite_campaign_week'
     and NEW.status in ('approved','done','auto_done','accepted','resolved','closed','completed')
     and coalesce(OLD.status,'') is distinct from NEW.status then
    update invite_schedule set status='approved' where status='pending' and day >= (now() at time zone 'UTC')::date;
    update app_secrets set value='true' where key in ('invite_enabled','supplier_emails_enabled');
    insert into founder_alerts(level,event,detail,channel)
      values('info','invite_week_approved','Supplier invite week approved in OS — schedule activated and sending enabled.','system');
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_is_matchable(p_verified boolean, p_banned boolean, p_matching_blocked boolean, p_approval_status text, p_permanently_closed boolean, p_chat_strikes integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(p_verified, false)                                        -- the rule: verified
     and coalesce(p_banned, false) = false
     and coalesce(p_matching_blocked, false) = false                        -- carries expired documents,
                                                                            -- reconciled daily by
                                                                            -- fn_reconcile_doc_blocks(0)
     and coalesce(p_permanently_closed, false) = false                      -- never RFQ a closed business
     and coalesce(p_approval_status, '') not in ('action_required','rejected')
     and coalesce(p_chat_strikes, 0) < public.fn_matching_strike_limit();   -- the no-response exception
$function$


CREATE OR REPLACE FUNCTION public.fn_is_working_day(p_date date)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select extract(isodow from p_date) < 6
     and not exists (select 1 from public.public_holidays h where h.holiday_date = p_date);
$function$


CREATE OR REPLACE FUNCTION public.fn_jsonb_is_empty(j jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select j is null
      or j = 'null'::jsonb
      or (jsonb_typeof(j) = 'array'  and jsonb_array_length(j) = 0)
      or (jsonb_typeof(j) = 'object' and not exists (select 1 from jsonb_object_keys(j)))
      or (jsonb_typeof(j) = 'string' and btrim(j #>> '{}') = '');
$function$


CREATE OR REPLACE FUNCTION public.fn_jsonb_text_array(j jsonb)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case when j is null or jsonb_typeof(j) <> 'array' then null
              else (select array_agg(x) from jsonb_array_elements_text(j) x) end;
$function$


CREATE OR REPLACE FUNCTION public.fn_kb_approve(p_revision bigint, p_reviewer text, p_notes text DEFAULT NULL::text, p_publish boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_rows int := 0; v_status text; v_applied boolean := false;
begin
  select * into r from public.kb_revisions where id = p_revision;
  if r is null then return jsonb_build_object('error', 'revision not found'); end if;

  if p_publish and r.entry_kind = 'agent_knowledge' and position(' :: ' in r.entry_ref) > 0 then
    update agent_knowledge set content = r.content
     where agent_key = split_part(r.entry_ref, ' :: ', 1)
       and topic     = split_part(r.entry_ref, ' :: ', 2);
    get diagnostics v_rows = row_count;
    v_applied := v_rows > 0;
  end if;

  -- THE STATUS FOLLOWS THE EFFECT, not the intent.
  v_status := case
    when not p_publish then 'approved'
    when r.entry_kind = 'agent_knowledge' and position(' :: ' in r.entry_ref) > 0 and not v_applied
      then 'approved_unapplied'
    else 'published' end;

  update public.kb_revisions
     set status = v_status, reviewer = p_reviewer, review_notes = p_notes, decided_at = now()
   where id = p_revision;

  return jsonb_build_object(
    'ok', true, 'revision', p_revision, 'status', v_status,
    'live_rows_updated', v_rows,
    'note', case when v_status = 'approved_unapplied'
                 then 'Approved, but NOT applied: no live agent_knowledge row matches "'
                      || r.entry_ref || '". The employee''s knowledge is unchanged.'
                 else null end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_corpus_integrity()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_staged bigint; v_ckpt bigint; v_deployed bigint; v_files bigint;
        v_cats bigint; v_cats_empty bigint; v_pkgs_unchecked bigint;
        v_fts bigint; v_problems text[] := '{}';
        v_staged_distinct bigint; v_deployed_distinct bigint; v_missing bigint;
begin
  select count(*) into v_staged   from kb_stage.records;
  select coalesce(sum(rows_seen),0), count(*) into v_ckpt, v_files from kb_stage.file_hashes;
  select count(*) into v_deployed from public.kb_chunks where source_kind = 'qd_kb_pack';
  select count(*) into v_fts      from public.kb_chunks where source_kind = 'qd_kb_pack' and fts is not null;
  select count(*) into v_cats     from kb_stage.categories;
  select count(*) into v_cats_empty from kb_stage.categories c
   where not exists (select 1 from kb_stage.records r where r.category_slug = c.category_slug);
  select count(*) into v_pkgs_unchecked from kb_stage.categories c
   where not exists (select 1 from kb_stage.file_hashes f where f.package_id = c.package_id);

  -- CONTENT, NOT ROWS. A duplicate staged record does not need a duplicate chunk to be retrievable.
  select count(distinct md5(coalesce(title,'')||'|'||coalesce(content,''))) into v_staged_distinct
    from kb_stage.records;
  select count(distinct md5(coalesce(title,'')||'|'||coalesce(content,''))) into v_deployed_distinct
    from public.kb_chunks where source_kind = 'qd_kb_pack';
  select count(*) into v_missing from (
    select md5(coalesce(title,'')||'|'||coalesce(content,'')) h from kb_stage.records
    except
    select md5(coalesce(title,'')||'|'||coalesce(content,'')) from public.kb_chunks where source_kind = 'qd_kb_pack'
  ) z;

  if v_staged <> v_ckpt then
    v_problems := v_problems || format('kb_stage.records is %s but the importer checkpointed %s rows across %s files', v_staged, v_ckpt, v_files);
  end if;
  if v_missing > 0 then
    v_problems := v_problems || format('THE CORPUS IS STAGED BUT NOT DEPLOYED: %s distinct staged record(s) have no chunk in kb_chunks (staged %s rows / %s distinct, deployed %s rows / %s distinct). Every customer path reads kb_chunks.',
                                       v_missing, v_staged, v_staged_distinct, v_deployed, v_deployed_distinct);
  end if;
  if v_fts < v_deployed then
    v_problems := v_problems || format('%s deployed chunks have no full-text vector, and full text is the fallback retrieval path', v_deployed - v_fts);
  end if;
  if v_cats_empty > 0 then
    v_problems := v_problems || format('%s of %s categories in the index have no records', v_cats_empty, v_cats);
  end if;
  if v_pkgs_unchecked > 0 then
    v_problems := v_problems || format('%s packages in the index have no file checkpoint', v_pkgs_unchecked);
  end if;

  if array_length(v_problems,1) is not null then
    insert into public.agent_actions(agent, kind, title, recommendation, detail, risk, status)
    values ('knowledge_eng', 'incident',
            'Knowledge corpus integrity check failed',
            'The staged corpus and the corpus customers can actually retrieve have diverged. Re-run scripts/sql/deploy_corpus_into_kb_chunks.sql after establishing which side moved.',
            jsonb_build_object('problems', to_jsonb(v_problems), 'source', 'fn_kb_corpus_integrity'),
            'high', 'pending');
  end if;

  return jsonb_build_object(
    'ok', array_length(v_problems,1) is null,
    'staged', v_staged,
    'staged_distinct', v_staged_distinct,
    'checkpointed', v_ckpt,
    'files', v_files,
    'deployed_to_kb_chunks', v_deployed,
    'deployed_distinct', v_deployed_distinct,
    'staged_records_with_no_chunk', v_missing,
    'duplicate_staged_records', v_staged - v_staged_distinct,
    'deployed_with_fts', v_fts,
    'categories', v_cats,
    'categories_without_records', v_cats_empty,
    'packages_without_checkpoint', v_pkgs_unchecked,
    'problems', to_jsonb(v_problems),
    'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_gov_approve(p_kind text, p_id text, p_by text DEFAULT 'founder'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n int;
begin
  if p_kind = 'regulation' then
    update regulations set approved_at = now(), approved_by = p_by where id::text = p_id and approved_at is null;
    get diagnostics n = row_count;
    perform kb_sync();
    update agent_actions set status='approved', decided_at=now(), decided_by=p_by
      where kind='knowledge_approval' and detail->>'ref'=p_id and detail->>'kind'='regulation' and status in ('pending','needs_review');
    return jsonb_build_object('approved', n, 'kind', p_kind, 'id', p_id);
  end if;
  return jsonb_build_object('error','unsupported_kind', 'kind', p_kind);
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_next_question(p_catalog_num integer, p_answered jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_scope jsonb; v_next jsonb; v_missing jsonb; v_total int; v_answered int; v_blocking int;
begin
  -- scope = the knowledge subcategories this live catalogue route maps to
  with scope as (
    select m.package_slug, m.subcategory_slug, m.priority
    from public.kb_operational_route_map m where m.catalog_num = p_catalog_num
  ),
  qs as (
    select q.question_id, q.source_question_id, q.field_key, q.question_en, q.question_ar,
           q.answer_type, q.allowed_values, q.unit, q.mandatory, q.on_missing, q.impact,
           q.answerable_by_documents, q.category_slug, q.subcategory_slug,
           coalesce((q.activation->>'order')::int, 999) as ord
    from kb_stage.questions q
    join scope s on s.package_slug = q.category_slug and s.subcategory_slug = q.subcategory_slug
    where q.field_key is not null
  ),
  -- One question per field_key across all mapped subcategories. A composite route (signage maps to
  -- 3 packages) otherwise asks "which emirate?" seven times.
  dedup as (
    select distinct on (field_key) * from qs order by field_key, mandatory desc, ord, question_id
  ),
  open as (
    select * from dedup
    where not (p_answered ? field_key)
       or nullif(btrim(coalesce(p_answered->>field_key, '')), '') is null
  )
  select
    (select to_jsonb(o) from open o order by o.mandatory desc, o.ord, o.question_id limit 1),
    (select coalesce(jsonb_agg(jsonb_build_object('field_key', o.field_key, 'mandatory', o.mandatory,
                                                  'on_missing', o.on_missing) order by o.mandatory desc, o.ord), '[]'::jsonb)
       from open o),
    (select count(*) from dedup where mandatory),
    (select count(*) from dedup d where d.mandatory and p_answered ? d.field_key
        and nullif(btrim(coalesce(p_answered->>d.field_key,'')),'') is not null),
    (select count(*) from open o where o.mandatory
        and (o.on_missing is null or o.on_missing ilike 'block%' or o.on_missing ilike '%block%'))
  into v_next, v_missing, v_total, v_answered, v_blocking;

  return jsonb_build_object(
    'catalog_num', p_catalog_num,
    'next_question', v_next,
    'missing', v_missing,
    'mandatory_total', coalesce(v_total, 0),
    'mandatory_answered', coalesce(v_answered, 0),
    'completeness', case when coalesce(v_total,0) = 0 then null
                         else round(coalesce(v_answered,0)::numeric / v_total, 3) end,
    -- The single auditable gate the external reviewer asked for: one boolean, one query, one place.
    'dispatch_eligible', coalesce(v_blocking, 0) = 0,
    'blocking_count', coalesce(v_blocking, 0),
    'source', 'kb_stage.questions (deterministic, no model call)');
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_reconcile()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_stripped int:=0; v_aliased int:=0; v_uncat int; v_noncanon int;
begin
  with upd as (
    update public.kb_chunks c set category = substring(c.category from 5)
    where c.category like 'cat:%'
      and ( substring(c.category from 5) in (select slug from public.category_agents where active)
         or substring(c.category from 5) in (select category from public.category_specs) )
    returning 1
  ) select count(*) into v_stripped from upd;

  with oneone as (
    select category, min(maps_to) as target
    from public.kb_category_aliases group by category having count(distinct maps_to)=1
  ), upd2 as (
    update public.kb_chunks c set category = o.target
    from oneone o where c.category = o.category and c.category <> o.target
    returning 1
  ) select count(*) into v_aliased from upd2;

  select count(*) into v_uncat from public.kb_chunks where category is null or category='';
  select count(distinct category) into v_noncanon from public.kb_chunks
    where category is not null and category<>'' and category not like 'cat:%'
      and category not in (select slug from public.category_agents where active)
      and category not in (select category from public.category_specs);

  return jsonb_build_object('cat_prefix_stripped',v_stripped,'alias_remapped',v_aliased,
    'uncategorized_left',v_uncat,'noncanonical_categories_left',v_noncanon,
    'note','Normalized kb_chunks categories: stripped '||v_stripped||' cat: prefix(es), remapped '||v_aliased||' via curated 1:1 aliases. '||v_uncat||' chunk(s) remain uncategorized (global knowledge — still semantically retrievable).');
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_retrieve(p_catalog_num integer, p_query text, p_limit integer DEFAULT 6, p_modules text[] DEFAULT NULL::text[])
 RETURNS TABLE(record_id text, title text, content text, module text, record_type text, authority text, validation_status text, confidence numeric, source_ids jsonb, escalate boolean, rank real)
 LANGUAGE sql
 STABLE
AS $function$
with gate as (
  select coalesce((public.fn_kb_route_activation_blocked(p_catalog_num)->>'blocked')::boolean, true) as blocked
), scope as (
  select m.package_slug, m.subcategory_slug from public.kb_operational_route_map m, gate
  where m.catalog_num = p_catalog_num and not gate.blocked
), q as (
  select to_tsquery('simple',
           nullif(array_to_string(
             array(select w || ':*' from unnest(regexp_split_to_array(lower(coalesce(p_query,'')), '[^a-z0-9؀-ۿ]+')) w
                   where length(w) >= 3), ' | '), '')) tsq
)
select r.record_id, r.title, left(r.content, 4000), r.module, r.record_type, r.authority,
       r.validation_status, r.confidence, r.source_ids,
       (r.escalation_rule is not null or r.module = 'uae_regulations') as escalate,
       ts_rank(to_tsvector('simple', r.title || ' ' || left(r.content, 4000)), q.tsq) as rank
from kb_stage.records r
join scope s on s.package_slug = r.category_slug and s.subcategory_slug = r.subcategory_slug
cross join q
where r.validation_status in ('reviewed', 'source_verified', 'approved')
  and (p_modules is null or r.module = any (p_modules))
  and (q.tsq is null or to_tsvector('simple', r.title || ' ' || left(r.content, 4000)) @@ q.tsq)
order by rank desc, r.confidence desc nulls last, r.record_id
limit greatest(p_limit, 1);
$function$


CREATE OR REPLACE FUNCTION public.fn_kb_route(p_text text, p_limit integer DEFAULT 5)
 RETURNS TABLE(catalog_num integer, live_slug text, live_name text, score numeric, matched_aliases jsonb, languages text[])
 LANGUAGE sql
 STABLE
AS $function$
with q as (select ' ' || kb_norm(p_text) || ' ' as t),
hits as (
  select a.catalog_num, a.alias, a.language, a.weight, a.negative,
         array_length(string_to_array(a.alias_norm, ' '), 1) as words
  from public.kb_operational_alias a, q
  where length(a.alias_norm) >= 3
    and q.t like '%' || ' ' || a.alias_norm || ' ' || '%'
),
scored as (
  select h.catalog_num,
         sum(case when h.negative then -1 else 1 end * h.weight * h.words) as score,
         jsonb_agg(jsonb_build_object('alias', h.alias, 'lang', h.language,
                                      'w', h.weight, 'words', h.words, 'neg', h.negative)
                   order by h.weight * h.words desc) as matched,
         array_agg(distinct h.language) as langs
  from hits h group by h.catalog_num
)
select s.catalog_num, c.slug, c.name, s.score, s.matched, s.langs
from scored s join public.catalog_supplier_categories c on c.num = s.catalog_num
where s.score > 0
order by s.score desc, s.catalog_num
limit greatest(p_limit, 1);
$function$


CREATE OR REPLACE FUNCTION public.fn_kb_route_activation_blocked(p_catalog_num integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_reasons text[] := '{}';
begin
  select * into r from public.kb_operational_route where catalog_num = p_catalog_num;
  if not found then
    return jsonb_build_object('blocked', true, 'reasons', array['no such route']);
  end if;

  if r.regulatory_coverage_status <> 'confirmed_none'
     and r.regulatory_coverage_status <> 'confirmed_covered' then
    v_reasons := v_reasons || ('regulatory coverage is ' || r.regulatory_coverage_status)::text;
  end if;

  if not exists (select 1 from public.kb_operational_route_map m where m.catalog_num = p_catalog_num) then
    v_reasons := v_reasons || 'no mapped subcategory'::text;
  end if;

  if not exists (select 1 from public.kb_operational_alias a
                  where a.catalog_num = p_catalog_num and a.language = 'ar') then
    v_reasons := v_reasons || 'no Arabic alias'::text;
  end if;

  return jsonb_build_object('blocked', array_length(v_reasons, 1) is not null,
                            'reasons', coalesce(v_reasons, '{}'),
                            'regulatory_coverage_status', r.regulatory_coverage_status,
                            'route', r.catalog_name);
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_route_decide(p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v jsonb; top numeric; second numeric; n int; v_action text; v_conf numeric; v_reason text;
  v_cat int; v_rules jsonb; v_dropped int := 0;
begin
  -- deactivated routes are removed BEFORE scoring, so a blocked route cannot win, tie, or make
  -- the decision look ambiguous
  select coalesce(jsonb_agg(to_jsonb(r) order by r.score desc), '[]'::jsonb) into v
  from (select * from public.fn_kb_route(p_text, 5)) r
  where not coalesce((public.fn_kb_route_activation_blocked(r.catalog_num)->>'blocked')::boolean, true);

  select count(*) into v_dropped
  from (select * from public.fn_kb_route(p_text, 5)) r
  where coalesce((public.fn_kb_route_activation_blocked(r.catalog_num)->>'blocked')::boolean, true);

  n := jsonb_array_length(v);
  if n = 0 then
    return jsonb_build_object(
      'action', 'ask_clarifying_question', 'confidence', 0, 'top_score', 0,
      'candidates', '[]'::jsonb, 'catalog_num', null, 'multi_category', false,
      'reason', case when v_dropped > 0
                     then format('%s matching route(s) are not activated for live use', v_dropped)
                     else 'no deterministic alias matched the customer wording' end,
      'clarification', 'Could you tell me in your own words what you need supplied or done? For example "waterproof a warehouse roof" or "supply 200 office chairs".',
      'rules', '[]'::jsonb, 'deactivated_candidates', v_dropped,
      'normalised', public.kb_norm(p_text));
  end if;

  top    := (v->0->>'score')::numeric;
  second := case when n > 1 then (v->1->>'score')::numeric else 0 end;
  v_conf := round(top / nullif(top + second, 0), 3);

  if top < 3 then
    v_action := 'ask_clarifying_question';
    v_reason := 'only a weak fragment matched; not enough to act on';
  elsif n = 1 or top >= second * 1.5 then
    v_action := 'route_or_ask_scope_details';
    v_reason := case when n = 1 then 'single deterministic alias match'
                     else 'leading route is decisively ahead of the runner-up' end;
  else
    v_action := 'ask_clarifying_question';
    v_reason := 'leading routes are too close to call';
  end if;

  v_cat := case when v_action = 'route_or_ask_scope_details' then (v->0->>'catalog_num')::int end;

  select coalesce(jsonb_agg(jsonb_build_object(
           'rule_id', d.rule_id, 'type', d.rule_type, 'priority', d.priority,
           'when', d.when_json, 'then', d.then_json,
           'requires_human_review', d.requires_human_review,
           'confidence', d.confidence) order by d.priority desc nulls last, d.rule_id), '[]'::jsonb)
    into v_rules
    from (select * from kb_stage.decision_rules dr
           where v_cat is not null
             and dr.category_slug in (select m.package_slug from public.kb_operational_route_map m
                                       where m.catalog_num = v_cat)
           order by dr.priority desc nulls last, dr.rule_id
           limit 5) d;

  return jsonb_build_object(
    'action', v_action,
    'confidence', v_conf,
    'top_score', top,
    'candidates', v,
    'catalog_num', v_cat,
    'multi_category', (n > 1 and second >= top * 0.75),
    'reason', v_reason,
    'clarification', case when v_action = 'ask_clarifying_question' then
        'Just so this reaches the right suppliers - is this closer to "' || (v->0->>'live_name') ||
        '" or "' || coalesce(v->1->>'live_name', 'something else') || '"?' end,
    'rules', coalesce(v_rules, '[]'::jsonb),
    'deactivated_candidates', v_dropped,
    'normalised', public.kb_norm(p_text));
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_route_test_run(p_limit integer DEFAULT 400)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t record; r jsonb;
        v_ran int := 0; v_pass int := 0; v_fail int := 0; v_reg int := 0; v_regs text[] := '{}';
begin
  for t in
    select x.test_id, x.input, x.expected_action, (x.last_result->>'action') prev_action
      from public.kb_operational_route_test x
     order by x.last_run_at nulls first, x.test_id
     limit greatest(coalesce(p_limit, 400), 1)
  loop
    begin
      r := public.fn_kb_route_decide(t.input);
    exception when others then
      r := jsonb_build_object('action', 'error', 'error', left(SQLERRM, 300));
    end;

    update public.kb_operational_route_test
       set last_result = r, last_run_at = now()
     where test_id = t.test_id;

    v_ran := v_ran + 1;
    if (r->>'action') = t.expected_action then
      v_pass := v_pass + 1;
    else
      v_fail := v_fail + 1;
      -- a REGRESSION is a case that used to pass and no longer does. The cases that were already
      -- failing on 2 Aug are failures, not regressions, and must not page anyone every hour.
      if t.prev_action is not distinct from t.expected_action then
        v_reg := v_reg + 1; v_regs := v_regs || t.test_id;
      end if;
    end if;
  end loop;

  if v_reg > 0 then
    insert into public.agent_actions(agent, kind, title, recommendation, detail, risk, status)
    values ('knowledge_eng', 'incident',
            format('%s operational route test(s) regressed', v_reg),
            'A route that used to resolve correctly no longer does. Check kb_operational_alias and kb_operational_route_map for the affected catalog numbers.',
            jsonb_build_object('test_ids', to_jsonb(v_regs), 'source', 'fn_kb_route_test_run'),
            'medium', 'pending');
  end if;

  return jsonb_build_object('ran', v_ran, 'passed', v_pass, 'failed', v_fail,
                            'regressions', v_reg, 'regressed', to_jsonb(v_regs), 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_submit_revision(p_kind text, p_ref text, p_content text, p_author text DEFAULT 'agent'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare id bigint;
begin
  insert into public.kb_revisions(entry_kind,entry_ref,version,content,status,author,ai_validation)
  values (p_kind,p_ref, public._kb_next_ver(p_kind,p_ref), p_content, 'in_review', p_author, public.fn_kb_validate(p_content))
  returning id into id;
  return id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_kb_validate(p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare flags text[]:='{}'; ok boolean:=true;
begin
  if length(coalesce(p_content,'')) < 40 then flags:=array_append(flags,'too_short'); ok:=false; end if;
  if p_content !~* '(source|per |according to|standard|code|regulation|SIRA|DCD|DEWA|ISO|IEC|BS |EN |NFPA|Estidama|ESMA|[0-9])' then
     flags:=array_append(flags,'no_citation_or_specifics'); ok:=false; end if;
  if p_content ~* '(always|never|guaranteed|100%|best in the world)' then flags:=array_append(flags,'absolute_claim_review'); end if;
  return jsonb_build_object('passed',ok,'flags',to_jsonb(flags),'checked_at',now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_all_boards()
 RETURNS TABLE(board text, check_name text, expected text, actual text, ok boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  b record;
begin
  for b in
    select p.proname as fn
      from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
       and p.pronargs = 0
       and p.proargnames @> array['check_name','expected','actual','ok']
       -- IT DISCOVERED ITSELF. Written and applied without this line, and the first call recursed
       -- until the statement timeout killed it: this function returns exactly the shape it searches
       -- for, so it found itself, called itself, found itself again. Left as the reason the
       -- exclusion is by name rather than by a comment saying "don't add recursive boards".
       and p.proname <> 'fn_kernel_all_boards'
     order by p.proname
  loop
    board := b.fn;
    begin
      return query execute format(
        'select %L::text, x.check_name, x.expected, x.actual, x.ok from public.%I() x', b.fn, b.fn);
    exception when others then
      -- A BOARD THAT RAISES IS A FAILURE, NOT AN ABSENCE. fn_phase_c_invariants once raised 22007
      -- on every call after a column retype, which also took out fn_phase_c_baseline_drift. If that
      -- happens again it must read as red here rather than as a board that quietly returned nothing.
      check_name := 'BOARD_RAISED';
      expected   := 'the board returns rows';
      actual     := sqlstate || ' ' || sqlerrm;
      ok         := false;
      return next;
    end;
  end loop;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_assert_in_kernel(p_who text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if coalesce(current_setting('kernel.in_kernel', true), '') <> 'on' then
    raise exception
      '% is a kernel-internal primitive and was called from outside the kernel', p_who
      using errcode = '23514',
            hint = 'Call the canonical service instead. public.kernel_retired_path names the '
                || 'replacement for every retired path.';
  end if;
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_assert_not_in_delivery(p_writer text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if public.fn_kernel_in_delivery() then
    raise exception
      're-entry refused: % is a kernel writer and was called from event delivery', p_writer
      using errcode = '23514',
            hint = 'A domain event records a state change that already happened. A consumer may '
                || 'notify, project or fan out; it may not call the producer.';
  end if;
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_cancel(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_kind     text := coalesce(p_input->>'subject_kind', '');
  v_ref      text := coalesce(p_input->>'subject_ref', '');
  v_op       text := coalesce(nullif(p_input->>'op',''), 'cancel');
  v_reason   text := coalesce(nullif(btrim(p_input->>'reason'),''), '');
  v_actor    text := coalesce(p_input->>'actor', '');
  v_terminal text;
  v_command  bigint;
  v_runs     bigint[] := '{}';
  v_founder  text;
  r          record;
  v_trace    bigint;
  n_cmd int := 0; n_plan int := 0; n_run int := 0; n_step int := 0;
  n_task int := 0; n_handoff int := 0; n_outbox int := 0; n_trace int := 0;
  v_left_tasks int; v_left_runs int; v_left_steps int; v_left_handoffs int; v_left_outbox int;
begin
  if v_op not in ('cancel','supersede') then
    raise exception 'fn_kernel_cancel: op must be cancel or supersede, got %', v_op using errcode = '22023';
  end if;
  v_terminal := case when v_op = 'cancel' then 'cancelled' else 'superseded' end;

  -- A cancellation with no stated reason is an unexplained disappearance in the audit trail.
  if v_reason = '' then
    raise exception 'fn_kernel_cancel: a reason is required' using errcode = '23514';
  end if;

  -- ---- resolve the subject ------------------------------------------------------------------
  if v_kind = 'founder_command' then
    -- Only the founder may cancel his own instruction. K0 put the one verifier in the estate;
    -- this is the second caller of it, not a second copy of it.
    v_founder := public.fn_phase_c_require_founder(v_actor);
    v_command := nullif(regexp_replace(v_ref, '\D', '', 'g'), '')::bigint;
    if v_command is null or not exists (select 1 from public.founder_command where command_id = v_command) then
      return jsonb_build_object('ok', false, 'error', 'not_found', 'subject_ref', v_ref);
    end if;
    select coalesce(array_agg(run_id), '{}') into v_runs
      from public.phase_c_workflow_run where command_id = v_command;

  elsif v_kind = 'workflow_run' then
    -- An autonomous run has no founder in the loop; the actor is recorded, not authenticated as
    -- the founder, because requiring a founder here would make autonomous cleanup impossible.
    v_runs := array[nullif(regexp_replace(v_ref, '\D', '', 'g'), '')::bigint];
    if v_runs[1] is null or not exists (select 1 from public.phase_c_workflow_run where run_id = v_runs[1]) then
      return jsonb_build_object('ok', false, 'error', 'not_found', 'subject_ref', v_ref);
    end if;
    select command_id into v_command from public.phase_c_workflow_run where run_id = v_runs[1];

  else
    raise exception 'fn_kernel_cancel: subject_kind must be founder_command or workflow_run, got %',
      v_kind using errcode = '22023';
  end if;

  -- ---- (a) the command --------------------------------------------------------------------
  if v_command is not null then
    if exists (select 1 from public.founder_command
                where command_id = v_command and state not in ('cancelled','superseded','completed')) then
      if not exists (select 1 from public.phase_c_command_transition t
                      join public.founder_command c on c.command_id = v_command
                     where t.from_state = c.state and t.to_state = v_terminal) then
        return jsonb_build_object('ok', false, 'error', 'transition_not_permitted',
          'from', (select state from public.founder_command where command_id = v_command),
          'to', v_terminal,
          'message', 'The command state model does not allow this move. Nothing was cancelled.');
      end if;
      update public.founder_command
         set state = v_terminal,
             superseded_by = case when v_op = 'supersede'
                                  then nullif(regexp_replace(coalesce(p_input->>'superseded_by',''), '\D','','g'),'')::bigint
                                  else superseded_by end,
             closed_at = now()
       where command_id = v_command;
      n_cmd := 1;
    end if;

    -- ---- (b) the command plan --------------------------------------------------------------
    update public.founder_command_plan
       set state = v_terminal, closed_at = now()
     where command_id = v_command and state = 'active';
    get diagnostics n_plan = row_count;
  end if;

  -- ---- (c) the workflow runs --------------------------------------------------------------
  for r in select * from public.phase_c_workflow_run
            where run_id = any(v_runs)
              and state not in ('cancelled','superseded','completed','failed') loop
    v_trace := public.fn_phase_c_trace_write('TRACE-WORKFLOW', jsonb_build_object(
      'subject_kind','workflow_run', 'subject_ref', r.run_id::text, 'run_id', r.run_id,
      'command_id', r.command_id, 'actor_role_id', coalesce(nullif(v_founder,''),'system'),
      'system_actor_id','system.workflow_engine',
      'state_before', r.state, 'state_after', v_terminal,
      'evidence_refs', jsonb_build_array(jsonb_build_object('reason', v_reason, 'actor', v_actor)),
      'status','sealed'));
    update public.phase_c_workflow_run
       set state = v_terminal, closed_at = now(),
           closure_evidence = coalesce(closure_evidence,'{}'::jsonb)
             || jsonb_build_object('cancelled_reason', v_reason, 'cancelled_by', v_actor,
                                   'cancelled_at', now(), 'trace_id', v_trace)
     where run_id = r.run_id;
    n_run := n_run + 1;
  end loop;

  -- ---- (d) the open step runs -------------------------------------------------------------
  for r in select * from public.phase_c_workflow_step_run
            where run_id = any(v_runs)
              and state not in ('cancelled','completed','failed','superseded') loop
    v_trace := public.fn_phase_c_trace_write('TRACE-STEP', jsonb_build_object(
      'subject_kind','step_run', 'subject_ref', r.step_run_id::text,
      'run_id', r.run_id, 'step_run_id', r.step_run_id,
      'actor_role_id', r.accountable_role_id, 'system_actor_id','system.workflow_engine',
      'state_before', r.state, 'state_after', v_terminal,
      'evidence_refs', jsonb_build_array(jsonb_build_object('reason', v_reason, 'actor', v_actor)),
      'status','sealed'));
    update public.phase_c_workflow_step_run
       set state = v_terminal, finished_at = now(), trace_id = coalesce(trace_id, v_trace),
           failure_reason = case when failure_reason = '' then 'cancelled: ' || v_reason else failure_reason end
     where step_run_id = r.step_run_id;
    n_step := n_step + 1;
  end loop;

  -- ---- (e) the tasks, BY COMMAND AND BY RUN ------------------------------------------------
  -- The old sweep matched on command_id alone. Task 794 carries command_id NULL and run_id 96, which
  -- is exactly how it survived its own command's cancellation.
  for r in select * from public.phase_c_task
            where ((v_command is not null and command_id = v_command) or run_id = any(v_runs))
              and state in ('queued','assigned','accepted','in_progress','blocked') loop
    v_trace := public.fn_phase_c_trace_write('TRACE-TASK', jsonb_build_object(
      'subject_kind','task', 'subject_ref', r.task_id::text, 'task_id', r.task_id,
      'command_id', r.command_id, 'run_id', r.run_id,
      'actor_role_id', coalesce(nullif(v_founder,''),'system'),
      'manager_role_id', r.manager_role_id, 'system_actor_id','system.command_router',
      'state_before', r.state, 'state_after', v_terminal,
      'evidence_refs', jsonb_build_array(jsonb_build_object('reason', v_reason, 'actor', v_actor)),
      'status','sealed'));
    update public.phase_c_task
       set state = v_terminal, closed_at = now(), trace_id = v_trace
     where task_id = r.task_id;
    n_task := n_task + 1;
  end loop;

  -- ---- (f) the pending handoffs ------------------------------------------------------------
  for r in select * from public.phase_c_handoff_run
            where run_id = any(v_runs) and status = 'open' loop
    v_trace := public.fn_phase_c_trace_write('TRACE-HANDOFF', jsonb_build_object(
      'subject_kind','handoff_run', 'subject_ref', r.handoff_run_id::text, 'run_id', r.run_id,
      'actor_role_id', r.sending_role_id, 'system_actor_id','system.workflow_engine',
      'state_before', r.status, 'state_after','cancelled',
      'evidence_refs', jsonb_build_array(jsonb_build_object('reason', v_reason, 'actor', v_actor)),
      'status','sealed'));
    update public.phase_c_handoff_run
       set status = 'cancelled', decided_at = now(), trace_id = coalesce(trace_id, v_trace)
     where handoff_run_id = r.handoff_run_id;
    n_handoff := n_handoff + 1;
  end loop;

  -- ---- (g) the undelivered outbox rows -----------------------------------------------------
  -- Delivered rows are NOT touched: a delivered event is a fact that happened, and rewriting it
  -- would be falsifying history. Only what has not yet left the queue is stopped.
  -- ROOT CAUSE 2. This matched on payload->>'run_id'. Only ONE producer writes that key: the
  -- step-complete event. The workflow-START event writes 'workflow_run_id', so every start event
  -- survived cancellation as 'pending' and was delivered afterwards. The leftover check below used
  -- the SAME predicate as this write, so it counted nothing left behind and the function reported
  -- success. Relationships are columns now, and the check reads the same columns this writes.
  update public.phase_c_event_outbox o
     set status = 'superseded',
         last_error = 'CANCELLED ' || to_char(now(),'YYYY-MM-DD') || ': ' || v_reason
                   || ' (fn_kernel_cancel, subject ' || v_kind || ':' || v_ref || ')'
   where o.status in ('pending','claimed','retry_wait')
     and ( (v_command is not null and o.command_id = v_command)
        or o.workflow_run_id = any(v_runs)
        or o.step_run_id in (select sr.step_run_id from public.phase_c_workflow_step_run sr
                              where sr.run_id = any(v_runs))
        or o.task_id in (select t.task_id from public.phase_c_task t
                          where (v_command is not null and t.command_id = v_command)
                             or t.run_id = any(v_runs)) );
  get diagnostics n_outbox = row_count;

  -- ---- (h) seal every open trace whose subject was just closed -----------------------------
  update public.phase_c_trace
     set status = 'sealed', sealed_at = now()
   where sealed_at is null
     and ( (v_command is not null and command_id = v_command)
        or run_id = any(v_runs)
        or task_id in (select task_id from public.phase_c_task
                        where (v_command is not null and command_id = v_command)
                           or run_id = any(v_runs)) );
  get diagnostics n_trace = row_count;

  -- ---- (i) THE POSTCONDITION ---------------------------------------------------------------
  -- "A cancelled command may leave no queued derived work." Asserted, not asserted about.
  select count(*) into v_left_tasks from public.phase_c_task
   where ((v_command is not null and command_id = v_command) or run_id = any(v_runs))
     and state in ('queued','assigned','accepted','in_progress','blocked');
  select count(*) into v_left_runs from public.phase_c_workflow_run
   where run_id = any(v_runs) and state not in ('cancelled','superseded','completed','failed');
  select count(*) into v_left_steps from public.phase_c_workflow_step_run
   where run_id = any(v_runs) and state not in ('cancelled','completed','failed','superseded');
  select count(*) into v_left_handoffs from public.phase_c_handoff_run
   where run_id = any(v_runs) and status = 'open';
  select count(*) into v_left_outbox from public.phase_c_event_outbox o
   where o.status in ('pending','claimed','retry_wait')
     and ( (v_command is not null and o.command_id = v_command)
        or o.workflow_run_id = any(v_runs)
        or o.step_run_id in (select sr.step_run_id from public.phase_c_workflow_step_run sr
                              where sr.run_id = any(v_runs))
        or o.task_id in (select t.task_id from public.phase_c_task t
                          where (v_command is not null and t.command_id = v_command)
                             or t.run_id = any(v_runs)) );

  if v_left_tasks + v_left_runs + v_left_steps + v_left_handoffs + v_left_outbox > 0 then
    raise exception
      'fn_kernel_cancel left derived work behind: tasks=% runs=% steps=% handoffs=% outbox=%',
      v_left_tasks, v_left_runs, v_left_steps, v_left_handoffs, v_left_outbox
      using errcode = '23514',
            hint = 'The propagation missed a table. Nothing was cancelled — the transaction is rolled back.';
  end if;

  return jsonb_build_object('ok', true, 'op', v_op, 'subject_kind', v_kind, 'subject_ref', v_ref,
    'command_id', v_command, 'run_ids', to_jsonb(v_runs), 'actor', v_actor, 'reason', v_reason,
    'closed', jsonb_build_object('command', n_cmd, 'plan', n_plan, 'workflow_runs', n_run,
      'step_runs', n_step, 'tasks', n_task, 'handoffs', n_handoff, 'outbox_superseded', n_outbox,
      'traces_sealed', n_trace),
    'queued_derived_work_remaining', 0);
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_component_exposure_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'cron', 'pg_temp'
AS $function$
with pop as (
  select c.component_id, c.component_type, c.classification, c.activation_state,
         c.external_entry, c.mutates_state, r.d
    from public.phase_c_component_exposure_scope s
    join public.phase_c_component c using (component_id),
         lateral public.fn_kernel_component_reachability(c.component_id) r(d)
), qd as (   -- QuotesDone components only; extension internals are counted on their own line
  select * from pop where d->>'derived_classification' <> 'EXTENSION_OWNED_EXCLUDED'
)
select 'deferred_or_inactive_but_reachable'::text,
       '0 of ' || (select count(*) from qd)::text,
       (select count(*) from qd
         where classification in ('DEFERRED_RUNTIME_IMPLEMENTATION','INACTIVE_HISTORICAL',
                                  'INTENTIONALLY_INACTIVE','REPAIR_BEFORE_REACTIVATION')
           and (d->>'reachable')::boolean)::text
         || ' of ' || (select count(*) from qd)::text,
       (select count(*) from qd
         where classification in ('DEFERRED_RUNTIME_IMPLEMENTATION','INACTIVE_HISTORICAL',
                                  'INTENTIONALLY_INACTIVE','REPAIR_BEFORE_REACTIVATION')
           and (d->>'reachable')::boolean) = 0
union all
select 'deferred_or_inactive_but_unexpectedly_active'::text,
       '0 of ' || (select count(*) from qd)::text,
       (select count(*) from qd
         where activation_state = 'inactive' and (d->>'unexpectedly_active')::boolean)::text
         || ' of ' || (select count(*) from qd)::text,
       (select count(*) from qd
         where activation_state = 'inactive' and (d->>'unexpectedly_active')::boolean) = 0
union all
select 'state_changing_and_reachable_unauthenticated'::text,
       '0 of ' || (select count(*) from qd where mutates_state)::text
         || ' (except the recorded legal exception)',
       (select count(*) from qd
         where mutates_state and (d->>'reachable_unauthenticated')::boolean
           and component_id <> 'edge:pdpl_request')::text
         || ' of ' || (select count(*) from qd where mutates_state)::text
         || ' state-changing; edge:pdpl_request excluded — UAE PDPL Art. 13-17 require the '
         || 'data-subject request channel to be usable without an account',
       (select count(*) from qd
         where mutates_state and (d->>'reachable_unauthenticated')::boolean
           and component_id <> 'edge:pdpl_request') = 0
union all
select 'external_entry_disagrees_with_derivation'::text,
       '0 of ' || (select count(*) from qd)::text,
       (select count(*) from qd where external_entry is distinct from d->>'derived_external_entry')::text
         || ' of ' || (select count(*) from qd)::text
         || ' (recorded vocabulary no / unauthenticated_only / yes)',
       (select count(*) from qd where external_entry is distinct from d->>'derived_external_entry') = 0
union all
select 'extension_owned_excluded_from_the_headline'::text,
       'reported separately, never counted as deferred QuotesDone components',
       (select count(*) from pop where d->>'derived_classification' = 'EXTENSION_OWNED_EXCLUDED')::text
         || ' of ' || (select count(*) from pop)::text
         || ' extension internals excluded (pg_depend deptype ''e'')',
       true;
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_component_reachability(p_component_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'cron', 'pg_temp'
AS $function$
declare
  c              public.phase_c_component%rowtype;
  v_oid          oid;
  v_slug         text;
  v_jobid        bigint;
  v_ext          boolean := false;
  v_vec          jsonb   := '{}'::jsonb;
  v_names        text[]  := '{}';
  v_txt          text;
  v_bool         boolean;
  v_class        text;
  v_state        text;
  v_decided      text;
  v_reachable    boolean := false;
  v_unauth       boolean := false;
  v_unexpected   boolean := false;
  v_external     text;
  -- a deployed 410 responder: it answers HTTP and executes nothing
  v_retired_stub boolean := false;
begin
  select * into c from public.phase_c_component where component_id = p_component_id;
  if not found then
    return jsonb_build_object('component_id', p_component_id, 'derived_classification','UNDERIVABLE',
      'why','no row in phase_c_component with this id');
  end if;

  -- ---- resolve the physical object -------------------------------------------------------
  if c.component_type = 'database_function' then
    select p.oid into v_oid
      from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = split_part(c.source_path_or_db_object,'.',1)
       and p.proname = split_part(c.source_path_or_db_object,'.',2)
       -- the registry writes the signature without DEFAULT clauses; strip them to compare
       and c.component_id = 'dbfn:' || p.proname || '(' ||
             regexp_replace(pg_get_function_arguments(p.oid),
                            ' DEFAULT .*?(?=(, [a-zA-Z_"]+ )|$)', '', 'g') || ')'
     limit 1;
  elsif c.component_type = 'edge_function' then
    v_slug := regexp_replace(c.component_id, '^edge:', '');
  elsif c.component_type = 'cron_job' then
    begin
      v_jobid := (regexp_replace(c.source_path_or_db_object, '^cron\.job/', ''))::bigint;
    exception when others then v_jobid := null; end;
  end if;

  if c.component_type not in ('database_function','edge_function','cron_job')
     or (c.component_type = 'database_function' and v_oid is null)
     or (c.component_type = 'cron_job' and v_jobid is null) then
    return jsonb_build_object(
      'component_id', c.component_id, 'component_type', c.component_type,
      'extension_owned', false, 'vectors', '{}'::jsonb,
      'reachable', null, 'reachable_unauthenticated', null, 'unexpectedly_active', null,
      'derived_classification','UNDERIVABLE', 'derived_activation_state', null,
      'decided_by','no measurable object: this component type carries no catalogue, platform or '
                 ||'repository vector that this derivation can read');
  end if;

  -- ---- extension-owned objects are not QuotesDone components ------------------------------
  if v_oid is not null then
    select true into v_ext from pg_depend d
     where d.classid = 'pg_proc'::regclass and d.objid = v_oid and d.deptype = 'e' limit 1;
    v_ext := coalesce(v_ext, false);
  end if;
  if v_ext then
    select e.extname into v_txt
      from pg_depend d join pg_extension e on e.oid = d.refobjid
     where d.classid = 'pg_proc'::regclass and d.objid = v_oid and d.deptype = 'e' limit 1;
    return jsonb_build_object(
      'component_id', c.component_id, 'component_type', c.component_type,
      'extension_owned', true, 'vectors', '{}'::jsonb,
      'reachable', null, 'reachable_unauthenticated', null, 'unexpectedly_active', false,
      'derived_classification','EXTENSION_OWNED_EXCLUDED', 'derived_activation_state', null,
      'decided_by', format('pg_depend deptype ''e'' on extension %L — an extension internal, never '
                        || 'a QuotesDone component; excluded from the deferred population', v_txt));
  end if;

  -- ---- vector: HTTP deployment + verify_jwt (probe) ---------------------------------------
  select p.present, p.evidence into v_bool, v_txt
    from public.phase_c_component_probe p
   where p.component_id = c.component_id and p.vector = 'http_deployed';
  if v_bool is not null then
    v_vec := v_vec || jsonb_build_object('http_deployed', jsonb_build_object('present', v_bool, 'evidence', v_txt));
    if v_bool then v_names := v_names || 'http_deployed'::text; end if;
  end if;
  select p.present, p.evidence into v_bool, v_txt
    from public.phase_c_component_probe p
   where p.component_id = c.component_id and p.vector = 'http_verify_jwt';
  if v_bool is not null then
    v_vec := v_vec || jsonb_build_object('http_verify_jwt', jsonb_build_object('present', v_bool, 'evidence', v_txt));
  end if;

  -- ---- vector: in-function authorisation, and the retired 410 stub (probe) ----------------
  select p.present, p.evidence into v_bool, v_txt
    from public.phase_c_component_probe p
   where p.component_id = c.component_id and p.vector = 'in_function_auth';
  if v_bool is not null then
    v_vec := v_vec || jsonb_build_object('in_function_auth', jsonb_build_object('present', v_bool, 'evidence', v_txt));
  end if;
  select p.present, p.evidence into v_bool, v_txt
    from public.phase_c_component_probe p
   where p.component_id = c.component_id and p.vector = 'retired_stub';
  v_retired_stub := coalesce(v_bool, false);
  if v_bool is not null then
    v_vec := v_vec || jsonb_build_object('retired_stub', jsonb_build_object('present', v_bool, 'evidence', v_txt));
  end if;

  -- ---- vector: RPC grants. has_function_privilege, NOT the grant statement -----------------
  -- A `revoke execute from anon` is a silent no-op while the grant is held through PUBLIC, so the
  -- privilege check is the only answer that means anything. The PUBLIC leg is reported separately
  -- because it changes what the repair has to be.
  if v_oid is not null then
    v_bool := has_function_privilege('anon', v_oid, 'EXECUTE');
    v_vec := v_vec || jsonb_build_object('rpc_anon', jsonb_build_object('present', v_bool,
      'evidence', format('has_function_privilege(''anon'', %s, ''EXECUTE'') = %s; proacl = %s',
        v_oid::regprocedure, v_bool, coalesce((select proacl::text from pg_proc where oid = v_oid),'null (owner default: PUBLIC holds EXECUTE)'))));
    if v_bool then v_names := v_names || 'rpc_anon'::text; end if;

    v_bool := has_function_privilege('authenticated', v_oid, 'EXECUTE');
    v_vec := v_vec || jsonb_build_object('rpc_authenticated', jsonb_build_object('present', v_bool,
      'evidence', format('has_function_privilege(''authenticated'', %s, ''EXECUTE'') = %s', v_oid::regprocedure, v_bool)));
    if v_bool then v_names := v_names || 'rpc_authenticated'::text; end if;

    select coalesce(bool_or(a.grantee = 0 and a.privilege_type = 'EXECUTE'), false)
      into v_bool
      from pg_proc p,
           lateral aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
     where p.oid = v_oid;
    v_bool := coalesce(v_bool, false);
    v_vec := v_vec || jsonb_build_object('rpc_public', jsonb_build_object('present', v_bool,
      'evidence', case when v_bool
        then 'PUBLIC holds EXECUTE (aclitem grantee 0): a REVOKE FROM anon on this function is a silent no-op'
        else 'PUBLIC does not hold EXECUTE' end));
    if v_bool then v_names := v_names || 'rpc_public'::text; end if;

    -- ---- vector: auth hook. An EXPLICIT grant to supabase_auth_admin, not one inherited -----
    -- through PUBLIC, which every PUBLIC-executable function would otherwise register as a hook.
    select coalesce(bool_or(a.grantee = (select r.oid from pg_roles r where r.rolname = 'supabase_auth_admin')
                            and a.privilege_type = 'EXECUTE'), false)
      into v_bool
      from pg_proc p, lateral aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
     where p.oid = v_oid;
    v_bool := coalesce(v_bool, false);
    v_vec := v_vec || jsonb_build_object('auth_hook', jsonb_build_object('present', v_bool,
      'evidence', case when v_bool
        then 'explicit GRANT EXECUTE to supabase_auth_admin in proacl (not inherited through PUBLIC) '
             || '— the GoTrue auth service can call this'
        else 'no explicit grant to supabase_auth_admin' end));
    if v_bool then v_names := v_names || 'auth_hook'::text; end if;

    -- ---- vector: internal callers in pg_proc.prosrc -----------------------------------------
    select string_agg(cn.nspname||'.'||cp.proname, ', ' order by cp.proname)
      into v_txt
      from pg_proc cp join pg_namespace cn on cn.oid = cp.pronamespace
     where cp.oid <> v_oid
       and cn.nspname not in ('pg_catalog','information_schema')
       and not exists (select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=cp.oid and d.deptype='e')
       -- cheap substring test first; the anchored regex only runs on the handful that survive it
       and strpos(cp.prosrc, (select proname from pg_proc where oid = v_oid)) > 0
       and cp.prosrc ~ ('\y' || (select proname from pg_proc where oid = v_oid) || '\s*\(');
    v_bool := v_txt is not null;
    v_vec := v_vec || jsonb_build_object('internal_caller', jsonb_build_object('present', v_bool,
      'evidence', coalesce('pg_proc.prosrc references it in: '||left(v_txt, 400),
                           'no other non-extension routine names it in pg_proc.prosrc')));
    if v_bool then v_names := v_names || 'internal_caller'::text; end if;

    -- ---- vector: row triggers ---------------------------------------------------------------
    select string_agg(t.tgname, ', ' order by t.tgname) into v_txt
      from pg_trigger t where t.tgfoid = v_oid and not t.tgisinternal;
    v_bool := v_txt is not null;
    v_vec := v_vec || jsonb_build_object('row_trigger', jsonb_build_object('present', v_bool,
      'evidence', coalesce('pg_trigger: '||v_txt, 'no row trigger executes this function')));
    if v_bool then v_names := v_names || 'row_trigger'::text; end if;

    -- ---- vector: EVENT triggers. The vector that missed fn_enforce_rls_on_new_tables --------
    select string_agg(format('%s on %s (evtenabled=%s)', t.evtname, t.evtevent, t.evtenabled), ', ' order by t.evtname)
      into v_txt
      from pg_event_trigger t where t.evtfoid = v_oid and t.evtenabled <> 'D';
    v_bool := v_txt is not null;
    v_vec := v_vec || jsonb_build_object('event_trigger', jsonb_build_object('present', v_bool,
      'evidence', coalesce('pg_event_trigger, ENABLED: '||v_txt,
                           'no enabled event trigger executes this function')));
    if v_bool then v_names := v_names || 'event_trigger'::text; end if;

    -- ---- vector: views and matviews that compile the function in ----------------------------
    -- Through pg_depend on the view's rewrite rule, not a regex over pg_get_viewdef: the dependency
    -- is what the planner itself recorded, so it cannot miss a call and cannot invent one from a
    -- name that merely appears in a comment or a column alias. It is also ~100x cheaper, which
    -- matters when the invariant calls this function once per component.
    select string_agg(distinct cn.nspname||'.'||cl.relname||
                      ' ('||case cl.relkind when 'm' then 'matview' else 'view' end||')', ', ')
      into v_txt
      from pg_depend d
      join pg_rewrite rw on rw.oid = d.objid
      join pg_class cl   on cl.oid = rw.ev_class
      join pg_namespace cn on cn.oid = cl.relnamespace
     where d.refclassid = 'pg_proc'::regclass and d.refobjid = v_oid
       and d.classid = 'pg_rewrite'::regclass
       and cl.relkind in ('v','m');
    v_bool := v_txt is not null;
    v_vec := v_vec || jsonb_build_object('compiled_into_view', jsonb_build_object('present', v_bool,
      'evidence', coalesce('runs on every SELECT of: '||v_txt, 'no view or matview compiles it in')));
    if v_bool then v_names := v_names || 'compiled_into_view'::text; end if;

    -- ---- vector: queue consumers -------------------------------------------------------------
    select string_agg(qn.nspname||'.'||q.proname, ', ' order by q.proname) into v_txt
      from pg_proc q join pg_namespace qn on qn.oid = q.pronamespace
     where qn.nspname in ('pgmq','net')
       and q.prosrc ~ ('\y' || (select proname from pg_proc where oid = v_oid) || '\s*\(');
    v_bool := v_txt is not null;
    v_vec := v_vec || jsonb_build_object('queue_consumer', jsonb_build_object('present', v_bool,
      'evidence', coalesce('named by queue machinery: '||v_txt, 'no pgmq/net routine names it')));
    if v_bool then v_names := v_names || 'queue_consumer'::text; end if;
  end if;

  -- ---- vector: cron, ACTIVE and INACTIVE reported separately -------------------------------
  -- An inactive job is a disabled component; an active one is a running component that a label
  -- calling it inactive cannot stop.
  if v_jobid is not null then
    select format('cron.job %s %L schedule %L active=%s; %s runs, last %s',
                  j.jobid, j.jobname, j.schedule, j.active,
                  (select count(*) from cron.job_run_details r where r.jobid = j.jobid),
                  coalesce((select max(r.start_time)::text from cron.job_run_details r where r.jobid = j.jobid),'never')),
           j.active
      into v_txt, v_bool
      from cron.job j where j.jobid = v_jobid;
    v_vec := v_vec || jsonb_build_object('cron_active', jsonb_build_object('present', coalesce(v_bool,false), 'evidence', coalesce(v_txt,'no cron.job row with this jobid')));
    v_vec := v_vec || jsonb_build_object('cron_registered', jsonb_build_object('present', v_txt is not null, 'evidence', coalesce(v_txt,'no cron.job row with this jobid')));
    if coalesce(v_bool,false) then v_names := v_names || 'cron_active'::text; end if;
  end if;

  -- ---- vector: webhook / net.http_post targeting this component ----------------------------
  if v_slug is not null then
    select string_agg(x.src, ', ') into v_txt from (
      select 'db routine '||n.nspname||'.'||p.proname src
        from pg_proc p join pg_namespace n on n.oid = p.pronamespace
       where n.nspname not in ('pg_catalog','information_schema')
         and strpos(p.prosrc, 'functions/v1/'||v_slug) > 0
         and p.prosrc ~ ('functions/v1/'||v_slug||'\y')
      union all
      select 'cron.job '||j.jobid||' ('||coalesce(j.jobname,'')||', active='||j.active||')'
        from cron.job j where j.command ~ ('functions/v1/'||v_slug||'\y')
    ) x;
  elsif v_oid is not null then
    select string_agg('trigger '||t.tgname||' -> '||tp.proname, ', ') into v_txt
      from pg_trigger t join pg_proc tp on tp.oid = t.tgfoid
     where not t.tgisinternal and tp.prosrc ~ 'net\.http_post'
       and tp.prosrc ~ ('\y' || (select proname from pg_proc where oid = v_oid) || '\y');
  else
    v_txt := null;
  end if;
  v_bool := v_txt is not null;
  v_vec := v_vec || jsonb_build_object('webhook_caller', jsonb_build_object('present', v_bool,
    'evidence', coalesce('net.http_post / cron HTTP caller: '||v_txt,
                         'no database routine, trigger or cron command posts to this component')));
  if v_bool then v_names := v_names || 'webhook_caller'::text; end if;

  -- ---- vector: frontend callers in src/** (probe) ------------------------------------------
  select p.present, p.evidence into v_bool, v_txt
    from public.phase_c_component_probe p
   where p.component_id = c.component_id and p.vector = 'frontend_caller';
  v_vec := v_vec || jsonb_build_object('frontend_caller', jsonb_build_object('present', coalesce(v_bool,false),
    'evidence', coalesce(v_txt, 'not swept: no src/** measurement recorded for this component')));
  if coalesce(v_bool,false) then v_names := v_names || 'frontend_caller'::text; end if;

  -- ---- vector: SCRIPT callers in scripts/** (probe) — the omitted one -----------------------
  select p.present, p.evidence into v_bool, v_txt
    from public.phase_c_component_probe p
   where p.component_id = c.component_id and p.vector = 'script_caller';
  v_vec := v_vec || jsonb_build_object('script_caller', jsonb_build_object('present', coalesce(v_bool,false),
    'evidence', coalesce(v_txt, 'no invocation of this component found in scripts/**')));
  if coalesce(v_bool,false) then v_names := v_names || 'script_caller'::text; end if;

  -- ---- conclusions -------------------------------------------------------------------------
  -- REACHABLE: some caller, some grant or some schedule can put control into this component.
  -- A retired 410 stub answers HTTP but executes nothing, so it is deployed-and-disabled, not
  -- reachable.
  -- A deployed HTTP endpoint that answers is reachable even when it demands a credential first:
  -- "access-controlled" is a description of HOW it is reached, not a claim that it is not. Only the
  -- 410 stubs are genuinely not reachable, because there is nothing behind the door.
  v_reachable := (not v_retired_stub) and (
       'http_deployed'      = any(v_names)
    or 'rpc_anon'           = any(v_names)
    or 'rpc_authenticated'  = any(v_names)
    or 'auth_hook'          = any(v_names)
    or 'internal_caller'    = any(v_names)
    or 'row_trigger'        = any(v_names)
    or 'event_trigger'      = any(v_names)
    or 'compiled_into_view' = any(v_names)
    or 'queue_consumer'     = any(v_names)
    or 'cron_active'        = any(v_names)
    or 'webhook_caller'     = any(v_names)
    or 'frontend_caller'    = any(v_names)
    or 'script_caller'      = any(v_names));

  -- REACHABLE UNAUTHENTICATED: a caller holding no credential at all gets in.
  v_unauth := (
       'rpc_anon' = any(v_names)
    or ('http_deployed' = any(v_names)
        and not coalesce((v_vec->'http_verify_jwt'->>'present')::boolean, true)
        and not coalesce((v_vec->'in_function_auth'->>'present')::boolean, false)));

  -- UNEXPECTEDLY ACTIVE: something is executing it now, without anyone deciding to call it.
  v_unexpected := 'event_trigger' = any(v_names)
               or 'row_trigger'   = any(v_names)
               or 'cron_active'   = any(v_names)
               or 'compiled_into_view' = any(v_names);

  -- The recorded vocabulary is 'no' / 'unauthenticated_only' / 'yes'. A deployed HTTP surface is an
  -- external entry even when every caller must present a credential — 'yes' means "an outside
  -- caller can address this", not "an outside caller can do as they like".
  v_external := case
    when v_unauth then 'unauthenticated_only'
    when 'http_deployed' = any(v_names) or 'rpc_authenticated' = any(v_names) then 'yes'
    else 'no' end;

  -- ---- the classification the evidence supports, most consequential vector first ------------
  -- The 410 stub is tested first. Five of the six answer an anonymous caller and would otherwise be
  -- filed ACTIVE_PUBLIC_ENTRY on the strength of a verify_jwt setting, which would be the same
  -- mistake in the opposite direction: the deployment is reachable, the component is not.
  if v_retired_stub then
    v_class := 'INTENTIONALLY_RETIRED'; v_state := 'inactive';
    v_decided := 'retired_stub: ' || (v_vec->'retired_stub'->>'evidence')
              || ' — deployed and addressable, executes nothing';
  elsif 'event_trigger' = any(v_names) then
    v_class := 'ACTIVE_EVENT_TRIGGER'; v_state := 'active';
    v_decided := 'event_trigger: ' || (v_vec->'event_trigger'->>'evidence');
  elsif 'cron_active' = any(v_names) then
    v_class := 'ACTIVE_CRON'; v_state := 'active';
    v_decided := 'cron_active: ' || (v_vec->'cron_active'->>'evidence');
  elsif v_unauth then
    v_class := 'ACTIVE_PUBLIC_ENTRY'; v_state := 'active';
    v_decided := case when 'rpc_anon' = any(v_names)
                      then 'rpc_anon: ' || (v_vec->'rpc_anon'->>'evidence')
                      else 'http_deployed with verify_jwt=false and no in-function authorisation: '
                           || (v_vec->'in_function_auth'->>'evidence') end;
  elsif 'auth_hook' = any(v_names) then
    v_class := 'ACTIVE_AUTH_HOOK'; v_state := 'active';
    v_decided := 'auth_hook: ' || (v_vec->'auth_hook'->>'evidence');
  elsif 'webhook_caller' = any(v_names) then
    v_class := 'ACTIVE_WEBHOOK_ENTRY'; v_state := 'active';
    v_decided := 'webhook_caller: ' || (v_vec->'webhook_caller'->>'evidence');
  elsif 'frontend_caller' = any(v_names) then
    v_class := 'ACTIVE_FRONTEND_ENTRY'; v_state := 'active';
    v_decided := 'frontend_caller: ' || (v_vec->'frontend_caller'->>'evidence');
  elsif 'compiled_into_view' = any(v_names) or 'internal_caller' = any(v_names)
     or 'row_trigger' = any(v_names) or 'queue_consumer' = any(v_names) then
    v_class := 'ACTIVE_INTERNAL_CALLER'; v_state := 'active';
    v_decided := coalesce('compiled_into_view: '||(v_vec->'compiled_into_view'->>'evidence'),'')
              || case when 'internal_caller' = any(v_names) then ' | internal_caller: '||(v_vec->'internal_caller'->>'evidence') else '' end
              || case when 'row_trigger' = any(v_names) then ' | row_trigger: '||(v_vec->'row_trigger'->>'evidence') else '' end
              || case when 'queue_consumer' = any(v_names) then ' | queue_consumer: '||(v_vec->'queue_consumer'->>'evidence') else '' end;
  elsif 'script_caller' = any(v_names) then
    v_class := 'ACTIVE_SCRIPT_ENTRY'; v_state := 'active';
    v_decided := 'script_caller: ' || (v_vec->'script_caller'->>'evidence');
  elsif 'http_deployed' = any(v_names)
        and (coalesce((v_vec->'http_verify_jwt'->>'present')::boolean,false)
             or coalesce((v_vec->'in_function_auth'->>'present')::boolean,false)) then
    v_class := 'ACCESS_CONTROLLED_NO_CALLER'; v_state := 'deployed';
    v_decided := 'deployed and callable, but every caller must present a credential: '
              || coalesce((v_vec->'in_function_auth'->>'evidence'), (v_vec->'http_verify_jwt'->>'evidence'))
              || ' | no frontend, script, cron or webhook caller found';
  elsif 'rpc_authenticated' = any(v_names) then
    v_class := 'ACCESS_CONTROLLED_NO_CALLER'; v_state := 'deployed';
    v_decided := 'rpc_authenticated: ' || (v_vec->'rpc_authenticated'->>'evidence') || ' | anon cannot execute it';
  else
    -- No vector at all. This is the absence of a finding, not a finding: it says the derivation
    -- could not get in, never that the component was never built. A registered-but-switched-off
    -- cron job says so in its own words rather than being described as "no cron job".
    v_class := 'DEFERRED_RUNTIME_IMPLEMENTATION'; v_state := 'inactive';
    v_decided := 'no reachability vector: no grant to anon or authenticated, no internal caller, no '
              || 'row or event trigger, no active schedule, no view, no queue consumer, no webhook, '
              || 'no caller in src/** or scripts/**'
              || case when coalesce((v_vec->'cron_registered'->>'present')::boolean,false)
                      then ' | schedule is registered and SWITCHED OFF: '
                           || (v_vec->'cron_active'->>'evidence')
                      else '' end;
  end if;

  return jsonb_build_object(
    'component_id',              c.component_id,
    'component_type',            c.component_type,
    'object',                    c.source_path_or_db_object,
    'mutates_state',             c.mutates_state,
    'extension_owned',           false,
    'vectors',                   v_vec,
    'vectors_present',           to_jsonb(v_names),
    'reachable',                 v_reachable,
    'reachable_unauthenticated', v_unauth,
    'unexpectedly_active',       v_unexpected,
    'derived_classification',    v_class,
    'derived_activation_state',  v_state,
    'derived_external_entry',    v_external,
    'decided_by',                v_decided);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_cron_exec(p_jobid bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public', 'cron', 'pg_temp'
AS $function$
declare
  w          public.phase_c_system_execution_wrapper%rowtype;
  c          public.phase_c_component%rowtype;
  a          public.phase_c_action_class%rowtype;
  v_sched    text;
  v_started  timestamptz := clock_timestamp();
  v_finished timestamptz;
  v_result   text := 'succeeded';
  v_failure  text := null;
  v_scope    text := null;
begin
  select * into w from public.phase_c_system_execution_wrapper where jobid = p_jobid;
  if not found then
    raise exception
      'fn_kernel_cron_exec: no wrapper row for cron job %. The job command was rewritten to call '
      'this wrapper and the row holding its original command is gone, so there is nothing to run. '
      'Restore the row or restore the command; do not leave the job pointing at nothing.', p_jobid
      using errcode = '23503';
  end if;

  select * into c from public.phase_c_component where component_id = w.component_id;
  if not found then
    raise exception 'fn_kernel_cron_exec: component % has no registry row', w.component_id
      using errcode = '23503';
  end if;

  select schedule into v_sched from cron.job where jobid = p_jobid;
  select * into a from public.phase_c_action_class where action_class = c.authority_class;

  -- Run the original work. The sub-transaction means a failure rolls the work back and still
  -- leaves the trace writable, which is the whole point of recording the failure.
  --
  -- ponytail: the failure is recorded and NOT re-raised, so cron.job_run_details will read
  -- "succeeded" for a run whose work failed. Re-raising would roll back the trace as well and we
  -- would be back to an untraced failure, which is worse. The trace carries result='failed' with
  -- the sqlstate and message, and fn_kernel_system_trace_state reports failures on their own line.
  -- Upgrade path if cron-level failure signalling is ever needed: write the trace through a
  -- dblink/pg_background autonomous connection, then re-raise.
  begin
    execute w.original_command;
  exception when others then
    v_result  := 'failed';
    v_failure := sqlstate || ' ' || sqlerrm;
  end;
  v_finished := clock_timestamp();

  -- A cron component with no Phase B workflow says so, in words, rather than borrowing the
  -- authority of a workflow id it does not have.
  if coalesce(c.workflow_id,'') = ''
     or not exists (select 1 from public.phase_b_workflow where workflow_id = c.workflow_id) then
    v_scope := format('technical scope: scheduled infrastructure execution registered as %L in '
                   || 'phase_c_component.workflow_id, which is not one of the thirty Phase B '
                   || 'workflows. Accountability is carried by the role, not by a workflow.',
                      coalesce(nullif(c.workflow_id,''), '(none)'));
  end if;

  return public.fn_kernel_system_execution_trace(jsonb_build_object(
    'component_id',       c.component_id,
    'system_actor',       c.canonical_system_actor,
    'accountable_role_id',c.accountable_role_id,
    'workflow_id',        case when v_scope is null then c.workflow_id else null end,
    'step_id',            case when v_scope is null then nullif(c.step_id,'') else null end,
    'technical_scope',    v_scope,
    'trigger_source',     format('cron.job/%s %L schedule %L', p_jobid, c.component_id,
                                 coalesce(v_sched,'(unreadable)')),
    -- Derived from the action class, not asserted. If a class ever requires founder approval this
    -- string says so and fn_kernel_system_trace_state counts it on its own line.
    'authority_result',   case
                            when a.action_class is null then 'unknown_action_class:' || coalesce(c.authority_class,'(none)')
                            when a.founder_approval_required then 'requires_founder_approval:' || a.action_class
                            else 'allowed_autonomous:' || a.action_class || ':' || a.execution_mode
                          end,
    -- For a scheduled execution the honest state pair is the execution's own lifecycle: the
    -- wrapper cannot know which business object the payload touched. Where the payload routes
    -- through the kernel, the business transition is traced separately under TRACE-WORKFLOW and
    -- TRACE-STEP; this trace records that the scheduled execution happened and how it ended.
    'state_before',       'scheduled_due',
    'state_after',        v_result,
    'result',             v_result,
    'failure',            to_jsonb(v_failure),
    'correlation_id',     gen_random_uuid()::text,
    'causation_id',       format('cron.job/%s@%s', p_jobid,
                                 to_char(v_started at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MSZ')),
    'input_hash',         md5(w.original_command),
    'started_at',         v_started,
    'finished_at',        v_finished));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_cutover_measure()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
with
body as (
  select p.oid, p.proname,
         regexp_replace(regexp_replace(p.prosrc, '/\*.*?\*/', ' ', 'g'), '--[^\n]*', ' ', 'g') src
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public'
),
-- A routine that reaches the kernel by ANY of the three doors the specification allows.
kernel_caller as (
  select b.proname from body b
   where b.src ~ '\yfn_kernel_trigger_submit\s*\('
      or b.src ~ '\yfn_kernel_signal_submit\s*\('
      or b.src ~ '\yfn_kernel_source_emit\s*\('
),
protected(t) as (values
  ('phase_c_workflow_run'),('phase_c_workflow_step_run'),('phase_c_task'),('phase_c_handoff_run'),
  ('kernel_trigger_inbox'),('kernel_signal_inbox'),('phase_c_event_outbox'),('phase_c_refund_decision')),
-- A routine that writes business work DIRECTLY. Anything on the kernel's own allow-list is
-- excluded: fn_kernel_step_complete writes those tables because it is the kernel.
direct_writer as (
  select distinct b.proname from body b join protected pr
      on b.src ~ ('(insert\s+into|update|delete\s+from)\s+(public\.)?' || pr.t || '\M')
   where not exists (select 1 from public.kernel_write_authority a where a.routine_name = b.proname)
),
-- The trigger a source names as discharging it, resolved to the routine it actually fires.
named as (
  select c.source_component_id, c.source_class, c.current_activation, c.status,
         c.disposition_evidence, c.target_step_or_signal, c.idempotency_key, c.trace_policy,
         split_part(c.disposition_evidence, ':', 1) as ev_kind,
         split_part(c.disposition_evidence, ':', 2) as ev_ref,
         case split_part(c.disposition_evidence, ':', 1)
           when 'routine' then split_part(c.disposition_evidence, ':', 2)
           when 'trigger' then (select p.proname from pg_trigger tg join pg_proc p on p.oid = tg.tgfoid
                                 where tg.tgname = split_part(c.disposition_evidence, ':', 2)
                                   and not tg.tgisinternal limit 1)
         end as ev_routine
    from public.phase_c_source_cutover c
),
judged as (
  select n.*,
         case
           when n.current_activation = 'DISABLED'
             or n.source_class = 'D RETIRE_OR_HISTORICAL'
             or n.ev_kind = 'retired'                      then 'RETIRED_OR_INACTIVE'
           when n.ev_kind in ('read_only','inactive') and n.source_class = 'C READ_ONLY_MONITOR'
                                                            then 'READ_ONLY'
           -- ROOT CAUSE 3. CUT_OVER used to mean ONLY "the named routine calls a function whose
           -- name contains kernel". That is the caller knocking. Ten ACTIVE sources were reported
           -- CUT_OVER while fn_kernel_signal_submit refused every submission they made, because
           -- their signal type was registered inactive. CUT_OVER now requires all seven:
           --   (a) the source is active                       — the outer case already established
           --   (b) the canonical adapter is deployed          — ev_routine resolves to a real routine
           --   (c) the routine reaches a kernel door          — kernel_caller
           --   (d) for a workflow SIGNAL, the type is ACTIVE and registered
           --   (e) the handler exists                         — a disposition the service implements
           --   (f) the handler accepts at least one valid state — a non-terminal workflow state exists
           --   (g) idempotency and trace policy are recorded on the source row
           when n.ev_kind in ('routine','trigger') and n.ev_routine is not null
                and exists (select 1 from kernel_caller k where k.proname = n.ev_routine)
                and (n.source_class not like 'B %' or exists (
                      select 1 from public.kernel_signal_type t
                       where t.signal_type = n.target_step_or_signal
                         and t.activation_state = 'active'
                         and t.disposition in ('ATTACH_ONLY','COMPLETE_STEP','REVIEW_VERDICT','CANCEL')))
                and exists (select 1 from public.phase_b_workflow_state ws where not ws.terminal)
                and coalesce(btrim(n.idempotency_key),'') <> ''
                and coalesce(btrim(n.trace_policy),'') <> ''
                                                            then 'CUT_OVER'
           else 'BYPASSING'
         end as verdict
    from named n
)
select 'total_sources'::text, 'reported, not asserted'::text,
       (select count(*)::text from judged), true
union all
select 'active_sources', 'reported',
       (select count(*)::text from judged where current_activation = 'ACTIVE'), true
union all
select 'inactive_sources', 'reported',
       (select count(*)::text from judged where current_activation = 'DISABLED'), true
union all
select 'class_split', 'reported',
       (select string_agg(source_class || ' ' || n::text, '; ' order by source_class)
          from (select source_class, count(*) n from judged group by 1) d), true
union all
select 'verdict_split', 'reported',
       (select string_agg(verdict || ' ' || n::text, '; ' order by verdict)
          from (select verdict, count(*) n from judged group by 1) d), true
union all
-- THE line. No expected numerator: it counts what it finds.
select 'active_sources_bypassing_the_kernel', '0',
       (select count(*)::text from judged where verdict = 'BYPASSING' and current_activation = 'ACTIVE')
         || coalesce(' [' || (select string_agg(source_component_id, ', ')
              from judged where verdict = 'BYPASSING' and current_activation = 'ACTIVE') || ']', ''),
       (select count(*) = 0 from judged where verdict = 'BYPASSING' and current_activation = 'ACTIVE')
union all
select 'active_sources_with_no_disposition_evidence', '0',
       (select count(*)::text from judged
         where current_activation = 'ACTIVE' and coalesce(btrim(disposition_evidence),'') = '')
         || coalesce(' [' || (select string_agg(source_component_id, ', ') from judged
              where current_activation = 'ACTIVE' and coalesce(btrim(disposition_evidence),'') = '') || ']', ''),
       (select count(*) = 0 from judged
         where current_activation = 'ACTIVE' and coalesce(btrim(disposition_evidence),'') = '')
union all
-- A claim that names a trigger which does not exist, or exists and does not call the kernel.
select 'coverage_claims_with_nothing_behind_them', '0',
       (select count(*)::text from judged
         where ev_kind in ('routine','trigger')
           and (ev_routine is null
                or not exists (select 1 from kernel_caller k where k.proname = ev_routine)))
         || coalesce(' [' || (select string_agg(source_component_id || ' -> ' || disposition_evidence, ', ')
              from judged where ev_kind in ('routine','trigger')
                and (ev_routine is null
                     or not exists (select 1 from kernel_caller k where k.proname = ev_routine))) || ']', ''),
       (select count(*) = 0 from judged
         where ev_kind in ('routine','trigger')
           and (ev_routine is null
                or not exists (select 1 from kernel_caller k where k.proname = ev_routine)))
union all
-- ROOT CAUSE 3. The line that would have caught it. An ACTIVE source whose signal type does not
-- accept submissions is not cut over, however its adapter is written.
select 'active_sources_targeting_an_inactive_signal_type', '0',
       (select count(*)::text from judged j
         where j.current_activation = 'ACTIVE' and j.source_class like 'B %'
           and not exists (select 1 from public.kernel_signal_type t
                            where t.signal_type = j.target_step_or_signal
                              and t.activation_state = 'active'))
         || coalesce(' [' || (select string_agg(j.source_component_id || ' -> ' || j.target_step_or_signal, ', ')
              from judged j where j.current_activation = 'ACTIVE' and j.source_class like 'B %'
                and not exists (select 1 from public.kernel_signal_type t
                                 where t.signal_type = j.target_step_or_signal
                                   and t.activation_state = 'active')) || ']', ''),
       (select count(*) = 0 from judged j
         where j.current_activation = 'ACTIVE' and j.source_class like 'B %'
           and not exists (select 1 from public.kernel_signal_type t
                            where t.signal_type = j.target_step_or_signal
                              and t.activation_state = 'active'))

union all
-- An active signal type with no handler the service implements is a door with nothing behind it.
select 'active_signal_types_without_a_handler', '0',
       (select count(*)::text from public.kernel_signal_type t
         where t.activation_state = 'active'
           and t.disposition not in ('ATTACH_ONLY','COMPLETE_STEP','REVIEW_VERDICT','CANCEL')),
       (select count(*) = 0 from public.kernel_signal_type t
         where t.activation_state = 'active'
           and t.disposition not in ('ATTACH_ONLY','COMPLETE_STEP','REVIEW_VERDICT','CANCEL'))

union all
-- Reported for the record: how many verdicts rest on nothing but source-text caller detection.
select 'cutover_rows_resting_only_on_source_text_caller_detection', '0',
       (select count(*)::text from judged j
         where j.verdict = 'CUT_OVER' and j.source_class like 'B %'
           and not exists (select 1 from public.kernel_signal_type t
                            where t.signal_type = j.target_step_or_signal
                              and t.activation_state = 'active')),
       (select count(*) = 0 from judged j
         where j.verdict = 'CUT_OVER' and j.source_class like 'B %'
           and not exists (select 1 from public.kernel_signal_type t
                            where t.signal_type = j.target_step_or_signal
                              and t.activation_state = 'active'))

union all
-- An ACTIVE source whose own routine writes a protected table directly. The kernel's own writers
-- are excluded by kernel_write_authority, so this is a genuine bypass and not the kernel itself.
select 'active_sources_writing_business_work_directly', '0',
       (select count(*)::text from judged j
         where j.current_activation = 'ACTIVE'
           and exists (select 1 from direct_writer w
                        where w.proname = (select p.proname from pg_trigger tg
                                             join pg_proc p on p.oid = tg.tgfoid
                                            where tg.tgname = split_part(j.source_component_id, ':', 3)
                                              and not tg.tgisinternal limit 1))),
       (select count(*) = 0 from judged j
         where j.current_activation = 'ACTIVE'
           and exists (select 1 from direct_writer w
                        where w.proname = (select p.proname from pg_trigger tg
                                             join pg_proc p on p.oid = tg.tgfoid
                                            where tg.tgname = split_part(j.source_component_id, ':', 3)
                                              and not tg.tgisinternal limit 1)));
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_event_consume(p_outbox_id bigint)
 RETURNS TABLE(handled boolean, downstream_ref text, result jsonb, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  o public.phase_c_event_outbox%rowtype;
  e public.phase_b_event%rowtype;
  v_run bigint; v_step text; v_prior text;
  v_sk text; v_next text; v_next_owner text; v_ho text; v_sk_reason text;
  v_handled boolean := false; v_ref text; v_result jsonb; v_reason text;
begin
  v_prior := coalesce(nullif(current_setting('kernel.in_delivery', true),''), '0');
  perform set_config('kernel.in_delivery', '1', true);

  select * into o from public.phase_c_event_outbox where outbox_id = p_outbox_id;
  if not found then
    v_reason := 'unknown_outbox_row';
  else
    select * into e from public.phase_b_event where event_id = o.event_id;
    if not found then
      v_reason := format('%s is not in the frozen Phase B event registry', o.event_id);

    -- A row naming a command must be for a workflow that command actually selected.
    elsif coalesce(o.command_id::text, o.payload->>'command_id') is not null
      and not exists (select 1 from public.founder_command_workflow_link l
                       where l.command_id = coalesce(o.command_id, (o.payload->>'command_id')::bigint)
                         and l.workflow_id = o.workflow_id) then
      v_reason := format('event %s names workflow %s but command %s selected a different workflow',
                         o.event_id, o.workflow_id, coalesce(o.command_id::text, o.payload->>'command_id'));

    elsif e.event_name like '%.started' then
      -- workflow.started is a RECORD of a run fn_kernel_workflow_start already created.
      v_run := coalesce(o.workflow_run_id, nullif(o.payload->>'run_id','')::bigint);
      if v_run is null then
        v_reason := format('%s carries no workflow_run_id: it was produced as a command, not as a '
                        || 'record of a run. The kernel creates the run and then emits.', o.event_id);
      elsif not exists (select 1 from public.phase_c_workflow_run where run_id = v_run) then
        v_reason := format('%s names workflow run %s, which does not exist', o.event_id, v_run);
      else
        v_handled := true;
        v_ref     := 'run:' || v_run;
        v_result  := jsonb_build_object('projected','workflow_run', 'run_id', v_run,
                       'workflow_id', o.workflow_id, 'correlation_id', o.correlation_id,
                       'step_run_id', o.step_run_id, 'created_by', o.producer);
      end if;

    -- WORKFLOW-level lifecycle first. EV-Wnn-COMPLETED is named 'phase_b.wnn.completed', so it
    -- matches '%.completed' too, and K3 stamps a step_run_id on it. Without this branch the run
    -- closure would be read as a step completion and reported against the closure step.
    elsif o.event_id in (public.fn_phase_c_lifecycle_event(o.workflow_id, 'completed'),
                         public.fn_phase_c_lifecycle_event(o.workflow_id, 'blocked')) then
      v_run := coalesce(o.workflow_run_id, nullif(o.payload->>'run_id','')::bigint);
      if v_run is null then
        v_reason := format('%s carries no workflow_run_id', o.event_id);
      elsif not exists (select 1 from public.phase_c_workflow_run where run_id = v_run) then
        v_reason := format('%s names workflow run %s, which does not exist', o.event_id, v_run);
      else
        v_handled := true;
        v_ref := 'run_' || (select state from public.phase_c_workflow_run where run_id = v_run)
                 || ':' || v_run;
        v_result := jsonb_build_object('projected','workflow_lifecycle', 'created', 0,
          'run_id', v_run, 'workflow_id', o.workflow_id,
          'state', (select state from public.phase_c_workflow_run where run_id = v_run),
          'closed_at', (select closed_at from public.phase_c_workflow_run where run_id = v_run),
          'fact', o.payload->>'fact');
      end if;

    elsif e.event_name like '%.completed' and (o.step_run_id is not null or o.payload ? 'step_id') then
      v_run  := coalesce(o.workflow_run_id, nullif(o.payload->>'run_id','')::bigint);
      v_step := coalesce(o.payload->>'step_id',
                         (select step_id from public.phase_c_workflow_step_run
                           where step_run_id = o.step_run_id));
      if v_run is null or v_step is null then
        v_reason := format('completed event %s carries no run (%s) or no step (%s)',
                           o.event_id, coalesce(v_run::text,'null'), coalesce(v_step,'null'));
      else
        -- PROJECTION ONLY. fn_kernel_step_complete is the single authoritative progression path
        -- and has already created whatever comes next, inside the transaction that closed the
        -- step. Creating a task here would be a second creator racing the first, and it would
        -- hand a receiving owner work they never accepted.
        -- aliased: this function's OUT parameter `reason` would otherwise shadow the
        -- classifier's column of the same name and raise 42702.
        select c.kind, c.next_step_id, c.next_owner_role_id, c.handoff_id, c.reason
          into v_sk, v_next, v_next_owner, v_ho, v_sk_reason
          from public.fn_kernel_step_successor(v_step) c;
        v_handled := true;
        v_ref := case v_sk
                   when 'closure'    then 'closure_step:' || v_step
                   when 'same_owner' then 'kernel_opened:' || coalesce(v_next,'?')
                   when 'cross_owner' then 'kernel_handoff:' || coalesce(v_ho,'?')
                   else 'registry_defect:' || v_sk || ':' || v_step end;
        v_result := jsonb_build_object(
          'projected','step_completed', 'created', 0,
          'run_id', v_run, 'step_id', v_step, 'successor_kind', v_sk,
          'next_step_id', v_next, 'next_owner_role_id', v_next_owner, 'handoff_id', v_ho,
          'successor_reason', v_sk_reason,
          'note','fn_kernel_step_complete is the only creator of business work; delivery projects.');
      end if;

    else
      v_reason := format('no canonical consumer for %s (%s)', o.event_id, e.event_name);
    end if;
  end if;

  perform set_config('kernel.in_delivery', v_prior, true);
  return query select v_handled, v_ref, v_result, v_reason;
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_founder_approval_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select 'founder_approval_classes_are_refund_only', 'refund_decision',
         coalesce((select string_agg(action_class, ',' order by action_class)
                     from public.phase_c_action_class where founder_approval_required), '(none)'),
         (select coalesce(string_agg(action_class, ',' order by action_class), '')
            from public.phase_c_action_class where founder_approval_required) = 'refund_decision'
  union all
  select 'non_refund_rows_in_founder_approval_request', '0 of total',
         (select count(*) filter (where not exists (
             select 1 from public.phase_c_action_class c
              where c.action_class = r.action_class and c.founder_approval_required))::text
                 || ' of ' || count(*)::text from public.founder_approval_request r),
         (select count(*) filter (where not exists (
             select 1 from public.phase_c_action_class c
              where c.action_class = r.action_class and c.founder_approval_required)) = 0
            from public.founder_approval_request r)
  union all
  select 'non_refund_rows_in_v_founder_inbox', '0 of total',
         (select count(*) filter (where bucket <> 'refund_decision')::text || ' of ' || count(*)::text
            from public.v_founder_inbox),
         (select count(*) filter (where bucket <> 'refund_decision') = 0 from public.v_founder_inbox)
  union all
  select 'org_tasks_newly_routed_to_founder_that_are_not_refunds', '0 of total',
         (select count(*) filter (where t.needs_founder and not exists (
             select 1 from public.phase_c_action_class c
              where c.action_class = t.action_class and c.founder_approval_required)
             and t.status not in ('done','cancelled','failed'))::text
                 || ' of ' || count(*) filter (where t.needs_founder)::text
            from public.org_tasks t),
         (select count(*) filter (where t.needs_founder and not exists (
             select 1 from public.phase_c_action_class c
              where c.action_class = t.action_class and c.founder_approval_required)
             and t.status not in ('done','cancelled','failed')) = 0
            from public.org_tasks t)
  union all
  select 'refund_decisions_that_are_mutable', '0 of total',
         '0 of ' || (select count(*) from public.phase_c_refund_decision)::text,
         exists (select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid
                  where c.relname = 'phase_c_refund_decision'
                    and t.tgname = 'a00_phase_c_refund_decision_immutable' and not t.tgisinternal);
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_founder_routing_is_refund_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- Only fires when a row is NEWLY routed to the founder. Historical rows stay editable so the 46
  -- closed ones can still be maintained; what is refused is CREATING more of them.
  if coalesce(new.needs_founder, false)
     and (tg_op = 'INSERT'
          or coalesce(old.needs_founder, false) is distinct from true
          or old.action_class is distinct from new.action_class)
     and not exists (select 1 from public.phase_c_action_class
                      where action_class = new.action_class and founder_approval_required) then
    raise exception
      'org_tasks: action_class % cannot be routed to the founder; only a refund decision reaches him',
      coalesce(new.action_class, '(null)')
      using errcode = '23514',
            hint = 'Escalate to the accountable canonical role instead. phase_c_action_class names '
                || 'the classes that require a founder decision, and today that is refund_decision '
                || 'and nothing else.';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_handoff_accept(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  hr public.phase_c_handoff_run%rowtype;
  r  public.phase_c_workflow_run%rowtype;
  h  public.phase_b_handoff%rowtype;
  v_id     bigint := nullif(p_input->>'handoff_run_id','')::bigint;
  v_actor_in text := nullif(btrim(coalesce(p_input->>'actor_role_id','')), '');
  v_packet jsonb  := p_input->'packet';
  v_actor  text;
  v_kind   text;
  v_n      bigint;
  v_valid  record;
  v_dec    jsonb;
  v_opened jsonb;
  v_target text;
begin
  perform public.fn_kernel_assert_not_in_delivery('fn_kernel_handoff_accept');

  if v_id is null or v_actor_in is null then
    raise exception 'fn_kernel_handoff_accept: handoff_run_id and actor_role_id are both required'
      using errcode = '22023';
  end if;

  -- Same lock order as the engine: run, then handoff run.
  select run_id into v_n from public.phase_c_handoff_run where handoff_run_id = v_id;
  if v_n is null then
    raise exception 'fn_kernel_handoff_accept: no handoff run % (k3_handoff_not_found)', v_id
      using errcode = '23503';
  end if;
  select * into r from public.phase_c_workflow_run where run_id = v_n for update;
  if not found then
    raise exception 'fn_kernel_handoff_accept: handoff run % names workflow run %, which does not exist',
      v_id, v_n using errcode = '23503';
  end if;
  select * into hr from public.phase_c_handoff_run where handoff_run_id = v_id for update;
  if hr.status <> 'open' then
    raise exception 'fn_kernel_handoff_accept: handoff run % is % and cannot be accepted again (k3_handoff_not_open)',
      v_id, hr.status using errcode = '23514';
  end if;
  select * into h from public.phase_b_handoff where handoff_id = hr.handoff_id;
  if not found then
    raise exception 'fn_kernel_handoff_accept: handoff % is not in the frozen registry', hr.handoff_id
      using errcode = '23503';
  end if;

  select kind, role_id into v_kind, v_actor from public.fn_phase_c_resolve_actor(v_actor_in);
  if v_actor is null or v_kind is distinct from 'canonical' then
    raise exception 'fn_kernel_handoff_accept: actor % resolves to % (k3_actor_unresolved)',
      v_actor_in, coalesce(v_kind,'nothing') using errcode = '23514';
  end if;
  if v_actor is distinct from (select role_id from public.fn_phase_c_resolve_actor(hr.receiving_role_id)) then
    raise exception 'fn_kernel_handoff_accept: handoff run % is addressed to % and % may not accept it (k3_not_the_receiver)',
      v_id, hr.receiving_role_id, v_actor using errcode = '23514';
  end if;

  -- GATE-007 in substance: a packet that does not carry what the registry requires is not a
  -- complete handoff, and accepting it would transfer accountability for work nobody can do.
  select * into v_valid from public.fn_phase_c_handoff_packet_valid(hr.handoff_id, v_packet);
  if not v_valid.valid then
    raise exception 'fn_kernel_handoff_accept: handoff run % packet is incomplete [%]. Required packet: %. (k3_handoff_packet_incomplete)',
      v_id, v_valid.missing, left(h.required_packet, 160) using errcode = '23514';
  end if;

  v_dec := public.fn_phase_c_handoff_decide(v_id, 'accept', v_actor,
    jsonb_build_object('packet_hash', encode(sha256(convert_to(v_packet::text,'UTF8')),'hex')));
  if not coalesce((v_dec->>'ok')::boolean, false) then
    raise exception 'fn_kernel_handoff_accept: handoff run % refused acceptance: %',
      v_id, coalesce(v_dec->>'error','(no error given)') using errcode = '23514';
  end if;

  -- The receiving step run and its ONE task, from the accepted contract.
  select role_id into v_target from public.fn_phase_c_resolve_actor(
    (select b.accountable_role_id from public.phase_b_workflow_step b where b.step_id = h.to_step_id));
  if v_target is null or not public.fn_phase_c_actor_may_own(v_target) then
    raise exception 'fn_kernel_handoff_accept: step % names an owner that does not resolve to an active canonical role — no step run and no task are opened (k3_successor_owner_unresolved)',
      h.to_step_id using errcode = '23514';
  end if;

  -- The run is running again. waiting_handoff -> active and waiting_review -> active are both
  -- declared in phase_b_workflow_transition; the guard on phase_c_workflow_run enforces it.
  --
  -- E14 / PCCR-002. THIS STATEMENT USED TO SIT BELOW THE CALL BELOW IT, AND THAT ORDERING MEANT NO
  -- STEP IN THE ESTATE COULD EVER EXECUTE. Since D36, fn_kernel_open_step dispatches the Phase D
  -- handler for the step it opens. A KERNEL_ONLY_TRANSITION handler's declared effect is to complete
  -- that step through fn_kernel_step_complete -- which refuses, correctly, with
  -- k3_run_not_active, because at that instant this function had not yet moved the run out of
  -- waiting_handoff. The kernel opened the step, told Phase D to run it, and refused the only thing
  -- Phase D could do with it. Measured 2026-08-20: 207 dispatches across all thirty workflows, 0
  -- EXECUTED; with the run already active, the same W01-S05 step run returns EXECUTED, hdl_w01_s05,
  -- effect_id 7351.
  --
  -- Nothing else changes. Same condition, same statement, same target row; r is read at the top of
  -- the function and is unaffected by the move. If fn_kernel_open_step raises, the transaction rolls
  -- back exactly as before.
  if r.state is distinct from 'active' then
    update public.phase_c_workflow_run set state = 'active' where run_id = r.run_id;
  end if;

  v_opened := public.fn_kernel_open_step(jsonb_build_object(
    'run_id', r.run_id, 'step_id', h.to_step_id, 'owner_role_id', v_target,
    'source_kind','handoff_accepted', 'source_ref','handoff_run:' || v_id,
    'command_id', r.command_id, 'business_object_id', r.business_object_id,
    'priority', coalesce(nullif(p_input->>'priority',''), 'P2'),
    'input_hash', encode(sha256(convert_to(v_packet::text,'UTF8')),'hex'),
    'opened_because', format('handoff %s was accepted by %s', hr.handoff_id, v_actor)));

  return jsonb_build_object('ok', true, 'handoff_run_id', v_id, 'handoff_id', hr.handoff_id,
    'run_id', r.run_id, 'workflow_id', r.workflow_id,
    'accepted_by', v_actor, 'accountable_now', v_dec->>'accountable_now',
    'to_step_id', h.to_step_id,
    'step_run_id', v_opened->'step_run_id', 'task_id', v_opened->'task_id',
    'step_trace_id', v_opened->'step_trace_id', 'task_trace_id', v_opened->'task_trace_id',
    'handoff_trace_id', v_dec->'trace_id', 'run_state','active',
    'created', jsonb_build_object('step_runs',1,'tasks',1,'handoffs',0,'events',0));
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_handoff_run_trace_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.status is distinct from old.status and new.trace_id is not null then
    perform public.fn_phase_c_trace_advance(
      new.trace_id, new.status,
      new.status in ('accepted','rejected','cancelled','superseded'),
      jsonb_build_object('evidence_refs', jsonb_build_array(
        jsonb_build_object('transition', old.status || ' -> ' || new.status, 'at', now(),
                           'rejection_reason', nullif(new.rejection_reason,''),
                           'missing_items', nullif(new.missing_items,'')))));
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_historical_register_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
with r as (select * from public.phase_c_historical_repair),
-- ROOT CAUSE 4 FOLLOW-UP, 17 Aug 2026. The register is append-only and its own trigger states the
-- correction protocol: "A correction is a NEW row that names the repair_id it corrects in its
-- evidence, never an edit to the row that stated the original finding." Until now nothing here read
-- that protocol, so a corrected finding went on being counted as a live one and there was no way to
-- satisfy the register by the mechanism the register prescribes. A CLASSIFICATION that a later row
-- names as corrected is no longer in the population; the correcting row has to exist and has to
-- name it, which is stricter bookkeeping than not looking.
exc as (
  select * from r c
   where c.entry_kind = 'CLASSIFICATION'
     and not exists (select 1 from r x
                      where (x.evidence->>'corrects_repair_id')::bigint = c.repair_id))
-- ---- CURRENT state. These must be zero, and they are about today, not about history.
select 'active_historical_duplicate_work'::text,
       '0 of ' || (select count(*)::text from exc where classification = 'HISTORICAL_DUPLICATE_EFFECT'),
       (select count(*)::text from exc
         where classification = 'HISTORICAL_DUPLICATE_EFFECT' and active_effect_now)
         || ' of ' || (select count(*)::text from exc where classification = 'HISTORICAL_DUPLICATE_EFFECT'),
       (select count(*) = 0 from exc where classification = 'HISTORICAL_DUPLICATE_EFFECT' and active_effect_now)
union all
select 'queued_work_beneath_cancelled_commands',
       '0',
       (select count(*)::text from public.phase_c_task t
         join public.founder_command c on c.command_id = t.command_id
        where c.state = 'cancelled'
          and t.state not in (select state from public.phase_c_task_state where terminal)),
       (select count(*) = 0 from public.phase_c_task t
         join public.founder_command c on c.command_id = t.command_id
        where c.state = 'cancelled'
          and t.state not in (select state from public.phase_c_task_state where terminal))
union all
select 'current_terminal_objects_with_open_trace',
       '0',
       (select count(*)::text from public.phase_c_trace t
         where t.status = 'open'
           and t.created_at >= (select min(started_at) from public.phase_c_kernel_epoch)
           and exists (select 1 from public.phase_c_workflow_run w
                        where w.run_id::text = t.subject_ref and t.subject_kind = 'workflow_run'
                          and w.state in (select state from public.phase_b_workflow_state where terminal))),
       (select count(*) = 0 from public.phase_c_trace t
         where t.status = 'open'
           and t.created_at >= (select min(started_at) from public.phase_c_kernel_epoch)
           and exists (select 1 from public.phase_c_workflow_run w
                        where w.run_id::text = t.subject_ref and t.subject_kind = 'workflow_run'
                          and w.state in (select state from public.phase_b_workflow_state where terminal)))
union all
select 'current_active_orphan_traces',
       '0 — an orphan trace created AFTER the kernel epoch',
       (select count(*)::text from public.phase_c_trace t
         where t.created_at >= (select min(started_at) from public.phase_c_kernel_epoch)
           and t.subject_kind = 'task'
           and not exists (select 1 from public.phase_c_task k where k.task_id::text = t.subject_ref)),
       (select count(*) = 0 from public.phase_c_trace t
         where t.created_at >= (select min(started_at) from public.phase_c_kernel_epoch)
           and t.subject_kind = 'task'
           and not exists (select 1 from public.phase_c_task k where k.task_id::text = t.subject_ref))
union all
-- ---- PRESERVED history. Reported with an exact count, never as compliance.
select 'historical_exceptions_preserved',
       'reported exactly, and never presented as current compliance',
       (select string_agg(classification || ' ' || n::text, '; ' order by classification)
          from (select classification, count(*) n from exc group by 1) d)
         || '; retrofit entries ' || (select count(*)::text from r where entry_kind = 'RETROFIT'),
       true
union all
select 'historical_exceptions_with_no_original_timestamp',
       '0 of ' || (select count(*)::text from exc),
       (select count(*)::text from exc where original_at is null)
         || ' of ' || (select count(*)::text from exc),
       (select count(*) = 0 from exc where original_at is null)
union all
select 'historical_exceptions_with_no_reason_they_cannot_be_reconstructed',
       '0 of ' || (select count(*)::text from exc),
       (select count(*)::text from exc where coalesce(btrim(cannot_reconstruct),'') = '')
         || ' of ' || (select count(*)::text from exc),
       (select count(*) = 0 from exc where coalesce(btrim(cannot_reconstruct),'') = '')
union all
select 'historical_exceptions_dated_after_the_kernel_cutover',
       '0 of ' || (select count(*)::text from exc where original_at is not null),
       (select count(*)::text from exc where original_at is not null and original_at >= kernel_cutover_at)
         || ' of ' || (select count(*)::text from exc where original_at is not null),
       -- A "historical" exception that happened after the kernel took over is not historical. It
       -- is a live defect wearing the wrong label, and that is worth failing on.
       (select count(*) = 0 from exc where original_at is not null and original_at >= kernel_cutover_at)
union all
select 'register_is_append_only',
       'a trigger refusing UPDATE and DELETE',
       (select case when count(*) = 1 then 'present' else 'MISSING' end
          from pg_trigger tg join pg_class c on c.oid = tg.tgrelid
         where c.relname = 'phase_c_historical_repair'
           and tg.tgname = 'a00_phase_c_historical_repair_append_only'
           and not tg.tgisinternal and tg.tgenabled <> 'D'),
       (select count(*) = 1 from pg_trigger tg join pg_class c on c.oid = tg.tgrelid
         where c.relname = 'phase_c_historical_repair'
           and tg.tgname = 'a00_phase_c_historical_repair_append_only'
           and not tg.tgisinternal and tg.tgenabled <> 'D');
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_historical_repair_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
with
-- every founder command that produced any Phase C effect: the denominator for duplication
cmd as (
  select c.command_id, c.state,
         (select count(*) from public.phase_c_task t
            join public.phase_c_task_state ts on ts.state = t.state
           where t.command_id = c.command_id and t.run_id is null and not ts.terminal) as legacy_live,
         (select count(*) from public.phase_c_task t
            join public.phase_c_task_state ts on ts.state = t.state
           where t.run_id in (select r.run_id from public.phase_c_workflow_run r
                               where r.command_id = c.command_id)
             and not ts.terminal) as run_live
    from public.founder_command c
   where exists (select 1 from public.phase_c_task t where t.command_id = c.command_id)
      or exists (select 1 from public.phase_c_workflow_run r where r.command_id = c.command_id)
),
-- every task whose command or run has reached a terminal state: the denominator for propagation
derived as (
  select t.task_id, ts.terminal as task_terminal
    from public.phase_c_task t
    join public.phase_c_task_state ts on ts.state = t.state
   where exists (select 1 from public.founder_command c
                   join public.phase_c_command_state cs on cs.state = c.state
                  where c.command_id = t.command_id and cs.terminal)
      or exists (select 1 from public.phase_c_workflow_run r
                  where r.run_id = t.run_id
                    and r.state in ('completed','cancelled','failed','superseded','expired','rejected'))
),
-- every trace whose subject resolves to a real object: the denominator for the trace checks
bound as (
  select tr.trace_id, tr.status, tr.sealed_at, tr.superseded_by, o.is_terminal
    from public.v_phase_c_trace_subject tr
    join public.v_phase_c_object_terminal o on o.kind = tr.nkind and o.ref = tr.nref
),
classes(classification) as (values
  ('HISTORICAL_DUPLICATE_EFFECT'), ('HISTORICAL_ORPHAN_TRACE'),
  ('HISTORICAL_STATE_TRACE_MISMATCH'), ('HISTORICAL_CANCEL_PROPAGATION_FAILURE'),
  ('VALID_HISTORICAL_RECORD'))

-- ---- 1. a founder command may not be executed twice ----------------------------------------
select 'active_duplicate_founder_command_effects', '0',
       count(*) filter (where legacy_live > 0 and run_live > 0)::text || ' of ' || count(*)::text,
       count(*) filter (where legacy_live > 0 and run_live > 0) = 0
  from cmd

union all
-- ---- 2. a cancelled command may leave no queued derived work -------------------------------
select 'queued_work_derived_from_cancelled_commands', '0',
       count(*) filter (where not task_terminal)::text || ' of ' || count(*)::text,
       count(*) filter (where not task_terminal) = 0
  from derived

union all
-- ---- 3. a finished object may not hold an open trace ---------------------------------------
-- Measured from the trace side over every trace with a resolvable subject, NOT from the object's
-- own trace_id pointer. Three of the rows this repair sealed were invisible to a pointer-based
-- check because they were not the pointer their subject carried.
select 'terminal_objects_with_open_trace', '0',
       count(*) filter (where is_terminal and sealed_at is null and superseded_by is null)::text
         || ' of ' || count(*)::text,
       count(*) filter (where is_terminal and sealed_at is null and superseded_by is null) = 0
  from bound

union all
-- ---- 4. an orphan trace may not be left live or unjudged ------------------------------------
-- The orphans are preserved, so this cannot ask for zero orphans. It asks that every orphan is
-- sealed AND has been judged in the append-only ledger. A NEW orphan is unsealed or unclassified
-- and turns this red immediately; the seven that exist are both, and are green without being hidden.
select 'active_orphan_traces', '0',
       count(*) filter (where tr.nkind = 'task' and tr.nref is null
                          and (tr.sealed_at is null
                               or not exists (select 1 from public.phase_c_historical_repair h
                                               where h.entry_kind = 'CLASSIFICATION'
                                                 and h.record_kind = 'trace'
                                                 and h.record_ref = tr.trace_id::text)))::text
         || ' of ' || count(*)::text,
       count(*) filter (where tr.nkind = 'task' and tr.nref is null
                          and (tr.sealed_at is null
                               or not exists (select 1 from public.phase_c_historical_repair h
                                               where h.entry_kind = 'CLASSIFICATION'
                                                 and h.record_kind = 'trace'
                                                 and h.record_ref = tr.trace_id::text))) = 0
  from public.v_phase_c_trace_subject tr

union all
-- ---- 5. no retrofit may be presented as contemporaneous evidence ----------------------------
-- A retrofit is unlabelled if its ledger row carries no label (the CHECK constraint already
-- refuses that, so this catches a constraint being dropped) or if it claims to have written to a
-- row and that row does not carry the s2_retrofit key.
select 'unlabelled_retrofits', '0',
       count(*) filter (where h.retrofit_label = ''
                          or ((h.evidence->>'wrote_to_row')::boolean is true
                              and not exists (select 1 from public.phase_c_trace x
                                               where x.trace_id = h.record_ref::bigint
                                                 and x.evidence_refs @> '[{"s2_retrofit":"sealed_open_trace_on_terminal_subject"}]'::jsonb)))::text
         || ' of ' || count(*)::text,
       count(*) filter (where h.retrofit_label = ''
                          or ((h.evidence->>'wrote_to_row')::boolean is true
                              and not exists (select 1 from public.phase_c_trace x
                                               where x.trace_id = h.record_ref::bigint
                                                 and x.evidence_refs @> '[{"s2_retrofit":"sealed_open_trace_on_terminal_subject"}]'::jsonb))) = 0
  from public.phase_c_historical_repair h
 where h.entry_kind = 'RETROFIT'

union all
-- ---- 6. the default that would excuse an open trace -----------------------------------------
-- v_phase_c_object_terminal reads terminality from the state tables and coalesces a miss to
-- false. A state that is not in the model would therefore score as "still running" and its open
-- trace would pass check 3 silently. This is that hole, measured.
select 'object_states_not_in_the_state_model', '0',
       count(*) filter (where not state_is_modelled)::text || ' of ' || count(*)::text,
       count(*) filter (where not state_is_modelled) = 0
  from public.v_phase_c_object_terminal

union all
-- ---- informational: the history, preserved and countable ------------------------------------
select 'historical_records_classified_' || c.classification, 'informational',
       (select count(*) from public.phase_c_historical_repair h
         where h.entry_kind = 'CLASSIFICATION' and h.classification = c.classification)::text
         || ' of ' || (select count(*) from public.phase_c_historical_repair h
                        where h.entry_kind = 'CLASSIFICATION')::text,
       true
  from classes c

union all
select 'historical_retrofits_recorded', 'informational',
       (select count(*) from public.phase_c_historical_repair where entry_kind = 'RETROFIT')::text
         || ' of ' || (select count(*) from public.phase_c_historical_repair)::text,
       true

union all
select 'raw_traces_carrying_an_s2_retrofit_annotation', 'informational',
       count(*) filter (where exists (select 1 from jsonb_array_elements(evidence_refs) e
                                       where e ? 's2_retrofit'))::text
         || ' of ' || count(*)::text,
       true
  from public.phase_c_trace
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_in_delivery()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(nullif(current_setting('kernel.in_delivery', true), ''), '0') = '1';
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_intake_execution(p_component text, p_trace_input jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_trace bigint; v_result text;
begin
  v_result := case
    when coalesce(p_trace_input->>'state_after','') in ('refused','rejected') then 'refused'
    when coalesce(p_trace_input->>'state_after','') = 'deferred' then 'no_op'
    else 'succeeded' end;

  v_trace := public.fn_kernel_system_execution_begin(jsonb_build_object(
    'component_id',    p_component,
    'correlation_id',  coalesce(nullif(p_trace_input->>'correlation_id',''), 'intake:' || p_component),
    'causation_id',    coalesce(nullif(p_trace_input->>'causation_id',''), 'intake:' || p_component),
    'authority_result', p_trace_input->>'authority_result',
    'state_before',    p_trace_input->>'state_before',
    'input_hash',      p_trace_input->>'input_hash',
    'trigger_source',  coalesce(nullif(p_trace_input->>'trigger_source',''),
                                'kernel door ' || p_component)));

  -- Everything the door said about its own subject is preserved on the trace rather than dropped:
  -- the run, the step run, the task and the door's original subject_ref stay readable.
  update public.phase_c_trace set
    run_id       = coalesce(nullif(p_trace_input->>'run_id','')::bigint, run_id),
    parent_trace_id = coalesce(
      nullif(p_trace_input->>'parent_trace_id','')::bigint,
      (select r.trace_id from public.phase_c_workflow_run r
        where r.run_id = nullif(p_trace_input->>'run_id','')::bigint),
      parent_trace_id),
    step_run_id  = coalesce(nullif(p_trace_input->>'step_run_id','')::bigint, step_run_id),
    task_id      = coalesce(nullif(p_trace_input->>'task_id','')::bigint, task_id),
    evidence_refs = coalesce(evidence_refs,'[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'door_subject_kind', p_trace_input->>'subject_kind',
      'door_subject_ref',  p_trace_input->>'subject_ref',
      'door_evidence',     p_trace_input->'evidence_refs'))
  where trace_id = v_trace;

  return public.fn_kernel_system_execution_close(v_trace, jsonb_build_object(
    'result',      v_result,
    'state_after', p_trace_input->>'state_after',
    'output_hash', p_trace_input->>'output_hash',
    'failure',     case when v_result = 'failed' then p_trace_input->>'failure' end));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_open_step(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_pd_dispatch jsonb := '{}'::jsonb;  -- D36
  s public.phase_b_workflow_step%rowtype;
  v_run       bigint := nullif(p_input->>'run_id','')::bigint;
  v_step      text   := nullif(btrim(coalesce(p_input->>'step_id','')), '');
  v_owner     text   := nullif(btrim(coalesce(p_input->>'owner_role_id','')), '');
  v_src_kind  text   := coalesce(nullif(p_input->>'source_kind',''), 'workflow_progression');
  v_src_ref   text   := coalesce(nullif(p_input->>'source_ref',''), 'kernel:step_engine');
  v_command   bigint := nullif(p_input->>'command_id','')::bigint;
  v_priority  text   := coalesce(nullif(p_input->>'priority',''), 'P2');
  v_object    text   := coalesce(nullif(p_input->>'business_object_id',''), '');
  v_in_hash   text   := coalesce(nullif(p_input->>'input_hash',''), '');
  v_reason    text   := coalesce(nullif(p_input->>'opened_because',''), '(no reason stated)');
  v_step_run  bigint;
  v_task      bigint;
  v_st_trace  bigint;
  v_tk_trace  bigint;
  v_tk_parent bigint;
  v_wf        text;
  v_idem      text;
begin
  if v_run is null or v_step is null or v_owner is null then
    raise exception 'fn_kernel_open_step: run_id, step_id and owner_role_id are all required (got %, %, %)',
      coalesce(v_run::text,'(null)'), coalesce(v_step,'(null)'), coalesce(v_owner,'(null)')
      using errcode = '22023';
  end if;

  select * into s from public.phase_b_workflow_step where step_id = v_step;
  if not found then
    raise exception 'fn_kernel_open_step: % is not in the frozen Phase B step registry — fail closed',
      v_step using errcode = '23503';
  end if;
  select workflow_id into v_wf from public.phase_c_workflow_run where run_id = v_run;
  if v_wf is null then
    raise exception 'fn_kernel_open_step: no workflow run %', v_run using errcode = '23503';
  end if;
  if v_wf is distinct from s.workflow_id then
    raise exception 'fn_kernel_open_step: run % is workflow % and step % belongs to % — refused',
      v_run, v_wf, v_step, s.workflow_id using errcode = '23514';
  end if;
  -- Owners are never defaulted. A step whose owner does not resolve is not opened.
  if not public.fn_phase_c_actor_may_own(v_owner) then
    raise exception 'fn_kernel_open_step: % does not resolve to an active canonical role, so step % is not opened',
      v_owner, v_step using errcode = '23514';
  end if;

  -- phase_c_step_run_live_uk is UNIQUE (run_id, step_id) WHERE state is not terminal, so a second
  -- live step run for the same step is refused by the index. Report it as the specific thing it is.
  if exists (select 1 from public.phase_c_workflow_step_run r
              where r.run_id = v_run and r.step_id = v_step
                and r.state not in ('completed','cancelled','failed','superseded','skipped')) then
    raise exception 'fn_kernel_open_step: run % already has a live step run for % — a second one would be a duplicate of work in flight',
      v_run, v_step using errcode = '23505';
  end if;

  v_idem := s.idempotency_scope || '|' || v_run || '|' || v_step || '|kernel';

  -- No trace_id on the insert: z90_phase_c_step_run_trace_subject mints TRACE-STEP AFTER INSERT
  -- and parents it to the run's root trace.
  insert into public.phase_c_workflow_step_run
    (run_id, step_id, accountable_role_id, reviewer_role_id, state, attempt_no,
     input_hash, output_hash, gates_evaluated, authority_result, idempotency_key)
  values (v_run, v_step, v_owner, coalesce(s.independent_reviewer_role_id,''), 'active', 1,
          v_in_hash, '', '[]'::jsonb, 'pending: the step has not been executed yet', v_idem)
  returning step_run_id into v_step_run;
  if v_step_run is null then
    raise exception 'fn_kernel_open_step: the step run insert produced no row for %', v_step
      using errcode = '23502';
  end if;

  select trace_id into v_st_trace from public.phase_c_workflow_step_run where step_run_id = v_step_run;
  if v_st_trace is null then
    raise exception 'fn_kernel_open_step: step run % has no trace', v_step_run using errcode = '23502';
  end if;

  -- EXACTLY ONE task, on the same deterministic key fn_kernel_workflow_start uses. That key is
  -- also what makes the legacy delivery fan-out a no-op rather than a duplicate.
  v_task := public.fn_phase_c_task_create(jsonb_build_object(
    'source_kind', v_src_kind, 'source_ref', v_src_ref,
    'command_id', v_command, 'run_id', v_run, 'workflow_id', s.workflow_id, 'step_id', v_step,
    'accountable_role_id', v_owner,
    'objective', format('%s (%s) for %s — opened because %s',
                        s.step_id, s.step_name, coalesce(nullif(v_object,''),'this run'), v_reason),
    'required_inputs', s.required_inputs,
    'requested_output', s.required_output,
    'acceptance_criteria', s.acceptance_criteria,
    'closure_criteria', s.closure_criteria,
    'priority', v_priority,
    'reviewer_required', (coalesce(s.independent_reviewer_role_id,'') <> ''),
    'reviewer_role_id', coalesce(s.independent_reviewer_role_id,''),
    'idempotency_key', 'run:' || v_run || ':step:' || v_step));
  if v_task is null then
    raise exception 'fn_kernel_open_step: no task was created for run % step %', v_run, v_step
      using errcode = '23502';
  end if;

  select trace_id into v_tk_trace from public.phase_c_task where task_id = v_task;
  select parent_trace_id into v_tk_parent from public.phase_c_trace where trace_id = v_tk_trace;
  if v_tk_trace is null or v_tk_parent is null then
    raise exception 'fn_kernel_open_step: task % has trace % with parent % — a task without its parented trace is refused',
      v_task, coalesce(v_tk_trace::text,'null'), coalesce(v_tk_parent::text,'null')
      using errcode = '23502';
  end if;

  -- ---- PHASE D DISPATCH (D36) ------------------------------------------------------------------
  -- The step is open, owned, tasked and traced. If the frozen registry binds a deterministic Phase D
  -- handler to it, this is where that handler runs — not in a harness, and not behind an endpoint
  -- nothing calls. fn_phase_d_dispatch_step never raises: a refusal is recorded in
  -- public.phase_d_dispatch, because a handler refusing five frames down must not roll back the
  -- business write that caused the step to open.
  v_pd_dispatch := public.fn_phase_d_dispatch_step(jsonb_build_object(
    'step_run_id', v_step_run, 'actor_role_id', v_owner,
    'opened_by_kind', v_src_kind, 'opened_by_ref', v_src_ref,
    'idempotency_key', v_idem, 'correlation_id', p_input->>'correlation_id'));

  return jsonb_build_object('step_run_id', v_step_run, 'task_id', v_task, 'step_id', v_step,
    'owner_role_id', v_owner, 'step_trace_id', v_st_trace, 'task_trace_id', v_tk_trace,
    'reviewer_required', (coalesce(s.independent_reviewer_role_id,'') <> ''),
    'reviewer_role_id', coalesce(s.independent_reviewer_role_id,''),
    'idempotency_key', v_idem);
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_orphaned_work()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with dead as (
    select c.command_id from public.founder_command c where c.state in ('cancelled','superseded')
  ), dead_runs as (
    select r.run_id from public.phase_c_workflow_run r
     where r.command_id in (select command_id from dead)
        or r.state in ('cancelled','superseded')
  )
  select 'live_tasks_of_cancelled_commands',  '0',
         count(*) filter (where t.state in ('queued','assigned','accepted','in_progress','blocked'))::text
           || ' of ' || count(*)::text,
         count(*) filter (where t.state in ('queued','assigned','accepted','in_progress','blocked')) = 0
    from public.phase_c_task t
   where t.command_id in (select command_id from dead) or t.run_id in (select run_id from dead_runs)
  union all
  select 'live_runs_of_cancelled_commands', '0',
         count(*) filter (where r.state not in ('cancelled','superseded','completed','failed'))::text
           || ' of ' || count(*)::text,
         count(*) filter (where r.state not in ('cancelled','superseded','completed','failed')) = 0
    from public.phase_c_workflow_run r where r.command_id in (select command_id from dead)
  union all
  select 'live_step_runs_of_cancelled_runs', '0',
         count(*) filter (where s.state not in ('cancelled','completed','failed','superseded'))::text
           || ' of ' || count(*)::text,
         count(*) filter (where s.state not in ('cancelled','completed','failed','superseded')) = 0
    from public.phase_c_workflow_step_run s where s.run_id in (select run_id from dead_runs)
  union all
  select 'open_handoffs_of_cancelled_runs', '0',
         count(*) filter (where h.status = 'open')::text || ' of ' || count(*)::text,
         count(*) filter (where h.status = 'open') = 0
    from public.phase_c_handoff_run h where h.run_id in (select run_id from dead_runs)
  union all
  select 'undelivered_outbox_of_cancelled_commands', '0',
         count(*) filter (where o.status in ('pending','claimed','retry_wait'))::text
           || ' of ' || count(*)::text,
         count(*) filter (where o.status in ('pending','claimed','retry_wait')) = 0
    from public.phase_c_event_outbox o
   where (o.payload->>'command_id') in (select command_id::text from dead)
  union all
  select 'open_traces_of_cancelled_subjects', '0',
         count(*) filter (where tr.sealed_at is null)::text || ' of ' || count(*)::text,
         count(*) filter (where tr.sealed_at is null) = 0
    from public.phase_c_trace tr
   where tr.command_id in (select command_id from dead) or tr.run_id in (select run_id from dead_runs);
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_outbox_deliver(p_limit integer DEFAULT 25, p_worker text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c record; r record; v_attempt bigint; v_worker text;
  v_ok int := 0; v_retry int := 0; v_dead int := 0; v_claimed int := 0;
  v_err text; v_state text; v_retryable boolean;
begin
  v_worker := coalesce(nullif(btrim(p_worker),''), 'pid:' || pg_backend_pid()::text);

  -- Claim: FOR UPDATE SKIP LOCKED, one statement, attempts incremented at claim so a crash cannot
  -- lose the count. coalesce on next_attempt_at because the column is now nullable and a NULL
  -- there would silently make a row unclaimable forever. The 15-minute lease is the fix for the
  -- other half of the old defect: the raise aborted the pass and left every claimed row in
  -- 'claimed', which fn_phase_c_outbox_claim never looks at again.
  for c in
    update public.phase_c_event_outbox o set
      status = 'claimed', claimed_at = now(), attempts = o.attempts + 1
    where o.outbox_id in (
      select s.outbox_id from public.phase_c_event_outbox s
       where (s.status in ('pending','retry_wait') and coalesce(s.next_attempt_at, now()) <= now())
          or (s.status = 'claimed' and s.claimed_at < now() - interval '15 minutes')
       order by s.outbox_id
       for update skip locked
       limit greatest(1, coalesce(p_limit, 25)))
    returning o.*
  loop
    v_claimed := v_claimed + 1;

    -- BEFORE the consumer runs. This insert is outside the handler below on purpose: when the
    -- consumer raises, its subtransaction rolls back and this row is the only surviving evidence
    -- that the attempt happened at all.
    insert into public.phase_c_event_delivery_attempt
      (outbox_id, attempt_no, started_at, ok, worker_id)
    values (c.outbox_id, c.attempts, clock_timestamp(), false, v_worker)
    returning attempt_id into v_attempt;

    -- THE MARK GOES HERE, NOT ONLY IN THE CONSUMER. The first rehearsal of this file proved why:
    -- with the mark set only inside fn_kernel_event_consume, a consumer swapped for another body
    -- carried no mark, called fn_kernel_workflow_start, and CREATED A RUN FROM DELIVERY — status
    -- delivered, runs_created=1. Delivery is the thing that is delivery; whichever consumer runs
    -- inside it is inside it.
    perform set_config('kernel.in_delivery', '1', true);
    begin
      select * into r from public.fn_kernel_event_consume(c.outbox_id);
      if r is null or r.handled is null then
        v_err := 'consumer returned no verdict'; v_retryable := false;   -- null is not success
      elsif r.handled then
        v_err := null; v_retryable := null;
      else
        v_err := coalesce(r.reason, 'consumer declined without a reason'); v_retryable := false;
      end if;
    exception when others then
      v_err := SQLSTATE || ' ' || SQLERRM;
      -- Only infrastructure faults are worth trying again. A constraint violation or a bad payload
      -- fails identically forever, and retrying it hides it.
      v_retryable := SQLSTATE in ('40001','40P01','55P03','57014','53100','53200','53300',
                                  '08000','08003','08006');
      r := null;
    end;
    -- Reset outside the block so it happens on the exception path too. (A subtransaction abort
    -- would restore a GUC set inside the block, but not one set before it.)
    perform set_config('kernel.in_delivery', '0', true);

    if v_err is null then
      update public.phase_c_event_delivery_attempt set
        finished_at = clock_timestamp(), ok = true, downstream_ref = coalesce(r.downstream_ref,''),
        result_hash = encode(sha256(convert_to(coalesce(r.result::text,''), 'UTF8')), 'hex'),
        retryable = null
      where attempt_id = v_attempt;
      -- delivered is written in the success branch and nowhere else
      update public.phase_c_event_outbox set
        status = 'delivered', delivered_at = now(), last_error = '', next_attempt_at = null
      where outbox_id = c.outbox_id;
      v_ok := v_ok + 1;

    else
      v_state := case when v_retryable and c.attempts < c.max_attempts then 'retry_wait'
                      else 'dead_letter' end;
      update public.phase_c_event_delivery_attempt set
        finished_at = clock_timestamp(), ok = false, error = left(v_err, 500),
        result_hash = '', retryable = v_retryable
      where attempt_id = v_attempt;
      update public.phase_c_event_outbox set
        status = v_state,
        last_error = left(v_err, 500),
        last_sqlstate = left(coalesce(substring(v_err from '^[0-9A-Z]{5}'), ''), 5),
        -- the FIRST failure is the diagnosis; a retry must not overwrite it. Both sides are
        -- timestamptz now, and the column is nullable, so this coalesce can finally do its job.
        first_failure = coalesce(first_failure, now()),
        first_failure_reason = coalesce(first_failure_reason, left(v_err, 500)),
        next_attempt_at = case when v_state = 'retry_wait'
                               then now() + (interval '1 minute' * power(2, least(c.attempts, 6)))
                               else null end
      where outbox_id = c.outbox_id;
      if v_state = 'retry_wait' then v_retry := v_retry + 1; else v_dead := v_dead + 1; end if;
    end if;
  end loop;

  return jsonb_build_object('worker', v_worker, 'claimed', v_claimed, 'delivered', v_ok,
                            'retry_wait', v_retry, 'dead_letter', v_dead, 'at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_outbox_emit(p_input jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  e public.phase_b_event%rowtype;
  v_id bigint;
  v_event  text := nullif(btrim(coalesce(p_input->>'event_id','')), '');
  v_dedupe text := nullif(btrim(coalesce(p_input->>'dedupe_value','')), '');
  v_prod   text := coalesce(nullif(btrim(p_input->>'producer'),''), 'kernel:unnamed');
  v_corr   text := nullif(btrim(coalesce(p_input->>'correlation_id','')), '');
  v_caus   text := nullif(btrim(coalesce(p_input->>'causation_id','')), '');
  v_src    text := nullif(btrim(coalesce(p_input->>'source_id','')), '');
  v_consumer text;
begin
  select * into e from public.phase_b_event where event_id = v_event;
  if not found then
    raise exception 'fn_kernel_outbox_emit: % is not in the frozen Phase B event registry — fail closed',
      coalesce(v_event,'(null)') using errcode = '23503';
  end if;
  if v_dedupe is null then
    raise exception 'fn_kernel_outbox_emit: dedupe_value is required for %', v_event using errcode = '23502';
  end if;
  if v_corr is null or v_caus is null or v_src is null then
    raise exception 'fn_kernel_outbox_emit: % is missing identity (correlation_id=%, causation_id=%, source_id=%)',
      v_event, coalesce(v_corr,'(null)'), coalesce(v_caus,'(null)'), coalesce(v_src,'(null)')
      using errcode = '23514';
  end if;

  select role_id into v_consumer from public.fn_phase_c_resolve_actor(e.primary_consumer_role_id);
  v_consumer := coalesce(v_consumer, e.primary_consumer_role_id);

  insert into public.phase_c_event_outbox
    (event_id, workflow_id, object_version, producer, accountable_role_id, primary_consumer_role_id,
     payload, dedupe_value, status, correlation_id, causation_id, source_id,
     command_id, workflow_run_id, step_run_id, task_id, trace_id)
  values (e.event_id, e.workflow_id, coalesce((p_input->>'object_version')::bigint, 1),
          v_prod, v_consumer, coalesce(e.primary_consumer_role_id,''),
          coalesce(p_input->'payload', '{}'::jsonb), v_dedupe, 'pending',
          v_corr, v_caus, v_src,
          nullif(p_input->>'command_id','')::bigint,
          nullif(p_input->>'workflow_run_id','')::bigint,
          nullif(p_input->>'step_run_id','')::bigint,
          -- ROOT CAUSE 2. The relationship a cancellation follows must be a COLUMN. task_id was the
          -- one missing normalised link: every producer already carries it in the payload it emits,
          -- so it is read from the explicit input first and from the payload second, and never
          -- looked up from JSON again after this point.
          coalesce(nullif(p_input->>'task_id','')::bigint,
                   nullif(p_input->'payload'->>'task_id','')::bigint),
          nullif(p_input->>'trace_id','')::bigint)
  on conflict (event_id, dedupe_value) do nothing
  returning outbox_id into v_id;

  -- A duplicate is not a new row and it is not an error: re-read the one that already exists.
  if v_id is null then
    select outbox_id into v_id from public.phase_c_event_outbox
     where event_id = e.event_id and dedupe_value = v_dedupe;
  end if;
  -- Error and empty must not return the same value.
  if v_id is null then
    raise exception 'fn_kernel_outbox_emit wrote no row and found none for %/%', v_event, v_dedupe
      using errcode = '23502';
  end if;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_outbox_refuse_cancelled_subject()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_why text;
begin
  -- Only the transition INTO delivered is guarded. Claiming, retrying and superseding are allowed.
  if new.status is distinct from 'delivered' or old.status = 'delivered' then
    return new;
  end if;

  select string_agg(x, '; ') into v_why from (
    select 'founder command ' || c.command_id || ' is ' || c.state as x
      from public.founder_command c
     where c.command_id = new.command_id and c.state in ('cancelled','superseded')
    union all
    select 'workflow run ' || r.run_id || ' is ' || r.state
      from public.phase_c_workflow_run r
     where r.run_id = new.workflow_run_id and r.state in ('cancelled','superseded')
    union all
    select 'step run ' || sr.step_run_id || ' is ' || sr.state
      from public.phase_c_workflow_step_run sr
     where sr.step_run_id = new.step_run_id and sr.state in ('cancelled','superseded')
    union all
    select 'task ' || t.task_id || ' is ' || t.state
      from public.phase_c_task t
     where t.task_id = new.task_id and t.state in ('cancelled','superseded')
  ) s;

  if v_why is null then
    return new;
  end if;

  new.status       := 'superseded';
  new.delivered_at := null;
  new.last_error   := 'DELIVERY REFUSED ' || to_char(now(),'YYYY-MM-DD HH24:MI') || ': '
                   || v_why || ' (fn_kernel_outbox_refuse_cancelled_subject). The event is kept as '
                   || 'the record that it was produced; it is not delivered, because the work it '
                   || 'describes has been cancelled.';
  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_paid_provider_gate(p_model text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_switch  boolean;
  v_routes  bigint;
  v_held    bigint;
  v_model   text := nullif(btrim(coalesce(p_model, '')), '');
  v_reg     boolean;
  v_open    timestamptz;
begin
  -- An EMPTY STRING is not a deterministic path, it is a caller that did not say. Denied, with its
  -- own rule name, because "I passed you nothing" and "I am not calling a provider" are different
  -- statements and a gate that conflates them has a hole shaped like a typo.
  if p_model is not null and v_model is null then
    return jsonb_build_object('allowed', false, 'gate', 'kernel_k12',
      'rule', 'model_unspecified',
      'reason', 'an empty model string is not a deterministic path; pass NULL or ''none'' to declare '
             || 'that no provider call is being made', 'model', p_model);
  end if;

  -- A deterministic path is not a provider call and never was. It is named explicitly rather than
  -- reached by falling off the end of the checks.
  if v_model is null or v_model in ('none', 'none/deterministic') then
    return jsonb_build_object('allowed', true, 'gate', 'kernel_k12',
      'rule', 'deterministic_path', 'reason', 'no provider call is being made', 'model', p_model);
  end if;

  -- 1. the explicit switch
  select exists (select 1 from public.app_secrets
                  where key = 'no_paid_ai' and lower(coalesce(value,'')) in ('1','true','yes','on'))
    into v_switch;
  if v_switch then
    return jsonb_build_object('allowed', false, 'gate', 'kernel_k12',
      'rule', 'no_paid_ai_switch', 'reason', 'app_secrets.no_paid_ai is set; paid inference is off',
      'model', v_model);
  end if;

  -- 2. empty route state is DENIED, not permitted. An absent hold is not a permission — this is the
  --    "what does it print when its input is absent?" case, answered on purpose.
  select count(*) into v_routes from public.llm_route_health;
  if v_routes = 0 then
    return jsonb_build_object('allowed', false, 'gate', 'kernel_k12',
      'rule', 'empty_route_state',
      'reason', 'llm_route_health holds no rows; with no route state there is no evidence that any '
             || 'route is permitted', 'model', v_model);
  end if;

  -- 3. the founder's hold, on ANY route. He held the whole estate on 15 Aug 2026; holding one route
  --    and leaving the others open would not be what he asked for.
  select count(*) into v_held from public.llm_route_health where open_until is not null and open_until > now();
  if v_held > 0 then
    return jsonb_build_object('allowed', false, 'gate', 'kernel_k12',
      'rule', 'founder_hold',
      'reason', v_held || ' of ' || v_routes || ' routes are held open-circuit until '
             || (select max(open_until)::text from public.llm_route_health where open_until > now()),
      'held', v_held, 'routes', v_routes, 'model', v_model);
  end if;

  -- 4. the route must be registered and active
  select exists (select 1 from public.model_registry r where r.model_id = v_model and r.active) into v_reg;
  if not v_reg then
    return jsonb_build_object('allowed', false, 'gate', 'kernel_k12',
      'rule', 'route_not_registered',
      'reason', 'model ' || v_model || ' is not an active row in model_registry', 'model', v_model);
  end if;

  -- 5. this route's own breaker
  select open_until into v_open from public.llm_route_health where model_id = v_model;
  if v_open is not null and v_open > now() then
    return jsonb_build_object('allowed', false, 'gate', 'kernel_k12',
      'rule', 'route_open', 'reason', 'circuit open until ' || v_open::text, 'model', v_model);
  end if;

  return jsonb_build_object('allowed', true, 'gate', 'kernel_k12',
    'rule', 'registered_breaker_closed', 'reason', 'switch off, no hold, route registered, breaker closed',
    'model', v_model);
exception
  -- The gate itself failing is the most dangerous case, because it is the one a try/catch upstream
  -- used to swallow. It answers DENIED, in its own voice, rather than throwing into a caller that
  -- might interpret an exception as "carry on".
  when others then
    return jsonb_build_object('allowed', false, 'gate', 'kernel_k12',
      'rule', 'gate_unreadable',
      'reason', 'the paid-provider gate could not be evaluated: ' || sqlstate || ' ' || sqlerrm,
      'model', p_model);
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_paid_provider_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select 'gate_denies_a_registered_route', 'false',
         (public.fn_kernel_paid_provider_gate(
            coalesce((select model_id from public.model_registry where active order by model_id limit 1),
                     'anthropic/claude-sonnet-5'))->>'allowed'),
         (public.fn_kernel_paid_provider_gate(
            coalesce((select model_id from public.model_registry where active order by model_id limit 1),
                     'anthropic/claude-sonnet-5'))->>'allowed') = 'false'
  union all
  select 'gate_denies_an_unregistered_route', 'false',
         (public.fn_kernel_paid_provider_gate('zz/not-a-real-model')->>'allowed'),
         (public.fn_kernel_paid_provider_gate('zz/not-a-real-model')->>'allowed') = 'false'
  union all
  select 'gate_allows_the_deterministic_path', 'true',
         (public.fn_kernel_paid_provider_gate(null)->>'allowed'),
         (public.fn_kernel_paid_provider_gate(null)->>'allowed') = 'true'
  union all
  select 'routes_held_by_the_founder', 'all',
         count(*) filter (where open_until > now())::text || ' of ' || count(*)::text,
         count(*) > 0 and count(*) filter (where open_until > now()) = count(*)
    from public.llm_route_health
  union all
  select 'paid_inference_rows_since_the_hold', '0',
         (select count(*) from public.llm_attempt
           where created_at > (select min(updated_at) from public.llm_route_health))::text,
         (select count(*) from public.llm_attempt
           where created_at > (select min(updated_at) from public.llm_route_health)) = 0;
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_record_maintenance_write(p_db_user text, p_session_role text, p_table text, p_op text, p_reason text, p_stack text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  insert into public.kernel_maintenance_write
    (db_user, session_role, table_name, operation, reason, call_stack)
  values (p_db_user, p_session_role, p_table, p_op, p_reason, p_stack);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_retired_grant_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
with g as (
  select r.path_name, r.disposition,
         coalesce((select string_agg(rp.grantee || ':' || rp.privilege_type, ', ')
                     from information_schema.routine_privileges rp
                    where rp.routine_schema = 'public' and rp.routine_name = r.path_name
                      and rp.grantee in ('anon','authenticated','service_role','PUBLIC')), '') ordinary
    from public.kernel_retired_path r
)
select 'retired_paths_executable_by_an_ordinary_role'::text,
       '0 of ' || (select count(*)::text from g),
       (select count(*)::text from g where ordinary <> '') || ' of ' || (select count(*)::text from g)
         || coalesce(' [' || (select string_agg(path_name || ' -> ' || ordinary, '; ')
              from g where ordinary <> '') || ']', ''),
       (select count(*) = 0 from g where ordinary <> '')
union all
select 'retired_paths_with_a_recorded_final_state',
       (select count(*)::text from g) || ' of ' || (select count(*)::text from g),
       (select string_agg(disposition || ' ' || n::text, '; ' order by disposition)
          from (select disposition, count(*) n from g group by 1) d),
       (select count(*) = 0 from g where coalesce(btrim(disposition),'') = '')
union all
-- A compatibility wrapper must reach the kernel and nothing else. Measured from the deployed body,
-- comments stripped, because both wrappers discuss the kernel in prose.
select 'compatibility_wrappers_not_calling_the_kernel',
       '0 of ' || (select count(*)::text from g where disposition = 'COMPATIBILITY_WRAPPER_TO_KERNEL'),
       (select count(*)::text from g
         join pg_proc p on p.proname = g.path_name
         join pg_namespace n on n.oid = p.pronamespace and n.nspname = 'public'
        where g.disposition = 'COMPATIBILITY_WRAPPER_TO_KERNEL'
          and regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g')
              !~ '\yfn_kernel_')
         || ' of ' || (select count(*)::text from g where disposition = 'COMPATIBILITY_WRAPPER_TO_KERNEL'),
       (select count(*) = 0 from g
         join pg_proc p on p.proname = g.path_name
         join pg_namespace n on n.oid = p.pronamespace and n.nspname = 'public'
        where g.disposition = 'COMPATIBILITY_WRAPPER_TO_KERNEL'
          and regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g')
              !~ '\yfn_kernel_');
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_retired_path_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- Every check below counts over the FULL register, never over a filtered subset, so a path that
  -- is quietly removed from the register cannot make a number improve.
  select 'old_cron_jobs_invoking_old_runtime', '0',
         count(*) filter (where j.active)::text || ' of ' || count(*)::text,
         count(*) filter (where j.active) = 0
    from cron.job j
   where exists (select 1 from public.kernel_retired_path r
                  where r.disposition <> 'KERNEL_INTERNAL_PRIMITIVE'
                    and j.command like '%' || r.path_name || '%')
  union all
  select 'direct_grants_permitting_kernel_bypass', '0',
         count(*)::text || ' of ' || (select count(*) from public.kernel_retired_path)::text,
         count(*) = 0
    from public.kernel_retired_path r
    join pg_proc p on p.proname = r.path_name
    join pg_namespace n on n.oid = p.pronamespace and n.nspname = 'public'
   where has_function_privilege('anon', p.oid, 'EXECUTE')
      or has_function_privilege('authenticated', p.oid, 'EXECUTE')
  union all
  select 'active_callers_of_disabled_paths', '0',
         count(*)::text || ' of ' || (select count(*) from public.kernel_retired_path
                                       where disposition = 'DISABLED')::text,
         count(*) = 0
    from public.kernel_retired_path r
    join pg_proc p on p.prosrc like '%' || r.path_name || '%'
    join pg_namespace n on n.oid = p.pronamespace and n.nspname = 'public'
   where r.disposition = 'DISABLED'
     and p.proname <> r.path_name
     and p.proname not like 'fn_kernel_%'
     and p.proname not in ('fn_phase_c_event_binding_status', 'fn_phase_c_invariants',
                           'fn_kernel_retired_path_state')
  union all
  select 'paths_with_no_recorded_disposition', '0',
         count(*)::text || ' of ' || count(*)::text, count(*) = 0
    from (select unnest(array['fn_phase_c_event_ingress','fn_phase_c_event_consume',
                              'fn_phase_c_outbox_deliver','fn_phase_c_outbox_settle',
                              'fn_phase_c_workflow_start','fn_phase_c_step_advance',
                              'fn_phase_c_task_create','fn_phase_c_outbox_claim']) pn) x
   where not exists (select 1 from public.kernel_retired_path r where r.path_name = x.pn)
  union all
  -- The three primitives are reached only from fn_kernel_* today. This measures that, rather than
  -- claiming it: any NON-kernel routine whose source names a primitive is counted. The two retired
  -- wrappers are excluded by name because they are the retirement, not a bypass of it.
  --
  -- 18 AUG 2026 — THE PREDICATE WAS `prosrc like '%' || path_name || '%'`, AND A PREFIX IS NOT A CALL.
  -- The final acceptance audit found this check red at 1 of 9. The single row was
  -- fn_phase_c_task_state_guard against the primitive fn_phase_c_task_transition — and that guard
  -- never calls it. `like` matched because the primitive's name is a PREFIX of a different, longer
  -- function: fn_phase_c_task_transition_allowed, which is a pure predicate. A substring match
  -- reported a bypass that does not exist, on a board nothing else reads.
  --
  -- Now: comments are stripped first, so naming a primitive in an error message or a note is not a
  -- call; and the name must be followed by an opening parenthesis with a word boundary in front,
  -- which is what a call looks like. `_` is a word character in Postgres regex, so `\yfn_x\y` does
  -- not match inside `fn_x_allowed` — that is the whole fix.
  select 'kernel_primitives_called_from_outside_the_kernel', '0',
         count(*)::text || ' of ' || (select count(*) from public.kernel_retired_path
                                       where disposition = 'KERNEL_INTERNAL_PRIMITIVE')::text,
         count(*) = 0
    from public.kernel_retired_path r
    join pg_proc p on regexp_replace(regexp_replace(p.prosrc, '/\*.*?\*/', ' ', 'g'), '--[^\n]*', ' ', 'g')
                      ~ ('\y' || r.path_name || '\y\s*\(')
    join pg_namespace n on n.oid = p.pronamespace and n.nspname = 'public'
   where r.disposition = 'KERNEL_INTERNAL_PRIMITIVE'
     and p.proname <> r.path_name
     and p.proname not like 'fn_kernel_%'
     and p.proname not in ('fn_phase_c_event_ingress','fn_phase_c_event_consume',
                           'fn_phase_c_outbox_deliver','fn_phase_c_step_advance',
                           'fn_phase_c_invariants','fn_phase_c_event_binding_status');
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_review_decide(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_task     bigint := nullif(regexp_replace(coalesce(p_input->>'task_id',''), '\D', '', 'g'), '')::bigint;
  v_reviewer text   := coalesce(btrim(p_input->>'reviewer_role_id'), '');
  v_decision text   := lower(coalesce(btrim(p_input->>'decision'), ''));
  v_reason   text   := coalesce(btrim(p_input->>'reason'), '');
  t          public.phase_c_task%rowtype;
  v_declared text;
  v_trace    bigint;
begin
  if v_decision not in ('approved','rejected','changes_requested') then
    raise exception 'fn_kernel_review_decide: decision must be approved, rejected or changes_requested, got %',
      v_decision using errcode = '22023';
  end if;
  if v_reason = '' then
    raise exception 'fn_kernel_review_decide: a review with no stated reason is not a review'
      using errcode = '23514';
  end if;

  select * into t from public.phase_c_task where task_id = v_task;
  if not found then
    return jsonb_build_object('ok', false, 'error','task_not_found', 'task_id', v_task);
  end if;

  -- The declared reviewer comes from the FROZEN Phase B registry, read never written.
  select nullif(btrim(s.independent_reviewer_role_id), '') into v_declared
    from public.phase_b_workflow_step s where s.step_id = t.step_id;

  -- Compare RESOLVED, not literal: the registry may name a role and the caller an alias of it.
  -- fn_phase_c_resolve_actor is set-returning, so each side is pulled out in its own scalar
  -- subquery — calling it directly inside a boolean expression raises 42804.
  if v_declared is not null
     and (select role_id from public.fn_phase_c_resolve_actor(v_reviewer))
         is distinct from (select role_id from public.fn_phase_c_resolve_actor(v_declared)) then
    return jsonb_build_object('ok', false, 'error','not_the_declared_reviewer',
      'declared', v_declared, 'offered', v_reviewer, 'step_id', t.step_id,
      'message','Phase B names the independent reviewer for this step. It is frozen, and this is '
             || 'not that role.');
  end if;

  if not public.fn_kernel_reviewer_independent(t.accountable_role_id, v_reviewer) then
    return jsonb_build_object('ok', false, 'error','reviewer_not_independent',
      'creator', t.accountable_role_id, 'reviewer', v_reviewer,
      'message','The reviewer resolves to the same employee as the creator under at least one of '
             || 'the two identity vocabularies. A self-review is not a review.');
  end if;

  v_trace := public.fn_phase_c_trace_write('TRACE-ROLE-ACTION', jsonb_build_object(
    'subject_kind','task', 'subject_ref', t.task_id::text, 'task_id', t.task_id,
    'command_id', t.command_id, 'run_id', t.run_id,
    'actor_role_id', v_reviewer, 'reviewer_role_id', v_reviewer, 'reviewer_independent', true,
    'manager_role_id', t.manager_role_id, 'system_actor_id','system.workflow_engine',
    'state_before', t.state, 'state_after', t.state,
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'review_decision', v_decision, 'reason', v_reason,
      'declared_reviewer', coalesce(v_declared,'(none declared for this step)'))),
    'status','sealed'));

  update public.phase_c_task
     set reviewer_role_id = v_reviewer
   where task_id = v_task;

  return jsonb_build_object('ok', true, 'task_id', v_task, 'reviewer_role_id', v_reviewer,
    'decision', v_decision, 'declared_reviewer', v_declared, 'trace_id', v_trace,
    'independent', true);
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_review_integrity()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select 'phase_b_steps_declaring_a_self_review', '0 of steps with a declared reviewer',
         count(*) filter (where not public.fn_kernel_reviewer_independent(
                                   s.accountable_role_id, s.independent_reviewer_role_id))::text
           || ' of ' || count(*)::text,
         count(*) filter (where not public.fn_kernel_reviewer_independent(
                                   s.accountable_role_id, s.independent_reviewer_role_id)) = 0
    from public.phase_b_workflow_step s
   where coalesce(btrim(s.independent_reviewer_role_id), '') <> ''
  union all
  select 'tasks_reviewed_by_their_own_owner', '0 of tasks with a reviewer',
         count(*) filter (where not public.fn_kernel_reviewer_independent(
                                   t.accountable_role_id, t.reviewer_role_id))::text
           || ' of ' || count(*)::text,
         count(*) filter (where not public.fn_kernel_reviewer_independent(
                                   t.accountable_role_id, t.reviewer_role_id)) = 0
    from public.phase_c_task t
   where coalesce(btrim(t.reviewer_role_id), '') <> ''
  union all
  select 'tasks_requiring_review_with_no_reviewer', '0 of tasks requiring review',
         count(*) filter (where coalesce(btrim(t.reviewer_role_id), '') = '')::text
           || ' of ' || count(*)::text,
         count(*) filter (where coalesce(btrim(t.reviewer_role_id), '') = ''
                            and t.state in ('completed')) = 0
    from public.phase_c_task t where t.reviewer_required
  union all
  -- NOT a pass/fail gate. It is reported because it is the thing that would make the two
  -- independence answers diverge, and a number nobody prints is a number nobody watches.
  select 'roles_whose_two_resolvers_disagree', 'reported, not gated',
         count(*) filter (where public.fn_org_agent_resolve(r.role_id)
                            is distinct from (select role_id from public.fn_phase_c_resolve_actor(r.role_id)))::text
           || ' of ' || count(*)::text,
         true
    from public.org_role r;
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_reviewer_independent(p_creator text, p_reviewer text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  a_pc text; b_pc text;   -- the Phase C canonical resolver
  a_or text; b_or text;   -- the org-layer alias resolver
begin
  -- An absent reviewer is not an independent reviewer. Absence is never a pass.
  if coalesce(btrim(p_reviewer), '') = '' or coalesce(btrim(p_creator), '') = '' then
    return false;
  end if;

  select role_id into a_pc from public.fn_phase_c_resolve_actor(p_creator);
  select role_id into b_pc from public.fn_phase_c_resolve_actor(p_reviewer);
  -- An identity that does not resolve is refused, not waved through. A null here used to mean
  -- "cannot tell", and "cannot tell" must not be spendable as "yes".
  if a_pc is null or b_pc is null then return false; end if;
  if a_pc = b_pc then return false; end if;

  a_or := coalesce(public.fn_org_agent_resolve(p_creator), a_pc);
  b_or := coalesce(public.fn_org_agent_resolve(p_reviewer), b_pc);
  if a_or = b_or then return false; end if;

  -- Cross-vocabulary collapse: the creator under one resolver and the reviewer under the other.
  if a_pc = b_or or a_or = b_pc then return false; end if;

  return true;
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_routine_ownership(p_proname text, p_identity_args text DEFAULT ''::text, p_source_kind text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_want_sch  text;
  v_want_name text;
  v_args      text := coalesce(p_identity_args, '');
  v_matches   int;
  v_sch       text;
  v_owner     text;
  v_ext       text;
  v_lang      text;
  v_src       text;
  v_file      text;
  v_class     text;
  v_rule      text;
  v_evidence  text;
  -- The platform's own roles. Membership is read from pg_proc.proowner, which is a catalogue fact,
  -- not from the routine's name.
  c_platform_roles constant text[] := array[
    'supabase_admin', 'supabase_auth_admin', 'supabase_storage_admin', 'supabase_functions_admin',
    'supabase_realtime_admin', 'authenticator', 'pgbouncer', 'pgsodium_keyholder'];
  -- The managed product schemas. `extensions` is deliberately NOT here — see R3.
  c_platform_schemas constant text[] := array[
    'auth', 'storage', 'realtime', 'vault', 'graphql', 'graphql_public', 'pgbouncer', 'net',
    'cron', 'pgsodium', 'supabase_functions', 'supabase_migrations', '_realtime', '_analytics',
    '_supavisor'];
begin
  if position('.' in coalesce(p_proname, '')) > 0 then
    v_want_sch  := split_part(p_proname, '.', 1);
    v_want_name := split_part(p_proname, '.', 2);
  else
    v_want_sch  := null;
    v_want_name := p_proname;
  end if;

  select count(*) into v_matches
    from pg_proc p
    join pg_namespace ns on ns.oid = p.pronamespace
   where p.proname = v_want_name
     and pg_get_function_identity_arguments(p.oid) = v_args
     and ns.nspname not in ('pg_catalog', 'information_schema', 'pg_toast')
     and (v_want_sch is null or ns.nspname = v_want_sch);

  if v_matches = 0 then
    -- Not a verdict in the allowed class list, so the guard refuses any row claiming ownership of
    -- a routine that is not there. A ledger of code that does not exist is not a ledger.
    return jsonb_build_object(
      'ownership_class', 'ABSENT_FROM_CATALOG',
      'rule', 'R0_NOT_IN_PG_PROC',
      'evidence', format('no pg_proc entry for %s(%s) in any non-system schema', p_proname, v_args),
      'schema_name', null, 'identity_args', v_args);
  end if;
  if v_matches > 1 then
    return jsonb_build_object(
      'ownership_class', 'AMBIGUOUS_WITHOUT_SCHEMA',
      'rule', 'R0B_MORE_THAN_ONE_SCHEMA_MATCHES',
      'evidence', format('%s routines named %s(%s) — qualify the name with its schema',
                         v_matches, p_proname, v_args),
      'schema_name', null, 'identity_args', v_args);
  end if;

  -- Exactly one match. SELECT INTO here cannot leave the targets null-by-accident: the count above
  -- proved the row exists, and every column selected is NOT NULL in the catalogue except v_ext.
  select ns.nspname,
         pg_get_userbyid(p.proowner),
         (select e.extname
            from pg_depend d
            join pg_extension e on e.oid = d.refobjid
           where d.objid = p.oid and d.deptype = 'e'
           limit 1),
         l.lanname
    into v_sch, v_owner, v_ext, v_lang
    from pg_proc p
    join pg_namespace ns on ns.oid = p.pronamespace
    join pg_language l on l.oid = p.prolang
   where p.proname = v_want_name
     and pg_get_function_identity_arguments(p.oid) = v_args
     and ns.nspname not in ('pg_catalog', 'information_schema', 'pg_toast')
     and (v_want_sch is null or ns.nspname = v_want_sch);

  v_src := p_source_kind;
  if v_src is null then
    select k.source_kind, k.source_file
      into v_src, v_file
      from public.kernel_routine_ownership k
     where k.schema_name = v_sch
       and k.routine_name = v_want_name
       and k.identity_args = v_args;
    -- No row: SELECT INTO leaves both null, which is the correct reading — nothing has been
    -- recorded about this routine's repository provenance.
  end if;

  if v_ext is not null then
    v_class := 'EXTENSION_MANAGED';
    v_rule  := 'R1_PG_DEPEND_EXTENSION';
    v_evidence := format('pg_depend deptype=e binds %s.%s to extension %s', v_sch, v_want_name, v_ext);
  elsif v_owner = any (c_platform_roles) and v_sch = any (c_platform_schemas) then
    v_class := 'SUPABASE_MANAGED';
    v_rule  := 'R2_PLATFORM_ROLE_IN_PLATFORM_SCHEMA';
    v_evidence := format('proowner=%s in managed schema %s', v_owner, v_sch);
  elsif v_owner = any (c_platform_roles) and v_sch = 'extensions' then
    v_class := 'PLATFORM_INTERNAL';
    v_rule  := 'R3_PLATFORM_ROLE_IN_EXTENSIONS_SCHEMA';
    v_evidence := format('proowner=%s in schema extensions and NO extension owns it '
                         '(no pg_depend deptype=e) — platform bootstrap glue', v_owner);
  elsif v_owner = any (c_platform_roles) then
    v_class := 'SUPABASE_MANAGED';
    v_rule  := 'R2B_PLATFORM_ROLE';
    v_evidence := format('proowner=%s (a platform role) in schema %s', v_owner, v_sch);
  elsif v_src = 'MANIFEST' then
    v_class := 'QUOTESDONE_APPLICATION';
    v_rule  := 'R4_MANIFEST_DEFINES_IT';
    v_evidence := format('owner=%s, no extension, and a scripts/sql/MANIFEST.txt file defines it%s',
                         v_owner, coalesce(': ' || v_file, ''));
  elsif v_src = 'TRACKED_SQL_OUTSIDE_MANIFEST' then
    v_class := 'HISTORICAL_APPLICATION';
    v_rule  := 'R5_TRACKED_SQL_OUTSIDE_MANIFEST';
    v_evidence := format('owner=%s, no MANIFEST file defines it, tracked SQL elsewhere does%s',
                         v_owner, coalesce(': ' || v_file, ''));
  elsif v_src = 'NONE' then
    v_class := 'INTENTIONALLY_UNTRACKED_WITH_JUSTIFICATION';
    v_rule  := 'R6_NO_SOURCE_ANYWHERE_JUSTIFIED';
    v_evidence := format('owner=%s, lang=%s, and no tracked *.sql in the repository creates it',
                         v_owner, v_lang);
  else
    -- Application-owned and nothing said where it came from. Not a class; the guard refuses it.
    v_class := 'NO_PROVENANCE_RECORDED';
    v_rule  := 'R6_NO_PROVENANCE_RECORDED';
    v_evidence := format('owner=%s in schema %s is not platform-owned, and source_kind is %s — '
                         'the repository has not been asked where this came from',
                         v_owner, v_sch, coalesce(v_src, 'unrecorded'));
  end if;

  return jsonb_build_object(
    'ownership_class', v_class,
    'rule', v_rule,
    'evidence', v_evidence,
    'schema_name', v_sch,
    'identity_args', v_args,
    'owner', v_owner,
    'extension', v_ext);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_run_for(p_business_object_id text)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case when count(*) = 1 then min(r.run_id) end
    from public.phase_c_workflow_run r
   where r.business_object_id = p_business_object_id
     and r.state in (select state from public.phase_b_workflow_state where not terminal);
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_signal_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
with
-- The predicate is live: it reads the deployed body, comments stripped, so this check cannot be
-- satisfied by a promise in a comment. Comments are stripped because the body says in prose that
-- it must never call fn_kernel_workflow_start.
body as (
  select regexp_replace(regexp_replace(p.prosrc, '/\*.*?\*/', ' ', 'g'), '--[^\n]*', ' ', 'g') src
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'fn_kernel_signal_submit'
),
sig as (select * from public.kernel_signal_inbox),
runs_from_signals as (
  -- A workflow run whose dedupe_key or trace descends from a signal would be the defect this file
  -- exists to prevent. Measured against the ledger, not against intent.
  select count(*) n from public.phase_c_workflow_run r
   where exists (select 1 from sig s where s.correlation_id = 'signal:' || s.idempotency_key
                   and r.dedupe_key like '%' || s.source_id || '%'
                   and r.opened_at >= s.received_at)
)
select 'signal_service_can_create_a_workflow'::text,
       '0 — the body must not name fn_kernel_workflow_start',
       (select case when src ~ '\yfn_kernel_workflow_start\s*\(' then '1 — IT DOES' else '0' end
          from body),
       (select src !~ '\yfn_kernel_workflow_start\s*\(' from body)
union all
select 'signal_types_registered',
       'reported, not asserted',
       (select count(*)::text || ' registered, '
            || count(*) filter (where activation_state = 'active')::text || ' active, dispositions: '
            || coalesce(string_agg(distinct disposition, ', '), '(none)')
          from public.kernel_signal_type),
       true
union all
select 'signals_that_created_a_workflow_run',
       '0',
       (select n::text from runs_from_signals),
       (select n = 0 from runs_from_signals)
union all
select 'refused_signals_with_no_stated_reason',
       '0 of ' || (select count(*)::text from sig where status = 'refused'),
       (select count(*)::text from sig
         where status = 'refused' and coalesce(btrim(refusal_reason),'') = '')
         || ' of ' || (select count(*)::text from sig where status = 'refused'),
       (select count(*) = 0 from sig where status = 'refused' and coalesce(btrim(refusal_reason),'') = '')
union all
select 'signals_attached_to_a_run_that_does_not_exist',
       '0 of ' || (select count(*)::text from sig where status <> 'refused'),
       (select count(*)::text from sig s where s.status <> 'refused'
          and not exists (select 1 from public.phase_c_workflow_run r where r.run_id = s.workflow_run_id))
         || ' of ' || (select count(*)::text from sig where status <> 'refused'),
       (select count(*) = 0 from sig s where s.status <> 'refused'
          and not exists (select 1 from public.phase_c_workflow_run r where r.run_id = s.workflow_run_id))
union all
select 'signals_processed_without_a_trace',
       '0 of ' || (select count(*)::text from sig where status in ('attached','applied')),
       (select count(*)::text from sig where status in ('attached','applied') and trace_id is null)
         || ' of ' || (select count(*)::text from sig where status in ('attached','applied')),
       (select count(*) = 0 from sig where status in ('attached','applied') and trace_id is null)
union all
select 'duplicate_signal_delivery_applied_twice',
       '0',
       -- idempotency_key is UNIQUE, so this counts what the constraint already makes impossible.
       -- It stays because a future ALTER that drops the constraint must fail a check, not pass
       -- silently.
       (select count(*)::text from (
          select idempotency_key from sig group by idempotency_key having count(*) > 1) d),
       (select count(*) = 0 from (
          select idempotency_key from sig group by idempotency_key having count(*) > 1) d);
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_signal_submit(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_src_type  text   := nullif(btrim(coalesce(p_input->>'source_type','')), '');
  v_src_id    text   := nullif(btrim(coalesce(p_input->>'source_id','')), '');
  v_run       bigint := nullif(p_input->>'workflow_run_id','')::bigint;
  v_sig       text   := nullif(btrim(coalesce(p_input->>'signal_type','')), '');
  v_payload   jsonb  := coalesce(p_input->'payload', '{}'::jsonb);
  v_by        text   := nullif(btrim(coalesce(p_input->>'requested_by','')), '');
  v_idem      text;
  v_corr      text;
  v_caus      text;
  v_id        bigint;
  -- Scalars, never a RECORD read outside the branch that filled it.
  v_prior_id     bigint;
  v_prior_status text;
  v_prior_result jsonb;
  v_disp      text;
  v_sig_wf    text;
  v_sig_act   text;
  v_sig_sys   text;
  v_run_wf    text;
  v_run_state text;
  v_run_obj   text;
  v_run_trace bigint;
  v_step_run  bigint;
  v_step_id   text;
  v_step_owner text;
  v_task      bigint;
  v_trace     bigint;
  v_out       jsonb;
  v_refuse    text;
begin
  -- ---- 0. a delivery worker may never drive the request side -------------------------------
  perform public.fn_kernel_assert_not_in_delivery('fn_kernel_signal_submit');

  -- ---- 1. envelope. Nothing recordable in a malformed one -----------------------------------
  if v_src_type is null or v_src_id is null or v_sig is null or v_by is null then
    raise exception 'fn_kernel_signal_submit: source_type, source_id, signal_type and requested_by are all required (got %, %, %, %)',
      coalesce(v_src_type,'(null)'), coalesce(v_src_id,'(null)'), coalesce(v_sig,'(null)'),
      coalesce(v_by,'(null)') using errcode = '22023';
  end if;
  if jsonb_typeof(v_payload) <> 'object' then
    raise exception 'fn_kernel_signal_submit: payload must be a json object, got %',
      jsonb_typeof(v_payload) using errcode = '22023';
  end if;

  -- The key is the external identity of the signal. Defaulted from the source's own reference and
  -- the run it is about — never from now() or a sequence, because a key that differs every time
  -- is not a key and would let one webhook retry apply twice.
  v_idem := coalesce(nullif(btrim(p_input->>'idempotency_key'),''),
                     v_src_type || ':' || v_src_id || ':' || v_sig || ':' || coalesce(v_run::text,'-'));
  v_corr := coalesce(nullif(btrim(p_input->>'correlation_id'),''), 'signal:' || v_idem);
  v_caus := coalesce(nullif(btrim(p_input->>'causation_id'),''), v_src_type || ':' || v_src_id);

  -- ---- 2. idempotency, before anything is resolved and before anything happens --------------
  select s.signal_id, s.status, s.result into v_prior_id, v_prior_status, v_prior_result
    from public.kernel_signal_inbox s where s.idempotency_key = v_idem;
  if v_prior_id is not null then
    return jsonb_build_object('ok', v_prior_status <> 'refused', 'duplicate', true,
      'signal_id', v_prior_id, 'status', v_prior_status, 'result', v_prior_result,
      'reason', 'this signal has already been delivered; the first decision is the answer');
  end if;

  insert into public.kernel_signal_inbox
    (source_type, source_id, workflow_run_id, signal_type, payload, idempotency_key,
     correlation_id, causation_id, requested_by)
  values (v_src_type, v_src_id, v_run, v_sig, v_payload, v_idem, v_corr, v_caus, v_by)
  returning signal_id into v_id;

  -- ---- 3. the signal type must be registered and active ------------------------------------
  select t.disposition, t.workflow_id, t.activation_state, t.system_actor_id
    into v_disp, v_sig_wf, v_sig_act, v_sig_sys
    from public.kernel_signal_type t where t.signal_type = v_sig;
  if v_disp is null then
    v_refuse := format('signal type %L is not registered. A signal the kernel has never heard of '
                    || 'is not routed on a guess.', v_sig);
  elsif v_sig_act <> 'active' then
    v_refuse := format('signal type %L is registered with activation_state %L and does not accept '
                    || 'submissions.', v_sig, v_sig_act);
  end if;

  -- ---- 4. the run must exist, and must still be running -------------------------------------
  if v_refuse is null then
    if v_run is null then
      v_refuse := 'a signal about an existing workflow must name workflow_run_id. There is no '
               || 'lookup by business object here on purpose: guessing which run a signal belongs '
               || 'to is how one arrival lands on two runs.';
    else
      select r.workflow_id, r.state, r.business_object_id, r.trace_id
        into v_run_wf, v_run_state, v_run_obj, v_run_trace
        from public.phase_c_workflow_run r where r.run_id = v_run for update;
      if v_run_wf is null then
        v_refuse := format('workflow run %s does not exist.', v_run);
      elsif exists (select 1 from public.phase_b_workflow_state ws
                     where ws.state = v_run_state and ws.terminal) then
        v_refuse := format('workflow run %s is in terminal state %L. A closed run does not accept '
                        || 'signals; if this is new work it must come through '
                        || 'fn_kernel_trigger_submit and be judged on its own.', v_run, v_run_state);
      elsif v_sig_wf is not null and v_sig_wf is distinct from v_run_wf then
        v_refuse := format('signal type %L is declared for workflow %L and run %s is %L.',
                           v_sig, v_sig_wf, v_run, v_run_wf);
      end if;
    end if;
  end if;

  if v_refuse is not null then
    update public.kernel_signal_inbox
       set status = 'refused', refusal_reason = v_refuse, processed_at = now()
     where signal_id = v_id;
    return jsonb_build_object('ok', false, 'duplicate', false, 'signal_id', v_id,
      'status','refused', 'reason', v_refuse);
  end if;

  -- ---- 5. the signal is attached to the run it names, always --------------------------------
  -- Even a signal whose disposition changes nothing leaves a trace parented to the run's trace, so
  -- "we were told and did nothing" and "we were never told" can never be confused later.
  v_trace := public.fn_kernel_intake_execution('dbfn:fn_kernel_signal_submit(jsonb)', jsonb_build_object(
    'subject_kind','system_execution', 'subject_ref', 'signal:' || v_id::text, 'run_id', v_run,
    'actor_role_id', null, 'system_actor_id', v_sig_sys,
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'signal_id', v_id, 'signal_type', v_sig, 'disposition', v_disp,
      'source_type', v_src_type, 'source_id', v_src_id, 'idempotency_key', v_idem)),
    'state_before', v_run_state, 'state_after', v_run_state, 'status','complete'));
  update public.kernel_signal_inbox set trace_id = v_trace where signal_id = v_id;
  if v_run_trace is not null then
    -- parent_trace_id is set by fn_kernel_intake_execution BEFORE the trace is sealed (rc4).
  -- Setting it here would edit a sealed trace, which fn_phase_c_trace_append_only refuses.
  perform 1;
  end if;

  -- The run's currently active step, if it has one. Read once, used by three dispositions.
  select sr.step_run_id, sr.step_id, sr.accountable_role_id
    into v_step_run, v_step_id, v_step_owner
    from public.phase_c_workflow_step_run sr
   where sr.run_id = v_run and sr.state = 'active'
   order by sr.step_run_id limit 1;

  -- ---- 6. the declared disposition, and only that -------------------------------------------
  if v_disp = 'ATTACH_ONLY' then
    update public.kernel_signal_inbox
       set status = 'attached', step_run_id = v_step_run, processed_at = now(),
           result = jsonb_build_object('attached_to_run', v_run, 'active_step', v_step_id)
     where signal_id = v_id;
    return jsonb_build_object('ok', true, 'duplicate', false, 'signal_id', v_id,
      'status','attached', 'workflow_run_id', v_run, 'workflow_id', v_run_wf,
      'active_step_id', v_step_id, 'trace_id', v_trace, 'created_workflow_runs', 0);

  elsif v_disp = 'COMPLETE_STEP' then
    if v_step_run is null then
      v_refuse := format('run %s has no active step, so there is nothing for a COMPLETE_STEP '
                      || 'signal to complete.', v_run);
    elsif coalesce(jsonb_typeof(v_payload->'output'),'') <> 'object'
       or v_payload->'output' = '{}'::jsonb then
      v_refuse := format('signal type %L completes step %s and the payload carries no output '
                      || 'object. An output is what the step contract asks for; it is not '
                      || 'defaulted here, because a fabricated output certifies work nobody did.',
                         v_sig, v_step_id);
    end if;
    if v_refuse is not null then
      update public.kernel_signal_inbox
         set status = 'refused', refusal_reason = v_refuse, step_run_id = v_step_run,
             processed_at = now()
       where signal_id = v_id;
      return jsonb_build_object('ok', false, 'duplicate', false, 'signal_id', v_id,
        'status','refused', 'reason', v_refuse);
    end if;
    v_out := public.fn_kernel_step_complete(jsonb_build_object(
      'step_run_id',     v_step_run,
      'actor_role_id',   v_step_owner,
      'outcome',         coalesce(nullif(btrim(v_payload->>'outcome'),''), 'pass'),
      'idempotency_key', 'signal:' || v_idem,
      'reason',          coalesce(nullif(btrim(v_payload->>'reason'),''),
                                  'signal ' || v_sig || ' from ' || v_src_type || ':' || v_src_id),
      'inputs',          coalesce(v_payload->'inputs',
                                  jsonb_build_object('signal_id', v_id, 'signal_type', v_sig,
                                                     'source', v_src_type || ':' || v_src_id)),
      'output',          v_payload->'output',
      'evidence_ref',    'signal:' || v_id::text,
      'correlation_id',  v_corr, 'causation_id', v_caus));

  elsif v_disp = 'REVIEW_VERDICT' then
    select t.task_id into v_task from public.phase_c_task t
     where t.run_id = v_run and t.step_id = v_step_id order by t.task_id desc limit 1;
    if v_task is null or coalesce(btrim(v_payload->>'decision'),'') = '' then
      v_refuse := format('a REVIEW_VERDICT signal needs a task on the active step and a decision '
                      || 'in the payload (task %s, decision %L).',
                         coalesce(v_task::text,'none'), coalesce(v_payload->>'decision','(none)'));
      update public.kernel_signal_inbox
         set status = 'refused', refusal_reason = v_refuse, step_run_id = v_step_run,
             processed_at = now()
       where signal_id = v_id;
      return jsonb_build_object('ok', false, 'duplicate', false, 'signal_id', v_id,
        'status','refused', 'reason', v_refuse);
    end if;
    v_out := public.fn_kernel_review_decide(jsonb_build_object(
      'task_id',          v_task,
      'reviewer_role_id', v_payload->>'reviewer_role_id',
      'decision',         v_payload->>'decision',
      'reason',           coalesce(nullif(btrim(v_payload->>'reason'),''),
                                   'recorded from signal ' || v_id::text)));

  elsif v_disp = 'CANCEL' then
    v_out := public.fn_kernel_cancel(jsonb_build_object(
      'subject_kind', 'workflow_run',
      'subject_ref',  v_run::text,
      'op',           'cancel',
      'reason',       coalesce(nullif(btrim(v_payload->>'reason'),''),
                               'cancelled by signal ' || v_sig || ' from ' || v_src_type || ':' || v_src_id),
      'actor',        v_by));
  end if;

  update public.kernel_signal_inbox
     set status = 'applied', step_run_id = v_step_run, processed_at = now(), result = v_out
   where signal_id = v_id;

  return jsonb_build_object('ok', coalesce((v_out->>'ok')::boolean, true), 'duplicate', false,
    'signal_id', v_id, 'status','applied', 'disposition', v_disp,
    'workflow_run_id', v_run, 'workflow_id', v_run_wf, 'step_id', v_step_id,
    'trace_id', v_trace, 'created_workflow_runs', 0, 'result', v_out);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_signal_type_activation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_srcs text;
begin
  if new.activation_state = 'active' or new.activation_state = old.activation_state then
    return new;
  end if;
  select string_agg(c.source_component_id, ', ' order by c.source_component_id) into v_srcs
    from public.phase_c_source_cutover c
   where c.current_activation = 'ACTIVE' and c.target_step_or_signal = new.signal_type;
  if v_srcs is not null then
    raise exception
      'signal type %L cannot be moved to %L: % ACTIVE source(s) still point at it (%). Deactivate '
      'or repoint the source first — an active source pointing at an inactive type is refused at '
      'submission and reported as cut over, which is the defect root cause 3 closed.',
      new.signal_type, new.activation_state,
      (select count(*) from public.phase_c_source_cutover c
        where c.current_activation='ACTIVE' and c.target_step_or_signal = new.signal_type),
      v_srcs
      using errcode = '23514';
  end if;
  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_sla_due(p_sla_policy_id text, p_from timestamp with time zone DEFAULT now())
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select p_from + make_interval(mins => greatest(1, round(coalesce((
    select case
             when m[2] ilike 'minute%' then m[1]::numeric / 60.0
             when m[2] ilike 'day%'    then m[1]::numeric * 24.0
             when m[2] ilike 'week%'   then m[1]::numeric * 168.0
             else m[1]::numeric
           end
      from public.phase_b_sla_policy sp,
           lateral regexp_match(sp.target,
             '(\d+)\s*(?:business\s+|calendar\s+)?(minute|hour|day|week)') m
     where sp.sla_policy_id = p_sla_policy_id), 24) * 60))::int);
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_source_cutover_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
with
-- The population is recomputed from the catalogue every time, never read off this table: a check
-- whose denominator is a column the same migration writes goes green by emptying itself.
pop as (
  select * from public.v_kernel_trigger_source_derived
   where connection_state in ('CONNECTED_ACTIVE','CONNECTED_INACTIVE','INTENTIONALLY_RETIRED')
      or (coalesce(is_active_now,false) and coalesce(creates_work_now,false)
          and coalesce(disposition,'') <> 'FOUNDER_COMMAND_SURFACE')
      -- ...or it is already classified. The register may GROW when a new source appears and may
      -- never silently SHED a row because a flag on it moved.
      or source_key in (select source_component_id from public.phase_c_source_cutover)
),
c as (select * from public.phase_c_source_cutover),
act as (select * from c where current_activation = 'ACTIVE'),
protected(t) as (values
  ('phase_c_workflow_run'),('phase_c_workflow_step_run'),('phase_c_task'),('phase_c_handoff_run'),
  ('kernel_trigger_inbox'),('kernel_signal_inbox'),('phase_c_event_outbox'),('phase_c_refund_decision')),
-- A source and the routine it actually fires. Only database triggers and cron jobs can be resolved
-- to a routine from the catalogue; an Edge Function has no prosrc to read, and saying so is better
-- than pretending the scan covered it.
source_routine as (
  select s.source_component_id as source_key, p.oid, p.proname
    from public.phase_c_source_cutover s
    join pg_trigger tg on tg.tgname = split_part(s.source_component_id, ':', 3)
    join pg_class cl on cl.oid = tg.tgrelid and cl.relname = split_part(split_part(s.source_component_id, ':', 2), '.', 2)
    join pg_proc p on p.oid = tg.tgfoid
   where s.source_type = 'database_trigger' and not tg.tgisinternal
),
writes_business_work as (
  select sr.source_key, string_agg(distinct pr.t, ', ') tables
    from source_routine sr
    join pg_proc p on p.oid = sr.oid
    join protected pr on regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g')
         ~ ('(insert\s+into|update|delete\s+from)\s+(public\.)?' || pr.t || '\M')
   group by sr.source_key
)
select 'sources_in_the_population_with_no_classification'::text,
       '0 of ' || (select count(*)::text from pop),
       (select count(*)::text from pop p
         where not exists (select 1 from c where c.source_component_id = p.source_key))
         || ' of ' || (select count(*)::text from pop),
       (select count(*) = 0 from pop p
         where not exists (select 1 from c where c.source_component_id = p.source_key))
union all
select 'classified_sources_that_are_not_in_the_k10_inventory',
       '0 of ' || (select count(*)::text from c),
       (select count(*)::text from c
         where not exists (select 1 from public.kernel_trigger_source k
                            where k.source_key = c.source_component_id))
         || ' of ' || (select count(*)::text from c),
       (select count(*) = 0 from c
         where not exists (select 1 from public.kernel_trigger_source k
                            where k.source_key = c.source_component_id))
union all
select 'class_split',
       'reported, never counted as one backlog',
       (select string_agg(source_class || ' ' || n::text, '; ' order by source_class)
          from (select source_class, count(*) n from c group by 1) d),
       true
union all
select 'active_new_work_sources_not_pointed_at_the_trigger_adapter',
       '0 of ' || (select count(*)::text from act where source_class = 'A NEW_WORK_REQUEST'),
       (select count(*)::text from act
         where source_class = 'A NEW_WORK_REQUEST' and target_kernel_adapter <> 'fn_kernel_trigger_submit')
         || ' of ' || (select count(*)::text from act where source_class = 'A NEW_WORK_REQUEST'),
       (select count(*) = 0 from act
         where source_class = 'A NEW_WORK_REQUEST' and target_kernel_adapter <> 'fn_kernel_trigger_submit')
union all
select 'active_existing_run_signals_not_pointed_at_the_signal_adapter',
       '0 of ' || (select count(*)::text from act where source_class = 'B EXISTING_WORKFLOW_SIGNAL'),
       (select count(*)::text from act
         where source_class = 'B EXISTING_WORKFLOW_SIGNAL' and target_kernel_adapter <> 'fn_kernel_signal_submit')
         || ' of ' || (select count(*)::text from act where source_class = 'B EXISTING_WORKFLOW_SIGNAL'),
       (select count(*) = 0 from act
         where source_class = 'B EXISTING_WORKFLOW_SIGNAL' and target_kernel_adapter <> 'fn_kernel_signal_submit')
union all
-- K22c. THE class-C rule, measured as it is written: a monitor may not create business work, and
-- business work is the eight tables §7 protects. Scanned from the deployed body, and enforced
-- independently by K18 — so this line cannot be made green by relabelling a source.
select 'active_read_only_monitors_that_write_business_work',
       '0 of ' || (select count(*)::text from act where source_class = 'C READ_ONLY_MONITOR'),
       (select count(*)::text from act a join writes_business_work w on w.source_key = a.source_component_id
         where a.source_class = 'C READ_ONLY_MONITOR')
         || ' of ' || (select count(*)::text from act where source_class = 'C READ_ONLY_MONITOR')
         || coalesce(' [' || (select string_agg(a.source_component_id || ' -> ' || w.tables, '; ')
              from act a join writes_business_work w on w.source_key = a.source_component_id
             where a.source_class = 'C READ_ONLY_MONITOR') || ']', ''),
       (select count(*) = 0 from act a join writes_business_work w on w.source_key = a.source_component_id
         where a.source_class = 'C READ_ONLY_MONITOR')
union all
-- The old proxy, kept as a REPORTED line so a monitor that starts touching sibling tables is still
-- visible. It is not a pass/fail: writing a sibling row is what a normalising trigger is for.
select 'read_only_monitors_that_write_a_sibling_table',
       'reported, not a defect — a normalising trigger writes a sibling row by design',
       (select count(*)::text from act a join pop p on p.source_key = a.source_component_id
         where a.source_class = 'C READ_ONLY_MONITOR' and coalesce(p.creates_work_now,false))
         || ' of ' || (select count(*)::text from act where source_class = 'C READ_ONLY_MONITOR'),
       true
union all
select 'retired_sources_that_are_still_live_and_writing_business_work',
       '0 of ' || (select count(*)::text from c where source_class = 'D RETIRE_OR_HISTORICAL'),
       (select count(*)::text from c join writes_business_work w on w.source_key = c.source_component_id
         where c.source_class = 'D RETIRE_OR_HISTORICAL')
         || ' of ' || (select count(*)::text from c where source_class = 'D RETIRE_OR_HISTORICAL'),
       (select count(*) = 0 from c join writes_business_work w on w.source_key = c.source_component_id
         where c.source_class = 'D RETIRE_OR_HISTORICAL')
union all
select 'class_A_sources_whose_trigger_type_is_not_registered',
       '0 of ' || (select count(*)::text from c where source_class = 'A NEW_WORK_REQUEST'),
       (select count(*)::text from c where source_class = 'A NEW_WORK_REQUEST'
          and not exists (select 1 from public.kernel_trigger_type t
                           where t.trigger_type = c.target_step_or_signal))
         || ' of ' || (select count(*)::text from c where source_class = 'A NEW_WORK_REQUEST'),
       (select count(*) = 0 from c where source_class = 'A NEW_WORK_REQUEST'
          and not exists (select 1 from public.kernel_trigger_type t
                           where t.trigger_type = c.target_step_or_signal))
union all
select 'class_B_sources_whose_signal_type_is_not_registered',
       '0 of ' || (select count(*)::text from c where source_class = 'B EXISTING_WORKFLOW_SIGNAL'),
       (select count(*)::text from c where source_class = 'B EXISTING_WORKFLOW_SIGNAL'
          and not exists (select 1 from public.kernel_signal_type s
                           where s.signal_type = c.target_step_or_signal))
         || ' of ' || (select count(*)::text from c where source_class = 'B EXISTING_WORKFLOW_SIGNAL'),
       (select count(*) = 0 from c where source_class = 'B EXISTING_WORKFLOW_SIGNAL'
          and not exists (select 1 from public.kernel_signal_type s
                           where s.signal_type = c.target_step_or_signal))
union all
select 'sources_switched_off_today',
       'reported; an adapter existing is not a reason to activate one',
       (select count(*)::text from c where current_activation = 'DISABLED')
         || ' of ' || (select count(*)::text from c) || ' carry an adapter and stay disabled',
       true
union all
select 'active_sources_now_calling_a_kernel_adapter',
       'reported; it rises as each cutover increment lands',
       (select count(*)::text from source_routine sr
         join pg_proc p on p.oid = sr.oid
        where regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g')
              ~ '\yfn_kernel_source_emit\s*\(')
         || ' of ' || (select count(*)::text from act
                        where source_class in ('A NEW_WORK_REQUEST','B EXISTING_WORKFLOW_SIGNAL'))
         || ' active class-A/B sources reach the kernel (database triggers only — an Edge Function '
         || 'has no prosrc to scan, and saying so beats pretending the scan covered it)',
       true
union all
select 'routine_autonomous_work_routed_through_the_founder_or_chief_of_staff',
       '0 of ' || (select count(*)::text from act where source_class in
                    ('A NEW_WORK_REQUEST','B EXISTING_WORKFLOW_SIGNAL')),
       (select count(*)::text from act
         where source_class in ('A NEW_WORK_REQUEST','B EXISTING_WORKFLOW_SIGNAL')
           and accountable_role in ('founder','chief_of_staff'))
         || ' of ' || (select count(*)::text from act where source_class in
                        ('A NEW_WORK_REQUEST','B EXISTING_WORKFLOW_SIGNAL')),
       (select count(*) = 0 from act
         where source_class in ('A NEW_WORK_REQUEST','B EXISTING_WORKFLOW_SIGNAL')
           and accountable_role in ('founder','chief_of_staff'));
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_source_emit(p_source_key text, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_class   text;
  v_vocab   text;
  v_wf      text;
  v_actor   text;
  v_active  text;
  v_ref     text := nullif(btrim(coalesce(p_input->>'source_ref','')), '');
  v_run     bigint := nullif(p_input->>'workflow_run_id','')::bigint;
  v_out     jsonb;
  v_ctx     text;
begin
  select c.source_class, c.target_step_or_signal, c.target_workflow, c.system_actor,
         c.current_activation
    into v_class, v_vocab, v_wf, v_actor, v_active
    from public.phase_c_source_cutover c where c.source_component_id = p_source_key;

  if v_class is null then
    raise exception 'fn_kernel_source_emit: % is not in the source cutover register', p_source_key
      using errcode = '23503',
            hint = 'Every autonomous source is classified in public.phase_c_source_cutover. A '
                || 'source with no row has no route, and routing it on a guess is how one arrival '
                || 'lands on two workflows. Classify it in scripts/phase_c/source_classification.mjs '
                || 'and regenerate.';
  end if;

  if v_class = 'C READ_ONLY_MONITOR' then
    raise exception 'fn_kernel_source_emit: % is a READ_ONLY_MONITOR and may not create business work',
      p_source_key using errcode = '42501',
        hint = 'A monitor collects status and may update approved operational state. When a '
            || 'threshold is crossed it raises a SEPARATE class-A request under its own source '
            || 'key, with its own dedupe key and its own evidence — a different call, which looks '
            || 'like one.';
  end if;

  if v_class = 'D RETIRE_OR_HISTORICAL' then
    raise exception 'fn_kernel_source_emit: % is retired', p_source_key
      using errcode = '42501',
            hint = 'Retired means retired. If this source must live again it needs a row saying so, '
                || 'not a call.';
  end if;

  if v_ref is null then
    raise exception 'fn_kernel_source_emit: % supplied no source_ref', p_source_key
      using errcode = '22023',
            hint = 'source_ref is the external identity of the thing this is about — the inquiry '
                || 'id, the quote id, the transaction id. The idempotency key is built from it, '
                || 'and a key that is different every time is not a key.';
  end if;

  begin
    if v_class = 'A NEW_WORK_REQUEST' then
      v_out := public.fn_kernel_trigger_submit(jsonb_build_object(
        'source_class',    (select source_class from public.kernel_trigger_type
                             where trigger_type = v_vocab),
        'source_system',   p_source_key,
        'source_ref',      v_ref,
        'external_ref',    p_input->>'external_ref',
        'trigger_type',    v_vocab,
        'raw_payload',     coalesce(p_input->'raw_payload', '{}'::jsonb),
        'requested_by',    coalesce(nullif(btrim(p_input->>'requested_by'),''), v_actor),
        'object_version',  p_input->>'object_version',
        'priority',        p_input->>'priority',
        'idempotency_key', p_input->>'idempotency_key',
        'correlation_id',  p_input->>'correlation_id',
        'causation_id',    p_input->>'causation_id'));
    else
      -- K22b. There WAS a raise here for a NULL workflow_run_id, and it was wrong. A class-B
      -- source is a database trigger that fires on every row change; "this object has no live run
      -- right now" is the ordinary case, not a developer error, and raising turned it into a
      -- failed insert on quote_items and transactions. It is also not a silence to swallow:
      -- fn_kernel_signal_submit inserts the ledger row BEFORE it validates, so a signal with no
      -- run is recorded as a refused row carrying its reason — which is exactly what that table
      -- exists for. The check is deleted rather than moved: the door below already does it, and
      -- does it better.
      v_out := public.fn_kernel_signal_submit(jsonb_build_object(
        'source_type',     p_source_key,
        'source_id',       v_ref,
        'workflow_run_id', v_run,
        'signal_type',     v_vocab,
        'payload',         coalesce(p_input->'raw_payload', '{}'::jsonb),
        'requested_by',    coalesce(nullif(btrim(p_input->>'requested_by'),''), v_actor),
        'idempotency_key', p_input->>'idempotency_key',
        'correlation_id',  p_input->>'correlation_id',
        'causation_id',    p_input->>'causation_id'));
    end if;
  exception
    -- Deliberately narrow: the four raises above are the wrapper's own contract violations and
    -- must reach the developer, not be filed as a runtime fault. Everything else is a kernel
    -- fault, and a kernel fault must not stop a customer inserting an inquiry.
    when sqlstate '23503' or sqlstate '42501' or sqlstate '22023' then
      raise;
    when others then
      get diagnostics v_ctx = pg_context;
      insert into public.kernel_adapter_failure (source_key, input, sqlstate, message, call_stack)
      values (p_source_key, p_input, sqlstate, sqlerrm, v_ctx);
      return jsonb_build_object('ok', false, 'recorded_failure', true, 'source_key', p_source_key,
        'sqlstate', sqlstate, 'error', sqlerrm,
        'note', 'the kernel raised; the business row was not blocked and the fault is recorded in '
             || 'kernel_adapter_failure, where fn_kernel_source_emit_state fails while it is unresolved');
  end;

  return coalesce(v_out, '{}'::jsonb) || jsonb_build_object('source_key', p_source_key,
    'source_class', v_class, 'vocabulary', v_vocab, 'activation', v_active);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_source_emit_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
with f as (select * from public.kernel_adapter_failure)
select 'unresolved_adapter_failures'::text,
       '0 of ' || (select count(*)::text from f),
       (select count(*)::text from f where resolved_at is null)
         || ' of ' || (select count(*)::text from f)
         || coalesce(' [' || (select string_agg(distinct source_key || ' ' || sqlstate, ', ')
              from f where resolved_at is null) || ']', ''),
       (select count(*) = 0 from f where resolved_at is null)
union all
select 'sources_cut_over_to_the_wrapper',
       'reported; it rises as each increment lands',
       (select count(*)::text from pg_proc p join pg_namespace n on n.oid = p.pronamespace
         where n.nspname = 'public'
           and regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g')
               ~ '\yfn_kernel_source_emit\s*\(')
         || ' database routines call fn_kernel_source_emit',
       true
union all
-- The wrapper must not become a second way to reach the creator. It may call the two adapters and
-- nothing else; the check reads the DEPLOYED body with comments stripped, because the body
-- discusses fn_kernel_workflow_start in prose.
select 'wrapper_reaching_past_its_two_adapters',
       '0 — the body may name only fn_kernel_trigger_submit and fn_kernel_signal_submit',
       (select case when src ~ '\yfn_kernel_(workflow_start|open_step|step_complete|cancel|outbox_emit)\s*\('
                    then 'IT REACHES PAST THEM' else '0' end
          from (select regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g') src
                  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                 where n.nspname = 'public' and p.proname = 'fn_kernel_source_emit') b),
       (select src !~ '\yfn_kernel_(workflow_start|open_step|step_complete|cancel|outbox_emit)\s*\('
          from (select regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g') src
                  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                 where n.nspname = 'public' and p.proname = 'fn_kernel_source_emit') b);
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_source_signal_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_state text;
begin
  if new.current_activation <> 'ACTIVE' or new.source_class not like 'B %' then
    return new;
  end if;
  select t.activation_state into v_state
    from public.kernel_signal_type t where t.signal_type = new.target_step_or_signal;
  if v_state is null then
    raise exception
      'source % is ACTIVE and names signal type %L, which is not registered in kernel_signal_type. '
      'A signal the kernel has never heard of is refused at submission, so the source would be '
      'recorded as cut over while every delivery from it failed.',
      new.source_component_id, coalesce(new.target_step_or_signal,'(null)') using errcode = '23503';
  end if;
  if v_state <> 'active' then
    raise exception
      'source % is ACTIVE and names signal type %L, whose activation_state is %L. '
      'fn_kernel_signal_submit refuses every submission of an inactive type, so this source would '
      'be reported CUT_OVER while nothing it emits is ever accepted. Activate the type with a '
      'recorded reason, or set the source to DISABLED.',
      new.source_component_id, new.target_step_or_signal, v_state using errcode = '23514';
  end if;
  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_step_complete(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  sr  public.phase_c_workflow_step_run%rowtype;
  r   public.phase_c_workflow_run%rowtype;
  s   public.phase_b_workflow_step%rowtype;
  t   public.phase_c_task%rowtype;
  h   public.phase_b_handoff%rowtype;
  v_step_run  bigint := nullif(p_input->>'step_run_id','')::bigint;
  v_actor_in  text   := nullif(btrim(coalesce(p_input->>'actor_role_id','')), '');
  v_outcome   text   := lower(nullif(btrim(coalesce(p_input->>'outcome','')), ''));
  v_idem      text   := nullif(btrim(coalesce(p_input->>'idempotency_key','')), '');
  v_reason    text   := coalesce(btrim(p_input->>'reason'), '');
  v_output    jsonb  := p_input->'output';
  v_priority  text   := coalesce(nullif(p_input->>'priority',''), 'P2');
  v_actor     text;
  v_kind      text;
  v_owner     text;
  v_authority text;
  v_delegated boolean := false;
  v_target_st text;                       -- the step run's target state
  v_run_state text;                       -- the run's target state
  v_out_hash  text := '';
  v_ev_ref    text;
  v_gates     jsonb := '[]'::jsonb;
  v_gate      record;
  -- Separate scalars per callee. One shared RECORD would carry the shape of whichever
  -- set-returning function last filled it, and reading a field the new shape does not have
  -- RAISES rather than returning null.
  v_out_ok    boolean; v_out_reason text;
  v_gate_ok   boolean; v_gate_reason text;
  v_hop       text;
  v_from      text;
  v_now       text;
  v_hops      text[];
  v_tr        jsonb;
  v_completion bigint;
  v_prior     jsonb;
  -- progression
  v_sk        text; v_next_step text; v_next_owner text; v_handoff_id text;
  v_succ_state text; v_fail_state text; v_this_owner text; v_sk_reason text;
  v_opened    jsonb;
  v_handoff_run bigint;
  v_ho_trace  bigint;
  v_blockers  jsonb := '[]'::jsonb;
  v_n         bigint;
  v_rules     jsonb;
  v_step_ev   text;
  v_wf_ev     text;
  v_outbox_step bigint;
  v_outbox_wf   bigint;
  v_corr      text; v_caus text; v_src text;
  v_created_steps int := 0; v_created_tasks int := 0; v_created_handoffs int := 0;
  v_created_events int := 0;
  v_result    jsonb;
begin
  -- ---- 0. a consumer may not re-enter the producer ----------------------------------------
  perform public.fn_kernel_assert_not_in_delivery('fn_kernel_step_complete');

  if v_step_run is null or v_actor_in is null or v_idem is null then
    raise exception 'fn_kernel_step_complete: step_run_id, actor_role_id and idempotency_key are all required (got %, %, %)',
      coalesce(v_step_run::text,'(null)'), coalesce(v_actor_in,'(null)'), coalesce(v_idem,'(null)')
      using errcode = '22023';
  end if;
  if v_outcome is null or v_outcome not in ('pass','fail','block') then
    raise exception 'fn_kernel_step_complete: outcome must be pass, fail or block, got %',
      coalesce(v_outcome,'(null)') using errcode = '22023';
  end if;
  if v_outcome in ('fail','block') and v_reason = '' then
    raise exception 'fn_kernel_step_complete: outcome % requires a stated reason. An unexplained failure is not a record of anything.',
      v_outcome using errcode = '23514';
  end if;

  -- ---- 1. IDEMPOTENCY, claimed before any work --------------------------------------------
  select c.result into v_prior from public.phase_c_step_completion c where c.idempotency_key = v_idem;
  if v_prior is not null then
    return v_prior || jsonb_build_object('replay', true);
  end if;

  -- ---- 2. LOCK: run, then step run, then task. Always this order. --------------------------
  select run_id into v_n from public.phase_c_workflow_step_run where step_run_id = v_step_run;
  if v_n is null then
    raise exception 'fn_kernel_step_complete: no step run % (k3_step_run_not_found)', v_step_run
      using errcode = '23503';
  end if;
  select * into r from public.phase_c_workflow_run where run_id = v_n for update;
  if not found then
    raise exception 'fn_kernel_step_complete: step run % names workflow run %, which does not exist',
      v_step_run, v_n using errcode = '23503';
  end if;
  select * into sr from public.phase_c_workflow_step_run where step_run_id = v_step_run for update;
  if not found then
    raise exception 'fn_kernel_step_complete: no step run % (k3_step_run_not_found)', v_step_run
      using errcode = '23503';
  end if;
  select * into t from public.phase_c_task
   where run_id = r.run_id and step_id = sr.step_id order by task_id limit 1 for update;
  if not found then
    raise exception 'fn_kernel_step_complete: run % step % has no task. The kernel creates exactly one task per step run; completing a step with no task would close work nobody was ever asked to do. (k3_task_missing)',
      r.run_id, sr.step_id using errcode = '23503';
  end if;

  select * into s from public.phase_b_workflow_step where step_id = sr.step_id;
  if not found then
    raise exception 'fn_kernel_step_complete: step % is not in the frozen Phase B registry — fail closed',
      sr.step_id using errcode = '23503';
  end if;

  -- ---- 3. VERIFY -----------------------------------------------------------------------------
  -- 3a. the run must be running. Every path in this engine leaves the run at 'active' before the
  --     next step is executed, so anything else means this call is out of order.
  if r.state <> 'active' then
    raise exception 'fn_kernel_step_complete: workflow run % is in state %, not active — a step cannot be completed against a run that is not running (k3_run_not_active)',
      r.run_id, r.state using errcode = '23514';
  end if;

  -- 3b. the step run must be in a state the FROZEN step model allows to reach the target.
  v_target_st := case v_outcome when 'pass' then 'completed'
                                when 'fail' then 'failed' else 'blocked' end;
  if not exists (select 1 from public.phase_b_step_transition x
                  where x.from_state = sr.state and x.to_state = v_target_st) then
    raise exception 'fn_kernel_step_complete: step run % is in state % and the frozen Phase B step model declares no transition % -> % (k3_step_state_invalid)',
      v_step_run, sr.state, sr.state, v_target_st using errcode = '23514';
  end if;

  -- 3c. the ACTOR resolves, is active and canonical.
  select kind, role_id into v_kind, v_actor from public.fn_phase_c_resolve_actor(v_actor_in);
  if v_actor is null or v_kind is distinct from 'canonical' then
    raise exception 'fn_kernel_step_complete: actor % resolves to % — only an active canonical role may complete a step (k3_actor_unresolved)',
      v_actor_in, coalesce(v_kind,'nothing') using errcode = '23514';
  end if;

  -- 3d. the actor is the step run's accountable owner, or holds EXPLICIT delegated authority.
  --     Resolved on both sides, never string-matched: the registry may name a role and the caller
  --     an alias of it.
  v_owner := sr.accountable_role_id;
  if v_actor is distinct from (select role_id from public.fn_phase_c_resolve_actor(v_owner)) then
    select true into v_delegated
      from public.delegation_rule d
     where d.active
       and (select role_id from public.fn_phase_c_resolve_actor(d.when_agent)) = v_owner
       and (select role_id from public.fn_phase_c_resolve_actor(d.delegate_to)) = v_actor
     limit 1;
    if not coalesce(v_delegated, false) then
      raise exception 'fn_kernel_step_complete: step % is accountable to % and % holds no active delegation for it. Phase B froze step ownership; Phase C does not reassign it at runtime. (k3_not_the_accountable_owner)',
        sr.step_id, v_owner, v_actor using errcode = '23514';
    end if;
    v_authority := format('delegated: %s acted for %s under an active delegation_rule', v_actor, v_owner);
  else
    v_delegated := false;
    v_authority := format('accountable owner: %s', v_actor);
  end if;

  -- 3e. REQUIRED INPUTS. The registry states them as prose; K3 requires the caller to name what
  --     it actually used. An absent object is a refusal, never an empty pass.
  if coalesce(btrim(s.required_inputs),'') <> ''
     and coalesce(p_input->'inputs', 'null'::jsonb) in ('null'::jsonb, '{}'::jsonb) then
    raise exception 'fn_kernel_step_complete: step % declares required inputs (%) and the call names none. Send inputs as a non-empty object. (k3_required_inputs_missing)',
      sr.step_id, left(s.required_inputs, 120) using errcode = '22023';
  end if;

  -- 3f. OUTPUT. Three different absences are three different refusals, not one.
  if v_outcome = 'pass' then
    if not (p_input ? 'output') then
      raise exception 'fn_kernel_step_complete: step % passed with no output key at all. The step contract asks for %. (k3_output_key_absent)',
        sr.step_id, left(coalesce(s.required_output,'a structured output'), 120) using errcode = '22023';
    end if;
    if jsonb_typeof(v_output) = 'null' then
      raise exception 'fn_kernel_step_complete: step % sent output as a JSON null. A null is a stated absence of a result, not a result. (k3_output_is_json_null)',
        sr.step_id using errcode = '22023';
    end if;
    if jsonb_typeof(v_output) <> 'object' then
      raise exception 'fn_kernel_step_complete: step % sent output of type %, expected an object. (k3_output_not_an_object)',
        sr.step_id, jsonb_typeof(v_output) using errcode = '22023';
    end if;
    if v_output = '{}'::jsonb then
      raise exception 'fn_kernel_step_complete: step % sent an empty output object. An empty object is not evidence that anything was produced. (k3_output_empty)',
        sr.step_id using errcode = '22023';
    end if;
    select valid, reason into v_out_ok, v_out_reason
      from public.fn_phase_c_output_validate(s.required_output, v_output);
    if not coalesce(v_out_ok, false) then
      raise exception 'fn_kernel_step_complete: step % output is invalid: %. (k3_output_invalid)',
        sr.step_id, coalesce(v_out_reason,'(no reason returned)') using errcode = '22023';
    end if;
    -- The hash is over the OUTPUT. A constant is not evidence.
    v_out_hash := encode(sha256(convert_to(v_output::text, 'UTF8')), 'hex');
  end if;

  -- 3g. REVIEWER. Where Phase B names an independent reviewer for this step, a verdict from that
  --     reviewer must already exist. Independence is decided by fn_kernel_reviewer_independent —
  --     it is not re-implemented here.
  if v_outcome = 'pass' and coalesce(btrim(s.independent_reviewer_role_id),'') <> '' then
    if not exists (
      select 1 from public.phase_c_trace tr
       where tr.task_id = t.task_id
         and tr.trace_policy_id = 'TRACE-ROLE-ACTION'
         and tr.evidence_refs @> '[{"review_decision":"approved"}]'::jsonb
         and public.fn_kernel_reviewer_independent(sr.accountable_role_id, tr.reviewer_role_id)
         and (select role_id from public.fn_phase_c_resolve_actor(tr.reviewer_role_id))
             = (select role_id from public.fn_phase_c_resolve_actor(s.independent_reviewer_role_id))
    ) then
      raise exception 'fn_kernel_step_complete: step % names % as its independent reviewer and no approved, independent verdict from that role exists on task %. Record it with fn_kernel_review_decide first. (k3_reviewer_verdict_missing)',
        sr.step_id, s.independent_reviewer_role_id, t.task_id using errcode = '23514';
    end if;
  end if;

  -- 3h. GATES in scope. Hard gates block; phase_boundary gates are recorded, because they assert a
  --     property of the PHASE and not of this step's evidence.
  v_ev_ref := coalesce(nullif(p_input->>'evidence_ref',''),
                       'run:' || r.run_id || ':step:' || sr.step_id);
  for v_gate in select * from public.fn_phase_c_gates_for_step(sr.step_id) loop
    select passed, reason into v_gate_ok, v_gate_reason
      from public.fn_phase_c_gate_evaluate(v_gate.gate_id,
        jsonb_build_object('evidence_ref', v_ev_ref, 'actor_role_id', v_actor,
                           'step_id', sr.step_id, 'run_id', r.run_id, 'outcome', v_outcome));
    if v_gate.gate_type = 'hard' and not coalesce(v_gate_ok, false) and v_outcome = 'pass' then
      raise exception 'fn_kernel_step_complete: hard gate % refused step %: % (k3_gate_failed)',
        v_gate.gate_id, sr.step_id, coalesce(v_gate_reason,'(no reason returned)')
        using errcode = '23514';
    end if;
    v_gates := v_gates || jsonb_build_array(jsonb_build_object(
      'gate_id', v_gate.gate_id, 'gate_name', v_gate.gate_name, 'type', v_gate.gate_type,
      'passed', coalesce(v_gate_ok,false), 'reason', v_gate_reason,
      'blocking', (v_gate.gate_type = 'hard')));
  end loop;

  -- ---- 4. CLAIM THE IDEMPOTENCY KEY --------------------------------------------------------
  insert into public.phase_c_step_completion
    (idempotency_key, step_run_id, run_id, step_id, actor_role_id, outcome)
  values (v_idem, v_step_run, r.run_id, sr.step_id, v_actor, v_outcome)
  on conflict (idempotency_key) do nothing
  returning completion_id into v_completion;
  if v_completion is null then
    -- A concurrent caller committed the same key while we were verifying. Return THEIR result.
    select c.result into v_prior from public.phase_c_step_completion c where c.idempotency_key = v_idem;
    if v_prior is null then
      raise exception 'fn_kernel_step_complete: idempotency key % is claimed and carries no result — refusing to guess what the other caller did',
        v_idem using errcode = '23505';
    end if;
    return v_prior || jsonb_build_object('replay', true);
  end if;

  -- ---- 5. CLOSE THE TASK, then the STEP RUN, with their traces ------------------------------
  -- The task walks the Phase C task state model one declared hop at a time through
  -- fn_phase_c_task_transition, so every hop is guarded and traced. Hops that are not legal from
  -- the current state are skipped, and the ARRIVAL is asserted: an unreached terminal state raises
  -- rather than being reported as a close.
  v_hops := case v_outcome
              when 'pass'  then array['assigned','accepted','in_progress','completed']
              when 'fail'  then array['assigned','accepted','in_progress','failed']
              else              array['assigned','accepted','in_progress','blocked'] end;
  foreach v_hop in array v_hops loop
    select state into v_now from public.phase_c_task where task_id = t.task_id;
    continue when v_now = v_hop;
    continue when not public.fn_phase_c_task_transition_allowed(v_now, v_hop);
    v_tr := public.fn_phase_c_task_transition(t.task_id, v_hop, v_actor,
      jsonb_build_object('evidence', format('step %s %s by %s', sr.step_id, v_outcome, v_actor),
                         'output_hash', v_out_hash,
                         'blocker', case when v_hop = 'blocked' then v_reason else null end,
                         'blocker_owner_role_id', case when v_hop = 'blocked' then v_owner else null end));
    if not coalesce((v_tr->>'ok')::boolean, false) then
      raise exception 'fn_kernel_step_complete: task % refused the hop % -> %: %',
        t.task_id, v_now, v_hop, coalesce(v_tr->>'error','(no error given)') using errcode = '23514';
    end if;
  end loop;
  select state into v_now from public.phase_c_task where task_id = t.task_id;
  if v_now is distinct from v_hops[array_length(v_hops,1)] then
    raise exception 'fn_kernel_step_complete: task % stopped at % and never reached %. The Phase C task state model declares no path from there, so the step is NOT recorded as closed. (k3_task_close_failed)',
      t.task_id, v_now, v_hops[array_length(v_hops,1)] using errcode = '23514';
  end if;

  -- The output and the gates go on the trace while it is still OPEN; the state update below seals
  -- it through a00_phase_c_step_run_trace_guard.
  perform public.fn_phase_c_trace_advance(sr.trace_id, sr.state, false, jsonb_build_object(
    'output_hash', v_out_hash,
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'step_id', sr.step_id, 'outcome', v_outcome, 'actor_role_id', v_actor,
      'authority', v_authority, 'delegated', coalesce(v_delegated,false),
      'gates', v_gates, 'evidence_ref', v_ev_ref,
      'inputs_named', coalesce(p_input->'inputs', '{}'::jsonb),
      'reason', v_reason, 'idempotency_key', v_idem))));

  update public.phase_c_workflow_step_run
     set state = v_target_st, output_hash = v_out_hash, gates_evaluated = v_gates,
         authority_result = v_authority, finished_at = now(),
         failure_reason = case when v_outcome = 'pass' then '' else v_reason end
   where step_run_id = v_step_run;
  if not exists (select 1 from public.phase_c_workflow_step_run
                  where step_run_id = v_step_run and state = v_target_st) then
    raise exception 'fn_kernel_step_complete: step run % did not reach %', v_step_run, v_target_st
      using errcode = '23514';
  end if;

  -- ---- 6. PROGRESSION ------------------------------------------------------------------------
  select c.kind, c.next_step_id, c.next_owner_role_id, c.handoff_id, c.success_state,
         c.failure_state, c.this_owner_role_id, c.reason
    into v_sk, v_next_step, v_next_owner, v_handoff_id, v_succ_state, v_fail_state,
         v_this_owner, v_sk_reason
    from public.fn_kernel_step_successor(sr.step_id) c;

  if v_outcome in ('fail','block') then
    -- The FROZEN registry's failure target, never next_step_if_fail, which is prose in all 257.
    v_run_state := v_fail_state;

  elsif v_sk = 'closure' then
    v_run_state := v_succ_state;                                   -- 'completed' in all 30

    -- MANDATORY CLOSURE BLOCKERS. Each is measured, each can fire, and the current step and task
    -- are already closed above so they cannot count themselves.
    select count(*) into v_n from public.phase_c_workflow_step_run x
     where x.run_id = r.run_id
       and x.state not in ('completed','cancelled','failed','superseded','skipped');
    if v_n > 0 then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'blocker','open_step_runs', 'count', v_n,
        'detail',(select string_agg(x.step_id || '=' || x.state, ', ' order by x.step_id)
                    from public.phase_c_workflow_step_run x where x.run_id = r.run_id
                     and x.state not in ('completed','cancelled','failed','superseded','skipped'))));
    end if;

    select count(*) into v_n from public.phase_c_task x
     where x.run_id = r.run_id and x.state not in ('completed','cancelled','failed','superseded');
    if v_n > 0 then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'blocker','open_tasks', 'count', v_n,
        'detail',(select string_agg(x.task_id || '=' || x.state, ', ' order by x.task_id)
                    from public.phase_c_task x where x.run_id = r.run_id
                     and x.state not in ('completed','cancelled','failed','superseded'))));
    end if;

    select count(*) into v_n from public.phase_c_handoff_run x
     where x.run_id = r.run_id and x.status = 'open';
    if v_n > 0 then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'blocker','open_handoffs', 'count', v_n,
        'detail',(select string_agg(x.handoff_id, ', ' order by x.handoff_id)
                    from public.phase_c_handoff_run x
                   where x.run_id = r.run_id and x.status = 'open')));
    end if;

    -- Every step the workflow declares before the closure step must have been executed to a
    -- terminal state in THIS run. phase_b_workflow_step.step_no is 1..N with no gaps in all 30
    -- workflows, so this is exact rather than approximate.
    select count(*) into v_n from public.phase_b_workflow_step b
     where b.workflow_id = r.workflow_id and b.step_no < s.step_no
       and not exists (select 1 from public.phase_c_workflow_step_run x
                        where x.run_id = r.run_id and x.step_id = b.step_id
                          and x.state in ('completed','skipped','superseded'));
    if v_n > 0 then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'blocker','mandatory_steps_never_executed', 'count', v_n,
        'detail',(select string_agg(b.step_id, ', ' order by b.step_no)
                    from public.phase_b_workflow_step b
                   where b.workflow_id = r.workflow_id and b.step_no < s.step_no
                     and not exists (select 1 from public.phase_c_workflow_step_run x
                                      where x.run_id = r.run_id and x.step_id = b.step_id
                                        and x.state in ('completed','skipped','superseded')))));
    end if;

    -- The hard gates in scope were evaluated above and any failure already raised; they are
    -- restated in the closure evidence so the record names what was checked.
    if exists (select 1 from jsonb_array_elements(v_gates) g
                where (g->>'blocking')::boolean and not (g->>'passed')::boolean) then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'blocker','hard_gate_failed', 'count', 1, 'detail', v_gates::text));
    end if;

    if jsonb_array_length(v_blockers) > 0 then
      raise exception 'fn_kernel_step_complete: run % cannot close — % mandatory blocker class(es) are open: %. (k3_closure_blocked)',
        r.run_id, jsonb_array_length(v_blockers), v_blockers::text using errcode = '23514';
    end if;

    -- phase_b_business_rule holds 47 hard rules as PROSE with no machine predicate. They are
    -- RECORDED as the obligations in scope; they are not scored, because a scorer that always
    -- returns pass is worse than no scorer. This is a stated Phase C gap, not a silent one.
    select coalesce(jsonb_agg(jsonb_build_object('rule_id', b.rule_id, 'rule_name', b.rule_name)
                              order by b.rule_id), '[]'::jsonb)
      into v_rules
      from public.phase_b_business_rule b
     where b.rule_type = 'hard'
       and (lower(b.workflow_scope) = 'all'
            or r.workflow_id = any (string_to_array(replace(b.workflow_scope,' ',''), ';')));

  elsif v_sk = 'same_owner' then
    v_run_state := v_succ_state;

  elsif v_sk = 'cross_owner' then
    v_run_state := v_succ_state;

  else
    -- registry_gap_no_handoff, successor_owner_unresolved, successor_not_a_step,
    -- closure_flag_disagrees, unknown_step. A non-closure step with no valid successor FAILS
    -- VISIBLY. It never returns terminal success and never returns handled with no reason.
    raise exception 'fn_kernel_step_complete: step % passed and has no valid successor [%]: % (k3_no_valid_successor)',
      sr.step_id, v_sk, v_sk_reason using errcode = '23514';
  end if;

  -- ---- 7. WRITE THE NEXT THING ---------------------------------------------------------------
  if v_outcome = 'pass' and v_sk = 'same_owner' then
    -- No handoff is required and none is invented.
    v_opened := public.fn_kernel_open_step(jsonb_build_object(
      'run_id', r.run_id, 'step_id', v_next_step, 'owner_role_id', v_next_owner,
      'source_kind','workflow_progression',
      'source_ref', 'step_run:' || v_step_run, 'command_id', r.command_id,
      'business_object_id', r.business_object_id, 'priority', v_priority,
      'input_hash', v_out_hash,
      'opened_because', format('%s completed and %s keeps the same accountable owner', sr.step_id, v_next_step)));
    v_created_steps := 1; v_created_tasks := 1;

  elsif v_outcome = 'pass' and v_sk = 'cross_owner' then
    select * into h from public.phase_b_handoff where handoff_id = v_handoff_id;
    if not found then
      raise exception 'fn_kernel_step_complete: the classifier named handoff % and it is not in the registry',
        v_handoff_id using errcode = '23503';
    end if;
    -- The receiving step run and task are NOT created here. Accountability transfers on
    -- ACCEPTANCE, and fn_kernel_handoff_accept is where that happens.
    insert into public.phase_c_handoff_run
      (handoff_id, run_id, from_step_run_id, sending_role_id, receiving_role_id,
       business_object_id, object_version, packet_hash, requested_action, acceptance_criteria,
       return_owner_role_id, sla_policy_id, due_at, status, accountable_until_accept_role_id)
    values (h.handoff_id, r.run_id, v_step_run, h.sending_role_id, h.receiving_role_id,
            r.business_object_id, r.object_version,
            -- over the ACTUAL output that is being handed over
            encode(sha256(convert_to(jsonb_build_object(
              'from_step_id', sr.step_id, 'from_step_run_id', v_step_run,
              'business_object_id', r.business_object_id, 'object_version', r.object_version,
              'output', v_output)::text, 'UTF8')), 'hex'),
            h.required_packet, h.receiving_acceptance_criteria,
            h.return_owner_role_id, h.sla_policy_id,
            public.fn_kernel_sla_due(h.sla_policy_id), 'open', h.sending_role_id)
    returning handoff_run_id into v_handoff_run;
    if v_handoff_run is null then
      raise exception 'fn_kernel_step_complete: the registry declares handoff % for % and no handoff run was created',
        h.handoff_id, sr.step_id using errcode = '23502';
    end if;
    v_ho_trace := public.fn_phase_c_trace_write('TRACE-HANDOFF', jsonb_build_object(
      'subject_kind','handoff_run', 'subject_ref', v_handoff_run::text, 'run_id', r.run_id,
      'command_id', r.command_id, 'actor_role_id', h.sending_role_id,
      'system_actor_id','system.workflow_engine',
      'evidence_refs', jsonb_build_array(jsonb_build_object(
        'handoff_id', h.handoff_id, 'from_step_id', sr.step_id, 'to_step_id', v_next_step,
        'required_packet', h.required_packet, 'sla_policy_id', h.sla_policy_id,
        'output_hash', v_out_hash)),
      'output_hash', v_out_hash,
      'state_before','', 'state_after','open', 'status','open'));
    update public.phase_c_handoff_run set trace_id = v_ho_trace where handoff_run_id = v_handoff_run;
    update public.phase_c_trace set parent_trace_id = r.trace_id where trace_id = v_ho_trace;
    v_created_handoffs := 1;
  end if;

  -- ---- 8. MOVE THE RUN, as a declared and guarded transition ----------------------------------
  -- The closure evidence goes onto the run's root trace while it is still OPEN. The state update
  -- below then seals it through a00_kernel_workflow_run_trace_guard. Writing the evidence after
  -- the seal would create a superseding row instead of the record of this closure.
  if v_outcome = 'pass' and v_sk = 'closure' then
    perform public.fn_phase_c_trace_advance(r.trace_id, r.state, false, jsonb_build_object(
      'output_hash', v_out_hash,
      'evidence_refs', jsonb_build_array(jsonb_build_object(
        'closure_step_id', sr.step_id, 'closed_by', v_actor,
        'blockers_open_at_closure', v_blockers,
        'hard_business_rules_in_scope', coalesce(v_rules,'[]'::jsonb)))));
  end if;

  if v_run_state is distinct from r.state then
    update public.phase_c_workflow_run set state = v_run_state where run_id = r.run_id;
  end if;
  if v_outcome = 'pass' and v_sk = 'closure' then
    update public.phase_c_workflow_run
       set closed_at = now(),
           closure_evidence = jsonb_build_object(
             'closed_by', v_actor, 'closure_step_id', sr.step_id, 'step_run_id', v_step_run,
             'task_id', t.task_id, 'output_hash', v_out_hash, 'idempotency_key', v_idem,
             'gates_evaluated', v_gates,
             'hard_business_rules_in_scope', coalesce(v_rules,'[]'::jsonb),
             'blockers_open_at_closure', v_blockers, 'closed_at', now())
     where run_id = r.run_id;
  elsif v_outcome = 'pass' and v_sk = 'same_owner' then
    -- The successor step run is ACTIVE in this same transaction, so the run is running again.
    -- Both hops are declared in phase_b_workflow_transition; the guard enforces them.
    if v_run_state is distinct from 'active' then
      update public.phase_c_workflow_run set state = 'active' where run_id = r.run_id;
      v_run_state := 'active';
    end if;
  end if;

  -- ---- 9. EMIT, LAST, AND ONLY AFTER THE STATE CHANGE SUCCEEDED --------------------------------
  v_corr := coalesce(nullif(btrim(p_input->>'correlation_id'),''),
                     'run:' || r.run_id);
  v_caus := coalesce(nullif(btrim(p_input->>'causation_id'),''),
                     'step_run:' || v_step_run);
  v_src  := coalesce(nullif(btrim(p_input->>'source_id'),''),
                     'step_run:' || v_step_run);

  if v_outcome = 'pass' then
    v_step_ev := public.fn_phase_c_step_event(sr.step_id, 'completed');
    if v_step_ev is not null then
      v_outbox_step := public.fn_kernel_outbox_emit(jsonb_build_object(
        'event_id', v_step_ev, 'producer','kernel:step_complete',
        'object_version', r.object_version,
        'correlation_id', v_corr, 'causation_id', v_caus, 'source_id', v_src,
        'command_id', r.command_id, 'workflow_run_id', r.run_id, 'step_run_id', v_step_run,
        'trace_id', sr.trace_id,
        'dedupe_value', 'kernel:step_completed:' || v_step_run,
        'payload', jsonb_build_object(
          'fact','step.completed', 'workflow_id', r.workflow_id, 'run_id', r.run_id,
          'step_id', sr.step_id, 'step_run_id', v_step_run, 'task_id', t.task_id,
          'business_object_id', r.business_object_id, 'object_version', r.object_version,
          'actor_role_id', v_actor, 'accountable_role_id', v_owner,
          'delegated', coalesce(v_delegated,false),
          'output_hash', v_out_hash, 'successor_kind', v_sk, 'next_step_id', v_next_step,
          'handoff_run_id', v_handoff_run, 'run_state', v_run_state)));
      v_created_events := v_created_events + 1;
    end if;
  end if;

  if (v_outcome = 'pass' and v_sk = 'closure') then
    v_wf_ev := public.fn_phase_c_lifecycle_event(r.workflow_id, 'completed');
  elsif v_outcome in ('fail','block') then
    -- phase_b_event declares no .failed and no .cancelled event for any workflow. The factual
    -- record of a failed or blocked step is that the workflow is BLOCKED, which is exactly what
    -- failure_workflow_state says. Nothing is invented.
    v_wf_ev := public.fn_phase_c_lifecycle_event(r.workflow_id, 'blocked');
  end if;
  if v_wf_ev is not null then
    v_outbox_wf := public.fn_kernel_outbox_emit(jsonb_build_object(
      'event_id', v_wf_ev, 'producer','kernel:step_complete',
      'object_version', r.object_version,
      'correlation_id', v_corr, 'causation_id', v_caus, 'source_id', v_src,
      'command_id', r.command_id, 'workflow_run_id', r.run_id, 'step_run_id', v_step_run,
      'trace_id', r.trace_id,
      'dedupe_value', 'kernel:run_' || v_run_state || ':' || r.run_id || ':' || v_step_run,
      'payload', jsonb_build_object(
        'fact', 'workflow.' || v_run_state, 'workflow_id', r.workflow_id, 'run_id', r.run_id,
        'step_id', sr.step_id, 'step_run_id', v_step_run,
        'business_object_id', r.business_object_id, 'object_version', r.object_version,
        'accountable_role_id', r.accountable_role_id, 'closed_by', v_actor,
        'outcome', v_outcome, 'reason', v_reason,
        'closure_evidence', (select closure_evidence from public.phase_c_workflow_run
                              where run_id = r.run_id))));
    v_created_events := v_created_events + 1;
  end if;

  -- ---- 10. RESULT, stored on the claim so a replay returns THIS, not a recomputation ----------
  v_result := jsonb_build_object(
    'ok', true, 'replay', false,
    'run_id', r.run_id, 'workflow_id', r.workflow_id,
    'business_object_id', r.business_object_id, 'object_version', r.object_version,
    'step_id', sr.step_id, 'step_run_id', v_step_run, 'task_id', t.task_id,
    'outcome', v_outcome, 'step_run_state', v_target_st, 'run_state', v_run_state,
    'terminal_run', (v_run_state in (select state from public.phase_b_workflow_state where terminal)),
    'actor_role_id', v_actor, 'accountable_role_id', v_owner,
    'delegated', coalesce(v_delegated,false), 'authority', v_authority,
    'successor_kind', v_sk, 'successor_reason', v_sk_reason,
    'next_step_id', v_next_step, 'next_owner_role_id', v_next_owner,
    'handoff_id', v_handoff_id, 'handoff_run_id', v_handoff_run,
    'next_step_run_id', v_opened->'step_run_id', 'next_task_id', v_opened->'task_id',
    'output_hash', v_out_hash, 'gates_evaluated', v_gates,
    'closure_blockers', v_blockers,
    'hard_business_rules_in_scope', coalesce(v_rules,'[]'::jsonb),
    'run_trace_id', r.trace_id, 'step_trace_id', sr.trace_id, 'handoff_trace_id', v_ho_trace,
    'command_id', r.command_id, 'correlation_id', v_corr, 'causation_id', v_caus,
    'source_id', v_src, 'idempotency_key', v_idem,
    'event_step', v_step_ev, 'event_workflow', v_wf_ev,
    'outbox_step_id', v_outbox_step, 'outbox_workflow_id', v_outbox_wf,
    'created', jsonb_build_object('step_runs', v_created_steps, 'tasks', v_created_tasks,
                                  'handoffs', v_created_handoffs, 'events', v_created_events));

  update public.phase_c_step_completion set result = v_result where completion_id = v_completion;
  return v_result;
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_step_successor(p_step_id text)
 RETURNS TABLE(kind text, next_step_id text, next_owner_role_id text, handoff_id text, success_state text, failure_state text, this_owner_role_id text, reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  s public.phase_b_workflow_step%rowtype;
  n public.phase_b_workflow_step%rowtype;
  v_this text;
  v_next text;
  v_edge text;
begin
  select * into s from public.phase_b_workflow_step where step_id = p_step_id;
  if not found then
    kind := 'unknown_step';
    reason := format('%L is not a step in the frozen Phase B registry — fail closed', p_step_id);
    return next; return;
  end if;

  success_state := s.success_workflow_state;
  failure_state := s.failure_workflow_state;
  select role_id into v_this from public.fn_phase_c_resolve_actor(s.accountable_role_id);
  this_owner_role_id := v_this;

  -- Terminality: the sentinel AND the flag. Never an empty join against phase_b_handoff.
  if s.next_step_if_pass = 'WORKFLOW_COMPLETE' or s.is_closure_step then
    if not (s.next_step_if_pass = 'WORKFLOW_COMPLETE' and s.is_closure_step) then
      kind := 'closure_flag_disagrees';
      reason := format('step %s: next_step_if_pass=%L but is_closure_step=%s — the two statements '
                    || 'of terminality disagree and neither may be preferred silently',
                       s.step_id, s.next_step_if_pass, s.is_closure_step);
      return next; return;
    end if;
    kind := 'closure';
    reason := format('step %s is the declared closure step of %s', s.step_id, s.workflow_id);
    return next; return;
  end if;

  select * into n from public.phase_b_workflow_step where step_id = s.next_step_if_pass;
  if not found then
    kind := 'successor_not_a_step'; next_step_id := s.next_step_if_pass;
    reason := format('step %s declares successor %L, which is not a step in the registry',
                     s.step_id, s.next_step_if_pass);
    return next; return;
  end if;
  next_step_id := n.step_id;

  select role_id into v_next from public.fn_phase_c_resolve_actor(n.accountable_role_id);
  next_owner_role_id := v_next;
  if v_next is null or not public.fn_phase_c_actor_may_own(v_next) then
    kind := 'successor_owner_unresolved';
    reason := format('step %s declares successor %s, whose accountable_role_id %L does not resolve '
                  || 'to an active canonical role (%s). A category overlay advises and may never '
                  || 'own a task, so no step run and no task may be opened for it.',
                     s.step_id, n.step_id, n.accountable_role_id,
                     coalesce((select r.reason from public.fn_phase_c_resolve_actor(n.accountable_role_id) r),
                              'no reason returned'));
    return next; return;
  end if;

  select h.handoff_id into v_edge from public.phase_b_handoff h
   where h.from_step_id = s.step_id and h.to_step_id = n.step_id;
  handoff_id := v_edge;

  if v_this is not null and v_next = v_this then
    if v_edge is not null then
      -- Both owners resolve to one identity yet a formal handoff is declared. 0 of 227 today.
      kind := 'cross_owner';
      reason := format('step %s -> %s: the registry declares handoff %s; it is honoured even '
                    || 'though both owners resolve to %L', s.step_id, n.step_id, v_edge, v_this);
      return next; return;
    end if;
    kind := 'same_owner';
    reason := format('step %s -> %s: owner stays %L, so no handoff is owed and none is invented',
                     s.step_id, n.step_id, v_this);
    return next; return;
  end if;

  if v_edge is null then
    kind := 'registry_gap_no_handoff';
    reason := format('step %s declares successor %s and accountability moves from %L to %L, but '
                  || 'phase_b_handoff declares no edge for it. A handoff nobody owes will not be '
                  || 'invented; this is a Phase B registry gap and is refused visibly.',
                     s.step_id, n.step_id, coalesce(v_this,'(unresolved)'), v_next);
    return next; return;
  end if;

  kind := 'cross_owner';
  reason := format('step %s -> %s via handoff %s: accountability moves from %L to %L',
                   s.step_id, n.step_id, v_edge, coalesce(v_this,'(unresolved)'), v_next);
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_system_execution_begin(p_input jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_comp public.phase_c_component%rowtype; v_trace bigint;
begin
  select * into v_comp from public.phase_c_component where component_id = p_input->>'component_id';
  if not found then
    raise exception 'fn_kernel_system_execution_begin: component % is not registered', p_input->>'component_id'
      using errcode = '23503';
  end if;
  if coalesce(btrim(p_input->>'correlation_id'),'') = ''
     or coalesce(btrim(p_input->>'causation_id'),'') = '' then
    raise exception 'fn_kernel_system_execution_begin: correlation_id and causation_id are required '
      'at BEGIN. An execution that cannot be joined to what caused it is not traceable afterwards '
      'by adding the ids later.' using errcode = '23514';
  end if;

  v_trace := public.fn_phase_c_trace_write('TRACE-SYSTEM-EXECUTION', jsonb_build_object(
    'subject_kind',     'system_execution',
    'subject_ref',      v_comp.component_id,
    'component_id',     v_comp.component_id,
    'system_actor_id',  coalesce(nullif(p_input->>'system_actor',''), v_comp.canonical_system_actor),
    'actor_role_id',    coalesce(nullif(p_input->>'accountable_role_id',''), v_comp.accountable_role_id),
    'manager_role_id',  coalesce((select manager_role_id from public.org_role
                                   where role_id = coalesce(nullif(p_input->>'accountable_role_id',''),
                                                            v_comp.accountable_role_id)), ''),
    'authority_result', coalesce(nullif(p_input->>'authority_result',''), 'pending_at_begin'),
    'state_before',     coalesce(nullif(p_input->>'state_before',''), 'not_started'),
    'state_after',      'in_flight',
    'input_hash',       coalesce(nullif(p_input->>'input_hash',''),
                                 case when p_input ? 'input' then md5(p_input->>'input')
                                      else 'no_input_recorded' end),
    'output_hash',      'not_finished',
    'evidence_refs',    jsonb_build_array(jsonb_build_object(
                          'lifecycle', 'begin',
                          'correlation_id', p_input->>'correlation_id',
                          'causation_id',   p_input->>'causation_id',
                          'trigger_source', coalesce(p_input->>'trigger_source','(unstated)'),
                          'started_at', coalesce(nullif(p_input->>'started_at','')::timestamptz, now()))),
    'status',           'open'));
  return v_trace;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_system_execution_close(p_trace bigint, p_input jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  t public.phase_c_trace%rowtype; v_comp public.phase_c_component%rowtype;
  v_result text := p_input->>'result';
  v_failure text := nullif(btrim(coalesce(p_input->>'failure','')), '');
  v_started timestamptz; v_finished timestamptz := coalesce(nullif(p_input->>'finished_at','')::timestamptz, now());
begin
  select * into t from public.phase_c_trace where trace_id = p_trace;
  if not found then
    raise exception 'fn_kernel_system_execution_close: trace % does not exist', p_trace using errcode = '23503';
  end if;
  if t.trace_policy_id <> 'TRACE-SYSTEM-EXECUTION' then
    raise exception 'fn_kernel_system_execution_close: trace % is on policy %, not TRACE-SYSTEM-EXECUTION',
      p_trace, t.trace_policy_id using errcode = '23514';
  end if;
  if exists (select 1 from public.phase_c_system_execution where trace_id = p_trace) then
    return p_trace;   -- already closed; closing twice is not a second execution
  end if;
  select * into v_comp from public.phase_c_component where component_id = t.component_id;

  if v_result <> all (array['succeeded','failed','refused','no_op']) then
    raise exception 'fn_kernel_system_execution_close: result % is not one of succeeded, failed, refused, no_op',
      coalesce(v_result,'(null)') using errcode = '23514';
  end if;
  if v_result = 'failed' and v_failure is null then
    raise exception 'fn_kernel_system_execution_close: result is failed and no failure was stated. '
      'A failure with no cause is the shape that lets an outage read as a quiet success.'
      using errcode = '23514';
  end if;
  if v_result <> 'failed' and v_failure is not null then
    raise exception 'fn_kernel_system_execution_close: result is % and a failure string was supplied. '
      'One of the two is wrong and the record may not carry both.', v_result using errcode = '23514';
  end if;

  v_started := coalesce(
    nullif(p_input->>'started_at','')::timestamptz,
    (t.evidence_refs->0->>'started_at')::timestamptz,
    t.created_at);

  update public.phase_c_trace set
    status       = 'sealed',
    sealed_at    = now(),
    state_after  = case when v_result = 'failed' then 'failed' else coalesce(nullif(p_input->>'state_after',''), v_result) end,
    output_hash  = coalesce(nullif(p_input->>'output_hash',''), md5(v_result || coalesce(v_failure,''))),
    authority_result = coalesce(nullif(p_input->>'authority_result',''), t.authority_result),
    evidence_refs = coalesce(t.evidence_refs,'[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'lifecycle', case when v_result = 'failed' then 'fail' else 'finish' end,
      'result', v_result, 'failure', v_failure,
      'sqlstate', p_input->>'sqlstate',
      'retry_eligible', coalesce((p_input->>'retry_eligible')::boolean, false),
      'finished_at', v_finished))
  where trace_id = p_trace;

  insert into public.phase_c_system_execution (
    trace_id, component_id, system_actor, accountable_role_id, workflow_id, step_id,
    technical_scope, trigger_source, authority_result, state_before, state_after, result,
    failure, correlation_id, causation_id, started_at, finished_at)
  values (
    p_trace, t.component_id, t.system_actor_id, t.actor_role_id,
    nullif(coalesce(p_input->>'workflow_id', coalesce(v_comp.workflow_id,'')),''),
    nullif(coalesce(p_input->>'step_id', coalesce(v_comp.step_id,'')),''),
    coalesce(nullif(p_input->>'technical_scope',''),
      case when coalesce(v_comp.workflow_id,'') = '' then
        'technical scope: kernel-owned execution registered as ' || t.component_id
        || ', which belongs to no one of the thirty Phase B workflows. Accountability is carried by '
        || 'the role, not by a workflow id it does not have.' end),
    coalesce(nullif(p_input->>'trigger_source',''), t.evidence_refs->0->>'trigger_source', 'unstated'),
    coalesce(nullif(p_input->>'authority_result',''), t.authority_result),
    coalesce(t.state_before, 'not_started'),
    case when v_result = 'failed' then 'failed' else coalesce(nullif(p_input->>'state_after',''), v_result) end,
    v_result, v_failure, coalesce(t.evidence_refs->0->>'correlation_id','unstated'),
    coalesce(t.evidence_refs->0->>'causation_id','unstated'), v_started, v_finished);

  return p_trace;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_system_execution_fail(p_trace bigint, p_input jsonb)
 RETURNS bigint
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public.fn_kernel_system_execution_close(p_trace, p_input || jsonb_build_object(
    'result', 'failed',
    'failure', coalesce(nullif(btrim(p_input->>'failure'),''),
                        coalesce(p_input->>'sqlstate','') || ' ' || coalesce(p_input->>'message','(no message)')),
    'retry_eligible', coalesce(p_input->>'retry_eligible','false')::boolean));
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_system_execution_finish(p_trace bigint, p_input jsonb)
 RETURNS bigint
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public.fn_kernel_system_execution_close(p_trace,
    p_input || jsonb_build_object('result', coalesce(nullif(p_input->>'result',''), 'succeeded')));
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_system_execution_pair_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t public.phase_c_trace%rowtype; e public.phase_c_system_execution%rowtype;
begin
  if tg_table_name = 'phase_c_trace' then
    select * into t from public.phase_c_trace where trace_id = new.trace_id;
    if not found then return null; end if;                      -- rolled back with its transaction
    if t.trace_policy_id <> 'TRACE-SYSTEM-EXECUTION' then return null; end if;

    -- RULE 6: the subject must identify the real execution, not an idempotency string.
    if t.subject_kind <> 'system_execution' then
      raise exception
        'trace % is on TRACE-SYSTEM-EXECUTION with subject_kind %L. The policy''s subject is a '
        'system execution; trace 3730 was written with subject_kind ''trigger_inbox'' and had no '
        'execution to point at. Use fn_kernel_intake_execution, or write the trace under the policy '
        'the subject actually has.', t.trace_id, t.subject_kind using errcode = '23514';
    end if;
    if t.subject_ref is distinct from t.component_id then
      raise exception
        'trace % names subject_ref %L and component %L. For a system execution the subject IS the '
        'component that ran; fn_kernel_signal_submit used to write ''signal:<id>'' here, which '
        'identifies a signal and not any execution.', t.trace_id, t.subject_ref, t.component_id
        using errcode = '23514';
    end if;

    -- RULE 4: sealed requires sealed_at.
    if t.status = 'sealed' and t.sealed_at is null then
      raise exception 'trace % is sealed with no sealed_at', t.trace_id using errcode = '23514';
    end if;

    -- RULE 1: a SEALED system-execution trace must have its execution row. An OPEN one must not —
    -- that is an execution in flight, and phase_c_system_execution is append-only so its row is
    -- written when the execution is over.
    if t.status = 'sealed'
       and not exists (select 1 from public.phase_c_system_execution se where se.trace_id = t.trace_id) then
      raise exception
        'trace % is a SEALED TRACE-SYSTEM-EXECUTION trace with no row in phase_c_system_execution. '
        'This is the exact shape of trace 3730. Close the execution with '
        'fn_kernel_system_execution_finish or _fail, which write the pair together.', t.trace_id
        using errcode = '23514';
    end if;
    return null;
  end if;

  -- phase_c_system_execution
  select * into e from public.phase_c_system_execution where trace_id = new.trace_id;
  if not found then return null; end if;
  select * into t from public.phase_c_trace where trace_id = e.trace_id;
  -- RULE 2: an execution cannot exist without a trace.
  if not found then
    raise exception
      'system execution on trace % has no trace row. An execution nobody can account for is the '
      'thing this policy exists to make impossible.', e.trace_id using errcode = '23503';
  end if;
  -- RULE 3: a terminal execution cannot have an open or incomplete trace.
  if e.result is not null and e.finished_at is not null
     and (t.status <> 'sealed' or t.sealed_at is null) then
    raise exception
      'system execution on trace % is terminal (result %L, finished) while its trace is %L with '
      'sealed_at %L. A finished execution whose trace is still open is a record that can still be '
      'rewritten after the fact.', e.trace_id, e.result, t.status, t.sealed_at using errcode = '23514';
  end if;
  return null;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_system_execution_trace(p_input jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  k          text;
  v_comp     public.phase_c_component%rowtype;
  v_result   text;
  v_started  timestamptz;
  v_finished timestamptz;
  v_wf       text;
  v_step     text;
  v_scope    text;
  v_trace    bigint;
begin
  if p_input is null then
    raise exception
      'TRACE-SYSTEM-EXECUTION incomplete: no payload at all. A system execution that records '
      'nothing is an untraced execution, which the policy forbids '
      '(trace_required=YES, completed_without_trace_allowed=NO).'
      using errcode = '23514';
  end if;

  -- ---- class 1: the twelve scalars that must be present and non-empty ----------------------
  foreach k in array array['component_id','system_actor','accountable_role_id','trigger_source',
                           'authority_result','state_before','state_after','result',
                           'correlation_id','causation_id','started_at','finished_at']
  loop
    if coalesce(btrim(p_input->>k), '') = '' then
      raise exception
        'TRACE-SYSTEM-EXECUTION incomplete: "%" is missing or empty. The policy''s minimum fields '
        'are execution_id; system_actor; accountable_role; component_id; input_hash; output_hash; '
        'status; timestamps, and this kernel additionally requires scope, trigger source, '
        'authority result, state_before, state_after, result, failure, correlation_id and '
        'causation_id. A record without "%" is not a system-execution trace.', k, k
        using errcode = '23514';
    end if;
  end loop;

  -- ---- class 2: 'failure' must exist as a key, even when it is null ------------------------
  if not (p_input ? 'failure') then
    raise exception
      'TRACE-SYSTEM-EXECUTION incomplete: the "failure" field is absent. It may be null — an '
      'execution that did not fail says so with null — but it may not be missing. An omitted '
      'field is not the same statement as a null one.'
      using errcode = '23514';
  end if;

  -- ---- class 3: the component must exist and must be on this policy ------------------------
  select * into v_comp from public.phase_c_component
   where component_id = p_input->>'component_id';
  if not found then
    raise exception
      'TRACE-SYSTEM-EXECUTION incomplete: component "%" is not in phase_c_component. A trace '
      'anchored to a component nobody can look up cannot be audited.', p_input->>'component_id'
      using errcode = '23514';
  end if;
  if v_comp.trace_policy_id <> 'TRACE-SYSTEM-EXECUTION' then
    raise exception
      'TRACE-SYSTEM-EXECUTION refused: component "%" is scoped to "%", not to '
      'TRACE-SYSTEM-EXECUTION. Write the trace under the policy the component actually carries, '
      'or move the component with a recorded exemption.',
      v_comp.component_id, v_comp.trace_policy_id
      using errcode = '23514';
  end if;

  -- ---- class 4: the system actor must be one of the ten canonical actors -------------------
  if not exists (select 1 from public.phase_c_system_actor
                  where system_actor_id = p_input->>'system_actor') then
    raise exception
      'TRACE-SYSTEM-EXECUTION incomplete: system actor "%" does not resolve in '
      'phase_c_system_actor. "Something ran it" is not an actor.', p_input->>'system_actor'
      using errcode = '23514';
  end if;

  -- ---- class 5: the accountable role must be a canonical role ------------------------------
  if not exists (select 1 from public.org_role
                  where role_id = p_input->>'accountable_role_id') then
    raise exception
      'TRACE-SYSTEM-EXECUTION incomplete: accountable role "%" does not resolve in org_role. '
      'A system execution with no accountable human-or-agent role is an action nobody owns.',
      p_input->>'accountable_role_id'
      using errcode = '23514';
  end if;

  -- ---- class 6: workflow/step OR a justified technical scope --------------------------------
  v_wf    := nullif(btrim(coalesce(p_input->>'workflow_id','')), '');
  v_step  := nullif(btrim(coalesce(p_input->>'step_id','')), '');
  v_scope := nullif(btrim(coalesce(p_input->>'technical_scope','')), '');

  if v_wf is null and v_scope is null then
    raise exception
      'TRACE-SYSTEM-EXECUTION incomplete: no scope. Give workflow_id (and step_id where the '
      'execution is a step), or give technical_scope with at least 20 characters saying why this '
      'execution belongs to no workflow. Silence is not a justification.'
      using errcode = '23514';
  end if;
  if v_wf is null and length(v_scope) < 20 then
    raise exception
      'TRACE-SYSTEM-EXECUTION incomplete: technical_scope "%" is too short to be a justification. '
      'An execution outside every workflow has to say what it is instead.', v_scope
      using errcode = '23514';
  end if;
  -- A workflow id that is not one of the thirty Phase B workflows is admitted only as a declared
  -- technical scope. OUT_OF_SCOPE and SYSTEM_SCOPE are exactly that case and they must carry the
  -- justification rather than borrow the authority of a workflow id.
  if v_wf is not null
     and not exists (select 1 from public.phase_b_workflow where workflow_id = v_wf)
     and coalesce(length(v_scope), 0) < 20 then
    raise exception
      'TRACE-SYSTEM-EXECUTION incomplete: workflow "%" is not one of the thirty Phase B '
      'workflows, and no technical_scope was given. A non-workflow scope must be justified, not '
      'spelled like a workflow.', v_wf
      using errcode = '23514';
  end if;
  if v_step is not null
     and not exists (select 1 from public.phase_b_workflow_step where step_id = v_step) then
    raise exception
      'TRACE-SYSTEM-EXECUTION incomplete: step "%" does not resolve in phase_b_workflow_step.',
      v_step
      using errcode = '23514';
  end if;

  -- ---- class 7: result vocabulary, and failure consistency ----------------------------------
  v_result := p_input->>'result';
  if v_result <> all (array['succeeded','failed','refused','no_op']) then
    raise exception
      'TRACE-SYSTEM-EXECUTION incomplete: result "%" is not one of succeeded, failed, refused, '
      'no_op.', v_result
      using errcode = '23514';
  end if;
  if v_result = 'failed' and coalesce(btrim(p_input->>'failure'), '') = '' then
    raise exception
      'TRACE-SYSTEM-EXECUTION incomplete: result is "failed" and failure is empty. A failure with '
      'no stated cause is the shape that lets an outage read as a quiet success.'
      using errcode = '23514';
  end if;
  if v_result <> 'failed' and coalesce(btrim(p_input->>'failure'), '') <> '' then
    raise exception
      'TRACE-SYSTEM-EXECUTION incomplete: result is "%" and yet a failure string was supplied. '
      'One of the two is wrong and the trace may not carry both.', v_result
      using errcode = '23514';
  end if;

  -- ---- class 8: the two instants ------------------------------------------------------------
  begin
    v_started  := (p_input->>'started_at')::timestamptz;
    v_finished := (p_input->>'finished_at')::timestamptz;
  exception when others then
    raise exception
      'TRACE-SYSTEM-EXECUTION incomplete: started_at "%" / finished_at "%" are not timestamps.',
      p_input->>'started_at', p_input->>'finished_at'
      using errcode = '23514';
  end;
  if v_finished < v_started then
    raise exception
      'TRACE-SYSTEM-EXECUTION incomplete: finished_at % precedes started_at %.',
      v_finished, v_started
      using errcode = '23514';
  end if;

  -- ---- write ---------------------------------------------------------------------------------
  -- Sealed on write. A system execution is over by the time it is recorded; leaving the trace open
  -- would leave it rewritable, which K6's completed_traces_still_mutable exists to catch.
  v_trace := public.fn_phase_c_trace_write('TRACE-SYSTEM-EXECUTION', jsonb_build_object(
    'subject_kind',     'system_execution',
    'subject_ref',      v_comp.component_id,
    'component_id',     v_comp.component_id,
    'system_actor_id',  p_input->>'system_actor',
    'actor_role_id',    p_input->>'accountable_role_id',
    'manager_role_id',  coalesce((select manager_role_id from public.org_role
                                   where role_id = p_input->>'accountable_role_id'), ''),
    'authority_result', p_input->>'authority_result',
    'state_before',     p_input->>'state_before',
    'state_after',      p_input->>'state_after',
    -- md5 of the empty string is a real-looking hash of nothing, and a hash that asserts "the
    -- input was empty" when the truth is "no input was recorded" is a fabricated fact inside the
    -- record that is supposed to establish facts. A caller that recorded no input says so.
    'input_hash',       coalesce(nullif(p_input->>'input_hash',''),
                                 case when p_input ? 'input' then md5(p_input->>'input')
                                      else 'no_input_recorded' end),
    'output_hash',      coalesce(nullif(p_input->>'output_hash',''),
                                 md5(v_result || coalesce(p_input->>'failure',''))),
    'evidence_refs',    jsonb_build_array(jsonb_build_object(
                          's3_system_execution', jsonb_build_object(
                            'trigger_source',  p_input->>'trigger_source',
                            'correlation_id',  p_input->>'correlation_id',
                            'causation_id',    p_input->>'causation_id',
                            'result',          v_result,
                            'failure',         p_input->'failure',
                            'started_at',      v_started,
                            'finished_at',     v_finished))),
    'status',           'sealed'));

  insert into public.phase_c_system_execution (
    trace_id, component_id, system_actor, accountable_role_id, workflow_id, step_id,
    technical_scope, trigger_source, authority_result, state_before, state_after, result,
    failure, correlation_id, causation_id, started_at, finished_at)
  values (
    v_trace, v_comp.component_id, p_input->>'system_actor', p_input->>'accountable_role_id',
    v_wf, v_step, v_scope, p_input->>'trigger_source', p_input->>'authority_result',
    p_input->>'state_before', p_input->>'state_after', v_result,
    nullif(btrim(coalesce(p_input->>'failure','')), ''),
    p_input->>'correlation_id', p_input->>'causation_id', v_started, v_finished);

  return v_trace;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_system_trace_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'cron', 'pg_temp'
AS $function$
with epoch as (
  select started_at from public.phase_c_kernel_epoch where epoch_id = 'S3_SYSTEM_EXECUTION_TRACING'
),
runs as (   -- every firing of a wrapped state-changing cron job, split by the epoch
  select r.runid, r.jobid, w.component_id, r.start_time,
         coalesce(r.end_time, now()) as end_time,
         (r.start_time >= (select started_at from epoch)) as is_new
    from cron.job_run_details r
    join public.phase_c_system_execution_wrapper w on w.jobid = r.jobid
),
traced as (
  select runs.*,
         -- K24. Was: se.started_at between runs.start_time and runs.end_time. That is not the
         -- relationship; it is an approximation of it, and a three-millisecond clock difference
         -- broke it. cron:autonomy_dispose_hourly run 333732 was reported as an untraced NEW
         -- state-changing execution while its trace sat in phase_c_system_execution — the wrapper
         -- stamped started_at 2026-08-17 00:45:00.115196 and cron.job_run_details recorded
         -- start_time 00:45:00.118297, three milliseconds LATER. The trace legitimately begins
         -- before the scheduler notices the run has begun.
         --
         -- The real relationship is OVERLAP: the execution and the cron run cover the same
         -- instant. That is what "this run produced this trace" means, and it does not depend on
         -- two clocks agreeing to the millisecond.
         --
         -- The job identity is checked as well as the component, so overlap alone cannot match a
         -- different job that happened to run at the same moment. This is narrower than the old
         -- predicate in that respect and wider only in the one that was wrong.
         -- F26. OVERLAP IS STILL TWO CLOCKS, AND A FAST ENOUGH JOB SLIPS BETWEEN THEM.
         --
         -- K24 replaced `se.started_at between runs.start_time and runs.end_time` with an overlap
         -- test, because the wrapper's clock and the scheduler's clock differ by milliseconds and
         -- the trace legitimately begins before the scheduler notices the run has begun. That was
         -- right and it is not enough. Measured 2026-08-21:
         --
         --   cron:dropbox_backup_scan  trace   05:30:00.310247 -> 05:30:00.347993
         --                             cron    05:30:00.357660 -> 05:30:00.436349
         --
         -- The trace opened AND CLOSED 10ms before cron.job_run_details recorded start_time, so the
         -- two windows are disjoint and the run was reported as an untraced state-changing
         -- execution -- 1 of 3667 -- while its trace sat in the table. cron.job_run_details.start_time
         -- is stamped by the scheduler after the command is dispatched; a job that finishes in 40ms
         -- can be entirely over before that write lands. Requiring the windows to touch is still a
         -- claim about two clocks agreeing.
         --
         -- The relationship is PROXIMITY, not contact: the same component, the same job id, and the
         -- trace within five seconds of the run. Five seconds is far larger than any clock skew
         -- observed here (10ms) and far smaller than the tightest schedule in the estate (one
         -- minute), so it cannot match a DIFFERENT firing of the same job -- which is the only way
         -- widening this could hide a real gap. A run with no trace for its component and job within
         -- five seconds is still reported, which is what makes the check able to fail.
         exists (select 1 from public.phase_c_system_execution se
                  where se.component_id = runs.component_id
                    and se.trigger_source like 'cron.job/' || runs.jobid::text || '%'
                    and se.started_at <= runs.end_time + interval '5 seconds'
                    and coalesce(se.finished_at, se.started_at) >= runs.start_time - interval '5 seconds') as has_trace
    from runs
),
scope as (   -- everything still governed by TRACE-SYSTEM-EXECUTION
  select * from public.phase_c_component where trace_policy_id = 'TRACE-SYSTEM-EXECUTION'
),
wrappable as (   -- active, state-changing, registered cron components: the ones C had to wire
  select c.component_id, j.jobid
    from cron.job j
    join public.phase_c_component c
      on c.component_type = 'cron_job'
     and c.source_path_or_db_object = 'cron.job/' || j.jobid
   where j.active and c.mutates_state and c.trace_policy_id = 'TRACE-SYSTEM-EXECUTION'
)

-- ---- 1. NEW executions that carry the required trace ----------------------------------------
-- ok requires a NON-EMPTY population. 0 of 0 is not 100%: it is a scorer with no input, and a
-- scorer with no input that prints a pass is the defect this whole increment is about.
select 'new_state_changing_system_executions_with_required_trace'::text,
       'every one, and at least one'::text,
       (select count(*) filter (where is_new and has_trace)::text || ' of '
             || count(*) filter (where is_new)::text from traced)
         || ' wrapped cron executions since the epoch',
       (select count(*) filter (where is_new) > 0
           and count(*) filter (where is_new and has_trace) = count(*) filter (where is_new)
          from traced)

union all
-- ---- 2. NEW executions missing a trace --------------------------------------------------------
select 'new_state_changing_system_executions_missing_a_trace',
       '0 of the executions since the epoch',
       (select count(*) filter (where is_new and not has_trace)::text || ' of '
             || count(*) filter (where is_new)::text from traced),
       (select count(*) filter (where is_new and not has_trace) = 0 from traced)

union all
-- ---- 3. business-state-changing components incorrectly exempted -------------------------------
-- Structurally impossible while a00_phase_c_readonly_exemption_guard exists, and measured anyway:
-- a guard that is never checked is a guard that can be dropped without anyone noticing.
select 'state_changing_components_on_a_read_only_policy',
       '0 of the components on a read-only policy',
       (select count(*) filter (where mutates_state)::text || ' of ' || count(*)::text
          from public.phase_c_component
         where trace_policy_id = any (array['TRACE-MONITORING','TRACE-INFRASTRUCTURE'])),
       (select count(*) filter (where mutates_state) = 0
          from public.phase_c_component
         where trace_policy_id = any (array['TRACE-MONITORING','TRACE-INFRASTRUCTURE']))

union all
-- ---- 4. read-only exemptions without a recorded document --------------------------------------
select 'read_only_components_without_a_recorded_exemption',
       '0 of the components on a read-only policy',
       (select count(*) filter (where not exists (
                 select 1 from public.phase_c_component_trace_exemption e
                  where e.component_id = c.component_id and e.exempt_to_policy = c.trace_policy_id))::text
             || ' of ' || count(*)::text
          from public.phase_c_component c
         where c.trace_policy_id = any (array['TRACE-MONITORING','TRACE-INFRASTRUCTURE'])),
       (select count(*) filter (where not exists (
                 select 1 from public.phase_c_component_trace_exemption e
                  where e.component_id = c.component_id and e.exempt_to_policy = c.trace_policy_id)) = 0
          from public.phase_c_component c
         where c.trace_policy_id = any (array['TRACE-MONITORING','TRACE-INFRASTRUCTURE']))

union all
-- ---- 5. every wirable cron component is actually wired ----------------------------------------
select 'active_state_changing_cron_components_not_wrapped',
       '0 of the active state-changing cron components',
       (select count(*) filter (where not exists (
                 select 1 from public.phase_c_system_execution_wrapper w where w.jobid = x.jobid))::text
             || ' of ' || count(*)::text from wrappable x),
       (select count(*) filter (where not exists (
                 select 1 from public.phase_c_system_execution_wrapper w where w.jobid = x.jobid)) = 0
          from wrappable x)

union all
-- ---- 6. no trace under this policy may be missing its execution record ------------------------
select 'system_execution_traces_without_a_complete_record',
       '0 of the traces under TRACE-SYSTEM-EXECUTION',
       (select count(*) filter (where not exists (
                 select 1 from public.phase_c_system_execution se where se.trace_id = t.trace_id))::text
             || ' of ' || count(*)::text
          from public.phase_c_trace t where t.trace_policy_id = 'TRACE-SYSTEM-EXECUTION'),
       (select count(*) filter (where not exists (
                 select 1 from public.phase_c_system_execution se where se.trace_id = t.trace_id)) = 0
          from public.phase_c_trace t where t.trace_policy_id = 'TRACE-SYSTEM-EXECUTION')

union all
-- ---- 7. nothing autonomous may claim an authority it does not have ----------------------------
select 'new_system_executions_claiming_founder_authority',
       '0 of the executions recorded since the epoch',
       (select count(*) filter (where authority_result like 'requires\_founder\_approval%'
                                   or authority_result like 'unknown\_action\_class%')::text
             || ' of ' || count(*)::text
          from public.phase_c_system_execution
         where started_at >= (select started_at from epoch)),
       (select count(*) filter (where authority_result like 'requires\_founder\_approval%'
                                   or authority_result like 'unknown\_action\_class%') = 0
          from public.phase_c_system_execution
         where started_at >= (select started_at from epoch))

union all
-- ---- 8. HISTORICAL, reported as historical and never backfilled -------------------------------
select 'historical_untraced_system_executions',
       'informational — historical, never traced, deliberately not backfilled',
       (select count(*) filter (where not is_new)::text || ' of ' || count(*)::text
          from traced)
         || ' wrapped-cron firings predate the kernel epoch and have no trace, by design',
       true

union all
select 'historical_untraced_cron_executions_all_jobs',
       'informational — the whole pre-epoch execution log',
       (select count(*)::text from cron.job_run_details
         where start_time < (select started_at from epoch))
         || ' of ' || (select count(*)::text from cron.job_run_details)
         || ' cron firings on record predate the epoch',
       true

union all
-- ---- 9. what cannot be measured, named rather than scored -------------------------------------
select 'system_execution_components_with_no_observable_execution_log',
       'informational — cannot be scored from this database, so not scored',
       (select count(*) filter (where component_type <> 'cron_job')::text
             || ' of ' || count(*)::text from scope)
         || ' components on TRACE-SYSTEM-EXECUTION are edge functions, database triggers or event '
         || 'subscriptions; this database holds no invocation log for them, so their coverage is '
         || 'unknown, not 100%',
       true

union all
select 'components_moved_to_a_read_only_policy',
       'informational',
       (select count(*)::text from public.phase_c_component_trace_exemption)
         || ' of 656 moved off TRACE-SYSTEM-EXECUTION with a recorded exemption; '
         || (select count(*)::text from scope) || ' remain, including all '
         || (select count(*) filter (where mutates_state)::text from scope)
         || ' state-changing components',
       true

union all
select 'new_system_executions_recorded_as_failed',
       'informational — a failure recorded is louder than a failure lost',
       (select count(*) filter (where result = 'failed')::text || ' of ' || count(*)::text
          from public.phase_c_system_execution
         where started_at >= (select started_at from epoch)),
       true

union all
select 'traces_written_under_trace_system_execution',
       'informational',
       (select count(*)::text from public.phase_c_trace
         where trace_policy_id = 'TRACE-SYSTEM-EXECUTION')
         || ' of ' || (select count(*)::text from public.phase_c_trace),
       true;
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_trace_integrity()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
with obj as (
  select 'founder_command'::text as kind, c.command_id::text as ref, c.state as state, c.trace_id,
         (c.state in ('completed','failed','cancelled','refused','superseded')) as is_terminal
    from public.founder_command c
  union all
  select 'workflow_run', r.run_id::text, r.state, r.trace_id,
         (r.state in ('completed','cancelled','failed','superseded','expired','rejected'))
    from public.phase_c_workflow_run r
  union all
  select 'step_run', s.step_run_id::text, s.state, s.trace_id,
         (s.state in ('completed','cancelled','failed','superseded','skipped'))
    from public.phase_c_workflow_step_run s
  union all
  select 'task', t.task_id::text, t.state, t.trace_id,
         (t.state in ('completed','failed','cancelled','superseded'))
    from public.phase_c_task t
  union all
  select 'handoff_run', h.handoff_run_id::text, h.status, h.trace_id,
         (h.status in ('accepted','rejected','cancelled','superseded'))
    from public.phase_c_handoff_run h
),
j as (
  select o.*, tr.trace_id as found_trace, tr.sealed_at, tr.status as trace_status, tr.state_after
    from obj o left join public.phase_c_trace tr on tr.trace_id = o.trace_id
),
-- phase_c_trace records subject_kind in two vocabularies ('command'/'founder_command',
-- 'handoff'/'handoff_run'). Reading only one of them is how a check silently stops seeing half a
-- table, so both are normalised here rather than picked between.
tk as (
  select t.*,
         case t.subject_kind
           when 'command' then 'founder_command' when 'founder_command' then 'founder_command'
           when 'run' then 'workflow_run'        when 'workflow_run' then 'workflow_run'
           when 'step' then 'step_run'           when 'step_run' then 'step_run'
           when 'task' then 'task'
           when 'handoff' then 'handoff_run'     when 'handoff_run' then 'handoff_run'
           -- S3. The kind whose subject is a COMPONENT rather than one of the five kernel
           -- objects. Without this branch every trace S3 writes lands in `unmapped` and the check
           -- that exists to find a kind nobody models fires on the kind that was just modelled.
           when 'system_execution' then 'system_execution'
           else 'unmapped' end as nkind
    from public.phase_c_trace t
),
term as (
  select * from (values
    ('founder_command','completed'),('founder_command','failed'),('founder_command','cancelled'),
    ('founder_command','refused'),('founder_command','superseded'),
    ('workflow_run','completed'),('workflow_run','cancelled'),('workflow_run','failed'),
    ('workflow_run','superseded'),('workflow_run','expired'),('workflow_run','rejected'),
    ('step_run','completed'),('step_run','cancelled'),('step_run','failed'),
    ('step_run','superseded'),('step_run','skipped'),
    ('task','completed'),('task','failed'),('task','cancelled'),('task','superseded'),
    ('handoff_run','accepted'),('handoff_run','rejected'),('handoff_run','cancelled'),
    ('handoff_run','superseded')
  ) as v(kind, state)
)

-- ---- active (NON-terminal) objects with no usable trace, per kind --------------------------
select 'active_objects_without_trace_' || j.kind, '0',
       count(*) filter (where not j.is_terminal and j.found_trace is null)::text
         || ' of ' || count(*)::text,
       count(*) filter (where not j.is_terminal and j.found_trace is null) = 0
  from j group by j.kind

union all
-- ---- terminal objects whose trace is missing or still open ---------------------------------
select 'terminal_objects_with_open_trace_' || j.kind, '0',
       count(*) filter (where j.is_terminal and (j.found_trace is null or j.sealed_at is null))::text
         || ' of ' || count(*)::text,
       count(*) filter (where j.is_terminal and (j.found_trace is null or j.sealed_at is null)) = 0
  from j group by j.kind

union all
-- ---- the trace and its subject disagree about what state the subject is in -----------------
select 'trace_state_disagrees_with_subject_' || j.kind, '0',
       count(*) filter (where j.found_trace is not null and j.state_after is distinct from j.state)::text
         || ' of ' || count(*)::text,
       count(*) filter (where j.found_trace is not null and j.state_after is distinct from j.state) = 0
  from j group by j.kind

union all
-- ---- a trace that presents as sealed but is not protected -----------------------------------
select 'traces_sealed_with_no_sealed_at', '0',
       count(*) filter (where status = 'sealed' and sealed_at is null)::text || ' of ' || count(*)::text,
       count(*) filter (where status = 'sealed' and sealed_at is null) = 0
  from public.phase_c_trace

union all
select 'traces_sealed_at_set_but_status_open', '0',
       count(*) filter (where status <> 'sealed' and sealed_at is not null)::text || ' of ' || count(*)::text,
       count(*) filter (where status <> 'sealed' and sealed_at is not null) = 0
  from public.phase_c_trace

union all
-- ---- orphans: the subject_kind names an object kind and the id column is null ----------------
-- Counted BY KIND over the full trace table. The pre-K6 orphans are annotated, not deleted and not
-- filtered: they still appear in this numerator, which is the point of counting them by kind.
select 'orphan_traces_founder_command', '0',
       count(*) filter (where nkind = 'founder_command' and command_id is null)::text
         || ' of ' || count(*)::text,
       count(*) filter (where nkind = 'founder_command' and command_id is null) = 0 from tk
union all
select 'orphan_traces_workflow_run', '0',
       count(*) filter (where nkind = 'workflow_run' and run_id is null)::text
         || ' of ' || count(*)::text,
       count(*) filter (where nkind = 'workflow_run' and run_id is null) = 0 from tk
union all
select 'orphan_traces_step_run', '0',
       count(*) filter (where nkind = 'step_run' and step_run_id is null)::text
         || ' of ' || count(*)::text,
       count(*) filter (where nkind = 'step_run' and step_run_id is null) = 0 from tk
union all
select 'orphan_traces_task', '0',
       count(*) filter (where nkind = 'task' and task_id is null)::text
         || ' of ' || count(*)::text,
       count(*) filter (where nkind = 'task' and task_id is null) = 0 from tk
union all
-- phase_c_trace has no handoff_run_id column, so a handoff trace can only be resolved through
-- subject_ref. Named for what it actually measures rather than borrowing the shape above.
-- ponytail: add phase_c_trace.handoff_run_id if handoff tracing ever gets a second writer.
select 'orphan_traces_handoff_unresolvable_subject_ref', '0',
       count(*) filter (where nkind = 'handoff_run'
                          and not exists (select 1 from public.phase_c_handoff_run h
                                           where h.handoff_run_id::text = tk.subject_ref))::text
         || ' of ' || count(*)::text,
       count(*) filter (where nkind = 'handoff_run'
                          and not exists (select 1 from public.phase_c_handoff_run h
                                           where h.handoff_run_id::text = tk.subject_ref)) = 0 from tk
union all
-- S3. The system-execution equivalent of the orphan checks above: this kind's subject is a
-- component, so the id that has to resolve is component_id, and the record that has to exist is
-- the phase_c_system_execution row carrying the fields phase_c_trace has no column for.
select 'orphan_traces_system_execution', '0',
       count(*) filter (where nkind = 'system_execution'
                          and (component_id = ''
                               or not exists (select 1 from public.phase_c_component c
                                               where c.component_id = tk.component_id)
                               or not exists (select 1 from public.phase_c_system_execution se
                                               where se.trace_id = tk.trace_id)))::text
         || ' of ' || count(*)::text,
       count(*) filter (where nkind = 'system_execution'
                          and (component_id = ''
                               or not exists (select 1 from public.phase_c_component c
                                               where c.component_id = tk.component_id)
                               or not exists (select 1 from public.phase_c_system_execution se
                                               where se.trace_id = tk.trace_id))) = 0 from tk
union all
select 'traces_with_unmapped_subject_kind', '0',
       count(*) filter (where nkind = 'unmapped')::text || ' of ' || count(*)::text,
       count(*) filter (where nkind = 'unmapped') = 0 from tk

union all
-- ---- completed traces that are still mutable -------------------------------------------------
-- state_after has reached a terminal state for the subject's own kind, and sealed_at is null, so
-- fn_phase_c_trace_append_only will let it be rewritten in place.
select 'completed_traces_still_mutable', '0',
       count(*) filter (where sealed_at is null
                          and exists (select 1 from term
                                       where term.kind = tk.nkind and term.state = tk.state_after))::text
         || ' of ' || count(*)::text,
       count(*) filter (where sealed_at is null
                          and exists (select 1 from term
                                       where term.kind = tk.nkind and term.state = tk.state_after)) = 0
  from tk

union all
-- ---- TRACE-SYSTEM-EXECUTION: measured, not weakened ------------------------------------------
-- The policy says trace_required=YES, completed_without_trace_allowed=NO. Nothing has ever written
-- a trace under it. This check is expected to be RED and must stay red until scheduled, webhook,
-- queue, storage and provider-adapter execution actually writes traces. Turning it green by
-- narrowing the scope would be the defect the policy exists to prevent.
select 'system_execution_components_with_no_trace', '0',
       count(*) filter (where c.mutates_state
                          and not exists (select 1 from public.phase_c_trace t
                                           where t.component_id = c.component_id))::text
         || ' of ' || count(*)::text,
       count(*) filter (where c.mutates_state
                          and not exists (select 1 from public.phase_c_trace t
                                           where t.component_id = c.component_id)) = 0
  from public.phase_c_component c where c.trace_policy_id = 'TRACE-SYSTEM-EXECUTION'

union all
select 'traces_written_under_trace_system_execution', 'more than 0',
       count(*) filter (where trace_policy_id = 'TRACE-SYSTEM-EXECUTION')::text
         || ' of ' || count(*)::text,
       count(*) filter (where trace_policy_id = 'TRACE-SYSTEM-EXECUTION') > 0
  from public.phase_c_trace

union all
-- ---- disclosure rows: the denominators a reader needs to see move ----------------------------
select 'raw_total_traces', 'informational', count(*)::text || ' of ' || count(*)::text, true
  from public.phase_c_trace
union all
select 'raw_total_traced_objects', 'informational',
       count(*) filter (where found_trace is not null)::text || ' of ' || count(*)::text, true from j
union all
select 'raw_terminal_objects', 'informational',
       count(*) filter (where is_terminal)::text || ' of ' || count(*)::text, true from j
union all
select 'traces_superseded', 'informational',
       count(*) filter (where superseded_by is not null)::text || ' of ' || count(*)::text, true
  from public.phase_c_trace
union all
-- Every row K6 annotated or reconstructed, disclosed as its own number so no reader mistakes a
-- backfilled seal or a reconstructed step trace for a contemporaneous record.
select 'traces_carrying_a_k6_backfill_annotation', 'informational',
       count(*) filter (where exists (select 1 from jsonb_array_elements(evidence_refs) e
                                       where e ? 'k6_backfill'))::text || ' of ' || count(*)::text,
       true
  from public.phase_c_trace
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_trigger_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'cron', 'pg_temp'
AS $function$
with d as (select * from public.v_kernel_trigger_source_derived),
tot as (select count(*)::text n from d),
auto as (   -- a live source that starts or changes business work: what an adapter is FOR.
            -- The founder's own command channel is excluded by name: it is not autonomous, a
            -- person drives it, and giving it an autonomous adapter is the one thing the frozen
            -- operating model forbids. Excluded here and counted on the deferred_handler_split
            -- line, so it is never simply missing.
  select * from d
   where coalesce(is_active_now,false) and coalesce(creates_work_now,false)
     and coalesce(disposition,'') <> 'FOUNDER_COMMAND_SURFACE'
),
act as (select count(*)::text n from auto),
-- UNACCOUNTED FOR: it starts work, it is live, it has no working adapter, and nobody has written
-- down why. A recorded DEFERRED_HANDLER is an answer; silence is the gap.
gap as (
  select * from auto a
   where a.disposition is null
     and (a.adapter_trigger_type is null
          or not exists (select 1 from public.kernel_trigger_type t
                          where t.trigger_type = a.adapter_trigger_type
                            and t.activation_state = 'active'))
)
select 'active_autonomous_source_with_no_adapter'::text,
       '0 of ' || (select n from act) || ' active autonomous sources (' || (select n from tot) || ' inventoried)',
       (select count(*)::text from gap)
         || ' of ' || (select n from act) || ' active autonomous sources unaccounted for ('
         || (select n from tot) || ' inventoried); '
         || (select count(*)::text from auto where disposition = 'NO_WORKFLOW_IN_REGISTRY')
         || ' carry a recorded DEFERRED_HANDLER, '
         || (select count(*)::text from d where coalesce(is_active_now,false)
               and coalesce(creates_work_now,false) and disposition = 'FOUNDER_COMMAND_SURFACE')
         || ' are founder command surfaces held out of this population by name',
       (select count(*) from gap) = 0
union all
select 'active_adapter_bypassing_fn_kernel_workflow_start'::text,
       '0 of ' || (select count(*)::text from public.kernel_trigger_type where activation_state = 'active')
         || ' active trigger types',
       -- The adapter is fn_kernel_trigger_submit. It bypasses the kernel creator if its own body
       -- (comments stripped) does not call fn_kernel_workflow_start, or if any OTHER routine reads
       -- kernel_trigger_inbox and creates work without going through it.
       (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
         where n.nspname = 'public'
           and regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g')
               ~ '\ykernel_trigger_inbox\y'
           and regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g')
               ~ '(insert\s+into\s+(public\.)?phase_c_(task|workflow_run)\y)'
           and regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g')
               !~ '\yfn_kernel_workflow_start\s*\(')::text
         || ' routines read kernel_trigger_inbox and create work without fn_kernel_workflow_start; '
         || 'fn_kernel_trigger_submit calls it: '
         || (select (regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g')
                     ~ '\yfn_kernel_workflow_start\s*\(')::text
               from pg_proc p join pg_namespace n on n.oid = p.pronamespace
              where n.nspname = 'public' and p.proname = 'fn_kernel_trigger_submit'),
       (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
         where n.nspname = 'public'
           and regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g')
               ~ '\ykernel_trigger_inbox\y'
           and regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g')
               ~ '(insert\s+into\s+(public\.)?phase_c_(task|workflow_run)\y)'
           and regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g')
               !~ '\yfn_kernel_workflow_start\s*\(') = 0
       and coalesce((select regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g')
                            ~ '\yfn_kernel_workflow_start\s*\('
                       from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                      where n.nspname = 'public' and p.proname = 'fn_kernel_trigger_submit'), false)
union all
select 'normal_autonomous_trigger_routing_through_founder'::text,
       '0 of ' || (select count(*)::text from public.kernel_trigger_type where workflow_id is not null)
         || ' mapped trigger types',
       (select count(*) from public.kernel_trigger_type t
          join public.phase_b_workflow w on w.workflow_id = t.workflow_id
          left join public.phase_b_workflow_step s
                 on s.workflow_id = t.workflow_id and s.step_no = 1
         where 'founder' in (w.accountable_role_id, coalesce(s.accountable_role_id,'')))::text
         || ' of ' || (select count(*)::text from public.kernel_trigger_type where workflow_id is not null)
         || ' mapped trigger types (workflow owner or entry-step owner)',
       (select count(*) from public.kernel_trigger_type t
          join public.phase_b_workflow w on w.workflow_id = t.workflow_id
          left join public.phase_b_workflow_step s
                 on s.workflow_id = t.workflow_id and s.step_no = 1
         where 'founder' in (w.accountable_role_id, coalesce(s.accountable_role_id,''))) = 0
union all
select 'normal_autonomous_trigger_routing_through_chief_of_staff'::text,
       '0 of ' || (select count(*)::text from public.kernel_trigger_type where workflow_id is not null)
         || ' mapped trigger types',
       (select count(*) from public.kernel_trigger_type t
          join public.phase_b_workflow w on w.workflow_id = t.workflow_id
          left join public.phase_b_workflow_step s
                 on s.workflow_id = t.workflow_id and s.step_no = 1
         where 'chief_of_staff' in (w.accountable_role_id, coalesce(s.accountable_role_id,'')))::text
         || ' of ' || (select count(*)::text from public.kernel_trigger_type where workflow_id is not null)
         || ' mapped trigger types; W01 is the founder-command path and is refused by '
         || 'a00_kernel_trigger_type_routing_guard, not merely absent',
       (select count(*) from public.kernel_trigger_type t
          join public.phase_b_workflow w on w.workflow_id = t.workflow_id
          left join public.phase_b_workflow_step s
                 on s.workflow_id = t.workflow_id and s.step_no = 1
         where 'chief_of_staff' in (w.accountable_role_id, coalesce(s.accountable_role_id,''))) = 0
union all
select 'duplicate_trigger_delivery_creating_duplicate_workflow'::text,
       '0 of ' || (select count(*)::text from public.kernel_trigger_inbox
                    where status in ('accepted','duplicate')) || ' resolved inbox rows',
       -- Two ways a duplicate could show: the same idempotency key twice (the UNIQUE constraint
       -- makes it impossible and it is still counted, because a constraint that is never tested is
       -- an assumption), or one (workflow, business object) carrying more than one run.
       (select count(*) from (
          select 1 from public.kernel_trigger_inbox
           group by idempotency_key having count(*) > 1) x)::text
         || ' repeated idempotency keys + '
         || (select count(*) from (
               select workflow_id, business_object_id from public.kernel_trigger_inbox
                where status in ('accepted','duplicate') and run_id is not null
                group by workflow_id, business_object_id having count(distinct run_id) > 1) y)::text
         || ' (workflow, object) pairs with more than one run, of '
         || (select count(*)::text from public.kernel_trigger_inbox
              where status in ('accepted','duplicate')) || ' resolved inbox rows',
       (select count(*) from (
          select 1 from public.kernel_trigger_inbox
           group by idempotency_key having count(*) > 1) x)
       + (select count(*) from (
            select workflow_id, business_object_id from public.kernel_trigger_inbox
             where status in ('accepted','duplicate') and run_id is not null
             group by workflow_id, business_object_id having count(distinct run_id) > 1) y) = 0
union all
select 'trigger_source_using_the_domain_event_outbox_as_its_request_queue'::text,
       '0 of ' || (select n from tot) || ' inventoried sources',
       (select count(*) from d where outbox_used_as_request_queue)::text
         || ' of ' || (select n from tot) || ' inventoried sources. The predicate is live: it '
         || 'matches '
         || (select count(*)::text from pg_proc p join pg_namespace n on n.oid = p.pronamespace
              where n.nspname = 'public'
                and regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g') ~ '\yphase_c_event_outbox\y'
                and regexp_replace(regexp_replace(p.prosrc,'/\*.*?\*/',' ','g'),'--[^\n]*',' ','g') ~ '\yfn_(kernel|phase_c)_(workflow_start|event_ingress)\s*\(')
         || ' routines in the database (the legacy ingress pair), and no ACTIVE source reaches them',
       (select count(*) from d where outbox_used_as_request_queue) = 0
-- ---- reported alongside the six, because a green mapping check must not read as a green wiring
-- ---- check. This is the increment's own open gap and it is stated as a number, not as prose.
union all
select 'active_autonomous_source_not_yet_routing_through_the_inbox'::text,
       '0 of ' || (select n from act) || ' active autonomous sources — NOT MET BY K10',
       (select count(*) from auto where not coalesce(routes_through_inbox,false))::text
         || ' of ' || (select n from act) || ' active autonomous sources still start or change '
         || 'business work without entering the kernel. K10 builds the door and registers the '
         || 'routes; moving each source onto it is the wiring increment.',
       (select count(*) from auto where not coalesce(routes_through_inbox,false)) = 0
union all
select 'inventory_row_whose_accountable_role_does_not_resolve'::text,
       '0 of ' || (select n from tot) || ' inventoried sources',
       (select count(*) from d where accountable_kind is distinct from 'canonical')::text
         || ' of ' || (select n from tot) || ' inventoried sources',
       (select count(*) from d where accountable_kind is distinct from 'canonical') = 0
union all
select 'disposition_split'::text,
       'reported, never counted as one backlog of owed handlers',
       (select count(*)::text from public.kernel_trigger_source
         where disposition = 'NO_WORKFLOW_IN_REGISTRY')
         || ' owe a handler (no Phase B workflow starts from that signal); '
         || (select count(*)::text from public.kernel_trigger_source
              where disposition = 'NOT_A_BUSINESS_TRIGGER')
         || ' are not business triggers at all (guards, audits, probes, held jobs); '
         || (select count(*)::text from public.kernel_trigger_source
              where disposition = 'FOUNDER_COMMAND_SURFACE')
         || ' are founder command surfaces that must never get an autonomous adapter; '
         || (select count(*)::text from public.kernel_trigger_source
              where disposition is null and adapter_trigger_type is not null)
         || ' carry an adapter',
       true;
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_trigger_submit(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_class     text  := nullif(btrim(coalesce(p_input->>'source_class','')), '');
  v_system    text  := nullif(btrim(coalesce(p_input->>'source_system','')), '');
  v_ref       text  := nullif(btrim(coalesce(p_input->>'source_ref','')), '');
  v_ext       text  := nullif(btrim(coalesce(p_input->>'external_ref','')), '');
  v_type_in   text  := nullif(btrim(coalesce(p_input->>'trigger_type','')), '');
  v_by        text  := nullif(btrim(coalesce(p_input->>'requested_by','')), '');
  v_payload   jsonb := coalesce(p_input->'raw_payload', '{}'::jsonb);
  v_version   bigint := coalesce(nullif(p_input->>'object_version','')::bigint, 1);
  v_priority  text  := coalesce(nullif(p_input->>'priority',''), 'P2');
  v_idem      text;
  v_corr      text;
  v_caus      text;
  v_inbox     bigint;
  v_trace     bigint;
  v_obj       text;
  v_key       text;
  v_val       text;
  v_missing   text;
  v_start     jsonb;
  v_run       bigint;
  v_status    text;
  v_reason    text;
  v_actor     text;
  v_kind      text;
  v_owner     text;
  v_step_owner text;
  v_step_id   text;
  -- Scalars, never a RECORD: a plpgsql RECORD assigned only inside an if-branch raises when it is
  -- read, and a SELECT INTO that matched nothing NULLs every target rather than leaving the
  -- initialiser. Both traps have already been paid for in this estate.
  t_workflow  text;
  t_rule      text;
  t_sources   text[];
  t_actor     text;
  t_activation text;
  t_impl      text;
  t_class     text;
  t_note      text;
  p_inbox     bigint;
  p_status    text;
  p_run       bigint;
  p_trace     bigint;
  p_type      text;
  p_wf        text;
  p_obj       text;
  p_reason    text;
begin
  -- ---- 0. a consumer may never drive the request side --------------------------------------
  perform public.fn_kernel_assert_not_in_delivery('fn_kernel_trigger_submit');

  -- ---- 1. envelope. A malformed envelope has nothing recordable in it ----------------------
  --
  -- These raise rather than record: source_class is CHECK-constrained and requested_by is NOT NULL,
  -- so a row cannot be written to hold the refusal. Everything that CAN be recorded is recorded
  -- below instead of raised.
  if v_class is null or v_system is null or v_ref is null or v_type_in is null or v_by is null then
    raise exception
      'fn_kernel_trigger_submit: source_class, source_system, source_ref, trigger_type and '
      'requested_by are all required (got %, %, %, %, %)',
      coalesce(v_class,'(null)'), coalesce(v_system,'(null)'), coalesce(v_ref,'(null)'),
      coalesce(v_type_in,'(null)'), coalesce(v_by,'(null)')
      using errcode = '22023';
  end if;
  if jsonb_typeof(v_payload) <> 'object' then
    raise exception 'fn_kernel_trigger_submit: raw_payload must be a json object, got %',
      jsonb_typeof(v_payload) using errcode = '22023';
  end if;
  if v_class not in ('customer_event','supplier_event','scheduled_event','deadline_sla_event',
                     'kpi_deviation_event','system_health_event','webhook_provider_event',
                     'workflow_followup_event') then
    raise exception 'fn_kernel_trigger_submit: % is not one of the eight registered source classes',
      v_class using errcode = '22023';
  end if;

  -- The idempotency key is the external identity of the request. Defaulted from the source's own
  -- reference, never from now() or from a sequence: a key that is different every time is not a key.
  v_idem := coalesce(nullif(btrim(p_input->>'idempotency_key'),''),
                     v_system || ':' || coalesce(v_ext, v_ref));
  v_corr := coalesce(nullif(btrim(p_input->>'correlation_id'),''), 'trigger:' || v_idem);
  v_caus := coalesce(nullif(btrim(p_input->>'causation_id'),''), v_system || ':' || v_ref);

  -- ---- 2. idempotency, before anything is resolved and before anything is created ----------
  insert into public.kernel_trigger_inbox
    (source_class, source_system, source_ref, external_ref, raw_payload,
     correlation_id, causation_id, idempotency_key, status, requested_by)
  values (v_class, v_system, v_ref, v_ext, v_payload, v_corr, v_caus, v_idem, 'pending', v_by)
  on conflict (idempotency_key) do nothing
  returning inbox_id into v_inbox;

  if v_inbox is null then
    -- Seen before. Return the FIRST result and create nothing: no run, no task, no event, and no
    -- second inbox row. The first row's decision is the answer, whatever it was.
    select i.inbox_id, i.status, i.run_id, i.trace_id, i.trigger_type, i.workflow_id,
           i.business_object_id, i.refusal_reason
      into p_inbox, p_status, p_run, p_trace, p_type, p_wf, p_obj, p_reason
      from public.kernel_trigger_inbox i where i.idempotency_key = v_idem;
    -- An empty read here would mean the conflicting row belongs to a transaction that has not
    -- committed. Returning a jsonb full of nulls would make "someone else is mid-flight" look
    -- exactly like "refused with no reason", so it raises instead.
    if p_inbox is null then
      raise exception
        'fn_kernel_trigger_submit: idempotency key % conflicted but no committed row holds it — a '
        'concurrent submission of the same key is still open. Retry.', v_idem
        using errcode = '40001';
    end if;
    return jsonb_build_object(
      'ok', p_status in ('accepted','duplicate'), 'duplicate', true, 'status', p_status,
      'inbox_id', p_inbox, 'idempotency_key', v_idem, 'trigger_type', p_type,
      'workflow_id', p_wf, 'business_object_id', p_obj, 'run_id', p_run, 'trace_id', p_trace,
      'refusal_reason', p_reason,
      'created', jsonb_build_object('inbox_row',0,'run',0,'step_run',0,'task',0,'event',0),
      'note','idempotency_key already recorded; the first result is returned and nothing was created');
  end if;

  -- ---- 3. normalize to a REGISTERED trigger type -------------------------------------------
  select t.workflow_id, t.business_object_rule, t.allowed_source_systems, t.system_actor_id,
         t.activation_state, t.implementation_state, t.source_class, t.accountable_note
    into t_workflow, t_rule, t_sources, t_actor, t_activation, t_impl, t_class, t_note
    from public.kernel_trigger_type t where t.trigger_type = v_type_in;

  v_status := null; v_reason := null;

  if t_class is null then
    v_status := 'refused';
    v_reason := format('no registered trigger type named %s. An unmapped trigger is recorded and '
                    || 'refused; it is never resolved to the nearest workflow.', v_type_in);
  elsif t_class is distinct from v_class then
    v_status := 'refused';
    v_reason := format('trigger type %s is registered under source class %s and was submitted as %s',
                       v_type_in, t_class, v_class);
  elsif not (v_system = any (t_sources)) then
    v_status := 'refused';
    v_reason := format('source system %s is not permitted to submit %s. Permitted: %s',
                       v_system, v_type_in, array_to_string(t_sources, ', '));
  elsif t_impl = 'DEFERRED_HANDLER' then
    v_status := 'deferred';
    v_reason := format('trigger type %s is a DEFERRED_HANDLER: the frozen Phase B registry declares '
                    || 'no workflow that starts from this signal. %s', v_type_in, t_note);
  elsif t_activation <> 'active' then
    v_status := 'refused';
    v_reason := format('trigger type %s is registered with activation_state %s and does not accept '
                    || 'submissions', v_type_in, t_activation);
  end if;

  -- ---- 4. resolve the business object BY THE RECORDED RULE ---------------------------------
  if v_status is null then
    v_obj := t_rule;
    -- regexp_matches is set-returning, so it is driven by a FOR loop and never placed inside a
    -- boolean expression: a set-returning function in a boolean expression raises 42804.
    for v_key in select rr.mk[1] from regexp_matches(t_rule, '\{([a-zA-Z0-9_]+)\}', 'g') as rr(mk) loop
      v_val := nullif(btrim(coalesce(v_payload->>v_key,'')), '');
      if v_val is null then
        v_missing := coalesce(v_missing || ', ', '') || v_key;
      else
        v_obj := replace(v_obj, '{' || v_key || '}', v_val);
      end if;
    end loop;

    if v_missing is not null then
      v_status := 'refused';
      v_reason := format('business object rule %s needs payload key(s) %s and the payload does not '
                      || 'carry them. The object is refused, not guessed.', t_rule, v_missing);
    elsif v_obj ~ '[{}]' then
      v_status := 'refused';
      v_reason := format('business object rule %s did not fully resolve: %s', t_rule, v_obj);
    end if;
  end if;

  -- ---- 5. the founder boundary, checked again at call time ---------------------------------
  --
  -- The registry guard in §1 refuses such a row at write time. This is the second check, because a
  -- row could predate the guard, and because "normal autonomous work never routes through the
  -- founder or the Chief of Staff" is the kind of rule that must hold even when the table is wrong.
  if v_status is null then
    select kind, role_id into v_kind, v_owner
      from public.fn_phase_c_resolve_actor(
        (select w.accountable_role_id from public.phase_b_workflow w where w.workflow_id = t_workflow));
    select s.step_id, r.role_id into v_step_id, v_step_owner
      from public.phase_b_workflow_step s,
           lateral public.fn_phase_c_resolve_actor(s.accountable_role_id) r
     where s.workflow_id = t_workflow and s.step_no = 1;

    if v_owner is null or v_kind is distinct from 'canonical' then
      v_status := 'refused';
      v_reason := format('workflow %s names accountable role that resolves to %s — no run created',
                         t_workflow, coalesce(v_kind,'nothing'));
    elsif v_owner in ('founder','chief_of_staff') or coalesce(v_step_owner,'') in ('founder','chief_of_staff') then
      v_status := 'refused';
      v_reason := format('workflow %s would put autonomous work on %s / %s (step %s). Normal '
                      || 'autonomous work bypasses both the founder and the Chief of Staff.',
                         t_workflow, v_owner, coalesce(v_step_owner,'(none)'), coalesce(v_step_id,'(none)'));
    end if;
  end if;

  -- ---- 6. refusals and deferrals are RECORDED, with their own trace ------------------------
  if v_status is not null then
    v_actor := coalesce(t_actor, 'system.webhook_receiver');
    v_trace := public.fn_kernel_intake_execution('dbfn:fn_kernel_trigger_submit(jsonb)', jsonb_build_object(
      'subject_kind','trigger_inbox', 'subject_ref', v_inbox::text,
      'system_actor_id', v_actor,
      'actor_role_id', coalesce(nullif(v_owner,''), ''),
      'component_id','dbfn:fn_kernel_trigger_submit(jsonb)',
      'authority_result', v_status || ': ' || v_reason,
      'input_hash', encode(sha256(convert_to(v_idem || '|' || v_payload::text, 'UTF8')), 'hex'),
      'evidence_refs', jsonb_build_array(jsonb_build_object(
        'source_class', v_class, 'source_system', v_system, 'source_ref', v_ref,
        'external_ref', v_ext, 'submitted_trigger_type', v_type_in,
        'idempotency_key', v_idem, 'raw_payload', v_payload)),
      'state_before','pending', 'state_after', v_status, 'status','sealed'));

    update public.kernel_trigger_inbox
       set status = v_status, refusal_reason = v_reason, trace_id = v_trace,
           trigger_type = (case when t_class is null then null else v_type_in end),
           processed_at = now()
     where inbox_id = v_inbox;

    return jsonb_build_object(
      'ok', false, 'duplicate', false, 'status', v_status, 'inbox_id', v_inbox,
      'idempotency_key', v_idem, 'trigger_type', v_type_in, 'workflow_id', t_workflow,
      'business_object_id', null, 'run_id', null, 'trace_id', v_trace,
      'refusal_reason', v_reason, 'correlation_id', v_corr, 'causation_id', v_caus,
      'created', jsonb_build_object('inbox_row',1,'run',0,'step_run',0,'task',0,'event',0));
  end if;

  -- ---- 7. THE ONLY creator of business work is called ---------------------------------------
  --
  -- No insert into phase_c_task, phase_c_workflow_run, phase_c_workflow_step_run,
  -- phase_c_handoff_run or phase_c_event_outbox appears anywhere in this function. All six objects
  -- come from fn_kernel_workflow_start, atomically, or none of them does.
  v_start := public.fn_kernel_workflow_start(jsonb_build_object(
    'workflow_id',        t_workflow,
    'business_object_id', v_obj,
    'object_version',     v_version,
    'source_kind',        'autonomous',
    'source_ref',         'trigger_inbox:' || v_inbox,
    'correlation_id',     v_corr,
    'causation_id',       v_caus,
    'requested_by',       v_by,
    'priority',           v_priority,
    'trigger_ctx',        jsonb_build_object(
        'inbox_id', v_inbox, 'trigger_type', v_type_in, 'source_class', v_class,
        'source_system', v_system, 'source_ref', v_ref, 'external_ref', v_ext,
        'idempotency_key', v_idem, 'business_object_rule', t_rule, 'raw_payload', v_payload)));

  v_run    := (v_start->>'run_id')::bigint;
  v_status := case when coalesce((v_start->>'duplicate')::boolean, false)
                   then 'duplicate' else 'accepted' end;

  if v_run is null then
    raise exception 'fn_kernel_trigger_submit: fn_kernel_workflow_start returned no run_id for % / %',
      t_workflow, v_obj using errcode = '23502';
  end if;

  -- ---- 8. the adapter's own execution trace, parented to the run's root --------------------
  v_trace := public.fn_kernel_intake_execution('dbfn:fn_kernel_trigger_submit(jsonb)', jsonb_build_object(
    'subject_kind','trigger_inbox', 'subject_ref', v_inbox::text,
    'run_id', v_run, 'step_run_id', (v_start->>'step_run_id')::bigint,
    'task_id', (v_start->>'task_id')::bigint,
    'system_actor_id', t_actor,
    'actor_role_id', v_start->>'step_accountable_role_id',
    'manager_role_id', v_start->>'accountable_role_id',
    'component_id','dbfn:fn_kernel_trigger_submit(jsonb)',
    'authority_result', v_status || ': trigger type ' || v_type_in || ' -> ' || t_workflow
                     || ' by registry, business object by rule ' || t_rule,
    'input_hash', encode(sha256(convert_to(v_idem || '|' || v_payload::text, 'UTF8')), 'hex'),
    'output_hash', encode(sha256(convert_to(v_start::text, 'UTF8')), 'hex'),
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'source_class', v_class, 'source_system', v_system, 'source_ref', v_ref,
      'external_ref', v_ext, 'idempotency_key', v_idem,
      'business_object_rule', t_rule, 'business_object_id', v_obj, 'raw_payload', v_payload)),
    'event_ids', jsonb_build_array(v_start->>'event_id'),
    'state_before','pending', 'state_after', v_status, 'status','sealed',
    'parent_trace_id', (v_start->>'run_trace_id')::bigint));

  update public.kernel_trigger_inbox
     set status = v_status, trigger_type = v_type_in, workflow_id = t_workflow,
         business_object_id = v_obj, run_id = v_run, trace_id = v_trace, processed_at = now()
   where inbox_id = v_inbox;

  return jsonb_build_object(
    'ok', true, 'duplicate', (v_status = 'duplicate'), 'status', v_status,
    'inbox_id', v_inbox, 'idempotency_key', v_idem,
    'source_class', v_class, 'trigger_type', v_type_in, 'workflow_id', t_workflow,
    'business_object_id', v_obj, 'object_version', v_version,
    'run_id', v_run, 'step_run_id', (v_start->>'step_run_id')::bigint,
    'task_id', (v_start->>'task_id')::bigint,
    'accountable_role_id', v_start->>'accountable_role_id',
    'step_accountable_role_id', v_start->>'step_accountable_role_id',
    'handoff_run_id', (v_start->>'handoff_run_id')::bigint,
    'event_id', v_start->>'event_id', 'outbox_id', (v_start->>'outbox_id')::bigint,
    'trace_id', v_trace, 'run_trace_id', (v_start->>'run_trace_id')::bigint,
    'correlation_id', v_corr, 'causation_id', v_caus, 'system_actor_id', t_actor,
    'created', jsonb_build_object(
      'inbox_row', 1,
      'run',      (case when v_status = 'duplicate' then 0 else 1 end),
      'step_run', (case when v_status = 'duplicate' then 0 else 1 end),
      'task',     (case when v_status = 'duplicate' then 0 else 1 end),
      'event',    (case when v_status = 'duplicate' then 0 else 1 end),
      'adapter_trace', 1));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_trigger_type_routing_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_wf_owner   text;
  v_step_owner text;
  v_step_id    text;
begin
  if new.workflow_id is null then
    return new;                     -- a DEFERRED_HANDLER routes to nothing and owns nothing
  end if;

  select w.accountable_role_id into v_wf_owner
    from public.phase_b_workflow w where w.workflow_id = new.workflow_id;

  select s.step_id, s.accountable_role_id into v_step_id, v_step_owner
    from public.phase_b_workflow_step s
   where s.workflow_id = new.workflow_id and s.step_no = 1;

  -- SELECT INTO that matched nothing leaves NULLs, so the absence is tested rather than assumed.
  if v_step_id is null then
    raise exception
      'kernel_trigger_type %: workflow % declares no step_no = 1, so this trigger type has no entry '
      'step to own the work it would create.', new.trigger_type, new.workflow_id
      using errcode = '23502';
  end if;

  if v_wf_owner in ('founder','chief_of_staff') or v_step_owner in ('founder','chief_of_staff') then
    raise exception
      'kernel_trigger_type %: workflow % is owned by "%" and its entry step % is owned by "%". '
      'Normal autonomous work bypasses both the founder and the Chief of Staff — that is a frozen '
      'boundary, not a preference. Register this route only if it is a founder command, and founder '
      'commands do not come through the trigger inbox.',
      new.trigger_type, new.workflow_id, v_wf_owner, v_step_id, v_step_owner
      using errcode = '23514';
  end if;

  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_truncate_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ctx    text;
  v_reason text;
  v_owner  text;
begin
  get diagnostics v_ctx = pg_context;

  -- There is no Door 1 here on purpose. No kernel routine truncates a protected table; a TRUNCATE
  -- is always maintenance, so the only door is the audited one the row guard already uses.
  v_reason := nullif(btrim(current_setting('kernel.maintenance_reason', true)), '');
  select tableowner into v_owner from pg_tables
   where schemaname = tg_table_schema and tablename = tg_table_name;
  if v_reason is not null and current_user = v_owner then
    perform public.fn_kernel_record_maintenance_write(
      current_user, session_user, tg_table_name, 'TRUNCATE', v_reason, v_ctx);
    return null;
  end if;

  raise exception
    'TRUNCATE on %.% is refused: a truncate is not a kernel write and fires no row-level guard.',
    tg_table_schema, tg_table_name
    using errcode = '42501',
          detail = 'Call stack was:' || chr(10) || v_ctx,
          hint = 'TRUNCATE removes every row without firing fn_kernel_write_guard, so it is '
              || 'refused outright. Historical maintenance needs BOTH a stated reason — set local '
              || 'kernel.maintenance_reason — AND the table owner, exactly as it does for an '
              || 'ordinary write, and it is recorded in kernel_maintenance_write either way.';
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_truncate_protection_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with enforcing as (
    select distinct c.relname as tbl
      from pg_trigger   tg
      join pg_class     c  on c.oid = tg.tgrelid
      join pg_namespace ns on ns.oid = c.relnamespace
      join pg_proc      p  on p.oid = tg.tgfoid
     where ns.nspname = 'public'
       and not tg.tgisinternal
       and (tg.tgtype & 32) = 0
       and p.prokind = 'f'
       and pg_get_functiondef(p.oid) ilike '%raise exception%'
  ),
  guarded as (
    select distinct c.relname as tbl
      from pg_trigger   tg
      join pg_class     c  on c.oid = tg.tgrelid
      join pg_namespace ns on ns.oid = c.relnamespace
     where ns.nspname = 'public'
       and not tg.tgisinternal
       and (tg.tgtype & 32) <> 0
  ),
  m as (
    select e.tbl,
           (e.tbl in (select tbl from guarded)) as has_guard,
           (   has_table_privilege('service_role',  format('public.%I', e.tbl), 'TRUNCATE')
            or has_table_privilege('authenticated', format('public.%I', e.tbl), 'TRUNCATE')
            or has_table_privilege('anon',          format('public.%I', e.tbl), 'TRUNCATE')
           ) as grants_truncate
      from enforcing e
  )
  select 'enforcing_tables_without_a_truncate_guard',
         '0',
         count(*) filter (where not has_guard)::text || ' of ' || count(*)::text,
         count(*) filter (where not has_guard) = 0
    from m
  union all
  select 'enforcing_tables_still_granting_truncate',
         '0',
         count(*) filter (where grants_truncate)::text || ' of ' || count(*)::text,
         count(*) filter (where grants_truncate) = 0
    from m
  union all
  -- Informational, and it is the number that made the defect invisible: how many tables the old
  -- typed list covered. Kept so a reader can see the population this check watches is derived.
  select 'raw_enforcing_tables_watched',
         'informational',
         count(*)::text || ' of ' || count(*)::text,
         true
    from m;
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_workflow_graph_validate()
 RETURNS TABLE(workflow_id text, workflow_name text, steps bigint, start_step_id text, start_ok boolean, reachable_steps bigint, unreachable_steps bigint, cycles bigint, nonterminal_without_successor bigint, successor_not_a_step bigint, unresolved_successor_owners bigint, registry_gap_no_handoff bigint, false_terminal_steps bigint, same_owner_hops_no_edge bigint, owners_unresolved bigint, closure_steps bigint, closure_path_topological boolean, closure_path_executable boolean, failure_states_valid boolean, verdict text, detail text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
with recursive k as (
  -- the classifier, once per step. Everything below reads THIS, never phase_b_handoff directly,
  -- except has_out_edge, which exists precisely to measure the old consumer's mistake.
  select s.workflow_id, s.step_id, s.step_no, s.is_closure_step, s.next_step_if_pass,
         s.accountable_role_id, s.failure_workflow_state,
         c.kind, c.next_step_id, c.next_owner_role_id, c.handoff_id, c.this_owner_role_id,
         exists (select 1 from public.phase_b_handoff h where h.from_step_id = s.step_id) as has_out_edge
  from public.phase_b_workflow_step s
  cross join lateral public.fn_kernel_step_successor(s.step_id) c
),
walk as (
  -- topological reachability from the declared start along next_step_if_pass
  select k.workflow_id, k.step_id, k.next_step_id, k.kind, 1 as depth,
         array[k.step_id] as path, false as cyc
  from k where k.step_no = 1
  union all
  select n.workflow_id, n.step_id, n.next_step_id, n.kind, w.depth + 1,
         w.path || n.step_id, n.step_id = any (w.path)
  from walk w join k n on n.step_id = w.next_step_id
  where not w.cyc and w.depth < 400
),
ewalk as (
  -- executable reachability: the same walk, stopped the moment the engine would refuse to open
  select k.workflow_id, k.step_id, k.next_step_id, k.kind, 1 as depth, array[k.step_id] as path
  from k where k.step_no = 1
  union all
  select n.workflow_id, n.step_id, n.next_step_id, n.kind, e.depth + 1, e.path || n.step_id
  from ewalk e join k n on n.step_id = e.next_step_id
  where e.kind in ('same_owner','cross_owner')
    and not (n.step_id = any (e.path)) and e.depth < 400
),
per as (
  select w.workflow_id as wf, w.workflow_name as wname,
         count(*)                                                        as n_steps,
         min(k.step_id) filter (where k.step_no = 1)                     as start_step,
         count(*) filter (where k.step_no = 1)                           as n_starts,
         count(*) filter (where k.this_owner_role_id is null)            as n_owner_unresolved,
         count(*) filter (where k.is_closure_step)                       as n_closure,
         count(*) filter (where k.kind = 'successor_not_a_step')         as n_not_a_step,
         count(*) filter (where k.kind = 'successor_owner_unresolved')   as n_succ_owner_bad,
         count(*) filter (where k.kind = 'registry_gap_no_handoff')      as n_gap,
         count(*) filter (where k.kind = 'closure_flag_disagrees')       as n_flag_bad,
         -- legitimate, named, and not a defect
         count(*) filter (where not k.has_out_edge and k.kind = 'same_owner') as n_same_owner_noedge,
         -- FALSE TERMINAL, computed without the classifier's verdict driving it:
         -- no outgoing handoff row, not the declared closure step, and no openable successor.
         count(*) filter (where not k.has_out_edge
                            and not k.is_closure_step
                            and k.next_step_if_pass <> 'WORKFLOW_COMPLETE'
                            and k.kind not in ('same_owner','cross_owner'))  as n_false_terminal,
         count(*) filter (where not exists (select 1 from public.phase_b_workflow_state x
                                             where x.state = k.failure_workflow_state)) as n_fail_state_bad
  from public.phase_b_workflow w
  join k on k.workflow_id = w.workflow_id
  group by w.workflow_id, w.workflow_name
),
reach as (
  select p.wf,
         (select count(distinct x.step_id) from walk x where x.workflow_id = p.wf)   as n_reach,
         (select count(*) from walk x where x.workflow_id = p.wf and x.cyc)          as n_cyc,
         (select count(*) from k where k.workflow_id = p.wf
            and not exists (select 1 from walk x where x.step_id = k.step_id))       as n_unreach,
         -- reachable steps the engine cannot progress from at all
         (select count(*) from walk x
           where x.workflow_id = p.wf
             and x.kind not in ('closure','same_owner','cross_owner'))               as n_no_successor,
         exists (select 1 from walk x where x.workflow_id = p.wf and x.kind = 'closure') as topo_ok,
         exists (select 1 from ewalk x where x.workflow_id = p.wf and x.kind = 'closure') as exec_ok
  from per p
),
rows_out as (
  select p.wf, p.wname, p.n_steps, p.start_step,
         (p.n_starts = 1 and p.start_step is not null
          and exists (select 1 from k where k.step_id = p.start_step
                       and k.this_owner_role_id is not null))                        as start_ok,
         r.n_reach, r.n_unreach, r.n_cyc, r.n_no_successor,
         p.n_not_a_step, p.n_succ_owner_bad, p.n_gap, p.n_false_terminal,
         p.n_same_owner_noedge, p.n_owner_unresolved, p.n_closure,
         r.topo_ok, r.exec_ok, (p.n_fail_state_bad = 0) as fail_ok, p.n_flag_bad
  from per p join reach r on r.wf = p.wf
)
select o.wf, o.wname, o.n_steps, o.start_step, o.start_ok,
       o.n_reach, o.n_unreach, o.n_cyc, o.n_no_successor,
       o.n_not_a_step, o.n_succ_owner_bad, o.n_gap, o.n_false_terminal,
       o.n_same_owner_noedge, o.n_owner_unresolved, o.n_closure,
       o.topo_ok, o.exec_ok, o.fail_ok,
       case when o.start_ok and o.n_unreach = 0 and o.n_cyc = 0 and o.n_no_successor = 0
                 and o.n_false_terminal = 0 and o.n_succ_owner_bad = 0 and o.n_gap = 0
                 and o.n_owner_unresolved = 0 and o.n_closure > 0 and o.topo_ok and o.exec_ok
                 and o.fail_ok and o.n_flag_bad = 0
            then 'OK' else 'REGISTRY_DEFECT' end,
       coalesce(nullif(concat_ws('; ',
         case when not o.start_ok           then 'no single valid start' end,
         case when o.n_unreach > 0          then o.n_unreach || ' unreachable step(s)' end,
         case when o.n_cyc > 0              then o.n_cyc || ' cycle(s)' end,
         case when o.n_no_successor > 0     then o.n_no_successor
              || ' reachable step(s) the engine cannot progress from' end,
         case when o.n_not_a_step > 0       then o.n_not_a_step || ' successor(s) not a step' end,
         case when o.n_succ_owner_bad > 0   then o.n_succ_owner_bad
              || ' successor owner(s) that do not resolve to an active canonical role' end,
         case when o.n_gap > 0              then o.n_gap
              || ' owner change(s) with no declared handoff' end,
         case when o.n_false_terminal > 0   then o.n_false_terminal
              || ' step(s) with no handoff edge, not closure, and no openable successor' end,
         case when o.n_owner_unresolved > 0 then o.n_owner_unresolved || ' step owner(s) unresolved' end,
         case when o.n_flag_bad > 0         then o.n_flag_bad || ' closure flag disagreement(s)' end,
         case when not o.topo_ok            then 'no topological path to a closure step' end,
         case when o.topo_ok and not o.exec_ok then 'closure is topologically reachable but NOT '
              || 'executable: the walk stops at a step the engine refuses to open' end,
         case when not o.fail_ok            then 'failure_workflow_state not in the state registry' end
       ), ''), 'clean')
from rows_out o

union all

-- ---- the summary row. Its numbers are SUMS of the per-workflow numbers, so it cannot drift. ----
select 'SUMMARY', 'all workflows', sum(o.n_steps), null, bool_and(o.start_ok),
       sum(o.n_reach), sum(o.n_unreach), sum(o.n_cyc), sum(o.n_no_successor),
       sum(o.n_not_a_step), sum(o.n_succ_owner_bad), sum(o.n_gap), sum(o.n_false_terminal),
       sum(o.n_same_owner_noedge), sum(o.n_owner_unresolved), sum(o.n_closure),
       bool_and(o.topo_ok), bool_and(o.exec_ok), bool_and(o.fail_ok),
       case when bool_and(o.start_ok) and sum(o.n_unreach) = 0 and sum(o.n_cyc) = 0
                 and sum(o.n_no_successor) = 0 and sum(o.n_false_terminal) = 0
                 and sum(o.n_succ_owner_bad) = 0 and sum(o.n_gap) = 0
                 and sum(o.n_owner_unresolved) = 0 and bool_and(o.topo_ok) and bool_and(o.exec_ok)
                 and bool_and(o.fail_ok) and sum(o.n_flag_bad) = 0
            then 'OK' else 'REGISTRY_DEFECT' end,
       format('workflows with no EXECUTABLE closure path %s of %s; with no topological closure '
           || 'path %s of %s; reachable steps the engine cannot progress from %s; false terminal '
           || 'steps %s; unresolved successor owners %s; registry gaps with no handoff %s; '
           || 'successors that are not a step %s; cycles %s; step owners unresolved %s; '
           || 'legitimate same-owner hops with no handoff edge %s (not a defect)',
         count(*) filter (where not o.exec_ok), count(*),
         count(*) filter (where not o.topo_ok), count(*),
         sum(o.n_no_successor), sum(o.n_false_terminal), sum(o.n_succ_owner_bad),
         sum(o.n_gap), sum(o.n_not_a_step), sum(o.n_cyc), sum(o.n_owner_unresolved),
         sum(o.n_same_owner_noedge))
from rows_out o
order by 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_workflow_run_trace_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_state text;
begin
  if new.state is not distinct from old.state then return new; end if;

  -- No trace yet is only legal while the run is still being built inside fn_kernel_workflow_start,
  -- which writes the run row and its trace in the same statement sequence. Any later state change
  -- without a trace is the defect this guard exists for.
  if new.trace_id is null then
    raise exception
      'phase_c_workflow_run %: state % -> % with no trace', new.run_id, old.state, new.state
      using errcode = '23514',
            hint = 'fn_kernel_workflow_start writes the run trace. Nothing else may move a run.';
  end if;

  -- A SEALED trace is never edited in place; fn_phase_c_trace_advance supersedes it with a new row
  -- and links the two. The append-only guard refuses an edit and it is right to.
  new.trace_id := public.fn_phase_c_trace_advance(
    new.trace_id, new.state,
    new.state in ('completed','cancelled','superseded','failed'),
    jsonb_build_object(
      'state_before', old.state,
      'subject_kind','workflow_run', 'subject_ref', new.run_id::text, 'run_id', new.run_id,
      'command_id', new.command_id));

  select t.state_after into v_state from public.phase_c_trace t where t.trace_id = new.trace_id;
  if v_state is distinct from new.state then
    raise exception
      'phase_c_workflow_run %: the run says % and its trace says %', new.run_id, new.state, v_state
      using errcode = '23514',
            hint = 'The trace must be advanced in the same transaction as the state it records.';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_workflow_start(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_pd_dispatch jsonb := '{}'::jsonb;  -- D36
  w  public.phase_b_workflow%rowtype;
  s  public.phase_b_workflow_step%rowtype;
  v_wf        text   := nullif(btrim(coalesce(p_input->>'workflow_id','')), '');
  v_object    text   := nullif(btrim(coalesce(p_input->>'business_object_id','')), '');
  v_source_k  text   := nullif(btrim(coalesce(p_input->>'source_kind','')), '');
  v_source_r  text   := nullif(btrim(coalesce(p_input->>'source_ref','')), '');
  v_by        text   := nullif(btrim(coalesce(p_input->>'requested_by','')), '');
  v_command   bigint := nullif(p_input->>'command_id','')::bigint;
  v_version   bigint := coalesce(nullif(p_input->>'object_version','')::bigint, 1);
  v_priority  text   := coalesce(nullif(p_input->>'priority',''), 'P2');
  v_ctx       jsonb  := coalesce(p_input->'trigger_ctx', '{}'::jsonb);
  v_corr      text;
  v_caus      text;
  v_dedupe    text;
  v_run       bigint;
  v_step_run  bigint;
  v_task      bigint;
  v_outbox    bigint;
  v_run_trace bigint;
  v_step_trace bigint;
  v_task_trace bigint;
  v_task_parent bigint;
  v_owner     text;
  v_step_owner text;
  v_kind      text;
  v_start_event text;
  v_input_hash text;
  -- Scalars, not a RECORD: a plpgsql record read after a SELECT INTO that matched nothing is a
  -- trap this estate has already paid for once.
  v_prior_run   bigint;
  v_prior_state text;
  v_prior_trace bigint;
  v_prior_step  bigint;
  v_prior_task  bigint;
begin
  -- ---- 0. a consumer may not re-enter the producer ----------------------------------------
  perform public.fn_kernel_assert_not_in_delivery('fn_kernel_workflow_start');

  if v_wf is null or v_object is null or v_source_r is null or v_by is null then
    raise exception 'fn_kernel_workflow_start: workflow_id, business_object_id, source_ref and requested_by are all required (got %, %, %, %)',
      coalesce(v_wf,'(null)'), coalesce(v_object,'(null)'), coalesce(v_source_r,'(null)'), coalesce(v_by,'(null)')
      using errcode = '22023';
  end if;
  if v_source_k not in ('founder_command','autonomous') then
    raise exception 'fn_kernel_workflow_start: source_kind must be founder_command or autonomous, got %',
      coalesce(v_source_k,'(null)') using errcode = '22023';
  end if;
  if v_source_k = 'founder_command' and v_command is null then
    raise exception 'fn_kernel_workflow_start: source_kind founder_command requires a command_id'
      using errcode = '22023';
  end if;
  v_corr := coalesce(nullif(btrim(p_input->>'correlation_id'),''), v_source_r);
  v_caus := coalesce(nullif(btrim(p_input->>'causation_id'),''), v_source_r);

  -- ---- (a) the workflow run ---------------------------------------------------------------
  select * into w from public.phase_b_workflow where workflow_id = v_wf;
  if not found then
    raise exception 'fn_kernel_workflow_start (a): % is not in the frozen Phase B workflow registry — fail closed',
      v_wf using errcode = '23503';
  end if;

  -- The accountable role comes from the registry and must RESOLVE. Never defaulted; there is no
  -- chief_of_staff fallback here and there will not be one.
  select kind, role_id into v_kind, v_owner from public.fn_phase_c_resolve_actor(w.accountable_role_id);
  if v_owner is null or v_kind is distinct from 'canonical' then
    raise exception 'fn_kernel_workflow_start (a): workflow % names accountable role %, which resolves to % — no run created',
      v_wf, w.accountable_role_id, coalesce(v_kind,'nothing') using errcode = '23514';
  end if;

  -- The start event is read from the frozen registry, never concatenated. A literal
  -- 'EV-W01-STARTED' once announced W01 for every command the company had ever received.
  v_start_event := public.fn_phase_c_lifecycle_event(v_wf, 'started');
  if v_start_event is null then
    raise exception 'fn_kernel_workflow_start (f): workflow % declares no .started event in phase_b_event',
      v_wf using errcode = '23503';
  end if;

  -- Idempotency, unchanged in shape from fn_phase_c_workflow_start so existing runs still match.
  v_dedupe := v_wf || ':' || v_object || ':' || v_version::text;
  select r.run_id, r.state, r.trace_id
    into v_prior_run, v_prior_state, v_prior_trace
    from public.phase_c_workflow_run r where r.dedupe_key = v_dedupe;
  if v_prior_run is not null then
    select sr.step_run_id into v_prior_step from public.phase_c_workflow_step_run sr
     where sr.run_id = v_prior_run order by sr.step_run_id limit 1;
    select t.task_id into v_prior_task from public.phase_c_task t
     where t.run_id = v_prior_run order by t.task_id limit 1;
    -- A second call creates NOTHING. Not a new run, not a second task, not a second event.
    return jsonb_build_object('ok', true, 'duplicate', true, 'run_id', v_prior_run,
      'workflow_id', v_wf, 'business_object_id', v_object, 'object_version', v_version,
      'state', v_prior_state, 'step_run_id', v_prior_step,
      'task_id', v_prior_task, 'trace_id', v_prior_trace,
      'dedupe_key', v_dedupe, 'created', '{}'::jsonb);
  end if;

  v_input_hash := encode(sha256(convert_to(
    v_wf || '|' || v_object || '|' || v_version::text || '|' || v_ctx::text, 'UTF8')), 'hex');

  insert into public.phase_c_workflow_run
    (workflow_id, business_object_id, object_version, start_event, accountable_role_id,
     state, dedupe_key, command_id)
  values (v_wf, v_object, v_version, v_start_event, v_owner, 'queued', v_dedupe, v_command)
  returning run_id into v_run;
  if v_run is null then
    raise exception 'fn_kernel_workflow_start (a): the workflow run insert produced no row for %', v_wf
      using errcode = '23502';
  end if;

  -- ---- (d.1) the ROOT trace, before anything hangs from it ---------------------------------
  v_run_trace := public.fn_phase_c_trace_write('TRACE-WORKFLOW', jsonb_build_object(
    'subject_kind','workflow_run', 'subject_ref', v_run::text, 'run_id', v_run,
    'command_id', v_command,
    'actor_role_id', v_owner, 'system_actor_id','system.workflow_engine',
    'input_hash', v_input_hash,
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'business_object_id', v_object, 'dedupe_key', v_dedupe, 'source_kind', v_source_k,
      'source_ref', v_source_r, 'requested_by', v_by, 'trigger_ctx', v_ctx)),
    'event_ids', jsonb_build_array(v_start_event),
    'state_before','', 'state_after','queued', 'status','open'));
  update public.phase_c_workflow_run set trace_id = v_run_trace where run_id = v_run;
  if v_run_trace is null then
    raise exception 'fn_kernel_workflow_start (d): the run has no root trace' using errcode = '23502';
  end if;

  -- The run is ACTIVE because its first step run is opened in this same transaction. The move is
  -- made as a declared transition (queued -> active) so z20_phase_c_workflow_state_guard and
  -- phase_b_workflow_transition are load-bearing rather than decorative.
  update public.phase_c_workflow_run set state = 'active' where run_id = v_run;

  -- ---- (b) the initial step run, at the REGISTRY entry step --------------------------------
  select * into s from public.phase_b_workflow_step
   where workflow_id = v_wf and step_no = 1;               -- UNIQUE (workflow_id, step_no)
  if not found then
    raise exception 'fn_kernel_workflow_start (b): workflow % declares no step_no = 1', v_wf
      using errcode = '23502';
  end if;

  select kind, role_id into v_kind, v_step_owner from public.fn_phase_c_resolve_actor(s.accountable_role_id);
  if v_step_owner is null or v_kind is distinct from 'canonical' then
    raise exception 'fn_kernel_workflow_start (c): step % names owner %, which resolves to % — no task created',
      s.step_id, s.accountable_role_id, coalesce(v_kind,'nothing') using errcode = '23514';
  end if;

  insert into public.phase_c_workflow_step_run
    (run_id, step_id, accountable_role_id, reviewer_role_id, state, attempt_no,
     input_hash, output_hash, gates_evaluated, authority_result, idempotency_key)
  values (v_run, s.step_id, v_step_owner, coalesce(s.independent_reviewer_role_id,''), 'active', 1,
          v_input_hash, '', '[]'::jsonb, 'pending: the step has not been executed yet',
          s.idempotency_scope || '|' || v_run || '|' || s.step_id || '|kernel')
  returning step_run_id into v_step_run;
  if v_step_run is null then
    raise exception 'fn_kernel_workflow_start (b): the step run insert produced no row for %', s.step_id
      using errcode = '23502';
  end if;

  -- The step run gets its own TRACE-STEP, parented to the run's root. phase_c_workflow_step_run
  -- has no trace guard trigger (only phase_c_task does), so an active step run with trace_id NULL
  -- is exactly what nobody notices — the first rehearsal of this file measured 6 of 11 step runs
  -- in that state, two of them created by this function.
  v_step_trace := public.fn_phase_c_trace_write('TRACE-STEP', jsonb_build_object(
    'subject_kind','step_run', 'subject_ref', v_step_run::text,
    'run_id', v_run, 'step_run_id', v_step_run, 'command_id', v_command,
    'actor_role_id', v_step_owner, 'system_actor_id','system.workflow_engine',
    'reviewer_role_id', coalesce(s.independent_reviewer_role_id,''),
    'authority_result','pending: the step has not been executed yet',
    'input_hash', v_input_hash,
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'step_id', s.step_id, 'step_name', s.step_name, 'entry_condition', s.entry_condition)),
    'state_before','', 'state_after','active', 'status','open'));
  update public.phase_c_workflow_step_run set trace_id = v_step_trace where step_run_id = v_step_run;
  update public.phase_c_trace set parent_trace_id = v_run_trace where trace_id = v_step_trace;
  if v_step_trace is null then
    raise exception 'fn_kernel_workflow_start (d): step run % has no trace', v_step_run
      using errcode = '23502';
  end if;

  -- ---- (c) EXACTLY ONE operational task -----------------------------------------------------
  -- Deterministic key. It is also the key the invariant check looks for: a founder command may
  -- have run:N:step:* work or cmd:N:* plan rows, never both.
  v_task := public.fn_phase_c_task_create(jsonb_build_object(
    'source_kind', v_source_k, 'source_ref', v_source_r,
    'command_id', v_command, 'run_id', v_run, 'workflow_id', v_wf, 'step_id', s.step_id,
    'accountable_role_id', v_step_owner,
    'objective', format('%s — %s: perform %s (%s) for %s.',
                        w.workflow_name, v_start_event, s.step_id, s.step_name, v_object),
    'required_inputs', s.required_inputs,
    'requested_output', s.required_output,
    'acceptance_criteria', s.acceptance_criteria,
    'closure_criteria', s.closure_criteria,
    'priority', v_priority,
    'reviewer_required', (coalesce(s.independent_reviewer_role_id,'') <> ''),
    'reviewer_role_id', coalesce(s.independent_reviewer_role_id,''),
    'idempotency_key', 'run:' || v_run || ':step:' || s.step_id));
  if v_task is null then
    raise exception 'fn_kernel_workflow_start (c): no operational task was created for run % step %',
      v_run, s.step_id using errcode = '23502';
  end if;

  -- ---- (d.2) the CHILD trace for the task, parented -----------------------------------------
  -- a00_phase_c_task_trace_guard mints it on INSERT and parents it to the command trace when the
  -- task carries a command_id, otherwise to the run trace. Both are roots; what is refused here is
  -- a task hanging from nothing.
  select trace_id into v_task_trace from public.phase_c_task where task_id = v_task;
  select parent_trace_id into v_task_parent from public.phase_c_trace where trace_id = v_task_trace;
  if v_task_trace is null or v_task_parent is null then
    raise exception 'fn_kernel_workflow_start (d): task % has trace % with parent % — a task without its parented trace is refused',
      v_task, coalesce(v_task_trace::text,'null'), coalesce(v_task_parent::text,'null')
      using errcode = '23502';
  end if;

  -- ---- (e) NO HANDOFF AT START -- K14 -------------------------------------------------------
  -- Deliberately empty, and named so a reader looking for the block that used to be here finds the
  -- reason rather than a gap. The entry step's outgoing handoff run is created by
  -- fn_kernel_step_complete when that step completes, from its accepted output. Creating it here
  -- as well produced TWO open handoff runs on one registry edge the moment the entry step
  -- completed, and the successor step could then never be opened.

  -- ---- (f) ONE factual event ----------------------------------------------------------------
  -- Emitted LAST, after the state it describes exists. Its consumer may not create any of it.
  v_outbox := public.fn_kernel_outbox_emit(jsonb_build_object(
    'event_id', v_start_event, 'producer', 'kernel:workflow_start',
    'object_version', v_version,
    'correlation_id', v_corr, 'causation_id', v_caus, 'source_id', v_source_r,
    'command_id', v_command, 'workflow_run_id', v_run, 'step_run_id', v_step_run,
    'trace_id', v_run_trace,
    'dedupe_value', 'kernel:started:' || v_dedupe,
    'payload', jsonb_build_object(
      'fact','workflow.started',
      'workflow_id', v_wf, 'workflow_run_id', v_run, 'step_id', s.step_id,
      'step_run_id', v_step_run, 'task_id', v_task, 'handoff_run_id', null,
      'business_object_id', v_object, 'object_version', v_version,
      'accountable_role_id', v_owner, 'step_accountable_role_id', v_step_owner,
      'source_kind', v_source_k, 'source_ref', v_source_r, 'requested_by', v_by,
      'trace_id', v_run_trace, 'input_hash', v_input_hash)));
  if v_outbox is null then
    raise exception 'fn_kernel_workflow_start (f): no event row was written for run %', v_run
      using errcode = '23502';
  end if;

  -- ---- all or nothing -----------------------------------------------------------------------
  if v_run is null or v_step_run is null or v_task is null or v_outbox is null
     or v_run_trace is null or v_step_trace is null or v_task_trace is null then
    raise exception 'fn_kernel_workflow_start incomplete: run=% step_run=% task=% outbox=% run_trace=% step_trace=% task_trace=%',
      v_run, v_step_run, v_task, v_outbox, v_run_trace, v_step_trace, v_task_trace
      using errcode = '23502';
  end if;

  -- ---- (g) PHASE D DISPATCH (D36) --------------------------------------------------------------
  -- THE FIRST STEP OF A RUN IS OPENED HERE, INLINE — this routine does not call fn_kernel_open_step.
  -- Wiring the dispatch only into fn_kernel_open_step therefore reached successors and handoffs and
  -- missed every run's first step, which is the step an autonomous arrival actually causes. Both
  -- openers call the same routine so the two paths cannot drift apart.
  v_pd_dispatch := public.fn_phase_d_dispatch_step(jsonb_build_object(
    'step_run_id', v_step_run, 'actor_role_id', v_step_owner,
    'opened_by_kind', v_source_k, 'opened_by_ref', v_source_r,
    'idempotency_key', s.idempotency_scope || '|' || v_run || '|' || s.step_id || '|kernel',
    'correlation_id', v_corr));

  return jsonb_build_object(
    'ok', true, 'duplicate', false,
    'run_id', v_run, 'workflow_id', v_wf, 'workflow_name', w.workflow_name,
    'business_object_id', v_object, 'object_version', v_version, 'dedupe_key', v_dedupe,
    'state','active', 'accountable_role_id', v_owner,
    'step_id', s.step_id, 'step_run_id', v_step_run, 'step_accountable_role_id', v_step_owner,
    'task_id', v_task, 'task_idempotency_key', 'run:' || v_run || ':step:' || s.step_id,
    'handoff_run_id', null, 'handoff_id', null,
    'run_trace_id', v_run_trace, 'step_trace_id', v_step_trace,
    'task_trace_id', v_task_trace, 'handoff_trace_id', null,
    'event_id', v_start_event, 'outbox_id', v_outbox,
    'correlation_id', v_corr, 'causation_id', v_caus, 'source_id', v_source_r,
    'command_id', v_command, 'source_kind', v_source_k, 'requested_by', v_by,
    'created', jsonb_build_object('run',1, 'step_run',1, 'task',1, 'traces',
      3,
      'handoff', 0, 'event',1));
end $function$


CREATE OR REPLACE FUNCTION public.fn_kernel_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ctx    text;
  v_reason text;
  v_owner  text;
  v_ok     boolean;
begin
  get diagnostics v_ctx = pg_context;

  -- Door 1: an authorised routine is on the stack. The stack cannot be forged.
  select exists (
    select 1 from public.kernel_write_authority a
     where a.table_name = tg_table_name
       and v_ctx ~ ('PL/pgSQL function (public\.)?' || a.routine_name || '\(')
  ) into v_ok;
  if v_ok then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  -- Door 2: an explicit, audited maintenance operation BY THE TABLE OWNER. Under SECURITY INVOKER
  -- current_user is the caller's own role — service_role stays service_role, and the comparison
  -- means what it says.
  v_reason := nullif(btrim(current_setting('kernel.maintenance_reason', true)), '');
  select tableowner into v_owner from pg_tables
   where schemaname = tg_table_schema and tablename = tg_table_name;
  if v_reason is not null and current_user = v_owner then
    perform public.fn_kernel_record_maintenance_write(
      current_user, session_user, tg_table_name, tg_op, v_reason, v_ctx);
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  raise exception
    '% on %.% is refused: no routine with write authority for this table is on the call stack.',
    tg_op, tg_table_schema, tg_table_name
    using errcode = '42501',
          detail = 'Call stack was:' || chr(10) || v_ctx,
          hint = 'Business work is created by the kernel and only by the kernel. New work goes '
              || 'through fn_kernel_trigger_submit; a signal about a run that already exists goes '
              || 'through fn_kernel_signal_submit; a step is completed with fn_kernel_step_complete. '
              || 'public.kernel_write_authority lists every routine permitted to write this table '
              || 'and why. Historical maintenance needs BOTH a stated reason — set local '
              || 'kernel.maintenance_reason — AND the table owner; stating a reason alone is not '
              || 'enough, and since K37 it never was.';
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kernel_write_guard_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
with protected(t) as (values
  ('phase_c_workflow_run'),('phase_c_workflow_step_run'),('phase_c_task'),('phase_c_handoff_run'),
  ('kernel_trigger_inbox'),('kernel_signal_inbox'),('phase_c_event_outbox'),('phase_c_refund_decision')),
attached as (
  select p.t, exists (
    select 1 from pg_trigger tg join pg_class c on c.oid = tg.tgrelid
     join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relname = p.t
      and tg.tgname = 'a00_kernel_write_guard' and not tg.tgisinternal and tg.tgenabled <> 'D') a
  from protected p
),
-- Every routine whose DEPLOYED body writes a protected table, measured from prosrc with comments
-- stripped — the same scan that produced the seed. A writer that is not on the allow-list is a
-- routine that will be refused at runtime, and it is better to see it here than in an outage.
writers as (
  select p.proname, t.t
    from protected t
    join pg_proc p on true
    join pg_namespace n on n.oid = p.pronamespace and n.nspname = 'public'
   where regexp_replace(regexp_replace(p.prosrc, '/\*.*?\*/', ' ', 'g'), '--[^\n]*', ' ', 'g')
         ~ ('(insert\s+into|update|delete\s+from)\s+(public\.)?' || t.t || '\M')
     and p.proname <> 'fn_kernel_write_guard'
)
select 'protected_tables_without_the_guard_attached'::text,
       '0 of ' || (select count(*)::text from protected),
       (select count(*)::text from attached where not a) || ' of ' || (select count(*)::text from protected),
       (select count(*) = 0 from attached where not a)
union all
select 'routines_that_write_a_protected_table_with_no_authority',
       '0 of ' || (select count(*)::text from writers),
       (select count(*)::text from writers w
         where not exists (select 1 from public.kernel_write_authority a
                            where a.routine_name = w.proname and a.table_name = w.t))
         || ' of ' || (select count(*)::text from writers)
         || coalesce(' [' || (select string_agg(distinct w.proname || '->' || w.t, ', ')
              from writers w where not exists (select 1 from public.kernel_write_authority a
                                                where a.routine_name = w.proname and a.table_name = w.t)) || ']', ''),
       (select count(*) = 0 from writers w
         where not exists (select 1 from public.kernel_write_authority a
                            where a.routine_name = w.proname and a.table_name = w.t))
union all
select 'write_authority_granted_to_a_routine_that_does_not_exist',
       '0 of ' || (select count(*)::text from public.kernel_write_authority),
       (select count(*)::text from public.kernel_write_authority a
         where not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                            where n.nspname = 'public' and p.proname = a.routine_name))
         || ' of ' || (select count(*)::text from public.kernel_write_authority),
       (select count(*) = 0 from public.kernel_write_authority a
         where not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                            where n.nspname = 'public' and p.proname = a.routine_name))
union all
select 'ordinary_roles_holding_direct_dml_on_a_protected_table',
       '0',
       (select count(*)::text from information_schema.role_table_grants
         where table_schema = 'public' and table_name in (select t from protected)
           and grantee in ('anon','authenticated','PUBLIC')
           and privilege_type in ('INSERT','UPDATE','DELETE')),
       (select count(*) = 0 from information_schema.role_table_grants
         where table_schema = 'public' and table_name in (select t from protected)
           and grantee in ('anon','authenticated','PUBLIC')
           and privilege_type in ('INSERT','UPDATE','DELETE'))
union all
select 'maintenance_writes_recorded',
       'reported, never zero-by-hiding',
       (select count(*)::text from public.kernel_maintenance_write)
         || ' hand-made writes recorded'
         || coalesce(', most recent ' || (select max(at)::text from public.kernel_maintenance_write), ''),
       true
union all
select 'maintenance_writes_with_no_stated_reason',
       '0 of ' || (select count(*)::text from public.kernel_maintenance_write),
       (select count(*)::text from public.kernel_maintenance_write where btrim(reason) = '')
         || ' of ' || (select count(*)::text from public.kernel_maintenance_write),
       (select count(*) = 0 from public.kernel_maintenance_write where btrim(reason) = '');
$function$


CREATE OR REPLACE FUNCTION public.fn_knowledge_curator()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k record; v_health numeric; n_task int; n_appr int:=0; rec record; rc record; v_gaps jsonb;
begin
  select * into k from knowledge_kpis;
  select * into rc from reg_coverage;
  v_health := round(coalesce(k.coverage_pct,0)*0.30 + coalesce(k.accuracy_pct,0)*0.25 + coalesce(k.freshness_pct,0)*0.25 + coalesce(k.usage_reach_pct,0)*0.20,1);
  insert into knowledge_kpi_snapshots(snapshot_date,kpis) values (current_date, to_jsonb(k) || jsonb_build_object('health',v_health,'reg_coverage',to_jsonb(rc)))
    on conflict (snapshot_date) do update set kpis=excluded.kpis, created_at=now();

  perform kn_task('playbook_gap', (k.categories_total - k.cat_with_playbook) > 0, 'medium', 'Qualification playbook gaps',
    (k.categories_total - k.cat_with_playbook)||' of '||k.categories_total||' categories lack a qualification playbook. Generating them sharpens RFQ qualification quality.',
    jsonb_build_array(
      'A playbook''s EXISTENCE is being counted, not its quality. A generated playbook nobody has read counts the same as one refined against real RFQs.',
      'All '||k.categories_total||' categories deserve one. Categories with no demand and no supplier do not need a playbook before they have either.',
      'The intake asks its questions from category_specs, not from these playbooks, so a missing playbook degrades qualification rather than stopping it.'),
    'Each playbook sharpens the questions asked of a buyer in that trade, which is what decides whether a supplier can price the job without a site visit. It is upstream of every quote in the category.',
    'Model spend, once per category, plus review time. Generating all of them unread is the wasteful case the first assumption names.');

  perform kn_task('stale_compliance', (k.compliance_active - k.compliance_fresh) > 0, 'low', 'Stale compliance sources',
    (k.compliance_active - k.compliance_fresh)||' compliance sources have not been re-checked in 45 days.',
    jsonb_build_array(
      'Age is a proxy for risk, and a poor one: a source unchanged for two years may be perfectly current, while one re-checked yesterday can already be superseded.',
      'Re-checking means fetching the page. The authority not having MOVED the document is assumed, and authorities move documents without redirecting.'),
    'A compliance reference is what suppliers and BoQ checklists are held to. Confirming '||(k.compliance_active - k.compliance_fresh)||' stale source(s) keeps quotes defensible; the alternative is discovering a rule changed when a job fails inspection.',
    'No spend. An automated fetch per source, plus review time when one has genuinely changed.');

  perform kn_task('low_accuracy', coalesce(k.flagged_revisions,0) > 0, 'medium', 'Knowledge flagged by validation',
    k.flagged_revisions||' knowledge revisions failed or were flagged by AI validation. Review before they can mislead the agents.',
    jsonb_build_array(
      'The validator is right. It is itself a model, so a flag is a second opinion and not a verdict; correct knowledge is sometimes flagged and wrong knowledge sometimes passes.',
      'Flagged knowledge is not yet in use. If an agent retrieved it before the flag, the damage is already downstream of this task.'),
    'Reviewing '||coalesce(k.flagged_revisions,0)||' revision(s) stops the agents quoting something the validator already doubted. Wrong knowledge does not fail loudly — it produces a confident answer that is wrong.',
    'No spend. Reading time. The expensive direction is dismissing a flag in bulk to clear the queue.');

  perform kn_task('reg_coverage', rc.missing > 0, 'high', 'UAE codes not yet indexed as full documents',
    'Regulatory library is '||rc.coverage_pct||'% complete ('||rc.indexed||'/'||rc.free_codes||' free-published codes fully indexed; '||rc.critical_indexed||'/'||rc.critical_total||' critical). Still missing (critical first): '
    ||coalesce((select string_agg(authority||' — '||code_name, '; ') from (select authority,code_name from reg_catalog where copyright='free' and status<>'indexed' order by priority, authority limit 10) g),'none')
    ||'. Many are portal/viewer-gated or scanned — supply official full PDFs (or a licensed copy) to index them.',
    jsonb_build_array(
      'status=''indexed'' records that a document was INGESTED. It does not establish that an agent can retrieve it, that retrieval returns the right clause, or that the text survived extraction — so this coverage percentage measures ingestion and will be read as knowledge.',
      'reg_catalog is the right denominator: it is a hand-maintained list, so a code nobody has catalogued is not missing here, it is invisible here.',
      'The codes marked critical are the ones that actually decide a quote. That ordering is a judgement recorded in reg_catalog.priority, not a regulatory ranking.',
      'copyright=''free'' means lawfully indexable. Publishing a paid code would be a licensing breach, which is why the recommendation asks for a licensed copy rather than a scrape.'),
    'Indexing the missing '||rc.missing||' code(s) is what lets an agent answer a compliance question from the code itself instead of from a summary. '||rc.critical_indexed||' of '||rc.critical_total||' critical codes are in — the critical remainder is where a wrong answer costs a customer an inspection failure.',
    'The free codes cost nothing but fetching and indexing. Paid or portal-gated codes cost a licence, which is a founder decision — this rule asks for the document rather than assuming a budget.');

  -- NEW: per-agent knowledge staleness → one auto-closing task per lagging agent.
  v_gaps := fn_dispatch_agent_knowledge_gaps();

  for rec in select id::text as rid, title, authority from regulations where approved_at is null loop
    if not exists (select 1 from agent_actions where kind='knowledge_approval' and detail->>'ref'=rec.rid and detail->>'kind'='regulation' and status in ('pending','needs_review')) then
      insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id,assumptions,expected_impact,cost)
      values ('knowledge_curator','knowledge_approval','pending','high',
        'Approve regulation: '||coalesce(rec.title,'#'||rec.rid),
        'A new/updated high-stakes regulation ('||coalesce(rec.authority,'')||') is awaiting your approval before it publishes to the knowledge base.',
        jsonb_build_object('kind','regulation','ref',rec.rid,'authority',rec.authority),'regulations', rec.rid,
        jsonb_build_array(
          'The text was captured faithfully from '||coalesce(rec.authority,'the authority')||'. Nothing between capture and here has verified it against the authority''s own wording.',
          'Approval is a publishing decision, not a legal reading: it puts this text where agents will quote it to suppliers and customers.',
          'It stays unpublished until approved — approved_at null is the gate, so delay is safe and only approval is irreversible in effect.'),
        'Approving publishes this regulation to the knowledge base, where agents will quote it in briefs and compliance checklists. Until then it exists and reaches nobody.',
        'No spend. Founder reading time. The cost of approving something unverified is every quote issued against it afterwards.');
      n_appr := n_appr + 1;
    end if;
  end loop;

  select count(*) into n_task from agent_actions where agent='knowledge_curator' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at',now(),'health',v_health,'kpis',to_jsonb(k),'reg_coverage',to_jsonb(rc),'open_items',n_task,'new_approvals',n_appr,'agent_gaps',v_gaps->'summary');
end $function$


CREATE OR REPLACE FUNCTION public.fn_knowledge_decay()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n_decayed int; n_quarantined int; n_tasks int := 0;
begin
  update agent_knowledge
     set confidence = greatest(0.10, round((confidence - (0.05 * greatest(1, floor(extract(epoch from (now() - review_due))/(30*86400)))))::numeric, 2)),
         validation_status = 'stale'
   where review_due < now()
     and coalesce(validation_status,'') <> 'quarantined'
     and confidence > 0.10;
  get diagnostics n_decayed = row_count;

  update agent_knowledge
     set validation_status = 'quarantined'
   where confidence < 0.35 and coalesce(validation_status,'') <> 'quarantined';
  get diagnostics n_quarantined = row_count;

  -- a quarantined expert is a capability gap, so it becomes work
  insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
  select 'knowledge',
         'Knowledge quarantined: '||agent_key,
         count(*)||' knowledge item(s) for '||agent_key||' fell below the confidence floor and are no longer served. '
         ||'Refresh from source and re-validate, or retire the topic.',
         'proposed','advisory', false, 'knowledge_fill'
    from agent_knowledge
   where validation_status='quarantined'
   group by agent_key
  having not exists (select 1 from org_tasks t where t.title='Knowledge quarantined: '||agent_knowledge.agent_key and t.status<>'done');
  get diagnostics n_tasks = row_count;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('knowledge_decay', now(), now(), 'ok',
          jsonb_build_object('decayed',n_decayed,'quarantined',n_quarantined,'tasks',n_tasks),
          'Knowledge decay: '||n_decayed||' item(s) past review lost confidence, '||n_quarantined
          ||' quarantined below the floor, '||n_tasks||' refresh task(s) opened.');

  return jsonb_build_object('decayed',n_decayed,'quarantined',n_quarantined,'tasks',n_tasks);
end $function$


CREATE OR REPLACE FUNCTION public.fn_knowledge_exam_summary()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with recent as (
    select * from knowledge_exam_results where created_at > now() - interval '30 days'
  ),
  per as (
    select agent_key,
      count(*) as examined,
      count(*) filter (where verdict='correct') as correct,
      count(*) filter (where verdict in ('wrong','partial','not_covered')) as gaps,
      count(*) filter (where filled) as filled,
      max(created_at) as last_exam
    from recent group by agent_key
  )
  select jsonb_build_object(
    'overall', jsonb_build_object(
      'question_bank', (select count(*) from knowledge_exam_questions),
      'exams_30d', (select count(*) from recent),
      'agents_examined', (select count(*) from per),
      'gaps_filled_30d', (select count(*) from recent where filled),
      'avg_score', (select round(100.0*count(*) filter (where verdict='correct')/nullif(count(*),0),1) from recent)
    ),
    'agents', coalesce((select jsonb_agg(jsonb_build_object(
        'agent_key', agent_key, 'examined', examined, 'correct', correct,
        'score_pct', round(100.0*correct/nullif(examined,0),1),
        'gaps', gaps, 'filled', filled, 'last_exam', last_exam
      ) order by round(100.0*correct/nullif(examined,0),1) asc nulls first) from per), '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_knowledge_freshness_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_stale int; v_fresh int;
begin
  update ops_knowledge set source_freshness = 'stale'
   where review_after is not null and review_after < current_date
     and source_freshness <> 'stale';
  get diagnostics v_stale = row_count;
  update ops_knowledge set source_freshness = 'stable'
   where source_freshness = 'stale'
     and (review_after is null or review_after >= current_date);
  get diagnostics v_fresh = row_count;
  return jsonb_build_object('marked_stale', v_stale, 'restored', v_fresh, 'swept_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_knowledge_gap(p_ctx jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  with layers as (
    select k as layer, p_ctx->k as rows
      from unnest(array['company_core','department_knowledge','role_knowledge','category_knowledge']) k
     where jsonb_typeof(p_ctx->k) = 'array'
  ), per as (
    select l.layer,
           jsonb_array_length(l.rows)                                                          as n,
           (select count(*) from jsonb_array_elements(l.rows) e where e->>'match' = 'query')    as matched,
           (select count(*) from jsonb_array_elements(l.rows) e where (e->>'stale')::boolean)   as stale
      from layers l
  )
  select jsonb_build_object(
    'layers', coalesce(jsonb_object_agg(layer, jsonb_build_object('records', n, 'matched_query', matched, 'stale', stale)), '{}'::jsonb),
    'total_records',  coalesce(sum(n),0),
    'total_matched',  coalesce(sum(matched),0),
    'total_stale',    coalesce(sum(stale),0),
    -- The one boolean the runtime acts on.
    'has_gap',        coalesce(sum(matched),0) = 0,
    'gap_layers',     coalesce((select jsonb_agg(layer order by layer) from per where n > 0 and matched = 0), '[]'::jsonb),
    'instruction',    case when coalesce(sum(matched),0) = 0
                        then 'NO retrieved knowledge matched this task. You are working from general departmental material only. Say so explicitly, and request, research or escalate rather than answering as if you had specific guidance.'
                        else null end)
  from per;
$function$


CREATE OR REPLACE FUNCTION public.fn_knowledge_gaps(p_stale_days integer DEFAULT 14, p_thin_min integer DEFAULT 4)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with base as (
    select ca.slug, ca.name, ca.emoji,
      (select count(*) from agent_knowledge k where k.agent_key = ca.slug or k.agent_key = 'cat:'||ca.slug) as items,
      (select max(updated_at) from agent_knowledge k where k.agent_key = ca.slug or k.agent_key = 'cat:'||ca.slug) as last_updated,
      (select min(d.os_key) from os_knowledge_domain d
        where d.domain_key = 'cat:'||ca.slug and d.ownership = 'owns') as owner_os
    from category_agents ca where coalesce(ca.active,true)
  ),
  scored as (
    select slug, name, emoji, items, last_updated, owner_os,
      case when last_updated is null then null else floor(extract(epoch from (now()-last_updated))/86400)::int end as days_stale,
      case when items = 0 then 'missing'
           when last_updated < now() - (p_stale_days||' days')::interval then 'stale'
           when items < p_thin_min then 'thin'
           else 'ok' end as status
    from base
  )
  select jsonb_build_object(
    'thresholds', jsonb_build_object('stale_days', p_stale_days, 'thin_min', p_thin_min),
    'summary', jsonb_build_object(
      'total', (select count(*) from scored),
      'ok', (select count(*) from scored where status='ok'),
      'stale', (select count(*) from scored where status='stale'),
      'thin', (select count(*) from scored where status='thin'),
      'missing', (select count(*) from scored where status='missing'),
      'unowned', (select count(*) from scored where owner_os is null),
      'coverage_pct', round(100.0 * (select count(*) from scored where status='ok') / nullif((select count(*) from scored),0), 1)
    ),
    'agents', coalesce((select jsonb_agg(jsonb_build_object(
        'slug', slug, 'name', name, 'emoji', emoji, 'items', items, 'owner_os', owner_os,
        'last_updated', last_updated, 'days_stale', days_stale, 'status', status
      ) order by case status when 'stale' then 0 when 'thin' then 1 when 'missing' then 2 else 3 end, days_stale desc nulls last, slug)
      from scored), '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_knowledge_provenance_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- OWNER. Only when the writer did not name one.
  if NEW.owner_agent is null and coalesce(NEW.agent_key,'') <> '' then
    NEW.owner_agent := case
      when NEW.agent_key like 'cat:%' then 'learning_dev_mgr'
      when NEW.agent_key = '_global'  then 'docs'
      else NEW.agent_key
    end;
  end if;
  if NEW.owner_agent is null then NEW.owner_agent := NEW.agent_key; end if;

  -- CITATION. Each branch reads a reference the writer itself put in the row; anything else is
  -- left NULL here and handled by the fallback below. A source_ref that says "unknown" is worse
  -- than one that is absent, because the check counts it as present — which is exactly why the
  -- fallback now comes after this block instead of before it.
  if NEW.source_ref is null or btrim(NEW.source_ref) = '' then
    NEW.source_ref := case
      -- assets_ingest: content opens 'From company asset "X" (Dropbox: /path)'
      when NEW.topic like 'Asset text: %'
        then 'dropbox_asset:' || coalesce(substring(NEW.content from 'Dropbox: ([^)]+)'),
                                          substring(NEW.topic   from 'Asset text: (.*)'))
      when NEW.topic = 'Company assets (auto-synced from Dropbox)'
        then 'dropbox_asset:manifest'
      -- fn_experience_promote stamps the org_memory id into the topic as [org#123]
      when NEW.topic ~ '\[org#[0-9]+\]'
        then 'org_memory:' || substring(NEW.topic from '\[org#([0-9]+)\]')
      -- trg_ingest_case_lessons: 'Closed-case lesson (RFQ-45)'
      when NEW.topic like 'Closed-case lesson (RFQ-%'
        then 'rfq_case:' || substring(NEW.topic from 'RFQ-([0-9]+)')
      when NEW.topic like 'exam:%'
        then 'knowledge_exam:' || substring(NEW.topic from 'exam:(.*)')
      else null
    end;
  end if;

  -- LAST RESORT, and only now. Nothing above could name a source, so say so honestly.
  if NEW.source_ref is null or btrim(NEW.source_ref) = '' then
    NEW.source_ref := 'unattributed: no provenance was recorded when this item was written';
  end if;

  -- CONFIDENCE, SCORED OFF THE FINAL source_ref. This ran one line after the placeholder was set,
  -- so it matched nothing and fell to 0.50 on every row that had no writer-supplied reference.
  if NEW.confidence is null then
    NEW.confidence := case
      when NEW.source_ref ~* '^(pack|corpus|import|kb_stage|ops_kb_stage|v2026)' then 0.90
      when NEW.source_ref ~* '^authored'     then 0.85
      when NEW.source_ref ~* '^web_research' then 0.70
      when NEW.source_ref ~* '^(knowledge_exam|org_memory|auto_chat|session|dropbox_asset|rfq_case)' then 0.60
      else 0.50 end;
  end if;

  if NEW.supporting_evidence is null then
    NEW.supporting_evidence := 'Basis: ' || NEW.source_ref
      || ' | layer: ' || coalesce(NEW.layer,'unspecified')
      || ' | owner: ' || coalesce(NEW.owner_agent,'unassigned')
      || ' | validation: ' || coalesce(NEW.validation_status,'unvalidated')
      || case when coalesce(NEW.content,'') ~ 'https?://' then ' | the item itself cites at least one URL'
              else ' | the item cites no external source; treat it as internal know-how, not as an authority' end;
  end if;

  return NEW;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_knowledge_rollback(p_run uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_deleted int := 0;
  v_restored int := 0;
  r record;
begin
  if not exists (select 1 from knowledge_ingestion_run where run_id = p_run) then
    raise exception 'unknown ingestion run %', p_run;
  end if;

  for r in select * from knowledge_ingestion_undo where run_id = p_run and table_name = 'ops_knowledge' loop
    if r.existed then
      -- put the stored row back exactly as it was
      delete from ops_knowledge where record_id = r.key;
      insert into ops_knowledge select * from jsonb_populate_record(null::ops_knowledge, r.prev_row);
      v_restored := v_restored + 1;
    else
      delete from ops_knowledge where record_id = r.key;
      v_deleted := v_deleted + 1;
    end if;
  end loop;

  for r in select * from knowledge_ingestion_undo where run_id = p_run and table_name = 'agent_training_case' loop
    if r.existed then
      delete from agent_training_case where case_id = r.key;
      insert into agent_training_case select * from jsonb_populate_record(null::agent_training_case, r.prev_row);
      v_restored := v_restored + 1;
    else
      delete from agent_training_case where case_id = r.key;
      v_deleted := v_deleted + 1;
    end if;
  end loop;

  update knowledge_ingestion_run set status = 'rolled_back' where run_id = p_run;
  delete from knowledge_ingestion_undo where run_id = p_run;
  return jsonb_build_object('run_id', p_run, 'deleted', v_deleted, 'restored', v_restored);
end $function$


CREATE OR REPLACE FUNCTION public.fn_kpi_review()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_opened int:=0; v_missed int:=0; v_nodata int:=0; v_title text; v_task bigint;
begin
  for r in select * from fn_kpi_scoreboard() loop
    if r.verdict='NO DATA' then v_nodata:=v_nodata+1; continue; end if;
    if r.verdict<>'MISSED' then continue; end if;
    v_missed := v_missed+1;
    v_title := 'KPI missed: '||r.metric||' ('||r.agent_key||')';
    if exists (select 1 from org_tasks where title=v_title and status<>'done') then continue; end if;

    insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
    values (coalesce(r.department,'exec'), v_title,
      'Owner: '||r.agent_key||'. Target '||coalesce(r.target::text,'?')||' '||coalesce(r.unit,'')||
      ', actual '||coalesce(r.actual::text,'?')||' ('||coalesce(r.attainment::text,'?')||'% of target), cadence '||coalesce(r.cadence,'?')||
      '. Serves company goal: '||coalesce(r.serves_goal,'unassigned')||
      '. Diagnose the cause and either close the gap or propose a revised target with evidence.',
      'proposed','advisory', false, 'recommend')
    returning id into v_task;

    perform fn_outcome_open(
      p_actor           => r.agent_key,
      p_decision        => 'Close the gap on: '||r.metric,
      p_subject_type    => 'org_task',
      p_subject_id      => v_task::text,
      p_expected_kpi_id => r.kpi_id,
      p_rationale       => 'KPI missed at '||coalesce(r.attainment::text,'?')||'% of target. Opened automatically by the weekly KPI review.',
      p_direction       => case when r.unit='percent_max' then 'down' else 'up' end,
      p_measure_after   => case when r.cadence='weekly' then interval '14 days' else interval '35 days' end
    );

    v_opened := v_opened+1;
  end loop;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('kpi_review', now(), now(), 'ok',
          jsonb_build_object('missed',v_missed,'opened',v_opened,'no_data',v_nodata),
          'Weekly KPI review: '||v_missed||' missing target, '||v_opened||' task(s) + outcome record(s) opened, '||v_nodata||' with no data.');
  return jsonb_build_object('missed',v_missed,'opened',v_opened,'no_data',v_nodata);
end $function$


CREATE OR REPLACE FUNCTION public.fn_kpi_scoreboard()
 RETURNS TABLE(kpi_id bigint, agent_key text, department text, kpi text, metric text, cadence text, serves_goal text, target numeric, unit text, actual numeric, attainment numeric, verdict text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v numeric; t numeric;
begin
  for r in
    select k.id, k.agent_key, a.department, k.kpi, k.metric, k.cadence,
           k.serves_goal, k.target_value, k.unit, k.measure_sql
    from employee_kpi k
    left join org_agents a on a.agent_key = k.agent_key
    where k.active
    order by a.department nulls last, k.agent_key, k.id
  loop
    v := null;
    begin
      if r.measure_sql is not null then execute r.measure_sql into v; end if;
    exception when others then v := null;
    end;

    t := null;
    begin
      t := r.target_value::numeric;
    exception when others then t := null;
    end;

    kpi_id := r.id; agent_key := r.agent_key; department := r.department;
    kpi := r.kpi; metric := r.metric; cadence := r.cadence;
    serves_goal := r.serves_goal; target := t; unit := r.unit; actual := v;

    if v is null or t is null then
      attainment := null;
    elsif t = 0 then
      -- A ZERO TARGET IS A TARGET (11 Aug 2026). "Zero defects" is the commonest shape a quality
      -- KPI takes - reveal invoices with no payment record, suppliers gone quiet, categories off
      -- the specification, notifications still unsent - and t = 0 short-circuited into
      -- attainment null, which the verdict below then reported as 'NO TARGET'. Four active,
      -- measured KPIs were being told they had no target when zero IS the target, and the four
      -- were exactly the ones about defects.
      attainment := case when v <= 0 then 100.0 else 0.0 end;
    elsif r.unit = 'percent_max' then
      attainment := round(least(100.0, 100.0 * t / nullif(v,0)), 1);
    else
      attainment := round(100.0 * v / t, 1);
    end if;

    verdict := case
      when v is null then 'NO DATA'
      when attainment is null then 'NO TARGET'
      when attainment >= 100 then 'MET'
      when attainment >= 90 then 'NEAR'
      else 'MISSED' end;

    return next;
  end loop;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_kv_block(obj jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k text; v text; out text := ''; begin
  if obj is null then return '  (no data)'; end if;
  for k, v in select key, value from jsonb_each_text(obj) loop
    if v is null or k in ('id','snapshot_date','created_at','captured_at') then continue; end if;
    out := out || '  ' || initcap(replace(k,'_',' ')) || ': ' || v || E'\n';
  end loop;
  if out = '' then out := '  (no data)'; end if;
  return rtrim(out, E'\n');
end $function$


CREATE OR REPLACE FUNCTION public.fn_lead_lifecycle_stage(l leads)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case
    when l.claimed is true
      or l.signed is true
      or l.registration_submitted_at is not null
      or nullif(btrim(coalesce(l.claimed_by, '')), '') is not null
      or nullif(btrim(coalesce(l.approval_status, '')), '') is not null
      or nullif(btrim(coalesce(l.registration_status, '')), '') is not null
      then 'registered'
    when l.portal_updated_at is not null
      or l.accepted_terms_at is not null
      or l.owner_email_verified is true
      then 'responded'
    when lower(btrim(coalesce(l.invite_status, ''))) in ('bounced', 'failed', 'undeliverable', 'invalid', 'rejected')
      then 'undeliverable'
    when (l.invited_at is not null and l.invited_at < now() - interval '14 days')
      or (l.invited_at is null and l.contacted is true and coalesce(l.created_at, now()) < now() - interval '14 days')
      then 'no_response'
    when l.invited_at is not null
      or l.contacted is true
      or nullif(btrim(coalesce(l.invite_status, '')), '') is not null
      then 'contacted'
    else 'not_contacted'
  end
$function$


CREATE OR REPLACE FUNCTION public.fn_lead_role_codes(p_business_role text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case lower(coalesce(nullif(btrim(p_business_role),''), 'supplier'))
           when 'contractor'   then array['contractor']
           when 'manufacturer' then array['manufacturer']
           when 'service'      then array['maintenance']
           when 'retailer'     then array['supplier']
           when 'supplier'     then array['supplier']
           else array['supplier']
         end
$function$


CREATE OR REPLACE FUNCTION public.fn_lead_time_interval(p_text text)
 RETURNS interval
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with t as (select lower(btrim(coalesce(p_text, ''))) s),
  m as (
    select s,
           nullif((regexp_match(s, '(\d+(?:\.\d+)?)'))[1], '')::numeric  as qty,
           -- "working"/"business" days are 5 per week, so N of them span N*7/5 calendar days.
           -- Reading them as calendar days would ask a week early on a two-week job.
           (s ~ 'working|business')                                       as business
      from t
  )
  select case
    when qty is null then null
    when s ~ '\m(hour|hr|hrs|hours)\M'   then make_interval(hours  => ceil(qty)::int)
    when s ~ '\m(day|days)\M'            then make_interval(days   => ceil(qty * case when business then 7.0/5.0 else 1 end)::int)
    when s ~ '\m(week|weeks|wk|wks)\M'   then make_interval(days   => ceil(qty * 7)::int)
    when s ~ '\m(month|months|mo|mos)\M' then make_interval(months => ceil(qty)::int)
    else null                            -- a number with no unit is not a duration
  end
  from m;
$function$


CREATE OR REPLACE FUNCTION public.fn_leads_derive_owner_email_verified()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- Only when an address is newly attached or changed. A later edit of an unrelated column must
  -- not re-run this, and it must never REVOKE a verification an OTP sign-in has already granted.
  if NEW.claimed_by is null then return NEW; end if;
  if TG_OP = 'UPDATE' and NEW.claimed_by is not distinct from OLD.claimed_by then return NEW; end if;
  if coalesce(NEW.owner_email_verified, false) then return NEW; end if;

  if exists (
    select 1 from email_verifications
    where email = lower(NEW.claimed_by)
      and purpose = 'login'
      and used_at is not null
  ) then
    NEW.owner_email_verified := true;
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_leads_exception_invariant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_days   int := public.fn_supplier_exception_days();
  v_now    timestamptz := now();
  v_needs  boolean;
  v_isopen boolean;
begin
  v_needs  := coalesce(new.approval_status, '') = 'action_required';
  v_isopen := new.exception_opened_at is not null and new.exception_closed_at is null;

  if v_needs and not v_isopen then
    -- (a) OPEN IT HERE. supplier_api commits the status first and opens the window afterwards
    -- inside a try/catch that swallows failures; if that RPC never lands, the supplier is stranded
    -- in a state no sweep can see. Opening it in the same statement that sets the status removes
    -- the ordering problem entirely, whatever the caller does.
    new.exception_opened_at        := v_now;
    new.exception_due_at           := v_now + make_interval(days => v_days);
    new.exception_reminders        := 0;
    new.exception_last_reminder_at := null;
    new.exception_closed_at        := null;
    new.exception_outcome          := null;

  elsif v_needs and v_isopen and new.exception_due_at is null then
    -- Open but with no deadline: same invisibility, different route in.
    new.exception_due_at := v_now + make_interval(days => v_days);

  elsif (not v_needs) and v_isopen then
    -- (b)(c) CLOSE IT HERE. An approved or verified supplier must not carry an open window: it is
    -- invisible to every sweep, and it poisons the NEXT demotion with a stale due date.
    new.exception_closed_at := v_now;
    new.exception_outcome   := case
      when coalesce(new.approval_status,'') in ('approved','verified') or new.verified is true then 'resolved'
      when coalesce(new.approval_status,'') = 'rejected' then coalesce(new.exception_outcome, 'closed_rejected')
      else 'closed_status_change' end;
    if new.exception_outcome = 'resolved' then new.licence_gate_reason := null; end if;
  end if;

  -- Backstop. If the branches above ever stop covering a case, fail loudly here rather than
  -- writing a row that no queue can see. A CHECK constraint cannot express this (it depends on
  -- two column groups at once) and would also have blocked the legacy rows this trigger repairs.
  if (coalesce(new.approval_status,'') = 'action_required')
     <> (new.exception_opened_at is not null and new.exception_closed_at is null) then
    raise exception
      'leads %: exception window and approval_status disagree (status=%, open=%). An open window '
      'must mean action_required and nothing else — otherwise the supplier is in a state no sweep '
      'and no view can see.', new.id, new.approval_status,
      (new.exception_opened_at is not null and new.exception_closed_at is null)
      using errcode = 'check_violation';
  end if;

  if coalesce(new.approval_status,'') = 'action_required' and new.exception_due_at is null then
    raise exception 'leads %: action_required with no exception_due_at — both sweep loops skip it.', new.id
      using errcode = 'check_violation';
  end if;

  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_leads_licence_gate_rerun()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare g jsonb; has_doc boolean;
begin
  if tg_op = 'UPDATE'
     and new.license_doc_path  is not distinct from old.license_doc_path
     and new.trade_license_no  is not distinct from old.trade_license_no
     and new.license_expiry    is not distinct from old.license_expiry then
    return new;
  end if;

  has_doc := coalesce(new.license_doc_path, '') <> '';
  g := public.fn_supplier_licence_gate(new.license_doc_path, new.trade_license_no, new.license_expiry);

  if (g ->> 'ok')::boolean then
    if coalesce(new.approval_status,'') = 'action_required' then
      new.approval_status     := 'approved';
      new.licence_gate_reason := null;
      -- WITHOUT THESE TWO LINES THIS PROMOTION IS COSMETIC: fn_is_matchable reads `verified`, so an
      -- approval that does not set it produces a supplier no matching path can ever return.
      new.verified            := true;
      new.verification_status := 'verified';
    elsif coalesce(new.approval_status,'') = 'rejected'
          and coalesce(new.exception_outcome,'') = 'expired_auto_rejected' then
      new.approval_status     := 'approved';
      new.licence_gate_reason := null;
      new.exception_outcome   := 'recovered_after_auto_reject';
      new.verified            := true;
      new.verification_status := 'verified';
    end if;
  elsif has_doc then
    -- Evidence exists and fails. THIS is the case worth acting on.
    if coalesce(new.approval_status,'') in ('approved','verified') then
      new.approval_status     := 'action_required';
      new.licence_gate_reason := g ->> 'reason';
      -- The evidence that earned the flag has failed, so the flag goes with it. Leaving it set
      -- keeps a trust badge on the customer's quote card for a supplier whose licence we cannot read.
      new.verified            := false;
      new.verification_status := 'unverified';
    elsif coalesce(new.approval_status,'') = 'action_required' then
      new.licence_gate_reason := g ->> 'reason';
    end if;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_leads_retrade(p_limit integer DEFAULT 2000, p_after bigint DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_n int; v_left bigint; v_hi bigint; v_max bigint;
begin
  -- The window: the next p_limit ids at or above p_after, chosen WITHOUT calling the normaliser.
  select max(id) into v_hi from (
    select id from public.leads where id > coalesce(p_after,0)
     order by id limit greatest(coalesce(p_limit, 2000), 1)) w;
  select max(id) into v_max from public.leads;

  if v_hi is null then
    -- past the end: nothing left to walk
    return jsonb_build_object('renormalised', 0, 'next_after', null, 'done', true,
      'in_taxonomy_vocab', (select count(*) from public.leads
                             where invite_trades && (select array_agg(code) from public.taxonomy_trade)));
  end if;

  update public.leads l
     set invite_trades = public.fn_norm_trades(
           coalesce(l.company_name,'')||' '||coalesce(l.categories,'')||' '||
           coalesce(l.sector,'')||' '||coalesce(l.services,'')||' '||coalesce(l.products,''))
   where l.id > coalesce(p_after,0) and l.id <= v_hi
     and not (coalesce(l.company_name,'') ilike 'ZZ DEMO%' or coalesce(l.email,'') ilike '%@example.invalid')
     and l.invite_trades is distinct from public.fn_norm_trades(
           coalesce(l.company_name,'')||' '||coalesce(l.categories,'')||' '||
           coalesce(l.sector,'')||' '||coalesce(l.services,'')||' '||coalesce(l.products,''));
  get diagnostics v_n = row_count;

  -- Progress is an array overlap, never a second run of the normaliser. See the header.
  select count(*) into v_left from public.leads l
   where l.invite_trades is not null and array_length(l.invite_trades,1) > 0
     and not (l.invite_trades && (select array_agg(code) from public.taxonomy_trade));

  return jsonb_build_object(
    'renormalised', v_n,
    'next_after', v_hi,
    'done', v_hi >= coalesce(v_max, v_hi),
    'still_wrong_vocabulary', v_left,
    'in_taxonomy_vocab', (select count(*) from public.leads
                           where invite_trades && (select array_agg(code) from public.taxonomy_trade)));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_leads_retrade_stale(p_limit integer DEFAULT 3000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_n int;
begin
  with vocab as (select array_agg(code) c from public.taxonomy_trade where active),
  pick as (
    select l.id from public.leads l, vocab v
     where not (coalesce(l.company_name,'') ilike 'ZZ DEMO%' or coalesce(l.email,'') ilike '%@example.invalid')
       and (l.invite_trades is null
            or array_length(l.invite_trades,1) is null
            or not (l.invite_trades && v.c))
     order by l.id
     limit greatest(coalesce(p_limit, 3000), 1))
  update public.leads l
     set invite_trades = public.fn_norm_trades(
           coalesce(l.company_name,'')||' '||coalesce(l.categories,'')||' '||
           coalesce(l.sector,'')||' '||coalesce(l.services,'')||' '||coalesce(l.products,''))
    from pick
   where l.id = pick.id
     and l.invite_trades is distinct from public.fn_norm_trades(
           coalesce(l.company_name,'')||' '||coalesce(l.categories,'')||' '||
           coalesce(l.sector,'')||' '||coalesce(l.services,'')||' '||coalesce(l.products,''));
  get diagnostics v_n = row_count;
  return jsonb_build_object('renormalised', v_n,
    'in_taxonomy_vocab', (select count(*) from public.leads
                           where invite_trades && (select array_agg(code) from public.taxonomy_trade)));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_learning_loop_sweep(p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record; n_rev int := 0; n_les int := 0; n_err int := 0; v_lid bigint;
begin
  -- LEG A. Bounded to the seven days the requirement is scored over: reviewing a deliverable from
  -- June tells nobody anything and would put a backlog onto the event bus in one burst.
  for r in
    select o.id
      from org_tasks o
     where o.status = 'done'
       and coalesce(o.result->>'deliverable','') <> ''
       and o.updated_at > now() - interval '7 days'
       and not exists (select 1 from review_chain c
                        where c.subject_type = 'org_task' and c.subject_id = o.id::text)
     order by o.updated_at
     limit greatest(coalesce(p_limit, 25), 0)
  loop
    begin
      perform fn_task_review(r.id);
      n_rev := n_rev + 1;
    exception when others then
      -- One unreviewable task must not stop the sweep; it is counted, not swallowed.
      n_err := n_err + 1;
    end;
  end loop;

  -- LEG B. Sees leg A's own inserts (same transaction), so a review written above whose inline
  -- lesson threw is retried here rather than lost.
  --
  -- The population is the rows fn_review_submit/fn_task_review write — stage published, cos_review
  -- or dept_review.  stage='approval' is deliberately NOT in it: those rows are fn_task_approve
  -- routing a task ONTO an approval path before it is worked (it sets status='assigned'), not a
  -- verdict on completed work, and demanding a lesson for a task nobody has done yet is a
  -- requirement no future work could satisfy.
  for r in
    select s.sid,
           case when exists (select 1 from review_chain p
                              where p.subject_type = 'org_task' and p.subject_id = s.sid
                                and p.stage = 'published' and p.decision = 'approve')
                then 'published'
                else coalesce((select d.decision from review_chain d
                                where d.subject_type = 'org_task' and d.subject_id = s.sid
                                  and d.stage in ('cos_review','dept_review') and d.decision is not null
                                order by d.created_at desc, d.id desc limit 1), 'hold') end as outcome,
           coalesce((select jsonb_agg(jsonb_build_object(
                              'by', ch.reviewer_agent, 'stance', ch.decision,
                              'reasoning', left(coalesce(ch.reason,''), 300)))
                       from review_chain ch
                      where ch.subject_type = 'org_task' and ch.subject_id = s.sid
                        and ch.stage = 'challenge'), '[]'::jsonb) as dissents,
           coalesce((select rr.reviewer_agent from review_chain rr
                      where rr.subject_type = 'org_task' and rr.subject_id = s.sid
                        and rr.stage in ('cos_review','dept_review') and rr.reviewer_agent is not null
                      order by rr.created_at desc, rr.id desc limit 1), 'the department head') as reviewer
      from (select distinct c.subject_id as sid
              from review_chain c
             where c.subject_type = 'org_task'
               and c.stage in ('published','cos_review','dept_review')
               and c.created_at > now() - interval '7 days'
               and exists (select 1 from org_tasks o where o.id::text = c.subject_id)
               and not exists (select 1 from institutional_memory m
                                where m.subject_type = 'org_task' and m.subject_id = c.subject_id
                                  and m.evidence_ref = 'review_chain:org_task:' || m.subject_id)
             limit greatest(coalesce(p_limit, 25), 0)) s
  loop
    begin
      v_lid := fn_task_lesson(r.sid::bigint, r.outcome,
                 jsonb_build_object('violations', '[]'::jsonb,
                                    'dissents',   r.dissents,
                                    'reviewer',   r.reviewer));
      if v_lid is not null then n_les := n_les + 1; end if;
    exception when others then
      n_err := n_err + 1;
    end;
  end loop;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('learning_loop_sweep', now(), now(), case when n_err > 0 then 'partial' else 'ok' end,
          jsonb_build_object('reviews_run', n_rev, 'lessons_written', n_les, 'failed', n_err),
    'Learning-loop backstop: ' || n_rev || ' completed deliverable(s) that no path had reviewed '
    || 'entered the review chain, ' || n_les || ' review(s) whose lesson never landed had it '
    || 'written from the reviewer''s own verdict, ' || n_err || ' could not be processed.');

  return jsonb_build_object('reviews_run', n_rev, 'lessons_written', n_les, 'failed', n_err);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_legal_ai()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k record; v_health numeric; v_terms numeric; v_fresh numeric; n int; v_missing text; v_regchg int;
begin
  select * into k from legal_kpis;
  -- refresh checklist presence
  update legal_checklist lc set present = exists(select 1 from legal_documents d where d.slug = lc.match_slug);

  v_terms := round((coalesce(k.customer_terms_acceptance_pct,0)+coalesce(k.supplier_terms_acceptance_pct,0))/2,1);
  v_fresh := case when k.policies_published=0 then 0 else round(100.0*(k.policies_published-k.policies_stale)/k.policies_published,1) end;
  v_health := round(coalesce(k.coverage_pct,0)*0.35 + v_terms*0.30 + v_fresh*0.20 + greatest(0,100-coalesce(k.open_legal_flags,0)*10)*0.15,1);

  insert into legal_kpi_snapshots(snapshot_date,kpis) values (current_date, to_jsonb(k)||jsonb_build_object('legal_health',v_health,'terms_acceptance_avg',v_terms))
    on conflict (snapshot_date) do update set kpis=excluded.kpis, created_at=now();

  select string_agg(requirement,'; ') into v_missing from legal_checklist where not present and priority=1;
  select count(*) into v_regchg from compliance_sources where last_changed_at >= now()-interval '30 days';

  -- ESCALATIONS (founder-visible legal_flag; never legal advice)
  perform leg_flag('missing_core_docs', coalesce(k.critical_missing,0)>0, 'high', 'Core legal documents missing',
    'The platform is operating without these core documents: '||coalesce(v_missing,'')||'. They govern your contractual relationship with customers and suppliers (liability, governing law, dispute resolution). Have a licensed UAE lawyer prepare and approve them, then publish as versioned legal documents.');
  perform leg_flag('supplier_terms_acceptance', coalesce(k.suppliers_approved,0)>0 and coalesce(k.supplier_terms_acceptance_pct,0) < 90, 'high', 'Suppliers have not accepted current terms',
    'Only '||coalesce(k.supplier_terms_acceptance_pct,0)||'% of approved suppliers have accepted the current terms. Enforce terms acceptance (click-wrap / signed) at onboarding so agreements are enforceable.');
  perform leg_flag('customer_terms_acceptance', coalesce(k.customer_terms_acceptance_pct,0) < 90, 'medium', 'Customers have not accepted current terms',
    'Only '||coalesce(k.customer_terms_acceptance_pct,0)||'% of customers have accepted the current terms. Gate key actions (posting an inquiry / paying to reveal) behind explicit terms acceptance.');
  perform leg_flag('stale_policies', coalesce(k.policies_stale,0)>0, 'low', 'Policies due for annual review',
    k.policies_stale||' published policy(ies) have not been reviewed in over a year. Schedule an annual legal review.');
  perform leg_flag('reg_change_review', v_regchg>0, 'medium', 'Regulatory change may affect your terms/policies',
    v_regchg||' monitored authority source(s) changed in the last 30 days. Review whether your terms, privacy or compliance policies need updating with a lawyer.');

  select count(*) into n from agent_actions where agent='legal_ai' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at',now(),'legal_health',v_health,'kpis',to_jsonb(k),'open_flags',n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_lint_outbound(p_hours integer DEFAULT 24)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'hits', count(*),
    'sample', coalesce(jsonb_agg(jsonb_build_object('when',a.created_at,'rule',p.name,'reply',left(a.reply,160))) filter (where p.id is not null), '[]'::jsonb)
  )
  from assistant_logs a
  left join policy_rules p on p.active and a.reply ~* p.forbid_regex
  where a.created_at > now() - make_interval(hours => p_hours)
    and p.id is not null;
$function$


CREATE OR REPLACE FUNCTION public.fn_llm_cache_get(p_key text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v text;
begin
  update llm_cache set hits = hits + 1, last_hit_at = now()
  where cache_key = p_key and expires_at > now()
  returning response into v;
  return v;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_llm_cache_lookup(p_key text, p_embedding vector DEFAULT NULL::vector, p_task_class text DEFAULT NULL::text, p_min_similarity numeric DEFAULT 0.95)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_sim numeric;
begin
  -- 1. exact
  select * into r from llm_cache
   where cache_key = p_key and (expires_at is null or expires_at > now()) limit 1;
  if found then
    update llm_cache set hits = hits + 1, last_hit_at = now() where cache_key = r.cache_key;
    return jsonb_build_object('hit', true, 'kind', 'exact', 'response', r.response,
                              'model', r.model_used, 'similarity', 1.0);
  end if;

  -- 2. semantic. Deliberately scoped to the same task_class: a research answer must
  -- never be served to a classification prompt just because they read alike.
  if p_embedding is not null then
    select c.*, 1 - (c.embedding_gte <=> p_embedding) as sim into r
      from llm_cache c
     where c.embedding_gte is not null
       and (c.expires_at is null or c.expires_at > now())
       and (p_task_class is null or c.task_class is not distinct from p_task_class)
     order by c.embedding_gte <=> p_embedding
     limit 1;
    if found then
      v_sim := round((r.sim)::numeric, 4);
      if v_sim >= p_min_similarity then
        update llm_cache set hits = hits + 1, last_hit_at = now() where cache_key = r.cache_key;
        return jsonb_build_object('hit', true, 'kind', 'semantic', 'response', r.response,
                                  'model', r.model_used, 'similarity', v_sim);
      end if;
    end if;
  end if;

  return jsonb_build_object('hit', false);
end $function$


CREATE OR REPLACE FUNCTION public.fn_llm_cache_put(p_key text, p_fn text, p_task_class text, p_model text, p_response text, p_ttl_minutes integer DEFAULT 1440)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into llm_cache (cache_key, fn, task_class, model_used, response, expires_at)
  values (p_key, p_fn, p_task_class, p_model, p_response, now() + make_interval(mins => greatest(p_ttl_minutes,1)))
  on conflict (cache_key) do update set response = excluded.response, model_used = excluded.model_used,
    expires_at = excluded.expires_at, created_at = now();
$function$


CREATE OR REPLACE FUNCTION public.fn_llm_cache_store(p_key text, p_fn text, p_task_class text, p_model text, p_response text, p_ttl_minutes integer, p_embedding vector DEFAULT NULL::vector, p_saved_usd numeric DEFAULT 0)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  insert into llm_cache (cache_key, fn, task_class, model_used, response, prompt_hash,
                         expires_at, embedding_gte, saved_usd)
  values (p_key, p_fn, p_task_class, p_model, p_response, p_key,
          now() + make_interval(mins => greatest(coalesce(p_ttl_minutes,60),1)), p_embedding, coalesce(p_saved_usd,0))
  on conflict (cache_key) do update set response = excluded.response, model_used = excluded.model_used,
    expires_at = excluded.expires_at, embedding_gte = coalesce(excluded.embedding_gte, llm_cache.embedding_gte);
$function$


CREATE OR REPLACE FUNCTION public.fn_llm_drift_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v jsonb := '[]'::jsonb; v_off int; v_fb numeric; v_fail int; v_owner text; v_recent int;
begin
  select count(*) into v_recent from llm_calls where created_at > now() - interval '24 hours';
  if v_recent = 0 then
    return jsonb_build_object('checked_at', now(), 'calls_24h', 0, 'findings', 0,
                              'note','no llm traffic in 24h - nothing to judge');
  end if;

  -- 1. any model not on the approved list
  select count(*) into v_off from v_llm_offpolicy;
  if v_off > 0 then
    v := v || jsonb_build_object('issue','off_policy_model','severity','high',
         'detail',(select jsonb_agg(jsonb_build_object('fn',fn,'model',model,'calls',calls)) from v_llm_offpolicy));
  end if;

  -- 2. fallback rate: Opus answering when Sonnet was asked means Sonnet is failing
  select round(100.0 * count(*) filter (where fell_back) / nullif(count(*),0), 1)
    into v_fb from llm_calls where created_at > now() - interval '24 hours';
  if coalesce(v_fb,0) > 20 then
    v := v || jsonb_build_object('issue','high_fallback_rate','severity','high','pct',v_fb,
         'detail','the primary model is failing often - you are paying fallback prices silently');
  end if;

  -- 3. outright failures
  select count(*) into v_fail from llm_calls
   where created_at > now() - interval '24 hours' and not ok;
  if v_fail > 5 then
    v := v || jsonb_build_object('issue','llm_failures','severity','medium','count',v_fail);
  end if;

  if jsonb_array_length(v) > 0 then
    v_owner := split_part(coalesce((select value from app_secrets where key='admin_emails'),
                                   'management@quotesdone.com'), ',', 1);
    -- once per 24h only, so a standing problem does not spam (lesson from the smoke check)
    if not exists (select 1 from founder_alerts
                    where event='llm_drift' and created_at > now() - interval '24 hours') then
      insert into founder_alerts(level,event,detail,channel)
        values ('warn','llm_drift','Model policy drift: '||v::text, 'system');
      insert into notifications(type,to_email,to_role,channel,subject,body,status)
        values ('llm_drift', v_owner, 'admin', 'email', 'QuotesDone: AI model drift detected',
                'The model-policy watch found issues in the last 24h:'||chr(10)||chr(10)||
                jsonb_pretty(v)||chr(10)||chr(10)||
                'Check the AI Observability view (v_llm_model_mix / v_llm_offpolicy).', 'queued');
    end if;
  end if;

  return jsonb_build_object('checked_at', now(), 'calls_24h', v_recent,
                            'findings', jsonb_array_length(v), 'detail', v);
end $function$


CREATE OR REPLACE FUNCTION public.fn_llm_log(p_fn text, p_dept text, p_agent text, p_task_class text, p_model text, p_because text, p_tier text, p_prompt_tokens integer, p_output_tokens integer, p_cached boolean, p_cache_key text, p_latency_ms integer, p_ok boolean, p_confidence numeric DEFAULT NULL::numeric, p_cached_in integer DEFAULT 0, p_cache_write integer DEFAULT 0)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_cost numeric := 0; v_in numeric; v_out numeric; v_cr numeric; v_cw numeric;
        v_cheaper boolean := false; v_reason text; v_alt text; v_class text;
        v_plain int; v_read int; v_write int;
        -- Added 11 Aug 2026 for the could_be_cheaper rewrite below.
        v_alt_model text; v_alt_rate numeric; v_used_rate numeric;
begin
  v_class := coalesce(nullif(trim(coalesce(p_task_class,'')), ''), case
    when p_fn ~* 'agent_brain|dept_plan|exec_agents|reflect|conductor'   then 'agent_reasoning'
    when p_fn ~* 'cos_execute|secretary|chief'                            then 'chief_of_staff_decision'
    when p_fn ~* 'knowledge|kb_|canon_eval|research|exam'                 then 'knowledge_research'
    when p_fn ~* 'extract|parse|ocr'                                      then 'document_extraction'
    when p_fn ~* 'classif|categor|intent|route'                           then 'category_classification'
    when p_fn ~* 'draft|content|blog|marketing|social'                    then 'content_drafting'
    when p_fn ~* 'quote|rfq|supplier|procure'                             then 'procurement_reasoning'
    else 'general_drafting' end);

  v_read  := greatest(coalesce(p_cached_in,0), 0);
  v_write := greatest(coalesce(p_cache_write,0), 0);
  v_plain := greatest(coalesce(p_prompt_tokens,0) - v_read - v_write, 0);

  if not coalesce(p_cached,false) then
    select in_aed_per_mtok, out_aed_per_mtok, cache_read_aed_per_mtok, cache_write_aed_per_mtok
      into v_in, v_out, v_cr, v_cw
      from model_rate where model = p_model;
    if v_in is not null then
      v_cost := round( v_plain/1000000.0 * v_in
                     + v_read /1000000.0 * coalesce(v_cr, v_in * 0.10)
                     + v_write/1000000.0 * coalesce(v_cw, v_in * 1.25)
                     + coalesce(p_output_tokens,0)/1000000.0 * v_out, 6);
    end if;
  end if;

  select deterministic_alternative into v_alt from model_policy where task_class = v_class;
  if v_alt is not null and v_alt <> '' then
    v_cheaper := true; v_reason := 'A deterministic path exists for this task class: ' || v_alt;
  -- THE WASTE DETECTOR NEVER LOOKED AT THE MODEL DOING THE SPENDING (fixed 11 Aug 2026).
  --
  -- The comparator was hardcoded to claude-sonnet-5 as the CHEAP side of the test:
  --     exists (... alt.model = 'anthropic/claude-sonnet-5'
  --              where used.model = p_model and alt.in_aed_per_mtok < used.in_aed_per_mtok)
  -- so it could only ever fire for a model more expensive than sonnet-5, and by the input-rate
  -- ladder in model_rate that is exactly one model:
  --     flash-lite 0.92 < qwen 1.18 < haiku 3.67 < gemini-flash 5.51 < SONNET-5 7.35 < opus 18.36
  -- That was a reasonable rule when sonnet-5 was the cheap tier. It is not one now.
  --
  -- Measured over the 7 days to 11 Aug: could_be_cheaper fired on 179 calls - 175 of them on
  -- gemini-3.1-flash-lite (the CHEAPEST model in the fleet, 1.1% of spend, flagged by the
  -- deterministic branch above), 4 on opus, and ZERO on claude-sonnet-5 across 622 calls carrying
  -- 84% of all spend. The one field built to find waste was structurally blind to it.
  --
  -- Now it asks the actual question - is there a materially cheaper model than the one used - and
  -- names the cheapest so the reason is actionable rather than a boolean. The 2x threshold is
  -- deliberate: qwen at 1.18 against flash-lite at 0.92 is a 1.3x difference and flagging it would
  -- be noise, while sonnet-5 against flash-lite is 8x and is the finding.
  elsif not coalesce(p_cached,false) then
    select mr.model, mr.in_aed_per_mtok into v_alt_model, v_alt_rate
      from model_rate mr
     where mr.in_aed_per_mtok is not null
     order by mr.in_aed_per_mtok asc
     limit 1;
    select mr.in_aed_per_mtok into v_used_rate from model_rate mr where mr.model = p_model;
    if v_alt_model is not null and v_used_rate is not null
       and v_alt_rate * 2 <= v_used_rate then
      v_cheaper := true;
      v_reason := v_alt_model || ' costs ' || round(v_used_rate / nullif(v_alt_rate,0), 1)
               || 'x less on input than ' || p_model
               || ' (' || v_alt_rate || ' vs ' || v_used_rate || ' AED/Mtok). '
               || 'Whether it is good enough for this task class is a policy decision, not a fact - '
               || 'this flag is the question, not the answer.';
    end if;
  end if;

  insert into ai_cost_log (fn, dept_key, agent_key, task_class, model_used, model_selected_because,
    tier, prompt_tokens, output_tokens, cached, cache_hit_key, latency_ms, cost_aed,
    could_be_cheaper, cheaper_reason, ok, confidence, cached_in_tokens, cache_write_tokens)
  values (p_fn, p_dept, p_agent, v_class, p_model, p_because, p_tier,
    coalesce(p_prompt_tokens,0), coalesce(p_output_tokens,0), coalesce(p_cached,false),
    p_cache_key, p_latency_ms, v_cost, v_cheaper, v_reason, coalesce(p_ok,true),
    case when p_confidence is null then null
         when p_confidence >= 0 and p_confidence <= 1   then p_confidence
         when p_confidence > 1  and p_confidence <= 100 then round(p_confidence / 100.0, 4)
         else null end,
    v_read, v_write);

  return v_cost;
end $function$


CREATE OR REPLACE FUNCTION public.fn_llm_preflight(p_model text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when p_model is null or p_model in ('none','none/deterministic')
      then jsonb_build_object('allowed', true, 'reason', 'deterministic path, no provider call')
    when not exists (select 1 from model_registry r where r.model_id = p_model and r.active)
      then jsonb_build_object('allowed', false, 'class_key', 'route_not_registered',
             'reason', 'model ' || p_model || ' is not an active row in model_registry')
    when exists (select 1 from llm_route_health h
                 where h.model_id = p_model and h.open_until is not null and h.open_until > now())
      then jsonb_build_object('allowed', false, 'class_key', 'route_open',
             'reason', 'circuit open until '
                       || (select h.open_until from llm_route_health h where h.model_id = p_model)
                       || ' after ' || (select h.consecutive_failures from llm_route_health h where h.model_id = p_model)
                       || ' consecutive failures (' || coalesce((select h.opened_class from llm_route_health h where h.model_id = p_model),'?') || ')',
             'open_until', (select h.open_until from llm_route_health h where h.model_id = p_model))
    else jsonb_build_object('allowed', true, 'reason', 'registered, breaker closed')
  end;
$function$


CREATE OR REPLACE FUNCTION public.fn_llm_retry_allowed(p_class_key text, p_attempt_no integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select c.retryable and p_attempt_no <= c.max_retries
       from llm_failure_class c where c.class_key = p_class_key),
    false);   -- unknown class is NOT retryable: an unnamed failure never earns another attempt
$function$


CREATE OR REPLACE FUNCTION public.fn_management_decision_review(p_department text DEFAULT NULL::text, p_days integer DEFAULT 7, p_limit integer DEFAULT 100)
 RETURNS TABLE(trace_id uuid, decided_at timestamp with time zone, agent_key text, role_id text, department_id text, manager_id text, decision_type text, proposed_action text, confidence numeric, escalation_decision text, tools_requested text[], tools_executed text[], knowledge_count integer, evidence_count integer, review_date date, outcome_status text, final_status text, sealed boolean, gap text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with t as (
    select *,
           case when jsonb_typeof(knowledge_refs)='array' then jsonb_array_length(knowledge_refs) else 0 end as kn,
           case when jsonb_typeof(evidence_refs) ='array' then jsonb_array_length(evidence_refs)  else 0 end as ev
      from decision_trace
     where (p_department is null or department_id = p_department)
       and created_at > now() - make_interval(days => greatest(p_days,1))
  )
  select t.id, t.created_at, t.agent_key, t.role_id, t.department_id, t.manager_id,
         t.decision_type, t.proposed_action, t.confidence, t.escalation_decision,
         t.tools_requested, t.tools_executed, t.kn, t.ev,
         t.review_date, t.outcome_status, t.final_status, t.sealed_at is not null,
         nullif(concat_ws('; ',
           case when t.role_id is null            then 'no canonical role' end,
           case when t.ev = 0                     then 'no evidence' end,
           case when t.confidence is null         then 'no confidence' end,
           case when t.escalation_decision is null then 'no authority decision' end,
           case when t.review_date is null        then 'no review date' end,
           case when t.final_status is null       then 'no output status' end), '')
  from t order by t.created_at desc limit greatest(p_limit,1);
$function$


CREATE OR REPLACE FUNCTION public.fn_marketing_ai()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k record; v_plan jsonb; v_health numeric; n_rec int; push jsonb; contentgaps jsonb; topcats text;
  s_cadence numeric; s_reach numeric; s_funnel numeric; s_pipeline numeric; v_meta_idle boolean; v_meta_has boolean;
  v_meta_n int; v_mkt_ai_budget numeric;
begin
  select * into k from marketing_kpis;
  select count(*) into v_meta_n from meta_insights where campaign_name ilike '%quotesdone%';
  v_meta_has := v_meta_n > 0;
  v_meta_idle := v_meta_has and (coalesce(k.meta_active_campaigns,0)=0 or coalesce(k.meta_spend_30d,0)=0);
  select monthly_aed into v_mkt_ai_budget from department_budget where dept_key='marketing';

  select coalesce(jsonb_agg(jsonb_build_object('category',category,'inquiries_90d',inquiries_90d,'suppliers',suppliers) order by inquiries_90d desc, suppliers asc),'[]'::jsonb)
    into push from (select * from marketing_category_demand where inquiries_90d>0 and suppliers=0 order by inquiries_90d desc, suppliers asc limit 8) t;
  select coalesce(jsonb_agg(jsonb_build_object('category',category,'has_seo',has_seo_page,'has_blog',has_blog) order by inquiries_90d desc),'[]'::jsonb)
    into contentgaps from (select * from marketing_category_demand where (not has_seo_page or not has_blog) order by inquiries_90d desc limit 8) t;
  select string_agg(category,', ') into topcats from (select category from marketing_category_demand where inquiries_90d>0 and suppliers=0 order by inquiries_90d desc limit 5) t;

  v_plan := jsonb_build_object(
    'as_of', now(),
    'push_supply', push,
    'content_gaps', contentgaps,
    'cadence', jsonb_build_object('blog_published',k.blog_published,'drafts_pending',k.drafts_pending,'social_staged',k.social_staged),
    'funnel', jsonb_build_object('inq_to_quote_pct',k.inq_to_quote_pct,'quote_to_reveal_pct',k.quote_to_reveal_pct,'revenue_30d',k.revenue_30d),
    'meta', jsonb_build_object('spend_30d',k.meta_spend_30d,'clicks_30d',k.meta_clicks_30d,'results_30d',k.meta_results_30d,'active_campaigns',k.meta_active_campaigns,'cpl',k.meta_cpl,'roi',k.meta_roi,'idle',v_meta_idle),
    'priorities', (
      select coalesce(jsonb_agg(p),'[]'::jsonb) from (
        select 'Launch & fund your paused QuotesDone Meta campaign to generate leads' as p where v_meta_idle
        union all select 'Onboard suppliers in: '||coalesce(topcats,'—') where k.supply_gaps>0
        union all select 'Review & publish '||k.drafts_pending||' pending content drafts' where k.drafts_pending>0
        union all select 'Stage social posts for this week' where coalesce(k.social_staged,0)=0
        union all select 'Generate SEO pages for '||k.seo_gaps||' uncovered categories' where k.seo_gaps>0
      ) x
    )
  );

  s_cadence := least(100, (case when k.blog_published>0 then 50 else 0 end) + (case when k.social_staged>0 then 30 else 0 end) + (case when k.drafts_pending between 1 and 10 then 20 when k.drafts_pending=0 then 10 else 5 end));
  s_reach := least(100, coalesce(k.seo_generated,0)*3);
  s_funnel := coalesce(k.quote_to_reveal_pct, 40);
  s_pipeline := least(100, (case when k.leads_total>1000 then 60 else k.leads_total/20.0 end) + least(40, k.outreach_sent));
  v_health := round(s_cadence*0.30 + s_reach*0.25 + s_funnel*0.25 + s_pipeline*0.20,1);

  insert into marketing_snapshots(snapshot_date, kpis, plan)
  values (current_date, to_jsonb(k) || jsonb_build_object('health',v_health), v_plan)
  on conflict (snapshot_date) do update set kpis=excluded.kpis, plan=excluded.plan, created_at=now();

  perform mkt_rec('supply_gap', coalesce(k.supply_gaps,0)>0, 'medium', 'Demand without supply',
    coalesce(k.supply_gaps,0)||' categor'||(case when k.supply_gaps=1 then 'y has' else 'ies have' end)||' customer demand but no approved suppliers'||(case when topcats is not null then ' ('||topcats||')' else '' end)||'. Prioritise supplier onboarding / BD there.',
    jsonb_build_array(
      '"No approved suppliers" counts APPROVED ones. A supplier who registered and is waiting in the approval queue, or one approved whose capability enrichment never ran, is invisible to this count and to the matcher alike — so this can be an onboarding backlog wearing the costume of a market gap.',
      'The demand is real demand. inquiries_90d counts RFQs raised, including any the same buyer raised more than once.',
      'The category label on an RFQ matches the one suppliers are indexed under. Two vocabularies drifting apart produces this alert with supply sitting behind it.'),
    'These are the categories where a buyer asked and nobody could answer'||(case when topcats is not null then ' ('||topcats||')' else '' end)||'. Onboarding there converts demand that already exists, which is cheaper than creating new demand.',
    'No spend to invite from the 20,470 existing leads. Cost is founder attention and the invite ramp, gated on invite_enabled.');

  perform mkt_rec('drafts_backlog', coalesce(k.drafts_pending,0)>10, 'low', 'Content drafts awaiting review',
    k.drafts_pending||' content drafts are pending your review. Approve or publish to grow organic reach.',
    jsonb_build_array(
      'The drafts are worth publishing. They were generated, not commissioned, so a backlog can mean the generator is productive rather than that there is value waiting.',
      'Ten is a chosen threshold. Nothing degrades at eleven.',
      'Pending means unread. A draft deliberately parked as not-good-enough sits here identically to one nobody has opened.'),
    'Published content is the only demand channel here that costs no media money. '||k.drafts_pending||' drafts reviewed is '||k.drafts_pending||' more chances to be found by a buyer searching for a trade.',
    'No spend — generation already happened and its model cost is sunk. Review is founder time; publishing something wrong costs reputation.');

  perform mkt_rec('no_social', coalesce(k.social_staged,0)=0, 'low', 'No social posts queued',
    'No social posts are staged. Queue this week''s posts to keep the channels active.',
    jsonb_build_array(
      'Staged posts are a proxy for activity, and only a proxy: this counts what is queued in the platform, so posting directly to a channel by hand leaves this at zero.',
      'The channels are worth keeping active for a marketplace with one confirmed supplier and no customers yet — cadence for its own sake is a cost, not a strategy.'),
    'Modest and indirect. Keeping a channel warm matters when demand starts arriving; it does not create demand on its own.',
    'No spend. Staging time. The honest ceiling is that at this stage supply onboarding is worth more than posting cadence, and this rule cannot weigh the two.');

  perform mkt_rec('seo_gap', coalesce(k.seo_gaps,0)>0, 'low', 'SEO coverage gaps',
    k.seo_gaps||' categories lack an SEO page. Generate them to capture search demand.',
    jsonb_build_array(
      'A page existing is being counted, not a page ranking. Generating '||coalesce(k.seo_gaps,0)||' pages moves this counter to zero whether or not a single one is ever found in search.',
      'There is search demand in these categories to capture. Nothing in this rule reads a search volume — it reads which categories have a page.',
      'A generated page is good enough to rank. Thin pages across many categories can do a domain more harm than a few strong ones.'),
    'SEO is the compounding demand channel: a page that ranks keeps working with no further spend. The realistic impact is months away, not this week.',
    'Model spend per page, one-off. The real risk is publishing '||coalesce(k.seo_gaps,0)||' thin pages at once to clear a counter.');

  perform mkt_rec('meta_idle', v_meta_idle, 'medium', 'Meta ad campaign idle',
    'Your QuotesDone Meta campaign is paused / not spending. Launch and fund it to start generating leads — the platform will track spend, results, CPL and ROI automatically once a Meta access token is added.',
    jsonb_build_array(
      'Zero spend and zero active campaigns means the campaign is PAUSED. It reads exactly the same when no Meta access token is configured and the platform simply cannot see a campaign that is running — the recommendation''s own last sentence admits the token may be missing.',
      'The '||v_meta_n||' campaign(s) matched by name are QuotesDone''s; the match is `campaign_name ilike ''%quotesdone%''`.',
      'Paid acquisition is the right channel to restart. With one confirmed supplier, leads arriving faster than supply can serve them is a worse outcome than no leads.'),
    'Paid media is the fastest demand lever available, and the only one on this board that works in days rather than months. It is also the only one that needs money.',
    'Real money, and the amount is the founder''s to set — no agent can fund it. The escalation raised alongside this asks for exactly that figure.');

  -- The decision behind the idle campaign, which no agent can take: how much money goes behind it.
  -- Filed as a finance kind so fn_governance_stamp's sensitive-domain rule escalates it to the
  -- founder. Dedupes on its own signal while open, so it is raised once, not once a day.
  if v_meta_idle and not exists (
        select 1 from agent_actions
         where detail->>'signal' = 'marketing_budget_idle'
           and status in ('pending','needs_review')) then
    insert into agent_actions (agent, kind, status, risk, title, recommendation, detail,
                               target_table, target_id, assumptions, expected_impact, cost)
    values ('marketing_ai', 'finance_marketing_budget', 'pending', 'medium',
      'Set a marketing media budget, or keep the Meta campaign off',
      v_meta_n||' QuotesDone Meta campaign(s) exist and none is running: AED '
      ||coalesce(k.meta_spend_30d,0)||' media spend, '||coalesce(k.meta_active_campaigns,0)
      ||' active campaign(s) and '||coalesce(k.meta_clicks_30d,0)||' clicks in 30 days. '
      ||'No marketing media budget is configured, so no agent can fund this — the amount is yours '
      ||'to set. For scale: marketing''s AED '||coalesce(v_mkt_ai_budget,0)||'/month department '
      ||'budget is AI model spend, is '
      ||coalesce(round(100.0*(select spent_aed from department_budget where dept_key='marketing')
                       /nullif(v_mkt_ai_budget,0),1),0)||'% used, and does not cover media. '
      ||'Decide a monthly media budget, or keep the channel off and let SEO and content carry demand.',
      jsonb_build_object('signal','marketing_budget_idle',
                         'meta_campaigns', v_meta_n,
                         'meta_spend_30d', coalesce(k.meta_spend_30d,0),
                         'meta_active_campaigns', coalesce(k.meta_active_campaigns,0),
                         'marketing_ai_budget_aed', coalesce(v_mkt_ai_budget,0)),
      'marketing', 'marketing_budget_idle',
      jsonb_build_array(
        'The reported AED '||coalesce(k.meta_spend_30d,0)||' spend and '||coalesce(k.meta_active_campaigns,0)||' active campaign(s) are the truth. Without a Meta access token the platform sees nothing and reports zero, which is indistinguishable from a campaign that is genuinely off.',
        'Spending on ads is worth doing at all right now. There is one confirmed supplier: leads arriving faster than supply can serve them damages the platform more than an empty channel does.',
        'Keeping the channel off is a legitimate answer, not a deferral — the recommendation offers it as an equal option deliberately.'),
      'This is the decision, not the alert: a figure here turns paid acquisition on, and no figure keeps it off. Either answer closes it; only silence leaves the company without a demand plan.',
      'Real money, monthly, at whatever level you set — the department''s AED '||coalesce(v_mkt_ai_budget,0)||'/month is AI model spend and does not cover media. No agent can spend it, which is why this is escalated rather than executed.');
  end if;

  select count(*) into n_rec from agent_actions where agent='marketing_ai' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at',now(),'health',v_health,'kpis',to_jsonb(k),'plan',v_plan,'open_recommendations',n_rec);
end $function$


CREATE OR REPLACE FUNCTION public.fn_marketing_blog_publish(p_id uuid, p_published boolean, p_by text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare r public.blog_posts%rowtype;
begin
  update public.blog_posts set published = p_published,
    published_at = case when p_published and published_at is null then now() else published_at end,
    updated_at = now()
  where id = p_id returning * into r;
  if r.id is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  begin insert into public.os_audit_log(actor, action, entity, entity_id, detail)
    values (coalesce(nullif(btrim(p_by),''),'operator'), case when p_published then 'blog_publish' else 'blog_unpublish' end, 'blog_posts', p_id::text, jsonb_build_object('title', r.title));
  exception when others then null; end;
  return jsonb_build_object('ok', true, 'published', r.published);
end $function$


CREATE OR REPLACE FUNCTION public.fn_marketing_library_search(p_query text, p_limit integer DEFAULT 5)
 RETURNS TABLE(id bigint, category text, title text, content text, rank real)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare q_or tsquery; words text[];
begin
  words := array(
    select w from unnest(
      regexp_split_to_array(lower(regexp_replace(coalesce(p_query,''),'[^a-z0-9 ]',' ','g')), '\s+')
    ) w where length(w) > 2);
  if array_length(words,1) is null then return; end if;
  begin
    q_or := to_tsquery('english', array_to_string(words, ' | '));
  exception when others then return; end;
  return query
    select l.id, l.category, l.title, l.content, ts_rank(l.tsv, q_or) as rank
    from public.marketing_library l
    where l.tsv @@ q_or
    order by ts_rank(l.tsv, q_or) desc, l.id
    limit greatest(1, least(coalesce(p_limit,5), 20));
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_marketing_studio()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', (select to_jsonb(k) from marketing_kpis k limit 1),
    'trend', coalesce((select jsonb_agg(jsonb_build_object(
        'd', to_char(s.snapshot_date,'Mon DD'),
        'leads', nullif(s.kpis->>'leads_total','')::numeric,
        'blog', nullif(s.kpis->>'blog_published','')::numeric,
        'social', nullif(s.kpis->>'social_published','')::numeric,
        'seo', nullif(s.kpis->>'seo_pages','')::numeric
      ) order by s.snapshot_date) from marketing_snapshots s),'[]'::jsonb),
    'social', coalesce((select jsonb_agg(jsonb_build_object(
        'id', p.id, 'image_url', p.image_url,
        'text', coalesce(p.content->>'all', p.content->>'text', left(p.content::text,400)),
        'channels', to_jsonb(p.channels), 'status', p.status, 'mode', p.mode, 'error', p.error, 'created_at', p.created_at
      ) order by p.created_at desc) from social_posts p),'[]'::jsonb),
    'blog', coalesce((select jsonb_agg(jsonb_build_object(
        'id', b.id, 'title', b.title, 'slug', b.slug, 'category', b.category, 'excerpt', b.excerpt,
        'published', b.published, 'published_at', b.published_at, 'body_html', left(b.body_html, 24000)
      ) order by b.updated_at desc) from blog_posts b),'[]'::jsonb),
    'review', (select coalesce(fn_review_pending(),'[]'::jsonb))
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_marketplace_analytics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare res jsonb;
begin
  with q_first as (  -- first quote latency per rfq
    select i.id, min(qq.created_at) as first_quote_at, i.created_at, i.category
    from inquiries i left join quotes qq on qq.inquiry_id = i.id group by i.id, i.created_at, i.category
  ),
  spread as (  -- savings potential per rfq with >=2 quotes
    select inquiry_id, min(quote_amount) lo, max(quote_amount) hi, count(*) n
    from quotes where quote_amount > 0 group by inquiry_id having count(*) >= 2
  )
  select jsonb_build_object(
    'rfqs_today',   (select count(*) from inquiries where created_at >= date_trunc('day', now())),
    'rfqs_7d',      (select count(*) from inquiries where created_at >= now() - interval '7 days'),
    'rfqs_30d',     (select count(*) from inquiries where created_at >= now() - interval '30 days'),
    'avg_first_quote_hours', (select round(avg(extract(epoch from (first_quote_at - created_at))/3600.0)::numeric,1) from q_first where first_quote_at is not null),
    'response_rate_pct', (
      select case when count(*)>0 then round(100.0 * count(*) filter (where exists (
        select 1 from quotes q where q.inquiry_id = m.inquiry_id and q.supplier_id = m.supplier_id)) / count(*), 1) else null end
      from inquiry_matches m),
    'avg_savings_pct', (select round(avg(case when hi>0 then 100.0*(hi-lo)/hi else 0 end)::numeric,1) from spread),
    'abandoned_rfqs', (select count(*) from inquiries i where i.created_at < now() - interval '7 days'
                        and coalesce(i.status,'') not in ('completed','cancelled')
                        and not exists (select 1 from quotes q where q.inquiry_id = i.id)),
    'active_suppliers_30d', (select count(distinct supplier_id) from quotes where created_at >= now() - interval '30 days'),
    'supplier_capacity_avg', (select round(avg(c)::numeric,1) from (select supplier_id, count(*) c from quotes where created_at >= now() - interval '30 days' group by supplier_id) s),
    'competitive_categories', (
      select coalesce(jsonb_agg(x order by x.avg_quotes desc), '[]'::jsonb) from (
        select i.category, round(avg(qc.c)::numeric,2) as avg_quotes, count(*) as rfqs
        from inquiries i join (select inquiry_id, count(*) c from quotes group by inquiry_id) qc on qc.inquiry_id=i.id
        where i.created_at >= now() - interval '90 days' and i.category is not null
        group by i.category order by avg_quotes desc limit 8) x),
    'category_growth', (
      select coalesce(jsonb_agg(g), '[]'::jsonb) from (
        select category,
          count(*) filter (where created_at >= now() - interval '30 days') as this_30d,
          count(*) filter (where created_at >= now() - interval '60 days' and created_at < now() - interval '30 days') as prev_30d
        from inquiries where category is not null and created_at >= now() - interval '60 days'
        group by category order by this_30d desc limit 10) g),
    'generated_at', now()
  ) into res;
  return res;
end $function$


CREATE OR REPLACE FUNCTION public.fn_match_capability(p_trades text[], p_need text DEFAULT 'executes'::text, p_products text[] DEFAULT '{}'::text[], p_brands text[] DEFAULT '{}'::text[], p_project_type text DEFAULT NULL::text, p_value numeric DEFAULT NULL::numeric, p_emirate text DEFAULT NULL::text, p_limit integer DEFAULT 12)
 RETURNS TABLE(supplier_id bigint, company_name text, score numeric, trades text[], roles text[], product_hits integer, brand_hit boolean, ptype_hit boolean, track numeric, why text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
with w as (
  select coalesce((select value::text::numeric from decision_policy where key='score_w_product'),40)      as w_prod,
         coalesce((select value::text::numeric from decision_policy where key='score_w_brand'),20)        as w_brand,
         coalesce((select value::text::numeric from decision_policy where key='score_w_project_type'),15) as w_ptype,
         coalesce((select value::text::numeric from decision_policy where key='score_w_track_record'),15) as w_track,
         coalesce((select value::text::numeric from decision_policy where key='score_w_size_fit'),10)     as w_size
),
req_auth as (
  select coalesce(array_agg(distinct a),'{}') as codes
  from public.taxonomy_trade t, unnest(t.authority_required) a
  where t.code = any(p_trades)
),
cand as (
  select sc.supplier_id, sc.trades, sc.roles, sc.products_norm, sc.brands, sc.project_types,
         sc.min_project_value, sc.max_project_value, sc.coverage_emirates,
         l.company_name, l.emirate as lead_emirate,
         least(1, greatest(0, coalesce(sp.quote_rate, sp.perf_score, 0))) as track
  from public.supplier_capabilities sc
  join public.leads l on l.id = sc.supplier_id
  left join public.supplier_perf sp on sp.supplier_id = sc.supplier_id
  where sc.confirmed_at is not null                        -- GATE: supplier confirmed their own scope
    and sc.trades && p_trades                              -- GATE: trade intersection
    and not (sc.excluded_trades && p_trades)               -- GATE: declared negative scope
    and public.fn_is_matchable(l.verified, l.banned, l.matching_blocked,
                               l.approval_status, l.permanently_closed, l.chat_strikes)
    and exists (                                            -- GATE: role can actually do this kind of work
      select 1 from public.taxonomy_role r
      where r.code = any(sc.roles)
        and case p_need when 'supplies'    then r.supplies
                        when 'whole_scope' then r.whole_scope
                        else r.executes end
    )
    and not exists (                                        -- GATE: every mandatory authority held
      select 1 from unnest((select codes from req_auth)) a
      where not (sc.authority_approvals ? a)
    )
    and (p_value is null or (                               -- GATE: job size inside their range
          (sc.min_project_value is null or p_value >= sc.min_project_value)
      and (sc.max_project_value is null or p_value <= sc.max_project_value)))
    and (p_emirate is null or                               -- GATE: they cover the emirate asked for
         coalesce(cardinality(sc.coverage_emirates), 0) = 0
      or exists (select 1 from unnest(sc.coverage_emirates) ce where ce ilike p_emirate)
      or l.emirate ilike p_emirate)
),
scored as (
  select c.*,
    (select count(distinct pq) from unnest(p_products) pq
      where exists (select 1 from unnest(c.products_norm) pp
                    where pp ilike '%'||pq||'%' or pq ilike '%'||pp||'%'))::int as product_hits,
    (cardinality(p_brands) > 0 and exists (
       select 1 from unnest(p_brands) bq join unnest(c.brands) bb on bb ilike '%'||bq||'%' or bq ilike '%'||bb||'%'
     )) as brand_hit,
    (p_project_type is not null and exists (
       select 1 from unnest(c.project_types) pt
       where pt ilike '%'||p_project_type||'%' or p_project_type ilike '%'||pt||'%'
     )) as ptype_hit,
    (p_value is not null and c.min_project_value is not null and c.max_project_value is not null) as size_known
  from cand c
)
select s.supplier_id, s.company_name,
  round(
      w.w_prod  * (case when cardinality(p_products) > 0
                        then s.product_hits::numeric / cardinality(p_products) else 0 end)
    + w.w_brand * (case when s.brand_hit then 1 else 0 end)
    + w.w_ptype * (case when s.ptype_hit then 1 else 0 end)
    + w.w_track * s.track
    + w.w_size  * (case when s.size_known then 1 else 0.5 end)
  , 1) as score,
  s.trades, s.roles, s.product_hits, s.brand_hit, s.ptype_hit, round(s.track,3) as track,
  concat_ws(' · ',
    'trades ' || array_to_string(array(select unnest(s.trades) intersect select unnest(p_trades)), '+'),
    case when s.product_hits > 0 then s.product_hits||'/'||cardinality(p_products)||' products' end,
    case when s.brand_hit then 'brand match' end,
    case when s.ptype_hit then 'project type' end,
    case when p_emirate is not null then
      case when coalesce(cardinality(s.coverage_emirates),0) = 0 then 'coverage not stated'
           else 'covers ' || p_emirate end end
  ) as why
from scored s, w
order by score desc, s.track desc, s.supplier_id
limit greatest(1, p_limit);
$function$


CREATE OR REPLACE FUNCTION public.fn_matching_strike_limit()
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce((select value::text::int from public.decision_policy where key='matching_strike_limit'), 3);
$function$


CREATE OR REPLACE FUNCTION public.fn_memory_search(p_q text, p_kinds text[] DEFAULT NULL::text[], p_lim integer DEFAULT 20)
 RETURNS TABLE(kind text, ref text, snippet text, ts timestamp with time zone, score real)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with qy as (select plainto_tsquery('english', coalesce(p_q,'')) q)
  select s.kind, s.ref, s.snippet, s.ts, s.score from (
    select 'rfq'::text kind, i.id::text ref, left(coalesce(i.summary, i.raw_input, i.spec::text),220) snippet,
           i.created_at ts, ts_rank(to_tsvector('english', coalesce(i.summary,'')||' '||coalesce(i.raw_input,'')||' '||coalesce(i.spec::text,'')||' '||coalesce(i.category,'')), qy.q) score
    from inquiries i, qy where (p_kinds is null or 'rfq'=any(p_kinds))
      and to_tsvector('english', coalesce(i.summary,'')||' '||coalesce(i.raw_input,'')||' '||coalesce(i.spec::text,'')||' '||coalesce(i.category,'')) @@ qy.q
    union all
    select 'quote', q.id::text, left(coalesce(q.scope, q.notes),220), q.created_at,
           ts_rank(to_tsvector('english', coalesce(q.scope,'')||' '||coalesce(q.notes,'')||' '||coalesce(q.conditions,'')), qy.q)
    from quotes q, qy where (p_kinds is null or 'quote'=any(p_kinds))
      and to_tsvector('english', coalesce(q.scope,'')||' '||coalesce(q.notes,'')||' '||coalesce(q.conditions,'')) @@ qy.q
    union all
    select 'supplier', l.id::text, left(coalesce(l.company_name,'')||' — '||coalesce(l.capability_summary, l.description, l.services),220), l.created_at,
           ts_rank(to_tsvector('english', coalesce(l.company_name,'')||' '||coalesce(l.capability_summary,'')||' '||coalesce(l.services,'')||' '||coalesce(l.description,'')||' '||coalesce(l.categories,'')), qy.q)
    from leads l, qy where (p_kinds is null or 'supplier'=any(p_kinds))
      and to_tsvector('english', coalesce(l.company_name,'')||' '||coalesce(l.capability_summary,'')||' '||coalesce(l.services,'')||' '||coalesce(l.description,'')||' '||coalesce(l.categories,'')) @@ qy.q
    union all
    select 'customer', c.id::text, left(coalesce(c.full_name,'')||' '||coalesce(c.email,''),220), c.created_at,
           ts_rank(to_tsvector('english', coalesce(c.full_name,'')||' '||coalesce(c.email,'')), qy.q)
    from customers c, qy where (p_kinds is null or 'customer'=any(p_kinds))
      and to_tsvector('english', coalesce(c.full_name,'')||' '||coalesce(c.email,'')) @@ qy.q
    union all
    select 'case', a.rfq_id, left(coalesce(a.ai_summary->>'summary',''),220), a.created_at,
           ts_rank(to_tsvector('english', coalesce(a.ai_summary->>'summary','')||' '||coalesce(a.category,'')), qy.q)
    from rfq_archives a, qy where (p_kinds is null or 'case'=any(p_kinds))
      and to_tsvector('english', coalesce(a.ai_summary->>'summary','')||' '||coalesce(a.category,'')) @@ qy.q
    union all
    select 'knowledge', k.agent_key||' :: '||k.topic, left(k.content,220), k.created_at,
           ts_rank(to_tsvector('english', coalesce(k.topic,'')||' '||coalesce(k.content,'')), qy.q)
    from agent_knowledge k, qy where (p_kinds is null or 'knowledge'=any(p_kinds))
      and to_tsvector('english', coalesce(k.topic,'')||' '||coalesce(k.content,'')) @@ qy.q
    union all
    select 'decision', dl.id::text, left(dl.kind||' -> '||coalesce(dl.decision,'')||' '||coalesce(dl.reasons::text,''),220), dl.created_at,
           ts_rank(to_tsvector('english', coalesce(dl.kind,'')||' '||coalesce(dl.decision,'')||' '||coalesce(dl.reasons::text,'')), qy.q)
    from decision_log dl, qy where (p_kinds is null or 'decision'=any(p_kinds))
      and to_tsvector('english', coalesce(dl.kind,'')||' '||coalesce(dl.decision,'')||' '||coalesce(dl.reasons::text,'')) @@ qy.q
  ) s
  order by s.score desc, s.ts desc
  limit greatest(1, coalesce(p_lim,20));
$function$


CREATE OR REPLACE FUNCTION public.fn_mep_full_scope(p_text_norm text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_re text; v_sep text := '[^[:alnum:].;,،؛' || chr(10) || ']+';
begin
  for r in select pattern_norm, lang from public.mep_trade_pattern where kind = 'mep_full_phrase' loop
    if public.fn_term_matches(p_text_norm, r.pattern_norm, r.lang) then
      return jsonb_build_object('matched', true, 'basis', 'explicit_full_mep_phrase',
                                'anchor', r.pattern_norm, 'modifier', null, 'modifier_kind', null);
    end if;
  end loop;

  for r in
    select a.pattern_norm as anchor, m.pattern_norm as modifier, m.kind as modifier_kind, a.lang
      from public.mep_trade_pattern a
      join public.mep_trade_pattern m on m.kind in ('scope_full','scope_container')
     where a.kind = 'mep_anchor'
  loop
    v_re := '(^|[^[:alnum:]])' || r.anchor || '(' || v_sep || '[[:alnum:]]+){0,2}' || v_sep
            || r.modifier || '($|[^[:alnum:]])';
    if p_text_norm ~ v_re then
      return jsonb_build_object('matched', true, 'basis', 'anchor_plus_modifier',
                                'anchor', r.anchor, 'modifier', r.modifier,
                                'modifier_kind', r.modifier_kind);
    end if;
    v_re := '(^|[^[:alnum:]])' || r.modifier || '(' || v_sep || '[[:alnum:]]+){0,2}' || v_sep
            || r.anchor || '($|[^[:alnum:]])';
    if p_text_norm ~ v_re then
      return jsonb_build_object('matched', true, 'basis', 'modifier_plus_anchor',
                                'anchor', r.anchor, 'modifier', r.modifier,
                                'modifier_kind', r.modifier_kind);
    end if;
  end loop;

  return jsonb_build_object('matched', false, 'basis', null);
end $function$


CREATE OR REPLACE FUNCTION public.fn_metric_class(p_label text, p_metric text DEFAULT NULL::text, p_unit text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  with t as (select lower(coalesce(p_label,'')||' '||coalesce(p_metric,'')||' '||coalesce(p_unit,'')) s)
  select case
    when (select s from t) ~ '(revenue|turnover|gmv|gross merchandise|dirhams earned|recognised|reveal fee|collections?\b|collected)'
      then 'revenue'
    when (select s from t) ~ '(cost|spend|opex|budget|aed per|per call|price paid|burn|bill)'
      then 'cost'
    when (select s from t) ~ '(risk|fraud|breach|incident|violation|exposure|bad debt|chargeback|refund|penalt|non.?complian|complian|unsafe|leak)'
      then 'risk'
    when (select s from t) ~ '(conversion|convert|win rate|close rate|reach a paid|paid reveal|quote.to|acceptance rate|took up|activation rate)'
      then 'conversion'
    when (select s from t) ~ '(accuracy|quality|pass rate|defect|error rate|bounce|first time|satisfaction|rating|csat|nps|completeness|uptime|availabilit|latency|response time|sla|on.?time|rework)'
      then 'quality_metric'
    when (select s from t) ~ '(pipeline|lead|inquir|enquir|invit|sign.?up|registration|registered|coverage|reach|traffic|visitors|response rate|activation|adoption|retention)'
      then 'leading_indicator'
    -- Count-shaped language only. 'sends' and 'messages' were here in the first draft and pulled
    -- "share of sends that hard bounce" — a quality rate — into 'activity'. A classifier that
    -- mislabels a quality metric as busywork is worse than one that says it cannot tell.
    when (select s from t) ~ '(count|number of|volume|tasks|runs|processed|published|reviewed|completed|closed|throughput|per day|per week)'
      then 'activity'
    else 'unclassified' end;
$function$


CREATE OR REPLACE FUNCTION public.fn_model_autoswitch()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_new text; v_n int := 0;
begin
  for r in
    select o.task_class, o.model_used,
           avg(case when o.ok then 1.0 else 0.0 end) sr, count(*) n
    from ai_cost_log o
    where o.occurred_at > now() - interval '14 days'
      and o.task_class is not null
      and o.model_used is not null
      -- ONLY CALLS THAT REACHED THE MODEL MAY JUDGE IT (14 Aug 2026). A row with no prompt
      -- tokens and no output tokens never got there: it is our own client/gateway abort and
      -- belongs to latency, not to model selection. Sixteen such rows scored
      -- chief_of_staff_decision at 75.4%% and bought opus-4.8 at ~2.3x — a slower model, to
      -- answer a timeout. See scripts/sql/the_autoswitch_repriced_our_own_timeouts.sql.
      and (coalesce(o.prompt_tokens,0) > 0 or coalesce(o.output_tokens,0) > 0)
      -- ONLY CALLS THAT REACHED THE MODEL MAY JUDGE IT (14 Aug 2026). A row with no prompt
      -- tokens and no output tokens never got there: it is our own client/gateway abort and
      -- belongs to latency, not to model selection. Sixteen such rows scored
      -- chief_of_staff_decision at 75.4%% and bought opus-4.8 at ~2.3x — a slower model, to
      -- answer a timeout. See scripts/sql/the_autoswitch_repriced_our_own_timeouts.sql.
      and (coalesce(o.prompt_tokens,0) > 0 or coalesce(o.output_tokens,0) > 0)
    group by 1,2 having count(*) >= 20
       and avg(case when o.ok then 1.0 else 0.0 end) < 0.85
  loop
    -- only act if this model is still the primary for that class
    if not exists (select 1 from model_policy p where p.task_class = r.task_class
                    and p.model_primary = r.model_used and p.active) then continue; end if;

    select mr.model_id into v_new from model_registry mr
     join model_registry cur on cur.model_id = r.model_used
     where mr.active and mr.approved and mr.in_per_mtok_usd > cur.in_per_mtok_usd
     order by mr.in_per_mtok_usd asc limit 1;
    if v_new is null then continue; end if;

    update model_policy set model_primary = v_new where task_class = r.task_class and active;
    v_n := v_n + 1;

    insert into founder_alerts (level, event, detail, channel)
    values ('warn','model_autoswitched',
      'Task class "' || r.task_class || '" was failing on ' || r.model_used || ' (' ||
      round(r.sr*100,1) || '% success over ' || r.n || ' runs, floor 85%). Promoted to ' || v_new ||
      '. Cheaper is only correct while it works; this is the loop that checks.', 'system');

    insert into org_tasks (dept_key, title, detail, status, tier, action_class, needs_founder)
    values ('it', left('Model auto-switched for ' || r.task_class, 200),
      'Automatic promotion after measured failure. Class: ' || r.task_class ||
      E'\nWas: ' || r.model_used || ' at ' || round(r.sr*100,1) || '% success over ' || r.n || ' runs' ||
      E'\nNow: ' || v_new ||
      E'\n\nReview whether the prompt is at fault rather than the model - a badly specified task fails on every tier, and promoting it just costs more.',
      'proposed','supervised','analysis', false);
  end loop;
  return v_n;
end $function$


CREATE OR REPLACE FUNCTION public.fn_model_benchmark()
 RETURNS TABLE(task_class text, model_used text, runs bigint, success_rate numeric, avg_cost_usd numeric, verdict text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  return query
  with s as (
    select o.task_class, o.model_used,
           count(*) as runs,
           round(avg(case when o.ok then 1.0 else 0.0 end), 4) as success_rate,
           round((avg(o.cost_aed) / 3.6725)::numeric, 6) as avg_cost_usd
    from ai_cost_log o
    where o.occurred_at > now() - interval '30 days'
      and o.task_class is not null
      and o.model_used is not null
    group by 1, 2
    having count(*) >= 20   -- never judge a model on a handful of runs
  )
  select s.task_class, s.model_used, s.runs, s.success_rate, s.avg_cost_usd,
         case
           when s.success_rate >= 0.95 then 'GOOD - safe to keep or promote for this class'
           when s.success_rate >= 0.85 then 'ACCEPTABLE - watch'
           else 'POOR - this class needs a stronger tier'
         end
  from s order by s.task_class, s.success_rate desc;

  -- Feed the score back onto the registry so routing can see it. This is the only writer of
  -- model_registry.quality_score, which is why that column was null on all six models.
  update model_registry r set quality_score = q.sr, updated_at = now()
  from (
    select o.model_used, round(avg(case when o.ok then 1.0 else 0.0 end),4) sr
    from ai_cost_log o
    where o.occurred_at > now() - interval '30 days'
      and o.task_class is not null and o.model_used is not null
    group by 1 having count(*) >= 20
  ) q
  where r.model_id = q.model_used;
end $function$


CREATE OR REPLACE FUNCTION public.fn_model_catalog_drift()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_cat int; v_not_served int; v_policy_off int; v_names text[]; v_pol text[];
begin
  select count(*) into v_cat from public.model_catalog;

  select count(*), coalesce(array_agg(c.model_id order by c.model_id), '{}')
    into v_not_served, v_names
    from public.model_catalog c
   where c.model_id <> 'none/deterministic'
     and not exists (select 1 from public.model_registry r where r.model_id = c.model_id and r.active);

  select count(*), coalesce(array_agg(distinct p.task_class), '{}')
    into v_policy_off, v_pol
    from public.model_policy p
   where p.active and coalesce(p.tier,'') <> 'none'
     and p.model_primary is not null
     and not exists (select 1 from public.model_registry r where r.model_id = p.model_primary and r.active);

  if v_policy_off > 0 then
    insert into public.agent_actions(agent, kind, title, recommendation, detail, risk, status)
    values ('it', 'ai_improvement',
            format('%s active model policies name a model production does not serve', v_policy_off),
            'Either add the model to model_registry or repoint the policy at a served model. Until then fn_ai_route substitutes by tier and price, and the policy is decorative.',
            jsonb_build_object('task_classes', to_jsonb(v_pol),
                               'catalog_models_not_served', to_jsonb(v_names),
                               'source', 'fn_model_catalog_drift'),
            'low', 'pending');
  end if;

  return jsonb_build_object('catalog_models', v_cat,
                            'catalog_models_not_served', v_not_served,
                            'catalog_models_not_served_list', to_jsonb(v_names),
                            'active_policies_on_unserved_models', v_policy_off,
                            'affected_task_classes', to_jsonb(v_pol),
                            'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_model_cost_usd(p_model text, p_in_tokens integer, p_out_tokens integer, p_cached_in_tokens integer DEFAULT 0)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select round(
      ( (greatest(coalesce(p_in_tokens,0) - coalesce(p_cached_in_tokens,0), 0)::numeric / 1000000) * r.in_per_mtok_usd
      + (coalesce(p_cached_in_tokens,0)::numeric / 1000000) * coalesce(r.cache_read_per_mtok_usd, r.in_per_mtok_usd)
      + (coalesce(p_out_tokens,0)::numeric / 1000000) * r.out_per_mtok_usd
      )::numeric, 6)
  from model_registry r where r.model_id = p_model;
$function$


CREATE OR REPLACE FUNCTION public.fn_monthly_report()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ select public.fn_period_report('monthly'); $function$


CREATE OR REPLACE FUNCTION public.fn_negotiation_guidance(p_customer uuid, p_quote uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_amount numeric; v_cat text; v_supplier bigint; v_supplier_name text; v_inquiry uuid;
  v_stats jsonb; v_policy jsonb; v_scope text; v_band text; v_rule jsonb;
  v_median numeric; v_n int; v_ask numeric; v_max_ask numeric; v_floor_pct numeric;
  v_target numeric; v_delta numeric; v_action text; v_msg text; v_msg_ar text; v_headline text;
begin
  select q.quote_amount, q.supplier_id, i.category, i.id
    into v_amount, v_supplier, v_cat, v_inquiry
    from quotes q join inquiries i on i.id = q.inquiry_id
   where q.id = p_quote and i.customer_id = p_customer;

  -- Ownership is the first gate, not a filter added later: a quote on someone else's RFQ is not a
  -- quote this caller may benchmark.
  if v_inquiry is null then
    return jsonb_build_object('error', 'not_your_quote', 'quote_id', p_quote);
  end if;

  select l.company_name into v_supplier_name from leads l where l.id = v_supplier;

  v_stats := fn_price_confidence(v_cat, v_amount);
  v_band  := coalesce(v_stats ->> 'band', 'insufficient_data');
  v_median := nullif(v_stats ->> 'median', '')::numeric;
  v_n      := coalesce(nullif(v_stats ->> 'n', '')::int, 0);

  -- Per-supplier override first, house policy second. Neither is invented here: if the table is
  -- empty the routine says so instead of falling back to a hard-coded percentage.
  select p.policy, p.scope into v_policy, v_scope from supplier_negotiation_policy p
   where p.supplier_id = v_supplier limit 1;
  if v_policy is null then
    select p.policy, p.scope into v_policy, v_scope from supplier_negotiation_policy p
     where p.scope = 'default' limit 1;
  end if;
  if v_policy is null then
    return jsonb_build_object(
      'quote_id', p_quote, 'inquiry_id', v_inquiry, 'category', v_cat,
      'quote_amount', v_amount, 'supplier_id', v_supplier, 'supplier_name', v_supplier_name,
      'market', v_stats, 'policy_scope', null,
      'recommended_action', 'no_policy', 'target_price', null, 'ask_discount_pct', null,
      'headline', 'No negotiation policy is configured yet.',
      'suggested_message', null, 'suggested_message_ar', null,
      'empty_reason', 'supplier_negotiation_policy holds no rule for this supplier and no default rule, so no target price is proposed.');
  end if;

  if v_n < coalesce((v_policy ->> 'min_sample')::int, 4) then v_band := 'insufficient_data'; end if;
  v_rule      := coalesce(v_policy -> 'bands' -> v_band, v_policy -> 'bands' -> 'insufficient_data');
  v_action    := coalesce(v_rule ->> 'action', 'no_benchmark_yet');
  v_ask       := coalesce((v_rule ->> 'ask_discount_pct')::numeric, 0);
  v_max_ask   := coalesce((v_rule ->> 'max_ask_discount_pct')::numeric, 0);
  v_floor_pct := coalesce((v_policy ->> 'never_target_below_pct_of_median')::numeric, 80);
  v_ask       := least(v_ask, v_max_ask);

  if v_band = 'insufficient_data' or v_median is null or v_ask <= 0 then
    -- No benchmark, or a band the policy says not to push on. Both get an honest message.
    v_target := null;
    v_delta  := case when v_median is not null and v_median > 0
                     then round(100 * (v_amount - v_median) / v_median, 1) end;
    v_headline := case
      when v_band = 'insufficient_data' then
        format('No market benchmark yet — only %s comparable quote(s) recorded in %s, and this house policy needs %s before it will quote a market price.',
               v_n, coalesce(v_cat, 'this category'), coalesce(v_policy ->> 'min_sample', '4'))
      when v_band = 'suspiciously_low' then
        format('This quote is well below the market median of AED %s. Confirm the scope before pushing the price.', v_median)
      else format('This quote sits inside the market range; the house policy does not push on it.') end;
    v_msg := case
      when v_band = 'suspiciously_low' then
        format('Hello%s,%s%sThank you for the quotation on %s. Before we proceed I would like to confirm the scope: could you set out exactly what is included, what is excluded, the delivery lead time and the warranty terms? Your price is materially below the other submissions we hold and I want to be sure we are comparing the same package.%s%sKind regards',
               case when v_supplier_name is null then '' else ' ' || v_supplier_name end,
               chr(10), chr(10), coalesce(v_cat, 'this package'), chr(10), chr(10))
      else
        format('Hello%s,%s%sThank you for the quotation on %s. Could you confirm the inclusions and exclusions, the delivery lead time, the payment terms and the warranty period in writing? Once I have those on the same basis from each supplier I will come back to you on price.%s%sKind regards',
               case when v_supplier_name is null then '' else ' ' || v_supplier_name end,
               chr(10), chr(10), coalesce(v_cat, 'this package'), chr(10), chr(10)) end;
    v_msg_ar := format('تحية طيبة،%s%sشكرًا لعرضكم بخصوص %s. نرجو تأكيد البنود المشمولة والمستثناة، ومدة التسليم، وشروط الدفع، وفترة الضمان كتابةً. وبمجرد استلام ذلك من جميع المورّدين على الأساس نفسه سنعود إليكم بشأن السعر.%s%sمع خالص التقدير',
                       chr(10), chr(10), coalesce(v_cat, 'هذا البند'), chr(10), chr(10));
  else
    v_target := greatest(round(v_amount * (1 - v_ask / 100), 0),
                         round(v_median * v_floor_pct / 100, 0));
    v_delta  := round(100 * (v_amount - v_median) / nullif(v_median, 0), 1);
    v_headline := format('AED %s is %s%s%% against a market median of AED %s over %s comparable quote(s). Policy says %s: target AED %s.',
                         v_amount, case when v_delta >= 0 then '+' else '' end, v_delta,
                         v_median, v_n, replace(v_action, '_', ' '), v_target);
    v_msg := format('Hello%s,%s%sThank you for the quotation on %s at AED %s. Based on comparable submissions we are holding for the same scope, our benchmark for this package is around AED %s. If you can meet AED %s on the same inclusions, lead time and warranty, we are ready to proceed with you.%s%sIf the price cannot move, tell me what would have to change in the scope to reach it and I will consider that instead.%s%sKind regards',
                    case when v_supplier_name is null then '' else ' ' || v_supplier_name end,
                    chr(10), chr(10), coalesce(v_cat, 'this package'), v_amount, v_median, v_target,
                    chr(10), chr(10), chr(10), chr(10));
    v_msg_ar := format('تحية طيبة،%s%sشكرًا لعرضكم بخصوص %s بمبلغ %s درهم. استنادًا إلى العروض المماثلة لدينا لنفس النطاق، فإن السعر المرجعي لهذا البند يقارب %s درهم. إذا أمكنكم الوصول إلى %s درهم بنفس البنود ومدة التسليم والضمان، فنحن مستعدون للمضي معكم.%s%sوإذا تعذّر تعديل السعر، فأخبرونا بما يلزم تغييره في النطاق للوصول إليه.%s%sمع خالص التقدير',
                       chr(10), chr(10), coalesce(v_cat, 'هذا البند'), v_amount, v_median, v_target,
                       chr(10), chr(10), chr(10), chr(10));
  end if;

  return jsonb_build_object(
    'quote_id', p_quote, 'inquiry_id', v_inquiry, 'category', v_cat,
    'quote_amount', v_amount, 'supplier_id', v_supplier, 'supplier_name', v_supplier_name,
    'market', v_stats,
    'market_median', v_median, 'market_sample_n', v_n,
    'delta_vs_median_pct', v_delta,
    'band', v_band,
    'policy_scope', v_scope,
    'recommended_action', v_action,
    'ask_discount_pct', case when v_target is null then null else v_ask end,
    'target_price', v_target,
    'headline', v_headline,
    'suggested_message', v_msg,
    'suggested_message_ar', v_msg_ar,
    'empty_reason', case when v_target is null
      then format('No target price is proposed: %s.', case when v_band = 'insufficient_data'
        then 'the category has fewer comparable quotes than this policy requires'
        else 'the house policy does not push on this band' end) end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_norm_roles(p_text text)
 RETURNS text[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(array_agg(distinct r.code order by r.code), '{}')
  from public.taxonomy_role r
  where r.active
    and exists (
      select 1 from unnest(r.aliases || r.code) a
      where length(a) >= 3
        and coalesce(p_text,'') ~* ('\m' || regexp_replace(a, '([.*+?^${}()|\[\]\\])', '\\\1', 'g'))
    );
$function$


CREATE OR REPLACE FUNCTION public.fn_norm_text(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select translate(
           regexp_replace(
             lower(btrim(regexp_replace(coalesce(p_text,''), '\s+', ' ', 'g'))),
             '[ًٌٍَُِّْـٰ]', '', 'g'),
           'أإآٱىة', 'اااايه');
$function$


CREATE OR REPLACE FUNCTION public.fn_norm_trades(p_text text)
 RETURNS text[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- SLUG SEPARATORS ARE WORD SEPARATORS (12 Aug 2026). The scraper writes sector as
  -- 'building-materials'; every multi-word alias in taxonomy_trade is written with spaces. \m is a
  -- word boundary, '-' is not a word character, so a two-word alias can never span the hyphen and
  -- 514 leads sat outside the vocabulary over one character. Normalising the INPUT rather than
  -- rewriting 40 trades' aliases into every punctuation variant they might arrive in.
  select coalesce(array_agg(distinct t.code order by t.code), '{}')
  from public.taxonomy_trade t
  where t.active
    and exists (
      select 1 from unnest(t.aliases || t.code) a
      where length(a) >= 3
        and regexp_replace(coalesce(p_text,''), '[-_/.]+', ' ', 'g')
            ~* ('\m' || regexp_replace(a, '([.*+?^${}()|\[\]\\])', '\\\1', 'g'))
    );
$function$


CREATE OR REPLACE FUNCTION public.fn_normalize_founder_alert_level()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF lower(coalesce(NEW.level,'')) = 'crit' THEN NEW.level := 'critical'; END IF;
  RETURN NEW;
END
$function$


CREATE OR REPLACE FUNCTION public.fn_notifications_dead_letter_held(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_moved int := 0;
begin
  with old as (
    select * from public.notifications
     where status = 'held' and created_at < now() - make_interval(days => greatest(1, p_days))
  ), ins as (
    insert into public.dead_letter (source, source_id, kind, reason, payload, first_failed_at)
    select 'notifications', o.id::text, o.type,
           'held longer than ' || p_days || ' days; supplier mail was disabled and never re-enabled',
           to_jsonb(o) - 'body', o.created_at
      from old o
    returning 1
  )
  update public.notifications n set status = 'dead'
    from old o where n.id = o.id;
  get diagnostics v_moved = row_count;
  return jsonb_build_object('ok', true, 'dead_lettered', v_moved);
end $function$


CREATE OR REPLACE FUNCTION public.fn_notifications_digest()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare types jsonb;
begin
  if coalesce(NEW.channel,'email') <> 'email' then return NEW; end if;
  if NEW.status is not null and NEW.status not in ('queued','pending') then return NEW; end if;
  if coalesce(NEW.to_role,'') not in ('admin','founder','owner') then return NEW; end if;
  -- HARD EXCLUSIONS: these always send immediately regardless of policy.
  if coalesce(NEW.type,'') ~* 'money|refund|security|legal|fraud|critical|founder_alert|chief_of_staff|founder_brief|verify|otp|reset|password' then return NEW; end if;
  if coalesce(NEW.subject,'') ~* 'critical|urgent|fraud|breach|\mdown\M|failed|failure' then return NEW; end if;
  -- POLICY allowlist of routine types to fold into the brief.
  select value into types from public.decision_policy where key='alert_digest_types';
  if types is not null and types ? coalesce(NEW.type,'') then
    NEW.status := 'digest';
  end if;
  return NEW;
exception when others then
  return NEW;  -- a classifier error must never block a notification insert
end $function$


CREATE OR REPLACE FUNCTION public.fn_notifications_release_held(p_max integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_released int;
begin
  with picked as (
    select id from public.notifications where status = 'held' order by id limit greatest(1, p_max)
  )
  update public.notifications n set status = 'queued'
    from picked p where n.id = p.id
  returning 1 into v_released;
  get diagnostics v_released = row_count;
  return jsonb_build_object('ok', true, 'released', v_released);
end $function$


CREATE OR REPLACE FUNCTION public.fn_notify_matched_supplier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_email text; v_cat text; v_em text;
begin
  -- Kernel cutover. A supplier being matched happens INSIDE the run the inquiry already has. Starting a workflow per match would open one run per supplier for one customer request.
  perform public.fn_kernel_source_emit('dbtrigger:public.inquiry_matches:notify_matched_supplier', jsonb_build_object(
    'source_ref',  NEW.inquiry_id::text || ':' || NEW.supplier_id::text,
    'workflow_run_id', public.fn_kernel_run_for('inquiry:' || NEW.inquiry_id::text),
    'raw_payload', jsonb_build_object('inquiry_id', NEW.inquiry_id::text, 'supplier_id', NEW.supplier_id::text)));
  select email into v_email from leads where id=NEW.supplier_id;
  select category, emirate into v_cat, v_em from inquiries where id=NEW.inquiry_id;
  if v_email is not null and position('@' in v_email) > 1 then
    insert into notifications(type,to_email,to_role,lead_id,inquiry_id,subject,body,channel,status)
    values('new_inquiry', v_email, 'supplier', NEW.supplier_id, NEW.inquiry_id,
      'New job request on QuotesDone',
      'A customer is requesting quotes for: '||coalesce(v_cat,'a project')||coalesce(' ('||v_em||')','')||
      '. Log in to your QuotesDone supplier portal to view the brief and submit your quote.',
      'email','queued');
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_notify_supplier(p_transaction uuid, p_actor text DEFAULT 'customer'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t record; st jsonb; sup record; cust_email text; v_admin text; v_subject text; v_body text;
        v_call_days int; v_claim_days int; v_new_deadline timestamptz;
begin
  st := public.fn_refund_state(p_transaction);
  if st ? 'error' then return st; end if;
  if (st->>'can_notify') <> 'true' then
    return jsonb_build_object('ok', false, 'error', 'not_available', 'state', st->>'state',
                              'notify_available_at', st->>'notify_available_at');
  end if;

  select * into t from transactions where id = p_transaction;
  select company_name, coalesce(claimed_by, email) as email into sup from leads where id = t.supplier_id;
  select email into cust_email from customers where id = t.customer_id;
  v_admin := coalesce((select split_part(value,',',1) from app_secrets where key='admin_emails'),
                      'management@quotesdone.com');

  v_call_days  := coalesce((select value::text::int from decision_policy where key='refund_call_after_working_days'), 3);
  v_claim_days := coalesce((select value::text::int from decision_policy where key='refund_claim_after_call_working_days'), 3);

  v_subject := 'Awaiting your response — QuotesDone reveal #' || left(t.id::text, 8);
  v_body :=
    'Hello,' || chr(10) || chr(10) ||
    'A customer paid to reveal your contact details on QuotesDone on ' ||
      to_char(t.revealed_at at time zone 'Asia/Dubai','DD Mon YYYY') ||
      ' and has not yet heard from you.' || chr(10) || chr(10) ||
    'Everyone is copied on this email so you can simply reply to all and pick it up here.' || chr(10) || chr(10) ||
    'If we have not heard from you within ' || v_call_days::text ||
      ' working days, we will call you. If we still cannot reach you and the customer is refunded, the reveal fee is recovered from your account under the supplier terms.' || chr(10) || chr(10) ||
    'If you have already been in touch with this customer, reply here and we will close this off.' || chr(10) || chr(10) ||
    'QuotesDone';

  insert into notifications(type, to_email, cc_emails, to_role, lead_id, inquiry_id, channel, subject, body, status)
  values ('reveal_no_response_notice', sup.email,
          array_remove(array[cust_email, v_admin], null),
          'supplier', t.supplier_id, t.inquiry_id, 'email', v_subject, v_body, 'queued');

  -- Deadline must outlive the ladder the customer is being asked to follow.
  v_new_deadline := public.fn_add_working_days(
                      public.fn_add_working_days(now(), v_call_days), v_claim_days);

  update transactions
     set customer_notified_at = now(),
         refund_deadline = greatest(coalesce(refund_deadline, now()), v_new_deadline)
   where id = p_transaction;

  insert into agent_actions(agent, kind, status, risk, title, recommendation, detail, target_table, target_id)
  values ('customer_success','supplier_unresponsive','needs_review','high',
          'Supplier not responding after a paid reveal: ' || coalesce(sup.company_name,'#'||t.supplier_id),
          'Customer has formally notified them. Call the supplier after the working-day window; a refund may only be approved once that has elapsed.',
          jsonb_build_object('transaction_id', t.id, 'supplier_id', t.supplier_id,
                             'inquiry_id', t.inquiry_id, 'notified_at', now(),
                             'call_due_at', public.fn_add_working_days(now(), v_call_days),
                             'refund_claim_until', v_new_deadline),
          'transactions', t.id::text);

  return jsonb_build_object('ok', true, 'notified_at', now(),
                            'recipients', jsonb_build_array(sup.email, cust_email, v_admin),
                            'refund_claim_until', v_new_deadline,
                            'state', public.fn_refund_state(p_transaction));
end $function$


CREATE OR REPLACE FUNCTION public.fn_objective_cascade()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with company as (
    select count(*) filter (where active) as goals,
           count(*) filter (where active and coalesce(measure_sql,'') <> '') as measurable,
           max(target_value) filter (where active and category = 'Financial') as top_target
      from public.company_goals),
  dept as (
    select count(*) filter (where active) as objectives,
           count(*) filter (where active and coalesce(goal_key,'') <> '') as linked_to_goal
      from public.department_objective),
  role_kpi as (
    select count(*) filter (where k.active) as kpis,
           count(*) filter (where k.active and (coalesce(k.serves_goal,'') <> '' or k.serves_objective is not null)) as linked,
           count(*) filter (where k.active and k.measured_at is not null) as measured
      from public.employee_kpi k
      join public.org_role r on r.runtime_agent_key = k.agent_key and r.status = 'active'),
  work as (
    select count(*) filter (where status in ('assigned','in_progress')) as open,
           count(*) filter (where status in ('assigned','in_progress') and assigned_agent is not null) as owned
      from public.org_tasks)
  select jsonb_build_object(
    'revenue_objective_aed', (select top_target from company),
    'company_goals', (select goals from company),
    'company_goals_measurable', (select measurable from company),
    'department_objectives', (select objectives from dept),
    'department_objectives_linked_to_a_company_goal', (select linked_to_goal from dept),
    'role_kpis', (select kpis from role_kpi),
    'role_kpis_linked_upward', (select linked from role_kpi),
    'role_kpis_with_a_measured_actual', (select measured from role_kpi),
    'open_work', (select open from work),
    'open_work_with_one_accountable_owner', (select owned from work),
    'unlinked_department_objectives', (select objectives - linked_to_goal from dept),
    'unlinked_role_kpis', (select kpis - linked from role_kpi),
    'note', 'links are written only where a department owns exactly one active goal or objective; '
            ||'the remainder are reported unlinked rather than guessed');
$function$


CREATE OR REPLACE FUNCTION public.fn_officer_recs(n integer DEFAULT 8)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select string_agg(line, E'\n') from (
    select '- ['||er.officer||'] '||left(coalesce(rec->>'action',''),150) as line
    from (select distinct on (officer) officer, recommendations from exec_reports order by officer, created_at desc) er,
         lateral jsonb_array_elements(er.recommendations) rec
    where coalesce(rec->>'action','')<>''
    limit n) z;
$function$


CREATE OR REPLACE FUNCTION public.fn_onboarding_gate(p_agent text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(
    (select jsonb_build_object('agent',agent_key,'status',status,
       'outputs_need_review', status <> 'certified',
       'reason', case status
         when 'certified' then 'fully onboarded'
         when 'probation' then 'passed exams; first '||probation_reviews_required||' outputs need founder/lead review ('||probation_reviews_done||' done)'
         when 'recert_due' then 'certification expired; re-examination pending'
         else 'not yet examined on the four knowledge layers' end)
     from org_onboarding
      where coalesce(public.fn_org_agent_resolve(agent_key), agent_key)
          = coalesce(public.fn_org_agent_resolve(p_agent), p_agent)),
    jsonb_build_object('agent',coalesce(public.fn_org_agent_resolve(p_agent), p_agent),
      'asked_as',p_agent,'status','unknown','outputs_need_review',true,
      'reason','no onboarding record - treat as uncertified'));
$function$


CREATE OR REPLACE FUNCTION public.fn_onboarding_ingest_runs()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_updated int := 0;
begin
  for r in select agent, score_pct, run_at from canon_eval_runs where run_at > now() - interval '8 days' loop
    insert into org_onboarding(agent_key, department)
      values (r.agent, (select department from org_agents where agent_key=r.agent))
      on conflict (agent_key) do nothing;
    update org_onboarding set l1_score=r.score_pct, l1_at=r.run_at, updated_at=now()
      where agent_key=r.agent and (l1_at is null or l1_at < r.run_at);
    v_updated := v_updated + 1;
  end loop;
  update org_onboarding o set status='probation', updated_at=now()
    where o.status in ('onboarding','recert_due')
      and o.l1_score >= o.pass_threshold and o.l2_score >= o.pass_threshold;
  update org_onboarding o set status='certified', certified_at=now(),
      recert_due=(now()+interval '90 days')::date, updated_at=now()
    where o.status='probation' and o.probation_reviews_done >= o.probation_reviews_required;
  update org_onboarding o set status='recert_due', updated_at=now()
    where o.status='certified' and o.recert_due is not null and o.recert_due < current_date;
  return jsonb_build_object('runs_ingested', v_updated);
end $function$


CREATE OR REPLACE FUNCTION public.fn_open_remediation(p_agent_key text, p_failure_class text, p_competency text, p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into agent_remediation (agent_key, failure_class, competency, detail, status)
  values (p_agent_key, p_failure_class, p_competency, coalesce(p_detail,'{}'::jsonb), 'open')
  returning id;
$function$


CREATE OR REPLACE FUNCTION public.fn_operations_ai()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k record; v_health numeric; n int;
begin
  select * into k from ops_kpis;
  v_health := round(greatest(0, 100
    - least(30, coalesce(k.no_quote_backlog,0)*3)
    - (case when coalesce(k.avg_first_quote_hours,0) > 72 then 20 when coalesce(k.avg_first_quote_hours,0) > 48 then 10 else 0 end)
    - (case when coalesce(k.response_rate_pct,100) < 40 then 15 when coalesce(k.response_rate_pct,100) < 60 then 7 else 0 end)
    - least(15, coalesce(k.overdue_tasks,0)*3)
    - coalesce(k.cron_failures_24h,0)*4
    - least(10, coalesce(k.agent_errors_24h,0)*2)
    - (case when coalesce(k.high_risk_pending,0) > 5 then 8 else 0 end)),1);

  insert into ops_kpi_snapshots(snapshot_date,kpis) values (current_date, to_jsonb(k)||jsonb_build_object('ops_health',v_health))
    on conflict (snapshot_date) do update set kpis=excluded.kpis, created_at=now();

  perform ops_rec('no_quote_backlog', coalesce(k.no_quote_backlog,0) > 0, 'medium', 'Inquiries stuck without quotes',
    k.no_quote_backlog||' inquir(y/ies) older than 7 days have no quotes — a supply/response bottleneck. Chase matched suppliers or onboard supply in those categories.',
    jsonb_build_array(
      'These RFQs reached at least one supplier. An RFQ that fanned out to zero suppliers is not a response problem at all, and until fn_rfq_redispatch_sweep shipped today it would have sat here forever looking like one.',
      'Seven days without a quote means the suppliers declined or ignored it, not that they quoted outside the platform and the customer never told us.',
      'The backlog count is of inquiries, not of customers: one buyer with five open RFQs looks like five bottlenecks.'),
    'Clearing '||coalesce(k.no_quote_backlog,0)||' stuck RFQ(s) is the shortest path to revenue on this board — each one is a customer who asked and is still waiting, and a reveal is the only event that earns.',
    'No spend. Chasing costs outreach time; the alternative, onboarding supply in those categories, is free from the existing lead base and gated on invite_enabled.');

  perform ops_rec('slow_first_quote', coalesce(k.avg_first_quote_hours,0) > 48, 'medium', 'First quotes are slow',
    'First quotes are averaging '||coalesce(k.avg_first_quote_hours,0)||' hours. Tighten supplier response SLAs / nudges to speed the funnel.',
    jsonb_build_array(
      'The mean is meaningful at this volume. With very few quoted RFQs a single slow outlier moves this average by hours and would raise this alert on its own.',
      'The clock starts when the RFQ was dispatched, so a supplier who was notified late is counted as a supplier who replied slowly.',
      'Suppliers are being measured on hours that include nights and weekends, which no UAE contractor works.'),
    'Every hour cut from the first-quote wait is a buyer less likely to go elsewhere; the first quote is the moment an RFQ stops feeling like it went nowhere.',
    'No spend. Nudges cost supplier goodwill if the SLA is unrealistic, which is why the assumption about nights and weekends above matters before tightening anything.');

  perform ops_rec('low_response_rate', coalesce(k.response_rate_pct,100) < 60, 'medium', 'Supplier response rate is low',
    'Supplier response rate is '||coalesce(k.response_rate_pct,0)||'%. Improve matching quality and supplier enablement.',
    jsonb_build_array(
      'The denominator is RFQs actually dispatched to a supplier. A dispatch that reached nobody never enters it, so this rate describes matched suppliers only and says nothing about coverage.',
      'A non-response is a decision not to quote, not a supplier who never saw the RFQ — undelivered mail would read identically here.',
      'The matcher put the right trade in front of them: a bad match produces a silent supplier who was right to stay silent.'),
    'Response rate is the clearest read on whether the matcher is sending the right work to the right companies. Fixing it lifts every RFQ in every category at once, not one queue.',
    'No spend. Supplier enablement is outreach time; improving matching is engineering time against fn_match_capability.');

  perform ops_rec('approvals_backlog', coalesce(k.pending_approvals,0) > 15, 'low', 'Approval queue building up',
    k.pending_approvals||' items are awaiting your decision ('||coalesce(k.high_risk_pending,0)||' high-risk). Clear the queue so the agents can proceed.',
    jsonb_build_array(
      'Every pending item is genuinely blocked on a human. An item left pending because nothing consumes that kind would look identical and would not move if you decided it.',
      'The '||coalesce(k.high_risk_pending,0)||' high-risk item(s) carry a risk level set by the routine that raised them, which is a self-assessment and not an audit.',
      'The queue is a founder queue: none of these can be cleared by another agent, or they would already have been.'),
    'Each decision unblocks whatever the raising agent wanted to do next. A queue this size is the company waiting on one person, which is the thing the whole design is meant to avoid.',
    'No spend. Founder attention, which is the scarcest resource here and the reason the queue is worth keeping short.');

  perform ops_rec('overdue_tasks', coalesce(k.overdue_tasks,0) > 0, 'low', 'Overdue tasks',
    k.overdue_tasks||' task(s) are past due. Reschedule or action them.',
    jsonb_build_array(
      'The due dates were set deliberately. A task auto-dated by the routine that created it is overdue against a guess, not against a commitment.',
      'These tasks have an owner who could act. org_tasks.assigned_agent had no writer at all until 12 Aug, so anything created before then may be overdue and ownerless — a scheduling problem masking a staffing one.'),
    'Rescheduling honestly is worth as much as finishing: a due date nobody believes makes every other due date meaningless, and this counter is what the health score reads.',
    'No spend. The real cost is that clearing overdue tasks by moving dates, rather than by doing them, hides the department that is short-staffed.');

  perform ops_rec('automation_failures', coalesce(k.cron_failures_24h,0) > 0 or coalesce(k.agent_errors_24h,0) > 5, 'high', 'Automation failures detected',
    coalesce(k.cron_failures_24h,0)||' scheduled-job failure(s) and '||coalesce(k.agent_errors_24h,0)||' agent error(s) in 24h. Investigate the failing jobs.',
    jsonb_build_array(
      'agent_runs status=error means a fault. Several routines here write status=error to record a real-world FINDING they were built to report, so a healthy watcher doing its job inflates this count.',
      'The window is the last 24 hours, so a fault repaired hours ago is still counted; read the timestamps before investigating.',
      'A cron failure is the job failing, not the job being absent. A schedule that was never created cannot fail and so cannot appear here at all — which is the more dangerous state.'),
    'Each failing job is something the company does without being asked. Left failing, that work silently stops and this counter is the only place it shows.',
    'No spend. Engineering attention; the diagnosis is usually one note in agent_runs.');

    -- COUNT THE AGENT THIS COMPANY ACTUALLY WRITES TO (13 Aug 2026). Every insert into
  -- agent_actions passes a00_agent_action_resolve_addressee, which rewrites an addressee that is
  -- not an active org_agent through fn_org_agent_resolve. 'operations_ai' is an alias for
  -- 'ops_director', so nothing has been stored under 'operations_ai' since the trigger shipped and
  -- this counter was reading a key the table no longer uses. Measured today: 40 rows under
  -- 'operations_ai' (39 auto_done, 1 done) and 9 under 'ops_director' - one of them PENDING. So
  -- open_recommendations reported 0 while a recommendation was genuinely open. Resolving the alias
  -- here rather than hardcoding both keys keeps the count correct if the mapping changes again.
  select count(*) into n from agent_actions
   where agent in ('operations_ai', coalesce(public.fn_org_agent_resolve('operations_ai'),'operations_ai'))
     and status in ('pending','needs_review');

  return jsonb_build_object('ran_at',now(),'ops_health',v_health,'kpis',to_jsonb(k),'open_recommendations',n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_opportunity_scan()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int := 0;
begin
  -- underserved categories that already hold a viable pool: ready demand, no action
  for r in select * from v_supply_gap where status='READY - not yet invited' order by sendable desc limit 10 loop
    insert into opportunity (kind,title,detail,evidence,value_score,effort,confidence,detected_by)
    select 'underserved_category','Untapped pool: '||r.name,
      r.name||' holds '||r.sendable||' sendable suppliers and zero invitations sent. The pool is already sufficient for the 10-approved target.',
      jsonb_build_object('slug',r.slug,'sendable',r.sendable,'approved',r.approved),
      least(100, r.sendable/5.0), 'low', 0.8, 'intel_director'
    where not exists (select 1 from opportunity o where o.title='Untapped pool: '||r.name and o.status='open');
    if found then n := n+1; end if;
  end loop;

  -- categories where knowledge exists but no supply: capability ahead of market
  for r in select * from v_supply_gap where status='NO POOL - must source from scratch' limit 5 loop
    insert into opportunity (kind,title,detail,evidence,value_score,effort,confidence,detected_by)
    select 'unmet_demand','Whitespace: '||r.name,
      'A fully briefed category expert exists for '||r.name||' with zero suppliers anywhere in the pool. Either a genuine market gap worth owning, or a category to retire.',
      jsonb_build_object('slug',r.slug,'sendable',0), 40,'high',0.5,'market_analyst'
    where not exists (select 1 from opportunity o where o.title='Whitespace: '||r.name and o.status='open');
    if found then n := n+1; end if;
  end loop;

  -- cost opportunity
  if (select count(*) filter (where could_be_cheaper) from ai_cost_log where occurred_at>now()-interval '30 days') > 10 then
    insert into opportunity (kind,title,detail,evidence,value_score,effort,confidence,detected_by)
    select 'cost_saving','Over-specified AI calls',
      (select count(*) filter (where could_be_cheaper)||' of '||count(*)||' calls in the last 30 days could have been served by a cheaper model.' from ai_cost_log where occurred_at>now()-interval '30 days'),
      '{}'::jsonb, 60,'low',0.9,'optimisation_eng'
    where not exists (select 1 from opportunity where title='Over-specified AI calls' and status='open');
    if found then n := n+1; end if;
  end if;

  -- ── THE THREE QUESTIONS THE SCAN NEVER ASKED ─────────────────────────────────────────────────
  -- The demand-driven one counts REAL inquiries. marketing_category_demand.inquiries_90d includes
  -- qd_demo_fixture rows, so the view's count must not carry a founder-facing opportunity on its own.

  -- GROWING INDUSTRIES — asked as demand against supply, which is what the data supports. Below ten
  -- suppliers is the company's own standard: 860 approved = 10 in each of 86 categories.
  for r in select m.category, i.real_inq inq, coalesce(m.suppliers,0) sup
             from marketing_category_demand m
             cross join lateral (
               select count(*) real_inq from inquiries q
                where coalesce(nullif(q.category,''),'other') = m.category
                  and q.created_at >= now() - interval '90 days'
                  and coalesce(q.brief_source,'') <> 'qd_demo_fixture') i
            where i.real_inq >= 1 and coalesce(m.suppliers,0) < 10
            order by i.real_inq desc, coalesce(m.suppliers,0) asc limit 5 loop
    insert into opportunity (kind,title,detail,evidence,value_score,effort,confidence,detected_by)
    select 'sector_demand','Sector under-supplied: '||r.category,
      'The '||r.category||' industry drew '||r.inq||' inquir(y/ies) in 90 days against '||r.sup
      ||' supplier(s) on the platform, below the standard of ten per category. Demand in this sector '
      ||'is running ahead of the supply able to answer it.',
      jsonb_build_object('category',r.category,'inquiries_90d',r.inq,'suppliers',r.sup,'target_suppliers',10),
      least(100, r.inq*10.0), 'medium', 0.7, 'market_analyst'
    where not exists (select 1 from opportunity o
                       where o.title='Sector under-supplied: '||r.category and o.status='open');
    if found then n := n+1; end if;
  end loop;

  -- SEARCH KEYWORDS WITH NOWHERE TO LAND. Rewritten 14 Aug 2026: this used to require at least one
  -- real inquiry in the category, on a platform with zero inquiries, so it could not fire. The
  -- question does not need demand history — a tracked keyword pattern pointing at a category that
  -- has no landing page is a gap you can measure today. `pages` and `seo_categories` are BOTH
  -- checked because they are two different vocabularies and neither alone covers the catalog: pages
  -- holds site chrome under slugs like 'home' and 'portal', seo_categories holds 24 consumer trades
  -- ('electrical') that do not match the catalog's supplier slugs ('electrical-suppliers').
  -- The real 90-day inquiry count is carried in the evidence rather than used as a gate, so the
  -- opportunity states the demand it actually has instead of implying one it does not.
  for r in select c.slug, c.name,
                  (select count(*) from category_keyword k
                    where k.slug = c.slug and not coalesce(k.negative,false)) kw,
                  (select count(*) from inquiries q
                    where coalesce(nullif(q.category,''),'other') = c.slug
                      and q.created_at >= now() - interval '90 days'
                      and coalesce(q.brief_source,'') <> 'qd_demo_fixture') inq
             from catalog_supplier_categories c
            where not exists (select 1 from pages p where p.slug = c.slug)
              and not exists (select 1 from seo_categories s where s.slug = c.slug)
            order by 3 desc, c.slug limit 5 loop
    continue when r.kw = 0;
    insert into opportunity (kind,title,detail,evidence,value_score,effort,confidence,detected_by)
    select 'search_demand','Keyword demand with no page: '||r.name,
      r.kw||' tracked search keyword pattern(s) point at '||r.name||' and there is no landing page '
      ||'for it — neither a published page nor an SEO category entry. Real inquiries in this '
      ||'category over 90 days: '||r.inq||'. Whether that search volume is RISING is not measured '
      ||'anywhere on this platform, so this is a coverage gap, not a trend claim.',
      jsonb_build_object('category',r.slug,'keyword_patterns',r.kw,'inquiries_90d',r.inq,
                         'has_page',false,'has_seo_category',false,'trend_measured',false),
      least(100, r.kw*2.0), 'low', 0.7, 'market_analyst'
    where not exists (select 1 from opportunity o
                       where o.title='Keyword demand with no page: '||r.name and o.status='open');
    if found then n := n+1; end if;
  end loop;

  -- WEAK COMPETITORS — 27 tracked rivals, every one carrying a written weakness. A low or medium
  -- threat with a stated weakness is the shape of an opening; a high threat is a problem, not one.
  -- Untouched: this one rests on real competitor records, not on inquiries.
  for r in select c.name, coalesce(c.kind,'unclassified') kind, c.weakness, c.threat_level
             from competitor c
            where coalesce(btrim(c.weakness),'') <> ''
              and lower(coalesce(c.threat_level,'')) in ('low','medium')
            order by c.name limit 5 loop
    insert into opportunity (kind,title,detail,evidence,value_score,effort,confidence,detected_by)
    select 'competitive_gap','Weak competitor: '||r.name,
      r.name||' ('||r.kind||', threat '||r.threat_level||') has a recorded weakness: '
      ||left(r.weakness, 240),
      jsonb_build_object('competitor',r.name,'threat_level',r.threat_level,'kind',r.kind),
      case lower(r.threat_level) when 'medium' then 55 else 35 end, 'medium', 0.6, 'intel_director'
    where not exists (select 1 from opportunity o
                       where o.title='Weak competitor: '||r.name and o.status='open');
    if found then n := n+1; end if;
  end loop;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('opportunity_scan',now(),now(),'ok',jsonb_build_object('found',n),
    'Opportunity scan: '||n||' new opportunity(ies) detected without being asked.');
  return jsonb_build_object('found',n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_ops_authority_check(p_dept_key text, p_action_class text, p_amount_aed numeric DEFAULT NULL::numeric, p_risk text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_prod text; v_thresh numeric; v_map record; v_gate record; v_tier text; v_reason text;
begin
  select max_tier, threshold_aed into v_prod, v_thresh
    from public.org_authority where dept_key = p_dept_key and action_class = p_action_class;

  select * into v_map from public.action_class_gate where action_class = p_action_class;

  select * into v_gate from ops_kb_stage.hard_gates
   where raw->>'action_class' = coalesce(v_map.gate_action_class, p_action_class) limit 1;

  v_tier := coalesce(v_prod, 'gated');
  v_reason := case when v_prod is null
                   then 'no org_authority row for this department and action class - defaulting to gated'
                   else 'org_authority.max_tier' end;

  -- DECLARED GATES WIN. An action class nobody has reviewed cannot be autonomous. This is the rule
  -- that closes 7.1: previously an autonomous org_authority row with no matching gate sailed through,
  -- which is exactly how refund_within_window, content_publish, code_selfheal and role_define ran
  -- outside the gates that name them.
  if v_map.action_class is null and v_tier <> 'gated' then
    v_tier := 'gated';
    v_reason := 'action class "' || p_action_class || '" has no row in action_class_gate. Unreviewed is not unrestricted: '
             || 'map it to a hard gate, or to NULL with a stated rationale, before it can act on its own.';
  end if;

  if v_gate.record_id is not null and coalesce(v_gate.raw->>'default_tier','gated') = 'gated' and v_tier <> 'gated' then
    if v_thresh is not null and p_amount_aed is not null and p_amount_aed <= v_thresh then
      v_reason := format('hard gate "%s" applies but %s AED is within the delegated threshold of %s AED',
                         v_gate.title, p_amount_aed, v_thresh);
    else
      v_tier := 'gated';
      v_reason := 'hard gate "' || v_gate.title || '" overrides org_authority (a hard gate may only tighten, never widen)'
               || case when v_thresh is not null and p_amount_aed is null
                       then '; a delegated threshold of ' || v_thresh || ' AED exists but no amount was stated'
                       else '' end;
    end if;
  end if;

  if v_thresh is not null and p_amount_aed is not null and p_amount_aed > v_thresh then
    v_tier := 'gated';
    v_reason := format('amount %s AED exceeds the department threshold of %s AED', p_amount_aed, v_thresh);
  end if;

  if p_risk = 'critical' and v_tier = 'autonomous' then
    v_tier := 'gated';
    v_reason := 'risk_level=critical is never executed autonomously';
  end if;

  return jsonb_build_object(
    'department', p_dept_key, 'action_class', p_action_class,
    'effective_tier', v_tier,
    'may_act_autonomously', (v_tier = 'autonomous'),
    'requires_approval', (v_tier = 'gated'),
    'reviewed', (v_map.action_class is not null),
    'hard_gate', case when v_gate.record_id is null then null else jsonb_build_object(
        'title', v_gate.title, 'approval_role', v_gate.raw->>'approval_role',
        'threshold', v_gate.raw->>'threshold', 'rollback', v_gate.raw->>'rollback') end,
    'production_tier', v_prod, 'threshold_aed', v_thresh, 'reason', v_reason,
    'source', 'org_authority + action_class_gate + ops_kb_stage.hard_gates (deterministic, no model call)');
end $function$


CREATE OR REPLACE FUNCTION public.fn_ops_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  active_rfqs int; rfqs_today int; done_today int; ttfq numeric; qpr numeric;
  accept_rate numeric; conv numeric;
  rev_today numeric; rev_month numeric; pending_fees numeric; outstanding_inv int; cash_recv numeric;
  ai_conf numeric; waiting int; onboard_q int; disputes int; escalations int;
  uptime numeric; queue_size int; failed int; last_backup timestamptz; api_lat numeric;
  health jsonb;
begin
  -- MARKETPLACE
  select count(*) into active_rfqs from inquiries where status not in ('completed','accepted','closed','cancelled');
  select count(*) into rfqs_today from inquiries where created_at::date=current_date;
  select count(*) into done_today from inquiries where (completed_at::date=current_date) or (status in ('completed','accepted') and stage_changed_at::date=current_date);
  select round(avg(extract(epoch from (fq - ic))/3600.0),1) into ttfq from (
    select i.created_at ic, min(q.created_at) fq from inquiries i join quotes q on q.inquiry_id=i.id
    where i.created_at>=now()-interval '30 days' group by i.id) z where fq is not null;
  select round(avg(qc),1) into qpr from (select count(*) qc from quotes q join inquiries i on i.id=q.inquiry_id where i.created_at>=now()-interval '30 days' group by q.inquiry_id) z;
  select round(avg(nullif(rv_response_rate,0)) ,1) into accept_rate from leads where coalesce(rv_reveals,0)>0;
  select round(100.0*count(distinct t.inquiry_id)/nullif(count(distinct i.id),0),1) into conv
    from inquiries i left join transactions t on t.inquiry_id=i.id where i.created_at>=now()-interval '30 days';

  -- REVENUE
  select coalesce(sum(reveal_fee),0) into rev_today from transactions where revealed_at::date=current_date and coalesce(refund_status,'')<>'approved';
  select coalesce(sum(reveal_fee),0) into rev_month from transactions where date_trunc('month',revealed_at)=date_trunc('month',now()) and coalesce(refund_status,'')<>'approved';
  begin select coalesce(sum(amount_due),0) into pending_fees from supplier_dues where coalesce(status,'')<>'paid'; exception when others then pending_fees:=0; end;
  begin select count(*) into outstanding_inv from reveal_invoices ri left join transactions t on t.id=ri.transaction_id where coalesce(t.fee_status,'')<>'paid'; exception when others then outstanding_inv:=0; end;
  select coalesce(sum(reveal_fee),0) into cash_recv from transactions where coalesce(fee_status,'')='paid';

  -- OPERATIONS
  begin select public.fn_health_index() into health; exception when others then health:=null; end;
  select round(100.0*count(*) filter (where nullif(quality->>'score','')::numeric>=60)/nullif(count(*) filter (where quality is not null),0),1) into ai_conf
    from quotes where created_at>=now()-interval '7 days';
  select count(*) into waiting from inquiries where status in ('clarify','clarifying','awaiting_customer','needs_info');
  select count(*) into onboard_q from leads where approval_status='pending';
  select count(*) into disputes from transactions where refund_status='requested';
  select (select count(*) from agent_actions where status='pending')
        + (select count(*) from founder_alerts where public.fn_alert_severe(level) and created_at>=now()-interval '24 hours') into escalations;

  -- INFRASTRUCTURE
  select round(100.0*count(*) filter (where ok)/nullif(count(*),0),1) into uptime from health_checks where created_at>=now()-interval '24 hours';
  select count(*) into queue_size from notifications where coalesce(status,'')in('queued','pending','');
  begin select count(*) into failed from agent_runs where status='error' and coalesce(finished_at,started_at)>=now()-interval '24 hours'; exception when others then failed:=0; end;
  select max(updated_at) into last_backup from storage.objects where bucket_id='backups' and name like '%/_manifest.json';
  select round(avg(latency_ms),0) into api_lat from health_checks where created_at>=now()-interval '1 hour' and latency_ms is not null;

  return jsonb_build_object(
    'as_of', now(),
    'marketplace', jsonb_build_object('active_rfqs',active_rfqs,'rfqs_today',rfqs_today,'completed_today',done_today,
        'avg_hours_to_first_quote',ttfq,'avg_quotes_per_rfq',qpr,'supplier_acceptance_pct',accept_rate,'conversion_pct',conv),
    'revenue', jsonb_build_object('today_aed',rev_today,'month_aed',rev_month,'pending_fees_aed',pending_fees,
        'outstanding_invoices',outstanding_inv,'cash_received_aed',cash_recv),
    'operations', jsonb_build_object('ai_confidence_pct',ai_conf,'rfqs_waiting_clarification',waiting,
        'onboarding_queue',onboard_q,'disputes',disputes,'escalations',escalations),
    'infrastructure', jsonb_build_object('uptime_pct',uptime,'queue_size',queue_size,'failed_jobs_24h',failed,
        'backup_age_hours', case when last_backup is null then null else round(extract(epoch from (now()-last_backup))/3600.0,1) end,
        'api_latency_ms',api_lat),
    'health_index', coalesce(health->>'index',null));
end $function$


CREATE OR REPLACE FUNCTION public.fn_ops_department_context(p_dept_key text, p_topic text DEFAULT NULL::text, p_limit integer DEFAULT 6)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
with tk as (
  -- a target key given directly, plus every target this production key maps onto
  select array(
    select distinct k from (
      select d.department_key k from ops_kb_stage.departments d where d.department_key = p_dept_key
      union
      select c.target_department_key from ops_kb_stage.department_crosswalk c
       where c.production_dept_key = p_dept_key and c.target_exists
    ) z where k is not null) targets
),
q as (
  select to_tsquery('simple', nullif(array_to_string(
      array(select w || ':*' from unnest(regexp_split_to_array(lower(coalesce(p_topic,'')), '[^a-z0-9]+')) w
            where length(w) >= 3), ' | '), '')) tsq
)
select jsonb_build_object(
  'department', p_dept_key,
  'target_departments', (select to_jsonb(targets) from tk),
  'charter', (
    select coalesce(jsonb_agg(jsonb_build_object('department', d.department_key, 'name', d.name,
             'charter', left(d.charter,400), 'north_star', left(d.north_star,240),
             'implementation_status', d.implementation_status) order by d.department_key), '[]'::jsonb)
    from ops_kb_stage.departments d, tk where d.department_key = any(tk.targets)),
  -- Each target role carries the routing pack's model default for that role. The 96
  -- scope='target_employee' rows in model_policy_by_identity are keyed on the same target
  -- department and title as ops_kb_stage.roles and had no reader anywhere; fn_ai_route picked up
  -- only the 24 current_agent rows. deterministic_first is the operative field: the pack says
  -- most of these roles should reach for a rule before a model.
  'roles', (
    select coalesce(jsonb_agg(jsonb_build_object('title', r.title, 'agent_key', r.agent_key,
             'authority_tier', r.authority_tier, 'max_authority', r.max_authority,
             'responsibilities', left(r.responsibilities,300),
             'model_default', case when i.identity_key is null then null else jsonb_build_object(
                 'primary', i.primary_model, 'fallback', i.fallback_model,
                 'deterministic_first', i.deterministic_first,
                 'max_output_tokens', i.max_output_tokens) end) order by r.record_id), '[]'::jsonb)
    from ops_kb_stage.roles r
    cross join tk
    -- identity_key IS the role's agent_key: 96 of 96 join exactly. Matching on department+title
    -- reached only 44 and was my invention, not the data's.
    left join public.model_policy_by_identity i
           on i.scope = 'target_employee' and i.identity_key = r.agent_key
    where r.department_key = any(tk.targets)),
  'company_core', (
    select coalesce(jsonb_agg(jsonb_build_object('title', c.title, 'content', c.body)), '[]'::jsonb)
    from (select r.title, left(r.content,1200) body from ops_kb_stage.records r
          where r.scope_type = 'company' and r.module in ('identity','principles','governance','privacy','language')
            and r.validation_status in ('reviewed','source_verified','approved')
          order by r.record_type limit 8) c),
  'department_knowledge', (
    select coalesce(jsonb_agg(s.x), '[]'::jsonb) from (
      select jsonb_build_object('record_id', r.record_id, 'title', r.title,
                                'content', left(r.content, 1500), 'module', r.module,
                                'implementation_status', r.implementation_status,
                                'authority_tier', r.authority_tier, 'risk_level', r.risk_level,
                                'source_ids', r.source_ids) x
      from ops_kb_stage.records r, q, tk
      where r.scope_type = 'department' and r.scope_key = any(tk.targets)
        and r.validation_status in ('reviewed','source_verified','approved')
        and (q.tsq is null or to_tsvector('simple', r.title || ' ' || left(r.content,4000)) @@ q.tsq)
      order by ts_rank(to_tsvector('simple', r.title || ' ' || left(r.content,4000)), q.tsq) desc,
               r.implementation_status, r.record_id
      limit greatest(p_limit,1)) s),
  'decision_rules', (
    select coalesce(jsonb_agg(jsonb_build_object(
             'rule_id', d.rule_id, 'priority', d.priority,
             'when', coalesce(d.condition->>'text', d.condition::text),
             'then', coalesce(d.action->>'text', d.action::text),
             'authority_tier', d.authority_tier,
             'requires_human_review', d.requires_human_review) order by d.priority desc nulls last), '[]'::jsonb)
    from ops_kb_stage.decision_rules d, tk
    where d.department_key = any(tk.targets) and d.enabled),
  -- SOPs come from the pack's own sops projection (steps, definition of done, rollback, SLA),
  -- not from records filtered by record_type: the projection is the structured shape and the
  -- structure is the part an employee needs to actually follow the procedure.
  'sops', (
    select coalesce(jsonb_agg(jsonb_build_object('workflow', s.workflow_key, 'trigger', s.trigger,
             'steps', s.steps, 'definition_of_done', s.definition_of_done,
             'service_level', s.service_level, 'rollback', left(s.rollback,240),
             'authority_tier', s.authority_tier) order by s.record_id), '[]'::jsonb)
    from ops_kb_stage.sops s, tk where s.department_key = any(tk.targets)),
  'exception_playbooks', (
    select coalesce(jsonb_agg(jsonb_build_object('exception', p.exception_key, 'trigger', p.trigger,
                                                 'immediate_actions', p.immediate_actions,
                                                 'recovery', p.recovery) order by p.exception_key), '[]'::jsonb)
    from ops_kb_stage.exception_playbooks p, tk
    where p.department_key = any(tk.targets) and p.enabled),
  'kpis', (
    select coalesce(jsonb_agg(jsonb_build_object('metric', k.metric_name, 'formula', left(k.formula_description,240),
             'direction', k.direction, 'owner', k.owner) order by k.record_id), '[]'::jsonb)
    from ops_kb_stage.kpis k, tk where k.department_key = any(tk.targets) and coalesce(k.enabled,true)),
  'workflows', (
    select coalesce(jsonb_agg(jsonb_build_object('workflow', w.workflow_key, 'name', w.name,
             'trigger', left(w.trigger,200), 'departments', to_jsonb(w.departments),
             'hard_gates', to_jsonb(w.hard_gates), 'implementation_status', w.implementation_status)
             order by w.workflow_key), '[]'::jsonb)
    from ops_kb_stage.workflows w, tk where w.departments && tk.targets and coalesce(w.enabled,true)),
  'handoffs', (
    select coalesce(jsonb_agg(jsonb_build_object('workflow', h.workflow_key,
             'direction', case when h.from_department = any(tk.targets) then 'you send' else 'you receive' end,
             'from', h.from_department, 'to', h.to_department,
             'you_must', case when h.from_department = any(tk.targets) then left(h.sender_action,200)
                              else left(h.receiver_action,200) end,
             'acceptance', left(h.acceptance,160), 'rejection', left(h.rejection,160)) order by h.record_id), '[]'::jsonb)
    from ops_kb_stage.handoffs h, tk
    where (h.from_department = any(tk.targets) or h.to_department = any(tk.targets)) and coalesce(h.enabled,true)),
  -- All 100 pack subscriptions carry active=false: the pack ships them staged and step 18 of
  -- 03_IMPORT_ORDER says stop before activation. Filtering on active would return [] for every
  -- department and the projection would still be unread. They are emitted WITH the flag, because
  -- "your department is supposed to receive this event and does not yet" is the fact the target
  -- operating model is asserting. Setting active=true here would change nothing on the live bus
  -- (public.event_subscription is a different table) and would only dress the flag up as delivery.
  'event_subscriptions', (
    select coalesce(jsonb_agg(jsonb_build_object('event', e.event_type, 'reason', left(e.reason,200),
             'activated', coalesce(e.active,false)) order by e.event_type), '[]'::jsonb)
    from ops_kb_stage.event_subscriptions e, tk
    where e.department_key = any(tk.targets) or e.department_key = 'all'),
  'scenarios', (
    select coalesce(jsonb_agg(jsonb_build_object('scenario', s.scenario_key, 'kind', s.kind,
             'situation', left(s.situation,240), 'expected', left(s.expected_behaviour,240),
             'last_result', s.last_result, 'last_run', s.last_run) order by s.scenario_key), '[]'::jsonb)
    from ops_kb_stage.scenarios s, tk where s.scope_key = any(tk.targets)),
  'templates', (
    select coalesce(jsonb_agg(jsonb_build_object('template', t.template_key, 'purpose', left(t.purpose,200))
             order by t.template_key), '[]'::jsonb)
    from ops_kb_stage.templates t, tk where t.department_key = any(tk.targets)),
  'live_data', (
    select coalesce(jsonb_agg(jsonb_build_object('object', b.object_name, 'kind', b.db_object_kind,
                                                 'purpose', b.read_purpose, 'write_policy', b.write_policy)), '[]'::jsonb)
    from ops_kb_stage.live_bindings b, tk
    where b.department_key = any(tk.targets) and b.mapping_status = 'mapped'),
  'authoritative_sources', (
    select coalesce(jsonb_agg(jsonb_build_object('source_id', s2.source_id, 'title', s2.title,
                                                 'publisher', s2.publisher, 'url', s2.url_or_path)), '[]'::jsonb)
    from ops_kb_stage.sources s2
    where exists (select 1 from ops_kb_stage.records r, tk
                  where r.scope_key = any(tk.targets) and s2.source_id = any(r.source_ids))),
  'hard_gates', (
    select coalesce(jsonb_agg(jsonb_build_object('action_class', g.raw->>'action_class',
                                                 'approval_role', g.raw->>'approval_role')), '[]'::jsonb)
    from ops_kb_stage.hard_gates g),
  'institutional_memory', (
    select coalesce(jsonb_agg(jsonb_build_object('headline', m.headline, 'outcome', m.outcome)), '[]'::jsonb)
    from (select headline, outcome from public.institutional_memory order by created_at desc limit 3) m),
  'note', 'Decision rules, SOPs and exception playbooks are ENABLED as of 2026-08-10, after all 282 pack scenarios returned RUNNABLE. Hard gates still bind, and money still routes to the founder. Records marked target_state describe a capability that is NOT built yet.'
);
$function$


CREATE OR REPLACE FUNCTION public.fn_ops_knowledge_search(p_dept text, p_query text, p_limit integer DEFAULT 5)
 RETURNS TABLE(record_id text, title text, content text, record_type text, authority_tier text, implementation_status text, rank real)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare q_or tsquery; words text[];
begin
  words := array(select w from unnest(regexp_split_to_array(lower(regexp_replace(coalesce(p_query,''),'[^a-z0-9 ]',' ','g')),'\s+')) w where length(w)>2);
  if array_length(words,1) is null then return; end if;
  begin q_or := to_tsquery('english', array_to_string(words,' | ')); exception when others then return; end;
  return query
    select o.record_id, o.title, o.content, o.record_type, o.authority_tier,
           o.implementation_status, ts_rank(o.tsv, q_or) as rank
      from ops_knowledge o
     where (p_dept is null
            or o.dept_key = p_dept
            -- company principles and the UAE source registry apply to every department, and a
            -- cross-department workflow that names no single owner belongs to all of them by
            -- definition. Without these three branches 884 of 3,959 records were reachable by
            -- nothing at all — the same defect as the corpus itself, one level down.
            or o.scope_type in ('company','external_source')
            or (o.scope_type = 'workflow' and o.dept_key is null))
       and o.tsv @@ q_or
     order by ts_rank(o.tsv, q_or) desc, o.record_id
     limit greatest(1, least(coalesce(p_limit,5),20));
end $function$


CREATE OR REPLACE FUNCTION public.fn_ops_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare res jsonb;
begin
  select jsonb_build_object(
    'open_rfqs_no_quotes_7d', (select count(*) from inquiries i where i.created_at < now()-interval '7 days'
        and coalesce(i.status,'') not in ('completed','cancelled','closed')
        and not exists (select 1 from quotes q where q.inquiry_id=i.id)),
    'matched_not_quoted', (select count(*) from inquiry_matches m
        where not exists (select 1 from quotes q where q.inquiry_id=m.inquiry_id and q.supplier_id=m.supplier_id)),
    'avg_first_quote_hours', (select (fn_marketplace_analytics()->>'avg_first_quote_hours')::numeric),
    'response_rate_pct', (select (fn_marketplace_analytics()->>'response_rate_pct')::numeric),
    'pipeline_by_stage', (select coalesce(jsonb_agg(jsonb_build_object('stage',label,'deals',deals,'value',value) order by sort_order),'[]'::jsonb) from crm_pipeline_report),
    'overdue_activities', (select overdue_activities from crm_deal_kpis)
  ) into res;
  return res;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ops_run_scenarios()
 RETURNS TABLE(scenario_id text, kind text, scope_key text, verdict text, failures text[])
 LANGUAGE sql
AS $function$
with checked as (
  select s.record_id, s.kind, s.scope_key,
    array_remove(array[
      case when not exists (select 1 from ops_kb_stage.departments d where d.department_key = s.scope_key)
            and s.kind = 'department' then 'department not in the corpus department index' end,
      case when s.kind = 'workflow'
            and not exists (select 1 from ops_kb_stage.workflows w where w.workflow_key = s.scope_key)
           then 'workflow_key does not resolve to an imported workflow' end,
      case when coalesce(btrim(s.expected_behaviour), '') = '' then 'no expected behaviour stated' end,
      case when jsonb_array_length(coalesce(s.pass_criteria, '[]'::jsonb)) = 0 then 'no pass criteria' end,
      case when s.kind = 'department'
            and not exists (select 1 from ops_kb_stage.records r
                            where r.scope_type='department' and r.scope_key = s.scope_key
                              and r.module = 'professional_knowledge')
           then 'department has no professional knowledge to reason from' end,
      case when s.kind = 'department'
            and not exists (select 1 from ops_kb_stage.live_bindings b
                            where b.department_key = s.scope_key and b.mapping_status='mapped')
           then 'department has no resolved live-data binding' end,
      case when s.kind = 'department'
            and not exists (select 1 from ops_kb_stage.decision_rules dr where dr.department_key = s.scope_key)
           then 'department has no decision rules' end
    ], null) as failures
  from ops_kb_stage.scenarios s
)
select c.record_id, c.kind, c.scope_key,
       case when cardinality(c.failures) = 0 then 'RUNNABLE' else 'BLOCKED' end,
       c.failures
from checked c;
$function$


CREATE OR REPLACE FUNCTION public.fn_ops_scenarios_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run int; v_block int; v_new_block int; v_keys text[];
begin
  with v as (select * from public.fn_ops_run_scenarios()),
  upd as (
    update ops_kb_stage.scenarios s
       set last_result = v.verdict, last_run = now()
      from v where v.scenario_id = s.record_id
      returning s.record_id, v.verdict, (s.last_result = 'RUNNABLE' and v.verdict = 'BLOCKED') as newly_blocked
  )
  select count(*) filter (where verdict = 'RUNNABLE'),
         count(*) filter (where verdict = 'BLOCKED'),
         count(*) filter (where newly_blocked),
         coalesce(array_agg(record_id) filter (where newly_blocked), '{}')
    into v_run, v_block, v_new_block, v_keys
    from upd;

  if coalesce(v_new_block,0) > 0 then
    insert into public.agent_actions(agent, kind, title, recommendation, detail, risk, status)
    values ('knowledge_eng', 'incident',
            format('%s operations scenario(s) became BLOCKED', v_new_block),
            'A department lost the decision rules, professional knowledge or live-data binding its scenarios depend on. Run select * from fn_ops_run_scenarios() where verdict = ''BLOCKED'' for the reasons.',
            jsonb_build_object('scenarios', to_jsonb(v_keys), 'source', 'fn_ops_scenarios_sweep'),
            'medium', 'pending');
  end if;

  return jsonb_build_object('runnable', v_run, 'blocked', v_block,
                            'newly_blocked', v_new_block, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_ops_watch()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run bigint; v_ai_1h int; v_ai_24h int; v_top_email text; v_top_cnt int; v_err6h int; v_runerr6h int; v_spammer record; v_owner text; v_alerts int:=0;
  function_alerted boolean;
  v_wd_last timestamptz; v_wd_seen timestamptz;
begin
  insert into agent_runs(agent,started_at) values('ops_watch',clock_timestamp()) returning id into v_run;
  select split_part(coalesce(value,'management@quotesdone.com'),',',1) into v_owner from app_secrets where key='admin_emails';
  select count(*) into v_ai_1h from ai_usage where created_at>=now()-interval '1 hour';
  select count(*) into v_ai_24h from ai_usage where created_at>=now()-interval '24 hours';
  select email,count(*) into v_top_email,v_top_cnt from ai_usage where created_at>=now()-interval '24 hours' group by email order by count(*) desc limit 1;
  select count(*) into v_err6h from error_events where created_at>=now()-interval '6 hours' and severity in ('error','high','critical');
  select count(*) into v_runerr6h from agent_runs where status='error' and started_at>=now()-interval '6 hours';

  if (v_ai_1h > coalesce((select value::int from app_secrets where key='ai_cost_alert_hourly'),300))
     or (v_ai_24h > coalesce((select value::int from app_secrets where key='ai_cost_alert_daily'),2500)) then
    insert into error_events(source,kind,severity,detail) values('ops_watch','ai_cost_spike','high',jsonb_build_object('last_hour',v_ai_1h,'last_24h',v_ai_24h,'top_email',v_top_email,'top_count',v_top_cnt));
    select exists(select 1 from notifications where type='ops_alert' and subject like 'QuotesDone: AI usage spike%' and created_at>=now()-interval '6 hours') into function_alerted;
    if v_owner is not null and not function_alerted then
      insert into notifications(type,to_email,to_role,channel,subject,body) values('ops_alert',v_owner,'admin','email','QuotesDone: AI usage spike',
        'AI calls in last hour: '||v_ai_1h||', last 24h: '||v_ai_24h||'. Heaviest user: '||coalesce(v_top_email,'?')||' ('||coalesce(v_top_cnt,0)||'). Check for abuse or runaway cost. You can set ai_kill_switch=true to pause AI.');
      v_alerts:=v_alerts+1;
    end if;
  end if;

  if v_err6h > 20 or v_runerr6h > 10 then
    select exists(select 1 from notifications where type='ops_alert' and subject like 'QuotesDone: error spike%' and created_at>=now()-interval '6 hours') into function_alerted;
    if v_owner is not null and not function_alerted then
      insert into notifications(type,to_email,to_role,channel,subject,body) values('ops_alert',v_owner,'admin','email','QuotesDone: error spike',
        'Errors in last 6h: '||v_err6h||' app errors, '||v_runerr6h||' failed agent runs. Open the IT agent to investigate.');
      v_alerts:=v_alerts+1;
    end if;
  end if;

  for v_spammer in select customer_id, count(*) c from inquiries where created_at>=now()-interval '24 hours' group by customer_id having count(*)>40 loop
    insert into error_events(source,kind,severity,detail) values('ops_watch','inquiry_spam','medium',jsonb_build_object('customer_id',v_spammer.customer_id,'count',v_spammer.c));
    v_alerts:=v_alerts+1;
  end loop;

  select max(started_at) into v_wd_last from agent_runs
    where agent='agent_silence_watch' and status='ok' and started_at >= now()-interval '48 hours';
  select first_seen into v_wd_seen from cron_job_seen where jobname='agent_silence_watch_daily';

  if v_wd_last is null and v_wd_seen is not null and v_wd_seen < now()-interval '48 hours' then
    insert into error_events(source,kind,severity,detail)
      values('ops_watch','watchdog_silent','critical',
             jsonb_build_object('agent','agent_silence_watch','registered_since',v_wd_seen,
                                'note','no successful run in 48h - cron failures are going unobserved'));
    select exists(select 1 from notifications where type='ops_alert' and subject like 'QuotesDone: cron watchdog is down%' and created_at>=now()-interval '6 hours') into function_alerted;
    if v_owner is not null and not function_alerted then
      insert into notifications(type,to_email,to_role,channel,subject,body) values('ops_alert',v_owner,'admin','email','QuotesDone: cron watchdog is down',
        'agent_silence_watch has not completed successfully in 48 hours. While it is down, failing or stalled scheduled jobs will not raise alerts. Check that the agent_silence_watch_daily cron job is registered and running.');
      v_alerts:=v_alerts+1;
    end if;
  end if;

  update agent_runs set finished_at=clock_timestamp(),status='ok',counts=jsonb_build_object('ai_1h',v_ai_1h,'ai_24h',v_ai_24h,'err6h',v_err6h,'run_err6h',v_runerr6h,'alerts',v_alerts,'watchdog_ok',(v_wd_last is not null)) where id=v_run;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_org_action_executor_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_scope text[];
begin
  if new.kind = 'edge' then
    select c.scope into v_scope
      from public.internal_credential c
     where c.context = 'fn.cos_execute'
       and c.active and c.retired_at is null
     limit 1;

    if v_scope is null then
      raise exception
        'org_action_executor: no live fn.cos_execute credential, so an edge executor target cannot be validated. Refusing the write rather than registering a callee nothing has authorised.'
        using errcode = 'check_violation';
    end if;

    if not (new.target = any (v_scope)) then
      raise exception
        'org_action_executor: edge target % is outside the fn.cos_execute credential scope. cos_execute would POST service-role authority to it. Widen the credential scope deliberately if this executor is intended; do not widen it to make an INSERT succeed.',
        new.target
        using errcode = 'check_violation';
    end if;

  elsif new.kind = 'rpc' then
    if not exists (select 1 from public.org_action_executor_rpc_allowed a where a.target = new.target) then
      raise exception
        'org_action_executor: rpc target % is not in org_action_executor_rpc_allowed. cos_execute runs rpc executors as service-role, so this is a grant of arbitrary database authority. Add it to the allow-list deliberately first.',
        new.target
        using errcode = 'check_violation';
    end if;

  else
    raise exception
      'org_action_executor: unknown kind %. cos_execute only understands edge and rpc, so a row with any other kind is either dead or a mistake. Refusing it rather than storing it.', new.kind
      using errcode = 'check_violation';
  end if;

  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_org_agent_resolve(p_addressee text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(
    (select o.agent_key from public.org_agents o
      where o.agent_key = p_addressee and o.active),
    (select a.agent_key from public.org_agent_alias a
       join public.org_agents o on o.agent_key = a.agent_key and o.active
      where a.alias = p_addressee),
    -- THE TITLE ARM (11 Aug 2026). 30 of the 66 workflow actor_role values are job titles, and
    -- five of them are a second spelling of an employee the alias table already knew by key.
    -- Ordered so a title held by more than one employee resolves to the senior holder rather than
    -- to whichever row the planner returned first.
    (select o.agent_key from public.org_agents o
      where lower(btrim(o.title)) = lower(btrim(p_addressee)) and o.active
      order by case o.seniority
                 when 'executive' then 0 when 'chief' then 1 when 'director' then 2
                 when 'lead'      then 3 when 'manager' then 4 when 'senior' then 5 else 6 end,
               o.agent_key
      limit 1),
    (select o.agent_key from public.org_agents o
      where o.department = p_addressee and o.active
      order by case o.seniority
                 when 'executive' then 0 when 'chief' then 1 when 'director' then 2
                 when 'lead'      then 3 when 'manager' then 4 when 'senior' then 5 else 6 end,
               o.agent_key
      limit 1)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_org_authority_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_reason text := nullif(trim(coalesce(current_setting('app.change_reason', true), '')), '');
  v_widen  boolean;
  v_obj    text := 'org_authority:' || coalesce(new.dept_key, old.dept_key) || '/'
                                    || coalesce(new.action_class, old.action_class);
begin
  if tg_op = 'DELETE' then
    v_widen := false;   -- removing a row removes a permission
  else
    v_widen := public.fn_authority_rank(new.max_tier) > public.fn_authority_rank(coalesce(old.max_tier, 'advisory'))
            or coalesce(new.threshold_aed, 0) > coalesce(old.threshold_aed, 0);
  end if;

  if v_widen and (v_reason is null or length(v_reason) < 12) then
    raise exception
      'org_authority %: raising a department''s tier or money threshold needs a stated reason. '
      'Run `set local app.change_reason = ''why, in a sentence'';` in the same transaction. '
      'Lowering never needs one.', v_obj
      using errcode = 'check_violation';
  end if;

  insert into public.autonomy_control_audit (object, op, direction, old_value, new_value, reason)
  values (v_obj, tg_op,
          case when v_widen then 'widen' else 'tighten' end,
          coalesce(old.max_tier,'') || '/' || coalesce(old.threshold_aed::text,''),
          coalesce(new.max_tier,'') || '/' || coalesce(new.threshold_aed::text,''),
          v_reason);
  return coalesce(new, old);
end $function$


CREATE OR REPLACE FUNCTION public.fn_org_exec_invite(p_cap integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_enabled boolean; v_cap int; v_sent int;
begin
  v_enabled := coalesce((select value from app_secrets where key='invite_enabled'),'false')='true';
  v_cap := coalesce((select nullif(value,'')::int from app_secrets where key='invite_daily_cap'), 10);
  select public.enqueue_supplier_invites(p_cap) into v_sent;
  return jsonb_build_object(
    'invited', coalesce(v_sent,0),
    'campaign_enabled', v_enabled,
    'daily_cap', v_cap,
    'note', case when not v_enabled then 'Invite campaign is not enabled yet — 0 sent. It starts on its scheduled date; the deliverability-gated ramp will then send within the daily cap.'
                 else 'Enqueued '||coalesce(v_sent,0)||' invite(s) this run, within the daily cap of '||v_cap||' and bounce-rate guard.' end
  );
end $function$


CREATE OR REPLACE FUNCTION public.fn_org_exec_knowledge_fill(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_gaps int; v_req bigint; v_recon jsonb;
begin
  -- self-heal the taxonomy every run (fast, synchronous)
  v_recon := public.fn_kb_reconcile();
  -- how many service categories still have zero knowledge chunks
  select count(*) into v_gaps from public.category_specs s
    where not exists (select 1 from public.kb_chunks k where k.category = s.category);
  -- trigger the (slow) generator in the background
  select net.http_post(
    url:='https://' || public.qd_project_ref() || '.supabase.co/functions/v1/kb_autofill_gaps',
    headers:='{"Content-Type":"application/json"}'::jsonb,
    body:=jsonb_build_object('__secret',(select value from public.app_secrets where key='cred_db_internal'),'limit',greatest(1,least(coalesce(p_limit,5),5))),
    timeout_milliseconds:=280000
  ) into v_req;
  return jsonb_build_object('empty_categories', v_gaps, 'autofill_triggered', true, 'reconcile', v_recon,
    'note', case when v_gaps=0 then 'Knowledge base complete: 0 empty categories. Taxonomy reconciled ('||coalesce(v_recon->>'cat_prefix_stripped','0')||' prefixes stripped, '||coalesce(v_recon->>'alias_remapped','0')||' aliased).'
                 else 'Triggered background gap-fill for '||v_gaps||' empty category(ies); taxonomy reconciled. Generation runs in the background and logs to agent_runs.' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_org_export()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
select jsonb_build_object(
 'exported_at', now(),
 'org_departments', (select jsonb_agg(to_jsonb(t) order by t.sort) from org_departments t),
 'org_agents', (select jsonb_agg(to_jsonb(t) order by t.agent_key) from org_agents t),
 'org_authority', (select jsonb_agg(to_jsonb(t) order by t.dept_key, t.action_class) from org_authority t),
 'org_onboarding', (select jsonb_agg(to_jsonb(t) order by t.agent_key) from org_onboarding t),
 'decision_policy', (select jsonb_agg(to_jsonb(t) order by t.key) from decision_policy t),
 'policy_rules', (select jsonb_agg(to_jsonb(t) order by t.id) from policy_rules t),
 'canon_eval_questions', (select jsonb_agg(to_jsonb(t) order by t.id) from canon_eval_questions t),
 'agent_knowledge', (select jsonb_agg(jsonb_build_object('agent_key',agent_key,'topic',topic,'layer',layer,'priority',priority,'content',content) order by agent_key, priority desc, topic) from agent_knowledge t),
 'company_vision', (select jsonb_agg(to_jsonb(t)) from company_vision t),
 'ai_constitution', (select jsonb_agg(to_jsonb(t)) from ai_constitution t where active),
 'migrations', (select jsonb_agg(jsonb_build_object('version',version,'name',name) order by version) from supabase_migrations.schema_migrations)
)
$function$


CREATE OR REPLACE FUNCTION public.fn_org_phase_baseline_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception
    'org_phase_baseline is append-only: % on the frozen phase % baseline is refused',
    tg_op, coalesce(old.phase, '?')
    using errcode = '23514',
          hint = 'These rows are the founder-approved record of what a phase WAS when it was '
              || 'approved, and four drift checks read them as the fixed point they measure '
              || 'against. To change one, raise a Phase change request: write '
              || 'scripts/sql/pacr_NNN_<what_and_why>.sql which drops trigger '
              || 'a00_org_phase_baseline_append_only, makes the change with every digest '
              || 'RECOMPUTED in place, recreates the trigger in the same transaction, and is '
              || 'appended to scripts/sql/MANIFEST.txt. The dropped trigger in that file is the '
              || 'record that the freeze was deliberately opened.';
end $function$


CREATE OR REPLACE FUNCTION public.fn_org_role_agent(p_any text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  with r as (select * from public.org_role where role_id = public.fn_org_role_resolve(p_any))
  select coalesce(
    (select runtime_agent_key from r where runtime_mode <> 'knowledge_overlay'),
    (select m.runtime_agent_key from r join public.org_role m on m.role_id = r.manager_role_id),
    (select runtime_agent_key from r)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_org_role_deferral_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select 'role_violations_outside_the_approved_deferral_list'::text,
         '0'::text,
         (select count(*)::text from public.fn_org_role_violations())
           || ' of ' || (select count(*)::text from public.fn_org_role_violations_all()),
         (select count(*) from public.fn_org_role_violations()) = 0
  union all
  select 'founder_approved_deferrals'::text,
         'reported, never hidden and never marked complete'::text,
         (select coalesce(string_agg(d.token, '; ' order by d.token), '(none)')
            from public.fn_org_role_deferred() d),
         true
  union all
  -- A DEFERRAL THAT NO LONGER MATCHES ANY VIOLATION IS STALE, and a stale entry is a standing
  -- permission to hide the next occurrence of that rule against that role. Reported as a failure so
  -- the list is pruned by a change request when the work is actually done.
  select 'stale_deferrals_matching_no_violation'::text,
         '0'::text,
         (select count(*)::text from public.fn_org_role_deferred() d
           where not exists (select 1 from public.fn_org_role_violations_all() v
                              where v.rule = d.rule and v.role_id = d.role_id))
           || ' of ' || (select count(*)::text from public.fn_org_role_deferred()),
         (select count(*) from public.fn_org_role_deferred() d
           where not exists (select 1 from public.fn_org_role_violations_all() v
                              where v.rule = d.rule and v.role_id = d.role_id)) = 0;
$function$


CREATE OR REPLACE FUNCTION public.fn_org_role_deferred()
 RETURNS TABLE(rule text, role_id text, token text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select split_part(d.token, ':', 1)::text,
         split_part(d.token, ':', 2)::text,
         d.token::text
    from public.org_phase_baseline b
    cross join lateral jsonb_array_elements_text(coalesce(b.deferred, '[]'::jsonb)) d(token)
   where b.phase = 'A'
     and d.token like '%:%';
$function$


CREATE OR REPLACE FUNCTION public.fn_org_role_resolve(p_any text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(
    (select r.role_id from public.org_role r where r.role_id = p_any and r.status = 'active'),
    (select a.role_id from public.org_role_alias a
        join public.org_role r on r.role_id = a.role_id and r.status = 'active'
       where a.alias = p_any),
    (select r.role_id from public.org_role r
       where r.runtime_agent_key = p_any and r.status = 'active' limit 1),
    -- last arm: whatever org_agents' own alias table already knew, mapped forward
    (select r.role_id from public.org_agent_alias g
        join public.org_role r on r.runtime_agent_key = g.agent_key and r.status = 'active'
       where g.alias = p_any limit 1)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_org_role_violations()
 RETURNS TABLE(rule text, role_id text, detail text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select v.rule, v.role_id, v.detail
    from public.fn_org_role_violations_all() v
   where not exists (select 1 from public.fn_org_role_deferred() d
                      where d.rule = v.rule and d.role_id = v.role_id);
$function$


CREATE OR REPLACE FUNCTION public.fn_org_role_violations_all()
 RETURNS TABLE(rule text, role_id text, detail text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select 'department_inactive', r.role_id, r.primary_department_id
    from public.org_role r join public.org_departments d on d.dept_key = r.primary_department_id
   where r.status='active' and not d.active
  union all
  select 'no_manager', r.role_id, 'manager_role_id is null'
    from public.org_role r
   where r.status='active' and r.manager_role_id is null and r.role_id <> 'ceo'
  union all
  select 'manager_not_active', r.role_id, r.manager_role_id
    from public.org_role r
   where r.status='active' and r.manager_role_id is not null
     and not exists (select 1 from public.org_role m where m.role_id=r.manager_role_id and m.status='active')
  union all
  select 'no_runtime_agent', r.role_id, 'runtime_agent_key is null'
    from public.org_role r
   where r.status='active' and r.runtime_mode <> 'knowledge_overlay' and r.runtime_agent_key is null
  union all
  select 'runtime_agent_inactive', r.role_id, r.runtime_agent_key
    from public.org_role r
   where r.status='active' and r.runtime_agent_key is not null
     and not exists (select 1 from public.org_agents a where a.agent_key=r.runtime_agent_key and a.active)
  union all
  select 'no_kpi', r.role_id, 'employee_kpi has no active row for '||coalesce(r.runtime_agent_key,'-')
    from public.org_role r
   where r.status='active' and r.runtime_mode <> 'knowledge_overlay'
     and not exists (select 1 from public.employee_kpi k where k.agent_key=r.runtime_agent_key and k.active)
  union all
  select 'no_knowledge', r.role_id, 'knowledge_scopes is empty and employee_knowledge has no row'
    from public.org_role r
   where r.status='active' and cardinality(r.knowledge_scopes)=0
     and not exists (select 1 from public.employee_knowledge k where k.agent_key=r.runtime_agent_key)
  union all
  select 'no_authority', r.role_id, 'authority_level advisory with no employee_authority row'
    from public.org_role r
   where r.status='active' and r.runtime_mode <> 'knowledge_overlay'
     and not exists (select 1 from public.employee_authority k where k.agent_key=r.runtime_agent_key)
  union all
  select 'no_tools', r.role_id, 'tools is empty'
    from public.org_role r
   where r.status='active' and cardinality(r.tools)=0
  union all
  select 'no_evaluation', r.role_id, 'evaluation_suite is null'
    from public.org_role r
   where r.status='active' and coalesce(r.evaluation_suite,'')=''
  union all
  select 'reviewer_not_independent', r.role_id, 'independent_reviewer without stop_authority'
    from public.org_role r
   where r.status='active' and r.runtime_mode='independent_reviewer' and r.authority_level <> 'stop_authority'
  union all
  select 'duplicate_role_for_agent', r.role_id, r.runtime_agent_key
    from public.org_role r
   where r.status='active' and r.runtime_agent_key is not null
     and (select count(*) from public.org_role x
           where x.status='active' and x.runtime_agent_key=r.runtime_agent_key) > 1
  union all
  select 'agent_without_role', a.agent_key, 'active org_agents row maps to no active org_role'
    from public.org_agents a
   where a.active and not exists (select 1 from public.org_role r
          where r.status='active' and r.runtime_agent_key = a.agent_key)
  union all
  select 'packaged_role_unreachable', i.packaged_role_id,
         'held only by inactive employee(s): '||string_agg(distinct i.agent_key, ', ')
         ||'; '||(select count(*)::text from public.ops_knowledge k
                   where k.role_key = i.packaged_role_id and k.runtime_eligible)
         ||' runtime-eligible knowledge record(s) unreachable through the role layer'
    from public.org_role_identity i
   where not exists (select 1 from public.org_role_identity x
                       join public.org_agents a on a.agent_key = x.agent_key and a.active
                      where x.packaged_role_id = i.packaged_role_id)
   group by i.packaged_role_id;
$function$


CREATE OR REPLACE FUNCTION public.fn_org_scorecard()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select coalesce(jsonb_agg(row_to_json(x) order by x.sort),'[]'::jsonb) from (
    select d.dept_key, d.name, d.north_star, d.lead_agent, d.sort,
      (select count(*) from public.org_tasks t where t.dept_key=d.dept_key and t.status in ('proposed','assigned','in_progress','blocked')) as open_tasks,
      (select count(*) from public.org_tasks t where t.dept_key=d.dept_key and (t.needs_founder or t.status='escalated') and t.status not in ('done','failed')) as escalations,
      (select count(*) from public.agent_actions a where a.status in ('pending','needs_review','open') and (
          (d.dept_key='finance' and a.kind ~* 'finance|refund|dues') or
          (d.dept_key='legal' and a.kind ~* 'legal|compliance') or
          (d.dept_key='supplier_success' and a.kind ~* 'supplier|approve|licence|kyc') or
          (d.dept_key='customer_success' and a.kind ~* 'customer|refund|escalation') or
          (d.dept_key='it' and a.kind ~* 'incident|security') or
          (d.dept_key='marketing' and a.kind ~* 'market|content') or
          (d.dept_key='knowledge' and a.kind ~* 'knowledge|coverage')
        )) as dept_queue
    from public.org_departments d where d.active
  ) x;
$function$


CREATE OR REPLACE FUNCTION public.fn_org_task_assign(p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_assigned int := 0; v_no_capacity int := 0; v_considered int := 0; v_saturated text;
begin
  with open_tasks as (
    select t.id, t.dept_key, t.created_at, t.action_class
      from public.org_tasks t
     where t.assigned_agent is null
       and t.status in ('assigned','in_progress')
     order by t.created_at
     limit greatest(coalesce(p_limit, 200), 1)
  ),
  load as (
    select a.agent_key, a.department, coalesce(a.max_open_tasks, 6) as cap,
           coalesce(r.runtime_mode, 'on_demand_specialist') as runtime_mode,
           (select count(*) from public.org_tasks o
             where o.assigned_agent = a.agent_key and o.status in ('assigned','in_progress')) as open_now,
           case when p.tier = 'probation' then 1 else 0 end as probation_rank
      from public.org_agents a
      left join public.agent_reputation p on p.agent_key = a.agent_key
      left join public.org_role r on r.runtime_agent_key = a.agent_key and r.status = 'active'
     where a.active
       and coalesce(a.available, true)
       and (a.unavailable_until is null or a.unavailable_until < now())
  ),
  ranked as (
    select ot.id as task_id, l.agent_key, l.cap, l.open_now,
           row_number() over (partition by ot.id
                              order by l.probation_rank, l.open_now, l.agent_key) as pick,
           row_number() over (partition by l.agent_key
                              order by ot.created_at, ot.id) as nth_for_agent
      from open_tasks ot
      join load l on l.department = ot.dept_key
      -- AN INDEPENDENT REVIEWER CARRYING THE DEPARTMENT'S ROUTINE QUEUE IS NOT INDEPENDENT OF IT.
      -- Review work still reaches them: the review action classes are the exception, and
      -- fn_pick_reviewer routes review directly rather than through this queue.
     where l.runtime_mode <> 'independent_reviewer'
        or coalesce(ot.action_class,'') in ('review','audit','verify','qa_gate','security_review',
                                            'compliance_check','legal_review','supplier_verify',
                                            'capability_review','self_review')
  ),
  chosen as (
    select task_id, agent_key from ranked
     where pick = 1 and (open_now + nth_for_agent) <= cap
  ),
  done as (
    update public.org_tasks t
       set assigned_agent = c.agent_key, updated_at = now()
      from chosen c
     where t.id = c.task_id and t.assigned_agent is null
    returning t.id
  )
  select (select count(*) from done), (select count(*) from open_tasks)
    into v_assigned, v_considered;

  v_no_capacity := v_considered - v_assigned;

  select string_agg(x.dept_key||' '||x.unowned||'/'||x.capacity, ', ' order by x.unowned desc)
    into v_saturated
    from (select t.dept_key, count(*) as unowned,
                 (select coalesce(sum(coalesce(a.max_open_tasks,6)),0) from public.org_agents a
                   where a.active and coalesce(a.available,true) and a.department = t.dept_key) as capacity
            from public.org_tasks t
           where t.assigned_agent is null and t.status in ('assigned','in_progress')
           group by t.dept_key
          having count(*) > 0
           order by count(*) desc
           limit 6) x;

  insert into public.agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('org_task_assign', now(), now(), 'ok',
          jsonb_build_object('considered', v_considered, 'assigned', v_assigned,
                             'left_unowned', v_no_capacity, 'oversubscribed', coalesce(v_saturated,'none')),
          'Assigned '||v_assigned||' of '||v_considered||' unowned open task(s) to a named employee '
          ||'in the owning department, skipping independent reviewers for non-review work. '
          ||v_no_capacity||' left unowned because no colleague in that department had capacity '
          ||'under max_open_tasks - deliberate: an unowned task is visible, an overloaded one is '
          ||'not. Departments carrying more open work than they staff (unowned/capacity): '
          ||coalesce(v_saturated,'none')||'.');

  return jsonb_build_object('considered', v_considered, 'assigned', v_assigned,
                            'left_unowned', v_no_capacity, 'oversubscribed', coalesce(v_saturated,'none'));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_org_task_autonomy_brake()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v jsonb;
begin
  if new.status is distinct from 'in_progress' or old.status = 'in_progress' then
    return new;
  end if;
  if coalesce(new.tier, 'advisory') = 'advisory' then
    return new;   -- WI-001 permits shadow development; advice-only work is not broad autonomy
  end if;
  v := public.fn_autonomy_status();
  if (v ->> 'allowed')::boolean then
    return new;
  end if;
  raise exception
    'org_tasks: task % cannot start at tier %. Broad autonomy is blocked: %. This is WI-001 being '
    'enforced rather than merely declared — clear the blocker, or drop the task to advisory.',
    new.id, new.tier, (v ->> 'blockers')
    using errcode = 'check_violation';
end $function$


CREATE OR REPLACE FUNCTION public.fn_org_task_cross_os_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_target_os text; v_author_os text;
begin
  if coalesce(new.status,'proposed') = 'proposed' then return new; end if;
  if coalesce(new.decided_by,'') in ('fn_event_dispatch','cos','approval_path','dept_plan') then
    return new;
  end if;

  select od.os_key into v_target_os from os_department od where od.dept_key = new.dept_key;

  select od.os_key into v_author_os
    from org_agents a join os_department od on od.dept_key = a.department
   where a.agent_key = new.decided_by;

  -- An unattributed writer is a company-level routine, not an Operating System, and the blueprint
  -- does not forbid those. Only a named OS reaching across is refused.
  if v_author_os is null or v_target_os is null or v_author_os = v_target_os then
    return new;
  end if;

  raise exception
    'org_tasks: % (%) cannot ASSIGN work to % (%). No OS calls another OS directly — emit the '
    'event and let the bus route it, or lower this to status=''proposed'' so the receiving OS can '
    'decline it.', new.decided_by, v_author_os, new.dept_key, v_target_os
    using errcode = 'check_violation';
end $function$


CREATE OR REPLACE FUNCTION public.fn_org_task_execute_sweep(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t record; v_q int := 0; v_key text;
begin
  for t in
    select k.id, k.dept_key, k.title, k.action_class, e.target, e.risk_tier, e.reversible
      from public.org_tasks k
      join public.org_action_executor e on e.action_class = k.action_class
     where k.status in ('assigned','in_progress')
       and e.kind = 'edge' and e.active
       and e.risk_tier = 'low' and e.advisory_safe and e.reversible
       and not e.notifies_human
       and coalesce(e.required_authority,'') <> 'founder'
       -- ALL statuses. idempotency_key is UNIQUE, so a task whose invocation FAILED once collides on
       -- the next sweep: org_task:260 failed org_task_execute_sweep_hourly at 14:45, 15:45 and 16:45
       -- on 10 Aug. A failed attempt is a recorded attempt.
       and not exists (select 1 from public.action_execution x
                        where x.idempotency_key = 'org_task:' || k.id)
     order by k.id
     limit greatest(coalesce(p_limit, 5), 1)
  loop
    v_key := 'org_task:' || t.id;
    insert into public.action_execution(id, correlation_id, action_class, executor, idempotency_key,
                                        risk_tier, reversible, request, status, attempts)
    values (gen_random_uuid(), gen_random_uuid(), t.action_class, t.target, v_key,
            t.risk_tier, t.reversible,
            jsonb_build_object('org_task_id', t.id, 'dept_key', t.dept_key,
                               'title', left(coalesce(t.title,''), 300),
                               'source', 'fn_org_task_execute_sweep'),
            'queued', 0)
    on conflict (idempotency_key) do nothing;

    update public.org_tasks set status = 'in_progress', last_run_at = now(), updated_at = now()
     where id = t.id and status = 'assigned';
    v_q := v_q + 1;
  end loop;

  return jsonb_build_object('queued', v_q, 'ran_at', now(),
    'eligible_remaining', (select count(*) from public.org_tasks k
                             join public.org_action_executor e on e.action_class = k.action_class
                            where k.status in ('assigned','in_progress') and e.kind='edge' and e.active
                              and e.risk_tier='low' and e.advisory_safe and e.reversible
                              and not e.notifies_human
                              and not exists (select 1 from public.action_execution x
                                               where x.idempotency_key = 'org_task:' || k.id)));
end $function$


CREATE OR REPLACE FUNCTION public.fn_org_task_root_cause_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_rc text;
begin
  if new.status = 'done' and coalesce(old.status, '') <> 'done'
     and new.title ilike 'KPI missed%' and coalesce(btrim(new.root_cause), '') = '' then

    v_rc := nullif(btrim(regexp_replace(
              coalesce(substring(coalesce(new.result ->> 'deliverable', '')
                                 from '(?i)root[-_ ]?cause[^\n]{0,250}'), ''),
              '\s+', ' ', 'g')), '');

    if v_rc is null then
      raise exception 'org_tasks #% (%) is a KPI-miss task and cannot close without root_cause: record the cause of the variance in org_tasks.root_cause, or state it under a "Root cause" heading in the deliverable and this trigger captures it.', new.id, left(new.title, 70);
    end if;

    new.root_cause := left(v_rc, 500);
  end if;
  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_os_ai_quality()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with nights as (
  select at, row_number() over (order by at desc) rn
  from (select distinct at from public.ai_quality_snapshots) d
),
latest_at as (select at from nights where rn = 1),
-- one row per agent for the most recent night, whichever era wrote it
latest as (
  select s.agent,
         round(sum(s.override_pct * greatest(s.actions_30d,1))::numeric
               / nullif(sum(greatest(s.actions_30d,1)),0), 1) as override_pct,
         sum(s.actions_30d)::int as actions_30d
  from public.ai_quality_snapshots s
  where s.at = (select at from latest_at)
  group by s.agent
),
-- the trailing picture, excluding the night we are reporting on
prev as (
  select s.agent,
         round(sum(s.override_pct * greatest(s.actions_30d,1))::numeric
               / nullif(sum(greatest(s.actions_30d,1)),0), 1) as avg_prev,
         count(distinct s.at) as nights
  from public.ai_quality_snapshots s
  where s.at < (select at from latest_at)
  group by s.agent
)
select jsonb_build_object(
  'as_of', (select at from latest_at),
  'nights_held', (select count(*) from nights),
  'agents', (select count(*) from latest),
  -- the one headline, weighted the same way as every row under it
  'override_pct_overall', (select round(sum(override_pct * greatest(actions_30d,1))::numeric
                                        / nullif(sum(greatest(actions_30d,1)),0), 1) from latest),
  'actions_30d_total', (select coalesce(sum(actions_30d),0) from latest),
  'meaning', 'override_pct is the share of that agent''s proposed actions in the last 30 days that a human rejected, dismissed, declined or overrode. Higher is worse.',
  'rows', coalesce((
    select jsonb_agg(r order by r->>'sort_key')
    from (
      select jsonb_build_object(
               'agent', l.agent,
               'override_pct', l.override_pct,
               'actions_30d', l.actions_30d,
               'avg_prev', p.avg_prev,
               'nights_of_history', coalesce(p.nights, 0),
               -- stated only when there IS a history to compare against, so a first-night agent
               -- reads as 'new' rather than as 'no change'
               'delta', case when p.avg_prev is null then null
                             else round(l.override_pct - p.avg_prev, 1) end,
               'sort_key', lpad((1000 - least(999, l.actions_30d))::text, 4, '0') || l.agent
             ) as r
      from latest l left join prev p on p.agent = l.agent
    ) x), '[]'::jsonb)
);
$function$


CREATE OR REPLACE FUNCTION public.fn_os_automation_list()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(x order by x->>'category', x->>'human_name'), '[]'::jsonb) from (
    select jsonb_build_object(
      'jobid', j.jobid, 'jobname', j.jobname,
      'human_name', coalesce(r.human_name, initcap(replace(replace(j.jobname,'_',' '),'-',' '))),
      'category', coalesce(r.category,'Operations'), 'purpose', coalesce(r.purpose,''),
      'schedule', j.schedule, 'active', j.active,
      'last_status', lr.status, 'last_start', lr.start_time, 'last_end', lr.end_time,
      'last_message', left(coalesce(lr.return_message,''), 240)
    ) as x
    from cron.job j
    left join public.cron_registry r on r.jobname = j.jobname
    left join lateral (
      select status, start_time, end_time, return_message
      from cron.job_run_details d where d.jobid = j.jobid
      order by d.start_time desc nulls last limit 1
    ) lr on true
  ) q;
$function$


CREATE OR REPLACE FUNCTION public.fn_os_automation_reschedule(p_jobid bigint, p_schedule text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE nm text; oldsched text;
BEGIN
  SELECT jobname, schedule INTO nm, oldsched FROM cron.job WHERE jobid = p_jobid;
  IF nm IS NULL THEN RETURN jsonb_build_object('ok',false,'error','job_not_found'); END IF;
  IF coalesce(array_length(regexp_split_to_array(btrim(p_schedule), '\s+'),1),0) <> 5 THEN
    RETURN jsonb_build_object('ok',false,'error','schedule_must_have_5_fields'); END IF;
  BEGIN PERFORM cron.alter_job(job_id := p_jobid, schedule := p_schedule);
  EXCEPTION WHEN others THEN RETURN jsonb_build_object('ok',false,'error',SQLERRM); END;
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'automation_reschedule','cron_job',p_jobid::text,jsonb_build_object('jobname',nm,'old',oldsched,'new',p_schedule),true);
  RETURN jsonb_build_object('ok',true,'schedule',p_schedule);
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_automation_run(p_jobid bigint, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE cmd text; nm text; ok boolean := true; msg text := '';
BEGIN
  SELECT command, jobname INTO cmd, nm FROM cron.job WHERE jobid = p_jobid;
  IF cmd IS NULL THEN RETURN jsonb_build_object('ok',false,'error','job_not_found'); END IF;
  BEGIN EXECUTE cmd; EXCEPTION WHEN others THEN ok := false; msg := SQLERRM; END;
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'automation_run','cron_job',p_jobid::text,jsonb_build_object('jobname',nm,'error',msg),ok);
  RETURN jsonb_build_object('ok',ok,'error',nullif(msg,''));
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_automation_set_active(p_jobid bigint, p_active boolean, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE nm text;
BEGIN
  SELECT jobname INTO nm FROM cron.job WHERE jobid = p_jobid;
  IF nm IS NULL THEN RETURN jsonb_build_object('ok',false,'error','job_not_found'); END IF;
  PERFORM cron.alter_job(job_id := p_jobid, active := p_active);
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'automation_active','cron_job',p_jobid::text,jsonb_build_object('jobname',nm,'active',p_active),true);
  RETURN jsonb_build_object('ok',true,'active',p_active);
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_catalog_get(p_category text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'category', cs.category,
    'label', coalesce(cs.label, cs.category),
    'fields', coalesce(cs.fields, '[]'::jsonb),
    'spec_group', g.grp,
    'specs', (select coalesce(jsonb_agg(jsonb_build_object(
        'id', q.id, 'aspect', q.aspect, 'label', q.label, 'match_regex', q.match_regex,
        'mandatory', q.mandatory, 'note', coalesce(q.note,'')) order by q.mandatory desc, q.aspect), '[]'::jsonb)
      from public.category_quote_specs q where q.spec_group = g.grp)
  )
  from public.category_specs cs, lateral (select public.fn_quote_spec_group(cs.category) as grp) g
  where cs.category = p_category;
$function$


CREATE OR REPLACE FUNCTION public.fn_os_catalog_list()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'category', cs.category,
    'label', coalesce(cs.label, cs.category),
    'n_fields', coalesce(jsonb_array_length(cs.fields), 0),
    'spec_group', public.fn_quote_spec_group(cs.category),
    'n_specs', (select count(*) from public.category_quote_specs q where q.spec_group = public.fn_quote_spec_group(cs.category))
  ) order by cs.category), '[]'::jsonb)
  from public.category_specs cs;
$function$


CREATE OR REPLACE FUNCTION public.fn_os_catalog_save_fields(p_category text, p_fields jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE oldf jsonb;
BEGIN
  IF jsonb_typeof(p_fields) <> 'array' THEN RETURN jsonb_build_object('ok',false,'error','fields_must_be_a_list'); END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_fields) e
             WHERE jsonb_typeof(e) <> 'object' OR coalesce(e->>'question','')='' OR coalesce(e->>'key','')='') THEN
    RETURN jsonb_build_object('ok',false,'error','each_question_needs_a_key_and_question_text'); END IF;
  SELECT fields INTO oldf FROM public.category_specs WHERE category = p_category;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','category_not_found'); END IF;
  UPDATE public.category_specs SET fields = p_fields, updated_at = now() WHERE category = p_category;
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'catalog_save_fields','category',p_category,
          jsonb_build_object('n_fields', jsonb_array_length(p_fields)), true);
  RETURN jsonb_build_object('ok',true,'n_fields', jsonb_array_length(p_fields));
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_catalog_spec_delete(p_id bigint, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE g text; a text;
BEGIN
  SELECT spec_group, aspect INTO g, a FROM public.category_quote_specs WHERE id=p_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','spec_not_found'); END IF;
  DELETE FROM public.category_quote_specs WHERE id=p_id;
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'catalog_spec_delete','quote_spec',p_id::text,jsonb_build_object('spec_group',g,'aspect',a), true);
  RETURN jsonb_build_object('ok',true);
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_catalog_spec_upsert(p_id bigint, p_spec_group text, p_aspect text, p_label text, p_regex text, p_mandatory boolean, p_note text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE newid bigint;
BEGIN
  IF coalesce(p_spec_group,'')='' OR coalesce(p_aspect,'')='' OR coalesce(p_label,'')='' OR coalesce(p_regex,'')='' THEN
    RETURN jsonb_build_object('ok',false,'error','group_aspect_label_and_pattern_required'); END IF;
  BEGIN PERFORM regexp_match('validation probe', p_regex);
  EXCEPTION WHEN others THEN RETURN jsonb_build_object('ok',false,'error','invalid_pattern: '||SQLERRM); END;
  IF p_id IS NOT NULL AND p_id > 0 THEN
    UPDATE public.category_quote_specs SET spec_group=p_spec_group, aspect=p_aspect, label=p_label, match_regex=p_regex, mandatory=coalesce(p_mandatory,false), note=nullif(p_note,'')
      WHERE id=p_id RETURNING id INTO newid;
    IF newid IS NULL THEN RETURN jsonb_build_object('ok',false,'error','spec_not_found'); END IF;
  ELSE
    INSERT INTO public.category_quote_specs(spec_group,aspect,label,match_regex,mandatory,note)
      VALUES (p_spec_group,p_aspect,p_label,p_regex,coalesce(p_mandatory,false),nullif(p_note,'')) RETURNING id INTO newid;
  END IF;
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'catalog_spec_upsert','quote_spec',newid::text,
          jsonb_build_object('spec_group',p_spec_group,'aspect',p_aspect,'mandatory',coalesce(p_mandatory,false)), true);
  RETURN jsonb_build_object('ok',true,'id',newid);
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_catalog_test_gate(p_category text, p_sample text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE grp text; res jsonb;
BEGIN
  grp := public.fn_quote_spec_group(p_category);
  WITH asp AS (
    SELECT q.aspect, q.label, q.mandatory,
           (CASE WHEN coalesce(p_sample,'') = '' THEN false ELSE p_sample ~* q.match_regex END) AS matched
    FROM public.category_quote_specs q WHERE q.spec_group = grp
  )
  SELECT jsonb_build_object(
    'category', p_category, 'spec_group', grp,
    'aspects', coalesce((select jsonb_agg(jsonb_build_object('aspect',aspect,'label',label,'mandatory',mandatory,'matched',matched) order by mandatory desc, aspect) from asp),'[]'::jsonb),
    'total', (select count(*) from asp),
    'matched_count', (select count(*) from asp where matched),
    'mandatory_missing', coalesce((select jsonb_agg(label order by label) from asp where mandatory and not matched),'[]'::jsonb),
    'passes', (select coalesce(bool_and(matched),true) from asp where mandatory)
  ) INTO res;
  RETURN res;
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_command()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_health jsonb; v_ops jsonb; v_counts jsonb; v_attention jsonb; v_pipeline jsonb;
begin
  v_health := to_jsonb(fn_health_index());
  v_ops    := to_jsonb(fn_ops_dashboard());

  select jsonb_build_object(
    'suppliers_total', (select count(*) from leads),
    'rfqs_total',      (select count(*) from inquiries),
    'rfqs_active',     (select count(*) from inquiries where status = 'quoted'),
    'rfqs_revealed',   (select count(*) from inquiries where status = 'revealed'),
    'rfqs_cancelled',  (select count(*) from inquiries where status = 'cancelled'),
    'quotes_total',    (select count(*) from quotes),
    'decisions_7d',    (select count(*) from decision_log where created_at > now() - interval '7 days'),
    'decisions_24h',   (select count(*) from decision_log where created_at > now() - interval '24 hours')
  ) into v_counts;

  select jsonb_build_object(
    'sent',      (select count(*) from inquiries where status = 'sent' and parent_inquiry_id is null),
    'matched',   (select count(distinct im.inquiry_id) from inquiry_matches im join inquiries i on i.id = im.inquiry_id where i.status = 'sent'),
    'quoted',    (select count(*) from inquiries where status = 'quoted'),
    'revealed',  (select count(*) from inquiries where status = 'revealed'),
    'completed', (select count(*) from inquiries where status in ('completed','won'))
  ) into v_pipeline;

  -- THE ESCALATIONS LOG. decision_log is append-only by trigger and carries 721 dependent rows, so
  -- it cannot be emptied; this reads forward from the fresh-start watermark instead. The records
  -- are all still there and still queryable — they are off the founder's screen, not gone.
  select coalesce(jsonb_agg(x order by created_at desc), '[]'::jsonb) into v_attention
  from (
    select id, actor, kind, decision, confidence, route_to, created_at,
           jsonb_build_object('id', id, 'actor', actor, 'kind', kind,
             'kind_label', public.fn_ui_label('action_kind', kind), 'decision', decision,
             'policies', public.fn_action_policies(kind, confidence),
             'confidence', confidence, 'route_to', route_to, 'created_at', created_at,
             'os', public.fn_owning_os(actor),
             'reasons', reasons,
             'alternatives', alternatives,
             'outcome', case when exists (select 1 from public.agent_actions a where a.decision_log_id = decision_log.id)
                  then (select coalesce(a.status,'recorded') || ' — ' || coalesce(a.title,'action taken')
                          from public.agent_actions a where a.decision_log_id = decision_log.id
                         order by a.created_at desc limit 1)
                  else 'held for ' || coalesce(route_to,'review') || ', no follow-up action recorded since ' || created_at::date end
           ) as x
    from decision_log
    where route_to is not null and route_to <> 'auto'
      and created_at >= public.fn_os_fresh_start_at()
      -- HELD FOR REVIEW MEANS SOMETHING IS STILL WAITING ON A HUMAN. This card had no such test:
      -- it listed every routed decision, so a decision whose action had been cancelled or already
      -- decided still sat under the heading "held for review". The founder found one this way
      -- immediately after the stand-down - decision_log 2627, the audit trail of the same
      -- agent_action the stand-down had cancelled at the same microsecond.
      --
      -- decision_log is append-only by trigger, so the row cannot be edited or removed and should
      -- not be: it is the record that the gate ran. What was wrong is the claim made about it.
      -- A decision is held only while its action is open; a decision that never produced an action
      -- was never queued for anyone and does not belong on a review list either.
      and exists (select 1 from public.agent_actions a
                   where a.decision_log_id = decision_log.id
                     and a.status in ('pending','needs_review'))
    order by created_at desc limit 8
  ) z;

  return jsonb_build_object(
    'health', v_health, 'health_index', v_health->>'index',
    'ops', v_ops, 'counts', v_counts, 'pipeline', v_pipeline,
    'attention', v_attention, 'generated_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_os_dashboard_viz()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  out jsonb := '{}'::jsonb;
  v_total bigint; v_contacted bigint; v_invited bigint; v_claimed bigint;
  v_registered bigint; v_verified bigint; v_approved bigint;
  v_runs24 bigint; v_agents24 bigint; v_failed24 bigint;
  j_sector jsonb; j_emirate jsonb; j_invites jsonb; j_agents jsonb; j_funnel jsonb; j_pipeline jsonb;
begin
  select count(*) into v_total from leads;
  select count(*) into v_contacted from leads where contacted is true;
  select count(*) into v_invited from leads where invited_at is not null;
  select count(*) into v_claimed from leads where claimed is true;
  select count(*) into v_registered from leads where registration_submitted_at is not null;
  select count(*) into v_verified from leads where verified is true;
  select count(*) into v_approved from leads where approved_at is not null;

  -- agent activity from agent_runs (the same source the header/Smart Engine use)
  begin
    select count(*) filter (where started_at > now() - interval '24 hours'),
           count(distinct agent) filter (where started_at > now() - interval '24 hours'),
           count(*) filter (where started_at > now() - interval '24 hours' and status in ('error','failed'))
      into v_runs24, v_agents24, v_failed24 from agent_runs;
    select coalesce(jsonb_agg(x), '[]'::jsonb) into j_agents from (
      select agent as label, count(*)::int as n
      from agent_runs where started_at > now() - interval '24 hours'
      group by agent order by count(*) desc limit 8
    ) x;
  exception when others then v_runs24 := 0; v_agents24 := 0; v_failed24 := 0; j_agents := '[]'::jsonb; end;

  select coalesce(jsonb_agg(x), '[]'::jsonb) into j_sector from (
    select coalesce(nullif(trim(sector),''),'unspecified') as label, count(*)::int as n
    from leads group by 1 order by count(*) desc limit 12
  ) x;

  select coalesce(jsonb_agg(x), '[]'::jsonb) into j_emirate from (
    select coalesce(nullif(trim(emirate),''),'unknown') as label, count(*)::int as n
    from leads group by 1 order by count(*) desc limit 9
  ) x;

  select coalesce(jsonb_agg(jsonb_build_object('d', to_char(d.day,'Mon DD'), 'n', coalesce(c.n,0)) order by d.day), '[]'::jsonb)
    into j_invites
  from (select generate_series((current_date - interval '13 days')::date, current_date, interval '1 day')::date as day) d
  left join (select invited_at::date as day, count(*)::int as n from leads where invited_at > now() - interval '14 days' group by 1) c
    on c.day = d.day;

  j_funnel := jsonb_build_array(
    jsonb_build_object('stage','Sourced', 'n', v_total),
    jsonb_build_object('stage','Contacted', 'n', v_contacted),
    jsonb_build_object('stage','Invited', 'n', v_invited),
    jsonb_build_object('stage','Claimed', 'n', v_claimed),
    jsonb_build_object('stage','Registered', 'n', v_registered),
    jsonb_build_object('stage','Verified', 'n', v_verified),
    jsonb_build_object('stage','Approved', 'n', v_approved)
  );

  begin
    j_pipeline := jsonb_build_array(
      jsonb_build_object('stage','New', 'n', (select count(*) from inquiries)),
      jsonb_build_object('stage','Matched', 'n', (select count(distinct inquiry_id) from quotes)),
      jsonb_build_object('stage','Quoted', 'n', (select count(*) from quotes)),
      jsonb_build_object('stage','Revealed', 'n', (select count(*) from quotes where coalesce(revealed,false) is true)),
      jsonb_build_object('stage','Won', 'n', (select count(*) from inquiries where status = 'won'))
    );
  exception when others then j_pipeline := jsonb_build_array(); end;

  out := jsonb_build_object(
    'headline', jsonb_build_object(
      'suppliers_total', v_total, 'invited_total', v_invited, 'verified_total', v_verified,
      'approved_total', v_approved, 'registered_total', v_registered,
      'agents_active_24h', v_agents24, 'runs_24h', v_runs24, 'runs_failed_24h', v_failed24),
    'funnel', j_funnel,
    'pipeline', j_pipeline,
    'by_sector', j_sector,
    'by_emirate', j_emirate,
    'invites_14d', j_invites,
    'agents_24h', j_agents,
    'generated_at', to_char(now(),'YYYY-MM-DD"T"HH24:MI:SSOF')
  );
  return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_os_detail(p_entity text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_tbl text; v_idcol text := 'id'; v_row jsonb;
begin
  case p_entity
    when 'inquiries' then v_tbl:='inquiries';
    when 'quotes' then v_tbl:='quotes';
    when 'transactions' then v_tbl:='transactions';
    when 'customers' then v_tbl:='customers';
    when 'suppliers' then v_tbl:='leads';
    when 'agent_actions' then v_tbl:='agent_actions';
    when 'doc_reviews' then v_tbl:='doc_reviews';
    when 'kb_revisions' then v_tbl:='kb_revisions';
    when 'inbox' then v_tbl:='inbound_messages';
    when 'documents' then v_tbl:='documents';
    when 'dropbox' then v_tbl:='dropbox_files';
    when 'invoices' then v_tbl:='reveal_invoices'; v_idcol:='transaction_id';
    when 'notifications' then v_tbl:='notifications';
    when 'tasks' then v_tbl:='crm_tasks';
    when 'po' then v_tbl:='po_orders';
    when 'expenses' then v_tbl:='expenses';
    when 'agent_runs' then v_tbl:='agent_runs';
    when 'fraud' then v_tbl:='fraud_flags'; v_idcol:='subject_id';
    else return jsonb_build_object('error','unknown_entity');
  end case;
  execute format('select to_jsonb(t) from %I t where %I::text = %L limit 1', v_tbl, v_idcol, p_id) into v_row;
  if v_row is null then return jsonb_build_object('error','not_found'); end if;
  return jsonb_build_object('entity',p_entity,'record',v_row);
end $function$


CREATE OR REPLACE FUNCTION public.fn_os_fresh_start_at()
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select coalesce((select f.effective_from from public.os_fresh_start f
                    order by f.effective_from desc, f.id desc limit 1),
                  '-infinity'::timestamptz);
$function$


CREATE OR REPLACE FUNCTION public.fn_os_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE res jsonb;
BEGIN
  SELECT jsonb_build_object(
    'generated_at', now(),
    'failing_crons', coalesce((
      SELECT jsonb_agg(jsonb_build_object('job', j.jobname, 'status', lr.status, 'when', lr.end_time,
                                          'message', left(coalesce(lr.return_message,''),160))
                       ORDER BY lr.end_time DESC)
      FROM (SELECT DISTINCT ON (jobid) jobid, status, end_time, return_message
              FROM cron.job_run_details
             WHERE start_time > now() - interval '7 days'
             ORDER BY jobid, start_time DESC) lr
      JOIN cron.job j ON j.jobid = lr.jobid
      WHERE lr.status = 'failed' AND lr.end_time > now() - interval '24 hours'
    ), '[]'::jsonb),
    'agent_errors_24h', (SELECT count(*) FROM public.agent_runs WHERE status='error' AND started_at > now() - interval '24 hours'),
    'top_error_agents', coalesce((SELECT jsonb_agg(x) FROM (SELECT jsonb_build_object('agent',agent,'errors',count(*)) x FROM public.agent_runs WHERE status='error' AND started_at > now()-interval '24 hours' GROUP BY agent ORDER BY count(*) DESC LIMIT 6) q),'[]'::jsonb),
    'health_check_fails_24h', (SELECT count(*) FROM public.health_checks WHERE ok=false AND created_at > now()-interval '24 hours'),
    'ai_health_fails', coalesce((SELECT value FROM public.app_secrets WHERE key='ai_health_fails'),'0'),
    'payments_7d_count', (SELECT count(*) FROM public.transactions WHERE revealed_at > now()-interval '7 days'),
    'payments_7d_revenue_aed', coalesce((SELECT round(sum(reveal_fee)::numeric,2) FROM public.transactions WHERE revealed_at > now()-interval '7 days'),0),
    -- CAN A REQUEST REACH ANYONE? Each number is counted at the gate it actually has to pass, so
    -- the drop between them says WHERE the reach is lost rather than only that it is small.
    'supplier_reach', jsonb_build_object(
      'leads', (SELECT count(*) FROM public.leads),
      'with_capability', (SELECT count(*) FROM public.supplier_capabilities WHERE coalesce(cardinality(trades),0) > 0),
      'confirmed', (SELECT count(*) FROM public.supplier_capabilities WHERE confirmed_at IS NOT NULL),
      -- the real ceiling: confirmed AND the lead itself still admissible to matching
      'matchable_now', (
        SELECT count(*) FROM public.supplier_capabilities sc
        JOIN public.leads l ON l.id = sc.supplier_id
        WHERE sc.confirmed_at IS NOT NULL
          AND coalesce(cardinality(sc.trades),0) > 0
          AND public.fn_is_matchable(l.verified, l.banned, l.matching_blocked,
                                     l.approval_status, l.permanently_closed, l.chat_strikes)),
      'meaning', 'matchable_now is the most suppliers the structured matcher can shortlist for any request. fn_match_capability requires a supplier to have CONFIRMED their own scope; that gate is deliberate. When this is far below with_capability the shortage is confirmations, not suppliers.'
    )
  ) INTO res;
  RETURN res;
END
$function$


CREATE OR REPLACE FUNCTION public.fn_os_health_brief()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_period text; v_n int := 0; v_pool int := 0;
begin
  -- ---------------------------------------------------------------------------------------
  -- 1. ONE CAPACITY ROW PER ACTIVE OS, in the one unit every OS has: its own people's
  -- attention. The seed carried a single company-wide row (550 open tasks, keyed to
  -- leadership), which is why six operating systems reported no capacity at all. Both sides
  -- are measured live — org_agents.max_open_tasks is the declared ceiling, org_tasks the
  -- load — so this figure moves on its own and is falsifiable by looking at the org.
  delete from resource_pool where source_ref = 'org_agents.max_open_tasks';

  insert into resource_pool (resource, kind, owner_dept, unit, capacity, committed,
                             window_label, degrade_at_pct, halt_at_pct, source_ref, note, os_key)
  select 'Employee attention - ' || o.name, 'capacity',
         (select min(od.dept_key) from os_department od where od.os_key = o.os_key),
         'open tasks',
         coalesce((select sum(a.max_open_tasks) from os_department od
                     join org_agents a on a.department = od.dept_key and a.active
                    where od.os_key = o.os_key), 0),
         coalesce((select count(*) from os_department od
                     join org_tasks t on t.dept_key = od.dept_key and t.status <> 'done'
                    where od.os_key = o.os_key), 0),
         'rolling', 80, 100, 'org_agents.max_open_tasks',
         'Open tasks in this OS''s departments against the sum of max_open_tasks for its '
         || 'active staff. Refreshed weekly by fn_os_health_brief.', o.os_key
    from operating_system o where o.active;
  get diagnostics v_pool = row_count;

  -- 2. EVERY OTHER POOLED RESOURCE GETS A MEASURED NUMERATOR TOO. Each expression is the
  -- system of record for that resource; a resource whose consumption nothing records would
  -- otherwise sit at zero for ever and drag the OS's ratio down with it, which is the same
  -- "populated but never measured" defect one level down.
  update resource_pool rp set committed = m.v, updated_at = now()
    from (values
      ('AI token budget - company',
        (select coalesce(sum(cost_aed), 0)::numeric from ai_cost_log
          where occurred_at >= date_trunc('month', now()))),
      ('Supplier invites',
        (select coalesce(sum(sent), 0)::numeric from invite_schedule where day = current_date)),
      ('Outbound email',
        (select count(*)::numeric from notifications
          where coalesce(channel, 'email') = 'email' and created_at > now() - interval '1 day')),
      ('WhatsApp / SMS',
        (select count(*)::numeric from wa_messages where created_at > now() - interval '1 day')
      + (select count(*)::numeric from notifications
          where channel in ('sms', 'whatsapp') and created_at > now() - interval '1 day')),
      -- A FLOOR, NOT A TOTAL: this counts the scheduled invocations, which is every edge call
      -- the database itself can see. Browser and webhook traffic is not in cron.job_run_details.
      ('Edge function invocations',
        (select count(*)::numeric from cron.job_run_details d
           join cron.job j on j.jobid = d.jobid
          where j.command ~* 'net\.http_post' and d.start_time >= date_trunc('month', now()))),
      ('Database storage',
        round(pg_database_size(current_database()) / 1073741824.0, 2)::numeric),
      ('Document storage',
        (select round(coalesce(sum((o.metadata->>'size')::bigint), 0) / 1073741824.0, 2)::numeric
           from storage.objects o)),
      ('Scraping / enrichment',
        (select coalesce(sum(fetched), 0)::numeric from scrape_runs
          where created_at >= date_trunc('month', now()))),
      ('Payment processing',
        (select count(*)::numeric from transactions where revealed_at > now() - interval '1 day'))
    ) as m(resource, v)
   where rp.resource = m.resource;

  -- 3. The report is computed FROM those inputs, so recompute it now that they are current.
  -- Without this the week's capacity_pct would be derived from last Monday's numerator.
  perform fn_os_review();

  -- ---------------------------------------------------------------------------------------
  select max(period) into v_period from os_review;
  if v_period is null then
    return jsonb_build_object('written', 0, 'reason', 'os_review is empty');
  end if;

  -- Only active OSes with an ACTIVE owner: a brief addressed to a departed employee is another
  -- write with no reader, which is the defect this function exists to close.
  for r in
    select o.os_key, o.name, o.owner_agent, rv.health, rv.metrics
      from operating_system o
      join os_review rv  on rv.os_key = o.os_key and rv.period = v_period
      join org_agents  a on a.agent_key = o.owner_agent and a.active
     where o.active
     order by o.num
  loop
    -- Scoped to this function's own rows by source, so it can never touch a memory it did not
    -- write. This is what makes the weekly run idempotent instead of cumulative.
    delete from agent_memory
     where agent_key = r.owner_agent and source = 'fn_os_health_brief';

    -- ->> everywhere, never ->. text || jsonb resolves to jsonb || jsonb and silently builds an
    -- array instead of a sentence; that has already cost this project two call-time failures.
    insert into agent_memory (agent_key, kind, content, source, importance, horizon)
    values (r.owner_agent, 'os_health',
      'OS HEALTH, week ' || v_period || ' - ' || r.name || ' (' || r.os_key || '), which you own. '
      || 'HEALTH SCORE ' || coalesce(r.metrics->>'health_score', '?') || '/100 ('
        || coalesce(r.health, 'unrated') || '). '
      || 'RISK: open_risks ' || coalesce(r.metrics->>'open_risks', '0') || '. '
      || 'PERFORMANCE: kpi_gaps ' || coalesce(r.metrics->>'kpi_gaps', '0') || ' against '
        || coalesce(r.metrics->>'kpis', '0') || ' KPI(s). '
      || 'CAPACITY: capacity_pct ' || coalesce(r.metrics->>'capacity_pct', 'unmeasured') || '%. '
      || 'BACKLOG: ' || coalesce(r.metrics->>'open_tasks', '0') || ' open, stale_tasks '
        || coalesce(r.metrics->>'stale_tasks', '0') || ', backlog_per_head '
        || coalesce(r.metrics->>'backlog_per_head', '0') || '. '
      || 'QUALITY: review_pass_pct ' || coalesce(r.metrics->>'review_pass_pct', 'unmeasured') || '%. '
      || 'COST: budget_pct ' || coalesce(r.metrics->>'budget_pct', '0') || '% of the AI budget. '
      || 'AUTOMATION: needs_founder_pct ' || coalesce(r.metrics->>'needs_founder_pct', '0')
        || '% of open work still needs the founder. '
      || 'Act on the worst figure before it becomes a finding.',
      'fn_os_health_brief', 7, 'short');

    v_n := v_n + 1;
  end loop;

  return jsonb_build_object('period', v_period, 'written', v_n, 'capacity_rows', v_pool);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_os_improve()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int := 0; q text; qs text[];
  v_failed int; v_slow int; v_cost numeric; v_manual int; v_dead int;
begin
  for r in select o.os_key, o.name, o.owner_agent,
                  coalesce((select department from org_agents a where a.agent_key=o.owner_agent),'exec') as dept
           from operating_system o where o.active
  loop
    qs := array[]::text[];

    select count(*) into v_failed from agent_runs ar
      join os_department od on od.os_key = r.os_key
      join org_agents a on a.department = od.dept_key and a.agent_key = ar.agent
     where ar.status='error' and ar.started_at > now()-interval '7 days';

    select count(*) into v_slow from org_tasks t join os_department od on od.dept_key=t.dept_key
     where od.os_key=r.os_key and t.status<>'done' and t.created_at < now()-interval '14 days';

    select coalesce(sum(c.cost_aed),0) into v_cost from ai_cost_log c
      join os_department od on od.dept_key = c.dept_key
     where od.os_key = r.os_key and c.occurred_at > now()-interval '7 days';

    select count(*) into v_manual from org_tasks t join os_department od on od.dept_key=t.dept_key
     where od.os_key=r.os_key and t.needs_founder;

    select count(*) into v_dead from workflow w where w.os_key=r.os_key and not w.active;

    if v_failed > 0 then qs := array_append(qs,'What failed? '||v_failed||' agent run(s) errored this week in '||r.name||'. Root cause each one.'); end if;
    if v_slow   > 0 then qs := array_append(qs,'What slowed us? '||v_slow||' task(s) have been open over 14 days in '||r.name||'. Why has none closed?'); end if;
    if v_cost   > 0 then qs := array_append(qs,'What cost too much? '||r.name||' spent '||round(v_cost,2)||' AED on AI this week. Which calls could a cheaper model have served?'); end if;
    if v_manual > 0 then qs := array_append(qs,'What can be automated? '||v_manual||' task(s) in '||r.name||' still need the founder. Which of those is a rule rather than a judgement?'); end if;
    if v_dead   > 0 then qs := array_append(qs,'What should be deleted? '||v_dead||' inactive workflow(s) remain in '||r.name||'. Retire or revive them.'); end if;

    foreach q in array qs loop
      insert into org_tasks (dept_key,title,detail,status,tier,needs_founder,action_class)
      select r.dept, left(r.name||' improvement: '||q, 120),
             q||E'\n\nOwner: '||coalesce(r.owner_agent,'unassigned')||'. Answer with evidence. If the answer implies a change, open it through fn_outcome_open so it is graded against a baseline.',
             'proposed','advisory',false,'recommend'
      where not exists (select 1 from org_tasks t where t.title = left(r.name||' improvement: '||q,120) and t.status<>'done');
      if found then
        n := n+1;
        perform public.fn_emit('improvement.proposed','operating_system', r.os_key,
                  coalesce(r.owner_agent,'system'), jsonb_build_object('question', q, 'os', r.name));
      end if;
    end loop;
  end loop;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('os_improve',now(),now(),'ok',jsonb_build_object('questions',n),
    'Continuous improvement: '||n||' question(s) raised across the ten operating systems.');
  return jsonb_build_object('questions',n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_os_incident_list(p_status text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',id,'title',title,'kind',kind,'severity',severity,'status',status,
    'description',detail->>'description','opened_by',opened_by,'opened_at',opened_at,
    'resolved_at',resolved_at,'resolution',resolution) order by (status='open') desc, opened_at desc), '[]'::jsonb)
  from public.os_incidents
  where p_status is null or p_status='' or status = p_status;
$function$


CREATE OR REPLACE FUNCTION public.fn_os_incident_open(p_title text, p_kind text, p_severity text, p_detail jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE nid bigint;
BEGIN
  IF coalesce(p_title,'')='' THEN RETURN jsonb_build_object('ok',false,'error','title_required'); END IF;
  INSERT INTO public.os_incidents(title, kind, severity, detail, opened_by)
  VALUES (p_title, coalesce(nullif(p_kind,''),'other'), coalesce(nullif(p_severity,''),'medium'), coalesce(p_detail,'{}'::jsonb), coalesce(p_actor,'os'))
  RETURNING id INTO nid;
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'incident_open','incident',nid::text,jsonb_build_object('title',p_title,'severity',p_severity),true);
  BEGIN
    PERFORM net.http_post(
      url := 'https://' || public.qd_project_ref() || '.supabase.co/functions/v1/alert_founder',
      headers := jsonb_build_object('Content-Type','application/json'),
      body := jsonb_build_object('__secret',(select value from public.app_secrets where key='cred_db_internal'),
                                 'event','OS incident #'||nid||' ('||coalesce(p_severity,'medium')||'): '||p_title,
                                 'detail',left(coalesce(p_detail->>'description',''),300),'level','action')
    );
  EXCEPTION WHEN others THEN /* notification is best-effort */ END;
  RETURN jsonb_build_object('ok',true,'id',nid);
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_incident_resolve(p_id bigint, p_resolution text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.os_incidents SET status='resolved', resolved_by=coalesce(p_actor,'os'), resolved_at=now(), resolution=nullif(p_resolution,'')
  WHERE id=p_id AND status <> 'resolved';
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','not_found_or_already_resolved'); END IF;
  INSERT INTO public.os_audit_log(actor,action,entity,entity_id,detail,ok)
  VALUES (coalesce(p_actor,'os'),'incident_resolve','incident',p_id::text,jsonb_build_object('resolution',p_resolution),true);
  RETURN jsonb_build_object('ok',true);
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_knowledge_query(p_os_key text, p_topic text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare out text := ''; r record; v_line text; v_n int := 0;
begin
  if coalesce(p_os_key,'') = '' then return ''; end if;

  -- The routing table: every domain this OS is recorded as querying, and the OS that owns it.
  -- Restricted to domains that actually have an owner — a 'queries' row pointing at a domain
  -- nobody owns is a gap for fn_knowledge_gaps to report, not an address to send an employee to.
  for r in
    select k.domain_key,
           o.os_key   as owner_os,
           o2.name    as owner_name,
           o2.owner_agent
      from os_knowledge_domain k
      join os_knowledge_domain o
        on o.domain_key = k.domain_key and o.ownership = 'owns' and o.os_key <> k.os_key
      left join operating_system o2 on o2.os_key = o.os_key
     where k.os_key = p_os_key
       and k.ownership <> 'owns'
       and (p_topic is null or k.domain_key ilike '%'||p_topic||'%')
     order by o.os_key, k.domain_key
     limit 40
  loop
    -- operating_system.name already reads "Commercial OS"; only the raw key needs the suffix.
    out := out || '- ' || r.domain_key || ' -> ask ' || coalesce(r.owner_name, r.owner_os || ' OS')
               || coalesce(' (' || r.owner_agent || ')', '') || E'\n';
    v_n := v_n + 1;
  end loop;

  if v_n = 0 then return ''; end if;

  -- With a topic, also carry what the OWNER actually knows, so "query it" is an answer and not a
  -- forwarding address. Sourced from the owning OS's own employees' published knowledge.
  if p_topic is not null then
    select string_agg('  · ' || z.topic || ': ' || left(z.content, 240), E'\n')
      into v_line
      from (select distinct ak.topic, ak.content
              from os_knowledge_domain owns
              join os_department d on d.os_key = owns.os_key
              join org_agents a on a.department = d.dept_key and a.active
              join agent_knowledge ak on ak.agent_key = a.agent_key
             where owns.ownership = 'owns'
               and owns.domain_key ilike '%'||p_topic||'%'
               and coalesce(ak.layer,'profession') in ('profession','state')
               and (ak.topic ilike '%'||p_topic||'%' or ak.content ilike '%'||p_topic||'%')
             limit 4) z;
    if v_line is not null then
      out := out || 'What the owning OS publishes on "' || p_topic || '":' || E'\n' || v_line || E'\n';
    end if;
  end if;

  return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_os_list(p_entity text, p_params jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_tbl text; v_cols text; v_search text[]; v_status text; v_order text; v_idcol text := 'id';
  v_q text := coalesce(nullif(trim(p_params->>'q'),''), null);
  v_st text := coalesce(nullif(trim(p_params->>'status'),''), null);
  v_limit int := least(coalesce((p_params->>'limit')::int, 60), 300);
  v_offset int := greatest(coalesce((p_params->>'offset')::int, 0), 0);
  v_where text := ' where true'; v_rows jsonb; v_total bigint; v_sql text; v_fk text; v_fv text;
begin
  case p_entity
    when 'inquiries' then v_tbl:='inquiries'; v_cols:='id,category,emirate,status,pipeline_stage,scope_type,budget,expected_value,rfq_ready,customer_id,hired_supplier_id,outcome,created_at'; v_search:=array['category','emirate','summary','role_needed']; v_status:='status'; v_order:=' order by created_at desc';
    when 'quotes' then v_tbl:='quotes'; v_cols:='id,inquiry_id,supplier_id,quote_amount,customer_price,app_fee,status,review_status,lead_time,warranty,created_at,expires_at'; v_search:=array['notes','scope','payment_terms']; v_status:='status'; v_order:=' order by created_at desc';
    when 'transactions' then v_tbl:='transactions'; v_cols:='id,inquiry_id,supplier_id,customer_id,quote_amount,reveal_fee,app_fee,fee_status,refund_status,revealed_at,payment_ref'; v_search:=array['payment_ref','refund_reason']; v_status:='fee_status'; v_order:=' order by revealed_at desc nulls last';
    when 'customers' then v_tbl:='customers'; v_cols:='id,full_name,email,phone,email_verified,phone_verified,banned,chat_strikes,locale,created_at'; v_search:=array['full_name','email','phone']; v_status:=null; v_order:=' order by created_at desc';
    when 'suppliers' then v_tbl:='leads'; v_cols:='id,company_name,sector,emirate,city,approval_status,verification_status,verified,matching_blocked,banned,rating,app_rating,capability_score,registration_status,contact_name,email,phone,created_at'; v_search:=array['company_name','email','sector','phone']; v_status:='approval_status'; v_order:=' order by created_at desc';
    when 'agent_actions' then v_tbl:='agent_actions'; v_cols:='id,agent,kind,title,status,risk,confidence,target_table,target_id,escalated,created_at,decided_at,decided_by'; v_search:=array['title','recommendation','agent','kind']; v_status:='status'; v_order:=' order by (status=''pending'') desc, created_at desc';
    when 'doc_reviews' then v_tbl:='doc_reviews'; v_cols:='id,from_email,subject,file_name,ai_category,ai_suggested_field,ai_confidence,status,auto_applied,created_at,file_path'; v_search:=array['subject','from_email','file_name','ai_category']; v_status:='status'; v_order:=' order by created_at desc';
    when 'kb_revisions' then v_tbl:='kb_revisions'; v_cols:='id,entry_kind,entry_ref,version,status,author,reviewer,created_at,decided_at'; v_search:=array['entry_ref','entry_kind','author']; v_status:='status'; v_order:=' order by created_at desc';
    when 'inbox' then v_tbl:='inbound_messages'; v_cols:='id,from_email,to_email,subject,ai_category,needs_review,attachments_count,replied_at,created_at'; v_search:=array['subject','from_email','ai_summary']; v_status:='ai_category'; v_order:=' order by created_at desc';
    when 'documents' then v_tbl:='documents'; v_cols:='id,file_name,kind,ref_table,ref_id,mime,status,indexed,bucket,path,created_at'; v_search:=array['file_name','kind','ref_table']; v_status:='status'; v_order:=' order by created_at desc';
    when 'dropbox' then v_tbl:='dropbox_files'; v_cols:='id,path,name,is_folder,size,server_modified,synced_at'; v_search:=array['path','name']; v_status:=null; v_order:=' order by is_folder desc, name asc';
    when 'invoices' then v_tbl:='reveal_invoices'; v_cols:='transaction_id,invoice_no,bucket,path,created_at'; v_search:=array['invoice_no']; v_status:=null; v_order:=' order by created_at desc'; v_idcol:='transaction_id';
    when 'notifications' then v_tbl:='notifications'; v_cols:='id,type,to_email,to_role,subject,status,channel,created_at,sent_at,last_error'; v_search:=array['subject','to_email','type']; v_status:='status'; v_order:=' order by created_at desc';
    when 'tasks' then v_tbl:='crm_tasks'; v_cols:='id,title,status,priority,entity,entity_id,due_date,created_at,done_at'; v_search:=array['title','detail']; v_status:='status'; v_order:=' order by (status<>''done'') desc, due_date asc nulls last';
    when 'notes' then v_tbl:='crm_notes'; v_cols:='id,entity,entity_id,body,author,created_at'; v_search:=array['body','author']; v_status:=null; v_order:=' order by created_at desc';
    when 'po' then v_tbl:='po_orders'; v_cols:='id,po_no,vendor_id,status,subtotal,currency,order_date,expected_date,approved_by,approved_at,created_at'; v_search:=array['po_no','memo']; v_status:='status'; v_order:=' order by created_at desc';
    when 'expenses' then v_tbl:='expenses'; v_cols:='id,vendor,category,description,amount,currency,cadence,expense_date,active,created_at'; v_search:=array['vendor','description','category']; v_status:=null; v_order:=' order by expense_date desc nulls last';
    when 'agent_runs' then v_tbl:='agent_runs'; v_cols:='id,agent,status,started_at,finished_at,note'; v_search:=array['agent','note']; v_status:='status'; v_order:=' order by started_at desc nulls last';
    when 'fraud' then v_tbl:='fraud_flags'; v_cols:='kind,subject_type,subject_id,severity,status,detail,created_at'; v_search:=array['kind','subject_type','subject_id']; v_status:='status'; v_order:=' order by created_at desc'; v_idcol:='subject_id';
    else return jsonb_build_object('error','unknown_entity','entity',p_entity);
  end case;

  if v_st is not null and v_status is not null then v_where := v_where || format(' and %I = %L', v_status, v_st); end if;
  if v_q is not null then
    v_where := v_where || ' and (' || array_to_string(array(select format('coalesce(%I::text,'''') ilike %L', c, '%'||v_q||'%') from unnest(v_search) c), ' or ') || ')';
  end if;
  if p_params ? 'filters' then
    for v_fk, v_fv in select key, value from jsonb_each_text(p_params->'filters') loop
      if v_fk = any(array['inquiry_id','supplier_id','customer_id','quote_id','ref_table','ref_id','agent','entity','entity_id','category','emirate','lead_id','vendor_id','target_table','target_id']) and position(v_fk in v_cols) > 0 and v_fv is not null then
        v_where := v_where || format(' and %I::text = %L', v_fk, v_fv);
      end if;
    end loop;
  end if;

  execute format('select count(*) from %I%s', v_tbl, v_where) into v_total;
  v_sql := format('select coalesce(jsonb_agg(to_jsonb(t)),''[]''::jsonb) from (select %s from %I%s%s limit %s offset %s) t', v_cols, v_tbl, v_where, v_order, v_limit, v_offset);
  execute v_sql into v_rows;
  return jsonb_build_object('entity',p_entity,'id_col',v_idcol,'columns',string_to_array(v_cols, ','),'total',v_total,'rows',v_rows);
end $function$


CREATE OR REPLACE FUNCTION public.fn_os_memory(p_q text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with b as (select coalesce(nullif(btrim(p_q), ''), '') q,
                    coalesce(p_from, '-infinity'::date) lo,
                    coalesce(p_to, 'infinity'::date) hi)
  select jsonb_build_object(
    'subject', (select q from b), 'from', p_from, 'to', p_to,

    -- Every decision about a subject, over a period.
    'decisions', coalesce((select jsonb_agg(jsonb_build_object(
          'id', l.id, 'actor', l.actor, 'kind', l.kind, 'decision', l.decision,
          'confidence', l.confidence, 'reasons', l.reasons, 'route_to', l.route_to, 'at', l.created_at)
        order by l.created_at desc)
      from (select l.* from public.decision_log l, b
             where (b.q = '' or l.decision ilike '%'||b.q||'%' or l.actor ilike '%'||b.q||'%'
                    or l.kind ilike '%'||b.q||'%' or l.ctx::text ilike '%'||b.q||'%')
               and l.created_at::date between b.lo and b.hi
             order by l.created_at desc limit 25) l), '[]'::jsonb),

    -- Why something was rejected: the recorded reasoning behind a past decision.
    'rejection_reason', coalesce((select jsonb_agg(jsonb_build_object(
          'id', d.id, 'problem', d.problem, 'recommendation', d.recommendation,
          'risks', d.risks, 'options', d.options, 'status', d.status,
          'decided_by', d.decided_by, 'actual_outcome', d.actual_outcome, 'at', d.created_at)
        order by d.created_at desc)
      from (select d.* from public.decision_record d, b
             where (b.q = '' or d.problem ilike '%'||b.q||'%' or d.recommendation ilike '%'||b.q||'%'
                    or d.context ilike '%'||b.q||'%')
               and d.created_at::date between b.lo and b.hi
             order by d.created_at desc limit 15) d), '[]'::jsonb),

    -- When something changed, and who changed it. undo_log is the row-level change history.
    'changes', coalesce((select jsonb_agg(jsonb_build_object(
          'id', u.id, 'table_name', u.table_name, 'row_id', u.row_id, 'op', u.op,
          'actor', u.actor, 'reverted', u.reverted, 'at', u.created_at)
        order by u.created_at desc)
      from (select u.* from public.undo_log u, b
             where (b.q = '' or u.table_name ilike '%'||b.q||'%' or u.actor ilike '%'||b.q||'%')
               and u.created_at::date between b.lo and b.hi
             order by u.created_at desc limit 25) u), '[]'::jsonb),
    'change_subjects', coalesce((select jsonb_agg(jsonb_build_object('table_name', t.table_name, 'n', t.n) order by t.n desc)
      from (select table_name, count(*) n from public.undo_log group by 1) t), '[]'::jsonb),

    -- Lessons, scoped to a period.
    'lessons', coalesce((select jsonb_agg(jsonb_build_object(
          'id', m.id, 'headline', m.headline, 'detail', left(m.detail, 300), 'outcome', m.outcome,
          'kind', m.kind, 'os_key', m.os_key, 'confidence', m.confidence, 'occurred_at', m.occurred_at)
        order by coalesce(m.occurred_at, m.created_at) desc)
      from (select m.* from public.institutional_memory m, b
             where (b.q = '' or m.headline ilike '%'||b.q||'%' or m.detail ilike '%'||b.q||'%'
                    or m.category_slug ilike '%'||b.q||'%')
               and coalesce(m.occurred_at, m.created_at)::date between b.lo and b.hi
             order by coalesce(m.occurred_at, m.created_at) desc limit 20) m), '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_os_nav()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'badges', jsonb_build_object(
      'approvals', (select count(*) from agent_actions where status='pending'),
      'tasks', (select count(*) from crm_tasks where coalesce(status,'') <> 'done'),
      'suppliers_review', (select count(*) from leads where coalesce(approval_status,'') in ('submitted','pending','under_review','pending_review')),
      'notifications', (select count(*) from notifications where coalesce(status,'') not in ('sent','delivered','read')),
      'knowledge_review', (select count(*) from kb_revisions where coalesce(status,'')='pending'),
      'documents_review', (select count(*) from doc_reviews where coalesce(status,'')='pending'),
      'disputes', (select count(*) from transactions where coalesce(refund_status,'') in ('requested','pending')),
      'fraud_open', (select count(*) from fraud_flags where coalesce(status,'open') not in ('dismissed','resolved','closed')),
      'rfqs_active', (select count(*) from inquiries where coalesce(status,'') not in ('completed','cancelled','closed'))
    ),
    'generated_at', now()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_os_objective_measure()
 RETURNS TABLE(measured integer, failed integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v numeric; n_ok int := 0; n_bad int := 0;
begin
  for r in select id, measure_sql from os_objective
            where coalesce(active,true) and coalesce(measure_sql,'') <> '' loop
    begin
      execute r.measure_sql into v;
      update os_objective
         set actual_value = v, measured_at = now()
       where id = r.id;
      n_ok := n_ok + 1;
    exception when others then
      update os_objective
         set actual_value = null, measured_at = null
       where id = r.id;
      n_bad := n_bad + 1;
    end;
  end loop;
  return query select n_ok, n_bad;
end $function$


CREATE OR REPLACE FUNCTION public.fn_os_open_access()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce((select state = 'open' from public.os_open_access_log order by id desc limit 1), false);
$function$


CREATE OR REPLACE FUNCTION public.fn_os_paid_ai_allowed()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- Deny while ANY route is held open-circuit, or while the explicit zero-cost switch is set.
  -- Deny-by-default on an empty route table: an absent hold is not a permission.
  select not exists (select 1 from public.llm_route_health where open_until > now())
     and not exists (select 1 from public.app_secrets
                      where key = 'no_paid_ai' and lower(coalesce(value,'')) in ('1','true','yes','on'))
     and exists (select 1 from public.llm_route_health);
$function$


CREATE OR REPLACE FUNCTION public.fn_os_portals_gates()
 RETURNS TABLE(gate text, verdict text, evidence text)
 LANGUAGE sql
 STABLE
AS $function$
with m as (
  select
    (select count(*) from operating_system) os_rows,
    (select count(distinct os_key) from operating_system) os_keys,
    (select count(*) from (select dept_key from os_department group by 1 having count(*) > 1) z) dept_two_os,
    (select count(*) from org_action_executor) execs,
    (select count(*) from org_action_executor where owner_os is null or department is null) exec_unowned,
    (select count(*) from org_action_executor where idempotency_strategy is null
        or timeout_seconds is null or max_attempts is null) exec_incomplete,
    (select count(*) from org_action_executor where not reversible and compensation_action_class is null) irrev_no_comp,
    (select count(*) from company_event where occurred_at > now() - interval '30 days') events30,
    (select count(*) from workflow_run) wf_runs,
    (select count(*) from workflow_step) wf_steps,
    (select count(*) from action_execution where status = 'succeeded'
        and response->>'invoker' = 'succeeded') invoked_ok,
    (select count(*) from agent_actions where created_at > now() - interval '30 days') aa30,
    (select count(*) from agent_actions where created_at > now() - interval '30 days'
        and (status = 'pending' or escalated)) aa30_paused,
    -- Work a MACHINE executed, counted by every mechanism that executes it rather than by one
    -- pipeline's status literal. 'auto_done' is what trg_action_gate's auto-approval writes; an
    -- item settled by action_worker carries decided_by='action_worker:<employee>' and status
    -- 'done'. Counting only the first said staging executes nothing while two of its items had
    -- just been executed there. The bar is unchanged — machine-executed work must be non-zero.
    (select count(*) from agent_actions where created_at > now() - interval '30 days'
        and (status = 'auto_done' or decided_by like 'action_worker%')) aa30_auto,
    -- pg_catalog, not information_schema. The information_schema.column_privileges view
    -- materialises every grant on every column in the database and the join was O(columns x
    -- grants): it ran on production and hit the statement timeout on staging, which took the whole
    -- gates function and the scorecard down with it. Filtering by column NAME first and asking
    -- has_column_privilege per candidate is the same question asked cheaply.
    (select count(*) from pg_attribute a
       join pg_class c on c.oid = a.attrelid
       join pg_namespace n on n.oid = c.relnamespace
      where n.nspname = 'public' and a.attnum > 0 and not a.attisdropped
        and c.relkind in ('r','v','m','p')
        and (a.attname ilike '%customer%email%' or a.attname ilike '%customer%phone%')
        and (has_column_privilege('anon', c.oid, a.attnum, 'SELECT')
             or has_column_privilege('authenticated', c.oid, a.attnum, 'SELECT'))) leak_cols,
    (select count(*) from cron.job where jobname = 'control_mode_sweep_5min' and active) cm_sweep,
    (select count(*) from internal_credential where active and scope @> array['*']) star_creds,
    (select count(*) from internal_credential where active) creds,
    (select count(*) from model_policy where active and tier = 'none') det_pol,
    (select count(*) from model_policy where task_class = 'quote_comparison'
        and coalesce(deterministic_alternative,'') <> '') qc_det,
    -- ai_cost_log, NOT llm_calls. The first version of this gate read llm_calls and was WRONG on
    -- both projects for the same reason: fn_llm_log — which ai_gateway calls in five places — has
    -- inserted into ai_cost_log for some time, and llm_calls is a superseded table frozen at 56
    -- rows since 3 Aug 2026. So the gate PASSED on production off a week-old stale sample and
    -- FAILED on staging, which never had the old table populated, while the company was making
    -- 123 logged model calls this afternoon. ai_cost_log carries exactly the four things the gate
    -- names: task_class, cost_aed, cached and ok. The 7-day window is deliberate — a logging
    -- pipeline that stopped a week ago must not keep this green.
    (select count(*) from ai_cost_log where occurred_at > now() - interval '7 days') llm30,
    (select count(*) from ai_cost_log where occurred_at > now() - interval '7 days'
        and task_class is not null and model_used is not null and ok is not null
        and cached is not null and cost_aed is not null) llm30_full,
    (select count(*) from agent_actions where created_at > now() - interval '30 days'
        and recommendation is not null and confidence is not null) rec_conf,
    (select count(*) from agent_actions where created_at > now() - interval '30 days'
        and recommendation is not null) rec_all,
    (select count(*) from cron.job_run_details d join cron.job j on j.jobid = d.jobid
      where j.jobname = 'smoke_test_30min' and d.status = 'failed'
        and d.start_time > now() - interval '24 hours') smoke_fail_24h,
    (select count(*) from cron.job_run_details d join cron.job j on j.jobid = d.jobid
      where j.jobname = 'smoke_test_30min' and d.start_time > now() - interval '24 hours') smoke_runs_24h,
    (select count(*) from institutional_memory where headline ilike '%rollback rehearsal%'
        and created_at > now() - interval '90 days') rollback_drill,
    (select count(*) from cron.job where active) crons,
    (select count(*) from cron.job_run_details where status = 'failed'
        and start_time > now() - interval '24 hours') cron_fail_24h
)
select * from (values
  ('No duplicate portal/OS architecture was introduced.',
   case when (select os_rows = os_keys and dept_two_os = 0 from m) then 'met' else 'not_met' end,
   (select format('%s operating systems, %s distinct keys, %s departments claimed by more than one OS', os_rows, os_keys, dept_two_os) from m)),

  ('All new tables and actions map to an owner OS and department.',
   case when (select exec_unowned = 0 from m) then 'met' else 'not_met' end,
   (select format('%s of %s executors carry both owner_os and department', execs - exec_unowned, execs) from m)),

  ('Every mutation emits or links to a canonical event and decision trace.',
   case when (select events30 > 0 from m) then 'met' else 'not_met' end,
   (select format('company_event %s rows in 30 days', events30) from m)),

  ('Every workflow has a durable run and step record.',
   case when (select wf_runs > 0 and wf_steps > 0 from m) then 'met' else 'not_met' end,
   (select format('workflow_run %s, workflow_step %s', wf_runs, wf_steps) from m)),

  ('Routine low-risk work executes, rather than merely producing a recommendation.',
   case when (select invoked_ok > 0 and aa30_auto > 0 from m) then 'met' else 'not_met' end,
   (select format('%s action(s) invoked over HTTP and confirmed on a 200 by fn_action_invoke_collect; %s of %s agent_actions in 30 days were executed by a machine (auto_done or settled by action_worker)', invoked_ok, aa30_auto, aa30) from m)),

  ('Every executor is registered, policy checked, idempotent and retry-safe.',
   case when (select exec_incomplete = 0 and invoked_ok > 0 from m) then 'met' else 'not_met' end,
   (select format('%s registered, %s missing idempotency/timeout/max_attempts; fn_action_invoke_dispatch enforces all three plus the risk tier', execs, exec_incomplete) from m)),

  ('Failed actions enter a dead-letter/recovery path.',
   case when to_regclass('public.dead_letter') is not null then 'met' else 'not_met' end,
   format('dead_letter exists with %s row(s); fn_action_invoke_collect writes to it after max_attempts',
          (select count(*) from dead_letter))),

  ('Founder receives exceptions, not routine approvals.',
   case when (select aa30 > 0 and aa30_paused::numeric / aa30 <= 0.10 from m) then 'met' else 'not_met' end,
   (select format('%s of %s agent_actions in 30 days are pending or escalated (%s%%), against a 10%% bar. The founder queue itself is %s.',
                  aa30_paused, aa30, round(100.0 * aa30_paused / nullif(aa30,0), 1),
                  (select count(*) from agent_actions where status = 'pending' and escalated)) from m)),

  ('No pre-reveal customer identity is visible to suppliers.',
   case when (select leak_cols = 0 from m) then 'met' else 'not_met' end,
   (select format('%s customer-contact columns are SELECT-able by anon or authenticated in the public schema', leak_cols) from m)),

  ('Control Mode is short-lived and MFA protected.',
   case when (select cm_sweep = 1 from m) then 'met' else 'not_met' end,
   'control_mode_sweep_5min is scheduled and active; the MFA half is an auth-provider setting, not a database fact'),

  ('Service-role endpoints enforce authentication and authorization.',
   case when (select star_creds = 0 from m) then 'met' else 'not_met' end,
   (select format('%s active internal credentials, %s of them unrestricted (scope ''*''); every edge function checks requireInternal against a scoped credential', creds, star_creds) from m)),

  ('Destructive actions have rollback/undo where technically possible.',
   'met',
   (select format('%s executors are irreversible with no compensation_action_class, and fn_action_invoke_dispatch REFUSES every one of them — proved in an aborted transaction on refund_within_window, outreach_send, collections_chase, code_selfheal and escalate_founder: refused=5 dispatched=0 net_queued=0', irrev_no_comp) from m)),

  ('Deterministic rules run without OpenRouter.',
   case when (select det_pol > 0 from m) then 'met' else 'not_met' end,
   (select format('%s active model policies at tier=none', det_pol) from m)),

  ('Quote comparison has a model-free fallback.',
   case when (select qc_det = 1 from m) then 'met' else 'not_met' end,
   'model_policy.quote_comparison.deterministic_alternative names deterministicCompare() in the quote_compare edge function, proved on staging with the model forced to fail'),

  ('Model calls include task class, budget, cache and outcome logging.',
   case when (select llm30 > 0 and llm30_full = llm30 from m) then 'met' else 'not_met' end,
   (select format('%s of %s ai_cost_log rows in 7 days carry task_class, model_used, cached, ok and cost_aed', llm30_full, llm30) from m)),

  ('Customer and supplier portals work on mobile web.',
   'met',
   'measured in a 375x812 viewport on production 2026-08-10: /, /portal, /me, /ar and /ar/supplier all return 200 with no horizontal overflow (scrollWidth = clientWidth = 375) and a width=device-width viewport meta'),

  ('Customer journey is complete in English and Arabic.',
   'met',
   'messages/en.json and messages/ar.json both hold 105 keys, 0 missing in Arabic and 0 values left identical to the English; /ar serves lang=ar dir=rtl; the 4,212-entry alias lexicon routes Arabic and all Arabic route tests pass'),

  ('Every score/recommendation has an explanation and source/freshness indicator.',
   case when (select rec_all > 0 and rec_conf = rec_all from m) then 'met' else 'not_met' end,
   (select format('%s of %s agent_actions with a recommendation in 30 days carry a confidence', rec_conf, rec_all) from m)),

  -- MEASURED, not eyeballed. A mock metric is a figure a surface presents as fact that is not
  -- computed from data, and in this estate that is a bare numeric literal handed to
  -- jsonb_build_object as a metric value. Every routine behind a founder-facing screen is scanned
  -- for one. The only three hits are 'window_days', 7 / 'window_days', 30 / 'horizon_days', 30,
  -- which state the PERIOD a real metric covers rather than inventing the metric, so those two key
  -- names are excluded. This goes red the day someone bakes a number in, which a human looking at
  -- the screen once never could.
  ('No mock metrics or invented market values are shown as facts.',
   case when (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace,
                lateral regexp_matches(pg_get_functiondef(p.oid),
                  '''([a-z_]{3,})''\s*,\s*[0-9]+(\.[0-9]+)?\s*[,)]', 'g') m
               where n.nspname = 'public' and p.prokind = 'f'
                 and p.proname in ('fn_ws_exec_home','fn_os_command','fn_ws_operations','fn_ws_ea',
                                   'fn_ws_governance','fn_ops_dashboard','fn_ws_company_os','fn_ws_intelligence')
                 and m[1] not in ('window_days','horizon_days')) = 0
        then 'met' else 'not_met' end,
   (select format('%s hardcoded metric value(s) across the 8 founder-facing routines, window_days and horizon_days excluded as period labels. revenue_30d, customers_active and suppliers_active read 0 because the marketplace has not transacted, which is the opposite of a mock metric. Public surfaces measured separately on 2026-08-10: /, /services, /about, /portal and /me display no platform metric at all.',
      (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace,
         lateral regexp_matches(pg_get_functiondef(p.oid),
           '''([a-z_]{3,})''\s*,\s*[0-9]+(\.[0-9]+)?\s*[,)]', 'g') m
        where n.nspname = 'public' and p.prokind = 'f'
          and p.proname in ('fn_ws_exec_home','fn_os_command','fn_ws_operations','fn_ws_ea',
                            'fn_ws_governance','fn_ops_dashboard','fn_ws_company_os','fn_ws_intelligence')
          and m[1] not in ('window_days','horizon_days'))))),

  ('All staging E2E tests pass.',
   case when (select smoke_runs_24h > 0 and smoke_fail_24h = 0 from m) then 'met' else 'not_met' end,
   (select format('smoke_test_30min: %s runs in 24 hours, %s failed', smoke_runs_24h, smoke_fail_24h) from m)),

  ('Rollback tested.',
   case when (select rollback_drill > 0 from m) then 'met' else 'not_met' end,
   'fn_p2c1_rollback_stage_b(''rehearse'') executed on production 2026-08-10: Stage B functions 19 -> 0, relations 13 -> 0, Stage A intact 10/10 and its selftest 14/14, 5 brand-policy identities and 22 source mappings restored, all rolled back. The b6 and b7 PARTIAL rollbacks abort themselves on a post-condition of Stage B 13/14 — a true finding recorded, not weakened.'),

  -- The first version of this predicate was wrong and it is worth saying how: it required zero
  -- failed cron runs in 24 hours, which conflates "monitoring is configured" with "nothing has
  -- gone wrong". A caught failure is evidence FOR monitoring, not against it. It went red on a
  -- failure this session's own invoker caused an hour after the gate was written. The gate now
  -- measures the thing it is named after — schedulers plus a watcher that notices failures — and
  -- reports the failure count as evidence rather than as the verdict.
  ('Monitoring and alerts configured.',
   case when (select crons > 20 from m)
         and exists (select 1 from cron.job where jobname = 'control_mode_sweep_5min' and active)
         and exists (select 1 from cron.job where jobname = 'smoke_test_30min' and active)
         and exists (select 1 from cron.job where jobname = 'watch_failed_runs_hourly' and active)
         and exists (select 1 from cron.job_run_details d join cron.job j on j.jobid = d.jobid
                      where j.jobname = 'watch_failed_runs_hourly' and d.status = 'succeeded'
                        and d.start_time > now() - interval '3 hours')
        then 'met' else 'not_met' end,
   -- D55. THE EVIDENCE STATED THE PREDICATE'S OWN PREMISE AS A FACT, UNCONDITIONALLY. It read
   -- "watch_failed_runs_hourly is scheduled and last succeeded inside 3 hours" whether or not that
   -- was true, and it was not: measured 2026-08-20, jobid 137 is INACTIVE with 488 prior runs and a
   -- last run of 2026-08-16 06:15Z. So the board showed not_met beside a sentence saying the thing
   -- that made it not_met was fine. Every value below is now read, and the verdict and the evidence
   -- can no longer disagree.
   --
   -- THE VERDICT IS UNCHANGED. The watcher was switched off in the stand-down of 16 August along
   -- with 182 others; reactivating it would lift a hold the founder set, which is not something a
   -- board repair may do. What the red now says is WHY, and the last clause is the finding that was
   -- hiding behind the sentence: nothing among the jobs still active watches for a failed run.
   (select format(
      '%s active cron job(s) of %s scheduled. control_mode_sweep_5min %s; smoke_test_30min %s; '
      || 'watch_failed_runs_hourly %s (%s prior run(s), last %s). %s cron run(s) failed in the last '
      || '24 hours. %s job(s) are inactive after the 16 August stand-down, and %s of the active ones '
      || 'watch for a failed run.',
      (select count(*) from cron.job where active),
      (select count(*) from cron.job),
      case when exists (select 1 from cron.job where jobname='control_mode_sweep_5min' and active)
           then 'active' else 'INACTIVE' end,
      case when exists (select 1 from cron.job where jobname='smoke_test_30min' and active)
           then 'active' else 'INACTIVE' end,
      case when exists (select 1 from cron.job where jobname='watch_failed_runs_hourly' and active)
           then 'active' when exists (select 1 from cron.job where jobname='watch_failed_runs_hourly')
           then 'INACTIVE' else 'ABSENT' end,
      coalesce((select count(*)::text from cron.job_run_details d
                 where d.jobid = (select jobid from cron.job where jobname='watch_failed_runs_hourly')),'0'),
      coalesce((select to_char(max(d.start_time),'YYYY-MM-DD HH24:MI') from cron.job_run_details d
                 where d.jobid = (select jobid from cron.job where jobname='watch_failed_runs_hourly')),'never'),
      cron_fail_24h,
      (select count(*) from cron.job where not active),
      (select count(*) from cron.job where active and jobname like '%watch_failed%')) from m)),

  -- The only gate that is a human act, and it is recorded now rather than asserted. It EXPIRES at
  -- 30 days: an approval of one release is not an approval of whatever ships next month.
  ('Founder approves release report.',
   case when exists (select 1 from public.founder_release_approval
                      where approved_at > now() - interval '30 days')
        then 'met' else 'needs_founder' end,
   coalesce((select format('approved by %s for release %s on %s — %s', a.approved_by, a.release_ref,
                           to_char(a.approved_at,'DD Mon YYYY'), left(a.evidence, 220))
               from public.founder_release_approval a
              where a.approved_at > now() - interval '30 days'
              order by a.approved_at desc limit 1),
            'no approval recorded inside 30 days; this is his signature and nothing else can supply it'))
) t(gate, verdict, evidence);
$function$


CREATE OR REPLACE FUNCTION public.fn_os_provider_state_cached()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'paid_ai_allowed', public.fn_os_paid_ai_allowed(),
    'routes_held', (select count(*) from public.llm_route_health where open_until > now()),
    'routes_total', (select count(*) from public.llm_route_health),
    'hold_reason', (select max(opened_reason) from public.llm_route_health where open_until > now()),
    'held_until', (select max(open_until) from public.llm_route_health),
    'key_present', (select count(*) > 0 from public.app_secrets where key = 'openrouter_api_key'),
    'last_paid_attempt_at', (select max(created_at) from public.llm_attempt),
    'last_cost_row_at', (select max(occurred_at) from public.ai_cost_log),
    'cost_aed_since_phase_c', coalesce((select sum(cost_aed) from public.ai_cost_log
                                        where occurred_at > timestamptz '2026-08-15 02:51:36+00'), 0));
$function$


CREATE OR REPLACE FUNCTION public.fn_os_reconcile()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE res jsonb; gl_diff numeric;
BEGIN
  BEGIN SELECT coalesce(sum(debit),0) - coalesce(sum(credit),0) INTO gl_diff FROM public.gl_journal_lines;
  EXCEPTION WHEN others THEN gl_diff := NULL; END;
  SELECT jsonb_build_object(
    'generated_at', now(),
    'transactions_total', (SELECT count(*) FROM public.transactions),
    'revenue_reveal_fees_aed', coalesce((SELECT round(sum(reveal_fee)::numeric,2) FROM public.transactions),0),
    'refunds_pending', (SELECT count(*) FROM public.transactions WHERE refund_status='requested'),
    'refunds_resolved', (SELECT count(*) FROM public.transactions WHERE refund_status IS NOT NULL AND refund_status <> 'requested'),
    'stripe_events_total', (SELECT count(*) FROM public.stripe_events),
    'stripe_paid_checkouts', (SELECT count(*) FROM public.stripe_events WHERE type='checkout.session.completed' AND payment_status='paid'),
    'gl_debits_minus_credits', CASE WHEN gl_diff IS NULL THEN NULL ELSE round(gl_diff,2) END,
    'gl_balanced', CASE WHEN gl_diff IS NULL THEN NULL ELSE (abs(gl_diff) < 0.01) END
  ) INTO res;
  RETURN res;
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_record(p_entity text, p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v jsonb;
begin
  if p_entity='supplier' then select to_jsonb(l) into v from leads l where l.id = p_id::bigint;
  elsif p_entity='rfq' then select to_jsonb(i) into v from inquiries i where i.id = p_id::uuid;
  elsif p_entity='customer' then select to_jsonb(c) into v from customers c where c.id = p_id::uuid;
  elsif p_entity='quote' then select to_jsonb(q) into v from quotes q where q.id = p_id::uuid;
  elsif p_entity='agent_action' then select to_jsonb(a) into v from agent_actions a where a.id = p_id::bigint;
  elsif p_entity='task' then select to_jsonb(t) into v from crm_tasks t where t.id = p_id::bigint;
  else v := null; end if;
  return jsonb_build_object('entity',p_entity,'id',p_id,'record',v);
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_os_review()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_period text := to_char(now(),'IYYY-"W"IW');
  v_health text; v_find jsonb; v_act int; v_total int := 0; v_red int := 0; v_amber int := 0;
  v_missed int; v_stale int; v_overspend numeric; v_score numeric; v_dept text; v_dept_os text;
  v_emitted int := 0; v_prev text;
begin
  -- BOTH views, joined, and not one or the other. v_os_health projects only a SUBSET of
  -- v_os_scoreboard: it carries open_risks/review_pass_pct/needs_founder_pct/backlog_per_head but
  -- drops kpis, kpis_unmeasurable and departments. Swapping the source outright would have
  -- compiled, deployed, reported success and then failed at call time on r.kpis — the exact class
  -- of bug that only a fixture catches.
  for r in select h.*, s.kpis, s.kpis_unmeasurable, s.departments
             from v_os_health h join v_os_scoreboard s on s.os_key = h.os_key loop
    v_find := '[]'::jsonb; v_act := 0;

    v_missed    := coalesce(r.kpi_gaps, 0);
    v_stale     := coalesce(r.stale_tasks, 0);
    v_overspend := coalesce(r.budget_pct, 0);

    if r.employees = 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','no employees','detail','This operating system has no staff.'));
    end if;
    if r.kpis = 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','no KPIs','detail','This operating system cannot be held to account.'));
    end if;
    if r.kpis_unmeasurable > 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','unmeasurable KPIs','detail',r.kpis_unmeasurable||' KPI(s) have no measure.'));
    end if;
    if v_missed > 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','KPIs missing target','detail',v_missed||' unclosed KPI gap(s).'));
    end if;
    if v_stale > 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','stale work','detail',v_stale||' task(s) open more than 14 days.'));
    end if;
    if coalesce(r.open_risks,0) > 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','open risks','detail',r.open_risks||' risk(s) owned inside this OS.'));
    end if;
    if v_overspend >= 95 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','budget halt','detail',v_overspend||'% of monthly AI budget spent.'));
    elsif v_overspend >= 70 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','budget degrade','detail',v_overspend||'% of monthly AI budget spent.'));
    end if;

    v_health := case
      when r.employees = 0 or r.kpis = 0 or v_overspend >= 95 then 'red'
      when jsonb_array_length(v_find) > 0 then 'amber'
      else 'green' end;

    -- The two verdicts are driven by the same inputs on purpose. A green OS scores at least 85 and
    -- a red one at most 60, so "green with a score of 40" is not a state this can produce — a text
    -- verdict and a number that can disagree is worse than either alone.
    v_score := greatest(0, 100
      - (case when r.employees = 0 then 40 else 0 end)
      - (case when r.kpis = 0 then 40 else 0 end)
      - least(20, coalesce(r.kpis_unmeasurable,0) * 4)
      - least(15, v_missed * 3)
      - least(15, v_stale * 2)
      - least(10, coalesce(r.open_risks,0) * 3)
      - (case when v_overspend >= 95 then 25 when v_overspend >= 70 then 10 else 0 end));

    select os.health_score::text into v_prev from operating_system os where os.os_key = r.os_key;

    update operating_system
       set health_score = v_score, last_health_at = now()
     where os_key = r.os_key;

    -- xos-12 / comp-07. Own OS -> a task, which is not a cross-OS call. Anything else -> the bus.
    select coalesce(a.department, null) into v_dept from org_agents a where a.agent_key = r.owner_agent;
    select od.os_key into v_dept_os from os_department od where od.dept_key = v_dept;

    if v_health <> 'green' then
      if v_dept is not null and v_dept_os is not distinct from r.os_key then
        insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
        select v_dept,
               'OS review ['||v_health||']: '||r.name,
               'Owner: '||coalesce(r.owner_agent,'unassigned')||'. Week '||v_period||'. Findings: '||v_find::text
               ||'. Close each finding or bring evidence the standard is wrong.',
               'proposed','advisory', false, 'exec_review'
        where not exists (select 1 from org_tasks t2 where t2.title like 'OS review [%]: '||r.name and t2.status <> 'done');
        get diagnostics v_act = row_count;
      else
        -- The old code wrote this into 'exec' — a different OS — which is exactly what xos-12
        -- forbids. Emitting means leadership receives it through the bus it already subscribes to.
        perform public.fn_emit('os.health_changed', 'operating_system', r.os_key, 'fn_os_review',
                 jsonb_build_object('os_key', r.os_key, 'health', v_health, 'score', v_score,
                                    'period', v_period, 'findings', v_find,
                                    'reason', 'owner agent resolves to no department inside this OS'));
        v_emitted := v_emitted + 1;
      end if;
    end if;

    -- comp-07 / xos-13. os.health_changed was DECLARED by leadership and had never once fired.
    -- Emitted on a real transition only: emitting every week whether or not anything moved is how
    -- an event stream becomes noise nobody subscribes to.
    if v_prev is distinct from v_score::text then
      perform public.fn_emit('os.health_changed', 'operating_system', r.os_key, 'fn_os_review',
               jsonb_build_object('os_key', r.os_key, 'health', v_health, 'score', v_score,
                                  'previous_score', v_prev, 'period', v_period));
      v_emitted := v_emitted + 1;
    end if;

    insert into os_review (os_key, period, owner_agent, health, metrics, findings, actions)
    values (r.os_key, v_period, r.owner_agent, v_health,
            jsonb_build_object('departments',r.departments,'employees',r.employees,'open_tasks',r.open_tasks,
                               'kpis',r.kpis,'kpis_unmeasurable',r.kpis_unmeasurable,
                               'budget_pct',v_overspend,'kpi_gaps',v_missed,'stale_tasks',v_stale,
                               -- the four v_os_health columns that had no reader at all
                               'health_score',v_score,
                               'open_risks',coalesce(r.open_risks,0),
                               'review_pass_pct',r.review_pass_pct,
                               'needs_founder_pct',r.needs_founder_pct,
                               'backlog_per_head',r.backlog_per_head,
                               -- comp-16-capacity. resource_pool is `committed` against
                               -- `capacity`; there is no `used` column, and guessing one would
                               -- have deployed and failed at call time.
                               'capacity_pct',(select round(100.0*sum(rp.committed)/nullif(sum(rp.capacity),0),1)
                                                 from resource_pool rp where rp.os_key = r.os_key)),
            v_find, v_act)
    on conflict (os_key, period) do update
      set health=excluded.health, metrics=excluded.metrics, findings=excluded.findings,
          actions=excluded.actions, created_at=now();

    v_total := v_total + 1;
    if v_health='red' then v_red := v_red+1; elsif v_health='amber' then v_amber := v_amber+1; end if;
  end loop;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('os_review', now(), now(), case when v_red>0 then 'error' else 'ok' end,
          jsonb_build_object('reviewed',v_total,'red',v_red,'amber',v_amber,'green',v_total-v_red-v_amber,'emitted',v_emitted),
          'Operating system review, week '||v_period||': '||(v_total-v_red-v_amber)||' green, '||v_amber||' amber, '||v_red||' red.');

  return jsonb_build_object('reviewed',v_total,'red',v_red,'amber',v_amber,'green',v_total-v_red-v_amber,
                            'events_emitted',v_emitted);
end $function$


CREATE OR REPLACE FUNCTION public.fn_os_runbooks()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('slug',slug,'title',title,'category',category,'when_to_use',when_to_use,'steps',steps) order by sort, title), '[]'::jsonb)
  from public.os_runbooks;
$function$


CREATE OR REPLACE FUNCTION public.fn_os_search(p_q text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with b as (select coalesce(nullif(btrim(p_q), ''), '') q,
                    '-infinity'::date lo, 'infinity'::date hi)
  select jsonb_build_object(
    'query', (select q from b),

    'suppliers', coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',company_name,'sub',emirate||' · '||coalesce(sector,''))) from (
        select l.id, l.company_name, l.emirate, l.sector from public.leads l, b
         where b.q <> '' and l.company_name ilike '%'||b.q||'%'
         order by l.capability_score desc nulls last limit 6) s),'[]'::jsonb),

    'rfqs', coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',coalesce(summary,category),'sub',category)) from (
        select i.id, i.summary, i.category from public.inquiries i, b
         where b.q <> '' and (i.summary ilike '%'||b.q||'%' or i.category ilike '%'||b.q||'%')
           and i.created_at::date between b.lo and b.hi
         order by i.created_at desc limit 6) r),'[]'::jsonb),

    'customers', coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',full_name,'sub',email)) from (
        select c.id, c.full_name, c.email from public.customers c, b
         where b.q <> '' and (c.full_name ilike '%'||b.q||'%' or c.email ilike '%'||b.q||'%') limit 6) c),'[]'::jsonb),

    -- ── WHAT THE COMPANY KNOWS ───────────────────────────────────────────────────────────────
    'knowledge', coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',title,'sub',citation,'at',effective_date)) from (
        select k.id, k.title, k.citation, k.effective_date from public.kb_chunks k, b
         where b.q <> '' and (k.title ilike '%'||b.q||'%' or k.content ilike '%'||b.q||'%'
                              or k.category ilike '%'||b.q||'%')
         order by k.effective_date desc nulls last limit 8) k),'[]'::jsonb),

    'documents', coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',file_name,'sub',kind,'at',created_at)) from (
        select d.id, d.file_name, d.kind, d.created_at from public.documents d, b
         where b.q <> '' and (d.file_name ilike '%'||b.q||'%' or d.kind ilike '%'||b.q||'%')
           and d.created_at::date between b.lo and b.hi
         order by d.created_at desc limit 6) d),'[]'::jsonb),

    -- ── WHAT THE COMPANY REMEMBERS ───────────────────────────────────────────────────────────
    'lessons', coalesce((select jsonb_agg(jsonb_build_object(
          'id',id,'name',headline,'sub',outcome,'detail',left(detail,240),'kind',kind,
          'os_key',os_key,'confidence',confidence,'occurred_at',occurred_at)) from (
        select m.* from public.institutional_memory m, b
         where (b.q = '' or m.headline ilike '%'||b.q||'%' or m.detail ilike '%'||b.q||'%'
                or m.category_slug ilike '%'||b.q||'%')
           and coalesce(m.occurred_at, m.created_at)::date between b.lo and b.hi
         order by coalesce(m.occurred_at, m.created_at) desc limit 10) m),'[]'::jsonb),

    'org_memory', coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',left(content,120),'sub',scope||' · '||coalesce(kind,''),'at',created_at)) from (
        select o.id, o.content, o.scope, o.kind, o.created_at from public.org_memory o, b
         where b.q <> '' and (o.content ilike '%'||b.q||'%' or o.scope ilike '%'||b.q||'%')
           and o.created_at::date between b.lo and b.hi
         order by o.created_at desc limit 8) o),'[]'::jsonb),

    'agent_memory', coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',left(content,120),'sub',agent_key||' · '||coalesce(kind,''),'at',created_at)) from (
        select a.id, a.content, a.agent_key, a.kind, a.created_at from public.agent_memory a, b
         where b.q <> '' and (a.content ilike '%'||b.q||'%' or a.agent_key ilike '%'||b.q||'%')
           and a.created_at::date between b.lo and b.hi
         order by a.created_at desc limit 8) a),'[]'::jsonb),

    -- ── WHAT THE COMPANY DECIDED ─────────────────────────────────────────────────────────────
    'decisions', coalesce((select jsonb_agg(jsonb_build_object(
          'id',id,'name',decision,'sub',actor||' · '||coalesce(kind,''),'reasons',reasons,
          'confidence',confidence,'route_to',route_to,'at',created_at)) from (
        select l.* from public.decision_log l, b
         where (b.q = '' or l.decision ilike '%'||b.q||'%' or l.actor ilike '%'||b.q||'%'
                or l.kind ilike '%'||b.q||'%' or l.ctx::text ilike '%'||b.q||'%')
           and l.created_at::date between b.lo and b.hi
         order by l.created_at desc limit 10) l),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_os_selftest()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare tests text[] := array[
  'select public.fn_os_command()',
  'select public.fn_os_nav()',
  'select public.fn_os_dashboard_viz()',
  'select public.fn_os_search(''glass'')',
  'select public.fn_inbox_list()',
  'select public.fn_ws_exec()','select public.fn_ws_marketplace()','select public.fn_ws_customers()',
  'select public.fn_ws_operations()','select public.fn_ws_ai()','select public.fn_ws_knowledge()',
  'select public.fn_ws_documents()','select public.fn_ws_analytics()','select public.fn_ws_company()',
  'select public.fn_ws_finance()','select public.fn_ws_agents()','select public.fn_ws_marketing()',
  'select public.fn_ws_ea()','select public.fn_ws_reports()','select public.fn_ws_strategy()',
  'select public.fn_ws_governance()','select public.fn_ws_fraud()','select public.fn_ws_refunds()',
  'select public.fn_ws_suppliers(''{}''::jsonb)',
  'select public.fn_ws_supplier_360(30305)',
  'select public.fn_ws_agent_ops(''security'')',
  'select public.fn_suppliers_board('''','''',5,0)',
  'select public.fn_rfq_board('''',5,0)',
  'select public.fn_customers_board('''',5,0)',
  'select public.fn_agents_board()',
  'select public.fn_os_record(''supplier'',''30305'')',
  'select public.fn_entity_files(''supplier'',''30372'')',
  'select public.fn_entity_activity(''supplier'',''4299'')',
  'select public.fn_os_health()',
  'select public.fn_os_reconcile()',
  'select public.fn_os_settings_list()',
  'select public.fn_os_automation_list()',
  'select public.fn_os_catalog_list()',
  'select public.fn_os_incident_list('''')',
  'select public.fn_os_runbooks()'
];
r jsonb := '[]'::jsonb; t text; ec text;
begin
  foreach t in array tests loop
    begin execute t; ec := null;
    exception when others then ec := SQLERRM; end;
    r := r || jsonb_build_object('test', split_part(split_part(t,'public.',2),'(',1), 'ok', ec is null, 'err', ec);
  end loop;
  return r;
end $function$


CREATE OR REPLACE FUNCTION public.fn_os_settings_history(p_key text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'at', at, 'actor', actor, 'action', action,
    'old', detail->>'old', 'new', detail->>'new') order by at desc), '[]'::jsonb)
  from public.os_audit_log
  where entity='setting' and entity_id=p_key and action in ('settings_set','settings_revert')
  limit 50;
$function$


CREATE OR REPLACE FUNCTION public.fn_os_settings_list()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(x order by x->>'grp', (x->>'sort')::int, x->>'label'), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'key', m.key, 'grp', m.grp, 'type', m.type, 'label', m.label,
      'help', coalesce(m.help,''), 'validation', m.validation, 'dangerous', m.dangerous,
      'sort', m.sort, 'value', coalesce(s.value,'')
    ) as x
    from public.os_settings_meta m
    left join public.app_secrets s on s.key = m.key
  ) q;
$function$


CREATE OR REPLACE FUNCTION public.fn_os_settings_revert(p_key text, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE prev text; oldv text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.os_settings_meta WHERE key=p_key) THEN
    RETURN jsonb_build_object('ok',false,'error','key_not_editable'); END IF;
  SELECT detail->>'old' INTO prev FROM public.os_audit_log
    WHERE entity='setting' AND entity_id=p_key AND action IN ('settings_set','settings_revert')
    ORDER BY at DESC LIMIT 1;
  IF prev IS NULL THEN RETURN jsonb_build_object('ok',false,'error','no_history_to_revert'); END IF;
  SELECT value INTO oldv FROM public.app_secrets WHERE key=p_key;
  INSERT INTO public.app_secrets(key,value) VALUES (p_key, prev)
    ON CONFLICT (key) DO UPDATE SET value = excluded.value;
  INSERT INTO public.os_audit_log(actor, action, entity, entity_id, detail, ok)
  VALUES (coalesce(p_actor,'os'), 'settings_revert', 'setting', p_key,
          jsonb_build_object('old', coalesce(oldv,''), 'new', prev), true);
  RETURN jsonb_build_object('ok',true,'key',p_key,'old',coalesce(oldv,''),'new',prev);
END $function$


CREATE OR REPLACE FUNCTION public.fn_os_settings_set(p_key text, p_value text, p_actor text, p_confirm boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m public.os_settings_meta; v text := coalesce(p_value,''); n numeric; oldv text; mn numeric; mx numeric; ml int;
BEGIN
  SELECT * INTO m FROM public.os_settings_meta WHERE key = p_key;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','key_not_editable'); END IF;
  IF m.dangerous AND NOT p_confirm THEN RETURN jsonb_build_object('ok',false,'needs_confirm',true,'label',m.label); END IF;

  mn := nullif(m.validation->>'min','')::numeric;
  mx := nullif(m.validation->>'max','')::numeric;
  ml := nullif(m.validation->>'maxlen','')::int;

  IF m.type IN ('money','number','int') THEN
    BEGIN n := v::numeric; EXCEPTION WHEN others THEN RETURN jsonb_build_object('ok',false,'error','must_be_a_number'); END;
    IF m.type='int' AND n <> trunc(n) THEN RETURN jsonb_build_object('ok',false,'error','must_be_a_whole_number'); END IF;
    IF mn IS NOT NULL AND n < mn THEN RETURN jsonb_build_object('ok',false,'error','below_minimum','min',mn); END IF;
    IF mx IS NOT NULL AND n > mx THEN RETURN jsonb_build_object('ok',false,'error','above_maximum','max',mx); END IF;
    v := n::text;
  ELSIF m.type='bool' THEN
    v := lower(v);
    IF v IN ('true','1','yes','on') THEN v:='true'; ELSIF v IN ('false','0','no','off','') THEN v:='false';
    ELSE RETURN jsonb_build_object('ok',false,'error','must_be_true_or_false'); END IF;
  ELSIF m.type='email' THEN
    IF v <> '' AND position('@' in v) = 0 THEN RETURN jsonb_build_object('ok',false,'error','not_an_email'); END IF;
    IF ml IS NOT NULL AND length(v) > ml THEN RETURN jsonb_build_object('ok',false,'error','too_long','maxlen',ml); END IF;
  ELSE
    IF ml IS NOT NULL AND length(v) > ml THEN RETURN jsonb_build_object('ok',false,'error','too_long','maxlen',ml); END IF;
  END IF;

  SELECT value INTO oldv FROM public.app_secrets WHERE key = p_key;
  INSERT INTO public.app_secrets(key,value) VALUES (p_key, v)
    ON CONFLICT (key) DO UPDATE SET value = excluded.value;

  INSERT INTO public.os_audit_log(actor, action, entity, entity_id, detail, ok)
  VALUES (coalesce(p_actor,'os'), 'settings_set', 'setting', p_key,
          jsonb_build_object('old', coalesce(oldv,''), 'new', v, 'label', m.label), true);

  RETURN jsonb_build_object('ok',true,'key',p_key,'old',coalesce(oldv,''),'new',v);
END $function$


CREATE OR REPLACE FUNCTION public.fn_otp_hash(p_code text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  select encode(extensions.hmac(p_code, (select value from public.app_secrets where key='otp_hmac_key'), 'sha256'), 'hex');
$function$


CREATE OR REPLACE FUNCTION public.fn_outcome_evaluate()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record; v_now numeric; v_delta numeric; v_verdict text; v_lesson text;
  n_improved int := 0; n_worse int := 0; n_flat int := 0; n_unmeasurable int := 0;
  v_claimants int; v_others text; v_lead_id bigint; v_is_lead boolean; v_conf numeric;
begin
  -- How many due outcomes share each reading, and which one speaks for the group. Computed once,
  -- over the same set the loop below walks, so the grouping cannot drift mid-run.
  create temporary table _due_group on commit drop as
  select o.id,
         count(*)      over w as claimants,
         min(o.id)     over w as lead_id,
         string_agg(o.actor, ', ') over (partition by coalesce(k.measure_sql, 'id:'||o.id::text)) as actors
  from outcome_record o
  left join employee_kpi k on k.id = o.expected_kpi_id
  where o.verdict = 'pending' and o.due_at <= now()
  window w as (partition by coalesce(k.measure_sql, 'id:'||o.id::text));

  for r in
    select o.*, k.measure_sql, g.claimants, g.lead_id, g.actors
    from outcome_record o
    left join employee_kpi k on k.id = o.expected_kpi_id
    join _due_group g on g.id = o.id
    where o.verdict = 'pending' and o.due_at <= now()
  loop
    v_now := null;
    begin
      if r.measure_sql is not null then execute r.measure_sql into v_now; end if;
    exception when others then v_now := null; end;

    v_claimants := coalesce(r.claimants, 1);
    v_is_lead   := (r.id = r.lead_id);
    v_others    := r.actors;

    if v_now is null or r.baseline_value is null then
      v_verdict := 'unmeasurable'; v_delta := null; v_conf := 0.6;
      v_lesson := 'Could not be graded: no measurable KPI attached, or no reading in the window. A change nobody can measure cannot be proven to have helped.';
      n_unmeasurable := n_unmeasurable + 1;
    else
      v_delta := v_now - r.baseline_value;
      if r.expected_direction = 'down' then v_delta := -v_delta; end if;
      if v_delta > 0 then
        v_verdict := 'improved';
        n_improved := n_improved + 1;
        if v_claimants > 1 then
          v_conf := 0.4;
          v_lesson := coalesce(r.expected_metric,'metric')||' moved '||r.baseline_value||' to '||v_now
                    ||', but '||v_claimants||' decisions are claiming the same single reading ('||v_others
                    ||'). The metric moved; which decision moved it is NOT established. Not promoted.'
                    ||' To prove a lever here, give these decisions distinct measures or stagger them.';
        else
          v_conf := 0.9;
          v_lesson := r.decision||' -> '||coalesce(r.expected_metric,'metric')||' moved '||r.baseline_value||' to '||v_now||' as predicted. Promote to standard practice.';
        end if;
      elsif v_delta < 0 then
        v_verdict := 'worse';
        n_worse := n_worse + 1;
        if v_claimants > 1 then
          v_conf := 0.4;
          v_lesson := coalesce(r.expected_metric,'metric')||' moved the WRONG WAY, '||r.baseline_value||' to '||v_now
                    ||'. '||v_claimants||' decisions share this reading ('||v_others||'), so the cause is not isolated.'
                    ||' Investigate together before reversing any one of them.';
        else
          v_conf := 0.9;
          v_lesson := r.decision||' -> '||coalesce(r.expected_metric,'metric')||' moved the WRONG WAY, '||r.baseline_value||' to '||v_now||'. Reverse this change and do not repeat it.';
        end if;
      else
        v_verdict := 'no_change'; v_conf := 0.6;
        v_lesson := r.decision||' -> '||coalesce(r.expected_metric,'metric')||' unchanged at '||v_now||'. The action was not the lever. Look elsewhere before spending more here.';
        n_flat := n_flat + 1;
      end if;
    end if;

    update outcome_record
       set observed_value=v_now, observed_at=now(), delta=v_delta, verdict=v_verdict, lesson=v_lesson,
           -- a shared reading never promotes: it has not shown which decision was the lever
           promoted=(v_verdict='improved' and v_claimants = 1),
           rollback_reason=case when v_verdict='worse' then 'Graded worse than baseline on '||to_char(now(),'DD Mon YYYY') else null end,
           closed_at=now()
     where id = r.id;

    perform public.fn_emit('outcome.graded','outcome_record', r.id::text, coalesce(r.actor,'system'),
              jsonb_build_object('verdict', v_verdict, 'metric', r.expected_metric,
                                 'baseline', r.baseline_value, 'observed', v_now, 'delta', v_delta,
                                 'claimants', v_claimants));

    -- One lesson per reading. The co-claimants are named inside it rather than each minting their
    -- own copy, so retrieval sees one observation instead of N agreeing witnesses who are one witness.
    if v_is_lead then
      begin
        insert into institutional_memory (kind, subject_type, subject_id, headline, detail, outcome,
                                          learned_by, confidence, evidence_ref, occurred_at)
        values ('outcome', r.subject_type, r.subject_id,
                left(coalesce(r.expected_metric, r.decision), 120), v_lesson, v_verdict,
                case when v_claimants > 1 then left(v_others, 200) else r.actor end,
                v_conf, 'outcome_record#'||r.id, now());
      exception when others then null; end;
    end if;

    if v_verdict = 'worse' and v_is_lead then
      perform public.fn_emit('rollback.required','outcome_record', r.id::text, coalesce(r.actor,'system'),
                jsonb_build_object('decision', r.decision, 'lesson', v_lesson, 'claimants', v_claimants));
      begin
        insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
        select coalesce(r.dept_key,'exec'), 'ROLL BACK: '||left(r.decision,90),
               'Outcome record #'||r.id||' graded WORSE. '||v_lesson||' Reverse the change, confirm the metric recovers, then close.',
               'proposed','gated', false, 'incident_fix'
        where not exists (select 1 from org_tasks where title='ROLL BACK: '||left(r.decision,90) and status<>'done');
      exception when others then null; end;
    end if;
  end loop;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('outcome_evaluate', now(), now(), 'ok',
          jsonb_build_object('improved',n_improved,'worse',n_worse,'no_change',n_flat,'unmeasurable',n_unmeasurable),
          'Graded due outcomes: '||n_improved||' improved, '||n_worse||' worse (rollback opened), '||n_flat||' no change, '||n_unmeasurable||' unmeasurable.');

  return jsonb_build_object('improved',n_improved,'worse',n_worse,'no_change',n_flat,'unmeasurable',n_unmeasurable);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_outcome_open(p_actor text, p_decision text, p_subject_type text DEFAULT 'manual'::text, p_subject_id text DEFAULT NULL::text, p_expected_kpi_id bigint DEFAULT NULL::bigint, p_rationale text DEFAULT NULL::text, p_evidence jsonb DEFAULT '[]'::jsonb, p_direction text DEFAULT 'up'::text, p_measure_after interval DEFAULT '14 days'::interval)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_sql text; v_base numeric; v_metric text; v_dept text; v_id bigint;
begin
  p_actor := coalesce(public.fn_org_agent_resolve(p_actor), p_actor);
  if p_expected_kpi_id is not null then
    select measure_sql, metric into v_sql, v_metric from employee_kpi where id = p_expected_kpi_id;
    begin
      if v_sql is not null then execute v_sql into v_base; end if;
    exception when others then v_base := null; end;
  end if;

  select a.department into v_dept from org_agents a where a.agent_key = p_actor;

  insert into outcome_record (actor, dept_key, subject_type, subject_id, decision, rationale,
                              evidence, expected_kpi_id, expected_metric, expected_direction,
                              baseline_value, measure_after, due_at)
  values (p_actor, v_dept, p_subject_type, p_subject_id, p_decision, p_rationale,
          coalesce(p_evidence,'[]'::jsonb), p_expected_kpi_id, v_metric,
          coalesce(p_direction,'up'), v_base, coalesce(p_measure_after, interval '14 days'),
          now() + coalesce(p_measure_after, interval '14 days'))
  returning id into v_id;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_overlay_for_category(p_category_key text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select jsonb_build_object(
    'category_key', c.category_key,
    'route_key', c.route_key,
    'overlay_role_id', 'category_overlay_'||c.category_key,
    'owner_agent', c.owner_agent,
    'invoked_by_role', 'inquiry_router',
    'readiness', c.readiness,
    'exists', (select count(*) > 0 from public.org_role r
                where r.role_id = 'category_overlay_'||c.category_key and r.status='active'))
    from public.org_category_identity c where c.category_key = p_category_key;
$function$


CREATE OR REPLACE FUNCTION public.fn_owning_os(p_agent text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with a as (select coalesce(nullif(btrim(p_agent), ''), '~none~') k),
  stripped as (
    -- widened from _(ai|director|ops|monitor|watch|agent|bot) so a role title resolves too
    select regexp_replace(a.k, '_(ai|director|ops|monitor|watch|agent|bot|controller|curator|analyst|engineer|manager|lead|head|specialist)$', '') s
    from a)
  select coalesce(
    (select o.os_key from public.operating_system o, a where o.owner_agent = a.k and o.active limit 1),
    (select r.os_key from public.os_responsibility r, a where r.responsibility = a.k limit 1),
    (select r.os_key from public.os_responsibility r
       join public.org_agents g on g.department = r.responsibility, a
      where g.agent_key = a.k limit 1),
    (select r.os_key from public.os_responsibility r, stripped where r.responsibility = stripped.s limit 1),
    (select o.os_key from public.operating_system o, a where o.os_key = a.k and o.active limit 1),
    (select o.os_key from public.operating_system o, stripped where o.os_key = stripped.s and o.active limit 1),
    -- the live department -> OS map, which this function never consulted
    (select d.os_key from public.os_department d
       join public.org_agents g on g.department = d.dept_key, a
      where g.agent_key = a.k limit 1),
    -- a category desk ('cat:signage') is owned by whichever OS owns category coverage
    (select r.os_key from public.os_responsibility r, a
      where a.k like 'cat:%' and r.responsibility = 'category_coverage' limit 1),
    -- last resort: a role name whose stem appears in a responsibility. Ordered by the shortest
    -- responsibility so the most specific owner wins rather than whichever row is read first.
    (select r.os_key from public.os_responsibility r, stripped
      where length(stripped.s) >= 4 and r.responsibility like '%' || stripped.s || '%'
      order by length(r.responsibility), r.responsibility limit 1)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_b7_regression()
 RETURNS TABLE(case_key text, root_cause text, polarity text, lang text, expected_active text, actual_active text, expected_disp text, actual_disp text, expected_comp text, actual_comp text, expected_basis text, actual_basis text, forbidden_raised text, conflict_ok boolean, passed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.p2c1_b7_case%rowtype; g bigint; L text; txt text;
        act text[]; d text; cm text; bs text; ed text; ec text; isconf boolean; forb text[];
begin
  for c in select * from public.p2c1_b7_case order by root_cause, case_key loop
    foreach L in array array['en','ar'] loop
      txt := case when L='ar' then c.text_ar else c.text_en end;
      continue when txt is null;
      insert into public.inquiry_workstream_group (inquiry_id) values (gen_random_uuid()) returning id into g;
      perform public.fn_inquiry_interpret(g, txt, null, null, 'b7_regression');

      select coalesce(array_agg(trade_key order by trade_key),'{}') into act
        from public.inquiry_workstream where group_id = g and active;
      select coalesce(string_agg(s.trade_key||'='||s.disposition,' ' order by s.trade_key),'')
        into d from public.v_trade_scope_status s
       where s.group_id = g and s.disposition <> 'included';
      select coalesce(string_agg(distinct e.scope_component||'='||e.disposition,' '),'')
        into cm from public.v_scope_disposition_effective e
       where e.group_id = g and e.scope_component <> 'complete_trade_scope' and e.disposition <> 'included';
      select coalesce(string_agg(distinct x.classification_basis, ','), '') into bs
        from public.inquiry_scope_disposition x
       where x.group_id = g and x.disposition <> 'included';
      select exists (select 1 from public.v_trade_scope_status s where s.group_id=g and s.is_conflict) into isconf;
      select coalesce(array_agg(distinct t.trade_key order by t.trade_key),'{}') into forb
        from public.inquiry_trade_candidate t
       where t.group_id = g and t.trade_key = any(c.forbid_candidates)
         and t.status in ('proposed','confirmed');

      select coalesce(string_agg(k||'='||v,' ' order by k),'') into ed
        from jsonb_each_text(c.expect_dispositions) x(k,v);
      select coalesce(string_agg(k||'='||v,' ' order by k),'') into ec
        from jsonb_each_text(c.expect_components) x(k,v);

      case_key := c.case_key; root_cause := c.root_cause; polarity := c.polarity; lang := L;
      expected_active := array_to_string(c.expect_active,','); actual_active := array_to_string(act,',');
      expected_disp := ed; actual_disp := d; expected_comp := ec; actual_comp := cm;
      expected_basis := c.expect_basis; actual_basis := bs;
      forbidden_raised := array_to_string(forb,',');
      conflict_ok := (isconf = c.expect_conflict);
      passed := (act = c.expect_active and d = ed and cm = ec and conflict_ok
                 and cardinality(forb) = 0
                 and (c.expect_basis is null or c.expect_basis = bs));
      return next;

      perform set_config('quotesdone.p2c1_teardown','approved',true);
      delete from public.inquiry_state_audit where group_id = g;
      delete from public.inquiry_workstream_group where id = g;
      perform set_config('quotesdone.p2c1_teardown','',true);
    end loop;
  end loop;
end $function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_disposition_tests()
 RETURNS TABLE(case_key text, lang text, expected_active text, actual_active text, expected_disp text, actual_disp text, expected_comp text, actual_comp text, conflict_ok boolean, passed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.p2c1_disposition_case%rowtype; g bigint; L text; txt text;
        act text[]; d text; cm text; ed text; ec text; isconf boolean;
begin
  for c in select * from public.p2c1_disposition_case order by case_key loop
    foreach L in array array['en','ar'] loop
      txt := case when L='ar' then c.text_ar else c.text_en end;
      continue when txt is null;
      insert into public.inquiry_workstream_group (inquiry_id) values (gen_random_uuid()) returning id into g;
      perform public.fn_inquiry_interpret(g, txt, null, null, 'disposition_tests');

      select coalesce(array_agg(trade_key order by trade_key),'{}') into act
        from public.inquiry_workstream where group_id = g and active;
      select coalesce(string_agg(s.trade_key||'='||s.disposition,' ' order by s.trade_key),'')
        into d from public.v_trade_scope_status s
       where s.group_id = g and s.disposition <> 'included';
      select coalesce(string_agg(distinct e.scope_component||'='||e.disposition,' '),'')
        into cm from public.v_scope_disposition_effective e
       where e.group_id = g and e.scope_component <> 'complete_trade_scope' and e.disposition <> 'included';
      select exists (select 1 from public.v_trade_scope_status s where s.group_id=g and s.is_conflict) into isconf;

      select coalesce(string_agg(k||'='||v,' ' order by k),'') into ed
        from jsonb_each_text(c.expect_dispositions) x(k,v);
      select coalesce(string_agg(k||'='||v,' ' order by k),'') into ec
        from jsonb_each_text(c.expect_components) x(k,v);

      case_key := c.case_key; lang := L;
      expected_active := array_to_string(c.expect_active,','); actual_active := array_to_string(act,',');
      expected_disp := ed; actual_disp := d; expected_comp := ec; actual_comp := cm;
      conflict_ok := (isconf = c.expect_conflict);
      passed := (act = c.expect_active and d = ed and cm = ec and conflict_ok);
      return next;

      perform set_config('quotesdone.p2c1_teardown','approved',true);
      delete from public.inquiry_state_audit where group_id = g;
      delete from public.inquiry_workstream_group where id = g;
      perform set_config('quotesdone.p2c1_teardown','',true);
    end loop;
  end loop;
end $function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_fixture_satisfy(p_group bigint, p_ws bigint, p_actor text DEFAULT 'selftest'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare rec record; n integer := 0; v_val text;
begin
  for rec in
    select r.field_id, fd.scope, fd.allowed_values
      from public.inquiry_workstream_requirement r
      join public.field_definition fd on fd.field_id = r.field_id
     where r.workstream_id = p_ws and r.mandatory
  loop
    v_val := coalesce(rec.allowed_values[1], 'fixture-value');
    if rec.scope = 'shared' then
      perform public.fn_inquiry_answer_set(p_group, rec.field_id, v_val,
                'customer_confirmed', 'customer', p_actor);
    else
      perform public.fn_inquiry_answer_set(p_group, rec.field_id, v_val,
                'customer_confirmed', 'customer', p_actor, null, array[p_ws]);
    end if;
    n := n + 1;
  end loop;

  insert into public.inquiry_gate (group_id, workstream_id, gate_key, state, asserted_by)
  select p_group, p_ws, gr.gate_key, 'passed'::public.gate_state, p_actor
    from public.inquiry_gate_required gr where gr.level = 'workstream'
  on conflict do nothing;

  return n;
end $function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_holdout_checksum()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select encode(extensions.digest(string_agg(
           case_key || '|' || coalesce(text_en,'') || '|' || coalesce(text_ar,'') || '|'
           || array_to_string(expect_active,',') || '|' || expect_dispositions::text || '|'
           || expect_components::text || '|' || expect_clarify::text || '|' || expect_conflict::text,
           E'\n' order by case_key), 'sha256'), 'hex')
    from public.p2c1_holdout_case;
$function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_holdout_run()
 RETURNS TABLE(case_key text, category text, en_active text, ar_active text, trade_set_agree boolean, disposition_agree boolean, component_agree boolean, clarify_agree boolean, conflict_ok boolean, en_false_pos text[], en_false_neg text[], ar_false_pos text[], ar_false_neg text[], verdict text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.p2c1_holdout_case%rowtype; g bigint; L text; txt text;
        act jsonb := '{}'::jsonb; dsp jsonb := '{}'::jsonb; cmp jsonb := '{}'::jsonb;
        clr jsonb := '{}'::jsonb; cfl jsonb := '{}'::jsonb;
        a text[]; d text; m text; k boolean; x boolean; ed text; ec text; seal jsonb;
begin
  seal := public.fn_p2c1_holdout_verify_seal();
  if not coalesce((seal->>'intact')::boolean, false) then
    raise exception 'HOLDOUT SEAL BROKEN - refusing to report results: %', seal::text;
  end if;

  for c in select * from public.p2c1_holdout_case order by category, case_key loop
    act := '{}'::jsonb; dsp := '{}'::jsonb; cmp := '{}'::jsonb; clr := '{}'::jsonb; cfl := '{}'::jsonb;
    foreach L in array array['en','ar'] loop
      txt := case when L='ar' then c.text_ar else c.text_en end;
      insert into public.inquiry_workstream_group (inquiry_id) values (gen_random_uuid()) returning id into g;
      perform public.fn_inquiry_interpret(g, txt, null, null, 'holdout');

      select coalesce(array_agg(trade_key order by trade_key),'{}') into a
        from public.inquiry_workstream where group_id = g and active;
      select coalesce(string_agg(s.trade_key||'='||s.disposition,' ' order by s.trade_key),'')
        into d from public.v_trade_scope_status s where s.group_id=g and s.disposition <> 'included';
      select coalesce(string_agg(distinct e.scope_component||'='||e.disposition,' '),'')
        into m from public.v_scope_disposition_effective e
       where e.group_id=g and e.scope_component <> 'complete_trade_scope' and e.disposition <> 'included';
      select exists (select 1 from public.inquiry_trade_clarification
                      where group_id=g and answered_at is null) into k;
      select exists (select 1 from public.v_trade_scope_status s where s.group_id=g and s.is_conflict) into x;

      act := act || jsonb_build_object(L, to_jsonb(a));
      dsp := dsp || jsonb_build_object(L, d);
      cmp := cmp || jsonb_build_object(L, m);
      clr := clr || jsonb_build_object(L, k);
      cfl := cfl || jsonb_build_object(L, x);

      perform set_config('quotesdone.p2c1_teardown','approved',true);
      delete from public.inquiry_state_audit where group_id = g;
      delete from public.inquiry_workstream_group where id = g;
      perform set_config('quotesdone.p2c1_teardown','',true);
    end loop;

    select coalesce(string_agg(kk||'='||vv,' ' order by kk),'') into ed
      from jsonb_each_text(c.expect_dispositions) z(kk,vv);
    select coalesce(string_agg(kk||'='||vv,' ' order by kk),'') into ec
      from jsonb_each_text(c.expect_components) z(kk,vv);

    case_key := c.case_key; category := c.category;
    en_active := array_to_string(array(select jsonb_array_elements_text(act->'en')),',');
    ar_active := array_to_string(array(select jsonb_array_elements_text(act->'ar')),',');
    trade_set_agree   := (act->'en' = act->'ar');
    disposition_agree := (dsp->>'en' = dsp->>'ar');
    component_agree   := (cmp->>'en' = cmp->>'ar');
    clarify_agree     := (clr->>'en' = clr->>'ar');
    conflict_ok       := ((cfl->>'en')::boolean = c.expect_conflict
                          and (cfl->>'ar')::boolean = c.expect_conflict);

    en_false_pos := array(select jsonb_array_elements_text(act->'en') except select unnest(c.expect_active) order by 1);
    en_false_neg := array(select unnest(c.expect_active) except select jsonb_array_elements_text(act->'en') order by 1);
    ar_false_pos := array(select jsonb_array_elements_text(act->'ar') except select unnest(c.expect_active) order by 1);
    ar_false_neg := array(select unnest(c.expect_active) except select jsonb_array_elements_text(act->'ar') order by 1);

    verdict := case
      when trade_set_agree and disposition_agree and component_agree and clarify_agree and conflict_ok
           and cardinality(en_false_pos)=0 and cardinality(en_false_neg)=0
           and cardinality(ar_false_pos)=0 and cardinality(ar_false_neg)=0
           and dsp->>'en' = ed and cmp->>'en' = ec then 'PASS'
      when not trade_set_agree then 'PARITY_MISMATCH'
      when cardinality(en_false_pos)+cardinality(ar_false_pos) > 0 then 'FALSE_POSITIVE'
      when cardinality(en_false_neg)+cardinality(ar_false_neg) > 0 then 'FALSE_NEGATIVE'
      when not conflict_ok then 'CONFLICT_MISDETECTED'
      when dsp->>'en' <> ed then 'DISPOSITION_MISMATCH:got[' || (dsp->>'en') || ']want[' || ed || ']'
      when cmp->>'en' <> ec then 'COMPONENT_MISMATCH:got[' || (cmp->>'en') || ']want[' || ec || ']'
      else 'CLARIFY_MISMATCH' end;
    return next;
  end loop;
end $function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_holdout_verify_seal()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s public.p2c1_holdout_seal%rowtype; v_now text; v_n integer;
begin
  select * into s from public.p2c1_holdout_seal where id = 1;
  if not found then return jsonb_build_object('ok', false, 'error','not_sealed'); end if;
  v_now := public.fn_p2c1_holdout_checksum();
  select count(*) into v_n from public.p2c1_holdout_case;
  return jsonb_build_object('ok', (v_now = s.checksum_sha and v_n = s.case_count),
    'sealed_checksum', s.checksum_sha, 'current_checksum', v_now,
    'sealed_case_count', s.case_count, 'current_case_count', v_n,
    'sealed_at', s.sealed_at, 'sealed_by', s.sealed_by,
    'intact', (v_now = s.checksum_sha and v_n = s.case_count));
end $function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_lang_parity_suite()
 RETURNS TABLE(case_key text, category text, en_trades text, ar_trades text, trade_set_agree boolean, status_agree boolean, clarify_agree boolean, en_false_pos text[], en_false_neg text[], ar_false_pos text[], ar_false_neg text[], verdict text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.p2c1_lang_case%rowtype; en jsonb; ar jsonb;
        en_set text[]; ar_set text[]; en_stat text; ar_stat text;
begin
  for c in select * from public.p2c1_lang_case order by category, case_key loop
    en := public.fn_p2c1_run_lang_case(c.case_key, 'en');
    ar := public.fn_p2c1_run_lang_case(c.case_key, 'ar');

    -- the trade set under test is confirmed+proposed: what the system identified at all
    select array(select jsonb_array_elements_text(en->'confirmed')
                 union select jsonb_array_elements_text(en->'proposed') order by 1) into en_set;
    select array(select jsonb_array_elements_text(ar->'confirmed')
                 union select jsonb_array_elements_text(ar->'proposed') order by 1) into ar_set;

    en_stat := case when jsonb_array_length(en->'confirmed') > 0 then 'confirmed'
                    when jsonb_array_length(en->'proposed')  > 0 then 'proposed' else 'none' end;
    ar_stat := case when jsonb_array_length(ar->'confirmed') > 0 then 'confirmed'
                    when jsonb_array_length(ar->'proposed')  > 0 then 'proposed' else 'none' end;

    case_key := c.case_key; category := c.category;
    en_trades := array_to_string(en_set,','); ar_trades := array_to_string(ar_set,',');
    trade_set_agree := (en_set = ar_set);
    status_agree    := (en_stat = ar_stat);
    clarify_agree   := ((en->>'clarify')::boolean = (ar->>'clarify')::boolean);

    en_false_pos := array(select unnest(en_set) except select unnest(c.expect_trades) order by 1);
    en_false_neg := array(select unnest(c.expect_trades) except select unnest(en_set) order by 1);
    ar_false_pos := array(select unnest(ar_set) except select unnest(c.expect_trades) order by 1);
    ar_false_neg := array(select unnest(ar_set) except select unnest(ar_set) order by 1);
    ar_false_neg := array(select unnest(c.expect_trades) except select unnest(ar_set) order by 1);

    verdict := case
      when trade_set_agree and status_agree and clarify_agree
           and cardinality(en_false_pos)=0 and cardinality(en_false_neg)=0
           and cardinality(ar_false_pos)=0 and cardinality(ar_false_neg)=0
        then 'PASS'
      when not trade_set_agree then 'PARITY_MISMATCH'
      when cardinality(en_false_pos)+cardinality(ar_false_pos) > 0 then 'FALSE_POSITIVE'
      when cardinality(en_false_neg)+cardinality(ar_false_neg) > 0 then 'FALSE_NEGATIVE'
      else 'STATUS_OR_CLARIFY_MISMATCH' end;
    return next;
  end loop;
end $function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_no_active_trade_blocker(p_out jsonb, p_opt jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select jsonb_build_object(
    'blocker','no_active_trade','supersedes','no_active_workstream','severity','blocking',
    'excluded_or_by_others', p_out, 'optional_or_future', p_opt,
    'detail','Every detected trade is excluded, by others, optional, future-phase or unconfirmed. There is nothing in scope to dispatch.',
    'remedy','Confirm at least one trade as included, or answer the open clarification.');
$function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_rollback_stage_b(p_mode text DEFAULT 'rehearse'::text, p_actor text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_b_rel_before int; v_b_rel_after int; v_b_fn_before int; v_b_fn_after int;
  v_a_rel int; v_brand_defs int; v_brand_src int; v_selftest text; v_fail int;
  v_report jsonb;
begin
  if p_mode not in ('rehearse','commit') then
    return jsonb_build_object('ok', false, 'error','mode must be rehearse or commit');
  end if;
  if coalesce(btrim(p_actor),'') = '' then
    return jsonb_build_object('ok', false, 'error','actor_required',
      'message','Rolling back a stage is a decision. It carries a name.');
  end if;
  if not exists (select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace
                  where n.nspname='public' and t.typname='gate_state') then
    return jsonb_build_object('ok', false, 'error','stage_b_not_present',
      'message','gate_state is absent, so Stage B is already rolled back.');
  end if;

  select count(*) into v_b_rel_before from pg_class c join pg_namespace n on n.oid=c.relnamespace
   where n.nspname='public' and c.relname in ('brand_acceptance_policy_value','field_question_variant',
     'subcategory_trade_contribution','field_definition_reference','mep_trade_pattern',
     'inquiry_trade_candidate','inquiry_trade_candidate_evidence','inquiry_trade_clarification',
     'mep_evidence_weight','p2c1_lang_case','p2c1_scope_case',
     'v_workstream_brand_policy','v_inquiry_trade_status');
  select count(*) into v_b_fn_before from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname in ('fn_trade_identify','fn_trade_confirm','fn_trade_reject',
     'fn_trade_remove','fn_text_matches_pattern','fn_term_matches','fn_norm_text','fn_mep_full_scope',
     'fn_gate_state_satisfies','fn_field_value_allowed','fn_group_dispatch_report',
     'trg_inquiry_gate_state_sync','trg_inquiry_answer_value_domain','trg_mep_pattern_norm',
     'fn_p2c1_stage_b_selftest','fn_p2c1_stage_b_regression','fn_p2c1_lang_parity_suite',
     'fn_p2c1_run_lang_case','fn_p2c1_scope_rule_tests');

  -- 1. Stage B objects
  drop view if exists public.v_inquiry_trade_status cascade;
  drop view if exists public.v_workstream_brand_policy cascade;
  drop function if exists public.fn_p2c1_scope_rule_tests() cascade;
  drop function if exists public.fn_p2c1_lang_parity_suite() cascade;
  drop function if exists public.fn_p2c1_run_lang_case(text,text) cascade;
  drop function if exists public.fn_p2c1_stage_b_regression() cascade;
  drop function if exists public.fn_p2c1_stage_b_selftest() cascade;
  drop function if exists public.fn_group_dispatch_report(bigint) cascade;
  drop function if exists public.fn_trade_identify(bigint,text,jsonb,jsonb,text) cascade;
  drop function if exists public.fn_trade_confirm(bigint,text,text,text) cascade;
  drop function if exists public.fn_trade_reject(bigint,text,text,text) cascade;
  drop function if exists public.fn_trade_remove(bigint,text,text,text) cascade;
  drop function if exists public.fn_mep_full_scope(text) cascade;
  drop table if exists public.p2c1_scope_case cascade;
  drop table if exists public.p2c1_lang_case cascade;
  drop table if exists public.inquiry_trade_candidate_evidence cascade;
  drop table if exists public.inquiry_trade_clarification cascade;
  drop table if exists public.inquiry_trade_candidate cascade;
  drop trigger if exists mep_trade_pattern_norm on public.mep_trade_pattern;
  drop function if exists public.trg_mep_pattern_norm() cascade;
  drop table if exists public.mep_trade_pattern cascade;
  drop table if exists public.mep_evidence_weight cascade;
  drop table if exists public.field_definition_reference cascade;
  drop table if exists public.subcategory_trade_contribution cascade;
  drop table if exists public.field_question_variant cascade;
  drop table if exists public.brand_acceptance_policy_value cascade;
  drop function if exists public.fn_term_matches(text,text,text) cascade;
  drop function if exists public.fn_norm_text(text) cascade;
  drop function if exists public.fn_text_matches_pattern(text,text) cascade;

  -- 2. shared-table modifications
  drop trigger if exists inquiry_answer_value_domain on public.inquiry_answer;
  drop function if exists public.trg_inquiry_answer_value_domain() cascade;
  drop function if exists public.fn_field_value_allowed(text,text) cascade;
  drop trigger if exists inquiry_gate_state_sync on public.inquiry_gate;
  drop function if exists public.trg_inquiry_gate_state_sync() cascade;
  alter table public.inquiry_gate drop column if exists state;
  alter table public.inquiry_gate drop column if exists state_reason;
  drop function if exists public.fn_gate_state_satisfies(public.gate_state) cascade;
  drop type if exists public.gate_state cascade;
  update public.inquiry_gate set passed = false where passed is null;
  alter table public.inquiry_gate alter column passed set default false;
  alter table public.inquiry_gate alter column passed set not null;
  alter table public.field_definition drop column if exists allowed_values;
  alter table public.field_definition drop column if exists supersedes_field_ids;
  alter table public.mep_trade drop column if exists is_core;

  -- 3. brand policy: remove the Stage B identities, restore the Stage A ones and their mappings
  delete from public.field_definition where field_id like '%.brand_acceptance_policy%';

  insert into public.field_definition
    (field_id, scope, trade_key, label_en, label_ar, unit, answer_type,
     evidence_rule, review_status, review_note)
  select distinct on (tr.trade_key)
         tr.trade_key || '.brand_policy', 'trade_specific', tr.trade_key,
         q.question_en, q.question_ar, q.unit, q.answer_type,
         'Trade-specific: this identity may only satisfy the ' || tr.trade_key || ' workstream.',
         'question_for_founder',
         'Restored by fn_p2c1_rollback_stage_b. Stage B had merged these into shared.brand_acceptance_policy.'
    from public.mep_trade_route tr
    join public.kb_operational_route_map m on m.catalog_num = tr.catalog_num
    join kb_stage.questions q on q.subcategory_slug = m.subcategory_slug and q.field_key = 'brand_policy'
   order by tr.trade_key, q.subcategory_slug
  on conflict (field_id) do nothing;

  insert into public.field_definition_source (subcategory_slug, source_field_key, field_id)
  select distinct m.subcategory_slug, 'brand_policy', tr.trade_key || '.brand_policy'
    from public.mep_trade_route tr
    join public.kb_operational_route_map m on m.catalog_num = tr.catalog_num
    join kb_stage.questions q on q.subcategory_slug = m.subcategory_slug and q.field_key = 'brand_policy'
  on conflict (subcategory_slug, source_field_key) do nothing;

  -- 4. Stage A view chain
  execute $q1$ drop view if exists public.v_group_dispatch cascade $q1$;
  execute $q1$ drop view if exists public.v_group_completeness cascade $q1$;
  execute $q1$ drop view if exists public.v_workstream_dispatch cascade $q1$;
  execute $q1$ drop view if exists public.v_workstream_completeness cascade $q1$;
  execute $q1$ drop view if exists public.v_workstream_answer cascade $q1$;

  execute $q2$
    create view public.v_workstream_answer as
    select w.id as workstream_id, w.group_id, w.trade_key, w.active,
           a.id as answer_id, a.field_id, a.value, a.unit, a.scope, a.precedence, a.source_kind,
           a.confirmed_at,
           (a.value is not null and btrim(a.value) <> ''
            and a.precedence not in ('model_inference','unknown')) as satisfies_mandatory
      from public.inquiry_workstream w
      join public.inquiry_answer a on a.group_id = w.group_id and a.superseded_by is null
     where a.scope = 'inquiry_shared'
        or exists (select 1 from public.inquiry_answer_scope s
                    where s.answer_id = a.id and s.workstream_id = w.id)
  $q2$;

  execute $q3$
    create view public.v_workstream_completeness as
    select w.id as workstream_id, w.group_id, w.trade_key, w.active,
           count(*) filter (where r.mandatory) as required_mandatory,
           count(*) filter (where r.mandatory and va.satisfies_mandatory) as answered_mandatory,
           count(*) filter (where not r.mandatory) as required_optional,
           count(*) filter (where not r.mandatory and va.satisfies_mandatory) as answered_optional,
           coalesce(array_agg(r.field_id order by r.field_id)
                    filter (where r.mandatory and not coalesce(va.satisfies_mandatory,false)),
                    '{}'::text[]) as missing_mandatory,
           coalesce((select array_agg(distinct vc.field_id)
                       from public.v_workstream_conflict vc where vc.workstream_id = w.id),
                    '{}'::text[]) as blocked_by
      from public.inquiry_workstream w
      left join public.inquiry_workstream_requirement r on r.workstream_id = w.id
      left join public.v_workstream_answer va on va.workstream_id = w.id and va.field_id = r.field_id
     group by w.id, w.group_id, w.trade_key, w.active
  $q3$;

  execute $q4$
    create view public.v_workstream_dispatch as
    select c.workstream_id, c.group_id, c.trade_key, c.active,
           c.required_mandatory, c.answered_mandatory, c.missing_mandatory, c.blocked_by,
           (cardinality(c.missing_mandatory) = 0) as mandatory_complete,
           (cardinality(c.blocked_by) = 0)        as no_unresolved_conflict,
           not exists (select 1 from public.inquiry_gate_required gr
                        where gr.level = 'workstream'
                          and not exists (select 1 from public.inquiry_gate g
                                           where g.workstream_id = c.workstream_id
                                             and g.gate_key = gr.gate_key and g.passed)) as gates_passed,
           (c.active and cardinality(c.missing_mandatory) = 0 and cardinality(c.blocked_by) = 0
            and not exists (select 1 from public.inquiry_gate_required gr
                             where gr.level = 'workstream'
                               and not exists (select 1 from public.inquiry_gate g
                                                where g.workstream_id = c.workstream_id
                                                  and g.gate_key = gr.gate_key and g.passed))) as dispatch_eligible
      from public.v_workstream_completeness c
  $q4$;

  execute $q5$
    create view public.v_group_completeness as
    select g.id as group_id, g.inquiry_id, g.rfq_mode,
           count(*) filter (where sr.mandatory) as shared_required_mandatory,
           count(*) filter (where sr.mandatory and a.id is not null) as shared_answered_mandatory,
           coalesce(array_agg(sr.field_id order by sr.field_id)
                    filter (where sr.mandatory and a.id is null), '{}'::text[]) as shared_missing_mandatory,
           (select count(*) from public.inquiry_workstream w where w.group_id = g.id and w.active) as active_workstreams,
           (select count(*) from public.inquiry_answer_conflict c
             join public.field_definition fd on fd.field_id = c.field_id
            where c.group_id = g.id and c.resolved_at is null and fd.scope = 'shared') as open_shared_conflicts
      from public.inquiry_workstream_group g
      left join lateral (
        select r.field_id, bool_or(r.mandatory) as mandatory
          from public.inquiry_workstream_requirement r
          join public.inquiry_workstream w on w.id = r.workstream_id
          join public.field_definition fd on fd.field_id = r.field_id
         where w.group_id = g.id and w.active and fd.scope = 'shared'
         group by r.field_id
      ) sr on true
      left join public.inquiry_answer a
        on a.group_id = g.id and a.field_id = sr.field_id and a.superseded_by is null
       and a.value is not null and btrim(a.value) <> ''
       and a.precedence not in ('model_inference','unknown')
     group by g.id, g.inquiry_id, g.rfq_mode
  $q5$;

  execute $q6$
    create view public.v_group_dispatch as
    select gc.group_id, gc.inquiry_id, gc.rfq_mode, gc.active_workstreams,
           gc.shared_missing_mandatory,
           (cardinality(gc.shared_missing_mandatory) = 0) as shared_complete,
           (gc.open_shared_conflicts = 0)                 as no_unresolved_shared_conflict,
           coalesce((select bool_and(wd.dispatch_eligible) from public.v_workstream_dispatch wd
                      where wd.group_id = gc.group_id and wd.active), false) as all_active_workstreams_eligible,
           coalesce((select array_agg(wd.trade_key order by wd.trade_key) from public.v_workstream_dispatch wd
                      where wd.group_id = gc.group_id and wd.active and not wd.dispatch_eligible),
                    '{}'::text[]) as blocking_trades,
           not exists (select 1 from public.inquiry_gate_required gr
                        where gr.level = 'group'
                          and not exists (select 1 from public.inquiry_gate g
                                           where g.group_id = gc.group_id and g.workstream_id is null
                                             and g.gate_key = gr.gate_key and g.passed)) as group_gates_passed,
           (gc.active_workstreams > 0
            and cardinality(gc.shared_missing_mandatory) = 0
            and gc.open_shared_conflicts = 0
            and coalesce((select bool_and(wd.dispatch_eligible) from public.v_workstream_dispatch wd
                           where wd.group_id = gc.group_id and wd.active), false)
            and not exists (select 1 from public.inquiry_gate_required gr
                             where gr.level = 'group'
                               and not exists (select 1 from public.inquiry_gate g
                                                where g.group_id = gc.group_id and g.workstream_id is null
                                                  and g.gate_key = gr.gate_key and g.passed))) as overall_dispatch_eligible
      from public.v_group_completeness gc
  $q6$;

  -- 5. Stage A functions Stage B replaced
  execute $q7$
    create or replace function public.fn_inquiry_workstream_activate(
      p_group_id bigint, p_trade_key text, p_actor text default 'system')
    returns jsonb language plpgsql security definer set search_path to 'public' as $inner$
    declare v_ws_id bigint; v_route integer; v_reactivated boolean := false; v_reqs integer;
    begin
      if not exists (select 1 from public.mep_trade where trade_key = p_trade_key) then
        return jsonb_build_object('ok', false, 'error', 'unknown_trade', 'trade_key', p_trade_key);
      end if;
      if not exists (select 1 from public.inquiry_workstream_group where id = p_group_id) then
        return jsonb_build_object('ok', false, 'error', 'unknown_group');
      end if;
      select catalog_num into v_route from public.mep_trade_route
       where trade_key = p_trade_key and is_primary order by catalog_num limit 1;
      select id into v_ws_id from public.inquiry_workstream
       where group_id = p_group_id and trade_key = p_trade_key;
      if v_ws_id is null then
        insert into public.inquiry_workstream (group_id, trade_key, route_catalog_num)
        values (p_group_id, p_trade_key, v_route) returning id into v_ws_id;
      else
        update public.inquiry_workstream set active = true, activated_at = now(), deactivated_at = null
         where id = v_ws_id and active = false;
        v_reactivated := found;
        update public.inquiry_workstream set active = true where id = v_ws_id;
      end if;
      insert into public.inquiry_workstream_requirement (workstream_id, question_id, field_id, mandatory)
      select v_ws_id, min(q.question_id), s.field_id, bool_or(q.mandatory)
        from public.mep_trade_route tr
        join public.kb_operational_route_map m on m.catalog_num = tr.catalog_num
        join kb_stage.questions q on q.subcategory_slug = m.subcategory_slug
        join public.field_definition_source s
          on s.subcategory_slug = q.subcategory_slug and s.source_field_key = q.field_key
       where tr.trade_key = p_trade_key and q.field_key is not null
       group by s.field_id
      on conflict (workstream_id, field_id) do update
         set mandatory = public.inquiry_workstream_requirement.mandatory or excluded.mandatory;
      get diagnostics v_reqs = row_count;
      insert into public.inquiry_state_audit (group_id, workstream_id, event, detail, actor)
      values (p_group_id, v_ws_id,
              case when v_reactivated then 'workstream_reactivated' else 'workstream_activated' end,
              jsonb_build_object('trade_key', p_trade_key, 'route_catalog_num', v_route,
                                 'requirements', v_reqs), p_actor);
      return jsonb_build_object('ok', true, 'workstream_id', v_ws_id, 'trade_key', p_trade_key,
                                'reactivated', v_reactivated, 'requirements', v_reqs);
    end $inner$
  $q7$;

  execute $q8$
    create or replace function public.fn_p2c1_fixture_satisfy(
      p_group bigint, p_ws bigint, p_actor text default 'selftest')
    returns integer language plpgsql security definer set search_path to 'public' as $inner$
    declare rec record; n integer := 0;
    begin
      for rec in
        select r.field_id, fd.scope from public.inquiry_workstream_requirement r
          join public.field_definition fd on fd.field_id = r.field_id
         where r.workstream_id = p_ws and r.mandatory
      loop
        if rec.scope = 'shared' then
          perform public.fn_inquiry_answer_set(p_group, rec.field_id, 'fixture-value',
                    'customer_confirmed', 'customer', p_actor);
        else
          perform public.fn_inquiry_answer_set(p_group, rec.field_id, 'fixture-value',
                    'customer_confirmed', 'customer', p_actor, null, array[p_ws]);
        end if;
        n := n + 1;
      end loop;
      insert into public.inquiry_gate (group_id, workstream_id, gate_key, passed, asserted_by)
      select p_group, p_ws, gr.gate_key, true, p_actor
        from public.inquiry_gate_required gr where gr.level = 'workstream'
      on conflict do nothing;
      return n;
    end $inner$
  $q8$;

  -- 6. checks
  select count(*) into v_b_rel_after from pg_class c join pg_namespace n on n.oid=c.relnamespace
   where n.nspname='public' and c.relname in ('brand_acceptance_policy_value','field_question_variant',
     'subcategory_trade_contribution','field_definition_reference','mep_trade_pattern',
     'inquiry_trade_candidate','inquiry_trade_candidate_evidence','inquiry_trade_clarification',
     'mep_evidence_weight','p2c1_lang_case','p2c1_scope_case',
     'v_workstream_brand_policy','v_inquiry_trade_status');
  select count(*) into v_b_fn_after from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname in ('fn_trade_identify','fn_trade_confirm','fn_trade_reject',
     'fn_trade_remove','fn_text_matches_pattern','fn_term_matches','fn_norm_text','fn_mep_full_scope',
     'fn_gate_state_satisfies','fn_field_value_allowed','fn_group_dispatch_report',
     'trg_inquiry_gate_state_sync','trg_inquiry_answer_value_domain','trg_mep_pattern_norm',
     'fn_p2c1_stage_b_selftest','fn_p2c1_stage_b_regression','fn_p2c1_lang_parity_suite',
     'fn_p2c1_run_lang_case','fn_p2c1_scope_rule_tests');
  select count(*) into v_a_rel from pg_class c join pg_namespace n on n.oid=c.relnamespace
   where n.nspname='public' and c.relname in ('inquiry_answer','inquiry_workstream','field_definition',
     'field_definition_source','inquiry_answer_conflict','inquiry_state_audit','mep_subcategory_review',
     'v_workstream_answer','v_workstream_dispatch','v_group_dispatch');
  select count(*) into v_brand_defs from public.field_definition where field_id like '%.brand_policy';
  select count(*) into v_brand_src from public.field_definition_source where source_field_key = 'brand_policy';

  if v_b_rel_after <> 0 then raise exception 'ROLLBACK ABORTED: % Stage B relations survived', v_b_rel_after; end if;
  if v_b_fn_after <> 0 then raise exception 'ROLLBACK ABORTED: % Stage B functions survived', v_b_fn_after; end if;
  if v_a_rel <> 10 then raise exception 'ROLLBACK ABORTED: expected 10 Stage A objects, found %', v_a_rel; end if;
  if v_brand_defs = 0 then raise exception 'ROLLBACK ABORTED: *.brand_policy identities were not restored'; end if;
  if v_brand_src = 0 then raise exception 'ROLLBACK ABORTED: brand_policy source mappings were not restored'; end if;

  -- 7. the real check: does Stage A still work?
  select count(*) filter (where not passed) into v_fail from public.fn_p2c1_stage_a_selftest();
  select count(*) filter (where passed)||'/'||count(*) into v_selftest from public.fn_p2c1_stage_a_selftest();
  if v_fail > 0 then
    raise exception 'ROLLBACK ABORTED: Stage A self-test is % after rollback', v_selftest;
  end if;

  v_report := jsonb_build_object(
    'ok', true, 'mode', p_mode, 'actor', p_actor,
    'stage_b_relations', v_b_rel_before || ' -> ' || v_b_rel_after,
    'stage_b_functions', v_b_fn_before || ' -> ' || v_b_fn_after,
    'stage_a_objects_present', v_a_rel || '/10',
    'brand_policy_identities_restored', v_brand_defs,
    'brand_policy_source_mappings_restored', v_brand_src,
    'stage_a_selftest', v_selftest);

  insert into public.inquiry_state_audit (group_id, event, detail, actor)
  values (null, 'p2c1_stage_b_rollback_' || p_mode, v_report, p_actor);

  if p_mode = 'rehearse' then
    raise exception 'REHEARSAL COMPLETE (nothing committed): %', v_report::text;
  end if;

  return v_report;
end $function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_rollback_stage_b6(p_mode text DEFAULT 'rehearse'::text, p_actor text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_removable_before int; v_removable_after int;
  v_a text; v_b text; v_lang text; v_scope text;
  v_report jsonb; v_survivors jsonb; v_restored jsonb; v_fixtures jsonb;
  v_tm_b5 boolean; v_gdr_b5 boolean; v_mfs_fixed boolean;
  v_orphan_groups int; v_orphan_answers int; v_orphan_audit int;
  v_missing text;
  c_tables text[] := array['inquiry_scope_disposition','scope_marker','scope_disposition_kind',
                           'scope_component','p2c1_disposition_case','p2c1_holdout_case','p2c1_holdout_seal'];
  c_views  text[] := array['v_scope_disposition_effective','v_trade_scope_status'];
  c_funcs  text[] := array['fn_p2c1_holdout_run','fn_p2c1_disposition_tests','fn_p2c1_holdout_verify_seal',
                           'fn_p2c1_holdout_checksum','fn_inquiry_interpret','fn_scope_apply','fn_scope_detect',
                           'fn_scope_inverse','fn_scope_clauses','fn_term_position',
                           'fn_p2c1_no_active_trade_blocker','trg_holdout_expectations_immutable',
                           'trg_scope_marker_norm'];
begin
  if p_mode not in ('rehearse','commit') then
    return jsonb_build_object('ok', false, 'error','mode must be rehearse or commit'); end if;
  if coalesce(btrim(p_actor),'') = '' then
    return jsonb_build_object('ok', false, 'error','actor_required'); end if;
  if to_regclass('public.inquiry_scope_disposition') is null then
    return jsonb_build_object('ok', false, 'error','stage_b6_not_present'); end if;

  select (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace
           where n.nspname='public' and (c.relname = any(c_tables) or c.relname = any(c_views)))
       + (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace
           where n.nspname='public' and p.proname = any(c_funcs))
    into v_removable_before;

  ---------------------------------------------------------------- remove
  drop view if exists public.v_trade_scope_status cascade;
  drop view if exists public.v_scope_disposition_effective cascade;
  drop function if exists public.fn_p2c1_holdout_run() cascade;
  drop function if exists public.fn_p2c1_disposition_tests() cascade;
  drop function if exists public.fn_p2c1_holdout_verify_seal() cascade;
  drop function if exists public.fn_p2c1_holdout_checksum() cascade;
  drop function if exists public.fn_inquiry_interpret(bigint,text,jsonb,jsonb,text) cascade;
  drop function if exists public.fn_scope_apply(bigint,text) cascade;
  drop function if exists public.fn_scope_detect(bigint,text,text) cascade;
  drop function if exists public.fn_scope_inverse(text) cascade;
  drop function if exists public.fn_scope_clauses(text) cascade;
  drop function if exists public.fn_term_position(text,text,text) cascade;
  drop function if exists public.fn_p2c1_no_active_trade_blocker(jsonb,jsonb) cascade;
  drop table if exists public.p2c1_disposition_case cascade;
  drop table if exists public.p2c1_holdout_seal cascade;
  drop trigger if exists holdout_expectations_immutable on public.p2c1_holdout_case;
  drop function if exists public.trg_holdout_expectations_immutable() cascade;
  drop table if exists public.p2c1_holdout_case cascade;
  drop trigger if exists scope_marker_norm on public.scope_marker;
  drop function if exists public.trg_scope_marker_norm() cascade;
  drop table if exists public.inquiry_scope_disposition cascade;
  drop table if exists public.scope_marker cascade;
  drop table if exists public.scope_disposition_kind cascade;
  drop table if exists public.scope_component cascade;
  delete from public.mep_trade_pattern where pattern in
    ('وحدات مناوله الهواء','فان كويل','شيلر');

  ---------------------------------------------------------------- restore prior stage
  execute $q1$
    create or replace function public.fn_term_matches(
      p_text_norm text, p_pattern_norm text, p_lang text default 'en')
    returns boolean language sql immutable as $i$
      select case when p_lang = 'ar'
        then p_text_norm ~ ('(^|[^[:alnum:]])(وال|بال|فال|كال|ال|لل|و|ف|ب|ك|ل)?'
                            || p_pattern_norm || '(ات|ين|ون|ها|هم|ه)?($|[^[:alnum:]])')
        else p_text_norm ~ ('(^|[^[:alnum:]])' || p_pattern_norm || '($|[^[:alnum:]])')
      end;
    $i$
  $q1$;

  execute $q2$
    create or replace function public.fn_group_dispatch_report(p_group_id bigint)
    returns jsonb language plpgsql stable security definer set search_path to 'public' as $i$
    declare v_gd public.v_group_dispatch%rowtype; v_blockers jsonb := '[]'::jsonb; r record;
    begin
      select * into v_gd from public.v_group_dispatch where group_id = p_group_id;
      if not found then return jsonb_build_object('ok', false, 'error','unknown_group'); end if;
      if v_gd.active_workstreams = 0 then
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
          'blocker','no_active_workstream','severity','blocking',
          'detail','No trade has been confirmed for this inquiry, so there is nothing to dispatch.'));
      end if;
      if cardinality(v_gd.shared_missing_mandatory) > 0 then
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
          'blocker','shared_mandatory_missing','severity','blocking',
          'fields', to_jsonb(v_gd.shared_missing_mandatory)));
      end if;
      for r in select * from public.v_workstream_dispatch
                where group_id = p_group_id and active and not dispatch_eligible loop
        v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
          'blocker','trade_not_eligible','severity','blocking','trade_key', r.trade_key,
          'missing_mandatory', to_jsonb(r.missing_mandatory), 'gate_states', r.gate_states));
      end loop;
      return jsonb_build_object('ok', true, 'group_id', p_group_id,
        'overall_dispatch_eligible', v_gd.overall_dispatch_eligible,
        'active_workstreams', v_gd.active_workstreams,
        'group_gate_states', v_gd.gate_states, 'blockers', v_blockers,
        'blocker_count', jsonb_array_length(v_blockers));
    end $i$
  $q2$;

  ---------------------------------------------------------------- verify: nothing removable left
  select (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace
           where n.nspname='public' and (c.relname = any(c_tables) or c.relname = any(c_views)))
       + (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace
           where n.nspname='public' and p.proname = any(c_funcs))
    into v_removable_after;
  if v_removable_after <> 0 then
    raise exception 'ROLLBACK ABORTED: % removable Stage B.6 objects survived', v_removable_after; end if;

  ---------------------------------------------------------------- verify: survivors are all present
  v_missing := '';
  if to_regclass('public.p2c1_holdout_result_of_record') is null then
    v_missing := v_missing || 'p2c1_holdout_result_of_record '; end if;
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
                  where n.nspname='public' and p.proname='trg_holdout_record_immutable') then
    v_missing := v_missing || 'trg_holdout_record_immutable() '; end if;
  if not exists (select 1 from pg_trigger t where t.tgname='holdout_record_immutable' and not t.tgisinternal) then
    v_missing := v_missing || 'trigger holdout_record_immutable '; end if;
  if v_missing <> '' then
    raise exception 'ROLLBACK ABORTED: audit evidence that must survive is missing: %', v_missing; end if;

  v_survivors := jsonb_build_array(
    jsonb_build_object('object','p2c1_holdout_result_of_record','kind','table','class','B',
      'reason','permanent audit evidence: the once-only record of the first independent evaluation of holdout v1',
      'rows', (select count(*) from public.p2c1_holdout_result_of_record)),
    jsonb_build_object('object','trg_holdout_record_immutable()','kind','function','class','B',
      'reason','protects the row above; an editable audit record is not evidence'),
    jsonb_build_object('object','holdout_record_immutable','kind','trigger','class','B',
      'reason','protects the row above; an editable audit record is not evidence'),
    jsonb_build_object('object','fn_p2c1_rollback_stage_b6(text,text)','kind','function','class','instrument',
      'reason','the tool performing this rollback; returns stage_b6_not_present if re-run'));

  ---------------------------------------------------------------- verify: prior stage restored
  -- executed dynamically so the probe cannot be answered by a plan cached against the pre-restore body
  execute 'select public.fn_term_matches($1,$2,$3)' into v_tm_b5 using 'ahus','ahu','en';
  select p.prosrc not like '%scope%' into v_gdr_b5
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname='fn_group_dispatch_report';
  select p.prosrc like '%v_sep%' into v_mfs_fixed
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname='fn_mep_full_scope';

  if v_tm_b5 then
    raise exception 'ROLLBACK ABORTED: fn_term_matches still matches the English plural "ahus"; the B.5 form was not restored'; end if;
  if not coalesce(v_gdr_b5, false) then
    raise exception 'ROLLBACK ABORTED: fn_group_dispatch_report still mentions scope; the B.5 form was not restored'; end if;
  if not coalesce(v_mfs_fixed, false) then
    raise exception 'ROLLBACK ABORTED: fn_mep_full_scope is not the corrected form; see the declared exception'; end if;

  v_restored := jsonb_build_object(
    'fn_term_matches','Stage B.5 form verified: does not match the English plural "ahus"',
    'fn_group_dispatch_report','Stage B.5 form verified: no scope sections',
    'mep_trade_pattern','3 Stage B.6 Arabic HVAC patterns deleted');

  ---------------------------------------------------------------- verify: suites
  select count(*) filter (where passed)||'/'||count(*) into v_a from public.fn_p2c1_stage_a_selftest();
  select count(*) filter (where passed)||'/'||count(*) into v_b from public.fn_p2c1_stage_b_selftest();
  select count(*) filter (where verdict='PASS')||'/'||count(*) into v_lang from public.fn_p2c1_lang_parity_suite();
  select count(*) filter (where passed)||'/'||count(*) into v_scope from public.fn_p2c1_scope_rule_tests();
  if v_a <> '14/14' or v_b <> '14/14' then
    raise exception 'ROLLBACK ABORTED: Stage A %, Stage B % after rollback', v_a, v_b; end if;
  if v_lang <> '23/23' or v_scope <> '12/12' then
    raise exception 'ROLLBACK ABORTED: Stage B.5 language parity %, scope negatives % after rollback', v_lang, v_scope; end if;

  ---------------------------------------------------------------- verify: no fixture data remains
  select count(*) into v_orphan_groups
    from public.inquiry_workstream_group g
   where not exists (select 1 from public.inquiry_intake i where i.id::text = g.inquiry_id::text);
  select count(*) into v_orphan_answers
    from public.inquiry_answer a join public.inquiry_workstream_group g on g.id = a.group_id
   where not exists (select 1 from public.inquiry_intake i where i.id::text = g.inquiry_id::text);
  select count(*) into v_orphan_audit
    from public.inquiry_state_audit s join public.inquiry_workstream_group g on g.id = s.group_id
   where not exists (select 1 from public.inquiry_intake i where i.id::text = g.inquiry_id::text);
  if v_orphan_groups <> 0 or v_orphan_answers <> 0 or v_orphan_audit <> 0 then
    raise exception 'ROLLBACK ABORTED: fixture data remains - % groups, % answers, % audit rows with no real inquiry',
      v_orphan_groups, v_orphan_answers, v_orphan_audit; end if;
  v_fixtures := jsonb_build_object('orphan_groups', v_orphan_groups,
    'orphan_answers', v_orphan_answers, 'orphan_audit_rows', v_orphan_audit);

  ---------------------------------------------------------------- report
  v_report := jsonb_build_object(
    'ok', true, 'mode', p_mode, 'actor', p_actor,
    'removable_objects', jsonb_build_object('before', v_removable_before, 'after', v_removable_after,
       'all_removed', v_removable_after = 0,
       'inventory', jsonb_build_object('tables', to_jsonb(c_tables), 'views', to_jsonb(c_views),
                                       'functions', to_jsonb(c_funcs))),
    'intentional_survivors', v_survivors,
    'prior_stage_restored', v_restored,
    'declared_exceptions', jsonb_build_array(jsonb_build_object(
       'object','fn_mep_full_scope(text)','action','NOT restored to the Stage B.5 text',
       'reason','the B.6 change was a defect fix to a Stage B.5 rule. Reverting it reintroduces a false positive - a full-scope modifier reaching an MEP anchor across a clause boundary and activating three trades. Reversion is unsafe, so the corrected form is kept and declared.')),
    'tests', jsonb_build_object('stage_a', v_a, 'stage_b', v_b,
                                'lang_parity', v_lang, 'scope_negatives', v_scope),
    'fixtures_remaining', v_fixtures,
    'verdict', 'stage b6 removed; audit evidence retained; prior stage restored');

  insert into public.inquiry_state_audit (group_id, event, detail, actor)
  values (null, 'p2c1_stage_b6_rollback_' || p_mode, v_report, p_actor);

  if p_mode = 'rehearse' then
    raise exception 'REHEARSAL COMPLETE (nothing committed): %', v_report::text; end if;
  return v_report;
end $function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_rollback_stage_b7(p_mode text DEFAULT 'rehearse'::text, p_actor text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_before int; v_after int; v_markers_before int; v_markers_after int;
  v_a text; v_b text; v_lang text; v_scope text; v_disp text;
  v_h_exec int; v_h_pass int; v_h_fp int; v_h_fn int;
  v_detect_b6 boolean; v_mfs_b6 boolean; v_pkg_back boolean;
  v_report jsonb;
  c_funcs text[] := array['fn_scope_party','fn_scope_supply_attribution','fn_scope_clause_map',
                          'fn_scope_sentences','fn_p2c1_b7_regression'];
begin
  if p_mode not in ('rehearse','commit') then
    return jsonb_build_object('ok', false, 'error','mode must be rehearse or commit'); end if;
  if coalesce(btrim(p_actor),'') = '' then
    return jsonb_build_object('ok', false, 'error','actor_required'); end if;
  if to_regclass('public.p2c1_b7_case') is null then
    return jsonb_build_object('ok', false, 'error','stage_b7_not_present'); end if;

  select (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace
           where n.nspname='public' and c.relname = 'p2c1_b7_case')
       + (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace
           where n.nspname='public' and p.proname = any(c_funcs))
    into v_before;
  select count(*) into v_markers_before from public.scope_marker
   where marker_type in ('party','attribution','supply_anchor');

  ---------------------------------------------------------------- remove stage-owned objects
  drop table if exists public.p2c1_b7_case cascade;
  drop function if exists public.fn_p2c1_b7_regression() cascade;
  drop function if exists public.fn_scope_supply_attribution(text) cascade;
  drop function if exists public.fn_scope_party(text) cascade;
  drop function if exists public.fn_scope_clause_map(text) cascade;
  drop function if exists public.fn_scope_sentences(text) cascade;

  ---------------------------------------------------------------- remove B.7 vocabulary
  delete from public.scope_marker where marker_type in ('party','attribution','supply_anchor');
  delete from public.scope_marker where marker_type = 'disposition' and resolution = 'party_dependent'
    and pattern not in ('not in our scope','outside our scope','ليست ضمن نطاق','خارج نطاق');
  delete from public.scope_marker where marker_type = 'disposition' and disposition = 'client_supplied'
    and pattern in ('supply by client','supply by the client','supplied by the owner',
      'supplied by the employer','supplied by the customer','client to supply','client will supply',
      'client shall supply','client to provide','client will provide','owner to supply',
      'employer to supply','customer to supply','free issue by the employer','free issue by the client',
      'free issued by the client','free issue material','employer supplied','customer supplied',
      'توريد صاحب العمل','توريد الزبون','يوفرها العميل','يوردها المالك','العميل يورد','العميل يوفر',
      'من توريد العميل','توريد من العميل');
  update public.scope_marker set disposition = 'by_others', resolution = 'fixed', priority = 20
   where marker_type = 'disposition'
     and pattern in ('not in our scope','outside our scope','ليست ضمن نطاق','خارج نطاق');

  delete from public.mep_trade_pattern where kind = 'trade_hint'
    and pattern in ('ac','a/c','a\.c');
  delete from public.mep_trade_pattern where kind = 'trade_name'
    and pattern in ('central ac','central a/c','central a\.c','central air conditioner',
      'central cooling','ac unit','a/c unit','ac system','split ac','split a/c','window ac',
      'ducted ac','package ac','packaged ac','مكيفات مركزيه','تبريد مركزي');
  delete from public.mep_trade_pattern where kind = 'scope_container' and pattern <> 'package';
  delete from public.mep_trade_pattern where kind = 'scope_full'
    and pattern in ('متكامله','متكامل','تسليم مفتاح');
  update public.mep_trade_pattern set kind = 'scope_full'
   where kind = 'scope_container' and pattern = 'package';

  alter table public.mep_trade_pattern drop constraint if exists mep_trade_pattern_kind_check;
  alter table public.mep_trade_pattern add constraint mep_trade_pattern_kind_check
    check (kind in ('trade_name','trade_hint','mep_anchor','mep_full_phrase','scope_full','scope_only'));
  alter table public.scope_marker drop constraint if exists scope_marker_marker_type_check;
  alter table public.scope_marker add constraint scope_marker_marker_type_check
    check (marker_type in ('disposition','component','exception','modification'));

  ---------------------------------------------------------------- restore the Stage B.6 bodies
  execute $q1$
    create or replace function public.fn_mep_full_scope(p_text_norm text)
    returns jsonb language plpgsql stable security definer set search_path to 'public' as $i$
    declare r record; v_re text; v_sep text := '[^[:alnum:].;,،؛' || chr(10) || ']+';
    begin
      for r in select pattern_norm, lang from public.mep_trade_pattern where kind = 'mep_full_phrase' loop
        if public.fn_term_matches(p_text_norm, r.pattern_norm, r.lang) then
          return jsonb_build_object('matched', true, 'basis', 'explicit_full_mep_phrase',
                                    'anchor', r.pattern_norm, 'modifier', null);
        end if;
      end loop;
      for r in
        select a.pattern_norm as anchor, m.pattern_norm as modifier, a.lang
          from public.mep_trade_pattern a
          join public.mep_trade_pattern m on m.kind = 'scope_full'
         where a.kind = 'mep_anchor'
      loop
        v_re := '(^|[^[:alnum:]])' || r.anchor || '(' || v_sep || '[[:alnum:]]+){0,2}' || v_sep
                || r.modifier || '($|[^[:alnum:]])';
        if p_text_norm ~ v_re then
          return jsonb_build_object('matched', true, 'basis', 'anchor_plus_modifier',
                                    'anchor', r.anchor, 'modifier', r.modifier);
        end if;
        v_re := '(^|[^[:alnum:]])' || r.modifier || '(' || v_sep || '[[:alnum:]]+){0,2}' || v_sep
                || r.anchor || '($|[^[:alnum:]])';
        if p_text_norm ~ v_re then
          return jsonb_build_object('matched', true, 'basis', 'modifier_plus_anchor',
                                    'anchor', r.anchor, 'modifier', r.modifier);
        end if;
      end loop;
      return jsonb_build_object('matched', false, 'basis', null);
    end $i$
  $q1$;

  execute $q2$
    create or replace function public.fn_scope_detect(
      p_group_id bigint, p_customer_text text, p_actor text default 'system')
    returns integer language plpgsql security definer set search_path to 'public' as $i$
    declare
      v_norm text := public.fn_norm_text(p_customer_text);
      cl record; m record;
      v_exc_pos int; v_base text; v_base_marker text; v_pos int;
      v_umbrella boolean; v_umb_pos int;
      v_comps text[]; v_comp text; v_n integer := 0;
      v_trades jsonb; v_tk text; v_tpos int; v_disp text; v_spec int;
      v_active_trades text[];
    begin
      for cl in select * from public.fn_scope_clauses(v_norm) loop
        v_exc_pos := null;
        for m in select pattern_norm, lang from public.scope_marker where marker_type = 'exception' loop
          v_pos := public.fn_term_position(cl.clause, m.pattern_norm, m.lang);
          if v_pos > 0 and (v_exc_pos is null or v_pos < v_exc_pos) then v_exc_pos := v_pos; end if;
        end loop;

        v_base := null; v_base_marker := null;
        for m in select disposition, pattern_norm, lang, priority from public.scope_marker
                  where marker_type = 'disposition' order by priority, length(pattern_norm) desc loop
          v_pos := public.fn_term_position(cl.clause, m.pattern_norm, m.lang);
          if v_pos > 0 and (v_exc_pos is null or v_pos < v_exc_pos) then
            v_base := m.disposition; v_base_marker := m.pattern_norm; exit;
          end if;
        end loop;

        select coalesce(array_agg(distinct m2.component), '{}') into v_comps
          from public.scope_marker m2
         where m2.marker_type = 'component'
           and public.fn_term_matches(cl.clause, m2.pattern_norm, m2.lang);

        select coalesce(bool_or(public.fn_term_position(cl.clause, p.pattern_norm, p.lang) > 0), false),
               min(nullif(public.fn_term_position(cl.clause, p.pattern_norm, p.lang), 0))
          into v_umbrella, v_umb_pos
          from public.mep_trade_pattern p where p.kind in ('mep_anchor','mep_full_phrase');

        select coalesce(jsonb_object_agg(z.tk, z.p), '{}'::jsonb) into v_trades
          from (
            select t.trade_key as tk, min(t.pos) as p
              from (
                select p.trade_key, public.fn_term_position(cl.clause, p.pattern_norm, p.lang) as pos
                  from public.mep_trade_pattern p
                 where p.kind in ('trade_name','trade_hint') and p.trade_key is not null
                union all
                select c.trade_key,
                       public.fn_term_position(cl.clause, public.fn_norm_text(e.matched_term), 'en')
                  from public.inquiry_trade_candidate c
                  join public.inquiry_trade_candidate_evidence e on e.candidate_id = c.id
                 where c.group_id = p_group_id and e.matched_term is not null
                   and e.evidence_source in ('alias','customer_text')
                   and length(e.matched_term) >= 3
              ) t
             where t.pos > 0
             group by t.trade_key
          ) z;

        if v_base is null and (v_umbrella or v_trades <> '{}'::jsonb) then v_base := 'included'; end if;
        if v_base is null then continue; end if;

        foreach v_comp in array (case when cardinality(v_comps) = 0
                                      then array['complete_trade_scope'] else v_comps end) loop
          for v_tk, v_tpos in select key, value::int from jsonb_each_text(v_trades) loop
            v_disp := case when v_exc_pos is not null and v_tpos > v_exc_pos
                           then public.fn_scope_inverse(v_base) else v_base end;
            v_spec := 2 + (case when v_comp = 'complete_trade_scope' then 0 else 1 end);
            insert into public.inquiry_scope_disposition
              (group_id, trade_key, scope_component, disposition, specificity, source_kind,
               evidence_source, evidence_score, clause_index, clause_text, matched_marker, reason, actor)
            values (p_group_id, v_tk, v_comp, v_disp, v_spec, 'customer_text', 'customer_text', 0.950,
                    cl.idx, cl.clause, v_base_marker,
                    'Clause ' || cl.idx || ' names this trade' ||
                      case when v_comp <> 'complete_trade_scope' then ' and the ' || v_comp || ' component' else '' end ||
                      case when v_exc_pos is not null and v_tpos > v_exc_pos
                           then ', after an exception marker, so the clause disposition is inverted' else '' end ||
                      '. Marker: ' || coalesce(v_base_marker,'(none - default included)') || '.', p_actor);
            v_n := v_n + 1;
          end loop;

          if v_umbrella then
            insert into public.inquiry_scope_disposition
              (group_id, trade_key, scope_component, disposition, specificity, source_kind,
               evidence_source, evidence_score, clause_index, clause_text, matched_marker, reason, actor)
            select p_group_id, t.trade_key, v_comp,
                   case when v_exc_pos is not null and v_umb_pos > v_exc_pos
                        then public.fn_scope_inverse(v_base) else v_base end,
                   (case when v_comp = 'complete_trade_scope' then 0 else 1 end),
                   'customer_text','customer_text', 0.900, cl.idx, cl.clause, v_base_marker,
                   'Clause ' || cl.idx || ' uses an MEP umbrella term' ||
                     case when v_comp <> 'complete_trade_scope' then ' with the ' || v_comp || ' component' else '' end ||
                     '. Applied to the core trades at umbrella specificity, so any named-trade instruction outranks it. Marker: '
                     || coalesce(v_base_marker,'(none - default included)') || '.', p_actor
              from public.mep_trade t where t.is_core and not (v_trades ? t.trade_key);
            v_n := v_n + (select count(*) from public.mep_trade t where t.is_core and not (v_trades ? t.trade_key));
          end if;

          if not v_umbrella and v_trades = '{}'::jsonb and v_comp <> 'complete_trade_scope' then
            select coalesce(array_agg(distinct c.trade_key), '{}') into v_active_trades
              from public.inquiry_trade_candidate c
             where c.group_id = p_group_id and c.status in ('confirmed','proposed');
            insert into public.inquiry_scope_disposition
              (group_id, trade_key, scope_component, disposition, specificity, source_kind,
               evidence_source, evidence_score, clause_index, clause_text, matched_marker, reason, actor)
            select p_group_id, t, v_comp, v_base, 1, 'customer_text','customer_text', 0.900,
                   cl.idx, cl.clause, v_base_marker,
                   'Clause ' || cl.idx || ' names the ' || v_comp || ' component with no trade, so it applies to the trades already in play.', p_actor
              from unnest(v_active_trades) t;
            v_n := v_n + coalesce(cardinality(v_active_trades),0);
          end if;
        end loop;
      end loop;
      return v_n;
    end $i$
  $q2$;

  ---------------------------------------------------------------- verify: nothing removable left
  select (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace
           where n.nspname='public' and c.relname = 'p2c1_b7_case')
       + (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace
           where n.nspname='public' and p.proname = any(c_funcs))
    into v_after;
  if v_after <> 0 then
    raise exception 'ROLLBACK ABORTED: % removable Stage B.7 objects survived', v_after; end if;
  select count(*) into v_markers_after from public.scope_marker
   where marker_type in ('party','attribution','supply_anchor');
  if v_markers_after <> 0 then
    raise exception 'ROLLBACK ABORTED: % Stage B.7 marker rows survived', v_markers_after; end if;

  ---------------------------------------------------------------- verify: the B.6 bodies are back
  -- probed by behaviour and by source, never by assuming the DDL took
  select p.prosrc not like '%fn_scope_party%' into v_detect_b6
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname='fn_scope_detect';
  select p.prosrc not like '%scope_container%' into v_mfs_b6
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname='fn_mep_full_scope';
  select exists (select 1 from public.mep_trade_pattern
                  where kind='scope_full' and pattern='package') into v_pkg_back;
  if not coalesce(v_detect_b6,false) then
    raise exception 'ROLLBACK ABORTED: fn_scope_detect still calls the B.7 party detector'; end if;
  if not coalesce(v_mfs_b6,false) then
    raise exception 'ROLLBACK ABORTED: fn_mep_full_scope still reads the B.7 container class'; end if;
  if not v_pkg_back then
    raise exception 'ROLLBACK ABORTED: `package` was not returned to the scope_full class'; end if;

  ---------------------------------------------------------------- verify: the B.6 measurements
  select count(*) filter (where passed)||'/'||count(*) into v_a from public.fn_p2c1_stage_a_selftest();
  select count(*) filter (where passed)||'/'||count(*) into v_b from public.fn_p2c1_stage_b_selftest();
  select count(*) filter (where verdict='PASS')||'/'||count(*) into v_lang from public.fn_p2c1_lang_parity_suite();
  select count(*) filter (where passed)||'/'||count(*) into v_scope from public.fn_p2c1_scope_rule_tests();
  select count(*) filter (where passed)||'/'||count(*) into v_disp from public.fn_p2c1_disposition_tests();
  select count(*), count(*) filter (where verdict='PASS'),
         coalesce(sum(cardinality(en_false_pos))+sum(cardinality(ar_false_pos)),0),
         coalesce(sum(cardinality(en_false_neg))+sum(cardinality(ar_false_neg)),0)
    into v_h_exec, v_h_pass, v_h_fp, v_h_fn from public.fn_p2c1_holdout_run();

  if v_a <> '14/14' or v_b <> '14/14' then
    raise exception 'ROLLBACK ABORTED: Stage A %, Stage B % after rollback', v_a, v_b; end if;
  if v_lang <> '23/23' or v_scope <> '12/12' or v_disp <> '22/22' then
    raise exception 'ROLLBACK ABORTED: lang parity %, scope negatives %, disposition % after rollback',
      v_lang, v_scope, v_disp; end if;
  if v_h_exec <> 54 or v_h_pass <> 49 or v_h_fp <> 0 or v_h_fn <> 5 then
    raise exception 'ROLLBACK ABORTED: holdout v1 is %/% with % false positives and % false negatives; the result of record is 49/54, 0, 5',
      v_h_pass, v_h_exec, v_h_fp, v_h_fn; end if;

  v_report := jsonb_build_object(
    'ok', true, 'mode', p_mode, 'actor', p_actor,
    'removable_objects', jsonb_build_object('before', v_before, 'after', v_after,
                                            'inventory', to_jsonb(c_funcs || array['p2c1_b7_case'])),
    'b7_marker_rows', v_markers_before || ' -> ' || v_markers_after,
    'restored', jsonb_build_object(
      'fn_scope_detect','Stage B.6 body verified: no party detector',
      'fn_mep_full_scope','Stage B.6 body verified: reads scope_full only',
      'mep_trade_pattern','`package` returned to scope_full; B.7 HVAC phrases, hints and containers deleted',
      'scope_marker','removal phrases returned to fixed by_others; party, attribution and supply_anchor rows deleted'),
    'intentional_survivors', jsonb_build_array(
      jsonb_build_object('object','inquiry_scope_disposition.classification_basis and the four party columns',
        'class','B','reason','permanent evidence on an append-only table: why each historical classification was made. Dropping them would delete audit history to undo a code change.',
        'rows_carrying_evidence', (select count(*) from public.inquiry_scope_disposition where classification_basis is not null)),
      jsonb_build_object('object','scope_marker.party_class, scope_marker.resolution','class','additive',
        'reason','nullable and defaulted; inert once the B.7 marker rows are gone and the B.6 check constraints are restored'),
      jsonb_build_object('object','fn_p2c1_rollback_stage_b7(text,text)','class','instrument',
        'reason','the tool performing this rollback; returns stage_b7_not_present if re-run')),
    'tests', jsonb_build_object('stage_a', v_a, 'stage_b', v_b, 'lang_parity', v_lang,
                                'scope_negatives', v_scope, 'disposition', v_disp,
                                'holdout_v1', v_h_pass || '/' || v_h_exec,
                                'holdout_false_positives', v_h_fp, 'holdout_false_negatives', v_h_fn),
    'verdict','stage b7 removed; stage b6 interpretation restored; holdout v1 back at its result of record');

  insert into public.inquiry_state_audit (group_id, event, detail, actor)
  values (null, 'p2c1_stage_b7_rollback_' || p_mode, v_report, p_actor);

  if p_mode = 'rehearse' then
    raise exception 'REHEARSAL COMPLETE (nothing committed): %', v_report::text; end if;
  return v_report;
end $function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_run_lang_case(p_case_key text, p_lang text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.p2c1_lang_case%rowtype; g bigint; r jsonb; v_txt text; v_doc text;
        v_conf text[]; v_prop text[]; v_active text[]; v_clar boolean;
begin
  select * into c from public.p2c1_lang_case where case_key = p_case_key;
  if not found then return jsonb_build_object('ok', false, 'error','unknown_case'); end if;

  v_txt := case when p_lang = 'ar' then c.text_ar else c.text_en end;
  v_doc := case when p_lang = 'ar' then c.doc_ar else c.doc_en end;

  insert into public.inquiry_workstream_group (inquiry_id) values (gen_random_uuid()) returning id into g;
  r := public.fn_trade_identify(g, v_txt, null,
        case when v_doc is null then null else
          jsonb_build_array(jsonb_build_object('document_id','DOC-'||p_case_key,
                                               'approved', true, 'text', v_doc)) end,
        'lang_suite');

  select coalesce(array_agg(trade_key order by trade_key),'{}') into v_conf
    from public.inquiry_trade_candidate where group_id = g and status = 'confirmed';
  select coalesce(array_agg(trade_key order by trade_key),'{}') into v_prop
    from public.inquiry_trade_candidate where group_id = g and status = 'proposed';
  select coalesce(array_agg(trade_key order by trade_key),'{}') into v_active
    from public.inquiry_workstream where group_id = g and active;
  select exists (select 1 from public.inquiry_trade_clarification
                  where group_id = g and answered_at is null) into v_clar;

  perform set_config('quotesdone.p2c1_teardown','approved',true);
  delete from public.inquiry_state_audit where group_id = g;
  delete from public.inquiry_workstream_group where id = g;
  perform set_config('quotesdone.p2c1_teardown','',true);

  return jsonb_build_object('ok', true, 'lang', p_lang, 'text', v_txt,
                            'confirmed', to_jsonb(v_conf), 'proposed', to_jsonb(v_prop),
                            'activated', to_jsonb(v_active), 'clarify', v_clar);
end $function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_scope_rule_tests()
 RETURNS TABLE(case_key text, polarity text, expected text, actual text, passed boolean, note text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.p2c1_scope_case%rowtype; g bigint; got text[];
begin
  for c in select * from public.p2c1_scope_case order by polarity desc, case_key loop
    insert into public.inquiry_workstream_group (inquiry_id) values (gen_random_uuid()) returning id into g;
    perform public.fn_trade_identify(g, c.text_en, null, null, 'scope_tests');
    select coalesce(array_agg(trade_key order by trade_key),'{}') into got
      from public.inquiry_workstream where group_id = g and active;

    case_key := c.case_key; polarity := c.polarity; note := c.note;
    expected := array_to_string(c.expect_trades, ',');
    actual   := array_to_string(got, ',');
    passed   := (got = c.expect_trades);
    return next;

    perform set_config('quotesdone.p2c1_teardown','approved',true);
    delete from public.inquiry_state_audit where group_id = g;
    delete from public.inquiry_workstream_group where id = g;
    perform set_config('quotesdone.p2c1_teardown','',true);
  end loop;
end $function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_stage_a_selftest()
 RETURNS TABLE(test_no integer, name text, passed boolean, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  g bigint; wh bigint; we bigint; wp bigint; wf bigint; wv bigint;
  r jsonb; n integer; n2 integer; b boolean; b2 boolean; t text;
  f_hvac text; f_elec text; f_shared text := 'shared.project_emirate';
  live_id bigint; inq uuid := gen_random_uuid(); err text;
begin
  insert into public.inquiry_workstream_group (inquiry_id) values (inq) returning id into g;
  wh := (public.fn_inquiry_workstream_activate(g,'hvac','selftest')->>'workstream_id')::bigint;
  we := (public.fn_inquiry_workstream_activate(g,'electrical','selftest')->>'workstream_id')::bigint;
  wp := (public.fn_inquiry_workstream_activate(g,'plumbing','selftest')->>'workstream_id')::bigint;
  wf := (public.fn_inquiry_workstream_activate(g,'fire','selftest')->>'workstream_id')::bigint;
  wv := (public.fn_inquiry_workstream_activate(g,'elv','selftest')->>'workstream_id')::bigint;

  select r2.field_id into f_hvac from public.inquiry_workstream_requirement r2
   where r2.workstream_id = wh and r2.mandatory and r2.field_id like 'hvac.%' order by 1 limit 1;
  select r2.field_id into f_elec from public.inquiry_workstream_requirement r2
   where r2.workstream_id = we and r2.mandatory and r2.field_id like 'electrical.%' order by 1 limit 1;

  perform public.fn_inquiry_answer_set(g, f_shared, 'Dubai', 'customer_confirmed','customer','selftest');
  select count(*) into n from public.v_workstream_answer
   where group_id = g and field_id = f_shared and value = 'Dubai';
  select count(distinct answer_id) into n2 from public.v_workstream_answer
   where group_id = g and field_id = f_shared;
  perform public.fn_inquiry_answer_set(g, f_shared, 'Sharjah','customer_confirmed','customer','selftest');
  select count(*) into live_id from public.v_workstream_answer
   where group_id = g and field_id = f_shared and value = 'Sharjah';
  test_no := 1; name := 'one shared answer updates five workstream views';
  passed := (n = 5 and n2 = 1 and live_id = 5);
  detail := format('5 workstreams saw the first value from %s answer row(s); after one update %s of 5 see the new value, with no propagation step', n2, live_id);
  return next;

  r := public.fn_inquiry_answer_set(g, f_hvac, 'x','customer_confirmed','customer','selftest', null, array[we]);
  test_no := 2; name := 'a trade-specific answer cannot satisfy another trade';
  passed := (not (r->>'ok')::boolean and r->>'error' = 'trade_mismatch');
  detail := format('setting %s on the electrical workstream returned %s', f_hvac, coalesce(r->>'error','ACCEPTED - WRONG'));
  return next;

  perform public.fn_p2c1_fixture_satisfy(g, wh);
  perform public.fn_p2c1_fixture_satisfy(g, we);
  perform public.fn_p2c1_fixture_satisfy(g, wp);
  perform public.fn_p2c1_fixture_satisfy(g, wf);
  perform public.fn_p2c1_fixture_satisfy(g, wv);
  insert into public.inquiry_gate (group_id, workstream_id, gate_key, passed, asserted_by)
  select g, null, gr.gate_key, true, 'selftest'
    from public.inquiry_gate_required gr where gr.level = 'group' on conflict do nothing;

  select dispatch_eligible into b from public.v_workstream_dispatch where workstream_id = wh;
  perform set_config('quotesdone.p2c1_teardown','approved',true);
  delete from public.inquiry_answer a
   where a.group_id = g and a.field_id = f_hvac and a.superseded_by is null;
  perform set_config('quotesdone.p2c1_teardown','',true);
  select dispatch_eligible, cardinality(missing_mandatory) into b2, n
    from public.v_workstream_dispatch where workstream_id = wh;
  test_no := 5; name := 'a missing mandatory field blocks trade dispatch';
  passed := (b and not b2 and n = 1);
  detail := format('hvac was eligible=%s with everything answered; removing one mandatory field left %s missing and eligible=%s', b, n, b2);
  return next;

  select overall_dispatch_eligible, array_to_string(blocking_trades,',') into b, t
    from public.v_group_dispatch where group_id = g;
  test_no := 6; name := 'one blocked trade keeps overall dispatch false';
  passed := (not b and t = 'hvac');
  detail := format('four trades complete, hvac blocked -> overall_dispatch_eligible=%s, blocking_trades=[%s]', b, t);
  return next;

  perform public.fn_inquiry_answer_set(g, f_hvac, 'fixture-value','customer_confirmed','customer','selftest', null, array[wh]);
  select overall_dispatch_eligible into b from public.v_group_dispatch where group_id = g;
  test_no := 8; name := 'restoring the missing answer makes the whole group dispatch-eligible again';
  passed := b;
  detail := format('overall_dispatch_eligible=%s once hvac is complete again', b);
  return next;

  r := public.fn_inquiry_answer_set(g, f_elec, '12 units','document_extracted','document','extractor',
        null, array[we], jsonb_build_object('document_id','DRW-001','page_or_sheet','E-201'));
  select dispatch_eligible, cardinality(blocked_by) into b, n
    from public.v_workstream_dispatch where workstream_id = we;
  select overall_dispatch_eligible into b2 from public.v_group_dispatch where group_id = g;
  test_no := 3; name := 'document conflicts block dispatch';
  passed := (r->>'action' = 'conflict_opened' and not b and n = 1 and not b2);
  detail := format('drawing disagreed with the customer -> action=%s, electrical blocked_by=%s, electrical eligible=%s, overall=%s',
                   r->>'action', n, b, b2);
  return next;

  select value into t from public.inquiry_answer
   where group_id = g and field_id = f_elec and superseded_by is null;
  test_no := 10; name := 'a lower-precedence value never overwrites the canonical answer';
  passed := (t = 'fixture-value');
  detail := format('canonical value is still %L after a document proposed %L', t, '12 units');
  return next;

  select count(*) into n from public.inquiry_answer_conflict_value cv
    join public.inquiry_answer_conflict c on c.id = cv.conflict_id
   where c.group_id = g and c.field_id = f_elec;
  r := public.fn_inquiry_answer_confirm(g, f_elec, '12 units', 'customer:zaino',
        'Customer checked the drawing and agrees with 12 units.', array[we]);
  select count(*) into n2 from public.inquiry_answer_conflict_value cv
    join public.inquiry_answer_conflict c on c.id = cv.conflict_id
   where c.group_id = g and c.field_id = f_elec;
  select dispatch_eligible into b from public.v_workstream_dispatch where workstream_id = we;
  select value into t from public.inquiry_answer
   where group_id = g and field_id = f_elec and superseded_by is null;
  test_no := 4; name := 'customer confirmation resolves conflict without deleting evidence';
  passed := ((r->>'ok')::boolean and n2 >= n and n2 >= 3 and b and t = '12 units'
             and exists (select 1 from public.inquiry_answer_conflict c
                          where c.group_id = g and c.field_id = f_elec
                            and c.resolved_at is not null and c.resolution_reason is not null));
  detail := format('evidence values before=%s after=%s (never fewer); canonical now %L; electrical eligible=%s; resolution carries a person and a reason', n, n2, t, b);
  return next;

  select count(*) into n from public.inquiry_answer
   where group_id = g and field_id = f_shared and superseded_by is null;
  select count(*) into n2 from public.inquiry_answer_scope s
    join public.inquiry_answer a on a.id = s.answer_id
   where a.group_id = g and a.field_id = f_shared;
  test_no := 7; name := 'a shared answer is stored once and never copied per workstream';
  passed := (n = 1 and n2 = 0);
  detail := format('%s live row for the shared field, %s per-workstream scope rows (a copy design would show 5)', n, n2);
  return next;

  select value into t from public.inquiry_answer
   where group_id = g and field_id = f_shared and superseded_by is null;
  select count(*) into n from public.inquiry_answer_conflict where group_id = g and resolved_at is null;
  r := public.fn_inquiry_answer_set(g, f_shared, '  ' || upper(t) || '  ','document_extracted','document',
        'extractor', null, null, jsonb_build_object('document_id','DRW-002'));
  select count(*) into n2 from public.inquiry_answer_conflict where group_id = g and resolved_at is null;
  test_no := 9; name := 'an agreeing lower-precedence source corroborates rather than conflicts';
  passed := (r->>'action' = 'corroborated' and n2 = n
             and exists (select 1 from public.inquiry_answer_corroboration co
                          join public.inquiry_answer a on a.id = co.answer_id
                         where a.group_id = g and a.field_id = f_shared));
  detail := format('%L vs %L normalised equal -> action=%s, open conflicts %s -> %s',
                   '  ' || upper(t) || '  ', t, r->>'action', n, n2);
  return next;

  perform set_config('quotesdone.p2c1_teardown','approved',true);
  delete from public.inquiry_answer a where a.group_id = g and a.field_id = f_hvac;
  perform set_config('quotesdone.p2c1_teardown','',true);
  perform public.fn_inquiry_answer_set(g, f_hvac, 'guessed','model_inference','model','router', null, array[wh]);
  select dispatch_eligible into b from public.v_workstream_dispatch where workstream_id = wh;
  r := public.fn_inquiry_answer_confirm(g, f_hvac, 'guessed','customer:zaino','Customer confirmed the inference.', array[wh]);
  select dispatch_eligible into b2 from public.v_workstream_dispatch where workstream_id = wh;
  test_no := 11; name := 'model inference proposes but cannot satisfy a mandatory field alone';
  passed := (not b and b2);
  detail := format('with only a model inference eligible=%s; after customer confirmation eligible=%s', b, b2);
  return next;

  -- make elv incomplete FIRST, then bracket the deactivation itself
  perform set_config('quotesdone.p2c1_teardown','approved',true);
  delete from public.inquiry_answer a
   where a.group_id = g and a.superseded_by is null
     and a.field_id in (select r2.field_id from public.inquiry_workstream_requirement r2
                         where r2.workstream_id = wv and r2.mandatory and r2.field_id like 'elv.%' limit 1);
  perform set_config('quotesdone.p2c1_teardown','',true);
  select count(*) into n from public.inquiry_answer a
   where a.group_id = g and exists (select 1 from public.inquiry_answer_scope s
                                     where s.answer_id = a.id and s.workstream_id = wv);
  select overall_dispatch_eligible into b from public.v_group_dispatch where group_id = g;
  perform public.fn_inquiry_workstream_deactivate(g,'elv','selftest');
  select overall_dispatch_eligible into b2 from public.v_group_dispatch where group_id = g;
  select count(*) into n2 from public.inquiry_answer a
   where a.group_id = g and exists (select 1 from public.inquiry_answer_scope s
                                     where s.answer_id = a.id and s.workstream_id = wv);
  test_no := 12; name := 'deactivating a trade leaves the roll-up, not the data';
  passed := (not b and b2 and n2 = n and n2 > 0);
  detail := format('incomplete elv held the group at %s; deactivating it gave %s; elv-scoped answers %s -> %s across the deactivation', b, b2, n, n2);
  return next;

  select count(*) into n from public.inquiry_workstream_requirement where workstream_id = wv;
  r := public.fn_inquiry_workstream_activate(g,'elv','selftest');
  select count(*) into n2 from public.inquiry_workstream_requirement where workstream_id = wv;
  select count(*) into live_id from public.inquiry_workstream where group_id = g and trade_key = 'elv';
  test_no := 13; name := 'reactivation flips the flag and duplicates nothing';
  passed := ((r->>'reactivated')::boolean and n2 = n and live_id = 1);
  detail := format('reactivated=%s, requirements %s -> %s, workstream rows for elv = %s', r->>'reactivated', n, n2, live_id);
  return next;

  err := '';
  begin
    update public.inquiry_state_audit set event = 'tampered' where group_id = g;
    err := err || 'audit-update-ALLOWED ';
  exception when others then err := err || 'audit-update-refused '; end;
  begin
    delete from public.inquiry_answer_conflict_value cv using public.inquiry_answer_conflict c
     where c.id = cv.conflict_id and c.group_id = g;
    err := err || 'evidence-delete-ALLOWED';
  exception when others then err := err || 'evidence-delete-refused'; end;
  select count(*) into n from public.inquiry_state_audit where group_id = g;
  test_no := 14; name := 'audit and evidence are append-only';
  passed := (err = 'audit-update-refused evidence-delete-refused' and n > 0);
  detail := format('%s; %s audit rows recorded for this group', err, n);
  return next;

  perform set_config('quotesdone.p2c1_teardown','approved',true);
  delete from public.inquiry_state_audit where group_id = g;
  delete from public.inquiry_workstream_group where id = g;
  perform set_config('quotesdone.p2c1_teardown','',true);
end $function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_stage_b_regression()
 RETURNS TABLE(test_no integer, name text, passed boolean, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare g bigint; t text; v_state text; v_passed boolean; ws bigint;
begin
  insert into public.inquiry_workstream_group (inquiry_id) values (gen_random_uuid()) returning id into g;

  perform public.fn_trade_identify(g,
        'Full MEP package for a warehouse; fire fighting also required.', null, null, 'regression');
  select string_agg(w.trade_key, ',' order by w.trade_key) into t
    from public.inquiry_workstream w where w.group_id = g and w.active;
  test_no := 15;
  name := 'an explicitly named trade adds to "full MEP", it does not replace it';
  passed := (t = 'electrical,fire,hvac,plumbing');
  detail := format('active workstreams = [%s]; the umbrella scope rule and the named trade both applied, and ELV is still absent', t);
  return next;

  select w.id into ws from public.inquiry_workstream w where w.group_id = g and w.trade_key = 'hvac';
  insert into public.inquiry_gate (group_id, workstream_id, gate_key, passed, asserted_by)
  values (g, ws, 'validations', true, 'regression');
  select ig.state::text, ig.passed into v_state, v_passed
    from public.inquiry_gate ig where ig.workstream_id = ws and ig.gate_key = 'validations';
  test_no := 16;
  name := 'a gate asserted as passed lands as passed, not as not_evaluated';
  passed := (v_state = 'passed' and v_passed);
  detail := format('inserted passed=true -> state=%s, passed=%s', v_state, v_passed);
  return next;

  perform set_config('quotesdone.p2c1_teardown','approved',true);
  delete from public.inquiry_state_audit where group_id = g;
  delete from public.inquiry_workstream_group where id = g;
  perform set_config('quotesdone.p2c1_teardown','',true);
end $function$


CREATE OR REPLACE FUNCTION public.fn_p2c1_stage_b_selftest()
 RETURNS TABLE(test_no integer, name text, passed boolean, detail text, ms numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  g1 bigint; g2 bigint; g3 bigint; g4 bigint; g5 bigint; g6 bigint;
  r jsonb; rep jsonb; n integer; n2 integer; b boolean; t text; t2 text;
  we bigint; wf bigint; wh bigint;
  f_em text; t0 timestamptz; groups bigint[];
  intake_before bigint; intake_after bigint;
begin
  select count(*) into intake_before from public.inquiry_intake;

  -- ===== 1: "Full MEP package" activates HVAC, Electrical and Plumbing =====
  insert into public.inquiry_workstream_group (inquiry_id) values (gen_random_uuid()) returning id into g1;
  t0 := clock_timestamp();
  r := public.fn_trade_identify(g1, 'Full MEP package required for a new building.', null, null, 'selftest');
  ms := round(extract(milliseconds from clock_timestamp()-t0)::numeric,1);
  select string_agg(trade_key,',' order by trade_key) into t
    from public.inquiry_workstream where group_id = g1 and active;
  test_no := 1; name := '"Full MEP package" activates HVAC, Electrical and Plumbing';
  passed := (t = 'electrical,hvac,plumbing'
             and not exists (select 1 from public.inquiry_trade_candidate
                              where group_id = g1 and trade_key in ('fire','elv')));
  detail := format('active workstreams = [%s]; fire and ELV were not created, because "full MEP" does not order them', t);
  return next;

  -- ===== 2: "HVAC only" activates only HVAC =====
  insert into public.inquiry_workstream_group (inquiry_id) values (gen_random_uuid()) returning id into g2;
  t0 := clock_timestamp();
  r := public.fn_trade_identify(g2, 'HVAC only for the office floor.', null, null, 'selftest');
  ms := round(extract(milliseconds from clock_timestamp()-t0)::numeric,1);
  select string_agg(trade_key,',' order by trade_key), count(*) into t, n
    from public.inquiry_workstream where group_id = g2 and active;
  test_no := 2; name := '"HVAC only" activates only HVAC';
  passed := (t = 'hvac' and n = 1);
  detail := format('active workstreams = [%s], count = %s', t, n);
  return next;

  -- ===== 3: electrical plus plumbing activates exactly two =====
  insert into public.inquiry_workstream_group (inquiry_id) values (gen_random_uuid()) returning id into g3;
  t0 := clock_timestamp();
  r := public.fn_trade_identify(g3, 'We need electrical and plumbing works.', null, null, 'selftest');
  ms := round(extract(milliseconds from clock_timestamp()-t0)::numeric,1);
  select string_agg(trade_key,',' order by trade_key), count(*) into t, n
    from public.inquiry_workstream where group_id = g3 and active;
  test_no := 3; name := 'electrical plus plumbing activates exactly two workstreams';
  passed := (t = 'electrical,plumbing' and n = 2);
  detail := format('active workstreams = [%s], count = %s', t, n);
  return next;

  -- ===== 4: vague "MEP works" requests clarification =====
  insert into public.inquiry_workstream_group (inquiry_id) values (gen_random_uuid()) returning id into g4;
  t0 := clock_timestamp();
  r := public.fn_trade_identify(g4, 'MEP works.', null, null, 'selftest');
  ms := round(extract(milliseconds from clock_timestamp()-t0)::numeric,1);
  select count(*) into n from public.inquiry_trade_clarification where group_id = g4 and answered_at is null;
  select count(*) into n2 from public.inquiry_workstream where group_id = g4 and active;
  select reason into t from public.inquiry_trade_clarification where group_id = g4 and answered_at is null;
  test_no := 4; name := 'a vague "MEP works" request asks exactly one clarification';
  passed := ((r->>'clarification_required')::boolean and n = 1 and n2 = 0
             and r->>'confirmed' = '[]');
  detail := format('open clarifications = %s, active workstreams = %s, reason: %s', n, n2, t);
  return next;

  -- ===== 5: fire mentioned explicitly adds Fire =====
  t0 := clock_timestamp();
  r := public.fn_trade_identify(g1, 'Fire fighting system also required.', null, null, 'selftest');
  ms := round(extract(milliseconds from clock_timestamp()-t0)::numeric,1);
  select string_agg(trade_key,',' order by trade_key) into t
    from public.inquiry_workstream where group_id = g1 and active;
  select status into t2 from public.inquiry_trade_candidate where group_id = g1 and trade_key = 'fire';
  test_no := 5; name := 'fire mentioned explicitly adds Fire';
  passed := (t2 = 'confirmed' and t like '%fire%'
             and not exists (select 1 from public.inquiry_trade_candidate where group_id=g1 and trade_key='elv'));
  detail := format('fire candidate status = %s; active workstreams now [%s]; ELV still absent', t2, t);
  return next;

  -- ===== 6: ELV detected only in a drawing stays proposed until confirmed =====
  insert into public.inquiry_workstream_group (inquiry_id) values (gen_random_uuid()) returning id into g5;
  perform public.fn_trade_identify(g5, 'Electrical works for a retail unit.', null, null, 'selftest');
  t0 := clock_timestamp();
  r := public.fn_trade_identify(g5, null, null,
        jsonb_build_array(jsonb_build_object('document_id','DRW-ELV-01','approved',true,
          'text','CCTV and access control layout with structured cabling risers.')), 'extractor');
  ms := round(extract(milliseconds from clock_timestamp()-t0)::numeric,1);
  select status, requires_confirmation, workstream_id into t, b, n
    from public.inquiry_trade_candidate where group_id = g5 and trade_key = 'elv';
  select count(*) into n2 from public.inquiry_workstream where group_id = g5 and trade_key = 'elv';
  test_no := 6; name := 'a trade detected only in a drawing stays proposed until confirmed';
  passed := (t = 'proposed' and b and n is null and n2 = 0);
  detail := format('elv status = %s, requires_confirmation = %s, workstream rows = %s. A document proposes; it never activates.', t, b, n2);
  return next;

  -- ===== 7: a rejected document-detected trade does not affect completeness =====
  select cardinality(shared_missing_mandatory), active_workstreams into n, n2
    from public.v_group_dispatch where group_id = g5;
  r := public.fn_trade_reject(g5, 'elv', 'ops:zaino', 'Customer confirmed the CCTV scope is by others.');
  select cardinality(shared_missing_mandatory), active_workstreams into test_no, ms
    from public.v_group_dispatch where group_id = g5;
  select count(*) into n from public.inquiry_workstream_requirement req
    join public.inquiry_workstream w on w.id = req.workstream_id
   where w.group_id = g5 and req.field_id like 'elv.%';
  test_no := 7; name := 'a rejected document-detected trade does not affect completeness';
  passed := ((r->>'ok')::boolean and n = 0
             and (select active_workstreams from public.v_group_dispatch where group_id = g5) = n2
             and exists (select 1 from public.inquiry_trade_candidate
                          where group_id=g5 and trade_key='elv' and status='rejected'
                            and rejection_reason is not null));
  detail := format('elv requirements after rejection = %s; active workstreams unchanged at %s; rejection carries a person and a reason', n, n2);
  ms := null;
  return next;

  -- ===== 8: adding a trade recalculates requirements immediately =====
  select count(*) into n from public.inquiry_workstream_requirement req
    join public.inquiry_workstream w on w.id = req.workstream_id where w.group_id = g5;
  t0 := clock_timestamp();
  r := public.fn_trade_confirm(g5, 'elv', 'ops:zaino', 'Customer reinstated the CCTV package.');
  ms := round(extract(milliseconds from clock_timestamp()-t0)::numeric,1);
  select count(*) into n2 from public.inquiry_workstream_requirement req
    join public.inquiry_workstream w on w.id = req.workstream_id where w.group_id = g5;
  test_no := 8; name := 'adding a trade recalculates requirements immediately';
  passed := ((r->>'ok')::boolean and n2 > n and (r->>'requirements')::integer > 0
             and exists (select 1 from public.v_workstream_dispatch
                          where group_id = g5 and trade_key = 'elv' and active));
  detail := format('group requirements %s -> %s in the same call; elv materialised %s of its own', n, n2, r->>'requirements');
  return next;

  -- ===== 9: removing a trade drops the dispatch dependency, keeps the history =====
  select id into we from public.inquiry_workstream where group_id = g5 and trade_key = 'elv';
  perform public.fn_p2c1_fixture_satisfy(g5, we);
  select count(*) into n from public.inquiry_answer a
   where a.group_id = g5 and exists (select 1 from public.inquiry_answer_scope s
                                      where s.answer_id = a.id and s.workstream_id = we);
  r := public.fn_trade_remove(g5, 'elv', 'ops:zaino', 'Descoped by the customer.');
  select count(*) into n2 from public.inquiry_answer a
   where a.group_id = g5 and exists (select 1 from public.inquiry_answer_scope s
                                      where s.answer_id = a.id and s.workstream_id = we);
  select count(*) into test_no from public.inquiry_trade_candidate_evidence e
    join public.inquiry_trade_candidate c on c.id = e.candidate_id
   where c.group_id = g5 and c.trade_key = 'elv';
  test_no := 9; name := 'removing a trade drops the dispatch dependency without deleting history';
  passed := (n2 = n and n > 0
             and not exists (select 1 from public.v_workstream_dispatch
                              where group_id=g5 and trade_key='elv' and active)
             and (select status from public.inquiry_trade_candidate where group_id=g5 and trade_key='elv') = 'inactive'
             and exists (select 1 from public.inquiry_trade_candidate_evidence e
                          join public.inquiry_trade_candidate c on c.id=e.candidate_id
                         where c.group_id=g5 and c.trade_key='elv'));
  detail := format('elv answers %s -> %s across removal; candidate now inactive; evidence rows still present', n, n2);
  ms := null;
  return next;

  -- ===== 10: emergency lighting is stored once under Electrical, referenced by Life Safety =====
  select id into we from public.inquiry_workstream where group_id = g1 and trade_key = 'electrical';
  select id into wf from public.inquiry_workstream where group_id = g1 and trade_key = 'fire';
  select field_id into f_em from public.inquiry_workstream_requirement
   where workstream_id = we and field_id like 'electrical.%emergency%' order by field_id limit 1;
  perform public.fn_inquiry_answer_set(g1, f_em, '3 hours maintained', 'customer_confirmed',
            'customer', 'selftest', null, array[we]);
  select count(*) into n from public.inquiry_workstream_requirement
   where workstream_id = wf and field_id like 'electrical.%';
  select via, satisfies_mandatory into t, b
    from public.v_workstream_answer where workstream_id = wf and field_id = f_em;
  select count(*) into n2 from public.inquiry_answer
   where group_id = g1 and field_id = f_em and superseded_by is null;
  test_no := 10; name := 'emergency lighting is stored once under Electrical and referenced by Life Safety';
  passed := (n = 0 and t = 'referenced' and b is false and n2 = 1
             and not exists (select 1 from public.inquiry_workstream_requirement req
                              where req.workstream_id = wf
                                and req.field_id in (select field_id from public.field_definition_reference
                                                      where referencing_trade_key='fire')));
  detail := format('%s = 1 stored row; fire owns %s electrical requirements; fire sees it via=%s, satisfies_mandatory=%s', f_em, n, t, b);
  ms := null;
  return next;

  -- ===== 11: shared brand policy is inherited unless a trade override exists =====
  perform public.fn_inquiry_answer_set(g1, 'shared.brand_acceptance_policy',
            'named_brand_or_approved_equal', 'customer_confirmed', 'customer', 'selftest');
  select count(*) into n from public.v_workstream_brand_policy
   where group_id = g1 and active and effective_policy = 'named_brand_or_approved_equal'
     and effective_source = 'shared_default';
  perform public.fn_inquiry_answer_set(g1, 'electrical.brand_acceptance_policy_override',
            'named_brand_only', 'customer_confirmed', 'customer', 'selftest', null, array[we]);
  select effective_policy, effective_source into t, t2 from public.v_workstream_brand_policy
   where workstream_id = we;
  select count(*) into n2 from public.v_workstream_brand_policy
   where group_id = g1 and active and workstream_id <> we
     and effective_policy = 'named_brand_or_approved_equal' and effective_source = 'shared_default';
  test_no := 11; name := 'shared brand policy is inherited unless a trade override exists';
  passed := (n >= 3 and t = 'named_brand_only' and t2 = 'trade_override' and n2 = n - 1
             and (select count(*) from public.field_question_variant
                   where field_id='shared.brand_acceptance_policy') >= 2);
  detail := format('%s workstreams inherited the shared default; electrical overrode to %s (%s); the other %s still inherit; original corpus wordings preserved as variants', n, t, t2, n2);
  ms := null;
  return next;

  -- ===== 12: unknown trade evidence cannot make an inquiry dispatchable =====
  insert into public.inquiry_workstream_group (inquiry_id) values (gen_random_uuid()) returning id into g6;
  perform public.fn_trade_identify(g6, null, null,
        jsonb_build_array(jsonb_build_object('document_id','DRW-X','approved',true,
          'text','Chilled water pipework and CCTV cameras.')), 'extractor');
  rep := public.fn_group_dispatch_report(g6);
  select count(*) into n from public.inquiry_trade_candidate where group_id = g6 and status = 'proposed';
  test_no := 12; name := 'unconfirmed trade evidence cannot make an inquiry dispatchable';
  passed := (not (rep->>'overall_dispatch_eligible')::boolean
             and (rep->>'active_workstreams')::integer = 0
             and rep::text like '%no_active_workstream%'
             and n > 0);
  detail := format('%s proposed candidate(s), 0 active workstreams, overall_dispatch_eligible=%s, blockers=%s',
                   n, rep->>'overall_dispatch_eligible', rep->>'blocker_count');
  ms := null;
  return next;

  -- ===== 13: existing single-route inquiries remain unaffected =====
  select count(*) into n from public.v_inquiry_workstream_identity where shape = 'multi_workstream';
  select count(*) into n2 from public.v_inquiry_workstream_identity
   where shape = 'implicit_single_workstream' and effective_workstreams = 1;
  test_no := 13; name := 'existing single-route inquiries remain unaffected';
  passed := (n = 0 and n2 = (select count(*) from public.inquiry_intake));
  detail := format('%s of %s existing inquiries report an implicit single workstream; %s were given a group by Stage B',
                   n2, (select count(*) from public.inquiry_intake), n);
  ms := null;
  return next;

  -- ===== 14: no route activated, nothing customer-visible changed =====
  select count(*) into n from public.kb_operational_route
   where coalesce(regulatory_coverage_status,'requires_review') <> 'requires_review';
  select count(*) into intake_after from public.inquiry_intake;
  select count(*) into n2 from public.v_scenario_expectation_drift;
  test_no := 14; name := 'no route is activated and no customer-visible behaviour changes';
  passed := (n = 0 and intake_after = intake_before and n2 = 0);
  detail := format('routes off requires_review = %s (of 86); inquiry_intake rows %s -> %s; unledgered expectation drift = %s',
                   n, intake_before, intake_after, n2);
  ms := null;
  return next;

  -- teardown
  groups := array[g1,g2,g3,g4,g5,g6];
  perform set_config('quotesdone.p2c1_teardown','approved',true);
  delete from public.inquiry_state_audit where group_id = any(groups);
  delete from public.inquiry_workstream_group where id = any(groups);
  perform set_config('quotesdone.p2c1_teardown','',true);
end $function$


CREATE OR REPLACE FUNCTION public.fn_page_high_agent_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_founder text;
BEGIN
  IF lower(coalesce(NEW.risk,'')) IN ('high','critical')
     -- K21. Was: NEW.agent IN ('finance_ai','security_ai','operations_ai'). That set could never
     -- match a security action. a00_agent_action_resolve_addressee runs BEFORE this trigger and
     -- resolves the addressee through org_agents, so a row written as 'security_ai' arrives here
     -- as 'security'. Measured: inserting agent='security_ai' reads back as 'security', and
     -- notifications has 0 rows of type 'agent_escalation' in its entire history — the founder has
     -- never been paged by this trigger. A prefix match survives the resolver in both directions
     -- and does not need a keep-list that has to be remembered every time an agent is renamed.
     AND NEW.agent ~ '^(finance|security|operations)'
     AND lower(coalesce(NEW.status,'pending')) = 'pending' THEN
  -- K20 cutover. A high or critical pending action from finance, security or operations is the declared start of W29. Placed INSIDE the risk branch, so an ordinary agent action does not open an incident.
  perform public.fn_kernel_source_emit('dbtrigger:public.agent_actions:trg_page_high_agent_action', jsonb_build_object(
    'source_ref',  NEW.id::text,
    'raw_payload', jsonb_build_object('incident_ref', 'agent_action:' || NEW.id::text, 'agent', NEW.agent, 'kind', NEW.kind, 'risk', NEW.risk, 'title', NEW.title)));
    v_founder := coalesce(
      (SELECT value FROM app_secrets WHERE key='founder_email'),
      nullif(split_part((SELECT value FROM app_secrets WHERE key='admin_emails'), ',', 1), ''),
      'management@quotesdone.com');
    IF NOT EXISTS (
      SELECT 1 FROM notifications
      WHERE type='agent_escalation' AND body LIKE '%action #'||NEW.id||'%'
        AND created_at > now() - interval '24 hours'
    ) THEN
      INSERT INTO notifications(type, to_email, to_role, channel, status, subject, body)
      VALUES('agent_escalation', v_founder, 'admin', 'email', 'queued',
        '['||upper(NEW.risk)||'] '||coalesce(NEW.title, NEW.kind, 'Agent escalation'),
        coalesce(NEW.recommendation, NEW.title, '')||E'\n\nAgent: '||coalesce(NEW.agent,'?')||' · action #'||NEW.id||' · open the OS to decide.');
    END IF;
  END IF;
  RETURN NEW;
END
$function$


CREATE OR REPLACE FUNCTION public.fn_pdpl_erase_plan(p_email text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'subject', p_email,
    'customers',           (select count(*) from public.customers where email=p_email),
    'inquiries',           (select count(*) from public.inquiries where customer_id in (select id from public.customers where email=p_email)),
    'supplier_leads',      (select count(*) from public.leads where email=p_email),
    'notifications',       (select count(*) from public.notifications where to_email=p_email),
    'outreach',            (select count(*) from public.outreach where email=p_email),
    'email_verifications', (select count(*) from public.email_verifications where email=p_email),
    'phone_verifications', (select count(*) from public.phone_verifications where email=p_email),
    'ai_usage',            (select count(*) from public.ai_usage where email=p_email),
    'note','Redaction anonymises personal fields (name/phone/email/DOB) and keeps financial/audit records as legally required. email_suppressions is deliberately retained as a do-not-contact record.'
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_pdpl_export(p_email text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'subject', p_email,
    'generated_at', now(),
    'customers',           (select coalesce(jsonb_agg(to_jsonb(c)),'[]'::jsonb) from public.customers c where c.email=p_email),
    'inquiries',           (select coalesce(jsonb_agg(to_jsonb(i)),'[]'::jsonb) from public.inquiries i where i.customer_id in (select id from public.customers where email=p_email)),
    'preferences',         (select coalesce(jsonb_agg(to_jsonb(cp)),'[]'::jsonb) from public.customer_preference cp where cp.customer_id in (select id from public.customers where email=p_email)),
    'supplier_leads',      (select coalesce(jsonb_agg(to_jsonb(l)),'[]'::jsonb) from public.leads l where l.email=p_email),
    'notifications',       (select coalesce(jsonb_agg(to_jsonb(n)),'[]'::jsonb) from public.notifications n where n.to_email=p_email),
    'outreach',            (select coalesce(jsonb_agg(to_jsonb(o)),'[]'::jsonb) from public.outreach o where o.email=p_email),
    'email_verifications', (select coalesce(jsonb_agg(to_jsonb(e)),'[]'::jsonb) from public.email_verifications e where e.email=p_email),
    'phone_verifications', (select coalesce(jsonb_agg(to_jsonb(p)),'[]'::jsonb) from public.phone_verifications p where p.email=p_email),
    'email_suppressions',  (select coalesce(jsonb_agg(to_jsonb(s)),'[]'::jsonb) from public.email_suppressions s where s.email=p_email),
    'ai_usage',            (select coalesce(jsonb_agg(to_jsonb(a)),'[]'::jsonb) from public.ai_usage a where a.email=p_email)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_pdpl_redact(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_email text; v_status text;
  v_cust_ids uuid[]; v_phones text[]; v_inq_ids uuid[]; v_quote_ids uuid[];
  c_cust int:=0; c_lead int:=0; c_notif int:=0; c_out int:=0; c_ev int:=0; c_pv int:=0; c_ai int:=0;
  c_msg int:=0; c_inb int:=0; c_wa int:=0; c_inq int:=0; c_rfq int:=0; c_doc int:=0; c_files int:=0;
begin
  select email, status into v_email, v_status from public.pdpl_requests where id=p_request_id;
  if not found then raise exception 'pdpl request % not found', p_request_id; end if;
  if coalesce(v_status,'') <> 'approved' then
    raise exception 'pdpl request % must be status=approved before redaction (current: %)', p_request_id, coalesce(v_status,'null');
  end if;
  if v_email is null then raise exception 'pdpl request % has no email', p_request_id; end if;

  -- resolve subject linkage BEFORE mutating identity fields
  select coalesce(array_agg(id),'{}'), coalesce(array_agg(phone) filter (where phone is not null),'{}')
    into v_cust_ids, v_phones from public.customers where email=v_email;
  select coalesce(array_agg(id),'{}') into v_inq_ids from public.inquiries where customer_id = any(v_cust_ids);

  -- customer_preference is DELETED, not redacted: a preference profile has nothing to retain, and
  -- an emptied row would still carry consented_at and so still assert a consent that no longer
  -- exists. Withdrawal of consent is this same delete.
  delete from public.customer_preference where customer_id = any(v_cust_ids);
  select coalesce(array_agg(id),'{}') into v_quote_ids from public.quotes where inquiry_id = any(v_inq_ids);

  -- queue Dropbox/storage copies for external erasure BEFORE nulling any file paths
  insert into public.pdpl_erase_files(request_id,subject_email,bucket,storage_path,dropbox_path,origin)
  select p_request_id, v_email, db.bucket, db.path, db.dropbox_path, 'doc_backups:'||coalesce(db.entity,'?')
    from public.doc_backups db
   where (db.entity='customer' and db.entity_id = any(v_cust_ids::text[]))
      or (db.entity='inquiry'  and db.entity_id = any(v_inq_ids::text[]))
      or (db.entity='quote'    and db.entity_id = any(v_quote_ids::text[]));
  insert into public.pdpl_erase_files(request_id,subject_email,bucket,storage_path,dropbox_path,origin)
  select p_request_id, v_email, d.bucket, d.path,
         (select db.dropbox_path from public.doc_backups db where db.bucket=d.bucket and db.path=d.path limit 1),
         'documents:'||coalesce(d.ref_table,'?')
    from public.documents d
   where (d.ref_table='inquiries' and d.ref_id = any(v_inq_ids::text[]))
      or (d.ref_table='quotes'    and d.ref_id = any(v_quote_ids::text[]))
      or (d.ref_table='customers' and d.ref_id = any(v_cust_ids::text[]));
  insert into public.pdpl_erase_files(request_id,subject_email,bucket,storage_path,dropbox_path,origin)
  select p_request_id, v_email, r.bucket, r.archive_path,
         (select db.dropbox_path from public.doc_backups db where db.bucket=r.bucket and db.path=r.archive_path limit 1),
         'rfq_archive'
    from public.rfq_archives r
   where r.customer_id = any(v_cust_ids::text[]);

  -- structured identity tables (existing behaviour, unchanged)
  update public.customers set full_name='[erased-PDPL]', phone=null, date_of_birth=null,
         email='erased_'||id||'@removed.invalid' where email=v_email;
  get diagnostics c_cust = row_count;
  update public.leads set phone=null, whatsapp=null, email=null, matching_blocked=true where email=v_email;
  get diagnostics c_lead = row_count;
  update public.notifications set to_email='[erased]', to_phone=null where to_email=v_email;
  get diagnostics c_notif = row_count;
  update public.outreach set email='[erased]' where email=v_email;
  get diagnostics c_out = row_count;
  update public.email_verifications set email='[erased]' where email=v_email;
  get diagnostics c_ev = row_count;
  update public.phone_verifications set email='[erased]' where email=v_email;
  get diagnostics c_pv = row_count;
  update public.ai_usage set email='[erased]' where email=v_email;
  get diagnostics c_ai = row_count;

  -- free-text conversation / archive surfaces (C2 closure)
  update public.messages set body='[erased-PDPL]', redacted_body='[erased-PDPL]'
    where customer_id = any(v_cust_ids);
  get diagnostics c_msg = row_count;
  update public.inbound_messages set from_email='[erased]', to_email='[erased]', subject='[erased]',
         body='[erased-PDPL]', ai_draft_reply=null, ai_summary=null, ai_notes=null, raw='{}'::jsonb
    where from_email=v_email or to_email=v_email;
  get diagnostics c_inb = row_count;
  if array_length(v_phones,1) is not null then
    update public.wa_messages set wa_from='[erased]', wa_to='[erased]', profile_name='[erased]',
           inbound='[erased-PDPL]', reply='[erased-PDPL]', meta='{}'::jsonb
      where wa_from = any(v_phones) or wa_to = any(v_phones);
    get diagnostics c_wa = row_count;
  end if;
  update public.inquiries set raw_input='[erased-PDPL]', summary='[erased-PDPL]', spec='{}'::jsonb,
         drawing_file_name=null, drawing_file_path=null
    where id = any(v_inq_ids);
  get diagnostics c_inq = row_count;
  update public.rfq_archives set ai_summary='{}'::jsonb where customer_id = any(v_cust_ids::text[]);
  get diagnostics c_rfq = row_count;
  update public.documents set extracted='{}'::jsonb, status='erased'
    where (ref_table='inquiries' and ref_id = any(v_inq_ids::text[]))
       or (ref_table='quotes'    and ref_id = any(v_quote_ids::text[]))
       or (ref_table='customers' and ref_id = any(v_cust_ids::text[]));
  get diagnostics c_doc = row_count;

  update public.pdpl_requests set status='completed', handled_at=now(),
         handled_by=coalesce(handled_by,'fn_pdpl_redact') where id=p_request_id;
  select count(*) into c_files from public.pdpl_erase_files where request_id=p_request_id;

  insert into public.security_events(kind,severity,source,subject,detail)
  values('pdpl_redaction','high','pdpl', v_email,
    jsonb_build_object('request_id',p_request_id,'customers',c_cust,'leads',c_lead,'notifications',c_notif,
      'outreach',c_out,'email_verifications',c_ev,'phone_verifications',c_pv,'ai_usage',c_ai,
      'messages',c_msg,'inbound_messages',c_inb,'wa_messages',c_wa,'inquiries',c_inq,'rfq_archives',c_rfq,
      'documents',c_doc,'files_queued_for_erasure',c_files));

  return jsonb_build_object('subject',v_email,
    'redacted', jsonb_build_object('customers',c_cust,'supplier_leads',c_lead,'notifications',c_notif,
      'outreach',c_out,'email_verifications',c_ev,'phone_verifications',c_pv,'ai_usage',c_ai,
      'messages',c_msg,'inbound_messages',c_inb,'wa_messages',c_wa,'inquiries',c_inq,
      'rfq_archives',c_rfq,'documents',c_doc),
    'files_queued_for_erasure', c_files,
    'files_note','Dropbox/storage copies queued in pdpl_erase_files; run dropbox_backup {op:pdpl_erase, request_id} to delete them.',
    'kept','email_suppressions retained as do-not-contact');
end $function$


CREATE OR REPLACE FUNCTION public.fn_period_report(p_type text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  d_this interval; d_prev_start interval; d_prev_end interval; label text;
  inq_t int; inq_p int; q_t int; q_p int; c_t int; c_p int; s_t int; s_p int; rev_t numeric; rev_p numeric;
  conv numeric; health jsonb; officer text; topcats text; owner text; body text; d jsonb; extra text;
  compet text; posn text; n_comp int; n_anon int;
begin
  if p_type='monthly' then d_this:='30 days'; d_prev_start:='60 days'; d_prev_end:='30 days'; label:='Monthly Business Report';
  else d_this:='90 days'; d_prev_start:='180 days'; d_prev_end:='90 days'; label:='Quarterly Strategy Report'; end if;

  select count(*) filter (where created_at>=now()-d_this), count(*) filter (where created_at>=now()-d_prev_start and created_at<now()-d_prev_end) into inq_t,inq_p from inquiries;
  select count(*) filter (where created_at>=now()-d_this), count(*) filter (where created_at>=now()-d_prev_start and created_at<now()-d_prev_end) into q_t,q_p from quotes;
  select count(*) filter (where created_at>=now()-d_this), count(*) filter (where created_at>=now()-d_prev_start and created_at<now()-d_prev_end) into c_t,c_p from customers;
  select count(*) filter (where registration_submitted_at>=now()-d_this), count(*) filter (where registration_submitted_at>=now()-d_prev_start and registration_submitted_at<now()-d_prev_end) into s_t,s_p from leads;
  select coalesce(sum(reveal_fee) filter (where revealed_at>=now()-d_this),0), coalesce(sum(reveal_fee) filter (where revealed_at>=now()-d_prev_start and revealed_at<now()-d_prev_end),0) into rev_t,rev_p from transactions where coalesce(refund_status,'')<>'approved';
  select round(100.0*count(distinct t.inquiry_id)/nullif(count(distinct i.id),0),1) into conv from inquiries i left join transactions t on t.inquiry_id=i.id where i.created_at>=now()-d_this;
  begin select public.fn_health_index() into health; exception when others then health:=null; end;
  select string_agg(cat,', ') into topcats from (select coalesce(nullif(category,''),'(uncat)') cat, count(*) n from inquiries where created_at>=now()-d_this group by 1 order by n desc limit 6) z;
  officer := public.fn_officer_recs(10);

  -- COMPETITIVE INTELLIGENCE, FROM THE ROSTER THE COMPANY ALREADY MAINTAINS.
  -- 27 tracked competitors, every one verified inside 60 days, and eight position dimensions
  -- measured against a market norm. None of it had ever reached a board report.
  select count(*), count(*) filter (where coalesce(offers_anonymity,false))
    into n_comp, n_anon from public.competitor;
  select string_agg(x.line, ' · ') into compet from (
      -- overlap is trimmed: the stored text runs to whole paragraphs, and five of them unabridged
      -- would be longer than the rest of the report put together.
      select c.name||' ('||coalesce(c.kind,'unclassified')||', threat '||coalesce(c.threat_level,'unrated')
             ||coalesce(' — '||left(nullif(btrim(c.overlap),''), 110), '')||')' as line
        from public.competitor c
       where coalesce(btrim(c.name),'') <> ''
       order by case lower(coalesce(c.threat_level,'')) when 'high' then 1 when 'medium' then 2
                                                        when 'low' then 3 else 4 end, c.name
       limit 5) x;
  select string_agg(p.dimension||': QuotesDone '||coalesce(p.quotesdone,'—')
                    ||' vs market '||coalesce(p.market_norm,'—')
                    ||coalesce(' ('||nullif(btrim(p.verdict),'')||')', ''), E'\n')
    into posn from public.competitive_position p;

  d := jsonb_build_array();
  if rev_t < rev_p then d := d||to_jsonb('Revenue down vs prior period — review demand and conversion'::text); end if;
  if inq_t < inq_p then d := d||to_jsonb('RFQ volume down vs prior period — assess top-of-funnel'::text); end if;
  if p_type='quarterly' then d := d||to_jsonb('Set next-quarter category focus and supply-activation targets'::text); end if;

  extra := 'RFQs '||inq_t||' (prev '||inq_p||') · Quotes '||q_t||' (prev '||q_p||') · New customers '||c_t||' (prev '||c_p||') · New suppliers '||s_t||' (prev '||s_p||') · Revenue AED '||round(rev_t)||' (prev AED '||round(rev_p)||')';

  body := public.fn_report_skeleton(
    'QuotesDone '||label||' — '||to_char(current_date,'Mon YYYY'),
    'Marketplace health '||coalesce(health->>'index','—')||'/100. Period totals: '||inq_t||' RFQs, '||q_t||' quotes, revenue AED '||round(rev_t)||', 30-day conversion '||coalesce(conv::text,'—')||'%.',
    jsonb_build_array(
      jsonb_build_object('heading','Key Metrics','body',extra),
      jsonb_build_object('heading','Trends (period over period)','body','Demand '||inq_t||' vs '||inq_p||' · Revenue AED '||round(rev_t)||' vs '||round(rev_p)||' · Suppliers +'||s_t||' vs +'||s_p),
      jsonb_build_object('heading','Growth & Categories','body','Top categories: '||coalesce(topcats,'—')),
      jsonb_build_object('heading',case when p_type='quarterly' then 'Strategy & Recommendations' else 'Recommendations' end,'body',coalesce(officer,'No officer recommendations yet.')),
      jsonb_build_object('heading','Competitive Position','body',
        n_comp||' competitor(s) tracked, '||(select count(*) from public.competitor where verified_at > now() - interval '60 days')
        ||' verified in the last 60 days. '||n_anon||' of '||n_comp
        ||' offer supplier anonymity, which is the differentiator this marketplace is built on.'
        ||coalesce(E'\nHighest threat: '||compet, '')
        ||coalesce(E'\n\nPosition against the market:\n'||posn, E'\nNo position dimensions are on record.')),
      jsonb_build_object('heading','Risks & Opportunities','body','Primary risk remains marketplace liquidity (activated supply + paying demand). Opportunity: convert the supplier database into an activated, quoting network in the top categories.')
    ), d,
    'Health: '||coalesce(health::text,'n/a'));

  insert into public.board_reports(week_start,title,body,kpis,report_type)
  values (date_trunc('month',current_date)::date, 'QuotesDone '||label||' — '||to_char(current_date,'Mon YYYY'), body,
    jsonb_build_object('rfqs',inq_t,'quotes',q_t,'customers',c_t,'suppliers',s_t,'revenue',rev_t,'conversion',conv,'health',(health->>'index')), p_type);

  select split_part(coalesce(value,'management@quotesdone.com'),',',1) into owner from app_secrets where key='admin_emails';
  insert into notifications(type,to_email,to_role,channel,subject,body)
  values ('period_report', coalesce(owner,'management@quotesdone.com'),'admin','email','QuotesDone '||label||' — '||to_char(current_date,'Mon YYYY'), body);
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase1_disarm(p_actor text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
declare v_id bigint; v_cron text := 'not_scheduled';
begin
  if coalesce(btrim(p_actor),'') = '' then raise exception 'an actor is required' using errcode='22023'; end if;
  if length(coalesce(btrim(p_reason),'')) < 8 then raise exception 'a reason of at least 8 characters is required' using errcode='22023'; end if;

  if public.fn_phase1_disarmed() then
    return jsonb_build_object('ok', true, 'already', true, 'disarmed', true,
      'note', 'Phase 1 was already disarmed; nothing changed.');
  end if;

  insert into public.phase1_rollback_log (actor, tier, reason, detail)
  values (p_actor, 'disarm', p_reason,
          jsonb_build_object('control_mode_actions_gated',
            (select count(*) from public.control_mode_action where classification = 'mutating')))
  returning id into v_id;

  -- The 5-minute sweep expires sessions and challenges. With the gate disarmed it has nothing to
  -- do, and leaving it running during a rollback only adds noise to the audit trail.
  begin
    perform cron.unschedule('control_mode_sweep_5min');
    v_cron := 'unscheduled';
  exception when others then v_cron := 'not_scheduled';
  end;

  return jsonb_build_object('ok', true, 'disarmed', true, 'log_id', v_id, 'cron', v_cron,
    'note', 'Every mutating action now passes and is written to control_mode_audit as action_allowed_phase1_disarmed. No rows were deleted. Re-arm with fn_phase1_rearm().');
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase1_disarmed()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((
    select tier = 'disarm' from public.phase1_rollback_log
     where tier in ('disarm','rearm') order by id desc limit 1
  ), false)
$function$


CREATE OR REPLACE FUNCTION public.fn_phase1_rearm(p_actor text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
declare v_id bigint; v_cron text;
begin
  if coalesce(btrim(p_actor),'') = '' then raise exception 'an actor is required' using errcode='22023'; end if;
  if length(coalesce(btrim(p_reason),'')) < 8 then raise exception 'a reason of at least 8 characters is required' using errcode='22023'; end if;

  if not public.fn_phase1_disarmed() then
    return jsonb_build_object('ok', true, 'already', true, 'disarmed', false,
      'note', 'Phase 1 was already armed; nothing changed.');
  end if;

  insert into public.phase1_rollback_log (actor, tier, reason, detail)
  values (p_actor, 'rearm', p_reason,
          jsonb_build_object('actions_allowed_while_disarmed',
            (select count(*) from public.control_mode_audit where event = 'action_allowed_phase1_disarmed')))
  returning id into v_id;

  begin
    perform cron.schedule('control_mode_sweep_5min', '*/5 * * * *', 'select public.fn_control_mode_sweep()');
    v_cron := 'scheduled';
  exception when others then v_cron := 'schedule_failed: ' || sqlerrm;
  end;

  return jsonb_build_object('ok', true, 'disarmed', false, 'log_id', v_id, 'cron', v_cron);
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase1_rollback_log_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  raise exception 'phase1_rollback_log is append-only; % is not permitted', TG_OP
    using errcode = '42501';
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase1_rollback_rehearse(p_actor text DEFAULT 'rehearsal'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
declare
  v_action text; v_before jsonb; v_during jsonb; v_after jsonb;
  v_d jsonb; v_r jsonb; v_steps jsonb := '[]'::jsonb;
begin
  select action into v_action from public.control_mode_action
   where classification = 'mutating' order by action limit 1;
  if v_action is null then raise exception 'no mutating action registered - nothing to rehearse against'; end if;

  v_before := public.fn_control_mode_require('rehearsal@quotesdone.com', v_action);
  v_steps := v_steps || jsonb_build_object('step','baseline','action',v_action,
    'allowed', v_before->>'allowed', 'expect','false',
    'pass', (v_before->>'allowed') = 'false');

  v_d := public.fn_phase1_disarm(p_actor, 'rollback rehearsal - aborted transaction, no lasting effect');
  v_steps := v_steps || jsonb_build_object('step','disarm','result',v_d,'pass', (v_d->>'ok')='true' and (v_d->>'disarmed')='true');

  v_during := public.fn_control_mode_require('rehearsal@quotesdone.com', v_action);
  v_steps := v_steps || jsonb_build_object('step','gate_after_disarm','allowed', v_during->>'allowed',
    'mode', v_during->>'mode', 'expect','true/disarmed',
    'pass', (v_during->>'allowed')='true' and (v_during->>'mode')='disarmed');

  v_steps := v_steps || jsonb_build_object('step','evidence_preserved',
    'refunds', (select count(*) from public.refunds),
    'control_mode_audit_rows', (select count(*) from public.control_mode_audit),
    'note','disarm deletes nothing; the count only grows because the disarmed pass is itself audited',
    'pass', true);

  v_r := public.fn_phase1_rearm(p_actor, 'rollback rehearsal - restoring the gate');
  v_steps := v_steps || jsonb_build_object('step','rearm','result',v_r,'pass',(v_r->>'ok')='true' and (v_r->>'disarmed')='false');

  v_after := public.fn_control_mode_require('rehearsal@quotesdone.com', v_action);
  v_steps := v_steps || jsonb_build_object('step','gate_after_rearm','allowed', v_after->>'allowed',
    'expect','false', 'pass', (v_after->>'allowed')='false');

  insert into public.phase1_rollback_log (actor, tier, reason, detail)
  values (p_actor, 'rehearse', 'tier 0 rollback rehearsal', jsonb_build_object('steps', v_steps));

  return jsonb_build_object(
    'ok', true,
    'all_passed', not exists (select 1 from jsonb_array_elements(v_steps) s where (s->>'pass') is distinct from 'true'),
    'steps', v_steps,
    'WARNING', 'This function MUTATES. It is only safe inside a transaction you abort. Everything it did is undone by ROLLBACK.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase1_status()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'disarmed', public.fn_phase1_disarmed(),
    'last_rollback_action', (select to_jsonb(l) from public.phase1_rollback_log l order by id desc limit 1),
    'objects', jsonb_build_object(
      'tables',    (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace
                     where n.nspname='public' and c.relkind='r'
                       and (c.relname like 'control_mode%' or c.relname like 'refund%' or c.relname='phase1_rollback_log')),
      'views',     (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace
                     where n.nspname='public' and c.relkind='v'
                       and (c.relname like 'v_refund%' or c.relname like 'v_supplier_exception%')),
      'functions', (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace
                     where n.nspname='public'
                       and (p.proname like 'fn_control_mode%' or p.proname like 'fn_refund%'
                            or p.proname like 'fn_supplier_exception%' or p.proname like 'fn_phase1%'))),
    'evidence_rows', jsonb_build_object(
      'refunds',                  (select count(*) from public.refunds),
      'refund_event_quarantine',  (select count(*) from public.refund_event_quarantine),
      'control_mode_audit',       (select count(*) from public.control_mode_audit),
      'control_mode_action',      (select count(*) from public.control_mode_action),
      'gated_actions',            (select count(*) from public.control_mode_action where classification='mutating')),
    'crons', (select coalesce(jsonb_object_agg(jobname, jsonb_build_object('schedule', schedule, 'active', active)), '{}'::jsonb)
                from cron.job where jobname in ('control_mode_sweep_5min','supplier_exception_sweep_daily')))
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_a_baseline_drift()
 RETURNS TABLE(subject text, approved text, live text)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare b public.org_phase_baseline%rowtype; v text;
begin
  select * into b from public.org_phase_baseline where phase = 'A';
  if not found then
    subject := 'baseline'; approved := 'a recorded Phase A baseline'; live := 'MISSING'; return next; return;
  end if;

  -- the counts, which are what a reader checks first
  v := (select count(*)::text from public.org_departments where active);
  if v is distinct from (b.counts->>'active_departments') then
    subject := 'active_departments'; approved := b.counts->>'active_departments'; live := v; return next; end if;

  v := (select count(*)::text from public.org_role where status='active' and runtime_mode <> 'knowledge_overlay');
  if v is distinct from (b.counts->>'canonical_roles') then
    subject := 'canonical_roles'; approved := b.counts->>'canonical_roles'; live := v; return next; end if;

  v := (select count(*)::text from public.org_role where status='active' and runtime_mode = 'knowledge_overlay');
  if v is distinct from (b.counts->>'category_overlays') then
    subject := 'category_overlays'; approved := b.counts->>'category_overlays'; live := v; return next; end if;

  v := (select count(*)::text from public.org_departments where active and lead_agent is not null);
  if v is distinct from (b.counts->>'department_heads') then
    subject := 'department_heads'; approved := b.counts->>'department_heads'; live := v; return next; end if;

  v := (select count(*)::text from public.org_workflow_ownership);
  if v is distinct from (b.counts->>'organizational_workflows') then
    subject := 'organizational_workflows'; approved := b.counts->>'organizational_workflows'; live := v; return next; end if;

  -- the invariant that must never come back non-zero
  v := (select count(*)::text from public.fn_phase_a_organization_violations());
  if v <> '0' then
    subject := 'phase_a_violations'; approved := '0'; live := v; return next; end if;

  -- the registry digests, each recomputed exactly as scripts/phase_a/freeze.mjs computed it:
  -- one line per row, fields joined by '|', lines joined by a newline, sha256 hex of the UTF-8 bytes.
  v := (select encode(sha256(convert_to(coalesce(string_agg(x, chr(10) order by x), ''), 'UTF8')), 'hex')
          from (select d.dept_key||'|'||d.name||'|'||coalesce(d.lead_agent,'') x
                  from public.org_departments d where d.active) s);
  if v is distinct from (b.registry_sha256->'departments'->>'database') then
    subject := 'registry:departments'; approved := b.registry_sha256->'departments'->>'database'; live := v; return next; end if;

  v := (select encode(sha256(convert_to(coalesce(string_agg(x, chr(10) order by sortkey), ''), 'UTF8')), 'hex')
          from (select r.role_id sortkey,
                       r.role_id||'|'||coalesce(r.manager_role_id,'founder')||'|'||r.primary_department_id x
                  from public.org_role r
                 where r.status='active' and r.runtime_mode <> 'knowledge_overlay') s);
  if v is distinct from (b.registry_sha256->'reporting_graph'->>'database') then
    subject := 'registry:reporting_graph'; approved := b.registry_sha256->'reporting_graph'->>'database'; live := v; return next; end if;

  v := (select encode(sha256(convert_to(coalesce(string_agg(x, chr(10) order by sortkey), ''), 'UTF8')), 'hex')
          from (select r.role_id sortkey, r.role_id||'|'||r.display_name||'|'||r.primary_department_id x
                  from public.org_role r
                 where r.status='active' and r.runtime_mode = 'knowledge_overlay') s);
  if v is distinct from (b.registry_sha256->'category_overlays'->>'database') then
    subject := 'registry:category_overlays'; approved := b.registry_sha256->'category_overlays'->>'database'; live := v; return next; end if;

  v := (select encode(sha256(convert_to(coalesce(string_agg(x, chr(10) order by sortkey), ''), 'UTF8')), 'hex')
          from (select o.workflow_id sortkey,
                       o.workflow_id||'|'||o.workflow_name||'|'||o.accountable_role_id||'|'
                       ||array_to_string(o.contributors, ';')||'|'||coalesce(o.independent_reviewer,'') x
                  from public.org_workflow_ownership o) s);
  if v is distinct from (b.registry_sha256->'workflow_ownership'->>'database') then
    subject := 'registry:workflow_ownership'; approved := b.registry_sha256->'workflow_ownership'->>'database'; live := v; return next; end if;

  v := (select encode(sha256(convert_to(coalesce(string_agg(x, chr(10) order by sortkey), ''), 'UTF8')), 'hex')
          from (select f.decision_key sortkey, f.decision_key||'|'||f.description x
                  from public.founder_reserved_decision f) s);
  if v is distinct from (b.registry_sha256->'founder_reserved'->>'database') then
    subject := 'registry:founder_reserved'; approved := b.registry_sha256->'founder_reserved'->>'database'; live := v; return next; end if;

  return;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_a_deferred_items()
 RETURNS TABLE(status text, rule text, role_id text, detail text)
 LANGUAGE sql
 STABLE
AS $function$
  select 'DEFERRED_TO_LATER_PHASES', v.rule, v.role_id, v.detail
    from public.fn_org_role_violations_all() v
   where v.rule in ('no_kpi','no_knowledge','no_authority','no_tools','no_evaluation',
                    'runtime_agent_inactive','no_model_policy');
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_a_freeze_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_reason text; v_depts int; v_roles int; v_overlays int; b public.org_phase_baseline%rowtype;
begin
  select * into b from public.org_phase_baseline where phase = 'A';
  if not found then return null; end if;   -- nothing approved yet, nothing to freeze

  select count(*) into v_depts from public.org_departments where active;
  select count(*) into v_roles from public.org_role where status='active' and runtime_mode <> 'knowledge_overlay';
  select count(*) into v_overlays from public.org_role where status='active' and runtime_mode = 'knowledge_overlay';

  if v_depts = (b.counts->>'active_departments')::int
     and v_roles = (b.counts->>'canonical_roles')::int
     and v_overlays = (b.counts->>'category_overlays')::int then
    return null;                            -- the shape is unchanged; this was not a Phase A change
  end if;

  v_reason := nullif(btrim(current_setting('app.phase_a_change_reason', true)), '');
  if v_reason is null then
    raise exception
      'PHASE A IS FROZEN. This statement changes the approved organisational shape from %/%/% to %/%/% '
      '(departments/roles/overlays), and the founder approved the first on 2026-08-15. A change needs a '
      'formal Phase A change request with evidence and founder approval. State it in the same transaction: '
      '  set local app.phase_a_change_reason = ''PACR-nnn: <finding, evidence, approver>'';',
      b.counts->>'active_departments', b.counts->>'canonical_roles', b.counts->>'category_overlays',
      v_depts, v_roles, v_overlays;
  end if;

  raise notice 'PHASE A SHAPE CHANGED to %/%/% under change reason: %', v_depts, v_roles, v_overlays, v_reason;
  return null;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_a_organization_violations()
 RETURNS TABLE(rule text, subject text, detail text)
 LANGUAGE sql
 STABLE
AS $function$
  -- active canonical department
  select 'department_not_active', r.role_id, r.primary_department_id
    from public.org_role r
    left join public.org_departments d on d.dept_key = r.primary_department_id
   where r.status='active' and (d.dept_key is null or not d.active)
  union all
  -- primary manager, with the CEO/founder boundary as the single exception
  select 'no_primary_manager', r.role_id, 'manager_role_id is null'
    from public.org_role r
   where r.status='active' and r.runtime_mode <> 'knowledge_overlay'
     and r.manager_role_id is null and r.role_id <> 'ceo'
  union all
  select 'manager_not_active', r.role_id, r.manager_role_id
    from public.org_role r
   where r.status='active' and r.manager_role_id is not null
     and not exists (select 1 from public.org_role m where m.role_id=r.manager_role_id and m.status='active')
  union all
  -- role class: every active role declares which kind of thing it is
  select 'no_role_class', r.role_id, coalesce(r.runtime_mode,'(null)')
    from public.org_role r
   where r.status='active' and coalesce(r.runtime_mode,'') = ''
  union all
  -- necessity, and the reason for it
  select 'no_necessity_status', r.role_id, 'necessity_status is null'
    from public.org_role r
   where r.status='active' and coalesce(btrim(r.necessity_status),'') = ''
  union all
  -- organizational purpose
  select 'no_organizational_purpose', r.role_id, 'necessity_reason/responsibilities empty'
    from public.org_role r
   where r.status='active'
     and coalesce(length(btrim(r.necessity_reason)),0) < 10
     and coalesce(length(btrim(r.responsibilities)),0) < 10
  union all
  -- owned decisions. Overlays own category judgement rather than decisions, and say so in their
  -- necessity_reason, so the rule is scoped to accountable roles rather than relaxed for everyone.
  select 'no_owned_decisions', r.role_id, 'owned_decisions is empty'
    from public.org_role r
   where r.status='active' and r.runtime_mode <> 'knowledge_overlay'
     and coalesce(cardinality(r.owned_decisions),0) = 0
  union all
  -- forbidden decisions: a role with no stated limits has no limits
  select 'no_forbidden_decisions', r.role_id, 'forbidden_decisions is empty'
    from public.org_role r
   where r.status='active' and r.runtime_mode <> 'knowledge_overlay'
     and coalesce(cardinality(r.forbidden_decisions),0) = 0
  union all
  -- AT LEAST ONE WORKFLOW, REVIEW OR MANAGEMENT RESPONSIBILITY. This is also the rule that catches
  -- a role retained only to keep a count at 90: such a role manages nobody, owns no workflow,
  -- appears in no step and reviews nothing.
  select 'no_responsibility', r.role_id, 'owns no workflow, no step, manages nobody, reviews nothing'
    from public.org_role r
   where r.status='active' and r.runtime_mode <> 'knowledge_overlay'
     and not exists (select 1 from public.org_workflow_ownership o where o.accountable_role_id = r.role_id)
     and not exists (select 1 from public.org_workflow_step s where s.accountable_role_id = r.role_id)
     and not exists (select 1 from public.org_workflow_ownership o where o.independent_reviewer = r.role_id)
     and not exists (select 1 from public.org_role m where m.manager_role_id = r.role_id and m.status='active')
     and not exists (select 1 from public.workflow_step w where w.actor_role = r.role_id)
     and not exists (select 1 from public.employee_workflow e where e.agent_key = r.runtime_agent_key)
     -- contributing to a workflow IS a responsibility. It is not ACCOUNTABILITY, which is why
     -- contributors are still refused as owners two rules down, but a role that contributes to a
     -- workflow is doing something and is not a row kept to make a count.
     and not exists (select 1 from public.org_workflow_ownership o where r.role_id = any(o.contributors))
  union all
  -- a contributor must be an active role or one of the three declared class terms
  select 'contributor_resolves_to_nobody', o.workflow_id, c
    from public.org_workflow_ownership o, unnest(o.contributors) c
   where not exists (select 1 from public.org_role r where r.role_id = c and r.status='active')
     and c not in ('department heads', 'category overlays', 'broad domain specialists')
  union all
  -- creator/reviewer separation, at the workflow and at the role
  select 'owner_reviews_own_workflow', o.workflow_id, o.accountable_role_id
    from public.org_workflow_ownership o
   where o.independent_reviewer = o.accountable_role_id
  union all
  select 'contributor_is_owner', o.workflow_id, o.accountable_role_id
    from public.org_workflow_ownership o
   where o.accountable_role_id = any(o.contributors)
  union all
  -- founder boundary
  select 'owns_founder_reserved_decision', r.role_id, d.decision_key
    from public.org_role r, public.founder_reserved_decision d, unnest(d.match_any) m(needle)
   where r.status='active'
     and position(m.needle in lower(array_to_string(r.owned_decisions,' | '))) > 0
  union all
  -- reporting cycles, walked rather than assumed
  select 'reporting_cycle', u.root, 'chain does not terminate'
    from (
      with recursive up(root, cur, depth, path) as (
        select role_id, manager_role_id, 1, array[role_id] from public.org_role where status='active'
        union all
        select u.root, r.manager_role_id, u.depth+1, u.path || r.role_id
          from up u join public.org_role r on r.role_id = u.cur and r.status='active'
         where u.depth < 30 and not r.role_id = any(u.path))
      select distinct root from up where depth >= 30) u
  union all
  select 'self_management', r.role_id, r.manager_role_id
    from public.org_role r where r.status='active' and r.manager_role_id = r.role_id
  union all
  -- duplicate active role identity
  select 'duplicate_active_identity', x.runtime_agent_key, 'held by more than one active role'
    from (select runtime_agent_key from public.org_role
           where status='active' and runtime_agent_key is not null
           group by 1 having count(*) > 1) x
  union all
  -- unresolved historical alias, both directions
  select 'retired_role_resolves_to_nobody', r.role_id, 'no alias'
    from public.org_role r
   where r.status = 'retired'
     and not exists (select 1 from public.org_role_alias a where a.alias = r.role_id)
  union all
  select 'alias_points_at_a_dead_role', a.alias, a.role_id
    from public.org_role_alias a
    join public.org_role r on r.role_id = a.role_id
   where r.status <> 'active'
  union all
  -- overlay ownership
  select 'overlay_is_not_a_category_overlay', r.role_id, 'not category_overlay_NNN_'
    from public.org_role r
   where r.status='active' and r.runtime_mode='knowledge_overlay'
     and r.role_id !~ '^category_overlay_[0-9]{3}_'
  union all
  select 'overlay_holds_a_runtime_employee', r.role_id, r.runtime_agent_key
    from public.org_role r
   where r.status='active' and r.runtime_mode='knowledge_overlay' and r.runtime_agent_key is not null
  union all
  select 'overlay_owns_a_workflow', o.workflow_id, o.accountable_role_id
    from public.org_workflow_ownership o join public.org_role r on r.role_id = o.accountable_role_id
   where r.runtime_mode = 'knowledge_overlay'
  union all
  select 'overlay_states_no_limit', r.role_id, 'necessity_reason does not say what it cannot decide'
    from public.org_role r
   where r.status='active' and r.runtime_mode='knowledge_overlay'
     and coalesce(r.necessity_reason,'') not ilike '%cannot decide%';
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_b_baseline_drift()
 RETURNS TABLE(subject text, approved text, live text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare b public.org_phase_baseline%rowtype; v text; r record;
begin
  select * into b from public.org_phase_baseline where phase = 'B';
  if not found then
    subject := 'baseline'; approved := 'a recorded Phase B baseline'; live := 'MISSING';
    return next; return;
  end if;

  -- the counts a reader checks first
  for r in select * from (values
      ('workflows',   (select count(*)::text from public.phase_b_workflow)),
      ('steps',       (select count(*)::text from public.phase_b_workflow_step)),
      ('handoffs',    (select count(*)::text from public.phase_b_handoff)),
      ('cross_department_handoffs',
                      (select count(*)::text from public.phase_b_handoff where handoff_type='cross_department')),
      ('business_objects', (select count(*)::text from public.phase_b_business_object)),
      ('business_rules',   (select count(*)::text from public.phase_b_business_rule)),
      ('gates',            (select count(*)::text from public.phase_b_gate)),
      ('exceptions',       (select count(*)::text from public.phase_b_exception)),
      ('sla_policies',     (select count(*)::text from public.phase_b_sla_policy)),
      ('events',           (select count(*)::text from public.phase_b_event)),
      ('workflow_states',      (select count(*)::text from public.phase_b_workflow_state)),
      ('workflow_transitions', (select count(*)::text from public.phase_b_workflow_transition)),
      ('step_states',          (select count(*)::text from public.phase_b_step_state)),
      ('step_transitions',     (select count(*)::text from public.phase_b_step_transition)),
      ('founder_boundaries',   (select count(*)::text from public.phase_b_founder_boundary)),
      ('crosswalk_classifications', (select count(*)::text from public.phase_b_crosswalk))
    ) t(k, v)
  loop
    if r.v is distinct from (b.counts->>r.k) then
      subject := 'count:'||r.k; approved := b.counts->>r.k; live := r.v; return next;
    end if;
  end loop;

  -- the frozen structure, one digest per subject the founder named
  for r in select * from public.fn_phase_b_structure_digest() loop
    if r.sha256 is distinct from (b.registry_sha256->'structure'->r.subject->>'database') then
      subject := 'structure:'||r.subject;
      approved := coalesce(b.registry_sha256->'structure'->r.subject->>'database', 'NOT RECORDED');
      live := r.sha256; return next;
    end if;
  end loop;

  -- the three founder-stated erratum conditions must still hold
  v := (select count(*)::text from public.fn_phase_b_effective_errata() where not resolved);
  if v <> '0' then
    subject := 'effective_errata_unresolved'; approved := '0'; live := v; return next;
  end if;

  -- and Phase A must still be frozen underneath it
  v := (select count(*)::text from public.fn_phase_a_baseline_drift());
  if v <> '0' then
    subject := 'phase_a_baseline_drift'; approved := '0'; live := v; return next;
  end if;

  return;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_b_change_request_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception
    'phase_b_change_request is append-only. % on % is refused. A change request is the audit trail '
    'for a frozen architecture; correcting one means raising the next change request that '
    'supersedes it, so both remain readable.',
    tg_op, coalesce(old.change_request_id, new.change_request_id);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_b_closure_blockers(p_workflow_id text, p_completed_steps text[], p_open_blockers bigint, p_open_handoffs bigint)
 RETURNS SETOF text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_missing text;
begin
  if p_open_blockers > 0 then
    return next format('%s unresolved blocker(s)', p_open_blockers);
  end if;
  if p_open_handoffs > 0 then
    return next format('%s handoff(s) not accepted', p_open_handoffs);
  end if;
  for v_missing in
    select s.step_id from public.phase_b_workflow_step s
    where s.workflow_id = p_workflow_id
      and s.step_id <> all (coalesce(p_completed_steps, '{}'::text[]))
  loop
    return next format('mandatory step %s not completed', v_missing);
  end loop;
  return;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_b_effective_errata()
 RETURNS TABLE(erratum text, condition text, measured text, resolved boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select 'EX-006',
         'exception is complete: escalation owner, required response and closure condition present, and escalation is independent of detection',
         format('escalation=%s detection=%s response=%s closure=%s',
                e.escalation_owner_role_id, e.detection_owner_role_id,
                case when e.required_response <> '' then 'present' else 'MISSING' end,
                case when e.closure_condition <> '' then 'present' else 'MISSING' end),
         e.escalation_owner_role_id <> '' and e.required_response <> ''
           and e.closure_condition <> '' and e.escalation_owner_role_id <> e.detection_owner_role_id
  from public.phase_b_exception e where e.exception_id = 'EX-006'

  union all
  select 'W13',
         'primary business object references an existing canonical object',
         format('primary_object=%s exists=%s', w.primary_object, (o.object_id is not null)),
         o.object_id is not null
  from public.phase_b_workflow w
  left join public.phase_b_business_object o on o.object_id = w.primary_object
  where w.workflow_id = 'W13'

  union all
  select 'W22',
         'workflow has exactly one explicit closure step, it is the step reaching WORKFLOW_COMPLETE, and GATE-008 is attached to it',
         format('closure_steps=%s reaches_complete=%s gate_008_attached_to=%s',
                (select count(*) from public.phase_b_workflow_step where workflow_id='W22' and is_closure_step),
                (select bool_and(next_step_if_pass = 'WORKFLOW_COMPLETE')
                   from public.phase_b_workflow_step where workflow_id='W22' and is_closure_step),
                coalesce((select string_agg(a.step_id, ',') from public.fn_phase_b_gate_attachment() a
                           where a.gate_id='GATE-008' and a.workflow_id='W22'), 'NONE')),
         (select count(*) from public.phase_b_workflow_step where workflow_id='W22' and is_closure_step) = 1
         and (select bool_and(next_step_if_pass = 'WORKFLOW_COMPLETE')
                from public.phase_b_workflow_step where workflow_id='W22' and is_closure_step)
         and exists (select 1 from public.fn_phase_b_gate_attachment() a
                      where a.gate_id='GATE-008' and a.workflow_id='W22' and a.step_id is not null);
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_b_freeze_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  b public.org_phase_baseline%rowtype;
  v_reason text;
  v_moved text;
  v_count bigint;
begin
  select * into b from public.org_phase_baseline where phase = 'B';
  if not found then return null; end if;    -- nothing approved yet, nothing to freeze

  -- Which of the founder's frozen subjects moved? Compared against the digest recorded at
  -- approval, using the same function the baseline was built from.
  select string_agg(d.subject || ' (' || left(d.sha256, 12) || ' != '
                    || left(coalesce(b.registry_sha256->'structure'->d.subject->>'database','NONE'), 12) || ')',
                    ', ' order by d.subject)
    into v_moved
  from public.fn_phase_b_structure_digest() d
  where d.sha256 is distinct from (b.registry_sha256->'structure'->d.subject->>'database');

  if v_moved is null then
    return null;                            -- the approved structure is unchanged
  end if;

  v_reason := nullif(btrim(current_setting('app.phase_b_change_reason', true)), '');
  if v_reason is null then
    raise exception
      'PHASE B IS FROZEN. This statement changes the approved workflow architecture: %. '
      'The founder approved this architecture on 2026-08-15 as the final QuotesDone business-workflow '
      'design. A change needs a formal Phase B change request stating the observed problem, evidence, '
      'current workflow and step, proposed change, affected owners, state-machine impact, gate and rule '
      'impact, customer/supplier impact, privacy/legal/financial impact, backward compatibility and '
      'whether founder approval is required. State it in the same transaction: '
      '  set local app.phase_b_change_reason = ''PBCR-nnn: <the above>'';',
      v_moved;
  end if;

  select count(*) into v_count from public.fn_phase_b_structure_digest() d
   where d.sha256 is distinct from (b.registry_sha256->'structure'->d.subject->>'database');
  raise notice 'PHASE B STRUCTURE CHANGED in % subject(s) [%] under change reason: %',
    v_count, v_moved, v_reason;
  return null;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_b_gate_attachment()
 RETURNS TABLE(gate_id text, workflow_id text, step_id text, attachment_basis text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with scoped as (
    -- expand workflow_scope; 'ALL' means every canonical workflow. Both ';' and '/' appear as
    -- separators across the package's registries, so both are split on.
    select g.gate_id, g.gate_name, g.gate_type, w.workflow_id
    from public.phase_b_gate g
    join public.phase_b_workflow w
      on g.workflow_scope = 'ALL'
      or w.workflow_id = any (string_to_array(replace(g.workflow_scope, '/', ';'), ';'))
  )
  -- gates that govern the phase rather than a step
  select s.gate_id, s.workflow_id, null::text, 'phase_level'
  from scoped s
  where s.gate_type = 'phase_boundary' or s.gate_id = 'GATE-001'

  union all
  -- GATE-008 closure completeness -> the workflow's closure step
  select s.gate_id, s.workflow_id, st.step_id, 'declared_step_property'
  from scoped s
  join public.phase_b_workflow_step st on st.workflow_id = s.workflow_id and st.is_closure_step
  where s.gate_id = 'GATE-008'

  union all
  -- GATE-005 founder boundary -> steps that carry a founder gate
  select s.gate_id, s.workflow_id, st.step_id, 'declared_step_property'
  from scoped s
  join public.phase_b_workflow_step st on st.workflow_id = s.workflow_id
   and st.founder_gate is not null and lower(st.founder_gate) <> 'none'
  where s.gate_id = 'GATE-005'

  union all
  -- GATE-004 creator/reviewer separation -> steps that carry an independent reviewer
  select s.gate_id, s.workflow_id, st.step_id, 'declared_step_property'
  from scoped s
  join public.phase_b_workflow_step st on st.workflow_id = s.workflow_id
   and st.independent_reviewer_role_id is not null
  where s.gate_id = 'GATE-004'

  union all
  -- GATE-007 complete handoff -> steps that send one
  select distinct s.gate_id, s.workflow_id, h.from_step_id, 'declared_step_property'
  from scoped s
  join public.phase_b_handoff h on h.workflow_id = s.workflow_id
  where s.gate_id = 'GATE-007'

  union all
  -- gates that govern every step
  select s.gate_id, s.workflow_id, st.step_id, 'universal'
  from scoped s
  join public.phase_b_workflow_step st on st.workflow_id = s.workflow_id
  where s.gate_id in ('GATE-002','GATE-003','GATE-006')

  union all
  -- workflow-scoped gates with no finer anchor declared in the package
  select s.gate_id, s.workflow_id, st.step_id, 'workflow_scope'
  from scoped s
  join public.phase_b_workflow_step st on st.workflow_id = s.workflow_id
  where s.gate_id not in ('GATE-001','GATE-002','GATE-003','GATE-004','GATE-005',
                          'GATE-006','GATE-007','GATE-008')
    and s.gate_type <> 'phase_boundary';
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_b_handoff_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_from public.phase_b_workflow_step%rowtype;
        v_to   public.phase_b_workflow_step%rowtype;
begin
  select * into v_from from public.phase_b_workflow_step where step_id = new.from_step_id;
  select * into v_to   from public.phase_b_workflow_step where step_id = new.to_step_id;
  if v_from.workflow_id <> new.workflow_id or v_to.workflow_id <> new.workflow_id then
    raise exception 'phase_b: handoff % joins steps outside workflow %', new.handoff_id, new.workflow_id;
  end if;
  if new.sending_role_id <> v_from.accountable_role_id then
    raise exception 'phase_b: handoff % says sender % but step % is owned by %',
      new.handoff_id, new.sending_role_id, new.from_step_id, v_from.accountable_role_id;
  end if;
  if new.receiving_role_id <> v_to.accountable_role_id then
    raise exception 'phase_b: handoff % says receiver % but step % is owned by %',
      new.handoff_id, new.receiving_role_id, new.to_step_id, v_to.accountable_role_id;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_b_invariants()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
with
-- ---------------------------------------------------------------- declared counts
counts(check_name, expected, actual) as (
  values
    ('count.workflows',            (select (b.counts->>'workflows')::text from public.org_phase_baseline b where b.phase = 'B'),  (select count(*)::text from public.phase_b_workflow)),
    ('count.steps',                (select (b.counts->>'steps')::text from public.org_phase_baseline b where b.phase = 'B'), (select count(*)::text from public.phase_b_workflow_step)),
    ('count.handoffs',             (select (b.counts->>'handoffs')::text from public.org_phase_baseline b where b.phase = 'B'), (select count(*)::text from public.phase_b_handoff)),
    ('count.business_objects',     (select (b.counts->>'business_objects')::text from public.org_phase_baseline b where b.phase = 'B'),  (select count(*)::text from public.phase_b_business_object)),
    ('count.business_rules',       (select (b.counts->>'business_rules')::text from public.org_phase_baseline b where b.phase = 'B'),  (select count(*)::text from public.phase_b_business_rule)),
    ('count.exceptions',           (select (b.counts->>'exceptions')::text from public.org_phase_baseline b where b.phase = 'B'),  (select count(*)::text from public.phase_b_exception)),
    ('count.sla_policies',         (select (b.counts->>'sla_policies')::text from public.org_phase_baseline b where b.phase = 'B'),  (select count(*)::text from public.phase_b_sla_policy)),
    ('count.gates',                (select (b.counts->>'gates')::text from public.org_phase_baseline b where b.phase = 'B'),  (select count(*)::text from public.phase_b_gate)),
    ('count.events',               (select (b.counts->>'events')::text from public.org_phase_baseline b where b.phase = 'B'), (select count(*)::text from public.phase_b_event)),
    ('count.workflow_states',      (select (b.counts->>'workflow_states')::text from public.org_phase_baseline b where b.phase = 'B'),  (select count(*)::text from public.phase_b_workflow_state)),
    ('count.workflow_transitions', (select (b.counts->>'workflow_transitions')::text from public.org_phase_baseline b where b.phase = 'B'),  (select count(*)::text from public.phase_b_workflow_transition)),
    ('count.step_states',          (select (b.counts->>'step_states')::text from public.org_phase_baseline b where b.phase = 'B'),  (select count(*)::text from public.phase_b_step_state)),
    ('count.step_transitions',     (select (b.counts->>'step_transitions')::text from public.org_phase_baseline b where b.phase = 'B'),  (select count(*)::text from public.phase_b_step_transition)),
    ('count.founder_boundaries',   (select (b.counts->>'founder_boundaries')::text from public.org_phase_baseline b where b.phase = 'B'),  (select count(*)::text from public.phase_b_founder_boundary)),
    ('count.cross_department_handoffs', (select (b.counts->>'cross_department_handoffs')::text from public.org_phase_baseline b where b.phase = 'B'),
      (select count(*)::text from public.phase_b_handoff where handoff_type = 'cross_department'))
),
-- ------------------------------------------------------------ identity and ownership
owners(check_name, expected, actual) as (
  values
    -- population first: a zero-violation count over an empty table proves nothing
    ('population.steps_with_owner', '257',
      (select count(*)::text from public.phase_b_workflow_step where accountable_role_id <> '')),
    ('identity.unknown_step_owners', '0',
      (select count(*)::text from public.phase_b_workflow_step s
        where s.actor_kind = 'canonical_role'
          and public.fn_phase_b_resolve_role(s.accountable_role_id) is null)),
    ('identity.inactive_step_owners', '0',
      (select count(*)::text from public.phase_b_workflow_step s
        join public.org_role r on r.role_id = s.accountable_role_id
        where s.actor_kind = 'canonical_role' and r.status <> 'active')),
    ('identity.steps_without_owner', '0',
      (select count(*)::text from public.phase_b_workflow_step where coalesce(accountable_role_id,'') = '')),
    -- step_id is the primary key, so a second accountable owner would need a second row
    ('identity.steps_with_multiple_owners', '0',
      (select count(*)::text from (
         select step_id from public.phase_b_workflow_step group by step_id having count(*) > 1) d)),
    ('identity.workflows_without_owner', '0',
      (select count(*)::text from public.phase_b_workflow where coalesce(accountable_role_id,'') = '')),
    ('identity.overlay_accountable_outside_scope', '0',
      (select count(*)::text from public.phase_b_workflow_step
        where actor_kind = 'category_overlay'
          and (workflow_id not in ('W05','W06','W07','W10','W14') or step_type <> 'analysis'))),
    ('identity.dynamic_actor_accountable', '0',
      (select count(*)::text from public.phase_b_workflow_step s
        join public.phase_b_dynamic_actor a on a.actor_token = s.accountable_role_id
        where not a.may_be_accountable))
),
-- ------------------------------------------------------------------------ coverage
role_use as (
  select accountable_role_id role_id from public.phase_b_workflow_step
  union select independent_reviewer_role_id from public.phase_b_workflow_step where independent_reviewer_role_id is not null
  union select unnest(contributors) from public.phase_b_workflow_step
  union select accountable_role_id from public.phase_b_workflow
  union select independent_reviewer_role_id from public.phase_b_workflow where independent_reviewer_role_id is not null
  union select unnest(contributors) from public.phase_b_workflow
  union select detection_owner_role_id from public.phase_b_exception
  union select escalation_owner_role_id from public.phase_b_exception
  union select accountable_role_id from public.phase_b_business_object
),
coverage(check_name, expected, actual) as (
  values
    ('coverage.canonical_roles_total', '90',
      (select count(*)::text from public.org_role
        where status = 'active' and runtime_mode <> 'knowledge_overlay')),
    ('coverage.roles_unrepresented', '0',
      (select count(*)::text from public.org_role r
        where r.status = 'active' and r.runtime_mode <> 'knowledge_overlay'
          and r.role_id not in (select role_id from role_use where role_id is not null))),
    ('coverage.departments_unrepresented', '0',
      (select count(*)::text from public.org_departments d
        where d.active and not exists (
          select 1 from public.org_role r
          where r.primary_department_id = d.dept_key and r.status = 'active'
            and r.role_id in (select role_id from role_use where role_id is not null)))),
    ('coverage.category_overlays_governed', '86',
      (select count(*)::text from public.org_role
        where status = 'active' and runtime_mode = 'knowledge_overlay')),
    ('coverage.workflows_without_steps', '0',
      (select count(*)::text from public.phase_b_workflow w
        where not exists (select 1 from public.phase_b_workflow_step s where s.workflow_id = w.workflow_id))),
    ('coverage.workflows_without_closure_step', '0',
      (select count(*)::text from public.phase_b_workflow w
        where not exists (select 1 from public.phase_b_workflow_step s
                           where s.workflow_id = w.workflow_id and s.is_closure_step))),
    ('coverage.workflows_with_multiple_closure_steps', '0',
      (select count(*)::text from (
         select workflow_id from public.phase_b_workflow_step where is_closure_step
         group by workflow_id having count(*) > 1) d))
),
-- ------------------------------------------------------------------ graph and sequence
graph(check_name, expected, actual) as (
  values
    ('graph.duplicate_workflow_ids', '0',
      (select count(*)::text from (select workflow_id from public.phase_b_workflow group by 1 having count(*)>1) d)),
    ('graph.duplicate_step_ids', '0',
      (select count(*)::text from (select step_id from public.phase_b_workflow_step group by 1 having count(*)>1) d)),
    ('graph.impossible_next_step_references', '0',
      (select count(*)::text from public.phase_b_workflow_step s
        where (s.next_step_if_pass not in ('WORKFLOW_COMPLETE','WORKFLOW_BLOCKED',
                'WORKFLOW_BLOCKED_OR_ESCALATED','CORRECTION_OR_REJECTION_PATH')
               and not exists (select 1 from public.phase_b_workflow_step t where t.step_id = s.next_step_if_pass))
           or (s.next_step_if_fail not in ('WORKFLOW_COMPLETE','WORKFLOW_BLOCKED',
                'WORKFLOW_BLOCKED_OR_ESCALATED','CORRECTION_OR_REJECTION_PATH')
               and not exists (select 1 from public.phase_b_workflow_step t where t.step_id = s.next_step_if_fail)))),
    ('graph.steps_without_inbound_path', '0',
      (select count(*)::text from public.phase_b_workflow_step s
        where s.step_no > 1
          and not exists (select 1 from public.phase_b_workflow_step p
                           where p.workflow_id = s.workflow_id
                             and (p.next_step_if_pass = s.step_id or p.next_step_if_fail = s.step_id)))),
    ('graph.step_numbering_not_dense', '0',
      (select count(*)::text from (
         select workflow_id from public.phase_b_workflow_step
         group by workflow_id
         having max(step_no) <> count(*) or min(step_no) <> 1) d)),
    ('graph.transitions_to_unknown_state', '0', '0'),   -- foreign keys make this structurally impossible
    ('graph.terminal_state_reopened', '0',
      (select count(*)::text from public.phase_b_workflow_transition t
        join public.phase_b_workflow_state f on f.state = t.from_state
        join public.phase_b_workflow_state x on x.state = t.to_state
        where f.terminal and not x.terminal)),
    ('graph.step_state_refs_unknown', '0', '0')          -- foreign keys, as above
),
-- -------------------------------------------------------------------------- handoffs
handoffs(check_name, expected, actual) as (
  values
    ('handoff.owner_change_without_contract', '0',
      (select count(*)::text from public.phase_b_workflow_step s
        join public.phase_b_workflow_step n on n.step_id = s.next_step_if_pass
        where s.accountable_role_id <> n.accountable_role_id
          and not exists (select 1 from public.phase_b_handoff h
                           where h.from_step_id = s.step_id and h.to_step_id = n.step_id))),
    ('handoff.incomplete_packet', '0',
      (select count(*)::text from public.phase_b_handoff
        where coalesce(required_packet,'') = '' or coalesce(receiving_acceptance_criteria,'') = ''
           or coalesce(rejection_condition,'') = '' or coalesce(return_owner_role_id,'') = ''
           or coalesce(closure_condition,'') = '' or coalesce(sla_policy_id,'') = '')),
    ('handoff.role_mismatch_with_steps', '0',
      (select count(*)::text from public.phase_b_handoff h
        join public.phase_b_workflow_step f on f.step_id = h.from_step_id
        join public.phase_b_workflow_step t on t.step_id = h.to_step_id
        where h.sending_role_id <> f.accountable_role_id
           or h.receiving_role_id <> t.accountable_role_id)),
    ('handoff.cross_department_without_sla', '0',
      (select count(*)::text from public.phase_b_handoff
        where handoff_type = 'cross_department' and coalesce(sla_policy_id,'') = '')),
    ('handoff.unknown_sla_reference', '0', '0')          -- foreign key
),
-- ---------------------------------------------------------------- review and authority
authority(check_name, expected, actual) as (
  values
    ('population.steps_with_reviewer', 'gt0',
      (case when (select count(*) from public.phase_b_workflow_step
                   where independent_reviewer_role_id is not null) > 0 then 'gt0' else '0' end)),
    ('authority.creator_reviewer_collisions', '0',
      (select count(*)::text from public.phase_b_workflow_step
        where independent_reviewer_role_id is not null
          and independent_reviewer_role_id = accountable_role_id)),
    ('authority.workflow_owner_reviewer_collisions', '0',
      (select count(*)::text from public.phase_b_workflow
        where independent_reviewer_role_id is not null
          and independent_reviewer_role_id = accountable_role_id)),
    ('authority.exception_escalates_to_its_own_detector', '0',
      (select count(*)::text from public.phase_b_exception
        where escalation_owner_role_id = detection_owner_role_id)),
    ('authority.overlay_with_dispatch_payment_reveal_release', '0',
      (select count(*)::text from public.phase_b_workflow_step
        where actor_kind = 'category_overlay' and workflow_id in ('W12','W15','W16','W17','W24'))),
    -- the supplier onboarding owner may not decide the supplier's own verification
    ('authority.onboarding_approving_own_supplier', '0',
      (select count(*)::text from public.phase_b_workflow_step s
        where s.workflow_id = 'W10' and s.step_type in ('decision','review')
          and s.accountable_role_id = (select accountable_role_id from public.phase_b_workflow where workflow_id = 'W09'))),
    -- the identity that moves the money may not be the identity that reconciles it
    ('authority.payment_executor_reconciles_own_action', '0',
      (select count(*)::text from public.phase_b_workflow_step r
        where r.workflow_id = 'W16' and r.step_type = 'review'
          and r.accountable_role_id in (
            select e.accountable_role_id from public.phase_b_workflow_step e
            where e.workflow_id = 'W16' and e.step_type in ('intake','execution','decision')
              and e.required_output ~* 'payment request|provider event|transaction state'))),
    -- whoever built the release may not issue its own go/no-go
    ('authority.release_decided_by_an_implementer', '0',
      (select count(*)::text from public.phase_b_workflow_step d
        where d.workflow_id = 'W24' and d.step_type = 'decision'
          and d.accountable_role_id in (
            select accountable_role_id from public.phase_b_workflow_step
            where workflow_id = 'W22' and step_type = 'execution'))),
    ('population.founder_boundaries_in_scope', '10',
      (select count(*)::text from public.phase_b_founder_boundary)),
    ('authority.founder_boundary_without_any_gate', '0',
      (select count(*)::text from public.phase_b_founder_boundary b
        where not exists (
          select 1 from public.phase_b_workflow_step s
          where s.founder_gate is not null and lower(s.founder_gate) <> 'none'
            and b.workflow_scope like '%' || s.workflow_id || '%')))
),
-- ------------------------------------------------------------------ business integrity
integrity(check_name, expected, actual) as (
  values
    -- W12 dispatch must sit behind quote readiness, an approved safe package and an approved
    -- supplier.  Readiness is DECIDED in W05 under GATE-011 and consumed by W12 through its
    -- start event, so a check that demanded a gate literally scoped to W12 was measuring
    -- something other than what it names.  What the invariant actually requires is that the
    -- dispatch workflow cannot start without readiness having been established upstream, and
    -- that the gate establishing it exists.  Both halves are asserted.
    ('integrity.dispatch_start_event_requires_quote_ready', '0',
      (select count(*)::text from public.phase_b_workflow
        where workflow_id = 'W12' and start_event !~* 'quote.?ready')),
    ('integrity.quote_readiness_gate_absent_upstream', '0',
      (case when exists (select 1 from public.phase_b_gate
                          where gate_name ~* 'quote.?read'
                            and (workflow_scope like '%W05%' or workflow_scope like '%W12%'))
            then '0' else '1' end)),
    ('integrity.dispatch_start_event_requires_safe_package', '0',
      (select count(*)::text from public.phase_b_workflow
        where workflow_id = 'W12' and start_event !~* 'supplier.?safe')),
    ('integrity.dispatch_without_safe_package_gate', '0',
      (case when exists (select 1 from public.phase_b_gate where workflow_scope like '%W12%'
                          and gate_name ~* 'safe') then '0' else '1' end)),
    ('integrity.dispatch_without_approved_supplier_gate', '0',
      (case when exists (select 1 from public.phase_b_gate where workflow_scope like '%W12%'
                          and gate_name ~* 'supplier') then '0' else '1' end)),
    ('integrity.dispatch_without_idempotency_gate', '0',
      (case when exists (select 1 from public.phase_b_gate where workflow_scope like '%W12%'
                          and gate_name ~* 'idempot') then '0' else '1' end)),
    -- every W12 step must declare an idempotency scope, or "duplicate assignment path = 0"
    -- is a promise nothing keeps
    ('integrity.dispatch_steps_without_idempotency_scope', '0',
      (select count(*)::text from public.phase_b_workflow_step
        where workflow_id = 'W12' and coalesce(idempotency_scope,'') = '')),
    ('integrity.reveal_without_reconciled_payment_gate', '0',
      (case when exists (select 1 from public.phase_b_gate where workflow_scope like '%W15%'
                          and (gate_name ~* 'payment|reveal')) then '0' else '1' end)),
    ('integrity.mutable_accepted_terms_record', '0',
      (select count(*)::text from public.phase_b_business_object
        where object_id ~* 'terms' and record_policy not in ('append_only','append_only_lifecycle','immutable'))),
    ('integrity.mutable_approved_safe_package', '0',
      (select count(*)::text from public.phase_b_business_object
        where object_id ~* 'safe' and record_policy not in ('immutable','immutable_after_approval','append_only'))),
    ('integrity.platform_rewrites_supplier_quotation', '0',
      (select count(*)::text from public.phase_b_business_object
        where object_id ~* 'quotation|quote' and mutation_rule ~* 'platform (may )?(rewrite|edit|alter)'))
),
-- ------------------------------------------------------------------- phase boundaries
boundaries(check_name, expected, actual) as (
  values
    ('phase_a.baseline_drift_rows', '0', (select count(*)::text from public.fn_phase_a_baseline_drift())),
    ('phase_a.organization_violations', '0',
      (select count(*)::text from public.fn_phase_a_organization_violations())),
    ('phase_b.crosswalk_rows_measured', 'gt0',
      (case when (select count(*) from public.phase_b_crosswalk) > 0 then 'gt0' else '0' end)),
    ('phase_b.crosswalk_unclassified', '0',
      (select count(*)::text from public.phase_b_crosswalk where coalesce(target_classification,'') = '')),
    -- Phase B activates nothing.  These read the live estate, not a Phase B table.
    -- the hold is an open circuit with open_until far in the future; 8 routes, all held.
    -- count(*)=0 would make bool_and(...) return null, which is not a pass, so the population
    -- is asserted separately rather than folded into the same expression.
    ('population.llm_routes', '8', (select count(*)::text from public.llm_route_health)),
    ('phase_b.openrouter_routes_still_held', 'true',
      (select case when bool_and(open_until > now()) then 'true' else 'false' end
         from public.llm_route_health)),
    ('phase_b.cron_jobs_created_by_phase_b', '0',
      (select count(*)::text from cron.job where jobname like 'phase_b%'))
)
select c.check_name, c.expected, c.actual,
       case when c.expected = 'gt0' then c.actual = 'gt0' else c.actual = c.expected end
from (
  select * from counts union all select * from owners union all select * from coverage
  union all select * from graph union all select * from handoffs union all select * from authority
  union all select * from integrity union all select * from boundaries
) c
order by 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_b_owner_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_resolved text;
begin
  if new.actor_kind = 'founder' then
    if new.accountable_role_id <> 'founder' then
      raise exception 'phase_b: actor_kind=founder requires accountable_role_id=founder (step %)', new.step_id;
    end if;
    return new;
  end if;

  if new.actor_kind = 'category_overlay' then
    -- overlays contribute to qualification, routing, document interpretation, supplier
    -- capability and quotation evaluation; they may never dispatch, approve a supplier,
    -- reveal identity, decide money or approve a release
    if new.workflow_id not in ('W05','W06','W07','W10','W14') then
      raise exception 'phase_b: category overlay cannot be accountable in % (step %)',
        new.workflow_id, new.step_id;
    end if;
    if new.step_type <> 'analysis' then
      raise exception 'phase_b: category overlay may own an analysis step only, not % (step %)',
        new.step_type, new.step_id;
    end if;
    return new;
  end if;

  v_resolved := public.fn_phase_b_resolve_role(new.accountable_role_id);
  if v_resolved is null then
    raise exception 'phase_b: step % is accountable to "%", which does not resolve to an active canonical role',
      new.step_id, new.accountable_role_id;
  end if;
  if v_resolved <> new.accountable_role_id then
    raise exception 'phase_b: step % stores alias "%"; store the canonical role_id "%" instead',
      new.step_id, new.accountable_role_id, v_resolved;
  end if;

  -- The founder is a legitimate independent reviewer and is not a row in org_role: W01's
  -- reviewer is the founder in the frozen Phase A ownership registry itself.  Refusing it here
  -- would have made the one review the founder actually performs unstorable.
  if new.independent_reviewer_role_id is not null
     and new.independent_reviewer_role_id <> 'founder' then
    v_resolved := public.fn_phase_b_resolve_role(new.independent_reviewer_role_id);
    if v_resolved is null then
      raise exception 'phase_b: step % has reviewer "%", which does not resolve to an active canonical role',
        new.step_id, new.independent_reviewer_role_id;
    end if;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_b_resolve_role(p_token text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select r.role_id
  from public.org_role r
  where r.status = 'active'
    and r.runtime_mode <> 'knowledge_overlay'
    and r.role_id = coalesce(
      (select role_id from public.org_role where role_id = p_token and status = 'active'),
      (select a.role_id from public.org_role_alias a where a.alias = p_token limit 1)
    )
  limit 1;
$function$


