CREATE OR REPLACE FUNCTION public.fn_phase_c_event_runtime_observation(p_event_id text)
 RETURNS TABLE(observation text, outbox_rows bigint, delivered_rows bigint, delivery_attempts bigint, first_seen timestamp with time zone, last_seen timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
           when count(*) filter (where o.status = 'delivered') > 0 then 'OBSERVED_DELIVERED'
           when count(*) > 0                                       then 'EMITTED_NOT_DELIVERED'
           else                                                         'NEVER_OBSERVED'
         end::text,
         count(*)::bigint,
         count(*) filter (where o.status = 'delivered')::bigint,
         (select count(*) from public.phase_c_event_delivery_attempt a
            join public.phase_c_event_outbox o2 on o2.outbox_id = a.outbox_id
           where o2.event_id = p_event_id)::bigint,
         min(o.created_at),
         max(o.created_at)
    from public.phase_c_event_outbox o
   where o.event_id = p_event_id;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_event_truth_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select 'stored_structural_status_disagrees_with_derived'::text,
         '0'::text,
         (select count(*)::text from public.v_phase_c_event_binding_state where structural_status_disagrees)
           || ' of ' || (select count(*)::text from public.phase_c_event_binding),
         (select count(*) from public.v_phase_c_event_binding_state where structural_status_disagrees) = 0
  union all
  select 'registry_only_event_presented_as_runtime_observed'::text,
         '0 — structurally impossible: runtime observation is derived, not stored'::text,
         '0 of ' || (select count(*)::text from public.phase_c_event_binding),
         true
  union all
  select 'structurally_connected'::text,
         'reported, never read as a runtime claim'::text,
         (select count(*)::text from public.v_phase_c_event_binding_state
           where structural_status_derived = 'CONNECTED')
           || ' of ' || (select count(*)::text from public.phase_c_event_binding),
         true
  union all
  select 'runtime_observed_at_least_once'::text,
         'reported; it rises as the runtime is released'::text,
         (select count(*)::text from public.v_phase_c_event_binding_state
           where runtime_observation <> 'NEVER_OBSERVED')
           || ' of ' || (select count(*)::text from public.phase_c_event_binding),
         true
  union all
  -- The one that would have caught the original defect if it had existed: an event the registry
  -- calls deferred, which is nevertheless running.
  --
  -- SCOPED TO THE CURRENT REGIME, AND THE HISTORY IS REPORTED ON ITS OWN LINE BELOW. On its first
  -- run this check fired at 1 of 60: EV-W06-COMPLETED, emitted and delivered once at
  -- 2026-08-16 23:15:23 — three minutes BEFORE the kernel epoch at 23:18:23. A pre-cutover emission
  -- by the runtime the kernel replaced is not a live contradiction, and counting it would hold this
  -- check red forever over a row nothing can now produce. Splitting the population by the epoch is
  -- the same discipline fn_kernel_system_trace_state already applies to cron executions.
  --
  -- last_seen, not first_seen: a binding that emitted before the cutover AND after it is a live
  -- contradiction and must still fail.
  select 'deferred_binding_that_is_actually_running'::text,
         '0 since the kernel epoch'::text,
         (select count(*)::text from public.v_phase_c_event_binding_state s
           where s.structural_status_derived = 'DEFERRED_RUNTIME_IMPLEMENTATION'
             and s.last_seen >= (select started_at from public.phase_c_kernel_epoch
                                  where epoch_id = 'S3_SYSTEM_EXECUTION_TRACING'))
           || ' of ' || (select count(*)::text from public.phase_c_event_binding
                          where connection_status = 'DEFERRED_RUNTIME_IMPLEMENTATION'),
         (select count(*) from public.v_phase_c_event_binding_state s
           where s.structural_status_derived = 'DEFERRED_RUNTIME_IMPLEMENTATION'
             and s.last_seen >= (select started_at from public.phase_c_kernel_epoch
                                  where epoch_id = 'S3_SYSTEM_EXECUTION_TRACING')) = 0
  union all
  select 'deferred_binding_that_ran_before_the_kernel_epoch'::text,
         'informational — historical, produced by the runtime the kernel replaced'::text,
         (select count(*)::text from public.v_phase_c_event_binding_state s
           where s.structural_status_derived = 'DEFERRED_RUNTIME_IMPLEMENTATION'
             and s.runtime_observation <> 'NEVER_OBSERVED'
             and s.last_seen < (select started_at from public.phase_c_kernel_epoch
                                 where epoch_id = 'S3_SYSTEM_EXECUTION_TRACING'))
           || ' of ' || (select count(*)::text from public.phase_c_event_binding
                          where connection_status = 'DEFERRED_RUNTIME_IMPLEMENTATION'),
         true;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_founder_approval_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- E40. This message was hard-coded to `public.phase_c_founder_approval` while the trigger sits on
  -- phase_c_frozen_subject as well, so a person hitting it was told the wrong table -- and then
  -- advised to "record a NEW row", which until this file was the one door standing open on that
  -- register. It names what it is actually protecting now.
  raise exception '% is append-only and its rows are permanent: % is refused. A founder approval and the frozen subjects it covers are the record that everything else is measured against, so they are never edited or deleted -- record a new row through a migration applied as the owner. (phase_c_approval_immutable)',
    TG_TABLE_NAME, TG_OP
    using errcode = '23514';
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_founder_approver_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.approved_by is null then
    return new;
  end if;

  if not exists (
        select 1 from public.phase_c_founder_identity fi
         where fi.active
           and lower(btrim(fi.identity)) = lower(btrim(new.approved_by))) then
    raise exception '%: approved_by % does not resolve to an active identity in public.phase_c_founder_identity. A governance record is approved by the founder or it is not approved. (pccr_approver_not_the_founder)',
      TG_TABLE_NAME, coalesce(nullif(btrim(new.approved_by),''), '(empty)')
      using errcode = '23514';
  end if;

  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_founder_auth_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select 'enabled_founder_identities_without_an_auth_subject'::text, '0'::text,
         (select count(*)::text from public.phase_c_founder_identity
           where active and kind = 'email' and auth_user_id is null),
         not exists (select 1 from public.phase_c_founder_identity
                      where active and kind = 'email' and auth_user_id is null)
  union all
  select 'require_founder_still_resolves_a_caller_supplied_string', '0',
         (select count(*)::text from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname = 'fn_phase_c_require_founder'
             and p.prosrc ~ 'f\.identity = lower\(btrim\(p_actor\)\)'),
         not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                      where n.nspname = 'public' and p.proname = 'fn_phase_c_require_founder'
                        and p.prosrc ~ 'f\.identity = lower\(btrim\(p_actor\)\)')
  union all
  select 'founder_bind_executable_by_anon_or_authenticated', '0',
         (select count(*)::text from information_schema.routine_privileges
           where routine_schema = 'public' and routine_name = 'fn_phase_c_founder_subject_bind'
             and grantee in ('anon','authenticated','PUBLIC')),
         not exists (select 1 from information_schema.routine_privileges
                      where routine_schema = 'public'
                        and routine_name = 'fn_phase_c_founder_subject_bind'
                        and grantee in ('anon','authenticated','PUBLIC'))
  union all
  select 'founder_auth_events_still_committed', '0',
         (select count(*)::text from public.phase_c_founder_auth_event),
         not exists (select 1 from public.phase_c_founder_auth_event);
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_founder_identity_human_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.active and new.kind <> 'email' then
    raise exception
      'phase_c_founder_identity: only an email identity may be active; % is kind %',
      new.identity, new.kind
      using errcode = '23514',
            hint = 'A build-mode or service identity must never be enabled as the founder. '
                || 'This is the defect the 16 Aug audit found (FAIL 1).';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_founder_subject_bind(p_subject uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id text; v_ev bigint;
begin
  if current_user in ('anon','authenticated') then
    raise exception 'fn_phase_c_founder_subject_bind: % may not bind a founder subject; this is the server path (pd_founder_bind_untrusted_caller)',
      current_user using errcode = '42501';
  end if;
  if p_subject is null then
    raise exception 'fn_phase_c_founder_subject_bind: a verified auth subject is required, and null is not one'
      using errcode = '28000';
  end if;

  select f.identity into v_id
    from public.phase_c_founder_identity f
   where f.auth_user_id = p_subject and f.active and f.kind = 'email';
  if v_id is null then
    raise exception 'not the founder: auth subject % does not resolve to an enabled founder identity', p_subject
      using errcode = '28000';
  end if;

  insert into public.phase_c_founder_auth_event
    (auth_subject, identity, route, txid, bound_by)
  values (p_subject, v_id, 'server_verified_subject', txid_current(), current_user)
  returning event_id into v_ev;

  perform set_config('app.phase_c_founder_auth_event', v_ev::text, true);
  return jsonb_build_object('ok', true, 'identity', v_id, 'event_id', v_ev,
    'note','transaction-local; the verifier requires this event to name the current txid');
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_freeze_amendment_approve(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  a          public.phase_c_freeze_amendment%rowtype;
  v_identity text;
  v_sub      uuid;
  v_route    text;
  v_ev       bigint;
  v_id       bigint;
  v_prior    text;
begin
  -- THE DOOR. Nothing below runs without a verified founder on this transaction: the resolver
  -- raises 28000 for a service_role connection, for a typed email, and for a bound event that
  -- belongs to some other transaction.
  v_identity := public.fn_phase_c_require_founder(null);

  -- Which route carried it. Re-derived here rather than returned by the resolver, because the row
  -- must record HOW the founder was authenticated and not merely that something said he was.
  begin v_sub := auth.uid(); exception when others then v_sub := null; end;
  if v_sub is not null then
    v_route := 'auth.uid()';
  else
    v_ev := nullif(btrim(current_setting('app.phase_c_founder_auth_event', true)),'')::bigint;
    select e.auth_subject into v_sub from public.phase_c_founder_auth_event e
     where e.event_id = v_ev and e.txid = txid_current();
    v_route := 'fn_phase_c_founder_subject_bind';
  end if;
  if v_sub is null then
    raise exception 'fn_phase_c_freeze_amendment_approve: the founder resolved to % and no auth subject can be named for the call. An approval that cannot say who authenticated is not a session approval. (pccr_approval_subject_unnameable)',
      v_identity using errcode = '28000';
  end if;

  -- ONE AMENDMENT PER CALL. The founder's instruction is that these are approved individually.
  if p_input ?| array['amendment_ids','amendments','change_request_refs'] then
    raise exception 'fn_phase_c_freeze_amendment_approve: this routine approves exactly one amendment per call. Bundling is what the founder refused: "Do not combine or rewrite the amendments." (pccr_approval_bundled)'
      using errcode = '22023';
  end if;
  v_id := nullif(btrim(coalesce(p_input->>'amendment_id','')),'')::bigint;
  if v_id is null then
    raise exception 'fn_phase_c_freeze_amendment_approve: amendment_id is required (pccr_approval_no_amendment)'
      using errcode = '22023';
  end if;

  select * into a from public.phase_c_freeze_amendment where amendment_id = v_id;
  if not found then
    raise exception 'fn_phase_c_freeze_amendment_approve: no amendment % (pccr_approval_unknown_amendment)', v_id
      using errcode = '23503';
  end if;

  -- THE APPROVAL NAMES WHAT IT APPROVES. A mistyped id lands on a different amendment silently
  -- unless the call also restates the change request, the subject and the digest being adopted.
  if coalesce(nullif(btrim(p_input->>'change_request_ref'),''),'') is distinct from a.change_request_ref
     or coalesce(nullif(btrim(p_input->>'subject'),''),'')          is distinct from a.subject
     or coalesce(nullif(btrim(p_input->>'new_digest'),''),'')       is distinct from a.new_digest then
    raise exception 'fn_phase_c_freeze_amendment_approve: amendment % is (%, %, new_digest %) and the call names (%, %, %). An approval must name the exact amendment it approves. (pccr_approval_names_a_different_amendment)',
      v_id, a.change_request_ref, a.subject, a.new_digest,
      coalesce(p_input->>'change_request_ref','(none)'), coalesce(p_input->>'subject','(none)'),
      coalesce(p_input->>'new_digest','(none)') using errcode = '22023';
  end if;

  if coalesce(p_input->>'amendment_table_digest','') !~ '^[0-9a-f]{64}$' then
    raise exception 'fn_phase_c_freeze_amendment_approve: amendment_table_digest must be the sha256 of the amendment tables the approval is based on; got %. (pccr_approval_no_document_digest)',
      coalesce(nullif(p_input->>'amendment_table_digest',''),'(none)') using errcode = '22023';
  end if;

  if (p_input->>'deployed_before_approval') is null then
    raise exception 'fn_phase_c_freeze_amendment_approve: deployed_before_approval must be stated true or false. Whether the code was already live when it was approved is a fact about this approval, not a detail to leave blank. (pccr_approval_deployment_order_unstated)'
      using errcode = '22023';
  end if;
  if (p_input->>'deployed_before_approval')::boolean
     and nullif(btrim(p_input->>'original_deployment_at'),'') is null then
    raise exception 'fn_phase_c_freeze_amendment_approve: amendment % is recorded as deployed before approval and the call names no original_deployment_at. A retrospective ratification that cannot say when the code shipped is not a record of anything. (pccr_approval_deployment_time_missing)',
      v_id using errcode = '22023';
  end if;

  -- ALREADY APPROVED THROUGH THIS DOOR: idempotent, and it does not restamp the time.
  if a.approval_basis = 'AUTHENTICATED_FOUNDER_SESSION' then
    if lower(a.approved_by) is distinct from lower(v_identity) then
      raise exception 'fn_phase_c_freeze_amendment_approve: amendment % is already approved in a verified session by % and % may not overwrite that record. (pccr_approval_would_overwrite_another_founder)',
        v_id, a.approved_by, v_identity using errcode = '23514';
    end if;
    return jsonb_build_object('ok', true, 'amendment_id', v_id, 'outcome','ALREADY_APPROVED',
      'approved_by', a.approved_by, 'approved_at', a.approved_at, 'approval_basis', a.approval_basis,
      'note','this door is idempotent and does not restamp an approval it has already recorded');
  end if;

  v_prior := coalesce(a.approval_basis, '(unapproved)');

  update public.phase_c_freeze_amendment
     set approved_by                      = v_identity,     -- THE VERIFIED IDENTITY, never the input
         approved_at                      = now(),
         approval_basis                   = 'AUTHENTICATED_FOUNDER_SESSION',
         approval_route                   = v_route,
         approval_auth_subject            = v_sub,
         approved_amendment_table_digest  = lower(btrim(p_input->>'amendment_table_digest')),
         deployed_before_approval         = (p_input->>'deployed_before_approval')::boolean,
         original_deployment_at           = nullif(btrim(p_input->>'original_deployment_at'),'')::timestamptz
   where amendment_id = v_id;

  return jsonb_build_object(
    'ok', true, 'amendment_id', v_id,
    'outcome', case when v_prior = 'WRITTEN_INSTRUCTION' then 'REAFFIRMED_IN_VERIFIED_SESSION'
                    else 'APPROVED_IN_VERIFIED_SESSION' end,
    'prior_approval_basis', v_prior,
    'change_request_ref', a.change_request_ref, 'subject', a.subject,
    'approved_by', v_identity, 'approval_route', v_route, 'approval_auth_subject', v_sub,
    'approval_type', case when (p_input->>'deployed_before_approval')::boolean
                          then 'retrospective founder ratification' else 'prospective approval' end,
    'original_deployment_at', nullif(btrim(p_input->>'original_deployment_at'),'')::timestamptz,
    'amendment_table_digest', lower(btrim(p_input->>'amendment_table_digest')));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_freeze_amendment_approver_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- An amendment awaiting approval is the normal state and is not this trigger's business. The
  -- board reports it; refusing it here would make an unapproved amendment unrecordable.
  if new.approved_by is null then
    return new;
  end if;

  if not exists (
        select 1 from public.phase_c_founder_identity fi
         where fi.active
           and lower(btrim(fi.identity)) = lower(btrim(new.approved_by))) then
    raise exception 'phase_c_freeze_amendment: approved_by % does not resolve to an active identity in public.phase_c_founder_identity. An amendment to a FROZEN Phase C contract is approved by the founder or it is not approved; a free-text name here cleared four of them and turned the freeze board green in one statement. (pccr_approver_not_the_founder)',
      coalesce(nullif(btrim(new.approved_by),''), '(empty)')
      using errcode = '23514';
  end if;

  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_freeze_drift()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
  with live as (
    select f.subject, f.object_identity, f.digest as frozen,
           case
             when f.object_kind = 'routine' then (
               select encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')
                 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
                where n.nspname='public'
                  and p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')'
                      = f.object_identity)
             when f.object_kind = 'table' and f.object_identity = 'public.phase_c_component' then (
               select encode(sha256(convert_to(string_agg(
                 c.component_id || '|' || coalesce(c.component_type,'') || '|' || coalesce(c.workflow_id,'')
                   || '|' || coalesce(c.step_id,'') || '|' || coalesce(c.accountable_role_id,'')
                   || '|' || coalesce(c.canonical_system_actor,'') || '|' || coalesce(c.authority_class,'')
                   || '|' || coalesce(c.trace_policy_id,'') || '|' || coalesce(c.activation_state,'')
                   || '|' || coalesce(c.classification,'') || '|' || coalesce(c.mutates_state::text,''),
                 chr(10) order by c.component_id),'UTF8')),'hex')
                 from public.phase_c_component c)
             else f.digest   -- repository_file subjects are checked in CI, not here; never silently green
           end as now_digest
      from public.phase_c_frozen_subject f
  ), judged as (
    -- D49. A live digest is undrifted when it matches the frozen baseline, OR when a recorded
    -- amendment carries BOTH the frozen baseline as its prior digest AND this body as its new one.
    -- An unrecorded edit is drift. An edit on top of an amendment is drift, because its prior digest
    -- no longer matches. Overwriting phase_c_frozen_subject.digest would have made both invisible.
    --
    -- E13 required the amendment to name a Phase C change request. E23 makes that reference a
    -- foreign key to public.phase_c_change_request, so an amendment can no longer point at a
    -- document nobody wrote.
    select l.*,
           exists (select 1 from public.phase_c_freeze_amendment a
                    where a.object_identity = l.object_identity
                      and a.prior_digest = l.frozen
                      and a.new_digest   = l.now_digest
                      and coalesce(btrim(a.change_request_ref),'') <> '') as amended
      from live l
  )
  select 'frozen_subjects_drifted', '0',
         count(*) filter (where now_digest is distinct from frozen and not amended)::text
           || ' of ' || count(*)::text,
         count(*) filter (where now_digest is distinct from frozen and not amended) = 0
    from judged
  union all
  select 'frozen_subjects_whose_object_no_longer_exists', '0',
         count(*) filter (where now_digest is null)::text || ' of ' || count(*)::text,
         count(*) filter (where now_digest is null) = 0
    from judged
  union all
  select 'frozen_subjects_changed_under_a_recorded_amendment', 'informational',
         count(*) filter (where amended)::text || ' of ' || count(*)::text, true
    from judged
  union all
  -- E23 REPLACES frozen_subjects_changed_with_no_change_request, WHICH COULD NOT FIRE.
  -- That row tested btrim(change_request_ref) = '' on a column that is NOT NULL and shape-checked,
  -- so it read 0 of 25 whatever anyone did. The R3 acceptance named it, correctly, as a green tick
  -- measuring nothing. What is checkable is whether the MECHANISM is still in place, and this row
  -- goes red the moment any of the three constraints is dropped.
  select 'change_request_reference_is_enforced', '3',
         -- The three are counted into ONE number. An earlier draft printed the two constraints as
         -- "2 of 3" and reported the NOT NULL separately, which read as a failing check sitting
         -- next to a green tick — the precise confusion this row exists to end.
         ((select count(*) from pg_constraint
            where conrelid = 'public.phase_c_freeze_amendment'::regclass
              and conname in ('phase_c_freeze_amendment_change_request_ref_shape',
                              'phase_c_freeze_amendment_change_request_fk'))
          + (select count(*) from information_schema.columns
              where table_schema='public' and table_name='phase_c_freeze_amendment'
                and column_name='change_request_ref' and is_nullable='NO'))::text
         || ' of 3 (shape check, foreign key to phase_c_change_request, NOT NULL)',
         (select count(*) from pg_constraint
           where conrelid = 'public.phase_c_freeze_amendment'::regclass
             and conname in ('phase_c_freeze_amendment_change_request_ref_shape',
                             'phase_c_freeze_amendment_change_request_fk')) = 2
         and (select count(*) from information_schema.columns
               where table_schema='public' and table_name='phase_c_freeze_amendment'
                 and column_name='change_request_ref' and is_nullable='NO') = 1
  union all
  select 'amendments_whose_change_request_is_unregistered', '0',
         (select count(*)::text from public.phase_c_freeze_amendment a
           where not exists (select 1 from public.phase_c_change_request cr
                              where cr.change_request_ref = a.change_request_ref))
         || ' of ' || (select count(*)::text from public.phase_c_freeze_amendment),
         not exists (select 1 from public.phase_c_freeze_amendment a
                      where not exists (select 1 from public.phase_c_change_request cr
                                         where cr.change_request_ref = a.change_request_ref))
  union all
  -- E34. THIS ROW'S ok WAS THE LITERAL true, AND IT READ 4 of 4.
  --
  -- Its own comment was candid - "Reported, never used. A change request that has been WRITTEN is
  -- not one that has been APPROVED" - and the consequence stood anyway: four amendments to frozen
  -- Phase C kernel contracts are live in production, unapproved, under a fully green board. The
  -- independent acceptance named it as the same species this estate keeps finding, a board row
  -- whose ok is a constant, and scored it LOW because it was disclosed. Disclosed in a comment is
  -- not disclosed on the board.
  --
  -- It is now a REAL RED, and it goes green the moment the founder signs. That is the right colour
  -- because the condition is genuinely unmet: an amendment to a frozen contract is not complete
  -- until the person who froze it has approved the change. Nothing here can clear it and nothing
  -- here should be able to - approved_by and approved_at are constrained to move as a pair, and a
  -- builder writing his own name into them would be the whole defect this row exists to surface.
  --
  -- 'expected' is now 0 rather than the word 'informational', so a reader comparing expected with
  -- actual sees the gap instead of a label that excuses it.
  -- E38. THIS ASKED `approved_by is null`, WHICH IS A QUESTION ABOUT A STORED STRING.
  -- An acceptance auditor added itself to public.phase_c_founder_identity as an email identity
  -- (service_role held INSERT), approved all four amendments with it, and DELETED the row again --
  -- leaving four approvals naming a string that resolves to nobody, and this row green. E38 revoked
  -- those write grants; this half asks the question fresh instead of trusting what was stored, so
  -- deleting the approver re-reddens the board in the same statement. It is also the backstop for
  -- an owner disabling the trigger: a guard can be turned off, a derivation cannot.
  select 'amendments_awaiting_founder_approval', '0',
         (select count(*) from public.phase_c_freeze_amendment a
           where a.approved_by is null
              or not exists (select 1 from public.phase_c_founder_identity fi
                              where fi.active
                                and lower(btrim(fi.identity)) = lower(btrim(a.approved_by))))::text
           || ' of ' || (select count(*) from public.phase_c_freeze_amendment)::text
           || ' await the founder (change requests named: '
           || (select coalesce(string_agg(distinct change_request_ref, ', '),'(none)')
                 from public.phase_c_freeze_amendment)
           -- E36. THIS SAID "Only he can clear this row." and nothing enforced it: approved_by was
           -- free text, and the acceptance auditor cleared all four with 'zz-r5-audit-not-the-founder'
           -- in one statement, turning the whole freeze board green. The trigger
           -- a10_freeze_amendment_approver_is_the_founder now refuses any approver that does not
           -- resolve to an ACTIVE row in public.phase_c_founder_identity. The row names the register
           -- rather than a person, because the register is what the database can check.
           || '). Cleared only while approved_by RESOLVES to one of the '
           || (select count(*)::text from public.phase_c_founder_identity where active)
           || ' active identities in public.phase_c_founder_identity -- asked here on every read, and enforced at write time by a10_freeze_amendment_approver_is_the_founder.',
         (select count(*) from public.phase_c_freeze_amendment a
           where a.approved_by is null
              or not exists (select 1 from public.phase_c_founder_identity fi
                              where fi.active
                                and lower(btrim(fi.identity)) = lower(btrim(a.approved_by)))) = 0
  union all
  -- F31. HOW THE APPROVAL WAS GIVEN, WHICH IS NOT THE SAME QUESTION AS WHETHER THERE IS ONE.
  --
  -- The row above asks whether approved_by resolves to an active founder identity. It cannot tell
  -- an approval the founder placed through a verified Supabase Auth session from one a migration
  -- wrote on the strength of an instruction he sent in a message. Both leave the same string in the
  -- same column. F23 wrote the second kind for PCCR-003 and said so in its own header; nothing on
  -- any board repeated it, so a reader saw "approved by the founder" and had no way to learn which.
  --
  -- This row is red while any approval rests on WRITTEN_INSTRUCTION. It is a disclosure, not an
  -- accusation: the instruction is real, quoted verbatim in the change request, and the design it
  -- approves is strictly harder to pass than the one it replaced. What is missing is his signature
  -- through the door F20 built and F21 granted, and that is his to give, not this repository's.
  select 'amendments_approved_on_written_instruction_only', '0',
         (select count(*) from public.phase_c_freeze_amendment
           where approval_basis = 'WRITTEN_INSTRUCTION')::text
         || ' of ' || (select count(*) from public.phase_c_freeze_amendment)::text
         || ' (change requests: '
         || (select coalesce(string_agg(distinct change_request_ref, ', '),'(none)')
               from public.phase_c_freeze_amendment where approval_basis = 'WRITTEN_INSTRUCTION')
         || '). An approval recorded from a written instruction is not a founder session. Cleared '
         || 'only by re-approval through a verified auth subject, which no migration can perform.',
         (select count(*) from public.phase_c_freeze_amendment
           where approval_basis = 'WRITTEN_INSTRUCTION') = 0
  union all
  select 'raw_frozen_subjects', 'informational',
         count(*)::text || ' of ' || count(*)::text, true
    from judged;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_gate_evaluate(p_gate_id text, p_evidence jsonb)
 RETURNS TABLE(passed boolean, reason text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare g public.phase_b_gate%rowtype; v_missing text;
begin
  select * into g from public.phase_b_gate where gate_id = p_gate_id;
  if not found then
    passed := false; reason := format('unknown gate %L — fail closed', p_gate_id); return next; return;
  end if;
  -- Deterministic evidence check: the gate declares what it requires; the caller supplies it.
  -- An absent evidence object is a refusal, never a pass.  pct(got, 0) returning 100 is the
  -- shape of defect this avoids: no evidence is not full evidence.
  if p_evidence is null or jsonb_typeof(p_evidence) <> 'object' or p_evidence = '{}'::jsonb then
    passed := false;
    reason := format('gate %s (%s) requires evidence and none was supplied', g.gate_id, g.gate_name);
    return next; return;
  end if;
  v_missing := coalesce((select string_agg(k, ', ')
                         from unnest(array['evidence_ref','actor_role_id']) k
                         where not (p_evidence ? k)), '');
  if v_missing <> '' then
    passed := false;
    reason := format('gate %s: evidence missing [%s]', g.gate_id, v_missing);
    return next; return;
  end if;
  if not public.fn_phase_c_actor_may_own(p_evidence->>'actor_role_id') then
    passed := false;
    reason := format('gate %s: actor %L does not resolve to an active canonical role',
                     g.gate_id, p_evidence->>'actor_role_id');
    return next; return;
  end if;
  passed := true;
  reason := format('gate %s (%s, %s) satisfied: %s', g.gate_id, g.gate_name, g.gate_type, g.pass_result);
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_gates_for_step(p_step_id text)
 RETURNS TABLE(gate_id text, gate_name text, gate_type text, workflow_scope text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select g.gate_id, g.gate_name, g.gate_type, g.workflow_scope
  from public.phase_b_workflow_step s
  join public.phase_b_gate g
    on g.workflow_scope = 'ALL'
    or s.workflow_id = any (string_to_array(replace(g.workflow_scope, ' ', ''), ';'))
  where s.step_id = p_step_id
  order by g.gate_id;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_handoff_decide(p_handoff_run_id bigint, p_decision text, p_actor text, p_ctx jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare hr public.phase_c_handoff_run%rowtype; v_actor text; v_trace bigint;
begin
  select * into hr from public.phase_c_handoff_run where handoff_run_id = p_handoff_run_id for update;
  if not found then return jsonb_build_object('ok', false, 'error','not_found'); end if;
  if hr.status <> 'open' then
    return jsonb_build_object('ok', false, 'error','already_decided', 'status', hr.status);
  end if;
  select role_id into v_actor from public.fn_phase_c_resolve_actor(p_actor);
  if v_actor is distinct from hr.receiving_role_id then
    return jsonb_build_object('ok', false, 'error','not_the_receiver',
      'receiver', hr.receiving_role_id, 'actor', coalesce(v_actor, p_actor));
  end if;
  if p_decision = 'reject'
     and (coalesce(p_ctx->>'reason','') = '' or coalesce(p_ctx->>'missing','') = '') then
    return jsonb_build_object('ok', false, 'error','rejection_must_be_specific',
      'message','A rejection must state the exact missing or invalid item and the return owner.');
  end if;

  update public.phase_c_handoff_run set
    status = case when p_decision = 'accept' then 'accepted' else 'rejected' end,
    rejection_reason = case when p_decision = 'accept' then '' else p_ctx->>'reason' end,
    missing_items = case when p_decision = 'accept' then '' else p_ctx->>'missing' end,
    return_owner_role_id = case when p_decision = 'accept' then return_owner_role_id
                                else coalesce(nullif(p_ctx->>'return_owner',''), return_owner_role_id, sending_role_id) end
  where handoff_run_id = p_handoff_run_id;

  v_trace := public.fn_phase_c_trace_write('TRACE-HANDOFF', jsonb_build_object(
    'subject_kind','handoff', 'subject_ref', p_handoff_run_id::text, 'run_id', hr.run_id,
    'actor_role_id', v_actor, 'state_before','open',
    'state_after', case when p_decision = 'accept' then 'accepted' else 'rejected' end,
    'status','sealed'));
  return jsonb_build_object('ok', true, 'handoff_run_id', p_handoff_run_id,
    'status', case when p_decision = 'accept' then 'accepted' else 'rejected' end,
    'accountable_now', (select accountable_until_accept_role_id from public.phase_c_handoff_run
                        where handoff_run_id = p_handoff_run_id),
    'trace_id', v_trace);
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_handoff_open(p_run_id bigint, p_handoff_id text, p_packet jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  h public.phase_b_handoff%rowtype;
  v_id bigint; v_trace bigint; v_hours numeric; v_due timestamptz;
  chk record;
begin
  select * into h from public.phase_b_handoff where handoff_id = p_handoff_id;
  if not found then
    return jsonb_build_object('ok', false, 'error','unknown_handoff', 'handoff_id', p_handoff_id);
  end if;
  select * into chk from public.fn_phase_c_handoff_packet_valid(p_handoff_id, p_packet);
  if not chk.valid then
    return jsonb_build_object('ok', false, 'error','incomplete_packet', 'missing', chk.missing,
      'return_owner', h.return_owner_role_id,
      'message','The sender keeps this. An incomplete packet does not become the receiver''s problem.');
  end if;

  -- The SLA target is prose ("1 minute", "4 business hours", "30 minutes when inputs are
  -- complete").  Parse the leading quantity AND its unit; taking the digits alone would turn
  -- "1 minute" into one hour and "5 minutes" into five, which is the wrong number twice over.
  select case
           when m[2] ilike 'minute%' then m[1]::numeric / 60.0
           when m[2] ilike 'day%'    then m[1]::numeric * 24.0
           when m[2] ilike 'week%'   then m[1]::numeric * 168.0
           else m[1]::numeric
         end
    into v_hours
  from public.phase_b_sla_policy sp,
       lateral regexp_match(sp.target, '(\d+)\s*(?:business\s+|calendar\s+)?(minute|hour|day|week)') m
  where sp.sla_policy_id = h.sla_policy_id;
  v_hours := coalesce(v_hours, 24);
  v_due := now() + make_interval(mins => greatest(1, round(v_hours * 60))::int);

  insert into public.phase_c_handoff_run
    (handoff_id, run_id, sending_role_id, receiving_role_id, business_object_id, object_version,
     packet_hash, requested_action, acceptance_criteria, return_owner_role_id, sla_policy_id,
     due_at, status, accountable_until_accept_role_id)
  values (p_handoff_id, p_run_id, h.sending_role_id, h.receiving_role_id,
          coalesce(p_packet->>'business_object_id',''),
          coalesce((p_packet->>'object_version')::bigint, 1),
          encode(sha256(convert_to(p_packet::text, 'UTF8')), 'hex'),
          coalesce(p_packet->>'requested_action',''), h.receiving_acceptance_criteria,
          h.return_owner_role_id, h.sla_policy_id, v_due, 'open', h.sending_role_id)
  returning handoff_run_id into v_id;
  if v_id is null then
    raise exception 'fn_phase_c_handoff_open wrote no row for %', p_handoff_id using errcode = '23502';
  end if;

  v_trace := public.fn_phase_c_trace_write('TRACE-HANDOFF', jsonb_build_object(
    'subject_kind','handoff', 'subject_ref', v_id::text, 'run_id', p_run_id,
    'actor_role_id', h.sending_role_id, 'state_before','', 'state_after','open',
    'output_hash', encode(sha256(convert_to(p_packet::text, 'UTF8')), 'hex'), 'status','open'));
  update public.phase_c_handoff_run set trace_id = v_trace where handoff_run_id = v_id;

  return jsonb_build_object('ok', true, 'handoff_run_id', v_id, 'sender', h.sending_role_id,
    'receiver', h.receiving_role_id, 'accountable_until_accept', h.sending_role_id,
    'sla_policy_id', h.sla_policy_id, 'sla_hours', v_hours, 'due_at', v_due, 'trace_id', v_trace);
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_handoff_overdue()
 RETURNS TABLE(handoff_run_id bigint, handoff_id text, sender text, receiver text, due_at timestamp with time zone, hours_late numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select h.handoff_run_id, h.handoff_id, h.sending_role_id, h.receiving_role_id, h.due_at,
         round(extract(epoch from (now() - h.due_at)) / 3600.0, 1)
  from public.phase_c_handoff_run h
  where h.status = 'open' and h.due_at is not null and h.due_at < now()
  order by h.due_at;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_handoff_packet_valid(p_handoff_id text, p_packet jsonb)
 RETURNS TABLE(valid boolean, missing text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare h public.phase_b_handoff%rowtype; v_missing text;
begin
  select * into h from public.phase_b_handoff where handoff_id = p_handoff_id;
  if not found then
    valid := false; missing := format('unknown handoff %L — fail closed', p_handoff_id); return next; return;
  end if;
  if p_packet is null or jsonb_typeof(p_packet) <> 'object' then
    valid := false; missing := 'no packet supplied'; return next; return;
  end if;
  v_missing := coalesce((select string_agg(k, ', ')
    from unnest(array['business_object_id','object_version','output','evidence_refs','requested_action']) k
    where not (p_packet ? k)), '');
  valid := (v_missing = '');
  missing := v_missing;
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_handoff_sender_retains()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.accountable_until_accept_role_id is distinct from new.sending_role_id then
      raise exception 'phase_c_handoff_run: the sender retains accountability until acceptance (got %, expected %)',
        new.accountable_until_accept_role_id, new.sending_role_id using errcode = '23514';
    end if;
    if not public.fn_phase_c_actor_may_own(new.sending_role_id)
       or not public.fn_phase_c_actor_may_own(new.receiving_role_id) then
      raise exception 'phase_c_handoff_run: sender % and receiver % must both resolve to active canonical roles',
        new.sending_role_id, new.receiving_role_id using errcode = '23514';
    end if;
    return new;
  end if;
  if old.status = 'open' and new.status = 'accepted' then
    new.accountable_until_accept_role_id := new.receiving_role_id;
    new.decided_at := now();
  elsif old.status = 'open' and new.status = 'rejected' then
    new.accountable_until_accept_role_id := coalesce(nullif(new.return_owner_role_id, ''), old.sending_role_id);
    new.decided_at := now();
  elsif old.status <> new.status and old.status <> 'open' then
    raise exception 'phase_c_handoff_run %: % is terminal; it cannot become %',
      old.handoff_run_id, old.status, new.status using errcode = '23514';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_historical_repair_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception
    'phase_c_historical_repair is append-only: % on repair_id % is refused',
    tg_op, coalesce(old.repair_id::text, '?')
    using errcode = '23514',
          hint = 'This table is the record of which historical records were defective, why, and '
              || 'what was done about them. A correction is a NEW row that names the repair_id it '
              || 'corrects in its evidence, written as its own migration — never an edit to the '
              || 'row that stated the original finding.';
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_invariants()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_bad bigint; v_pop bigint;
  v_deployed text[];
begin
  -- every routine any binding row names, so a binding cannot claim an undeployed function
  select array_agg(distinct p.proname) into v_deployed
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public' and p.proname like 'fn_phase_c%' or p.proname like 'fn_founder_command%';

  -- ---------------------------------------------------------------- frozen baseline
  check_name := 'phase_a_drift'; expected := '0';
  actual := (select count(*)::text from public.fn_phase_a_baseline_drift());
  ok := actual = expected; return next;

  check_name := 'phase_b_drift'; expected := '0';
  actual := (select count(*)::text from public.fn_phase_b_baseline_drift());
  ok := actual = expected; return next;

  check_name := 'phase_b_unresolved_errata'; expected := '0';
  actual := (select count(*)::text from public.fn_phase_b_effective_errata() where not resolved);
  ok := actual = expected; return next;

  check_name := 'active_departments';
  expected := (select counts->>'active_departments' from public.org_phase_baseline where phase='A');
  actual := (select count(*)::text from public.org_departments where active);
  ok := actual = expected; return next;

  check_name := 'canonical_roles';
  expected := (select counts->>'canonical_roles' from public.org_phase_baseline where phase='A');
  actual := (select count(*)::text from public.org_role where status='active' and runtime_mode <> 'knowledge_overlay');
  ok := actual = expected; return next;

  check_name := 'category_overlays';
  expected := (select counts->>'category_overlays' from public.org_phase_baseline where phase='A');
  actual := (select count(*)::text from public.org_role where status='active' and runtime_mode = 'knowledge_overlay');
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- binding coverage
  check_name := 'roles_bound';
  expected := (select count(*)::text from public.org_role where status='active' and runtime_mode <> 'knowledge_overlay');
  actual := (select count(*)::text from public.phase_c_role_binding where connection_status = 'CONNECTED');
  ok := actual = expected; return next;

  check_name := 'roles_without_binding'; expected := '0';
  actual := (select count(*)::text from public.org_role r
             where r.status='active' and r.runtime_mode <> 'knowledge_overlay'
               and not exists (select 1 from public.phase_c_role_binding b
                               where b.canonical_role_id = r.role_id
                                  or b.canonical_role_id in (select alias from public.org_role_alias a where a.role_id = r.role_id)));
  ok := actual = expected; return next;

  check_name := 'overlays_bound';
  expected := (select count(*)::text from public.org_role where status='active' and runtime_mode = 'knowledge_overlay');
  actual := (select count(*)::text from public.phase_c_overlay_binding where connection_status = 'CONNECTED');
  ok := actual = expected; return next;

  check_name := 'overlay_bindings_resolve'; expected := '0';
  actual := (select count(*)::text from public.phase_c_overlay_binding b
             where not exists (select 1 from public.org_role r
                               where r.role_id = b.live_role_id and r.status='active'
                                 and r.runtime_mode='knowledge_overlay'));
  ok := actual = expected; return next;

  check_name := 'workflows_bound';
  expected := (select count(*)::text from public.phase_b_workflow);
  actual := (select count(*)::text from public.phase_c_workflow_binding);
  ok := actual = expected; return next;

  check_name := 'workflows_without_binding'; expected := '0';
  actual := (select count(*)::text from public.phase_b_workflow w
             where not exists (select 1 from public.phase_c_workflow_binding b where b.workflow_id = w.workflow_id));
  ok := actual = expected; return next;

  check_name := 'steps_bound_or_classified';
  expected := (select count(*)::text from public.phase_b_workflow_step);
  actual := (select count(*)::text from public.phase_c_step_binding);
  ok := actual = expected; return next;

  check_name := 'steps_without_binding'; expected := '0';
  actual := (select count(*)::text from public.phase_b_workflow_step s
             where not exists (select 1 from public.phase_c_step_binding b where b.step_id = s.step_id));
  ok := actual = expected; return next;

  -- A deferral is only acceptable with an owner, a safe entry boundary and the Phase D work.
  check_name := 'deferred_steps_without_owner_or_action'; expected := '0';
  actual := (select count(*)::text from public.phase_c_step_binding
             where connection_status = 'DEFERRED_RUNTIME_IMPLEMENTATION'
               and (accountable_role_id = '' or canonical_runtime_handler = '' or phase_d_action = ''));
  ok := actual = expected; return next;

  -- "Resolves" here means the FROZEN Phase B rule, not the narrower "is a standing employee":
  -- exactly one of the 257 steps (W14-S05, an analysis step in W14) is owned by the
  -- relevant_category_overlay placeholder, which master spec §12 permits for an analysis step in
  -- W05/W06/W07/W10/W14.  fn_phase_c_step_owner_valid encodes that and nothing wider; the
  -- absolute "an overlay may never own a TASK" guard is separate and unchanged.
  check_name := 'step_owners_resolve'; expected := '0';
  actual := (select count(*)::text from public.phase_c_step_binding b
             where not public.fn_phase_c_step_owner_valid(b.step_id, b.accountable_role_id));
  ok := actual = expected; return next;

  check_name := 'steps_owned_by_overlay_outside_declared_scope'; expected := '0';
  actual := (select count(*)::text from public.phase_c_step_binding b
             join public.phase_b_workflow_step s on s.step_id = b.step_id
             where not public.fn_phase_c_actor_may_own(b.accountable_role_id)
               and not (s.step_type = 'analysis' and s.workflow_id in ('W05','W06','W07','W10','W14')));
  ok := actual = expected; return next;

  check_name := 'handoffs_bound';
  expected := (select count(*)::text from public.phase_b_handoff);
  actual := (select count(*)::text from public.phase_c_handoff_binding);
  ok := actual = expected; return next;

  check_name := 'handoffs_without_binding'; expected := '0';
  actual := (select count(*)::text from public.phase_b_handoff h
             where not exists (select 1 from public.phase_c_handoff_binding b where b.handoff_id = h.handoff_id));
  ok := actual = expected; return next;

  check_name := 'events_classified';
  expected := (select count(*)::text from public.phase_b_event);
  actual := (select count(*)::text from public.phase_c_event_binding);
  ok := actual = expected; return next;

  check_name := 'events_without_producer_or_consumer'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_binding
             where outbox_writer = '' or delivery_worker = '' or dedupe_key = '');
  ok := actual = expected; return next;

  check_name := 'gates_classified';
  expected := (select count(*)::text from public.phase_b_gate);
  actual := (select count(*)::text from public.phase_c_gate_binding);
  ok := actual = expected; return next;

  check_name := 'rules_classified';
  expected := (select count(*)::text from public.phase_b_business_rule);
  actual := (select count(*)::text from public.phase_c_rule_binding);
  ok := actual = expected; return next;

  -- Every routine a binding names must actually be deployed.  This is the check that stops a
  -- binding CSV from being a document: it re-reads pg_proc.
  check_name := 'bindings_naming_undeployed_routines'; expected := '0';
  actual := (
    with named as (
      select distinct (regexp_match(x, 'public\.(fn_[a-z0-9_]+)'))[1] as fn
      from (
        select gate_enforcer x from public.phase_c_step_binding
        union all select authority_enforcer from public.phase_c_step_binding
        union all select review_enforcer from public.phase_c_step_binding
        union all select event_emitter from public.phase_c_step_binding
        union all select handoff_writer from public.phase_c_step_binding
        union all select canonical_runtime_handler from public.phase_c_step_binding
        union all select resolver_path from public.phase_c_role_binding
        union all select task_receiver_path from public.phase_c_role_binding
        union all select authority_binding_path from public.phase_c_role_binding
        union all select review_binding_path from public.phase_c_role_binding
        union all select knowledge_scope_path from public.phase_c_role_binding
        union all select tool_policy_path from public.phase_c_role_binding
        union all select invocation_entrypoint from public.phase_c_overlay_binding
        union all select runtime_entrypoint from public.phase_c_workflow_binding
        union all select event_outbox_writer from public.phase_c_workflow_binding
        union all select runtime_writer from public.phase_c_handoff_binding
        union all select runtime_receiver from public.phase_c_handoff_binding
        union all select packet_schema_validator from public.phase_c_handoff_binding
        union all select sla_timer_handler from public.phase_c_handoff_binding
        union all select enforcement_function from public.phase_c_gate_binding
        union all select enforcement_function from public.phase_c_rule_binding
      ) s where x is not null
    )
    select count(*)::text from named
    where fn is not null
      and not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                      where n.nspname='public' and p.proname = named.fn));
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- runtime accountability
  check_name := 'components_inventoried'; expected := '>=1799';
  actual := (select count(*)::text from public.phase_c_component);
  ok := (select count(*) from public.phase_c_component) >= 1799; return next;

  check_name := 'active_state_changing_without_role'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where mutates_state and activation_state not in ('inactive','disabled')
               and accountable_role_id = '');
  ok := actual = expected; return next;

  check_name := 'active_state_changing_without_system_actor'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where mutates_state and activation_state not in ('inactive','disabled')
               and canonical_system_actor = '');
  ok := actual = expected; return next;

  check_name := 'active_state_changing_without_scope'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where mutates_state and activation_state not in ('inactive','disabled')
               and workflow_id = '');
  ok := actual = expected; return next;

  -- WAS: where classification = '' — the empty string, which no row has ever held, while 286 rows
  -- carried the literal 'NO_CALLER_UNCLASSIFIED' and 99 of those were active and state-changing.
  -- The check now measures the population gate 4 actually names.
  check_name := 'unclassified_components'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where mutates_state and activation_state not in ('inactive','disabled')
               and classification in ('', 'NO_CALLER_UNCLASSIFIED'));
  ok := actual = expected; return next;

  check_name := 'unclassified_edge_functions'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where component_type = 'edge_function'
               and activation_state not in ('inactive','disabled')
               and classification in ('', 'NO_CALLER_UNCLASSIFIED'));
  ok := actual = expected; return next;

  check_name := 'unclassified_db_functions_and_triggers'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where component_type in ('database_function','database_trigger') and classification = '');
  ok := actual = expected; return next;

  check_name := 'unclassified_cron_jobs'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where component_type = 'cron_job' and classification = '');
  ok := actual = expected; return next;

  check_name := 'generic_owner_used'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where accountable_role_id in ('Director','director','service_role','pg_cron','postgres','system','admin','code_runner','unknown',''));
  ok := actual = expected; return next;

  check_name := 'component_owners_resolve'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component c
             where not public.fn_phase_c_actor_may_own(c.accountable_role_id));
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- founder autonomy
  check_name := 'non_refund_founder_approvals'; expected := '0';
  actual := public.fn_phase_c_non_refund_founder_approvals()::text;
  ok := actual = expected; return next;

  check_name := 'action_classes_requiring_founder_approval'; expected := '1';
  actual := (select count(*)::text from public.phase_c_action_class where founder_approval_required);
  ok := actual = expected; return next;

  check_name := 'the_founder_approval_class_is_refund_decision'; expected := 'refund_decision';
  actual := coalesce((select action_class from public.phase_c_action_class where founder_approval_required), 'NONE');
  ok := actual = expected; return next;

  check_name := 'refund_executions_without_founder_decision'; expected := '0';
  actual := (select count(*)::text from public.phase_c_refund_decision
             where executed_at is not null and decision <> 'approved');
  ok := actual = expected; return next;

  check_name := 'refund_executor_equals_reconciler'; expected := '0';
  actual := (select count(*)::text from public.phase_c_refund_decision
             where executor_role_id = reconciler_role_id);
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- founder commands
  check_name := 'founder_messages_without_command'; expected := '0';
  actual := (select count(*)::text from public.founder_command_message m
             where not exists (select 1 from public.founder_command c where c.message_id = m.message_id));
  ok := actual = expected; return next;

  check_name := 'routed_commands_without_tasks'; expected := '0';
  actual := (select count(*)::text from public.founder_command c
             where c.state in ('tasks_created','in_progress','partially_blocked','completed')
               and c.intent_id not in ('CMD-STATUS','CMD-CANCEL','CMD-REPRIORITIZE','CMD-EXPLAIN')
               and c.outcome <> 'REFUND_APPROVAL'
               and not exists (select 1 from public.founder_command_task_link l where l.command_id = c.command_id));
  ok := actual = expected; return next;

  check_name := 'ambiguous_commands_that_created_tasks'; expected := '0';
  actual := (select count(*)::text from public.founder_command c
             where c.intent_id = 'AMBIGUOUS'
               and exists (select 1 from public.founder_command_task_link l where l.command_id = c.command_id));
  ok := actual = expected; return next;

  check_name := 'command_tasks_without_canonical_owner'; expected := '0';
  actual := (select count(*)::text from public.phase_c_task t
             where t.command_id is not null and not public.fn_phase_c_actor_may_own(t.accountable_role_id));
  ok := actual = expected; return next;

  check_name := 'command_plans_without_chief_of_staff_owner'; expected := '0';
  actual := (select count(*)::text from public.founder_command where command_owner_role_id <> 'chief_of_staff');
  ok := actual = expected; return next;

  check_name := 'duplicate_command_from_same_idempotency_key'; expected := '0';
  actual := (select coalesce(sum(n - 1), 0)::text from (
               select count(*) n from public.founder_command_message group by client_idempotency_key having count(*) > 1) s);
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- authority and review
  check_name := 'creator_reviewer_collisions'; expected := '0';
  actual := (select count(*)::text from public.phase_c_task
             where reviewer_required and not public.fn_phase_c_reviewer_independent(accountable_role_id, reviewer_role_id));
  ok := actual = expected; return next;

  check_name := 'step_bindings_with_self_review'; expected := '0';
  actual := (select count(*)::text from public.phase_c_step_binding
             where independent_reviewer_role_id <> ''
               and not public.fn_phase_c_reviewer_independent(accountable_role_id, independent_reviewer_role_id));
  ok := actual = expected; return next;

  check_name := 'overlay_owning_a_task'; expected := '0';
  actual := (select count(*)::text from public.phase_c_task t
             where (select kind from public.fn_phase_c_resolve_actor(t.accountable_role_id)) = 'overlay');
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- traces
  -- DENOMINATOR-AWARE. This reported 0 over a table that held 0 rows, which is not coverage.
  check_name := 'completed_commands_without_trace'; expected := '0 of >0';
  select count(*) filter (where trace_id is null), count(*) into v_bad, v_pop from public.founder_command where state in ('completed','cancelled','failed','refused','superseded');
  actual := v_bad::text || ' of ' || v_pop::text;
  ok := (v_bad = 0 and v_pop > 0); return next;
  -- (the shared tail below is skipped for this check)

  -- DENOMINATOR-AWARE. This reported 0 over a table that held 0 rows, which is not coverage.
  check_name := 'closed_tasks_without_trace'; expected := '0 of >0';
  select count(*) filter (where trace_id is null), count(*) into v_bad, v_pop from public.phase_c_task where closed_at is not null;
  actual := v_bad::text || ' of ' || v_pop::text;
  ok := (v_bad = 0 and v_pop > 0); return next;
  -- (the shared tail below is skipped for this check)

  -- DENOMINATOR-AWARE. This reported 0 over a table that held 0 rows, which is not coverage.
  check_name := 'completed_step_runs_without_trace'; expected := '0 of >0';
  select count(*) filter (where trace_id is null), count(*) into v_bad, v_pop from public.phase_c_workflow_step_run where state = 'completed';
  actual := v_bad::text || ' of ' || v_pop::text;
  ok := (v_bad = 0 and v_pop > 0); return next;
  -- (the shared tail below is skipped for this check)

  -- DENOMINATOR-AWARE. This reported 0 over a table that held 0 rows, which is not coverage.
  check_name := 'handoff_runs_without_trace'; expected := '0 of >0';
  select count(*) filter (where trace_id is null), count(*) into v_bad, v_pop from public.phase_c_handoff_run;
  actual := v_bad::text || ' of ' || v_pop::text;
  ok := (v_bad = 0 and v_pop > 0); return next;
  -- (the shared tail below is skipped for this check)

  -- ---------------------------------------------------------------- idempotency and delivery
  check_name := 'duplicate_outbox_dedupe_values'; expected := '0';
  actual := (select coalesce(sum(n - 1), 0)::text from (
               select count(*) n from public.phase_c_event_outbox group by event_id, dedupe_value having count(*) > 1) s);
  ok := actual = expected; return next;

  check_name := 'delivered_without_downstream_record'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_outbox o
             where o.status = 'delivered'
               and not exists (select 1 from public.phase_c_event_delivery_attempt a
                               where a.outbox_id = o.outbox_id and a.ok and a.downstream_ref <> ''));
  ok := actual = expected; return next;

  check_name := 'retry_erased_the_first_failure'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_outbox
             where attempts > 1 and status = 'delivered' and first_failure is null
               and exists (select 1 from public.phase_c_event_delivery_attempt a
                           where a.outbox_id = phase_c_event_outbox.outbox_id and not a.ok));
  ok := actual = expected; return next;

  check_name := 'duplicate_task_idempotency_keys'; expected := '0';
  actual := (select coalesce(sum(n - 1), 0)::text from (
               select count(*) n from public.phase_c_task group by idempotency_key having count(*) > 1) s);
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- cost
  check_name := 'paid_inference_since_phase_c_started'; expected := '0';
  -- WAS anchored to max(recorded_at) from phase_c_package_erratum: recording any new erratum moved
  -- the window forward and the check went green over whatever spend it had just stepped over, and
  -- emptying that table moved the anchor to now()-1 day. The start of Phase C is a fixed instant,
  -- and BOTH cost ledgers are counted, not one.
  actual := ((select count(*) from public.ai_cost_log where occurred_at > timestamptz '2026-08-15 02:51:36+00')
           + (select count(*) from public.llm_attempt where created_at  > timestamptz '2026-08-15 02:51:36+00'))::text;
  ok := actual = expected; return next;

  check_name := 'openrouter_routes_open'; expected := '0';
  actual := (select count(*)::text from public.llm_route_health where open_until <= now());
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- correction 2026-08-16
  -- Every one of these exists because the audit found the thing it measures, and found no check
  -- that could have seen it.

  check_name := 'tasks_without_trace'; expected := '0 of >0';
  select count(*) filter (where trace_id is null), count(*) into v_bad, v_pop from public.phase_c_task;
  actual := v_bad::text || ' of ' || v_pop::text;
  ok := (v_bad = 0 and v_pop > 0); return next;

  check_name := 'workflow_runs_without_trace'; expected := '0 of >0';
  select count(*) filter (where trace_id is null), count(*) into v_bad, v_pop
    from public.phase_c_workflow_run;
  actual := v_bad::text || ' of ' || v_pop::text;
  ok := (v_bad = 0 and v_pop > 0); return next;

  check_name := 'outbox_rows_without_trace'; expected := '0 of >0';
  select count(*) filter (where trace_id is null), count(*) into v_bad, v_pop
    from public.phase_c_event_outbox;
  actual := v_bad::text || ' of ' || v_pop::text;
  ok := (v_bad = 0 and v_pop > 0); return next;

  -- A command whose root trace describes a different moment than the command itself.
  check_name := 'commands_ahead_of_their_trace'; expected := '0';
  actual := (select count(*)::text from public.founder_command c
             join public.phase_c_trace t on t.trace_id = c.trace_id
             where t.state_after is distinct from c.state);
  ok := actual = expected; return next;

  -- The founder-command event must name the workflow the command actually selected.
  -- `superseded` rows are excluded because that status IS the finding: three rows emitted before
  -- the fix are quarantined there, unreachable by the claim (which takes only pending/retry_wait)
  -- and carrying the reason on the row. The companion check below makes that quarantine cost
  -- something, so this exclusion cannot become a hiding place.
  check_name := 'outbox_events_naming_another_workflow'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_outbox o
             where o.payload ? 'command_id' and o.status <> 'superseded'
               and not exists (select 1 from public.founder_command_workflow_link l2
                               where l2.command_id = (o.payload->>'command_id')::bigint
                                 and l2.workflow_id = o.workflow_id));
  ok := actual = expected; return next;

  check_name := 'outbox_superseded_without_a_stated_reason'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_outbox
             where status = 'superseded' and coalesce(btrim(last_error),'') = '');
  ok := actual = expected; return next;

  -- The queue has to have been drained by something, at least once.
  check_name := 'outbox_delivery_attempts_exist'; expected := '>0 when the outbox is non-empty';
  select count(*) into v_pop from public.phase_c_event_outbox;
  select count(*) into v_bad from public.phase_c_event_delivery_attempt;
  actual := v_bad::text || ' attempt(s) for ' || v_pop::text || ' outbox row(s)';
  ok := (v_pop = 0 or v_bad > 0); return next;

  check_name := 'outbox_rows_stuck_pending_over_an_hour'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_outbox
             where status = 'pending' and created_at < now() - interval '1 hour');
  ok := actual = expected; return next;

  check_name := 'outbox_dead_letter'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_outbox where status = 'dead_letter');
  ok := actual = expected; return next;

  -- An event binding may only claim CONNECTED when the derivation agrees.
  check_name := 'event_bindings_claiming_more_than_the_legs_support'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_binding b
             where b.connection_status
                   is distinct from (select status from public.fn_phase_c_event_binding_status(b.event_id)));
  ok := actual = expected; return next;

  check_name := 'active_state_changing_without_authority'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where mutates_state and activation_state not in ('inactive','disabled')
               and coalesce(authority_class,'') = '');
  ok := actual = expected; return next;

  check_name := 'active_state_changing_without_trace_policy'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where mutates_state and activation_state not in ('inactive','disabled')
               and coalesce(trace_policy_id,'') = '');
  ok := actual = expected; return next;

  -- A clarification the founder can never close was the seventh audit failure.
  check_name := 'clarification_required_has_an_exit'; expected := '2';
  actual := (select count(*)::text from public.phase_c_command_transition
             where from_state = 'clarification_required');
  ok := actual = expected; return next;

  return;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_kernel_epoch_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception
    'phase_c_kernel_epoch is append-only: % on epoch % refused. The instant that separates new '
    'work from historical work is not allowed to move — a window that follows its own newest row '
    'reports green over the period it just stepped across.',
    tg_op, coalesce(old.epoch_id, new.epoch_id)
    using errcode = '23514';
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_knowledge_scope(p_role text, p_workflow text, p_category text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id text; r public.org_role%rowtype; v_overlay text; v_missing text[] := '{}';
begin
  select role_id into v_id from public.fn_phase_c_resolve_actor(p_role);
  if v_id is null then
    return jsonb_build_object('ok', false, 'error','unresolved_identity', 'token', p_role);
  end if;
  select * into r from public.org_role where role_id = v_id;
  if p_workflow is not null and not exists (select 1 from public.phase_b_workflow where workflow_id = p_workflow) then
    v_missing := v_missing || ('unknown_workflow:' || p_workflow);
  end if;
  if p_category is not null then
    select role_id into v_overlay from public.fn_phase_c_resolve_actor(p_category);
    if v_overlay is null then v_missing := v_missing || ('unknown_category_overlay:' || p_category); end if;
  end if;
  if coalesce(array_length(r.knowledge_scopes, 1), 0) = 0 then
    v_missing := v_missing || ('role_has_no_declared_knowledge_scope:' || v_id);
  end if;
  return jsonb_build_object(
    'ok', cardinality(v_missing) = 0, 'role_id', v_id, 'department_id', r.primary_department_id,
    'workflow_id', p_workflow, 'category_overlay', v_overlay,
    'company_core_scopes', jsonb_build_array('company_policy','founder_boundaries','authority_matrix'),
    'department_scopes', jsonb_build_array('dept:' || r.primary_department_id),
    'role_scopes', to_jsonb(coalesce(r.knowledge_scopes, '{}')),
    'category_scopes', case when v_overlay is null then '[]'::jsonb else jsonb_build_array('overlay:' || v_overlay) end,
    'exclusions', jsonb_build_array('other_departments_private_scopes','v3_certification_answer_keys'),
    'missing_or_orphan', to_jsonb(v_missing),
    'retrieval_performed', false,
    'note', 'Phase C connects the scope interface only. No embedding or model call is made here.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_lifecycle_event(p_workflow_id text, p_lifecycle text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select e.event_id
    from public.phase_b_event e
   where e.workflow_id = nullif(btrim(coalesce(p_workflow_id, '')), '')
     and e.event_name like '%.' || lower(btrim(coalesce(p_lifecycle, '')))
   order by e.event_id
   limit 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_no_new_founder_approval_path()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception
    'Phase C founder autonomy: % is not an approval path any more. The founder receives exactly one routine manual approval, a specific refund decision. Route this to the internal authority gate (fn_phase_c_authority_check) instead.',
    tg_table_name using errcode = '23514';
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_non_refund_founder_approvals()
 RETURNS bigint
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select (select count(*) from public.founder_approval_request
           where action_class <> 'refund_decision' and state = 'pending')
       + (select count(*) from public.founder_release_approval where approved_at is null)
