CREATE OR REPLACE FUNCTION public.run_health_check()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare issues text[] := '{}'; stuck int; failed int; dirty_stuck boolean; inq int; q int; pend int; sms_stuck int; alert_recent boolean;
begin
  select count(*) into stuck from public.notifications
    where coalesce(status,'queued')='queued' and coalesce(channel,'email')<>'sms' and created_at < now()-interval '60 minutes';
  select count(*) into failed from public.notifications where status='failed' and created_at > now()-interval '24 hours';
  select count(*) into sms_stuck from public.notifications where channel='sms' and coalesce(status,'queued')='queued' and created_at < now()-interval '30 minutes';
  select (dirty and coalesce(last_deploy, '2000-01-01') < now()-interval '20 minutes') into dirty_stuck from public.deploy_state where id=1;
  select count(*) into inq from public.inquiries where created_at > now()-interval '24 hours';
  select count(*) into q from public.quotes where created_at > now()-interval '24 hours';
  select count(*) into pend from public.transactions where refund_status='requested';

  -- The ::text casts are load-bearing. `text[] || 'a bare literal'` resolves to anyarray||anyarray
  -- because an unadorned literal is type `unknown`, so Postgres parses the sentence as an array
  -- literal and raises 22P02. The sibling lines survived only because concatenating an int types
  -- the expression as text. 78 of 336 runs died here in the week to 4 Aug 2026 - the monitor
  -- crashed precisely when it had something to report, and took the other checks down with it.
  if stuck > 0 then issues := issues || ('Email queue stuck: '||stuck||' email(s) queued >1h — the email cron / Resend may be down.')::text; end if;
  if failed > 25 then issues := issues || ('High email failures: '||failed||' failed in 24h — check Resend domain auth.')::text; end if;
  -- only flagged while a deployer is actually scheduled; both deploy jobs are held disabled, so
  -- dirty can never clear and an ungated check would alert every 30 minutes about a decision.
  if coalesce(dirty_stuck,false)
     and exists (select 1 from cron.job where jobname in ('auto_deploy','site_autodeploy') and active) then
     issues := issues || ('Auto-deploy stuck: a page change has not deployed in 20+ min — check the Vercel token / cron.')::text; end if;
  -- sms only flagged if a sender is configured (else it is expected to sit)
  if sms_stuck > 0 and exists (select 1 from public.app_secrets where key='twilio_account_sid' and value is not null and value<>'') then
     issues := issues || ('SMS queue stuck: '||sms_stuck||' SMS queued >30min.')::text; end if;

  update public.health_state set last_run=now(), last_status=(case when array_length(issues,1) is null then 'ok' else 'issues' end) where id=1;
  select (last_alert_at > now()-interval '6 hours') into alert_recent from public.health_state where id=1;

  if array_length(issues,1) is not null and not coalesce(alert_recent,false) then
    insert into public.notifications(type,to_email,to_role,subject,body,status)
    select 'health_alert', trim(split_part(value,',',1)), 'admin', 'QuotesDone system health alert',
      'Automated check found issue(s):'||chr(10)||'- '||array_to_string(issues, chr(10)||'- ')||chr(10)||chr(10)||
      'Last 24h: '||inq||' inquiries, '||q||' quotes. Pending refund requests: '||pend||'.'||chr(10)||
      'Open the admin dashboard to investigate.', 'queued'
    from public.app_secrets where key='admin_emails';
    update public.health_state set last_alert_at=now() where id=1;
  end if;

  return json_build_object('ok',true,'status',(case when array_length(issues,1) is null then 'ok' else 'issues' end),'issues',to_jsonb(issues),'stuck_emails',stuck,'failed_24h',failed,'inq_24h',inq,'q_24h',q,'pending_refunds',pend);
end $function$


CREATE OR REPLACE FUNCTION public.run_no_quote_nudges()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int := 0; cemail text;
begin
  for r in
    select i.id, i.customer_id, i.summary, i.category from public.inquiries i
    where i.status='sent' and i.created_at < now() - interval '12 hours'
      and coalesce(i.no_quote_notified,false)=false
      and not exists (select 1 from public.quotes q where q.inquiry_id=i.id)
  loop
    select email into cemail from public.customers where id=r.customer_id;
    if cemail is not null then
      insert into public.notifications(type,to_email,to_role,inquiry_id,subject,body,status)
      values('no_quotes_yet', cemail,'customer', r.id,
        'We are still sourcing quotes for your request',
        'Thanks for your patience — no quote has come in yet for '||coalesce(r.summary,r.category)||'. Suppliers are still reviewing it. You can add detail or widen the request in the app, and we will email you the moment a quote arrives.','queued');
    end if;
    update public.inquiries set no_quote_notified=true where id=r.id;
    n := n+1;
  end loop;
  return n;
end $function$


CREATE OR REPLACE FUNCTION public.run_pending_digest()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s text;
begin
  select value into s from public.app_secrets where key='cred_db_internal';
  perform net.http_post(
    url := 'https://' || public.qd_project_ref() || '.supabase.co/functions/v1/pending_digest',
    headers := '{"Content-Type":"application/json"}'::jsonb,
    body := jsonb_build_object('__secret', s)
  );
end$function$


CREATE OR REPLACE FUNCTION public.run_reveal_nudges()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int := 0; cemail text; supemail text; comp text;
begin
  for r in
    select t.inquiry_id, t.supplier_id, t.customer_id
    from public.transactions t
    where t.revealed_at is not null
      and t.revealed_at < now() - interval '24 hours'
      and coalesce(t.refund_status,'') = 'window_open'
      and not exists (select 1 from public.messages m where m.inquiry_id=t.inquiry_id and m.supplier_id=t.supplier_id and m.sender='supplier')
      and not exists (select 1 from public.notifications x where x.type='reveal_nudge' and x.inquiry_id=t.inquiry_id)
  loop
    select email into cemail from public.customers where id=r.customer_id;
    select company_name, claimed_by into comp, supemail from public.leads where id=r.supplier_id;
    if cemail is not null then
      insert into public.notifications(type,to_email,to_role,inquiry_id,subject,body,status)
      values('reveal_nudge', cemail,'customer', r.inquiry_id,
        coalesce(comp,'Your supplier')||' has not replied yet',
        'It has been 24 hours and '||coalesce(comp,'the supplier')||' has not responded in the app. Try messaging again — or open the request and Report an issue to request a reveal-fee refund (within 72 hours of reveal).','queued');
    end if;
    if supemail is not null then
      insert into public.notifications(type,to_email,to_role,inquiry_id,subject,body,status)
      values('reveal_nudge_sup', supemail,'supplier', r.inquiry_id,
        'A customer is waiting for your reply',
        'A customer unlocked your quote on QuotesDone and is waiting to hear from you. Please log in and reply in the app to win the job.','queued');
    end if;
    n := n + 1;
  end loop;
  return n;
end $function$


CREATE OR REPLACE FUNCTION public.run_rfq_clarify(p_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; lbl text; miss_labels text[]; body text; subject text; n int:=0; sample jsonb:='[]'::jsonb; co text;
begin
  for r in
    select i.id, i.summary, i.completeness, c.email cust_email, c.full_name
    from public.inquiries i join public.customers c on c.id=i.customer_id
    where coalesce(i.rfq_ready,false)=false
      and coalesce(i.status,'') not in ('completed','accepted','closed','cancelled','lost')
      and i.created_at > now()-interval '30 days'
      and c.email is not null and c.email <> ''
      and jsonb_array_length(coalesce(i.completeness->'missing','[]'::jsonb)) > 0
      and not exists (select 1 from public.notifications nz where nz.type='inquiry_incomplete'
                        and nz.inquiry_id=i.id and nz.created_at > now()-interval '2 days')
    limit 200
  loop
    miss_labels := '{}';
    for lbl in select jsonb_array_elements_text(r.completeness->'missing') loop
      miss_labels := array_append(miss_labels, case lbl
        when 'category' then 'the type of service / category you need'
        when 'emirate' then 'which emirate the work is in'
        when 'scope_detail' then 'a clear description of the work (scope)'
        when 'scope_type' then 'whether it is a single trade or a full / turnkey job'
        when 'budget' then 'your budget or budget range'
        when 'supporting_detail' then 'supporting details — the trades involved, a drawing, or a bill of quantities (BOQ)'
        else lbl end);
    end loop;
    n := n+1;
    if jsonb_array_length(sample) < 10 then
      sample := sample || jsonb_build_object('inquiry_id',r.id,'to',r.cust_email,'missing',to_jsonb(miss_labels));
    end if;
    if not p_dry_run then
      co := coalesce(nullif(split_part(coalesce(r.full_name,''),' ',1),''),'there');
      subject := 'A few details needed to get you quotes — QuotesDone';
      body := 'Hi '||co||','||E'\n\n'||'Thanks for your request'||coalesce(' ('||left(r.summary,80)||')','')
        ||'. Before we can send it to suppliers and collect quotes, we need a little more information:'||E'\n\n'
        ||'• '||array_to_string(miss_labels, E'\n• ')||E'\n\n'
        ||'Please open your request on QuotesDone and add these details so we can match you to the right suppliers:'||E'\n'
        ||'https://quotesdone.com/app/'||E'\n\n'||'As soon as it is complete we will start collecting quotes for you. Thank you!';
      insert into public.notifications(type,to_email,to_role,inquiry_id,channel,subject,body,status)
        values('inquiry_incomplete', r.cust_email, 'customer', r.id, 'email', subject, body, 'queued');
    end if;
  end loop;
  return jsonb_build_object('ok',true,'dry_run',p_dry_run,'to_notify',n,'sample',sample);
end $function$


CREATE OR REPLACE FUNCTION public.run_site_autodeploy()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp', 'net'
AS $function$
declare s text; d boolean; lastdep timestamptz; ak text;
begin
  select dirty, last_deploy_at into d, lastdep from public.site_publish_state where id=1;
  if not coalesce(d,false) then return; end if;
  if lastdep is not null and now()-lastdep < interval '50 seconds' then return; end if;
  select value into s from public.app_secrets where key='cred_db_internal';
  select value into ak from public.app_secrets where key='anon_key';
  if s is null then return; end if;
  update public.site_publish_state set dirty=false, last_deploy_at=now() where id=1;
  update public.deploy_state set dirty=false, last_deploy=now(), last_status='triggered' where id=1;
  perform net.http_post(
    url := 'https://' || public.qd_project_ref() || '.supabase.co/functions/v1/site_deploy',
    body := jsonb_build_object('__secret', s),
    headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||ak),
    timeout_milliseconds := 150000
  );
end$function$


CREATE OR REPLACE FUNCTION public.scrub_inquiry_contacts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare changed boolean := false; v_name text;
begin
  new.summary_masked      := public.mask_contacts(new.summary);
  new.raw_input_masked    := public.mask_contacts(new.raw_input);
  new.budget_masked       := public.mask_contacts(new.budget);
  new.spec_masked         := public.mask_contacts_jsonb(new.spec);
  new.boq_masked          := public.mask_contacts_jsonb(new.boq);
  new.completeness_masked := public.mask_contacts_jsonb(new.completeness);

  if new.customer_id is not null then
    begin
      select nullif(btrim(c.full_name),'') into v_name from public.customers c where c.id = new.customer_id;
    exception when others then v_name := null; end;
    if v_name is not null then
      new.summary_masked   := public.mask_name(new.summary_masked,   v_name);
      new.raw_input_masked := public.mask_name(new.raw_input_masked, v_name);
      new.budget_masked    := public.mask_name(new.budget_masked,    v_name);
    end if;
  end if;

  changed := (new.summary_masked      is distinct from new.summary)
          or (new.raw_input_masked    is distinct from new.raw_input)
          or (new.budget_masked       is distinct from new.budget)
          or (new.spec_masked         is distinct from new.spec)
          or (new.boq_masked          is distinct from new.boq)
          or (new.completeness_masked is distinct from new.completeness);

  if changed then
    begin
      insert into public.founder_alerts(level, event, detail, channel)
      values ('warn', 'inquiry_contact_masked',
              'Masked customer contact details in the supplier-facing copy of inquiry '||coalesce(new.id::text,'?')||' from customer '||coalesce(new.customer_id::text,'?')||'.',
              'system');
    exception when others then null; end;
  end if;
  return new;
end;
$function$


CREATE OR REPLACE FUNCTION public.scrub_quote_contacts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare changed boolean := false;
begin
  if new.notes         is distinct from public.mask_contacts(new.notes)         then new.notes         := public.mask_contacts(new.notes);         changed := true; end if;
  if new.scope         is distinct from public.mask_contacts(new.scope)         then new.scope         := public.mask_contacts(new.scope);         changed := true; end if;
  if new.conditions    is distinct from public.mask_contacts(new.conditions)    then new.conditions    := public.mask_contacts(new.conditions);    changed := true; end if;
  if new.exclusions    is distinct from public.mask_contacts(new.exclusions)    then new.exclusions    := public.mask_contacts(new.exclusions);    changed := true; end if;
  if new.payment_terms is distinct from public.mask_contacts(new.payment_terms) then new.payment_terms := public.mask_contacts(new.payment_terms); changed := true; end if;
  if new.warranty      is distinct from public.mask_contacts(new.warranty)      then new.warranty      := public.mask_contacts(new.warranty);      changed := true; end if;
  if new.lead_time     is distinct from public.mask_contacts(new.lead_time)     then new.lead_time     := public.mask_contacts(new.lead_time);     changed := true; end if;
  if new.validity      is distinct from public.mask_contacts(new.validity)      then new.validity      := public.mask_contacts(new.validity);      changed := true; end if;
  if changed then
    begin
      insert into public.founder_alerts(level, event, detail, channel)
      values ('warn', 'quote_contact_masked',
              'Masked off-platform contact details in quote for inquiry '||coalesce(new.inquiry_id::text,'?')||' from supplier '||coalesce(new.supplier_id::text,'?')||'.',
              'system');
    exception when others then null; end;
  end if;
  return new;
end;
$function$


CREATE OR REPLACE FUNCTION public.sec_incident(p_sig text, p_cond boolean, p_sev text, p_title text, p_reco text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if p_cond and not exists (select 1 from agent_actions where kind='security_incident' and detail->>'signal'=p_sig and status in ('pending','needs_review')) then
    insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id)
    values ('security_ai','security_incident','pending',p_sev,p_title,p_reco,jsonb_build_object('signal',p_sig),'security',p_sig);
  end if;
end $function$


CREATE OR REPLACE FUNCTION public.trg_action_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare attrs jsonb; action text; esc jsonb; authz jsonb; blocked boolean:=false; reasons text[]:='{}'; amt numeric;
        v_sources jsonb := '[]'::jsonb; v_dl_id bigint;
        v_taken text; v_other text; v_why text; v_alts jsonb;
        v_kb_q text; v_kb jsonb; v_kb_cat text;
begin
  -- build context defensively (detail may be jsonb or text)
  begin
    attrs := case when jsonb_typeof(to_jsonb(NEW.detail)) = 'object' then to_jsonb(NEW.detail) else '{}'::jsonb end;
  exception when others then attrs := '{}'::jsonb; end;
  begin amt := nullif(attrs->>'amount_aed','')::numeric; if amt is null then amt := nullif(attrs->>'amount','')::numeric; end if; exception when others then amt := null; end;
  -- 'actor' IS PART OF THE CONTEXT, NOT JUST OF THE LEDGER ROW. NEW.agent was written to
  -- decision_log.actor and withheld from fn_should_escalate, so the router had nobody to route
  -- FROM and every one of these rows carried the same company-wide addressee. With it the
  -- escalation travels up the escalating employee's own reporting line.
  attrs := attrs || jsonb_build_object('amount_aed', amt, 'text', lower(coalesce(NEW.title,'')||' '||coalesce(NEW.recommendation,'')),
                                       'category', coalesce(attrs->>'category',''), 'moves_money', (lower(coalesce(NEW.kind,'')) ~ '(refund|payout|charge|payment|transfer)'),
                                       'actor', coalesce(NEW.agent,'agent'),
                                       -- KIND, FOR THE SAME REASON ACTOR IS HERE. fn_should_escalate
                                       -- has a rule that only makes sense for actions that ACT, and
                                       -- it could not tell a strategy from a handoff because the one
                                       -- field that says which is which was never passed.
                                       'kind', lower(coalesce(NEW.kind,'')));
  -- map action kind to an RBAC action
  action := case
    when lower(coalesce(NEW.kind,'')) ~ 'refund' then 'issue_refund'
    when lower(coalesce(NEW.kind,'')) ~ 'approve.*suppl|suppl.*approve|kyc' then 'approve_supplier'
    when lower(coalesce(NEW.kind,'')) ~ 'price|fee|commission' then 'edit_pricing'
    when lower(coalesce(NEW.kind,'')) ~ 'publish|post|content|blog|campaign' then 'publish_content'
    when lower(coalesce(NEW.kind,'')) ~ 'message|email|notify|send' then 'send_message'
    else 'run_agent_action' end;

  begin
    esc  := public.fn_should_escalate(attrs);
    authz:= public.fn_authorize(coalesce(NEW.agent,'agent'), action, attrs);
    if (esc->>'escalate')::boolean then blocked:=true; reasons := reasons || array(select jsonb_array_elements_text(coalesce(esc->'reasons','[]'))); end if;
    if not (authz->>'allowed')::boolean then blocked:=true; reasons := array_append(reasons, authz->>'reason'); end if;
  exception when others then blocked:=true; reasons := array_append(reasons,'gate error — held for review: '||sqlerrm); end;

  -- WHAT THIS DECISION WAS TAKEN ON. Each element is a retrieval that actually returned: if the
  -- call above raised, the variable is still NULL, nothing is appended, and the ledger row says so.
  if esc is not null then
    v_sources := v_sources || jsonb_build_array(jsonb_build_object(
      'kind', 'policy_check', 'ref', 'fn_should_escalate', 'result', esc));
  end if;
  if authz is not null then
    v_sources := v_sources || jsonb_build_array(jsonb_build_object(
      'kind', 'authority_check', 'ref', 'fn_authorize', 'result', authz));
  end if;

  -- THE KNOWLEDGE THIS DECISION WAS TAKEN AGAINST. Until this existed the two entries above were
  -- the whole of `sources` — the gate cited its own code and nothing else, so no employee could
  -- ever answer "which knowledge did you use". The lookup runs against the kb_chunks GIN index and
  -- is bounded to three chunks. It sits in its own block: if anything here raises, the failure is
  -- RECORDED rather than swallowed and the verdict proceeds untouched, because a knowledge lookup
  -- must never be able to hold up an action.
  begin
    -- action and kind are frequently the same word ('publish_content' maps to 'publish_content'),
    -- so the kind is only added when it says something the action does not. Otherwise the query
    -- reads "publish content publish content", which is not wrong but is careless in a record a
    -- human is meant to read.
    v_kb_q := btrim(regexp_replace(
                coalesce(action,'') ||
                case when lower(coalesce(NEW.kind,'')) = lower(coalesce(action,'')) or coalesce(NEW.kind,'') = ''
                     then '' else ' ' || NEW.kind end, '[_]+', ' ', 'g'));
    if v_kb_q <> '' then
      select jsonb_agg(jsonb_build_object('id', k.id, 'title', k.title, 'category', k.category)),
             (array_agg(k.category order by k.category))[1]
        into v_kb, v_kb_cat
        from (select c.id, c.title, c.category
                from public.kb_chunks c
               where c.fts @@ websearch_to_tsquery('english', v_kb_q)
               order by ts_rank(c.fts, websearch_to_tsquery('english', v_kb_q)) desc
               limit 3) k;
      if v_kb is not null then
        v_sources := v_sources || jsonb_build_array(jsonb_build_object(
          'kind', 'knowledge', 'ref', 'kb_chunks', 'query', v_kb_q, 'result', v_kb,
          -- The label is exact on purpose: this informs the human reading the decision. It does not
          -- move the boolean, which is still fn_should_escalate + fn_authorize. A source element
          -- implying it drove the verdict when it did not is the same defect one level down.
          'note', 'governing knowledge retrieved for this action class; informs the reviewer, does not set the verdict'));
        insert into public.kb_usage_log(query, category, agent)
        values (v_kb_q, coalesce(v_kb_cat, 'action_gate'), coalesce(NEW.agent, 'agent'));
      end if;
    end if;
  exception when others then
    v_sources := v_sources || jsonb_build_array(jsonb_build_object(
      'kind', 'knowledge_error', 'ref', 'kb_chunks', 'query', v_kb_q, 'error', sqlerrm));
  end;

  -- enforce: a gated action can never be auto-approved; force human review
  if blocked and coalesce(NEW.status,'pending') in ('approved','auto','auto_approved','executed','done') then
    NEW.status := 'needs_review';
  elsif blocked and coalesce(NEW.status,'pending')='pending' then
    NEW.status := 'needs_review';
  end if;

  -- THE OPTION THAT WAS NOT TAKEN. Two outcomes were genuinely available and one was genuinely
  -- rejected; the reasons it lost are the ones already computed above, not a new narrative.
  v_taken := case when blocked then 'held_for_review' else 'permitted' end;
  v_other := case when blocked then 'permitted' else 'held_for_review' end;
  v_why := case when blocked
    then case when array_length(reasons,1) is null
              then 'the gate blocked without recording a reason, which is itself the finding'
              else array_to_string(reasons, ' | ') end
    else 'fn_should_escalate did not fire and fn_authorize allowed it, so there was no ground to hold it' end;
  v_alts := jsonb_build_array(
    jsonb_build_object('option', v_taken, 'selected', true,
                       'basis', 'fn_should_escalate + fn_authorize on this action''s own context'),
    jsonb_build_object('option', v_other, 'selected', false, 'rejected_because', v_why));

  -- immutable audit
  begin
    insert into decision_log(actor,kind,ctx,decision,confidence,reasons,sources,route_to,alternatives)
    values (coalesce(NEW.agent,'agent'),'action_gate',
            jsonb_build_object('action',action,'kind',NEW.kind,'risk',NEW.risk,'attrs',attrs),
            case when blocked then 'held_for_review' else 'permitted' end,
            -- NEW.confidence, not a literal null. This trigger is named zzz_action_gate so it fires
            -- AFTER trg_governance_stamp, which is what stamps the 0.9 — see
            -- action_gate_runs_after_the_stamp.sql. Reading it any earlier reads a NULL.
            NEW.confidence,
            to_jsonb(reasons), v_sources, esc->>'route_to', v_alts)
    returning id into v_dl_id;
  exception when others then v_dl_id := null; end;

  NEW.decision_log_id := v_dl_id;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.trg_agent_knowledge_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_days int; begin
  v_days := case when coalesce(NEW.topic,'') ~* 'regulat|authorit|licen|complian|price|pricing|tax|vat|fee' then 90
                 when coalesce(NEW.topic,'') ~* 'market|supplier|commercial|brand|manufactur|competitor'    then 180
                 else 365 end;
  -- source_ref, confidence, owner_agent and supporting_evidence are deliberately NOT set here.
  -- They belong after trg_knowledge_provenance_stamp has had its chance to derive a real citation;
  -- setting them here is what stopped it running at all. See the header.
  if NEW.validation_status is null then NEW.validation_status := 'unvalidated'; end if;
  if NEW.review_due  is null then NEW.review_due  := (now() + (v_days     || ' days')::interval)::date; end if;
  if NEW.valid_until is null then NEW.valid_until := (now() + (v_days * 2 || ' days')::interval)::date; end if;
  return NEW;
end
$function$


CREATE OR REPLACE FUNCTION public.trg_ai_cost_attribute()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare m record;
begin
  if new.dept_key is null or new.agent_key is null then
    -- 1. the hand-maintained override, unchanged and still first.
    select * into m from ai_cost_fn_map where fn = new.fn;
    if found then
      new.dept_key  := coalesce(new.dept_key,  m.dept_key);
      new.agent_key := coalesce(new.agent_key, m.agent_key);
    end if;

    -- 2. what the ROUTER would have used. fn_ai_route attributes an un-departmented call from
    --    this exact table; until now the log did not, so the ceiling and the ledger disagreed.
    if new.dept_key is null then
      select t.dept_key into new.dept_key
        from fn_task_class t
       where t.fn = new.fn and t.active and t.dept_key is not null
       limit 1;
    end if;

    -- 3. the employee's own department, when the call names one.
    if new.dept_key is null and new.agent_key is not null then
      select a.department into new.dept_key
        from org_agents a
       where a.agent_key = new.agent_key and a.department is not null
       limit 1;
    end if;

    -- 4. the executor that owns this edge function.
    if new.dept_key is null then
      select e.department into new.dept_key
        from org_action_executor e
       where e.target = new.fn and e.department is not null
       limit 1;
    end if;
  end if;

  -- CANONICAL ON THE WAY IN. Whatever source supplied it, an absorbed key is stored as the
  -- department that absorbed it, so the ten budget rows are the only vocabulary the ledger uses.
  if new.dept_key is not null then
    new.dept_key := coalesce(public.fn_dept_canonical(new.dept_key), new.dept_key);
  end if;

  return new;
-- The swallow is deliberate and pre-existing: attribution must never cost a cost-log row. A
-- rising unattributed share is caught by the invariant test rather than by an exception here.
exception when others then return new;
end $function$


CREATE OR REPLACE FUNCTION public.trg_assistant_log_to_kernel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  perform public.fn_kernel_source_emit('edge:site_assistant', jsonb_build_object(
    'source_ref',  NEW.id::text,
    'raw_payload', jsonb_build_object(
      'case_ref', 'assistant:' || NEW.id::text,
      'message',  left(coalesce(NEW.message,''), 500),
      'audience', NEW.audience,
      'path',     NEW.path)));
  return NEW;
end
$function$


CREATE OR REPLACE FUNCTION public.trg_audit_agent_run()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  insert into os_audit_log (actor, action, entity, entity_id, detail, ok, err)
  values (
    coalesce(new.agent,'unknown_agent'),
    'agent_run',
    'agent_runs',
    new.id::text,
    jsonb_strip_nulls(jsonb_build_object(
      'status',  new.status,
      'counts',  new.counts,
      'note',    left(coalesce(new.note,''), 600),
      'started', new.started_at,
      'seconds', case when new.finished_at is not null and new.started_at is not null
                      then round(extract(epoch from (new.finished_at - new.started_at))::numeric, 2)
                      else null end)),
    coalesce(new.status,'ok') <> 'error',
    case when new.status = 'error' then left(coalesce(new.note,'error'), 400) else null end
  );
  return new;
exception when others then
  return new;   -- audit must never break the work it is recording
end $function$


CREATE OR REPLACE FUNCTION public.trg_autodispatch_inquiry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_secret text; v_ref text;
begin
  if NEW.rfq_ready is true
     and (TG_OP='INSERT' or OLD.rfq_ready is distinct from NEW.rfq_ready)
     and (NEW.routing is null or (NEW.routing->>'dispatched_at') is null) then
    select value into v_secret from app_secrets where key='cred_db_internal';
    select value into v_ref from app_secrets where key='project_ref';
    if v_ref is null then
      select substring(command from 'https://([a-z]+)[.]supabase[.]co') into v_ref
        from cron.job where command like '%supabase.co/functions/v1/%' limit 1;
    end if;
    -- Never raise inside the trigger: a missing ref must not stop an RFQ being created.
    -- fn_rfq_redispatch_sweep re-offers an RFQ that reached nobody within six hours.
    if v_ref is not null then
      perform net.http_post(
        url := 'https://'||v_ref||'.supabase.co/functions/v1/dispatch_inquiry',
        headers := jsonb_build_object('Content-Type','application/json'),
        body := jsonb_build_object('__secret', v_secret, 'inquiry_id', NEW.id));
    end if;
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.trg_block_banned_inquiry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_banned boolean;
begin
  select banned into v_banned from customers where id = NEW.customer_id;
  if coalesce(v_banned, false) then
    raise exception 'Your account has been paused due to repeated cancelled requests. Please contact support@quotesdone.com to restore it.';
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.trg_company_event_dispatch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  begin
    -- 20, not 1. See the header: at 1 this delivered only events stamped within the last sixty
    -- seconds, which was 4% of them, and everything else fell through to the 15-minute cron.
    perform public.fn_event_dispatch(20);
  exception when others then
    insert into public.agent_runs (agent, started_at, finished_at, status, counts, note)
    values ('event_dispatch_trigger', now(), now(), 'error',
      jsonb_build_object('sqlstate', sqlstate),
      'Inline dispatch from the company_event trigger failed: '||left(sqlerrm, 300)
      ||'. The event is stored and event_dispatch_15min will deliver it on the next tick.');
  end;
  return null;
end $function$


