CREATE OR REPLACE FUNCTION public.trg_gate_incomplete_match()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare ready boolean; v_found boolean := false; v_verdict text; v_reason text;
begin
  if NEW.inquiry_id is null then
    v_verdict := 'BLOCKED_MISSING_MATCH_EVIDENCE';
    v_reason  := 'the assignment names no inquiry, so there is nothing whose readiness could be judged';
  else
    select true, i.rfq_ready into v_found, ready
      from public.inquiries i where i.id = NEW.inquiry_id;
    if not coalesce(v_found, false) then
      v_verdict := 'BLOCKED_MISSING_MATCH_EVIDENCE';
      v_reason  := format('inquiry %s does not exist', NEW.inquiry_id);
    elsif ready is not true then
      v_verdict := 'BLOCKED_NOT_RFQ_READY';
      v_reason  := format('inquiry %s is %s; an incomplete RFQ does not qualify for routing',
                          NEW.inquiry_id,
                          case when ready is null then 'not scored for readiness' else 'not rfq_ready' end);
    else
      v_verdict := 'PASS';
      v_reason  := format('inquiry %s is rfq_ready', NEW.inquiry_id);
    end if;
  end if;

  perform set_config('app.inquiry_match_gate_verdict', v_verdict, true);
  perform set_config('app.inquiry_match_gate_reason',  v_reason,  true);
  if v_verdict = 'PASS' then return NEW; end if;

  raise warning 'gate_incomplete_match: % — %', v_verdict, v_reason;
  return null;   -- the row is refused; the verdict above is how a caller knows it was refused
end
$function$


CREATE OR REPLACE FUNCTION public.trg_goal_cascade()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if old.active is true and new.active is false then
    -- (1) KEPT. An objective serving a retired goal is superseded. This is the goal's own record
    -- being made consistent, not the creation of work, and leaving it out would strand objectives
    -- against a goal that no longer exists.
    update department_objective
       set status='superseded', updated_at=now()
     where goal_key = new.key and status='active';

    -- (2) DISABLED BY K31 — this was the bypass. It created an operational task per affected
    -- department, with no workflow run, no step, no accountable owner resolved through the kernel
    -- and no trace. No Phase B workflow starts from a goal retirement, so there is nowhere honest
    -- to route it; inventing a workflow to obtain a connected count is what §3 forbids. The
    -- statement is left here, commented, so a reader sees what was removed:
    --
    --   insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
    --   select distinct o.dept_key,
    --          'Re-plan after goal retired: '||new.key,
    --          'Company goal "'||coalesce(new.goal,new.key)||'" was retired. Objectives serving it
    --           are now superseded. Propose replacement objectives that serve an active goal.',
    --          'proposed','advisory', false, 'coordinate'
    --     from department_objective o
    --    where o.goal_key = new.key and o.status='superseded'
    --      and not exists (select 1 from org_tasks t
    --                       where t.title='Re-plan after goal retired: '||new.key and t.status<>'done');
    --
    -- It had never produced a row: org_tasks held zero 'Re-plan after goal retired' titles when
    -- this was written. The owed behaviour is recorded in phase_b_phase_c_wiring_gap.

    -- (3) KEPT. fn_emit_event does not write phase_c_event_outbox — measured, not assumed — so
    -- this is a legacy notice and not a second copy of a canonical domain event.
    begin
      perform fn_emit_event('goal.retired','company_goals',new.key,'ceo',
                            jsonb_build_object('goal',new.key));
    exception when others then null; end;
  end if;
  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.trg_health_check_agent_threshold()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_total   int;
  v_failed  int;
  v_rate    numeric;
  v_limit   numeric := coalesce(
    (select nullif(value,'')::numeric from app_secrets where key='agent_failure_rate_limit'), 0.10);
begin
  if new.check_kind is distinct from 'agent_runs' then
    return new;
  end if;

  select count(*),
         count(*) filter (where status not in ('ok','success','completed','skipped','warn'))
    into v_total, v_failed
  from agent_runs
  where started_at > now() - interval '1 hour';

  -- No runs at all in an hour is itself a failure: the company has gone quiet.
  if v_total = 0 then
    new.ok := false;
    new.detail := 'NO agent runs at all in the last hour - the company has gone silent, which is worse than a high failure rate.';
    return new;
  end if;

  v_rate := round(v_failed::numeric / v_total, 4);
  new.ok := (v_rate < v_limit);
  new.detail := v_failed || ' of ' || v_total || ' agent runs failed in the last hour ('
             || round(v_rate * 100, 2) || '%); threshold ' || round(v_limit * 100, 2) || '%'
             || case when new.ok then '' else ' - OVER THRESHOLD' end
             || '. [Recomputed by trg_health_check_agent_threshold; the raw producer sets ok=false on any single failure, which can never be true.]';
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.trg_holdout_expectations_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' then
    if coalesce(current_setting('quotesdone.holdout_change', true),'') = 'approved' then return old; end if;
    raise exception 'holdout case % cannot be deleted', old.case_key
      using hint = 'Use the P2-C5 expectation-change controls. A holdout that can be quietly pruned proves nothing.';
  end if;
  if coalesce(current_setting('quotesdone.holdout_change', true),'') = 'approved' then return new; end if;
  if new.expect_active       is distinct from old.expect_active
     or new.expect_dispositions is distinct from old.expect_dispositions
     or new.expect_components   is distinct from old.expect_components
     or new.expect_clarify      is distinct from old.expect_clarify
     or new.expect_conflict     is distinct from old.expect_conflict
     or new.text_en             is distinct from old.text_en
     or new.text_ar             is distinct from old.text_ar then
    raise exception 'holdout case % is frozen; its expectation cannot be edited in place', old.case_key
      using hint = 'Changing an expectation to match the code is how a suite stops being evidence.';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.trg_holdout_record_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  raise exception 'holdout result of record is immutable: % is not permitted', tg_op
    using hint = 'The first measurement of a holdout happens once. Re-running it later is a regression run, not a new first result.';
end $function$


