CREATE OR REPLACE FUNCTION public.trg_ingest_case_lessons()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare les text; key text; n int := 0;
begin
  if NEW.ai_summary is null or jsonb_typeof(NEW.ai_summary->'lessons') <> 'array' then return NEW; end if;
  key := coalesce(public.fn_resolve_cat_agent(NEW.category), '_global');
  for les in select jsonb_array_elements_text(NEW.ai_summary->'lessons') loop
    les := trim(les);
    if length(les) < 12 then continue; end if;
    if not exists (select 1 from agent_knowledge where agent_key=key and content=les) then
      insert into agent_knowledge(agent_key, topic, content, priority)
      values (key, 'Closed-case lesson (RFQ-'||NEW.rfq_id||')', les, 60);
      n := n + 1;
    end if;
  end loop;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.trg_inquiry_answer_value_domain()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if not public.fn_field_value_allowed(new.field_id, new.value) then
    raise exception 'value %L is not in the allowed domain for field %', new.value, new.field_id
      using hint = 'Allowed values are listed in field_definition.allowed_values.';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.trg_inquiry_answer_value_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' then
    if coalesce(current_setting('quotesdone.p2c1_teardown', true), '') = 'approved' then
      return old;
    end if;
    raise exception 'inquiry_answer rows are never deleted (id %)', old.id
      using hint = 'Supersede the answer instead. The chain is the history.';
  end if;
  if new.value       is distinct from old.value
     or new.field_id    is distinct from old.field_id
     or new.group_id    is distinct from old.group_id
     or new.precedence  is distinct from old.precedence
     or new.source_kind is distinct from old.source_kind then
    raise exception 'inquiry_answer % is immutable; supersede it instead of editing it', old.id;
  end if;
  if old.superseded_by is not null and new.superseded_by is distinct from old.superseded_by then
    raise exception 'inquiry_answer % is already superseded by %', old.id, old.superseded_by;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.trg_inquiry_enrich()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare dup int;
begin
  if NEW.urgency is null and NEW.spec is not null and (NEW.spec ? 'urgency') then NEW.urgency := NEW.spec->>'urgency'; end if;
  if NEW.plausibility is null and NEW.spec is not null and (NEW.spec ? 'plausibility') then NEW.plausibility := NEW.spec->'plausibility'; end if;
  if NEW.provenance is null and NEW.spec is not null and (NEW.spec ? 'provenance') then NEW.provenance := NEW.spec->'provenance'; end if;

  -- REMEMBERED PREFERENCE. Only fills a GAP — an emirate the customer stated on this RFQ always
  -- wins. `stated` beats `inferred`, and consent is re-checked on the read as well as the write.
  if NEW.emirate is null and NEW.customer_id is not null then
    select coalesce(p.preferences->'stated'->'emirates'->>0,
                    p.preferences->'inferred'->'emirates'->>0)
      into NEW.emirate
      from customer_preference p
      join customers c on c.id = p.customer_id
     -- Consent is read from customers.tos_accepted_at, where it actually lives, not from the copy
     -- on the preference row. A stale copy would keep a withdrawn profile readable.
     where p.customer_id = NEW.customer_id and c.tos_accepted_at is not null;
  end if;

  select count(*) into dup from inquiries i
    where i.customer_id = NEW.customer_id and i.created_at > now() - interval '30 minutes'
      and coalesce(i.category,'') = coalesce(NEW.category,'')
      and (i.summary = NEW.summary or (length(coalesce(NEW.summary,'')) > 8 and i.summary ilike '%' || left(NEW.summary, 40) || '%'));
  if dup > 0 then
    NEW.plausibility := coalesce(NEW.plausibility, '{}'::jsonb) || jsonb_build_object('possible_duplicate', true);
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.trg_inquiry_gate_state_sync()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.state is null then
    new.state := (case when new.passed is true then 'passed'
                       when new.passed is false then 'failed'
                       else 'not_evaluated' end)::public.gate_state;
  end if;
  new.passed := public.fn_gate_state_satisfies(new.state);
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.trg_inquiry_received()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cemail text;
begin
  -- child sub-RFQs of a combined project do not get their own "received" notice
  if NEW.parent_inquiry_id is not null then return NEW; end if;
  select email into cemail from public.customers where id = NEW.customer_id;
  if cemail is not null then
    insert into public.notifications(type,to_email,to_role,inquiry_id,subject,body,status)
    values('inquiry_received', cemail, 'customer', NEW.id,
      'We have received your request',
      case
        when NEW.scope_type = 'multi' then
          'Thanks — your combined request'||coalesce(' for '||left(NEW.summary,80),'')||' is in. We have split it into separate requests per trade and are matching each to the right specialists'||coalesce(' in '||NEW.emirate,' in the UAE')||'. You will be notified as quotes come in — track everything in the app.'
        when NEW.scope_type = 'turnkey' then
          'Thanks — your combined request'||coalesce(' for '||left(NEW.summary,80),'')||' is in. We are matching it to turnkey fit-out companies that can handle the whole project'||coalesce(' in '||NEW.emirate,' in the UAE')||'. You will be notified as quotes come in — track everything in the app.'
        else
          'Thanks — your request'||coalesce(' for '||left(NEW.summary,80),'')||' is in. We are matching it to relevant '||coalesce(NEW.category,'')||' suppliers in '||coalesce(NEW.emirate,'the UAE')||'. You will be notified as quotes come in — track everything in the app.'
      end,
      'queued');
  end if;
  -- K20 cutover. A new PARENT inquiry starts W05. Placed at the final return, after the early return that lets a child sub-RFQ of a combined project through without its own workflow — a combined project is one piece of work, not four.
  perform public.fn_kernel_source_emit('dbtrigger:public.inquiries:trg_inquiry_received_a', jsonb_build_object(
    'source_ref',  NEW.id::text,
    'raw_payload', jsonb_build_object('inquiry_id', NEW.id::text, 'customer_id', NEW.customer_id::text, 'category', NEW.category, 'emirate', NEW.emirate, 'scope_type', NEW.scope_type)));
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.trg_invite_cap_allocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_old numeric; v_new numeric;
begin
  if new.key <> 'invite_daily_cap' then return new; end if;

  -- A non-numeric or absent value is not a reallocation; nothing is recorded rather than guessed.
  begin
    v_old := nullif(btrim(coalesce(old.value, '')), '')::numeric;
    v_new := nullif(btrim(coalesce(new.value, '')), '')::numeric;
  exception when others then
    return new;
  end;
  if v_old is null or v_new is null then return new; end if;

  -- A move to the same number moved nothing. s23-reallocation-policy-cited counts a no-op as a
  -- finding, correctly, so one is never written.
  if v_old is not distinct from v_new then return new; end if;

  insert into public.allocation_change (resource, subject, from_value, to_value, reason, policy)
  values ('supplier_onboarding_capacity', 'invite_daily_cap', v_old, v_new,
          case when v_new > v_old
               then 'Daily supplier-invite capacity raised from ' || v_old || ' to ' || v_new
                    || '. Deliverability is inside tolerance, so more onboarding capacity is released.'
               else 'Daily supplier-invite capacity reduced from ' || v_old || ' to ' || v_new
                    || '. Bounce rate is above tolerance, so onboarding capacity is withdrawn to '
                    || 'protect the sending domain.' end,
          'invite ramp: capacity follows the measured 7-day bounce rate against invite_max_bounce_rate, '
          || 'warming at most 2x per day, floored at the base cap and ceilinged by the volume stage');
  return new;
end
$function$


